INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda yamacında', 'sevda-yamacinda-mahmut-kasapoglu-famqf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Attım yüreğimi aşk ocağına,

Duman oldum, çıktım dağ kucağına.

Kül olup savruldum yâr ayağına,

Sevda yamacında güller sarardı.

Ne bahara güldüm, ne kıştan yıldım;

Kar düştü saçıma, dal dal eğildim.

Bir çift kara gözde kendimi bildim,

Sevda yamacında yollar ağardı.

Gözlerin değince taşlar yarılır,

Kuruyan pınarın gözü açılır,

Kış vurmuş dallara çiçek saçılır,

Sevda yamacında kuşlar öterdi.

Gecemde bir kandil yaktı ak elin,

Yarama merhemdi petekten balın.

Ninni ninni aktı, çağladı dilin,

Sevda yamacında güller kızardı.

Altın taç yalandır, yaldızlı makam;

Gülüşünle dolar, al olur akşam.

Bir selamın gelse, dünyalar tamam,

Sevda yamacında ömrüm yeşerdi.

Varsın ayrılık da kapımı çalsın,

Hasret ateşini bağrıma salsın;

Adım bir köz olup gönlünde kalsın,

Sevda yamacında ocak tüterdi.

Turnalar götürsün göçümden haber,

Taşıma kazınsın: "Sevdi..." Bu yeter.

Ne kin kalır benden, ne kara keder;

Sevda yamacında güller açardı.', 'Attım yüreğimi aşk ocağına, Duman oldum, çıktım dağ kucağına. Kül olup savruldum yâr ayağına, Sevda yamacında güller sarardı. Ne bahara güld...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevda-yamacinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin olmaz', 'haberin-olmaz-mahmut-kasapoglu-fyu6w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir selam bıraktım sabah yeline,

Kapına varırım, haberin olmaz.

Gözümden taşan bu hasret seline

Kendimi salarım, haberin olmaz.

Ne taht ister gönlüm, ne de konaklar;

Bir sözünle güler kuru dudaklar.

Yolunun taşına kanar ayaklar,

İzini öperim, haberin olmaz.

Dağlar şahidimdir, ovalar bilir;

Sevda ağır yüktür, yiğit eğilir.

Bir ömür sırtıma kor gibi gelir,

Yanarak yürürüm, haberin olmaz.

Ne Mecnun olmaya kalmış kararım,

Ne Ferhat misali dağlar yararım.

Sana varamadan geçti baharım,

İçime gömerim, haberin olmaz.

Bir ezan sesinde hasretin boğar,

Bir akşam vaktinde gözlerin doğar.

Gönlüm kapısını sana aralar,

Başköşe veririm, haberin olmaz.

Dünya dedikleri konup göçmektir,

Sevda dedikleri Hakk''a uçmaktır.

Sana yanmak ise şükre geçmektir,

Elimi açarım, haberin olmaz.

Bir gün toprağıma rahmet dökülür,

Başucumda mor bir menekşe gülür.

Koklarsın, "Ne güzel..." sesin süzülür;

Sana karışırım, haberin olmaz.', 'Bir selam bıraktım sabah yeline, Kapına varırım, haberin olmaz. Gözümden taşan bu hasret seline Kendimi salarım, haberin olmaz. Ne taht iste...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/haberin-olmaz-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürekteki kerkük', 'yurekteki-kerkuk-mahmut-kasapoglu-yqrr9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özgürlüğü ufuktan

Doğan günden dermişim.

Her ezilen yüreğe

Bir umut göndermişim.

Kerkük diye ağlayan

Her sesi dinlemişim.

Toprağın her taşıyla

Birlikte inlemişim.

Bir bayrağın gölgesi

Yeter bana demişim.

Rüzgârına göğsümü

Yelken diye germişim.

Dicle''nin kıyısında

Hasretle diz çökmüşüm.

Fırat''ın sularına

Gözyaşımı dökmüşüm.

Bir çınarın kökünde

Asırlar beklemişim.

Koparılan dalları

Gövdeme eklemişim.

Sürgünlerde savrulup

Küllerden doğmuşum ben.

Zincirlere vurulup

Zinciri kırmışım ben.

Dil sustu sanmış onlar,

Ben sözü saklamışım.

Ninnide, hoyratlarda

Türkümü ağlamışım.

Bir çocuğun gözünde

Yarını görmüşüm ben.

Her masum tebessümle

Vatanı örmüşüm ben.

Dağlar bana eğilmez,

Ben dağla birleşmişim.

Doruğunda her gece

Bulutla dertleşmişim.

Kerkük bir şehir değil,

Bir ömür bilmişim ben.

Her Türkmen sözcüğünde

Bin yılı bulmuşum ben.

Çünkü vatan dediğin

Bir ana duasıdır;

Haritada renk değil,

Yürekte bir sızıdır.

Bedeli can olsa da

Bu yolu ben seçmişim.

Her şehidin ardından

Sessizce ant içmişim.

Gün gelir, zulüm biter,

Gece sabah olurmuş.

Hak yolunda yürüyen

Yoldaşını bulurmuş.

Bir gün tarih sorarsa:

"Ne bıraktın ardında?"

Derim: "Kerkük türküsü

Evladımın dilinde."

Adım unutulsa da

İzimi bırakmışım.

Her Türkmen yüreğinde

Çerağımı yakmışım.

Son nefeste bilinsin:

Ne kin ne öç gütmüşüm.

İnsanlığı severken

Kerkük''ü özlemişim.', 'Özgürlüğü ufuktan Doğan günden dermişim. Her ezilen yüreğe Bir umut göndermişim. Kerkük diye ağlayan Her sesi dinlemişim. Toprağın her taşıy...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/yurekteki-kerkuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kerküke sevda', 'kerkuke-sevda-mahmut-kasapoglu-m58mk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sevda var içimde, adı sensin Kerkük''üm

Yıllara meydan okur, bu hiç yılmayan ülküm

Ne rüzgâr silebilir, ne zaman bozar hüküm

Gönlümde kapanmayan bir yaradır Kerkük''üm.

Bir taşına dokunsam bin hatıra konuşur

Bir hoyratın yanığı gözlerimde tutuşur

Toprağınla yoğrulan bu can sana kavuşur

Hasretin sönmez bir kor, dağlar bağrım Kerkük''üm.

Seninle doğar şafak, seninle çöker akşam

Adın düşse dilime, çiçeğe durur yaşam

Dudağımda duasın, gözümde bir ihtişam

Kalbimin en derinde saklı sırrım Kerkük''üm.

Bülbülünün dilinde hüzünlü nağme vardır

Kalesinin burcunda bin yıllık çile vardır

Türkmen''in yüreğinde senden bir pare vardır

Gönüllerde taht kuran bir diyardır Kerkük''üm.

Nice kara gün gördün, nice fırtına aştın

Yine dimdik ayakta, çağlar boyu savaştın

Her düşen yaprağınla yeniden bahar açtın

Asırlara kazınan bir destandır Kerkük''üm.

Bir gün sorsalar bana: "Nedir en büyük sevdan?"

Derim ki: "Alın yazım, silinmeyen bir ferman."

Adını taşır kalbim, değişmez hiçbir zaman

Ömrümün sonuna dek tek yârimsin Kerkük''üm.', 'Bir sevda var içimde, adı sensin Kerkük''üm Yıllara meydan okur, bu hiç yılmayan ülküm Ne rüzgâr silebilir, ne zaman bozar hüküm Gönlümde kap...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kerkuke-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutlu Şehit', 'kutlu-sehit-kasim-kobakci-s8z3g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Korkak olan bile mertlik aradı,

Aslını bilenler tez haydaladı.

Onlar ki yiğittir, ileri koştu,

Onlar kutlu şehit, göklerde coştu.', 'Korkak olan bile mertlik aradı, Aslını bilenler tez haydaladı. Onlar ki yiğittir, ileri koştu, Onlar kutlu şehit, göklerde coştu....', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kutlu-sehit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde kalan hesap', 'i-cimde-kalan-hesap-mahmut-kasapoglu-6xibz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ömrümün yapraklarını hazan yeli sürünce,

Kül bağladı gönül evim, ocaklarım sönünce;

Bir yanım şafak, bir yanım gece; ruhum bölünce,

Bir mahşer kurdum içimde vicdanın huzurunda.

Haklılığım kumdan kale, yıkıldı her cevabım;

Kibrin kızgın harmanında saman oldu sevabım.

Aynalarda bir yabancı: o yüz benim azabım,

Her kırışık bir pişmanlık, kurşun gibi omzumda.

Bir günahın gölgesinde nice sevap üşürmüş,

İnsan kendi kurdu olup özünü çürütürmüş.

Bir damla gözyaşı bile dağları yürütürmüş;

Yeter ki bir gül açsın da gönlün taş avlusunda.

Kimi zaman bir bakışın bin kitaplık sözü var,

Kimi zaman bir susuşun mezar taşı yükü var.

Fırtınada kaybolanın sahile dönüşü var;

Yeter ki kul yorulmasın tövbenin yokuşunda.

Defter defter hesapları rüzgârlara bıraktım,

Bir çocuk masumluğuyla secdeye doğru aktım.

Kalbime ilk kez bir yolcu gözüyle uzun baktım:

Nefsimin kalesi düştü, fetih bu Hak yolunda.

Varsın dünya unutsun da ismimi yarın sabah,

Rahmet bir kez baksın bana, yeter o bir tek nigâh.

Kul dediğin kırık testi; dudağında dua, ah.

Af dilenen bir garibim Rabbimin kapısında.', 'Ömrümün yapraklarını hazan yeli sürünce, Kül bağladı gönül evim, ocaklarım sönünce; Bir yanım şafak, bir yanım gece; ruhum bölünce, Bir mahş...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/icimde-kalan-hesap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalıpları Kırmadıkça', 'kaliplari-kirmadikca-i-lyas-ates-1jjlz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bütün kalıpları kırmadıkça kalıplara takılı kalacaksınız

Kalıpları kıramayanlar kendilerine uygun kalıpları

seçecektir 

Kendisine uygun kalıbı seçmiş olanlar diğer kalıplara

düşman olacaklardır 

Eğer gerçekten inanmışsanız bütün kalıplardan 

kurtulmak zorundasınızdır 

Kalıplar sizlerin doğmuş olduklarınız ülke ve yöreye

töreye göre şekillenmiş olacaktır 

Sizler ülkeye yöreye töreye geleneklere taptığınız

sürece Allaha tapmış olmayacaksınız', 'Bütün kalıpları kırmadıkça kalıplara takılı kalacaksınız Kalıpları kıramayanlar kendilerine uygun kalıpları seçecektir  Kendisine uygun kalı...', ARRAY['Türk Edebiyatı','Şiir','İlyas Ateş']::text[], 8.5, '{"poet":"İlyas Ateş","poet_slug":"i-lyas-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kaliplari-kirmadikca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmeyen ümit', 'olmeyen-umit-mahmut-kasapoglu-f8tdo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kim der ki küle dönen köz bir daha yanmayacak?

Dilsiz geçen yıllarda şafak saklayacak gönül.

Her kırık hatırayı bir gün yıldızlar saracak,

Küllerden kanatlanıp yine parlayacak gönül.

Hasretin pençesinde sararıp soldu bu cismim,

Gurbetin taşlarında yitip gitti çocuk resmim.

Yine de her duada taze fidan oldu ismim,

Çöle düşen rahmetle gülü koklayacak gönül.

Ömür dediğin nedir? Bir bekleyiş, bir de yara.

Elbet vuslat değecek susmuş bütün baharlara.

Sabırla eğilen baş dik yükselir yarınlara,

Hakk''ın engin lütfuna ümit bağlayacak gönül.

Ne denli uzak olsa özlediğim o ilk seher,

Ümit tükenmedikçe ömür olmaz asla heder.

Bir avuç sevda için yutulsa da zehir keder,

Aşkın ezel sesiyle her dem çağlayacak gönül.

Ölen ümit değildir; yalnız göçen bir zamandır.

İnsan ümit ettikçe her nefesi yeni candır.

Dün, bugüne emanet; yarınsa Hak''tan fermandır,

Rahmetin eşiğine alnı yaslayacak gönül.', 'Kim der ki küle dönen köz bir daha yanmayacak? Dilsiz geçen yıllarda şafak saklayacak gönül. Her kırık hatırayı bir gün yıldızlar saracak, K...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olmeyen-umit-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazı', 'yazi-mahmut-kasapoglu-zkamd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doğmadan alnıma düşmüş bir kalem,

Mürekkebi kanım, kara yazı mı?

Her harfi bir hançer, noktası elem,

Satır satır okur beni mazi mi?

Dostlar kuşlar gibi göçtü diyardan,

Ne bir mektup geldi, ne selam yârdan.

Bir gölge sızıyor soğuk duvardan,

Toprak bizi bekler, yoksa sizi mi?

Gidip de ardına bir kez dönmeyen,

Bir damla yaşını yere dökmeyen,

Yuvamı yıkarken hiç diz çökmeyen;

Unuttuğu ben mi, yoksa sözü mü?

Gece yarısında uyanır yara,

Ay bile çekilir, gök olur kara.

Düşer bu can yine o eski dara;

Ağlayan gönül mü, gönül gözü mü?

Ayna da yalancı, sırrı dökülmüş,

Zaman bir yay olmuş, belim bükülmüş,

Gülüşler maskeymiş, birden sökülmüş;

Bu dünya gerçek mi, sahte yüzü mü?

Bir sevda gömdüm ben, içimde yanar,

Üstünü kül örter, el söndü sanar.

Kalbim her seherde adını anar;

Yakan alev midir, kalan közü mü?

Kalem kırılınca mürekkep kurur,

Satırlar silinir, sayfa savrulur,

Geride bir tek harf, bir nefes durur;

O tek harf ben miyim, canın özü mü?', 'Doğmadan alnıma düşmüş bir kalem, Mürekkebi kanım, kara yazı mı? Her harfi bir hançer, noktası elem, Satır satır okur beni mazi mi? Dostlar ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yazi-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözü Söyler Bilgeler', 'sozu-soyler-bilgeler-kasim-kobakci-urkbm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnci gibi parlayan, sözü söyler bilgeler,

Yıldızlı gecelerde, raks edermiş gölgeler,

Bir tatlı tebessümle, nurlanırmış bölgeler.

Cilalı bir lisandır, ruhu çeken limanlar,

Gönülden kopup gelir, şifa bulan zamanlar.

*

Bilinmeyen diyarda, sevgi gülleri açar,

İpekten harfler ile, göğe kokular saçar,

Süslü laflar duyanlar, kederden hemen kaçar.

Zarif bülbüller öter, mest olur tüm aşıklar,

Sırlı sözün gücüyle, yanar parlak ışıklar.

*

O uzak şehirde hep, altın ırmaklar akar,

Meçhul sultanlar varmış, aşka gıptayla bakar,

Büyülü kelamdır hep, dertleri yakıp yıkar.

Gümüş rengi seslerle, silinir derin izler,

Cilalı lisan ile, ayan olur tüm gizler.

*

Gizemli diyarlarda, çiçek açarmış dağlar,

Kelimeler raks edip, yeşermiş bütün bağlar,

Şairin kaleminden, tatlı bir nehir çağlar.

Cümleler güzel eser, uzanır narin eller,

Muhabbet rüzgarında, titrer kalpteki teller.

*

Pırıl pırıl parlayan, yakut zümrütlü taşlar,

Cilalı laflar ile, büyük sevdalar başlar,

Meclislerde susarmış, usulca ağır başlar.

Göz boyayan sanatla, sunulur tatlı gerçek,

Süslü bir vazo içre, açar efsunlu çiçek.

*

Eski zamanlarından, miras kalan konaklar,

Büyülü hikayeler, saklar pembe yanaklar,

Tatlı dilin sihrine, kanar susuz dudaklar.

Söz incelir ve parlar, mest olur hep bakışlar,

Ruhu sarıp sarmalar, sevgi dolu nakışlar.', 'İnci gibi parlayan, sözü söyler bilgeler, Yıldızlı gecelerde, raks edermiş gölgeler, Bir tatlı tebessümle, nurlanırmış bölgeler. Cilalı bir ...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sozu-soyler-bilgeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz, Kadın Gibidir', 'deniz-kadin-gibidir-pakize-ozbas-u4cqf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eyy ! 

Maviye sığamayan kadın, sana sesleniyorım... 

Kendi derinliğinde gökyüzünü bulan ruhum…

Nasıl boyayacaksın  bu kadar düşü maviye ?

Bir kadın tanıdım,

Göğsünde haritası olmayan denizler taşırdı.

Kimse bilmezdi hangi kıyısında yorulduğunu,

O, en derin yerinde bile

Kendine bir gökyüzü saklardı.

Farkettim kolayca  bana benzemekte olduğunu yüreğinin 

Saçlarına düşen yılları saymazdı,

Çünkü takvimler bilmezdi onun yaşını.

Bir gününü çocukluğuna bırakır,

Bir gününü hiç yaşanmamış yarınlara,

Kalanını da kimsenin bilmediği

O sessiz kadına ayırırdı.

Bir muştu olsun demekti belki de yorgun gönülde

Öyle her rüzgârda yön değiştirmezdi,

Ama bir yaprağın düşüşüne

Saatlerce bakabilirdi.

Kırılmış bir dalın gölgesinde

Bazen koca bir ömrü okur,

Sonra hiçbir şey olmamış gibi

Çayını tazelerdi.

Ne çok tanıklık etmişti bu manzaralara

Birilerine kapısını kapatmıştı,

Ama penceresinden ışığı eksiltmemişti.

Anlamıştı;

İnsan herkese yer açarken

Kendi içinde daralabiliyordu.

Şimdi kimseye yetişme telaşı yok,

Ne bir eksikliği tamamlama derdi

Ne de anlaşılmak için yorulmak…

Kendi sesinin kıyısında oturuyor,

Bir damla maviyi avucunda büyütüyor.

Fırtınaları göğsünde uyutmayı öğrenmişti,

Kendi yakamozunu kendi karanlığında yakardı.

Gece yanık, yıldızlar yanık  düşler göz olmuş o cenderede

Ve ben ona sordum bir akşam:

"Bu kadar şeyi nereye sakladın?"

Sustu yalnızca ...

"Ben hiçbir şeyi saklamadım,

Sadece herkesin baktığı yerden

Kendime bakmadım."

Bazı kadınlar denize benzemez;

Deniz, onların içinde

Kendi derinliğini arar…

Maviye sığmadı kadın,

Biraz da gökyüzüne taştı… 

Maviye sığmayan kadın,

Gönlüne sığdırır bütün gökyüzünü,

Kıyısına vuran her dalgayı bir duaya çevirip,

Göğe uğurlar 

Avuçlarında binlerce dilek 

Dudaklarında bitip tükenmek bilmeyen dualar… 

Her sabah yeniden okunacak

Pakize Özbaş

mavikatre💧', 'Eyy !  Maviye sığamayan kadın, sana sesleniyorım...  Kendi derinliğinde gökyüzünü bulan ruhum… Nasıl boyayacaksın  bu kadar düşü maviye ? Bi...', ARRAY['Türk Edebiyatı','Şiir','Pakize Özbaş']::text[], 8.5, '{"poet":"Pakize Özbaş","poet_slug":"pakize-ozbas","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/deniz-kadin-gibidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halk Tv ile Sözcü Tv''ye kayyum atandı', 'halk-tv-ile-sozcu-tv-ye-kayyum-atandi-yusuf-tuna-0lgdr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Devlet Küresel Gücün Tv''lerine el koydu,

Halk Tv ile Sözcü Tv''ye kayyum atandı.

Yaptığı yayınların elbette sonucu buydu,

Halk Tv ile Sözcü Tv''ye kayyum atandı.

Küresel Gücün Türkiyedeki eli kırıldı,

Türk Devletine düşman güçlere darbe vuruldu.

Abd ile İsrail''in sesi susturuldu,

Halk Tv ile Sözcü Tv''ye kayyum atandı.

Hükümet karşıtlığı ile kendisini bulan,

Her zaman devletimizin karşısında yer alan.

Sol kesim ile Fetöcülerin sözcüsü olan,

Halk Tv ile Sözcü Tv''ye kayyum atandı.

Bunlar İmamoğlu''nu destekliyor açık ayan,

Parasını Fon''a yatırıp haksız kazanç yiyen.

Milleti soyan siyesetçileri destekleyen,

Halk Tv ile Sözcü Tv''ye kayyum atandı.

Yusuf bunlar Fetöcülerle beraber olmuştur,

Bunlar var ya dış güçlerin yanında yer almıştır.

Hainlik yapana hesap sorma vakti gelmiştir,

Halk Tv ile Sözcü Tv''ye kayyum atandı.', 'Devlet Küresel Gücün Tv''lerine el koydu, Halk Tv ile Sözcü Tv''ye kayyum atandı. Yaptığı yayınların elbette sonucu buydu, Halk Tv ile Sözcü T...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Tuna']::text[], 8.5, '{"poet":"Yusuf Tuna","poet_slug":"yusuf-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/halk-tv-ile-sozcu-tv-ye-kayyum-atandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennem', 'cehennem-faruk-tosun-a3qqt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cehennem misafirlerini görünce

Hiddetinden parçalanacak gibi gürleyecek

Bunu duyan insan

Keşke toprak olsaydım 

Bunları yaşamasaydım diyeceksin

Ey insan 

Onu hiddetlendirecek ne yaptın

Bir düşün ve öyle yaşa

Allah’ı bilmemenin 

cezasını bilseydin 

Kütüphanelerden çıkmazdın

İbadet etmemenin

Cezasını bilseydin 

Bir ömrünü secde de geçirirdin

Vücuduna verdiğin zararların

Cezasını bilseydin

El bebek gül bebek beslerdin

İnsanlara yaptığın kötülüklerin

cezasını bilseydin

Onların altına döşekler sererdin

Anne babaya üff demenin 

cezasını bilseydin

Pervaneler gibi etrafında dönerdin

Faizin 

cezasını bilseydin 

Hayatta paraya dokunmazdın

Vatanı, sevdiklerini korumaktan kaçmanın cezasını bilseydin 

Sınır boylarında heykel olurdun

Zinanın 

cezasını bilseydin

Helalinin dışında kimseyle görüşmezdin

Onun için

Yakarsan öyle bir yanarsın ki

Tarif edilemez böylesi

Korkutursan öyle bir korkarsın ki

Bu korku atomu parçalar belki

Sevilmesi gerekeni sevmezsen

Sevgisizlikten kurur dökülürsün

Bilmen gerekeni bilmezsen

Cahillerin cahiline

Cehennem

Bildirilir

Gösterilir 

Öyle bir yaşatılır ki

Keşke toprak olsaydım 

Bunları yaşamasaydım dersin', 'Cehennem misafirlerini görünce Hiddetinden parçalanacak gibi gürleyecek Bunu duyan insan Keşke toprak olsaydım  Bunları yaşamasaydım diyecek...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tosun']::text[], 8.5, '{"poet":"Faruk Tosun","poet_slug":"faruk-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/cehennem-155-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okunmayı Bekleyen Kitap', 'okunmayi-bekleyen-kitap-ali-hasan-gokalp-1dme6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anlamıyorlar çünkü dünyaya aşıklar.

Bir mantık arıyorlar çünkü her şeye artı eksi olarak bakıyorlar.

Hesabı bıraksınlar.

Kitaba baksınlar.', 'Anlamıyorlar çünkü dünyaya aşıklar. Bir mantık arıyorlar çünkü her şeye artı eksi olarak bakıyorlar. Hesabı bıraksınlar. Kitaba baksınlar....', ARRAY['Türk Edebiyatı','Şiir','Ali Hasan Gökalp']::text[], 8.5, '{"poet":"Ali Hasan Gökalp","poet_slug":"ali-hasan-gokalp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/okunmayi-bekleyen-kitap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazin Müze', 'hazin-muze-kasim-kobakci-nnomp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sessizce başlasın bu zarif oyun,

Muharrir ruhunda saklı yalanlar.

*

Masumiyet adlı müzeye girmiş,

Geçmişi süsleyen sahte zamanlar.

*

Ustalıkla kendini yazıp silmiş,

Makyavelci zihni besleyen anlar.

*

Ruhunu satanlar köşeyi dönmüş,

Hedefe uzanmış geniş meydanlar.

*

Yüzüne masum maskeleri takmış,

Zehrini akıtmış sinsi yılanlar.

*

Kendi vicdanını ezip de sökmüş,

Başarı uğruna yanan vicdanlar.

*

Amaca giden yol mubahtır dermiş,

Külleri savrulan eski romanlar.

*

Menfaat uğruna dostları ezmiş,

Gölgede büyüyen gizli fermanlar.

*

Müzenin içinde hep sır gizlenmiş,

Gözyaşı dökermiş mağlup olanlar.

*

Zaferin tadını kadehten içmiş,

Şehre tepeden bakan kör sultanlar.

*

Bir masum resmin tam ardına geçmiş,

Merhamet dileyen mazlum insanlar.

*

En yakın dostunu sırtından deşmiş,

Kurguyu gerçeğe katan yazarlar.

*

Şaheser sanılan kitaba sızmış,

Aşkı bir araç gören o divanlar.

*

Sahte bir sevgiyle gözleri çelmiş,

Hikaye bitince gülen şeytanlar.

*

Şöhretin tacını başına giymiş,

Alkışla büyüyen en sahte şanlar.

*

Masum müzelerde sefaya ermiş,

Günahı sevapla örten hakanlar.

*

Muharrir sözüyle zehire girmiş,

Estetik içinde kaybolmuş kanlar.

*

Hileli zarları bilerek atmış,

Talihin çarkını bozan tiranlar.

*

Karanlık gecede kalpleri delmiş,

Acıdan beslenip duran kurbanlar.

*

Kendi eserine gülerek bakmış,

Masuma acıyıp sahte yananlar.

*

Makyavel ruhunu herkese vermiş,

Çıkarlar uğruna batan vatanlar.

*

Edebi masallar zihnini övmüş,

Gerçeği yalanla satan cüzdanlar.

*

Başarı tek kural diyerek gezmiş,

Güçlünün önünde susan irfanlar.

*

İyilik rolünü sahnede sevmiş,

Perdenin ardından esen tufanlar.

*

Kibirden kuleyi göklere dizmiş,

Yüceye uzanan devasa hanlar.

*

En saf duyguları tartıya dökmüş,

Parayla pulla dost olan kervanlar.

*

Hırsları kalbinin sesini kesmiş,

Kendi yalanına kanan zindanlar.

*

Masumiyet adlı kumaşı sermiş,

Üstünü örterek gülen dumanlar.

*

İlhamı o kurnaz şeytan üflemiş,

Karanlık ruhları sarmış ormanlar.

*

Saf saf sevenleri boşluğa itmiş,

Masumlar şehrinde ölen civanlar.

*

Sanatın ismini cidden kirletmiş,

Zirveye çıkınca yalnız kalanlar.

*

Müzenin sonunda tükenip bitmiş,

Boşluğa düşerek batan limanlar.

*

Muharrir gerçeği yalanla örmüş,

Aynada kendine küsmüş ummanlar.

*

Kalbinin zekası ebedi yenmiş,

Bu hazin müzeyi gezmiş ozanlar.', 'Sessizce başlasın bu zarif oyun, Muharrir ruhunda saklı yalanlar. * Masumiyet adlı müzeye girmiş, Geçmişi süsleyen sahte zamanlar. * Ustalık...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/hazin-muze-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burnumda tütüyorsun', 'burnumda-tutuyorsun-hasan-yilmaz-3-sv8gr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerim yollarda seni bekliyor,

Sensiz her saniye hüzün ekliyor,

Hasretin kalbime acı yüklüyor,

İnan canım, burnumda tütüyorsun.

Sensiz bitmiyor bu karanlık gece,

Kulağıma adını fısıldar yastığım bile.

Sensizlik yüreğime doldurur çile,

İnan canım, burnumda tütüyorsun.

Gözlerin aklımda, sesin kulağımda,

Baharım kışa döndü gönül bağımda,

Kurudum sarardım gençlik çağımda,

İnan canım, burnumda tütüyorsun.

Ruhum esen rüzgârda kokunu arar.

Hasretin her an yüreğimde kanar.

Sen yoksan bu ömür ne işe yarar.

İnan canım, burnumda tütüyorsun

Radyolar hep hüzün şarkıları çalıyor

Odamın her yanına özlemin doluyor

Sanki her gölge bana seni soruyor

İnan canım, burnumda tütüyorsun

Bahar gelse de açmaz oldu gülüm,

Yıkıldı umutlarım sustu artık dilim,

Sana uzanmaya korkar oldu elim,

İnan canım, burnumda tütüyorsun.

Bir gün ansızın gelsen, bitse bu acı,

Sensin şu dertli gönlümün tek ilacı,

Gönlümün sultanısın sevdamın tacı,

İnan canım, burnumda tütüyorsun.

Gelsen de artık bitse bu işkence

Hasretini döktüm yine bu şiirede

Bir yudum su ver son nefesimde

İnan canım, burnumda tütüyorsun.

2026', 'Gözlerim yollarda seni bekliyor, Sensiz her saniye hüzün ekliyor, Hasretin kalbime acı yüklüyor, İnan canım, burnumda tütüyorsun. Sensiz bit...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yılmaz 3']::text[], 8.5, '{"poet":"Hasan Yılmaz 3","poet_slug":"hasan-yilmaz-3","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/burnumda-tutuyorsun-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-ali-riza-malkoc-qsog2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hasret kaldık huzura, bir yudum olsa kâfi

Kaprislerden arınmış, sadeliği özledim

Maddeye esir düşen, insan olur mu safi?

Duyguyla akortlanmış, önceliği özledim

Çıkar uğruna bozduk, zaten şaşmış mizanı

Güçlüye kalkan ettik, kör ederek vicdanı

Mazlumun ahıyla bak, yıkıldı hak divanı

Olmayan adaletin, hukukunu özledim

Eskiden dert ehlinin, bağrı sessiz yanardı

Yürekteki yaralar, için için kanardı

Dost kıymetin bilenler, vefa ile anardı

Kervanı belli olan, gam yükünü özledim

Yad ellere özendik, unuttuk has mirası

Gösterişe yenildi, töremizin esası

Üstümde eğri durur, elin taklit libası

Başkalaşmış kültürün, öz kökünü özledim

Perde kalktı aradan, bütün kirler saçıldı

Sağlam sandığım sandık, kırılınca açıldı

Gizlenen kokuşmuşluk, görülünce kaçıldı

İçi çürük cevizin, kabuğunu özledim

Riyadan uzak durup, mertlik olsa özünde

Yalan dolan bilmeden, sadık kalsa sözünde

Muhabbetin ateşi, hiç sönmese közünde

Doğruluk - dürüstlüğü, gerçekliği özledim

Özledim ben özledim, hep yolunu gözledim

Her daim vicdanımı, adaletle sözledim

Doksan olan derdimi, bu gidişle yüzledim

Esaretten kurtulmuş, insanlığı özledim

Ali Rıza Malkoç

Samsun, 18.11.2026

arm.web.tr', 'Hasret kaldık huzura, bir yudum olsa kâfi Kaprislerden arınmış, sadeliği özledim Maddeye esir düşen, insan olur mu safi? Duyguyla akortlanmı...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Malkoç']::text[], 8.5, '{"poet":"Ali Rıza Malkoç","poet_slug":"ali-riza-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ozledim-1173-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan kalmasın', 'yalan-kalmasin-mahmut-kasapoglu-mnkda', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sustukça sinemde çığlık saklarım,

Yüreğim kırılsa figan olmasın.

Kendi yangınımda sessiz yanarım,

Bir damla gözyaşım umman olmasın.

Düştüğüm yerlerden göklere baktım,

Dua kandilini bağrımda yaktım.

En ağır hükmü ben kendime yazdım,

Vicdanım bir ömür zindan olmasın.

Ne bahar beklerim ne açan gülü,

Her mevsim savurdum ayrılık külü.

Dalında lal oldu gönül bülbülü,

Son nefesim bile pişman olmasın.

Bir gün aynalarda kendimle kaldım,

Yüzümde yılların izine daldım.

Dünyaya ne verdim, ondan ne aldım?

Hesabım mahşerde noksan olmasın.

Sevda bir emanet, ömür bir konak,

Kimine gülistan, kimine tuzak.

Giderken ardımda kalırsa bir hak,

Bir garibin ahı ferman olmasın.

Biter elbet bir gün çetin imtihan,

Sabırla yoğrulur yaralı insan.

Kasapoğlu der ki: fanidir cihan,

Adımdan geriye yalan kalmasın.', 'Sustukça sinemde çığlık saklarım, Yüreğim kırılsa figan olmasın. Kendi yangınımda sessiz yanarım, Bir damla gözyaşım umman olmasın. Düştüğüm...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yalan-kalmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derin Kader', 'derin-kader-ali-hasan-gokalp-9a2j6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eğer derinlik varsa orada kaybolmayı dert etme.

Kader seninle oynayacak aldırış etme.

Her şey bir kuyunun içinde.

Kendi kara deliğinin şeklinde.', 'Eğer derinlik varsa orada kaybolmayı dert etme. Kader seninle oynayacak aldırış etme. Her şey bir kuyunun içinde. Kendi kara deliğinin şekli...', ARRAY['Türk Edebiyatı','Şiir','Ali Hasan Gökalp']::text[], 8.5, '{"poet":"Ali Hasan Gökalp","poet_slug":"ali-hasan-gokalp","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/derin-kader-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıcak Ateş', 'sicak-ates-yasar-baykal-tlqn2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalbime söyle

Aşk kuru kalbime

Gerçekten, kalbin benim için mi?

Kalbim,

Kestane çatlar gibi 

Kabukta temas sesi

İçinde aşk kırıntısı

Sıcak ateş

Aşk buzlukta kalmış

Kalbim donmamış

Gir kalbime

Söyle

Kalpler yeterli

Şimdilik yeterli

Gerçekten kalbin,

Kalbin benim için mi?

İlk tomurcuk gibi mi?

İnci büyüsü gibi mi?

Söyle

Kalbime söyle', 'Kalbime söyle Aşk kuru kalbime Gerçekten, kalbin benim için mi? Kalbim, Kestane çatlar gibi  Kabukta temas sesi İçinde aşk kırıntısı Sıcak a...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Baykal']::text[], 8.5, '{"poet":"Yaşar Baykal","poet_slug":"yasar-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gercekten-kalbin-benim-icin-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde kalan söz', 'i-cimde-kalan-soz-mahmut-kasapoglu-u4sgb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensizlik bir denizdir, kıyısı bilinmeyen,

Her dalgası bir ömür yıkıp yine dinmeyen.

Hasretle çırpınarak bir gülüşe varmayan,

Alnıma kader diye yazılıp silinmeyen.

Gölgene dokunurken elim boşlukta yanar,

Geceler kirpiğimde seni ağıtla anar.

Adını söylemeye dilim varmaz bir türlü,

Her hecesi bağrımda bin ayrılıkla kanar.

Bir söz değil, bir bakış neler neler söylermiş,

Sevda susan dillerde en derinden inlermiş.

Kavuşmak bir masalsa, ayrılık bir hakikat;

Gönül hiç gelmeyeni yıllar yılı beklermiş.

Rüzgâr eski izlerle avuçlarımdan geçer,

Her yaprakta bir veda, her mevsim bir bir göçer.

Zaman bile yorulur seni benden silmekten,

Kalp, unutmak isterken yeniden seni seçer.

Ne yollar hiç kısaldı, ne de bekleyiş bitti,

Her sabah umut doğdu, her akşam sensiz gitti.

Bir ömür suskun kaldım, dile gelmez gönülle;

Adın, en uzun sözüm, dudaklarımda yitti.

VI

Varsın kavuşamasın gözlerimiz dünyada,

Aşk bazen vuslat değil, sadakattir duada.

Bir yadigâr kalacak benden geriye bir gün:

"Sevmiş, söyleyememiş" yazsın taşım orada.', 'Sensizlik bir denizdir, kıyısı bilinmeyen, Her dalgası bir ömür yıkıp yine dinmeyen. Hasretle çırpınarak bir gülüşe varmayan, Alnıma kader d...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/icimde-kalan-soz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyıya varamayanlar', 'kiyiya-varamayanlar-tek-i-nsan-cok-duygu-arfed', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kıyıya Varamayanlar

Ne düşünüyorsun,

Bilinmez denizde gibisin.

Ruhun derinlerde,

Sense yüzeyde.

İkisi de çırpınıyor

Boğulmamak için,

Her insan gibi

Hayata tutunmaya.

Kimi dalgayla savaşır,

Kimi kendisiyle.

Zor bu hayat.

Bir gün varacağız kıyıya,

Çırpınacağız yine de orada.', 'Kıyıya Varamayanlar Ne düşünüyorsun, Bilinmez denizde gibisin. Ruhun derinlerde, Sense yüzeyde. İkisi de çırpınıyor Boğulmamak için, Her ins...', ARRAY['Türk Edebiyatı','Şiir','Tek İnsan Çok Duygu']::text[], 8.5, '{"poet":"Tek İnsan Çok Duygu","poet_slug":"tek-i-nsan-cok-duygu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kiyiya-varamayanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Götürün getirin yollar', 'goturun-getirin-yollar-sedat-hunker-fkuv0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaç özlü gittiyse sizde onları

Kaç yüzlü gittiyse sizde onları

Kaç gözlü gittiyse sizde onları

Götürün getirin taş toprak yollar

Kaç telli gittiyse sizde onları

Kaç güllü gittiyse sizde onları

Kaç kullu gittiyse sizde onları

Götürün getirin taş toprak yollar

Kaç boylu gittiyse sizde onları

Kaç soylu gittiyse sizde onları

Kaç toylu gittiyse sizde onları

Götürün getirin taş toprak yollar

Kaç kaşlı gittiyse sizde onları

Kaç yaşlı gittiyse sizde onları

Kaç başlı gittiyse sizde onları

Götürün getirin taş toprak yollar

Kaç canlı gittiyse sizde onları

Kaç yanlı gittiyse sizde onları

Kaç kanlı gittiyse sizde onları

Götürün getirin taş toprak yollar

Kaç halli gittiyse sizde onları

Kaç elli gittiyse sizde onları

Kaç dilli gittiyse sizde onları

Götürün getirin taş toprak yollar

Kaç bağlı gittiyse sizde onları

Kaç çağlı gittiyse sizde onları

