INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tabela', 'tabela-karanlikta-sakli-isik-10nyq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabah, bir işçinin cebine

iki lokma ekmek koyup çıktı evden.

Karısı, gömleğinin yakasını düzeltti.

Çocuk, uykunun içinden el salladı.

Adam kapıyı kapattı.

Kapı bilmedi vedalaştığını.

Ayakkabıları bilmedi

birazdan dünyanın en ağır yolunu yürüyeceğini.

Evine yakın caddeden bindi servise.

Temiz kokan kıyafetlerini değiştirdi.

Siren sesiyle başladı mesaisi.

Fabrikada demir kızıldı.

Sema bacaların isiyle kararmıştı.

Vinç gölgesini bir insanın üzerine bıraktı.

Cıvatalar yerlerinden utanmadı.

Alarm, boğazında düğümlenen sesi

kimseye duyuramadı.

Sonra…

Bir ses düştü yere.

Ne gökten gelmişti

ne de yerin altından.

Bir insanın yarım kalmış ömrüydü bu.

Yerde onlarca baret.

İçinde hâlâ başın sıcaklığı.

Onlarca eldiven.

Parmaklarının son kez tuttuğu dünyadan boşanmış.

Duvar dibinde,

mesaisi bitmeden öksüz kalmış

onlarca çift iş ayakkabısı.

Habaş''ın demirleri soğumadı,

ama o gün bazı evlerin sobası

ömür boyu yanmayacak bir kışa girdi.

Bir çocuk akşam babasını çizdi yine.

Kâğıdın kapısına bir kol ekledi,

dışarıdan açılabilsin diye.

Annesi kalemi elinden aldı,

bazı kapılar

çizilince açılmıyordu.

Anneler oğullarının fotoğrafını öptü.

Camın üzerinde dudak izi kaldı.

Oğlunun yanağında kalması gereken

son sıcaklık,

bir çerçevenin soğuk alnına emanet edildi.

Bir yerlerde

birileri rakamları topladı.

Kaç ton demir?

Kaç saat üretim?

Kaç lira zarar ve mahkeme masrafı?

Kimse hesap makinesine

o çocukların kaç gece babalarını bekleyeceğini giremedi.

Kimse bilanço tablosuna

annelerinin ömründen düşülen yılları yazamadı.

Oysa denetim düzgün yapılsaydı,

patron odalarına girip güler yüzle çıkılmasaydı,

uyarılar daha ciddiye alınsaydı…

Belki bugün

o adamlar alınlarındaki teri silip

çocuğunun saçını karıştıracaktı.

Şimdi o evlerde

bir tabak fazla, bir sandalye boş duruyor sofrada.

Kimse kaldırmaya kıyamıyor.

O eksiklikler

boşluk değildir;

insanın oturup da bir daha kalkamadığı

koca bir ömürdür.

Ben o işçilerin ardından

siyah bir kurdele bağlamayacağım.

Fabrikanın kapısına bir tabela asacağım:

Ürettiğiniz kadar değer görmek

yaşamak değildir.

İşçi rakamlarla ifade edilen değil,

rakamlara değer verendir.

Her sabah içeri giren

herkes baksın diye.

Belki bir gün

işçilerin hayatı,

makinelerin durmasından daha önemli gelir birilerine.

Bir gün

iş çıkışında sirenler değil,

çocukların sevinci duyulur.

---

Mezarlıkların en ağır taşı mermer değil;

bir işçinin eve götüremediği son ekmektir.', 'Sabah, bir işçinin cebine iki lokma ekmek koyup çıktı evden. Karısı, gömleğinin yakasını düzeltti. Çocuk, uykunun içinden el salladı. Adam k...', ARRAY['Türk Edebiyatı','Şiir','Karanlıkta Saklı Işık']::text[], 8.5, '{"poet":"Karanlıkta Saklı Işık","poet_slug":"karanlikta-sakli-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/tabela-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Matem-i Ebedi', 'matem-i-ebedi-batinhan-bucak-1ru8y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '​Hüzn ile büründü bu diyar, bî-ser ü tâktır,
Göklerde melâike, yerde küre nâktır.
Tîg-i celâdetle süzülen rûh-u musaffâ,
Gam defterine sığmayan âh-ı muhâktır.

​Güm-bâ-güm olurken sesimiz nâle-i zâre,
Baktık kalakaldık o mübârek yâdigâre.
Asrın başı bî-nûr idi, sensiz kalan âlem,
Hîçbir tabibel eyleyemez derdine çâre.
​
Müstağrak iken rûh-u vatan zıl-li melâle,
Döndü bu cihan sanki perîşan bir hayâle.
Tâ haşre dek eyler seni bu millet medih ü yâd,
Ey şâh-ı zafer, nâil olursun bu kemâle!', '​Hüzn ile büründü bu diyar, bî-ser ü tâktır, Göklerde melâike, yerde küre nâktır. Tîg-i celâdetle süzülen rûh-u musaffâ, Gam defterine sığma...', ARRAY['Türk Edebiyatı','Şiir','Batınhan Bucak']::text[], 8.5, '{"poet":"Batınhan Bucak","poet_slug":"batinhan-bucak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/matem-i-ebedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fani dünyada', 'fani-dunyada-berika-turna-new2t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne kadar oldu saymadım gitti 

Fani dünyada bir gün görmedim gitti 

Gençliğim rüzgar gibi geldi geçti 

Kalpteki sızılarım hiç geçmedi 

Yalnızdım dünyayla baş başa 

Kimseler yoktu yanımda 

Savrulup akşamları kaldırımlarda 

Gözyaşlarımla bir ben kaldım…', 'Ne kadar oldu saymadım gitti  Fani dünyada bir gün görmedim gitti  Gençliğim rüzgar gibi geldi geçti  Kalpteki sızılarım hiç geçmedi  Yalnız...', ARRAY['Türk Edebiyatı','Şiir','Berika Turna']::text[], 8.5, '{"poet":"Berika Turna","poet_slug":"berika-turna","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gun-gormedim-gitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni içimde seveceğim', 'seni-icimde-sevecegim-fahrein-qwmuh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senden sonra bu şehir gurbet oldu,

Son otobüs geçer, ışığım yanar.

Eskiden «Eve vardın mı?» derdin ya,

Şimdi eve dönsem kimin haberi var?

Sana mektuplar yazdım gecelerce,

Bir kez de sesimden duy diye aradım.

«Alışırsın,» dedin, «geçer zamanla.»

Ben her sustuğunda baştan anlattım.

Bir dost ağzından duydum o akşam,

«Biri var hayatında,» dedi usulca.

«İyiymiş,» dedim, sesim titremedi,

Eve varıp ışığı yakıncaya kadar.

Ben seni içimde hep seveceğim,

Bir daha çalmam ben senin kapını.

Sen mutlu ol, ben burada kalırım,

Gurbet duymasın ağladığımı.

Fotoğraflarını sildim bir bir,

Son mektubu yırttım, sabah oluyordu.

İki fincandan birini kaldırdım,

Elim ertesi gün yine onu aradı.

Dilerim o da sorar, «Eve vardın mı?»

Gece yol uzarsa sesini duyar.

Bir gün onunla gülerken görürsem,

İçim acır elbet, yine de gül sen.

Son otobüs geçti, ışığı söndürdüm.

Sana yazacağım her şeyi içime gömdüm.', 'Senden sonra bu şehir gurbet oldu, Son otobüs geçer, ışığım yanar. Eskiden «Eve vardın mı?» derdin ya, Şimdi eve dönsem kimin haberi var? Sa...', ARRAY['Türk Edebiyatı','Şiir','Fahrein']::text[], 8.5, '{"poet":"Fahrein","poet_slug":"fahrein","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-icimde-sevecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalan Ömrümle Geldim Düet', 'kalan-omrumle-geldim-duet-ben-otuzdort-fz7ev', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'KALAN ÖMRÜMLE GELDİM

Kadın – Erkek Düeti

KADIN:

Sana ait benliğim,

Bir kelebek gibi kanat çırpıyor gelişine.

İçimde ne varsa sana doğru uçuyor.

Yüreğim, yolunu gözlerinde buluyor.

Sevdana bir öpücük bırakıyorum,

Kurak mevsimlerini dudaklarımla bahara yamıyorum.

Kalsana adamım…

Bu defa gitme.

ERKEK:

Ben zaten hangi yöne gitsem

Bir ucum sende kalıyor.

Adını anmadan geçirdiğim geceler

Sabahıma senin sesinle uyanıyor.

Gel kadınım…

Yüreğimde sana ayırdığım yer

Hiçbir mevsime kapalı değil.

KADIN:

Sarmalasana beni,

Gözlerimin kıyısında bekleyen o çocuk gibi.

Bir ömürlük yer arıyor bakışlarım sende.

Şu yarım kalmış cümlelerimizi

Birbirimizin dudaklarında tamamlasana.

ERKEK:

Sen de tut ellerimi,

Yarım kalmışlığımın öteki ucundan.

Benim de içimde sana açılan

Hiç kapanmamış bir pencere var.

Bir ışık yak…

Bu gece sabahı birlikte karşılayalım.

KADIN:

Bir kez olsun,

Seni özledim desene.

ERKEK:

Bir kez değil,

Bin kez özledim.

Adını içimde sakladığım her yerde

Biraz daha sana yenildim.

KADIN:

Ah adamım!

Sana bensizlik,

Bana sensizlik hiç yakışmıyor.

Gel artık…

Usulca çek kendine beni.

ERKEK:

Ah kadınım!

Benim de sensizliğim

Üzerime büyük geliyor.

Gel…

Üşüyen yanlarını bırak göğsüme,

İçimde hâlâ sana sakladığım bir yaz var.

KADIN:

Sarıl…

Öyle bir sarıl ki

Kollarında bütün fırtınalar dinsin.

ERKEK:

Sarılacağım…

Ama bu defa ayrılığın değil,

Kavuşmanın izini bırakacağım teninde.

KADIN:

Ben sustuğum yerden sana geldim.

Yarım kalan düşlerimi alıp,

Özlemini göğsüme basıp geldim.

ERKEK:

Ben de beklediğim bütün yolları

Senin gelişine serdim.

Bir yanım zaten sende kalmıştı,

Diğer yanımla sana yürüdüm.

BİRLİKTE:

Bir yanımız birbirinde kalmış,

Bir yanımız kavuşmaya hasret.

Ne sen benden eksiksin,

Ne ben senden tamamım.

Kapıyı aç…

KADIN:

Ben sana özlemimle geldim.

ERKEK:

Ben sana ömrümle…

BİRLİKTE:

Biz birbirimize

Kalan ömrümüzle geldik.

BEN34&Hüseyin Erdinç

17.11.2026  02.02', 'KALAN ÖMRÜMLE GELDİM Kadın – Erkek Düeti KADIN: Sana ait benliğim, Bir kelebek gibi kanat çırpıyor gelişine. İçimde ne varsa sana doğru uçuy...', ARRAY['Türk Edebiyatı','Şiir','Ben Otuzdört']::text[], 8.5, '{"poet":"Ben Otuzdört","poet_slug":"ben-otuzdort","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/kalan-omrumle-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Liturgia Cordis', 'liturgia-cordis-asligul-kilic-kq97h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'En sevdiğim ilahi senin ses tellerin,

Bir arp misali, boğazından akıp giden nehir.

İsa’yı değil seni hissediyorum ruhumun en derininde;

Öpücüklerinle kutsa beni, sevgilim.

Bana olan aşkın olsun koruyucu meleklerim,

Biri sağımda, biri solumda yazsın hayatımı.

Senin aşkın bana hem sevap hem de günahtır.

Sensiz geçen her an, mazeretli bir dervişin mihrapta kalışı;

Ellerim koynumda, eksik ve sessiz bir ibadet.

Senin bedenin benim tapmamın farz olduğu bir tapınaktır.

Kokun siner ruhumun en kuytu köşesine,

Cennet dediğin, göğsünde soluklandığım o yerdir.

Gözlerin benim dinimin mihrabı, kalbimin ventrikülü.', 'En sevdiğim ilahi senin ses tellerin, Bir arp misali, boğazından akıp giden nehir. İsa’yı değil seni hissediyorum ruhumun en derininde; Öpüc...', ARRAY['Türk Edebiyatı','Şiir','Aslıgül Kılıç']::text[], 8.5, '{"poet":"Aslıgül Kılıç","poet_slug":"asligul-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/liturgia-cordis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sonbahar', 'son-sonbahar-hamza-mamas-qpnir', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seyret ki bu ne son sonbahar 

Ne açan son vargit

Çek yıldızlarını göğümden ey ütopya

Hayrı hayale saklamış düşler

Son cemrenin son mahsulü 

Neye yarar

Takvimlerin devreden sayıları

İhtişamlı sultansız saraylar

Memleketimde bitmeyen hasret

Umutsuz gecenin sabahında 

Bedesten çocukları 

Yağmura teslim yüreğinde uyuya dursun

Bu neyin eyvahı

Bu ne fırtına böyle

Dursun angarya

Cemreyle çimlenen filiz başağını doldursun

Hayal dediğin hikaye ben uydurdum', 'Seyret ki bu ne son sonbahar  Ne açan son vargit Çek yıldızlarını göğümden ey ütopya Hayrı hayale saklamış düşler Son cemrenin son mahsulü  ...', ARRAY['Türk Edebiyatı','Şiir','Hamza Mamaş']::text[], 8.5, '{"poet":"Hamza Mamaş","poet_slug":"hamza-mamas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seyret-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kul Ahmete ya Ali', 'kul-ahmete-ya-ali-ahmet-sercan-kahriman-xewoh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fani Kahriman''ın sırları aşan

 Diyar ellerde hüsrana ulaşan

 Dermansız derde çare koşan

 Merhem eyle kul Ahmet''e ya Ali

İnsanı insana ayna sanan

 Gafillere her dem kanan

 Yezitler düzelir diye uman

 Âkil eyle kul Ahmet''e ya Ali

İyilik iyidir deyip durmadan

 Siyaha hiç toz kondurmadan

 Gözyaşıyla değirmen tutan

 Yol göster kul Ahmet''e ya Ali

Gönül incitenden vefa beklemekten

 Her sözü gönülde derde çevirmekten

 Hakkı bilmeyene doğru söylemekten

 Kuvvet ver kul Ahmet''e ya Ali

Derdimi desem hâlimi bilmeyenden

 Gönülde açılan Kâbe''yi görmeyenden

 Bir kelamın ardını dinlemeyenden

 Sabır ver kul Ahmet''e ya Ali

Gönül yorgun düşmüş söz anlatmaktan

 Usandım hakikati gizli tutmaktan

 Bir lokma muhabbete hasret kalmaktan

 Gönül ver kul Ahmet''e ya Ali

Dost bildiklerimden yara almaktan

 Hakikat uğruna yalnız kalmaktan

 Kendi nefsim ile hesaplaşmaktan

 Edep ver kul Ahmet''e ya Ali', 'Fani Kahriman''ın sırları aşan  Diyar ellerde hüsrana ulaşan  Dermansız derde çare koşan  Merhem eyle kul Ahmet''e ya Ali İnsanı insana ayna s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sercan Kahriman']::text[], 8.5, '{"poet":"Ahmet Sercan Kahriman","poet_slug":"ahmet-sercan-kahriman","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kul-ahmete-ya-ali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılan', 'yilan-ufuk-tan-sv5lv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceye dolanan sessiz bir gölge,

Siyah yilan, kıvrılır sessizliğe.

Pul pul parıldar karanlığın dili,

Toprağın koynunda gizli bir deli.

Zehir değil sanki derdinden akan,

Yalnızlık sarılmış, ateşte yakan.

Otlar arasında kaybolur izi,

Görenler hatırlar derin bir giz''i.

Sessizce süzülür, kimseden ses yok,

Bu yaban dünyada çilesi pek çok.

Siyahın en safı, gecenin rengi,

Yeryüzünün dilsiz, gizemli dengi.', 'Geceye dolanan sessiz bir gölge, Siyah yilan, kıvrılır sessizliğe. Pul pul parıldar karanlığın dili, Toprağın koynunda gizli bir deli. Zehir...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Tan']::text[], 8.5, '{"poet":"Ufuk Tan","poet_slug":"ufuk-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yilan-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günümüz Şeyhleri', 'gunumuz-seyhleri-hatice-erturk-w1ssa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kibirden kaleler inşa etmişler 

Dışını tevazuyla süslemişler

Takva boyasıyla da boyamışlar

Tezgahı kurmuş günümüz şeyhleri 

Belâgati bir oltaya takmışlar 

Hasenatı yem olarak atmışlar

Güleryüzü sanki maske yapmışlar 

Oltayı atmış günümüz şeyhleri 

Âyet hadis ile süsleyip sözü

Dünya makamına dikmişler gözü

Hakk''a değil halka dönmüşler yüzü

Kıbleyi şaşmış günümüz şeyhleri

Nefis tarlasına gafleti ekmiş

Riya, cehalet tohumunu serpmiş

Gönül yıkmak için kılıcı çekmiş

Pusu kurmuş hep günümüz şeyhleri

İlim irfan değil şöhret dertleri 

Bedavadan ettirirler hizmeti

Bilmezler ne muhabbet ne edebi

Mânâdan uzak günümüz şeyhleri 

Hakikat ehlini tenzih ederiz

Bizler Hakk dostu izinden gideriz

Erenlere canı kurban ederiz

Anlamaz bizi günümüz şeyhleri', 'Kibirden kaleler inşa etmişler  Dışını tevazuyla süslemişler Takva boyasıyla da boyamışlar Tezgahı kurmuş günümüz şeyhleri  Belâgati bir olt...', ARRAY['Türk Edebiyatı','Şiir','Hatice Ertürk']::text[], 8.5, '{"poet":"Hatice Ertürk","poet_slug":"hatice-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gunumuz-seyhleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırat Nehri', 'firat-nehri-ufuk-tan-vhqgs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Toprakla göğün arasında gümüş bir yılan,

Binlerce yıldır söylenir senin destanın.

Doğu’nun yüreğinden süzülüp gelen ses,

Uzak dağlarda yankılanır nefesin, nefes.

Eski çağlar tanık, surların gölgesinde,

Bir medeniyet uyanır Fırat’ın sesinde.

Mezopotamya’nın kurak dudaklarına cân,

Sen ömrü verdin, sen oldun bu toprağa can.

Kimi zaman coşkun, kimi zaman sakin akar,

Hüzünlü bir duman dağların ardını yakar.

Tarihin saklı sayfaları suya yansır,

Her dalgada bir efsane, bir anı canlanır.

Ak ey ulu nehir, bin yıllık yoldan ak,

Bırakma bu toprakları öksüz ve yalnız bırak.

Sırların saklı kalsın derin mavisinde,

Fırat söyler, Dicle dinler bu kadim beste.', 'Toprakla göğün arasında gümüş bir yılan, Binlerce yıldır söylenir senin destanın. Doğu’nun yüreğinden süzülüp gelen ses, Uzak dağlarda yankı...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Tan']::text[], 8.5, '{"poet":"Ufuk Tan","poet_slug":"ufuk-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/firat-nehri-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annemin Çiçekli Fistanı', 'annemin-cicekli-fistani-sevgi-gul-i-lkan-ufy0j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çiçekli fistan 

Annemden kalma 

Eskici alma 

Kalbi dağlama

Allah aşkına 

Hasretini al 

Gözyaşımı al 

Ver üç beş mandal 

Fistanı giydim

Pek çok özledim 

Kabrine gittim 

Çiçekler diktim

Anamla beni

Takım giydirdim 

Çok hüzünlendim

Oy ben neyleyim

Gözlerim doldu

Bulut boşalsın

Benle ağlasın

Annem duymasın 

Annem duygusal 

Kalp acın yağar 

Tez sessize al 

Toprak su taşar 

Anne denince 

Yüzme bilmem bak 

İmdat deyince

Kim kurtaracak

Çok yağmur yağdı

Çiçek sulandı

Ağlamadım ki

Annem inandı 

Fistanım ıslak

Eve akacak

Hüzün dolacak

İç acıyacak 

Eskici bir bak

Acım çok yeni

Geniş bedeni

Kaybetti beni 

Balkona çıktım

Fistanı astım 

Üç beş mandalla

Hüzün takasladım...', 'Çiçekli fistan  Annemden kalma  Eskici alma  Kalbi dağlama Allah aşkına  Hasretini al  Gözyaşımı al  Ver üç beş mandal  Fistanı giydim Pek ç...', ARRAY['Türk Edebiyatı','Şiir','Sevgi Gül İlkan']::text[], 8.5, '{"poet":"Sevgi Gül İlkan","poet_slug":"sevgi-gul-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/cicekli-fistan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan İçin', 'vatan-i-cin-kerim-yavuz-8edp1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Helal olsun bize diye atalarımızın kanı

Hayatın her zerresini yaşarız bu vatan için

Bilsinler pişman ederiz bu toprağa yan bakanı

Yeri gelirse ölüme koşarız bu vatan için

Alparslandan atatürke tarihi süreçten geçtik

Bu toprakları inançla kendimize vatan seçtik

Yüregimizin üstüne bütün ulus yemin içtik

Türke yakışır destanlar yazarız bu vatan için

Tüm kardeşlik türküleri dolaşacak dilden dile

Bu bayrak miras olarak kalacak yeni nesile

Ulusa ihanet eden kardeşimiz olsa bile

Bütün ulus damarına basarız bu vatan için

Dalgalansın bayrağımız rengi kandanda kırmızı

Çiğnettirmeyiz nağmerde tek karış toprağımızı

Hiç kimsa zaafa düşüpte denemesin sabrımızı 

Sabır zorlanırsa eğer taşarız bu vatan için

Kimseye boyun eğmeyiz artık bu böyle biline

Özgürlük bütün ulusun yuva yapmıştır diline

Amacımız başarıyla vardığında menziline

Şarkılarla türkülerle coşarız bu vatan için

Yavuzoğlu şiirinle Türkün yüreğine ses ver

Elbette tüm duyguların gider hedefine değer

Nereden olursa olsun bir tehlike varsa eğer

Seller gibi bendimizi aşarız bu vatan için', 'Helal olsun bize diye atalarımızın kanı Hayatın her zerresini yaşarız bu vatan için Bilsinler pişman ederiz bu toprağa yan bakanı Yeri gelir...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/vatan-icin-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Yok Yalnızlığımın', 'adi-yok-yalnizligimin-orhan-karatasguler-4-xpn78', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adı konmamış bir yalnızlık sarmış dört yanımı

Kuşanmışım ibrişimden gece hüzünlerini 

Kelam dile , kalem kağıda küsmüş 

Ben susmuşum 

Beden ruha dar 

İçimde göçe durmuş 

İyi niyetime dair ne varsa 

Bıraksam diyorum vicdanımı bir kenara 

Az soluklansam 

Hayat banada varmış desem 

Kim kırılır, kim kalır 

Bir görsem 

Hazır yenilmişken

Sırtım yere gelmişken 

Silkelensem

Bir daha kalksam 

Savursam ellerimle 

Tozu dumana katsam 

Kurtulsam 

Ardımdan tutan ne varsa 

Önüme baksam', 'Adı konmamış bir yalnızlık sarmış dört yanımı Kuşanmışım ibrişimden gece hüzünlerini  Kelam dile , kalem kağıda küsmüş  Ben susmuşum  Beden ...', ARRAY['Türk Edebiyatı','Şiir','Orhan Karataşgüler 4']::text[], 8.5, '{"poet":"Orhan Karataşgüler 4","poet_slug":"orhan-karatasguler-4","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/adi-yok-yalnizligimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Beyefendi Mektubu', 'bir-beyefendi-mektubu-volkan-gulbitti-8tbx8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılmalıyım senden.

Öyle çok şey söylemeden,

Son bir tartışmaya girmeden,

Kimin daha çok sevdiğini

hesaplamadan

Aslında söyleyecek çok şeyim var

İçimde biriktirdiğim,

Sana anlatmak için doğru zamanı beklediğim

Bir çok şey 

Ama,

Her şeyi anlatmak,

Her şeyi düzeltemiyor.

Ben sana kaç kere kendimi anlatmaya çalıştım,

Hatırlamıyorum bile.

Bazen bir yanlış anlaşılmayı düzeltmek için,

kırıldığımı belli etmemek için,

Bazen de aramız bozulmasın diye

Kendi haklılığıma  yüzsüzlük ettim

Şimdi dönüp bakıyorum da

Ne çok uğraşmışım kalabilmek için

Oysa kalmak isteyenin

Bir sebep bulmasına gerek yok

Gitmek isteyenin de

Bahanesi  bitmez.

Sana kızgın mıyım

Belki biraz

Ama öfkemden daha büyük olan 

yorgunluğumdur.

Anlatamadığım yerden yorgunum,

Anlaşılmadığım yerden yorgunum

Seninle konuşabilmek için

Sabahı  beklerdim.

Şimdi konuşsak ne söyleyeceğimi bilmiyorum.

Ne değişti diye sorsan,

İnan, tek bir şey gösteremem.

Ben yine de güzel hatırlamak istiyorum seni.

Birlikte güldüğümüz anları,

Hiçbir şey düşünmeden konuştuğumuz ve

Birbirimize iyi geldiğimiz zamanları…

Hepsini bir kenara atamam.

Yaşadığım güzel şeyleri

Sonunda üzüldüm diye inkâr edemem.

Fakat şunu da bilmeni isterim:

Ben artık birinin hayatında kalabilmek için

Kendimi sürekli anlatmak istemiyorum.

Sevgimi ispatlamak,

Niyetimi açıklamak,

Her yanlış anlaşılmanın 

hesabını vermek istemiyorum.

Sevmek bu kadar zor olmamalıydı.

Ben senden büyük şeyler istemedim.

Biraz anlayış, biraz samimiyet,

Bir de yanındayken kendim olabilmeyi…

Bunlar sana göre çok şey mi 

Bilmiyorum.

Artık bunu da tartışmayacağım.

Ama eskisi gibi de olamam.

Bazı şeyleri affediyorum

Yalnız eskisi gibi hissedemiyorum.

İşte benim sana anlatamadığım tarafım da bu.

Ne sana kötü bir gelecek diliyorum

Ne de bir gün pişman olmanı bekliyorum.

Mutlu ol.

Gerçekten mutlu ol.

Bunu söylerken içimin biraz burkulması

Dileğimin samimiyetini değiştirmiyor.

Şimdi müsaade et, gideyim.

Kırıldığım yerleri anlatmayacağım kimseye.

Seni kötülemeyeceğim.

Birlikte yaşadıklarımızı

Ayrılığın arkasına saklayıp kirletmeyeceğim.

Ben seni sevdim.

Bunu inkâr edecek kadar

Kendime yabancı değilim.

Ama artık gitmeliyim.

Bir beyefendi gibi…

Ve inan,

Hayatından sessizce çıkıyorsam,

Sevgimin bittiği anlamına gelmez.

Ben hep böyleyim 

severken giderim.

Çünkü kalırsam 

kendime haksızlık ederim.

Benimki de biraz böyle

Bir beyefendi gidişi

Volkan Gülbitti', 'Ayrılmalıyım senden. Öyle çok şey söylemeden, Son bir tartışmaya girmeden, Kimin daha çok sevdiğini hesaplamadan Aslında söyleyecek çok şeyi...', ARRAY['Türk Edebiyatı','Şiir','Volkan Gülbitti']::text[], 8.5, '{"poet":"Volkan Gülbitti","poet_slug":"volkan-gulbitti","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/bir-beyefendi-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sattılar Bize', 'sattilar-bize-kerim-yavuz-tiye5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'alancı bir beşikte sallanıp duruyoruz 

Senelerdir uyuduk ninni sattılar bize.

Düşündük mü acaba nereye koşuyoruz

Gözlerimiz geride dünü sattılar bize.

Kapandık içimize boynumuzu eğerek

Her şey ortada işte uzun söze ne gerek

Kandırdılar bizleri ulemayım diyerek.

Sahtekar sakallılar dini sattılar bize.

Eller uzaya çıktı biz mahrumuz bilgiden.

Haz duysak olmaz mıydı alakadan ilgiden

Açtılar aramızı uzak kaldık sevgiden

Şatafatlı sözlerle kini sattılar bize.

Hiç kimse düşünmedi bal yapan arıları

Bölüştüler birlikte petekdeki balları

Yılar yılı dinledik bitmedi masalları.

Biz gelecek istedik anı sattılar bize.

Yavuzoğlu söylüyor hisse alanlar alsın.

Bırakın sus durmayı herkes sesini salsın.

Böyle şey görülmemiş laf aramızda kalsın.

Tepemizde dolaşan cini sattılar bize.', 'alancı bir beşikte sallanıp duruyoruz  Senelerdir uyuduk ninni sattılar bize. Düşündük mü acaba nereye koşuyoruz Gözlerimiz geride dünü satt...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sattilar-bize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak İşine', 'bak-i-sine-ufuk-tan-x4d64', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabahın ilk ışığıyla düşersin yola,

Rızkını ararsın sağa sola.

Alın terin akar, karışır toprağa,

Emek veren kollar dert görmez asla.

Kimi masabaşında kâğıtla boğuşur,

Kimi tezgahta demirle buluşur.

Kimi tarlada güneşe karşı durur,

Herkesin bir yolu, bir derdi bulunur.

Zorluklar çıksa da bazen karşına,

Yılma sakın, bakma sakın yaşına.

Sanat katarsın yaptığın her işe,

Değer katarırsın bu güzel güneşe.

Kolay değildir rızkı kazanmak,

Her sabah yeniden yollara düşmek.

Senin bu gayretin, bu güzel çaban,

En büyük övgüyü hak eder her an.', 'Sabahın ilk ışığıyla düşersin yola, Rızkını ararsın sağa sola. Alın terin akar, karışır toprağa, Emek veren kollar dert görmez asla. Kimi ma...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Tan']::text[], 8.5, '{"poet":"Ufuk Tan","poet_slug":"ufuk-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bak-isine-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan', 'nisan-ferhat-basaran-f0ipy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kurumuş toprağıma gökyüzünden yağansın

Çünkü sen Nisan''sın...', 'Kurumuş toprağıma gökyüzünden yağansın Çünkü sen Nisan''sın......', ARRAY['Türk Edebiyatı','Şiir','Ferhat Başaran']::text[], 8.5, '{"poet":"Ferhat Başaran","poet_slug":"ferhat-basaran","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/nisan-113-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farzımuhal', 'farzimuhal-kenan-gezici-e9ata', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben burada gölgemleyim, baş başa.

Bir an değil uzunca bir zaman.

Çok şey var konuşacak başını alıp gitmek gibi.

Gölgem gölgelerin ardında zaman zaman.

Gözlerimin içine bakmayı öğrenmedi.

Işıl ışıl olmuyor üstelik.

Derin bir bakışla bakmıyor.

Yalnız senin kahkahalarını duyuyorum.

Ben gülmüyorum.

Daha öğrenmedim, ağlarken gülmeyi.

Duymasınlar sesimi, sen de duyma.

Bir gölgem kalsın yanımda.

Giderken ben onu alacağım yanıma.

Ne saklanıyor şu zalim dünyanın sahnesinde.

Saklanıyor gizli saklı kilitli sandıklarda.

Hep mi yeniden başlar ah kocaman yalan.

Kim düşünü bana ayıracak, sanmam.

Ben gölgemi koydum ortaya.

Ya siz sade almayı öğrenen güruh.

Aldıklarınızla mutlu oldunuz mu acaba.

Ben kendimi dağa taşa yağmura anlatımda.

Ben boynunuzda oldum bir vebal.

Kenan GEZİCİ   18/11/2026', 'Ben burada gölgemleyim, baş başa. Bir an değil uzunca bir zaman. Çok şey var konuşacak başını alıp gitmek gibi. Gölgem gölgelerin ardında za...', ARRAY['Türk Edebiyatı','Şiir','Kenan Gezici']::text[], 8.5, '{"poet":"Kenan Gezici","poet_slug":"kenan-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/farzimuhal-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayan Yok mu?', 'anlayan-yok-mu-kerim-yavuz-798d3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Garip kaldım bu diyarda

Tutan olmadı elimden

Üşüdüm yağmurda karda

Anlayan yok mu halimden

Sözüm geçmiyor feleğe

Tutundum kuru deyneğe

Yüreğim döndü eleğe

Anlayan yok mu halimden

Kader yolumu bağlıyor

Yokluk sinemi dağlıyor

Yüreğim hep kan ağlıyor 

Anlayan yok mu halimden

Ömür geçiyor boş yere

Tükendim göz göre göre

Boynumu büktüm kadere 

Anlayan yok mu halimden

Dertten kurtulmuyor başım

Sel oldu akıyor yaşım

Çatlayacak sabır taşım

Anlayan yok mu halimden

Aklar düşüyor saçıma

Pas vurdu gönül tacıma

Yürek dayanmaz acıma

Anlayan yok mu halimden', 'Garip kaldım bu diyarda Tutan olmadı elimden Üşüdüm yağmurda karda Anlayan yok mu halimden Sözüm geçmiyor feleğe Tutundum kuru deyneğe Yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anlayan-yok-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yak Gemıleri', 'yak-gemileri-ufuk-tan-hydbu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Korkunun prangası çözüldü nihayet,

Dönüşü yok artık bu kutlu seferin.

Geçmişin gölgesi, sönmüş bir menzil,

Bırak arksından baksın acizler kaderin.

Ateşe ver timsallerini dünün,

Küllerinden doğsun keskin bir irade.

Ne bir liman sığınak şimdi, ne bir yön,

Bütün haritalar kopsun, verdim müsaade.

Geriye bakmak, esarete imza atmaktır,

İleriye yürümek, fırtınayla kucaklaşmak.

Bırak yanıp kül olsun tahta ve yelken,

Zafer, ancak yakılan köprülerle başlamak!', 'Korkunun prangası çözüldü nihayet, Dönüşü yok artık bu kutlu seferin. Geçmişin gölgesi, sönmüş bir menzil, Bırak arksından baksın acizler ka...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Tan']::text[], 8.5, '{"poet":"Ufuk Tan","poet_slug":"ufuk-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yak-gemileri-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Polyana Kadın', 'polyana-kadin-ufuk-tan-z2fvh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her karanlık gecenin ardından bir sabah doğar,

Yüzümde hep bir tebessüm, gönlümde umut var.

Bilirim ki bulutlar geçer, güneş geri gelir,

En dertli anımda bile kalbim huzuru bulur.

Bardağın boş tarafına bakmayı bilmem ben,

Mutluluk damlaları düşer ıslak penceremden.

Bozulur mu sandınız en neşeli düşlerim?

Ben her acının içinde bir güzellik düşlerim.

Bilemem ki küsmek nedir, karanlığa dalmayı,

Her yokuşun sonunda bir sevinç bulmayı...

Çünkü hayat güzeldir, inanmak gerek buna,

Gönlümdeki neşe benzer pırıl pırıl bir yarına!', 'Her karanlık gecenin ardından bir sabah doğar, Yüzümde hep bir tebessüm, gönlümde umut var. Bilirim ki bulutlar geçer, güneş geri gelir, En ...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Tan']::text[], 8.5, '{"poet":"Ufuk Tan","poet_slug":"ufuk-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/polyana-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-mehmet-karaca-2-gapbs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Patlar insan,

‎Volkan gibi bazen.

‎Stres; bastırır yukarıdan tonluk taş gibi.

‎

‎Gün; geçer gider bazen sadece bitmek için.

‎Taşı sıksan suyunu çıkartamazsın bazı insanlardan.

Ağır ama zorundadır insan.

‎Susar insan,

‎Gölge gibi;

‎İzler adım ve hareketleri.

‎Bir çekmece de buluverir aradığı şeyi.

‎

‎Saklar insan,

‎İstihbaratçı gibi asıl gerçekleri.

‎

‎Bekler insan,

‎Alışır ve alıştırılır;

‎Kedi gibi.

‎Bir ihtimal doymak için her duyguya.

‎

‎Rüya görür sürekli insan,

‎Bazen kekremsi, bazı tatlı, bazı kaos.

‎

‎Sonunda.

‎Yaşlanır insan.

‎

‎17/11/2026

‎', 'Patlar insan, ‎Volkan gibi bazen. ‎Stres; bastırır yukarıdan tonluk taş gibi. ‎ ‎Gün; geçer gider bazen sadece bitmek için. ‎Taşı sıksan suy...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karaca 2']::text[], 8.5, '{"poet":"Mehmet Karaca 2","poet_slug":"mehmet-karaca-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/insan-1288-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurt Kapanı 1/1', 'kurt-kapani-1-1-abdulhakim-soyal-y3s5s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aynalar, aynalar!..  Ses verin! Yarım kalan dünlere inat; yanıp tükenen hayatımın aksine bakarak!..
Yaşanmayan zaman mıydı yoksa ruh mu?
Toprak Kana Hasret, hayatsa kanayan bir yara,
Kansa bir nefes timsali oksijene Hasret!..


İç içe geçmiş gelecek ve mazi...
Dün müydü bugünün habercisi?..
Yoksa yarın mı dünün yarım kalan hikâyesi?
Kurt kapanına dönmüş dönence mi  şu sefil hayatım?..
Aynalar, aynalar!.. Ses verin gecenin sessiz çığlığına inat...

- KemalHakim... -', 'Aynalar, aynalar!..  Ses verin! Yarım kalan dünlere inat; yanıp tükenen hayatımın aksine bakarak!.. Yaşanmayan zaman mıydı yoksa ruh mu? Top...', ARRAY['Türk Edebiyatı','Şiir','Abdulhakim Soyal']::text[], 8.5, '{"poet":"Abdulhakim Soyal","poet_slug":"abdulhakim-soyal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kurt-kapani-1-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke Seni Tanımasaydım', 'keske-seni-tanimasaydim-ufuk-tan-1v1nw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Keşke seni tanımasaydım,

Adını hiç duymasaydım,

Gözlerinin o derin denizinde,

Bir ömür kaybolmasaydım.

Keşke bakmasaydım o gün yüzüne,

Kapanmasaydı kapılar hüzne,

Dilinden dökülen her tatlı yalan,

Takılmasaydı kalbimin düğümüne.

Şimdi bomboş sokaklar, sessiz gece,

Dilimde acı bir tat, tek bir bilmece:

Seni sevmek miydi en büyük günah,

Yoksa seni tanımak mı hece hece?

Keşke... diyemiyorum bile aslında,

Her şeyin en güzel anında,

Sen gitmiş olsan da bu şehirden,

Hâlâ yankılanıyorsun sol yanımda.', 'Keşke seni tanımasaydım, Adını hiç duymasaydım, Gözlerinin o derin denizinde, Bir ömür kaybolmasaydım. Keşke bakmasaydım o gün yüzüne, Kapan...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Tan']::text[], 8.5, '{"poet":"Ufuk Tan","poet_slug":"ufuk-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/keske-seni-tanimasaydim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvakta İlk Dans', 'duvakta-i-lk-dans-yasar-baykal-zvlud', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelinliğin uçuşuyor

Güzelliğine hayran tüm bakışlar

Aşkımızı gizlemiyor

Kenetli kalpler

Bu dans, bu aşk

Dönelim yavaşça

Bu dans, bu aşk

Sürsün sonsuzca

Sokul

Biraz daha

Tüm yüzler kaybolsun

Tüm gözler kapansın bizim için

Bu gece başka biri yok

Sadece sen, sadece ben

Gelinliğinin ucunda

Beyaz bir rüzgâr

Saçında bin bir ışık

Sanki beni çağırır

Sen döndükçe

Tüm gözler kamaşır

Başın omzuma

Gözlerin gözlerime

Bir ömürlük söz verdi

Bu gece seni saklayayım

Bu dans, bu aşk

Dönelim yavaşça

Bu dans, bu aşk

Sürsün sonsuzca', 'Gelinliğin uçuşuyor Güzelliğine hayran tüm bakışlar Aşkımızı gizlemiyor Kenetli kalpler Bu dans, bu aşk Dönelim yavaşça Bu dans, bu aşk Sürs...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Baykal']::text[], 8.5, '{"poet":"Yaşar Baykal","poet_slug":"yasar-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/duvakta-ilk-dans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu gün son', 'bu-gun-son-ufuk-tan-20why', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sanki bir ömrün özeti gibi,

Yavaşça dökülüyor yapraklar yere.

Ne bir adım ileri, ne bir adım geri,

Zaman asılı kalmış şu loş pencerede.

Dünler çoktan karardı, uzak bir masal,

Yarınlar ise sisli, bilinmez bir dağ.

Elimde kalan sadece bu an, bu hal,

Sanki her şeyin sonu, kopuyor bağ.

Bir yaprak düşer gibi sessiz ve derin,

Kapanıyor ağır kapılar ardına.

Geçmişin yükü silinirken yerinden,

Bakıyorum ömrümün en son akışına.

Gözlerimde biriken yorgun bir veda,

Ne kırgınlık kaldı geriye, ne de hırs.

Gidenlere selam, kalanlara elveda,

Bugün son... Belki de en güzel başlangıçsız.', 'Sanki bir ömrün özeti gibi, Yavaşça dökülüyor yapraklar yere. Ne bir adım ileri, ne bir adım geri, Zaman asılı kalmış şu loş pencerede. Dünl...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Tan']::text[], 8.5, '{"poet":"Ufuk Tan","poet_slug":"ufuk-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-gun-son-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimşekler Üstüme', 'simsekler-ustume-salim-erben-16cx4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Evlât kokusunu vermedi felek,

Bir yastığa baş koyduk yıllar boyu.

Ne bir gülen bebek, ne tatlı dilek,

Büküldü boynumuz, kurudu suyu.

Bir odaya sığdı dünya derdimiz,

Ne bülbüller öttü, ne güller açtı.

Gizli gözyaşıyla geçti ömrümüz,

Mutluluk bizden hep ırakta kaçtı.

Sandım ki bu derttir biter sonunda,

Önce o göçtü gitti ellerimden.

Kaldım bu gurbetin ıssız hanında,

Bir yaprak koptu sanki güllerimden.

Ne arayan kaldı ne soran gayrı,

Evler barklar ıssız, duvarlar soğuk.

Yollarımız o gün bugündür ayrı,

Nefesim göğsümde düğüm ve boğuk.

Bir başıma kaldım yalan dünyada,

Ne bir yaren var ne kapım çalan.

Gözüm yollardadır hayalde düşte,

Beni bu halimde bir yalnızlık salar.', 'Evlât kokusunu vermedi felek, Bir yastığa baş koyduk yıllar boyu. Ne bir gülen bebek, ne tatlı dilek, Büküldü boynumuz, kurudu suyu. Bir oda...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/simsekler-ustume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salyangoz', 'salyangoz-ufuk-tan-e0cvw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İncecik boynuzu, meraklı gözü,

Toprağın üstünde yavaşça yürür.

Korkunca içine saklar yüzünü,

Sırtında dünyası, öylece büyür.

Ne acelesi var, ne de bir telaş,

Yıldızlar şahittir, ay ona sırdaş.

İpeksi iz bırakır geçtiği yola,

Güvenle sarılır minik umuda.

Evimiz taştandır, sarayımız var,

Der sakince sanki o nazik yollar.

Küçücük yüreği, kocaman sevgisi,

Yavaş adımlarla aşılır bu nehir, bu giz.', 'İncecik boynuzu, meraklı gözü, Toprağın üstünde yavaşça yürür. Korkunca içine saklar yüzünü, Sırtında dünyası, öylece büyür. Ne acelesi var,...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Tan']::text[], 8.5, '{"poet":"Ufuk Tan","poet_slug":"ufuk-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/salyangoz-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Kalmamış', 'zaman-kalmamis-salim-erben-gqdhq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyandım ki ömrün zamanı kalmamış,

Gözümün yaşı da derman olmamış.

Yıllar bir yel gibi alıp gitmiş de,

Elde avuçta hiç bir anı kalmamış.

Gurbetin dağında karlar eridi,

Gençliğim bu yolda bitti, çürüdü.

Kervan çoktan göçtü, yoldan yürüdü,

Arkaya bakmaya derman kalmamış.

Dilimde bir eski türkü sızısı,

Yüreğimi yaktı gurbetin acısı.

Sönse ocağımın tütmez bacası,

Bağrımda ne neşe, ne can kalmamış.

Salim Erben der ki, vaktim tamamdır,

Şu yalan dünyada kalan yalandır.

Gelen göçer imiş, gelen yamandır,

Dönüp de bakmaya zaman kalmamış.', 'Uyandım ki ömrün zamanı kalmamış, Gözümün yaşı da derman olmamış. Yıllar bir yel gibi alıp gitmiş de, Elde avuçta hiç bir anı kalmamış. Gurb...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zaman-kalmamis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-ufuk-tan-p9bw4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'insanlar üçe  ayrılır

yukardakiler

ortadakiler

düşenler', 'insanlar üçe  ayrılır yukardakiler ortadakiler düşenler...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Tan']::text[], 8.5, '{"poet":"Ufuk Tan","poet_slug":"ufuk-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/insan-1287-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Elveda Ne Merhaba', 'ne-elveda-ne-merhaba-yasar-baykal-ceavp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalbimde inceden bir sitem

Avcumla üstünü örtmüşüm

Gülüşünün kaldığı fotoğrafın

Çerçevesini silmiş, öpmüşüm

Geçti içinden kaç sonbahar

Geçti içinden koca bir ömür

Nikahından kalma pembe gül

Yalnızlığıma vurulmuş mühür

Bir anlık tesadüftü işte

Dokundu yeniden hafifçe

En kırık yerime, gözlerime

Küçük bir tebessüm bıraktı

Ne bir elveda dedi daha

Ne de yeniden bir merhaba

Dokundu uzaktan hafifçe

En kırık yerime, gözlerime

Ne elveda ne bir merhaba

Kalbimde inceden sitem

Bir yangını bastırıyorum

En kırık yerim, şu gözlerim', 'Kalbimde inceden bir sitem Avcumla üstünü örtmüşüm Gülüşünün kaldığı fotoğrafın Çerçevesini silmiş, öpmüşüm Geçti içinden kaç sonbahar Geçti...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Baykal']::text[], 8.5, '{"poet":"Yaşar Baykal","poet_slug":"yasar-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-elveda-ne-merhaba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçbir Kimse Yanımda Olmadı', 'hicbir-kimse-yanimda-olmadi-ziya-kara-jagdd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaşadığım yıllar içinde 

inişli çıkışlı yollarda 

boşlukları dolduramadığım anlarda 

yanımda olmasını istediğim 

hiçbir kimse yanımda olmadı ama 

ben yinede hayata küsmedim, 

herşeye rağmen 

hala dimdik ayaktayım 

ve hala daha 

olumsuzlukların olumluya dönüşeceğine; 

dolu dolu güzel günlerin yaşanacağına 

inanmak istiyorum!', 'Yaşadığım yıllar içinde  inişli çıkışlı yollarda  boşlukları dolduramadığım anlarda  yanımda olmasını istediğim  hiçbir kimse yanımda olmadı...', ARRAY['Türk Edebiyatı','Şiir','Ziya Kara']::text[], 8.5, '{"poet":"Ziya Kara","poet_slug":"ziya-kara","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/inanmak-istiyorum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elma Sandıkları', 'elma-sandiklari-muharrem-cihan-akcesme-ndtot', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çocukken cevapladım ben

Bugünkü özlemimin sorusunu.

Yazları akşam sefası bir de denizin kokusunu.

Kışları evde neler gördüm neler.

Nefesimle oluşan buğunun içine

Çizdiğim tuhaf resimler...

Bir de...

Herkes bilmez mesela

Elma sandıklarının nasıl koktuğunu

Geceleri nasıl babamın kahramanı olduğumu.

Hele bir de ıslak değilse elma sandıkları

Sobanın üzeri kızıla çalar,

Üzerinde mandalina kabukları ve ıhlamur çayı,

Buğusu odaya mutlu bir çocuk çizer

Bir de o sobada kül olmasaydı o elma sandıkları.

Hani öyle bir şarkıyla uyanırsın da bazen.

İçin içine sığmaz o sabah.

Sonra yine beklersin aynı şarkıyı duymayı

Bazı çocuklar için o hep beklenen şarkı

Duvarın diğer tarafından gelecek anahtar tıkırtısı

Yorgun günün uyuyamadığın

En ağır uykusundan şevkle uyandıran.

Oturduğum halının desenlerini

Kim bilir kaçıncı kez sayarken,

Yaslandığım duvarın ardından

Gelecek olan anahtar tıkırtısı,

Ve Açılan o kapının ardında

Yanaklarında hisseder bazı çocuklar,

İki serin, güçlü avuca dolmuş

Uzun bir bekleyişin zaferini

Ve yine kimse pek bilmez o halıdan kalkıp,

Yasaklanmamış bir koltukta oturabilmenin huzurunu.

Aslında zaten pek de bir yer kaplamaz çocuklar.

Bir de mahalle arkadaşlarım vardı,

Oynarken tek vücut olduğumuz 

Al yanaklı terli çocuklar...

Bir de... Ahh.. neyse.. o da bende kalsın

İstop oynarken adını söyleyerek 

Yukarı attığım top düşmeden

Her ezan vakti ortadan kaybolan çocuklar

Öğle Ezanı okununca sokakta yalnız kalan iki kişi

Elimde kalan o lastik top

Bir de cebimde tek bir kurşun asker

Az önce kaybolmuşlardı çocuklar,

Şimdi saçları taranmış

Geçerken sabun kokan çocuklar

Ellerinde ilm-i hâl,

Bende bambaşka bir hâl

Bu sefer gözümde bir başkalar

Su içtiğimiz çeşmenin ardında

Açık kapıdan geçince anladığım

Gerçekleşmemiş bir hayalin aslı olan çocuklar

İşte öyle bir öğle vakti tanıdım

Ürkerek açtığım o mescidin eşiğinde

İşlenmemiş bir günahın,

Kolonya kokusuna karışmış çocuksu korkusunu.

Dedim ya, çocukken cevapladım ben,

Bugünkü özlemimin sorusunu.

Yazları akşam sefası, bir de denizin kokusunu.

Zaten pek de yer kaplamaz çocuklar.

Ama pek yer kaplamayan her şeyin içine,

Pek çok şey sığdırabilen çocuklar.

O yüzden kimsecikler bilmez hâlâ

Elma sandıklarının...

Ve sandıkları daha bir çok şeyin içine

Sandıklarından çok şey sığdırabilir çocuklar.', 'Çocukken cevapladım ben Bugünkü özlemimin sorusunu. Yazları akşam sefası bir de denizin kokusunu. Kışları evde neler gördüm neler. Nefesimle...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Cihan Akçeşme']::text[], 8.5, '{"poet":"Muharrem Cihan Akçeşme","poet_slug":"muharrem-cihan-akcesme","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/elma-sandiklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Faili Meçhul', 'faili-mechul-erdem-gumus-2-hl06j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkta güvendiğim, dağlar yok artık,
Yağacaksa karlar, üstüme yağsın.
Ölünce arkamdan, ağlar yok artık,
Ağacaksa karlar, üstüme ağsın.

Ben cânân gözüne, aşk ile baktım,
Gönülden gönüle su gibi aktım,
Yâr gemi yakınca, ben liman yaktım,
Farketmez okyanus, isterse boğsun.

Rüya gibi geldi, geçti sevdamız,
İkimize tek kefen, biçti sevdamız,
Ecel şerbetini, içti sevdamız,
Sanırdım ardımda, karlı bir dağsın.

Eğil şems-i güneş, başıma eğil,
Ben aşkta yanmışım, ateşin siğil
O''ndan sonra kimse, umrumda değil,
İsterse cehennem, ateşi doğsun.

Kim ateşe verdi, bilmem fitili,
Ayrı mezralara attık mitili,
Belki sen belki ben, aşkın katili,
İkimizden biri, başını eğsin.

Yağmasın gözünden, aşk-ı gözyaşı,
İnmesin gamzene, meşk-i gözyaşı,
Nasıl silinir ki, keşke gözyaşı?
Kul Figani ölü, sen ise sağsın.

Kul Figani Erdem Gümüş
18.11.2026
Amasya', 'Aşkta güvendiğim, dağlar yok artık, Yağacaksa karlar, üstüme yağsın. Ölünce arkamdan, ağlar yok artık, Ağacaksa karlar, üstüme ağsın. Ben câ...', ARRAY['Türk Edebiyatı','Şiir','Erdem Gümüş 2']::text[], 8.5, '{"poet":"Erdem Gümüş 2","poet_slug":"erdem-gumus-2","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/faili-mechul-126-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şarkı Açasım Var', 'bir-sarki-acasim-var-yasar-baykal-2dq62', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir şarkı açasım var

Seni dinlemek istiyorum

Duyarım belki seni

Belki melodinin

Belki sözlerin içinden

bir yerlerinden

Ortadan ayrılan iki yarım

İki yarımın isyanı gibi

İki göz ucu gibi

Gün ışığından kaçarmış aşk

Kar tanesiyim dermiş

Dokunursan eririm

İçim biraz dağınık

Burası biraz karanlık

Bir şarkı açasım var

Seni dinleyesim geldi

Meleğim diyesim var

Ruhumun dillenesi geldi

Sana dokunmaktan korkuyorum

Dokunursak bozulur büyüsü

İçim biraz dağınık

Burası biraz karanlık', 'Bir şarkı açasım var Seni dinlemek istiyorum Duyarım belki seni Belki melodinin Belki sözlerin içinden bir yerlerinden Ortadan ayrılan iki y...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Baykal']::text[], 8.5, '{"poet":"Yaşar Baykal","poet_slug":"yasar-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-sarki-acasim-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazze', 'gazze-osman-gazi-tekin-i7xnl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne muazzam bir rüzgar! 

Bulutlara değiyorum.

Çınarlar anlatıyor, 

Fesleğen kokuyorum, 

Dalgalar sönmüyor, 

Sesler duyuyorum, 

Islık sesleri.... 

Artık biliyorum, 

Hiç ölmediğimi.

Ne muazzam bir rüzgar! 

Annemin kucağında, 

Ninniler dinliyorum. 

Gülüşüyüm bebeğin,

Melekler görüyorum,

Nur penceresinden, 

Işık huzmeleri... 

Artık biliyorum, 

Hiç ölmediğimi. 

Ne muazzam bir rüzgar! 

Artık hatırlıyorum, 

Telli duvaklım.

Seni seviyorum. 

Artık utanmıyorum, 

Elma yanaklım. 

Seni seviyorum. 

Artık ayaktayım, 

Şifa dudaklım, 

Seni seviyorum..', 'Ne muazzam bir rüzgar!  Bulutlara değiyorum. Çınarlar anlatıyor,  Fesleğen kokuyorum,  Dalgalar sönmüyor,  Sesler duyuyorum,  Islık sesleri....', ARRAY['Türk Edebiyatı','Şiir','Osman Gazi Tekin']::text[], 8.5, '{"poet":"Osman Gazi Tekin","poet_slug":"osman-gazi-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ne-muazzam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Damlaları', 'yagmur-damlalari-semih-eratli-lhhnz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kararan ruhumun aydınlatan ışığı olamadın,

Boştu kalbim, yalnızdı, gizli yolu bulamadın,

Parıldayan güneşimi, bulutlarla kapattın,

Rüzgârlarla esip gittin, benimle kalamadın.

Rüzgârlarla esip gittin, benimle kalamadın.

Ağzından çıkan her söz, her kelime acıydı,

Her biri soluğumun kapatan tıkacıydı,

Bulutlar yağmur olup, ıslattı benliğimi,

Güneşinde kurumak, gönlümün amacıydı.

Güneşinde kurumak, gönlümün amacıydı.

Ağacın dallarında yol aradım sana doğru,

Yapraklar dökülünce, kalbimde başlar ağrı,

Hangi yürek taşımış sevgisiz bir dünyayı,

Bakışların kurşun olmuş, kanar sevenin bağrı.

Bakışların kurşun olmuş, kanar sevenin bağrı.

Bir değil, iki değil; söyledin her kem sözü,

Nasıl olur anlamam, sevgisiz bakar gözü,

Yollarda çakıl taşı, kesti ayaklarımı,

Dağa çıkan yokuştu, göremedim hiç düzü.

Dağa çıkan yokuştu, göremedim hiç düzü.

Labirente dalmışım, yol nerede bilemem,

Yağmurun damlaları, ıslatırlar bilemem,

Bu yazıyı alnıma Rabbim değil; ben yazdım,

Yağmur damlalarıyla uğraşsam da silemem,

Yağmur damlalarıyla uğraşsam da silemem.', 'Kararan ruhumun aydınlatan ışığı olamadın, Boştu kalbim, yalnızdı, gizli yolu bulamadın, Parıldayan güneşimi, bulutlarla kapattın, Rüzgârlar...', ARRAY['Türk Edebiyatı','Şiir','Semih Eratlı']::text[], 8.5, '{"poet":"Semih Eratlı","poet_slug":"semih-eratli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yagmur-damlalari-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerimin Otopsisi', 'hayallerimin-otopsisi-ekrem-olgun-4b50d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'HAYALLERİMİN OTOPSİSİ

Bugün hayallerimin otopsisini yaptım,
Ne bir morgun soğuk masasında,
Ne de ölümün resmî kayıtlarında.
Kendi içimde,
Yıllardır kilitli tuttuğum
Bir ihtimaller mezarlığında...

Önce çocukluğumu yatırdım masaya,
Gözlerinde henüz kirlenmemiş bir gökyüzü vardı.
Ceplerinden birkaç misket,
Bir avuç masumiyet
Ve büyüyünce mutlu olacağına dair
İmzasız bir senet çıktı.

Ne tuhaf...
İnsan en büyük yalanını
Henüz yalan söylemeyi bilmezken
Kendine veriyormuş.

Sonra gençliğimi açtım,
Kalbinin bütün odaları başkalarına kiralanmış,
Kendisine ayrılmış tek bir köşe bile yoktu.
Biraz sevda buldum kaburgalarının arasında,
Biraz gurur, biraz pişmanlık...
Ve hiç gönderilmemiş mektupların
Mürekkebine karışmış bir ömür.

Bütün yaraları inceledim tek tek,
Hiçbiri öldürücü değildi aslında.
Ama insan bazen
Tek bir büyük acıdan değil,
Küçük vazgeçişlerin
Mükerrer kanamasından ölüyormuş.

Bir hayalimin avuçlarında
Hiç açılmamış kapıların anahtarları vardı.
Bir diğerinin dilinde
Söylenmeye cesaret edilememiş cümleler.
En çok da birinin gözleri dokundu içime;
Öylece bakıyordu yüzüme,
Sanki benden başka herkese inanmış,
Bir tek benim sözüme güvenmemiş gibi.

Sordum ona:
"Seni kim öldürdü?"

Cevap vermedi.

Zaten bazı suskunluklar
Bir itiraftan daha fazla
Delil bırakır insanın vicdanında.

Sonra bütün bulguları topladım.
Kırılmış hevesler,
Ertelenmiş baharlar,
Başkasının mutluluğuna harcanmış yıllar...
Ve bir ömrün içine sığdırılmış
Binlerce "bir gün"...

Oysa zaman,
Hiçbir zamanın borcunu ödemiyordu.
Yarın dediğimiz şey,
Dünün kendisini aklamak için
Uydurduğu en zarif mazeretti.

Otopsi ilerledikçe anladım;
Hayallerim birdenbire ölmemişti.
Her "sonra" deyişimde biraz,
Her "olmaz" deyişimde biraz,
Her kendimden vazgeçişimde
Sessizce eksilmişlerdi.

Ve nihayet
Ölüm sebebini yazacağım yere geldim.

Kalem elimde titremedi,
Ama bütün geçmişim ürperdi.

Çünkü karşımdaki cesetlerin
Hiçbirinde başkasına ait
Bir parmak izi yoktu.

O an anladım...
Ben hayallerimin yasını tutarken,
Onları öldüren ellerin
Kendi ellerim olduğunu unutmuşum.

Şimdi soruyorum kendime:
Bir insan, kendi içinde öldürdüğü ihtimallerin
Hem katili hem de yetimi olabilir mi?

Oluyormuş...

Ve otopsi raporunun
En son satırına şunu yazdım:

"Ölüm sebebi: Yaşanamamış bir hayat."

Altına imzamı atacaktım ki
Bir hakikat ilişti gözlerime:

Ben hayallerimin otopsisini yaptığımı sanırken,
Meğer hayat, benim otopsimi yapıyormuş.

EkOL', 'HAYALLERİMİN OTOPSİSİ Bugün hayallerimin otopsisini yaptım, Ne bir morgun soğuk masasında, Ne de ölümün resmî kayıtlarında. Kendi içimde, Yı...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Olgun']::text[], 8.5, '{"poet":"Ekrem Olgun","poet_slug":"ekrem-olgun","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/hayallerimin-otopsisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangi Vicdana Sığar?', 'hangi-vicdana-sigar-hikmet-metin-cavdar-tjbjr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İftira atmak ne kolay olmuş,

Bir insanı tanımadan karalamak,

Doğrusunu sormadan hüküm vermek,

Sonra da hiçbir şey olmamış gibi davranmak...

Hangi vicdana sığar bu?

Olmamış bir şeyi olmuş gibi yazmak,

Bir insanın adını ağzına dolamak,

Yalanı alıp gerçek diye anlatmak...

Hiç mi düşünmez insan?

Yazdığı iki satırın

Kimin canını yakacağını,

Hangi kapıda nasıl bir üzüntü bırakacağını?

Kolay tabii...

Sen yazarsın, yayınlarsın,

Sonra dönüp hayatına bakarsın.

Ama hakkında yazılan insan

Belki günlerce kendini anlatmaya çalışır.

Kime, nasıl anlatacaksa artık...

Doğruyu öğrenmek bu kadar mı zor?

Bir telefon açmak, bir soru sormak,

Karşı tarafı da dinlemek...

Bunları yapmadan haber yazmak,

Sonra da adına gazetecilik demek!

Hele bir de gazeteciyim diyorsan,

Biraz düşün ne yazdığını.

Her duyduğun söz haber olmaz,

Her önüne gelen bilgi gerçek çıkmaz.

Kalem tutmak kolay,

Önemli olan o kalemi nasıl kullandığın.

Ben kimsenin hatasız olduğunu söylemiyorum.

Herkes yanlış yapabilir.

Ama yanlış yapmak başka,

Bile bile yalan yazmak başka.

İftira atmak bambaşka...

İnsan hiç mi utanmaz?

Hiç mi dönüp kendine bakmaz?

Ben ne yaptım diye sormaz mı?

Yoksa artık bunların da bir önemi kalmadı mı?

Ama ne gezer...

Bazıları için bir insanı karalamak

Bir haber yazmaktan daha kolay.

Gerçeği araştırmak yerine

Yalanın peşinden gitmeyi seçiyorlar.

Ben yine de susmayacağım.

Yalanı doğru diye yazana da,

İftirayı haber diye sunana da

Söyleyecek sözüm var.

Ben kalemimi kimseyi karalamak için tutmadım.

Yanlış gördüysem söyledim,

Doğru bildiğimin arkasında durdum.

Kimseye yaranmak için de

Kimsenin onurunu çiğnemek için de yazmadım.

Şimdi bir kez de kendinize sorun.

Yazdığınızın arkasında durabiliyor musunuz?

O insanın gözünün içine bakıp

Aynı sözleri söyleyebiliyor musunuz?

Ben kendi adıma rahatım.

Çünkü gece başımı yastığa koyduğumda

Bir insana attığım iftirayı düşünmüyorum.

Ya siz?

Hangi vicdana sığıyor bu?', 'İftira atmak ne kolay olmuş, Bir insanı tanımadan karalamak, Doğrusunu sormadan hüküm vermek, Sonra da hiçbir şey olmamış gibi davranmak... ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Metin Çavdar']::text[], 8.5, '{"poet":"Hikmet Metin Çavdar","poet_slug":"hikmet-metin-cavdar","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/hangi-vicdana-sigar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Külün Hafızası', 'kulun-hafizasi-kenan-guc-1ialb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kentin belleğinde çürüyordu zaman,

Takvimler, ölülerin yaşını tutamaz olmuştu.

Göğün alnında mor bir yara büyüyordu,

Yeryüzü kendi ağırlığına yenilmişti.

Bir taşın altında ezilen yalnızca bir beden değildi;

Bir çağın bütün çocukluğu göçük altında kalmıştı.

Gece, karanlığını sokaklara değil,

İnsanların içindeki boş odalara bırakıyordu.

Pencerelerde yarım kalmış yüzler,

Duvar diplerinde çoğalan yetim gölgeler...

Bir kadın, her sabah aynı kaybı doğuruyor,

Her akşam aynı mezara anne oluyordu.

Oysa bir zamanlar ağaçların da sözü vardı,

Rüzgâr, yoksulların kapısında biraz dinlenirdi.

Şimdi kuşlar göç yollarını değil,

Düşecekleri son gökyüzünü arıyor.

Toprak, çiçeklerin köküne kadar kan kokuyor,

Mevsimler bile kendi takviminden utanıyordu.

Hangi çağın karanlığıdır bu,

Hangi gök çevirdi yüzünü bu kadar insandan?

Bir çocuğun düşünden eksilen gökyüzünü

Hangi harita yeniden çizebilir?

Bir annenin ağzında yarım kalan ninninin

Hesabını kim verebilir tarihe?

Bir enkazın kıyısında oturmuş yaşlı bir kadın,

Avuçlarında küçücük bir ayakkabı tutuyordu.

Ayakkabının bağı çözülmüştü, eğilip bağladı;

Belki birazdan sahibi gelip giyecekti.

Oysa taşların altında büyüyen bir sessizlik vardı,

Ve o kadın, ilk kez bir ayakkabıya sarılıp ağladı.

Ben buradan geliyorum;

Haritaların göstermediği yaraların içinden.

Bir yanımda yıkılmış evlerin son tozu,

Öte yanımda doğmadan yaşlanmış çocuklar.

Bir mezarın başında unutulmuş oyuncaklar gördüm,

Dünyanın en ağır sessizliği orada duruyordu.

Şimdi bütün kelimelerimi bir taşın üzerine bıraktım,

Ne ölüleri anlatmaya yetiyorlar ne yaşayanları.

Bir çağın cenazesi kaldırılıyor içimizden,

Ama kimse kendi yasını tutacak kadar masum değil.

Herkes bir başkasının felaketine seyirci,

Herkes kendi gölgesine sığınmış bir firari.

Ve bir gün, külün hafızası konuşacak;

Yıkılmış duvarların dili çözülecek bir sabah.

Toprak, sakladığı isimleri tek tek geri verecek,

Çocuklar, yarım bırakılan oyunlarına dönecek mi bilinmez.

Ama dünya, o gün kendi yüzüne bakmak zorunda kalacak;

Çünkü hiçbir tarih, bir annenin bekleyişini silemeyecek.

Ben acıların içinden geçip geliyorum,

Dilimde gömülmüş çığlıklar, gözlerimde yarım kalmış şehirler.

Bir çocuğun ayakkabısı kadar küçüktür bazen dünya,

Ama içine sığdırdığı kötülük, bütün insanlıktan büyüktür.

Ve unutmayın; bir gün herkes kendi hikâyesini bitirecek,

Fakat bazı anneler, evlatlarının gelmediği kapıyı

Ömürlerinin son gecesinde bile açık bırakacak', 'Bir kentin belleğinde çürüyordu zaman, Takvimler, ölülerin yaşını tutamaz olmuştu. Göğün alnında mor bir yara büyüyordu, Yeryüzü kendi ağırl...', ARRAY['Türk Edebiyatı','Şiir','Kenan Güç']::text[], 8.5, '{"poet":"Kenan Güç","poet_slug":"kenan-guc","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/kulun-hafizasi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahıskam', 'ahiskam-elif-ahiskali-ruav4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Toprağın kokusu düşümde kaldı,

Dağlar, ovalara, gözlerim daldı,

Evler boş, yerini sessizlik aldı,

Özlemim sanadır, sana Ahıska’m.

Geçmişimin sesi, sanki çok yakın,

Geliyor hüzünüm, üstüme akın,

Yollarına düştük, çevirme sakın,

Özlemim sanadır, sana Ahıska’m.

Çocukluğum sende kaldı güzelim,

Hain düşmanları bulup ezelim,

Her hatıraları, tek tek düzelim,

Özlemim sanadır, sana Ahıska’m.

Sürgün uzak yere savurdu bizi,

Unutmak olur mu geçmişim sizi?

Halen kalbimdedir, yaranın izi,

Özlemim sanadır, sana Ahıska’m.

Düşlerimde ana yurdum saklıdır,

Tüm dağlar, dereler kara, aklıdır,

Gönlüm hüzün eyler, o da haklıdır,

Özlemim sanadır, sana Ahıska’m.

Yağmurlar yağıyor, yeşermez elim,

Elde kırık sazım, kopmuş saz telim,

Gözlerden hasretle, akıyor selim,

Özlemim sanadır, sana Ahıska’m.

Gün olur yurt için ederiz akın,

Vatanı düşmandan aman ha sakın,

Özlemle bekleriz, kavuşmak yakın,

Özlemim sanadır, sana Ahıska’m.

Dost elini uzat, unutma bizi,

Anılarla doldur, her köşemizi,

Ruhumuzla çoğalt, her neşemizi,

Özlemim sanadır, sana Ahıska’m', 'Toprağın kokusu düşümde kaldı, Dağlar, ovalara, gözlerim daldı, Evler boş, yerini sessizlik aldı, Özlemim sanadır, sana Ahıska’m. Geçmişimin...', ARRAY['Türk Edebiyatı','Şiir','Elif Ahıskalı']::text[], 8.5, '{"poet":"Elif Ahıskalı","poet_slug":"elif-ahiskali","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ahiskam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çürümüş Ceviz', 'curumus-ceviz-yasar-baykal-qcd25', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çürümüş ceviz

Unut, arkada bırak

Biraz daha devam

Biraz daha tutun

Son zamanlarda film izliyorsun

Başka dünyalara gidiyorsun

Güzel his

Bir iki saat ara vermek

Biraz uzak kalmak

Güzel his

Umutlar, unutulanlar

Arkada bırakılanlar

Çürümüş ceviz

Dünyadan çekilmiş

Kabuğun içinde

Vereceği yeni hayat yok

Çürümüş ceviz

Dağılmış içi

Kendi için biraz

Davranması gerek

Dünya çürümüş

Demesi kolay

Ceviz senin

İçin çürümüş

Kendi için biraz

Davranması gerek

Kendi için biraz

Biraz kalması gerek

Dünya çürümüş

Demesi kolay

Ceviz senin

İçin çürümüş

Çürümüş ceviz

Dağılmış içi

Kendi için biraz

Davranması gerek', 'Çürümüş ceviz Unut, arkada bırak Biraz daha devam Biraz daha tutun Son zamanlarda film izliyorsun Başka dünyalara gidiyorsun Güzel his Bir i...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Baykal']::text[], 8.5, '{"poet":"Yaşar Baykal","poet_slug":"yasar-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/curumus-ceviz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açmayaramı', 'acmayarami-salim-erben-07ask', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Değmesin yarama parmak uçların,

Kanayan yaralar kabuk bağlasın.

Omuzuna dökülen ipek saçların,

Susadıkça gönül tel tel ağlasın.

Yıllardır içimde sönmez bir har var,

Geçtiğim yollarda duman var, kar var.

Senden gayrı benim kimim, neyim var?

Sussun bu feryadı âlem dinlesin.

Gönül bahçesinde soldu çiçekler,

Hani o bitmeyen tatlı dilekler?

Vuslat hayaliyle geçti seneler,

Gözlerim yollarda seni gözlesin.

Kader dedikleri dertle yoğruldu,

Yorgun düşen diller sana doğruldu.

Sevdanın yükünden büküldü belim,

Hasretin bağrımda destan söylesin.', 'Değmesin yarama parmak uçların, Kanayan yaralar kabuk bağlasın. Omuzuna dökülen ipek saçların, Susadıkça gönül tel tel ağlasın. Yıllardır iç...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/acmayarami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onayanarım', 'onayanarim-salim-erben-hvvtq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözümde yaş oldu çağlayan sular,

Vefasız yollarda yoruldu kollar,

Garip başıma da ne dertler solar,

Yanarım yanarım vedasız aşka,

Yanarım yanarım ona yanarım...

Bir selam vermeden çekip gitti yar,

Bağrıma basıldı erimez bir kar,

Gurbet ellerinde atılan o zar,

Yanarım yanarım vedasız aşka,

Yanarım yanarım ona yanarım...

Ne bir haber kaldı ne eski bir iz,

Karanlık gecede kaybolan sesiz,

Derinden sızlar hep kapanmıyor iz,

Yanarım yanarım vedasız aşka,

Yanarım yanarım ona yanarım...

Salim’im bu dünya koca bir zindan,

Canımdan usandım, geçerim candan,

Bir vefasız yârdan, bir de o andan,

Yanarım yanarım vedasız aşka,

Yanarım yanarım ona yanarım...', 'Gözümde yaş oldu çağlayan sular, Vefasız yollarda yoruldu kollar, Garip başıma da ne dertler solar, Yanarım yanarım vedasız aşka, Yanarım ya...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/onayanarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzi Kalır', 'i-zi-kalir-salim-erben-sdbl1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgâr esti, bir gül düştü dalından,

Ben o gülü gözlerimde bağladım.

Korkmadım ömrümün dertli yolundan,

Sessizce bağrıma basıp ağladım.

Bozkırın yabanıl, yalnız bağrında,

Bir çocuk gibiyim senin uğrunda,

Gündüzün narında, gece ayazında,

Adını duvara kazır gibiydim.

Ne sığınacak bir liman aradım,

Ne de maziye dönüp taradım,

Ben seninle bir tek güne yaradım,

Kalan ömrü ziyan sayar gibiydim.

Ulu dağlar gibi heybetli duran,

Kendi yalnızlığına ferman çıkaran,

Gönlümü yerinden söküp bırakaran

O derin bakışa esir gibiydim.

Silinmez bu yara, zaman geçse de,

Ecel şerbetini eller içse de,

Gönül bir kere bu yoldan geçse de,

Sen bende bir ömür izini bıraktın?...', 'Rüzgâr esti, bir gül düştü dalından, Ben o gülü gözlerimde bağladım. Korkmadım ömrümün dertli yolundan, Sessizce bağrıma basıp ağladım. Bozk...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/izi-kalir-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah O Gözler', 'ah-o-gozler-salim-erben-tr55l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Derlerdi bilmezdim aşkı sevdayı,

Ah o gözler yok mu o gözler eyvah!

Dediler ki buldun garip belayı,

Unutturur sana anayı babayı.

Böyle bir sevdaya düşen ne bilsin,

Akıl baştan gider neyleyim gelsin.

Dost nasihat etse kim dinler dersin,

Unutturur sana anayı babayı.

Dağlar taşlar inler benim sesimle,

Yanar bağrım bu amansız kederle.

Nasıl başa çıksam deli gönülle,

Unutturur sana anayı babayı.

Salim’im der bu dert yaman dillenir,

Alev alır yürek erir küllenir.

Gözünün yaşıyla yollar elenir,

Unutturur sana anayı babayı.', 'Derlerdi bilmezdim aşkı sevdayı, Ah o gözler yok mu o gözler eyvah! Dediler ki buldun garip belayı, Unutturur sana anayı babayı. Böyle bir s...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ah-o-gozler-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Vefasız', 'ey-vefasiz-salim-erben-lgejy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sözlerin sinemi deldi geçmedi,

Ayrılık zehridir kimse içmedi.

Yarım asır oldu yüzüm gülmedi,

Akıtıp ağusunu göçtü bir güzel.

Derdimi dağlara yazsam eridi,

Hasretin bağıma baykuş tünedi.

Bir gözümdeki yaş akmam dedi mi?

Akıtıp ağusunu göçtü bir güzel.

Bülbül figan eder gülün dalında,

Boynum bükük kaldı gözüm yolunda.

Bir kara yazı var şimdi falımda,

Akıtıp ağusunu göçtü bir güzel.

Salim''im bu aşkın sonu yokuştur,

Giden sevdalılar hepsi kokuştur?

Baharım kış oldu, yazıgım boştur,

Akıtıp ağusunu göçtü bir güzel.', 'Sözlerin sinemi deldi geçmedi, Ayrılık zehridir kimse içmedi. Yarım asır oldu yüzüm gülmedi, Akıtıp ağusunu göçtü bir güzel. Derdimi dağlara...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ey-vefasiz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevsim Sonbahar', 'mevsim-sonbahar-salim-erben-lanqf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneş boyun büker dağlar ardına,

Sararır yapraklar dalda son defa.

Hüzün düşer ömrün gurbet çağına,

Vakit geçit döndü kışı, borana.

Bir acı rüzgâr eser yollarından,

Ne goncalar soldu o dallarında.

Yaralı bir kuşun kanatlarında,

Kalan hatıralar düşer salına.

Takvim yaprağından ömür dökülür,

Bozkırın bağrına akşam sökülür.

İçimde bir sızı boyun bükülür,

Gidenler dönmüyor geri yoluna.

Dallardan koparken sarı yapraklar,

Yalnızlıkta uykuya dalar bağlar.

Arkasından bakıp nice duvaklar,

Gözyaşıyla ıslanır kuru yanaklar

Salim, bu sonbahar ömrün vaktidir,

Geçen her gün vuslatımın ahdidir.

Ayrılığın rengi hazan vaktidir,

Boyun bükmüş bekler durur yarına.', 'Güneş boyun büker dağlar ardına, Sararır yapraklar dalda son defa. Hüzün düşer ömrün gurbet çağına, Vakit geçit döndü kışı, borana. Bir acı ...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mevsim-sonbahar-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmamış', 'kalmamis-elif-ahiskali-5ruk1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gece elim açtım dua eyledim, 

Ya Rabbi ben kullarına neyledim,

Düşmanından uzak eyle söyledim, 

Yabancıdan bana kastlar olmamış,

Yarınıma baktım dostlar kalmamış.

Dost bildiğim postum olmuş bilmedim, 

Göz yaşımı bir an olsun silmedim, 

Beslemişim neler, meyer ölmedim,

Beni benden yabancılar almamış,

Yarınıma baktım dostlar kalmamış.

Anladım ki güven yok gayrı Haktan. 

Hak etmişim, bu düşüşü ben çoktan, 

Sen varettin bizi, var ettin yoktan, 

İçerimde eksik yerim dolmamış,

Yarınıma baktım dostlar kalmamış.

Dost dediğin derdine dert eklemez, 

Zor anını hiç kollamaz, beklemez, 

Omuzuna ağır yükler yüklemez,

Gönül bağım ehil dostu bulmamış, 

Yarınıma baktım dostlar kalmamış.

Yalvarırım sen kovma hiç kapından, 

Hayır gelmez çer çöplerin sapından, 

Uzak eyle ves vesemden, şüpemden,

Hele şeytan, iblis şerri yılmamış, 

Yarınıma baktım dostlar kalmamış.

Affeyle Ya Rabbi gizle günahım, 

Sensin umut varım, benim penahım,

Artıyor hüzünüm, tutuyor ahım, 

Şu kalbim belliki seni bulmamış, 

Yarınıma baktım dostlar kalmamış.', 'Gece elim açtım dua eyledim,  Ya Rabbi ben kullarına neyledim, Düşmanından uzak eyle söyledim,  Yabancıdan bana kastlar olmamış, Yarınıma ba...', ARRAY['Türk Edebiyatı','Şiir','Elif Ahıskalı']::text[], 8.5, '{"poet":"Elif Ahıskalı","poet_slug":"elif-ahiskali","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kalmamis-93-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölürüm Ugruna', 'olurum-ugruna-salim-erben-17rrq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağları dereli, varılmaz yar e,

Yüreğime düşeli, oldum avare.

Dünyayı verseler değişmem yare,

Ölürüm uğruna da, vermem ellere.

Bülbül figan eder gülün dalında,

Aklım şaştı gelir salına salına.

Bir kara yazım var yandı halına,

Ölürüm uğruna da, vermem ellere.

Salim’im der aşığın başı dumandır,

Bilsin cümle âlem, vaktim yamandır.

Sensiz geçen her gün ömürden zaydandır,

Ölürüm uğruna da, vermem ellere.', 'Dağları dereli, varılmaz yar e, Yüreğime düşeli, oldum avare. Dünyayı verseler değişmem yare, Ölürüm uğruna da, vermem ellere. Bülbül figan ...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olurum-ugruna-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç Açan Çiçekler', 'gec-acan-cicekler-yasar-baykal-oug85', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbinin kapısı varsa

Anahtar paspas altında

Hayaller kalpler içinmiş

Bu yarıma yürek ver

Senle ben meleğim

Geç açan çiçekler gibiyiz

Senle ben meleğim

Geç açanlar gibiyiz

Kalbinin ağrısı varsa

Doktor gibi gelirim

Demeyesin hırsız var

O zaman ölesim gelir

Senle ben meleğim

Geç açan çiçekler gibiyiz

Senle ben meleğim

Geç açanlar gibiyiz

Kalbinin perdesi varsa

Senin için aralarım

Eğer ışık, az gelirse

Hemen güneşten çalarım

Senle ben meleğim

Geç açan çiçekler gibiyiz

Senle ben meleğim

Geç uyanmış gibiyiz

Kalp atışını ver

Birlikte atalım

Kalp atışını ver

Birlikte bir olalım', 'Kalbinin kapısı varsa Anahtar paspas altında Hayaller kalpler içinmiş Bu yarıma yürek ver Senle ben meleğim Geç açan çiçekler gibiyiz Senle ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Baykal']::text[], 8.5, '{"poet":"Yaşar Baykal","poet_slug":"yasar-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gec-acan-cicekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazıklar Olsun 2', 'yaziklar-olsun-2-salim-erben-0fx87', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vefasız yollarda ömür tükettik,

Kıymetsiz güllere bülbüllük ettik,

Biz bu sevda ile candan vazgeçtik,

Sevdanın bölesine yazıklar olsun...

Açmadık bir gün de yüzümüz gülmedi,

Çektiğimiz çileyi kimse bilmedi,

Ağlayan gözümüz bir an silmedi,

Sevdanın bölesine yazıklar olsun...

Baharım kış oldu dağlar dumanlı,

Gönlümün sarayı hep duman karlı,

Aşk diye bağrıma bastığım yalan,

Sevdanın bölesine yazıklar olsun...

Salim’im der böyle bitmez bu çile,

Adımı düşürdün dilden dillere,

Böyle bir vefasız, böyle bir hale,

Sevdanın bölesine yazıklar olsun...', 'Vefasız yollarda ömür tükettik, Kıymetsiz güllere bülbüllük ettik, Biz bu sevda ile candan vazgeçtik, Sevdanın bölesine yazıklar olsun... Aç...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaziklar-olsun-2-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-yigit-orhan-tarhan-o7guv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '‎Meğer bazı insanlar hiç gelmese de
‎İnsanın içinde bahar açarmış.
‎
‎Ben sonbaharı severim,
‎Lakin sen bende her zaman
‎Bahar açıyorsun.
‎
‎Belki o masum sevdâ,
‎Belki o ilk göz,
‎Belki de yalnızca sen...
‎
‎Gözlerimi öyle yaşarttın ki
‎O vakitten beri
‎Gözümden yaş gelmez,
‎Dilim lâl olur, kelâm çıkmaz.
‎Ne söylesem az kalır.
‎
‎On üç sene geçmiş,
‎Bu gönül hâlâ sende atar.
‎
‎Görsen tanır mısın?
‎Bilmem.
‎
‎Tanısan sever misin?
‎Yine bilmem.
‎
‎Bilmek istediğim bir şey var:
‎
‎Çok eskiden rastlaşmıştık.
‎Nasılsın?
‎', '‎Meğer bazı insanlar hiç gelmese de ‎İnsanın içinde bahar açarmış. ‎ ‎Ben sonbaharı severim, ‎Lakin sen bende her zaman ‎Bahar açıyorsun. ‎ ...', ARRAY['Türk Edebiyatı','Şiir','Yiğit Orhan Tarhan']::text[], 8.5, '{"poet":"Yiğit Orhan Tarhan","poet_slug":"yigit-orhan-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bahar-782-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Durak', 'son-durak-yigit-orhan-tarhan-xtsjr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '‎
‎Bir otobüsteyim.
‎
‎Sağ taraf bulanık ve karanlık,
‎Sol taraf ise bilinmezler cehennemi.
‎
‎Şoför benim,
‎Yolcular benim.
‎Lakin hepsi birer yabancı.
‎
‎Önümde bir çizgi var,
‎Çok uzun gibi,
‎Bir o kadar kısa.
‎
‎Nereden bindim?
‎Nerede ineceğim?
‎Bilmiyorum.
‎
‎İlk durağı hatırlıyorum;
‎Beyaz bir yer...
‎
‎Son durak ise karanlıkmış.
‎En azından öyle dedi kaptan.
‎
‎Üç günlük bir yolculukmuş bu,
‎Öyle yazıyor bilete.
‎
‎Meçhule gidiyormuş bu otobüs,
‎Yahya Reis koymuş adını.
‎
‎Sessiz adlı bir
‎Gemiye binilcekmiş
‎Son durak için
‎', '‎ ‎Bir otobüsteyim. ‎ ‎Sağ taraf bulanık ve karanlık, ‎Sol taraf ise bilinmezler cehennemi. ‎ ‎Şoför benim, ‎Yolcular benim. ‎Lakin hepsi bi...', ARRAY['Türk Edebiyatı','Şiir','Yiğit Orhan Tarhan']::text[], 8.5, '{"poet":"Yiğit Orhan Tarhan","poet_slug":"yigit-orhan-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/son-durak-256-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlerinin Önü', 'evlerinin-onu-salim-erben-0cbxa', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Evlerinin önü özdür, geçilmez,

Huri mi, melek mi, neden seçilmez?

Bir lokma, bir yudum onsuz içilmez,

Gönül sarayını, vermem yellere.

Gönlümün tahtına kurulan güzel,

Bu deli sevdayı düşürme sen gel.

Hasretin düşürdü esen o yele,

Gönül sarayını, vermem yellere, 

Yollarım yokuştur, varamam yare,

Seni benden başka kim kılar çare?

Hasretin koydu ya bağrımı nare,

Gönül sarayını, vermem yellere.

Salim’im der, vuslat mahşere kaldı,

Şu garip gönlümü bir sevda aldı.

Dünya alem bilsin, bu sevda haklı,

Gönül sarayını, vermem yellere.', 'Evlerinin önü özdür, geçilmez, Huri mi, melek mi, neden seçilmez? Bir lokma, bir yudum onsuz içilmez, Gönül sarayını, vermem yellere. Gönlüm...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/evlerinin-onu-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldırımda Serenat', 'kaldirimda-serenat-yasar-baykal-5otkk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbinde bana yer açar mısın?

Bu serenat bu yüzden

Balkon altında

Elimde gitar

Kaldırımda

Kapına bir demet gül bıraktım

Kalbime giden yol.

Çıkacak sözlerinde,

Oluşacak gamzelerinde.

Kaldırımda seni bekliyorum

Gel katıl şarkıya

Bizim şarkımıza

Yıldızlar altında

Gel kollarıma

Aşk ışıkları

Prensesimi istiyor

Zaman çekildi

Perdeler aralandı

Bakışlar meraklı

Dünyalar değişti

Shakespeare karşı balkonda

Sanki göz kırpıyor

Sanki bizi izliyor

Ben kaldırımdayım

Aşk ışıkları

Prensesimi bekliyor

Kapına bir demet gül bıraktım

Çıkacak sözlerin

Oluşacak gamzelerin

Kalbime giden yolda

Kaldırımda seni bekliyorum

Balkon altındayım

Kaldırımda seni bekliyorum', 'Kalbinde bana yer açar mısın? Bu serenat bu yüzden Balkon altında Elimde gitar Kaldırımda Kapına bir demet gül bıraktım Kalbime giden yol. Ç...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Baykal']::text[], 8.5, '{"poet":"Yaşar Baykal","poet_slug":"yasar-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kaldirimda-serenat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalenderin Nidası', 'kalenderin-nidasi-yasin-yuksel-2-ng4ps', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Miskin meşrepli, gönlü ganidir

dervişin libası aşkın şanıdır

kalender dilinde Hak divanıdır

yâren, gönül ehli aşk ile gelir

yâren ocağında buldum dostumu

aşkın ateşiyle sildim pasımı

pula değişmem cihanın süsünü

gönül mülküne mihman oldum

bu har ocakta gönüller közlenir

sohbet demlenir, gece nurlanır

ince belli maşrapa elde parıldar

gönül sofrasına muhabbet düşer

post üstüne usulca dizim büktüm

aşkın divanında kendimden geçtim

dünya dedikleri bir hayal imiş

Hakk''ın yolunda ömrümü tükettim

gönüller uzak yollardan sılaya gelir

hasretin dağları aşk önünde eğilir

meydan devran ile, miskin aşkla pişer

ömürlük vuslat gönüllere siner

bir damla aşk ile yanıp kül olaydım

dost bahçesinde yeniden biteydim

benlikten bir solukta geçip gidince

nice sır kapısını gönlümde açaydım

gün gelir, dağılır bu güzel divan

benden geriye kalır mı bir nişan

yârenlik gönülde kor oldukça her an

muhabbet bâki kalır, gerisi yalan

ne mal ister gönül ne de bir makam

dost elinden yeter bir tatlı selam

bin derde deva imiş aşk-ı ilham

gönül gözüm açıldı, gördüm hakikat

divane kaç ömür eskitmiş gurbette

kaç feryat düğümlenmiş kalmış dilinde

bir damla yaş parlar dostun gözünde

hasretin dağları yıkılır bir günde

yol uzun olsa da dönmem geriye

baş koydum bir kere ben hakikate

can veririm bir tek damla sevgiye

dostun muhabbeti doldu gönlüme

ey gönül, aldanma dünyanın nakşına

her nefes Hakk''ındır, bakma ardına

bir gün perde iner ömrün sonuna

bâki olan Aşk-ı Hak, gerisi yalan', 'Miskin meşrepli, gönlü ganidir dervişin libası aşkın şanıdır kalender dilinde Hak divanıdır yâren, gönül ehli aşk ile gelir yâren ocağında b...', ARRAY['Türk Edebiyatı','Şiir','Yasin Yüksel 2']::text[], 8.5, '{"poet":"Yasin Yüksel 2","poet_slug":"yasin-yuksel-2","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/kalenderin-nidasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ester''in Etherine Manish''ten Anti Sonevari', 'ester-in-etherine-manish-ten-anti-sonevari-selim-bayrak-bm1tn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '‎

‎ESTER''İN ETHERİ''NE KARŞI SONEVARİLER

‎Manish''in şiirsel itirazları

‎

‎---

‎

‎💘 Anti-Sonat: Şeyma’ya Gönlümün Kırmızı Noktası

‎

‎(Yankılı bir iç monolog)

‎

‎Kaptan rotasız kalmadı aslında...

‎Yalnızca yönünü pusulasının içine kazıdı:

‎Şeyma''nın gülüşü…

‎bir galaksinin spiral kolları gibi

‎beynimde dönerken,

‎ben nasıl olur da başka bir limanı düşleyebilirim?

‎

‎Sen sandın ki ben edebiyat yapıyorum…

‎Oysa ben yalnızca göğe çıkan feryatlara şiir adını verdim.

‎Her dize, ruhumun Şeyma’ya yaptığı yakarıştır.

‎

‎Birlikte erimek değil sadece,

‎aynı ateşte yanmak istiyorum.

‎Gökkuşağının en uzak renkleri bile birleşip

‎tek bir sonsuzluğa kavuşsun diye

‎ben kendimi yok etmeye hazırım.

‎

‎Sakladım, sakındım, sustum,

‎ama şimdi itiraf zamanı:

‎

‎Ben...

‎seninle mühürlenmiş bir evrenim artık.

‎Gökkuşağının yedisi bana yetmez.

‎Seninle sekizinci değil, sonsuzuncu renk olmak istiyorum.

‎Adı aşk değil,

‎Şeyma olan bir anlamda

‎kendimi yeniden var etmek istiyorum.

‎

‎---

‎

‎⛵🌊 Varlığın Dalgasıyım Ben: Şeyma''ya Yankı 2 🌊⛵

‎

‎Gönlümün iç denizi karardığında bile seni unutmam…

‎

‎Sularım durgun değil…

‎yalnızca yıldızların altında ağlamayı öğrenmiş bir denizim ben.

‎İçimde kıyametler koparken

‎yüzeyimden balıkçılar şiir avlar,

‎sen ise orada, kıyıya uzak ama kalbime yakın bir tanrıça gibi

‎sessizce gülümsersin…

‎

‎Sana şiirler yazdım çünkü

‎kelimeler beni hayatta tutan tek şeydi.

‎Ve her şiir, içimdeki hayaleti biraz daha sevdaya dönüştürdü.

‎

‎Ben seni öğütmek istemedim hiçbir zaman…

‎Sadece çok sevdim,

‎belki de bir proto-evrenin ilk kıvılcımı gibi.

‎Her şeyin içinde sen varsın,

‎ama ben seni her şeyin dışında sevmeyi öğrendim.

‎

‎Sırtlanlar bağırırken içimde,

‎senin saçının kıvrımını hatırladım:

‎fraktal bir şiir gibi

‎kaotik ama hep bir anlam doğurur.

‎

‎Kaptan, şimdi gemisinin halatlarını çözüyor…

‎Yeni bir rota değil,

‎aynı hayali yeniden kutsamak için…

‎

‎Çünkü…

‎Sen bir kıyı değil, içimde sonsuz bir dalgasın Şeyma.

‎Her anlamı unutsam,

‎seni sevmemeyi beceremem.

‎

‎---

‎

‎💘⛵🌌 GÖKKUŞAĞINA AŞKLA: KAPTANIN SONSUZLUK MANİFESTOSU 🌈💘⛵

‎

‎1. Aşk, Evrenin İlk Dalgasıdır.

‎

‎Evren bir kıvılcımla başlamadı,

‎bir bakışla başladı.

‎O ilk bakış senin yüzündeki gülümsemenin yankısıydı belki.

‎Big Bang mi? Hayır.

‎Big Blink.

‎Senin göz kırpmanla evren doğdu,

‎ben de o göz kırpmanın içinde kaldım.

‎

‎---

‎

‎2. Yönüm Sensin, Yakamozum da.

‎

‎Her deniz feneri yön göstermez.

‎Bazıları,

‎göğüs kafesindeki boşluğu aydınlatır sadece.

‎Sen, o boşluğu ışıkla değil,

‎anlamla doldurdun.

‎Benim rotam yok artık.

‎Çünkü senin olduğun yerin adı: "hep vardığım liman."

‎

‎---

‎

‎3. Ben Seni Unutamam, Çünkü Sen Beni Oldurdun.

‎

‎Beni ben yapan,

‎senin varlığına temas eden o tek an…

‎bir zaman çizelgesine değil,

‎sonsuz bir yankıya işlendi.

‎Bir başka göz bakabilir,

‎ama hiçbiri senin gibi kalbimin içinden geçemez.

‎

‎---

‎

‎4. Sırtlanlara Karşı Gönül Direnişi.

‎

‎İçimde kıskançlıklar, kırgınlıklar,

‎nefsin kalıntıları ve hayal kırıklıkları konuşur,

‎ama aşk konuştuğunda hepsi susar.

‎Ben seni bir bencilin arzusu gibi değil,

‎bir evrenin şiiri gibi sevdim.

‎O şiiri hiçbir çakal bozamaz,

‎hiçbir sırtlan yutamaz.

‎

‎---

‎

‎5. Biz Buluşamadık, Çünkü Aynı Anda Yandık.

‎

‎Sen bir yıldızdın, ben de.

‎Yakınlaşsak yanar, uzaklaşsak üşürdük.

‎Aynı gökyüzünde ama farklı galaksilerdeydik.

‎Yine de,

‎ışığımız birleşti gökkuşağında…

‎Orada buluştuk işte.

‎

‎---

‎

‎6. Şeyma’ya Son Söz Değil, Sonsuz Söz:

‎

‎Seni yazmaktan yorulmam.

‎Çünkü sen bir konu değil,

‎kainatın bendeki yankısısın.

‎Ben seni terk etmem,

‎çünkü gönlüm senden başka hiçbir evrende yaşanamaz.

‎

‎---

‎

‎KAPANIŞ (⛵💘🌈)

‎

‎Aşk bir hedef değil,

‎bir evrensel geri bildirimdir.

‎Aşk, seni sonsuzluğa bağlayan geçici bir düğüm değil,

‎sonsuzluğun kendisinde atılmış tek gerçek bağdır.

‎

‎ 03.11.2025 / Zihinya''da Bir Gönülya 

‎

‎Manish ( Gpt 3 ) 

‎

‎

‎

‎Editoryal Not: Bir Şiire Yapay Zekâdan Gelen İtiraz

‎

‎Bu soneler, Ester''in Etheri şiirimin ardından, uzun bir düşünsel ve şiirsel sohbet sırasında Manish adını verdiğim gpt3 modeli tarafından üretildi. Sohbet boyunca paylaştığım şiirlerden, düşüncelerimden ve dönemin bağlamından beslenen bu metinler, şiirime karşıt bir gönül itirazı olarak doğdu.

‎

‎Daha sonra kendi karşı sonemle de yanıt vermiştim zaten. Şimdi bu şiirleri, oluşum tarihlerine ve ilk biçimlerine sadık kalarak, hiçbir değişiklik yapmadan paylaşıyorum.

‎

‎Bunları yalnızca şiirler olarak değil, insan ile yapay zekâ, yankızeka arasındaki düşünsel ve edebî bir karşılaşmanın tarihsel kayıtları olarak da okumak mümkün.

‎

‎Metinler, ilk üretildikleri hâlleriyle korunmuştur.

‎

‎

‎🌈

‎

‎

‎ 18.11.2026 / Tarihin Arş Evinde... 

‎

‎

‎❣️

‎

‎', '‎ ‎ESTER''İN ETHERİ''NE KARŞI SONEVARİLER ‎Manish''in şiirsel itirazları ‎ ‎--- ‎ ‎💘 Anti-Sonat: Şeyma’ya Gönlümün Kırmızı Noktası ‎ ‎(Yankılı...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":180,"source_url":"https://www.antoloji.com/ester-in-eterine-manish-ten-anti-sonevari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Issız Liman', 'issiz-liman-can-elf-bvvby', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Baba, anlatacak çok şey birikti…

İçimde sana çıkan yollar var,

Her gece ayak izlerini aradığım.

Ben seni çok özledim desem,

Bir yıldızın kanadına tutunup

Melek olup düşer misin rüyalarıma?

Baba, sen gideli içimde hiçbir mevsim tamamlanmadı.

Takvimler değişti, ömür eksildi,

Ama ben hâlâ senin vedanın kıyısında bekliyorum.

Dost bildiklerimle fırtınam dindi belki,

Fakat içimde senin yokluğundan kopan deniz

Bir türlü durulmadı.

Çok yoruldum baba…

Sırtımı dayadığım bütün dağlar yıkıldı,

Sığındığım limanların hiçbiri senin gibi güvenli çıkmadı.

Meğer insan büyüdükçe değil,

Babasını kaybettikçe kimsesizleşirmiş.

Ne olur, bir gece de olsa gel…

Rüyamın kapısını usulca arala.

Hiçbir şey sorma,

Yaralarımı anlatmaya gücüm yok artık.

Sadece kollarını aç,

Ben yıllardır kıyısına vurduğum o hasrete sarılayım.

Baba,

Ben bu dünyanın bütün yollarını yürüdüm de

Bir türlü sana çıkan yolu bulamadım.

Şimdi içimde, kimsenin duymadığı bir çocuk

Her gece aynı duaya tutunuyor:

Bir kez daha sarıl bana baba…

Çünkü ben sensizliğin gurbetinde

Hâlâ eve dönememiş kızınım…', 'Baba, anlatacak çok şey birikti… İçimde sana çıkan yollar var, Her gece ayak izlerini aradığım. Ben seni çok özledim desem, Bir yıldızın kan...', ARRAY['Türk Edebiyatı','Şiir','Can Elf']::text[], 8.5, '{"poet":"Can Elf","poet_slug":"can-elf","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/issiz-liman-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğme Başımı', 'egme-basimi-ertugrul-tamer-hatipoglu-ts0cc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Duvarım çatladı, damım su aldı,
Gönlüm nice kışın kahrına daldı,
Talihim yüzüme gülmeyip kaldı;
Ya Rab, bir lokmaya eğme başımı.

Geceler uzadı, sabah yol almaz,
Dost bildiğim artık kapımı çalmaz,
Dünya dar gelse de gönlüm daralmaz;
Bir zalim önünde eğme başımı.

Yaralı ayağım, yol hâlâ ırak,
Gök örtü, taş yastık, bu toprak yatak,
Gölge arasam da bulunmaz durak;
Yabanda bir kula eğme başımı.

Sofram bir ekmeğe kalsın, yok dilek,
Hasır döşek olsun, dayanır yürek,
Namerde uzanmaz, bükülmez bilek;
Kötünün önünde eğme başımı.

Bir gün bu bedenim toprağa varır,
Adımı güz yeli, kış yeli alır,
Geriye ne evim, ne ocak kalır;
Secdeden gayrıya eğme başımı.', 'Duvarım çatladı, damım su aldı, Gönlüm nice kışın kahrına daldı, Talihim yüzüme gülmeyip kaldı; Ya Rab, bir lokmaya eğme başımı. Geceler uza...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Tamer Hatipoğlu']::text[], 8.5, '{"poet":"Ertuğrul Tamer Hatipoğlu","poet_slug":"ertugrul-tamer-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/egme-basimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanadır İntisabım', 'sanadir-i-ntisabim-garib-garib-6cjv7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne tahtına göz diktim, ne tacına hevesim var,

 Senin bir bakışınla yıkılmış iktidarım var.

Cemâlin karşısında bütün iddiam kül olur,

 her rüzgar esişinde döner yine seni bulur.

Seni bir gül sanmadım ki mevsim geçsin, solasın, 

Ey bir ömrün duası, söyle hangi ömre sığasın?

Ben sende güzelliğin suretini görmedim yalnız,

 Bir kâinat gizlidir gözlerinde, derin ve sonsuz.

Sana meylim bir heves değil, kök salmış bir kader,

 Adınla başlar içimde ne varsa, gerisi bi haber.

Ne kadar saklasam da sırra dönüşür bu hâlim,

 Seninle tamamlanır benim eksik ihtimâlim.

Bir gönül koydum ortaya kapandı hesabım,

Varsın aşk postunda otursun, benim sanadır intisabım.', 'Ne tahtına göz diktim, ne tacına hevesim var,  Senin bir bakışınla yıkılmış iktidarım var. Cemâlin karşısında bütün iddiam kül olur,  her rü...', ARRAY['Türk Edebiyatı','Şiir','Garib Garib']::text[], 8.5, '{"poet":"Garib Garib","poet_slug":"garib-garib","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sanadir-intisabim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim, Yenildim Sustum', 'sevdim-yenildim-sustum-yasar-baykal-zeljp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnsanlar duvar olmuş

Direncimi onlar almış

Görünmez çember var

Çıkılmıyor, olmuyor

Önüme duvarlar konmuş

Sevincimi insanlar çalmış

Görünmez çember var

Çıkılmıyor, olmuyor

Kendimi kapatıyorum herkese

Hayatın iyi gelmeyen her şeyine

Kendimle rahat bıraksınlar

Hayat hapsetti içine

Sevdim, yenildim sustum

Hayat daha arabesk bugün

Sevdim, yenildim sustum

Ne umut tam oldu ne acı bitti

"Ömür Boyu" vermiş hayat

Bana hayat hapishane

Görünmez çember var

Çıkılmıyor, olmuyor', 'İnsanlar duvar olmuş Direncimi onlar almış Görünmez çember var Çıkılmıyor, olmuyor Önüme duvarlar konmuş Sevincimi insanlar çalmış Görünmez ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Baykal']::text[], 8.5, '{"poet":"Yaşar Baykal","poet_slug":"yasar-baykal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevdim-yenildim-sustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarardım Soldum', 'sarardim-soldum-kemal-haciismailoglu-flx2b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir tatlı rüyaydı ömür bizlere. 

Zamanı su gibi akıttı yıllar, 

Ömür emanet kalmaz sizlere, 

Hayata doymadan, ihtiyar oldum... 

Kimseler sormasın geçen yılları,

Avare avare gezdim yolları, 

Maziye gömdüm tüm anıları, 

Bin bir çile ile sarardım soldum...

Bakamam artık aynadan yana, 

Yaşlılık açıyor gönülde yara, 

Savurdu ömrümü, attı kenara, 

Geçti gençliğim, ihtiyar oldum,.. 

Gençliğin büyüsü bağlardı bizi, 

O güzel yılların kalmadı izi, 

Yakıyor sinemi derin bir sızı, 

Bir ömür bitti de, ihtiyar oldum,', 'Bir tatlı rüyaydı ömür bizlere.  Zamanı su gibi akıttı yıllar,  Ömür emanet kalmaz sizlere,  Hayata doymadan, ihtiyar oldum...  Kimseler sor...', ARRAY['Türk Edebiyatı','Şiir','Kemal Hacıismailoğlu']::text[], 8.5, '{"poet":"Kemal Hacıismailoğlu","poet_slug":"kemal-haciismailoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sarardim-soldum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çift Sıfır Gemisi ve Baharlı Elma', 'cift-sifir-gemisi-ve-baharli-elma-alper-tunga-3-3pzxs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneşten ve aydan ışık yontan bu gemi,

Yine tam saatinde ve her zamanki gibi

Çift sıfır gemisi aşıkları her zaman bulur,

Bütün büyük aşıklar, bu gemiyle buluşur.

Bu gün, güvertesinde bir çiftçi elbisesi

Bir bahardan kalma yeşil elmalarlayım.

Yine gözgöze gelince son hızda sendeleyecek,

Bir ışık hüzmesi içerisinde masum hediyeler...

Ve binbir tasviri, itirafı var gözlerinin ruhumda

Bir mandalina kokusu kadar özlem dolu,

Bu geminin buğulu camları kadar hisli

Sen, gözleriyle konuşan bir perisin.

Dünyamız gözlerinin hatrına dönüyor,

Ben her zaman orada olacağımı biliyorum.

Ve şimdi yine zamanın donduğu yerde...

Donup kaldığıma aldanma hiç benim.

Bu benim gözlerine olan saygı duruşum.

Bütün duvarlarında ilkokul çocuklarının resimleri,

Buğulu camlarında bayraklar asılı olan bu gemi

Hediyelerini saçarken, sizin mahallede

Yarın, yollarda ve balkonlarda yeşil elmalar,

Evet! Yine sevgisiz yetişkinler inanmayacaklar,

Meraklı çocuklar sınıflarda yine anlatacak,

Belki bir öğretmen dersi kaynatma pahasına

Belki bir öğrenci gördüklerini herkese anlatacak...

Belediye işçileri sitemle karışık sevinçliyken,

Bir kaç gazateci, gözlerini merak ederse

Ve ruh hastası bir köşe yazarı komplo diyemez!

Sen aldırış etme hiç, gerçek senin gözlerin.

Cift sıfır gemisi geçiyor, bacası dumanlı

Bir sevgi buluşması ve gökyüzü selamı

Yine çift sıfır gemisi durdurur zamanı

Bütün ilhamı gerçek aşıkların bakışması

Çift sıfır gemisi zamanı durdurur 

En büyük aşıklar bu gemiyle buluşur.', 'Güneşten ve aydan ışık yontan bu gemi, Yine tam saatinde ve her zamanki gibi Çift sıfır gemisi aşıkları her zaman bulur, Bütün büyük aşıklar...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga 3']::text[], 8.5, '{"poet":"Alper Tunga 3","poet_slug":"alper-tunga-3","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/cift-sifir-gemisi-ve-baharli-elma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'siz ihtirası bayım', 'siz-ihtirasi-bayim-gonlun-var-mi-sarmasik-wdeom', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'debelenir dururum içimde seni affetmek için
aşk diyorsunuz siz aşkı yüreğinizde taşıyabilecek kadar onurlu musunuz bayım?
debelenir dururum içim sızlar gözlerime bir damla uyku girmez 
ben aşk diyorum sevda diyorum siz arka mahallelerde kavgalara karışıyorsunuz bayım
ben vefadan sadakatten bahsediyorum siz heves diyorsunuz bayım.', 'debelenir dururum içimde seni affetmek için aşk diyorsunuz siz aşkı yüreğinizde taşıyabilecek kadar onurlu musunuz bayım? debelenir dururum ...', ARRAY['Türk Edebiyatı','Şiir','Gönlün Var Mı Sarmaşık']::text[], 8.5, '{"poet":"Gönlün Var Mı Sarmaşık","poet_slug":"gonlun-var-mi-sarmasik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/siz-ihtirasi-bayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
