INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Diyarda Diyarda', 'bizim-diyarda-diyarda-kerim-yavuz-mfq6m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğimde bir sancı var

İşçi darda köylü darda

İnsanımız kalmış naçar 

Bizim diyarda diyarda

Yokluk kanayan yaradır

Kaderimiz kapkaradır

Alın teri beş paradır

Bizim diyarda diyarda

Karışmış herkesin aklı

Duygular derinde saklı

Sabah bile ağlamaklı

Bizim diyarda diyarda

Ne huzur kaldı ne dirlik

Mumla aranıyor birlik

Tahtını kurmuş fakirlik 

Bizim diyarda diyarda

Eser durur çile yeli

Vallah deli olduk deli

Kafalar hep düşünceli

Bizim diyarda diyarda

Yokluk bize sadık yardır

Her ocakta hüzün vardır

Çoluk çocuk perişandır

Bizim diyarda diyarda', 'Yüreğimde bir sancı var İşçi darda köylü darda İnsanımız kalmış naçar  Bizim diyarda diyarda Yokluk kanayan yaradır Kaderimiz kapkaradır Alı...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bizim-diyarda-diyarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennetim Sensin', 'cennetim-sensin-hakan-dagli-2-dlv2n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni toprağa verdiğim o günden beri,

Geceler yıldızlarını saklıyor benden.

Güneş doğsa da aydınlanmıyor içim,

Bir tek sesin eksik bütün seslerden.

Her gece gökyüzüne bakıyorum,

Belki bir yıldızda gözlerin vardır.

Melekler sana kanat gererken,

Benim dualarımda adın saklıdır.

Bırak adımız göklerde yankılansın,

Melekler bile sevdamızı kıskansın

Cennetin bütün gülleri sana açılsın,

masallar  anlatsın aşkımızı.

Bir gün kavuşursak göğün katında,

Bütün melekler şahit olsun aşkımıza.

Cennet beklemesin bizi kapısında.

benim cennetim sensin.

Gel gör ki şimdi yoksun yanımda,

Sesin kaldı gecenin en tenhasında.

Ben hâlâ ilk günkü gibi severken,

hatıra sın artık kalbimin derinlerinde.

Varsın gökyüzü mavisini kaybetsin,

Bütün mevsimler bir kışa dönsün.

Senin olmadığın bir cennette,

Ne güller açsın ne bülbüller ötsün.

Bırak adımız göklerde yankılansın,

Melekler bile sevdamızı kıskansın

Cennetin bütün gülleri sana açılsın,

masallar  anlatsın aşkımızı.

Bir gün kavuşursak göğün katında,

Bütün melekler şahit olsun aşkımıza.

Cennet beklemesin bizi kapısında.

benim cennetim sensin.', 'Seni toprağa verdiğim o günden beri, Geceler yıldızlarını saklıyor benden. Güneş doğsa da aydınlanmıyor içim, Bir tek sesin eksik bütün sesl...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dağlı 2']::text[], 8.5, '{"poet":"Hakan Dağlı 2","poet_slug":"hakan-dagli-2","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/cennetim-sensin-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Güzel', 'hadi-guzel-kerim-yavuz-dnte8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hadi güzel gel murada erelim

Sevgi sende aşk bendedir sevdiğim

Yaylalardan lale sünbül derelim

Bahar sende yaz bendedir sevdiğim

Otursak birlikte taş arasına

Doldursan yoğurdu bakır tasına

Yayalım hayvanı köy merasına

Koyun sende kaz bendedir sevdiğim 

Senden ayrı düşsem içim kan ağlar

Kabarır yüreğim sel olur çağlar

Şenlensin obalar şenlensin dağlar 

Türkü sende saz bendedir sevdiğim

Etme güzel inatlaşma benimle

Gel ruhumu okşa tatlı dilinle

Gel evcilik oynayalım seninle

Cilve sende naz bendedir sevdiğim', 'Hadi güzel gel murada erelim Sevgi sende aşk bendedir sevdiğim Yaylalardan lale sünbül derelim Bahar sende yaz bendedir sevdiğim Otursak bir...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hadi-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolay Değil', 'kolay-degil-kerim-yavuz-08e1g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kolay değil hasretine dayanmak.

Kor ateşlerdeyim bunu bilesin.

Kolay değil senden ayrı yaşamak.

Diken üstündeyim bunu bilesin.

Hadi dön ki kavuşsun ellerimiz.

Hadi dön ki buluşsun gözlerimiz.

Karanlık gecenin loş ışığında,

Mehtapla süslensin gecelerimiz.

Sensiz gözlerime güneş doğmuyor.

Geri dön ki güneş doğsun yeniden.

Elini çabuk tut sensiz olmuyor.

Dönmezsen soğurum aşktan sevgiden.

Gecelerim kabus dolu ağlarım

Rüya olma hayalini istemem

Kurumak üzere gönül bağlarım

Yüreğime su serp, damla istemem.', 'Kolay değil hasretine dayanmak. Kor ateşlerdeyim bunu bilesin. Kolay değil senden ayrı yaşamak. Diken üstündeyim bunu bilesin. Hadi dön ki k...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kolay-degil-154-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancısın', 'yalancisin-kerim-yavuz-xdfqv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana kalbimi vermiştim.

İnan gönülden sevmiştim.

Seni böyle bilmemiştim.

Yalancısın yalancı yalancısın sen.

Hani ismim kalbinde yazılı kalacaktı.

Hani beni kalbinden kimse çıkaramazdı.

Hani birbirimizi ölüm ayıracaktı.

Yalancısın yalancı yalancısın sen.

Bana ne umutlar verdin.

Sözlerinle büyüledin.

Gönlüme tuz biber ektin.

Yalancısın yalancı yalancısın sen.

Hani kalbim tümüyle senin diyordun.

Hani bana mutluluklar vaat ediyordun.

Hani beni herkesten çok seviyordun.

Yalancısın yalancı yalancısın sen.', 'Sana kalbimi vermiştim. İnan gönülden sevmiştim. Seni böyle bilmemiştim. Yalancısın yalancı yalancısın sen. Hani ismim kalbinde yazılı kalac...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalancisin-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskunum', 'suskunum-kerim-yavuz-ixrsu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senden gelen her çileye göğüs gerip katlandım.

Senden başka tek bir kula el açıp yalvarmadım.

Dert verdin çile verdin yinede ağlamadım.

Çektirdiğin zulme rağmen bak yine ben suskunum.

Aşkım için, sevgim için, senin için suskunum.

Sarhoş dedin darılmadım.

Zalim dedin aldırmadım.

Kalpsiz dedin sustum kaldım.

Bak yine ben suskunum.

Aşkım için, sevgim için, senin için suskunum.

Bir gün seversin diye seni üzmek istemedim.

Öyle bağlandım ki sana seni benden çözemedim.

Senden başka hiç kimseye sevgilimsin diyemedim.

Çektirdiğin zulme rağmen bak yine ben suskunum.

Aşkım için,sevgim için,senin için suskunum.

Sarhoş dedin darılmadım.

Zalim dedin aldırmadım.

Kalpsiz dedin sustum kaldım.

Bak yine ben suskunum.

Aşkım için, sevgim için, senin için suskunum.

Suskunum, suskunum suskun.', 'Senden gelen her çileye göğüs gerip katlandım. Senden başka tek bir kula el açıp yalvarmadım. Dert verdin çile verdin yinede ağlamadım. Çekt...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/suskunum-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utan', 'utan-kerim-yavuz-fsvzz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dinle beni ey arlanmaz.

Ettiğin yanında kalmaz.

Haram ile karın doymaz.

Utan Gardaş utan utan

Yoldan sapma bile bile

İnsana yakışmaz hile.

Hile yapan düşer dile.

Utan Gardaş utan utan.

Sözün gerçeklerden uzak.

İçin kirli yüzünse ak.

Mazlumlara kurdun tuzak.

Utan Gardaş utan utan.

Utan dostundan eşinden.

Koşma haramın peşinden.

Kork Allahın ateşinden.

Utan Gardaş utan utan.

Dürüstlükten geri kalma.

İnsancıl ol zalim olma.

Mazlumun ahını alma.

Utan Gardaş utan utan.

Kalmadı mı sende onur.

Haram yemekten geri dur.

Eden ettiğini bulur.

Utan Gardaş utan utan', 'Dinle beni ey arlanmaz. Ettiğin yanında kalmaz. Haram ile karın doymaz. Utan Gardaş utan utan Yoldan sapma bile bile İnsana yakışmaz hile. H...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/utan-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz İkrar', 'sessiz-i-krar-mehmet-bildir-44fwy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SESSİZ İKRAR

Ben seni tanımadan önce de seviyordum sanki,

Adını bilmeden saklıyordum içimde bir yeri.

Henüz yüzün düşmemişti ömrümün aynasına,

Ama kalbim çoktan seçmişti kendi kaderini.

Sana ayrılan bir yer vardı ruhumun derininde,

Ne zaman açıldığını bilmediğim eski bir kapı.

Ben o kapının ardında büyüttüm bütün ömrümü,

Senin haberin olmadan sana adadım yarınlarımı.

Bir çocuğun dünyasında nasıl büyürse ilk bahar,

Benim içimde öyle büyüdü sana duyduğum sevda.

Ne bir karşılık bekledim ne de bir söz istedim,

Seni sevmek yetiyordu bana, gerisi kalsın zamana.

Kimseye anlatamadım içimdeki bu yangını,

Çünkü bazı duygular kelimelere sığmayacak kadar derindir.

Birine söylesem eksilecek sandım sevgimin büyüsü,

Sustum; çünkü sessizlik bile bazen insanın en sadık sırdaşıdır.

Ben seni bir ömrün bütün ihtimallerinden seçtim,

Kendi mutluluğumu senin huzuruna emanet ettim.

Sen bilmeden nice geceler sabaha kadar seni düşündüm,

Ben kendi içimde seninle binlerce hayat tükettim.

Bazen bir sesin yetti bütün günümü güzelleştirmeye,

Bazen bir sessizliğin yetti gecelerimi uzatmaya.

Sen sıradan bir günün içinden geçip giderken,

Ben bir ömür sığdırdım senin küçücük bir bakışına.

Ne zaman yorulsam adını koydum içimdeki sızıya,

Ne zaman kırılsam seni düşünerek topladım kendimi.

Çünkü ben sevgiyi bir mutluluk hesabı sanmadım,

Seni sevmeyi öğrendim, kendimden vazgeçmeden kendimi.

Belki hiçbir zaman bilmeyeceksin bunları,

Hangi gecede gözlerimin uykudan vazgeçtiğini.

Hangi cümlenin ucunda adını yutup sustuğumu,

Hangi sabahın seni düşünerek yeniden başladığını.

Benim senden sakladığım bir ömür var,

Her sayfasında senin adın, her satırında benim susuşum.

Bir gün bütün bu sessizlik dile gelirse,

Anlayacaksın; ben seni hiç kimseye anlatmadan yaşamışım.

Ve bir gün sorarsan kendime ne kaldı bu sevdadan,

Ne bir sitem saklayacağım ne de bir hesap soracağım.

Yalnızca şunu söyleyeceğim kendi kalbime:

Ben seni kaybettiğim yerde değil,

Seni hiç kimsenin bilmediği kadar sevdiğim yerde bulacağım.

Mehmet Bildir', 'SESSİZ İKRAR Ben seni tanımadan önce de seviyordum sanki, Adını bilmeden saklıyordum içimde bir yeri. Henüz yüzün düşmemişti ömrümün aynasın...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bildir']::text[], 8.5, '{"poet":"Mehmet Bildir","poet_slug":"mehmet-bildir","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/sessiz-ikrar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delikanlılık Bu mu?', 'delikanlilik-bu-mu-kerim-yavuz-oaj5v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Garibe el kaldırmak insanlığa sığar mı?

Mertliğin yiğitliğin raconuna uyar mı?

Haram lokma yemeyle söyle karın doyar mı?

Ettiğin iş mi senin delikanlılık bumu?

Toplumun her yerinde adaletsizlik varken.

Garibanlar kimsesiz sefilleri oynarken.

Hırsızlar bu vatan da kanımızı emerken

Sen hala susuyorsun delikanlılık bu mu?

Düşünce suç sayılıp özgürlük susturuldu.

Işık tutan kalemler sokaklarda vuruldu.

Halkımı soymak için rüşvet çarkı kuruldu 

Tepki göstermiyorsun delikanlılık bu mu?

Taşlarla sopalarla maçlara gidiyorsun.

Hiç ağza alınmaz küfürler ediyorsun.

Takımın yenilince terör estiriyorsun.

Utanman yok mu senin, delikanlılık bu mu?

Onlar büyüttü seni henüz bir bebek iken.

Ne hayaller kurdular seni adam ederken.

Anan baban hasretle yollarını gözlerken.

Bir hatır sormuyorsun delikanlılık bu mu?

Vazgeç bu tutumlardan birazcık beni dinle.

Bir yere varamazsın ne nefretle ne kinle.

Ülkemin insanları gurur duysun seninle.

Mantığınla bir düşün delikanlılık bu mu?', 'Garibe el kaldırmak insanlığa sığar mı? Mertliğin yiğitliğin raconuna uyar mı? Haram lokma yemeyle söyle karın doyar mı? Ettiğin iş mi senin...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/delikanlilik-bu-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Dere', 'kara-dere-kerim-yavuz-mtcyf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kara dere azdı gene

Mezar oluyor sevene

Tuttu evimi barkımı

Başıma yıktı bu sene

Kara dere derdin nedir

Sevene kastın nedendir

Bana yarimi geri ver 

Yarimi aldın sendedir

Kara dere bulanıyor 

Çoştu gene şahlanıyor

Aldın götürdün yarimi 

Bak yüreğim kan ağlıyor

Kara dere söz dinlemez 

Kötü huyundan vaz geçmez

Hırsız mı arsız mı desem

Aldığını geri vermez

Akar durursun boyuna

Lanet okudum huyuna

Nice canları götürdün

Gem vurulmaz mı suyuna', 'Kara dere azdı gene Mezar oluyor sevene Tuttu evimi barkımı Başıma yıktı bu sene Kara dere derdin nedir Sevene kastın nedendir Bana yarimi g...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kara-dere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimi Çaldın Geri Ver', 'kalbimi-caldin-geri-ver-kerim-yavuz-yllkb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nasıl oldu anlamadım Çabukluğuna şaştım kaldım

Son anda seni yakaladım Kalbimi çaldın geri ver

Sen kalbimin müptelası Sen hırsızların alâsı

Başımın talı belası Kalbimi çaldın geri ver

Ne hünerli biriymişsin Vallahi cin gibiymişsin

Sana bırakmam bilirsin Kalbimi çaldın geri ver

Doğru sözünü sakınma Aşktan yana hiç yakınma

Masum tavırlar takınma Kalbimi çaldın geri ver

Yeri yok bu aşkın bende İzi yokki bu bedende

Biliyorum kalbim sende Kalbimi çaldın geri ver

Anlatma gönül yaranı Hiç yermiyim numaranı

İnan yakarım çıranı Kalbimi çaldın geri ver

Hadi polis çağırmadan Ele güne karşı rezil olmadan

Daha fazla zorlamadan Kalbim çaldın geri ver

Hırsız hırsız seni gidi arsız Kalbimi çaldın geri ver', 'Nasıl oldu anlamadım Çabukluğuna şaştım kaldım Son anda seni yakaladım Kalbimi çaldın geri ver Sen kalbimin müptelası Sen hırsızların alâsı ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kalbimi-caldin-geri-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Buraları Bilemezsin', 'sen-buralari-bilemezsin-mustafa-kaynak-2-fa7ww', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaybolmuş bir şehirdeyim,

Kimseler yok sokaklarda.

Boş kaldırımlarda yürüyorum,

Sen geliyorsun aklıma.

Ellerim soğuktan donuyor,

Rüzgâr bir şarkı fısıldıyor.

Uzaklardan gelen sesler,

Gecenin rengine karışıyor.

Sen buraları bilemezsin.

Geceler çok soğuk geçer.

Sensiz soldu mevsimler,

Yokluğun ölümden beter.

Her köşe başında seni arıyorum,

Eski günlerin özlemini çekiyorum.

Bir türlü silemedim izlerini,

Her gece yeniden yaşıyorum seni.

Hoşça kal, işte gidiyorum,

Boş kaldırımlarda yürüyorum.

Karanlık sokaklarda kayboldum,

Seni hâlâ deli gibi seviyorum.

Mustafa Kaynak', 'Kaybolmuş bir şehirdeyim, Kimseler yok sokaklarda. Boş kaldırımlarda yürüyorum, Sen geliyorsun aklıma. Ellerim soğuktan donuyor, Rüzgâr bir ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kaynak 2']::text[], 8.5, '{"poet":"Mustafa Kaynak 2","poet_slug":"mustafa-kaynak-2","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-buralari-bilemezsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemezler Koçuk', 'yemezler-kocuk-kerim-yavuz-vke36', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen beni anlamıyorsun

Peşimi bırakmıyorsun

Kırdığın ceviz kırkı aştı

Bir türlü uslanmıyorsun

Üç düğme açtın yakanı

Yerim senin fiyakanı

Seni bilenler biliyor

Fuzuli işler bakanı

Belki pembe bir düşdesin

Uyan canım düşeceksin

Olmaz artık bu kadarı fazla

Ufak at civcivler yesin

O dillerini yesinler 

Yürü boyunu görsünler

Ölçüsüz attın isabet sıfır 

Yalanlarını sevsinler

Yemezler koçum havanı atma 

Uyanıklık edip beleşe konma 

Bu yolun sonu hayırlı değil

Doğru yürü sakın çamura batma

Sen beni sakın enayı sanma

Hilebazlık edip dümene yatma

Yedirmezler sana ballı lokmayı

Bir daha beni aklına sokma', 'Sen beni anlamıyorsun Peşimi bırakmıyorsun Kırdığın ceviz kırkı aştı Bir türlü uslanmıyorsun Üç düğme açtın yakanı Yerim senin fiyakanı Seni...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yemezler-kocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Meleğim', 'kara-melegim-kerim-yavuz-3l6yy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Esti ayrılık rüzgarı

Yıkıldı gönül direğim

Duy yüreğimin sesini

Ey benim kara meleğim

Sana meleğim demiştim

Seni gönülden sevmiştim

Bırakıp ta gittin beni

Ben aşkına güvenmiştim

Her şey virane gözümde

Sensiz hayat neye yarar

Bir ateş attın özüme

Yüreğime kastın mı var

Gönül bağına gireyim 

Budur inan tek dileğim

Gözümde ki kanlı yaşlar

Senin eserin meleğim

Kara meleğim kara meleğim

Neredeysen dön gel artık 

Sensiz yapamaz yüreğim

Su gibi ak toprağıma 

Solmadan gönül çiçeğim', 'Esti ayrılık rüzgarı Yıkıldı gönül direğim Duy yüreğimin sesini Ey benim kara meleğim Sana meleğim demiştim Seni gönülden sevmiştim Bırakıp ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kara-melegim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İdare Ediyorum', 'i-dare-ediyorum-kerim-yavuz-oifaq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben kendimde değilim

Divane geziyorum

Dertliyim kederliyim

İdare ediyorum

Gönlümün meziyeti

Çeker bu eziyeti

Durumu vaziyeti 

İdare ediyorum

İçimde ateş sönmez

Bu şansım kolay dönmez

Buna yaşamak denmez

İdare ediyorum

Yuvarlanıp giderek

Kader buymuş diyerek

Zeytin ekmek yiyerek

İdare ediyorum

Kırmadan kırılmadan

Kimseye darılmadan

İçkiye sarılmadan

İdare ediyorum', 'Ben kendimde değilim Divane geziyorum Dertliyim kederliyim İdare ediyorum Gönlümün meziyeti Çeker bu eziyeti Durumu vaziyeti  İdare ediyorum...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/idare-ediyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Gülmek Yakışıyor', 'sana-gulmek-yakisiyor-mustafa-kaynak-2-usqpy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni uzaktan görsem yeter bana,

Bir gülüşün bahar olsun dünyama.

Belki yollarımız hiç birleşmeyecek,

Sen sevmesen bile bu aşk sürecek.

Gözlerinde saklı taze baharlar,

Gülüşünde saklı güzel yarınlar.

Ben sana bir ömür sevdalıyım,

Sensiz geçmiyor aylar, yıllar.

Ben uzaktan severim, sen üzülme,

Yeter ki bahar açsın gönlünde.

Sana bahar yakışıyor, kış değil,

Gözlerinden gül düşsün, yaş değil.

Sana gülmek yakışıyor, hiç ağlama,

Güneş doğsun yüzüne her sabah.

Seni uzaktan görsem yeter bana,

Bir gülüşün bahar olsun dünyama.

Bir gün eski bir şarkı çalarsa,

Belki güzel günler gelir aklına.

Bil ki bir yerde ismini anıyorum,

Ömür boyu sana mutluluk diliyorum.

Her sevda kavuşmak değilmiş meğer,

Bazen sevmek, özlemek demekmiş.

Senden bana hep hasret düşse bile,

Seni uzaktan sevmek de güzelmiş.

Sana gülmek yakışıyor, hiç ağlama,

Güneş doğsun yüzüne her sabah.

Seni uzaktan görsem yeter bana,

Seni çok seviyorum, beni unutma.

Mustafa Kaynak', 'Seni uzaktan görsem yeter bana, Bir gülüşün bahar olsun dünyama. Belki yollarımız hiç birleşmeyecek, Sen sevmesen bile bu aşk sürecek. Gözle...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kaynak 2']::text[], 8.5, '{"poet":"Mustafa Kaynak 2","poet_slug":"mustafa-kaynak-2","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sana-gulmek-yakisiyor-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazıklar Olsun', 'yaziklar-olsun-kerim-yavuz-1ds0u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Haram yeme bile bili

Uzak dursun senden hile

Garibi acı söz ile 

Yakana yazıklar olsun

Kiminin kaderi kara

Kiminin yüreği yara

Fikirleri dört duvara

Tıkana yazıklar olsun

Kuzu emanet tilkiye

Bu vurdum duymazlık niye

Kimsesize köle diye

Bakana yazıklar olsun

Neden bu eziyet bize

Döndü baharımız güze

Haksız yere tepemize

Çıkana yazıklar olsun

Olan yok sözünün eri

Yüreğimiz yangın yeri

Kurduğumuz hayalleri 

Yıkana yazıklar olsun

Tak ettiler canımıza

Karlar yağdı yazımıza

Zehir olup kanımıza

Akana yazıklar olsun', 'Haram yeme bile bili Uzak dursun senden hile Garibi acı söz ile  Yakana yazıklar olsun Kiminin kaderi kara Kiminin yüreği yara Fikirleri dör...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yaziklar-olsun-324-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yayla', 'yayla-kerim-yavuz-3ymam', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeşil örtüleri sermiş düzüne

Heyecanla bizi bekliyor yayla

Bahar kokusunu sürmüş üstüne

Buram buram çiçek kokuyor yayla

Kışın oluyorsun duvaklı gelin

Yaz ayında çoktur gelen gidenin

Düşünce aklıma çayır çimenin

Yüreğim bir tuhaf oluyor yayla

Öpüşür bulutlar topraklarınla

Çiçekler aşk yaşar arılarınla

Bereket verirsin yağmurlarınla

Bilen kıymetini biliyor yayla

Bazan dağlarını sarar bir duman

Sensizlik içimde yaradır inan

Süzme yoğurdundan içtiğim zaman

İnan ki gözlerim gülüyor yayla

Şimdi gurbet oldu benim vatanım

Ayrı düştüm senden daraldı canım

Adını andıkça kaynıyor kanım

İnan ki gözlerim doluyor yayla

Çocukluk yıllarım geçti seninle

Tenimi okşardın seher yelinle

Bazen kemençeyle bazen saz ile

Yavuzoğlu seni anıyor yayla', 'Yeşil örtüleri sermiş düzüne Heyecanla bizi bekliyor yayla Bahar kokusunu sürmüş üstüne Buram buram çiçek kokuyor yayla Kışın oluyorsun duva...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yayla-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-kerim-yavuz-g8epi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her şey boş gözümde her taraf viran

Gurbette kendimi avutamadım

İnan ki aklımdan çıkmadın inan

Memleketim gibi  unutamadım

Bu gurbet ellerde geçmiyor günler

Hasrete bir türlü alışamadım

Bir yanım git diyor bir yanım gitme

Ben kendi kendimle barışamadım

Huzur bulamadım gurbet ellerde

Suyundan aşından tat alamadım

Gurbetle gavgalı geçiyor ömrüm

Gurbetle bir türlü dost olamadım', 'Her şey boş gözümde her taraf viran Gurbette kendimi avutamadım İnan ki aklımdan çıkmadın inan Memleketim gibi  unutamadım Bu gurbet ellerde...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gurbet-904-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'L''amitié entre femmes et hommes selon le Coran', 'l-amiti-entre-femmes-et-hommes-selon-le-coran-muhammed-ridvan-gizri-xq1cw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Le Coran ne sépare pas la femme et l''homme dans la vie sociale ; il les réunit au contraire dans une responsabilité morale commune. Le verset 71 de la sourate At-Tawba joue un rôle déterminant pour comprendre cette question.

« Les croyants et les croyantes sont alliés (awliyâ'') les uns des autres. Ils ordonnent le bien et interdisent le mal, accomplissent la prière, s''acquittent de la zakât, et obéissent à Allah et à Son messager. Voilà ceux à qui Allah accordera Sa miséricorde. Allah est certes Puissant et Sage. » (At-Tawba, 9/71)

La notion d''awliyâ'' (alliés, amis, soutiens) employée dans ce verset n''exprime pas un rapport d''autorité à sens unique, mais une communauté réciproque, égalitaire et fondée sur la responsabilité. Il est remarquable que ce lien d''alliance ne repose pas uniquement sur une proximité affective ou une harmonie sociale. L''expression « ordonner le bien et interdire le mal », qui suit immédiatement, en révèle clairement le fondement : une responsabilité morale partagée. Dans ce cadre, la relation entre femmes et hommes décrite par le verset ne relève pas d''un rapprochement dicté par les désirs de l''âme (nafs) ; elle consiste à se tenir côte à côte dans la construction de la foi et de la vertu. Voici donc le tableau que le Coran cherche à dresser à travers ce verset : la femme et l''homme ne sont pas deux mondes séparés, mais deux sujets partenaires d''une même société, d''une même responsabilité morale et d''une même miséricorde divine.

Aucun verset du Coran n''interdit directement l''amitié entre femmes et hommes. Au contraire, le Coran confirme, dans de nombreux contextes, que les deux sexes interagissent dans la vie sociale. La conversation de notre prophète Moïse avec les deux jeunes femmes au puits de Madian, la négociation de la reine de Saba avec ses dignitaires masculins, la participation des femmes à la vie sociale et religieuse à l''époque de notre prophète Muhammad : tout cela montre que la communication et l''interaction entre les sexes existent et sont légitimes dans le tableau général que dessine le Coran. De fait, certains versets des sourates An-Nûr et Al-Ahzâb n''ont pas été révélés pour interdire la communication entre femmes et hommes, mais pour déterminer la manière dont elle doit se dérouler. Autrement dit, l''islam n''ignore pas cette relation ; il lui trace un cadre.

L''accent le plus fort du verset 71 de la sourate At-Tawba porte sur le fait que l''union entre l''homme et la femme soit bâtie sur al-amr bi''l-ma''rûf wa''n-nahy ''ani''l-munkar, c''est-à-dire « ordonner le bien et interdire le mal ». Cela confère à la relation d''amitié une profondeur de sens considérable. Ainsi, les principes suivants constituent le fondement de la légitimité de l''amitié entre femmes et hommes en islam :

1. La pureté de l''intention : Le point de départ de la relation est de s''aimer pour l''agrément d''Allah et de vouloir le bien de l''autre. Le plaisir personnel, l''attirance ou la satisfaction des désirs de l''âme ne peuvent en être le but.

2. L''élévation morale : Une amitié qui élève ses membres moralement et spirituellement, qui les amène à se rappeler le bien et à s''éloigner mutuellement du mal, correspond pleinement à la définition de l''alliance (walâya) selon l''esprit du verset. À l''inverse, un rapprochement qui tire les personnes vers le bas, les rend complices dans le péché ou affaiblit leur spiritualité ne mérite pas le nom d''amitié.

3. Le sens des responsabilités : La relation d''amitié doit aussi jouer le rôle d''un mécanisme d''autocontrôle. Deux personnes qui s''aiment ne se poussent pas vers l''erreur ; elles s''attirent au contraire vers le juste. Ce sens des responsabilités vaut de manière égale pour la femme et pour l''homme.

Les dispositions que le Coran apporte à la relation entre femmes et hommes doivent être comprises non comme un instrument de contrainte, mais comme visant à préserver la paix sociale, la dignité de l''individu et le respect mutuel. Dans ce cadre, certaines limites fondamentales doivent impérativement être observées :

Le ton et le langage : Le verset 32 de la sourate Al-Ahzâb indique que la parole adressée aux femmes ne doit pas être d''une douceur susceptible de provoquer la tentation (fitna), mais mesurée. Ce principe énonce une règle de bienséance qui vaut en pratique non seulement pour les femmes, mais aussi pour les hommes. Un ton provocant, séducteur ou contenant une invitation explicite peut conduire quelqu''un « dont le cœur est malade » à se méprendre. Même dans une amitié, le ton et le contenu de la conversation doivent être façonnés dans cette conscience.

L''intimité et l''espace privé : Le respect des limites et de la sphère privée est un principe universel, toujours valable aujourd''hui. Ne pas pénétrer sans autorisation dans l''espace de vie, le corps ou le monde émotionnel d''autrui est une limite à ne jamais transgresser, y compris dans une relation d''amitié.

Éviter l''incontrôle émotionnel : Si une amitié se transforme avec le temps en dépendance affective, en sentiments amoureux dissimulés ou en rapprochement physique, elle ne relève plus du terrain de la walâya que trace le Coran. L''islam ne considère pas comme légitime une telle dérive, mais une relation consciente, mesurée et maîtrisée.

Le Coran n''écarte pas la femme de la vie sociale. La présence conjointe des femmes et des hommes dans la vie commerciale, dans les assemblées de savoir et dans la solidarité sociale est une réalité observée dès les premières époques de la civilisation islamique. Par conséquent, une conception selon laquelle « les femmes devraient rester à la maison et n''avoir aucune interaction avec les hommes » n''est conforme ni à l''ensemble du Coran ni à la pratique des débuts de l''islam. La vie sociale réunit inévitablement femmes et hommes dans les mêmes lieux, les mêmes responsabilités et, parfois, les mêmes liens d''amitié. Le Coran ne l''interdit pas ; il en règle la manière.

Au vu de tout ce cadre, on peut parvenir à la conclusion suivante :

Selon le Coran, l''amitié entre femmes et hommes n''est pas, en son essence, interdite. Bien au contraire, le verset 71 de la sourate At-Tawba lie les deux sexes dans une responsabilité morale commune ; il les définit comme alliés, amis et soutiens les uns des autres. Toutefois, la légitimité de cette relation dépend du respect de certains principes : la pureté de l''intention, l''élévation morale, la mesure du ton, la conscience de l''intimité et la maîtrise des émotions. Si une amitié porte ces principes, elle est conforme à l''esprit du Coran, fait partie du bien social et entre dans le champ de la promesse de recevoir « la miséricorde d''Allah ».

Si en revanche cette relation dégénère en rapprochement arbitraire, en satisfaction des désirs de l''âme ou en violation des limites morales, il ne s''agit plus d''amitié, mais d''autre chose, et c''est précisément cela que le Coran ne considère pas comme légitime.

L''islam ne sépare pas la femme et l''homme. Il les réunit dans la responsabilité. L''amitié est possible, mais cette amitié prend son sens sur le terrain de la conscience, de la bienséance et de la morale. Les limites n''existent pas pour restreindre la liberté, mais pour préserver la valeur de la relation.', 'Le Coran ne sépare pas la femme et l''homme dans la vie sociale ; il les réunit au contraire dans une responsabilité morale commune. Le verse...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/l-amitie-entre-femmes-et-hommes-selon-le-coran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-sahin-keven-2-f8kdf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalk parçalanmış ömür

Sonsuzluğa haber sal

Zaman son anı kemir

Yada boşluğunda kal', 'Kalk parçalanmış ömür Sonsuzluğa haber sal Zaman son anı kemir Yada boşluğunda kal...', ARRAY['Türk Edebiyatı','Şiir','Şahin Keven 2']::text[], 8.5, '{"poet":"Şahin Keven 2","poet_slug":"sahin-keven-2","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zaman-1173-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorum Buralardan', 'gidiyorum-buralardan-kerim-yavuz-rh4a9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dostlar benim size bir haberim var

Gidiyorum buralardan eyvallah

Sazım gurbet elde tutmadı ayar

Gidiyorum buralardan eyvallah

Eridim tükendim ben yana yana

Yeter dedim artık ben bu figana

Hakınızı helal eyleyin bana

Gidiyorum buralardan eyvallah

Bilmem ki bu şehrin nesine kandım

Buraya geleli kor olup yandım

Bu şehirde yaşamaktan usandım

Gidiyorum buralardan eyvallah

Burada garibin hayatı çile

Sarmış buraları hırsızlık hile

Avuçlarımdaki nasırlar ile

Gidiyorum buralardan eyvallah

Kimisi cin olmuş kimisi peri

Sömürdüler beni yıllardan beri

İnanın ki dönmem bir daha geri

Gidiyorum buralardan eyvallah

Olmadı burada mutlu bir anım

Köyüm diye diye kaynadı kanım

Bu şehire geldiğime pişmanım

Gidiyorum buralardan eyvallah', 'Dostlar benim size bir haberim var Gidiyorum buralardan eyvallah Sazım gurbet elde tutmadı ayar Gidiyorum buralardan eyvallah Eridim tükendi...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gidiyorum-buralardan-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lanet Olsun', 'lanet-olsun-kerim-yavuz-93vsn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hırsızlar sardı ülkeyi

Çalanlara lanet olsun

Beleşci ağası beyi

Talanlara lanet olsun

Devlet malı deniz derler

Haramı kökünden yerler

Halktan gizlenir gerçekler

Yalanlara lanet olsun

Uzak ettiler yakını

Kurdular rüşfet çarkını

Tüysüz yetimin hakkını

Alanlara lanet olsun

Akıl ermiyor bu işe

Bire alır satar beşe

Kargalar gibi beleşe

Konanlara lanet olsun

Uyanın yollara düşek

İlimle irfanla pişek

Yüzsüzlere yorga döşek

Olanlarna lanet olsun

Kalma yanlışlara sessiz

Sanmasınlar bizi dilsiz

Haksızlıklara ilgisiz

Kalanlara lanet olsun', 'Hırsızlar sardı ülkeyi Çalanlara lanet olsun Beleşci ağası beyi Talanlara lanet olsun Devlet malı deniz derler Haramı kökünden yerler Halkta...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/lanet-olsun-193-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Verin Ey Dağlar', 'yol-verin-ey-daglar-kerim-yavuz-vcx7u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bahar geldi sılaya döndü kuşlar 

Yol verin ey dağlar bende gideyim

Sel oldu akıyor gözümden yaşlar

Yol verin ey dağlar ben de gideyim

İş tutmuyor elim aklım hep yar da

Düştüm gurbet ele yüreğim dar da

Boynu bükük kaldım ben bu diyarda

Yol verin ey dağlar ben de gideyim

Alev alev yandı bu yürek dertte

Sıla özlemi var yanar elbette

Herkes gitti bir ben kaldım gurbette

Yol verin ey dağlar ben de gideyim

Bu gurbet derdime merhem olmadı

Dağ gibi derdimden zerre almadı

Artık dayanacak gücüm kalmadı

Yol verin ey dağlar ben de gideyim

Tüketiyor beni bu yangın yeri

Yolum gurbet ele düşeli beri

Özledim köyümde açan gülleri

Yol verin ey dağlar ben de gideyim

Doldu deli gönül ağlıyor gene

Yardım et Allahım hasret çekene

Herkes sılasına döndü bu sene

Yol verin ey dağlar ben de gideyim', 'Bahar geldi sılaya döndü kuşlar  Yol verin ey dağlar bende gideyim Sel oldu akıyor gözümden yaşlar Yol verin ey dağlar ben de gideyim İş tut...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yol-verin-ey-daglar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktan Sevmeye Alıştım Seni', 'uzaktan-sevmeye-alistim-seni-mustafa-kaynak-2-rjv8p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni görmeden geçti yıllarım,

İçimde kaldı sessiz duygularım.

Bir gün gelirsin diye bekledim seni,

Gurbette bir ömür sensiz geçti.

Sen başka sevdanın peşinden gittin,

Ben kendi dünyamda seni bekledim.

Sen hiç bilmedin sana olan sevdamı,

Yıllarca sakladım içimdeki aşkımı.

Uzaktan sevmeye alıştım seni,

Yıllarca kalbimde taşıdım seni.

Sen benden uzaklarda olsan bile,

Ben böyle sevmeye razıyım seni.

Belki bir başkası tutar ellerini,

Belki bir başkası güldürür gözlerini.

İçimde sana sakladığım sözlerimi,

Belki bir başkası söyler sevgisini.

Sana kavuşmak artık mümkün değil,

Yeter ki mutlu olsun güzel yüreğin.

Yarım kalan sevdam içimde saklı,

Bir ömür gülsün o ceylan gözlerin.

Eski günleri sessizce anarım,

Gülüşün düşer aklıma ansızın,

Dalıp giderim uzak yollarda,

Bir nefes kadar yakınım sana.

Uzaktan sevmeye alıştım seni,

Yıllarca kalbimde taşıdım seni.

Sen benden uzaklarda olsan bile,

Ben böyle sevmeye razıyım seni.

Ne bir sitemim var, ne bir isyanım,

Sen mutlu ol yeter, buna razıyım.

Ben kendi hâlimde, sen uzaklarda,

Seni uzaktan sevmeye alıştım.

Mustafa Kaynak', 'Seni görmeden geçti yıllarım, İçimde kaldı sessiz duygularım. Bir gün gelirsin diye bekledim seni, Gurbette bir ömür sensiz geçti. Sen başka...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kaynak 2']::text[], 8.5, '{"poet":"Mustafa Kaynak 2","poet_slug":"mustafa-kaynak-2","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/uzaktan-sevmeye-alistim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyanın  Nesini Seveyim?', 'dunyanin-nesini-seveyim-riza-akbulut-vrtvy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönlüme ümit ekerim yel alır.

İyi niyetimi hep sel alır.

Kırk yılda bir yar severim, el alır.

Ben bu dünyanın nesini seveyim?

Ezelden böyledir benim bahtım.

Aşta yok henüz bir siftahım.

Sorarsan millete bir padişahım. 

Ben bu dünyanın nesini öveyim?

Yıllar yılı gezdim diyar diyar.

Bulamadım kendime bir yar.

Şimdi isyan etsem eder mi kâr?

Ben bu dünyanın nesini seveyim?

Bilmiyorum nasıl böyle yaşıyorum.

İnan halime  ben de şaşıyorum.

Sanki dünyanın yükünü taşıyorum.

Böyledir kaderim, kimi döveyim?

Böyle yazılmış benim kaderim.

Yine de halime şükrederim.

Bir gün bu dünyadan göçer giderim.

Ben bu dünyanın nesini öveyim?', 'Gönlüme ümit ekerim yel alır. İyi niyetimi hep sel alır. Kırk yılda bir yar severim, el alır. Ben bu dünyanın nesini seveyim? Ezelden böyled...', ARRAY['Türk Edebiyatı','Şiir','Rıza Akbulut']::text[], 8.5, '{"poet":"Rıza Akbulut","poet_slug":"riza-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dunyanin-nesini-seveyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Les signes visibles et la limite de l''invisible (al-ghayb)', 'les-signes-visibles-et-la-limite-de-l-invisible-al-ghayb-muhammed-ridvan-gizri-57xrb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Depuis sa création, l''être humain est confronté à deux questions fondamentales : « Que s''est-il passé ? » et « Que va-t-il se passer ? ». Pour comprendre le passé, des sciences telles que l''histoire, la sociologie et l''archéologie ont été développées ; pour appréhender l''avenir, la météorologie, l''économie, la géologie et bien d''autres sciences de la prévision ont vu le jour. Pourtant, au cœur de cette quête se dresse une frontière ancienne et universelle : l''invisible (ghayb). Le Coran la définit de manière à la fois claire et profonde. Le verset 59 de la sourate Al-An''âm dit : « Les clés de l''invisible sont auprès de Lui. Nul ne les connaît hormis Lui. » En revanche, le verset 75 de la sourate Al-Hijr ne laisse pas l''être humain dans une posture entièrement passive : « Il y a en cela des signes pour ceux qui savent lire les indices. » Ces deux versets ne s''annulent pas, ils se complètent. L''un trace la limite de l''intelligence humaine, l''autre rappelle la responsabilité de l''homme à l''intérieur de cette limite.

Qu''est-ce que le ghayb, et pourquoi n''appartient-il qu''à Dieu ?

Le mot ghayb signifie littéralement « caché, invisible, ce qui ne peut être perçu par les sens ». Sur le plan théologique, il désigne le champ de la connaissance absolue : les inconnues du passé, les certitudes de l''avenir et la sagesse ultime des événements qui se déroulent dans l''univers. Le Coran aborde le ghayb selon une structure à deux niveaux. Le premier niveau est celui du ghayb absolu, auquel aucun moyen humain ne peut accéder : le moment de l''Heure dernière, la nature de l''esprit, la réalité du Paradis et de l''Enfer. Le second niveau comprend les inconnues relatives : ce qui est déjà réalisé auprès de Dieu, mais pas encore pour nous, et sur quoi l''on peut formuler des prévisions à partir des données disponibles. C''est précisément aux confins de ce second niveau que s''exercent la science et la raison. La connaissance divine de l''invisible est une connaissance absolue et immuable, au-delà du temps et de l''espace. L''esprit humain, lui, est un instrument qui fonctionne dans le temps, lié par la chaîne de la causalité, avec des données incomplètes et une perception limitée. Cette différence structurelle montre que, quels que soient ses progrès, l''être humain ne pourra jamais atteindre la connaissance absolue.

Lire les signes : une capacité unique donnée à l''être humain

Ce que le Coran présente comme la caractéristique essentielle qui distingue l''être humain des autres créatures, la raison, n''est pas un simple entrepôt de connaissances : c''est la capacité de lire les signes, d''établir des relations entre eux et d''en tirer des conclusions. Les expressions « pour ceux qui raisonnent », « pour ceux qui réfléchissent », « pour ceux qui prennent en considération », maintes fois répétées dans le Coran, montrent que cette capacité répond à un appel divin.

Quels sont donc ces signes ?

Les signes en météorologie : l''accumulation de nuages sombres, la baisse de la pression atmosphérique, la hausse du taux d''humidité : tout cela annonce une pluie ou une tempête prochaine. Le météorologue lit ces données et produit une prévision probabiliste. Il ne peut savoir avec certitude s''il pleuvra, mais il lit assez de signes pour recommander de prendre un parapluie.

Les signes en géologie : les tensions le long des failles, l''activité microsismique, les modifications de la structure du sol : le géologue analyse toutes ces données pour évaluer le risque sismique. Personne ne peut savoir exactement quand un séisme se produira ni quelle sera son intensité ; pourtant, les mesures de précaution dans les zones à risque, le renforcement des normes de construction et la mise en place de systèmes d''alerte précoce sont les fruits concrets de cette lecture des signes.

Les signes en économie : taux d''inflation, politiques de taux d''intérêt, données de production, statistiques du chômage : l''économiste expérimenté évalue ces indicateurs ensemble et peut déceler qu''une crise ou une reprise approche. Les rares analystes qui avaient prévu la crise financière mondiale de 2008 avaient lu ces signes différemment des autres. Mais personne ne savait à l''avance quand exactement la crise éclaterait, quelle banque elle toucherait et dans quelle mesure, ni quelles en seraient les conséquences à long terme.

Les signes en éducation : les performances passées d''un élève, ses habitudes de travail, sa motivation et son environnement social : un éducateur expérimenté peut rassembler ces données et formuler des prévisions pertinentes sur sa réussite future. Il ne s''agit pas de lire le destin, mais de procéder à une évaluation fondée sur des relations de cause à effet.

Le point commun de tous ces exemples est le suivant : en observant les données disponibles et en analysant leurs relations, l''être humain dessine une carte probabiliste de l''avenir. Cette carte est un guide, non une prophétie.

La frontière subtile entre deux notions

La différence entre lire les signes et connaître l''invisible n''est pas seulement épistémologique, elle est aussi existentielle. On peut clarifier cette distinction ainsi :

Lire les signes consiste à tirer des conclusions à partir de données. C''est une activité à la portée de l''être humain. Elle comporte une part de probabilité et de conjecture. Elle repose sur l''observation des causes. Elle admet la possibilité de l''erreur, et cette faillibilité fait partie de sa nature.

Connaître l''invisible, c''est connaître l''avenir avec certitude. Cela n''appartient qu''à Dieu. Cela implique une connaissance absolue. Cela repose sur la science infinie de Dieu. L''infaillibilité et la certitude en sont des attributs inséparables.

L''importance pratique de cette distinction est considérable. Lorsqu''un météorologue dit : « Il y a 80 % de chances qu''il pleuve demain », il ne prétend pas connaître l''invisible. Mais s''il affirme : « Il pleuvra à coup sûr demain, et cette pluie frappera tel village à telle heure », il a dépassé les limites de la prévision probabiliste. Cette affirmation est inacceptable, tant d''un point de vue scientifique que religieux.

L''équilibre du Coran : appel à la réflexion et appel à l''humilité

L''équilibre du Coran sur ce sujet est remarquable. D''un côté, il ordonne sans cesse d''user de la raison, d''observer l''univers et de tirer des leçons des signes. De l''autre, il rappelle encore et encore les limites du savoir humain et le caractère absolu de la science de Dieu. Cet équilibre protège l''être humain de deux écueils dangereux :

Le premier danger est de sacraliser l''ignorance. Certaines conceptions peuvent, au nom du ghayb, juger vain ou religieusement répréhensible tout effort de prévision. Or cela est contraire à l''esprit du Coran, qui encourage à observer les nuages, à ensemencer la terre et à prendre des précautions pour se protéger de la maladie.

Le second danger est d''absolutiser la raison. À l''époque moderne en particulier, l''illusion est répandue que la science pourrait acquérir une puissance sans limites et que toutes les inconnues finiront par être résolues. Pourtant, du principe d''incertitude de la mécanique quantique à la théorie du chaos, des marges d''erreur des modèles statistiques au silence qui précède parfois les grands séismes, la science a maintes fois confirmé ses propres limites. Quelle que soit la puissance de l''intelligence humaine, prétendre accéder à la connaissance certaine de l''avenir est injustifié, tant sur le plan scientifique que théologique.

La métaphore du parapluie : l''union de la précaution et de l''abandon confiant

L''une des plus belles images pour concrétiser ce sujet est celle du parapluie : la tâche de l''être humain est de voir les nuages devant lui et de prendre son parapluie. C''est le symbole de la lecture des signes et de la précaution. Ignorer les nuages et se faire tremper n''est pas de l''abandon confiant (tawakkul), c''est de la négligence. Mais savoir à quelle seconde précise la pluie commencera, combien de gouttes tomberont sur chaque mètre carré, quelles graines elle fera germer à long terme, quelle inondation ou quelle bénédiction elle apportera, relève du ghayb absolu. L''être humain reconnaît ici la limite de son savoir, et cette reconnaissance est l''expression non d''une faiblesse, mais d''une maturité.

La conception islamique du tawakkul exprime exactement cet équilibre. Précaution et abandon doivent coexister. Sans précaution, le tawakkul ouvre la porte à la paresse ; sans tawakkul, la précaution ouvre la porte à l''orgueil. Le verset 75 de la sourate Al-Hijr et le verset 59 de la sourate Al-An''âm ne s''excluent pas, ils se complètent : le premier invite l''être humain à réfléchir, à observer et à tirer du sens des signes ; le second rappelle que cet effort ne pourra jamais se transformer en connaissance absolue.

Le météorologue prévoit la tempête, mais c''est Dieu qui remplit le ciel de cette tempête. Le géologue mesure la faille, mais c''est Dieu qui commande aux forces sous le sol. L''économiste analyse les données, mais c''est Dieu qui oriente les volontés derrière les marchés. L''éducateur évalue le potentiel, mais c''est Dieu qui a créé ce potentiel. L''être humain est un lecteur de signes ; Dieu est l''auteur de toute chose.

Aussi, la position la plus juste pour l''être humain est d''utiliser sa raison au maximum, de lire les signes avec rigueur, de ne jamais négliger la précaution, de rester conscient des limites de son savoir tout au long de cette démarche, et de s''en remettre à Dieu pour l''issue finale. Car voir l''horizon est une chose ; connaître ce qui se trouve au-delà de l''horizon en est une autre.', 'Depuis sa création, l''être humain est confronté à deux questions fondamentales : « Que s''est-il passé ? » et « Que va-t-il se passer ? ». Po...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/les-signes-visibles-et-la-limite-de-l-invisible-al-ghayb-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Doğmaz Ocağıma', 'gunes-dogmaz-ocagima-kerim-yavuz-9fe17', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneş doğmaz ocağıma

Kar yağdı gönül dağıma

Ben yarimi kucağıma 

Alamadım alamadım

Dikenler düştü yoluma

Baykuşlar kondu dalıma

Yari eş diye koluma 

Takamadım takamadım

Düşmüşüm kara sevdaya

Çöller de kalmışım yaya

Yar gözlerine bakmaya 

Doyamadım doyamadım

Çoştu deli gönül yine

Yandı köz oldu bu sine

Aşk ateşini kalbine

Yakamadım yakamadım', 'Güneş doğmaz ocağıma Kar yağdı gönül dağıma Ben yarimi kucağıma  Alamadım alamadım Dikenler düştü yoluma Baykuşlar kondu dalıma Yari eş diye...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gunes-dogmaz-ocagima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen İstanbul''sun', 'sen-i-stanbul-sun-bekir-ercaliskan-v7tbu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SEN İSTANBUL''SUN

Ey... Gönlümün sultanı!

İstanbul’un yedi tepesi gibi bir mihrap kurdun yüreğimde;

Boğaz’ın gümüş sularına düşen akşam sisi saklı gözlerinde;

Sen İstanbul’sun!

Kız Kulesi’nin yalnızlığına bürünen o hüzünlü hikâyesin,

Yerebatan Sarayı’nın loş sularında Medusa’yı kıskandıran o derin esrar;

Haliç’in akşam alacasında suya vuran o mahzun gizemsin.

Boğaz’ın iki yakasını birleştiren o eşsiz vuslatsın,

Asırlara boyun eğmeyen kadim sursun.

Sen İstanbul’sun!

Geçmişin dehlizlerinden süzülen Bizans efsanelerinden çıkma bir mitsin.

İo’nun geçtiği sularda uyuyan bir efsane, gözlerinde yeniden hayat buluyor.

Argonotların altın postu aradığı denizler gibi,

Ruhum sende erişilmez bir hazine arıyor.

Byzas’ın bir kehanet uğruna kurduğu kadim şehir,

Kaderimin en eski sırrısın.

Hekate’nin meşalesi, gecelerimin en esrarlı aydınlığısın!

Sen İstanbul’sun!

Sultanahmet’in avlusunda uçuşan güvercinler kadar serazat,

Ayasofya’nın kubbesine sığınan dualar kadar mukaddessin.

Tenime değdiğin an içimde bin yıllık bir şehir uyanıyor.

Sabahları Boğaz’dan esen serin bir poyraz tazeliğindesin,

Boğaz’ın sularına düşen yakamozlar gözlerinin derinliklerinde can buluyor.

Ruhuma işleyen Zeyrek’in ahşap konaklarına sinmiş eski bir İstanbul kokusu,

Moda sahilinde gün batımını izlerken içimi ısıtan o derin huzursun,

Sen İstanbul’sun!

Her semtinde başka bir hatıra,

Her sokağında adının saklı olduğu bir gizemsin.

Yedikule’nin taşlarına sinmiş asırlık hatıralar gibi,

Dokunduğum her köşende tarihin izlerini taşıyorsun.

Valens’in kemerlerinden süzülürcesine ömrümün içinden sessizce akıp gidiyorsun.

Sen İstanbul’sun!

Galata’nın eski taş kulelerinde saklı bir sevda,

Göğe yükselen bakışlarında yeniden hayat buluyor.

Çemberlitaş’ın yüzyıllara meydan okuyan gövdesi gibi,

İçimdeki yerin zamana direniyor.

Topkapı Sarayı’nın ihtişamından ziyade,

Süleymaniye’nin o asil ve sessiz hüznünü yüzünde taşıyorsun.

Sen İstanbul’sun!

Fener’in eski kiliselerinde yankılanan çan seslerisin;

Ruhumun en derin yerinde çınlıyorsun.

Haliç’e bakan Pierre Loti hüznüdür gözlerindeki tarifsiz bekleyiş.

Karanlık mahzenlerde saklanan kadim sırlara inat,

Her bakışında başka bir âlem açılıyor.

Gülhane’nin asırlık ağaçlarında uyuyan zamansın;

Koynunda bütün hayatımı dinlendirmek istiyorum.

Haydarpaşa’da kavuşmayı bekleyen gönüllerin umudusun.

Sen İstanbul’sun!

Tarihî çeşmelerinden akan serin sulardan aziz,

Kapalıçarşı’nın kuytu dehlizlerinde saklı bir hazinesin.

Sen, iki kıtayı ayıran Boğaz değil,

İki ömrü birbirine bağlayan mukaddes köprüsün.

Kızıl bir akşamın engin sulara düşen son şavkı,

Yaşamımın en güzel yansımasısın.

Minarelerinden göğe yükselen ezanlarda adın düşüyor her sabah dualarıma.

Eyüp Sultan’da secdeye kapanan gönüllerin aradığı huzursun.

Sen İstanbul’sun!

Boğaz’ın derinliklerinde uyuyan bin yıllık bir sırsın,	

Çözemedikçe daha çok bağlanıyorum sana.

Yedi tepede yedi ayrı sevdasın,

Her hâlin başka bir yara açıyor ruhumda.

Adalar’dan esen o meltem ferahlığında bir nefessin,

İmparatorluklara başkent olmuş o kadim şehresin;

Kalbimde tek başına hüküm sürüyorsun.

Sen İstanbul’sun!

Sisler altında kaybolan bir masalsın.

Ey benim ömrümün en güzel coğrafyası!

Boğaziçi’nin serin rüzgârlarıyla göğsüme dolan en mukaddes nefesim,

Beyoğlu’nun eski kaldırımlarında yürür gibi adımlıyorum;

Çiçek Pasajı’nda kadehleri yudumlar gibi içiyorum seni,

Balat’ın rengârenk sokaklarında kaybolan bir çocukluk gibi, sende yitirdiğim kendimi arıyorum.

Uğruna şiirler yazılan, destanlar düzülen,

Ve ömrümün sonuna kadar sığınacağım tek limansın.

Kapılarına kazınmış kitabeler gibi hep aklımdasın.

Surlarında dalgalanan al bayrağın ruhusun.

Sen İstanbul’sun!

Bekir ERÇALIŞKAN 

13.11.2026

16:52', 'SEN İSTANBUL''SUN Ey... Gönlümün sultanı! İstanbul’un yedi tepesi gibi bir mihrap kurdun yüreğimde; Boğaz’ın gümüş sularına düşen akşam sisi ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Erçalışkan']::text[], 8.5, '{"poet":"Bekir Erçalışkan","poet_slug":"bekir-ercaliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/sen-istanbul-sun-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterim', 'i-sterim-kerim-yavuz-9cho1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mutluluk istedim çile verdilir

Sana mutlu olmak yasak dediler

Beni karanlığa mahküm ettiler

Ben de aydınlığı görmek isterim

Boynu bükük kaldım gözlerim gülmez

Gönül sarayımda fırtına dinmez

Çektiğim çileler bir türlü bitmez

Ben de herkes gibi gülmek isterim

Hayat yollarıma pusu kurdular

Beni yüreğimden atıp vurdular

Sevdiklerim bana düşman oldulan

Ben de bir gönüle girmek isterim

Tüketti gücümü çektiğim çile

Sanki senelere olmuşum köle

Her gün göz yaşlarım dönüşür sele

Ben de göz yaşımı silmek isterim

Sanki küle döndüm ben yana yana

Söyle zalim kader ne yaptım sana

Neden bu eziyet bu zülüm bana

Ben de mutluluğu dermek isterim', 'Mutluluk istedim çile verdilir Sana mutlu olmak yasak dediler Beni karanlığa mahküm ettiler Ben de aydınlığı görmek isterim Boynu bükük kald...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/isterim-309-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlarım', 'aglarim-kerim-yavuz-i5ofx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Haykırdım isyanımı inledi dağlar taşlar

Bahar gelmez yaz gelmez gönlümde kara kışlar

Yüreğim esir düştü gözümde kanlı yaşlar

Bir zalimin eline köle düştüm ağlarım

Tutup ta yüreğimi bulaştırmadım kine

Çilelerden bir türlü kurtulamadım yine

Kulak veren olmadı yüreğimin sesine

Kaderimle baş başa çöle düştüm ağlarım

Gülmedi bana kader acılarım dinmedi

Boyun büküp yaşamak yüreğime sinmedi

Kimse duygularımın kıymetini bilmedi

Deliye çıktı adım dile düştüm ağlarım', 'Haykırdım isyanımı inledi dağlar taşlar Bahar gelmez yaz gelmez gönlümde kara kışlar Yüreğim esir düştü gözümde kanlı yaşlar Bir zalimin eli...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aglarim-305-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Technologie et islam : le statut juridique des outils', 'technologie-et-islam-le-statut-juridique-des-outils-muhammed-ridvan-gizri-v8rlx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'L''un des principes les plus fondamentaux de l''islam, lorsqu''il s''agit de déterminer le statut d''une chose, est de considérer non pas son apparence ni son éventuel mésusage, mais l''équilibre global entre ses bienfaits et ses méfaits. Aujourd''hui, les débats autour d''outils technologiques tels que la télévision, le téléphone intelligent et l''intelligence artificielle négligent souvent ce principe et tombent dans l''erreur de qualifier ces outils directement de nuisibles ou d''illicites (haram). Or l''essence même du droit musulman classique est de juger les finalités et les méthodes, non les instruments.

Le droit islamique évalue un acte ou un objet selon sa nature propre et son but d''usage. En théorie des fondements du droit (uṣūl al-fiqh), la règle « al-umûr bi-maqâsidihâ » (les actes sont jugés selon leurs finalités) est la pierre angulaire de cette conception. Selon elle, tant qu''un outil ne produit pas directement et nécessairement, par lui-même, quelque chose d''illicite, il n''est pas possible de le déclarer haram. Le stylo en est l''exemple le plus simple. Un stylo reste le même stylo, qu''il serve à écrire le savoir ou à rédiger une calomnie. Il n''est en soi ni sacré ni satanique ; ce qui le rend l''un ou l''autre, c''est l''intention de la main qui le tient et la direction qu''elle lui donne. Le même raisonnement vaut pour la télévision, l''internet, le téléphone intelligent et l''intelligence artificielle.

Dans le fiqh classique, l''un des critères les plus solides pour décider si une chose est licite ou illicite est la prise en compte de l''équilibre entre utilité et nuisance (maslaha–mafsada). Si le préjudice potentiel d''une chose dépasse son utilité, elle peut être restreinte ; mais lorsque l''utilité l''emporte clairement, il n''est pas légitime de l''empêcher. Un médicament peut avoir des dizaines d''effets secondaires ; tant que ceux-ci ne le rendent pas plus dangereux que la maladie, l''interdire serait une erreur. Au contraire, l''utiliser à la bonne dose et pour la bonne indication est une responsabilité à la fois médicale et morale. La technologie doit être évaluée dans ce cadre : sans nier ses effets secondaires, et en tenant compte de son utilité sociale.

Il faut en outre souligner un point : certains outils, de par leur nature même, conduisent directement à l''illicite. Les machines de jeux d''argent, les instruments de sorcellerie et les ustensiles de consommation de stupéfiants entrent dans cette catégorie, car ces outils n''ont soit aucun usage légitime déterminant, soit une fonction première orientée vers le haram. La télévision, l''internet ou l''intelligence artificielle n''appartiennent pas à cette catégorie, car leur fonction première et prédominante est de transmettre l''information, de communiquer, d''apprendre et de produire. Le mésusage est secondaire et accidentel ; il n''est pas une nécessité inhérente à ces outils.

Le verset 32 de la sourate al-A''raf occupe une place déterminante dans cette discussion :

« Dis : Qui a interdit la parure qu''Allah a produite pour Ses serviteurs, ainsi que les bonnes nourritures ? Dis : Elles sont, dans la vie présente, pour ceux qui ont cru, et elles leur seront exclusivement réservées au Jour de la Résurrection. C''est ainsi que Nous exposons clairement les versets pour des gens qui savent. » (al-A''raf, 7/32)

Ce verset proclame clairement que les bienfaits qu''Allah a créés pour l''humanité sont, d''une manière générale, soumis au principe de la permission originelle (ibâha). Déclarer illicite un bienfait, un outil ou une possibilité sans preuve légitime est en contradiction directe avec ce verset. En effet, le verset situe l''épreuve non dans les outils, mais dans les choix et les intentions de l''être humain. La télévision, le téléphone intelligent et l''intelligence artificielle sont des bienfaits qui démocratisent l''accès au savoir accumulé par l''humanité, à l''art, à l''information médicale et à la capacité de communiquer. Les juger illicites sur la seule base d''un risque de mésusage va à l''encontre de l''esprit du verset.

Le verset 96 de la sourate as-Saffât déclare :

« Alors qu''Allah vous a créés, vous et ce que vous fabriquez. »

Ce verset exprime une vérité théologique très large : lorsque l''être humain produit, découvre ou invente, il n''est qu''un intermédiaire. Le véritable Créateur est Allah. L''ingénieur qui a découvert le transistor, le scientifique qui a conçu l''architecture de l''intelligence artificielle, le physicien qui a inventé la fibre optique : tous sont des instruments du décret et de la volonté d''Allah. De ce point de vue, la technologie n''est pas le fruit du hasard ; elle est le reflet de l''intelligence, de la curiosité et de la capacité de découverte qu''Allah a accordées à l''être humain. Rejeter la technologie reviendrait donc, en un sens, à rejeter la capacité qu''Allah a donnée à l''homme et les produits de cette capacité.

Le verset 188 de la sourate al-A''raf exprime les limites de l''être humain :

« Dis : Je ne détiens pour moi-même ni profit ni dommage, sauf ce qu''Allah veut. »

Le verset 51 de la sourate at-Tawba ajoute :

« Dis : Rien ne nous atteindra, sinon ce qu''Allah a prescrit pour nous. Il est notre Maître. Que les croyants placent donc leur confiance en Allah. »

Ces versets établissent la relation entre la volonté et les actes de l''être humain, d''une part, et la volonté divine, d''autre part. L''apparition de l''intelligence artificielle, la diffusion d''une connexion internet à toute l''humanité, le développement des algorithmes de traduction : tout cela s''est réalisé par la volonté d''Allah. Rejeter l''émergence de ces outils ou les assimiler au mal est, du point de vue de ces versets, une attitude incohérente.

En islam, la transmission du message (tabligh), c''est-à-dire faire parvenir le message d''Allah aux gens, est une responsabilité à la fois individuelle et collective. Le Coran déclare clairement que les messagers ont été envoyés à chaque peuple dans sa propre langue. Le verset 4 de la sourate Ibrâhîm montre combien le principe de lever la barrière linguistique et de rendre le message intelligible est fondamental pour la transmission.

Aujourd''hui, plus de 7 000 langues et des milliers de dialectes sont parlés dans le monde. Aucun être humain ne peut les connaître toutes, et aucune communauté de traducteurs ne peut les couvrir simultanément. La capacité de traitement des langues de l''intelligence artificielle ouvre précisément, à ce point, un espace où la responsabilité de la transmission rencontre la technologie. Les grands modèles de langage peuvent aujourd''hui comprendre, traduire et produire du contenu dans des centaines de langues. C''est une possibilité sans précédent dans l''histoire de l''islam. Un membre d''une tribu vivant dans les forêts d''Asie, un jeune du village le plus reculé d''Afrique, une petite communauté autochtone d''Amérique du Sud : chacun peut aujourd''hui, grâce à un système assisté par l''intelligence artificielle, accéder au message de l''islam dans sa langue maternelle. De plus, l''intelligence artificielle ne se contente pas de traduire : elle peut expliquer des concepts religieux complexes en fonction d''un niveau d''instruction donné, répondre à des questions et faire référence aux versets du Coran. Cette capacité ne supprime pas les méthodes traditionnelles de transmission ; au contraire, elle les renforce et en élargit la portée.

La télévision et les contenus vidéo numériques offrent eux aussi une possibilité unique pour la transmission du message. Les gens sont influencés de manière bien plus forte et durable par un récit visuel que par la lecture d''un texte. Les recherches en neurosciences montrent que le contenu audiovisuel reste beaucoup plus longtemps en mémoire que le texte. Un film ou un documentaire peut, en quelques heures, transmettre une profondeur émotionnelle qu''un livre de centaines de pages ne parvient pas à rendre. Cela peut à la fois consolider la foi des musulmans et, en faisant ressentir à des millions de personnes qui ne connaissent pas encore l''islam le lien profond de cette religion avec l''histoire de l''humanité, devenir un moyen de transmission. Ignorer ce potentiel, c''est comme poser à terre un outil puissant que l''on a entre les mains.

Un couteau coupe le pain, mais peut aussi blesser quelqu''un. Une voiture conduit à l''hôpital, mais peut aussi causer un accident. Un médicament soigne, mais une surdose peut tuer. Cette réalité ne nous oblige pas à interdire le couteau, la voiture ou le médicament ; elle rend nécessaires une culture de l''usage correct, une éducation et une réglementation. De même, la télévision comme l''intelligence artificielle portent un double potentiel. À la télévision, des contenus obscènes peuvent être diffusés ; sur ce même écran, on peut aussi dispenser un enseignement médical. L''intelligence artificielle peut être utilisée pour produire de la désinformation ; la même technologie peut aussi servir au diagnostic du cancer. Ce qu''il faut faire, ce n''est pas rejeter l''outil, mais construire le cadre éthique, l''éducation et le sens de la responsabilité qui orienteront l''outil dans la bonne direction.

Tout au long de l''histoire, les musulmans, plutôt que de rejeter les développements technologiques et intellectuels, les ont embrassés et y ont contribué. À l''âge d''or de la civilisation islamique, les travaux menés en mathématiques, en astronomie, en médecine, en chimie et en philosophie ont produit non seulement un savoir théorique, mais aussi des instruments pratiques. L''algèbre d''al-Khwârizmî, l''encyclopédie médicale d''Ibn Sînâ, les mesures géodésiques d''al-Bîrûnî : tout cela est le fruit du désir d''utiliser et de développer la technologie la plus avancée de leur époque. Qu''aujourd''hui les musulmans adoptent une attitude passive face à l''intelligence artificielle ou la rejettent est contraire à cette tradition enracinée. Au contraire, contribuer au développement de l''intelligence artificielle, à l''élaboration de son cadre éthique et à son utilisation en harmonie avec les valeurs islamiques est une responsabilité à la fois religieuse et civilisationnelle.

L''argument « cet outil peut être mal utilisé, donc il est dangereux » est un raisonnement incohérent en lui-même. Car si l''on suivait cette logique, l''éducation deviendrait haram (puisque le savoir peut aussi servir à fabriquer des armes), l''argent deviendrait haram (puisqu''il sert aussi à la corruption), le langage deviendrait haram (puisqu''il sert aussi à mentir). Il est évident qu''aucune de ces conclusions n''est acceptable. La possibilité d''un mésusage n''exige pas l''interdiction d''un outil ; elle exige son contrôle, l''éducation de ses utilisateurs et l''assumption de la responsabilité sociale. Le droit islamique a d''ailleurs adopté cette perspective : ce qui est haram, ce n''est pas l''outil, mais l''intention, l''acte et la méthode qui mènent à l''illicite.

Si l''on considère l''ensemble des arguments exposés ici, on parvient à la conclusion suivante : la télévision, le téléphone intelligent et l''intelligence artificielle ne peuvent être déclarés haram en eux-mêmes, dans le cadre des principes fondamentaux du Coran. Ces outils sont le produit de l''intelligence et de la capacité de découverte qu''Allah a accordées à l''humanité ; selon l''intention et la méthode de leurs utilisateurs, ils deviennent un moyen de bien ou de mal. Lorsqu''ils sont employés pour la transmission du message, le savoir, la justice et le service de l''humanité, ils ouvrent une grande porte de récompense. Dans le contexte du verset 96 d''as-Saffât, il convient de rappeler que Celui qui a créé ces outils est, en dernier ressort, Allah ; l''être humain n''en est que l''intermédiaire.

Aujourd''hui, la responsabilité des musulmans n''est pas de rejeter la technologie, mais de l''utiliser de manière juste, honnête et conforme aux valeurs humaines. Le potentiel de l''intelligence artificielle pour faire connaître l''islam au monde, traduire le Coran dans toutes les langues, corriger les malentendus sur la religion et ouvrir largement les portes du savoir constitue une opportunité très concrète et urgente. Saisir cette opportunité est une exigence du principe « amr bi''l-ma''rûf wa nahy ''ani''l-munkar » (ordonner le bien et interdire le blâmable).

Ce qui est erroné, ce n''est pas l''outil. Ce qui est erroné, c''est la direction, la voie, la méthode. Au lieu de laisser sécher l''encre du stylo, écrire les mots justes ; au lieu d''éteindre l''écran, diffuser les bons contenus ; au lieu de bloquer l''intelligence artificielle, l''utiliser pour la vérité et le bien : tel est le devoir du musulman de notre époque. Reconnaître les parures qu''Allah a créées et offertes à Ses serviteurs, Lui en être reconnaissant et les utiliser de la plus belle manière, voilà ce qu''exigent à la fois la raison et la foi.

« Dis : Qui a interdit la parure qu''Allah a produite pour Ses serviteurs, ainsi que les bonnes nourritures ? » (al-A''raf, 7/32)', 'L''un des principes les plus fondamentaux de l''islam, lorsqu''il s''agit de déterminer le statut d''une chose, est de considérer non pas son app...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/technologie-et-islam-le-statut-juridique-des-outils-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bükmem Boynumu', 'bukmem-boynumu-kerim-yavuz-ji8o1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Asla yaşayamam onsuz

Çiğnettirmem onurumu

Kalsam da çöller de susuz

Yine de bükmem boynumu

Yoldaşım olsa da çile

Göz yaşlarım dönse sele

Ateşler de yansam bile

Yine de bükmem boynumu

İşkenceler etseler de

Kılıç ile gelseler de 

Başımı isteseler de

Yine de bükmem boynumu

Zindanım olsa da her yer

Olsam da beterden beter

Kesse de yolumu kader 

Yine de bükmem boynumu', 'Asla yaşayamam onsuz Çiğnettirmem onurumu Kalsam da çöller de susuz Yine de bükmem boynumu Yoldaşım olsa da çile Göz yaşlarım dönse sele Ate...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bukmem-boynumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel Hediye', 'en-guzel-hediye-sinan-bayram-4az97', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevmek; bir insanın gözlerinde evini bulmaktır,

Uzakları yakın eden, mesafeleri tebessümle aşmaktır.

Hiçbir karşılık beklemeden, sırf var olduğu için,

Bir canı kendi canından öte tutabilmektir.

Sevmek; sessizliği paylaşabilmektir ansızın,

Birlikte susarken bile aynı şarkıyı duymaktır.

Gölgesinde serinlemek hayatın yorgunluğunun,

Bir avuç huzuru bir ömre sığdırabilmektir.

Ne bir hevesin peşinden koşmak, ne de geçici bir heves;

Sevmek, zamana meydan okuyan derin bir nefestir.

Gittiği yeri güzelleştiren, yüreğe sığmayan o duygu;

Hayatın insana verdiği en zarif, en güzel hediyedir.

Sinan Bayram', 'Sevmek; bir insanın gözlerinde evini bulmaktır, Uzakları yakın eden, mesafeleri tebessümle aşmaktır. Hiçbir karşılık beklemeden, sırf var ol...', ARRAY['Türk Edebiyatı','Şiir','Sinan Bayram']::text[], 8.5, '{"poet":"Sinan Bayram","poet_slug":"sinan-bayram","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/en-guzel-hediye-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat ile hasbihal', 'hayat-ile-hasbihal-mesut-karabulut-2-ofjw4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her notanın bir derdi vardır ya hani. Bir şarkı bazen bir ömür, bazense bir andır ya. Sırtındaki her heybenin yükünü taşıyamaz bazen sekiz nota, dokuz, on diye gider öyle bazen, gece kararırken hayatların karardığı gibi, doğan güneşe yüz sürmek için bekleyende olur. Yalnızlık sadece kader değildir bazen. Meydan dolusu kalabalıklarda karardır. Ne güneşin batışı ayın, nede ayın kayboluşu güneşin kaderidir. Kader, kederle hasbihal ettiği kadar kimle hem hal olurda huzur bulsun. Bazen bir çocuk gülümsemesi kadar güzel, bazen bir damla gözyaşı gördüğünde anlamsızdır hayat. Hasılı,, kadere düğüm atılıp, kedere düğüm tutulur bazen.', 'Her notanın bir derdi vardır ya hani. Bir şarkı bazen bir ömür, bazense bir andır ya. Sırtındaki her heybenin yükünü taşıyamaz bazen sekiz n...', ARRAY['Türk Edebiyatı','Şiir','Mesut Karabulut 2']::text[], 8.5, '{"poet":"Mesut Karabulut 2","poet_slug":"mesut-karabulut-2","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/hayat-ile-hasbihal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanç', 'i-nanc-kerim-yavuz-khf7q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Candan önce gelir vatan

Kör olur ona yan bakan

Milyanlarca yürektedir 

Bu toprak ta şehit yatan

Birlikte çıkar sesimiz

Dağ devirir nefesimiz

Verelim gönül gönüle

Hiç batmasın güneşimiz

Segi vardır özümüzde

Sevgi vardır sözümüzde

Kinin nefretin yalanın

Değeri yok gözümüzde

Yücedir gönül dağımız 

Kardeşliktir kan bağımız

Nağmertlere kan kusturur

İnanç kokan toprağımız', 'Candan önce gelir vatan Kör olur ona yan bakan Milyanlarca yürektedir  Bu toprak ta şehit yatan Birlikte çıkar sesimiz Dağ devirir nefesimiz...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/inanc-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Bitti', 'her-sey-bitti-kerim-yavuz-k4t9h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnız yıldızlar gibiyim Sevdiğim kız çekti gitti

Soğudum buzlar gibiyim Bitti işte herşey bitti

Sevdiğim kız çekti gitti

Doğarken battı güneşim Küllendi yanan ateşim

Teselli etme kardeşimBitti işte her şey bitti

Sevdiğik kız çekti gitti

Çekip gittiğiden beri Yandı kalbimin her yeri

Gitti artık dönmez geriBitti işte her şey bitti

Sevdiğim kız çekti gitti

Bu aşk bende kaldı yarım Ne tuzum kaldı ne tadım

Tükendi tüm umutlarım Bitti işte her şey bitti

Sevdiğim kız çekti gitti

Aşk zülüm eder mi cana Artık güneş doğmaz bana

Bilin ki bu aşktan yana Bitti işte her şey bitti

Sevdiğim kız çekti gitti

Gülmedi bana kaderim Artık şansım dönmez benim

Kalmadı aşka güvenim Bitti işte her şey bitti

Sevdiğim kız çekti gitti

Kar yağdı gönül bağıma Cevap yok aşka çağrıma 

Şimdi taş bastım bağrıma Bitti işte her şey bitti

Sevdiğim kız çekti gitti', 'Yalnız yıldızlar gibiyim Sevdiğim kız çekti gitti Soğudum buzlar gibiyim Bitti işte herşey bitti Sevdiğim kız çekti gitti Doğarken battı gün...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/her-sey-bitti-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Bıçak', 've-bicak-sair-zegan-soj5v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her şey ve huzur...

Hepsi üstüme geliyor,

Yol gibi çiğnenip eziliyorum,

Fark eden yok,

Merhamet yok.

Sesin gelmiyor.

Talih ve nasip...

Kapılar açılmıyor,

Acı gibi çiğneyip tükürüyorum,

Tadım yok,

Şansım yok.

Yüzün gülümsemiyor.

Söz ve şikayet...

Hepsi bana hakaret,

Dinledikçe ürküyorum.

Susan yok,

Muhatap yok.

Bana bağırıyor.

Güzel ve aşk...

Çok derin bakıyor,

Bir meyve gibi dalında.

Kalbim var,

Kelebekler var.

Çaresizce çırpınıyor.

Ceza ve kusur...

Sevmenin bir bedeli var,

İnsan sanki kaza yapıyor.

Suç yok,

Kasıt yok.

Ne yapsan acıtıyor.

                        Şair Zegan', 'Her şey ve huzur... Hepsi üstüme geliyor, Yol gibi çiğnenip eziliyorum, Fark eden yok, Merhamet yok. Sesin gelmiyor. Talih ve nasip... Kapıl...', ARRAY['Türk Edebiyatı','Şiir','Şair Zegan']::text[], 8.5, '{"poet":"Şair Zegan","poet_slug":"sair-zegan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ve-bicak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allégation de transmission du péché entre les générations', 'all-gation-de-transmission-du-p-ch-entre-les-g-n-rations-muhammed-ridvan-gizri-xrh6f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ces derniers temps, des notions telles que le « péché des ancêtres », la « malédiction lignagère » ou l''« extinction de la descendance par la malédiction » circulent de plus en plus sur les réseaux sociaux et dans certains milieux religieux. Le cœur de ces allégations est le suivant : le fait qu''un grand-père ait pratiqué l''usure, commis l''adultère ou maudit quelqu''un pourrait causer directement chez ses petits-enfants une maladie génétique, la stérilité ou une paralysie. Les défenseurs de ces thèses prétendent les fonder sur des versets du Coran.

Nous examinerons ici ces allégations de manière approfondie selon trois axes principaux :

1. L''invalidité de ces allégations au regard de la cohérence interne du Coran

2. Leur réfutation du point de vue de la biologie et de la génétique modernes

3. La dimension sociologique et économique : le mécanisme d''exploitation qui se cache derrière ce discours

LE REJET EXPLICITE PAR LE CORAN DE LA TRANSMISSION DU PÉCHÉ

Le principe de la responsabilité individuelle

L''un des piliers de la conception coranique de la morale et du droit est le principe de la responsabilité individuelle. Le verset 18 de la sourate Fâtir pose ce principe en termes très clairs :

> « Nul porteur ne portera le fardeau d''autrui. Et si celui dont la charge est lourde appelle quelqu''un à la porter, rien n''en sera porté, fût-ce par un proche parent. »

Ce verset est important à plusieurs égards. Premièrement, il énonce que le péché ne peut être transféré d''une personne à une autre. Deuxièmement, en soulignant que cette interdiction vaut même pour un « proche parent », il écarte le lien familial comme terrain d''exception. Troisièmement, le verset ne contient aucune condition ni aucune exception : l''interdiction est absolue.

Le verset 30 de la sourate Ash-Shûrâ rattache quant à lui la question à la relation entre l''acte individuel et sa conséquence :

> « Tout malheur qui vous atteint est dû à ce que vos mains ont accompli. Et Il pardonne beaucoup. »

Il est remarquable que le verset emploie l''expression « ce que vos mains ont accompli » et non « ce qu''ont accompli vos ancêtres ». Il rattache ainsi le malheur aux propres actes de l''individu, et non à quelqu''un situé dans la chaîne des ancêtres.

Le verset d''Al-Isrâ'' arraché à son contexte

Le verset 64 de la sourate Al-Isrâ'', auquel les tenants de ces allégations recourent fréquemment, est interprété comme signifiant que « Satan peut s''associer à la descendance des hommes ». Or cette interprétation n''est possible qu''en arrachant délibérément le verset à son contexte. La lecture conjointe des versets 63, 64 et 65 change le tableau :

> « Va-t''en ! Quiconque d''entre eux te suivra, la Géhenne sera votre rétribution, une rétribution complète. Excite par ta voix ceux d''entre eux que tu pourras, rassemble contre eux ta cavalerie et ton infanterie, associe-toi à eux dans les biens et les enfants, et fais-leur des promesses. Mais les promesses de Satan ne sont que tromperie. Tu n''auras aucun pouvoir sur Mes serviteurs. Et ton Seigneur suffit comme garant. »

Le verset 65 annule le pouvoir de Satan sur les serviteurs. L''expression « s''associer dans les biens et les enfants » signifie une influence morale, l''insinuation et l''incitation. On ne peut lui donner aucun sens d''intervention génétique directe ni d''extinction physique d''une lignée. Mettre en avant le seul verset 64 en occultant le verset 65 constitue donc à la fois une manipulation du point de vue du savoir et une trahison manifeste envers le lecteur.

La contradiction que révèle le récit de Job (Ayyoûb)

Dans le Coran, le prophète Ayyoûb est présenté comme frappé d''une maladie grave et d''une longue épreuve. Si l''on met le récit de Job en regard de la thèse de la « transmission du péché », une contradiction sérieuse apparaît : si toute maladie provenait du péché des ancêtres, la maladie de Job viendrait-elle, elle aussi, du péché de ses ancêtres ? Le Coran n''établit aucun lien de ce genre. Le récit de Job présente la maladie comme une épreuve, et non comme une punition ou une malédiction lignagère. Cela atteste, par l''exemple même des prophètes, que la conception coranique de la maladie est incompatible avec l''allégation de transmission du péché.

LES FAITS SCIENTIFIQUES ET LA JUSTE COMPRÉHENSION DE L''ÉPIGÉNÉTIQUE

Les mécanismes documentés des maladies génétiques

La génétique moderne a fourni l''explication moléculaire complète de nombreuses maladies héréditaires :

- Syndrome de Down : trisomie du chromosome 21 ; erreur aléatoire de ségrégation chromosomique survenant lors de la fécondation.

- Mucoviscidose : mutation récessive du gène CFTR situé sur le chromosome 7.

- Drépanocytose : substitution d''un seul nucléotide dans le gène HBB situé sur le chromosome 11.

- Myopathie de Duchenne : délétion du gène de la dystrophine sur le chromosome X.

Pour chacune de ces maladies, il est possible de démontrer par des tests de laboratoire quel gène, quel chromosome et quelle protéine sont touchés. Ces mécanismes n''entretiennent aucun lien biochimique, moléculaire ou statistique avec des actes moraux tels que l''usure, l''adultère ou la malédiction. Affirmer que « la génétique n''existe pas » ou que « la vraie cause est le péché des ancêtres » revient à rejeter l''ensemble de la biologie moderne, fondée sur des centaines de milliers d''observations, des milliers d''articles évalués par les pairs et des données cliniques.

Les limites de l''épigénétique et son interprétation erronée

L''épigénétique étudie les modifications de l''expression des gènes résultant de l''interaction de l''individu avec son environnement, et qui peuvent, dans certains cas, être transmises aux générations suivantes. Le tabac, l''alcool, le stress chronique, la malnutrition et l''exposition à des substances toxiques peuvent effectivement laisser des marques épigénétiques, dont certaines peuvent se transmettre d''une génération à l''autre. Il est toutefois indispensable de faire ici une distinction cruciale :

Le mécanisme d''une modification épigénétique est physique et chimique. Ainsi, le tabagisme d''une personne peut modifier le niveau de méthylation de certains gènes. En revanche, le fait de percevoir des intérêts ou de maudire quelqu''un ne laisse aucune trace moléculaire de cet ordre. Pour établir un lien causal entre un acte moral et un processus biochimique, il faudrait démontrer ce pont. Un tel pont n''existe ni dans la littérature scientifique ni dans le Coran.

L''inconsistance logique de l''allégation « malédiction-stérilité »

L''affirmation selon laquelle « lorsque le grand-père maudit, les petits-enfants ne peuvent pas avoir d''enfants » s''effondre devant quelques questions simples :

- Chaque personne qui ne peut pas avoir d''enfants a-t-elle réellement une malédiction dans ses ascendants ?

- Pourquoi toutes les personnes ayant reçu une malédiction ne deviennent-elles pas stériles ?

- Comment expliquer que, dans une même famille, l''un tombe malade et l''autre grandit en bonne santé ?

- Pourquoi les frères et sœurs de la personne maudite restent-ils si souvent parfaitement sains ?

Ces questions montrent que le modèle produit par les auteurs de ces allégations est dépourvu de toute force explicative cohérente. Une affirmation scientifique doit pouvoir être testée par l''observation et être réfutable. Le modèle de la « malédiction lignagère », qui explique chaque cas en le pliant à sa convenance, relève non de la science mais de la pseudo-science.

LA DIMENSION SOCIOLOGIQUE ET ÉCONOMIQUE : ANATOMIE D''UN MODÈLE D''EXPLOITATION

Le processus de construction du concept

La diffusion sociale de ce type de discours n''est pas le fruit du hasard ; elle obéit à une logique de marketing précise. On construit d''abord une peur théologique : « Le péché de tes ancêtres pèse sur toi. » On produit ensuite une solution spécifique à cette peur : des concepts originaux tels que « guérison lignagère », « thérapie du repentir » ou « solution de malédiction » sont mis sur le marché. Enfin, ces concepts sont proposés comme « services » payants. Ce modèle est une adaptation, en terrain islamique, de la conception chrétienne du baptême et de l''expiation par procuration. Or, comme les sociétés musulmanes ne croient pas à un rituel tel que le baptême, il devient nécessaire de produire de nouveaux concepts remplissant une fonction similaire.

Le public visé et ses points de vulnérabilité

Ce discours cible en particulier les personnes se trouvant dans les situations suivantes :

- Les familles dont un enfant souffre d''une maladie chronique

- Les couples qui n''arrivent pas à avoir d''enfant depuis longtemps

- Les individus qui trouvent absurdes leurs échecs économiques ou sociaux

Le point commun de ces personnes est qu''elles cherchent un sens à ce qu''elles vivent. La phrase « à cause du péché de ton grand-père » semble répondre à ce besoin : elle extériorise la faute tout en laissant entrouverte la porte d''une solution. Mais franchir cette porte est payant.

Séances et modèle économique

Des formules telles que « 5 séances de guérison lignagère » montrent clairement que ce discours n''est pas une simple interprétation théologique, mais un modèle commercial planifié. Lorsque le langage thérapeutique, la légitimité religieuse et la peur familiale sont réunis, il en résulte un outil de manipulation extrêmement puissant. Cette situation doit être considérée, au-delà d''un simple malentendu religieux, comme une escroquerie organisée qui exploite le désarroi des gens.

LA CONCEPTION CORANIQUE DE LA MALADIE ET DE L''ÉPREUVE

Le Coran envisage le monde dans un ordre de cause à effet. Dans cet ordre, la maladie peut apparaître sous plusieurs couches de sens :

Dimension de l''épreuve : il est annoncé que l''être humain sera éprouvé dans ses biens, sa vie, ses récoltes et ses proches (Al-Baqara, 155-157). La maladie peut être une forme de cette épreuve ; non pas une punition, mais un terrain de maturation.

Dimension de cause à effet : les comportements propres à la personne (tabac, alcool, mauvaise alimentation) peuvent conduire directement à des conséquences sur la santé. Le Coran l''englobe déjà ; l''expression « ce que vos mains ont accompli » y fait allusion.

Dimension du décret divin (qadar) : le Coran enseigne aussi que tout ne peut pas être imputé à une faute humaine. Le récit de Job en est l''exemple le plus clair.

Lorsque ces trois dimensions sont considérées ensemble, la thèse réductionniste selon laquelle « toute maladie provient nécessairement du péché d''un ancêtre » ne trouve aucune place à l''intérieur du Coran.

CONCLUSION

L''allégation de « transmission du péché entre les générations » est invalide sous quatre angles fondamentaux :

Premièrement, du point de vue du Coran : de nombreux versets, au premier rang desquels Fâtir 18 et Ash-Shûrâ 30, déclarent clairement que le péché ne peut être transféré d''une génération à l''autre. L''usage d''Al-Isrâ'' 64 arraché à son contexte est une manipulation du savoir.

Deuxièmement, du point de vue scientifique : les mécanismes des maladies génétiques sont documentés au niveau moléculaire. L''épigénétique est une réalité, mais elle recouvre des effets physiques et chimiques, non des actes moraux.

Troisièmement, du point de vue logique : l''allégation engendre des questions incohérentes, ne peut être testée par l''observation et se contredit elle-même.

Quatrièmement, du point de vue éthique : ce discours prépare un terrain d''exploitation systématique des familles ayant des enfants malades et des couples confrontés à l''infertilité.

En définitive, des notions telles que la « guérison lignagère » ou la « thérapie du repentir » ne concordent ni avec l''enseignement du Coran ni avec les données de la science. Ce sont des impostures commerciales qui instrumentalisent la souffrance et la sensibilité religieuse des gens, et qui doivent être rejetées aussi bien du point de vue théologique que médical et éthique.', 'Ces derniers temps, des notions telles que le « péché des ancêtres », la « malédiction lignagère » ou l''« extinction de la descendance par l...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/allegation-de-transmission-du-peche-entre-les-generations-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldırımlar Sessiz Bu Akşam', 'kaldirimlar-sessiz-bu-aksam-mustafa-kaynak-2-iycxr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine gecelere kaldım bu akşam,

Yürüyorum sessiz sokaklarda.

Sen evinde, ben uzak yollarda,

Yürüyorum yorgun kaldırımlarda.

Sokak lambaları susuyor,

Rüzgâr yüzüme dokunuyor.

Her köşede bir hatıran var,

Gölgen yanımda yürüyor.

Kaldırımlar sessiz bu akşam,

Yalnızlığım içimde büyüyor.

Bir ben varım, bir gölgen var,

Şarkımızı fısıldıyor rüzgâr.

Sessiz yollarda yürüyorum,

Kaybolan hayalini arıyorum.

Sen çok uzaklarda olsan da,

Sesini arıyorum sokaklarda.

Bir zamanlar gülüşün vardı,

O güzel anılar geride kaldı.

Ne gelen var artık, ne soran,

Issız sokakları ayrılık sardı.

Yağmur yağıyor, ıslanıyor saçlarım,

Sen uzaklardasın, hasretinle yanarım.

Seni arıyorum karanlık yollarda,

Gölgeni buldum sessiz sokaklarda.

Sabah olunca diner mi bu hüzün?

Yeniden güler mi yorgun yüzüm?

Belki bir gün biter bu hasret,

Baharda bir gün kavuşuruz elbet.

Kaldırımlar bana eşlik ediyor,

Yüreğim hâlâ seni bekliyor.

Sen çok uzaklarda olsan da,

Hatıralar yaşıyor bu sokaklarda.

Mustafa Kaynak', 'Yine gecelere kaldım bu akşam, Yürüyorum sessiz sokaklarda. Sen evinde, ben uzak yollarda, Yürüyorum yorgun kaldırımlarda. Sokak lambaları s...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kaynak 2']::text[], 8.5, '{"poet":"Mustafa Kaynak 2","poet_slug":"mustafa-kaynak-2","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kaldirimlar-sessiz-bu-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erir Yüce Dağın Karı', 'erir-yuce-dagin-kari-kerim-yavuz-aka6b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Erir yüce dağın karı

Çiçeklere konar arı

Bülbüller özler baharı

Ben de seni özlüyorum

Boyanır yeşile dağlar

Gönül ırmak gibi çağlar

Bulut çiçek için ağlar

Ben de sana ağlıyorum

Sevgisiz kalp neye yarar

Sevmekten korkacak ne var

Seven sevdiğini arar

Ben de seni arıyorum

Yüreğimin içi duru

Beslemez kini gururu

Topraklar bekler yağmuru 

Ben de seni bekliyorum', 'Erir yüce dağın karı Çiçeklere konar arı Bülbüller özler baharı Ben de seni özlüyorum Boyanır yeşile dağlar Gönül ırmak gibi çağlar Bulut çi...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/erir-yuce-dagin-kari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla', 'leyla-kerim-yavuz-7su8i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin loş ışığı vurunca pencereme

Uykularım kaçıyor anlamıyorsun Leylâ

Çoban yıldızı gibi doğuyorsun geceme

Duygularımı aşka yoramıyorsun Leylâ

Seni aşka çağrımın sanma gelecek sonu

Evet diyene kadar bitmeyecek bu konu

Bir kağıta yazıpta verdiğim telefonu

Haftalar aylar geçti aramıyorsun Leylâ

Sen çöllerde yağmurum sen hayat veren suyum

Sen gönlümün sultanı sensin benim gururum

Bil ki bu aşk uğruna tereddütsüz ölürüm

Gönül yarama deva olamıyorsun Leylâ

Gönülden sevmeyenler mutlu olmaz inanki

Gülsün seninde yüzün aşkın tadını var ki

Aşkı bilmeyenlerin esiri oldun sanki

Duygularını özgür bırakmıyorsun Leylâ

Biliyorsun bu aşkın kalbimde izi derin

Oysa bu aşktan yana hep susuyor dillerin

Pencerene her baktım kapalı perdelerin

Bir türlü gün yüzüne çıkamıyorsun Leylâ

Seni sevdim diyorum göğsümü gere gere

Kutsal kitap üstüne yemin ettim kaç kere

Sevmekten korkuyorsun hiç gereği yok yere

Karamsarlığa darbe yapamıyorsun Leylâ', 'Gecenin loş ışığı vurunca pencereme Uykularım kaçıyor anlamıyorsun Leylâ Çoban yıldızı gibi doğuyorsun geceme Duygularımı aşka yoramıyorsun ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/leyla-371-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilenler Gelsin', 'bilenler-gelsin-servet-bardak-lv22n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilenler Gelsin 

Bu dünya garibe dar ediliyor 

Sevgiyi saygıyı bilenler gelsin

Zalimler neşeyle içten gülüyor 

İnsanlık kitabı bilenler gelsin

.

Hayaller yeşersin hayattan yana 

Sevinçler şu neşe can versin cana

Hayatın sevinci yeterdir bana 

Yalansız dolansız gülenler gelsin

.

Yüreği deşenler türedi bir bir 

Her işin başında güzeldir tedbir 

Zalimin şu sesi çıkıyor hep gür

Saygıyla sevgiyle dolanlar gelsin

.

Serveti mutluluk belirmez yüzde 

Dürüstlük şu güven kalmıştır sözde 

Nice garibanın yüreği közde

Yüreğe su serpen bulanlar gelsin

.

17.11.2026

Servet BARDAK', 'Bilenler Gelsin  Bu dünya garibe dar ediliyor  Sevgiyi saygıyı bilenler gelsin Zalimler neşeyle içten gülüyor  İnsanlık kitabı bilenler gels...', ARRAY['Türk Edebiyatı','Şiir','Servet Bardak']::text[], 8.5, '{"poet":"Servet Bardak","poet_slug":"servet-bardak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bilenler-gelsin-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşer hayallerim', 'duser-hayallerim-servet-balibey-df5g8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşer hayallerim
Tane tane
gözlerimden 
Gider sevdiklerim
Umarsızca 
Çekip gider

Gitsin tüm rengarenk 
Senle dolu o anlarım
Gitsin Arzu dolu 
Bakışların duruşların
Gidiversin

Düşer anlam dolu
Sığındığım 
O anılar 


Gitme 
yemin ettim dönüp bakmam bir kez olsun
Gitme yemin ettim tüm bu sehir senin olsun
Senin olsun', 'Düşer hayallerim Tane tane gözlerimden  Gider sevdiklerim Umarsızca  Çekip gider Gitsin tüm rengarenk  Senle dolu o anlarım Gitsin Arzu dolu...', ARRAY['Türk Edebiyatı','Şiir','Servet Balıbey']::text[], 8.5, '{"poet":"Servet Balıbey","poet_slug":"servet-balibey","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/duser-hayallerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARIM KALAN BİR HİKÂYE', 'yarim-kalan-bi-r-hi-k-ye-yurekli-bir-kadin-95roj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben seni ne kal demeye zorlayabildim, Ne de gidişine alışabildim. Bir yanım hâlâ sana dönük, Bir yanım kırgınlığından kendini bile tanıyamaz hâlde.

Biz neydik, sen de bilmiyordun belki, Adını koyamadığın bir duygunun içinde kaybolduk. Ne tam anlamıyla birbirimize ait olduk, Ne de birbirimizden vazgeçebildik.

Sen gittin… Ama ardında yalnızca boş bir yer bırakmadın. Söylenmemiş sözler, yarım kalmış hayaller, Cevabını senden başka kimsenin veremeyeceği sorular bıraktın.

Biliyor musun, en çok neye kırgınım? Bir gün bitecek olmasına değil, Bir gün bu kadar yabancı olacağımızı Hiç düşünmeden sana kendimi açmış olmama…

Şimdi ne sana dönebiliyorum, Ne de senden tamamen uzaklaşabiliyorum. İçimde hâlâ seninle konuşan bir kadın var, Ama dışımda artık susmayı öğrenmiş bir kadın yaşıyor.

Belki bir gün ikimiz de başka hayatlarda, Başka insanlarla gülümseyeceğiz. Ama benim içimde bir hikâye kalacak; Ne başlangıcını unutabildiğim, Ne de sonunu anlayabildiğim…

Çünkü bazı insanlar giderken kapıyı kapatır, Ama ardında bir sürü açık cümle bırakır. Ve insan bazen birini özlediği için değil, Onunla yaşayamadığı ihtimallere veda edemediği için kalır.

Ben sana veda edemedim adam… Çünkü bizim hikâyemiz bitmedi belki, Sadece hiç yaşayamadığımız bir yerde Yarım kaldı…

— Yürekli bir kadın', 'Ben seni ne kal demeye zorlayabildim, Ne de gidişine alışabildim. Bir yanım hâlâ sana dönük, Bir yanım kırgınlığından kendini bile tanıyamaz...', ARRAY['Türk Edebiyatı','Şiir','Yürekli Bir Kadın']::text[], 8.5, '{"poet":"Yürekli Bir Kadın","poet_slug":"yurekli-bir-kadin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yarim-kalan-bir-hikaye-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Duygularım', 'benim-duygularim-kerim-yavuz-crfom', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bazen gama bürünüp bazende neşe ile

Bir ırmak gibi akan benim duygularımdır

İşledim cümleleri yüreğimin diliyle

Şiirle aşk yaşayan benim duygularımdır

Bazen bende işlerim ayrılığı derinden

Bazen mizah yazarım yürek oynar yerinden

Duygular damla damla düşüyor kalemimden

Kağıtlara çağlayan benim duygularımdır 

Hayat bir başka güzel baharıyla yazıyla

Her besteyi ahenkle çalar gönül sazıyla

Aşka kalpten susamış sevgili edasıyla

Yürekleri okşayan benim duygularımdır

Saldım duygularımı her biri bir gurbette

Benim ruhumu onlar taşıyorlar elbette

Her birinin hakkı var gönlümdeki servette

Şarkılarda ağlayan benim duygularımdır

Harcamıştım kendimi düşlerimin yolunda

Arzularım menzile ulaştı en sonunda

Şimdi görsünler beni mutluluğun kolunda

Başı sona bağlayan benim duygularımdır', 'Bazen gama bürünüp bazende neşe ile Bir ırmak gibi akan benim duygularımdır İşledim cümleleri yüreğimin diliyle Şiirle aşk yaşayan benim duy...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/benim-duygularim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gönül', 'deli-gonul-kerim-yavuz-qy9xe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Deli gönül bir güzele sevdalı

Bülbül olmuş etrafında dönüyor

Yar nazlanıp durur gönül yaralı

Duman olmuş baca gibi tütüyor

Deli gönül ahuzarda bu sene

Neden feryad fikan olsun sevene

Hadi güzel sen de sevmeyi dene

Etme güzel ömür kısa bitiyor

Gönül teli yanar durur aşk ile

Bülbül olmuş kanar dalda ki güle

Ne zaman bitecek çektiği çile

Deli gönül günden güne eriyor

Ahu gözlerine sürmüş kalemi

Sanki büyülemiş cümle alemi

Etme güzel deşme gönül yaremi

Deli gönül koro düşmüş yanıyor

Bir güzel peşinde olmuşum tazı

Gönül söz dinlese çekmem bu nazı

Yar sensin anlıma yazılan yazı

Gönül, bahçesinde seni bekliyor', 'Deli gönül bir güzele sevdalı Bülbül olmuş etrafında dönüyor Yar nazlanıp durur gönül yaralı Duman olmuş baca gibi tütüyor Deli gönül ahuzar...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/deli-gonul-395-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla Halimden', 'anla-halimden-kerim-yavuz-t4s6g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ardın sıra koşuyorum durmadan

Bilesin ki ismin düşmez dilimden

Geri dönmem kalbine ulaşmadan

Etme güzel etme anla halimden

Çiçekler olmadan yaşarmı arı

Söyle bülbül gülden kalırmı ayrı 

Dayanacak gücüm kalmadı gayrı

Etme güzel etme anla halimden

Ne olur yokuşum ulaşsa düze

İçimdeki bahar dönmese güze 

Çok ihtiyacım var bir tatlı söze

Etme güzel etme anla halimden

İste yüreğimi hemen vereyim

Sensiz mutluluğa nasıl ereyim

Ateşlere düştü deli yüreğim

Etme güzel etme anla halimden

Sensiz yaşamanın kalmadı tadı

Benim için sensin hayatın adı 

Az kaldı doluyor ömür miadı

Etme güzel etme anla halimden

Bir yol ver de yüreğine gireyim

Yüreğimi yüreğine sereyim

Sızlayıp duruyor gönül direğim

Etme güzel etme anla halimden', 'Ardın sıra koşuyorum durmadan Bilesin ki ismin düşmez dilimden Geri dönmem kalbine ulaşmadan Etme güzel etme anla halimden Çiçekler olmadan ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/anla-halimden-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıkta Yolumu Arıyorum', 'karanlikta-yolumu-ariyorum-mustafa-kaynak-2-x8075', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sessiz geceye düşmüş gibiyim,

Her yanım karanlık, ümitsizim.

Bir ışık arıyorum uzaklarda,

Kendi içimde kayıp gibiyim.

Karanlıkta yolumu arıyorum,

Bir çıkış yolu göremiyorum.

Yoruldu artık tüm hayallerim,

Kaybettim seni bulamıyorum.

Kimseler duymuyor sesimi,

Kimseler bilmiyor derdimi.

Bir umut ararken seni yollarda,

Yıldızlar kadar uzaklaştın bana.

Saçlarıma yağmur yağıyor,

İçimde fırtınalar kopuyor.

Karanlık çıkmaz sokaklar,

Önümde dağ gibi büyüyor.

Geceler uzun, sabah olmuyor,

Gözlerime bir türlü uyku dolmuyor.

Aklımda bin türlü düşünce var,

Hiçbiri derdime çare olmuyor.

Bir gün doğar mı bilmem güneşim,

Yeniden güler mi yorgun gözlerim?

Bir yol açılsa bana şu karanlıktan,

Belki yeniden yeşerir ümitlerim.

Yılların yükünü taşıdım içimde,

Söyleyemedim derdimi kimseye.

Gözlerim gülüyor görünse de,

Fırtınalar kopuyor yüreğimde.

Karanlıkta yolumu arıyorum,

Hâlâ senden bir ışık bekliyorum.

Ne kadar uzaklarda olsan da,

Sevdanla hayata tutunuyorum.

Mustafa Kaynak', 'Sessiz geceye düşmüş gibiyim, Her yanım karanlık, ümitsizim. Bir ışık arıyorum uzaklarda, Kendi içimde kayıp gibiyim. Karanlıkta yolumu arıy...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kaynak 2']::text[], 8.5, '{"poet":"Mustafa Kaynak 2","poet_slug":"mustafa-kaynak-2","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/karanlikta-yolumu-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Analyse scientifique et psychologique de l''allégation du « test du nazar » de Mücahid Cihad Han : anatomie d''un charlatanisme', 'analyse-scientifique-et-psychologique-de-l-all-gation-du-test-du-nazar-de-mucahid-cihad-han-anatomie-d-un-charlatanisme-muhammed-ridvan-gizri-ow98e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dans les domaines où le niveau de connaissances des sociétés est insuffisant, les charlatans ont toujours prospéré, d''hier à aujourd''hui. Ces figures exploitent les sensibilités religieuses, la curiosité métaphysique, la peur, le désarroi et, surtout, le manque de culture scientifique. La méthode de Mücahid Cihad Han, la « récitation de sourates sur un verre d''eau », en est un exemple contemporain.

L''allégation se résume ainsi : lorsqu''on récite à voix haute sur un verre d''eau la sourate Tebbet (Al-Masad), la sourate Al-Fatiha, ainsi que les sourates Al-Falaq et An-Nas, toute amertume ou tout changement de goût de l''eau serait la preuve que la personne est victime du « nazar » (mauvais œil).

Nous allons examiner cette allégation de façon systématique sous l''angle de la chimie, de la physique, de la psychologie et de la philosophie des sciences, démontrer pourquoi elle est fausse et mettre en lumière le fonctionnement de ce type de mécanismes de charlatanisme.

ÉVALUATION DE L''ALLÉGATION SOUS L''ANGLE DE LA PHILOSOPHIE DES SCIENCES

Le principe de réfutabilité

Pour qu''une affirmation soit considérée comme scientifiquement valide, elle doit satisfaire au principe de réfutabilité (falsifiabilité) formulé par Karl Popper. Autrement dit, elle doit pouvoir, en principe, être testée et réfutée.

À première vue, l''allégation de Mücahid Cihad Han semble testable : « Récite les sourates ; si l''eau devient amère, il y a du nazar. » Pourtant, elle est structurellement fallacieuse, car l''eau changera de goût en toute circonstance, que des sourates aient été récitées ou non. Cette méthode est donc un piège « qui se vérifie toujours ». En philosophie des sciences, on parle de proposition invérifiable : une construction qui paraît testable, mais qui peut interpréter tous les résultats en sa faveur.

Le rasoir d''Ockham

Le principe selon lequel « lorsque deux hypothèses expliquent le même phénomène, il faut préférer celle qui comporte le moins de présupposés » s''applique directement à cette allégation. Pour expliquer le changement de goût de l''eau, deux options existent :

- Hypothèse métaphysique : le nazar que porterait la personne se refléterait dans l''eau par l''intermédiaire des versets récités.

- Hypothèse physico-chimique : le souffle, la variation de température, l''absorption du CO₂ et le dégazage du chlore.

La seconde hypothèse explique entièrement le phénomène sans exiger la moindre hypothèse supplémentaire. En vertu du rasoir d''Ockham, il n''existe aucune raison valable d''adopter l''hypothèse métaphysique.

Le sophisme post hoc ergo propter hoc

Cette erreur logique classique, dont le nom latin signifie « après cela, donc à cause de cela », est au cœur de l''allégation. L''individu fait le raisonnement en chaîne suivant :

1. Les sourates ont été récitées.

2. Le goût de l''eau a changé.

3. Ce sont donc les sourates qui ont modifié le goût, et c''est la preuve du nazar.

Or, entre ces deux événements, il n''existe qu''une succession temporelle, et non un lien de causalité. Si, pendant le même laps de temps, on récitait un poème, on lisait à voix haute un article de journal ou l''on se contentait de souffler vers le verre sans rien dire, les processus chimiques se dérouleraient de la même manière et le goût changerait de la même façon.

LES PROCESSUS PHYSICO-CHIMIQUES QUI MODIFIENT LE GOÛT DE L''EAU

Absorption du dioxyde de carbone et formation d''acide carbonique

La proportion de CO₂ dans l''atmosphère est d''environ 0,04 %. En revanche, la proportion de CO₂ dans l''air expiré par les poumons humains se situe entre 4 % et 5 %, soit une concentration environ 100 fois supérieure à celle de l''air atmosphérique.

La consigne « récite à voix haute sur l''eau » oblige la personne à se pencher juste au-dessus du verre et à souffler directement, de façon prolongée, dans ce volume restreint. Cela augmente considérablement la concentration locale de CO₂ de l''air contenu dans le verre. Conformément à la loi de Henry, le CO₂ gazeux, sous pression partielle élevée, diffuse rapidement dans la phase liquide. La réaction chimique suivante se produit alors :

CO₂ + H₂O ⇌ H₂CO₃ (acide carbonique)

L''acide carbonique formé libère dans l''eau des protons (H⁺) et des ions bicarbonate (HCO₃⁻), ce qui abaisse le pH de l''eau. La langue humaine est sensible aux variations acides du pH et perçoit ce changement comme un goût aigre, légèrement amer, éventé ou piquant. Le souffle projeté directement dans le verre pendant une récitation intense et à voix haute accélère nettement ce processus d''acidification.

Le point crucial est le suivant : cet effet n''a absolument aucun rapport avec le contenu religieux du texte récité. Si n''importe quel autre texte avait été lu avec la même intensité et pendant la même durée, voire si l''on avait simplement soufflé de façon rythmée, la réaction chimique se serait déroulée de la même manière.

Micro-gouttelettes de salive et flore buccale

Pendant la parole à voix haute, en particulier lors de la prononciation de phonèmes riches en consonnes dures et en sons gutturaux, comme c''est le cas en arabe, des gouttelettes d''aérosol microscopiques sont projetées de la bouche du locuteur vers l''eau. Ces gouttelettes contiennent des enzymes digestives (amylase), des protéines, du mucus et divers composés organiques.

Le mélange de ces microparticules à l''eau modifie directement sa tension superficielle et sa composition chimique. Des recherches montrent que ce mécanisme peut entraîner un changement de goût encore plus rapide que l''effet d''acidification du CO₂. En somme, il est évident que ce qui modifie l''eau n''est pas le texte sacré, mais le propre matériel biologique du locuteur.

Dégazage du chlore

Dans les réseaux d''eau urbains, du chlore libre ou des chloramines sont utilisés à des fins de désinfection microbiologique. Le chlore confère à l''eau une vivacité caractéristique et un léger goût chimique légèrement amer.

Comme le chlore est volatil, lorsque l''eau est laissée dans un récipient ouvert, et plus encore lorsqu''elle est exposée au courant d''air créé par la parole et à l''énergie cinétique des ondes sonores, le chlore gazeux quitte rapidement la phase liquide pour se mêler à l''atmosphère. Avec le départ du chlore, le goût familier de « l''eau du robinet » change de façon marquée. L''eau peut sembler plus « fade », « différente » ou, pour certains, « amère » par rapport à son état initial.

Le charlatan fait aussi de ce processus naturel un élément de sa thèse : le changement de goût, c''est-à-dire le dégazage du chlore, est présenté comme un « signe de nazar ».

Variation de température et effet sur les récepteurs gustatifs

Les papilles gustatives de la langue humaine sont moins sensibles aux stimuli chimiques à basse température. Les mécanismes des récepteurs gustatifs, tels que les canaux TRPM5, s''engourdissent en partie au froid, ce qui relève le seuil de perception gustative. Dans l''eau bue froide, l''amertume naturelle de minéraux comme le magnésium, le calcium et les sulfates est masquée.

Or, pendant la durée du rituel, l''eau est laissée en attente et échange de la chaleur avec la température ambiante. De plus, le flux d''air expiré juste au-dessus du verre, à une température d''environ 35–36 °C, réchauffe activement la surface de l''eau. À mesure que l''eau se réchauffe, l''effet inhibiteur sur les récepteurs disparaît et le goût des minéraux déjà présents dans l''eau est perçu beaucoup plus nettement. Le sujet interprète ce changement thermique selon une chaîne causale erronée : « l''eau est devenue amère après la récitation des sourates ».

LES MÉCANISMES PSYCHOLOGIQUES

Les modifications physico-chimiques à elles seules ne suffiraient pas à rendre ce piège aussi efficace. Le véritable pouvoir de manipulation provient des failles cognitives de l''esprit humain.

L''effet d''attente (expectancy effect)

Lorsqu''on présente à l''individu, avant le rituel, la prémisse catégorique selon laquelle « s''il y a du nazar sur toi, le goût de cette eau deviendra amer », le cortex gustatif du cerveau passe en état d''alerte maximale. Le cerveau est désormais programmé en mode « recherche d''amertume ».

Une différence de goût microscopique, une variation de température ou un goût minéral auxquels l''individu ne prêterait normalement aucune attention deviennent soudain, sous l''effet de cette puissante suggestion, une donnée sensorielle considérable. Le cerveau active son mécanisme de perception sélective et étiquette comme « amer » un stimulus neutre.

Ce phénomène correspond exactement à l''effet nocebo en pharmacologie (une attente négative produisant des symptômes physiques négatifs). Le nocebo, contraire de l''effet placebo, est la transformation par le corps en expérience physiologique de la croyance de la personne selon laquelle son attente se réalisera dans un sens négatif.

L''apophénie (apophenia)

L''esprit humain a une forte tendance à trouver des motifs et des relations significatifs au sein de données aléatoires. L''apophénie, définie par le psychologue Klaus Conrad, est la tendance à établir des liens significatifs entre des faits sans rapport.

Ce mécanisme constitue le terrain cognitif le plus fertile pour le charlatanisme. L''individu, bien qu''il n''existe aucun lien de causalité entre le changement de goût de l''eau et la notion de « nazar », interprète ces deux événements comme étant dans une relation significative. La cause n''en est pas que l''eau soit véritablement ensorcelée, mais la nature humaine, en quête de sens.

Modification du seuil de perception et attention sélective

Lorsque l''attention se concentre sur un stimulus sensoriel précis, le cerveau commence à traiter plus intensément les signaux relatifs à ce stimulus. Un individu qui entre dans le cadre « ressens l''amertume » classe immédiatement comme « anormal » et « amer » le moindre goût minéral, résidu de chlore ou écart de température qu''il aurait autrement laissé passer comme neutre. Il s''agit d''un phénomène d''attention sélective et de modification du seuil de perception, bien documenté en psychologie clinique. Le charlatanisme exploite cette faille avec habileté.

RÉFUTATION EXPÉRIMENTALE — PROTOCOLE DE TEST À L''AVEUGLE

La manière la plus convaincante de prouver que l''allégation repose sur des fondements physiques et psychologiques, et non métaphysiques, est de la soumettre à une expérience scientifique contrôlée et reproductible. Un protocole de test en double aveugle conçu à cet effet est présenté ci-dessous.

Conception de l''expérience

On prépare trois verres en verre identiques, remplis d''eau de la même source, à volume et température égaux :

- Verre X (expérience active) : les sourates concernées sont récitées à voix haute.

- Verre Y (contrôle placebo) : pendant la même durée, à la même distance, on lit un texte ordinaire (poème, article de journal) ou l''on se contente de souffler de façon rythmée.

- Verre Z (contrôle naturel) : aucune intervention n''est effectuée ; on le laisse simplement à l''air libre pendant la même durée.

Un chercheur indépendant mélange ensuite les verres et colle sous chacun un code aléatoire. Ni la personne qui effectue la récitation ni le sujet qui effectuera le test de dégustation ne savent quel verre correspond à quoi. Le sujet goûte les eaux et doit choisir celle qui est « la plus amère » ou dont « le goût a le plus changé ».

Résultat attendu

Si cette expérience est répétée des centaines de fois, le taux de choix du verre X (l''eau sur laquelle les sourates ont été récitées) par le sujet ne dépassera pas, statistiquement, le seuil de hasard de 33,3 %. Le sujet rapportera tout aussi fréquemment le verre Y ou le verre Z comme « devenu amer ».

Ce résultat prouve mathématiquement que le changement de goût ne présente aucune corrélation avec le contenu religieux du texte récité. L''unique source du changement réside dans les processus physico-chimiques qui se produisent de manière égale dans les trois verres.

Reproductibilité universelle de la méthode

Si l''allégation reposait sur un véritable fondement métaphysique, l''effet devrait disparaître lorsqu''un autre texte est récité à la place des sourates. Or le même changement de goût s''observera également dans les conditions suivantes :

- lorsqu''un texte non religieux quelconque est lu ;

- lorsqu''on se contente de souffler de façon rythmée ;

- lorsque l''eau est laissée à l''air libre sans y toucher (plus lentement, mais dans le même sens).

Cette reproductibilité universelle réfute entièrement le fondement de l''allégation.

ANATOMIE DU MÉCANISME DU CHARLATANISME

Le modèle classique du charlatanisme

La stratégie appliquée par Mücahid Cihad Han et ses semblables correspond exactement au modèle classique du charlatanisme étudié depuis des siècles dans la littérature médicale et la psychologie sociale :

Première étape : on choisit un processus naturel inévitable, qui se produira en toutes circonstances. Ici, ce processus est l''acidification, le réchauffement et le dégazage du chlore de l''eau laissée dans un récipient ouvert.

Deuxième étape : ce processus entièrement naturel est emballé dans un rituel religieux ou mystique. L''attitude grave et autoritaire qui accompagne la récitation à voix haute de sourates soigneusement choisies suscite chez les spectateurs admiration et confiance.

Troisième étape : en exploitant les sensibilités religieuses, le manque de connaissances et le désarroi du public visé, le résultat naturel obtenu est présenté comme une méthode de diagnostic métaphysique.

Quatrième étape : ce faux mécanisme de diagnostic ouvre la plupart du temps la porte à une exploitation commerciale : frais de séance, amulettes, eau « bénie par des prières », rituels spéciaux.

Pourquoi est-ce aussi convaincant ?

Plusieurs raisons fondamentales expliquent la force de cette méthode de charlatanisme.

Premièrement, le piège est inévitable. La méthode présente comme « preuve » un changement physique qui se produira quoi qu''on fasse. Si le patient trouve l''eau « amère », il y a du nazar ; s''il ne la trouve pas amère, il n''y en a pas, ou bien la personne n''a pas goûté avec assez d''attention. Tous les résultats peuvent être intégrés au système.

Deuxièmement, un bouclier de légitimité religieuse est utilisé. L''emploi de textes sacrés comme instrument rend la critique difficile. Lorsque la personne remet la méthode en question, les sensibilités religieuses entrent en jeu et empêchent une évaluation rationnelle.

Troisièmement, le public visé est le plus souvent composé d''individus déjà anxieux et en quête de solutions. L''effet nocebo fonctionne extrêmement bien sur ce terrain ; l''esprit, qui s''attend déjà à un problème, est prêt à trouver des « preuves ».

Le préjudice social

Au-delà du préjudice individuel, ces pratiques ont aussi un coût social. Le renforcement de la superstition au détriment de l''esprit critique et de la culture scientifique prépare le terrain au recours à de fausses méthodes plutôt qu''à une aide professionnelle pour les problèmes de santé. Outre l''exploitation financière, elles conduisent les individus à mal cadrer leurs véritables problèmes psychologiques ou médicaux sous l''étiquette de « nazar ».

CONCLUSION

L''allégation du « test du nazar par la récitation de sourates sur un verre d''eau » avancée par Mücahid Cihad Han, examinée de façon approfondie sous l''angle de la chimie, de la physique, de la psychologie et de la philosophie des sciences, ne laisse subsister aucun élément métaphysique.

Le changement de goût de l''eau est expliqué de manière exhaustive par l''absorption du CO₂ et la formation d''acide carbonique, par les gouttelettes d''aérosol qui se mêlent à l''eau pendant la parole, par le dégazage du chlore, par l''activation des récepteurs gustatifs avec le réchauffement, ainsi que par de puissants mécanismes cognitifs tels que l''effet d''attente et l''apophénie.

Aucun de ces processus ne dépend du contenu du texte récité. Le même effet peut être obtenu avec un poème, un article de journal, des sons dépourvus de sens, ou simplement en soufflant quelques minutes vers le verre. Ce constat ne représente pas tant une réfutation scientifique de l''allégation qu''il ne démontre qu''elle n''a jamais été scientifique dès l''origine.

La véritable question est la suivante : cette méthode représente la forme la plus raffinée du charlatanisme, car ce qu''elle exploite n''est pas l''ignorance des gens, mais la structure cognitive universelle de l''être humain, qui cherche du sens, détecte des motifs et mêle ses croyances à la réalité. C''est pourquoi le bouclier le plus solide contre de telles allégations est l''esprit critique et la culture scientifique, capables de distinguer la religion des pratiques pseudo-religieuses.', 'Dans les domaines où le niveau de connaissances des sociétés est insuffisant, les charlatans ont toujours prospéré, d''hier à aujourd''hui. Ce...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/analyse-scientifique-et-psychologique-de-l-allegation-du-test-du-nazar-de-mucahid-cihad-han-anatomie-d-un-charlatanisme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Güzel', 'gel-guzel-kerim-yavuz-e3tcj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerim parlıyor seni görende

Yüreğinden kini at da gel güzel

Bekliyorum seni ben bu bedende

Açtım kollarımı koş da gel güzel

Kamçılıyor beni ılık nefesin

Titrer damarlarım sen bir afetsin

Ben mecnuna döndüm bunu bilesin

Hadi sen de Leylâ ol da gel güzel

Gel aşk çınarına sarıl belinden

Sen de payını al duygu selinden

Düşeyim ahenkle gönül telinden

Aşkı yüreğinden çal da gel güzel

Mahçup duruşuma aldanma sakın

Artık yüreğime yakın dur yakın

Sende aşka göre bir tavır takın

Saçına gülleri tak da gel güzel', 'Gözlerim parlıyor seni görende Yüreğinden kini at da gel güzel Bekliyorum seni ben bu bedende Açtım kollarımı koş da gel güzel Kamçılıyor be...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-guzel-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Güle Güle', 'git-gule-gule-kerim-yavuz-a0t7q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Demek ki bu aşka noktayı koydun 

Seven yüreğimi yaktın dil ile

Sonunda aşkımı hiçe mi saydın?

Peki öyle olsun git güle güle

Dünya da en kutsal duygudur sevmek

Heba oldu aşka verdiğim emek

Bizim kaderimiz böyleymiş demek

Peki öyle olsun git güle güle

Buruk bir üzüntü sardı sinemi

Aşkmıydı çektiğim yoksa çilemi

Senelerin aşkı bitti öylemi

Peki öyle olsun git güle güle

Yakardım uğruna ben bu bedeni

Belki de hor gördün candan seveni 

Demek ki kalbinden silmişsin beni

Peki öyle olsun git güle güle

Bilmelisin bu aşk kalbim de kordu

Bakışların bana sevdim diyordu

Böyle mi olması gerekiyordu?

Peki öyle olsun git güle güle', 'Demek ki bu aşka noktayı koydun  Seven yüreğimi yaktın dil ile Sonunda aşkımı hiçe mi saydın? Peki öyle olsun git güle güle Dünya da en kuts...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/git-gule-gule-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaradanur insanur cenurunet(cennet)', 'yaradanur-insanur-cenurunet-cennet-sedat-hunker-pwe9f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaradanur insanuru cenurunette(cennette) yaratır

İnsanur ben dünyada nasıl yaratılcam der

Yaradanur hızırla doğlarım der

Yaradanur insanuru cenurunette(cennette) yaratır

İnsanur ben dünyada nasıl çokluk bulcam der

Yaradanur hızırla çoğlarım der

Yaradanur insanuru cenurunette(cennette) yaratır

İnsanur ben dünyada yürek yanarsam ne olacak der

Yaradanur hızırla soğlarım der

Yaradanur insanuru cenurunette(cennette) yaratır

İnsanur ben dünyada hastalanırsam ne olacak der

Yaradanur hızırla yoğlarım der

Yaradanur insanuru cenurunette(cennette) yaratır

İnsanur ben dünyada işsiz kalırsam ne olacak der

Yaradanur hızırla sağlarım der

Yaradanur insanuru cenurunette(cennette) yaratır

İnsanur ben dünyada yaralanırsam ne olacak der

Yaradanur hızırla bağlarım der

Yaradanur insanuru cenurunette(cennette) yaratır

İnsanur ben dünyada yağmursuz kalırsam ne olacak der

Yaradanur hızırla yağlarım der

Kara mecnun

Hızırnur', 'Yaradanur insanuru cenurunette(cennette) yaratır İnsanur ben dünyada nasıl yaratılcam der Yaradanur hızırla doğlarım der Yaradanur insanuru ...', ARRAY['Türk Edebiyatı','Şiir','Sedat Hünker']::text[], 8.5, '{"poet":"Sedat Hünker","poet_slug":"sedat-hunker","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yaradanur-insanur-cenurunet-cennet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'L Lodos!', 'l-lodos-huseyin-varyeter-qch5o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Burada,

Kara bulutlara kadar,

Göğe uzanıyor ağaçlar.

Lodos,

Kızmış gibi herşeye,

Gece gece,

Hırsını alıyor...

Kalmayacak sanki,

Uğramadığı  bir ağaç...

Orman,

Sessiz karanlık.

Sanki,

Bütün ağaçlar,

Sırasını bekliyor...

Hayvanları,

Bir yerlere saklanmış!

Ezan okunurken,

Sesleri gelen,

Çakallar bile yok?

Her şey sus pus,

Ne gece ne de lodos.!

Israr ediyor...

Gece uzun,

Lodos kızgın!

Sessizlik,

Geceyi sarıyor ..!

Sanırım hepsi,

Şiddetle, 

Yağmuru bekliyor!...

17.Kasım.2026

07:38 Salı

Muradiyesarnıç/Mustafakemalpaşa', 'Burada, Kara bulutlara kadar, Göğe uzanıyor ağaçlar. Lodos, Kızmış gibi herşeye, Gece gece, Hırsını alıyor... Kalmayacak sanki, Uğramadığı  ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Varyeter']::text[], 8.5, '{"poet":"Hüseyin Varyeter","poet_slug":"huseyin-varyeter","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/l-lodos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalın Sazımı', 'calin-sazimi-kerim-yavuz-jby46', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnızlıktan usanmasın

Çalın sazımı sazımı

Tellerine pas vurmasın 

Çalın sazımı sazımı

Taht kurmuştur gönüllerde

Aranır gurbet ellerde

Bayramlarda düğünlerde

Çalın sazımı sazımı

Haksız olanları yersin

O da muradına ersin

Türkülere hayat versin 

Çalın sazımı sazımı

Kültürümüzün özüdür

Sevenin gönül gözüdür

Hayatın gerçek yüzüdür

Çalın sazımı sazımı', 'Yalnızlıktan usanmasın Çalın sazımı sazımı Tellerine pas vurmasın  Çalın sazımı sazımı Taht kurmuştur gönüllerde Aranır gurbet ellerde Bayra...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/calin-sazimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Unutmadım', 'ben-unutmadim-fahri-bulut-90jha', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BEN UNUTMADIM

Bir derdime bin dert katan en güzel,

Dertliye acımak sende ne gezer,

Oğrun bakışların bağrımı ezer,

Seni bilmem ama ben unutmadım.

Bağladın gönlümü zülfün teline,

Canı kurban ettin tatlı diline,

Ellerim bağladın ince beline,

Seni bilmem ama ben unutmadım.

Kalbimin içinde saklısın derdin,

El basıp sol yana yeminler verdin,

Yüzümü sinenin üssüne serdin,

Seni bilmem ama ben unutmadım.

Rızazade, güne ay, yıl eklerim,

Tüketmem sabrımı sabır ekerim

Gelin diye zil sesini beklerim,

Seni bilmem ama ben unutmadım.

17.11.2026

Fahri Bulut Rızazade Gaziantep akşamları…', 'BEN UNUTMADIM Bir derdime bin dert katan en güzel, Dertliye acımak sende ne gezer, Oğrun bakışların bağrımı ezer, Seni bilmem ama ben unutma...', ARRAY['Türk Edebiyatı','Şiir','Fahri Bulut']::text[], 8.5, '{"poet":"Fahri Bulut","poet_slug":"fahri-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ben-unutmadim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşın İçindeki Çığlık', 'tasin-i-cindeki-ciglik-seyrani-gol-4wies', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İçimde, kimsenin ayak basmadığı eski bir çağ var.

Duvarlarında asırlık bir sessizlik uyuyor.

Bir çiçeğin kokusunda ne çok ölüm saklı,

Unutulmuş dualara ne çok günah sinmiş.

Diğer bir gül, karanlıkta çürürken

bütün dikenleriyle dua ediyor.

Ve ben, o duanın hangi kelimesinde

insan olmaktan vazgeçtiğimi bilmiyorum.

Kör kuyuların dibinde bir su uyuyor;

rengi, dibe çökmüş günahların tortusu.

Üzerinde aylar değil,

yüzyıllardır ağlayan bir gökyüzü var.

Bir vakitler kutsal sayılan ne varsa

şimdi küf tutmuş bir hatıradan ibaret.

Mermerin alnında derin bir çatlak,

çatlağın içinde kıpırtısız bir sonsuzluk.

Bazen gecenin en eski yerinden

ince bir fısıltı yükseliyor.

Sanki ölüler, kefenlerinin içinden

yarım bıraktıkları düşleri çağırıyor.

Ne garip;

toprak bile sakladığı sırdan yorulmuş,

kökler karanlığa doğru büyüyor,

çiçekler ışığı görmeden soluyor.

Sabah gelmiyor artık.

Yalnızca gecenin rengi değişiyor

ve duvarlarda biraz daha derinleşiyor rutubet.

Bütün ömrümüz,

unutulmuş bir mezarın üzerinde

açmayı unutmuş bir çiçek sanki.

Ve bir gün, bütün aynalar kararacak;

yüzümüzü değil, içimizde çürüyen zamanı gösterecek.

O vakit hangi duaya sığınır insan,

kendi ruhu bile kendisine yabancıysa?

S.GÖL', 'İçimde, kimsenin ayak basmadığı eski bir çağ var. Duvarlarında asırlık bir sessizlik uyuyor. Bir çiçeğin kokusunda ne çok ölüm saklı, Unutul...', ARRAY['Türk Edebiyatı','Şiir','Seyrani Göl']::text[], 8.5, '{"poet":"Seyrani Göl","poet_slug":"seyrani-gol","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/tasin-icindeki-ciglik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban', 'kurban-kerim-yavuz-s4phu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özü sevgi kokan ey Anadolu.

Senin lisanına diline kurban

Yüreğinden geçer mutluluk yolu

Senin kasabana iline kurban

Veririz uğruna canlarımızı

Kutsal biliyoruz toprağımızı

Cılgına çevirir bayrağımızı

Senin rüzgarına yeline kurban

İzi vardır sende geçmiş her çağın

Nice kültürlerle dolmuş kucağın

Buram buram çiçek açar toprağın

Senin sümbülüne gülüne kurban

Dağılır semaya özgürce sesin

Düşmanına karşı gürler nefesin

Her zerrene kadar içimizdesin

Senin çamuruna çölüne kurban

Yanık türkülerin dağları deler

Çayır çimeninde kuzular meler

Derin sularında yüzer gemiler

Senin denizine gölüne kurban', 'Özü sevgi kokan ey Anadolu. Senin lisanına diline kurban Yüreğinden geçer mutluluk yolu Senin kasabana iline kurban Veririz uğruna canlarımı...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kurban-261-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükenmeyen Sevda', 'tukenmeyen-sevda-oktay-i-lcek-uiac8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mümkün değil bitirmek, zannetme ki elimde

Yüreğimde bu sevda, hiç durmadan coşuyor

Gönlüm unutur sanma, adın her an dilimde

Sana olan sevgiyle, hep peşinde koşuyor

Mutlulukla dolardım, yanımda olduğunda

İçmeden mest eylerdin, yüzüme güldüğünde

Hatıralar canlanıp, aklıma geldiğinde

Bağrımdaki bu yangın, şol dağları aşıyor

Kalbim senin sevgine, susamış çöller gibi

Sevdan her şeyden tatlı, bilesin ballar gibi

İnan bu aşk bendini, hep aşan seller gibi

Sığmayıp hiçbir yere, yüreğimden taşıyor

Düşünmem yokluğunu, seni anarım her gün

Nasıl da hoş olurum, beni sarınca övgün

Derviş der hiçbir zaman, tükenmeyen bu sevgin

Şu biçare kalbimde, hiç ölmeden yaşıyor

Oktay İlcek

15.11.2026', 'Mümkün değil bitirmek, zannetme ki elimde Yüreğimde bu sevda, hiç durmadan coşuyor Gönlüm unutur sanma, adın her an dilimde Sana olan sevgiy...', ARRAY['Türk Edebiyatı','Şiir','Oktay İlcek']::text[], 8.5, '{"poet":"Oktay İlcek","poet_slug":"oktay-i-lcek","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/tukenmeyen-sevda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tozlu Albümde Kaldı Hatıralar', 'tozlu-albumde-kaldi-hatiralar-mustafa-kaynak-2-rv60b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eski bir fotoğrafın düştü elime,

Bir zamanlar mutluyduk birlikte.

Yıllar geçti, soldu bütün renkler,

Geçmişte kaldı o gülen gözler.

Gençlik yıllarım geldi aklıma,

Bir başka güzeldi seninle bahar.

Sana söyleyemedim içimdeki aşkı,

Sessizce geçti mevsimler, yıllar.

Tozlu albümde kaldı hatıralar,

Birer birer soldu tüm sevdalar.

Ne sen geri geldin, ne o yıllar,

İçimde hâlâ yaşıyor taze baharlar.

Bir şarkı çalsa seni hatırlarım,

Her akşam geçmişe dalarım.

Gözlerimi kapatıp seni anarım,

Her gece hasretinle yanarım.

Belki kaderin yazısı böyleydi,

Bu aşk yaşanmadan sona erdi.

Sana ulaşmak mümkün değildi,

Benimkisi çocukça bir hayaldi.

Zamanı geri alsam seninle,

Tekrar o günlere dönsek birlikte.

Sana söylemek istediğim sözleri,

Gözlerine bakıp söylesem sessizce.

Tozlu fotoğraflar sararmış,

O yıllar uzaklarda kalmış.

Ne kadar özlesem de seni,

Hatıralar geçmişte kalmış.

Ah, nerede o güzel günler,

Nereye kayboldu eski hayaller?

Yıllarca seni bekledim yollarda,

Bir ömür geçti, dönmedin bana.

Mustafa Kaynak', 'Eski bir fotoğrafın düştü elime, Bir zamanlar mutluyduk birlikte. Yıllar geçti, soldu bütün renkler, Geçmişte kaldı o gülen gözler. Gençlik ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kaynak 2']::text[], 8.5, '{"poet":"Mustafa Kaynak 2","poet_slug":"mustafa-kaynak-2","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/tozlu-albumde-kaldi-hatiralar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Comprendre Said Nursi : une lecture entre sacralisation et dénigrement', 'comprendre-said-nursi-une-lecture-entre-sacralisation-et-d-nigrement-muhammed-ridvan-gizri-yqnz4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dans l''histoire religieuse et intellectuelle de la Turquie, il est difficile de trouver une autre figure aussi débattue que Said Nursi, à la fois exaltée à l''excès et injustement vilipendée. Une partie de ses partisans l''a élevé presque au rang de prophète ou de saint suprême (velayet), traitant ses paroles et ses œuvres comme des textes sacrés qu''il serait interdit de questionner. À l''inverse, une autre partie a brandi comme un sabre certaines questions relevant de l''ijtihad dans les Risâle (les « Épîtres de la Lumière ») pour s''attaquer directement à sa personne, à ses intentions et à sa moralité. Fait surprenant, ces deux attitudes contredisent directement les textes que Said Nursi a lui-même écrits. En plaçant cette contradiction au centre, nous tenterons de répondre à trois questions : que dit Said Nursi de sa propre faillibilité ? D''où vient l''attitude de sacralisation qui ignore cette faillibilité ? Et où se situe l''erreur méthodologique des campagnes de dénigrement qui font de cette faillibilité une arme ?

Dans ses propres mots : « Moi aussi, je peux être un corrupteur »

Pour tout penseur ou guide religieux, l''épreuve la plus honnête consiste à examiner ses propres paroles. Said Nursi s''y prête avec une grande ouverture. Les lignes suivantes des Münâzarât sont à cet égard remarquables :

> « Aucun corrupteur (müfsid) ne dit : "Je suis un corrupteur." Il apparaît toujours sous les traits de la vérité, ou bien il tient le faux pour le vrai… Même ma parole, ne l''acceptez pas en bloc par bonne opinion (hüsn-ü zan) du simple fait que c''est moi qui l''ai prononcée. Peut-être suis-je moi aussi un corrupteur. Ou bien je corromps sans le savoir. »

Ces phrases ne relèvent pas d''une simple humilité de convenance. Said Nursi formule ici un avertissement épistémique systématique : la parole de quiconque, quel qu''il soit, ne doit pas être tenue pour vraie du seul fait de son auteur. La pierre de touche, c''est-à-dire le critère, n''est pas la personne mais le Coran. Si la parole se révèle or, qu''on la garde dans son cœur ; si elle se révèle cuivre, qu''on la renvoie. Dans le Barla Lahikası, l''expression est plus nette encore :

> « Mes chers frères, votre maître n''est pas lâyuhtî (infaillible). Le croire exempt d''erreur est une erreur. »

Le mot « lâyuhtî » signifie précisément, en arabe, « infaillible, qui ne commet pas d''erreur ». Said Nursi a d''abord défini ce concept, puis proclamé ouvertement qu''il se tenait en dehors de cette catégorie. Il est même allé jusqu''à demander qu''on lui signale ses erreurs, jusqu''à dire que, si on le frappait sur la tête, il répondrait : « Que Dieu vous agrée. » Ce passage de la 16e Lettre cristallise cette attitude :

> « Si quelqu''un me disait ou me montrait qu''il y a un scorpion à mon cou ou dans mon sein, il ne faudrait pas lui en vouloir, mais plutôt s''en réjouir. »

Pris ensemble, ces trois extraits dessinent un tableau clair : Said Nursi a reconnu sa propre faillibilité tout au long de sa vie, à la fois comme position méthodologique et comme attitude morale. Il ne s''agit pas d''une humilité de façade, mais d''un principe fondamental, qui sert de socle à l''approche critique qu''il enseignait à ses disciples.

Première dérive : le réflexe de sacralisation et son terreau sociologique

Comment se fait-il alors que, malgré des déclarations aussi explicites sur sa faillibilité, une partie des Nurcus l''ait placé dans la position d''un lâyuhtî ? La réponse relève en grande partie de la psychologie sociale. Lorsque des foules s''attachent fortement à une idée ou à un chef, toute erreur ou tout échec de ce dernier risque d''être vécu comme un effondrement de leur propre terrain. La crainte que « si le chef peut se tromper, moi aussi je peux être dans l''erreur » déclenche des mécanismes de défense. La « solution » consiste à purger le chef de toute erreur, à le placer dans une position transcendante et à désigner comme une menace interne quiconque remet cette position en question. Ce schéma s''est répété à toutes les époques et dans toutes les cultures.

Le discours « il n''y a aucune erreur dans les Risâle » que l''on rencontre dans certains cercles du mouvement nurcu, ou encore les miracles (keramet) produits autour de Said Nursi, sont les fruits de cette dynamique sociologique. Ce n''est pas Said Nursi lui-même, mais une partie de ses suiveurs qui a opéré cette transformation. Une distinction essentielle s''impose ici : lire les Risâle avec une foi profonde et un enthousiasme sincère, les apprécier comme des textes qui éclairent la vie, est une chose ; les revêtir d''une intangibilité dogmatique en est une autre, et un abîme sépare les deux. La première est ce que Said Nursi souhaitait ; la seconde contredit ce qu''il a écrit de sa propre main. Le constat suivant, tiré de la Hutbe-i Şâmiye (Sermon de Damas), est particulièrement éclairant à cet égard :

> « Notre maladie et notre malheur les plus terribles, c''est la critique qui s''appuie sur la présomption et l''orgueil. Si l''équité guide la critique, elle rabote la vérité et la polit. Si l''orgueil la met à son service, elle détruit et met en pièces. »

Cette phrase ne vaut pas seulement pour les critiques venues de l''extérieur : elle fournit aussi un critère pour la manière d''accueillir les questionnements venus de l''intérieur. Une critique équitable fait resplendir la vérité. Un rejet dicté par l''orgueil détruit, et cette destruction se produit non seulement lorsqu''on rejette la critique, mais aussi lorsqu''on y répond par une défense excessive.

Seconde dérive : de la critique des Risâle à l''attaque contre la personne

Si l''on regarde l''autre face de la médaille, on observe une attitude différente mais tout aussi problématique. Une partie de ceux qui critiquent certaines questions d''*ijtihad*, certaines interprétations ou certains choix méthodologiques des *Risâle* en concluent que Said Nursi aurait délibérément falsifié la religion. Cette affirmation est méthodologiquement incohérente et peut être réfutée sous plusieurs angles.

Premièrement, une erreur dans un texte reflète la capacité de l''auteur, non son intention. Au cours de l''histoire, de nombreux grands savants ont soutenu des opinions que les générations suivantes ont jugées erronées. Cela ne fait pas d''eux des falsificateurs délibérés ; cela montre seulement qu''ils étaient des êtres humains.

Deuxièmement, il suffit de comparer le profil d''un falsificateur délibéré avec l''attitude de Said Nursi dans ses propres textes. Quelqu''un qui dit à ses disciples : « Passez ma parole à la pierre de touche, et si elle se révèle cuivre, jetez-la-moi au visage » ne correspond pas au profil d''un falsificateur exigeant une obéissance absolue. Au contraire, une telle invitation ne peut venir que de quelqu''un qui cherche la vérité et sait qu''il peut se tromper.

Troisièmement, les déclarations de Said Nursi citées plus haut invalident à elles seules cette accusation. Quelqu''un qui dit « Peut-être suis-je moi aussi un corrupteur, ou je corromps sans le savoir » est conscient que l''on peut commettre des erreurs sans le savoir. Par conséquent, même si l''on trouvait une erreur dans les *Risâle*, elle serait la preuve non d''une falsification intentionnelle, mais d''une limite humaine. Said Nursi l''avait d''ailleurs déjà admis.

La frontière entre critique légitime et attaque injuste

Il faut ici poser nettement une distinction : critiquer les Risâle et s''attaquer à la personne de Said Nursi ne sont pas la même chose. Remettre en question une méthode d''exégèse employée dans les Risâle est légitime. Soutenir qu''un ijtihad est faible du point de vue des disciplines concernées est légitime. Avancer qu''un passage est propre aux conditions de son époque et ne peut être généralisé à aujourd''hui est légitime. Tous ces processus intellectuels sont précisément ceux que Said Nursi lui-même invitait à mener et encourageait.

Mais en déduire que « ces erreurs révèlent sa mauvaise foi », affirmer que « les Risâle sont le produit d''une falsification délibérée », ou insulter sa personne, c''est franchir une limite à la fois éthique et méthodologique. Une telle inférence est disproportionnée par rapport aux preuves disponibles. Pour le dire dans les termes de la Hutbe-i Şâmiye : la critique équitable rabote la vérité, tandis que la présomption et l''orgueil détruisent. Une critique qui s''en prend à la personne n''est plus le produit d''une quête de vérité, mais d''autres motivations.

La difficulté du juste milieu

Trouver le juste milieu à propos de Said Nursi n''est pas facile, car de fortes pressions émotionnelles et sociales s''exercent aux deux extrémités. La sacralisation procure un sentiment d''appartenance à la communauté et de sécurité. Le dénigrement procure l''assurance et le sentiment de légitimité que donne l''apparence de faire de la critique. Ces deux attitudes servent moins une véritable quête de vérité que la satisfaction de besoins psychologiques.

Or les textes mêmes de Said Nursi contiennent une tout autre invitation : critique, mais avec équité. Interroge, mais vise l''idée, non la personne. Accepte, mais pas aveuglément : passe à la pierre de touche. Suis-le, mais ne le crois pas exempt d''erreur, car il a lui-même déclaré que cette croyance était une erreur.

Aucun être humain sur terre n''est exempt d''erreur. Said Nursi a reconnu cette réalité en théorie et l''a vécue de manière cohérente dans sa vie. Ceux qui l''attaquent injustement comme ceux qui le sacralisent injustement commettent, par ironie, la même faute sous deux angles opposés : les uns comme les autres refusent de voir en lui un être humain. Peut-être le respect le plus profond consiste-t-il à voir un homme tel qu''il est : un être humain qui a à la fois sa valeur et ses limites.', 'Dans l''histoire religieuse et intellectuelle de la Turquie, il est difficile de trouver une autre figure aussi débattue que Said Nursi, à la...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/comprendre-said-nursi-une-lecture-entre-sacralisation-et-denigrement-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-sokagin-sairi-2-1rg26', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir akşam üstü kapı çaldı.  

Çıktım dışarı kimseyi göremedim.

Beklediğim biri de yoktu aslında.  

Gece gece aklıma takıldı nedense. 

Aşktan yüzü gülmeyene kim uğrar ? 

Bir umut vardı, onu da o sıra kaybettim.

İçeriye rüzgarın dolmasıyla...

Ortamın havası değişmeye başladı. 

Sen değilde, o gelen  yokluğunmuş.

Ateşin dibin de kavrulurken yavaş yavaş.

Birden bire buz kesti kalbim.

Etrafta ki dumanın zehiri içime doldu. 

Kimsesiz bir insanın savunmazlığını yaşadım. 

Geçer dedim o an , düzelir dedim.

Ne sen geldin, ne de yokluğun beni rahat bıraktı. 

İkiside işe yaramadı.  

Bana yeryüzünde şahitlik edecek olan sadece ateşti. 

Acıyla yanı başında çırpındığım o ateş...

Dış kapı açık kalmış, 

Hüzüne dair herşey içeriye dolmak üzere.  

Mutlu gibi görünmeye çalıştığın anlar. Yalanlarla beni avuttuğun özlü sözler.

Aşk derken bile gözlerinin güldüğü o yalancı bakışın.

Saçlarınla oynarken ben, hoşuna gidiyormuş gibi tavırların. 

Senden başkasıyla yaşayamam diyişin.

Her hayal kurduğum da,  yalnız kaldığım o  zamanlar.

Yüzüme karşı seni seviyorum derken, o sesindeki yapmacık olan titreme.

Şimdi nerde bu saydıklarım, 

tüm herşeyin hesabını nasıl vereceksin ? 

Daha çok şey yazacığım fakat , benden geriye kalan evin içinde küller...

Eğer biraz daha anlatırsam, fırtına eşliğinde dışarıya taşacak küllerin hepsi.

İsmi belirsiz sokaklara bile dağılacak . Belki, temiz havaya karışarak senin içine de dolacak sevgili.

Bana ait olan hiç bir şeyi  istemeyeceğini bildiğim için,  susmak tek çözümdür. 

Sonra bir kapı daha çaldı uyandım.  Öncesinde , meğersem bir rüyadaymışım. 

Ev aynı ev sadece ateş yanmıyor.

Kapıyı açtım , gelen sevgilim.  

İçerde,  ayrılık üzerine bir konuşma havası vardı.

Sonucun ne olacağını merakla beklerken.

Dudaklarından çıkan ayrılalım sözü, yüreğime öyle bir oturdu ki. 

O vakit, gördüğüm rüyayı o sıra yaşadım...', 'Bir akşam üstü kapı çaldı.   Çıktım dışarı kimseyi göremedim. Beklediğim biri de yoktu aslında.   Gece gece aklıma takıldı nedense.  Aşktan ...', ARRAY['Türk Edebiyatı','Şiir','Sokağın Şairi 2']::text[], 8.5, '{"poet":"Sokağın Şairi 2","poet_slug":"sokagin-sairi-2","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ruya-1371-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sonbahar Gibi Seni Beklerim', 'ben-sonbahar-gibi-seni-beklerim-mustafa-kaynak-2-49dvs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mevsimler geçti, ömrüm tükendi,

Gönlümce bir bahar yaşayamadım.

Tozlu albümde eskidi hayallerim,

Gözlerine bakıp sana anlatamadım.

Yanı başımda mutluluk ararken,

Göremedim seni, kapandı gözlerim.

Aynı gökyüzü altında yaşarken,

Başka yerlerde geziyordu kalbim.

Sonbahar gibi hüzünlüyüm,

Hazan düşmüş yaprak gibiyim.

Sensiz geçen yılların ardından,

Kendi içimde kaybolmuş gibiyim.

Bir ışık arıyorum karanlıklarda,

Bir çıkış bulamıyorum yollarda.

Ömrüm seni beklemekle geçti,

İçimde hasretin bir türlü dinmedi.

Sana söyleyecek son bir sözüm var,

Bu sevda bitmeyecek sonsuza kadar.

Seni uzaktan sevmeye razıyım,

Yeter ki yüzünde güller açsın bahar.

Yaprakları dökülmüş çınar gibiyim,

Saçları ağarmış sevdalı gibiyim.

Yeter ki sen mutlu ol, hep gülümse,

Ben sonbahar gibi seni beklerim.

Mustafa Kaynak', 'Mevsimler geçti, ömrüm tükendi, Gönlümce bir bahar yaşayamadım. Tozlu albümde eskidi hayallerim, Gözlerine bakıp sana anlatamadım. Yanı başı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Kaynak 2']::text[], 8.5, '{"poet":"Mustafa Kaynak 2","poet_slug":"mustafa-kaynak-2","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ben-sonbahar-gibi-seni-beklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biraz Sen Biraz Ben', 'biraz-sen-biraz-ben-i-shak-koseoglu-emvq9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana bu akşam sıcaklığımda közlenmiş kahveler pişiriyorum;

 içine bir tatlı kaşığı ben attım,

 şekerini de sen koy.

 Ne eksik ne fazla...

 Tam da biz olalım.

 Biraz sen, biraz ben,

 bir fincanın buharında buluşan iki özlem gibi.', 'Sana bu akşam sıcaklığımda közlenmiş kahveler pişiriyorum;  içine bir tatlı kaşığı ben attım,  şekerini de sen koy.  Ne eksik ne fazla...  T...', ARRAY['Türk Edebiyatı','Şiir','İshak Köseoğlu']::text[], 8.5, '{"poet":"İshak Köseoğlu","poet_slug":"i-shak-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/biraz-sen-biraz-ben-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çay İle Fındık Atışma', 'cay-i-le-findik-atisma-kerim-yavuz-anwle', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Funduklen çay kapişti karşilukli atişti

O an masanun usti birbirine karişti

Birbirini yererek üstünlük istediler

Dinleyelum onlari bakalum ne dediler

Funduk söyledi çaya ben bir kuru yemişim

Doğu Karadenizi cennete çevir mişim

Çayda dedi funduğa ben sana neler derum

Bu cennetun içine yok midur benum yerum

Funduk söyledi çaya sana değer vermezler

Satiliyisun amma parani ödemezler

Çayda dedi funduğu Sensun yurek yarasi

Söktiler kökleruni oldun hıyar tarlasi

Funduk söyledi çaya yeter artuk azitma

Millet seni toplarken hep oldi romatizma

Çaydadedi funduğu hasta ettun kizlari

Dallarunİ eğerken kuruyi omuzlari

Funduk söyledi çaya anladum içun sizlar

Dallarumun altina piknik edeyi kizlar

Çayda dedi funduğa Ben sana neler derum

Yaz aylari geldimi şenlenur bahçelerum', 'Funduklen çay kapişti karşilukli atişti O an masanun usti birbirine karişti Birbirini yererek üstünlük istediler Dinleyelum onlari bakalum n...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cay-ile-findik-atisma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu İnsanlar', 'bu-i-nsanlar-kerim-yavuz-zbdvl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu insanlar değilmi kötülüğün alâsı.

Bu insanlar değilmi dünyanın baş belası 

Hangi taşı kaldırsan bunlar çıkar altından.

İçerler doyasıya mazlumların kanından.

Bu insanlar değilmi canı cana kırdıran

Bu insanlar değilmi sivilleri vurduran.

Yatmadımı pusuya ölüm makineleri

Bunlar susturmadımı kundakta bebekleri.

Değilmi bu insanlar yangını körükleyen.

Değilmi bu insanlar masumlara gürleyen

Hep kulak tıkadılar çığlıkların sesine,

Kustular kinlerini rüzgarın nefesine.', 'Bu insanlar değilmi kötülüğün alâsı. Bu insanlar değilmi dünyanın baş belası  Hangi taşı kaldırsan bunlar çıkar altından. İçerler doyasıya m...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bu-insanlar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Les fondements psychologiques et religieux de la fondation de communautés, de confréries et de courants doctrinaux', 'les-fondements-psychologiques-et-religieux-de-la-fondation-de-communaut-s-de-confr-ries-et-de-courants-doctrinaux-muhammed-ridvan-gizri-gc0zo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Faiblesse du nafs, faiblesse de la volonté et véritable guidance

Dire que l''être humain est un être social, ce n''est pas seulement dire qu''il a besoin de vivre avec les autres. Cette réalité recouvre aussi un schéma psychologique plus profond et plus complexe : le désir de faire adopter ses vérités par autrui, de rassembler une foule autour de sa vision du monde et de la garder attachée à soi. Ce désir est l''une des formes les plus anciennes et les plus dangereuses des faiblesses humaines. Fonder une communauté (cemaat), une confrérie (tarikat) ou un courant doctrinal (mezhep), c''est cette faiblesse revêtue d''une forme institutionnelle. Quiconque a fondé une communauté, une confrérie ou un courant doctrinal est devenu, consciemment ou non, l''esclave de son nafs (l''âme charnelle). Ce jugement vaut sans exception.

LA PSYCHOLOGIE DE LA QUÊTE D''APPROBATION

Le besoin de validation

Tout être humain veut confirmer la justesse de ce qu''il croit. C''est un besoin existentiel qui naît de la solitude épistémologique de l''homme. Celui qui élabore seul une idée, qui prend seul une décision, porte toujours en lui un doute. Le moyen le plus facile d''apaiser ce doute est la présence d''autres personnes qui partagent la même idée. L''approbation d''autrui devient pour l''individu la preuve extérieure de sa propre justesse. Ce mécanisme n''est pas pathologique en soi. Partager ses idées, en débattre et les éprouver auprès des autres fait partie du développement cognitif naturel de l''être humain. Le problème commence au moment où la quête d''approbation cesse d''être un besoin pour devenir une dépendance. À partir de là, la personne ne s''intéresse plus à la vérité de ses idées, mais au nombre de ceux qui les adoptent. La quête de la vérité se transforme en quête de la foule.

La solidarité de ceux qui pensent de la même manière

Se réunir avec des personnes qui pensent comme soi procure une puissante satisfaction psychologique, qui a plusieurs sources. La première est le sentiment d''être approuvé et validé. La deuxième est la sécurité née de l''appartenance. La troisième est le sentiment d''infaillibilité que produit la croyance collective. Le raisonnement « Nous sommes si nombreux, nous pensons tous ainsi ; donc c''est nous qui avons raison » est le ciment de bien des structures. Pourtant, ce raisonnement recèle une erreur fondamentale : l''adhésion de la majorité ne rend pas une idée vraie. L''histoire offre d''innombrables exemples d''erreurs collectives. La vérité ne se détermine pas au nombre de voix.

Du désir de diffuser une idée à la domination

Vouloir que ce que l''on croit vrai soit connu des autres est, au fond, une pulsion légitime. Un homme peut vouloir partager une vérité qui, croit-il, l''a sauvé. Tant qu''il est sincère, ce désir est une forme de générosité. Mais à un certain moment, il change de nature. La personne ne veut plus seulement partager un savoir, elle veut aussi façonner les comportements et les choix des autres. Le désir « qu''ils comprennent comme j''ai compris » devient peu à peu « qu''ils fassent comme je dis ». Cette transformation s''opère à l''insu de la personne, qui est le plus souvent incapable de dire quand elle a eu lieu. C''est là que sont semées les graines psychologiques de la fondation de communautés, de confréries et de courants doctrinaux : dans ce passage silencieux où le désir de partager devient désir d''orienter, le désir d''orienter devient désir de créer la dépendance, et le désir de créer la dépendance devient attente d''une obéissance absolue.

L''ILLUSION D''INFAILLIBILITÉ AU CŒUR DE LA STRUCTURE

Sur le nafs du fondateur

Celui qui fonde une structure s''installe inévitablement en son centre. Avec le temps, cette position centrale fait naître en lui un sentiment d''infaillibilité subtil mais profond. Ce sentiment n''est généralement pas exprimé ouvertement et le fondateur lui-même ne le remarque souvent pas. De l''extérieur, il paraît humble et semble reconnaître ses erreurs. Mais le fonctionnement de la structure révèle la réalité : les paroles du fondateur ne sont pas discutées, les critiques sont interprétées comme de la « rébellion » ou un « malentendu », et ceux qui contestent sont exclus. Cela contredit directement le principe le plus fondamental de la foi islamique. La qualité de « küllü layuhda », c''est-à-dire l''infaillibilité, ne peut être attribuée à aucun être humain. Qu''une structure fondée par un simple homme laisse entendre cette qualité, même indirectement, est une grave déviance religieuse.

La sacralisation de l''obéissance

Ce que les structures communautaires, confrériques et doctrinales ont en commun, c''est la sacralisation de l''obéissance envers le chef ou le fondateur. Cette sacralisation prend le plus souvent un voile religieux. Des discours tels que « Obéir au cheikh, c''est obéir à Dieu » ou « Manquer de respect au maître, c''est manquer de respect à la religion » créent en réalité des institutions intermédiaires qui coupent le lien direct entre l''homme et Dieu. Or le modèle de guidance que propose le Coran ne vise pas à rendre l''homme dépendant d''un intermédiaire, mais à faire de lui l''interlocuteur direct de la Parole de Dieu. Le verset 2 de la sourate al-Baqara dit : « Voici le Livre, point de doute en lui, un guide pour ceux qui craignent Dieu. » Le guide, c''est le Livre lui-même. Tout mur dressé entre le Livre lui-même et l''interprétation qu''un homme en donne viole ce principe.

Les conséquences structurelles de la fermeture à la critique

Une structure qui fait taire la critique interne pose, à cet instant même, les fondations de sa propre ruine. Un chef qu''on ne peut pas remettre en question finit par prendre des décisions coupées de la réalité. Une structure qui n''a pas l''habitude d''entendre les avertissements remarque tard, ou jamais, les signes de danger. L''histoire en offre d''innombrables exemples : des communautés religieuses aux mouvements politiques, bien des structures se sont effondrées précisément au moment où elles se sont fermées à la critique. D''un point de vue psychologique, les membres d''une structure qui étouffe la critique perdent eux aussi, avec le temps, leur capacité de penser de façon critique. Une fois le mécanisme de dépendance achevé, les individus ne peuvent plus penser par eux-mêmes. La structure pense pour eux, décide pour eux, trace leurs limites. Cela est en totale contradiction avec l''un des principes fondamentaux de l''islam : l''usage de la raison.

LA MESURE CORANIQUE ET LA VIGILANCE ENVERS LE NAFS

Sur Yûsuf 53

« Je ne prétends pas justifier mon âme ; car l''âme est très incitatrice au mal, sauf ce que mon Seigneur a pris en miséricorde. Mon Seigneur est certes Pardonneur et Miséricordieux. » (Sourate Yûsuf, verset 53)

Ce verset est l''expression la plus concise de la conception islamique du nafs. Celui qui parle, bien qu''il soit un messager, ne se fie pas à son nafs et se garde de se justifier lui-même. La formule « je ne prétends pas justifier mon âme » n''est pas seulement une phrase d''humilité ; c''est aussi un profond avertissement épistémologique. Sa portée pratique est la suivante : quelle que soit sa piété, l''étendue de son savoir ou la qualité de ses intentions, l''homme doit toujours garder à l''esprit que son nafs peut l''égarer. Celui qui fonde une communauté, une confrérie ou un courant doctrinal fait exactement le contraire : avec le temps, il se considère comme indépendant de son nafs, voire supérieur à lui. Le discours « Je suis sur le chemin de Dieu » peut devenir la porte ouverte sur l''un des plus grands pièges du nafs, car le nafs présente le plus souvent le mal sous les traits du bien.

La question de la faiblesse de la volonté

La volonté est la capacité de dire non à ses désirs immédiats au nom de ses valeurs à long terme. Celui qui a une forte volonté peut différer le plaisir que lui procurerait le fait que les autres le suivent, voire y renoncer entièrement. Dans le processus de fondation d''une communauté, d''une confrérie ou d''un courant doctrinal, la personne ne parvient en réalité pas à résister à la satisfaction immédiate, à l''approbation et au sentiment de puissance que l''on éprouve au milieu de la foule. C''est une manifestation classique de la faiblesse de la volonté. Plus clairement : fonder cette structure, c''est le choix par le nafs d''une voie plus facile et plus rapide. Exposer patiemment la vérité, accepter d''être mal compris, être mis en question et rester seul : voilà l''épreuve de la volonté. Celui qui a réellement de la volonté n''a pas besoin de la foule. Et lorsqu''il s''aperçoit qu''il en a besoin, il sait se remettre en question.

Al-Baqara 2 et le problème de l''instrumentalité

« Voici le Livre, point de doute en lui, un guide pour ceux qui craignent Dieu. » (Sourate al-Baqara, verset 2)

Ce verset établit clairement la source de la guidance : le guide, c''est le Coran. L''homme ne peut être, pour cette guidance, qu''un instrument, jamais la source. L''expression « pouvoir être un instrument » est essentielle, car un instrument s''efface une fois utilisé. Son but n''est pas lui-même, mais le point que l''on atteint. Dans les structures communautaires, confrériques et doctrinales, cette relation s''inverse : le chef cesse d''être un instrument et passe au rang de source. Les membres ne se soumettent plus au Coran, mais à la manière dont le chef l''interprète. Avec le temps, cette interprétation passe devant le Coran lui-même, car elle est une autorité concrète, compréhensible, facile à appliquer.

LES QUALITÉS DE LA VÉRITABLE GUIDANCE

Savoir s''effacer

Le véritable guide oriente les gens non vers son ombre, mais vers la lumière du Coran. Concrètement, cela signifie savoir s''effacer. La personne expose une idée ; elle l''expose et la laisse. Que l''auditeur adopte ou non cette idée relève de sa libre volonté. Le guide n''exige aucun résultat. Il n''attend pas d''être accepté. Il ne perçoit pas le refus comme une menace personnelle. Ce degré de maturité ne s''acquiert que par une forte volonté et un profond examen de conscience du nafs. La plupart des gens n''y parviennent pas, car le rejet d''une idée dans laquelle on a investi du travail pèse lourdement sur le nafs. Mais celui qui est capable de porter ce poids a franchi le seuil de la véritable guidance.

Ne pas verrouiller le savoir

Dès que le savoir est transformé en instrument de domination ou d''enrichissement, il s''éloigne de son essence. Celui qui est réellement sur le chemin de Dieu partage sans entrave ce qu''il a compris et écrit. Il ne se soucie pas des droits d''auteur. Il ne demande aucune rémunération. Il le rend accessible en PDF, sur papier, par tous les canaux et dans toutes les régions. Derrière cette attitude se trouve la conviction suivante : « Ce savoir ne m''appartient pas. Je ne suis qu''un transmetteur. Verrouiller le savoir, c''est en réalité trahir le dépôt confié par Dieu. » À l''inverse, nombre de structures religieuses présentent le savoir par strates : par des discours tels que « Tout le monde ne peut pas tout savoir » ou « Ce savoir n''est donné qu''à ceux qui ont atteint une certaine maturité », l''accès au savoir est restreint. Cette restriction est en réalité l''un des mécanismes de pouvoir les plus importants qui assurent la pérennité de la structure.

Admettre l''erreur d''emblée

« Voilà ce que j''ai compris ; l''erreur me revient, et la justesse revient au Maître de la Parole. » Cette phrase est la traduction pratique de la vigilance envers le nafs dont parle Yûsuf 53. Le véritable guide présente ses œuvres dans ce cadre. Il dit au lecteur : « Je peux me tromper. Ne m''accepte pas aveuglément. Utilise ta raison, compare avec le Coran, remets en question. » Les structures communautaires, confrériques et doctrinales appliquent au contraire exactement l''inverse de ce principe : les opinions du fondateur finissent par être tenues pour indiscutables. Celui qui s''y oppose est accusé de « faiblesse de foi » ou de « mauvaise intention ». La structure se construit ainsi, en son sein, une cuirasse d''intangibilité.

Vouloir être remis en question

La véritable guidance ne craint pas d''être questionnée ; au contraire, elle y invite. L''attitude « Questionnez-moi, montrez-moi mes erreurs, demandez-moi ce que vous ne comprenez pas » est à la fois un signe de maturité épistémologique et de santé du nafs. Une structure qui craint d''être questionnée a senti sa propre fragilité et s''est réfugiée derrière le bouclier de l''autorité pour la cacher. Cette fragilité finit par éclater au grand jour, car aucun édifice qui n''est pas bâti sur la vérité ne peut durer.

L''ATTRAIT DE L''INFAILLIBILITÉ ET LE MÉCANISME D''EFFONDREMENT DES STRUCTURES RELIGIEUSES

Pourquoi les gens rejoignent-ils ces structures ?

La réponse à cette question exige de considérer non seulement la faiblesse du fondateur, mais aussi celle du membre. Les gens rejoignent ces structures parce qu''ils cherchent la certitude au sein de l''incertitude. Ils s''imaginent que le Coran est difficile à comprendre et prétendent que l''affronter directement exige responsabilité et effort de réflexion. Or, selon eux, accepter « l''interprétation juste » d''un chef est bien plus facile. Cette facilité est un piège. Celui qui a livré sa raison à un chef ne pourra pas dire, le jour où il rendra des comptes : « On m''a dit ainsi. » Chacun rendra des comptes avec sa propre raison, sa propre volonté et son propre cœur.

L''effondrement est inévitable

Toute structure fondée sur une prétention à l''infaillibilité s''effondre inévitablement. Cet effondrement vient parfois d''une pression extérieure, parfois d''une fracture interne. Mais le véritable effondrement se produit dans l''esprit des membres de la structure, au moment où la déception remplace la confiance et où la colère remplace l''attachement. Ce ne sont pas les fondateurs qui paient le plus lourdement la facture de cet effondrement, mais les membres. Ces gens qui ont sacrifié leurs années, leurs efforts et parfois leurs familles se retrouvent, en regardant en arrière, à avoir servi une structure devenue l''esclave d''un nafs.

CONCLUSION

Fonder une communauté, une confrérie ou un courant doctrinal, c''est une faiblesse humaine qui prend une forme institutionnelle. Cette faiblesse se manifeste sous les formes suivantes : la quête d''approbation, la constitution d''une foule, l''exigence d''obéissance et l''illusion d''infaillibilité. Yûsuf 53 rappelle que le nafs de tout être humain peut commander le mal. Al-Baqara 2 établit que le seul véritable guide est le Coran lui-même. Lus ensemble, ces deux principes coraniques disent ceci : aucun homme ne peut se placer au-dessus du Coran ni à sa place. Quiconque commence à s''élever à cette position est devenu l''esclave de son nafs. Quiconque oriente les gens vers lui-même plutôt que vers le Coran a revêtu sa faiblesse de volonté d''un habit structurel. Le véritable guide offre le savoir gratuitement, admet l''erreur d''emblée, ne fuit pas le questionnement, sait s''effacer et oriente les gens non vers son ombre, mais vers l''unique guide qui ne recèle aucun doute : le Coran. Fonder une communauté, une confrérie ou un courant doctrinal se tient à l''exact opposé de cette ligne de guidance. Et quiconque fonde une telle structure, quel qu''il soit, a perdu le combat que lui livrait son nafs.', 'Faiblesse du nafs, faiblesse de la volonté et véritable guidance Dire que l''être humain est un être social, ce n''est pas seulement dire qu''i...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/les-fondements-psychologiques-et-religieux-de-la-fondation-de-communautes-de-confreries-et-de-courants-doctrinaux-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tevbe (36,37) Haram Aylara Hürmet Gerekir', 'tevbe-36-37-haram-aylara-hurmet-gerekir-selim-i-c-sdi50', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kâinatta işler ilahi düzen,

Her şey kusursuz; gösterilmiş özen,

Farkına varır dikkatlice süzen…

İbret gözüyle olursa bakışın;

Görmemek mümkün değil o nakışın.

Âlemde harika bir sistem ördü,

İzniyle bir yıl on iki ay sürdü,

Haram sayıldı bunlardan dördü…

Güvenle halkın içine karışın!

Çünkü sembolü bu aylar barışın.

Aylar arasında yaptılar nesî,

Peş peşe geliyordu üç tanesi,

Savaşamaması tek bahanesi…

Süslü gösterildi böyle yapışın,

Bir bedeli olacak bu sapışın.

Emre uymayıp yasağı delerse,

Mümine bu aylarda diş bilerse,

Karşılık verilir kavga dilerse…

Onlara karşı topluca savaşın!

Bil ki Allah ve Resulü yoldaşın.', 'Kâinatta işler ilahi düzen, Her şey kusursuz; gösterilmiş özen, Farkına varır dikkatlice süzen… İbret gözüyle olursa bakışın; Görmemek mümkü...', ARRAY['Türk Edebiyatı','Şiir','Selim İç']::text[], 8.5, '{"poet":"Selim İç","poet_slug":"selim-i-c","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tevbe-36-37-haram-aylara-hurmet-gerekir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Kızamıyorum Yüreğim', 'sana-kizamiyorum-yuregim-i-shak-koseoglu-xjm3v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vurgunlarda gezer deli yüreğim,

 hâlâ yorulmadın mı?

 Her seferinde biraz daha eksilirken

 kendine sarılmayı öğrenmedin mi?

Bir çocuk saflığıyla inanıyorsun yine,

 oysa avuçlarında eski yaraların izi duruyor hâlâ.

 Unuttun mu sanıyorsun?

 Yoksa hatırladığın hâlde sevmekten vazgeçemiyor musun?

Bir adım umutla gidiyorsun,

 iki adım kırgınlıkla dönüyorsun.

 Sonra sessizce oturup yaralarını okşuyor,

 kimse görmeden toparlanmaya çalışıyorsun.

"Ben görüyorum," diyorsun.

 Belki de sorun tam burada.

 Herkesin içindeki güzelliği görüyorsun da

 sana doğru gelen fırtınaları göremiyorsun.

Mutluluk neydi senin için?

 Bir sıcak söz mü,

 güvenle uzanan bir el mi,

 gitmeyeceğine inanılan bir çift göz mü?

Belki de bu yüzden şaşırdı rotan.

 Kötü olduğundan değil,

 fazla inandığından.

Bak, hâlâ atıyorsun o göğsün içinde;

 her çarpışında biraz ürkek,

 biraz yorgun,

 ama yine de sevgiye aç.

Ne garip...

 En çok canı yanan sensin,

 ama en çok sen affediyorsun.

Ve belki de bu yüzden

 herkes senin güçlü olduğunu sanıyor.

 Oysa kimse bilmiyor;

 geceleri sessizce içine çöken o kırgınlığı,

 her yeni yarada biraz daha sessizleşen çırpınışını.

Ey yüreğim,

 sana kızamıyorum artık.

 Çünkü anladım ki sen akılsız olduğundan değil,

 güzel kalmaktan vazgeçemediğinden kırılıyorsun.', 'Vurgunlarda gezer deli yüreğim,  hâlâ yorulmadın mı?  Her seferinde biraz daha eksilirken  kendine sarılmayı öğrenmedin mi? Bir çocuk saflığ...', ARRAY['Türk Edebiyatı','Şiir','İshak Köseoğlu']::text[], 8.5, '{"poet":"İshak Köseoğlu","poet_slug":"i-shak-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sana-kizamiyorum-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Yara', 'gizli-yara-kasim-kobakci-6ustr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak karanlık çökmüş tarlaya,

Yorgun yolcu düşmüş buraya,

Umut bağlar eski binaya,

Adım atmış ıssız avluya,

Çare yok ki gizli yaraya.

*

Bolca saman, ahır ve kümes,

Çıkmaz buralardan tek bir ses.

*

Sabah olmuş güneş parlıyor,

Seyyah etrafını tarıyor,

Kaybolmuş birini soruyor,

Rüzgar çatılarda uluyor,

Saatler yerinde duruyor.

*

Ne bir köy var ne de bir nefes,

Bu garip çiftlik büyük kafes.

*

Hep pas tutmuş çitlerde demir,

İçtiğim acı sular zehir,

Uzakta kalmış büyük şehir,

Akmaz burada garip nehir,

Seyyah bu topraklarda esir.

*

İnsan yok ki hayvanlar sırdaş,

Uzuyor gece yavaş yavaş.

*

Ahıra dolmuş rüzgar serin,

Çiftlikte izleri çok derin,

Üstünü örtmüş bütün yerin,

Karanlık altındadır zemin,

Dertleri deşilmez kimsenin.

*

Toprakla eder büyük savaş,

Sürüler olmuş ona yoldaş.

*

Savrulurken göğe toz saman,

Bu çılgın çiftlikte hal yaman,

Aklını kaybetmiş bak zaman,

Fırtına vurup vermez aman,

Bacalardan tütmez hiç duman.

*

Etrafını sarmış kara tel,

Rüzgar esip uğuldar hep yel.

*

Geceleri bastırır ayaz,

Çıplak tepeler olur beyaz,

Kaybolmuş seyyaha gelmez yaz,

Delilik içinde uyur az,

Çalmaz burada ne tef ne saz.

*

Yağmur yağar olur büyük sel,

Kimseden uzanmaz asla el.

*

Çareyi bulmak için arar,

Dört yana bakıp verir karar,

Korku garip ruhunu sarar,

Yalnızlık ona verir zarar,

Boşa koşturmak neye yarar.

*

Bolca kümes ve bolca ahıl,

Taşlıdır yolları hep çakıl.

*

Çatısı buluttan bir durak,

Asfaltsız köy yolları kurak,

Hastane yok doktor çok uzak,

Bu meçhul çiftlik büyük tuzak,

Her yanı ot bürümüş toprak.

*

Kalmamış kimsede hiç akıl,

Delirmek burda sanki asıl.

*

Bağırır ahırdaki domuz,

Su kuyusu kurumuş susuz,

Sürüler tokuşturur boynuz,

Hayat burada sanki ucuz,

Yük binmiş çöküyor hep omuz.

*

Hastalık sarmıştır çare yok,

Bu köyde dertli insan pek çok.

*

Tepeden doğacaktır güneş,

Seyyah arıyor kendine eş,

Yanmaz ocakta artık ateş,

Ahılda koyun olmuş kardeş,

Ortalıkta çürümüş bir leş.

*

Vuruyor kalbine derin ok,

Köylünün karnı acıya tok.

*

Çatılarda bir büyük delik,

Çatlamış herkeste o kemik,

Anlamsız bakışlar hep kesik,

Bu tımarhanede his eksik,

Korkular bekliyor hep tetik.

*

Kökleri çürümüş kör ağaç,

Bu topraklar hep suya muhtaç.

*

Otlar boyu aşmış da biter,

Bacasız evlerden dert tüter,

Durum dünkünden daha beter,

Akıllar hep meçhule yiter,

Garip seyyaha bu dert yeter.

*

Bulunamaz derdine ilaç,

Çiftlikte gezenler sanki aç.

*

Karanlık gecede bir kör göz,

Dilinde kalmamış tek bir söz,

Ocakta sönüyor artık köz,

Çiftliğin içinde işler öz,

Kimseye diyemez bunu çöz.

*

Kırılan pencerelerde cam,

Ne bir evi kalmış ne yaşam.

*

Anlatılan bir garip masal,

Çobanlar çalamıyor kaval,

Delinmiş ambardaki çuval,

Bu deli düzen değil yasal,

Her şey korkunç ötesi misal.

*

Bitmez içindeki derin gam,

Boşlukta geçiyor her akşam.

*

Fırtına vurup gelmiş o kış,

Kapanmış yolları yok çıkış,

Seyyahtan meçhule bir bakış,

Yüzünde çizgiler hep nakış,

Titreyen kalbinde boş atış.

*

İş işten geçmiş zaman geçmez,

Delirmiş zihni yolu seçmez.

*

Gökyüzü kararmış yok ki ay,

Ahırda koşamıyor bak tay,

Günleri birer birer sen say,

Kaderden kalmamış zerre pay,

Bu zalim hayata der ki vay.

*

Ektiği tohumu biçemez,

Zehirli sulardan içemez.', 'Bak karanlık çökmüş tarlaya, Yorgun yolcu düşmüş buraya, Umut bağlar eski binaya, Adım atmış ıssız avluya, Çare yok ki gizli yaraya. * Bolca...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":143,"source_url":"https://www.antoloji.com/gizli-yara-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaylalar', 'yaylalar-kerim-yavuz-9agv8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün mutlaka deyip söz vermişim kendime

Elbette muradıma ereceğim yaylalar

Gül yüzlü nazlı yari alıp ta ellerime

Gelip çiçeklierini dereceğim yaylalar

Bir gün kurtulacağım kaderin oyunundan

Bilirsin hoşlanırım süzülmüş yoğurdundan

Yüreğinden fışkıran o buz gibi suyundan

Elbet bir gün iştahla içeçeğim yaylalar

Bilesin çok özledim yayla muhlamasını

Dikeceğim kafama bakır ayran tasını

Yeşil çimenlerine çilingir sofrasını

Kuşkun olmasın bir gün sereceğim yaylalar

Bahar da çeşit çeşit gül açar dağlarına

Konvoylar sıra sıra dizilir yollarına

Elime sepet takıp derin ormanlarına

Mantar toplamak için gireceğim yaylalar

Rüyalarıma girip bölüyorsun uykumu

Kader elbette sana bağlayacak yolumu

Toprağının üstüne yastık edip kolumu

Sırtımı da Güneşe vereceğim yaylalar

Söyledim bu gurbete benim yakamı bırak

O çiçek kokuları şimdi benden çok ırak

Alacağım elime uzun saplı bir orak

Çayırlarından ekin biçeceğim yaylalar', 'Bir gün mutlaka deyip söz vermişim kendime Elbette muradıma ereceğim yaylalar Gül yüzlü nazlı yari alıp ta ellerime Gelip çiçeklierini derec...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yaylalar-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen.', 'bazen-fehmi-tazegul-rw89n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yolda Sokakta dolaşır insanlar.

Ömrüm geçmiş olmuş sonbahar.

Fakirle yoksulu yoldaş kim anlar.

Bazen deli bazense garip dediler.

Üzülürken canan söylerim türkü.

Belimi bükmüştür hasretin yükü.

İçimi sızlatır uçan kuşların göçü.

Bazen deli bazense deli dediler.

Hiç unutmam ben geçen yılları.

Hayalimdeki dağları taşlı yolları.

Mesken yaptım kayalarla taşları.

Bazen deli bazense deli dediler.

Fehmi.

Yağmura rüzgâra bel bağladım.

Gözlerim yaşlı susarak ağladım.

Dostla yoldaşıma hep uğradım.

Bazen deli bazense deli dediler.', 'Yolda Sokakta dolaşır insanlar. Ömrüm geçmiş olmuş sonbahar. Fakirle yoksulu yoldaş kim anlar. Bazen deli bazense garip dediler. Üzülürken c...', ARRAY['Türk Edebiyatı','Şiir','Fehmi Tazegül']::text[], 8.5, '{"poet":"Fehmi Tazegül","poet_slug":"fehmi-tazegul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bazen-720-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-kerim-yavuz-7f6rh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gurbet ellere düştüm düşeli

Elime kelepçe taktı ayrılık

Hangi yüze baksam hepsi neşeli

Beni ateşine yaktı ayrılık

Gurbet, fermanını verdi elime

Soğuk kollarını sardı belime

Yar yar diye yanan gönül telime

Hasret çivisini çaktı ayrılık

Anlamıyor kimse hasret çekeni

Özledim köyümde kuru dikeni

Gül yüzlü yarimden ayırıp beni

Gurbet kervanına kattı ayrılık

Kalmadı huzurum başım hep duman

Gurbetin koynunda geçmiyor zaman

Aşkı sevdiğimle paylaşamadan

Beni gurbet ele attı ayrılık

Nedense gurbetin hep yönü batı

Silinse tarihten kalmasa adı

Şimdi yaşantımın kalmadı tadı

Kalbime ok gibi battı ayrılık', 'Bu gurbet ellere düştüm düşeli Elime kelepçe taktı ayrılık Hangi yüze baksam hepsi neşeli Beni ateşine yaktı ayrılık Gurbet, fermanını verdi...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ayrilik-2079-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'La véracité : une vertu morale à la lumière du Coran', 'la-v-racit-une-vertu-morale-la-lumi-re-du-coran-muhammed-ridvan-gizri-db756', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Des relations humaines saines et des sociétés qui vivent dans la paix et la confiance ne sont possibles que si de solides valeurs morales sont mises en pratique. La véracité est sans aucun doute la première de ces valeurs. Elle consiste à se tenir à l''écart du mensonge, de la ruse, de la tromperie et de l''hypocrisie, à faire concorder la parole et le comportement, et à faire en sorte que l''être intérieur soit identique au visage qu''on montre. Cette vertu, qui occupe depuis des siècles le centre de toutes les religions, de toutes les philosophies morales et de tous les systèmes de pensée sociale, jouit aussi d''une place privilégiée parmi les enseignements fondamentaux de l''islam. Le Coran invite les croyants à être, en toute circonstance, des personnes sincères dans leurs paroles et dignes de confiance. Cet appel n''est pas seulement une obligation religieuse : il a aussi un sens profond pour la préservation de l''intégrité intérieure de l''individu, pour le renforcement de la confiance sociale et, en définitive, pour l''obtention de l''agrément d''Allah.

Le sens et la portée de la véracité

Un regard superficiel pourrait réduire la véracité à « ne pas mentir ». Pourtant, dans la morale islamique, elle recouvre un champ de sens bien plus vaste. La sincérité dans la parole n''en est qu''une dimension. Être véridique au vrai sens du terme, c''est aussi rester fidèle à sa parole donnée, être honnête dans les transactions, respecter les dépôts confiés et porter en soi un monde intérieur sincère envers Allah. Le Coran exprime cette conception globale par la notion de « sidq ». Le sidq désigne l''harmonie parfaite entre la parole, l''intention et l''action. En tout point où cette harmonie est rompue, il y a un écart par rapport à la véracité. C''est d''ailleurs précisément pour cette raison que le Coran condamne sévèrement l''hypocrisie, qui est la forme la plus grave de cette discordance entre l''intérieur et l''extérieur.

L''appel du Coran à la véracité

En invitant les croyants à se tenir aux côtés des gens sincères et véridiques, le Coran évoque en réalité la construction d''une communauté. Dans le verset 119 de la sourate At-Tawba, le Très-Haut dit :

« Ô vous qui croyez ! Craignez Allah et soyez avec les véridiques. »

Ce verset attire l''attention sur la dimension sociale de la véracité, au-delà de la simple vertu individuelle. La compagnie de personnes véridiques nourrit le développement spirituel de l''individu et prépare le terrain à l''établissement d''un climat de confiance dans la société. Lorsque les gens de bien vivent ensemble, la véracité cesse d''être une qualité ordinaire pour devenir le trait fondamental de la communauté dans laquelle on vit. Le verset 70 de la sourate Al-Ahzâb renforce cet appel par un ordre plus direct :

« Ô vous qui croyez ! Craignez Allah et tenez un langage droit. »

Ce verset est remarquable en ce qu''il mentionne la droiture dans la parole en même temps que la taqwa, c''est-à-dire une profonde conscience de sa responsabilité envers Allah. La véracité n''est donc pas une simple courtoisie sociale ni un calcul d''intérêt pratique : elle est le reflet naturel du respect et de l''amour que l''on porte à Allah. La personne pieuse sait qu''Allah voit et entend tout ; seule comme au milieu de la foule, elle agit donc avec la même honnêteté.

L''effet destructeur du mensonge

L''importance de la véracité se comprend aussi à travers les ravages causés par son contraire, le mensonge. Le mensonge est un comportement néfaste qui ébranle la confiance entre les gens, érode l''affection et trouble la paix sociale. Dans les relations individuelles, il conduit à la méfiance et à la rupture. À l''échelle de la société, sa généralisation fait que la méfiance remplace la solidarité, et la peur, l''affection. Le Coran expose ce danger très clairement. Dans le verset 30 de la sourate Al-Hajj, il est dit :

« Évitez donc la souillure des idoles et évitez les paroles mensongères. »

Il est très significatif que le mensonge soit cité dans la même catégorie que les idoles. Tout comme l''association (le chirk), le mensonge est une souillure qui éloigne l''être humain d''Allah et de son humanité. On souligne ainsi que le mensonge n''est pas seulement un défaut moral, mais une impureté spirituelle. De fait, dans les sociétés où le mensonge se répand, la confiance dans le droit est ébranlée, les gens ne peuvent plus se fier à la parole les uns des autres, la vie commerciale est entravée et les liens familiaux se défont. En revanche, dans les sociétés où règne la véracité, la solidarité se renforce, les différends se règlent plus facilement et les gens peuvent se tendre la main.

La véracité : une intégrité qui va de la parole au comportement

La véritable véracité n''est pas une vertu qui reste dans les mots. Elle exige une intégrité qui se manifeste dans tous les domaines de la vie. Être honnête dans les achats et les ventes, tenir une promesse une fois qu''on l''a faite, veiller sur un dépôt confié, s''éloigner du gain illicite : tout cela en est l''expression concrète. Le croyant est une personne dont l''intérieur et la parole ne font qu''un. Il ne se comporte pas différemment selon qu''il est observé par les autres ou qu''il est seul. En effet, la conscience de foi que le Coran enseigne inclut la certitude que chaque instant se déroule en présence d''Allah. Un individu qui agit avec cette conscience ne se tourne ni vers la ruse, ni vers la malhonnêteté, ni vers la tromperie, car aucune parole et aucun acte n''échappent à Allah. À ce stade, la véracité n''est pas maintenue par un mécanisme de contrôle extérieur, mais par un sentiment de responsabilité venu de l''intérieur. Cette discipline intérieure constitue l''un des points forts de la morale islamique.

Le rôle de la famille et de l''éducation

La véracité est une vertu qu''il faut enseigner et faire vivre. Le cadre où ce processus se déroule le mieux est la famille. Les enfants apprennent les notions non pas dans les livres, mais à travers les exemples qu''ils vivent. Lorsque les parents restent fidèles à une promesse faite à un jeune enfant, qu''ils distinguent le vrai du faux dans leur conduite et qu''ils adoptent l''honnêteté comme principe dans la vie quotidienne, cela joue un rôle déterminant dans l''intériorisation de ces valeurs par l''enfant. À l''inverse, si les parents mentent pour leur propre intérêt ou incitent leurs enfants à mentir, cela crée dans l''esprit de l''enfant un terrain qui légitime le mensonge. C''est pourquoi l''éducation morale repose avant tout sur la cohérence de l''exemple donné par les adultes. Les parents qui veulent enseigner la véracité à leurs enfants doivent d''abord incarner cette valeur dans leur propre vie.

La véracité et la sincérité envers Allah

La conception coranique de la véracité ne se limite pas aux relations entre les gens. Être sincère envers Allah, c''est-à-dire garder ses intentions pures et accomplir ses actes d''adoration non par ostentation mais avec une véritable soumission, constitue aussi l''essence de la véracité. Rester attaché aux mêmes valeurs, seul comme au sein d''une communauté, est l''expression la plus profonde de la sincérité et de la véracité. Pour le croyant conscient qu''Allah sait et voit tout, la véracité n''est pas une contrainte, mais un choix volontaire et une preuve d''amour. Cette conscience le conduit à être honnête non seulement envers les autres, mais aussi envers lui-même et envers Allah. La véracité est une haute valeur morale, au point de rencontre de la vertu individuelle et de la paix sociale, où l''ordre de la vie d''ici-bas rejoint le gain de l''au-delà. Le Coran ordonne cette valeur et indique aussi la voie pour y parvenir : vivre avec un profond respect envers Allah, c''est-à-dire par la taqwa. Le croyant doit faire de la véracité un principe dans sa parole, son comportement, ses relations commerciales, sa vie familiale et son lien avec Allah. Ce principe fait de lui, dans cette vie, une personne digne de confiance et sereine, et lui ouvre la voie vers l''agrément d''Allah. Car au fondement du portrait moral que le Coran dessine pour l''être humain se trouvent le sidq, c''est-à-dire la véracité, la fiabilité et la sincérité.', 'Des relations humaines saines et des sociétés qui vivent dans la paix et la confiance ne sont possibles que si de solides valeurs morales so...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/la-veracite-une-vertu-morale-a-la-lumiere-du-coran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geveze Gece', 'geveze-gece-kerim-yavuz-mtgvx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç susmak bilmiyor geveze gece,

Şarkılar söylüyor çiğlık çığlığa

Hayatım karıştı oldu bilmece

Yürek dayanmıyor bu yalnızlığa

Üşüdüm bu gece hava çok soğuk.

Kendime sokuldum kedi misali.

Yalnızlık odamda cirit atıyor.

Dizlerim göğsümde aklım firari.

Dışarıda raks eden yağmurun sesi,

Camların yüzüne vurup duruyor.

Bütün hırçınlığı üstünde bugün,

Duygularım benden hesap soruyor.

Karanlık her şeyi kökünden yutmuş.

Artık görünmüyor yıldızlı gemi.

Uyandı efkârım odama çöktü.

Koyulaştı o an gecenin demi.

Ey insafsın gece gelme üstüme.

An olur sabaha sorarım seni.

Koz kullanma bana yalnızlığımı.

Nemli bulut gibi ağlatma beni.', 'Hiç susmak bilmiyor geveze gece, Şarkılar söylüyor çiğlık çığlığa Hayatım karıştı oldu bilmece Yürek dayanmıyor bu yalnızlığa Üşüdüm bu gece...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/geveze-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'La moquerie et le respect de la dignité humaine', 'la-moquerie-et-le-respect-de-la-dignit-humaine-muhammed-ridvan-gizri-6i2vq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'L''être humain est, par sa création même, un être digne et précieux. La préservation de cette dignité n''est pas seulement une responsabilité individuelle, c''est aussi une nécessité sociale. La morale islamique pose comme principe fondamental que chacun protège aussi bien son propre honneur et sa propre dignité que ceux des autres. Dans ce cadre, se moquer d''autrui, le mépriser et l''avilir est considéré non seulement comme une faiblesse personnelle, mais aussi comme un mal social.

Les différences entre les êtres humains et le véritable critère de supériorité

Allah a créé les êtres humains différents les uns des autres par leur constitution physique, leur raison, leurs aptitudes, leur sensibilité et leur intelligence. Ces différences sont une conséquence naturelle de la richesse de la vie et de la coopération sociale. De même que chacun surpasse autrui dans un domaine, chacun a aussi ses insuffisances. Par conséquent, nul n''a le droit de mépriser quelqu''un en raison d''une seule qualité qu''il possède. Il faut souligner en particulier que des caractéristiques d''ordre terrestre comme la couleur de peau, la race, la fortune et le rang ne constituent, selon l''islam, aucun véritable critère de supériorité. Le seul critère de supériorité que l''islam reconnaît entre les hommes est la taqwa, c''est-à-dire vivre avec une profonde conscience d''Allah et rechercher Son agrément. Ce principe fondamental montre clairement qu''il n''existe aucune justification à l''orgueil ni à la prétention de supériorité.

La nature de la moquerie et ses formes

La moquerie consiste à exposer publiquement le défaut, le manque ou la différence d''autrui pour l''humilier. Au cœur de ce comportement se trouvent le plus souvent le sentiment de se croire grand et la volonté de déprécier l''autre. En d''autres termes, la moquerie est en grande partie une faiblesse morale nourrie par l''orgueil. Elle ne se limite pas à la parole. On peut rabaisser autrui de bien des manières :

- Par la parole et l''écrit : rabaisser quelqu''un en évoquant ou en écrivant, ouvertement ou à mots couverts, ses défauts, ses particularités physiques ou sa condition sociale.

- Par les gestes et les mimiques : les mouvements des bras et des mains, les expressions du visage et le langage corporel peuvent se transformer en un instrument d''humiliation parfois plus dur que la parole.

- Par l''imitation : imiter la manière de parler, la démarche ou les comportements de quelqu''un, d''une façon qu''il ne souhaite pas, pour le rendre ridicule est aussi une forme de moquerie.

- Par l''allusion et le sous-entendu : sans le dire directement, par des insinuations subtiles et des regards entendus, la moquerie peut parfois blesser bien plus que la moquerie ouverte.

Le Coran a expressément interdit toutes ces formes de moquerie et condamne sévèrement ceux qui s''y livrent. Donner des sobriquets désobligeants figure tout particulièrement parmi ces interdits. S''adresser à quelqu''un par un nom ou un titre qu''il n''aimerait pas et qui porte atteinte à son honneur est jugé aussi laid que de l''humilier ouvertement.

Les méfaits individuels et sociaux de la moquerie

La moquerie ne nuit pas seulement à la personne moquée : elle ébranle profondément celui qui s''y livre ainsi que la société dans laquelle il vit.

- La réputation du moqueur est entamée. Celui qui a pris l''habitude de mépriser les autres finit par perdre, aux yeux de la société, sa crédibilité et sa considération. Les gens ne voient pas comme une personne de valeur celui qui prend plaisir à en abaisser un autre. Le moqueur ruine ainsi, sans s''en rendre compte, sa propre réputation.

- Un temps précieux est gaspillé. La moquerie détourne l''individu de son propre développement et des vrais problèmes auxquels il doit faire face. S''occuper des défauts des autres, c''est consacrer son temps et son énergie à une occupation vaine.

- Les liens de fraternité sont abîmés. L''islam vise à construire un lien de fraternité solide entre les croyants. Or se moquer et mépriser détruit directement ce lien et engendre fragilité et division dans la société.

- Des sentiments d''hostilité et de vengeance naissent. Avec le temps, l''amertume et la colère s''accumulent dans le cœur de la personne moquée. Cela prépare le terrain à des sentiments de vengeance et d''hostilité qui menacent la paix sociale. Ainsi, une habitude de moquerie d''apparence anodine au départ peut conduire à des ruptures sociales durables.

- Le tort retombe sur son auteur. Les paroles blessantes visant les parents ou les proches d''autrui reviennent souvent sous la même forme et blessent les propres proches de celui qui les a prononcées. Toute mauvaise parole finit tôt ou tard, d''une manière ou d''une autre, par retourner dans le monde de celui qui l''a dite.

Le silence est-il une approbation ?

La morale islamique ne tient pas seulement responsables ceux qui se moquent eux-mêmes, mais aussi ceux qui s''associent à une ambiance moqueuse en gardant le silence. Ne pas avertir quand on est témoin de moqueries, ne pas quitter les lieux ou se joindre aux rires de l''assistance revient à approuver ce comportement de manière indirecte. L''attitude du croyant consiste donc non seulement à s''abstenir lui-même de toute moquerie, mais aussi à se tenir à distance de ces milieux et à avertir, dans la mesure de ses moyens. Faire vivre la vérité et la morale ne consiste pas seulement à ne pas faire le mal, mais aussi à ne pas se taire devant lui.

L''attitude du croyant : un examen de conscience intérieur

Au lieu de se moquer des autres, la voie à suivre est celle de l''examen de conscience. Plutôt que de chercher les manques et les défauts d''autrui, l''être humain doit s''efforcer de voir ses propres imperfections et d''y remédier. Mépriser les autres n''est rien d''autre que projeter sur eux ses propres vides intérieurs. La véritable maturité s''acquiert en prenant conscience de ses limites et de ses défauts et en s''efforçant de les corriger. Les croyants évitent toute parole et tout comportement susceptibles de blesser autrui ; ils s''écartent des qualificatifs et des appellations qui atteindraient la personnalité, la foi ou l''identité des autres. Même lorsqu''ils transmettent le vrai et la vérité aux gens, ils emploient un langage soigné et respectueux. Car l''exactitude de ce qui est dit ne justifie pas que la manière de le dire soit grossière et blessante.

Bien qu''elle ressemble en apparence à un humour innocent, la moquerie recèle au fond l''orgueil, le mépris et le déni de la valeur accordée à l''être humain. La morale islamique a considéré la dignité humaine comme la valeur la plus fondamentale et a interdit toute atteinte à cette dignité, sous quelque forme que ce soit. Le véritable croyant ne fait à autrui rien de ce qu''il ne voudrait pas qu''on lui fasse. Au lieu de rabaisser les autres, il s''efforce de les comprendre ; au lieu de les mépriser, de leur accorder de la valeur. Le fondement d''une société saine et paisible est le respect que les individus manifestent envers la dignité les uns des autres. Ce respect ne s''édifie pas seulement en s''opposant aux grandes injustices, mais aussi en maîtrisant sa langue et sa conduite dans les moments les plus ordinaires de la vie quotidienne. S''abstenir de la moquerie est l''une des formes de respect les plus simples et les plus profondes que l''on puisse témoigner à l''humanité.', 'L''être humain est, par sa création même, un être digne et précieux. La préservation de cette dignité n''est pas seulement une responsabilité ...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/la-moquerie-et-le-respect-de-la-dignite-humaine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennem Yeri', 'cehennem-yeri-kerim-yavuz-kd30z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine perdelerin ardına kaldın,

Görmüyorum seni kaç günden beri.

Bilesin aklımı başımdan aldın

Cehenneme döndü bu yangın yeri

Bir cama çıksan da görsem yüzünü.

Doğsan güneş gibi umutlarıma.

Atsam yüreğimden derdi hüzünü,

Rehber etsem seni aşk yollarıma.

Şarkılar hüzünlü geceler demli,

Anla beni artık duy feryadımı.

Seni görmeyeli gözlerim nemli.

Sensizlik büsbütün çaldı tadımı.

Kulak vermiyorsun benim sesime

Şimdi göz yaşlarım akıyor sensiz

Yakıyor içimi cehennem yeri

Zavallı yüreğim cehennem sanki

Yanarım aşkına yanarım gülüm

Yüreği dağlanan benim inanki

Olur mu sevene aşk ile zülüm', 'Yine perdelerin ardına kaldın, Görmüyorum seni kaç günden beri. Bilesin aklımı başımdan aldın Cehenneme döndü bu yangın yeri Bir cama çıksan...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cehennem-yeri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Enflasyon', 'enflasyon-kerim-yavuz-0psg1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Engel tanımıyor kalktı atağa.

Evi birbirine kattı eflasyon

Kor ateşler gibi düştü mutfağa.

Mutfakta ateşi yaktı enflasyon.

İğneden ipliğe yine zam geldi

Umutlarımız tümden köreldi

Fakirin tasını deldikçe deldi.

Sanki ağaçkakan oldu enflasyon.

Öyle bir hırsız ki her yere girdi.

Fakir fukarayı yere devirdi.

Tuttu paramızı pula çevirdi.

Umutlarımızı yıktı enflasyon.

Ne yapsak bilmem ki gelirimiz dar

Ne cepte para var ne avuçta var.

Doymak bilmiyor ki o bir canavar.

Bütün paranızı yedi enflasyon.

Artık yokuşumuz çıkmıyor düze.

Şimdi baharımız dönüştü güze.

Uçak ne kelime sanki bir füze.

Erişilmez hıza çıktı enflasyon.

                 

Düştü endeksimiz tabana vurduk

Hırsıza ceza yok soyulduk durduk.

Sırtımıza bindi ezildik durduk.

Bizi iki büklüm etti enflasyon.', 'Engel tanımıyor kalktı atağa. Evi birbirine kattı eflasyon Kor ateşler gibi düştü mutfağa. Mutfakta ateşi yaktı enflasyon. İğneden ipliğe yi...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/enflasyon-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıl Ermez İşine', 'akil-ermez-i-sine-fahri-bulut-ei3zz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'AKIL ERMEZ İŞİNE

Masum yaşamdan bıkmış, her an ölüm düşlüyor,

Azrail’e yalvarıp, gel canımı al diyor.

Zalimler suç işliyor, suçlu masumdur diyor,

Her devir bir zalimi, masum kulun başına,

Şer ve bela edersin, akıl ermez işine.

Geldi geçti dünyayı, yenileme zamanı,

Lut''un tufanı gibi, bir tufan yap al canı,

Bunu bekliyor mazlum, istiyor çıksın canı,

Her devir bir zalimi, masum kulun başına,

Şer ve bela edersin, akıl ermez işine.

Yer ve gök titretiyor, suçsuzların feryadı,

Fakir aç insanlara, kalmadı yaşam tadı,

Bir başına fetvacı, kara kitaplı kadı,

Her devir bir zalimi, suçsuz kulun başına,

Şer ve bela edersin, akıl ermez işine.

Masumları ağlatır, zalimler güldürürsün,

Günah kar uzun yaşar, günahsız öldürürsün,

Adalet yok dünyanda, dinciyle kandırırsın,

Her devir bir zalimi, suçsuz kulun başına,

Şer ve bela edersin, akıl ermez işine.

Bir de bunun adına, tecelli, kader dersin,

Zalim zulüm kar kulu, dertle zebun etmezsin,

Yılan gibi sürüne, sürüne öldürmezsin,

Her devir bir zalimi, masum kulun başına,

Şer ve bela edersin, akıl ermez işine.

Rızazade, dilsize bir dil olur şairler,

Zalim kulu şiirle, halka şikâyet eyler,

Âşıklarla ve ozanlar, şiiri türkü söyler,

Her devir bir zalimi, masum kulun başına,

Şer ve bela edersin, akıl ermez işine.

17.11.2026

Fahri Bulut Rızazade Gaziantep sabahları…', 'AKIL ERMEZ İŞİNE Masum yaşamdan bıkmış, her an ölüm düşlüyor, Azrail’e yalvarıp, gel canımı al diyor. Zalimler suç işliyor, suçlu masumdur d...', ARRAY['Türk Edebiyatı','Şiir','Fahri Bulut']::text[], 8.5, '{"poet":"Fahri Bulut","poet_slug":"fahri-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/akil-ermez-isine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşmıyorum', 'sasmiyorum-kerim-yavuz-g8rbk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çekti zamlar kamasını.

Deldi garibin tasını.

Biri devlet kasasını.

Soyuyor da şaşmıyorum.

Pahalılık sanki füze.

Baharımız döndü güze.

Enflasyonun hızı yüze.

Çıkıyor da şaşmıyorum.

Vurguncu döşer ağını.

Emer mazlumun yağını.

Esnaf iflas bayrağını.

Açıyor da şaşmıyorum.

Sistemin her yeri yama.

Gene muhtaç olduk sama.

Devlet düşünceyi dama.

Tıkıyor da şaşmıyorum.

Kimi söz eder katından.

Kimi son model yatından.

İşçi memur hayatından.

Bıkıyor da şaşmıyorum.

Bizde yaratanın kulu.

Gözlerimiz sulu sulu.

Kepazelik İstanbul''u.

Sarıyor da şaşmıyorum.', 'Çekti zamlar kamasını. Deldi garibin tasını. Biri devlet kasasını. Soyuyor da şaşmıyorum. Pahalılık sanki füze. Baharımız döndü güze. Enflas...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sasmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki de Son Saatlerimiz', 'belki-de-son-saatlerimiz-ali-taskale-wdb7r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Belki de bu son saatlerimiz,

Belki de tenlerimizin birbirine yazdığı

Son gece mektupları…

Belki de son sevişmelerimiz seninle.

Şimdi,

Seni yine sana bırakıyorum;

Ama bil ki,

İçimde senden arta kalan hiçbir yer

Kendine ait değil artık.

Sürgün etme bu sevmelerimizi,

Bir kentin unutulmuş sokaklarına,

Bir gecenin soğumuş hafızasına…

Gitme,

Kal bizimle;

Henüz kapanmamış bir yaranın

Son sıcaklığı ol.

Belki de telafi edebiliriz

Yaşanmamışlığın küflendirdiği mevsimleri,

Birbirine değememiş günlerimizi,

Dudaklarımızda küllenmiş özlemleri,

Gözlerimizin birbirinden sakladığı

O eski, yaralı baharları…

Gitme, kal,

Erteleme bizi yarınlara;

Yarın dediğin,

Belki de hiç doğmayacak

Bir gecenin yetim sabahıdır.

Gitme, kal,

Bırak zaman kapımızda diz çöksün,

Saatler kendi akrep ve yelkovanını

Birbirine düşman etsin.

Birlikte öldürelim

Bu şehvetli gecelerdeki bedenlerimizi;

Tenlerimizde yeniden doğsun

Bütün ertelenmiş günahlarımız.

Ve sabah,

Eğer mutlaka gelecekse,

Bizi birbirinden ayıran bir vakit değil,

Birbirimizin içinde kaybolmuş

İki sonsuzluğun şahidi olsun.

Ali TAŞKALE

21 Mayıs 2019 | Datça', 'Belki de bu son saatlerimiz, Belki de tenlerimizin birbirine yazdığı Son gece mektupları… Belki de son sevişmelerimiz seninle. Şimdi, Seni y...', ARRAY['Türk Edebiyatı','Şiir','Ali Taşkale']::text[], 8.5, '{"poet":"Ali Taşkale","poet_slug":"ali-taskale","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/belki-de-son-saatlerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elim Mahküm', 'elim-mahkum-kerim-yavuz-hv20r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yokluğunla düştüm dara.

Sensizlik içimde yara.

Hiç bıkmadan ardın sıra,

Koşuyorum elim mahkûm.

Bilesin ismin dilimde.

Sen varsın duygu selimde.

Hasretini yüreğimde,

Taşıyorum elim mahkûm.

Yeter yaramı kaşıma,

İnsaf eyle göz yaşıma.

Engelleri tek başıma,

Aşıyorum elim mahkûm.

Hasretinle düştüm dile.

Gel de tükensin bu çile.

En sıcak havada bile,

Üşüyorum elim mahkûm.

Bedenin benden çok ırak,

Etme bu hasreti bırak.

Umuduma sarılarak,

Yaşıyorum elim mahkûm.', 'Yokluğunla düştüm dara. Sensizlik içimde yara. Hiç bıkmadan ardın sıra, Koşuyorum elim mahkûm. Bilesin ismin dilimde. Sen varsın duygu selim...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/elim-mahkum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamayı seviyorum', 'yasamayi-seviyorum-kerim-yavuz-6qhil', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlığın ortasından,

Mutluluğu görüyorum.

Bunca engellere rağmen,

Yaşamayı seviyorum.

Yaşamak kutsal duygudur .

Yaratanın bir lütfüdur.

Kıymet bilmek ve paylaşmak,

Hayatı sevdiren budur.

İnsanlığa yakışır mı,

Hayata elveda demek.

Zoru yenmek yürek ister,

Korkak işidir pes etmek.

Tabi ki her inişlerin,

Birde yokuşu olacak.

Engel ne olursa olsun,

Umutla aşılır ancak.

Dertlerde kullar içindir,

Gün gelir sarar insanı.

Derdi yenmektir arkadaş,

Hayatın en güzel yanı.

Kuvvetim yüreğimdedir,

Ürkmem nefretin sesinden.

Sorun ne olursa olsun,

Azmim gelir üstesinden.', 'Karanlığın ortasından, Mutluluğu görüyorum. Bunca engellere rağmen, Yaşamayı seviyorum. Yaşamak kutsal duygudur . Yaratanın bir lütfüdur. Kı...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yasamayi-seviyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yön Değiştiren Kan Yön Türkler', 'yon-degistiren-kan-yon-turkler-onder-karacay-esavq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '§

O olumlu kan yön değiştiren bir kandır. Yön Türk olarak bilinir o kanı taşıyan devrimci kadim bilgeler. Yön Türkler doğudan güneş gibi doğar batıda üretilen karanlığı aydınlığa dönüştürür. Atilla''nın, Alparslan''ın ve Fatih Sultan Mehmet han''ın roma zulmünü bitirdiği gibi. Hun Türk Nuh''un tınlanım yasasına uygun tufanı ile insanlığın ikinci başlangıcı başlar Atatürk ile sonsuzluğun devrimi yapılır.  Tüm bu yaşananların mekanı Anadolu zamana mührü vuran ise o kan yön Türklerdir. Son yön Türk ise tınlanım yasasına uygun son kozmik devrimi susuz şer tufanı ile yaşatır yarım kalan devrimi tamamlamak için tinsel varlık bir ahlaka yaşam yolculuğu ile dönüşür. İnsanlık sınavdan sınava geçer yaşattığını yaşayarak uyanan uyanır uyanmayan ürettiği veya destek verdiği kötülüğün altında kalır. 

§

▪️ Önder Karaçay ▪️', '§ O olumlu kan yön değiştiren bir kandır. Yön Türk olarak bilinir o kanı taşıyan devrimci kadim bilgeler. Yön Türkler doğudan güneş gibi doğ...', ARRAY['Türk Edebiyatı','Şiir','Önder Karaçay']::text[], 8.5, '{"poet":"Önder Karaçay","poet_slug":"onder-karacay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yon-degistiren-kan-yon-turkler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönmüyorsun', 'donmuyorsun-kerim-yavuz-zxkiz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dönüşsüz yola mı saptın,

Gittin geri dönmüyorsun.

Gurbeti sılamı yaptın,

Gittin geri dönmüyorsun.

Boynu bükük kaldım böyle.

Sensiz yaşanır mı söyle.

Gel gönlüme insaf eyle,

Gittin geri dönmüyorsun.

Ayrılıkla yanar beden,

Gülmez aşka zulüm eden. 

Elveda bile demeden,

Gitti geri dönmüyorsun.

Ayrılık yarası derin.

Tüketti beni kederin.

Ne mektup var ne haberin.

Gittin geri dönmüyorsun.

Beni ateşlere attın.

Nedir yüreğime kastın.

Sanki sırra kadem bastın.

Gittin geri dönmüyorsun.

Dönmüyorsun, dönmüyorsun.

Şu halimi görmüyorsun.

Göz yaşlarım sele döndü.

Göz yaşımı silmiyorsun.', 'Dönüşsüz yola mı saptın, Gittin geri dönmüyorsun. Gurbeti sılamı yaptın, Gittin geri dönmüyorsun. Boynu bükük kaldım böyle. Sensiz yaşanır m...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/donmuyorsun-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otur Sevgilim Sofraya 2', 'otur-sevgilim-sofraya-2-yakup-han-kilinc-q4qr5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tüm şiirler kademeli 

Telifini ödemeli 

Geldi yüz yılın modeli 

Otur sevgilim sofraya 

Tek bir mısra bile candır 

Bunları yazan insandır 

Ekmeğini aşa bandır 

Otur sevgilim sofraya 

Not: Bu şiir hayal ürünüdür. 

Yakuphan Kılınç', 'Tüm şiirler kademeli  Telifini ödemeli  Geldi yüz yılın modeli  Otur sevgilim sofraya  Tek bir mısra bile candır  Bunları yazan insandır  Ek...', ARRAY['Türk Edebiyatı','Şiir','Yakup Han Kılınç']::text[], 8.5, '{"poet":"Yakup Han Kılınç","poet_slug":"yakup-han-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/otur-sevgilim-sofraya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklerken', 'beklerken-nacar-bucak-drrip', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnerken sokak kedisi basamaklarından zamanın 

Gizlemişti pençelerini patilerinin zarafetinde

Fazla merak getirirdi ya sonunu hayatın 

Etse de merak geliyor son neticesinde

Anlamı yoktur allemin kallemin

Sonsuzluğa uzanan bu merdivenlerde

Başladığın yer ulaştığın yerdir 

Medcezirin hakimi olduğu bu denizde

Bittiği yerde basamak ve merdivenlerin

Düştü kedi hiçliğe 

Sanki değebilirmiş gibi yere

Dört ayağı üstüne', 'İnerken sokak kedisi basamaklarından zamanın  Gizlemişti pençelerini patilerinin zarafetinde Fazla merak getirirdi ya sonunu hayatın  Etse d...', ARRAY['Türk Edebiyatı','Şiir','Naçar Bucak']::text[], 8.5, '{"poet":"Naçar Bucak","poet_slug":"nacar-bucak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/beklerken-156-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyalamayın', 'oyalamayin-kerim-yavuz-fgv4i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İcraat vaat edip oy istediniz.

Yapacağız, edeceğiz dediniz.

Memleketin yıllarını yediniz.

Bizi boş sözlerle oyalamayın.

Kiminiz ak dediniz kiminiz kara.

Kavgada ezildi fakir fukara.

Cebimiz deliktir bağrımız yara.

Bizi boş sözlerle oyalamayın.

Enflasyon kor gibi ateş her yerde.

Yeter çare bulun amansız derde.

Hani verdiğiniz vaatler nerde.

Bizi boş sözlerle oyalamayın.

Eller girmiş iken uzay çağıma.

Beceriksizlerin yandık yağına.

Ülkeyi soktunuz borç batağına

Bizi boş sözlerle oyalamayın.

Kavgamız yok bizim barışımız var.

Medeni dünyayla yarışımız var.

Daha yapılacak çok işimiz var.

Bizi boş sözlerle oyalamayın.

Çağ nereye gitti biz nerde kaldık.

İlim gelişirken gaflete daldık.

Masallarınızdan bıktık usandık.

Bizi boş sözlerle oyalamayın.', 'İcraat vaat edip oy istediniz. Yapacağız, edeceğiz dediniz. Memleketin yıllarını yediniz. Bizi boş sözlerle oyalamayın. Kiminiz ak dediniz k...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/donmuyorsun-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'La mesure qui fait l''humain : justice, bonne opinion d''autrui (hüsnüzan) et responsabilité individuelle', 'la-mesure-qui-fait-l-humain-justice-bonne-opinion-d-autrui-husnuzan-et-responsabilit-individuelle-muhammed-ridvan-gizri-c6nwa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'L''un des problèmes les plus anciens de l''humanité consiste à réduire l''individu à un seul acte, à un seul instant ou à une seule identité, au lieu de le considérer dans sa globalité. Imputer la faute d''une personne à sa famille, à la communauté dont elle fait partie, à sa foi ou à sa nation est une attitude indéfendable, tant sur le plan moral que sur le plan logique. Un regard juste exige au contraire de voir l''être humain comme un être singulier, qui existe par ses propres actes et porte sa propre responsabilité. Nous examinerons ici les ravages du jugement hâtif, des généralisations fondées sur les préjugés et de l''accusation collective, puis la manière dont la morale islamique aborde ces questions.

Le danger du jugement hâtif et de l''étiquetage

Étiqueter durablement une personne à partir d''un seul comportement ouvre de profondes blessures, aussi bien sur le plan individuel que social. Les êtres humains sont complexes et multidimensionnels. Ils peuvent faillir un instant, commettre des erreurs, prendre une mauvaise décision. Mais lorsque cet état passager devient un stigmate immuable censé définir toute l''identité de la personne, nous déformons la vérité et nous commettons une injustice envers elle.

Les recherches en psychologie sociale montrent que les gens ont une tendance connue sous le nom d''« erreur fondamentale d''attribution ». Pour expliquer le comportement des autres, nous négligeons les facteurs situationnels et mettons en avant les traits personnels. Pour nos propres fautes, nous raisonnons à l''inverse et les imputons aux circonstances. Cette asymétrie prépare le terrain à des jugements faussés et injustes sur autrui.

La morale islamique est ici extrêmement claire. Dans le verset 12 de la sourate Al-Hujurât, le Coran interdit explicitement la supposition sans preuve et le préjugé : « Ô vous qui croyez ! Évitez la plupart des soupçons, car une partie des soupçons est un péché. » Ce principe reflète une conception universelle de la justice, qui ordonne d''évaluer l''individu d''après des preuves concrètes et non d''après des suppositions.

Le principe de responsabilité individuelle : chacun porte son propre fardeau

L''une des pierres angulaires du système moral de l''islam est la responsabilité individuelle. Le verset « Aucune âme ne gagne que ce qu''elle fait elle-même, et nulle ne porte le fardeau d''autrui » (Al-An''âm, 164) pose ce principe sans laisser place à la discussion. Le crime d''une personne ne peut être imputé à sa famille, à ses amis, au groupe auquel elle appartient ni à sa foi. C''est une exigence à la fois de la dignité humaine et de la justice divine.

Sur le plan juridique aussi, ce principe a une valeur universelle. Tous les systèmes juridiques modernes ont adopté la présomption d''innocence comme principe fondamental : tant que le crime n''est pas prouvé, la personne est innocente. La profonde convergence entre cette norme universelle et le principe posé par l''islam il y a des siècles, « berâet-i zimmet asıldır » (l''innocence est la règle originelle), montre que cette conception puise dans la raison commune de l''humanité.

Par conséquent, lorsqu''un crime est commis, la question à poser est : « Qu''a fait cette personne ? » et non : « Qui est cette personne, d''où vient-elle, que croit-elle ? » Déplacer le centre de l''enquête de l''individu vers le groupe, c''est renverser la justice.

L''accusation collective : juger une communauté sur la faute d''un seul

Les plus grandes atrocités de l''histoire sont nées de l''accusation de communautés entières plutôt que d''individus. Condamner tout un peuple, une religion ou un groupe ethnique en raison de l''acte d''une seule personne est un schéma familier, hier comme aujourd''hui, et il a chaque fois provoqué de profondes souffrances.

Lorsqu''il s''agit des musulmans, la question devient encore plus brûlante. Attribuer à l''islam tout entier ou à l''ensemble des musulmans les actes fautifs de certains individus est à la fois une erreur intellectuelle et une injustice morale. L''islam est une religion de plus de 1,8 milliard de fidèles, porteuse d''une civilisation profonde de quatorze siècles. Identifier ses enseignements aux actes déformés de quelques individus revient à ignorer son vaste héritage de savoir, de justice, de compassion et de respect de la dignité humaine.

La même logique vaut pour toute communauté. Le crime d''un chrétien ne peut être imputé au christianisme, ni la faute d''un juif au judaïsme, ni l''erreur d''un Turc à toute la nation turque. De telles généralisations nourrissent des préjugés déjà existants et détruisent les ponts de compréhension entre les groupes.

L''illusion du « tout le monde le fait » : le danger de normaliser le mal

L''un des outils les plus courants de l''érosion de la morale sociale est le discours « tout le monde fait comme ça ». Ce discours semble soulager l''individu en diluant la responsabilité morale dans la foule, mais il recèle en réalité un grave danger. La fréquence d''un comportement n''est pas un critère de vérité. Qu''un comportement soit adopté par un grand nombre de personnes ne le rend pas légitime sur le plan moral.

Dans l''histoire, l''esclavage, les bûchers de sorcières et bien d''autres oppressions ont eux aussi été pratiqués par « tout le monde ». Pourtant, cela ne les a jamais justifiés. La morale islamique interdit fermement à l''individu de se réfugier derrière la foule. Même lorsque l''attitude adoptée par la majorité est erronée, l''individu a le devoir de ne pas s''associer à cette erreur, d''élever la voix et, à tout le moins, de la désapprouver dans son cœur.

Le coût social des préjugés et des généralisations

Les généralisations fondées sur les préjugés ne nuisent pas seulement aux individus : elles détruisent profondément le tissu social. Les stéréotypes visant des groupes sèment entre les gens la méfiance, la tension et l''hostilité. Lorsque ces graines germent, elles donnent la discrimination, l''exclusion sociale, le discours de haine et parfois la violence.

Selon la théorie de l''identité sociale, les gens se sentent appartenir à certains groupes et perçoivent la glorification de ces groupes comme celle de leur propre honneur. Cette dynamique engendre une tendance à rabaisser les groupes extérieurs pour élever le sien. Mais céder à cette tendance, c''est à la fois renoncer à sa posture morale individuelle et faire sauter le fondement de la paix sociale. L''islam proclame que l''unité fondamentale de l''humanité et sa diversité ne sont pas une cause de conflit, mais une occasion de se connaître. Cette vision se situe au pôle opposé du préjugé et de la discrimination.

Hüsnüzan : regarder les gens avec bienveillance

Hüsnüzan signifie en arabe « belle supposition » et désigne une vertu importante de la morale islamique. Tendre autant que possible vers une interprétation positive à propos d''une personne, d''une communauté ou d''un événement est le fondement à la fois de la paix intérieure et de la confiance sociale.

Hüsnüzan n''est ni de la candeur ni de la naïveté. Ce n''est pas nier la réalité en dépit des preuves. Au contraire, c''est choisir, en l''absence de preuves, de remplacer la mauvaise pensée par la bonne. Ce choix purifie le cœur de la rancune et du soupçon, construit chaleur et confiance dans les relations et prépare le terrain de la paix sociale. Il invite l''être humain à sortir du cercle perpétuel du soupçon et de l''accusation pour agir avec empathie et compréhension.

D''abord, regarde-toi : la valeur morale de l''autocritique

Il est si facile de critiquer et de juger les autres, et si difficile de se tourner vers ses propres manques. Pourtant, le signe d''une véritable maturité morale est de pouvoir retourner vers soi le doigt pointé vers l''extérieur. La morale islamique y est très attentive. La question « Pourquoi vois-tu la paille dans l''œil de ton frère, et ne remarques-tu pas la poutre qui est dans le tien ? » ne figure pas seulement dans l''Évangile : elle se trouve au cœur de nombreuses religions et traditions de sagesse.

Consacrer à son propre amendement l''énergie que l''on dépense à juger les autres est bien plus fécond, pour le développement personnel comme pour la paix sociale. Cela ne signifie pas se taire devant les torts d''autrui. Dire la vérité et s''opposer au mal est un commandement de l''islam. Mais accomplir ce devoir en jugeant de l''extérieur, sans avoir d''abord demandé des comptes à son propre moi (nafs), c''est à la fois s''éloigner de la sincérité et faire tomber son cœur dans le piège de l''orgueil.

Un regard centré sur la justice

Amour ou haine, proximité ou éloignement : rien de tout cela ne doit éclipser la justice. Le Coran lance à ce sujet un avertissement très net : « Ô vous qui croyez ! Soyez des témoins qui font régner la justice pour Allah ; que la haine envers un peuple ne vous détourne pas de la justice ; cela est plus proche de la piété (*taqwâ*). » (Al-Mâ''ida, 8)

La justice est une mesure qui s''exerce indépendamment de la sympathie ou de l''antipathie. Fermer les yeux sur la faute de celui que l''on aime, ou condamner injustement celui que l''on n''aime pas, c''est dans les deux cas s''écarter de la justice. Un véritable sens de la justice exige de l''individu qu''il soit attaché à un principe supérieur à son intérêt et à ses sentiments. Ce principe se trouve au cœur non seulement de l''islam, mais aussi de la morale humaine universelle. La célèbre image de la justice aux yeux bandés, non par aveuglement mais par impartialité, symbolise l''idéal d''un jugement neutre, indépendant des émotions. Bâtir une véritable société humaine n''est possible que si cet idéal est intériorisé, aux niveaux individuel comme institutionnel.

Ne pas se hâter de juger autrui, éviter d''imputer la faute d''une personne à son groupe, s''abstenir de toute supposition sans preuve et cultiver la bonne opinion d''autrui : ce ne sont pas seulement des commandements religieux, mais aussi des principes moraux universels auxquels est parvenue la raison commune de l''humanité. Le sens de la responsabilité individuelle supprime le confort de se cacher derrière les foules et fait porter à chacun sa part. La justice, elle, est une mesure indépendante de l''amour comme de la haine, fondée sur la seule vérité.

Le socle d''une société saine est constitué d''individus sans préjugés, de personnes qui s''évaluent mutuellement avec bienveillance et de ceux qui savent appliquer la justice avec courage, même envers leurs proches. Bâtir ce socle ne passe pas par l''effort de changer l''extérieur, mais par le courage, pour chacun, de se regarder d''abord honnêtement en face.', 'L''un des problèmes les plus anciens de l''humanité consiste à réduire l''individu à un seul acte, à un seul instant ou à une seule identité, a...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/la-mesure-qui-fait-l-humain-justice-bonne-opinion-d-autrui-husnuzan-et-responsabilite-individuelle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hıyarın İşine Bak', 'hiyarin-i-sine-bak-kerim-yavuz-eerfr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Farkında değil amma mezarını kazıyor.

Her işi ayrı bir pot hıyarın işine bak.

Uslanacağı yerde her geçen gün azıyor.

Eceline susamış hıyarın işine bak.

Adı dillere düştü herkes onu tanıyor.

Kim saçma bir iş görse hemen onu anıyor.

Başını kuma gömmüş görünmezim sanıyor.

Beden açıkta kalmış hıyarın işine bak.

İçmiş sabaha kadar yalpalıyor dizleri.

Kudurmuş köpek gibi kan çanağı gözleri.

Adeta saçmalıyor belli değil sözleri.

Kayıp etmiş kendini hıyarın işine bak.

Beş tane çocuğu var bir tanesi de yolda.

Üçü orta okullu biride ilkokulda.

Bütün kazandığını tüketti sağda solda.

Uçkur düşkünü olmuş hıyarın işine bak.

Aklınca çevresini makaraya sarıyor.

Ne eşine dostuna ne kendine yarıyor.

Leş kokusu içinde gül kokusu arıyor.

Pusulayı şaşırmış hıyarın işine ba

Her gece bir alemde bitiriyor pilini.

Eşek arısı soksun ağzındaki dilini.

Perukla kapatıyor başındaki kelini.

Hem de makyaj yapıyor hıyarın işine bak', 'Farkında değil amma mezarını kazıyor. Her işi ayrı bir pot hıyarın işine bak. Uslanacağı yerde her geçen gün azıyor. Eceline susamış hıyarın...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hiyarin-isine-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımdasın', 'aklimdasin-kerim-yavuz-xrfb6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Zannetme ki ayrılık sildi seni içimden.

Dün gibi aklımdasın inan yaram kanıyor.

İsmin yağmurlar gibi dökülürken dilimden.

Adını andığım an inan içim yanıyor.

Kör olsun ayrılığı aşkımıza yazanlar.

Kör olsun aşkımızın kuyusunu kazanlar.

Anılarımız yine gülümsüyor maziden.

Silinmez yüreğimden seninle yaşananlar.

Sudan bahanelere kurban ettiler bizi.

Kirletmeye kalktılar tertemiz sevgimizi.

Bedenen ayrılsak da ruhunla içimdesin.

Silinmez yüreğimden bu aşkın derin izi.', 'Zannetme ki ayrılık sildi seni içimden. Dün gibi aklımdasın inan yaram kanıyor. İsmin yağmurlar gibi dökülürken dilimden. Adını andığım an i...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aklimdasin-147-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebebi Sensin', 'sebebi-sensin-kerim-yavuz-5wbmw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Söyle ey vefasız insanlık bu mu.

Beni terk edip de çekip gidensin.

Şimdi benziyorum bir serseriye.

Perişan halimin sebebi sensin.

Sen benim aşkıma vermedin değer.

Beni aldatmakmış niyetin meğer.

Böyle yaşamaktan bıkmışsam eğer.

Hayata küsmemin sebebi sensin.

Bu bana yaptığın aşk ile hile.

Beni deli edip düşürdün dile.

Gözlerimden yaşlar dönüştü sele.

Akan gözyaşımın sebebi sensin.

Kanıma dokundu kurduğun tuzak.

Artık mutluluklar benden çok uzak.

Efkârım tepemde saçlarımda ak.

Saçımda akların sebebi sensin.

Bilmem ki ben şimdi nasıl edeyim.

Sızlayıp duruyor gönül direğim.

Ayrıldık sözüyle yandı yüreğim.

Yürek yangınımın sebebi sensin.

Yıllardır avuttun beni boş yere.

Bana yaptığını düşün bir kere.

Sırdaş ettin beni düşüncelere.

Çektiğim çilenin sebebi sensin.', 'Söyle ey vefasız insanlık bu mu. Beni terk edip de çekip gidensin. Şimdi benziyorum bir serseriye. Perişan halimin sebebi sensin. Sen benim ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sebebi-sensin-157-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oldu Mu', 'oldu-mu-servet-balibey-linds', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürür adımlarım 
Bilinmez bir 
sensizliğe 
Çıkar çıkmaz yolum
Olmadığın 
geleceğe

Oldu mu sen söyle 
Nerdesin ben nerde
Olur mu ayrılık 
Severken öylece 
 

Aksın gözyaşlarım 
Gözlerimden 
ardın sıra 
Yıksın tüm bentleri
Götürsün 
kapısına


Hangi söz hangi göz
Avutur ki şu kalbimi 
Hangi kalp taşır İnan
Bende ki izlerini', 'Yürür adımlarım  Bilinmez bir  sensizliğe  Çıkar çıkmaz yolum Olmadığın  geleceğe Oldu mu sen söyle  Nerdesin ben nerde Olur mu ayrılık  Sev...', ARRAY['Türk Edebiyatı','Şiir','Servet Balıbey']::text[], 8.5, '{"poet":"Servet Balıbey","poet_slug":"servet-balibey","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oldu-mu-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Güzelin Yasına', 'bir-guzelin-yasina-kerim-yavuz-p2jmh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğimden kopar gelir duygular,

Akar gider bir güzelin yasına.

Kara toprak aldı nazik bedeni,

Henüz girmemişken yirmi yaşına.

Sardı beni ayrılığın kolları,

Akar gözlerimden inci taneler.

Bir güzeli gelin verdim toprağa,

Acısı ok gibi bağrımı deler.

Mezarından fışkıran bir çiçek var,

Bilirim ki, yardan bana hediye.

Göz yaşımla sularım toprağını,

O da kendi gibi solmasın diye.

Son dileğin nedir sorsalar bana,

Mezarında taş olmayı isterim.

Allah''ıma saygım arım olmazsa,

Asarım kendimi ona giderim.', 'Yüreğimden kopar gelir duygular, Akar gider bir güzelin yasına. Kara toprak aldı nazik bedeni, Henüz girmemişken yirmi yaşına. Sardı beni ay...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-guzelin-yasina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sosyal Medya', 'sosyal-medya-yakup-han-kilinc-0h51o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Onlarca sosyal medyada 

Ölenlerin emeği var 

Gece yarısı uykuyu 

Bölenlerin emeği var 

Bestesini yayınlayıp 

Parasını da kazanıp 

Şiirleriyle bezenip 

Gülenlerin emeği var 

Yakuphan Kılınç', 'Onlarca sosyal medyada  Ölenlerin emeği var  Gece yarısı uykuyu  Bölenlerin emeği var  Bestesini yayınlayıp  Parasını da kazanıp  Şiirleriyl...', ARRAY['Türk Edebiyatı','Şiir','Yakup Han Kılınç']::text[], 8.5, '{"poet":"Yakup Han Kılınç","poet_slug":"yakup-han-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sosyal-medya-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçime Sinmiyor Böyle Yaşamak', 'i-cime-sinmiyor-boyle-yasamak-kerim-yavuz-n489w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her gün damla damla tükeniyorum.

Beni bitiriyor böyle yaşamak.

Acılara karşı direniyorum.

İçime sinmiyor böyle yaşamak.

Yüzümde çizgiler saçlarımda ak.

Kader bana kurdu kahpe bir tuzak.

Ve bir yıldız gibi dünyadan uzak.

İçime sinmiyor böyle yaşamak.

Bu yalan dünyaya geldim geleli.

Ağır ödüyorum ben bedeli.

Bu dert tuzağına düştüm düşeli.

İçime sinmiyor böyle yaşamak.

Yaşamak isterdim bende baharı.

Lâkin hazandayım yüzüm sapsarı.

Çevreme örülmüş çile duvarı.

İçime sinmiyor böyle yaşamak.

Ha bugün ha yarın gülerim derken.

Yorgun düştüm mutluluğu ararken.

Dışarıda mis gibi bir bahar varken.

İçime sinmiyor böyle yaşamak.

Mum gibi eridim göz göre göre.

Göz yaşlarım oldu çağlayan dere.

Boynumu bükmüşüm zalim kadere.

İçime sinmiyor böyle yaşamak.', 'Her gün damla damla tükeniyorum. Beni bitiriyor böyle yaşamak. Acılara karşı direniyorum. İçime sinmiyor böyle yaşamak. Yüzümde çizgiler saç...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/icime-sinmiyor-boyle-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyvah', 'eyvah-kerim-yavuz-e1asd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Susuz kaldı bu sıra bu cennet gibi vatan.

Susamış derelerde boğuluyoruz eyvah!

Vurguncuya göz kırptı millete şaşı bakan.

Kendi vatanımızda soyuluyoruz eyvah!

Sokaklara döküldük korkular cebimizde.

Kıstılar sesimizi isyanlar elimizde.

Özgürlüğün bedeli morarmış belimizde.

Coplarla sopalarla dövülüyoruz eyvah!

Her şey maddiyat olmuş haberimiz yok meğer.

Parayla ölçülüyor cana verilen değer.

Cebimizdeki para rüşvet kokmazsa eğer.

Devlet kapılarından kovuluyoruz eyvah!

Vatanı karış karış parsellemişler çoktan.

Trilyoner zenginler türemişler hiç yoktan.

Millet iradesinin fışkırdığı noktadan.

Kendi bıçağımızla oyuluyoruz eyvah!', 'Susuz kaldı bu sıra bu cennet gibi vatan. Susamış derelerde boğuluyoruz eyvah! Vurguncuya göz kırptı millete şaşı bakan. Kendi vatanımızda s...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eyvah-239-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Karanlığı Saçlarını Dokusun', 'gecenin-karanligi-saclarini-dokusun-kasim-kobakci-gqa8p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzaklardan süzülen gemiler yorgun düşmüş,

Bırak bu ıssız sahil karanlıkta uyusun,

Gecenin örtüsüyle bütün dertler örtülmüş,

Tahtaların üstünde zaman usulca dursun.

*

Sisin içinde yiten o eski tahta liman,

Gözlerini kapatıp daldığında her zaman,

Denizden yükseliyor hafif tatlı bir duman,

Mırıldanan dalgalar kıyıya yavaş vursun,

*

Suların ninnisiyle serinliyor bak tenin,

Gölgelerin içinde gizleniyor bedenin,

Uykunun kollarına bırakılmış her yerin,

Bırak rüzgar ruhunu kötülükten korusun.

*

Kıyıdan uzaklaşan ufuktaki şu keder,

Gözlerinin önünden usulca kayıp gider,

Gece yarısı sessiz tüm acıların biter,

Kapanan kirpiklerin rüyaları okusun.

*

Rüyalarda açılmış denize doğru yollar,

Seni sarıp sarmalar görünmez ılık kollar,

Sakinliğe bürünmüş fısıldayan rüzgarlar,

Kayan yıldız tozları o uykunu solusun.

*

Sularda çözülüyor yıldızlı bir bilmece,

Dudağından dökülür uykuda sessiz hece,

Üzerine çöküyor pamuktan ılık gece,

Ayın gümüş ışığı yatağına kurulsun.

*

Eski tahtalar üstünde kalmadı artık iz,

Uykunun aleminde yapayalnız kaldık biz,

Beşik gibi sallanıp ninniler okur deniz,

Huzur veren dalgalar başucunda otursun.

*

Gözlerin kapanıyor sularla yavaş yavaş,

Geceyle bütünleştin uykudur sana sırdaş,

Dalgaların köpüğü rüyalarına kardaş,

Ruhun derin denizin kollarında yorulsun.

*

Düşünceler dağılıp uçup gitsin çok uzak,

Ruhunu ısıtıyor denizde ılık kucak,

Kayan bütün yıldızlar uyurken sana tutsak,

İçindeki ateşler de sularla savrulsun.

*

Göz kapakların ağır uykun oluyor tamam,

Eski tahtalar üstüne son buluyor akşam,

Rüyaların içinde yeşersin yeni yaşam,

Gecenin karanlığı saçlarını dokusun.', 'Uzaklardan süzülen gemiler yorgun düşmüş, Bırak bu ıssız sahil karanlıkta uyusun, Gecenin örtüsüyle bütün dertler örtülmüş, Tahtaların üstün...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/gecenin-karanligi-saclarini-dokusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçti Gitti O Nadir Yıllar', 'gecti-gitti-o-nadir-yillar-i-lknur-cekici-31ct8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne varsa kalbimde saf olan , senden kalan

Sildim attım içimden , düştün artık gözümden 

Tükendi hayallerim , kışa döndü baharlarım

Bir yabancı el oldun , boşa giden sel oldun

Tutunduğum dal idin , koptun ziyan oldun

Seni koşulsuz seven ,yollarını bekleyen

En mavi hayalleri , senin uğruna gören

Her sözüne güvenen , bendim seni seven

Bu saatten sonra gelsen , bize ne olur  ?

Yaşattığın yalanı silsen maziden , nasıl olur ?

Unuturmuyum olanları , inanırmıyım sevgiylen

Aşk ile mutlulukla , sana koşarmıyım yeniden

Bu saatten sonra ne kapıma gel dayan , 

Ne arkamdan bak da , hüzünle sen yan

Geçti gitti o Nadir , sevildiğin yıllar 

Söndü küle döndü , içimdeki korlar', 'Ne varsa kalbimde saf olan , senden kalan Sildim attım içimden , düştün artık gözümden  Tükendi hayallerim , kışa döndü baharlarım Bir yaban...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecti-gitti-o-nadir-sevildigin-yillar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Compassion et responsabilité envers les animaux', 'compassion-et-responsabilit-envers-les-animaux-muhammed-ridvan-gizri-2o4tt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tous les êtres vivants de la terre existent par la création d''Allah et mènent leur vie dans l''ordre qu''Il a établi. De même que l''être humain est une créature précieuse créée par Allah, les animaux sont des êtres vivants qui reflètent l''art d''Allah, dotés de caractéristiques, de besoins et de modes de vie qui leur sont propres. Le Coran n''enseigne pas à l''homme de se prévaloir d''une supériorité sur les autres créatures, mais d''agir avec un sens de la responsabilité, car chaque être vivant créé par Allah est une manifestation de Sa puissance et de Sa miséricorde. Dans le verset 38 de la sourate Al-An''âm, Allah dit :

« Il n''est point de bête qui marche sur terre, ni d''oiseau qui vole de ses deux ailes, qui ne forment des communautés semblables à vous… »

Ce verset montre clairement que les animaux ne sont pas de simples êtres sans valeur, destinés uniquement à servir les humains. Eux aussi, comme les hommes, forment des communautés, avec leur propre organisation, leurs modes de communication, leurs structures sociales et le mode de vie qu''Allah a déterminé pour eux. Aujourd''hui, les recherches scientifiques montrent que de nombreuses espèces animales possèdent des systèmes de communication élaborés, des liens familiaux, des comportements d''entraide et même des réactions émotionnelles telles que le deuil. Cette réalité contribue à faire comprendre la vérité divine que le Coran a annoncée il y a des siècles.

Le Coran rappelle aussi que les animaux sont pour les hommes d''importants bienfaits. Dans plusieurs versets, Allah informe les êtres humains qu''ils peuvent tirer profit des animaux de diverses manières. Se nourrir de leur viande, profiter de leur lait, de leur laine et de leur peau, utiliser leur force pour porter des charges et se déplacer, tout cela fait partie des bienfaits qu''Allah a accordés aux hommes. Dans le verset 5 de la sourate An-Nahl, il est dit :

« Et il a créé les bestiaux : vous y trouvez de quoi vous réchauffer et d''autres avantages, et vous en mangez. »

Dans la même sourate, il est également précisé que les animaux portent des fardeaux, facilitent les déplacements des hommes et procurent de nombreux autres avantages qui rendent la vie plus aisée. Le Coran n''interdit donc pas de tirer profit des animaux ; au contraire, il indique qu''il s''agit d''un des bienfaits qu''Allah offre à l''homme. Toutefois, le principe fondamental posé par le Coran est le suivant : bénéficier d''un bienfait ne donne pas le droit de se montrer injuste envers lui. L''homme n''est pas un maître irresponsable sur la terre, mais un serviteur tenu d''agir dans les limites fixées par Allah. C''est pourquoi, en tirant profit des animaux, il faut toujours conserver la compassion et la justice.

Faire souffrir un animal sans nécessité, l''affamer, le priver d''eau, le torturer, lui nuire pour se divertir ou le tuer pour le simple plaisir est incompatible avec l''éthique islamique, car Allah a interdit l''injustice. L''injustice ne se commet pas seulement envers les êtres humains : tout être vivant maltraité sans raison est lui aussi victime d''une injustice.

Le Coran ordonne fréquemment à l''homme de ne pas semer la corruption sur terre. Polluer l''environnement, détruire les habitats naturels, provoquer l''extinction d''espèces animales ou adopter des comportements qui rompent l''équilibre écologique doivent également être considérés comme relevant de cette interdiction. En effet, Allah a créé l''univers selon une mesure et un équilibre précis, et l''homme a le devoir de préserver cet équilibre.

Faire preuve de compassion envers les animaux ne se limite pas à les nourrir. Veiller à leur santé, leur offrir des lieux de vie propres, empêcher la propagation des maladies, protéger leur vie et répondre à leurs besoins font aussi partie de cette responsabilité. Ceux qui possèdent un animal de compagnie doivent le considérer non comme un objet, mais comme un être vivant qu''Allah leur a confié en dépôt. De la même manière, les animaux d''élevage ou de charge ne sont pas de simples instruments de profit économique : ils ont eux aussi droit au repos, à la nourriture et à un bon traitement.

La conception de la compassion enseignée par le Coran ne se limite pas aux relations entre les êtres humains. La miséricorde d''Allah embrasse toutes les créatures. Pour mériter sa part de cette miséricorde divine, l''homme doit à son tour se montrer bienveillant envers tous les êtres vivants créés par Allah. Que le fort fasse preuve de compassion envers le faible est l''un des principes fondamentaux de l''éthique coranique. Même s''ils ne peuvent pas parler, les animaux ressentent la douleur, éprouvent la peur, se fatiguent et veulent vivre. Ainsi, toute compassion qu''on leur témoigne est en réalité un respect envers l''être vivant qu''Allah a créé.

Dans le monde moderne, l''industrialisation, la chasse inconsidérée, la destruction des espaces naturels et la pollution menacent la vie de millions d''animaux. La conscience du dépôt confié (l''amâna) que le Coran met en avant revêt aujourd''hui une importance plus grande que jamais. L''homme ne peut pas agir en ne pensant qu''à son propre intérêt : il est tenu de veiller aussi aux droits des générations futures et des autres êtres vivants.

En conclusion, le Coran n''attribue pas aux animaux un caractère sacré qui les soustrairait entièrement à l''usage de l''homme, et il ne les considère pas non plus comme des êtres sans valeur. Ce sont des créatures d''Allah, des communautés comme celles des hommes, qui vivent selon l''ordre établi par Allah. Allah a permis aux hommes d''en tirer profit, mais Il a limité cet usage par les principes de la compassion, de la justice et de la responsabilité. Par conséquent, l''attitude juste pour un musulman consiste à considérer les animaux comme un dépôt d''Allah, à ne pas leur infliger de souffrances inutiles, à veiller à leurs besoins, à respecter leur droit à la vie, à protéger l''environnement et à faire de la compassion le principe en toute circonstance. Car chaque être vivant créé par Allah est une preuve de Sa puissance, ainsi qu''un bienfait et une responsabilité pour l''homme. Dans la mesure où l''homme s''acquitte de cette responsabilité, il honore le dépôt d''Allah et agit conformément à l''éthique qu''enseigne le Coran.', 'Tous les êtres vivants de la terre existent par la création d''Allah et mènent leur vie dans l''ordre qu''Il a établi. De même que l''être humai...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/compassion-et-responsabilite-envers-les-animaux-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Ne Olur', 'gitme-ne-olur-kerim-yavuz-wk5ih', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensiz mutluluklar çok uzak bana.

Beni mutsuzluğa itme ne olur.

Gönül bağı ile bağlandım sana.

Bırakıp da gitme, gitme ne olur. 

Mutluluk değil mi aşkın emeli.

Aşksız yaşayana kalpsiz demeli.

Umutlarımın sensin temeli.

Bırakıp da gitme, gitme ne olur.

Dünya benim olur sende seversen.

Yanar kül olurum eğer gidersen.

Daha iflah olmam elveda dersen.

Bırakıp da gitme, gitme ne olur.

Dargın düşer inan hayatla aram.

Kapanmaz gönlümde kanayan yaram.

Sensiz yaşamak mı vallahi haram

Bırakıp da gitme, gitme ne olur.

Seven ayrılıktan hiç söz eder mi.

Gönülden sevenler cefa çeker mi.

Sensiz yaşamaya gücüm yeter mi.

Bırakıp da gitme, gitme ne olur.

Gözümde yaşların işi olmasın.

Gönül bahçemdeki güller solmasın.

Hasretin ateşi beni yakmasın.

Bırakıp da gitme, gitme ne olur.', 'Sensiz mutluluklar çok uzak bana. Beni mutsuzluğa itme ne olur. Gönül bağı ile bağlandım sana. Bırakıp da gitme, gitme ne olur.  Mutluluk de...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gitme-ne-olur-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tribine nazına, hayranım bakışına', 'tribine-nazina-hayranim-bakisina-kamile-i-lbey-zlla6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Verse 1

Yollarını gözlerim, gülleri sererim.

Kimselere bakma sakın, kız nasibin benim.

Aklım gider aklına, aşkın düştü bağrıma,

Bana varmazsan eğer kaçırırım vallaha.

Yollarını gözlerim, gülleri sererim.

Kimselere bakma sakın, kız nasibin benim.

Aklım gider aklına, aşkın düştü bağrıma,

Bana varmazsan eğer kaçırırım vallaha.

        Pre chorus

 Tribine,nazına o güzel bakışına.

Kurban olurum,saçlarının karasına.

Tıkır tıkır yürüyüşüne, işvene cilvene.

Deli oluyorum, seni her gördüğümde

        Chorus

Tribine,nazına o güzel bakışına.

Kurban olurum,saçlarının karasına.

Tıkır tıkır yürüyüşüne, işvene cilvene.

Deli oluyorum, seni her gördüğümde

            Verse 2

Boyuna, endamına bir ben değil alem hasta.

Yanıyorum her dakika ,bir adım at bana,

Gönlüm durmaz senden yana,

Kaçma güzelim yaklaş bana,

          Final

  Tribine,nazına o güzel bakışına.

Kurban olurum,saçlarının karasına.

Tıkır tıkır yürüyüşüne, işvene cilvene.

Deli oluyorum, seni her gördüğümde', 'Verse 1 Yollarını gözlerim, gülleri sererim. Kimselere bakma sakın, kız nasibin benim. Aklım gider aklına, aşkın düştü bağrıma, Bana varmazs...', ARRAY['Türk Edebiyatı','Şiir','Kamile İlbey']::text[], 8.5, '{"poet":"Kamile İlbey","poet_slug":"kamile-i-lbey","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/tribine-nazina-hayranim-bakisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Etme Gurbet', 'etme-gurbet-kerim-yavuz-5pwet', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllar oldu düştüm senin eline.

Etme gurbet çok özledim sılamı.

Ben köyümü dolamışım dilime.

Etme gurbet etme bırak yakamı.

Babamın mezarı dua bekliyor.

Bütün sevdiklerim bana gel diyor.

Kora düştü gönlüm her gün eriyor.

Etme gurbet etme bırak yakamı.

Köyümün hasreti içimi bürür.

Bütün hayallerim sılaya yürür.

Çok sürmez bu hasret beni öldürür.

Etme gurbet etme bırak yakamı.

Sende şaşırmışım sağım solumu.

Mahkûm gibi bağlamışsın kolumu.

Sana neyledimde kestin yolumu.

Etme gurbet etme bırak yakamı.

Etme gurbet etme bırak yakamı.

Daha fazla deşme gönül yaramı.

Köyümün hasreti tüketti beni.

Laik görme bana figanı gamı.

Ozan Kerim der ki: Gamlıdır sinem.

Yeter artık göz yaşlarımı silem.

Bir yol ver de köy yolunda görünem.

Etme gurbet etme bırak yakamı.', 'Yıllar oldu düştüm senin eline. Etme gurbet çok özledim sılamı. Ben köyümü dolamışım dilime. Etme gurbet etme bırak yakamı. Babamın mezarı d...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/etme-gurbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözler 2', 'sozler-2-alp-kaan-aksu-5zy6n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İman varsa ,imkan da vardır.', 'İman varsa ,imkan da vardır....', ARRAY['Türk Edebiyatı','Şiir','Alp Kaan Aksu']::text[], 8.5, '{"poet":"Alp Kaan Aksu","poet_slug":"alp-kaan-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/sozler-2-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nokta Nokta', 'nokta-nokta-kerim-yavuz-1g1o3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Artık ayar tutmuyor bozuldu düzenimiz.

Kimi sefil perişan kiminin karnı tokta.

Allah''tan başkasına kalmadı güvenimiz.

Feryadımıza sessiz kalana nokta nokta.

Boğuyorsunuz bizi kendi havuzumuzda.

Tadımız yoktu zaten yok oldu tuzumuzda.

Ne cepte para kaldı ne de avucumuzda. 

Vatandaşı kaz gibi yolana nokta nokta.

Delindikçe delindi fakirin çorba tası.

Umurlarında değil vatandaşın tasası.

Elbet sizi de tutar mazlumun  bedduası.

Mazlumların ahını alana nokta nokta.

Kimi vurgunu vurup yurt dışına kaçıyor.

Kimisi dolarları çevresine saçıyor.

Kimide kemerine hala delik açıyor.

Memleketin malını çalana nokta nokta.

Çaresizliğe düşüp nice sürünenler var.

Çalıp çırpıp yinede masum görünenler var.

Aslında diken olup güle bürünenler var.

İki yüzlü  riyakâr olana nokta nokta.

Gerçekleri söyledim kim isterse alınsın.

İster yalan desinler ister suskun kalınsın.

İsterseler bedenim ilmiklerde salınsın.

Dürüst olmalı herkes yalana nokta nokta.', 'Artık ayar tutmuyor bozuldu düzenimiz. Kimi sefil perişan kiminin karnı tokta. Allah''tan başkasına kalmadı güvenimiz. Feryadımıza sessiz kal...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nokta-nokta-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orgueil et humilité : l''épreuve de l''homme face à lui-même et à l''univers', 'orgueil-et-humilit-l-preuve-de-l-homme-face-lui-m-me-et-l-univers-muhammed-ridvan-gizri-6vu53', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tout au long de l''histoire, philosophes, théologiens et penseurs de la morale ont désigné l''une des plus grandes faiblesses de l''être humain par un seul et même concept : l''orgueil (kibir). Loin d''être un simple défaut de caractère individuel, il apparaît comme un facteur déterminant dans l''effondrement des civilisations, la dégradation des relations et l''éclatement des sociétés. Il demeure le plus grand obstacle sur le chemin de la connaissance de soi. L''orgueil, c''est se gonfler d''importance, mépriser et dédaigner autrui, s''admirer soi-même, se tenir pour supérieur aux autres. Cette définition montre qu''il ne se réduit pas à un comportement visible : c''est une attitude intérieure aux racines profondes. Face à lui, l''humilité (tevazu) est la vertu placée au cœur de la morale islamique et formulée comme la réponse la plus puissante à l''orgueil. Nous verrons ici ce qu''est l''orgueil, ce qui le nourrit, quels ravages il cause à l''individu et à la société, et pourquoi l''humilité n''est pas seulement une vertu, mais aussi une manière d''être.

Anatomie de l''orgueil : qu''est-ce que c''est, et qu''aveugle-t-il ?

L''orgueilleux se glorifie des biens, du rang, des talents, du savoir et des autres bienfaits qu''il possède, et se juge supérieur et privilégié par rapport aux autres. Plus dangereux encore, il s''imagine que ces bienfaits n''existent que chez lui et qu''il ne les perdra jamais. Ce dernier point constitue la dimension la plus destructrice de l''orgueil : l''illusion de permanence. Attribuer entièrement à soi-même des bienfaits éphémères (statut, propriété, savoir ou talent) et croire qu''on les possédera éternellement engendre une profonde cécité qui coupe l''homme de la vérité. L''histoire regorge d''exemples de ceux qui ont chèrement payé cet aveuglement : les dynasties les plus puissantes se sont effondrées, les plus grandes fortunes se sont dispersées, les esprits les plus brillants se sont effacés avec le temps. Malgré cela, à toutes les époques, l''être humain a eu tendance à oublier le caractère passager de ce qu''il possède.

Une autre dimension de l''orgueil est la distorsion cognitive. Le sentiment de grandeur nous empêche de voir la réalité telle qu''elle est. L''orgueilleux ne supporte pas la critique, car elle touche au trône qu''il s''est bâti. Il rejette le retour d''information, car celui-ci affaiblit sa prétention à la supériorité. Il se ferme aux points de vue différents, car les admettre reviendrait à reconnaître ses propres manques. Dans ce cercle vicieux, l''orgueilleux rapetisse à mesure qu''il croit grandir, et s''éloigne de la véritable sagesse à mesure qu''il paraît savant.

La voie ouverte par Satan : l''origine métaphysique de l''orgueil

L''orgueil est une voie que Satan a ouverte dans l''histoire de l''humanité. Cette qualification n''est pas une métaphore choisie au hasard. Dans l''islam, le premier acte d''orgueil est le suivant : lorsque Allah créa Adam, il ordonna aux anges et à Iblis de se prosterner devant lui. Iblis refusa d''obéir et dit : « Je suis meilleur que lui : tu m''as créé de feu et tu l''as créé d''argile. » Ce refus n''est pas une simple désobéissance, mais une comparaison et une prétention à la supériorité. Autrement dit, l''orgueil renferme, en son essence, une comparaison : je vaux plus que lui. C''est pourquoi celui qui s''enorgueillit suit les traces de Satan et entrouvre en même temps une porte menant à la mécréance (küfür).

L''idée que l''orgueil entrouvre la porte du kufr (le fait de voiler la vérité, l''ingratitude) est d''une grande justesse. Car l''orgueil est, en définitive, une forme d''ingratitude : ignorer le véritable propriétaire de tout ce que l''on possède, oublier la source des bienfaits, considérer son existence comme le fruit de son seul mérite. Tout cela relève d''une attitude qui cherche à recouvrir la vérité de la création. Sous cet angle, l''orgueil n''est pas seulement une faiblesse morale, mais aussi une révolte contre la finalité de la création et contre la vérité. Le poids moral si lourd qu''il porte l''éloigne des simples défauts de caractère et en fait une question existentielle, directement liée à l''être, à la question du sens et à ce que l''homme est.

Le miroir du Coran : « Tu ne peux fendre la terre ni atteindre les montagnes »

> « Ne marche pas sur terre avec arrogance : tu ne peux fendre la terre ni atteindre les montagnes en hauteur. » (Sourate al-Isrâ'', verset 37)

Le langage de ce verset est d''une grande netteté. L''image de celui qui marche avec arrogance ne désigne pas seulement une attitude physique : elle symbolise toute une posture de vie. Et la phrase qui suit rappelle la finitude de l''homme par deux exemples concrets : tu ne peux fendre la terre, tu ne peux atteindre les montagnes. Aussi puissant, riche ou savant soit-il, l''homme reste petit, fragile et éphémère face à l''immense échelle de la nature. La terre sous nos pieds porte l''accumulation de milliards d''années ; les montagnes qui lui font face se dressaient bien avant l''histoire humaine et se dresseront bien après elle.

Ce verset n''offre pas à l''homme une humiliation, mais une perspective. Celui qui connaît ses limites use plus sagement des moyens qui lui sont accordés. Au lieu de se vanter de son savoir, il en admet les bornes ; au lieu de s''enorgueillir de sa position, il en assume la responsabilité.

L''humilité : non pas la pusillanimité, mais la maturité

Il faut bien comprendre le concept d''humilité, opposé à l''orgueil. Être humble, ce n''est ni être pusillanime ni manquer de confiance en soi. C''est au contraire posséder une maturité et un équilibre intérieurs qui permettent d''accepter la vérité, le droit et la justice tels qu''ils sont. Cette distinction est capitale. Se faire plus petit qu''on ne l''est constitue aussi une forme de mensonge : une fausse modestie ne saurait remplacer la véritable humilité. La véritable humilité consiste, pour l''homme, à connaître sa propre valeur sans s''en servir comme d''un instrument de domination sur les autres. Être doux lorsqu''on est fort, rester ouvert à l''apprentissage lorsqu''on est savant, tenir les gens pour égaux lorsqu''on occupe une position respectée : voilà les manifestations concrètes de l''humilité dans la vie.

La position du musulman dans ce cadre est frappante : au lieu de s''enorgueillir des moyens dont il dispose, il les partage avec autrui. Il sait que tous les bienfaits qui lui sont accordés sont une grâce d''Allah, et il remercie son Seigneur qui les lui a octroyés. La gratitude (şükür) ne se limite pas ici à un remerciement verbal : elle se manifeste par le bon emploi du bienfait, c''est-à-dire par son partage et par le service rendu à l''humanité. Ainsi l''humilité cesse d''être un simple état intérieur pour devenir une vertu sociale.

La métaphore de la branche : le signe de la vraie maturité

« Comme les arbres qui, à mesure que leurs fruits mûrissent, courbent leurs branches vers le sol pour en offrir aux gens, les croyants dotés de raison, de savoir et de sagesse deviennent humbles. » Cette image résume l''essence de l''humilité avec une admirable simplicité. La branche vide reste droite ; la branche chargée de fruits se courbe. Il en va de même de l''homme : celui qui est creux fait du bruit et s''exprime en prenant de grands airs ; celui qui déborde véritablement se penche, donne, partage.

Le vrai savoir, la raison et la sagesse ne conduisent pas l''homme à se donner de l''importance, mais à servir la société, à partager et à se rendre utile. Devenir plus humble à mesure que ses titres ou ses moyens augmentent est le plus grand signe d''une véritable compétence. Dans l''histoire, les plus beaux exemples de ce modèle se trouvent chez les messagers (rasûl), qui ont consacré généreusement leur savoir et leur temps à l''humanité.

Égalité et justice : la destruction sociale causée par l''orgueil

Le musulman sait que tous les êtres humains sont égaux devant Allah et devant la loi, et que la supériorité ne se mesure que par la piété (takva). Il ne blâme, ne méprise ni ne dénigre personne en raison de sa naissance, de sa race, de sa couleur, de sa famille, de sa profession ou de ses moyens matériels. Ce principe a valeur de manifeste universel de justice et de droits humains.

C''est précisément ici qu''intervient la dimension sociale de l''orgueil : celui de l''individu se transforme, à l''échelle de la société, en discrimination, en exclusion et en oppression hiérarchique. Les prétentions de supériorité raciale, la discrimination de classe, le mépris professionnel, l''exclusion économique : tout cela n''est rien d''autre que l''orgueil individuel agrandi à l''échelle de la société. Faire de la piété le seul critère de supériorité fait voler en éclats toutes ces hiérarchies artificielles. La piété est conscience de la responsabilité, vertu et proximité de la vérité. Elle ne s''achète pas et ne se transmet pas par héritage : elle ne s''acquiert qu''en la vivant. La famille où tu es né, la langue que tu parles, la couleur que tu portes, la fortune que tu produis : rien de cela ne peut, à lui seul, être un critère de valeur. Cette perspective constitue le fondement théologique de la justice sociale.

L''homme devant le miroir

Le choix entre orgueil et humilité tient, au fond, à la façon dont l''homme se voit lui-même. Celui qui se place au centre de la réalité, qui pense mériter ce qu''il possède et le garder à jamais, tombe dans le piège de l''orgueil. Celui qui se considère comme un dépositaire, qui sait que ce qu''il possède est une grâce et que cette grâce appelle le partage, marche dans l''ample liberté de l''humilité.

« Tu ne peux fendre la terre ni atteindre les montagnes » : ce rappel n''est pas donné pour rapetisser l''homme, mais pour lui faire retrouver sa véritable grandeur. Car la vraie grandeur ne consiste pas à se proclamer grand, mais à faire grandir les autres, à embrasser la vérité et à s''attacher non à ce qui passe, mais à ce qui demeure. Comme la branche qui plie sous le poids du fruit mûr : plus tu donnes, plus tu es béni.', 'Tout au long de l''histoire, philosophes, théologiens et penseurs de la morale ont désigné l''une des plus grandes faiblesses de l''être humain...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/orgueil-et-humilite-l-epreuve-de-l-homme-face-a-lui-meme-et-a-l-univers-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygularımı Geri Ver', 'duygularimi-geri-ver-kerim-yavuz-fxh14', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Duygularımı gasp edip gönlümü öksüz bıraktın.

Hırsız, seni arıyorum, duygularımı geri ver.

Hiç yüreğin titremeden, beni ateşlere attın.

Alev alev yanıyorum, duygularımı geri ver.

Ne olursun anla beni yaşayamam ben onlarsın.

Onlar tertemiz duygular onlar suçsuz ve günahsız.

Duy yüreğimin sesini olma bu kadar insafsız.

Karaları bağlıyorum duygularımı geri ver.

Bir gün, bir ay, bir yıl değil senelerin birikimi.

Bu duyguların yoluna heder etmişim kendimi.

İçime kapandım durdum aşamıyorum bendimi

Gece gündüz ağlıyorum duygularımı geri ver.

Onlar yüreğimin sesi sana hibemi edeyim.

Kelimeler kifayetsiz bilmem sana ne diyeyim.

Anlamıyorsun halimden sabrımın son demindeyim.

Boynu bükük yaşıyorum duygularımı geri ver.', 'Duygularımı gasp edip gönlümü öksüz bıraktın. Hırsız, seni arıyorum, duygularımı geri ver. Hiç yüreğin titremeden, beni ateşlere attın. Alev...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/duygularimi-geri-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutuştu Duygularım', 'tutustu-duygularim-kerim-yavuz-coroo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kıvılcımın yetti tutuştu duygularım.

Aşkının ateşine yanıyorum güzelim.

Göz kapaklarım dargın bölündü uykularım.

İnsafsız hasretinle yaşıyorum güzelim.

Titredi damarlarım gözlerine bakınca.

Beni de diz çöktürdü o şiddetli depremin.

Aşkın volkanlar gibi yüreğime akınca.

Yaktı kül etti beni insafsız cehennemin.

Hep peşinde koşmaktan düşmüş olsam da dile.

Sana uzanan yoldan geri dönmeyeceğim.

Merhametsiz hasretin beni tüketse bile.

Yeminim var güzelim başka sevmeyeceğim.

Rüzgarlara kat yolla o ılık nefesini.

Ardına kadar açtım bütün pencereleri.

Ne olur anla beni duy kalbimin sesini.

Üstüme salma benim insafsız geceleri.

Bunu şimdi anladım aşk tutuşmakmış meğer.

Bütün arzularımla yandım tutuştum sana.

Bu aşka bir karşılık vermeyeceksen eğer.

Hedef yüreğim olsun bir kurşun yolla bana.', 'Bir kıvılcımın yetti tutuştu duygularım. Aşkının ateşine yanıyorum güzelim. Göz kapaklarım dargın bölündü uykularım. İnsafsız hasretinle yaş...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tutustu-duygularim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuzey''in Çocukları', 'kuzey-in-cocuklari-kerim-yavuz-xulbf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir bölge var yurdumda Sakarya dan Artvin''e.

İşte burada yaşar kuzeyin çocukları.

Arasan bulamazsın yer yok nefrete kine.

Sevgiyle dolup taşar kuzeyin çocukları.

Vatan sevgisi sarar benliğini özünü.

Haksızlık gördüğünde esirgemez sözünü.

Namerdin çirkin yüzü korkutamaz gözünü.

Çelik yürekli olur kuzeyin çocukları.

Denizde izleri var yosun kokan ağların.

Gülümseyen yüzü var o yemyeşil dağların.

İzlerine rastlarsın tarih kokan çağların.

Zengin kültürle yaşar kuzeyin çocukları.

Bin bir güzellik vardır yayla şenliklerinde.

Kemence sesi duyan duramıyor yerinde.

Bütün aşık gençlerin duyguları derinde.

Sevdi mi candan sever kuzeyin çocukları.

Otantik bir lisanla süslenmiştir dilleri.

Sevdirir benliğini tertemiz yürekleri.

Azmi kuvvet bilirler bükülmez bilekleri.

Tuttuğunu koparır kuzeyin çocukları.

Sevgi bir damla değil sanki çağlayan dere.

Hadi sizde buyurun sevgi olduğu yere.

Doyumsuz mutluluğu sizde tadın bir kere.

Size de kucak açsın kuzeyin çocukları.', 'Bir bölge var yurdumda Sakarya dan Artvin''e. İşte burada yaşar kuzeyin çocukları. Arasan bulamazsın yer yok nefrete kine. Sevgiyle dolup taş...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kuzey-in-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'La colère : l''épreuve de la nature innée et l''équilibre des émotions', 'la-col-re-l-preuve-de-la-nature-inn-e-et-l-quilibre-des-motions-muhammed-ridvan-gizri-ncl3i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'L''être humain est la somme de ses émotions. Joie, tristesse, peur, espoir et colère… aucune d''elles n''existe par hasard : toutes sont des mécanismes intérieurs qui font de l''homme un être humain, le rattachent à la vie et le protègent. Parmi ces émotions, la colère est peut-être la plus mal comprise, la plus instrumentalisée et la moins bien gérée. Elle est innée et fait partie intégrante de la nature humaine (fitra). Admettre cette réalité est la première étape pour établir avec elle un rapport sain. Car tenter de nier la colère, de l''ignorer ou de la réprimer en toutes circonstances n''est ni possible ni sain. La colère réprimée finit par se transformer en anxiété, en dépression et en tension intérieure chronique. Le problème n''est pas l''existence de la colère, mais la manière de la gérer.

Deux extrêmes dangereux : l''absence de colère et la colère excessive

Il existe deux attitudes erronées face à la colère, et toutes deux présentent de sérieux dangers pour l''être humain.

La première est l''absence de colère. À première vue, elle peut passer pour une vertu, et certains y voient même un signe de maturité ou de tolérance. En réalité, elle conduit à rester spectateur de l''injustice, à plier devant l''oppression, à la lâcheté et à l''avilissement. Un homme qui ne réagit à rien et ne dit mot devant aucune injustice n''incarne pas la justice sociale, mais la passivité. La défense de la religion, de l''honneur, de la patrie et de l''équité exige une colère saine et légitime. Dans la défense de ces valeurs sublimes, la colère devient une force morale.

La seconde est la colère excessive. Une colère incontrôlée et démesurée mène à l''oppression, au meurtre, à la brutalité et à des ravages difficilement réparables. À l''origine de bien des meurtres, rixes, foyers détruits, rancunes profondes et séparations de la vie quotidienne, on trouve un instant de colère incontrôlée. Après cette réaction brève et intense, l''homme éprouve de grands regrets, mais il est parfois trop tard : une parole prononcée ne peut être reprise, et un cœur brisé ne peut pas toujours être réparé.

C''est précisément ici que l''approche de l''islam à l''égard de la colère se révèle pleine de sagesse et d''équilibre : ni supprimer la colère, ni s''y abandonner. La voie du milieu consiste à la maîtriser.

Les causes de la colère

Pour gérer la colère, il faut d''abord la comprendre. En examinant les principaux facteurs qui mettent l''être humain en colère, on constate qu''à la base de la plupart d''entre eux se trouvent la vulnérabilité, la peur ou l''impuissance.

La frustration est l''une des sources les plus courantes de colère. Ne pas parvenir à atteindre un objectif, ou voir ses désirs constamment entravés, engendre une profonde déception qui, avec le temps, se transforme en colère.

Le sentiment d''être victime d''une injustice est aussi un puissant déclencheur. La conviction d''être traité injustement crée une voix intérieure qui légitime la colère. Ce sentiment est parfois fondé, parfois issu d''une erreur de perception.

La peur et l''anxiété sont le visage invisible de la colère. Elle est souvent un bouclier de défense : lorsqu''ils se sentent faibles ou sans défense, les gens tentent de se protéger par une attitude agressive. Autrement dit, un éclat soudain et violent est en réalité le reflet d''une peur enfouie.

La fatigue et le stress chronique abaissent nettement le seuil de la colère. Le manque de sommeil, un rythme de travail intense et les pressions accumulées poussent à réagir durement même à des situations mineures qui, en temps normal, n''auraient pas d''importance.

Les expériences passées jouent également un rôle déterminant. Les façons d''exprimer la colère observées pendant l''enfance, en particulier, peuvent être reproduites inconsciemment à l''âge adulte. L''enfant d''un parent qui exprimait sa colère en criant ou par la violence aura tendance, en grandissant, à perpétuer les mêmes schémas.

Enfin, les attentes non satisfaites sont l''une des sources de colère chroniques les plus répandues de la vie moderne. Des attentes toujours plus élevées envers les autres comme envers la vie entraînent des déceptions et, par conséquent, de la colère.

Les moyens de gérer la colère

La colère n''est pas une émotion incontrôlable. Avec une intention juste et un effort conscient, elle peut être largement maîtrisée, tant sur le plan individuel que social.

Premier pas : prendre conscience de sa colère. Pouvoir dire « En ce moment, je suis en colère » est l''étape de conscience la plus décisive pour éviter que cette émotion ne vous submerge. Nommer la colère ralentit considérablement sa transformation en réaction instinctive et automatique.

Faire de l''optimisme un principe. Le moyen le plus profond d''éviter la colère est d''aborder la vie et les événements avec un regard optimiste. Savoir interpréter chaque situation en bien et considérer les choses sous leur aspect positif nourrit la paix intérieure. Une bonne pensée dans l''esprit et une belle parole sur la langue rendent l''homme heureux et serein. À l''inverse, les mauvaises pensées et les paroles dures fatiguent avant tout celui qui les porte, plus encore que la personne qu''elles visent.

Chercher refuge auprès d''Allah. Dans la religion musulmane, l''un des principaux moyens de vaincre la colère est de chercher refuge auprès d''Allah au moment où elle survient. Ce n''est pas seulement un acte religieux, mais aussi une profonde pause psychologique : l''être humain s''arrête un instant, respire et s''élève à une perspective supérieure.

Se taire. Sous l''effet de la colère, on ne peut pas penser juste. La conscience s''obscurcit, le jugement s''affaiblit et l''on réagit le plus souvent de manière excessive. Lorsqu''on est en colère, il faut d''abord maîtriser sa langue, se taire et attendre que les nerfs s''apaisent, puis parler en veillant à la justice : cela protège à la fois les relations et la conscience. Bien des regrets naissent précisément de paroles prononcées là où il aurait fallu se taire.

Quitter les lieux. S''éloigner physiquement, pour un court moment, de l''endroit où l''on se trouve permet de se couper des éléments déclencheurs. Ce geste simple peut briser le cycle d''escalade de la colère.

Respirer profondément. Inspirer par le nez pendant environ 4 secondes, puis expirer lentement pendant 6 à 8 secondes agit directement sur le système nerveux. Cette technique, à la fois scientifique et pratique, atténue l''intensité physiologique de la colère.

Se laver les mains et le visage, ou faire les ablutions. La colère tend le système nerveux et augmente la chaleur du corps. Se laver les mains et le visage à l''eau froide, faire ses ablutions ou prendre une douche détend cette tension physiologique et apaise l''esprit. Cette pratique est soutenue à la fois par l''enseignement islamique traditionnel et par la psychophysiologie moderne.

Remettre ses pensées en question. Une fois sorti du moment de colère, se poser les questions suivantes peut changer beaucoup de choses : M''a-t-on vraiment insulté ? Suis-je en train d''exagérer l''événement ? L''autre personne pourrait-elle avoir eu une autre intention ou une autre explication ? Le plus souvent, la plus grande partie de la colère se dissout une fois la situation envisagée sous un autre angle.

Se concentrer sur le problème, non sur la personne. Dire « Ce comportement m''a dérangé » plutôt que « Tu es toujours comme ça » est à la fois plus constructif et évite de mettre l''autre sur la défensive. Accuser la personne aggrave le conflit ; parler du problème prépare le terrain à une solution.

Bouger physiquement. Une marche rapide, la course ou tout autre exercice aide à évacuer par des voies physiologiques les hormones de stress qui montent pendant la colère, notamment le cortisol et l''adrénaline. À mesure que le corps bouge, l''esprit s''assouplit.

Veiller au sommeil et à l''alimentation. La faim, un sommeil irrégulier et un excès de caféine abaissent le seuil de colère à notre insu. Préserver l''équilibre du corps pose les bases de l''équilibre de l''esprit.

Demander un soutien professionnel si nécessaire. Si la colère sort fréquemment de tout contrôle, affecte gravement les relations et la vie professionnelle, ou risque de dégénérer en violence physique, demander l''aide d''un psychologue ou d''un psychiatre est une démarche qui demande du courage et qui est tout à fait appropriée. Demander de l''aide n''est pas une faiblesse, mais une marque de maturité.

La frontière subtile entre réprimer et gérer la colère

Gérer la colère et la réprimer sont deux choses très différentes. La colère réprimée ne disparaît pas : elle se retourne simplement vers l''intérieur. Avec le temps, elle peut se manifester sous forme d''anxiété, de dépression, de tensions corporelles et de maladies chroniques. Le but n''est pas d''effacer l''émotion, mais de pouvoir l''exprimer de manière contrôlée et sans nuire. Une expression saine de la colère soulage l''individu tout en transmettant à l''autre un message respectueux.

La perspective du Coran : réprimer sa colère et pardonner

Le Coran présente la maîtrise de la colère comme une haute vertu morale. Dans le verset 134 de la sourate Al-Imran, il est dit :

« Ceux qui dépensent dans l''aisance comme dans la gêne, qui répriment leur colère et pardonnent aux gens. Allah aime les bienfaisants (muhsinîn). »

Ce qui frappe dans ce verset, c''est l''expression « réprimer » (littéralement « avaler ») la colère. La colère n''est pas niée : son existence est reconnue. Mais l''absorber, la digérer et neutraliser ainsi son potentiel destructeur est présenté comme une haute maturité morale. Le pardon est en outre désigné comme le sommet de cette maturité, et ce tableau est couronné par la bonne nouvelle qu''Allah aime les muhsinîn, c''est-à-dire ceux qui se conduisent avec excellence.

Reconnaître la colère, être conscient plutôt qu''impulsif

La colère est l''épreuve commune de l''humanité. À chaque époque, sous chaque latitude, cette émotion puissante qui habite chaque être humain représente, lorsqu''elle est bien utilisée, la justice, le courage et l''honneur. Mal utilisée, elle ouvre les plaies les plus profondes de l''histoire. L''enjeu n''est pas de fuir la colère, mais d''entretenir avec elle un rapport conscient. Faire de l''optimisme un principe, chercher refuge auprès d''Allah, savoir se taire, écouter les signaux du corps et demander de l''aide au besoin : telles sont les pierres angulaires de ce chemin. Celui qui sait maîtriser sa colère offre un présent non seulement à lui-même, mais aussi à tous ceux qui l''entourent : un climat de paix, de justice et de pardon. Dans un tel climat, les individus comme les sociétés peuvent bâtir une vie plus humaine et plus digne.', 'L''être humain est la somme de ses émotions. Joie, tristesse, peur, espoir et colère… aucune d''elles n''existe par hasard : toutes sont des mé...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/la-colere-l-epreuve-de-la-nature-innee-et-l-equilibre-des-emotions-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyahsınız', 'siyahsiniz-durmus-ali-eker-rp1fw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'tükürsem tükrük kirlenir

sahi insanmısınız siz

siyahtan da siyahsınız ----

müslüman sandık sizi biz

-------------

hepimizi aldatınız

 bizimle  namaz kıldınız

siyoniste yem oldunuz

sşyahtan bda siyahsınız

----------

faizi helalm kıldınız

  devleti bir bir  soydunuz

 halkı enayisaydınız

siyatan da siyahsınız

 -----------

kimliğiniz   bilinmiyor

  ne derlerse alnmyor

 sülün osnan biliniyor

siz ondan da siyahsınız

-----------

yahudiye dost oldunuz

 siz paraya kul  oldunuz

itibarda pul oldunuz

 siyahtanda siyahsunuz

---------

vicdan siyah saçınız ak

utanmıyoruz der ahmak

 düştüğünüz duruma bak 

 gecedenb de siyahsınız

------

 adalt yok ahlak kayıp

hırsızlık  yapmamak ayıp !

 öksüzü yetimi soyup

 siyah    renten siyahsıız

----------

kimi  arsa kimi borsa

altınız da  binek   forsa

  bun iktidar bir dönerse

 siyahtan da siyahsınız

--------

  din dediniz  kin çıktınız

 fors dediniz fon çıktınız

 hırsızlıknda   pir  çıktınız

beyazdan   siyah çıktınız

---------

  hesabınız tutar sasnma

 makam mevkiye inanma

 iiki metre  birçukurda

kesenize kalır sanma

---------

 kimi cinmci kimi foncu

 yitirdiniz mi  inancı

baş örtülü fatna bacı

siyah   alnın  oncu   buncu

--------

size  artık kar etmez söz 

 dünyayı yeseniz  az

 iblis  günaha  hiç doymaz

 ak ndediniz   nsiyahsınız', 'tükürsem tükrük kirlenir sahi insanmısınız siz siyahtan da siyahsınız ---- müslüman sandık sizi biz ------------- hepimizi aldatınız  biziml...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Ali Eker']::text[], 8.5, '{"poet":"Durmuş Ali Eker","poet_slug":"durmus-ali-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/siyahsiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ummanlarda Dert Salapurya', 'ummanlarda-dert-salapurya-kasim-kobakci-cef76', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En karanlık ufkun yası uyuşsun,

Islak rüzgarların sesi buluşsun,

Kızıl şafakların kanı tutuşsun,

Dilsiz gökyüzünün hüznü konuşsun.

*

Ne yolcuyu bekler ne liman arar,

Sonsuz köpükleri gözüyle tarar,

Zaman hep ahşap gövdesini yorar,

Her damla tuz ona derdini sorar.

*

Solgun sislerin içinde bir duman,

Bu yorgun tekneye acımaz zaman,

Kara dalgaların öfkesi yaman,

Fırtına vurunca vermez hiç aman.

*

Meçhullere sessizce akıp gider,

Tahtasına sinmiş tükenmez keder,

Parçalanmış yelken rüzgarı iter,

Bu sonsuz karanlık ne zaman biter.

*

Dertlidir gecenin o ıssız koyu,

Sürükler yükünü asırlar boyu,

Kimseler bilemez bu garip huyu,

Gözyaşıyla dolar denizin suyu.

*

Çatlakları sızlar üşür hep derin,

Rüzgarın nefesi buz gibi serin,

Yorgun direğinde hüznü var yerin,

Islak ağıtları düşmüş göklerin.

*

Sulara gömülmüş umutlar yavaş,

Kendi kaderiyle eder hep savaş,

Rüzgarsız havada sular tek sırdaş,

Her dalga köpüğü sancıya kardaş.

*

Denizin kalbine sessiz bir akış,

Yıldızsız semadan hüzünlü bakış,

Tahtaya işlenmiş dert nakış nakış,

Meçhule uzanmış bu dilsiz çıkış.

*

Sonsuza doğru açılırken deniz,

Ardında kalmıyor silik ince iz,

Bu garip tekneyle yolculukta biz,

Karanlık sularda saklanmış her giz.

*

Bitmeyen yollara serilmiş derya,

Görülmez burada hiç de bir rüya,

Yalanmış umutlar silinmiş güya,

Durgun ummanlarda dert salapurya.', 'En karanlık ufkun yası uyuşsun, Islak rüzgarların sesi buluşsun, Kızıl şafakların kanı tutuşsun, Dilsiz gökyüzünün hüznü konuşsun. * Ne yolc...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/ummanlarda-dert-salapurya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atatürk''ün Çocukları', 'ataturk-un-cocuklari-kerim-yavuz-z2r5o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önce vatan diye diye Samsun da meşale yandı.

Esareti ret ederek ulusumuz ayaklandı.

Gülümsedi bayrağımız nazlı nazlı dalgalandı.

Al bayrağın bekçisidir Atatürk''ün çocukları.

Mustafa Kemal Atatürk hedefi halka gösterdi.

Kadın erkek genç ihtiyar birlikte elel verdi.

Binlerce şehit ve gazi bağımsızlık böyle geldi.

Hürriyetin bekçisidir Atatürk''ün çocukları.

Çağdaş bir ülke kurmaktı ulu önderin niyeti.

Cumhuriyetimiz oldu düşüncenin nihayeti.

Toplumun temel hakkıdır din ve vicdan hürriyeti.

Laikliğin bekçisidir Atatürk''ün çocukları.

Uygarlığı hakim kılmak hepimizin görevidir.

Ülkemde yaşayan her fert gururluyum demelidir.

Atamın inkılâpları çağdaşlığın temelidir.

Devrimlerin bekçisidir Atatürk''ün çocukları.

Kurban oluruz Türkiye''m senin Türk kokan adına.

Cumhuriyet ile vardık demokrasinin tadına.

Hakim oldu hür düşünce ülkemin her noktasına.

Özgürlüğün bekçisidir Atatürk''ün çocukları.

Gururla övünsün halkım asil bir Türk olduğuna.

Vatan millet sevgisini aşılasın çocuğuna.

Zerresine göz koyanı pişman eder doğduğuna.

Bu vatanın bekçisidir Atatürk''ün çocukları.', 'Önce vatan diye diye Samsun da meşale yandı. Esareti ret ederek ulusumuz ayaklandı. Gülümsedi bayrağımız nazlı nazlı dalgalandı. Al bayrağın...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ataturk-un-cocuklari-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ölmediğim Kaldı', 'bir-olmedigim-kaldi-kerim-yavuz-8qttb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep mutluluk aradım güneşin doğuşunda.

Lakin gülmedi yüzüm çileler koğuşunda.

Hiç tükenmek bilmeyen bu hayat yokuşunda.

Öyle yordu ki kader, bir ölmediğim kaldı.

Yüreğim paramparça çile dolu her yeri.

Apansız bu dertlere tutulduğumdan beri.

Ömrümün baharında yüreğime hançeri,

Öyle vurdu ki kader, bir ölmediğim kaldı.

Sanki ben, ben değilim unutturdu adımı.

Her saat biraz daha kaçırıyor tadımı.

Hiç insaf eylemeden kolumu, kanadımı,

Öyle kırdı ki kader, bir ölmediğim kaldı.

Umurunda değilim, bakmaz akan yaşıma.

Sanki bütün zehrini kattı benim aşıma.

Beni hedef alıp da kaya gibi başıma,

Öyle düştü ki kader, bir ölmediğim kaldı.

Harabeye çevirdi gönlümdeki sarayı.

Mutluluk benden uzak, açtı benden arayı.

Yüreğimi kaplayan bu kapanmaz yarayı.

Öyle deşti ki kader, bir ölmediğim kaldı.

Tükendim bittim artık almadan vere vere.

Darbeler bir değil ki darbeler yüz bin kere.

Yüreğimden tutup da kaldırıp yerden yere,

Öyle vurdu ki kader, bir ölmediğim kaldı.', 'Hep mutluluk aradım güneşin doğuşunda. Lakin gülmedi yüzüm çileler koğuşunda. Hiç tükenmek bilmeyen bu hayat yokuşunda. Öyle yordu ki kader,...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-olmedigim-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaban Gülüm', 'yaban-gulum-kerim-yavuz-1betg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne olursun dön gel artık kendini saklama benden.

Hep seni haykırıyorum, ismin düşmüyor dilimden.

Aşkın ile tutuşmuşum, anlamıyorsun halimden.

İçimde ateş gibisin, yanıyorum yaban gülüm.

Rüzgarlar kasıga gibi, esiyor gönül bağıma.

Hayatın baharındayım, insaf et gençlik çağıma.

Aşkını ırmaklar gibi, bırakı ver toprağıma.

Susuz kalmış çiçek gibi, kuruyorum yaban gülüm.

Söyle bana aşk çiçeğim, ben sensiz nasıl yaşarım.

Yeter çektiğim bu hasret, tükensin haykırışlarım.

Yağmur bulutları gibi, boşalıyor göz yaşlarım.

Yokluğunda gece gündüz, ağlıyorum yaban gülüm.

Sensiz geçen her anıma, lanet olsun yüz bin kere.

İnan ki kahroluyorum, sensiz yok olan günlere.

Ellerim koynumda şimdi, boyun bükmüşüm kadere.

Buna yaşamak denirse, yaşıyorum yaban gülüm.', 'Ne olursun dön gel artık kendini saklama benden. Hep seni haykırıyorum, ismin düşmüyor dilimden. Aşkın ile tutuşmuşum, anlamıyorsun halimden...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaban-gulum-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Répondre au mal par le bien', 'r-pondre-au-mal-par-le-bien-muhammed-ridvan-gizri-0dltx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tout au long de l''histoire de l''humanité, l''une des dynamiques les plus fondamentales qui assurent la pérennité des sociétés est le sentiment de confiance mutuelle et de bienveillance entre les individus. C''est dans la conception morale de l''islam que ce sentiment trouve son expression la plus élevée. En effet, l''islam ne considère pas l''être humain uniquement comme un être juridique, mais aussi comme un sujet moral, et il lui indique dans la beauté du caractère la voie de l''élévation en ce monde et dans l''au-delà. La dimension peut-être la plus difficile et la plus précieuse de cette conception du bon comportement est la capacité de répondre au mal par le bien. Nous examinerons ici cette vertu en profondeur, dans le cadre des valeurs fondamentales de l''islam.

La source du bien : l''intention pure et l''agrément divin

Dans la conception morale de l''islam, la valeur d''un acte se mesure non seulement à son apparence extérieure, mais avant tout à l''intention qui l''engendre. Lorsque le bien est accompli dans l''attente d''une contrepartie, par souci de prestige social ou comme un investissement utile pour l''avenir, il s''éloigne de son essence et perd sa valeur. Le véritable bien est celui qui est accompli uniquement pour obtenir l''agrément d''Allah, sans aucune attente d''ordre terrestre. Le Coran exprime cette vérité ainsi : « Nous ne vous nourrissons que pour l''agrément d''Allah ; nous n''attendons de vous ni récompense ni remerciement. » (al-Insân, 9). Ce verset offre le plus beau tableau de l''intention pure et du bien désintéressé. Faire le bien sans contrepartie témoigne que l''être humain a dépassé son âme instinctive (*nafs*) et s''est paré des attributs moraux divins. La nature humaine, en effet, tend à vouloir recevoir en retour ce qu''elle donne. Parvenir à surmonter cette inclination est un signe de maturité et de profondeur. Lorsqu''un croyant fait le bien, il en attend la récompense non pas des hommes, mais d''Allah, et cette attente ne le décevra jamais. Ainsi, le bien cesse d''être le maillon d''un cycle d''échanges et devient un acte sublime qui porte son sens en lui-même.

La vertu de rendre le bien reçu

Tout en définissant le bien désintéressé comme la plus haute vertu, l''islam fait aussi un devoir de répondre au bien reçu par la gratitude et la fidélité. Rester insensible au bien que l''on nous fait n''est pas seulement un manque de courtoisie humaine : cela revêt également une dimension d''ingratitude envers le divin. Répondre à un bien reçu par un bien semblable, c''est à la fois reconnaître la valeur de ce bien et perpétuer la chaîne de la bienfaisance. Lorsqu''il n''est pas possible de rendre ce bien matériellement, un remerciement sincère suffit, du point de vue de l''accomplissement de la dette de fidélité, et revêt une grande importance. Ainsi, le sentiment de confiance mutuelle et de reconnaissance, qui est le fondement de la solidarité sociale, se transmet de génération en génération.

La valeur unique de répondre au mal par le bien

Le sommet le plus difficile et le plus précieux de la morale islamique est sans aucun doute la capacité de répondre par le bien à celui qui nous a fait du mal. Ce comportement n''est pas un bien ordinaire : c''est une vertu extraordinaire, qui exige de surmonter la colère, le ressentiment et le désir de vengeance enracinés dans les couches les plus profondes de l''âme. Le Coran pose à ce sujet un principe d''une grande force : « Le bien et le mal ne sont pas égaux. Repousse le mal par ce qui est meilleur, et voilà que celui avec qui tu avais une inimitié devient comme un ami chaleureux. » (Fussilat, 34). La vérité exprimée dans ce verset renvoie à une réalité psychologique très profonde. Lorsqu''une personne reçoit du bien de quelqu''un à qui elle a fait du mal, cette réponse inattendue fait fondre tous les sentiments négatifs de son cœur. L''hostilité cède la place à l''étonnement, puis, avec le temps, au respect et à l''affection. L''histoire comme la vie quotidienne en offrent d''innombrables exemples. Celui qui répond au mal par le bien a le pouvoir de transformer l''autre et de semer entre deux personnes non pas l''inimitié, mais la graine de l''affection. C''est la méthode de changement la plus efficace et la plus durable dans les relations sociales. Par ailleurs, les bienfaits ordinaires peuvent s''oublier avec le temps, alors que le bien accompli malgré le mal reçu laisse dans l''esprit et le cœur de celui qui en bénéficie une trace indélébile. Car un tel bien n''est pas une simple pratique de politesse, mais une extraordinaire leçon d''humanité. Celui qui l''a vécue en garde, toute sa vie, le souvenir de ce moment et de cette personne.

La force de la patience : la voie de la résistance au mal

Dans l''islam, la patience n''est pas une endurance passive, mais une forme de résistance active et consciente. Face aux ignorants, Allah guide ainsi les croyants : « Les serviteurs du Tout-Miséricordieux sont ceux qui marchent sur terre avec humilité et qui, lorsque les ignorants s''adressent à eux, disent : "Paix !" » (al-Furqân, 63). Ce verset nous enseigne que répondre au mal au même niveau n''est pas une solution, et que la véritable humiliation consiste au contraire à descendre au niveau de l''autre. Dans le cours de la vie quotidienne, il est inévitable de croiser des personnes incompréhensives, agressives ou grossières. À ces moments-là, deux voix s''élèvent à l''intérieur de l''être humain. L''une est celle de l''âme instinctive, celle de la colère et de la vengeance, qui paraît bien plus facile en pratique. L''autre est celle de la raison et de la foi, la voix qui choisit la patience, le calme et la dignité. Ce que l''islam demande, c''est précisément la maturité nécessaire pour écouter cette seconde voix. Celui qui atteint cette maturité a protégé son monde intérieur et conduit avec sagesse ses relations sociales. La patience est aussi l''art de maîtriser la colère.

Pardonner : la plus haute force

Le maillon le plus éclatant de la chaîne du bien face au mal est le pardon. Le pardon n''est pas une marque de faiblesse, mais au contraire la manifestation d''une grande force intérieure et d''une maturité spirituelle. Le Coran évoque le pardon avec éloge : « Quiconque pardonne et réconcilie, sa récompense incombe à Allah. » (ash-Shûrâ, 40). Lorsque la douleur causée par le mal est mise en balance avec le pardon et la rétribution d''Allah, on voit qu''elle prend un sens : elle devient une épreuve qui fait mûrir l''être humain et l''élève. Le pardon est une vertu extrêmement utile, tant sur le plan individuel que social. Au niveau individuel, il libère l''être humain du fardeau spirituel que créent la colère et le ressentiment. Celui qui garde en lui ses rancœurs porte en réalité un lourd fardeau sur le dos ; pardonner, c''est le déposer. Au niveau social, le pardon répare les ponts brisés, réchauffe les relations refroidies et prévient l''usure du tissu social. Les liens de parenté constituent à cet égard un terrain particulièrement sensible. Les petites rancœurs qui s''accumulent avec le temps, les malentendus et le manque de communication peuvent creuser de profonds fossés entre parents. Combler ces fossés dépend souvent du pas de pardon que l''une des parties fera avec courage. Seul un caractère fort et vertueux est capable de faire ce pas.

Le coût social de répondre au mal par le mal

La réaction qui paraît la plus facile et la plus séduisante pour l''âme humaine est de rendre le mal à l''identique. Cette réaction peut procurer un soulagement momentané, mais à long terme elle détruit les relations, affaiblit les liens sociaux et éloigne l''être humain de ses propres valeurs. De plus, celui qui répond au mal par le mal descend au niveau de celui qui avait tort au départ, ce qui lui ôte sa supériorité morale. Le coût social de cette riposte dépasse de loin le cadre des relations individuelles. Les petits conflits entre individus peuvent se transformer en différends de longue durée entre des familles et des communautés. Or le croyant vertueux porte la responsabilité de briser ce cercle vicieux. Son attitude n''influence pas que lui-même : elle touche aussi son entourage et prépare le terrain à un climat de justice, de confiance et de compassion dans la société.

Le beau caractère est une question de choix

La conception islamique du bon comportement ordonne de faire le bien sans contrepartie, de répondre par la gratitude aux bienfaits reçus, de répondre aux torts par la patience et le pardon, et de ne pas descendre au niveau des ignorants. Toutes ces vertus élèvent l''être humain non seulement dans l''au-delà, mais aussi en ce monde : elles lui apportent la paix dans son monde intérieur et font de lui un être digne de confiance et respecté au sein de la société. Répondre au mal par le bien n''est pas un réflexe ordinaire, mais un choix conscient. Ce choix ne s''appuie pas sur la colère, mais sur la sagesse ; non sur la satisfaction immédiate, mais sur des beautés durables. Pour pouvoir faire ce choix, il faut une foi solide, une volonté ferme et une profonde maturité intérieure. Telle est précisément la qualité que l''islam attend du musulman et qui le distingue des autres : le courage et la maturité de choisir non pas ce qui est facile, mais ce qui est beau. Le beau caractère est une valeur universelle, qui approfondit le lien de l''individu avec Allah, mûrit ses relations avec les autres et rend la société dans laquelle il vit plus paisible, plus juste et plus compatissante. Le musulman ne se contente pas de connaître cette valeur : il s''efforce de la vivre chaque jour, dans chaque milieu et dans chaque relation, afin d''offrir à l''humanité le plus bel exemple.', 'Tout au long de l''histoire de l''humanité, l''une des dynamiques les plus fondamentales qui assurent la pérennité des sociétés est le sentimen...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/repondre-au-mal-par-le-bien-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sol Yanımda Hiç Bitmeyen Şubat, Babam', 'sol-yanimda-hic-bitmeyen-subat-babam-ali-taskale-odnxm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Babamın aziz hatırasına___

Ocak çekildi takvimden,

ama kışı çıkmadı ömrümün.

Bir fener söndü gözlerimde,

karanlığı çöktü bütün cümlelerimin.

Şubat, kapıma her dayandığında

biraz daha kanıyor içimdeki Ocak.

Takvim yaprakları düşüyor birer birer,

ben hâlâ son nefesinin kıyısında

bekliyorum dönmeyecek bir zamanı...

Bilseydim o bakışın son limanım,

gözlerine biraz daha uzun demir atardım.

Ellerini avuçlarımda biraz daha tutar,

sesini hafızamın en derin yerine saklardım.

Meğer insan, bir vedanın içinde

bütün ömrünü kaybedebilirmiş, babam...

Ben sustum...

Gözlerim, içimdeki yangının külünü taşıyor.

Her damla yaş, senden kopmuş

küçük bir hatıranın mezar taşı.

Yokluğun, göğsümde kapısı kapanmayan

karanlık bir oda gibi duruyor.

Ne zaman içeri girsem,

çocukluğum oturuyor köşede,

başını dizlerine koymuş seni bekliyor...

Ağırmış, babam,

özlemi yılların sırtında taşımak.

Zormuş, insanın en güvenli limanından

bir ömür uzağa savrulması.

Kulağımda hâlâ o narin sesin,

bir kuşun kanadına ilişmiş son bahar gibi...

Bir ses düşüyor içimin kuyusuna,

yankısı geliyor, kendisi gelmiyor.

Dönüp bakıyorum her defasında,

kapıda sen yoksun,

ama yokluğun ayakkabılarını çıkarmadan

oturmuş evimin başköşesine...

Çok özledim babam...

O canını, sıcağını,

avuçlarımda dinlenen ellerini,

dünyanın bütün gürültüsünü susturan

şefkatli kucağını...

Bir kez daha başımı göğsüne koyabilsem,

bütün kırılmış zamanları onarırdım.

Bir kez daha sesini duyabilsem,

ömür dediğim şu uzun yolculuğu

yeniden yürümeye razı olurdum...

Hangi bahar uğrarsa uğrasın kapıma,

çiçekler açsa da bütün dallarımda,

içimde bir ağaç var ki, babam,

kökleri senin gidişine bağlanmış.

Her mevsim yaprak döküyor sol yanım,

her rüzgâr adını fısıldıyor.

Dışarıda dünya yeniden yeşeriyor,

benim içimde Ocak hiç bitmiyor...

Uçtu nefesin, göğe karıştı izin,

ardında yarım kalmış bir ömrün sessizliği.

Şimdi ellerin yok ellerimin içinde,

hangi dua dindirebilir bu ayrılık denizini?

Oda sessiz, duvarlar sağır,

saatler bile senin yokluğunda ağır.

Bir zamanlar sesinle ısınan evimiz,

şimdi hatıralarının üşüdüğü bir kış bahçesi...

Çok özledim babam...

Bazen bir fotoğrafına takılıyor gözlerim,

zamanın paslandırmadığı tek kapı o.

Gülüşün, eski bir evin penceresinden

içeri sızan son güneş gibi.

Dokunamıyorum, sarılamıyorum,

ama her gece içimde seninle konuşuyorum.

Ben anlatıyorum, sessizlik dinliyor;

sen susuyorsun, kalbim cevap veriyor.

Sonra ikimiz birden susuyoruz...

Bir daha söyle babam,

bir kez daha çağır beni o sesinle.

Bütün yolları yürüyüp gelirim,

çocukluğumun çıplak ayaklarıyla.

Bir kez daha başımı okşa,

bir kez daha gözlerime bak.

Bırak, dünya bir anlığına dursun,

bırak, ölümün susturduğu sesini

kalbim yeniden duysun...

Ama biliyorum...

Bazı kapılar yalnızca hatıralara açılır,

bazı yolların dönüşü yoktur.

Bazı vedalar toprağa değil,

insanın ömrüne gömülür.

Sen toprağın altında uyurken, babam,

ben yokluğunun üstünde yaşıyorum.

Her sabah biraz daha büyüyor içimde

sana kavuşamamanın çocukluğu...

Işıklar içinde uyu güzel babam...

Gökyüzü yorganın, yıldızlar kandilin olsun.

Melekler başucunda nöbet tutsun,

uykun huzurla, mekânın cennet olsun...

Ben burada,

senin bıraktığın sesin eşiğinde,

bir ömür daha seni beklerim...

Çünkü bazı özlemler dinmez, babam,

bazı yaralar kabuk bağlamaz.

Ve bazı insanlar ölse de

evlatlarının kalbinden hiç ayrılmaz...

Sen gittin babam...

Ama benim sol yanımda hâlâ sen varsın.

Ve orada, takvimler ne kadar değişirse değişsin,

Ocak hiç bitmeyecek...

Hember | 02 Şubat 2018', 'Babamın aziz hatırasına___ Ocak çekildi takvimden, ama kışı çıkmadı ömrümün. Bir fener söndü gözlerimde, karanlığı çöktü bütün cümlelerimin....', ARRAY['Türk Edebiyatı','Şiir','Ali Taşkale']::text[], 8.5, '{"poet":"Ali Taşkale","poet_slug":"ali-taskale","theme":"Türk Şiiri","is_hero":false,"total_lines":107,"source_url":"https://www.antoloji.com/sol-yanimda-hic-bitmeyen-subat-babam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yilsonu Itibariyla', 'yilsonu-itibariyla-seyfi-karaca-2cmmn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Leningrad ( Petersburg) doğunun gizli saklı Paris’i, Paris ise batının tanıdık bildik Paris’ i diye bilinir ya….

Rusların Gogol, Puşkin, Tolstoy, Gorki ve her biri Edebiyat’ ın ehil kalemi diğerlerinin her köşe bucak bulvar cadde köprü ara yol ana cadde kavşak geçit dere tepe ırmak meydan koruluk park bahçe kule resmi veya sivil yapı binalarıyla Fransızların Flaubert, Zola, Hugo, Balzac ve diğerlerinin şehir romancılığında yazıp anlattıklarıyla birbirlerinin yarım kalan eksiğinin akıntısı dinmeyen bir yağmur nehri gibi üstüne ışık görmemiş veya gün yüzüne çıkmamışlığı karanlıkta koymayan insan hikayeleri katıp tamamlıyorcasına kesişen bileşenlerin Paris’ inde ortaklaşırlar.

Böylece tüfek fişeklendikçe katlettiği kirli donanımlı ve hormonlaşmış yapay büyümeli şehrleşmelere zehir zıkkım yedirerek doğa tabiat geyik maral filaningo turna üveyik kumru kurbağa çaylak akbaba ve nicesinin yaşam alanlarını söktü yaktı yıktı viran ören ettiğinin gelişmemiş çevre kazanım ve değer bilinçsizliğiyle aç gözlülüğünü doyurmaya avlanırken aldandı ve kendini avladı insanlık. Mezarlaşan dünya moloz yığınıyla kirli siyasetin de kendi ganimet peşi kovalamak ve oy avcılığı peşi gütmekten başka hiç bir şeye hiç bir ilgisinin alakasının olmadığı sürekli atık şiddet cehalet gericilik manyaklık kavga fiyaka sosyete gösteriş kargaşa kötü niyet ayrışma gerilim sapkınlık acımasızlık kayıtsızlık kültürsüzlük ve sorun üreten Paris ışıltılı ve radyodalga sinyalli etkileşimleşme betonlaşma ve plastikleşme çöplüğüne atıldı.

Sidney ve Şikago, veya Duplin ve Buenes Aires Rio de Jenerio, aç gözlülüğünü doyuramayan istila yayılmacılığının her şeyi avlarken kendine av olan doyumsuzluklarla bir uçtan bir uca dünyayı zaptetmeye dönük yapay bulguların yedeğinde çığ çığlık yuvarlanıp büyürken, Londra ve Berlin , Leningrat’ la Paris’ in hem kontrol kule karakolu hem de onları birbirine bağlayan köprü ayaklarıdırlar. 

İstanbul… ? Neresi diye sormaya bile gerek duyurmayan gelmiş geçmiş medeniyetlerin beşik yeri, suyun üstünde güneşin sımsıcak izini bıraktığı pırıl pırıl kandillerin hep yandığı; ve doymak bilmeyen masal bozucu hırsız uğursuz ve yolsuz haramilerin güzelliğine hor bakıp aralıksız kesintisiz yazık ettikleri nazlı güzelliğin su perisi ve deniz kızıdır.

Önce Paris sonra Petersbur’ lu ( Leningrad) Paris, İznik’ te bozup tamir ettikleri İncil’ ile doğuyu batıya götürerek Kelt’ lerin ( Galya) ölülerle yaşayanlar arasında kurulacak bağ ve kutlanacak gündür diye kış soğuklarında toplanarak insanın kendi içinde yuvalanmış ve dışını kuşatan kötülükleri kovalayan ışıklı maskeli Helloween ritüellerine Nikelaus’ lu geyikli noel öyküleri konuşlandırılmış çam ağaçlarını tepeden tırnağa süslenmiş mum parıltılarıyla giydirip donatarak kış ayazının esaret hükmüne aldığı amansız eşkiyalığı kendi içinde ve dışındaki kötülüklerle benzer saydıkları hapsolunmuşluğu kovalasın diye bol gürültülü ve maskeli kılıklı Karnevallere kendi uydurduğuna inanma endüstrisi kurup sanayileşti. 

Maya’ dan’ İnka’ dan, Latin’ den Orta ve Uzak doğu’ dan Afro american yurop derme toplama ve karma karışık kult totem ve sanayi kurgu kurmacasıyla İşte yine Noel’ in her ayak çark çevrimli Silvester fabrikasyon ürünü Crismax yeni yol ve yeni yıl karneval kozmo dönencelerinin bir adım öncesi ve sonrası eşik ayağında, yaşlandıkça kendini tanımaz hale gelen parıltılı ışıklara öpücükler kondurarak havai fişeklerde kendini tavlayıp avladığı hayatı kaymış insanlık allem kallem ve iki Paris arası darbucak dünya…

Yıl sonu itibarına,

Yıl sonu itibarına,

İlerdeki günlerde Gogol’ un Neva Bulvarı’ nı yorup yazmak dileğiyle.

Kasım/26', 'Leningrad ( Petersburg) doğunun gizli saklı Paris’i, Paris ise batının tanıdık bildik Paris’ i diye bilinir ya…. Rusların Gogol, Puşkin, Tol...', ARRAY['Türk Edebiyatı','Şiir','Seyfi Karaca']::text[], 8.5, '{"poet":"Seyfi Karaca","poet_slug":"seyfi-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yilsonu-itibariyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Face à l''oppression, la posture du musulman : un équilibre entre soumission, révolte et sagesse', 'face-l-oppression-la-posture-du-musulman-un-quilibre-entre-soumission-r-volte-et-sagesse-muhammed-ridvan-gizri-7xwu1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'L''une des tensions les plus anciennes et les plus irrésolues de la pensée politique islamique concerne l''attitude que doit adopter le musulman face à un gouvernant injuste. Pendant des siècles, la réponse à cette question est restée coincée entre deux extrêmes : l''obéissance absolue ou la révolte sans condition. Pourtant, le Coran ne s''exprime pas dans cette logique binaire, mais au sein d''un cadre éthico-politique bien plus nuancé et intégré. Le verset 113 de la sourate Hûd interdit de pencher vers l''injustice ; le verset 97 de la sourate An-Nisâ'' ne condamne pas l''inaction, mais prive l''inaction de toute excuse ; la sourate Al-Baqara (217), elle, proclame que la fitna est un désordre plus grave que le meurtre. Lus ensemble, ces trois versets ne dessinent ni la soumission ni la révolte irréfléchie. Ils dessinent une raison de la responsabilité, une éthique de la clairvoyance (basîra), un principe d''équilibre. La posture du musulman face au gouvernant injuste ne peut être ni le silence enseigné par les fatwas d''obéissance, ni la fitna allumée par un soulèvement voué à l''échec. La juste attitude est une posture de sagesse, enracinée dans la conscience du *tawhîd*, attentive à la balance des avantages et des dommages, centrée sur l''intérêt de la communauté, et qui n''abandonne, en aucune conjoncture, le parti de la justice.

Le piège de la légitimité créé par l''obéissance absolue

Les fatwas d''obéissance et le bouclier sécuritaire de l''oppresseur

À travers l''histoire, certains savants religieux, au nom de « ne pas provoquer de fitna », se sont abstenus d''élever la voix contre l''oppression et ont présenté ce silence comme une obligation religieuse. L''aspect le plus dangereux de cette attitude est que l''oppresseur puise précisément sa force dans ces fatwas. Il sait qu''un discours religieux existe qui empêche la société de se mettre en mouvement, et il l''utilise comme cuirasse de sa propre autorité. C''est l''un des plus grands pièges de l''esprit musulman : la solution produite pour prévenir la fitna devient un instrument qui pérennise l''oppression. La fatwa d''obéissance ne réduit pas la violence du pouvoir ; elle lui confère l''intouchabilité.

La question de Yazîd et la leçon amère de l''histoire

La résistance de Husayn face à l''oppression de Yazîd constitue le point de rupture historique le plus profond sur cette question. Le soulèvement de Husayn est l''un des moments où l''exigence de justice et la fermeté des principes se sont exprimées avec le plus de force. Mais ce qui a suivi cet événement révèle une leçon tout aussi importante : les attitudes divergentes face à l''oppression apparues après Karbala sont devenues, au fil des siècles, l''un des principaux éléments alimentant la fracture entre sunnites et chiites. Cette hostilité s''est traduite par des rituels physiques durant le mois de Muharram, par un discours de rancœur transmis de génération en génération et par la fragmentation effective de l''unité de la communauté musulmane. Le message est le suivant : se taire face à l''oppression ne règle pas seulement le problème de l''instant ; cela sème à long terme les graines de blessures sociales plus grandes. L''histoire a prouvé que le silence a un coût.

Le cadre à trois axes du Coran

Hûd 113 : l''interdiction de pencher vers l''injustice

« Ne vous penchez pas vers ceux qui commettent l''injustice, sinon le Feu vous touchera. »

Ce verset n''interdit pas seulement de participer activement à l''oppression, mais aussi de pencher, ne serait-ce que dans le cœur, vers elle. La notion de « penchant » (mayl) y est extrêmement large : trouver l''oppression naturelle, la légitimer, lui donner un consentement silencieux ou se tenir aux côtés de l''oppresseur entre dans le champ de cette interdiction. La lecture politique du verset est claire : même lorsqu''il a perdu le courage de s''opposer au pouvoir injuste, un musulman n''a pas le luxe de le regarder avec sympathie ou de rationaliser son oppression. Se tenir du côté de la justice est un principe fondamental, indépendant du poids des circonstances. C''est le reflet du tawhîd dans la politique : la puissance absolue appartient à Dieu seul ; aucun gouvernant injuste ne peut être sacralisé ni rendu intouchable.

An-Nisâ'' 97 : l''excuse de l''impuissance n''est pas recevable

« Lorsque les anges prennent l''âme de ceux qui ont été injustes envers eux-mêmes, ils disent : "Dans quelle situation étiez-vous ?" Ils répondent : "Nous étions faibles sur terre." Ils disent : "La terre de Dieu n''était-elle pas assez vaste pour que vous y émigriez ?" »

Ce verset est une demande de comptes d''une extrême sévérité. La justice divine rejette l''argument qui attribue le fait de rester sous l''oppression à de la « faiblesse ». Ce que le verset enseigne est fondamental : même lorsque la capacité de changer l''oppression est réduite à zéro, une option demeure devant le musulman : l''hégire (hijra). L''hégire n''est pas ici un simple déplacement géographique, mais une démarche stratégique entreprise pour protéger la religion, la vie et la descendance. Ce n''est pas une fuite, mais une forme de résistance. Là où, sous la domination des oppresseurs, les droits religieux et humains se sont totalement effondrés, rester sur place n''est pas une vertu ; cela devient au contraire un choix dont il faudra rendre compte.

Al-Baqara 217 : la fitna est plus grave que le meurtre

« La fitna est plus grave que le meurtre. »

Le fait que ce verset ne soit pas une disposition portant directement sur la lutte politique n''invalide pas le principe d''évaluation des dommages qu''il contient. La fitna, c''est l''effondrement de l''ordre social, la suspension du droit, la mise en danger de la vie, des biens et de l''honneur des innocents : enfants, femmes, personnes âgées. La question déterminante est la suivante : le résultat de l''action envisagée conduira-t-il, au-delà de la possibilité d''instaurer un ordre juste, à une guerre civile de grande ampleur, à l''effondrement total de l''autorité de l''État et à l''absence de protection pour les innocents ? Si l''on ne peut apporter une réponse qui ne laisse pas cette équation incohérente, c''est-à-dire si les dommages du mouvement dépassent manifestement ses bénéfices, alors s''y engager cesse d''être une obligation religieuse ; cela devient une responsabilité religieuse.

La construction de l''esprit équilibré du croyant

Le calcul des risques : la raison stratégique de l''islam

Face aux décisions politiques, le musulman n''est condamné ni à un idéalisme aveugle ni à une soumission nourrie par la peur. La raison politique de l''islam commande une évaluation réaliste des risques :

Première question : pour qui ce mouvement est-il bénéfique, pour qui est-il nuisible ? Comment les avantages et les dommages se répartissent-ils ?

Deuxième question : quel est le coût de l''inaction ? Quelles destructions sociales la pérennisation de l''oppresseur entraîne-t-elle à long terme ?

Troisième question : la série d''événements que déclenchera le passage à l''action est-elle contrôlable ? Ou bien va-t-on engager un engrenage de fitna ?

Un esprit qui pose ces trois questions successivement n''est condamné ni à la fatwa du « supporte tout » ni au slogan du « lève-toi quoi qu''il arrive ». Cet esprit est la basîra elle-même, une vertu qui a toujours occupé une place particulière dans la religion islamique.

Le tawhîd : le socle de toute analyse

Sous toutes ces évaluations, une seule chose demeure constante : le tawhîd. La puissance absolue appartient à Dieu. Aucun gouvernant injuste, si fort qu''il paraisse, n''est tout-puissant. Cette conviction constitue la forteresse psychologique la plus profonde du musulman face à l''oppresseur. Oublier le tawhîd entraîne deux conséquences dangereuses : soit l''on voit l''oppresseur comme une force insurmontable et l''on se soumet à lui, soit l''on se jette, sans tenir compte du décret divin, dans des démarches dont les résultats sont imprévisibles. Ces deux erreurs sont le produit de l''effacement du tawhîd.

An-Nisâ'' 135 et l''obligation de témoigner

« Même si cela est contre vous-mêmes ou contre vos parents… maintenez la justice. »

Ce verset montre à quel point le témoignage de justice est inconditionnel. Le musulman est tenu de maintenir son témoignage en faveur du droit, même lorsque cela va à l''encontre de son propre intérêt. C''est la proclamation que le principe de justice est placé au-dessus de toutes les conditions de la société. Lire ce verset en rapport avec l''attitude face au gouvernant injuste, c''est comprendre ceci : le silence ne signifie pas toujours consentement ; mais si une personne se tait alors qu''elle a les moyens de rejeter l''oppression, ce mutisme peut contribuer à la perpétuation de l''injustice. C''est pourquoi l''obligation minimale du musulman est de ne pas agréer l''oppression dans son cœur et d''exprimer la justice autant qu''il en est capable, même si cette expression ne constitue pas un appel à la révolte.

Les témoins de l''histoire : Ahmad ibn Hanbal, l''imam Mâlik et ''Umar ibn ''Abd al-''Azîz

Historiquement, quelques savants de l''islam ont offert des exemples puissants de la manière dont cet équilibre s''établit. Ahmad ibn Hanbal et l''imam Mâlik n''ont pas défendu des oppresseurs comme Yazîd ; mais ils n''ont pas non plus préparé le terrain à des soulèvements irréfléchis. ''Umar ibn ''Abd al-''Azîz constitue quant à lui l''une des preuves, rares mais puissantes, qu''un changement par l''intérieur est possible. Lorsque la justice est embrassée jusque dans le pouvoir, elle peut laisser une empreinte. C''est aussi une option qui fait partie du répertoire du musulman.

Les strates de sens stratégiques de l''hégire

L''hégire n''est pas une migration ordinaire. Dans le cadre d''An-Nisâ'' 97, elle est une démarche rendue obligatoire lorsque la poursuite de la vie religieuse, la protection de la descendance et la préservation de l''identité sociale n''ont plus que ce seul moyen. Mais l''hégire a aussi ses limites : elle ne peut signifier l''abandon total de l''existence d''une communauté. Un berger qui abandonne son troupeau et s''enfuit, et un berger qui se retire vers une position où il pourra survivre et protéger son troupeau, sont deux choses différentes. C''est pourquoi l''hégire doit être comprise non comme « abandonner », mais comme « se repositionner pour pouvoir continuer ». Pouvoir reprendre des forces sans provoquer de fitna, en préservant l''existence religieuse et humaine : ce n''est pas une soumission qui renonce à chercher la justice, mais un effort pour la porter sur un terrain plus solide.

Ni obéissance absolue ni révolte irréfléchie : sagesse et justice

Le tableau qui se dégage de cet ensemble est celui d''un principe d''équilibre. Le Coran a posé trois interdits à travers trois versets, et ces interdits ne se contredisent pas ; ils se complètent :

- Hûd 113 interdit de pencher vers l''injustice. Cet interdit est valable en toutes circonstances. Le musulman ne peut jamais se tenir aux côtés de l''oppresseur.

- An-Nisâ'' 97 n''admet pas l''impuissance comme excuse. Si l''on ne peut lutter, il faut émigrer. Produire une alternative est un commandement.

- Al-Baqara 217 définit la fitna comme un désordre plus grave que le meurtre. Si le prix de l''action doit être la vie d''innocents, cette action ne peut être engagée sans réflexion.

Lus ensemble, ces principes font apparaître le portrait d''un croyant qui garde le tawhîd vivant, qui n''agrée pas l''oppression, même dans son cœur, qui calcule les risques et les conséquences, qui justifie par ses principes aussi bien le passage à l''action que l''inaction, qui maintient son témoignage de justice indépendamment des conditions et qui ne considère aucun pouvoir comme intouchable. Ce n''est ni l''éthique de la soumission ni le romantisme de la révolte. C''est la posture de sagesse que l''islam commande : résister pour la justice, protéger les innocents, avancer en préservant le tawhîd, et ne jamais se tenir aux côtés de l''oppresseur.

En conclusion, l''éthique politique que pose le Coran rejette aussi bien la soumission à l''oppresseur que la révolte aux conséquences non calculées. Le musulman est tenu de se tenir du côté de la justice ; mais cette obligation n''est pas indépendante de la sagesse. Ne pas pencher vers l''injustice, témoigner de la justice, épuiser les possibilités, émigrer lorsque cela s''impose, et faire tout cela dans la conscience du tawhîd : tels sont les éléments fondamentaux de la posture politique équilibrée que le Coran indique.', 'L''une des tensions les plus anciennes et les plus irrésolues de la pensée politique islamique concerne l''attitude que doit adopter le musulm...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/face-a-l-oppression-la-posture-du-musulman-un-equilibre-entre-soumission-revolte-et-sagesse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firariden Gözaydin', 'firariden-gozaydin-seyfi-karaca-172yl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çek kenara kendini

Bozulacaksa bozulsun zincirlere vurgun kozmo butik hiza

Zamanın bol olsun

Gramafon döndükçe sana dolansın seninle dönsün fırfır

Aklındaki hiç gitmeyen

Hiç bir yere hiç doğmamış

Hiç bir yola hiç girmemiş, hiç bir kırmızı ışıklı durağa uğramamış

Dantelli iç çamaşırlarının rüzgarın çalgısıyla renkli mandal kıskaçlarında dans ettiği

Kopar şu kendini herkese ama illa mutlaka görünür kılma kör düğümlerini, suyun karşı yakasına geç

Sessizliğin huzur veren kalbini gez gör dolaş camın arkasındaki kaktüslü eve hiç merak salma

Etrafı duvarlarla sarılmış tutsak ağaçları ve saatin içerden fışkırıp çınlayan sarhoşluğa fire veren iniltilerini

Orası ışık yılından bile uzak ve karanlıktır

Dopdolu

Dipdiri

Dipdingin

Çırılçıplak ormanlar gibi

Hiç senden vazgeçmemişliği çek çıkar ışıklar görsün

Bildin işte, gidip gelindikçe yol olur

Sevip bağlandıkça da aşk

Ör şu ilmek oymak kozayı ey deli divanelere yurt olan yare diyar gönlüm deyiver

Sarıver şu menzilsiz bucaksız mekiği uçarı özgürlüğün kol kanadına

Koralmış ocağı kur, ateşi yak

Çünkü bu yolun yolculuğu ve bu çözülmez kopmaz bağ

Açık ara sevgiliye aşşşşktır

Bildin işte o çılgın şeyi

Bu sefer o sihirli sobedir

Bu sefer her akşam ve geceye yıldızlıyağmur sevgiliyi resmeden buğulu cam yazısı

Bu sefer ertesi seferlere günaydın

Bu sefer her sefere

Buğum boğum firariden gözaydın

Kasim /26', 'Çek kenara kendini Bozulacaksa bozulsun zincirlere vurgun kozmo butik hiza Zamanın bol olsun Gramafon döndükçe sana dolansın seninle dönsün ...', ARRAY['Türk Edebiyatı','Şiir','Seyfi Karaca']::text[], 8.5, '{"poet":"Seyfi Karaca","poet_slug":"seyfi-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/firariden-gozaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EMEKLİLİKTE HAYATA TAKILANLAR', 'emekli-li-kte-hayata-takilanlar-mesut-karabulut-2-ml1jk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerimi açtım sabah ezanı okunuyor. Kolumu ve elimi hissetmiyorum. nasıl uyuşmuş, Galiba yine kolumun üzerinde uyudum. Yastığı kucaklayıp kolumun üstüne yatmayı çok seviyorum.  Hoca yine çok güzel okuyor sabah ezanını. Çocukluktan beri severim sabah ezanını. Üstümü giyindim hızlı bir şekilde.  Gözlerim nasıl uykulu. Dışarısı çok karanlık. Bu senede saatleri geri almadılar. Soğuk üstelik. Otobüs durağında kimse yok sanki sadece benim çalışması gereken. Uzaktan bir gölge göründü . Arkasından bir gölge daha. Bu topallayarak yürüyen kesin Osman abi. Yere tükürdü, üstelik yoldaki küçük taşları tekmeledi. Diğeri resul abi emekli ama çalışmak zorunda bizim gibi. Emeklilik hayali ile yıllarca çalışmış ama emekliilk nasıl birşey bilmeyenlerden. Sahte uydurma enflasyon rakamları sayesinde maaşlar bir simit bir çaya yetmiyor. Bu hesaplama yöntemini değerli bir siyasi öğretti bize. Robot yapmak için ugrasmalarina gerek kalmadı. Robot gibi hissediyoruz. Duyguları alınmış. Bugün günlerden salı, hafta tatili hayalini kurmaya başladım bile.', 'Gözlerimi açtım sabah ezanı okunuyor. Kolumu ve elimi hissetmiyorum. nasıl uyuşmuş, Galiba yine kolumun üzerinde uyudum. Yastığı kucaklayıp ...', ARRAY['Türk Edebiyatı','Şiir','Mesut Karabulut 2']::text[], 8.5, '{"poet":"Mesut Karabulut 2","poet_slug":"mesut-karabulut-2","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/emeklilikte-hayata-takilanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gri miydi Aşk', 'gri-miydi-ask-zafer-unsal-2-dsss5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevmek miydi aşk, yoksa sevilmek mi?

Koyu bir siyah mıydı, yoksa koyu bir beyaz mı,

Yoksa gri miydi aşk?

Belki de yaşamaktı sevilmek, içine çektiğin nefesti belki;

Sevmekse, nefes alıp vermekti.

Hayat bulmak mıydı bu döngüde,

Yoksa bir bakışta nefessiz kalmak mıydı aşk?

Zamanın peşinde koşan akrep miydi sevmek,

Ona yetişmeye çalışan yelkovan mıydı sevilmek?

Yoksa tam da kavuşacakken durmuş,

Bozuk bir saat miydi aşk?

Nisan yağmuru muydu sevmek,

Ağustos güneşi miydi sevilmek?

Yoksa hazan vurduğunda,

Eylül rüzgârlında ayrılık mıydı aşk?

Kor bir alev olup yakmak mıydı sevmek,

O ateşte kavrulmak mıydı sevilmek?

Yoksa geriye küllerin kalınca,

Rüzgârda savrulup gitmek miydi aşk?

Gözlerinde cenneti bulmak mıydı bir sevgilinin,

Hasretiyle cehennemi yaşamak mıydı acaba sevmek?

Yoksa tüm dünyanı başına yıkan,

Sessiz bir kızılca kıyamet miydi aşk?

Ne siyahtı , ne de beyazdı aşk,

Ben hangi renge boyasam ,

Hep bir yerinden gri kanadı aşk...', 'Sevmek miydi aşk, yoksa sevilmek mi? Koyu bir siyah mıydı, yoksa koyu bir beyaz mı, Yoksa gri miydi aşk? Belki de yaşamaktı sevilmek, içine ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Unsal 2']::text[], 8.5, '{"poet":"Zafer Unsal 2","poet_slug":"zafer-unsal-2","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/gri-miydi-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Yalanmış Meğer', 'askin-yalanmis-meger-kerim-yavuz-uycbo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Terk edip gittin beni hasretin kucağına.

Hüzünlüyüm bu gece, gözlerim ağlamaklı.

Düştüm işte bir kere aşkının tuzağına.

Yüreğimin içinde gizli bir isyan saklı.

Sakın ola kalbimin sessizliğine kanma.

Yarın bugün değildir bunu anlayacaksın.

Aşkı oyun zannedip kazançlı çıktım sanma.

Elveda değişine çok pişman olacaksın.

Yorgun düştü bu gece bahtımın kollarında.

Yalnızlık limanına demir attı saatler.

Konuşurken seninle mutluluk yollarında.

Demek hep yalan imiş o verdiğin vaatler.

Bu gece yıldızlardan eser yok gökyüzünde.

Gözlerimin ucunda kara kara bulutlar.

Aşka ihanet ettin durmadın ki sözünde.

Bir yanlış adım yetti suya düştü umutlar.

Umutlarımı çalıp çekip gittin buradan.

Bir sözünle yok ettin bu aşkın temelini.

Hiç ummadığım anda yıktı beni elvedaın.

Çok ağır ödüyorum bu aşkın bedelini.

Kalbimi alet ettin çirkin emellerine.

Bunu şimdi anladım aşkın yalanmış meğer.

Bana ıstırap verdin mutluluğun yerine.

Vicdanına bir danış vicdanın varsa eğer.', 'Terk edip gittin beni hasretin kucağına. Hüzünlüyüm bu gece, gözlerim ağlamaklı. Düştüm işte bir kere aşkının tuzağına. Yüreğimin içinde giz...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/askin-yalanmis-meger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolun Açık Olsun Bernam', 'yolun-acik-olsun-bernam-sessiz-i-syan-27mv5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben senin en çok gülüşünü seviyorum,

Bir de o tatlı dilini, içtenliğini…

Bazen küçücük bir sözünle mutlu ediyorsun beni,

Bazen hiçbir şey yapmadan bile güzelleştiriyorsun günü.

Benim güzel Bernam, benim balım,

Seninle ilgili güzel hayallerim var.

Öyle büyük laflar etmeye gerek yok,

Ben senin mutlu olduğunu görmeye bile hayranım.

Şimdi yeni bir yol başlıyor önünde,

Belki biraz heyecan, belki biraz telaş var içinde.

Ama ben seni tanıyorum güzelim,

İstediğinde neler başarabileceğini de biliyorum.

Kur hayallerini, aç kendi yolunu,

Koy imzanı hayatın en güzel yerine.

Bir gün kendi şirketinin kapısını açtığında,

İlk başarının heyecanı hiç eksilmesin yüreğinde.

Hadi benim balım, gül yine öyle,

Yakışıyor sana hayatın en güzel hâliyle.

Sen yeter ki inan kendine,

Ben inanıyorum senin o güzel yüreğine.

Her şey gönlünce olsun benim Bernam,

Hiç eksilmesin yüzünden o güzel tebessüm.

Sen her şeyin en güzeline layıksın,

Bunu sana söylemekten hiç yorulmam.

Biliyor musun, seni düşününce

İçimden ne güzel şeyler geçiyor sessizce.

Neşen hiç kaybolmasın, gözlerin hep gülsün,

Hayat karşına hep güzel insanlar çıkarsın.

Yorulduğunda biraz dinlen, ama vazgeçme,

Kendinden, hayallerinden, o güzel kalbinden.

Çünkü senin başarını görmek istiyorum,

Güzel haberlerini duydukça ben de mutlu oluyorum.

Ben sana boşuna balım demiyorum ki,

Senin tatlılığın başka, yerin başka bende.

Dilerim hayat sana bütün güzelliklerini sunsun,

Ve sen hep böyle gül, benim güzel Bernam…

İyi ki varsın balım,

İyi ki hayallerin var.

Yolun açık, bahtın güzel olsun.

Seni güzel şeyler beklesin', 'Ben senin en çok gülüşünü seviyorum, Bir de o tatlı dilini, içtenliğini… Bazen küçücük bir sözünle mutlu ediyorsun beni, Bazen hiçbir şey ya...', ARRAY['Türk Edebiyatı','Şiir','Sessiz İsyan']::text[], 8.5, '{"poet":"Sessiz İsyan","poet_slug":"sessiz-i-syan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yolun-acik-olsun-bernam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekletme n''olur', 'bekletme-n-olur-rustem-sahin-ypazr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BEKLETME N''OLUR (738)

Uğruna ömrümü verdiğim güzel

Yeter yollarını bekletme n''olur 

Sarardı umutlar  oldu bak  gazel

Bir derdime bin dert ekletme n''olur 

Açılsın bize de vuslatın yolu 

Kurumaz kirpikler  gözler yaş dolu 

Sensizlik her gece sızlatır solu 

Hasreti omzuma yükletme n''olur 

Uçan turnalara ahvalimi sor 

Sönmüyor bağrımda yanan kızıl kor 

Bu firkatin bana ölümden de zor

Boş kalan sinemi oklatma n''olur 

Biçareyim işte anla halimden 

Göller baraj oldu gözüm selinden 

Bir eski resmin var düşmez elimden 

Sen diye resmini koklatma n''olur 

ZA''ÎFÎ"m gülmedi zalım kaderim 

Bitmedi gönlümde gamım kederim 

Ölürsem sevdiğim hasret giderim 

Ömrümün son güzü bekletme n''olur 

02 ŞUBAT 2026 İST

ŞİİR: BEKLETME N''OLUR 

ŞAİR:TC KÜLTÜR VE TURİZM BAKANLIĞI HALK ŞAİRİ RÜSTEM ŞAHİN (ZA''ÎFÎ)

KİTAPLARI: GÖNÜLDEN DİLE, GEL SEVDİĞİM VE BU HİCRAN YARASI(738)

Not: Sayfamda paylaştığım tüm şiirlerim kitaplarımda ve Antoloji com''da tescillidir keyifli okumalar.', 'BEKLETME N''OLUR (738) Uğruna ömrümü verdiğim güzel Yeter yollarını bekletme n''olur  Sarardı umutlar  oldu bak  gazel Bir derdime bin dert ek...', ARRAY['Türk Edebiyatı','Şiir','Rüstem Şahin']::text[], 8.5, '{"poet":"Rüstem Şahin","poet_slug":"rustem-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bekletme-n-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Duvarım', 'aglama-duvarim-ahmet-ihsan-arac-xtx2o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bütün şiirlerim çalıntıdır; 

Ömrümün uykusuz gecelerinden, Kimsenin görmediği 

İçime gömdüğüm nice anlardan

Damlalardır damıttıĝım. 

Ağlama duvarımdır şiirler benim

.Herkesin bir ağlama duvarı vardır.

Kimi annesine ağlar, 

Kimi kardeşine, 

Kimi bir dostuna, ya da sevgilisine

Ben mısralara ağlarım.

Bazen bir mısra tutar elimden

Bazen bir kelime sıvazlar sırtımı

teselli eder beni

Sanmayın ki şiirlerimi ben yazdım. 

Ben yalnızca sustum; 

Umitlerim, acılarım konuştu

Geceler dile geldi

Şimdi her şiirimde biraz ben varım, 

Biraz o, biraz bu

Biraz kaybettiğim, biraz vazgeçtiğim

Ve kimsenin bilmediği kadar incindiklerim

Ben şiir yazmam aslında; 

Mısralara aĝlarim', 'Bütün şiirlerim çalıntıdır;  Ömrümün uykusuz gecelerinden, Kimsenin görmediği  İçime gömdüğüm nice anlardan Damlalardır damıttıĝım.  Ağlama ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ihsan Arac']::text[], 8.5, '{"poet":"Ahmet Ihsan Arac","poet_slug":"ahmet-ihsan-arac","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aglama-duvarim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüşvet', 'rusvet-kerim-yavuz-faflo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bulaştın mikrop gibi sistemin her yerine.

İnan isyanlardayız gülemiyoruz rüşvet.

Sanki yazmışlar seni ülkemin kaderine.

Seni kaderimizden silemiyoruz rüşvet.

Biliyorum varlığın kağıt üstünde yasak.

Ne olurdu seni hiç aramıza sokmasak.

Devlet kapılarında kokunu duyurmasak.

İnsanca bir davranış göremiyoruz rüşvet.

Çarkın dönüp duruyor yok ki sana dur diyen.

Kor ateşlerde yansın seni alıp da yiyen.

Var mı acaba sana elini değdirmeyen.

Bu soruya bir yanıt veremiyoruz rüşvet.

Kırılsın birer birer sana dokunan eller. 

Lal olsun konuşmasın seni isteyen diller.

İspat etmek imkânsız yok edilmiş deliller.

Seni gözler önüne seremiyoruz rüşvet.

Bir belgeye kırk imza inan aklım duruyor.

Sen olmasan işimiz ağır aksak yürüyor.

Devlet kapılarında herkes seni soruyor.

Sensiz hiçbir kapıdan giremiyoruz rüşvet. 

Sen bu sistem içinde kanayan bir yarasın.

Bazen adın hediye bazen nakit parasın.

Onurlu insanlarca karadan da karasın. 

Seni bu topraklarda istemiyoruz rüşvet.', 'Bulaştın mikrop gibi sistemin her yerine. İnan isyanlardayız gülemiyoruz rüşvet. Sanki yazmışlar seni ülkemin kaderine. Seni kaderimizden si...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/rusvet-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Pirinç', 'bu-pirinc-salih-yildiz-yzkrm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '"Bu pirinç daha çok, su çeker" gayri 

Tüp yandıkça hala, fena şişiyor.

Dicle, Fırat bağlı, Sakarya ayrı 

Kızılırmak bitti, o ki pişiyor.

Çorak tarlalarda yetişmiş belli 

Fiyatı pahalı kelli de felli

Sahibi çok  yaman baklava dilli 

Hep baklagiller''e kuyu eşiyor.

Yanında halt etmiş Tosya pirinci

Gündemden düşmüyor kavi direnci 

Süper kazandırmış mübarek inci

Hiç olmadık kadar ranta koşuyor.

İçi ak taş dolu tehlike büyük 

Sahibi sırtında çok-çok ağır yük

Özenle yapışmış bedende sülük 

İçine çektiği her fert üşüyor.

Onun paraları ihraç ürünü 

Zahir büyük sanal haraç ürünü 

Gözleri doymamış bir aç dürümü

Müşteri yedikçe, yeyip coşuyor.

Garibi makarna, bulgura devam

Pilav nice zaman bulur ki kıvam?

Onu bekleyemem, Yıkılır yuvam

Helaller peşinde, zarzor yaşıyor...

Salih Yıldız...16.11.2026

.', '"Bu pirinç daha çok, su çeker" gayri  Tüp yandıkça hala, fena şişiyor. Dicle, Fırat bağlı, Sakarya ayrı  Kızılırmak bitti, o ki pişiyor. Çor...', ARRAY['Türk Edebiyatı','Şiir','Salih Yıldız']::text[], 8.5, '{"poet":"Salih Yıldız","poet_slug":"salih-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bu-pirinc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar Arasında', 'yildizlar-arasinda-kerim-yavuz-vfyih', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yıllar oldu orada uyumayı özledim,

Uyut beni güzelim yıldızlar arasında.

Bıkmadan usanmadan yollarını bekledim,

Uyut beni güzelim yıldızlar arasında.

Umutsuzluğa asla gönlümde yer vermedim.

Bütün isyanlarımı seninle frenledim.

Bil ki seneler boyu hep bu günü bekledim.

Uyut beni güzelim yıldızlar arasında.

Kalbime kor düşmüştü kaynıyordu her yeri.

Hasretini geceme bıraktığından beri.

Hadi dokun geceme kapat şu perdeleri.

Uyut beni güzelim yıldızlar arasında.

Bu anın gizemine bilsen nasıl susadım.

Hasretin içerimde ateşler gibi yandım.

Artık bu yastıklardan yorganlardan usandım.

Uyut beni güzelim yıldızlar arasında.

İnan ki kıvılcımlar dolaşıyor bu kana.

Aşkının ateşine düştüğümden bu yana.

O gül dudaklarınla bir ninni söyle bana.

Uyut beni güzelim yıldızlar arasında.', 'Yıllar oldu orada uyumayı özledim, Uyut beni güzelim yıldızlar arasında. Bıkmadan usanmadan yollarını bekledim, Uyut beni güzelim yıldızlar ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yildizlar-arasinda-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçış Yok Benden', 'kacis-yok-benden-kerim-yavuz-q1u16', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşkı sağanak gibi saldım üstüne,

Kaçış yok güzelim, kaçış yok benden.

Kor ateşler gibi düştün özüme,

Kaçış yok güzelim, kaçış yok benden.

Benden başkasını yüreğinden sil.

Okşasın ruhumu gönlündeki dil.

Tüm yolların kesik bunu böyle bil.

Kaçış yok güzelim, kaçış yok benden.

Bir ömür kalayım gönül bağında.

Buselerim olsun gül dudağında.

Pusuya yatmışım aşk sokağında.

Kaçış yok güzelim, kaçış yok benden.

İhanetim olmaz sevdiklerime.

İsmini doladım gönül dilime.

Bir kere işledin iliklerime.

Kaçış yok güzelim, kaçış yok benden.

Sakın ha ellerin sözüne kanma.

Aşkımdan başka bir ateşe yanma.

Bu aşktan geriye dönerim sanma

Kaçış yok güzelim, kaçış yok benden.

Sen kuş olsan bile, ben ok olurum.

Seni yüreğinden, atıp vururum.

Sırra kadem bassan, yine bulurum.

Kaçış yok güzelim, kaçış yok benden.', 'Aşkı sağanak gibi saldım üstüne, Kaçış yok güzelim, kaçış yok benden. Kor ateşler gibi düştün özüme, Kaçış yok güzelim, kaçış yok benden. Be...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kacis-yok-benden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlar', 'dostlar-kerim-yavuz-wetbn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ömür nasıl geçti anlayamadım bende.

Değişiyor duygular hazan yeli esende.

Zamanın izlerini aynalarda görende.

Gözlerim bir noktaya donup kalıyor dostlar.

Son noktaya az kaldı, bunun bilincindeyim.

İfadesi zor olan bir duygu içindeyim.

An gibi geçti hayat, ömrün son demindeyim.

Sormayın yıllarımı, gün bugünkü gün dostlar.

Elbet sizlerde bir gün varırsınız menzile.

Kiminiz genç yaşında, kiminiz baston ile.

Yaş yılları devirip yetmişe gelse bile.

Dünya denen mekânda yaşamak güzel dostlar.

Mazide kaldı şimdi deli dolu o anlar.

Sönüyor birer birer  içimdeki volkanlar.

Dünyanın kanunu bu, toprak olacak canlar.

Geleceği düşünüp öyle yaşayın dostlar.

Dinleyin bir nasihat edeceğim sizlere.

Canlarımız emanet yaradan dan bizlere.

Sakın kini, nefreti, koymayın gönüllere.

Gönüller sevgi ile huzura erer dostlar.', 'Bir ömür nasıl geçti anlayamadım bende. Değişiyor duygular hazan yeli esende. Zamanın izlerini aynalarda görende. Gözlerim bir noktaya donup...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dostlar-223-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaynanaya Mektup', 'kaynanaya-mektup-kerim-yavuz-wb5tk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Buralarda durum hiç iyi değil.

Oğlun iflas topu atayi ana.

Ne olur dua et secdeye eğil.

Gurbet batağına batayi ana.

Kaderimiz oldu dipsiz bir kuyu.

İskiden geldiler kestiler suyu.

Bunalıma girdi değişti huyu.

Gelene gidene çatayi ana.

Ne kömürümüz var ne odunumuz.

Ne tuzumuz kaldı nede unumuz.

Bilmem ne olacak bizim sonumuz.

Çaresiz yüzüme bakayi ana.

Ne yapsın uşağın işi olmazsa.

Kapladı içini derin bir tasa

Önce telavizyon ardından masa.

Evde ne var ne yok satayi ana.

Ekonomik kriz bozdu işini.

Düştü merdivenden kırdı dişini.

Aksilikler bırakmıyor peşini.

Evde yorgan döşek yatayi ana.

Aklında tütüyor yemyeşil Rize.

O çok utanıyor gel deyin bize. 

Parasızlıktan girdi krize.

Evi birbirine katayi ana.', 'Buralarda durum hiç iyi değil. Oğlun iflas topu atayi ana. Ne olur dua et secdeye eğil. Gurbet batağına batayi ana. Kaderimiz oldu dipsiz bi...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kaynanaya-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kalabalığa Bile Sığamadım', 'bir-kalabaliga-bile-sigamadim-yunus-emre-kulakoglu-82zlz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kalabalığın ortasında yapayalnız kaldım,

Herkesin arasında kendime bile uzaklaştım.

Yüzümde bir tebessüm, içimde tarifi zor bir keder,

Kimse bilmedi, ben kaç kez kendimden vazgeçtim.

Ben kaç zamandır kendime ulaşamıyorum,

Nereye gitsem eski hâlime rastlayamıyorum.

Bir zamanlar yarınlara inanan bir adamdım,

Şimdi yarın dediğim güne bile inanamıyorum.

Belki de bu yüzden kalabalıklarda sustum,

Herkesin sesini duydum, kendi sesimi unuttum.

Bir çift göz hâlimi fark etsin diye bekledim,

Ben herkese yetişirken kendime geç kaldım.

Büyüdüm diyorlar, oysa içimde hâlâ

Teselli bekleyen küçücük bir çocuk var.

Herkes uyuduğunda başlıyor sessizce ağlamaya,

Ben sustukça biraz daha derinleşiyor yaraları.

Geceleri kimse bilmez neler yaşadığımı,

Kaç gece sesim çıkmadan ağladığımı.

Sabah olunca yüzüme bir tebessüm takarım,

Kimse görmesin diye içimdeki yıkımı saklarım.

Benden hep güçlü olmamı beklediler,

Düştüğümde kalkmamı, sustuğumda gülmemi istediler.

Bir kez olsun yoruldun mu diye sormadılar,

Sanki benim de kırılmaya hakkım yokmuş gibi davrandılar.

İçimde birikenleri anlatsam ömrüm yetmez,

Hangi yarama dokunsam hiçbir kelime yetmez.

Beni bir kez olsun gerçekten dinleseydiniz,

Belki de gözlerinizi kaçırırdınız, yüzleşemezdiniz.

Biliyor musunuz, en çok neye üzülüyorum?

Bir zamanlar nasıl güldüğümü hatırlayamıyorum.

Hayat benden çok şey aldı, buna da alıştım,

İnsanın en büyük yenilgisi, acısına alışmasıymış.

Bana nasıl yaşadığımı sormayın artık,

Ben nefes almayı öğrendim, yaşamayı değil.

Herkes bir ömür yaşadığımı sanıyor,

Ben o ömrün içinde kendime hiç rastlamadım.

#Emre', 'Bir kalabalığın ortasında yapayalnız kaldım, Herkesin arasında kendime bile uzaklaştım. Yüzümde bir tebessüm, içimde tarifi zor bir keder, K...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre Kulakoğlu']::text[], 8.5, '{"poet":"Yunus Emre Kulakoğlu","poet_slug":"yunus-emre-kulakoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bir-kalabaliga-bile-sigamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Değilim', 'yorgun-degilim-kerim-yavuz-ture7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben aşkını yıllardır kalbim de taşıyorum

Daha bin yıl taşırım inan yorgun değilim

Bir gün dönersin diye umutla yaşıyorum

Daha bin yıl yaşarım inan yorgun değilim

Yıllar oldu yüreğim ayrı düştü eşinden

Yanıyor alev alev hasretin ateşinden

Bıkmadan usanmadan koştum senin peşinden

Daha bin yıl koşarım inan yorgun değilim

Ben bunca fırtınaya nasıl dayandım şaştım

Kabarmış deniz gibi aşkınla dolup taştım

Sana ulaşmak için karlı dağları aştım

Daha bin dağ aşarım inan yorgun değilim', 'Ben aşkını yıllardır kalbim de taşıyorum Daha bin yıl taşırım inan yorgun değilim Bir gün dönersin diye umutla yaşıyorum Daha bin yıl yaşarı...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yorgun-degilim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Böyle Değildin', 'sen-boyle-degildin-kerim-yavuz-4g6px', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen böyle değildin ne oldu sana

Bağrıma bastığım taş olup çıktın

Senden ayrılmam diyordun bana

Şimdi hayatımdan düş olup çıktın

Ya sen bana anlat ya beni anla

Gönül dağlarımdan kış olup çıktın

İçimde kalmadı senden bir damla

Süzüldün gözümden yaş olup çıktın

Acı ızdırapsın çekilmez derdin

Söküp attırdığım diş olup çıktın

Kırdım kapısını sana yol verdim

Gönül kafesimden kuş olup çıktın', 'Sen böyle değildin ne oldu sana Bağrıma bastığım taş olup çıktın Senden ayrılmam diyordun bana Şimdi hayatımdan düş olup çıktın Ya sen bana ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-boyle-degildin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzellik', 'guzellik-kerim-yavuz-r4ek1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerime doğuyor

Yüzündeki güzellik

Bana neşe sunuyor

Sözündeki güzellik

Gönlüme pusu kurdu

Beni yürekten vurdu

Hep peşinden koşturdu

Nazındaki güzellik

Sensin benim sevdiğim

Diller de güzelliğin

En güzel özelliğin

Özünde ki güzellik

Sevmeye alıştırdı

Kendimle barıştırdı

Yeşille tanıştırdı

Gözünde ki güzellik

Gel gezelim illeri

Bende sözümün eri

Coşturur türküleri

Sazında ki güzellik

Huyların uslu kedi

Kalbimdesin ebedi

Yüreğime sev dedi

Yazında ki güzellik', 'Gözlerime doğuyor Yüzündeki güzellik Bana neşe sunuyor Sözündeki güzellik Gönlüme pusu kurdu Beni yürekten vurdu Hep peşinden koşturdu Nazın...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/guzellik-141-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ellerin Olursan', 'sen-ellerin-olursan-kerim-yavuz-7xgcf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidersen kanar yaram Gitme gözleri karam

Yaşamak bana haram Sen ellerin olursan

İnan ki Dünya durur Akan dereler kurur

Sebep olan kör olur Sen ellerin olursan

Bil ki yok olur tadım Tökezler durur atım

Zehir olur hayatım Sen ellerin olursan

Kalırsa bu aşk yarım Bölünür uykularım

Kan ağlar duygularım Sen ellerin olursan

Ayrılık sözü zülüm Bırakma beni gülüm

Lâyıktır bana ölüm Sen ellerin olursan

Özüme düşer ateş Sema da solar Güneş

Kereme olurum eş Sen ellerin olursan

Boran olur dağlarım Viran olur bağlarım

Gece gündüz ağlarım Sen ellerin olursan

Yıkılır hayallerim Bomboş kalır ellerim

Solar açan güllerim Sen ellerin olursan', 'Gidersen kanar yaram Gitme gözleri karam Yaşamak bana haram Sen ellerin olursan İnan ki Dünya durur Akan dereler kurur Sebep olan kör olur S...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-ellerin-olursan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğine Can mı Geldi?', 'yuregine-can-mi-geldi-kerim-yavuz-3hlg5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerin gülüyor bana Yüreğine can mı geldi?

Söyle neler oldu sana Yüreğine can mı geldi?

Kurumuş yaprak gibiydin Verimsiz topram gibiydin

Dünyadan uzak gibiydin Yüreğine can mı geldi?

Değer vermemiştin aşka Yüreğin dönmüştü taşa

Değişmişsin baştan başa Yüreğine can mı geldi?

Kulak ver de beni dinle Aşka mı bulaştın söyle?

Bu ne değişiklik böyle? Yüreğine can mı geldi?

Parıltı var gözlerin de Şirinlik var sözlerinde

Duramıyorsun yerinde Yüreğine can mı geldi?

Ben sevmiş sen sevmemiştin Aşka yalandır demiştin

Kalbini mühürlemiştin Yüreğine can mı geldi?', 'Gözlerin gülüyor bana Yüreğine can mı geldi? Söyle neler oldu sana Yüreğine can mı geldi? Kurumuş yaprak gibiydin Verimsiz topram gibiydin D...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuregine-can-mi-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atom Molekülü İnsanın Varlığı', 'atom-molekulu-i-nsanin-varligi-onder-karacay-xofs0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnsan, iki hidrojen bir oksijen, bir karbon iki oksijen atomundan oluşan bir molekül olarak geometrik ve elektrik ile tini birbirine bağlı kimyasal, biyolojik ve fiziksel bir varlıktır. Fizik ötesi tesirleri tini ve atom molekülü özelliği ile alan bir varlık olması yaşamın diğer paydaşlarından us ve duyunc farkındalığı üretmesi açısından ayrılır. 

Bilinç ve duyuncu güdüyü dengede tutabilme yeteneğine sahiptir. 

Nefsinin arzularına kendisine karşı oynanan oyunlara düşmediği müddetçe insanı ele geçirmek ve kullanmak mümkün değildir. 

İnsanı bu öz bilinç değerinden uzaklaştırmak için çabalayan küresel çete yapay zeka ile kendi değerinin farkına varmayan her insan şirk ağına düşürerek adeta alay etmektedir. 

Öz değer uyanışını bu sebeple durdurmak veya kendilerine hizmet eden bir anlayışa dönüştürmek niyeti de bu sebeple eninde sonunda boşa çıkartılacaktır. 

Yapay zeka bir şirk ve şer tufanı ibretidir. İnsanlık bu sınavdan geçmektedir.', 'İnsan, iki hidrojen bir oksijen, bir karbon iki oksijen atomundan oluşan bir molekül olarak geometrik ve elektrik ile tini birbirine bağlı k...', ARRAY['Türk Edebiyatı','Şiir','Önder Karaçay']::text[], 8.5, '{"poet":"Önder Karaçay","poet_slug":"onder-karacay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/atom-molekulu-insanin-varligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçlarını Bırak Seher Yeline', 'saclarini-birak-seher-yeline-kerim-yavuz-7m1xq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saçlarını bırak seher yeline

Gözlerine bakıp hayal kurayım

Dudağını uzat şarap yerine

Kadehi yerlere vurup kırayım

Deniz misin ırmak mısın göl müsün?

Menekşe mi  sümbül müsün gül müsün?

Beyaz güvercin mi bir bülbül müsün?

Söyle seni hangisinden sorayım

Bulutlar üstün de uçar gideriz

Mutluluğa yelken açar gideriz

Ben ırmak olayım sende bir deniz

Yıllar boyu sana akıp durayım

Bakışın ilkbahar sözlerinse yaz

Yanakların elma dudağın kiraz

Hadi gözlerime gülümse biraz

Yürekten kahkaha atıp durayım', 'Saçlarını bırak seher yeline Gözlerine bakıp hayal kurayım Dudağını uzat şarap yerine Kadehi yerlere vurup kırayım Deniz misin ırmak mısın g...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/saclarini-birak-seher-yeline-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Çıkan Yollar', 'sana-cikan-yollar-kerim-yavuz-n3bc1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana çıkan yollar kesildi bir bir

Gelmek istiyorum gelemiyorum

Kaderim böyleymiş elimde değil

Silmek istiyorum silemiyorum

Hep çile çekmekten ağardı saçım

Tükendi umudum kalmadı gücüm

Kime ne yaptım ki ne idi suçum

Bilmek istiyorum bilemiyorum

İstemem dünyayı verseler bana

Sen bir yana idin dünya bir yana

Sensiz yaşamaktan usandım amma

Ölmek istiyorum ölemiyorum', 'Sana çıkan yollar kesildi bir bir Gelmek istiyorum gelemiyorum Kaderim böyleymiş elimde değil Silmek istiyorum silemiyorum Hep çile çekmekte...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-cikan-yollar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt', 'agit-i-brahim-kiraz-fj2c7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '君のために枯れてしまった私の可憐な薔薇、

Kimi no tame ni karete shimatta watashi no karen''na bara,

 kimi no tame ni moeru watashi no tsubasa. 

Karera wa waraukeredo,

 watashi no tameiki wa moesakaru. 

Ushinawa reta fukai shunkan wa, 

minashigo no yō ni torinokosa reta. Itoshīhitoyo, 

kono doryoku wa yōide wanai. 

Gin to kin wa nokoru, hōsekishō ga hitsuyōda. Tenshi wa kimi ga nani o shita no ka to toudarou. 

Nagare tsudzukeru chi no namida wa, watashi no monoda.

Senin için solan nazik gülüm,

Yanan kanat benim, senin için.

Gülen onlar, yanık ahlar benim,

Yitip giden derin anlar yetim.

Basit değil yarim bunca emek 

Kalır gümüş altın sarraf gerek

Neler yaptın ettin sorar Melek

Akıp duran Kanlı Yaşlar benim.

君のために枯れてしまった私の可憐な薔薇、

Kimi no tame ni karete shimatta watashi no karen''na bara,

 kimi no tame ni moeru watashi no tsubasa. 

Karera wa waraukeredo,

 watashi no tameiki wa moesakaru. 

Ushinawa reta fukai shunkan wa, 

minashigo no yō ni torinokosa reta. Itoshīhitoyo, 

kono doryoku wa yōide wanai. 

Gin to kin wa nokoru, hōsekishō ga hitsuyōda. Tenshi wa kimi ga nani o shita no ka to toudarou. 

Nagare tsudzukeru chi no namida wa, watashi no monoda.', '君のために枯れてしまった私の可憐な薔薇、 Kimi no tame ni karete shimatta watashi no karen''na bara,  kimi no tame ni moeru watashi no tsubasa.  Karera wa warauke...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kiraz']::text[], 8.5, '{"poet":"İbrahim Kiraz","poet_slug":"i-brahim-kiraz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/agit-465-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Kötü Yollarda Gezdiğin İçin', 'hep-kotu-yollarda-gezdigin-i-cin-kerim-yavuz-hdij2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep kötü yollar da gezdiğin için

Sonun da çamura batmış gibisin

Ne gençliğin kalmış ne güzelliğin

Erimiş tükenmiş bitmiş gibisin

Benim gibi seven bulamamışsın

Bir gün bile mutlu olmamışsın

Aşkına karşılık alamamışsın

Kendini ucuza satmış gibisin

Gerçek mi sanmıştın yalan sözleri

Dostun mu sanmiştın sahte yüzleri

Yüzün de dertlerin derin izleri

Her türlü acıyı tatmış gibisin

Belliydi kaderin, gittiğin anda

Bir yanda endişe dertler bir yanda

Gizlemeye kalkma her şey meydanda

Bir derdine bin dert katmış gibisin

Zehir sana şimdi ekmeğin aşın

Dinecek mi bilmem akan göz yaşın

Derten kurtulmuyor çileli başın

Kuyruklu belâya çatmış gibisin

Gözlerin yaş dolu yüreğin yara

Dünün ziyan olmuş yarının kara

Dibi görünmeyen uçurumlara

Sen kendi kendini atmış gibisin', 'Hep kötü yollar da gezdiğin için Sonun da çamura batmış gibisin Ne gençliğin kalmış ne güzelliğin Erimiş tükenmiş bitmiş gibisin Benim gibi ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hep-kotu-yollarda-gezdigin-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırı Sayılır Delilerdenim', 'hatiri-sayilir-delilerdenim-kerim-yavuz-kbdgk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akıl mı kaldı ki başım da benim

Hatırı sayılır delilerdenim

Bil ki sana isyan etti bedenim

Hatırı sayılır delilerdenim

Sen beni yitirdin bunu böyle bil

Gönül defterinden artık beni sil

Öyle tatlı kaçık az buçuk değil

Hatırı sayılır delilerdenim

Vurulmuştum sana gördüğüm an da

Sen yoktun yanımda içim yanan da

İşte gör halimi her şey meydan da

Hatırı sayılır delilerdenim

Köz oldu yanıyor kalbim ateşte

İster hayalde gör istersen düşte

Sayende aklımı uçurdum işte

Hatırı sayılır delilerdenim

Umutlar besledim hayaller kurdum

Uğruna boş yere kendimi yordum

Meyhane meyhane gezindim durdum

Hatırı sayılır delilerdenim

Pişman olsan bile beni arama 

Çare bulamassın artık yarama

Herkes beni normal sanıyor amma

Hatırı sayılır delilerdenim', 'Akıl mı kaldı ki başım da benim Hatırı sayılır delilerdenim Bil ki sana isyan etti bedenim Hatırı sayılır delilerdenim Sen beni yitirdin bun...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hatiri-sayilir-delilerdenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güney Berlin''e Kaçış', 'guney-berlin-e-kacis-alper-tunga-3-f6zyv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu gün, bir suç işledim ve yarında...

Unutamıyorum...Ben herşeye şahit oldum.

Şimdi bir genaral vuruldu silahsız ve yıldızsız,

Dün bataklıktan su içerken, bu gün bir tarlada

General olduğunu söylememeliyim, söylemedim

Tanıdılar onu, bana kim inanabilir artık...

Artık üç kişiyiz. Saklanıyor ve kaçıyor

Dar köprülerde, şehir meydanlarında

Kurşuna dizilen esirler geliyor aklıma

Biriyle suyumu paylaşmıştım, bana bakıyordu

Bana kim inabilir, o tetiği ben çekmiştim.

Sovyetlerin keşif uçakları kadar küçük düşürücü,

Gittiğini zannederseniz ve ikinci saldırı uçağı...

Bir çok kan içmiş Rus size doğru koşarken mi,

Heryerde aranıyorken mi, kaçarken mi...

Temmuz takvimi için güney Berlin''e gitmeliyim.

Nerede olduğumuzu hiç bilmiyorum.

Kimin, kim olduğunu bu gün anlatamam.

Stalingrad bir cehennemdi ve sonrasıda

Önceside başka bir cehennemdi ve yarında...', 'Bu gün, bir suç işledim ve yarında... Unutamıyorum...Ben herşeye şahit oldum. Şimdi bir genaral vuruldu silahsız ve yıldızsız, Dün bataklıkt...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga 3']::text[], 8.5, '{"poet":"Alper Tunga 3","poet_slug":"alper-tunga-3","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/guney-berlin-e-kacis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '?????? Gamzede Değilim', 'gamzede-degilim-i-brahim-kiraz-62kqg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '别沉溺于酒窝

Bié chénnì yú jiǔwō, bié wèi mòshēng ér fánnǎo

àiqíng shì zǔzhòu, xiānshēng, bié míshī zài wéixiào de yǎn móu

mìngyùn yóu nǐ zhǎngkòng, yìzhì zài nǐ shǒuzhōng

bié yīn bù shùncóng shén de zhǐyì ér pànnì

zài ānquán de tǔdì shàng mànyóu, kàn, gǎnshòu, wúxū guānzhù jiǔwō

nǐ de línghún zǒng shì kěwàng wènhòu, xúnzhǎozhe chūlù

zhè shì yī zhǒng jiérán bùtóng de ài, mángmù de ránshāo

wǒ xīnzhōng de zhè huànyǐng shì shénme, bié zéguài wǒ de fùmǔ

Gamzelerde kalma ,gariplikle darda kalma

Aşk beladır efendi aman gülen gözlere dalma

Kader senin ettiğindir iraden elinin altında

Haktan gelene boyun bükmeyip asi olma

Emin beldelerde dolaş bir gör gamze görmeden dol,

Ruhun selam vermek ister hep arar bir yol,

Bambaşka bir sevdadır bu yanar durur kör,

Bu heyula nedir içimdeki Parende Tatyusu sakın ayıplama', '别沉溺于酒窝 Bié chénnì yú jiǔwō, bié wèi mòshēng ér fánnǎo àiqíng shì zǔzhòu, xiānshēng, bié míshī zài wéixiào de yǎn móu mìngyùn yóu nǐ zhǎngkòn...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kiraz']::text[], 8.5, '{"poet":"İbrahim Kiraz","poet_slug":"i-brahim-kiraz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gamzede-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umurumda Değilsin', 'umurumda-degilsin-kerim-yavuz-xc76w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gidersen güle güle umurumda değilsin

Seni unuttum bile umurumda değilsin

	Artık adımı anma sensiz yapamam sanma

	Boşuna havalanma umurumda değilsin

Sana boyun bükemem ardından yaş dökemem

Kaprisini çekemem umurumda değilsin

	Bırak yakamı bırak git başka birini yak

	Uzak dur benden uzak umurumda değilsin

Sana gönül veremem yüreğine giremem

Altın olsan istemem umurumda değilsin

	Güzelliğine kandım Sen de aşıksın sandım

	Nazlarından usandım umurumda değilsin', 'Gidersen güle güle umurumda değilsin Seni unuttum bile umurumda değilsin 	Artık adımı anma sensiz yapamam sanma 	Boşuna havalanma umurumda d...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umurumda-degilsin-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen gülünce', 'sen-gulunce-mahmut-kasapoglu-axqtn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gül desem sana bile, güller mahcup kalırlar,

Baktığın her köşede bahar olup açarlar.

Seni bir görenlerin o an değişir hâli,

Aşkı senden öğrenir yanan gönüller, çağlar.

Ay desem, ay da senin ışığını kıskanır,

Yıldızlar gökten iner, gözlerine yaslanır.

Bir tebessüm uğruna nice ömür adanır,

Sen gülünce kaderim yeni baştan canlanır.

Yâr desem eksik olur, can desem yetmez sana;

Sevda senden başlamış, sende varmış limana.

Kalbimin en kuytusu yazılmıştır adına,

Sensiz geçen her saat ağır gelir zamana.

Bir dokunsan gönlüme bahar iner içine,

Hasret bile diz çöker senin tatlı hâline.

En güzel anım oldu seninle karşılaşmak,

Şükürler ediyorum seni veren Rabb''ime.

Seni böyle yaratmak ne incelik, ne hüner!

Kirpiğinde sır saklı, gülüşünde bir gevher.

Sevdam ne bugün doğdu, ne de doğdu bu akşam;

İlk nefesimden beri bekliyormuşum meğer.

Gel desem uzak değil, git desen gidemem ki;

Adını silmek için başka bir ömür gerek.

Sana yazılmasam ben bu kadar sevemem ki,

Aşk dediğin biraz da kader, biraz da yürek.', 'Gül desem sana bile, güller mahcup kalırlar, Baktığın her köşede bahar olup açarlar. Seni bir görenlerin o an değişir hâli, Aşkı senden öğre...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-gulunce-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemiyorum', 'i-stemiyorum-kerim-yavuz-g4vfn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıkın köprüleri dönmesin geri

Gelmesin gelmesin istemiyorum

Neler çekiyorum gideli beri

Bimesin bilmesin istemiyorum

Ne inancı kalmış ne de duygusu

Kâbusa dönüşsün tatlı uykusu

Çölde kalsam bile iki damla su

Vermesin vermesin istemiyorum

Benim gibi seven kul bulamasın

Mutluluğa çıkan yol bulamasın

Kendine tutacak dal bulamasın

Gülmesin gülmesin istemiyorum

Zehir etti bana tatlı aşımı

Derde saldı benim dertsiz başımı

Şimdi gözlerimden akan yaşımı

Silmesin silmesin istemiyorum

Onu da çileler kalbinden vursun

Gelmesin istemem uzakta dursun

O da benim gibi sürünsün dursun

Ölmesin ölmesin istemiyorum', 'Yıkın köprüleri dönmesin geri Gelmesin gelmesin istemiyorum Neler çekiyorum gideli beri Bimesin bilmesin istemiyorum Ne inancı kalmış ne de ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/istemiyorum-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerine Doğacağım', 'gozlerine-dogacagim-kerim-yavuz-rcnqp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sensizlik canıma yetti

Artık sabrımı tüketti

Beni sana mecbur etti

Gözlerine doğacağım

Saklama kalbinde kini

Gizleme benden kendini

Merhametsiz hasretini

Ellerin de boğacağım

Sensin yıldızların eşi

Sensin gönlümün güneşi

Aşk denilen bu ateşi

Yüreğine yakacağım

Engeller dümdüz olacak

Karanlıklar dağılacak

Seni çöllerde bulacak

Köklerine yağacağım', 'Sensizlik canıma yetti Artık sabrımı tüketti Beni sana mecbur etti Gözlerine doğacağım Saklama kalbinde kini Gizleme benden kendini Merhamet...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerine-dogacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babamın ardından', 'babamin-ardindan-sabit-sureyya-sirer-ik2gr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir evladın, babasına söyleyemedikleri…

Baba…

Sen gideli bir başka doğuyor sabahlar,

Güneş aynı güneş, gökyüzü aynı gökyüzü…

Ama hiçbir şey eskisi gibi değil.

İnsan büyüyor baba,

Yaşı ilerliyor, saçlarına aklar düşüyor,

Fakat içinde bir çocuk kalıyor;

Her yorulduğunda seni arayan…

On dört Kasım''da dünyaya geldin,

Yetmiş dört yıl ömür sürdün bu dünyada.

On yedi Kasım''da sustu sesin,

Ama benim içimde hiç bitmedi yankın.

Takvimler üç günü gösteriyor belki,

Benim yüreğim o günden beri

Bir ömrü sensiz yaşıyor baba…

Bana hayatı anlatmadın belki her zaman,

Ama yaşayarak öğrettin birçok şeyi.

Dik durmayı, eğilmemeyi,

İnsanın sözüyle, özüyle bir olmasını…

Ve en önemlisi,

İnsan giderken ardında ne bıraktığıyla yaşar, demeyi.

Şimdi kendi yolumda yürüyorum,

Bazen bir kararın eşiğinde duruyorum.

İçimden bir ses yükseliyor:

"Babam olsaydı ne derdi?"

İşte o an anlıyorum baba,

Sen toprağın altında olsan da

Benim içimde hâlâ yol gösteriyorsun.

Ne makamın kaldı geriye ne de unvanın,

Ne de dünyaya ait başka bir şey…

Bir evladın yüreğinde bıraktığın iz kaldı.

Benim taşıdığım en kıymetli miras,

Adından önce öğrendiğim insanlık,

Ve senden bana kalan o görünmez bağ…

Bazen bir rüzgârda arıyorum seni,

Bazen gökyüzüne dalıp gidiyorum.

Belki bir kuşun kanadında geçiyorsundur,

Belki sessiz bir akşamın içinden

Bana bakıyorsundur…

Bilmeni isterim baba;

Ben hâlâ senin evladınım.

Yaşım kaç olursa olsun,

Hayat beni nereye götürürse götürsün,

Dünyanın bütün yollarını aşsam da

Senin yanındaki o çocuk kalacağım.

Ve bir gün,

Zamanın bütün mesafeleri ortadan kalktığında,

Sana anlatacak çok şeyim olacak.

Yarım kalan sohbetlerimizi tamamlayacağız,

Ben yine seni dinleyeceğim,

Sen yine susarak çok şey anlatacaksın…

O güne kadar adını yüreğimde taşıyacağım.

Çünkü bazı insanlar ölmez baba,

Yalnızca ellerini tutamazsın artık.

Ama öğrettikleriyle yaşar,

Hatıralarıyla çoğalır,

Evlatlarının yüreğinde ölümsüzleşir.

Sen benim geçmişim değilsin baba;

Sen, bugünümde taşıdığım köküm,

Yarınlarıma bıraktığın izsin.', 'Bir evladın, babasına söyleyemedikleri… Baba… Sen gideli bir başka doğuyor sabahlar, Güneş aynı güneş, gökyüzü aynı gökyüzü… Ama hiçbir şey ...', ARRAY['Türk Edebiyatı','Şiir','Sabit Süreyya Sirer']::text[], 8.5, '{"poet":"Sabit Süreyya Sirer","poet_slug":"sabit-sureyya-sirer","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/babamin-ardindan-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümün sultanı', 'gonlumun-sultani-mahmut-kasapoglu-e9qhd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Can dersem ben sana, sanma ki dilden;

Senden kıymetlisi göze görünmez.

Gönlümün sultanı sensin ezelden,

Senden başka yâre yüzüm hiç dönmez.

Ay dersem sana da sakın utanma,

Nurunla gecem bir seyran olur hep.

Gülüşün içime bahardır amma,

Sensiz geçen ömrüm hazan olur hep.

Gül dersem sana da dikeni sensin,

Acın da bal gelir sevdan uğruna.

Yarayı sen açtın, merhemi sensin,

Canımı adadım senin yoluna.

Yâr dersem sana da yeridir inan,

Vefanla gönlüme tahtını kurdun.

Bir ömür sürse de bitmez bu destan,

Kalbime adının mührünü vurdun.

Işık dersem sana boşuna değil,

Karanlık gecemde sabahımsın sen.

Bu yanış sevdanın oyunu değil,

Hem duam hem de tek günahımsın sen.

Su dersem sana da can suyu sensin,

Kuruyan gönlüme rahmet olup yağ.

Baharımın gülü, neşesi sensin,

Seninle yeşerir içimde her bağ.

Taç dersem sana da başımın tacı,

Dünyaya değişmem bir tek sözünü.

Sensizlik bağrımda zehirden acı,

Unutmam ömrümce ela gözünü.

Baht dersem sana da bahtımsın benim,

Yüzüm güldüyse hep senin yüzünden.

Gönlümde bir ahit, dilimde yemin:

Ayrılmam ölsem de senin izinden.

Ömür dersem sana eksiktir bu söz,

Seninle anlamlı her bir zamanım.

Nereye baksam da sende kalır göz,

Sensin her nefesim, sensin cananım.

Son dersem sana da sonum ol artık,

Başlangıcım sensin, sensin duam da.

Allah''tan dileğim ebedî birlik,

Adın yazılsın hep alın yazımda.', 'Can dersem ben sana, sanma ki dilden; Senden kıymetlisi göze görünmez. Gönlümün sultanı sensin ezelden, Senden başka yâre yüzüm hiç dönmez. ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/gonlumun-sultani-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Olsun İstiyorum', 'sevgi-olsun-i-stiyorum-kerim-yavuz-fj3bc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönülden gönüle akan

Sevgi olsun istiyorum

Benim yüreğimi yakan

Sevgi olsun istiyorum

Dağlaraın en tepesinde

Rüzgarların nefesinde

Denizin dalga sesinde

Sevgi olsun istiyorum

İnsanların özlerinde 

Şarkıların sözlerinde

Sevnlerin gözlerinde 

Sevgi olsun istiyorum

Duvarda ki resimlerde

Seyrettiğim filmlerde

Romanlarda şiirlerde

Sevgi olsun istiyorum

Bir bebek doğduğu anda

Damarında akan kan da

Tüm annelerin koynunda

Sevgi olsun istiyorum

Dünyanın tur atışında

Hem yazında hem kışında

Güneşin her doğuşunda

Sevgi olsun istiyorum', 'Gönülden gönüle akan Sevgi olsun istiyorum Benim yüreğimi yakan Sevgi olsun istiyorum Dağlaraın en tepesinde Rüzgarların nefesinde Denizin d...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevgi-olsun-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seversen Mutlu Olursun', 'seversen-mutlu-olursun-kerim-yavuz-s6pxe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sev ki sende sevilesin

Nefret senden geri dursun

Bak bunu böyle bilesin

Seversen mutlu olursun

Aç gönlünü sevgi ile

Tomurcuklar dönsün güle

Kurumuş yaprağı bili

Seversen mutlu olursun

Ses gelsin gönül telinden

Oynatsın seni yerinden

Eser kalmaz dertlerinden

Seversen mutlu olursun

Mutluluk değildir para

Mutluluğu sende ara

Sevgisiz kalp düşer dara

Seversen mutlu olursun

Kim sever ki kem gözleri

Kim sever acı sözleri

Garipleri öksüzleri 

Seversen mutlu olursun

Gelip geçti bunca sene

Sen halâ mutsuzsun gene

Bir kez olsun sen de dene

Seversen mutlu olursun', 'Sev ki sende sevilesin Nefret senden geri dursun Bak bunu böyle bilesin Seversen mutlu olursun Aç gönlünü sevgi ile Tomurcuklar dönsün güle ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seversen-mutlu-olursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'L''ihsan en Islam : la dimension cultuelle du travail bien fait', 'l-ihsan-en-islam-la-dimension-cultuelle-du-travail-bien-fait-muhammed-ridvan-gizri-48f3x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'L''Islam n''est pas une religion qui se réduit à l''accomplissement de certains actes cultuels. Au contraire, outre les piliers fondamentaux que sont la prière, le jeûne et le hajj, chaque bon comportement que l''être humain manifeste dans sa vie quotidienne a également de la valeur auprès d''Allah. De l''acte de céder sa place à une personne âgée dans le bus jusqu''à la quête d''une subsistance licite (halal), de nombreux actes peuvent, selon l''intention et leur nature profonde, acquérir la valeur d''un acte d''adoration. Au cœur de cette conception se trouve l''ihsan, l''un des concepts fondamentaux de l''éthique islamique.

Qu''est-ce que l''ihsan ?

Le mot signifie littéralement « faire de la plus belle manière, faire le bien », mais il revêt dans la littérature religieuse un sens bien plus profond. L''ihsan ne concerne pas seulement la qualité du travail : il est aussi directement lié à la relation de conscience que la personne entretient avec Allah. Dans son essence, l''ihsan comprend les trois dimensions suivantes :

- Qualité : que le travail accompli soit solide, complet et soigné

- Intention : que le travail soit accompli en recherchant l''agrément d''Allah

- Constance : manifester ce soin non seulement lorsqu''on est contrôlé, mais en toute circonstance

Le message de la perfection de l''univers

Derrière la conception islamique de l''ihsan se trouve un principe universel : Allah a créé toute chose de la plus belle manière. Le Saint Coran exprime cette vérité de façon explicite. La chaleur et la lumière du soleil, l''ordre des étoiles dans le ciel, le fonctionnement parfait du corps humain et les équilibres délicats qui rendent la vie possible sur terre : tout cela est le reflet concret de l''art et de la perfection divins. La perfection dont le Très-Haut a fait preuve en créant cet univers impose en même temps une responsabilité à l''être humain : toi aussi, fais ton travail de la plus belle manière. Car l''être humain doit avoir un caractère empreint de responsabilité, qui ne relâche jamais son souci du travail bien fait.

L''ihsan dans la vie quotidienne : les domaines de responsabilité

L''ihsan est une vertu qui doit se manifester non seulement à la mosquée ou pendant l''acte d''adoration, mais dans tous les domaines de la vie. Dans ce cadre, on peut examiner ce que signifie l''ihsan pour différents groupes professionnels et rôles sociaux :

Le fonctionnaire et l''agent public : Un fonctionnaire doit accomplir sa tâche de la manière la plus juste et la plus complète, non pas parce qu''il est sous la surveillance de son supérieur, mais dans la conscience qu''Allah le voit à chaque instant. L''essence du service public n''est pas l''intérêt personnel, mais l''utilité collective. Un agent public qui agit avec l''ihsan intériorise cette responsabilité.

L''enseignant et l''éducateur : Être enseignant, ce n''est pas seulement remplir des heures de cours, c''est façonner les générations de demain. Un enseignant animé par l''ihsan entre en classe avec l''enthousiasme de se demander : « Que puis-je enseigner à mes élèves aujourd''hui, qu''est-ce que je peux apporter à leur vie ? » Sans cet enthousiasme et cette conscience de sa responsabilité, l''enseignement ne dépasse pas l''accomplissement d''une tâche technique.

Le producteur et le commerçant : Transiger sur l''honnêteté en produisant ou en vendant une marchandise est une lourde responsabilité, tant sur le plan juridique que moral. Produire des biens de qualité et solides n''est pas seulement un choix commercial, c''est aussi une obligation religieuse. L''Islam interdit catégoriquement de réaliser un gain injuste en présentant sa marchandise autrement qu''elle n''est, en trichant sur le poids ou en la vendant à un prix exorbitant.

L''ouvrier et le travailleur : Un ouvrier d''usine se comporte-t-il différemment lorsqu''il est sous le regard de l''employeur et lorsque celui-ci a le dos tourné ? La conception de l''ihsan rend cette question absurde, car le fondement de l''ihsan est la conscience d''être à chaque instant en présence d''Allah. Un ouvrier qui travaille avec cette conscience rend aussi son labeur licite et béni.

Le gain licite et l''évitement du gain illicite

Dans l''éthique islamique du travail, il est extrêmement important que le gain soit obtenu par des moyens licites. Cela ne signifie pas seulement se tenir à distance des sources illicites (haram), mais exige aussi que la méthode d''acquisition du gain soit honnête et équitable. Un gain obtenu par la tromperie, en fixant un prix supérieur à la valeur réelle, a beau ressembler en apparence à un profit, il nuit sur le plan spirituel à la personne comme à la société. Celui qui fait bien son travail et gagne honnêtement sa vie obtient ainsi l''agrément d''Allah et renforce en même temps la confiance sociale.

Le travail accompli avec sincérité : sa dimension spirituelle

De même qu''il existe une différence profonde entre une prière accomplie dans le recueillement et une prière bâclée, il existe la même différence profonde entre un travail accompli avec sincérité et un travail accompli en fuyant ses responsabilités. La sincérité et la conscience que l''on recherche dans les actes d''adoration doivent aussi être recherchées dans les tâches quotidiennes. En ce sens, ensemencer un champ pour qu''il soit fertile, construire solidement un bâtiment, soigner un malade avec attention ou former un élève avec patience : tout cela peut, lorsque cela est fait avec une intention juste, avoir valeur d''acte d''adoration. Ce pont entre la religion et le monde est la plus belle manifestation de la conception globale de la vie propre à l''Islam.

Le témoignage de l''histoire : une civilisation fondée sur la sincérité

Le monde islamique, qui a fondé une grande civilisation dans l''histoire, n''a pas atteint ce succès par un effort ordinaire, mais par la sincérité (ikhlas), l''honnêteté et le souci de la qualité. Les avancées scientifiques d''al-Andalus, les édifices grandioses de l''architecture ottomane, les apports de la médecine islamique à l''humanité : tout cela est le fruit de personnes qui accomplissaient leur travail avec ihsan. Les mosquées, les madrasas et les ponts construits à cette époque sont encore debout plusieurs siècles plus tard. Cette solidité ne tient pas seulement à la force de la pierre et du mortier, mais aussi, directement, au sens de la responsabilité devant Allah qu''avaient ceux qui assemblaient cette pierre et ce mortier. De nos jours également, faire sienne à nouveau cette conception est la condition la plus fondamentale de l''élévation individuelle et collective.

La conception islamique de l''ihsan offre une alternative solide aux approches qui séparent nettement la vie religieuse de la responsabilité terrestre. Selon cette conception, l''être humain doit être ferme dans sa foi, sincère dans ses actes d''adoration, et compétent et honnête dans son travail. Là où ces trois éléments sont réunis, la responsabilité envers Allah est remplie et la dette envers l''humanité est acquittée. L''élévation véritable d''une société dépend de ce fondement moral avant même de dépendre de sa puissance technologique ou économique. L''ihsan est une valeur que chacun peut, à partir de son propre coin, répandre dans toute la société. Et c''est peut-être cela dont nous avons le plus besoin aujourd''hui : des personnes qui accomplissent leur travail en sachant qu''Allah les voit.', 'L''Islam n''est pas une religion qui se réduit à l''accomplissement de certains actes cultuels. Au contraire, outre les piliers fondamentaux qu...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/l-ihsan-en-islam-la-dimension-cultuelle-du-travail-bien-fait-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her hali kader', 'her-hali-kader-mahmut-kasapoglu-uvdix', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecelerde kor olur yüreğimin her sözü,

Hasret ile sulanır gönlümün mahzun özü.

Yazılmışsa alnıma hicranın acı yüzü,

Gülüşünde de kader, bakışında da kader.

Ruhumda mühürlüdür gözlerinin son izi,

Bağrımda saklı kaldı ilk sevdamızın gizi.

Kurumadı bir türlü ayrılığın denizi,

Sessizliğinde kader, çığlığında da kader.

Ne bir umut yeşerdi, ne bir düş buldu durak,

Her sevincin ardında bekler pusuda firak.

Bitmez sanmıştım aşkı, oysa kurulu tuzak;

Başlangıcında kader, bitişinde de kader.

Sevda, dedim, ömrüme sonsuzluğu yazacak;

Meğer kader kalbime ayrılığı kazacak.

Gözlerimde her damla seni diye akacak,

Yağmurunda da kader, sellerinde de kader.

Yandıkça çoğalıyor küllerimde köz sesin,

Geceleri büyüyor içimdeki hasretin.

Asırlar yetmez imiş, dinmez bende bu derdin;

Yarasında da kader, merheminde de kader.

Varsın dünya dönsün hep başka başka renklere,

Benim bahtım bağlanmış suskun eski günlere.

Aşk dedikleri şeymiş: boyun eğmek küllere;

Yanışında da kader, küllenişinde kader.

Bir avuç hatırayla ayakta kaldım yine,

Adını fısıldadım gecelerin tenine.

Bu sevda işlenmişse kalbimin derinine,

İşlenişte de kader, silinişte de kader.

Senden kaçtım, ama hep döndüm aynı yollara,

Kederimi yükledim ağır akan sulara.

Sen öğrettin: aşk bazen sığmıyormuş yıllara;

Özleminde de kader, vuslatında da kader.

Dilerim ki bir sabah doğsun bahtın güneşi,

Sönsün artık gözünde ayrılığın ateşi.

Anladım ki sevdanın değişmiyor nakışı;

Yazısında da kader, duasında da kader.', 'Gecelerde kor olur yüreğimin her sözü, Hasret ile sulanır gönlümün mahzun özü. Yazılmışsa alnıma hicranın acı yüzü, Gülüşünde de kader, bakı...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/her-hali-kader-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sayılır', 'sayilir-kerim-yavuz-wqeny', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yan yana dizilse kızlar

Onu gören yürek sızlar

Gökte parlayan yıldızlar

Yanında sönük sayılır

Doğadaki bütün renkler

Kırlarda açan çiçekler

Yeşil mavi elâ gözler

Yanında donuk sayılır

On sekize yeni girmiş

Serpilmiş kemâle ermiş

Dünya güzelide kimmiş

Yanında sıfır sayılır

Sarı saçlar lüle lüle

Benzer yanakları güle 

Elmas zümrüt altın bile

Yanında gümüş sayılır', 'Yan yana dizilse kızlar Onu gören yürek sızlar Gökte parlayan yıldızlar Yanında sönük sayılır Doğadaki bütün renkler Kırlarda açan çiçekler ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sayilir-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neydi bu şehrin adı.', 'neydi-bu-sehrin-adi-cevat-cestepe-zftl2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'NEYDİ BU ŞEHRİN ADI…

.

Efkar bastıran kayıpların izleri peşinde…

Zaman hırsızının çalıp, ardına bakmadan kaçarken torbasından dökülen 

caddelerinden sökülmüş paslı raylar arasında dolaşırken aklıma takıldı…

Düşündükçe kınından çekilmiş gümüş bir bıçak gibi parlayan o hatıraları

tüm kayıtlardan silinen ve unutulmaya mahkûm müebbet hüküm giyen,

neydi bu şehrin adı…

. ,

Şimdi kadim bir hayalin sessizliğinde…

Ardında beyaz köpüklü dalgalar bırakıp, vapurlara yoldaş olan martıları

ve bir kenara atılan balıkçı ağlarında, kedilerin o cennet kokulu uykuları…

Artık çoktan sönmüş ışıklarıyla, anılarda gece gündüz ışıl-ışıl ışıldayan

hesabı borçlu zamanlara saklanmış ve hasreti vurgun olup yürek vuran,

sahi neydi bu şehrin adı…

. ,

Sudan uzak, sabundan yoksun göndermelerle sahi neydi bu şehrin adı,

bu ülkenin adı…

.

Cevat Çeştepe

Kasım 2026', 'NEYDİ BU ŞEHRİN ADI… . Efkar bastıran kayıpların izleri peşinde… Zaman hırsızının çalıp, ardına bakmadan kaçarken torbasından dökülen  cadde...', ARRAY['Türk Edebiyatı','Şiir','Cevat Çeştepe']::text[], 8.5, '{"poet":"Cevat Çeştepe","poet_slug":"cevat-cestepe","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/neydi-bu-sehrin-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer Bahçıvan Körse', 'eger-bahcivan-korse-sukrullah-yavuzer-0bfnq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimi bahçeler vardır; toprakları taze, suları berrak, tohumları en asilinden umutlarla ekilmiştir. Ancak o bahçenin kaderini tayin eden şey, ne toprağın cömertliği ne de gökyüzünün rahmetidir. Bütün mesele, o bahçenin emanet edildiği ellerdedir. Eğer bahçıvan körse, yani çiçeğin rengini göremez, susuzluğunu yaprağının titreyişinden okuyamaz, güneşe olan hasretini sezemezse; o bahçede en güzel güller dahi boynunu büküp toprağa küser.

Hayatın da kendine mahsus bahçeleri vardır. Kalbimiz, emeğimiz, sevgimiz, zamanımız ve zihnimiz... Bunların her biri özenle bakılması, incelikle budanması, şefkatle sulanması gereken nadide çiçeklerdir. Ne var ki insan, ömrünün bazı dönemlerinde en değerli hazinelerini yanlış ellere, yanlış yüreklere teslim eder.

"Ehline denk gelmeyen her şey solar."

Bu cümle, hayatta yaşanabilecek en sessiz ve en derin acının özetidir.

İlgi görmeyen sevgi körelir; bir zamanlar dağları deviren o coşku, yanlış anlaşılmaların arasında boğulup can verir.

Değeri bilinmeyen emek insanı yorar; en gayretli ruhlar dahi, çabasının karşılığını kör bir gözde, sağır bir kulakta kaybolduğunu gördüğünde vazgeçer.

Anlaşılmayan hassasiyet hırpalanır; ince kalpler, kaba dokunuşlar altında yaprak döker.

Kör bir bahçevanın elinde, dünyanın en nadide orkidesi bile sıradan bir ot muamelesi görür. Bahçıvanın gözleri görmediği için çiçeğin soluşunu suçlayamazsınız; hata çiçeği o toprağa, o kör ellerin merhametine bırakan zamandadır.

Oysa her çiçek, kendisini anlayan, rengini sevinçle karşılayan, kokusunu içine çeken bir bahçevanın ellerinde yeniden dirilir. Solan çiçeklerin ardından üzülmek yerine, belki de asıl yapılması gereken, ellerin kıymetini bilen bir iklime doğru yola çıkmaktır. Çünkü biliyoruz ki toprak ne kadar kısır olursa olsun, ehil ellerde can bulur; ama ehline denk gelmeyen en görkemli bahçeler bile sessizce kuruyup gider.', 'Kimi bahçeler vardır; toprakları taze, suları berrak, tohumları en asilinden umutlarla ekilmiştir. Ancak o bahçenin kaderini tayin eden şey,...', ARRAY['Türk Edebiyatı','Şiir','Şükrullah Yavuzer']::text[], 8.5, '{"poet":"Şükrullah Yavuzer","poet_slug":"sukrullah-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/eger-bahcivan-korse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğruyu Söyle', 'dogruyu-soyle-kerim-yavuz-tdnk8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dinle beni güzel sözüm var sana

Uzak dur yalandan doğruyu söyle

Derde düşsem meylin kalır mı bana

Yine severmisin doğruyu söyle

Seninle dolarken bu gönül tasım

Elbette neşeli mutluluk dansım

Farz et dertten yana dönmüyor şansım

Yine severmisin doğruyu söyle

Eski sevdalara veren yok değer

Sen geçmişi düşün aşkı öyle der

Yolum çıkmazlara düşerse eğer

Yine severmisin doğruyu söyle

Kader yollarımı çıkmaza soksa

Dikenli yollardan çıkışım yoksa

Yüreğim köz gibi yanıp kül olsa

Yine severmisin doğruyu söyle

Farz et dertler bana vermiyor aman

Farz et efkârdayım başım hep duman

Yolum çıkmazlara düştüğü zaman

Yine severmisin doğruyu söyle

Kapanmaz kalbimden bu aşkın izi

Engel tanımaz ki aşkın krizi

Ayrılığa mahküm etseler bizi

Yine severmisin doğruyu söyle', 'Dinle beni güzel sözüm var sana Uzak dur yalandan doğruyu söyle Derde düşsem meylin kalır mı bana Yine severmisin doğruyu söyle Seninle dola...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dogruyu-soyle-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadehi Yavaşça Vursan', 'kadehi-yavasca-vursan-kasim-kobakci-4b51j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kadehi yavaşça vursan,

Masada uykuya dursan,

Hayale bir köprü kursan,

Ruhunu uykuyla sarsan.

*

Bu masada biz kalalım,

Kadehleri hep sayalım,

Tatlı uykuya dalalım,

Usulca yana kayalım.

*

Gelecek nesiller içsin,

Kendinden sessizce geçsin,

Uykudan kaftanlar biçsin,

Gözleri uykuyu seçsin.', 'Kadehi yavaşça vursan, Masada uykuya dursan, Hayale bir köprü kursan, Ruhunu uykuyla sarsan. * Bu masada biz kalalım, Kadehleri hep sayalım,...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kadehi-yavasca-vursan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaf`lar Ve Kef`ler', 'kaf-lar-ve-kef-ler-selim-ozl-lh6h1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KAFLAR VE KEFLER

Kaf ve kef, harf harf dokunuyor adın, gönül defterime.
Başı yok bir sevda , 
sevdan örülüyor kelimelerle şimdi.
Kaflar ve kefler
 işliyor duyguları ilmek ilmek.
Ne çok özel oluyor,
senin geçtiğin cümleler.
Harflerden kelimeler..
anlamlar...
Düşler... sen.... ve sevinçler.
Şimdi durur kelimeler,
 duygularda anlam çaresiz .
Ne güzel şey seni sevmek , 
tarifsiz derin nehirler.
Ne güzel olur, 
içinde adın yazılmış sözlerde, halim.
Harfler çare bulamaz hislere...
sen geçince içimden 
hayallerle haller ve nehirler.
Adın sevgi bağlarına bir anahtar.
Açılır Sen deyince kapıları
Sen deyince başlar yeniden
Başlar anlamlara kelimeler.
Yine Sözler, kaf''lar ve kef''ler', 'KAFLAR VE KEFLER Kaf ve kef, harf harf dokunuyor adın, gönül defterime. Başı yok bir sevda ,  sevdan örülüyor kelimelerle şimdi. Kaflar ve k...', ARRAY['Türk Edebiyatı','Şiir','Selim Özl']::text[], 8.5, '{"poet":"Selim Özl","poet_slug":"selim-ozl","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kaf-lar-ve-kef-ler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Küstün', 'neden-kustun-kerim-yavuz-6esp3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söyle bana neydi suçum

Neden küstün bana Dünya

Tükendim kalmadı gücüm

Neden küstün bana Dünya

Çile ömrümün her anı

Elimde durur fermanı

Yemedim haram lokmanı

Neden küstün bana Dünya

Kıymetini mi bilmedim

Sana değer mi vermedim

Suçum neydi bilemedim 

Neden küstün bana Dünya

Acı söz yoktur sözüme

İhanet yoktur özüme

Hiç gülmüyorsun yüzüme

Neden küstün bana Dünya

Hançer yedim yüreğimden

Kalbim sızlıyor derinden

Çevirdin yüzünü benden

Neden küstün bana Dünya

Bu ne insafsızlık böyle

Gel halime insaf eyle

Kastın mı var bana söyle

Neden küstün bana Dünya', 'Söyle bana neydi suçum Neden küstün bana Dünya Tükendim kalmadı gücüm Neden küstün bana Dünya Çile ömrümün her anı Elimde durur fermanı Yeme...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/neden-kustun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimle', 'kalbimle-mahmut-kasapoglu-o689n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlıktan korkmadan daldım ıssız çöllere,

Her adımım can kattı suskun kalan dillere.

İnandıkça eriştim en kutlu menzillere,

Yıldızları bağladım umut dolu kalbimle.

Bir dağ çıktı karşıma, aşındırdım taşını,

Rüzgârlara bıraktım gönlümün gözyaşını.

Yıkılmadım, kaldırdım her düşenin başını,

Merhameti kuşandım şefkat dolu kalbimle.

Kırık düşler topladım yolların kıyısından,

Bir çiçek büyüttüm ben taşların oyasından.

Gülüşler devşirerek ömrün en koyusundan

Baharları çağırdım sevgi dolu kalbimle.

Hakikatin sesini duydum her nefesinde,

İnsanlığın izini sürdüm her hecesinde.

Kibre hiç yer vermedim ömrümün köşesinde,

Tevazuyla yürüdüm vakur duran kalbimle.

Nice fırtınalardan selametle geçerek,

Umudumu çoğalttım karanlığı biçerek.

Her yenilgi ardından yeni bir yol seçerek

Zaferimi dokudum metin duran kalbimle.

Dost bildiğim ellerden incinse de yüreğim,

Sevgiyle doldu taştı hem dilim hem dileğim.

Affetmekle yoğruldu en derinden emeğim,

Kin ateşin söndürdüm engin olan kalbimle.

Bir damlayı ummana katabildimse eğer,

O zaman ömrüm olur ardımda kalan eser.

İyilikten yükselir en erişilmez değer,

İz bıraktım zamana pak ve temiz kalbimle.

Ne dün beni tüketti ne de yarın yıldırdı,

İnancım düştüğümde tutup beni kaldırdı.

Her son yeni bir doğuş, gönlüm bunu haykırdı,

Ufuklara uzandım huzur dolu kalbimle.

Fanidir dünya, baki hoş bir seda bırakmak,

Mazluma el uzatıp yaralarını sarmak.

En büyük servet budur: gönüllerde yer almak,

Zenginliği tattım ben cömert olan kalbimle.

Son nefeste dilerim yüzüm ak, alnım açık,

Geride kalanlara olsun sözüm bir ışık.

Sevgiyle atan yürek düşse de kalmaz yıkık,

Ebediyeti andım iman dolu kalbimle.', 'Karanlıktan korkmadan daldım ıssız çöllere, Her adımım can kattı suskun kalan dillere. İnandıkça eriştim en kutlu menzillere, Yıldızları bağ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kalbimle-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Oldu Sana', 'ne-oldu-sana-kerim-yavuz-6pwbq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen değil miydin pencereden yollarımı kollayan

Sen değil miydin kaderini aşkımıza bağlayan

Sen değil miydin bu aşk için gece gündüz ağlayan

Ne oldu sanada değiştin böyle 

Başka biri mi var çekinme söyle

Hani ben bölerdim uykularını

Hani ben süslerdim rüyalarını

Gel gülüm aç bana sorunlarını

Ne oldu sana da değiştin böyle 

Başka biri mi var çekinme söyle

Sen değil miydin ismimizi ağaçlara kazıyan

Sen değil miydrin kollarını bedenime dolayan

Sen değil miydin mutluğu aşkımız da arayan

Ne oldu sana da değiştin böyle 

Başka biri mi var çekinme söyle

Bilirsin sevenler seveni özler

Söyle yalanmıydı verdiğin sözler

Hani nerede o sevdalı gözler

Ne oldu sana da değiştin böyle 

Başka biri mi var çekinme söyle', 'Sen değil miydin pencereden yollarımı kollayan Sen değil miydin kaderini aşkımıza bağlayan Sen değil miydin bu aşk için gece gündüz ağlayan ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-oldu-sana-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmiyor', 'yetmiyor-kerim-yavuz-xbuah', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdim seni elâ gözlüm 

Yüreğime söz geçmiyor

Koşuyorum ardın sıra

Takadım sana yetmiyor

Alev alev yanıyorum

Sensizlik hiç çekilmiyor

İsmini haykırıyorum

Nefesim sana yetmiyor

Hep seni düşünüyorum

Aşkını aklım ermiyor 

Durdursunlar saatleri

Zamanım sana yetmiyor', 'Sevdim seni elâ gözlüm  Yüreğime söz geçmiyor Koşuyorum ardın sıra Takadım sana yetmiyor Alev alev yanıyorum Sensizlik hiç çekilmiyor İsmini...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yetmiyor-124-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstersen', 'i-stersen-mahmut-kasapoglu-lhyxl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bozkıra düşmüş bir selam mısın sen?

Yüreğim yayladır, varmak istersen.

Gecemin koynunda kelam mısın sen?

Dilimde duadır, durmak istersen.

Yorulmuş ömrüme gölgeni ser de,

Bir çift söz bırak da çiçekler der de.

Gönülden ekelim sevdayı yerde,

Başakta baş olur, sürmek istersen.

Dağların başına duman çökerken,

Hasretin içime korlar dökerken,

Her sabah adınla şafak sökerken,

Açarım kapımı, girmek istersen.

Kırılan dallara bahar değince,

Kuruyan pınarlar çağlar sevince.

Kul Hakk''a diz çöküp boyun eğince

Düzelir yazılar, görmek istersen.

Ne mala aldanmış ne şana kulum,

Bir garip sevdaya düşmüşüm gülüm.

Doğruyu söylemek benim tek yolum,

Darılmaz yüreğim, sormak istersen.

Gün gelir dağ taş da dile kavuşur,

Sabreden bülbül de güle kavuşur.

Hak diye yürüyen gönle kavuşur,

Tut elimden benim, ermek istersen.', 'Bozkıra düşmüş bir selam mısın sen? Yüreğim yayladır, varmak istersen. Gecemin koynunda kelam mısın sen? Dilimde duadır, durmak istersen. Yo...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/istersen-131-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar Gelin Giderken', 'yar-gelin-giderken-kerim-yavuz-f5s37', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben yare aşkımı söyleyemedim

Allah’ın emriyle istetemedim

Böyle olur sonum hiç bilemedim

Yar güllere ben dikene büründüm

Saçına takmışlar beyaz simleri

Eline vermişler gül çiçekleri

Neşe saçıyorken elâ gözleri

Yar sevince ben mateme büründüm

Yaktı yüreğimi burdan gidedken

Davul zurna köy içinde inlerken

Yar gelin olmuş ta ata binerken

Yar beyaza ben karaya büründüm', 'Ben yare aşkımı söyleyemedim Allah’ın emriyle istetemedim Böyle olur sonum hiç bilemedim Yar güllere ben dikene büründüm Saçına takmışlar be...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yar-gelin-giderken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çeşme Güzeli', 'cesme-guzeli-kerim-yavuz-lrole', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elinde testisi gidiyor suya

Yanağı gamzeli gözleri rüya

Canımı verirdim o fidan boya

Aksa yüreğime çeşme güzeli

Daha yeni girdi yirmi yaşına

Yan gelip oturmuş çeşme taşına

Kırmızı gülleri taktı saçına

Yaktı yüreğimi çeşme güzeli

Çeşmenin altında dolar testisi

Vurulmuşum ona boştur gerisi

Ela gözlerine baksa birisi

Yakar yüreğimi çeşme güzeli

Sanki gökten yıldız düştü yerlere 

Dolamış kemeri ince bellere

Bilsin ki yar etmem onu ellere

Canımın canıdır çeşme güzeli 

Toplanmış çeşmede kızı kadını 

Bilen bilir sevdalığın tadını

Kalbimin içine yazdım adını

Yatar yüreğime çeşme güzeli', 'Elinde testisi gidiyor suya Yanağı gamzeli gözleri rüya Canımı verirdim o fidan boya Aksa yüreğime çeşme güzeli Daha yeni girdi yirmi yaşına...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cesme-guzeli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sislerin ardından', 'sislerin-ardindan-mahmut-kasapoglu-bpiuh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine bulutlar çöktü dağların omzuna,

Kül kokulu akşamlar indi yüreğime.

Adını rüzgârlara söyledim usulca,

Yankısı geri döndü bu sessizliğime.

Sen bana bahar diye açan kardelendin,

Ben sana karlar içre üşüyen dağ oldum.

Bir ömür beklemenin sessiz duasıyla

Kaderin kapısında yanan çerağ oldum.

Gözlerinden bir damla yaş eğer düşerse,

Bil ki benim içimde deniz olup taşar.

Sen ağlama sevgilim, ben gözyaşlarını

Şifa diye içerim, gönlüm öyle yaşar.

Dünya bize dar geldi, vakit bize küstü,

Ne vuslat nasip oldu ne de sıcak bir el.

Lakin bil ki mahşerde ilk aradığım sen,

Son sevdam da yine sen, ey ezelî güzel.

Şimdi yine bulutlar üstüme yürürken,

Umutlar yorgun düştü, ufuklarım duman.

Sen artık sus sevgilim, bozma düşlerini;

Ben geleceğim elbet, sislerin ardından…

Ya bu dünyada,

Ya da Rabbimin bizi ayırmadığı

O sonsuz zamanda…', 'Yine bulutlar çöktü dağların omzuna, Kül kokulu akşamlar indi yüreğime. Adını rüzgârlara söyledim usulca, Yankısı geri döndü bu sessizliğime...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sislerin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Ne Olursun', 'gel-ne-olursun-kerim-yavuz-ferhu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seviyorum seni anla halimden

Damarım da kansın gözümde nursun

Bilesin ki ismin düşmez dilimden

Bırak şu gururu gel ne olursun

Hasretin kalbime ederken zülüm

Diyardan diyara savruldu külüm

Sensizlik çekilir dert değil gülüm

Bırak şu gururu gel ne olursun

Sensizlik kendimle açtı aramı

Bıraktı elime kederi gamı

Daha fazla deşme gönül yaramı

Bırak şu gururu gel ne olursun

Yok et yüreğimden haykırışları

Gel de at içimden kara kışları

Silinsin gözümden hasret yaşları

Bırak şu gururu gel ne olursun

Bir kuru ekmeği bölüşür yeriz

Alın yazımıza boyun eğeriz 

Ayrı kalamayız gülle dikeniz

Bırak şu gururu gel ne olursun', 'Seviyorum seni anla halimden Damarım da kansın gözümde nursun Bilesin ki ismin düşmez dilimden Bırak şu gururu gel ne olursun Hasretin kalbi...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-ne-olursun-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Gücü', 'sevginin-gucu-kerim-yavuz-9o3ni', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünya onunla tur atar

Her işin temeli sevgi

Yolun en sonuna kadar

Yüreğin emeli sevgi

Sevmek gerek dolu dolu

Segidir mutluluk yolu

Sevmesini bil yeter ki

Güler sana Anadolu

Sevgi ile büyür bebek

Sevgi damarda kan demek

Sevgi tanrının lütfudur 

Günüh onu esirgemek

Onunla coşar gönüllen

Onunla konuşur diller

O lokman hekim gibidir 

Onulmaz dertleri siler

Sevgi olsun özünüz de

Sevgi olsun sözünüz de

Neye bakarsanız bakın

Sevgi olsun gözünüz de', 'Dünya onunla tur atar Her işin temeli sevgi Yolun en sonuna kadar Yüreğin emeli sevgi Sevmek gerek dolu dolu Segidir mutluluk yolu Sevmesini...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevginin-gucu-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni bekleyen ömür', 'seni-bekleyen-omur-mahmut-kasapoglu-ly1o6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine akşam usulca çöktü dağ başlarına,

Koyu bir hüzün düştü gönlümün bağlarına.

Adını söyledim de sustu bütün rüzgârlar,

Bir hasret demir attı gözümün yaşlarına.

Bir demet gül büyüttüm ben gönül toprağımda,

Ne sana varabildi ne kaldı kucağımda.

Kader ince bıçaktı, kesti bütün yolları,

Umutlarım kanadı sessizce dudağımda.

Gecelerce yürüdüm, yıldız küstü gözüme,

Ay bile ses vermedi yalvaran her sözüme.

Ayağım taşa değdi, yüreğim de ateşe,

Bir sen gelip başını hiç koymadın dizime.

Susuz çöller gibiydi sensiz geçen yıllarım,

Bir damla gülüşüne kurban olsun baharım.

Gözlerin bir değseydi şu yaralı gönlüme,

Belki de yeşerirdi tüm kurumuş dallarım.

Önümüzde uzanan yollar değilmiş yalnız,

İnsanların hükmüymüş bizi eden çaresiz.

Yaklaştıkça büyüdü aradaki ayrılık,

İki kalp yan yana da kalabilirmiş sessiz.

Ben seni sevmedim ki bir mevsim hevesine,

Adını ben işledim ömrümün nefesine.

Bir gün toprak örterse yorulmuş bedenimi,

Sevdam yürümez mi hiç sonsuzluk ülkesine?

Her sabah doğan güneş seni getirir sandım,

Her akşam yıldızlarla adını gizli andım.

Beklemek ibadetmiş seven yürekler için,

Sabrın kapısında ben ömür boyu dayandım.

Dilerim ki gül açsın yürüdüğün her diyar,

Benim payıma düşsün yağmurlar ve sonbahar.

Yeter ki sen üzülme, yeter ki sen gül biraz,

Ben acıya razıyım, sen ol mesut, bahtiyar.

Kader pişman olursa bir gün açtığı derde,

Kalkarsa aradaki o kapkaranlık perde,

İlk sözüm yine sensin, son sözüm yine sensin,

Değişmez kalbim asla, ne hazda ne kederde.

Sen sus artık sevgilim, duasız gün olmasın,

Gözlerinden o umut bir an bile solmasın.

Ben gelmezsem bu dünya yollarından yanına,

Rabbim ayırmaz bizi, sevda yetim kalmasın.', 'Yine akşam usulca çöktü dağ başlarına, Koyu bir hüzün düştü gönlümün bağlarına. Adını söyledim de sustu bütün rüzgârlar, Bir hasret demir at...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/seni-bekleyen-omur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derman Bulamadım', 'derman-bulamadim-yuksel-sari-wbacn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine akşam oldu içimde hüzün 

Nice ahlar çektim daldım derine 

Gözümde tütüyor ay gibi yüzün

Kimseyi koymadım senin yerine

Şu gönlümü sensiz avutamadım 

Yollarına bakar ağlar gözlerim 

Çıkmadın aklımdan unutamadım 

Bir ömür geçse de seni özlerim 

Geçmiyor geceler bitmiyor günler 

Bir başıma koydun bu ıssız yerde 

Yokluğun bir bıçak kalbimi deler

Derman bulamadım bu acı derde

Ayazda bıraktın sen yüreğimi

En güzel düşlerim seninle gitti 

Hasretin eritti şu bedenimi

Çektiğim bu çile canıma yetti', 'Yine akşam oldu içimde hüzün  Nice ahlar çektim daldım derine  Gözümde tütüyor ay gibi yüzün Kimseyi koymadım senin yerine Şu gönlümü sensiz...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Sarı']::text[], 8.5, '{"poet":"Yüksel Sarı","poet_slug":"yuksel-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/derman-bulamadim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vekilim', 'vekilim-kerim-yavuz-3snqu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oy, oy diye peşimizden çok gezdin

Oyumuzu alıp gittin vekilim

Koltuk sevdasıymış meğerse derdin

Meclise yan gelip yattın vekilim

Hani söz verdiğin vaatler nerde

Hani çare idin her türlü derde

Derdimize deva olacak yerde

Gelene gidine çattın vekilim

Partinin rozeti vardı yakanda

Sen böyle değildin nutuk atanda

Bir baktık köşeyi döndün bir anda

Servetine servet kattın vekilim

Kendi tabanına sırtını döndün

Bil ki içimiz de mum gibi söndün

Bize kör oldun da zengini gördün

Bizi sermayeye sattın vekilim

Makamı kapınca değiştin durdun

Hep yoldaşı oldun çakalın kurdun

Fırsat elde iken vurgunu vurdun

Hep kendi cebine attın vekilim

Dünya öylesine büyük bir han ki

Gelenler gidecek bir gün inanki

Önce gözümüzde güneştin sanki

Şimdi ufkumuza battın vekilim', 'Oy, oy diye peşimizden çok gezdin Oyumuzu alıp gittin vekilim Koltuk sevdasıymış meğerse derdin Meclise yan gelip yattın vekilim Hani söz ve...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/vekilim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemin olsun', 'yemin-olsun-kerim-yavuz-fyl60', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu sevda uğruna düşsem de dile

Haram olsun başka güzel seversem

Beni can evimden vursan da bile

Yemin olsun ben bu aşktan dönersem

Diken olmuş aşkın batar bağrıma

Deva olmuyorsun gönül ağrıma

Cevap vermesende aşka çağrıma

Yemin olsun ben bu aşktan dönersem

Cefa çektirsende pes ettim sanma

Bu mahsum halime sakın aldanma

Yüreğim aşkınla yanıyor amma

Yemin olsun ben bu aşktan dönersem

Sen bana yar olsan bende sana yar

Söyle gülüm bunda kızacak ne var

Bedenim toprağa ğirene kadar

Yemin olsun ben bu aşktan dönersem

Üzüyorsun sevdam seni seveni

Bu insafsızlığın nedir nedeni

Kurşunlara hedef etsen de beni

Yemin olsun ben bu aşktan dönersem

Bu yoldan dönemem sözümde erim.

Bendimi aşarım sana giderim.

Gülmese de bana kötü kaderim.

Yemin olsun ben bu aşktan dönersem.', 'Bu sevda uğruna düşsem de dile Haram olsun başka güzel seversem Beni can evimden vursan da bile Yemin olsun ben bu aşktan dönersem Diken olm...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yemin-olsun-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mümkün mü?', 'mumkun-mu-mahmut-kasapoglu-ejoui', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğim hasretin koruna düştü,

Küllerden bir sevda dermek mümkün mü?

Talihim yüzüme bakmadan küstü,

Dağılan umudu sarmak mümkün mü?

Çiçeğim ayazın elinde soldu,

Toprağa yeni renk sermek mümkün mü?

Gözlerim geceler boyu yoruldu,

Karanlığa güneş kurmak mümkün mü?

Sesini rüzgârın koynunda aradım,

Sükûtu sevdaya yormak mümkün mü?

Her adımda biraz daha kanadım,

Yaralı kalbi onarmak mümkün mü?

Ömrümün defteri hüzünle doldu,

Silineni geri yazmak mümkün mü?

İçimde bin umut bir mezar oldu,

Mezardan bahar doğurmak mümkün mü?

Sevdamız bir ömür ateşte pişti,

Kırık aynada yüz görmek mümkün mü?

Gidenin ardından yıllar da geçti,

Kalanı sabırla örmek mümkün mü?

Benliğim sensizlik yüküyle çöktü,

Yıkılan gönlüme varmak mümkün mü?

Ayrılık aşkımı kökünden söktü,

Canı candan alıp vermek mümkün mü?', 'Yüreğim hasretin koruna düştü, Küllerden bir sevda dermek mümkün mü? Talihim yüzüme bakmadan küstü, Dağılan umudu sarmak mümkün mü? Çiçeğim ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mumkun-mu-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende atıyor kalbim', 'sende-atiyor-kalbim-selim-ozl-uvirp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sende Atıyor Kalbim
Bir bakmışsın gözlerin ellerim oluyor
Dokunuyor, 
her bir parmak ucundan tenime
Uçsuz bucaksız bir okyanus gibi,
içimde çoğalıyor, bitmeyen bir sevgi.

Yan yana duruyoruz,
 dünya dönüyor
Ve zaman duruyor, usulca..
Herkes bir yere yetişiyor,
 biz duruyoruz
İki farklı insan, aynı hayali soluyoruz.
Sadece gözlerin konuşuyor şimdi
Sözler suspus olmuş, 
gözlerimiz nehir gibi
Bakışlar anlatıyor sevgimizi.
İki kalp, iki ruh , biz olduk şimdi.
Sana bakarken, kendime bakıyorum
gözlerin evim oluyor,
Kaybolmuyorum artık,
O gözlerde doğuyorum
 o ellerde yeniden.

Bir bakmışsın ellerin ellerim oluyor,
Usulca, bir kuş tüyü gibi konuyor.
Yalnızlık, o eski ve yorgun misafir,
Bir anda çekip gidiyor.
Şimdi artık korkmuyorum,
Gözlerin yüreğimde çağıldıyor.', 'Sende Atıyor Kalbim Bir bakmışsın gözlerin ellerim oluyor Dokunuyor,  her bir parmak ucundan tenime Uçsuz bucaksız bir okyanus gibi, içimde ...', ARRAY['Türk Edebiyatı','Şiir','Selim Özl']::text[], 8.5, '{"poet":"Selim Özl","poet_slug":"selim-ozl","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sende-atiyor-kalbim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Derdini', 'soyle-derdini-kerim-yavuz-4lwz8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Burası er meydanı ozanların yeridir

Seni de bekliyoruz gel de söyle derdini

Burda mızrak konuşur senelerden beridir

Tokmağı at elinden telle söyle derdini

Burda nefrete yer yok yüreğini temizle

Ayrı gayrımız yoktur kardeş ol hepimizle

Biz nice gönüllere taht kurduk dilimizle

Silahı at elinden dille söyle derdini

Gönüller bir olursa dağılır karanlıklar 

Her sabah umutlara gülümser aydınlıklar

Sevmesini bilince yok olur kırgınlıklar

Dikeni at elinden gülle söyle derdini.', 'Burası er meydanı ozanların yeridir Seni de bekliyoruz gel de söyle derdini Burda mızrak konuşur senelerden beridir Tokmağı at elinden telle...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/soyle-derdini-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakmayın Beni', 'yakmayin-beni-kerim-yavuz-ay8le', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kader mahkümuyum nasıl edeyim

Dertlerin peşine takmayın beni

Bir kuzu misali henüz körpeyim

Kurtlar masasına atmayın beni

Artık acılarım bulsa nihayet

Çaresiz kalana olmaz hıyanet

Şerefim namusum size emanet

Yoldan çıkmışlara katmayın beni

Boynu bükük kaldım çile her yanım

Yok ki anlatacak mutlu bir anım

Unutmayın sakın bende insanım

Köle pazarında satmayın beni

Şevkat damardaki kandır insana

Bilin kimsesizlik zülümdür cana

Benim derdim zaten yetiyor bana

Cehennem narına yakmayın beni

Dinamitlemeyin sevği dağımı 

Talana kakmayın gönül bağımı

Çıkmaza sokmayın gençlik çağımı

Kuru ağaç gibi yıkmayın beni', 'Kader mahkümuyum nasıl edeyim Dertlerin peşine takmayın beni Bir kuzu misali henüz körpeyim Kurtlar masasına atmayın beni Artık acılarım bul...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yakmayin-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim sen', 'sevgilim-sen-mahmut-kasapoglu-6c3j2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ömür tükense yollarında ben,

Yorgunluk bana rahattır sevgili.

Aşk dediğin gönle düşen bir vatan,

Sana varmak ayrı bahttır sevgili.

Bir gün saçlarımıza karlar yağsa,

Yıllar yüzümüzde izler bıraksa,

Yüreğimiz aynı sevdayla atsa,

İşte gerçek zenginliktir sevgili.

Ne zaman ömrümün perdesi inse,

Son nefeste dilim duaya dönse,

İlk sözüm, son sözüm yine sen olsa;

Seni sevmek de kulluktur sevgili.

Aşk değildir yalnız kavuşup gülmek,

Ömrü vefayla tamamlayabilmek,

Canı emanet, sevdayı mühür bilmek…

Bu ayrıcalık değil, nasiptir sevgili.', 'Bir ömür tükense yollarında ben, Yorgunluk bana rahattır sevgili. Aşk dediğin gönle düşen bir vatan, Sana varmak ayrı bahttır sevgili. Bir g...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgilim-sen-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce ruhlum', 'i-nce-ruhlum-selim-ozl-ez6cx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sanki pamuk değse 
incinir gibi ruhun
Uçuyor  içimde hissin. 
inciden ışıltılar gibi
Anlatılmaz bir hisle kaplanmışım.
Bir pembe sis var çepeçevre.
Sular çağlar , gözlerim aralanır senle
Öyle hafif ki sevgin, 
ruhumun ferahlığı olur.
İyilikler taşar senden, 
dolarsın gönlüme.
Ruhumda bahar olursun,
Müjde olursun.
Türlü çiçeklerle dolar dağlarım.
Yemyeşil kırlarım olur.
Cennetin ırmağı olur sevgin.
her yerde çağlar çağıldar adın.
Suları şırıl şırıl, adını çağlar içime.
Pırlanta kalbin, 
ışıtır içimi uzaklardan.
Güneşi olur gözlerimin, 
güzel gözlerin.
Saçlarına tutunurum,
sevginle dolanır dilim.
Şimdi her şarkım sana yazılır.
Yetmez saatler, 
yıllar rüzgar gibi koşar..
Geçmiyor zamana sözümüz.
Yinesi olsa,
ömürler adanır büyük aşkımıza', 'Sanki pamuk değse  incinir gibi ruhun Uçuyor  içimde hissin.  inciden ışıltılar gibi Anlatılmaz bir hisle kaplanmışım. Bir pembe sis var çep...', ARRAY['Türk Edebiyatı','Şiir','Selim Özl']::text[], 8.5, '{"poet":"Selim Özl","poet_slug":"selim-ozl","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ince-ruhlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'De l''orgueil à la catégorie : la réfutation coranique et scientifique du racisme', 'de-l-orgueil-la-cat-gorie-la-r-futation-coranique-et-scientifique-du-racisme-muhammed-ridvan-gizri-q60tz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'L''histoire de l''humanité a été, dans une large mesure, l''histoire de la distinction entre « nous » et « l''autre ». La forme la plus durable et la plus destructrice de cette distinction est celle des prétentions de supériorité fondées sur la catégorie de la race. Le racisme ne peut être réduit à un simple préjugé, à une discrimination grossière ou à une ignorance née du manque d''instruction. Examiné en profondeur, il apparaît comme une structure de pensée incohérente, qui s''effondre simultanément sur les plans biologique, épistémologique, éthique, historique et théologique.

L''ILLUSION BIOLOGIQUE : LA RÉALITÉ GÉNÉTIQUE DE LA « RACE »

Que dit l''ADN humain ?

L''argument le plus fondamental du racisme est biologique : « Il existe entre les êtres humains des différences biologiques naturelles, durables et déterminantes. » Or la génétique moderne a radicalement réfuté cette affirmation. 99,9 % de l''ADN humain est commun à tous les individus. Les 0,1 % de variation restants recouvrent des adaptations superficielles comme la couleur de la peau, la tolérance au lactose ou l''adaptation à l''altitude. Ces différences ne créent ni hiérarchie d''intelligence, ni échelle de valeur. Le résultat le plus frappant, peut-être, de la génétique des populations moderne est le suivant : la différence génétique entre deux individus appartenant à la même « race » peut être plus grande que celle qui sépare des « races » différentes. Cette seule découverte suffit à ruiner le fondement biologique du racisme. En effet, si la catégorie de « race » ne parvient même pas à rendre compte de la différence entre les individus censés la composer, elle n''est pas une réalité biologique, mais une fiction mentale.

Où la race existe-t-elle, où n''existe-t-elle pas ?

La génétique des populations établit clairement que la variation humaine ne forme pas des catégories distinctes séparées par des frontières nettes, mais un espace continu. Autrement dit, les « frontières raciales » n''existent pas dans la nature ; elles ont été tracées par l''être humain pour faciliter la modélisation. La race n''est pas une ligne tracée par la nature, mais une carte artificielle dessinée par les sociétés humaines, le plus souvent au service d''intérêts politiques et économiques. De même que la carte n''est pas le territoire, l''étiquette raciale n''est pas la réalité biologique. L''histoire le confirme : les catégories raciales ont été élargies, rétrécies et redéfinies selon les circonstances de chaque époque. Au XIXᵉ siècle, les Irlandais étaient considérés en Angleterre comme « une race à part ». Au début du XXᵉ siècle, les Italiens et les Juifs n''étaient pas reconnus comme « blancs » aux États-Unis. Ce fait montre clairement que les catégories raciales sont des produits politiques et non biologiques.

L''effondrement du mythe de la « race pure »

L''idée de « race pure » est insoutenable non seulement sur le plan scientifique, mais aussi sur le plan historique. L''histoire de l''humanité est une histoire ininterrompue de mélanges. Les migrations, les conquêtes, le commerce et les contacts culturels ont engendré des échanges génétiques constants entre régions et communautés. De surcroît, du point de vue de la diversité génétique, ce brassage réduit le risque de maladies génétiques et accroît la robustesse biologique : c''est donc non pas la « pureté », mais la diversité qui est biologiquement avantageuse.

L''ERREUR ÉPISTÉMOLOGIQUE : LE VICE DE PRODUCTION DU SAVOIR RACISTE

Le racisme comme théorie : pourquoi n''est-ce pas de la science ?

Une affirmation scientifique doit satisfaire trois conditions fondamentales : une définition claire, une mesurabilité et une réfutabilité. Les affirmations racistes ne remplissent aucune des trois.

- Définition claire : les limites de la catégorie de « race » sont floues, historiquement variables et incohérentes sur le plan de la mesure.

- Mesurabilité : les critères de supériorité allégués, tels que l''« intelligence », la « moralité » ou la « productivité », ne sont pas unidimensionnels mais constituent des structures multivariées. Ils ne peuvent être réduits à une seule étiquette.

- Réfutabilité : la pensée raciste est fermée au contre-exemple. Les individus qui ne correspondent pas au stéréotype sont déclarés « exceptions », ce qui préserve le système. Ce n''est pas une théorie scientifique, mais un cercle interprétatif qui se verrouille lui-même.

L''observation sélective : un filtre, non la réalité

Le mécanisme épistémologique de la pensée raciste fonctionne selon le cycle suivant :

1. On choisit d''abord un groupe et on lui suppose une caractéristique.

2. Les exemples conformes à cette supposition sont rendus « visibles ».

3. Les exemples non conformes sont considérés comme du « bruit de fond » ou comme des « exceptions ».

4. Le système n''est jamais mis à jour ; seul le filtre est renforcé.

Cette structure n''analyse pas la réalité ; elle sélectionne les données qui conviennent à une conclusion préétablie. Le racisme n''est donc pas un système de production de savoir, mais un réglage biaisé du filtre de la perception. Il ne voit pas la réalité ; il proclame « réalité » les données qui ont passé son propre filtre.

L''erreur de causalité

L''explication raciste affirme : « Ce groupe est ainsi parce qu''il appartient à cette race. » Or la véritable chaîne causale est le plus souvent la suivante :

- le colonialisme historique et la structure économique ;

- l''accès à l''éducation et les conditions d''alimentation ;

- les infrastructures de santé et les structures institutionnelles ;

- les traumatismes historiques et les opportunités non accumulées.

Dans cette chaîne, la race n''est pas une variable causale, mais un artefact de classification collé sur les résultats. Le racisme est un modèle de causalité inversée, qui prend l''effet pour la cause et la cause pour l''effet. Prenons un exemple concret : aux États-Unis, les taux de criminalité des Blancs pauvres sont eux aussi élevés. Cela montre clairement que la criminalité est liée à la pauvreté, et non à la race. Même s''il existe des différences moyennes dans les tests de QI, l''écart entre riches et pauvres au sein d''une même race est bien plus grand que cet écart entre groupes. La variable n''est pas la race, mais l''éducation, l''économie et les opportunités.

Le racisme comme perte d''information

Du point de vue de la théorie de l''information, le racisme fait ceci : il comprime des millions de variables individuelles en une seule étiquette. C''est produire un modèle minimal au prix d''une perte d''information maximale. Le racisme n''est donc pas une explication, mais une compression de données excessivement agressive qui déforme la réalité. Pour la grande majorité des caractéristiques humaines, la variance intragroupe est bien plus élevée que la variance intergroupe. Cela signifie, statistiquement, que l''étiquette raciale n''apporte qu''un gain d''information extrêmement faible sur un individu. Le racisme absolutise précisément cette variable au faible pouvoir explicatif.

L''ERREUR ÉTHIQUE : RÉDUIRE L''ÊTRE HUMAIN À UNE CATÉGORIE

La structure morale du racisme

L''erreur éthique du racisme consiste à attribuer la valeur non à l''individu mais à la catégorie. Or l''évaluation morale exige : l''intention, l''acte, le contexte et la capacité individuelle. La catégorie de race ne contient aucun de ces éléments. Le racisme choisit ainsi le mauvais niveau de données pour le jugement moral. Plus fondamentalement encore : le racisme fait de l''individu non plus un « être humain », mais un « représentant de catégorie ». Dès que cette transformation s''accomplit :

- la responsabilité individuelle s''efface ;

- l''empathie est désactivée ;

- la généralisation remplace le jugement moral.

Le racisme n''est donc pas seulement une idée fausse ; c''est un protocole de pensée qui arrête le fonctionnement du raisonnement moral.

L''effondrement logique de la prétention à la supériorité

La proposition « une race est supérieure » repose sur deux présupposés :

1. Il existe un ensemble unique de caractéristiques (intelligence, moralité, productivité, etc.).

2. Ces caractéristiques appartiennent de façon durable et collective à un groupe.

Ces deux présupposés s''effondrent. Les caractéristiques humaines sont multidimensionnelles ; l''intelligence, l''empathie, la fonctionnalité, la résilience et bien d''autres se répartissent selon des dimensions différentes. Aucun groupe n''est supérieur dans toutes ces dimensions. De plus, la distribution est individuelle, et non collective. L''idée de « supériorité raciale » est une projection erronée, qui réduit à un seul axe une réalité multidimensionnelle.

L''histoire prouve que la supériorité n''est pas biologique

Si les races étaient naturellement supérieures, la même race serait supérieure à toutes les époques. Or l''histoire montre que la supériorité des civilisations varie non selon la race, mais selon les institutions, l''accumulation du savoir et les conditions historiques. Les mêmes régions se sont élevées et effondrées à des époques différentes. La Mésopotamie, qui fut un temps le centre scientifique du monde, a pris du retard dans les siècles suivants. Al-Andalus, qui était la région la plus avancée d''Europe sous domination musulmane, a ensuite connu un renversement. Cela signifie que la supériorité est non pas biologique, mais historique et structurelle. Et les structures changent.

LA PERSPECTIVE ISLAMIQUE : LE BUT DE LA CRÉATION ET L''ORGUEIL

Le regard du Coran sur la race

Le verset 13 de la sourate Al-Hujurât exprime l''essence de cette question en une seule phrase : les êtres humains ont été répartis en peuples et en tribus, mais le but de cette distinction n''est pas la supériorité, c''est la connaissance mutuelle. La supériorité ne doit être recherchée que dans la taqwā, c''est-à-dire dans la responsabilité morale et l''attitude consciente envers Dieu. Ce verset contient aussi une déclaration épistémologique extrêmement forte : il qualifie toute prétention à la supériorité de déviation qui renverse le but de la création. Faire de la différence raciale une cause de supériorité, c''est, selon le Coran, dénaturer la finalité de la création.

L''orgueil : une lignée qui va d''Iblis au raciste

Dans le Coran, l''orgueil (kibr) est défini comme le fait de rejeter la vérité, de se considérer supérieur et de mépriser autrui. Cette définition est précisément l''essence du racisme. La parole d''Iblis : « Moi, j''ai été créé de feu, alors que lui l''a été d''argile » est le premier exemple, archétypal, de la prétention à la supériorité fondée sur l''origine. De ce point de vue, le racisme n''est pas un simple désaccord d''opinion, mais une corruption fondamentale que le Coran qualifie d''« orgueil ». C''est une manière de penser qui transpose la logique de Satan dans les relations humaines.

« Au-dessus de tout savant, il y a un plus savant »

« Au-dessus de chaque détenteur de savoir, il y a un connaisseur plus savant encore. » (Sourate Yûsuf, verset 76)

Ce verset établit le fondement théologique de l''humilité intellectuelle. Aucun individu, aucune communauté, aucun groupe ne peut prétendre à une supériorité absolue et durable en matière de savoir ou de vertu. Ce qui manque à une race se trouve chez une autre communauté. Cette interdépendance engendre la nécessité de l''union et de la coopération. Le principe « les croyants sont frères », énoncé au verset 10 de la sourate Al-Hujurât, repose lui aussi sur ce fondement.

LES RACINES PSYCHOLOGIQUES ET LES VOIES DE SOLUTION

Pourquoi le racisme paraît-il séduisant ?

Le racisme fonctionne le plus souvent par les mécanismes suivants :

- La simplification cognitive : le besoin de réduire une réalité sociale complexe à une seule variable.

- La préservation de l''identité : l''individu qui sent son identité menacée rétablit sa confiance à travers le groupe du « nous ».

- La projection vers l''extérieur du stress économique et social : la manière la plus facile de produire une « cible » pour des problèmes systémiques.

Dans ce cadre, le racisme n''est pas un système d''analyse de la réalité, mais un court-circuit mental. C''est la manière dont un esprit qui évite de comprendre les structures complexes se soulage en fabriquant un « ennemi ».

La solution : rendre durable la faculté de voir l''individu

La solution durable à la lutte contre le racisme tient à un seul changement : « voir un individu » au lieu de « penser un groupe ». Ce changement est favorisé par :

- Le contact individuel entre égaux : nouer de véritables relations avec des personnes d''autres groupes autour d''objectifs communs défait la généralisation automatique. L''esprit remplace la « catégorie » abstraite par un « être humain » concret.

- L''éducation : non pas une simple transmission de connaissances, mais un changement de manière de penser. Une éducation qui enseigne la diversité génétique, le contexte historique et le questionnement critique affaiblit la pensée catégorielle.

- Le changement de langage : « cette personne, dans cette situation » au lieu de « ils sont toujours comme ça ». Le langage façonne la pensée. Un langage qui parle de manière individuelle, qui ne généralise pas et qui se concentre sur le comportement plutôt que sur l''étiquette affaiblit les schémas racistes.

- La lutte contre les inégalités : le racisme naît souvent comme « explication » facile de l''inégalité. Là où existent le chômage, l''inégalité éducative et la ségrégation de l''espace de vie, l''esprit glisse aisément vers l''erreur selon laquelle « la cause, c''est l''identité ». Or la véritable cause est le système. C''est pourquoi la lutte contre le racisme ne peut être menée séparément de la lutte contre les inégalités structurelles.

CE QUE LE RACISME N''EST PAS, CE QU''IL EST

Le racisme n''est pas un manque d''information ; c''est une erreur de pensée à partir de catégories fausses. Le racisme n''est pas une opinion différente ; c''est une illusion ontologique qui prend pour réels des objets qui n''existent pas. Le racisme n''est pas seulement une pratique de discrimination ; c''est un protocole de pensée dans lequel le raisonnement moral devient radicalement inopérant. Toutes ces perspectives convergent vers une seule conclusion : la race n''est pas une réalité existant avec des frontières nettes dans la nature ; c''est un système de classification erroné, produit pour simplifier la variation biologique, renforcé avec le temps à des fins politiques et idéologiques, scientifiquement réfuté, moralement négateur du concept d''humanité, et qualifié d''« orgueil » sur le plan théologique. L''unité de l''humanité n''est pas un sentiment romantique engendré par la tolérance : c''est un fait biologique établi par la génétique, une nécessité prouvée par l''histoire et une conscience enseignée par la Révélation. La différence n''existe pas pour la supériorité, mais pour la connaissance mutuelle. La supériorité n''appartient pas à la race, mais à la vie vécue dans la conscience de la responsabilité.', 'L''histoire de l''humanité a été, dans une large mesure, l''histoire de la distinction entre « nous » et « l''autre ». La forme la plus durable ...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/de-l-orgueil-a-la-categorie-la-refutation-coranique-et-scientifique-du-racisme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Dertleri Sök At', 'butun-dertleri-sok-at-kasim-kobakci-wr98e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Boşlukta süzülürken silinmiş bütün mekan,

Dağılıp gidiyor bak eriyor sanki zaman,

Uyuşmuş bedenlerde donmuş gibi dolan kan,

Bırak gitsin hepsini silinsin şimdi bu an.

*

Sisli perde ardında uyuşuyor bak zihnin,

Dağılıyor rüzgarla o titreyen nefesin,

Tükendiğini anlar içindeki hevesin,

Bırak gitsin hepsini duyulmasın hiç sesin.

*

Uzandığın bu yerde uyuşmuş bütün kollar,

Akıp gider yanından yorgun ve bitkin yıllar,

Uyuşuyor inceden zihnini yoran sırlar,

Bırak gitsin ne varsa kapansın bütün yollar.

*

Gözlerinden süzülüp donmuş ufacık bir yaş,

Ne bir his kalmış orda ne de bitmez bir savaş,

Dağılmış bütün dertler silinip yavaş yavaş,

Bırak gitsin boşluğa uyuşup düşen bu baş.

*

Hiçe sayılsın bugün gelip geçici dertler,

Unut giden ne varsa sona eren seferler,

Silinip gidecektir karanlıkta bitenler,

Bırak gitsin rüzgara uçsun o hayaletler.

*

Görünmez oldu artık bakılan o bitkin yüz,

Üzerinde uyuşma içinde soğuk bir güz,

Ne bir duygu kıpırdar ne gece ne de gündüz,

Bırak gitsin hepsini yollar olsun artık düz.

*

Hücrelere yayılıp ezen bitmez bir akşam,

Dağılıyor ellerde tutulan o sırça cam,

Ne bir tat alınıyor ne ruhunda intizam,

Bırak gitsin hepsini bitsin içindeki gam.

*

Ruhunu teslim eden o uyuşuk yorgun el,

Dağılıyor zihninde boşa çıkan her emel,

Siliniyor içinden ödenmiş en son bedel,

Bırak gitsin hepsini kopsun içindeki tel.

*

Görünmez oldu artık uyuşuklaştı hayat,

Damağımda belirdi gereksiz eski bir tat,

Ne ilerle ne geri derin bir uykuya yat,

Bırak gitsin hepsini bütün dertleri sök at.', 'Boşlukta süzülürken silinmiş bütün mekan, Dağılıp gidiyor bak eriyor sanki zaman, Uyuşmuş bedenlerde donmuş gibi dolan kan, Bırak gitsin hep...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/butun-dertleri-sok-at-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapay Zeka Şirki', 'yapay-zeka-sirki-onder-karacay-i0769', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yapay zekayı varlık olarak kabul edenlerin zekasından değil varlığından şüphe etmek gerekir. 

İnsanın bilinçli veya bilinçsiz çaldırdığı bilgiyi insana satan bir şirkin ahlakına güven olabilir mi?

Bunu normal görerek bu şirk kurnazlığının meşru hale getirenler ve tüm kullanıcıları yarı biyolojik varlık olarak aşağılayan bu ahlaksızlık konusunda insanlık bir an önce kendine gelmesi gerekir. 

Dijital para ve dijital vatandaşlık gibi bir rezalete siyasi iktidarlar kamulaştırma devrimi ekonomisi olmadan, ulusal teknoloji olmadan alet olurlar ise sonu felaket olacaktır. 

Tek gözlü deccal şirkine öz bilincinden uzaklaşan insanı teknolojik gelişme adı altında aldatmak istiyorlar. 

Sosyal ağ hesaplarınızı kapatın, yapay zeka hesaplarınızı kapatın, yapay zekaya finansman sağlayan bankaları cezalandırın hesaplarınızı kapatın. Siz yoksasız yapay zeka şirkide yok olur. Siz destek olursanız siz yok sayılırsınız. 

İnsan yarı biyolojik bir varlık olarak gören ve yapay zekayı daha üstün bir varlık olarak gören geri zekalı işbirlikçiler bunu söyleyecek kadar hadlerini aştılar. 

▪️Önder Karaçay ▪️', 'Yapay zekayı varlık olarak kabul edenlerin zekasından değil varlığından şüphe etmek gerekir.  İnsanın bilinçli veya bilinçsiz çaldırdığı bil...', ARRAY['Türk Edebiyatı','Şiir','Önder Karaçay']::text[], 8.5, '{"poet":"Önder Karaçay","poet_slug":"onder-karacay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yapay-zeka-sirki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarına kalan bahar', 'yarina-kalan-bahar-mahmut-kasapoglu-tbqur', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bekledim ömrümce dönsün izlerin,

Solar mı gül yüzün bana varmadan?

Sakladım içimde kırık sözlerin,

Dinmez mi sızılar sabah gelmeden?

Yılların yükünü omzuma aldım,

Her düşen yaprakta seni aradım.

Ben seni unuttum desem de yandım,

Geçer mi ayrılık ömür bitmeden?

İncinmiş gönlümün dili suskundur,

Sevdanın esiri sabra mahkûmdur.

Her veda aslında gizli umuttur,

Doğar mı yıldızlar gece olmadan?

Dönersen kapımı açık bulursun,

Yorgun yüreğimi yine sorarsın.

Sevgiyi korudum, bunu bilirsin;

Yaşar mı insan hiç sevip yanmadan?

Varsın son sözümü rüzgâr söylesin,

Hasretin yükünü yıllar bölüşsün.

Sevenin gönlünü Rabbim güldürsün;

Vuslat mı bulunur sabır olmadan?', 'Bekledim ömrümce dönsün izlerin, Solar mı gül yüzün bana varmadan? Sakladım içimde kırık sözlerin, Dinmez mi sızılar sabah gelmeden? Yılları...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yarina-kalan-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelirsin Hatırıma', 'sen-gelirsin-hatirima-tahir-sariisik-c1jyx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her güneş batışında

Dalda kuşun kalkışında

Kalbimin acı atışında

Sen gelirsin hatırıma.

Geçse de uzun yıllar

Geçmez hicran acılar

Gözümde canlansa anılar

Sen gelirsin hatırıma.

Geçtiğinde ayrılık sözü,

Yanar ruhumda közü

Yarama bastığımda tuzu

Sen gelirsin hatırıma.', 'Her güneş batışında Dalda kuşun kalkışında Kalbimin acı atışında Sen gelirsin hatırıma. Geçse de uzun yıllar Geçmez hicran acılar Gözümde ca...', ARRAY['Türk Edebiyatı','Şiir','Tahir Sarıışık']::text[], 8.5, '{"poet":"Tahir Sarıışık","poet_slug":"tahir-sariisik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-gelirsin-hatirima-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Yarar', 'neye-yarar-kerim-yavuz-hujp8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen olmayınca yanımda

Söyle bu aşk neye yarar

Çiçek açmazsa dalımda 

Bahar gelmiş neye yarar

Aşka kıymet vermiyorsun

Seven kalbi sevmiyorsun

Bir kez olsun gelmiyorsun 

Kuru selâm neye yarar

Aşk gönüle akmayınca

Sevda ile yakmayınca

Gönül huzur bulmayınca

Servet para neye yarar

Oynattım aşkı yerinden

Ses yok gönül direğinden

Sevmiyorsan yüreğinden

Güzelliğin neye yarar

Sevgi gönüllerden taşsa

Yüce tepeleri aşsa

Yüreğin de sevgi yoksa

İnsanlığın neye yarar', 'Sen olmayınca yanımda Söyle bu aşk neye yarar Çiçek açmazsa dalımda  Bahar gelmiş neye yarar Aşka kıymet vermiyorsun Seven kalbi sevmiyorsun...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/neye-yarar-441-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralandım', 'yaralandim-kerim-yavuz-thvnk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yeşil gözlerine baktım

Dümen kırdım sana saptım

Aşk yolunda kaza yaptım 

Yaralandım yaralandım

Gülmüyor bana kaderim

Yok mu aşkta benim yerim

Kurşun yemişten beterim

Yaralandım yaralandım

Sakın ak deme karaya

Mesafe koyma araya

Gel tabip ol bu yaraya

Yaralandım yaralandım

İsyan var gönül evime

Her tarafı lime lime

Bir ok değdi yüreğime

Yaralandım yaralandım

Bakışların ok mu senin

Aşka kalbin tok mu senin

Hiç insafın yok mu senin

Yaralandım yaralandım

Yaralandım yaralandım

Can evimden yaralandım

Vuruldum sol tarafımdan

Yüreğimden yaralandım', 'Yeşil gözlerine baktım Dümen kırdım sana saptım Aşk yolunda kaza yaptım  Yaralandım yaralandım Gülmüyor bana kaderim Yok mu aşkta benim yeri...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yaralandim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Aşkını Ver Yeter', 'bana-askini-ver-yeter-kerim-yavuz-palwo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Darda deli gönül darda

Figanı dağları deler

Gözüm yok parada pulda

Bana aşkını ver yeter

Kaçma benden köşe bucak

Sensiz halim ne olacak

Avuç avuç kucak kucak

Bana aşkını ver yeter

Hadi çabuk tut elini 

Bekleme hazan yelini

Kalbim öder bedelini 

Bana aşkını ver yeter

Derde salma bu bedeni

İncitme seni seveni

Ne olur bekletme beni

Bana aşkını ver yeter

Essin artık bahar yeli

Ben deli olmuşum deli

Öderim neyse bedeli

Bana aşkını ver yeter', 'Darda deli gönül darda Figanı dağları deler Gözüm yok parada pulda Bana aşkını ver yeter Kaçma benden köşe bucak Sensiz halim ne olacak Avuç...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bana-askini-ver-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Kapımı Çaldı', 'ayrilik-kapimi-caldi-kerim-yavuz-wt33x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kara haberi duyanda

Yıkıldım kaldım o anda

Hiç ummadığım bir anda

	Ayrılık kapımı çaldı

	Sevdiğimi benden aldı

Kader ağ ördü başıma

Su kattı pişmiş aşıma

Acımadan genç yaşıma

	Ayrılık kapımı çaldı 

	Sevdiğimi benden aldı

Soldu bahçemde güllerim

Suya düştü ümitlerim

Gerçekleşmeden düşlerim

	Ayrılık kapımı çaldı

	Sevdigimi benden aldı

Erkendi bu gidiş erken

Ayrılık kalbimde diken

Yaşanacak çok şey varken

             Ayrılık kapımı çaldı

	Sevdigimi benden aldı

Felek layık gördü gamı

Açtı kendimle aramı

Henüz kurmadan yuvamı 

             Ayrılık kapımı çaldı

	Sevdigimi benden aldı', 'Kara haberi duyanda Yıkıldım kaldım o anda Hiç ummadığım bir anda 	Ayrılık kapımı çaldı 	Sevdiğimi benden aldı Kader ağ ördü başıma Su kattı...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ayrilik-kapimi-caldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler Boyu', 'geceler-boyu-kerim-yavuz-8k99o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün ağarır derdim başlar

Çağlarım geceler boyu

Gözlerimde kanlı yaşlar

Ağlarım geceler boyu

Gene gönül düştü dara

Kaderim karadan kara

Açılır kalbim de yara

Sızlarım geceler boyu

Hayat dert verdi elime

Deva olan yok derdime

Bu insafsız kaderime

Kızarım geceler boyu

İsyanda damarda kanım

Canım daralıyor canım

Bende garip bir ozanım

Yazarım geceler boyu

Silemem alın yazımı

Kimse çekmiyor nazımı

Alırım dertli sazımı

Çalarım geceler boyu

Dertler geliyor peşpeşe

Kalmadı içimdi neşe

Hasret denen bu ateşe

Yanarım geceler boyu', 'Gün ağarır derdim başlar Çağlarım geceler boyu Gözlerimde kanlı yaşlar Ağlarım geceler boyu Gene gönül düştü dara Kaderim karadan kara Açılı...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/geceler-boyu-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ceylan Bakışlım', 'ceylan-bakislim-kerim-yavuz-anlwg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman süslenip çıksa yoluma

Saçını yan atar ceylan bakışlım

Sevgilim deyipte girse koluma

Canıma can katar ceylan bakışlım

Bırakır saçını esen yellere

Dolar kemerini ince bellere

Deseler gel gidek gerbet ellere

Kaşlarını çatar ceylan bakışlım 

Onsuz geçen günüm hasta ve yorgun

Ceylan gözlerine vurgunum vurgun

Bazen çağlayarak bazen de durgun

Yüreğime akar ceylan bakışlım

Eğer bu sevdaya düşerse hile

Biterim bu sevda dönerse küle

Tereddüt etmeden Dünyanın bile

Anasını satar ceylan bakışlım

Esir etti beni sendeki gözler

Bil ki seven gözler seveni özler

Çıkmasın ağzından kırıcı sözler

Yüreğimi yakar ceylan bakışlım', 'Ne zaman süslenip çıksa yoluma Saçını yan atar ceylan bakışlım Sevgilim deyipte girse koluma Canıma can katar ceylan bakışlım Bırakır saçını...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ceylan-bakislim-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkülerin Dili', 'turkulerin-dili-kerim-yavuz-ahqos', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğinden bir ses sev sev diyorsa

Türkülerin dilindendir arkadaş

Duyguların çoşup raks ediyorsa

Türkülerin dilindendir arkadaş

Dökülür notaya yüreğin sesi

Lisanından belli dilin yöresi

Çağlıyorsa eğer gönül çeşmesi

Türkülerin dilindendir arkadaş

Sevmektir hayatın ana yasası

Severse silinir yüreğin pası

Savurursa seni aşk fırtınası

Türkülerin dilindendir arkadaş

Aklın fikrin eğer kalmışsa yarda

Elbette yüreğin dardadır darda

Neden diye sorma sebep ortada

Türkülerin dilindendir arkadaş

Türkülerin belli olmaz ki huyu

Onlardır yüreğin yağmuru suyu

Ruhun geziyorsa Anadolu''yu

Türkülerin dilindendir arkadaş', 'Yüreğinden bir ses sev sev diyorsa Türkülerin dilindendir arkadaş Duyguların çoşup raks ediyorsa Türkülerin dilindendir arkadaş Dökülür nota...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/turkulerin-dili-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Göründü', 'yol-gorundu-kerim-yavuz-m6d3p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaderim yazıldı kara 

Doyamadım nazlı yara

Gurbet denilen diyara 

Yine bana yol göründü

Gurbet insafsız kelime

Dolanır durur dilime

Verin sazımı elime

Yine bana yol göründü

Gülmedi yüzüm bir kere

Boyun bükmüşüm kadere

Güneşin battığı yere 

Yine bana yol göründü

Kalkmadan dağların karı 

Güllere konmadan arı

Henüz görmeden baharı

Yine bana yol göründü

Güller açmıyor dalıma 

Dikenler düştü yolumu

Bir baktım kahfe falıma

Yine bana yol göründü

Hayat çekilirmi böyle

İsyan mı edeyim söyle

Yar hakkını helal eyle

Yine bana yol göründü', 'Kaderim yazıldı kara  Doyamadım nazlı yara Gurbet denilen diyara  Yine bana yol göründü Gurbet insafsız kelime Dolanır durur dilime Verin sa...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yol-gorundu-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Güzel', 'yasamak-guzel-kerim-yavuz-wlios', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Diken neye yarar gülü açmazsa

Çiçek neye yarar koklayan yoksa

Hasret çekilirmi umut olmazsa

Seni hissederek yaşamak güzel

Gönlümde fırtına koparsa kopsun

Peşinden boş yere kendini yorsun

Ne kadar imkânsız olursa olsun

Senin hayalinle yaşamak güzel

Peşinden koşmaktan kalsamda fersiz

Gönlümün isyanı yersizdir yersiz

Uzaklara gitsen benden habersiz

Senin özleminle yaşamak güzel

Bu gönül uğruna olmazmı köle

Seni gören bülbül gelmezmi dile

Erişilmez bir dağ olsam da bile

Senin hasretinle yaşamak güzel

Küçük bir resmini elime alıp

Mutlulukları resimden çalıp

Yeşil gözlerinle hayale dalıp

Seni düşleyerek yaşamak güzel', 'Diken neye yarar gülü açmazsa Çiçek neye yarar koklayan yoksa Hasret çekilirmi umut olmazsa Seni hissederek yaşamak güzel Gönlümde fırtına k...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yasamak-guzel-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MUTLULUK DEDİĞİN', 'mutluluk-dedi-gi-n-muhsin-yener-2-z6zj3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kediye sorsan mutluluğu,
Bir sıcak kucak, biraz sevgi der.

Bir yoksula sorsan,
Başımı sokacak bir ev,
Bir lokma huzur der.

Bir köre sorsan,
Görmek değil yalnız,
Dünyanın renklerini yüreğimde duymak der.

Bir âşığa sorsan,
Sevdiğinin gülüşünde saklıdır mutluluk der.

Ey insan!
Mutluluğu uzaklarda arama,
O, yüreğinin bir köşesinde bekler.

Yalnız kinle kirletme orayı,
Öfkeyle, kırgınlıkla, acıyla söküp atma.

Çünkü mutluluk dediğin,
Ne servettir ne de saltanat

Bir sıcak yürek,
Bir parça sevgi,
Bir tutam huzur
Ve başkasının mutluluğuyla
Mutlu olabilmektir
Muhsin Yener', 'Bir kediye sorsan mutluluğu, Bir sıcak kucak, biraz sevgi der. Bir yoksula sorsan, Başımı sokacak bir ev, Bir lokma huzur der. Bir köre sors...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/mutluluk-dedigin-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çopurina Hırkası', 'copurina-hirkasi-kasim-kobakci-jcdkt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çopurina hırkasın geydi şad-âb,

Gözine perde çeküp indi mehtâb.

*

Sükutun bâdı esdi can mülkine,

İçildi sâkîden rûhânî şerâb.

*

Kapandı kirpükler yorgun tenine,

Görünmez oldı hiçbir fânî serâb.

*

Nefesler yavaşlar sâkindür yürek,

Âleme indi ulu tatlu bir hâb.

*

Hayâlât iklimi açdı kapusın,

Çekildi gün yüzinden sırlı hicâb.

*

Çopurina makamı sardı her yan,

Örtdi sîmâsı üzre kara niqâb.

*

Ne hırs u gavgâ kaldı ne de telaş,

Dindi zihnüñ içindeki o girdâb.

*

Gönül teknesinde yaslanup uyur,

Seccade oldı düşler olur mihrâb.

*

Terk eyle mâsivâyı dökülsün uş,

Gerekmez uyhuya hiç zahir esbâb.

*

Uyhu sırrına girmeyen ne bilsün,

Çopurina halinden anlar erbâb.

*

Ufukdan el salladı uyuşan ten,

Açıldı sükunete varan o bâb.

*

Sükut it kelamı terk eyle bunda,

Uyhu kendüsidür yorguna cevâb.

*

Fısıldar yılduzlar gökyüzi içün,

Kesildi yiryüzinden bütün hitâb.

*

Çalınmaz oldı cümbüş inlemez ney,

Uyhuya vardı hemen ol pür rubâb.

*

Okunmaz oldı harfler satır satır,

Kapandı ellerinden düşüp kitâb.

*

Güneşüñ ateşi söndi hanemde,

Bedende kalmadı hiç zerre bir tâb.

*

Dinlenmek hakdur cana ey yolcu bil,

Rûhı âsûdeliğe salmak sevâb.

*

Gicenüñ koynında müsavi cümle,

Tutulmaz uyhu ile hiçbir hisâb.

*

Koşuşma itmam oldı zemân toñdu,

Kesildi menzile giden o şitâb.

*

Bir rü''yâ telinde titrer hatıra,

Vurur kalbüñ teline gizli mızrâb.

*

Yanuñda kimse kalmaz sen biresin,

Uyhu oldı saña en sadık ahbâb.

*

Ferâmûş it ismüñi cismüñi uş,

Dökülsün üstünden hep şan u elqâb.

*

Çopurina örtüsi kâfî cana,

Çıkar at bedenüñden zerlü esvâb.

*

Çözülür dügüm dügüm olmış a''zâ,

Yatışur uyhunuñ demiyle asâb.

*

Topraga dönecek bu cismüñ bilgil,

Bugün yumuşak döşek yarın turâb.

*

Dinlenmezsen eger bu kervan içün,

Düşer bu bednüñ yola olur harâb.

*

Vesvese kuşları uçup uzakdur,

Kalmadı gönülde yanlış bir zehâb.

*

Gidişler dindi kamil geliş bitdi,

Soñ buldı uyhunuñ faslında iyâb.

*

Karanluk denizde parlar yakamoz,

Gökden kayar ara sıra pür şihâb.

*

Huzur dîvânında boynun eğerek,

Yüz sürer ol uyhuya öper rükâb.

*

Cismüñ yatagundadur rûhuñ uzak,

Seyreder alemi mutlak bir giyâb.

*

Yumuşacuk pamuk tarlası bigi,

Sarar her bir yanuñı beyaz sehhâb.

*

Gözyaşı pınarın kurudu dindi,

Serpildi rûhuña serin bir gül-âb.

*

Bu şiirdür seni sükuta çağrur,

Uyu ki çopurinada ol kâm-yâb', 'Çopurina hırkasın geydi şad-âb, Gözine perde çeküp indi mehtâb. * Sükutun bâdı esdi can mülkine, İçildi sâkîden rûhânî şerâb. * Kapandı kirp...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/copurina-hirkasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sen Varsın', 'bir-sen-varsin-kerim-yavuz-s6a1c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnan ki senden başka yok kimseye güvenim

Herkes terk etti beni bir sen kaldın sevenim

Seni görmediğim an yüreğim isyanlarda

Sapıyor sağa sola yol tutmuyor dümenim

Bütün yıldızlar kaydı bir sen kaldın parlayan

Bir sen varsın ruhumu sevgi ile okşayan

Öyle bir tutku ki bu açım bakışlarına

Bir yürek var ki bende aşkına hiç doymayan

Hadi bak gözlerime yeşersin umutlarım

Aşka değer vereni yüreğimden kutlarım

Umudumun üstüne seni ektim bir kere

Buram buram aşk kokar sana çıkan yollarım

Aşk meyhanesi açık sen de eşlik et bana

Mutluluk şarabından içelim kana kana

Aşka dair ne varsa yaşayalım birlikte

Ayrılık rüzgarları esmesin bizden yana

Yüzüyor duygularım aşkının denizinde 

Bilirim ki sen varsın gecelerin gizinde

Şarkıların içinde yaşayan efsanesin 

Aşkın melodi oldu yüreğimin dilinde', 'İnan ki senden başka yok kimseye güvenim Herkes terk etti beni bir sen kaldın sevenim Seni görmediğim an yüreğim isyanlarda Sapıyor sağa sol...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-sen-varsin-64-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞİİRLERİMİN YANGINI', 'si-i-rleri-mi-n-yangini-muhsin-yener-2-zy1bv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öyle kolay okunmaz benim şiirlerim,
Her harfinde bir sızı, her mısrasında bir yara var.
Ben öyle mürekkep dökmedim kâğıda;
Her kelimeme biraz ömrümü,
Biraz hasretimi, biraz da isyanımı kattım.

Bir dokunursun, yüreğine kor düşer,
Biraz yaklaşırsın, geçmişin kanar.
Çünkü benim şiirlerim,
Dağ başında unutulmuş bir çığlık,
Zulme boyun eğmeyen bir yürektir.

Ben sözü süslemedim kardeşim,
Acıyı olduğu gibi yazdım.
Kimi zaman bir annenin gözyaşı,
Kimi zaman yarım kalmış bir sevda,
Kimi zaman da insanlığın kanayan vicdanı oldum.

Okuyabilirsen oku beni,
Ama bil ki her mısramda bir ömür saklı.
Ben şiir yazmadım yalnızca,
Yüreğimin yangınını kâğıda bıraktım.

Muhsin Yener', 'Öyle kolay okunmaz benim şiirlerim, Her harfinde bir sızı, her mısrasında bir yara var. Ben öyle mürekkep dökmedim kâğıda; Her kelimeme bira...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/siirlerimin-yangini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyalar Aleminde', 'ruyalar-aleminde-kerim-yavuz-0stgy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızlığıma kanıp sevdiğim yok sanmayın

Benim de sevdiğim var rüyalar aleminde

Yemin olsun söylemem kimliğini sormayın

Benim de sevdiğim var rüyalar aleminde

Gece duygularımı onunla paylaşırım

Bütün mutlulukları rüyalara taşırım

Karanlığıma doğar kendimle barışırım

Benim de sevdiğim var rüyalar aleminde

Gizemli gecelerin meleği var karşımda

O var içtiğim sudu ekmeğimde aşımda

Damarımda kuvvettir hayatla yarışımda

Benim de sevdiğim var rüyalar aleminde

Her gece bir bahçede el ele tutuşuruz

Bir ağacın altında diz çöküp otururuz

Dilimiz kelâm bilmez gözlerle konuşuruz

Benim de sevdiğim var rüyalar aleminde

Yumuşacık saçları yastığıma serpilir

Başı bir kuş misali omuzuma devrilir

Belki tanışırsınız o kısmı Allah bilir

Benim de sevdiğim var rüyalar aleminde

Bana geceler yeter istemem gündüzleri

Çizilmiş yüreğime aşkın derin izleri

Beni hayata bağlar çimen renkli gözleri

Benim de sevdiğim var rüyalar aleminde', 'Yalnızlığıma kanıp sevdiğim yok sanmayın Benim de sevdiğim var rüyalar aleminde Yemin olsun söylemem kimliğini sormayın Benim de sevdiğim va...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ruyalar-aleminde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizliğe Sığındım', 'sessizlige-sigindim-hakan-sanyar-w91jr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yorgunum…

Öyle bir yorgunluk ki bu,

ne uyku dinlendiriyor beni

ne de sabahın ilk ışığı.

Bir kapıyı kapatıp

dünyayı dışarıda bırakmak istiyorum.

Sesler susunca belki

içimdeki gürültü de diner diye…

İnsanlardan kaçıyorum bazen,

kötü olduklarından değil;

kendimi anlatacak gücüm kalmadığından.

Bir “nasılsın?” sorusuna bile

uzun bir sessizlik sığdırıyorum.

Yalnızlık,

eskiden korktuğum bir misafirdi.

Şimdi yanı başımda oturuyor,

hiç konuşmadan anlaşıyoruz.

Belki de en çok

kimseye kırılmamak için kaçıyorum.

Kimseye yük olmamak,

kimsenin gözlerinde eksilmemek için…

Ve gece olunca

kendime dönüyorum usulca.

Bir ben kalıyorum,

bir de içimde dinmeyen yorgunluk.

Ama biliyorum…

Her kaçış sonsuza kadar sürmez.

Belki bir gün,

yeniden karışırım insanlara.

Bugün değil.

Bugün sadece

biraz sessizlik,

biraz yalnızlık

ve kimsenin bilmediği kadar

kendim olmak istiyorum.', 'Yorgunum… Öyle bir yorgunluk ki bu, ne uyku dinlendiriyor beni ne de sabahın ilk ışığı. Bir kapıyı kapatıp dünyayı dışarıda bırakmak istiyor...', ARRAY['Türk Edebiyatı','Şiir','Hakan Sanyar']::text[], 8.5, '{"poet":"Hakan Sanyar","poet_slug":"hakan-sanyar","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sessizlige-sigindim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde Sabah Olmuyor', 'i-cimde-sabah-olmuyor-hakan-sanyar-15s6g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayata dair güzel şeyler olmuyor artık.

Sabahlar, gecenin yüzünden

Siyah bir perdeyi yırtıp geliyor

Ama içeriye ışık değil,

Daha solgun bir karanlık doluyor.

Penceremin önünde bekleyen dünya

Her gün biraz daha uzak.

Sokaklar bildiğim isimleri taşıyor,

Ama hiçbir yol

Beni kendime götürmüyor.

İçimde terk edilmiş bir şehir var;

Kapıları pas tutmuş,

Meydanlarında rüzgâr dolaşıyor.

Bir zamanlar yaşayan ne varsa

Duvarlara gömülmüş sessizce.

İnsan bazen

Kendi kalbinin enkazında kalıyor.

Bir taşı kaldırsa

Altından eski bir ses çıkacak sanıyor,

Ama her şey susuyor.

Ne beklediğimiz geliyor,

Ne giden gerçekten gidiyor.

Bazı insanlar içimizden ayrılırken

Kapıyı açık bırakıyor.

Gece, o kapıdan girip

Yıllarca evimizde kalıyor.

Masada soğumuş bir çay,

Duvarlarda uzayan gölgeler…

Zaman, kırık bir bıçak gibi

Her gün aynı yerden kesiyor bizi.

Ve kimse görmüyor.

Kalabalıkların arasında

Yüzümde yaşayan bir yabancıyla yürüyorum.

Herkes bir yere yetişiyor,

Ben ise

Çoktan kaybolduğum bir yerde

Kendimi bekliyorum.

Hayata dair güzel şeyler olmuyor artık.

Belki de güzel olan her şey

Biz ona dokunamadan

Başka bir zamana göç ediyor.

Geceleri uzun yapan karanlık değil;

İçinde sabah olmayacağını bilmektir.

Ve bazı geceler,

İnsan uyumuyor.

Sadece gözlerini kapatıp

Kendi içinde

Yavaş yavaş

Kayboluşunu dinliyor.', 'Hayata dair güzel şeyler olmuyor artık. Sabahlar, gecenin yüzünden Siyah bir perdeyi yırtıp geliyor Ama içeriye ışık değil, Daha solgun bir ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Sanyar']::text[], 8.5, '{"poet":"Hakan Sanyar","poet_slug":"hakan-sanyar","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/icimde-sabah-olmuyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sazımın Telinden', 'sazimin-telinden-kerim-yavuz-qj4ql', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tanrım kalbime kuvvet ver

Tutam sevgiyi belinden

Umutlarım birer birer

Düşsün sazımın telinden

Çekmez başkası nazımı

Verin elime sazımı

Yazayım aşk fermanımı

Düşsün sazımın telinden

Kendimi bildim bileli

Türkülerdir gönül yeli

Duyguların en güzeli

Düşsün sazımın telinden

Sevgidir mutluluk yolu

Sevmek gerek dolu dolu

Cennet diyar Anadolu

Düşsün sazımın telinden

Gönül neler gördü neler

Güzeller bağrımı deler

Aşkla yıkanmış nağmeler

Düşsün sazımın telinden', 'Tanrım kalbime kuvvet ver Tutam sevgiyi belinden Umutlarım birer birer Düşsün sazımın telinden Çekmez başkası nazımı Verin elime sazımı Yaza...', ARRAY['Türk Edebiyatı','Şiir','Kerim Yavuz']::text[], 8.5, '{"poet":"Kerim Yavuz","poet_slug":"kerim-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sazimin-telinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AŞK FİDANI', 'ask-fi-dani-kerem-76ay9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aylar kayıp, yıllar yorgunsa,
Bahar rüzgarları gönlümden eserse,
Küllerimizden doğarsak eğer;
Hani olur da ellerin ellerime değer.
Mazur görülür tüm suçlar,
Birbirimize hasret kokan mektuplar yazarız.
İlk defa bize doğru uçar kuşlar,
Gagalarında bir katre aşk getirirler;
Kendi aşkımızı kendimiz yaratırız.
Görüyorsun işte küllerimizden,
Şu semaya uzanan bir aşk fidanı bu.
Virane hayattaki dertlerimizden,
Kana bulanmış bülbüllerimizden,
Göklerde gönül hürriyetimiz olan
Bir aşk büyütüyoruz, göğe kök salan.', 'Aylar kayıp, yıllar yorgunsa, Bahar rüzgarları gönlümden eserse, Küllerimizden doğarsak eğer; Hani olur da ellerin ellerime değer. Mazur gör...', ARRAY['Türk Edebiyatı','Şiir','Kerem']::text[], 8.5, '{"poet":"Kerem","poet_slug":"kerem","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ask-fidani-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebediyyen', 'ebediyyen-erol-aksu-tpsft', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'EBEDİYYEN 

Dışarıda esiyor deli rüzgar,

Dinmez gönlümdeki fırtınalar.

Yârdan geldi mi kötü haber,

Yüreğime düşer kor ateşi.

Aşkın kemendine düşmüşüm,

Ben yolumu kaybetmişim.

Sığınacak bir liman ararım,

Her geçene seni sorarım.

Bırakma beni bir başıma,

Seven gönlümü tek başına.

Geldim işte kapına,

Esirin oldum çaresizim.

Bu aşkın sevabından,

Korkmam ben günahından.

Sevdim seni ta ezelden,

Çıkamazsın kalbimden ebediyyen.

                    Erol AKSU 

                   15.11.2026', 'EBEDİYYEN  Dışarıda esiyor deli rüzgar, Dinmez gönlümdeki fırtınalar. Yârdan geldi mi kötü haber, Yüreğime düşer kor ateşi. Aşkın kemendine ...', ARRAY['Türk Edebiyatı','Şiir','Erol Aksu']::text[], 8.5, '{"poet":"Erol Aksu","poet_slug":"erol-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ebediyyen-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*** Cümle Cümle', 'cumle-cumle-nihat-kuruyer-3-v00ey', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ömür, hep kısacık derler

Yarınlar da uzadıkça uzanırmış 

En zor olan da, 

Bu belirsizliği, beklemekmiş 

Bakarsın bir gün o çok beklediğin 

Geciken hiç gelmeyecek, gelecek 

Gelip kapına girmiştir

Hiç uzamamış 

Bekletmemiş gibi.

Dal eğilmeye başlamıştır bir kere 

Gözlerine bakınca, gözlerin

Sözlerine bakınca, sözlerin 

Dilin pelte pelte, sürtmeye başlar 

Küçük heceler kurmaya başlarsın. 

Ve, kalıtsal bir tutku oluşur bedeninde

Suskun ve kimliksiz hissedersin 

Okunmamış o şiirler, hecesiyle 

Cümle cümle, 

Kalır dilinde..', 'Ömür, hep kısacık derler Yarınlar da uzadıkça uzanırmış  En zor olan da,  Bu belirsizliği, beklemekmiş  Bakarsın bir gün o çok beklediğin  G...', ARRAY['Türk Edebiyatı','Şiir','Nihat Kuruyer 3']::text[], 8.5, '{"poet":"Nihat Kuruyer 3","poet_slug":"nihat-kuruyer-3","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cumle-cumle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezara Kadar', 'mezara-kadar-erol-aksu-2x5px', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'MEZARA KADAR

Gözümde hasretin uykusuzluğu,

Kalbimde beklemenin huzursuzluğu.

Bakıyorum şimdi senin resmine,

Elimde sigara çekiyorum içime.

Yaşıyorum ben gözlerinde,

Ölüyorum sanki yokluğunda.

Şu üç günlük dünyamda,

Beklerim her gün yollarında.

Suskun dilim açıldı birden,

Seni görünce çözüldü hemen.

İki sözü bir araya getiremeden,

Tutuldu şimdi yeniden.

Vuslat beklerken ayrılık oldu,

Seven gönlüm harap oldu.

Bekleyeceğim seni ölene kadar,

Benim sevgim mezara kadar!

                                 Erol AKSU 

                                14.11.2026', 'MEZARA KADAR Gözümde hasretin uykusuzluğu, Kalbimde beklemenin huzursuzluğu. Bakıyorum şimdi senin resmine, Elimde sigara çekiyorum içime. Y...', ARRAY['Türk Edebiyatı','Şiir','Erol Aksu']::text[], 8.5, '{"poet":"Erol Aksu","poet_slug":"erol-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mezara-kadar-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehitlik Muradım', 'sehitlik-muradim-erol-aksu-1qupm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ŞEHİTLİK MURADIM

İki milyar Müslüman sus pus olmuş dünyada,

İzliyorlar hep birlikte, kardeş ölümünü yayında.

Can dayanmaz artık buna, canlar gitti binlerce,

Çoluk çocuk hepsi öldü, insan kalmadı Gazze''de.

Konuştu dünya liderimiz, alkışladı büyük milletimiz,

Lakin olmadı yardımımız, bitmiş bizim insanlığımız.

Onca İslam Devletinin yetmedi gücü İsrail''e,

İHA, SİHA askerimizi, gönderemedik Gazze''mize.

Camilerde, hutbelerde verdiler millete nasihati,

Anlatmadılar hiçbir zaman, dinin esas hakikatını.

Boykut yapmayı cihat saydılar, bu milleti hep uyuttular,

Meydan meydan dolaşıp, bir de buna şov yaptılar.

Yemin olsun Allah''a, el basarım Kur''an''a,

Giderse asker Gazze''ye, ben de giderim oraya.

İslam uğruna savaşmak, en öncelikli hedefim,

Allah yolunda şehit düşmek, en büyük muradım.

                                                       Erol AKSU 

                                                      14.11.2026', 'ŞEHİTLİK MURADIM İki milyar Müslüman sus pus olmuş dünyada, İzliyorlar hep birlikte, kardeş ölümünü yayında. Can dayanmaz artık buna, canlar...', ARRAY['Türk Edebiyatı','Şiir','Erol Aksu']::text[], 8.5, '{"poet":"Erol Aksu","poet_slug":"erol-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sehitlik-muradim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çakma Devrem', 'cakma-devrem-erol-aksu-9fp90', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ÇAKMA DEVREM 

Korgan yolları yokuştur,

İnişi çıkışından zordur.

Bir yiğit var aramızda,

Anlatır her gün Korgan''ı.

Şen şakrak birisidir,

Sohbeti hep güzeldir.

Zor bulunur emsali,

Polisin güler yüzüdür.

Lakin biraz bahtsızdır,

Zor geldi ilhamı.

Yoktur tavlada hiç şansı,

Yek gelir hep zarı.

Büyük Şeflerin içinde,

Özeldir hep onun yeri.

Çakma devrem kendisi,

Yoktur onun gibisi.

Nursoyludur soyadı,

Nur saçar nur yüzü.

Elindeki tesbih ile,

Salavat çeker hep dili.

Ağır basar kıdemi,

Dinlemez hiç kimseyi.

Yanlış yapanın biletini,

Keser hemen kendisi.

              Erol AKSU 

             14.11.2026



[  ]', 'ÇAKMA DEVREM  Korgan yolları yokuştur, İnişi çıkışından zordur. Bir yiğit var aramızda, Anlatır her gün Korgan''ı. Şen şakrak birisidir, Sohb...', ARRAY['Türk Edebiyatı','Şiir','Erol Aksu']::text[], 8.5, '{"poet":"Erol Aksu","poet_slug":"erol-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cakma-devrem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benimle misin?', 'benimle-misin-erol-aksu-cahnm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BENİMLE MİSİN?

Boş ümide mi kapıldım?

Yoksa hayallere mi daldım?

Bir haberini beklerken dışarıda,

Ne sıkıntılar yaşattın İçimde.

Gönül eğlendirmekse muradın,

İnan yanlış adama çattın.

Bırak oynama duygularımla,

Samimi değilse niyetin.

Aşık oldum ben sana,

Canım geldi burnuma.

Ne hayaller kurdum seninle,

Hepsini yarım bıraktın.

Ben seversem tam severim,

Samimidir hep niyetim,

İnan yoktur ortası bunun,

Ya çok severim ya hiç.

Sevmiyorsan söyle bana,

Ama beni aldatma,

Uzaklardan yine severim,

Yeter ki hevesimi kırma.

Sevdim seni ölümüne,

Giderim seninle her yere.

Net kararını söyle bana,

Benimle misin, değil mi?

Değilsen söyle bileyim,

Sevdamla birlikte gideyim.

Bir daha çıkmam karşına,

Bu aşkı burda bitireyim.

                Erol AKSU

               14.11.2026', 'BENİMLE MİSİN? Boş ümide mi kapıldım? Yoksa hayallere mi daldım? Bir haberini beklerken dışarıda, Ne sıkıntılar yaşattın İçimde. Gönül eğlen...', ARRAY['Türk Edebiyatı','Şiir','Erol Aksu']::text[], 8.5, '{"poet":"Erol Aksu","poet_slug":"erol-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/benimle-misin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin Var mı?', 'haberin-var-mi-i-brahim-cosar-1w6sa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gör bak ne oluyor her gün hayatta,

Suçlu arınıyor, haberin var mı?

Zenginler yaşarken köşk ile yatta,

Fakir sürünüyor, haberin var mı?

Adı simle işli giydiği donda,

İnsafla merhamet kalmamış onda.

Beyler dans ederken repoda, fonda,

Yönü görünüyor, haberin var mı?

Cahil halkım Rab adını duyunca,

Niyet edip cemaate uyunca,

Şeyhler şıhlar, tıka basa doyunca,

Zevkten geriniyor, haberin var mı?

Muhalife öfke, yandaşa rıza,

Yalakaya unvan, isyana ceza.

Olanları unutur mu hafıza?

Hırsız korunuyor, haberin var mı?

Eskiden dağlardı tutulan mevki,

Şimdi şehirlerde geziyor şaki.

Tavuğu kümesten kapacak tilki,

Kürke bürünüyor, haberin var mı?

Coşari, hayatın yolları diken,

Siyaset, kalplere fitneyi eken.

Hak, hukuk, eşitlik yok oluyorken,

Sona yürünüyor, haberin var mı?

13.11.2026 / Samsun', 'Gör bak ne oluyor her gün hayatta, Suçlu arınıyor, haberin var mı? Zenginler yaşarken köşk ile yatta, Fakir sürünüyor, haberin var mı? Adı s...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Coşar']::text[], 8.5, '{"poet":"İbrahim Coşar","poet_slug":"i-brahim-cosar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/haberin-var-mi-253-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tezat', 'tezat-meczup-kalem-fuf0t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimse görmemiş böylesine tezatı,

Herkes ya doğu ya batı partizanı.

Normal gördüklerinden ahlaksızlığı,

Olamıyorum toplumun bir parçası;

Bilmiyorum hangi tarafta sıkıntı.

Takatım kalmadı artık bu insanlara:

Özgürüm deyip mabadını açanlara,

Dini kullanıp mabedine kaçanlara...

Onlara olan tek kelamımsa:

Kur’an’dan bir ayet; 177, Bakara.', 'Kimse görmemiş böylesine tezatı, Herkes ya doğu ya batı partizanı. Normal gördüklerinden ahlaksızlığı, Olamıyorum toplumun bir parçası; Bilm...', ARRAY['Türk Edebiyatı','Şiir','Meczup Kalem']::text[], 8.5, '{"poet":"Meczup Kalem","poet_slug":"meczup-kalem","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tezat-151-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biten Aşk', 'biten-ask-i-brahim-cosar-3af46', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine yolun şaştı gönül,

Aşkın ile taştı gönül,

Hasret denilen yangına

Gurbet elde düştü gönül

Kardelenler açar deme

Benden aşkı esirgeme

Vuslat için bir umut ver

Güneşimi erteleme

İki gönül arasında

Kan akıyor yarasında

Biten bir aşk görüyorum

Gözlerinin karasında

Bende gurbet sende hasret

Diyorsun ki biraz sabret

Yine çenen düştü şair

Biraz da sen göster gayret

15.11.2026/Samsun', 'Yine yolun şaştı gönül, Aşkın ile taştı gönül, Hasret denilen yangına Gurbet elde düştü gönül Kardelenler açar deme Benden aşkı esirgeme Vus...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Coşar']::text[], 8.5, '{"poet":"İbrahim Coşar","poet_slug":"i-brahim-cosar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/biten-ask-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-selcuk-karakis-icfj5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidilmeyen yol mu vardı

Prangama takılmasam

Aşılmayan dağ mı vardı

Önünde sen durmasan

Söz dinler nefis mi vardı

O gözlerine dalmasam

Koparılmaz gül mü vardı

Böyle nadide olmasan

Dönülecek sıla mı vardı

Ben kapıları açmasam

Gönle gurbet mi vardı

Sen yoluna çıkmasan', 'Gidilmeyen yol mu vardı Prangama takılmasam Aşılmayan dağ mı vardı Önünde sen durmasan Söz dinler nefis mi vardı O gözlerine dalmasam Koparı...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Karakış']::text[], 8.5, '{"poet":"Selçuk Karakış","poet_slug":"selcuk-karakis","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gurbet-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair Ve Aşk''ın Halleri...~.~.~...', 'sair-ve-ask-in-halleri-selim-bayrak-ywzbn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '‎

‎Şair Ve Aşk''ın Halleri : 

‎

‎Varoluşun 

‎Da 

‎Öfkeli Ya Da Duygulu 

‎Ya Da Uykulu

‎Ve De Vurgulu

‎Bir Şiir Bir Şair

‎Aşık Aşk 

‎Ve De Sevda Olmadığını 

‎Kim Söyledi... 

‎

‎Şair ve Aşık 

‎Birer Gazdır

‎Sürekli ısınır

‎Ya da yoğuşur

‎Yoğunlaşır 

‎Aslında 

‎Her İnsan 

‎Her Şey Gibi

‎Belki Bir Miktar

‎Daha Faz''la

‎Ve Daha Kolay... 

‎

‎

‎Bir şey sıcaklaştığında değil

‎Soğuştuğunda yoğuşur belki

‎Ama resmi büyüttüğündeyse 

‎Gaz haline gelen Şey 

‎Öncesinde ısınan bir katıdır

‎Katı ya da sıvı hale gelen de 

‎Öncesinde 

‎Soğuyan bir gaz

‎

‎Canlılığın 

‎Oluşumun 

‎İlişkinin 

‎Verimin 

‎Çeşitliliğin 

‎Tohumu

‎Döngüselliktir

‎Biyoloji de 

‎Kainatın döngülerinin

‎Bir üretimidir

‎Üremek sadece 

‎Biyolojiye 

‎Ve türsel kopyaya indirgenemez 

‎

‎Canlılık 

‎En yalın enerjide bile bulunan 

‎Hareketliliğin 

‎Diğer enerji 

‎Ve sistemlerle 

‎Yani enerji organizasyonlarıyla

‎İletişim kurabilme kapasitesidir

‎

‎Bu da bir alfabe demektir

‎Enerji dinamik esnek özünde 

‎Bilgi üretir ve taşır 

‎Ama bu her daim 

‎Uyumlu ya da uyumsuz

‎İlişkiler ağı içinde gerçekleşir

‎

‎Hiçbir enerjiyi

‎Ne sonsuza kadar yalıtabilir

‎Ne de dondurabilirsiniz 

‎Mutlak sıfır yoktur 

‎

‎Hiçlik ortam 

‎Yokluk dönüşümdür 

‎Her bileşke zaten geçicidir

‎Isıl ölüm yaşayan bir sistem bile

‎İçten içe devinir 

‎Ve kararlılığı 

‎Ve ortamı sabit değildir

‎Zaten başka bir etmene maruz kalacak 

‎Ya da kendi içinde de 

‎Eninde sonunda faz değiştirecektir

‎

‎Her şey bir alfabedir

‎Ama muhakkak 

‎Çözünür 

‎Tekrar birleşir 

‎Ve bazen 

‎Yavaş yavaş 

‎Bazen de 

‎Hızlı hızlı değişir 

‎Sadece biyoloji değil

‎Her yapı evrimleşir 

‎Ama kodların sağlamlığı 

‎Sistemlere göre değişir 

‎Ama sistemler de iç içedir

‎Sanma ki 

‎Kainat 

‎Ve fizik yasaları da hep aynıydı

‎Ve aynı kalacak

‎

‎Ama bir yapı 

‎Muhakkak 

‎Oluşsal yolculuğunda 

‎Tamamen dağılır 

‎Varlığını 

‎Alfabesini

‎Kod ve protokollerini 

‎Üretemez hale gelir 

‎

‎Ama enerji 

‎Hem 

‎Kendi içindeki oluşumuna 

‎Hem de etrafıyla 

‎Uyumlu ya da uyumsuz 

‎Etkileşimine 

‎Devam eder

‎Hiçlikle de 

‎Sürekli etkileşir  

‎Hem kendi içindeki

‎Hem kendi dışındaki... 

‎Ayrıca iç ve dış da

‎Mutlak değildir

‎

‎Enerji sadece kendini gerip 

‎Farklı koşullarda 

‎Oluşlarda var etmez

‎Hiçliği de gerer 

‎Ve her an 

‎Birlikte devinirler

‎Boşluk olmadan 

‎Hoşluk olmaz

‎

‎Ama her boşluk da 

‎Hiçlik değildir

‎Boşluk da

‎Hiçlikle etkileşir 

‎Ve hiçlik

‎Nasıl

‎En yalın enerjinin 

‎Harcında bile varsa

‎Boşluğun da 

‎Harçlarından biridir 

‎

‎Alfabe 

‎Sadece kelimeler

‎Semboller ve bilgiden oluşmaz

‎Ortam ve bağlam da 

‎Ona dahildir 

‎Varoluşun alfabesinde 

‎Yokluk hiçlik 

‎Ve boşluk da vardır

‎Dikkatli bakarsan 

‎İnsan 

‎Ya da 

‎Zihin alfabesi de böyledir 

‎

‎Tamamen soyut 

‎Hiçbir şey yoktur

‎Tamamen somut da

‎Her şey bir hal''dir

‎Ve birbirine dönüşebilir 

‎

‎Yokoluş da 

‎Varoluş gibi bir fazdır 

‎Ve hiçlik de

‎Varoluşun alfabesinde 

‎Onu mümkün kılan

‎Ortam 

‎Dolaylı bir harftir 

‎Sadece boşluk 

‎Değil 

‎Hiçlik de olmadan

‎Herhangi bir harfi

‎Var edemezsiniz

‎

‎Hiçlik ve enerji

‎Bir varlığın 

‎Bir şeyin

‎İç içe geçmiş bir

‎Yüzü ya da halidir

‎O ilişki de 

‎Hiçbir zaman 

‎Mutlak sabit ve stabil değildir

‎

‎Her istikrar görelidir

‎Ve alfabe tarafından 

‎Her an yeniden yaratılıp

‎Kurgulanır

‎Ve hiçbir alfabe 

‎Kendini

‎Yavaş ya da hızlı

‎Değişmekten alıkoyamaz

‎

‎Değerli filozof 

‎Derrida''nın da değindiği gibi

‎Fark ve değişim kaçınılmazdır

‎Bağlam 

‎Birebir sabit mutlak

‎Ve aynı kalamaz... 

‎

‎

‎8 yıl kaskatı kesilen

‎Selim de 

‎İçten içe 

‎Belli belirsiz devinirken

‎Anlam Aşkıyla çözündü

‎Ama kalbi 

‎Katı halinden 

‎Daha çok kanadı

‎Acıdı

‎Sıvı hale geçince... 

‎Ve akacağı bir 

‎Nehir aradı

‎

‎

‎Şairler ve Aşıklar 

‎Önce Işığa akar 

‎Ufak bir yansıdan

‎Sımsıcak olur içi

‎O Renkli 

‎Sıcak Gölge 

‎Kendinin sanır

‎Daha da ısınır

‎Daha da harlanır

‎Ama kaynağın 

‎Kendisine ait olmadığını

‎Anladığında 

‎Ortam soğumaya başlar

‎Hem yoğuşur

‎Hem hasarlanır

‎

‎Aşıklar belki 

‎Kaçmayı becerir 

‎O dona dönebilecek

‎Olgudan

‎Korkudan 

‎

‎Şairin işi ise 

‎Her fazı kurcalamaktır

‎Aşkın imkansızlığıyla

‎Yoğuştukça yoğuşur 

‎Sıvı halin

‎Donup 

‎Ruhun kaskatı kesilmesi de 

‎Vaka-i Adiye

‎Alayı Bakiye''dir 

‎

‎Ama akıllı şair direnir

‎Kalemini susturmaz

O istese de 

‎Hiçbir aşktan kaçamaz

‎Bir ömür anlasa da 

‎Anlamasa da 

‎Kaleminin mürekkebi 

‎En katı halinde bile

‎İçten içe kaynar 

‎Değişir dönüşür ve gelişir 

‎

‎Şair 

‎Ruh Sağlığı için değil

‎Ruh Harlığı için yaşar

‎Ama her şey 

‎Tezatıyla mümkündür

‎Ve Aşıklardan fazla 

‎Şairler 

‎Ruh Darlığı Yaşar

‎Ve her darlık

‎Bir gerilimdir

‎Kainat 

‎Ya da varoluş

‎Kadersel oluş 

‎Bir bileşkeye 

‎Yeterli ömürü verirse

‎O darlık bir yerde patlar

‎

‎Sonsuz Toz Tanesi

‎Sonsuz Kar Tanesi Perisi

‎Bana ait değil

‎O kainata ve kendine ait 

‎Ama O''nun her renkli

‎Ve karanlık gölgesi de

‎Ufkuma düşmüşse

‎Bana ve kainata ait 

‎

‎İçimde ısınan soğuyan

‎Uçuşan yoğuşan 

‎Katışan donuşan 

‎Tekrar tekrar oluşan 

‎Tekrar tekrar ölüşen 

‎Tekrar tekrar doğuşan

‎Tekrar tekrar kuruyan

‎Tekrar tekrar

‎Bir toz tanesinden bile 

‎Buharlaşan 

‎İçimde 

‎Tüm çelişkileriyle 

‎Mikro değil

‎Makro değil

‎Kendine has 

‎Bir kosmos kuran... 

‎

‎Egom 

‎Periliğine 

‎Ürkekliğin 

‎Ve Gizemine 

‎Tahmin ettiği

‎Narsizm 

‎Ve kibrine 

‎İlk günden beri 

‎Ne kadar gıcık olursa olsun 

‎

‎Benim için 

‎Eşsiz bir Peri olduğunu

‎Kabul etmemenin 

‎Ruhumun fiziğinde 

‎Kimyası biyolojisinde 

‎Hiçbir karşılığı yok 

‎Her inkar 

‎Ayrı bir faz doğuruyor

‎Her kabulün doğurduğu gibi

‎

‎Ve Dünya''da 

‎Aslında 

‎Sanılanın aksine 

‎Peri''den 

‎Bol bir şey yok

‎Ve bu sadece

‎Bir insan 

‎Kadın

‎Erkek

‎Ya da başka kişi değil

‎Kişinin kendisi

‎Ve herhangi bir şey aslında

‎

‎Ama 

‎Bir gün

‎O makamdan 

‎İner misin bilmiyorum

‎Ama 

‎Tanrıça katında 

‎Bir tek sen oturuyorsun

‎

‎Diplomatik 

‎Bir merhabayı 

‎Esirgediğin 

‎Ama şiirlerine dalıp

‎Varlığını yok saydığın şair

‎Hiçbir renkli gölgeye 

‎Kendisininki dahil 

‎Dövdüremedi Gölgeni 

‎Anlaşılan o ki

‎Ruhuma da bedenime de

‎Senin kalıcı dövmen yapılmış

‎Beni komple söküp

‎Tekrar birleştirmeden 

‎O dövmeyi yok etmek

‎Mümkün değil sanırım 

‎Derrida Abim 

‎Beni affetsin

‎

‎Hafızam silinse de 

‎Ferhat Göçer''in 

‎Arar Bulurum 

‎Şarkısında da dediği gibi 

‎

‎" Dünyaya bir daha gelsem sevgilim

‎Arar bulurum yine seni severim "

‎

‎Sevgilim olsan da 

‎Olmasan da... 

‎

‎Sevdiğim diğer

‎Tüm Güzeller

‎Ve Perilerden de 

‎Özür dilerim

‎

‎Hangi makama 

‎Kimi neyi

‎Ne zaman

‎Ve nasıl

‎Oturtacağım... 

‎Ben karar vermiyorum sanırım

‎

‎Duygusal acziyet

‎Ve savruluş 

‎Şairlerin kaderi sanki

‎

‎Ya da ben 

‎Kendimce 

‎Uyanık bir filozof da 

‎Olduğum için

‎Kitabın ortasından değil

‎En kolay yerinden konuşuyorum

‎

‎"By the way"  

‎Her şair 

‎İstese de istemese de 

‎Farkında olsa da olmasa da

‎Bir filozoftur

‎Belki de her insan gibi

‎

‎Önemli olan ise 

‎Filozof olup olmamak değil

‎Bilgiyi nasıl yoğurduğundur

‎

‎Ayrıca 

‎Her Yiğidin 

‎Yoğurt Yiyişi 

‎Farklıdır 

‎

‎Da 

‎

‎Keşke

‎

‎Bir

‎

‎" Yiğit " 

‎

‎Olsaydım... 

‎

‎

‎🌈

‎

‎

‎17.11.2026 / Yoğuşmalı Şair 

‎

‎❣️

‎

‎

‎

‎

‎

‎', '‎ ‎Şair Ve Aşk''ın Halleri :  ‎ ‎Varoluşun  ‎Da  ‎Öfkeli Ya Da Duygulu  ‎Ya Da Uykulu ‎Ve De Vurgulu ‎Bir Şiir Bir Şair ‎Aşık Aşk  ‎Ve De Sev...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":431,"source_url":"https://www.antoloji.com/sair-ve-ask-in-halleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gider miydim?', 'gider-miydim-i-brahim-cosar-xv05d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gittim diye sitemler edip durursun bana

Senden sevdalı sözler gelseydi gider miydim

Sitemli sözcüklerle her gün vurursun bana

Yüreğin kalp kapımı çalsaydı gider miydim?

Gönlün huzur mu bulur sınırını aşmaktan?

Belli ki zevk alırsın dertlerimi deşmekten,

Gidişim, belirsizlik girdabına düşmekten;

Vuslat için bir çaba olsaydı gider miydim?

Yıllardır bir hayalin içinde yaşıyorum,

Hasrete yürek nasıl dayandı, şaşıyorum,

Her gece düşlerimde senle dolaşıyorum,

Ellerin ellerimde kalsaydı gider miydim?

Kurduğumuz hayalde aşkımız bir masaldı,

İmkânsızı denedik, bizi hasrete saldı.

Yıllardır gece gündüz aklım hep sende kaldı,

Senin de aklın bende kalsaydı gider miydim?

Sözlerin sitemkârdı, başın öne eğikti,

Elin titrek, sinirli, sesin hayli boğuktu.

Selam sabahı kestin, bakışların soğuktu,

Gözlerin gözlerime dalsaydı gider miydim?

İnan ki son günlerde aradım seni sık sık,

Uzun sürdü sessizlik, bir kez telefona çık.

Fotoğraf göndermişsin, kaş çatık, yüzün asık,

Yüzün eskisi gibi gülseydi gider miydim?

Şiirler gönüllerden ırmak olup akıyor,

Cümleler uzadıkça yürekleri yakıyor.

Gözlerim görünmeyen gözyaşları döküyor,

Ellerin gözyaşımı silseydi gider miydim?

Biz kaybettik mantıkla aşkın yaptığı harbi,

Umudun tükenmesi ayrılığın sebebi.

Coşari’nin kurduğu hayallerdeki gibi,

Kalbin aşk kıymetini bilseydi gider miydim?

16.11.2026 / Samsun', 'Gittim diye sitemler edip durursun bana Senden sevdalı sözler gelseydi gider miydim Sitemli sözcüklerle her gün vurursun bana Yüreğin kalp k...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Coşar']::text[], 8.5, '{"poet":"İbrahim Coşar","poet_slug":"i-brahim-cosar","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gider-miydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçün Beşlisi', 'ucun-beslisi-sinan-oguzhan-4l8f5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kulla kulluk edeceksen ey gafil bilmeden

 Aşkı arama boşa bin perişan olursun

 Ne eceler geldi geçti bu alemden bir bir

 Neşe içindeydiler hepsi bir içim cansuyu

 Narsız nurla ziyada an dem sönüp gittiler

 Aşk istersen ebedi narla dile ey garip

 Sır aleminden iner bir gece yüreğine 

 Bilesin ki kavuşmak yok bu ziya alemde

 Yanacaksın ahiri bilmeden şükür ile

 Nara bulanırsın erenlerin kor elinde

 Yandıkça yanasın gelir daha da istersin

 Ezalar sefa olur gayri sonsuz döngüde 

 Her solukta nar olur Rabbine sığınırsın

 Son nefes ebedi nur olur neşe içinde 

 Anlarsın ki sultanın ezelden yüreğinde 

17.11.2026 – 11.30

Karaoğlanoğlu', 'Kulla kulluk edeceksen ey gafil bilmeden  Aşkı arama boşa bin perişan olursun  Ne eceler geldi geçti bu alemden bir bir  Neşe içindeydiler h...', ARRAY['Türk Edebiyatı','Şiir','Sinan Oğuzhan']::text[], 8.5, '{"poet":"Sinan Oğuzhan","poet_slug":"sinan-oguzhan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ucun-beslisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Büyük Pişmanlığımsın!', 'en-buyuk-pismanligimsin-nihat-malkoc-n01d9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni zannetmiştim peri!

En büyük pişmanlığımsın!

Dönüp baktığımda geri,

En büyük pişmanlığımsın!

Baharı kışa döndürdün

Vicdanı taşa döndürdün

Kirpikte yaşa döndürdün

En büyük pişmanlığımsın!

Ben alevim, sen çırasın

Renkler içinde karasın

Ruhumda derin yarasın

En büyük pişmanlığımsın!

Düştüm hicranın koruna

Yaktı(n) cehennem narına

Ne bıraktın ki yarına?

En büyük pişmanlığımsın!

Umutları serap ettin

Gençliğimi harap ettin

Her ne varsa türap ettin

En büyük pişmanlığımsın!

Bahçemde açmadı çiçek

Talan etti börtü böcek

Denk tutuldu çulla ipek

En büyük pişmanlığımsın!

Zaman değiştirdi seni

Asra çevirdin her günü

Bugün arar oldum dünü

En büyük pişmanlığımsın!

Ne bahar ne yazım kaldı

Elde kırık sazım kaldı

Çoğu gitti, azım kaldı

En büyük pişmanlığımsın!

Yüreğimdeki sancısın!

Kalp hırsızı, yalancısın!

Şimdi bana yabancısın!

En büyük pişmanlığımsın!

17 Kasım 2026/Trabzon', 'Seni zannetmiştim peri! En büyük pişmanlığımsın! Dönüp baktığımda geri, En büyük pişmanlığımsın! Baharı kışa döndürdün Vicdanı taşa döndürdü...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/en-buyuk-pismanligimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fasık', 'fasik-bayram-erdogan-n2hdr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Fasık yaşıyorsun ölüm yok gibi

Ölümsüz dünyaya hazırlığın yok

Ölüm şaka yapmaz olsa da nebi

Ölümsüz dünyaya hazırlığın yok

Burada ölüm var bura geçici

Ölüm ayırmıyor yaşlıyı genci

Ölüme yeter mi beşerin gücü

Ölümsüz dünyaya hazırlığın yok

Hak yanında varsa kulun sevgisi

Sarsılmaz bozulmaz zerre dengesi

Orada adalet hakkın kendisi

Ölümsüz dünyaya hazırlığın yok

Vadenin sonu var vaktinde biter

Melekü''l-Mevt gelir nefesin keser

Yerinde yurdunda ne yeller eser

Ölümsüz dünyaya hazırlığın yok', 'Fasık yaşıyorsun ölüm yok gibi Ölümsüz dünyaya hazırlığın yok Ölüm şaka yapmaz olsa da nebi Ölümsüz dünyaya hazırlığın yok Burada ölüm var b...', ARRAY['Türk Edebiyatı','Şiir','Bayram Erdoğan']::text[], 8.5, '{"poet":"Bayram Erdoğan","poet_slug":"bayram-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fasik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YARINA SÖZ VERME', 'yarina-soz-verme-seval-ozgul-04cvr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her Günü Son Şansınmış Gibi Yaşa

Haydi kalk gönlüm,
biraz kendine gel,
Dün geçti, yarın meçhul;
bugüne gülümse.

Her üzüntüyü yük etme yüreğine,
Biraz da hayatı yaşa,
kendini üzme.

Yarına söz verme, ne olur bilinmez,
Bugünün güzelliği
yarına ertelenmez.
Gülmek varken ağlama,
hayat beklemez,
Ömür dediğin geçer,
geriye dönülmez.', 'Her Günü Son Şansınmış Gibi Yaşa Haydi kalk gönlüm, biraz kendine gel, Dün geçti, yarın meçhul; bugüne gülümse. Her üzüntüyü yük etme yüreği...', ARRAY['Türk Edebiyatı','Şiir','Seval Özgül']::text[], 8.5, '{"poet":"Seval Özgül","poet_slug":"seval-ozgul","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yarina-soz-verme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz Göre Göre', 'goz-gore-gore-osman-akcay-6z2jp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tamahkârlık yapma üç beş kuruşa

Çıkar için geçme esas duruşa

Sakın aman gelme bir dolduruşa

Tek başına kalma göz göre göre

Bulunur her işin bir çıkar yolu

Tahrik etme asla sen sağı solu

Sarsın varlığını dostluğun kolu

Kederlere dalma göz göre göre

Elbette yanılır sevda narında

Dolan dur neşeyle aşk pınarında

Bekleme sevginin sen kenarında

Gözlerde ufalma göz göre göre

Yünden çorap ören iplik eğirir

Güneşli gün dahi kara çevirir

Tutulmayan sözler insan devirir

Beddualar alma göz göre göre

Seven kalpler neden ızdırap çeksin

Mutlu olmak varken gözyaşı döksün

Sebepsiz yaşlanıp erkenden çöksün

Gençliğini çalma göz göre göre

Dr.Osman Akçay (Seğmenoğlu)', 'Tamahkârlık yapma üç beş kuruşa Çıkar için geçme esas duruşa Sakın aman gelme bir dolduruşa Tek başına kalma göz göre göre Bulunur her işin ...', ARRAY['Türk Edebiyatı','Şiir','Osman Akçay']::text[], 8.5, '{"poet":"Osman Akçay","poet_slug":"osman-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/goz-gore-gore-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk-ı Ebed.!', 'ask-i-ebed-baris-cansever-f9zt0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecenin en derin yerinde bir sızı başlar ya,

İşte o an gönlüm seni çağırır, duyar mısın bilmem.

Alnıma mühürlenmiş en güzel yazımsın benim,

Senden gayrı bir yola adım bile atmam ben.

✨✨

Gel artık sevdiğim, bitsin bu amansız bekleyiş,

Aşkın en saf haliyle kapımı çal bu gece.

Sen benim kaçamadığım, vazgeçemediğim yazgımsın,

Adın da dilimde saklı, en mukaddes hece.

✨✨

Yıldızlar da şahit olsun bu sessiz duama,

Rüzgâr kokunu getirsin bana uzak diyarlardan.

Bizi birbirimize bağlayan o görünmez ip var ya,

Çeksin seni göğsüme, kurtarsın bu hicrandan.

✨✨

Gözlerin gözlerime değdiği o kutlu an,

Zaman dursun, dünya sustuğu yerde kalsın.

Sen bana en başından beri yazılmış olansın,

Gel ki bu yarım kalmış ömrüm seninle dolsun.

✨✨

Ne mesafeler engel bu deli sevdaya,

Ne de aramıza giren o soğuk mevsimler.

Alın yazım diye öptüm seni en derinden,

Kavuşsun artık birbirine hasret kalan eller.

✨✨

Şafak sökmeden yetiş bu sana yanan kalbe,

Sustur içimdeki o dinmeyen fırtınayı.

Sen benim en güzel kaderim, tek gerçeğimsin,

Gel de vuslata dönüştür artık bu eşsiz rüyayı!', 'Gecenin en derin yerinde bir sızı başlar ya, İşte o an gönlüm seni çağırır, duyar mısın bilmem. Alnıma mühürlenmiş en güzel yazımsın benim, ...', ARRAY['Türk Edebiyatı','Şiir','Barış Cansever']::text[], 8.5, '{"poet":"Barış Cansever","poet_slug":"baris-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ask-i-ebed-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medeniyetin Beşiği Mezopotamya', 'medeniyetin-besigi-mezopotamya-mehmet-cobanoglu-eo46l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey dillere destan, toprağın altında fısıldar bin yıllık dermanın.
Adın yazıldı tarihe, asla silinmez bir hayal artık
Bağrın o eski, o derin liman,
Sanki Midyat’ın, Kızıltepe''nin o taş evleri,
Zamanı yontan o kadim hallerin...
Bin sevgi,
Bin sevda,
Kars’ın Ruslardan kalan damlarında,
Ayazda üşüyen
Ama sönmeyen
Bir köz gibi sıcak.
Sen ki medeniyetin beşiği, bereketli hilal,
Uruk, Babil, Akad küllerinden doğan
Mezopotamya
Yalnız göğsüme durmadan bir rüzgâr esiyor,
Öte yanda içimde büyümeyen asi bir çocuk var,

Ve
Bendeki olan sen,
Hâlen
Altmış yıllık bir hasret
Bir damla suya kavuşan toprak gibi
Can buldum, birden uyandım, toprağa ekilen tohum gibi.

Korkmuyoruz karanlıktan, ne de şu gecenin sahiplerinden,
Çünkü göğsümüzde senin adın,
Yüreğimizde ezilenlerin ahı var.
Biz bu sevgiyi
Gözaltıları,
Sürgünleri,
Bin yıllık kavganın orta yerinde büyüttük;
Ne göz yaşımız kurudu
Ne de inancımız
Mezopotamyam zapt edeceğimiz o büyük gün yakın.

Fırat’ın kıvrımında fersah fersah bir buğu tüter eskiden beri,
Her taşın altında yatar
Bin yıllık bir tesbih.
Kürt dağlarında rüzgâr
Özgürlüğü fısıldar,
Ermeni manastırında kederli
Çanlar çalar.
Bu güzelliklerin yüzü suyu hürmetine  
Ne olur,
Hep derin bak,
Sakın benden kaçırma gözlerini;
Yılların koyu karanlığının bitmesine ramak var.

Şimdi her köşe başı bahar,
Şimdi içimde,
Seninle çoğalan
Sana varan
Bir masalın
Tüm yolları var.
Kürt’ün halayı, Ermeni’nin ağıtı, Pers’in nazı,
Halklarının ortak coğrafyası 
Mezopotamya.
​Sen, bir dağ ateşi gibi düştün 
Ömrüme,
Elegez''in yamaçlarından
Ağrı''nın doruğundan
Süzülen bir tül gibisin,
Yüreklere doğan
Özgürlüğün kızıl güneşi,
Vadilerinde
Dicle''nin asi ve derin serinliği...
Toprağında
Dağlara çıkan partizanların ayak sesleri var.

Ben
Sana sevdalı rüzgâr gibi asi,
Umut gibi dağlı,
Yaman ve cesur.
Kızdırmasınlar beni, bana tehdit varsa eğer;
Sınır tanımam, töreye de ters düşen dosta selam vermem

Anadolu''nun kesişiminde yer alan kadim Mezopotamya
Zengin coğrafyanın
Kültürel mirasından doğdum
Yaşamı sevenlerdenim
Özgürlük neferiyim
Ne ordular durdurabilir beni,
Ne kanun
Ne yasalar!
Bir türkü tutturdum, yankısı Munzur’a yaslanır
Engel tanımayan bir nehir gibi
Özgürcesine.

Medeniyetin özgürlük çiçeği
Şimdi
Mardin’in gümüş tepsisinde
Bir akşamdır,
Siverek’in sıcağında
Kavrulur adımlar.
Ve Taşlıçay’ın rüzgârında
Savrulur
Hikâyen;

Sende, adı bilinmez, dumanı tütmez isimsiz mezarlar,
Üstünden uçuşan toz bulutu,
Annelerin gözlerinde dökülen
İnci tanesi yaş,
Beşikte sabaha uyanan ağlayan bebekler...
Yaralı göğsünde, kanat çırpan göçmen kuşları
Sarp kayalarında dağ keçileri, ürkek ceylanlar var,

Ve sessizliğin ininde saklanan bir tavşan, izini bırakır toprağına.
Bir vaşak süzülür ormanların alacakaranlığında,
Gizli ve asil.
Sarıkamış’ın ayazıyla kesişir yollar,
Yolgeçmez Vadisi’nde rüzgâr ulur,
Kağızman’ın eteklerinde,
Kötek Deresi
Coşkun ve hırçın akar karanlık tarihe inat.

Sen ki çölleri yeşerten yağmur kadar bereketli
Yüreğimin en gizli,
En mukaddes ezgisi.
Adını ansam rüzgâr susar, gece yatar,
Yollar aç bu gamlı ömre gelsin bahar.
Bir yanda yoksulluk var, diğer yanda da çok yakın özgürlük var,

Sorarım gidenlere, bu yollar kime mülk?
Gecenin sırtında bir yük,
Ayazda kalmış bir serçe,
Ama içimizde o inatçı, o asi türkü henüz dinmedi, bil ki...
Yoksulluğun orta yerinde
Açan bir zambaksın,
Biz ki dağların çocuklarıyız, yarası derin,
"Özgürlük nerede?" deme, o çok yakın.
Ve rüzgârın sesinde senin yerin!
Aynı rüzgâr esiyor,
Aynı acı duruyor,
Fakat yürek bu yükü hep umutla taşıyor.
Birlikte atar bu yürek, sökülür bu kara zincir,
Bir yudum su,
Bir nefes, o kutlu sabırla,
Ne zulüm kalır ne hasret, ne de bu ıssız gece,

Yazıldı yüreğime adın, en güzel dilden, en tatlı heceyle...
Süryani kadim diliyle okur,
Keldani bakraca şekil işler,
Dualarını derinden,
Mardin’in taş evleri ışıldar akşam serinliğinden.
Bir Kürt kızı oturmuş
Alçak kilim tezgâhına,
Elleri nasırlı
Ama sevda düşmüş nakışına.
Mekik gidip gelirken sedefli ellerinde,
Bir türkü mırıldanır nazlı ince dilinde
"MEZOPOTAMYA" diye
Düşer iplikler taşa,
Toprağın alın yazısı yazılır
Sanki baştan başa.
Bu kilim bir harita değil, bir halkın sesidir,
Kürt kızının parmaklarında zamanın nefesidir.

Mehmet Çobanoğlu 
17.11.2026
Gürpınar', 'Ey dillere destan, toprağın altında fısıldar bin yıllık dermanın. Adın yazıldı tarihe, asla silinmez bir hayal artık Bağrın o eski, o derin ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çobanoğlu']::text[], 8.5, '{"poet":"Mehmet Çobanoğlu","poet_slug":"mehmet-cobanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":147,"source_url":"https://www.antoloji.com/medeniyetin-besigi-mezopotamya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirin Altındaki İsim', 'siirin-altindaki-i-sim-nimet-oner-weo6j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şiir''in Altındaki İsim

Masanın üzerindeki lamba, Şirin’in defterine vuruyordu. 
Pencerenin alt köşesinde biriken su, ara sıra ahşap pervaza damlıyordu. Stalin bunu iki kez duydu. Üçüncüsünde Şair konuştu.

Gençliğinizde şiir yazdığınızı duydum. İlk şiiriniz çıktığında gazeteyi kime götürdünüz?

Stalin’in masaya vuran parmağı durdu.

Bunun ne önemi var?

İnsan bir şiiri basılınca önce birinin yüzünü görmek ister. Kimin yüzünü görmek istediğinizi merak ettim.

Stalin arkasına yaslandı. 
Şair defteri kendine doğru çekti. Lambanın ışığı, sayfanın altındaki ismine kadar indi.

Bu defterde sizi öfkelendirecek bir dize varsa söyleyin, yarın adımla yayımlayabilir miyim?

Okuyun, dedi Stalin.

Şair sayfaya baktı.

Gece babamı götürdüler.
Annem sabah sobayı yakarken
kapıda kalan bir tek ayakkabısını
her zamanki gibi ateşe doğru çevirdi.

Dışarıda bir araba geçti. 
Farları pencerenin suyunda bir an dağıldı.

Kimin babası? diye sordu Stalin.

Dizeleri yazdığım gün komşumuzun. Ertesi gün sokağın öbür ucundaki çocuğun.

Stalin elini uzattı. Şairin defterini masanın ortasına sürdü.
Sayfayı kendine çevirdi. 
Önce şiiri, sonra alttaki adı okudu.

Bu adla basılmasını gerçekten istiyor musunuz?

Şair hemen cevap veremedi. 
Evden çıkarken annesi, hava soğur diye atkısını boynuna iki kez dolamıştı. Şimdi ensesinde o düğümü hissediyordu.

İstiyorum, dedi. Korkuyorum da.

Koridordan ayak sesleri geldi. 
Kapının önünde yavaşlayıp uzaklaştı. Stalin defteri kapatacakmış gibi kapağı kaldırdı, sonra elini çekti.

Anneniz okudu mu?

Okudu. 
Ayakkabının hangisi olduğunu sordu. 
Sol tekiydi, dedim. 
Bir daha şiirden söz etmedi.

Stalin pencereye döndü. Pervazdan bir damla daha düştü.
İlk şiirimin çıktığı gazeteyi anneme götürdüm, dedi.

Şair bekledi. 
Stalin başka bir şey söylemedi. 
Defter aralarında açık duruyordu. 
Şair geri alırken başparmağı sayfanın altına, tam adının üstüne denk geldi. 
Bir an öyle kaldı. 
Sonra parmağını çekti.
İzin istedi ve gitti şair 

Azra Nimet Öner', 'Şiir''in Altındaki İsim Masanın üzerindeki lamba, Şirin’in defterine vuruyordu.  Pencerenin alt köşesinde biriken su, ara sıra ahşap pervaza ...', ARRAY['Türk Edebiyatı','Şiir','Nimet Öner']::text[], 8.5, '{"poet":"Nimet Öner","poet_slug":"nimet-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/siirin-altindaki-isim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin Devleti', 'sairin-devleti-nimet-oner-djvr4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şairin Devleti 

Bugün bir şair geçiyor içimden, Stalin''le buluşuyor.
Kızıl Meydan''ın üstüne ağır bir akşam çöküyor.
Kar sessiz.
Tarih gürültülü.
Bir masanın iki ucunda iki ayrı dünya oturuyor.
Birinin ellerinde şiir lekeleri.
Birinin ellerinde devletler.
Birinin cebinde yarım kalmış aşk mektupları.
Birinin cebinde ülke sınırları 
Şair çayını karıştırıyordu.
Stalin, piposunu kül tablasına bırakıp, Herzegovina Flor marka sigarasını içiyordu.
Gökyüzü ikisine de aynı uzaklıktan bakıyordu 
İkisi de yeryüzüne aynı mesafede duruyordu. 
Mutluluk nedir diye sordu şair.
Stalin cevap vermedi
Soruların ordusu olmaz der gibi.
Bazı sorular emir almaz.
Bazı sorular sınır tanımaz
Şair bir soru daha sordu 
Bir insanı yönetmek mi zor, bir insanı anlamak mı?
Kar biraz daha yağıyordu
Sessizlik biraz daha büyüyordu
Dünyanın bütün diktatörleri aynı anda susuyordu sanki.
İnsanı yönetmek mümkündür.
Korkutmak mümkündür.
Susturmak mümkündür.
Ağlatmak mümkündür 
Anlamak mümkün değil.
İşte o başka bir sanattır.
Şair masanın üzerine eğildi
Hiç âşık oldunuz mu? diye sordu
Stalin ilk kez gözlerini kaldırdı 
Bir anlığına haritalar düştü omuzlarından.
Makamlar.
Madalya sesleri.
Nutuklar.
Heykeller.
Bir anlığına sadece insan kaldı geriye.
Şair gördü,
Her gücün altında bir korku olduğunu.
Her öfkenin altında bir yara.
Her kibrin altında saklanmış bir eksiklik.
kibir yüksekten bakar.
Onur duyar.
Kibir konuşur.
Onur dinler.
Kibir buyurur.
Onur anlar.
Ve bir insanın onuru sağır olmuşsa
en yüksek kürsüde bile otursa
en yalnız insandır dünyada.
Gece ilerliyor.
Kar yağıyor.
Tarih not tutuyor.
Şair ayağa kalkıyor.
Paltosunu giyiyor.
Kapıya yöneliyor.
Tam çıkarken dönüp
Son kez bakıyor Stalin''e.
Bir ülke kaç yılda kurulur bilmiyorum 
Lakin,
Bir kalbin yıkılması tek cümle sürüyor diyor.
Sonra gidiyor şair 
Kar onun ayak izlerini örtüyor.
Stalin masada tek başına kalıyor.
Ve ilk kez anlıyor
Dünyanın bütün haritalarına sahip olmak,
bir insanın güvenini kazanmaktan daha kolaymış.
Bugün bir şair geçti içimden.
Stalin''le buluştu.
Tarihle konuştu.
İktidarla yüzleşti.
Sonra bir martı gibi
kalbimin kıyısına kondu.
Bana şunu bıraktı
Saygı sevginin hırkasıdır.
İhmal ve kibir bir sevginin fay hatlarıdır.
En büyük imparatorluk
bir insanın kalbinde yer bulamıyorsa
aslında yıkılmıştır.


Azra Nimet Öner', 'Şairin Devleti  Bugün bir şair geçiyor içimden, Stalin''le buluşuyor. Kızıl Meydan''ın üstüne ağır bir akşam çöküyor. Kar sessiz. Tarih gürült...', ARRAY['Türk Edebiyatı','Şiir','Nimet Öner']::text[], 8.5, '{"poet":"Nimet Öner","poet_slug":"nimet-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/sairin-devleti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Olan Yar -2', 'el-olan-yar-2-yunus-emre-kayabasi-6mat2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne tez el oldun ne tez el yar

Az biraz daha bekleyemez miydin

Ayrılığın acısı soğusaydı biraz

Ne tez el oldun ne tez el yar

Fark ettim ki gülemiyorum

Yarım kalmış ölemiyorum

Kapıyı çarpıpta gidemiyorum

Ne tez el oldun ne tez el yar

Boşunaymış o iç çekmelerim

Sitemi gururu bir kenara itmelerim

Sen gel dedin bende geldim

Ne tez el oldun ne tez el yar

El gibi ellerin el gibi şimdi bana

Görmüyor gözlerin bakmıyor bana

Lal olmuş o dilin konuşmuyor baksana

Ne tez el oldun ne tez el yar

Batsın gemiler vursun kıyıya

Sussun şiirler çöp kovasına

Vurulsun aşıklar mezarlıklara

Ne tez el oldun ne tez el yar', 'Ne tez el oldun ne tez el yar Az biraz daha bekleyemez miydin Ayrılığın acısı soğusaydı biraz Ne tez el oldun ne tez el yar Fark ettim ki gü...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre Kayabaşı']::text[], 8.5, '{"poet":"Yunus Emre Kayabaşı","poet_slug":"yunus-emre-kayabasi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/el-olan-yar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüyen Türkü', 'usuyen-turku-nimet-oner-ckufj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni dinlerken,
Kum Gibi''de dökülür insan,
Yorgun Demokratta susar,
Ağladıkça da içini yıkar,
Nereden Bileceksiniz de kalbini anlatırsın her dinleyenin 
Şafak Türküsünde güneş olursun yeniden dogarsin üzerimize 
Türküleri söyleyiş hâlin
sanki her kelime için bin ömür yaşamışsın.
Soylu sevdam, 
Bir şiir okurken bir türkü söylenirken,
Ahmet Kaya rüzgârı eser tüm ülkede.

Bir cümle, soğuk bir ava dönüştürür 
Bir cümle hara dönüştürür 
Şiirin içindeki o derinlik, o ağırlık, o susunca bile konuşan hâlin
Kelimelerin yaraların kadar gerçek,
duruşun acıların kadar dik,
hüzünlerin sevdan kadar ağır başlı.
Bir türküyü söylerken nasıl içine bin ömür sığdırıyorsan
Şiire de bin hayat ekliyorsun 
Bir bakıyorsun ki kelime, karşıdan bir dağ gibi
Bir bakıyorsun ki mısra, nefesini geri isteyecek kadar güçlü.
Ölüm yıldönümünde
çok kişi içinden sessiz bir türkü söyleyecek Ahmedim.
Benim içimden geçen türkü başka
Söylerken 
kendi yarama, kendi duruşuma, kendi isyanıma
bir selam veriyorum her defasında.

ÜŞÜYEN TÜRKÜ 

Bu gece içimde bir türkü üşüyor 
sesini kimse duymuyor sadece ben duyuyorum.
Karanlık bir sokak lambası gibi yanıyor acı,
biriken hüzün, sanki Ahmet’in sesiyle çoğalıyor.

Bir çay bardağının buğusunda silinen bir yüz gibi
hayat kendini yeniden yazıyor.
Gölgeler uzuyor duvarlarda,
bir adam sesleniyor uzaklardan 
Uçun kuşlar gidin, diyor,
bir annenin yüreğine konun.

O an anlıyorum 
bazı şarkılar ölmez,
bazı insanlar ölse de yaşar,
bazı acılar,
insanı diriltmek için canını yakar.

Sanki o gece
Gülten’in gözlerinden süzülen yaş
benim kirpiğime düştü 
Sanki o yabancı ülke zindanı
kalbimde bir yer açtı 
Sanki o şarkının içindeki yaralı çocuk
benim çocukluğumu çağırıyordu.

Sen,
sen bir mısranın içinde duruyorsun.
Türkülere benzeyen bir duruşla.
Suskunluğun şiir 
Konuşman gazel 
hüznün insanı iyileştiren bir isyan.

Bu gece yüreğimi,
İstanbul’un karanlığına çarpa çarpa
Seni dinliyorum.
Bir dağ gibi dik,
bir sitem gibi derin,
bir gurbet gibi yanık.

kendi kendime diyorum ki 
Ölümün susturamadığı sesler vardır.
İnsanın kalbine gömülür
Sonra büyür büyür büyür,
bir ömür bizi korur.

Senin için yaktım bu şiiri,
Ahmet''im
hem sana
hem de içimizde hâlâ usul usul yaşayan
o kederli türküye.

Bu şiir senindir
Senin sesinden doğdu, senin gecenden, senin nefesinden yazıldı.
Bir şiir, en çok hissedenin kalbinde yuva bulur.
Sen o dizelerin hem başlangıcı hem de varış noktasısin 
Sahibi sensin
Adı sensin
Ateşi sensin
Şair şiiri yazar, şiir kendini kimin kalbine emanet edeceğini kendi seçer.
Bu şiir seni seçti Ahmedim 
Al, mavi odana koy, ışığını hiç söndürme.

Azra Nimet Öner 

28 Ekim 1957’de Malatya’da doğdu, 16 Kasım 2000’de Paris’te vefat etti. Allah rahmet eylesin mekanı cennet olsun.', 'Seni dinlerken, Kum Gibi''de dökülür insan, Yorgun Demokratta susar, Ağladıkça da içini yıkar, Nereden Bileceksiniz de kalbini anlatırsın her...', ARRAY['Türk Edebiyatı','Şiir','Nimet Öner']::text[], 8.5, '{"poet":"Nimet Öner","poet_slug":"nimet-oner","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/usuyen-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '70de Olme Hissi', '70de-olme-hissi-aytug-paker-6t34i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yahu ben alismisim yalnizliga
Gelip de neden umut verdin ki sen bana
Hayir istemiyordum ki ben
Ne duzeni ne birini sevmeyi
Ne de birinin gozlerimin icine bakmasini
Yalnizligimda mutluydum ben
Oyle baktin ki ama dedim ulan
Dene lan nolabilir dedim ve gordum nolabilcegini
Ya benim okudugum roman bile tutunamayanlarken
Sen bana ask romanlarinin da oldugunu ogrettin
Madonnayi mesela ne guzel yazmis
sabahattin ali
Benim en sevdigim yazar 35lerinde olmusken
Neden gelip de bana 70de olme hissi uyandirdin durduk yere
Rezil kepaze olduk her zerresiyle
Romeo gibi hissettik zaman zaman
Cogu zaman
Hikayenin sonunda ikiside oluyordu
Bizim ki oyle olmadi adam oldu kadin yasamaya devam etti', 'Yahu ben alismisim yalnizliga Gelip de neden umut verdin ki sen bana Hayir istemiyordum ki ben Ne duzeni ne birini sevmeyi Ne de birinin goz...', ARRAY['Türk Edebiyatı','Şiir','Aytuğ Paker']::text[], 8.5, '{"poet":"Aytuğ Paker","poet_slug":"aytug-paker","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/70de-olme-hissi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalton Kardeşler', 'dalton-kardesler-ertugrul-bey-3uqyl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat akıyorken sular seller gibi

Dört yiğit vermiş omuz omuza kol kola

Birinin adı müslüm birinin adı ali 

Diğerinin adı memo ve birde muro kanka

Ablalar abiler çıkamıyor başa

Çok fena bu gençler cok fena

Her zaman ALLAH yar  olmuş ablalara

YOK ÖYLE PAPATYA VE EDA ABLA EDA

Baba mefhumunu yaşatır BASRİ Abi

Abidir abi BERKANT ve  KOSOVALI abi

Kankadan Daha çok daltonlar gibi

Reis Muro ayarsız memo müslüm baba ve ali

Koftiden değil gercekten severler

Müslüm şiir yazar memo şarkı söyler

Ali oyun oynar mura bağlama çalar 

Dillere destan canlar dillere bizim kankalar

Herkese koşmaya çalısir HÜSEYİN abi

ITALYAN KÜRDÜ hep  neşe kaynağı değilmi

Bir aslan kükredi müslüm baba miyav dedi

Aksada hayat bitmez bu sevgi bitmez ebedi

Baba ali hayķıriır vay vay vay yapma abla ya yapma yeter 

ayarsız memo gülerek yapar alaıyına atar gider

Fenerli muro reis ne yapsın ya sabır ya sabır der

Herşey onlar icin hersey iyiki var bizim kankalar', 'Hayat akıyorken sular seller gibi Dört yiğit vermiş omuz omuza kol kola Birinin adı müslüm birinin adı ali  Diğerinin adı memo ve birde muro...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Bey']::text[], 8.5, '{"poet":"Ertuğrul Bey","poet_slug":"ertugrul-bey","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kankalar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cocuklugum', 'cocuklugum-aytug-paker-fqe5k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yok be ya
Romantik iliskiler valla beni bulmaz sanirdim
Ta ki ilk tanismaya kadar
Bi goz temasi
Hafif bi tebessum
Atma iste zehirli oku
Inanirim demeye kalmadan
Inandim
Ask bu ya demedim belkide
Ama bu olsa ne guzel olur dedim
Meraklandim,heyecanlandim
Ellerim bile titredi
Ki ben sogukkanliyimdir
Cool da takilmam da cogu zaman
Senin yaninda her zaman cocuk gibiydim
Simdi sen gittin
Ben de olmedim zaten
Olen biri oldu ama
Yaninda cocuk gibi hisseden
Cocuklugum oldu', 'Yok be ya Romantik iliskiler valla beni bulmaz sanirdim Ta ki ilk tanismaya kadar Bi goz temasi Hafif bi tebessum Atma iste zehirli oku Inan...', ARRAY['Türk Edebiyatı','Şiir','Aytuğ Paker']::text[], 8.5, '{"poet":"Aytuğ Paker","poet_slug":"aytug-paker","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cocuklugum-459-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvar 32. Kilometre', 'duvar-32-kilometre-hulya-kirklaroglu-r68k2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'A4 büyüklüğünde çıktıyı heyecanla fotokopicinin ellerinden alırken bir gerçekle karşılaşmıştım. Bu kağıt illüzyon değildi. Parmaklarım hissedebiliyor ve gözlerim görüyordu üzerindeki yazılan şeyleri. 

Üniversite öğrencileri yanımdan gelip geçiyor. Fotokopi makinası peş peşe çıktıları basıyor. Çıktıları makineden alan çalışan kapağı ne renk olsun diyerek soruyor. Kimi siyah, kimi sarı ya da mavi diyordu. 

El çabukluğuyla çalışan, çıktıların yuvarlak tel girişini destelenmiş kitabın köşe altından takıyor, yuvarlaya yuvarlaya tüm sayfaları birleştiriyordu. Bir sanat atölyesi gibiydi bu dükkan çok severim ve içeri giren herkesin kitaplarını, duvarlarda duran tüm yazıları, hatta masa önü ve arkasındaki tüm şeyleri okumak istiyordum, istisnasız önüne geçilemez bir açlık yaşıyorum. 

Bu açlık kimi zaman ebeveynlerime öfke olarak yola çıkarken, öfkeyi boğazımda boğarak ama kızım bak ne erdemler öğretilmiş, bununla birlikte sevgi içinde ve varlıkla büyütüldün diyerek sol gözümden akan yaşa eşlik etmesin diyerek, kalbimi avutuyorum ki sağ gözümden de yaş akmasın.

Öylece duruyor orada işte Sevgili Günlüğüm✍🏻 istediğin zaman gözlerime bakabilir, görebilirsin de göz yaşı pınarında. 

Ne akabiliyor, ne de geri gidebiliyor…

Kasadaki yaşlı adam çıktı ve tekli fotokopileri el çabukluğuyla poşetlere yerleştiriyor, ardından para alıyor, verecekse üstünü veriyordu. Kimi öğrencilerde kartla ödüyordu. 

Kalbim yerinden çıkacak gibi çarpıyordu. Heyecan mutluluk neşe kendinden geçmiş bu üçlü yanında, endişe arzumu kamçılıyordu ama nasıl nasıl olacaktı? 

Ayak bileklerimden başlayarak, korku mu sarıyordu yüreğimi? 

Bu bir delilik miydi?

Hem de bu yaşta cık cık cık. 

Bu his farklıydı. Garip. Tarifi mümkün olmayan. 

İçini titreten bir duygu durumu.

Zihnim bedenimle aynı fikirde olmuyordu. Bu genelde hep böyle olmuştur zaten, ama bu sefer durum ciddiydi. Hep arada kalan benim, ama hep…

Efendim ? 

Hayır hayır kendime acımıyorum Sevgili Günlüğüm✍🏻

Bu ikisinin çatışması yanında kendime susamışlık sadece ve o susuzluktan seraplar görüyorum senin ve benim gibi tatlı şeyler; sahi biz gerçek miyiz? Gerçeksek eğer iyi ki varsın biriciğim, yokluğunu düşünmek bile istemem. Ne kadar yalnız olurdum elimi tutanlar olsa da şu koca dünyada…

1 tane şeffaf dosya lütfen diyerek ricada bulundum ve içine yerleştirdim fotokopiyi…

Elimdeydi, ücretini ödediğimde ise sahibi olacaktım ve kasada sıraya girdim. Alış veriş bittikten sonra merdivenlerden inerken soldaki renkli tükenmez kalemlere dokundum, pembenin tonu çok güzeldi evdeki bitince alayım diyerek, poşetin içindeki kıpırtıyı bastırmaya çalışıyordum.

Tüm azalarım kıpırtıya kapılmamak için farklı yönlere dikkatimi çekmeye çalışıyordu. 

Kapının önünde biraz ilerde sağda olan otobüs durağına, solda mıydı diyerek dikkatim poşetteki kıpırtıya inat,  dikkatimi kendi üzerine çekmeye çalışıyordu.

Duygu netti, vücut direnci isyana dönmüştü koca kocaman bir yenilmişlik içinde şaşkınlıktan kendini yerlerden yerlere atıyordu birer birer merdivenlerden inerken.

Fısıltılara bakılırsa azalardan biri abartısız merdivende intihar girişiminde bulundu. 

Durup onu seyrettim. 

Heee; yani burdan atsan kendini ne olur?

Hey Allahım Yarabbim ölecen mi? 

Beni mi öldürebileceksin?  Öff yürü hadi yürü diyerek elinden tuttum. Elleri buz kesilmişti. Elim yapıştı içim irkildi. Durum ciddi demek ki dedim, ama tavizsiz iniyordum merdivenlerden…

Bunlar çete çete Sevgili Günlüğüm✍🏻 bunlar konfor çetesi. 

Konfor alanına çekmekte üstlerine yok. Hatta, habire beni oram ağrıyor, buram ağrıyor diyerek doktora sürükleyende yine bu tatlış çeteleşmiş azalarım… 

Doktorlar istirahat etmeniz lazım derken… Zihnim he yavv he hee deyip söylenenlere pirim vermezken.

Çoğu zaman bu çete beni konfor alanına zihnimin perçeminden tutup sürükleye sürükleye götürdü. 

Doktorları benden daha dikkatli dinleyen yine bu azalar kendi aralarında söyleşi, muhabbet ne kutlamalar yaptılar anlatsam parmağını ısırırsın… 

Var yaaa geçmiş yıllarda altı ay spor yasaklanınca bunlar kürsü kurdu. Birbirine madalya törenleri, kupalar taktim ettiler konuşmacı olarakta ayak baldırlarımı kürsüye davet ettiler…

Sonra gelsin kimyasallar, elimde kumanda yabancı film belgeseller, göz yaşları…

Bir gün hastanedeydim yine kadının biri geldi barkod çıkaracak emar randevusu için. 

-Verilen saat çok erken ben o saatte gelemem dedi. -Niye dedi çalışan…

-Beş yıldır hastanelere gitmiyorum dedi. 

Kulaklarıma inanamıyordum. Kadına dönüp kırk bin kere maşallah. Beş yıldır hastanelere gelmediğinizi söylediniz- eveetttt dedi vurgulu bir şekilde… 

Bir şey dank etti. 

Bu çok çok iyi bir şey… 

Bu bana ilham olsun ve de hedefim…

Bende gitmiycem hastanelere dedim o an Thriodit ultrasonumdan sonra… O gün, bu çetenin maskesi yerle bir oldu… Bunların toplanmaları ertelendi. Ben madalyalar aldıkça bunların madalya törenleri sonlandı… 

Tüm bu yaşananlara rağmen bu seferki farklıydı.

Fotokopiyi onlarda görmüştü hatta kayıt olurken dudak yamultanıda vardı. Fotokopiyi elime alınca birbirlerini çimdikleyip uyandırdılar. İş ciddileşti fısıltılarıyla ayak sürümeleri ile beni kendi saflarına çekmeye çabaladılar ve de karşı atağa geçince ben

sürüm sürüm olmak ne demek o an yaşıyordum. Aynı anda öyle büyük bir aşkta beraberinde vardıki sürünmekle, hayata sıkı sıkı hatta sımsıkı tutunmayı aynı anda yaşamakta insana has bir beceriymiş.

Vücut tepkilerim her biri birbirinden kaçarcasına zihnimi düşman edinmişlik yolunda ellerinden geleni yapıyorlardı.

En çokta ayaklarım başıma kakar oldu bu kağıtta yazılı olan şeyleri… Bi ara bana bunu da mı yapacaktın diyerek yüzüme tükürdü… Tükürüğü silip, Yarabbi Şükür dedim.

Başına gelecekleri biliyordu. Ne yalan söyleyeyim en çokta zihnimi, ayaklarım için endişelenirken yakaladım.

Dükkan ardımızda kalırken, 

Bulgurlu yönüne giden otobüsler birbiri ardına geçiyordu önümden, fakat o da ne? Sanki mumyalanmış gibiydim.

Mısırlılardan ışın hızıyla öğrenilmiş öğreti ile mumyalanmış dimdik ayakta duran bendim… Fakat filmlerde olduğu gibi tabut içinde değildim. 

Otobüse bindim elimde poşet poşette Everestim vardı…

Yol boyunca tüm azalarım birleşerek el birliğiyle 

başımı gökyüzüne kaldırıyordu. Durumu kabullenmek onlar içinde kaçınılmaz bir durumdu. İşlerini de biliyorlardı. Akıllı, hatta zeki varlıklar içinde varlıklar sonuçta. 

 Peş peşe içimi çektirdiler. 

Otobüs git gide kalabalıklaşmış olsada duygularım hayata karışmış olduğundan dolayı, sakinleşmişti. 

 Gelmiştik ineceğim durağa. Fırından bir ekmek aldım eve doğru hafif eğimli yolu inerek düşüncelerden arınmak için terliyordum. 

Dışardayken her şey iyi has ta, evde yalnızdım. 

Evde duygularım, azalarımla baş başa bunlara nasıl bir yol gösterebilirim ki?

Üstelik göstersem de kendimi tanıdığımı düşünüyorum ama sadece düşünüyorum. Tanıyor muyum henüz bunun bilgisi bende değil, sen de Sevgili Günlüğüm✍🏻 

İşte bembeyaz bina karşımda ne kadar güzel yapılmış diyerek uzaktan seyrettim zerafetini. 

Bu binayı ilk gördüğüm anla hâlâ aynı sevgi dolu bakışlar içindeydim. 

Asansör düğmesi ve incecik bip sesi o an işler karıştı. Endişe ve neşe içinde asansöre bindim dans ediyordum. 

Bir beden bin bir türlü tiyatroculuk aynı bedende. 

Bu dans beş kat boyunca sürdü.

Kamera varmış asansörde bana neee diyerek dönüyordum yarım asra inat.

Ayaklarım neşe içindeydi. Sanırım sahiplerinden her ikiside şimdilik razıydı. Sonra omuzlarım devreye girdi biri iniyor biri kalkıyordu. Zarifti asansördeki dans. Ellerim tomurcuk açıyor gibi bir bir açıyordu parmaklarımı. 

Yüzümde neşe, ağzım kulaklarımda aynaya bir önümü dönüyor, bir arkamı dönüyordum.

Dıdıtt, geldik beşinci kata. İnerkende oynuyor muşum omuzlarım öyle dedi. Hatta anahtarı çantadan çıkarırken sağa sola yarım hilal şeklinde dönüyormuşum da sarı yeleğimin uzun yanları duvarlara da bi parça mutluluk taşımış. Ahh duvarların dili olsa da konuşsa 

Sevgili Günlüğüm✍🏻 senin gibi…

Elimi yüzümü yıkayıp, kağıdı poşetten çıkardım. 

Vizon rengi koltukta kağıda bakıyor göğsüme basıyor alıp tekrar kanepeye bırakıyor sonra tekrar göğsüme kalbimin atışını ona da duyurdum, kıpırdadı gibime geldi.

Ah kağıtların dili olsa da konuşsa senin gibi 

Sevgili Günlüğüm✍🏻

Müzik açtım yüksekçe sesle dans ediyordum kağıdın karşısında. 

Sonra davet ettim kırmadı beni partnerim olmayı kabul etti… Kim böylesi dokunabilirdi ki ellerime, kim?

Kim beni böyle mutlu edebilirdi ki; kim?

Ne bu kadar kalbimi hallaç pamuğuna çevirebilirdi ki? 

Dansımız sonrası. Şeffaf bant aradım çekmecedeydi. Doğruuu yatak odama hımmm nereye asalım seni? 

Başucu yok olmaz. 

Ayak ucu amaaa yüksekçe olsun gözümü açtığım an seni görebileyim sevgili hedefim diyerek bantı açtım. 

Üç yanından şeffaf bantla düzgün bantlamıştım, 

dördüncü kenarı düzgün tutamadım sanırım parmak ucumda yapışkanlı bantlarla kırışık oldu. Düzelteyim dedim bantı çekerken o da neeee? 

Duvarın boyası kalktı. Gözlerime inanamıştım önce, boyalarıda bozmuşlar a gülüm diyerek âna gerisin geri döndüm. 

Düzenli yapıştırıp iki koca adım geri giderek bakıyordum üzerindeki yazıya Sevgili Günlüğüm✍🏻

Merhaba HÜLYA KIRKLAROĞLU

TÜRKİYE İŞ BANKASI 48. İSTANBUL MARATONU 42 K kategorisine kaydınız başarıyla kaydoldunuz.

Kaydınız onaylanmıştır.

1. Bölüm', 'A4 büyüklüğünde çıktıyı heyecanla fotokopicinin ellerinden alırken bir gerçekle karşılaşmıştım. Bu kağıt illüzyon değildi. Parmaklarım hisse...', ARRAY['Türk Edebiyatı','Şiir','Hülya Kırklaroğlu']::text[], 8.5, '{"poet":"Hülya Kırklaroğlu","poet_slug":"hulya-kirklaroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/duvar-32-kilometre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gaybettim Anamı Ona Yanarım', 'gaybettim-anami-ona-yanarim-senol-sener-sxbk7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bahar ağzıydı, yetmiş yılında 

Gaybettim anamı, ona yanarım

Aksaray gazası, Niğde ilinde 

Gaybettim anamı, ona yanarım

Tarla çapasında, sancısı başlar 

Issız arazide, bitmez telaşlar

Şu iki gözümde, sel olur yaşlar

Gaybettim anamı, ona yanarım

Beni doğururken, can verir anam

Söyleyin bu derde, nasıl dayanam

Ciğerlerim sızlar, her gün her ahşam

Gaybettim anamı, ona yanarım

Sen gittin adımı, yetim goydular

Beni oğsüz çocuhlardan saydılar

Feryadımı uzahlardan duydular

Gaybettim anamı, ona yanarım

Birgün bile yüzün, görmedim anam

Yüzümü yüzüne, sürmedim anam

El gibi murada, ermedim anam

Gaybettim anamı, ona yanarım

Anlatdım halimi, Sözeri yazdı

Dertlerimi tek tek satıra dizdi

Anam mezarını, içime gazdı 

Gaybettim anamı, ona yanarım', 'Bir bahar ağzıydı, yetmiş yılında  Gaybettim anamı, ona yanarım Aksaray gazası, Niğde ilinde  Gaybettim anamı, ona yanarım Tarla çapasında, ...', ARRAY['Türk Edebiyatı','Şiir','Şenol Şener']::text[], 8.5, '{"poet":"Şenol Şener","poet_slug":"senol-sener","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gaybettim-anami-ona-yanarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Kabuğu Evin Sustuğu an', 'deniz-kabugu-evin-sustugu-an-ali-firat-dicle-b74gi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'DENİZ KABUĞU EVİN SUSTUĞU AN

Sabah oldu yine.

Ne olmuş yani?

Güneş dediğin de her gün doğuyor zaten,

Biraz da ayıp ediyor insana.

Kapının önünde yoksun.

Asansör duruyor,

Kapı açılıyor,

İnsanlar geliyor gidiyor.

Bir tek sen gelmiyorsun be Leo.

Eskiden ne güzel telaşımız vardı.

Ben eve gelirdim,

Sen dünyayı kurtarmış gibi karşılardın beni.

Bir kedi ne bilir ki sevinci derdim,

Meğer sevincin kendisiymişsin.

Şimdi ev dediğin dört duvar,

Bir de içinde dolaşan koca bir yokluk.

Mama kabın orada,

Su tasın orada,

Balkondaki kumun bile senden haberi var.

Ama sen yoksun.

Hay ben bu yokluğun...

Musluğu açıyorum bazen,

Belki sesini duyarsın diye değil,

Belki ben senin sesini duymayı unutmam diye.

Eskiden su kabın doluyken

Musluğun başına dikilirdin.

Patilerin fayanslarda,

Gözlerin damlayan suda...

Bir de benim bardağım vardı,

Hani şu gizli gizli içtiğin.

Şimdi bardağımda su eksilmiyor Leo.

İnsan kendi suyuna bile küsebiliyormuş.

Bir de forman asılı duruyor.

Fenerbahçe''nin sarı laciverti,

Arasında kalmış birkaç tüyün.

Bakıyorum da,

Bizim takımın en güzel oyuncusu sendin.

Ne transfer istedin,

Ne prim,

Ne de şampiyonluk.

Bir avuç mama,

Biraz su,

Bir de sevilmek.

Hepsi bu.

Ah be oğlum,

İnsan ne çok şeyi sonradan anlıyor.

Kapıdan her girişinde eğilip başını okşamak,

Bir akşam daha birlikte uyumak,

Seni musluğun başından kovalamak...

Meğer hayat dediğin

Büyük şeylerden değil,

Bir daha tekrarlanmayacak küçük şeylerden ibaretmiş.

Bir ihmalin gölgesi var içimde.

Dönüp dönüp aynı yere geliyorum.

Keşke diyorum,

Keşke o gün başka türlü olsaydı.

Keşke zaman dediğin

Biraz olsun insanın hatırını saysaydı.

Ama zamanın vicdanı yok Leo,

Ne geri dönüyor,

Ne de özür diliyor.

Yatağını toplamadım.

Battaniyendeki çukur duruyor.

Sanki birazdan gelip

Dünyanın bütün yorgunluğunu üzerinden atacak,

Bir güzel gerinecek,

Sonra da hiçbir şey olmamış gibi uyuyacaksın.

Oysa bir şey oldu.

Hem de çok şey oldu.

Sen gittin,

Ev sustu.

Ben kaldım,

İçimde bir deniz kabuğu büyüdü.

Ne zaman kulağıma dayasam

Senin mırıltından başka bir şey duymuyorum.

Bilirsin Leo,

Ben öyle göğe bakıp yıldız sayanlardan değildim.

Şimdi geceleri gökyüzüne bakıyorum.

Bir yerdeysen eğer,

Çok uzaklarda üşüme.

Burada senin yerin hâlâ sıcak.

Kapı hâlâ senin kapın,

Ev hâlâ senin evin.

Biliyor musun,

İnsan bazen bir kediyi kaybetmiyor yalnızca.

Eve dönmek için bir sebebini,

Sabah uyanmak için küçük bir telaşını,

Dünyaya karşı bütün savunmalarını kaybediyor.

Sen bana hiç büyük laflar etmedin.

Zaten gerek de yoktu.

Başını avucuma koyman yetiyordu.

Bir canlının insana güvenmesi

Ne büyük bir şeymiş meğer.

Ben seni koruyamadım diye

Kendimi hâlâ affedemiyorum.

Ama şunu bil.

Bu evde senden sonra

Hiçbir şey eskisi gibi olmayacak.

Bir bardak su,

Bir kapı sesi,

Bir avuç tüy,

Bir de akşamüstü güneşi...

Hepsi biraz sen olacak.

Uyu şimdi güzel oğlum.

Ben burada idare ederim.

Gerçi sensiz idare etmek de

Lafın gelişi işte...

Bir Leo yaşadı bu evde.

Küçücük patileriyle

Kocaman bir adamın yüreğine bastı.

Sonra gitti.

Şimdi o yürek,

Her attığında biraz sana çarpıyor.

16.11.2026 – Saat 17.21

(Leo''nun anısına)', 'DENİZ KABUĞU EVİN SUSTUĞU AN Sabah oldu yine. Ne olmuş yani? Güneş dediğin de her gün doğuyor zaten, Biraz da ayıp ediyor insana. Kapının ön...', ARRAY['Türk Edebiyatı','Şiir','Ali Fırat Dicle']::text[], 8.5, '{"poet":"Ali Fırat Dicle","poet_slug":"ali-firat-dicle","theme":"Türk Şiiri","is_hero":false,"total_lines":116,"source_url":"https://www.antoloji.com/deniz-kabugu-evin-sustugu-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman İçinde Zaman (sone)', 'zaman-i-cinde-zaman-sone-mehmet-hezari-uf80s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uykusuz gecelerde karanlığı dinlerim

Nidâları devirir sükutun kasırgası

Ayağıma vurulmuş yalnızlık prangası

Ayazda ısınırken ateşte serinlerim

Tersine akar durur zaman içinde zaman

Parçası eksik hayat, tamamlanmaz bir yapboz

Soğuk bir alev sanki su üstünde yakamoz

Elimde kalan tek şey doğru sandığım yalan

Suların aynasında yosun tutmuş umutlar

Rüzgarın kanadında uzaklaşır bulutlar

İçimdeki dehlizde ne ses var ne de ışık

Dibi görünmez girdap ufuklarda gördüğüm

Mazim kül renkli duman, akıbetim kördüğüm

Hayal ile hakikat birbirine dolaşık', 'Uykusuz gecelerde karanlığı dinlerim Nidâları devirir sükutun kasırgası Ayağıma vurulmuş yalnızlık prangası Ayazda ısınırken ateşte serinler...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Hezari']::text[], 8.5, '{"poet":"Mehmet Hezari","poet_slug":"mehmet-hezari","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zaman-icinde-zaman-sone-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tünel', 'tunel-zaman-melankoli-55b2l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Herk edilmiş tarlanın ekine kavuşması yıldan sonra

Terk edilmişliğin vuslata ermesi nice sonra

Budanmış ağaçların bol meyveye varması yıldan sonra

Yıkılmışlığın virandan kurtulması nice sonra

Sonbahar yağmurlarında tohum atılması hemen sonra

Kırılmışlığın içten onarılması nice sonra

Bahçede çapa derdine düşülmesi kıştan hemen sonra

Yokluğun benden ayrılması kim bilir nice sonra', 'Herk edilmiş tarlanın ekine kavuşması yıldan sonra Terk edilmişliğin vuslata ermesi nice sonra Budanmış ağaçların bol meyveye varması yıldan...', ARRAY['Türk Edebiyatı','Şiir','Zaman Melankoli']::text[], 8.5, '{"poet":"Zaman Melankoli","poet_slug":"zaman-melankoli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tunel-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öfke', 'ofke-mehmet-mujde-zunes', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ey sevgili öfke.

Kör edip gözlerimi,

Ana, baba, dost, akraba

kimseyi tanımazsın.

Bozarak dillerimi,

Gün görmemiş sözlerle,

Sen bana yakışmazsın.

Yıllar geçer, ömür geçer

Sevenler bile ayrılır.

Sadakati sarsılmaz

Herkes gider o kalır.

Çekilmez yarenliği

Dostluğu çok acıtır.

Kulağıma kan kırmızı

Kelimeler akıtır.

Başıma hep bela açar

İstenmeyen sevgili

Ama olmasa eğer

Savunmaz kimse beni

Hem haksızlık, yolsuzluk

Hem saygısızlık düşmanı

Yine de çok istemem

Davetsiz uğramanı

Bu ara hiç gitmiyor

Sırtıma döşek serer

Ey sevgili öfke

Beni en çok o sever.', 'Ey sevgili öfke. Kör edip gözlerimi, Ana, baba, dost, akraba kimseyi tanımazsın. Bozarak dillerimi, Gün görmemiş sözlerle, Sen bana yakışmaz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Mujde']::text[], 8.5, '{"poet":"Mehmet Mujde","poet_slug":"mehmet-mujde","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ofke-192-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sis çökmüş bizim köye', 'sis-cokmus-bizim-koye-yasin-yuksel-2-rptzd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İdris Dağı’ndan Güneş Doğarken...

İdris dağı’ndan bir şafak söküyor

dereşıha sisli bir sabah çöküyor

yürekler umutla baharı bekliyor

yüreklere ag gelin türkü düşüyor

dağın yücesinden nurlar süzülür

her seher vaktinde güller büzülür

ayazın bağrında hasret çözülür

gün döner yollar sevdayla gülüşür

yeşildereli gül meşreptir gönlü ganidir

kalender libası aşkın nişanıdır

cemalinin dilinde hakk’ın divanıdır

yâran arkadaş gönül ehli aşkla gelir

bak idris dağı kara kışa uyanmış

her dal ucunda bir çiçek uyuşmuş

karların altından zemzemler taşmış

sevdayla dirilir ak gün dağ taş toprak

ey nazlı yurdum gül yüzün hep gülsün

her hanen bereket her gönlün nûr dolsun

pınarların çağlasın bağların şen olsun

yarına sevgiyle yetişsin her canın günün

bir sisli bakışta görki nice bahar saklı

bir sıcak tebessüm gönülleri kucaklar

sevdanın türküsü dillerde yankılanır

bu devran aşkın mayasıyla çağlar

Elmalıdağ üstünde alâ turnalar döner

idris’in bağrında menekşeler göz kırpar

gün olur sevda yeli eser hasretler diner

güzellik üstüne gel gör ki nice kapılar açılır

sisler çekilince güneş doğar düze köye

bir avaz yükselir selamla dağdan ovaya

gönül gönle değer sevdalık düşer yola

türkü olur bizim bu köyün sisli özlemi..', 'İdris Dağı’ndan Güneş Doğarken... İdris dağı’ndan bir şafak söküyor dereşıha sisli bir sabah çöküyor yürekler umutla baharı bekliyor yürekle...', ARRAY['Türk Edebiyatı','Şiir','Yasin Yüksel 2']::text[], 8.5, '{"poet":"Yasin Yüksel 2","poet_slug":"yasin-yuksel-2","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sis-cokmus-bizim-koye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykuda Da Sever İnsan', 'uykuda-da-sever-i-nsan-sa-lih-ywnqg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uykuda da sever insan...
Sever, hem de daha çok sever.
Gözler kapanır, düşünceler açılır;
Onu son gördüğün gün gelir aklına.
Ne güzel gülüyor gözleri,
Ne güzel bakıyor sana.
Ama bilmediğin bir şey var: Son.
Son olduğunu bilmiyorsun tabii.
Kapılıyorsun bir hayale, son olmaması dileğiyle...
Gözün hiç açılmasın istiyorsun, düşüncesi hep aklında kalsın.
Korkma, göz açılınca da uyuyor insan.
Dünyanın en buruk uykusu... Neden mi?
Göz açıldıktan sonra derin bir rüyaya dalacaksın;
Yapay bir dünya, yapay bir çevre...
İşte bu yüzden uykuda da sever insan.', 'Uykuda da sever insan... Sever, hem de daha çok sever. Gözler kapanır, düşünceler açılır; Onu son gördüğün gün gelir aklına. Ne güzel gülüyo...', ARRAY['Türk Edebiyatı','Şiir','Sa Lih']::text[], 8.5, '{"poet":"Sa Lih","poet_slug":"sa-lih","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uykuda-da-sever-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda ve Bana Ettikleri', 'sevda-ve-bana-ettikleri-fikret-adimol-qpvgw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kara kışın ortasında,

Bunca yokluk arasında,

Vuruldum on altısında,

Şu sevdanın ettiğine bak.

Şu sevdanın ettiğine bak.

Anadan, babadan geçtim,

Çöllere, sellere düştüm,

Ne güzellere kör baktım,

Şu sevdanın ettiğine bak.

Şu sevdanın ettiğine bak.

Dağ ardından hasret göründü,

Gözlerim yaşlara büründü,

Yalnızın bir derdi varken,

Sevdalı kaça bölündü.

Şu sevdanın ettiğine bak.

Şu sevdanın ettiğine bak.

Mecnun’u, Kerem’i, Aslı’sı,

Acısı, sancısı, cabası,

Yok mudur bunun ortası,

Şu sevdanın ettiğine bak.

Şu sevdanın ettiğine bak.

Adımol der; kendini koru,

Sevda dediğin kurumuş koru,

Bir yandı mı sönmez koru,

Şu sevdanın ettiğine bak.

Şu sevdanın ettiğine bak.

Dağ ardından hasret göründü,

Gözlerim yaşlara büründü,

Yalnızın bir derdi varken,

Sevdalı kaça bölündü.

Şu sevdanın ettiğine bak.

Şu sevdanın ettiğine bak.', 'Kara kışın ortasında, Bunca yokluk arasında, Vuruldum on altısında, Şu sevdanın ettiğine bak. Şu sevdanın ettiğine bak. Anadan, babadan geçt...', ARRAY['Türk Edebiyatı','Şiir','Fikret Adımol']::text[], 8.5, '{"poet":"Fikret Adımol","poet_slug":"fikret-adimol","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sevda-ve-bana-ettikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Can Bir Ok', 'uc-can-bir-ok-mucahit-kurnaz-hwr6i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hangi fırtına koparabilir bu derin kökü?

Altaylar''dan Hazar''a yürüyen bu koca yükü?

Biz ki Yesevî''nin elindeki o sönmez çıra

Hacı Bektaş''ın dilindeki o kutsal çağrı

Ahmet-i Hanî''nin kaleminden damlayan sızıyla

Yıkarız karanlığı bu ülkenin Ay Yıldız nuruyla

Uyan ey devran, uyan yeşil yosun yatağında

Adın silinse de fırtınanın hoyrat bağında

Bir ananın duasında bir pirin nefesinde

Yaşarsın Turan''ın o gürbüz hür sesinde

Artık ne dalgadan korkar ne fırtınadan korkarız 

Biz üç can bir yürek; tarihe yön veren bir ok''uz!

Karanlık sularda karanlık unutuş yok artık

Şafak söktü ufkumuzda her yanımız aydınlık Birleştikçe çoğalan o ulu deryayız biz

Tarihin yazdığı en kadim en şanlı sayfayız biz!

Uyan ey devran uyan yeşil yosun yatağında

Adın silinse de fırtınanın hoyrat bağrında

Bir ananın duasında bir pirin nefesinde

Yaşarsın Turan''ın o gürbüz hür sesinde

Artık ne dalgadan korkar ne fırtınadan korkarız

Ey gafil! kardeşlikten öte kan bağımı ararsınız

Selçuklu, Osmanlı, Cumhuriyetle üç düğümle akrabayız

 Biz üç can bir yürek; tarihe yön veren bir ok''uz!', 'Hangi fırtına koparabilir bu derin kökü? Altaylar''dan Hazar''a yürüyen bu koca yükü? Biz ki Yesevî''nin elindeki o sönmez çıra Hacı Bektaş''ın ...', ARRAY['Türk Edebiyatı','Şiir','Mücahit Kurnaz']::text[], 8.5, '{"poet":"Mücahit Kurnaz","poet_slug":"mucahit-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/uc-can-bir-ok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ormanın türküsü', 'ormanin-turkusu-mahmut-kasapoglu-di9zx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dalına konarak bülbüller öter,

Meyvesiyle nice gönüller güler.

Yaprağı her daim umutlar eker,

Rahmeti uzanır her bir ağacın.

Çölleşen diyara olur can suyu,

Serinletir yazın ovayı, köyü.

Sessizce öğretir sabrı, doğruyu,

Hikmeti dillenir her bir ağacın.

Baltayı vuranlar düşünsün biraz,

Kesilen her gövde yarına ayaz.

Bir fidan dikmekten kaçınmak olmaz,

Sevabı büyüktür her bir ağacın.

Kökü topraktadır, başı semada,

Sessiz ibadeti her dem duada.

Bıraktığı izler kalır dünyada,

Vefası tükenmez her bir ağacın.

Bir fidan dikene rahmet erişir,

Adıyla birlikte hayır yetişir.

Dünya bir emanet, ömür de geçer,

Sadakası akar her bir ağacın.', 'Dalına konarak bülbüller öter, Meyvesiyle nice gönüller güler. Yaprağı her daim umutlar eker, Rahmeti uzanır her bir ağacın. Çölleşen diyara...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ormanin-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Geç Kaldım', 'cok-gec-kaldim-nihat-malkoc-3gov9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hüzünleri dağıtmaya,

Çok geç kaldım, çok geç kaldım

Yüreğimi sağaltmaya

Çok geç kaldım, çok geç kaldım

Kırık kalbi onarmaya,

Kim olduğumu sormaya,

Hak divanına varmaya,

Çok geç kaldım, çok geç kaldım

Öz benliğimi bilmeye,

Senden kendime gelmeye,

Ağız dolusu gülmeye,

Çok geç kaldım, çok geç kaldım

Kör nefsimden çark etmeye,

Hakikati fark etmeye,

Kaygıları terk etmeye

Çok geç kaldım, çok geç kaldım

Kendim için yaşamaya,

Dertlerimi boşamaya,

Yüreğimi ışımaya,

Çok geç kaldım, çok geç kaldım

Evvelimi ahir ettim

Mutluluğu tehir ettim

Günlerimi zehir ettim

Çok geç kaldım, çok geç kaldım

Mahkûm kaldım yâd ellere,

Bağban olmadım güllere,

Giremedim gönüllere,

Çok geç kaldım, çok geç kaldım

Gençlik elden uçtu, yazık!

Başımızda taçtı, yazık!

Ne yaralar açtı, yazık!

Çok geç kaldım, çok geç kaldım

Gençliğime doyamadım

Hakikati duyamadım 

Yâr dizinde uyumadım

Çok geç kaldım, çok geç kaldım

Baharımı güz eyledim

Derdim birdi, yüz eyledim

Ötelere göz eyledim

Çok geç kaldım, çok geç kaldım

17 Kasım 2026/Trabzon', 'Hüzünleri dağıtmaya, Çok geç kaldım, çok geç kaldım Yüreğimi sağaltmaya Çok geç kaldım, çok geç kaldım Kırık kalbi onarmaya, Kim olduğumu so...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/cok-gec-kaldim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslata çevir', 'vuslata-cevir-mahmut-kasapoglu-s9uec', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmurlar altında büyüyen sevdam,

Kırılmış kalbimi bahara çevir.

Üşüyen geceme doğan sabahım,

Sessiz duaları sehere çevir.

Gözlerin değince susuyor zaman,

Adını taşırım içimde her an.

Ayrılık dediğin yorgun bir yalan,

Kaderi yeniden esere çevir.

Sen benim içimde tüten ocağım,

Dünya yıkılsa da sensin durağım.

Çöle dönen ömrüm, kuruyan bağım,

Bir damla sevdayla pınara çevir.

Bilirim sevdanın yolu uzundur,

Sabredenin sonu elbet huzurdur.

Yaralı yüreğim sana tutkundur,

Sızlayan her yeri merheme çevir.

Ellerin değerse kalır mı kışlar?

Adını söylerken susar mı kuşlar?

Hasretin bağrıma bastığı taşlar,

Merhamet suyuyla yollara çevir.

Bir gün kader bizi mutlaka bulur,

Kırılan gönüller yine onulur.

Sevda Hakk''a varsa ebedî kalır,

Bugünü, yarını sen nura çevir.

Son nefes gelince kapanır perde,

Ne unvan kalacak ne saray yerde.

Bir tek sevgi geçer sonsuz seferde,

Kalbimin yönünü Mevlâ''ya çevir.

Eğer bir duaysan âmin olayım,

Eğer bir özlemsen seni bulayım.

Adını sevdayla dile alayım;

Bütün ayrılığı vuslata çevir.', 'Yağmurlar altında büyüyen sevdam, Kırılmış kalbimi bahara çevir. Üşüyen geceme doğan sabahım, Sessiz duaları sehere çevir. Gözlerin değince ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/vuslata-cevir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Gamzesi', 'gonul-gamzesi-muharrem-cihan-akcesme-br5d8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayat geldim dedirmezken,

Kalbim gidiyorum dedirmiyor.

En temiz duygular ve bakışın

Takılı kursağımda,

Ne kadar yazsam da

En derini söze dönüşmüyor.

Seslenişin yüreğime değdi,

Değdi de,

Öyle sevdim ben seni.

Yazdığım her şiir,

Senin gelişlerinin

Ve gülüşlerinin gönül gamzesi.

Gördüğüm yerlerde değilsin belki ama..

Sevdiğim her şeyde buldum ben seni.

Kimse bilmese bile,

Bu kalbin şâhidi var.

O''nun sesini sende duydum ben,

Ondan sevdim ben seni.

Kokusunu uzaktan alıp da

Çiçeğiyle kavuşmak isteyen arı gibi,

Üveys gibi sevdim ben seni.

Çünkü kimse bilmez,

Şu kalpte derin damlalarla

Suladığım sarı gülü

Kim bilir,

Belki bir gün bir gonca açar da

Yaprağına Mavi bir kelebek konar.

Kim bilir?...', 'Hayat geldim dedirmezken, Kalbim gidiyorum dedirmiyor. En temiz duygular ve bakışın Takılı kursağımda, Ne kadar yazsam da En derini söze dön...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Cihan Akçeşme']::text[], 8.5, '{"poet":"Muharrem Cihan Akçeşme","poet_slug":"muharrem-cihan-akcesme","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gonul-gamzesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnmiş Bir Nida', 'i-nmis-bir-nida-kasim-kobakci-jdye8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecenin ucundan inmiş bir nida,

Ruhları okşayan gök nefesidir.

Uykuya dalarken şu yorgun seda,

O tebliğ elinin nur elçisidir.

*

Ötelerden gelen o serin rüzgar,

Yorgun yüreklere umut taşıyan.

Sessiz uykularda nurlu bir bahar,

Geceyi aydınlık güne bağlayan.

*

Doğruluk uyuyan bir bebek gibi,

Onların dilinde hep şefkat olur.

Emanet saklanır bir çiçek gibi,

Gecenin bağrında selamet bulur.

*

Emri iletirler hiç incitmeden,

Uyuyan ruhlara yollar çizerek.

Geceyi bölerler iz belirtmeden,

Dertleri silerler umut vererek.

*

İlahi şefkatle gözetilirler,

Uykudan masumdur onların özü.

Hatadan uzakta temizlenirler,

Gülümseyen nurla doludur yüzü.

*

Onlar gelmeseydi sır bilinmezdi,

Geceler boyunca uyuyamazdık.

Karanlık ormanda yaş silinmezdi,

Aşkın şefkatine hiç doyamazdık.', 'Gecenin ucundan inmiş bir nida, Ruhları okşayan gök nefesidir. Uykuya dalarken şu yorgun seda, O tebliğ elinin nur elçisidir. * Ötelerden ge...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/inmis-bir-nida-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hz. Ali', 'hz-ali-hasan-yilmaz-3-wvmml', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kâbe’de dünyaya açtı gözünü,

Resûl’ün nuruyla, buldu özünü.

Küçükten öğrendi Hak sözünü,

Çocukken îmana erdi Ali’miz.

Hz. Muhammed bildi kemâli.

Dedi ki "İlimin kapısıdır Ali",

Hikmet deryâsı, her bir kelamı,

Gönüllere ilham verdi Ali’miz.

Eşi Fatıma cennetinin çiçeği,

Hasan ve Hüseyin canın dileği.

Ehl-i Beyt’in nurlu temel direği,

Sevgiyle yuvayı kurdu Ali’miz.

Dünya malına dönüp bakmadı,

Haram lokmayı asla  tatmadı.

Kuru arpayı bile ziyafet saydı

Şükür ile takvâya vardı Ali’miz.

Savaş meydanında titretti dağı,

Fırtına gibi esti geçti yiğitlik çağı.

Gönlü oldu her garibanın otağı,

Şefkatle yarayı sardı Ali’miz.

"Bana bir harf öğretenin"

"Kırk yıl kölesiyim" dedi Ali

İlim de onun için değerli idi

Cehâlet tozunu sildi Ali’miz.

Adâlet yolunda kılı kırk yardı.

Kardeşi Akîl’e ateşi sordu.

Milletin malını hep korudu,

Hakkı hukuku gördü Ali’miz.

Kûfe mihrâbında sabah vaktinde,

Zehirli bir hançer parladı sırtında.

Şehit olarak gitti o nurlu yoluna,

Bir gül gibi kuruyup soldu Ali’miz.

Şâh-ı Merdân derler arifler ona,

İlmi ile örnek oldu her câna.

İsmi nakşoldu bütün cihâna,

Gönül tahtımıza oturdu Ali’miz.

2026', 'Kâbe’de dünyaya açtı gözünü, Resûl’ün nuruyla, buldu özünü. Küçükten öğrendi Hak sözünü, Çocukken îmana erdi Ali’miz. Hz. Muhammed bildi kem...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yılmaz 3']::text[], 8.5, '{"poet":"Hasan Yılmaz 3","poet_slug":"hasan-yilmaz-3","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/hz-ali-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taze Çayın Öğlen Vakti', 'taze-cayin-oglen-vakti-alper-tunga-3-gbkth', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Merhaba gözleriyle konuşan o büyülü sevda,

Kalbinden yazıyorum ve en gizli yerinden.

Biraz öğlen çayı niyetinde geldim.

Biliyor musun, bazen kalbim yerinden çıkacak gibi,

Ben hiç sakin olmayı öğrenemedim, seni görünce

Seni görünce bütün şarkılar kulağımda

Eski, yeni ne varsa hepsi, hatta ilk taş plaklar...

Esengül belki, belki bütün sanat müzikleri

Belki nihavend, biraz hüzzam, biraz hicazkar

Şimdi taze çay içerken anlatmalı,

Bu günlerde, senin zihnimdeki haline çok hayranım.

Beni o kadar sevip, koruyor, kolluyor gibisin ki

İnan bana hissediyorum, şevkatinin ellerini

Elimi sımsıkı ısıtan ruhunu hissediyorum.

Birde, çok sevimli bir halin var..

O sevindiğin turuncun ve çocuksu gülüşün.

Ben, böyle sevinçlerini diliyorum hep,

Hep o halde dünyamda yaşanıyor varlığın.

Ben, seni hep o tasvir gibi sevindirmek...

Yani; ben seni güldürmeyi daha çok seviyorum.

Sana öğlen vaktinden taze çay diliyorum.', 'Merhaba gözleriyle konuşan o büyülü sevda, Kalbinden yazıyorum ve en gizli yerinden. Biraz öğlen çayı niyetinde geldim. Biliyor musun, bazen...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga 3']::text[], 8.5, '{"poet":"Alper Tunga 3","poet_slug":"alper-tunga-3","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/taze-cayin-oglen-vakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hz. Ömer', 'hz-omer-hasan-yilmaz-3-yxzaw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mekke’nin sert taşı, heybetli dağı,

Gölgesi bile titretir, karanlık çağı.

Çözüldü kalbinden, cehâlet bağı,

Hakîkat nuruyla, yandı Ömer’im.

Kılıcın çekmişti, öldürmek için,

İşitti Kur’anı kerimi, oldu mümin.

Buz gibi eridi, kalbindeki kin.

İslamın nuruna daldı Ömer’im.

Adâlet mülkünün, sarsılmaz taşı,

Mazlumun sığınağı, yetimin aşı.

Zâlimin gözünden, akıttı yaşı,

Mîzânı elinde, tuttu Ömer’im.

Ne zaman bir mazlumun kalbi yanar

Yüce Rabb hesabını benden sorar.

Diye hep titrerdi içi geceleri yanar,

Hesâbı nefsine, sordu Ömer’im.

Yamalı hırkası, tek varıydı onun,

Sarayı yok idi, koca sultânın.

Mescit direğiydi, yastığı cânın,

Tevâzu mülküne, erdi Ömer’im.

Mescid-i Nebevîde sabah namazında,

Hançerle kurban oldu adalet yolunda.

Defnedildi bedenı Hücre-i sadede.

Resulun izinde toprağa, girdi Ömer’im.

Bilinmeli ki Ömer, adâlet demek,

Onun yolundadır, en kutlu emek.

Gönüllere tahtı, kurdu o melek,

Sevgisi kalplere, doldu Ömer’im.

2026', 'Mekke’nin sert taşı, heybetli dağı, Gölgesi bile titretir, karanlık çağı. Çözüldü kalbinden, cehâlet bağı, Hakîkat nuruyla, yandı Ömer’im. K...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yılmaz 3']::text[], 8.5, '{"poet":"Hasan Yılmaz 3","poet_slug":"hasan-yilmaz-3","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hz-omer-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cuma günü', 'cuma-gunu-hasan-yilmaz-3-kjr5j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönüllere bir rahmet iner,

Bugün günlerden Cuma''dır.

Her kul bugün ibadet eder

Bugün günlerden Cuma''dır.

Bugün Hakk kapısı açılır.

Dillerden dualara saçılır.

Sadaka muhtaca dağıtılır.

Bugün günlerden Cuma''dır.

Müminlerin bayramıdır,

Gönüllerin seyranıdır,

Toplumun ilahi bağıdır

Bugün günlerden Cuma''dır.

Melekler iner semadan,

Nur yağar yüce Mevla''dan,

Uzak kalma bu rahmetten,

Bugün günlerden Cuma''dır.

Abdest alıp yola düşelim.

Cami kapısına koşalım.

Rabb’ın aşkıyla dolalım.

Bugün günlerden Cuma''dır.

Saf tutalım omuz omuza,

Şükredelim bu halimize,

Rabb’ın adı dilimizde,

Bugün günlerden Cuma''dır.

Hutbe okunur minberden.

İbret alalım her kelamdan.

Sıyrılalım tüm kederlerden.

Bugün günlerden Cuma''dır.

Salavat şakır bütün diller.

Birlikte atar bugün kalpler.

Fakiri, zengini aynı safdadır.

Bugün günlerden Cuma''dır.

2026', 'Gönüllere bir rahmet iner, Bugün günlerden Cuma''dır. Her kul bugün ibadet eder Bugün günlerden Cuma''dır. Bugün Hakk kapısı açılır. Dillerden...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yılmaz 3']::text[], 8.5, '{"poet":"Hasan Yılmaz 3","poet_slug":"hasan-yilmaz-3","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/cuma-gunu-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '4 Halife', '4-halife-hasan-yilmaz-3-nbaks', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Resul göçtü gitti, ebedi mekana,

Gönüller büründü, derin hüzüne.

İş kaldı emanetine sahip çıkmaya.

Yürüyecek birisi, onun nurlu izine.

İlk halîfe oldu, Hz. Ebu Bekir,

Sadâkat işinde, iyi bir rehber.

Sevr’in yoldaşıdır, o koca server,

Malını cânını, feda etti dînine.

Fitne ateşini, söndürdü hemen,

Kur’ân’ı toplattı, gitmeden serden.

Doğruluk timsâli, o nûrlu beden,

Teslimiyet vardı, her bir emrinde.

Ardından Hz. Ömer’e, geçti hilâfet,

Güneş oldu topluma, dağıttı adalet.

Hakkı bâtıldan ayırdı hep o hikmet,

Korkusu darbe vurdu zulmün dizine

Yabanda bir kuzuyu kurt kapar,

Sahibi hesabını Ömer’den sorar.

Yamalı bir hırkayla, cihânı sarar,

Tevâzu yakıştı, onun can özüne.

Üçüncü olarak, Hz. Osman geldi,

Kur’anı kitap haline getiren alimdi

Hayâ timsaliydi, melekler ona eğildi,

Cömertlik yakıştı, güzel yüzüne.

Kur’ân’ı çoğalttı, yaydı cihâna,

Sükûnet getirdi, her bir insana.

Şehîd oldu gitti, yüce Rahmân’a,

Kanı damladı o, Mushaf üstüne.

Dördüncü halîfe, Hz. Ali yar.

Hem bir alimdi hem de serdar.

Zülfikârı ile küffara korku salar,

Yiğitlik yazılıydı, onun sözüne.

Fâtıma’nın ananın yâri idi,

Hasan, Hüseyinin babası

Son anı oldu Kûfe mihrâbı.

Kavuştu o dâhi, dostun yüzüne.

Gelin dostlar, bu dört canı analım.

Ehl-i Beyt ile hep birlik olalım.

Resûl’ün yolunda, doğru kalalım,

Şefâat umarız, mahşer gününe.

2026', 'Resul göçtü gitti, ebedi mekana, Gönüller büründü, derin hüzüne. İş kaldı emanetine sahip çıkmaya. Yürüyecek birisi, onun nurlu izine. İlk h...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yılmaz 3']::text[], 8.5, '{"poet":"Hasan Yılmaz 3","poet_slug":"hasan-yilmaz-3","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/4-halife-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler Ocağı', 'dusler-ocagi-kasim-kobakci-cp5q4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin sessizliğine ben usulca dalacağım,

Gözlerimi kapatıp da rüyalarda kalacağım,

Yıldızların ninnisiyle uykuları alacağım,

Bu huzurlu karanlığı borçlarıma sayacağım.

*

Göz kapaklarım yavaşça kapanırken yorgunluktan,

Nefesim usulca akar içimdeki sonsuzluktan,

Sıyrılırım tüm dünyadan ruhumdaki durgunluktan,

Borçlarıma sayacağım bulduğumu mutluluktan.

*

Yavaş yavaş eriyorken gecenin kör rüyasında,

Kaybolurum hiç bilmeden yıldızların dünyasında,

Yüzüyorum sessizliğin en karanlık deryasında,

Borçlarıma sayacağım gölgelerin sevdasında.

*

Usul usul yatıyorum şu uykunun kucağına,

Gömülüyorum huzurun o sımsıcak yatağına,

Gülümseme konuyorken hayallerin dudağına,

Borçlarıma sayacağım dalıp düşler ocağına.', 'Gecenin sessizliğine ben usulca dalacağım, Gözlerimi kapatıp da rüyalarda kalacağım, Yıldızların ninnisiyle uykuları alacağım, Bu huzurlu ka...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dusler-ocagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlık', 'i-nsanlik-hasan-yilmaz-3-x761t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözümde yok fani dünya

İstemem şöhreti şanı

Rabb ihsan etmiş bu cana

İnsan, İnsanlığın büyük ünvanı

Şan şöhret kibir dağıdır.

Mal Mülk hep ayak bağıdır

İnsana verilen bir saraydır

Gönül insanlığın kutlu hanı

Surete bakıp aldanma

Kendini bir şey sanma

Topraktır aslın unutma

Tevazu insanlığın ilacıdır

Ne sultan kalır ne de taç,

Herkes bir nefese muhtaç,

Sevgidir her derde ilaç.

Sevgi insanlığın harcıdır

Bir can gider, bir can gelir.

Dünya bir yol üstü handır,

Dileğim iyilikle anılmaktır,

İyilik insanlığın mayasıdır

Bil ki hırs azgın bir attır,

Zaptedebilmek bir murattır

Sabır en büyük sanattır.

Sabır insanlığın temel taşıdır.

Kalbi olan muhtaca el uzatır

Azrail ansızın gelip canı alır

Geriye sadece iyi amel kalır

Cömertlik insanlığın elidir

Hakk''ı bilirim, haddimi aşmam.

Boş heves peşinde koşmam,

İnsanım ben, özümden şaşmam.

Tevazu insanlığın Miracıdır

2026', 'Gözümde yok fani dünya İstemem şöhreti şanı Rabb ihsan etmiş bu cana İnsan, İnsanlığın büyük ünvanı Şan şöhret kibir dağıdır. Mal Mülk hep a...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yılmaz 3']::text[], 8.5, '{"poet":"Hasan Yılmaz 3","poet_slug":"hasan-yilmaz-3","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/insanlik-302-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın Ötesinde', 'zamanin-otesinde-sa-lih-f5tge', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar geçti, bugün geçmedi

Bugünde geçti, sen geçmedin

Geceler geçti, saatler geçmedi

Bu gecede geçti, sen geçmedi bu kalpten

Duran zamanda yıllar gitmiş

Salise dahi sen gitmedin

Zaman aktı, herkes geçti

Serden geçti, senden geçemedi', 'Yıllar geçti, bugün geçmedi Bugünde geçti, sen geçmedin Geceler geçti, saatler geçmedi Bu gecede geçti, sen geçmedi bu kalpten Duran zamanda...', ARRAY['Türk Edebiyatı','Şiir','Sa Lih']::text[], 8.5, '{"poet":"Sa Lih","poet_slug":"sa-lih","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zamanin-otesinde-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Mazgal', 'sessiz-mazgal-kasim-kobakci-d33gd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yollarda bekleyen o sessiz mazgal,

Gecenin kalbinde karanlık kuyu.

Düşen yapraklarla örtülmüş masal,

Sokaklardan akar çamurun suyu.

*

Sokakta dinliyor bitmez feryadı,

Unutmuş insanlar çoktan o adı,

Demir parmaklıktan almış inadı,

Asla değişmiyor o sessiz huyu.

*

Rüzgar fısıldarken eski şarkıyı,

Unutmuş insanlar derin kıyıyı,

Sarmış yavaş yavaş gizli sızıyı,

Ninniler söyler, der sen artık uyu.

*

Yağmurlar yağarken coşup da taşar,

Kendi boşluğunda sırlarla yaşar,

Bazen sular ile bentleri aşar,

Bilinmez aslında nedir hiç soyu.

*

Bir çocuk takılıp, düşse bilyesi,

Duyulur derinden yankı, çilesi,

Demir çubukların bitmez hilesi,

Yıllar geçip uzar yolların boyu.

*

Şehrin gürültüsü üstünden geçer,

O kirli suları usulca içer,

Gelenler gidenler yönünü seçer,

Soğuk demirlerde kaybolmuş duyu.

*

Yalnız sokakta lambalar hep yanar,

Mazgalın üstüne çiğ düşer, donar,

Kediler orayı yuvası sanar,

Dağıtır gecede ağır uykuyu.

*

Baharlar gelince çamur kurur da,

Tozlanan yüzüne rüzgar vurur da,

Altında böcekler nöbet durur da,

Göstermez kimseye saklı kuytuyu.

*

Rüzgarla savrulan kuru yapraklar,

Aradan süzülen çamur topraklar,

Karanlık yüzünü örten duvaklar,

Gizliyor dibindeki pis tortuyu.

*

Gözünü yummadan bekler durmadan,

Kimseyi yormadan, tuzak kurmadan,

Saatler ilerler, zaman vurmadan,

Yok eder kalbindeki kör korkuyu.', 'Yollarda bekleyen o sessiz mazgal, Gecenin kalbinde karanlık kuyu. Düşen yapraklarla örtülmüş masal, Sokaklardan akar çamurun suyu. * Sokakt...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/sessiz-mazgal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgür İrade', 'ozgur-i-rade-alp-kaan-aksu-rlszv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Varsa sende özgür irade,
Sırf bu yüzden et rabbine tevbe.', 'Varsa sende özgür irade, Sırf bu yüzden et rabbine tevbe....', ARRAY['Türk Edebiyatı','Şiir','Alp Kaan Aksu']::text[], 8.5, '{"poet":"Alp Kaan Aksu","poet_slug":"alp-kaan-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ozgur-irade-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlatlar', 'evlatlar-mahmut-kasapoglu-3lfav', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceler koynumda yıldız büyütür,

Adınızı nefes gönle öğretir.

Sizsiz her mevsimim ömrü tüketir,

Bu hasret içimi biçer evlatlar...

Takvime düşmeyen günleri saydım,

Rüzgâra ses verdim, dağlara yaydım.

Sizden gelen müjdeyle nefes aldım,

Bekleyiş sabrımı ölçer evlatlar...

Bir baba yüreği susmayı bilir,

Gözyaşı içine akar, gizlenir.

Dağ gibi görünür, sessizce erir,

Kim bu yangınımı seçer evlatlar?

Yolların taşını duayla ördüm,

Her secde sonunda sizleri gördüm.

Rabb''ime emanet deyip gönderdim,

Rahmet izinizden geçer evlatlar...

Ne servet dilerim ne yüce bir şan,

Yeter ki helalden şaşmasın insan.

Vicdan pusulanız, doğruluk iman,

Kötülük yolundan kaçar evlatlar...

Gurbet dedikleri uzun imtihan,

Sabreden gönüller bulur bir derman.

Kış ne kadar sürse biter bir zaman,

Bahar yola güller saçar evlatlar...

Bir gün dönersiniz yüzünüz gülüp,

Kapılar açılır, ocaklar tütüp.

Hasretin zinciri kırılıp düşüp,

Yıllarım yeniden uçar evlatlar...

Ömür bir nehirse siz en duru su,

Yüreğimde saklı dua kokusu.

Gönlümün sizinle diner korkusu,

İmanım umuda göçer evlatlar...

Sizde devam eder ömrüm aslında,

Sizsiniz yarının temiz bağında.

Bir çınar gölgesi kalır ardında,

Ektiğim sevgiler açar evlatlar...

Elbet bu ayrılık hatıra olur,

Hüzünler çekilir, gönül durulur.

Bu ömür evlatlarla kemal bulur,

Ruhum vuslat suyu içer evlatlar...', 'Geceler koynumda yıldız büyütür, Adınızı nefes gönle öğretir. Sizsiz her mevsimim ömrü tüketir, Bu hasret içimi biçer evlatlar... Takvime dü...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/evlatlar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğe düşen iz', 'yurege-dusen-iz-mahmut-kasapoglu-vc7oq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aldanma dünyanın süslü yüzüne,

Bir gün toprak dolar sürme gözüne.

Güvenme fâninin tatlı sözüne,

Mevsimler sararıp dönüp geçmekte...

Gözünü kapatma mazlum ahına,

Bir damla yaş yeter Hak dergâhına.

Kul hakkı dokunur ömrün bağına,

Hesaplar sessizce gelip çatmakta...

Okşa bir yetimin küçük başını,

Aç kalan komşunla böl sen aşını.

Kimsesiz kalanın sil gözyaşını,

Dualar göklere erip geçmekte...

Ömür bir ırmaktır denize akar,

Ne kibir kalıcı ne boş iftihar.

İz bırak, gönüller seni hep anar,

Güzel ad çağları delip geçmekte...', 'Aldanma dünyanın süslü yüzüne, Bir gün toprak dolar sürme gözüne. Güvenme fâninin tatlı sözüne, Mevsimler sararıp dönüp geçmekte... Gözünü k...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yurege-dusen-iz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dem 3', 'dem-3-haci-gurbuz-ldecb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'DEM  ³

Aşk şarabını içmeyenler

onun sarhoşluğunu nereden bilsin…

Bir bakışla değişen dünyayı,

bir sesle titreyen yüreği

nasıl anlasın…

💗

Sevda dediğin bazen

insanı göğe çıkarır,

bazen de bir çift gözde

kaybettirir kendini.

💗

Aşkın ateşine düşmeyenler

gecelerin neden uykusuz geçtiğini,

bir ismin neden durmadan

kalpte yankılandığını bilemez.

💗

Çünkü aşk,

akıldan çok yüreğe dokunur;

içene hayat verir bazen,

bazen de

tatlı bir sarhoşluk gibi

alıp götürür insanı

H.G.17.07.2014', 'DEM  ³ Aşk şarabını içmeyenler onun sarhoşluğunu nereden bilsin… Bir bakışla değişen dünyayı, bir sesle titreyen yüreği nasıl anlasın… 💗 Se...', ARRAY['Türk Edebiyatı','Şiir','Hacı Gürbüz']::text[], 8.5, '{"poet":"Hacı Gürbüz","poet_slug":"haci-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dem-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazgıya düşen gölge', 'yazgiya-dusen-golge-mahmut-kasapoglu-vb8o8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sustuğun her sözün yankısı kaldı,

Gecenin koynuna bir keder saldı.

Zaman ince ince ömrünü çaldı,

Yıldızlara dalıp kalırsın hani...

Eski bir mektubun sararmış izi,

Anlatır sessizce bitmeyen sızı.

Alnına kaderin yazdığı yazı,

Okurken içine ağlarsın hani...

Gül sandığın dallar dikenle biter,

Her sıcak tebessüm bir günde yiter.

İnsan en çok kendi içinde tüter,

Külleri savurup solarsın hani...

Denizler çekilir, kıyı ses keser,

Yorgun martılar da göklere küser.

Gidenin ardından bir boşluk eser,

Sessiz limanlara varırsın hani...

Aynada çizgiler, gözlerde hüzün,

Ne dün eski dündür ne bugün bugün.

Bir avuç hatırayla geçer ömrün,

Kendini zamana salarsın hani...

Takdirin elinde ince bir düğüm,

Çözdükçe açılır yeni bir bölüm.

Hayat dedikleri uzun bir ölüm,

Her sabah yeniden doğarsın hani...

Dağların ardında tükenir yollar,

Yorulur beklemek, yorulur yıllar.

İçinde yeşerir gizli baharlar,

Sonbaharı bile sararsın hani...

Ne tahtın kalıcı ne altın tacın,

Bir avuç topraktır sonu muhtacın.

Dünya dediğin bir gölge ağacın,

Gölgesine kanıp dalarsın hani...

Gönlünde büyüyen sevda çiçeği,

Kurutur bazen de ömrün gerçeği.

Bir damla merhamet, bir dost emeği,

Bulamayınca daralırsın hani...

Gurbet bir çeşmedir, buz gibi tası,

Her yudumda saklı sılanın yası.

Kapanmaz gönlünde hasret yarası,

Bir türkü duyunca yanarsın hani...

Ananın duası yolunda fener,

Bin rüzgâr esse de bir an mı söner?

Ne kadar gitsen de yol ona döner,

Her seherde onu anarsın hani...

Bir gölge düşünce yazgı yüzüne,

Perde iner gibi gönül gözüne.

Dönüp bakmak gerek insan özüne,

Aynaya, kendine sorarsın hani...

Ömür bir yolculuk, dünya bir durak,

Yükünü Rabb''ine emanet bırak.

O''ndan habersizce düşmez bir yaprak,

Tevekkülle huzur bulursun hani...

Sonunda anlarsın vakit geçince,

İnsan insan olur gönül seçince.

Sevgiyle yoğrulan bütün ömrünce,

Affedip sen de gül açarsın hani...', 'Sustuğun her sözün yankısı kaldı, Gecenin koynuna bir keder saldı. Zaman ince ince ömrünü çaldı, Yıldızlara dalıp kalırsın hani... Eski bir ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/yazgiya-dusen-golge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Zaman ( Zıtlıklar Dünyası )', 'bu-zaman-zitliklar-dunyasi-faruk-tosun-4ln5t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kendini tanımayan bilmeyen gafiller

Bütün dünyaya kendi, her anı bildiriyor 

Bir elinde telefon diğerinde sosyal medya

Umurumda değil benim için dünya

İnsanların yaptığı şeytanı utandırıyor

Karanlıklar üzerine karanlık doğuyor 

Teknoloji canavarı her yeri boğuyor

Bütün bir dünya bir kutuya sığıyor

Aynı evde bütün aile efradı oturuyor

Herkes kutusunda bir dünyada yaşıyor

Anne, baba ve çocukları dertleşmiyor

Dünyanın diğer ucuna dert anlatıyor 

Zaman onun başında eridikçe eriyor

Faydalı kullanmayanlar ahmaklaşıyor

Komşusuna üzülmeyen insanlar 

Dünyanın öbür ucundakine yanıyor

Zıtlıklar dünyasında ölçüler karışıyor 

Okulda birbiriyle arkadaş olamayanlar 

Sosyal dünyada kankaları çoğalıyor 

Tanımadığı insanlar birbirini alkışlıyor

Çirkinler olmuş, dünya güzeli

Yaşlılar olmuş, dünyanın gençleri

İşsizler olmuş, zenginlerin zengini

Her dakikasını paylaşan bir zırdeli

Yemek yemeyenler zannedersin gürme 

Konuşamayanlar dönmüş bir bülbüle

Aynı şeyleri birine göre üreten gölge

Sevdiklerini pazarlayan pişmiş kelle

En özel aile ilişkileri meydanda olanlar

Çocukları olmuş birbirine figüranlar

Şimdiden iki yüzlülük dersi almaktalar

Aile değil film setindeki figüranlar

Neyin ne olduğu belli olmuyor

Kimin neye baktığı anlaşılmıyor

En iyi yanıltan bol beğeni topluyor

İki yüzlüler dünyası münafıklaştırıyor

Sabah akşam ne kadar görülmüşüm

Aynı anda ne kadar izlenmişim

Biraz takipçi nasıl toplayabilirim 

Para ile satın alınan bir sürü takipçim

Bu dünyadan daha sahte dünya

İkiyüzlülerin ürettikleri bir dünya

Her an her yerde olunan bir dünya

Bu dünyayı doğru kullanan müstesna', 'Kendini tanımayan bilmeyen gafiller Bütün dünyaya kendi, her anı bildiriyor  Bir elinde telefon diğerinde sosyal medya Umurumda değil benim ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tosun']::text[], 8.5, '{"poet":"Faruk Tosun","poet_slug":"faruk-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bu-zaman-zitliklar-dunyasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
