INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Sevgi', 'cok-sevgi-kazim-karagoz-vyw0q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Samimiyet arttıkça saygı azalır bil ki,

Çok sevgi nankör eder, hatta kaybolur belki!', 'Samimiyet arttıkça saygı azalır bil ki, Çok sevgi nankör eder, hatta kaybolur belki!...', ARRAY['Türk Edebiyatı','Şiir','Kazım Karagöz']::text[], 8.5, '{"poet":"Kazım Karagöz","poet_slug":"kazim-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/cok-sevgi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Bakan Görüyormu?', 'her-bakan-goruyormu-eminnur-acar-2-5iz3p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlamak için bakarsan görürsün

Her bakan görür mü sandın!

Amelenin, ünlü müteahhit olduğunu

Yurt dışında görev yapan aydınların

Ülkeye döndüklerinde, 

Halkın cehaletinden yararlananların

Villalar köşkler konaklar, aldıklarını

Daha da çok kazanmak için

Halkın cahil kalmasını istediklerini

Hurafelerle, uyuşturulduğunu

Çok paranın, helal kazançtan olmadığını

Haram paranın bedellerinin, ağır olduğunu gördüm

Hırsızlığın, zinanın para ile kapatıldığını

Belaların cehaletten, geldiğini

Helal kazancın, huzurunu bereketini gördüm

Anlamak bilmek için bakarsan 

Daha neler görürsün

Hele de gönül gözün açıksa

Sonsuzluğa yelken açarsın

Niyetlere göredir akıbet

Ne demişler

Çok laf yalansız, çok mal haramsız olmaz

Görmek bilmek anlamak için bakmalı evrene

 Siyahı beyazı, Afrikalısı, Amerikalısı

Yaşlısı genci demeden, güzelinde çirkininde

Hepsi aynı Allahlın kullarıdır

İlle ALLAH başka bir şey yok

           Görüyorum dediğin hayallerindir', 'Anlamak için bakarsan görürsün Her bakan görür mü sandın! Amelenin, ünlü müteahhit olduğunu Yurt dışında görev yapan aydınların Ülkeye döndü...', ARRAY['Türk Edebiyatı','Şiir','Eminnur Acar 2']::text[], 8.5, '{"poet":"Eminnur Acar 2","poet_slug":"eminnur-acar-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/her-bakan-goruyormu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
