INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki bahar', 'i-cimdeki-bahar-mahmut-kasapoglu-8pgfy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gecelerin külünden doğrulur sabahlar,

Rahmet ile yıkanır çorak kalan günahlar.

Her tomurcuk içinde sabra döner tüm ahlar,

Toprağın duasıdır filizlenen çınarlar.

Gözlerinden süzülen şefkat olur ırmaklar,

Yetim kalan düşlere kanat örer yapraklar.

Merhameti öğrenir dikenlerle topraklar,

Gülün sessiz zikrini dinler yorgun rüzgârlar.

Sessizliği dokurken örümceğin ağları,

Vakit taşa kazıyor unutulmuş çağları.

Kırık kalbin içinde saklı cennet bağları,

Aşk, yaraya değince açar sonsuz pınarlar.

Bir serçenin duası yükselirken göklere,

Yıldızlar secde eder isimsiz dileklere.

Kelebeğin ömrüyle varılmaz ötelere,

Hak için bırakılan izlerdir yâdigârlar.

Uzun kış gecesinde gönül üfler közünü,

Sabır sarar yavaşça yorgunluğun yüzünü.

Akan her gözyaşıyla insan bulur özünü,

Bir tebessümle erir yürekte kalan karlar.

Affın serin suyunda unuturum sitemi,

Dost eli silip geçer yüreğimden elemi.

Bir zerrede görürüm koskoca bir âlemi,

Tek bir sevgi sözüyle çöker kat kat duvarlar.

Her damla fısıldıyor Yaradan''ın adını,

Bülbül zikre açıyor seherde kanadını.

Arı bilir çiçekte gizlenen bal tadını,

Kâinat bir kitaptır, satır satır esrarlar.

Seccademi gönlüme şafak vakti sererim,

Rahmetinden bir nasip, Rabb''im, bunu dilerim.

Mum misali yanarak aşkın ile eririm,

İçimde çiçeklenir kışa dönen diyarlar.

Nehirler denizlere kavuşurken usulca,

İnsan kendi içine döner bazen mahzunca.

Ölen umut yeşerir yağmur kapı çalınca,

Rabb''in avucundadır ömür denen baharlar.', 'Gecelerin külünden doğrulur sabahlar, Rahmet ile yıkanır çorak kalan günahlar. Her tomurcuk içinde sabra döner tüm ahlar, Toprağın duasıdır ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/icimdeki-bahar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedikodudan Uzak', 'dedikodudan-uzak-kazim-karagoz-ollyr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dedikodu yapandan uzak durun gelin ki,

Sizin de dedikodunuzu yapar bilin ki.', 'Dedikodu yapandan uzak durun gelin ki, Sizin de dedikodunuzu yapar bilin ki....', ARRAY['Türk Edebiyatı','Şiir','Kazım Karagöz']::text[], 8.5, '{"poet":"Kazım Karagöz","poet_slug":"kazim-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/dedikodudan-uzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Makbul-ü Kabulüm', 'makbul-u-kabulum-saliha-ravza-olgun-uniyp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yâr, kaçırma gözlerini benden.

Odaklan göz bebeğime.

Bak nasıl pırıl pırıl açıyor,seni görünce.

Heyecanlıyım ben de...

​

Dizecektim art arda kelimeler.

Dilim tutuluyor heybetinde.

Siliniyor aktaracağım beyitler.

Dur öylece bakayım sana derince.

Konuşma tek bir hece.

​

Bakışın takılıyor nefesime.

Çekiyorum gönlüme.

Şenlik yeri oluyor göğüs kafesimde.

Seyreyle ki sevdiğini süzülsün kırlara.

Biliyorum oradayım gönül bağında.

​

Yemyeşil her yer, sarkıyor sevgiden salkımlar.

Gerdanını döndürsen benden yana.

Esintiyle kokun karışsın canıma.

Gülümsemen yankılanır bakışlarımda.

Bahar mevsimi yayılır organlarıma.

​

Yâr, kalkma yerinden.

Kaybolma gözümün önünden.

Korku salık vermesin bedenime.

Durma konuş benimle!

Uykuyu ertele.

Hâlimiz damlasın deftere.

Çocuk gibiyim sen yanımda olunca.

İçim kıpır kıpır ,zıplayıp duruyorum

O yana bu yana...

Bağım kopuyor meşgalelerimle,

Sen önümde belirince...

Doku bana yüreğinin sesini, ince ince...

​

Dinleniyor bütün yorgunluklar gölgende.

Buharlaşıyor marazlar, illetler harında.

Gözyaşları köşe bucak kaçıyor karşında.

Şifa yayılıyor katı elemlere, 

Deva giriyor tenhaneme...

​

Mescitten akan duasın secdede.

Ulaşacak gök kubbeye.

İnecek sahili selamete;

Makbulü kabulün,Kerem ve Ekrem ile...

​

Sessiz Şahit.', 'Yâr, kaçırma gözlerini benden. Odaklan göz bebeğime. Bak nasıl pırıl pırıl açıyor,seni görünce. Heyecanlıyım ben de... ​ Dizecektim art arda...', ARRAY['Türk Edebiyatı','Şiir','Saliha Ravza Olgun']::text[], 8.5, '{"poet":"Saliha Ravza Olgun","poet_slug":"saliha-ravza-olgun","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/sen-yanimda-olunca-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kül ve kelebek', 'kul-ve-kelebek-mahmut-kasapoglu-oqwjf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tohumlar düş görmüş suskun dallara,

Toprak sır saklamış gece boyunca.

Yıldızlar eğilmiş kör aynalara,

Ay, kendi yüzünü arar olunca.

Kırılmış zamanı dikmiş iğneler,

Sessizliğe ağıt örmüş düğmeler.

İsimsiz yavruyu bekler anneler,

Rahimler dua olup çağırınca.

Gölgeler su içmiş taş pınarlardan,

Yangınlar gül devşirmiş mezarlardan.

Kader ince ince örer ağlardan,

Kul kendi bahtını çözemez bunca.

Kelebek unutur tırtıl hâlini,

Rüzgâr saklar ömrün ilk suâlini.

Her ayrılık doğurur visâlini,

Sabır çile ile filiz atınca.

Ne diken gül olur ne kül menekşe,

Yine de umut iner en son düşe.

Ömür, ince yazı yazar ateşe;

Silinmez hakikat göz yaşarınca.

Bir gün bütün sırlar dile dökülür,

Kapanan kapılar göğe sökülür.

Çürüyen tohumdan bahar görülür,

Ölüm de hayata alın koyunca.', 'Tohumlar düş görmüş suskun dallara, Toprak sır saklamış gece boyunca. Yıldızlar eğilmiş kör aynalara, Ay, kendi yüzünü arar olunca. Kırılmış...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kul-ve-kelebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elif''im', 'elif-im-ada-sezer-ieki3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuzenim,Elif
Bazen kızdırsada beni,
Vazgeçemem ondan.
İstiklal gibi dalgalanan saçları,
Türk bayrağı kadar ihtişamlı.

Bulamam onun gibisini,
Dünya''mda bir tane.
Uzaklarda kalsakta,
Gözüm hep onu arar.
Canımdan can yakar.

Seviyorum onu,
Hiç göremesem bile.

~Saygılarımla ada~', 'Kuzenim,Elif Bazen kızdırsada beni, Vazgeçemem ondan. İstiklal gibi dalgalanan saçları, Türk bayrağı kadar ihtişamlı. Bulamam onun gibisini,...', ARRAY['Türk Edebiyatı','Şiir','Ada Sezer']::text[], 8.5, '{"poet":"Ada Sezer","poet_slug":"ada-sezer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/e-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Mutsuz Umutsuz', 'mutlu-mutsuz-umutsuz-kazim-karagoz-koqgc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gülümsediğin kadar mutlu veya mutsuzsun,

Önemsediğin kadar umutlu, umutsuzsun.', 'Gülümsediğin kadar mutlu veya mutsuzsun, Önemsediğin kadar umutlu, umutsuzsun....', ARRAY['Türk Edebiyatı','Şiir','Kazım Karagöz']::text[], 8.5, '{"poet":"Kazım Karagöz","poet_slug":"kazim-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/mutlu-mutsuz-umutsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahenger', 'ahenger-kull-emin-9xinv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimde yosun tutmuş bir rıhtım var,

Gelgitler artık biraz durgun gibi,

Yormuyor beni eskisi kadar.

Ne de olsa insan geçmez,

Gemi yanaşmaz bu koca rıhtıma;

Kimse kalmadı yalnızlıktan başka.

Sadece gözlerimde ufkun derinliği,

Anlatırım bu dermansız derdi.

Belki de yosun tutmuştu bu ahengerin kalbi...

Dönüp durur bu tershane gece gündüz,

İşler yüreğime yavaş yavaş yalnızlık.

Allah''ın bir kuluyum, sevilir miyim belirsiz.

Geceleri bırakıyorum kendimi rıhtımdan,

Düşüyorum belirsizlik denizinin dibine,

Vuruyorum kalbimi koca bir zincire.

Yerine göre bir pehlivanım, ya da bir çocuk...

Düşünüyorum bazen, nasıl bu kadar acımasızsın?

Kendimden mi utanmalıyım acımasız değilim diye,

Yoksa seni mi kınamalıyım rıhtımların gelgitinde?

Baskın olan sen misin, yoksa içi boş sözlerin mi?

Cennet bahçesi gibisin;

Günahkârı bile alıyordun içeri...

Bense Allah''ın bir kuluyum,

Sevilir miyim belirsiz.', 'İçimde yosun tutmuş bir rıhtım var, Gelgitler artık biraz durgun gibi, Yormuyor beni eskisi kadar. Ne de olsa insan geçmez, Gemi yanaşmaz bu...', ARRAY['Türk Edebiyatı','Şiir','Kull Emin']::text[], 8.5, '{"poet":"Kull Emin","poet_slug":"kull-emin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ahenger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adamlık terazisi', 'adamlik-terazisi-mahmut-kasapoglu-kwvk5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dağ sanıp kendini boşa kurulma,

Yel eser, dağına yaslanamazsın.

Kibir kanadıyla göğe savrulma,

Hakk''ın divanında aklanamazsın.

Makamın, servetin bir gün silinir,

İnsanın aynası ahlak bilinir.

Dil kılıcı değse gönül dilinir,

Kırdığın kalplerle paklanamazsın.

Edep, en değerli miras, satılmaz,

Altınla, gümüşle asla tartılmaz.

Saraylarla kalbe adım atılmaz,

Gönül tahtında hiç taçlanamazsın.

Kusuru örtmeyen kusur büyütür,

İntikamın zehri canı çürütür.

Affetmek insanı Hakk''a yürütür,

Kin ile dünyada boylanamazsın.

Bugün güldüğüne yarın ağlarsın,

Ektiğin ne varsa onu toplarsın.

Vicdan terazinde kendin tartarsın,

Hakikatten kaçıp saklanamazsın.

İnsanlık yolundan sözle geçilmez,

Kararmış yürekte ışık seçilmez.

Sevgi hâlde yaşar, dille biçilmez,

Adamlık giymeden nurlanamazsın.', 'Dağ sanıp kendini boşa kurulma, Yel eser, dağına yaslanamazsın. Kibir kanadıyla göğe savrulma, Hakk''ın divanında aklanamazsın. Makamın, serv...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/adamlik-terazisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskunluğun dili', 'suskunlugun-dili-mahmut-kasapoglu-1mrxh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdaya and içtim gönül rengimce,

Bir gölge uğruna sözden dönemem.

Yazılmış kaderim sabır dengimce,

Asla hakikati eğip bükemem.

Düştükçe göklere yükseldi başım,

Kırıldıkça sabır oldu sırdaşım.

Adını andıkça titrer her taşım,

Çağıran sesine sağır kalamam.

Ne kibir giyerim ne de pişmanlık,

Aşkın en büyük adıdır insanlık.

Karanlık büyüse, artsa yalnızlık,

İçimdeki güneşi söndüremem.

Çünkü sevda almak değil, vermektir,

Yarayı gül diye göğse dikmektir,

Bir ömrü bir ömre helal etmektir,

Ben böyle sevmişim, başka olamam.', 'Sevdaya and içtim gönül rengimce, Bir gölge uğruna sözden dönemem. Yazılmış kaderim sabır dengimce, Asla hakikati eğip bükemem. Düştükçe gök...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/suskunlugun-dili-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gardaşım 2', 'gardasim-2-servet-bardak-6b7ng', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gardaşım 2

Hayatın rengine daim aldandım 

Her beşeri inan ben kendim sandım

Çilenin içinde inanki yandım

Hayat bana acı vurdu gardaşım

.

Yüreğimde yara kapanmaz kanar 

Acılar içimde durmaz hep yanar

Ruhumun içinde daim hüzün var 

Hayat bana acı yordu gardaşım

.

Hüzünler içimde bağrımda ateş 

Hayatın içinde oldum çilekeş

Çektiğim inan ki dünyalara eş 

Hayat bana acı hardı gardaşım

.

Gözlerim yaş ile yıkandı durdu

Arkadaş dostlarım arkamdan vurdu

İçimde herdaim sönmeyen hardı

Hayat bana acı kırdı gardaşım

.

Sönmeyen bir ateş var şu içimde 

Her yerimde sızı durur acımda

Serveti ak düştü beyaz saçımda 

Hayat bana acı dardı gardaşım 

.

17.11.2026

Servet BARDAK', 'Gardaşım 2 Hayatın rengine daim aldandım  Her beşeri inan ben kendim sandım Çilenin içinde inanki yandım Hayat bana acı vurdu gardaşım . Yür...', ARRAY['Türk Edebiyatı','Şiir','Servet Bardak']::text[], 8.5, '{"poet":"Servet Bardak","poet_slug":"servet-bardak","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gardasim-2-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende kalan ben', 'sende-kalan-ben-mahmut-kasapoglu-lbyho', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saklanmış yıllara döner düşlerim,

İçimde büyür, yakarışım olur.

Adını andıkça susar seslerim,

Her sessizlik bana varışım olur.

Gözlerin değince bahar açardı,

Yüreğim en güzel sana kaçardı.

Menfaat sevgiyi pula satardı,

Vefaya tutunan duruşum olur.

Umut bir kez ölse insan eksilir,

Kırık aynalarda yürek kesilir.

İhanet edenin adı silinir,

Bana düşen yine bağışım olur.

Sen benim yarımdın, tamam olmadın,

Gönlüme kuruldun, yabancı kaldın.

"Sevmedim." desen de inkâr saymadım,

Çünkü aşk en saf inanışım olur.

Sevgin sahteydiyse gözlerin neden

Her vedasında titredi yeniden?

Hesabını yapmaz yürekten seven;

Çıkara eğilmek çöküşüm olur.

Aklımın kıyısı hâlâ sen kokar,

İçimde adını rüzgârlar okşar.

Bir gün vicdanın da kapımı çalar,

Affetmek en derin bakışım olur.

Ne kin taşıdım ben ne de pişmanlık,

Sevda, karanlıkta yanan bir ışık.

Sen gittin, sönmedi bende aydınlık,

Sevmek benim yaradılışım olur.

Aynı gökyüzünde yıldız sayarsan,

Gözün dolu dolu susup ağlarsan,

"Beni de sevmişti..." diye anlarsan,

İşte o anda varoluşum olur.', 'Saklanmış yıllara döner düşlerim, İçimde büyür, yakarışım olur. Adını andıkça susar seslerim, Her sessizlik bana varışım olur. Gözlerin deği...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sende-kalan-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennetmi yok insan dünya görür', 'cennetmi-yok-insan-dunya-gorur-sedat-hunker-o23nf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çilesiz cennet var dünya her çile

Hilesiz cennet var dünya her hile

Sillesiz cennet var dünya her sille

Cennetmi yok insan bu dünya görür

Yarasız cennet var dünya her yara

Karasız cennet var dünya her kara

Darasız cennet var dünya her dara

Cennetmi yok insan bu dünya görür

Yorgunsuz cennet var dünya her yorgun

Vurgunsuz cennet var dünya her vurgun

Korgunsuz cennet var dünya her korgun

Cennetmi yok insan bu dünya görür

Tokluklu cennet var dünya her toksuz

Yokluksuz cennet var dünya her yoksuz

Çokluklu cennet var dünya her çoksuz

Cennetmi yok insan bu dünya görür

Yıkılsız cennet var dünya her yıklı

Sıkılsız cennet var dünya her sıklı

Bıkılsız cennet var dünya her bıklı

Cennetmi yok insan bu dünya görür

Ak bahtlı cennet var dünya ak bahtsız

Sık bahtlı cennet var dünya sık bahtsız

Çok bahtlı cennet var dünya çok bahtsız

Cennetmi yok insan bu dünya görür

Ak günlü cennet var dünya ak günsüz

Pak günlü cennet var dünya pak günsüz

Hak günlü cennet var dünya hak günsüz

Cennetmi yok insan bu dünya görür

Közlesiz cennet var dünya her közlü

Üzlesiz cennet var dünya her üzlü

İzlesiz cennet var dünya her izli

Cennetmi yok insan bu dünya görür

Gülleli cennet var dünya her ağla

Gülleli cennet var dünya her çağla

Gülleli cennet var dünya her yağla

Cennetmi yok insan bu dünya görür

Sellesiz cennet var dünya her selli

Yellesiz cennet var dünya her yelli

Öllesiz cennet var dünya her öllü

Cennetmi yok insan bu dünya görür

Kara mecnun

İnsanur/suz', 'Çilesiz cennet var dünya her çile Hilesiz cennet var dünya her hile Sillesiz cennet var dünya her sille Cennetmi yok insan bu dünya görür Ya...', ARRAY['Türk Edebiyatı','Şiir','Sedat Hünker']::text[], 8.5, '{"poet":"Sedat Hünker","poet_slug":"sedat-hunker","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/cennetmi-yoktu-dunyayi-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Zamanlar Gözümde Ufaldı', 'sonsuz-zamanlar-gozumde-ufaldi-kasim-kobakci-iafue', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimse bilmezdi derin uykuda dün,

Gözlerin dalıp göçtüğü o sürgün,

Sessizce biterdi yaşanan her gün,

O yorgun kuşu uçurmak ne zordu,

Göğsüme ağır bir sessizlik vurdu.

*

Kim başarmış ki düşten uyanmayı,

Ellerde kalan o solgun anmayı,

Unutup ateşte usul yanmayı,

Kanatlanıyor içimdeki rüya,

Uykuyla dolup taşıyor hep dünya.

*

Acılar bile uykuya dalarken,

Karanlık odamda yalnız kalırken,

Geceler ağır sükunet bulurken,

Gülümser oldum kapanan gözlerle,

Süzüldüm göğe büyülü sözlerle.

*

Kanatlarımı açtım o boşlukta,

Uyuştum kaldım yavaşça loşlukta,

Süzülen tüyler serin bir hoşlukta,

Çırpınmadan uçtum sonsuz aleme,

Uykuya bandım yazarken kelime.

*

Kim bilebilir bu sessiz uçuşu,

Yuvadan düşüp uyanan bir kuşu,

Uykuda biten yorucu yokuşu,

Gözlerim yumuk bakamam sabaha,

Kanat çırpmaya gücüm yok bir daha.

*

Hayat çarkından uzaklaştı tenim,

Uykular oldu artık tek bedenim,

Bilinmez nerede gizli nedenim,

Lime lime etsem de hatırayı,

Unuttum uykuda köşkü sarayı.

*

İsyan dinlenir şu solgun yüzümde,

Kanatlanır rüya iki gözümde,

Uyku kalmıştır yalnızca sözümde,

Dualarım da ninnilere dalar,

Kanadım şimdi hep sonsuzda çalar.

*

Yavaşça süzül karanlık geceye,

Suskunluk eklensin dilde heceye,

Çözüm bulunmaz gizli bilmeceye,

Bir umut uçur yalnız rüyalardan,

Ses seda gelmez solgun hülyalardan.

*

Sessizlik örtmüş incecik yolları,

Düşürmüş yere bağlanan kolları,

Uyku kuşatmış kırılan dalları,

Kanatlanırım dipsiz hülyalara,

Uçarım sessiz derin dünyalara.

*

Direnmek zordur çöken ağırlığa,

Düştü yüreğim bu kör sağırlığa,

Gömüldüm bittim ıssız karanlığa,

Uyku vaktinde usulca süzüldüm,

Rüzgara karşı boynumdan büküldüm.

*

Gözüm kapalı gökyüzüne daldım,

Bulutlar üstünde uykuda kaldım,

Dinlenen ruhumdan nefesi saldım,

Çırpınıp durdu yavaşladı heves,

Rüzgar veriyor uyutan bir nefes.

*

Kim bilebilir uykuda uçmayı,

Kapalı gözle göklere kaçmayı,

Kanadı kırık bir ışık saçmayı,

Susuz kalmışım çöllerde gezerken,

Sükunet beni inceden ezerken.

*

Her geçen saat uykum derinleşir,

Uçan rüyalar zihnimde birleşir,

Suskunluk gelip ruhuma yerleşir,

Özlem ateşi sönmüş içten içe,

Kanatlarım da dönmüş sanki hiçe.

*

Sonsuz zamanlar gözümde ufaldı,

Her kanat çırpış uykudan bunaldı,

Bedende can yok yalnız rüya kaldı,

Süzülüp gittim uykunun koynuna,

Huzuru sardım titreyen boynuna.', 'Kimse bilmezdi derin uykuda dün, Gözlerin dalıp göçtüğü o sürgün, Sessizce biterdi yaşanan her gün, O yorgun kuşu uçurmak ne zordu, Göğsüme ...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/sonsuz-zamanlar-gozumde-ufaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DUAMDA KALDIN', 'duamda-kaldin-basri-erdogan-sn8rk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece çöktü, bir kandil yaktım odada
Fitili eğildi, gölgesi kaldı duvarda
Adını anmadan dua ettim bu defa
Bir tek sen vardın yine her âmin arasında

Ben seni unuttum dedim, dilim utandı
Elim eski mektubun üstünde kaldı
Yıllar önce hakkını helâl et demiştin
Helâl ettim yâr, hasretin bana kaldı', 'Gece çöktü, bir kandil yaktım odada Fitili eğildi, gölgesi kaldı duvarda Adını anmadan dua ettim bu defa Bir tek sen vardın yine her âmin ar...', ARRAY['Türk Edebiyatı','Şiir','Basri Erdoğan']::text[], 8.5, '{"poet":"Basri Erdoğan","poet_slug":"basri-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/duamda-kaldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ben dönerim senin eski yoluna', 'ben-donerim-senin-eski-yoluna-basri-erdogan-uxa7f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşam iner bizim köyün dağına
Herkes döner ocağına bağına
Hasret çöker yüreğimin sağına
Ben dönerim senin eski yoluna

Güz de düştü bahçemizin dalına
Ayaz vurdu avlumuzun gülüne
Anam bakar bir şey demez hâlime
Ben dönerim senin eski yoluna

Kar da yağsa ayaklarım izine
Selâm saldım köyümüzün yeline
Bir gün dönüp bakarsan şu evime
Ben dönerim senin eski yoluna', 'Akşam iner bizim köyün dağına Herkes döner ocağına bağına Hasret çöker yüreğimin sağına Ben dönerim senin eski yoluna Güz de düştü bahçemizi...', ARRAY['Türk Edebiyatı','Şiir','Basri Erdoğan']::text[], 8.5, '{"poet":"Basri Erdoğan","poet_slug":"basri-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-donerim-senin-eski-yoluna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müsait''im Ben', 'musait-im-ben-sair-halaoglu-0zbz9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerim Bu Gün Duman Sahası

Oturup Ağlamaya Müsait''im Ben 

Gönlümde Bir Hüzün Bir Cenk Havası 

Her An Vurulmaya Müsait''im Ben 

Çektiğim Feryatlar Arşa Ulaştı 

Sen Gideli Dertler Benle Dolaştı 

Hasretin İliğimden Kana Bulaştı 

Kahrımdan Ölmeye Müsait''im Ben 

Ayakta Derman Yok Duracak Dizde 

Kalmadı Dökecek Yaş Bitti Gözde 

Adını Sayıklasam Kalıyor Genzde 

Üflesen Yıkılmaya Müsait''im Ben 

Seni Yar Bilmiştim Sığındım Sana 

Demedim Hasret Koy Zulmeyle Bana

Sen Zayıf Noktamı Çözmüşsün Ama

Bir Sözünle Ölmeye Müsait''im Ben 

Vurulmak Çağımdayım İndir Darbeni 

Her Sillede Devir Yere Ser Beni 

Sen Ne Anlarsın ki Bende ki Seni

Lal Olup Susmaya Müsait''im Ben 

Bana Kör Olmuşsun Bakar Görmezsin 

Şu Gönül Yarama Merhem Olmazsın 

Gerçi Anlamazsın Sağır Duymazsın

Yanıp Kül Olmaya Müsait''im Ben', 'Gözlerim Bu Gün Duman Sahası Oturup Ağlamaya Müsait''im Ben  Gönlümde Bir Hüzün Bir Cenk Havası  Her An Vurulmaya Müsait''im Ben  Çektiğim Fer...', ARRAY['Türk Edebiyatı','Şiir','Şair Halaoğlu']::text[], 8.5, '{"poet":"Şair Halaoğlu","poet_slug":"sair-halaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/musait-im-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tadımlık', 'tadimlik-bayram-erdogan-ocbq1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ruhlar aleminden dünyaya geldik

Son nefeslik dünya tadımlık dünya

Neleri öğrendik neleri bildik

Son nefeslik dünya tadımlık dünya

İnsanoğlu beşer bilmez kendini

Ahreti unutur dünya dendi mi

Ölüm ayırmıyor fakir zengini

Son nefeslik dünya tadımlık dünya

Dünya sevgisine kanan zararda

Lokmayı harama banan zararda

Kendini ölümsüz sanan zararda

Son nefeslik dünya tadımlık dünya

Bir nefeste biter bütün servetin

Unutulur gider kadrin kıymetin

Var edene olsun sonsuz minnetin

Son nefeslik dünya tadımlık dünya

Gün gelir gündüzler geceye döner

Gün gelir nefsinde ateşi söner

Felek bu güç yetmez seni de yener

Son nefeslik dünya tadımlık dünya

Dünyanın da ömrü bitmek üzere

Ne sultana kalmış ne de vezire

Vadesi dolanlar girmiş kabire

Son nefeslik dünya tadımlık dünya', 'Ruhlar aleminden dünyaya geldik Son nefeslik dünya tadımlık dünya Neleri öğrendik neleri bildik Son nefeslik dünya tadımlık dünya İnsanoğlu ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Erdoğan']::text[], 8.5, '{"poet":"Bayram Erdoğan","poet_slug":"bayram-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tadimlik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Anam', 'canim-anam-mehmet-macit-3-5ceij', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Artık ellerin saçımı okşamıyor,
Hayalin gözümün önünden geçiyor.
Sesin ise kulaklarımda çınlıyor;
Seni çok özlüyorum, benim can anam.
​"Canım yavrum" diye her çağırdığında,
Sırtımı sıvazlayıp okşadığında,
Varlığınsa hep bir güç oldu yanımda;
Seni çok özlüyorum, benim can anam.
​Ne sen doyabildin ne  bizler sana,
Yaşanacak çok günler vardı burada,
Takdir-i ilahi emri geldi başa;
Seni çok özlüyorum, benim can anam.
​Gidişin yıkıcı ve ansızın sondu,
Yuvanın direğisin, tatlı hatunu...
Bayram günü bize zehir zindan oldu;
Seni çok özlüyorum, benim can anam.
​Ana gibi yar olmaz bu diyarda,
En sevgili sensin anladım sonunda,
Kanatsız bir meleksin sen hep aklımda;
Seni çok özlüyorum, benim can anam.
​Mehmet Macit', 'Artık ellerin saçımı okşamıyor, Hayalin gözümün önünden geçiyor. Sesin ise kulaklarımda çınlıyor; Seni çok özlüyorum, benim can anam. ​"Canı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Macit 3']::text[], 8.5, '{"poet":"Mehmet Macit 3","poet_slug":"mehmet-macit-3","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/canim-anam-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünün Beyler!', 'dusunun-beyler-kemal-bolukbasi-2y71j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabahtan akşama haber bandında

Bir talan bir vurgun konumuz bizim

Helal mi? Haram mı? Allah indinde

Yatırım, borsamız fonumuz bizim

"Halka arz" soygunun en baş eseri

Kumpası kuranlar kazanır seri

Üç koyar bir alır kahir ekseri

Hiç olur beşimiz onumuz bizim

Umuda yatırır gariban kuruş

Ayı var boğa var haydi gel vuruş

Denetim hikaye yalandan soruş

Soyulur sessizce donumuz bizim

Hem yerel, ulusal, küresel çapta

Milyonu milyarı geceden kapta

Davanı unutup yeminden sapta

Tiz çıkar sesimiz tonumuz bizim

Yolsuza yol bulur para demeti

Hırsızın nursuzun şanı şöhreti

Toplasan ne çıkar gaddi gameti

Tüyden de hafiftir tonumuz bizim

Helalden kazanmak ne güzel şeyler

Nimeti vereni düşünün beyler

Kemâli söylerse doğruyu söyler

İnşallah hayrolur sonumuz bizim.', 'Sabahtan akşama haber bandında Bir talan bir vurgun konumuz bizim Helal mi? Haram mı? Allah indinde Yatırım, borsamız fonumuz bizim "Halka a...', ARRAY['Türk Edebiyatı','Şiir','Kemal Bölükbaşı']::text[], 8.5, '{"poet":"Kemal Bölükbaşı","poet_slug":"kemal-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dusunun-beyler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süzülmüş Boya', 'suzulmus-boya-kasim-kobakci-ufast', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Fırçadan damlayarak süzülmüş boya,

Gözlerinde garip uyuşuk bir rüya.

Renkler hep birbirine karışıp akmış,

Hislerini sessizce boşluğa atmış.

*

Öz eseriydi onun sessizce solan,

Fırçasıyla tuvale usulca dolan.

Dışavurumcu hisler uykuya dalmış,

Bütün o çılgınlıklar mazide kalmış.

*

Bir dışlanmış dünyadan kopup gelerek,

Tuvale uzanıyor boyun eğerek.

Yeni bir tarz olsa da gözler kapalı,

Uykuya esir düşen eli boyalı.

*

Bu yüzden midir bilmem sebep belirsiz,

Çizgiler uyuşuktur şekiller kirsiz.

Sanatının ruhu da yavaşça soldu,

Eserinin özüne dinginlik doldu.

*

Tam değerlendirmeden geçip gittiler,

Bu uyuşuk renkleri de terk ettiler.

Bu modern ressamın sağ eli uyuşuk,

Dışavurumcu fırça kalmış buruşuk.

*

Zaman durmuş gibidir boya biterken,

Uykuya yenik düşmüş hem de çok erken.

Kırmızı yavaşlayıp mavi uyumuş,

Fırçanın ucundaki suyu kurumuş.

*

O deli hisler, artık bir sis içinde,

Kaybolup gidiyorlar renksiz biçimde.

Tablolar yığılmış hep tozlu köşeye,

Hiç gerek kalmamış artık, boş neşeye.

*

Fırçası ağırlaşıp kalkmaz hiç elden,

Şarkısı duyulmuyor kopan o telden.

Dışavurumcu ruhu teslim oluyor,

Tuvaller yavaş yavaş gölge doluyor.

*

Ne bir coşku kalmıştır ne bir fırtına,

Sadece bir ağırlık çökmüş sırtına.

Göz kapakları düşüp boyalar bitmiş,

Bu uyuşan zihnine yalnızlık yetmiş.

*

Karanlıklar dolmuş sonunda odaya,

Unutulmuş elleri küsmüş fırçaya.

Sonsuz sanat olmuştur uykusu şimdi,

Dışavurum, solan renksiz bir resimdi.', 'Fırçadan damlayarak süzülmüş boya, Gözlerinde garip uyuşuk bir rüya. Renkler hep birbirine karışıp akmış, Hislerini sessizce boşluğa atmış. ...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/suzulmus-boya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmece', 'bilmece-nihat-malkoc-pp7c3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çözülmez bir bilmeceyim

Hem yok''um, hem var gibiyim

Mahkumların baş koyduğu...

Mahpusta duvar gibiyim

Yaş dökerim yaş dökenle

Boyun bükerim bükenle

Dost geçinirim dikenle

Gülistanda har gibiyim

Ay olurum gecelerde

Gözyaşıyım hecelerde

Dolaşırım yücelerde

Dağ başında kar gibiyim

Atlasla değişmem çulu

Tek vasfım "Allah''ın kulu"

Yolumdur Mecnun''un yolu 

Leylâlara yâr gibiyim

Kör nefsimi haklarım ben

Yüreğimi yoklarım ben

Birde binler saklarım ben

Saçılmış bir nar gibiyim

Sessiz akan ırmağım ben

Kader usta, yamağım ben

Dünya denen yumağım ben

Yürekteki ar gibiyim

Hem ahirim hem önceyim 

Rengârenk bir hemençeyim

Davul, zurna, kemençeyim

Erzurum''da bar gibiyim

Ağzım sıkı, giz tutarım 

Hakikati iz tutarım

Ağustosta buz tutarım

Zemheride kor gibiyim

Veysel''in sazı bendedir

Yunus''un sözü bendedir

Şerefli mâzi bendedir

Asırlık çınar gibiyim', 'Çözülmez bir bilmeceyim Hem yok''um, hem var gibiyim Mahkumların baş koyduğu... Mahpusta duvar gibiyim Yaş dökerim yaş dökenle Boyun bükerim ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bilmece-332-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrak', 'bayrak-ali-i-hsan-gurbuz-3-tzj1i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gördüğümde göklerde merhem olur yarama

Barışın umudusun mazin temiz ak senin 

Her milleti temsilen bir bayrağı var ama 

Cihanda bir emsalin yok bayrağım yok senin 

Tarih dün seni yazdı yarınlarda bak senin

Kolu hiç bükülmedi seni burçta tutanın 

Sendeki ay yıldızdan aydınlandı vatanım 

Ümidi tek sendedir evlâd-ı fatihân’ın

Göklerden nazar eyler arkandadır hak senin 

Tarih dün seni yazdı yarınlarda bak senin

Cihana nizam veren kökü derindeki Türk 

Türk İslâm davası bu, bu mesele çok büyük 

Bir yanda Türk dünyası Kıbrıs, Bosna ve Kerkük 

Taşınacak şey değil omuzunda yük senin 

Tarih dün sen yazdı yarınlarda bak senin

Umudusun dünyada mazlumların umudu 

Bırakmasın yaradan al bayraksız buyurdu 

Fahri Kainat bile sana övgü buyurdu 

Hilâlin rengi gibi yüzün temiz pak senin 

Tarih dün seni yazdı yarınlarda bak senin

Ay yıldızın şavkından ilham alır bu vatan 

Al rengine can verdi sayısız şehit yatan 

Yıldızın mânâ yüklü odur Türk’ü anlatan 

Al içinde ay yıldız bir benzerin yok senin 

Tarih dün seni yazdı yarınlarda bak senin

Türk milleti tek yumruk nöbetle seni bekler 

Şeref duyar seninle dikildiğin yüksekler 

Hep senin uğrundadır vatandaki tümsekler 

Ulubatlıya değen o zehirli ok senin 

Tarih dün seni yazdı yarınlarda bak senin

Bayrak var mı uğruna senden başka ölünen? 

Barış için tek sensin aranılan sorulan 

Ege''den ta Sincan''a nakış, nakış örülen 

Altaylara uzanan damar, damar kök senin 

Tarih dün seni yazdı yarınlarda bak senin

Kulaklar hep sendedir beklenen haber sende 

Nazlı nazlı dalgalan düşmanları yar sende 

Toplanmışız altında kudret sende fer sende 

Emrindeyiz emrinde biz sonuna dek senin 

Tarih dün seni yazdı yarınlarda bak senin

Ta ezelden hıncı var sana tüm şer güçlerin

 Kanadısın kolusun mazlumun muhtaçların 

Sofrasısın her zaman sefillerin açların 

Hilâl-i ahmer sin sen gönül gözün tok senin 

Tarih dün seni yazdı yarınlarda bak senin

Sana yer göstermek mi söyle kimin haddine?

Bir müjde vermem gerek Oğuz Kağan ceddime 

Hududun Viyana''dan dayansın Çinseddine 

Turan''a bayrak olmak gayen olsun tek senin 

Tarih dün seni yazdı yarınlarda bak senin', 'Gördüğümde göklerde merhem olur yarama Barışın umudusun mazin temiz ak senin  Her milleti temsilen bir bayrağı var ama  Cihanda bir emsalin ...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Gürbüz 3']::text[], 8.5, '{"poet":"Ali İhsan Gürbüz 3","poet_slug":"ali-i-hsan-gurbuz-3","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/bayrak-249-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerden Nereye', 'nerden-nereye-haci-ahmet-kucuk-sw8nv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eskiye değil eksiye gidiyor memleket ,

Sağlığına değil , yokluğuna içiyor bu millet,

Hayallerinin yok oluşuna, heyecanlarının katline ,

Sağlığına değil yokluğuna içiyor bu millet…

Sokaklarda top oynayan çocukların sesi kısıldı,

Balkonlarda asılan çamaşırların defilesinin sonu hazırlandı,

Ekmek arası salça hamburgerin arkasında kaldı , 

Ev oturmalarının yerini sohbet grupları aldı …

Mektupların tadı başka bahara kaldı,

Yaşlıların duaları yerini beddualara bıraktı,

Okulları tatil eden kar memlekete darıldı, 

Karla birlikte mahsumiyette mazide kaldı…

Hani nerde o siftah yapmayan komşuma gidin diyen esnaflar ?

Hani nerde o komşusu açken tok yatmayanlar ? 

Hani nerde o mahremiyetini elden mahrum bırakanlar ? 

Hani nerde o bir söz uğruna herşeyi yakanlar ? …

Şimdi yok oluşlara yakıyorum sigaramı,

Özlemlerimi de içine koyup yakmak istiyorum dünyayı ,

Nasıl dindirecek zalimler zümresi masumların ahını,

Beyhude, bu hasta vücuda zaman ilacı …

Eskiye değil eksiye gidiyor memleket ,

Sağlığına değil , yokluğuna içiyor bu millet,

Hayallerinin yok oluşuna, heyecanlarının katline ,

Sağlığına değil yokluğuna içiyor bu millet…', 'Eskiye değil eksiye gidiyor memleket , Sağlığına değil , yokluğuna içiyor bu millet, Hayallerinin yok oluşuna, heyecanlarının katline , Sağl...', ARRAY['Türk Edebiyatı','Şiir','Hacı Ahmet Küçük']::text[], 8.5, '{"poet":"Hacı Ahmet Küçük","poet_slug":"haci-ahmet-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nerden-nereye-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehtabım', 'mehtabim-taha-bilal-mustafa-kekec-u898p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerine bakınca huzur bulurdum

Aşkın çiçeğini koklar sana vurulurdum

Yağmurlar durmazdı ama ben yol bulurdum

Kalbim papatyaydı sana açılırdım

Sen benim güneşimsin içimi ısıtan

Geceye mehtap olup yolumu aydınlatan

İyi ki varsın kalbime yazılan

Seninle geçsin ömrüm hiç bitmesin zaman

Mehtabım geceme doğan ışığım

Sensiz ben eksiğim sensiz yarım

Gel sarıl bana kaybolalım

Seninle tamam bu yarım kalan yanım

Hiç başkası yok yüreğimde

Bir tek sen varsın

Düşüm gerçeğe dönsün gel yanıma sarılsın kalbim

Vedalar düşsün peşimizden biz bize kalalım

Bir ömür değil sonsuzlukta sevdaya yazılalım

Ellerin değse yeter zaman dursun o an

Bir bakışınla diner içimdeki tufan

Yollar uzun olsa da sana çıkar her yan

Adın yankı olur kalbimde her zaman

Mehtabım geceme doğan ışığım

Sensiz ben eksiğim sensiz yarım

Gel sarıl bana kaybolalım

Seninle tamam bu yarım kalan yanım

Geceler şahidimiz yıldızlar bize bakar

Bu aşk bitmez kalbim sende yaşar', 'Gözlerine bakınca huzur bulurdum Aşkın çiçeğini koklar sana vurulurdum Yağmurlar durmazdı ama ben yol bulurdum Kalbim papatyaydı sana açılır...', ARRAY['Türk Edebiyatı','Şiir','Taha Bilal Mustafa Kekeç']::text[], 8.5, '{"poet":"Taha Bilal Mustafa Kekeç","poet_slug":"taha-bilal-mustafa-kekec","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/mehtabim-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Krankın Ninnisi', 'krankin-ninnisi-kasim-kobakci-3jg2h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dediler makinede çalış sen yavaş yavaş, 

İşçinin üzerine çöktü bir derin telaş,

Gözlerin kapanıp bitsin içindeki savaş,

O krankın ninnisiyle tatlı uykuya ulaş.

*

Çarkların arasında kırıldı tüm o heves,

Uyuyuşun içinden duyulmuyor hiçbir ses,

Pürüzsüz dönen kranka teslim olmuş her nefes,

Rulmanlara sıkışmış uyuyan demir kafes.

*

Yani diyeceğim o, makinede bitmiş yol,

Piston ile mil uymuş, kranka bağlanmış her kol,

Ruhun çekilip gitmiş, içindeki huzur bol,

Şu uyuşuk tezgahta, sonsuz rüyalarla dol.', 'Dediler makinede çalış sen yavaş yavaş,  İşçinin üzerine çöktü bir derin telaş, Gözlerin kapanıp bitsin içindeki savaş, O krankın ninnisiyle...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/krankin-ninnisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ALEV ALEV ŞİİRLERİM', 'alev-alev-si-i-rleri-m-muhsin-yener-2-y7xd6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Öyle kolay okunmaz benim şiirlerim
Her harfi bir yangın,
Her kelimesi kor,
Her dizesi yüreğe düşen bir ateştir.

Öyle uzaktan bakmakla anlaşılmaz beni anlatan mısralar
Bir dokunursun, için yanar.
Biraz daha yaklaşırsın, yüreğin tutuşur.
Bir adım daha atarsın,
Kendi ateşinde kavrulur,
Kül olup düşersin hayatın orta yerine

Sonra bir rüzgâr eser,
Savurur seni bilinmeyen diyarlara.
Ne geri dönebilirsin başladığın yere
Ne de bıraktığın gibi kalabilirsin

Çünkü benim şiirlerim okunmaz yalnızca,
Yaşanır, hissedilir, acısıyla yanılır.

Ben kelimeleri kâğıda değil,
Yüreğimin yangın yerine yazdım.

Muhsin Yener', 'Öyle kolay okunmaz benim şiirlerim Her harfi bir yangın, Her kelimesi kor, Her dizesi yüreğe düşen bir ateştir. Öyle uzaktan bakmakla anlaşı...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/alev-alev-siirlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmeme Müsade Et...!', 'seni-sevmeme-musade-et-evo-evrim-f44nb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni  sevmeme  müsaade et;beni acıtmadan,
