INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muallak''a', 'muallak-a-zeki-mert-kuku-2xwpx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gökağ sezişlerinde/ terkedişlerinde ses aileleri ve sazın sözünde hayvanların geviş getirişleri ve nuh gibi ve ruh gibi tufanda kaybolmayan hissedişleri yırtılıp çatlayan filiz veren tohumların topraklarında doğan hakanlar yolunda binek aslanlar gibi, zemine kök salıp çıkamayınca topraktan taşınan halılar kilim motifleri geometrik desenler ressamın elinde dokuma tezgahı gibi.

Fır fırıldak dönersin her tezata çatarsın sen ne büyük muammasın muallakta yatarsın', 'Gökağ sezişlerinde/ terkedişlerinde ses aileleri ve sazın sözünde hayvanların geviş getirişleri ve nuh gibi ve ruh gibi tufanda kaybolmayan ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Mert Kuku']::text[], 8.5, '{"poet":"Zeki Mert Kuku","poet_slug":"zeki-mert-kuku","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/muallak-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kin Lekesi Çıkmaz', 'kin-lekesi-cikmaz-onder-karacay-kxf4k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '§

