INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Bakışlım', 'siir-bakislim-erdal-ebem-4ifzp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne zaman sana dair şiir yazmak geçse içimden,

Nefesim buz kesiyor, daralıyorum,

Kayıp gidiyor heceler dilimin ucundan,

Daha mısra olamadan

Can çekişiyor kelimeler,

Yarım kalıyor her şey,

Aşkım,

Hüznüm

Sevincim.

Bazen düğüm düğüm olmuş mısraların arasında

Bir korku büyüyor içimde,

Hüznüme meydan okuyan çığlıklarım 

Ürpertiyor yüreğimi,

İç çekişlerime yenilmeden

Haykırmak istiyorum tüm benliğimle,

Sevdamı, Umudumu, Hayallerimi…

Yeter artık!

Dökülsün bir çırpıda yılların yorgunluğu,

Ve kaybolsun gözlerinin güzelliğinde..

Ah şiir bakışlım…

Sendeki beni düşünmeden,

Yazabilsem bendeki seni,

Belki anlatabilirdim

En güzel şiir olduğunu,

Keşke;

Mısra mısra okuyabilsen beni,

Görebilsen yüreğimin öyküsünü

Ve duyabilsen bu aşkın türküsünü,

Keşke..

Kalbinin en güzel köşesinde

Papatyalara arkadaş edip 

Saklayabilsen, 

Koklayabilsen,

Hissedebilsen bu aşkı

Ah sevgili ah…

Anlatmak istiyorum, anlatamıyorum,

Çıkmaz sokağın tam ortasındayım,

Bir yanım; aşk var koş diyor,

Bir yanım;  ateş var yanarsın kaç diyor,

Güzelliğin dur diye haykırıyor karşımda.

Anlayacağın ikilemdeyim,

Şiir mi yazsam; 

Seni mi okusam şiir diye…

Erdal EBEM', 'Ne zaman sana dair şiir yazmak geçse içimden, Nefesim buz kesiyor, daralıyorum, Kayıp gidiyor heceler dilimin ucundan, Daha mısra olamadan C...', ARRAY['Türk Edebiyatı','Şiir','Erdal Ebem']::text[], 8.5, '{"poet":"Erdal Ebem","poet_slug":"erdal-ebem","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/siir-bakislim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadsiz', 'hadsiz-erdal-ebem-mytnq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Doğumdan ölüme, yolculuktur bu hayat,

Yalan dünya diyenler neyi yalan bulmuşlar,

Yaşamadan görünmez, istenen ab-ı hayat,

Cennet-ul Kübra için, nasıl plan bulmuşlar.

Kuytu köşe başında, nöbet tutmak iş değil,

Kusursuz dost aramam, elbet kusur hoş değil,

Mesele had bilmekte, haddi bilmek boş değil,

Zaman denen mezarda, hadsiz ölen bulmuşlar.

Dağıtır bol keseden yardım sever bey gibi,

İç başkadır, dış başka, sanki biraz toy gibi,

Çok hoş gelir sözleri, ince sesli ney gibi,

Malın mülkün içinde, çulsuz olan bulmuşlar.

Düşünmeden harcamış, nefes denen nimeti,

Anlamam; aklım ermez, nedir gerçek niyeti,

Hakkı anmak dururken, boşa çekmiş zahmeti,

Gül kokulu diyarda, gülsüz kalan bulmuşlar.

Şu Mahlûkat içinde, insandır gerçek veli,

Yalnız ona değmekte, Rahman’ın güzel eli,

Gözler kör, ayak topal, akıl sersem ve deli,

Karanlık zindanlara, nice dolan bulmuşlar.

Haktan gayri yazamam, ağır gelir dilime,

Ne söylese bilmem ki, zalim oğlu zalime,

Feryadım boşa değil, ağlarım ben halime

Firgatliyi mest edip, derde salan bulmuşlar.

Erdal EBEM/Aşık Firgatli', 'Doğumdan ölüme, yolculuktur bu hayat, Yalan dünya diyenler neyi yalan bulmuşlar, Yaşamadan görünmez, istenen ab-ı hayat, Cennet-ul Kübra içi...', ARRAY['Türk Edebiyatı','Şiir','Erdal Ebem']::text[], 8.5, '{"poet":"Erdal Ebem","poet_slug":"erdal-ebem","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hadsiz-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyim', 'beyim-erdal-ebem-zxoei', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zamanın hırsına av olmuş gafil,

Bu çağın zehrini, görmez ki beyim,

Maziyi yok saymış, kibirli sefil,

Geçmişin izini, sürmez ki beyim.

Akraba, komşuya, güven kalmamış,

Talebe, hocayı, öven kalmamış,

Sokaklar kan gölü, seven kalmamış,

Sevgisiz bu vurgun, durmaz ki beyim.

Gençliğin hiçliği, destan dillerde,

Erdem dersen sürünüyor yerlerde,

Hayatlar şamata, gözler ellerde,

Bu nesil hayal de, kurmaz ki beyim.

İhtiyar korkuda, kim bakar diye,

Evlatsa devletten, bekler hediye,

Düşünmez Vallahi, el ne der diye,

Ölüsüne elin, vurmaz ki beyim.

Ne oldu bilmem ki, nedir bu sancı,

Ne oğlan adamdır, ne kızlar bacı,

Öyle bir devir ki, sapkın baş tacı,

Devlet bile hesap, sormaz ki beyim.

Şimdilerde millet, meta peşinde,

Helalmiş harammış, ezer dişinde,

Hayali gelecek, görür düşünde,

Lakin üçe beşe, varmaz ki beyim.

Sırtları dayanmış, sahte bir güce,

Ağan mı? paşan mı? kim daha yüce,

Hak’tan gayri olan, tüm güçler cüce,

Mutlak güce akıl, yormaz ki beyim.

Nesiller bozulmuş, değişmiş ruhu,

Özünü mahvetmiş, kaybolmuş rah’ı

Boş yere anlattım böyle güruhu,

Firgatli murada, ermez ki beyim.

Aşık Firgatli(Erdal Ebem)', 'Zamanın hırsına av olmuş gafil, Bu çağın zehrini, görmez ki beyim, Maziyi yok saymış, kibirli sefil, Geçmişin izini, sürmez ki beyim. Akraba...', ARRAY['Türk Edebiyatı','Şiir','Erdal Ebem']::text[], 8.5, '{"poet":"Erdal Ebem","poet_slug":"erdal-ebem","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/beyim-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daimi Duamsın', 'daimi-duamsin-dr-yusuf-polat-mc7hv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen gündüzlerimde yoksun, 

Gecelerime de her dem uğramazsın. 

Lâkin ne vakit korkular diz çöker, 

Ne vakit yasaklar susar içimde, 

Bir vakit gelir ki...

Sen artık kalbimde değilsin; 

Kalbim dediğim şeyin ta kendisisin.

Ben sana nasıl leke süreyim 

Hangi kir değebilir ki 

Uğruna bin geceyi sessizce tükettiğim 

O tertemiz hasrete...

Zira insan, 

En çok kavuşamadığını saklar içinde.

En çok dokunamadığını korur. 

Ve bazı sevdalar vardır;

Ne yaşanmıştır bütünüyle 

Ne de vazgeçilmiştir onlardan.

İşte sen, 

Benim hiç dokunamadığım 

Ama ömrüm boyunca 

Bitirmeye kıyamadığım daimi duamsın.', 'Sen gündüzlerimde yoksun,  Gecelerime de her dem uğramazsın.  Lâkin ne vakit korkular diz çöker,  Ne vakit yasaklar susar içimde,  Bir vakit...', ARRAY['Türk Edebiyatı','Şiir','Dr Yusuf Polat']::text[], 8.5, '{"poet":"Dr Yusuf Polat","poet_slug":"dr-yusuf-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/daimi-duamsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimizdeki Eksik', 'i-cimizdeki-eksik-umut-engin-deniz-6e5w3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İÇİMİZDEKİ EKSİK

Yaşlı bir evde zaman sadece zaman- değildir.

Duvarlarında yılların izi,

kapı önlerinde çocukların sesi, 

eşiğinde ayrılıkların ayak izi.

Mahallenin sokakları dardı, 

insanları birbirine yakındı.

Bir kapı aralanır...

Yarım kalan hayatlar, söylenememiş sözler, ertelenmiş vedalar,

bir daha yaşanmayacak anılar.

Bazen takvimden bir yaprak değil, insanın içinden bir ömür kopar.

Birileri göçtü,

birileri uzaklara düştü.

Bir evin ışığı söndü,

bir başkasının kapısı kilitlendi.

Hayat sürünerek yoluna devam etti. 

İzi kaldı.

16.11.2026

UNLBBCN

Umut Engin Deniz', 'İÇİMİZDEKİ EKSİK Yaşlı bir evde zaman sadece zaman- değildir. Duvarlarında yılların izi, kapı önlerinde çocukların sesi,  eşiğinde ayrılıkla...', ARRAY['Türk Edebiyatı','Şiir','Umut Engin Deniz']::text[], 8.5, '{"poet":"Umut Engin Deniz","poet_slug":"umut-engin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/icimizdeki-eksik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçak Çay', 'kacak-cay-hakan-dincel-8ogg8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kaçak bir çayı,

yudumlamak gibiydi aşkın.

Önce biraz acı ama,

Sonra has olmanın,

farklı olmanın tarifsiz tadı.

Demlendiginde sanki,

sana,

kollarını kocaman  açan,

kaçak çay  gibi,

acip kollarini,

boynuna sarılmak isterdi,

seninle demlendiginde yüreğim. 

Ama,

kaçak bakışlarla, 

kaçak çay tadında  sevilen sevgili,

Kaçak çayın rengi gibi,

Kapkara etti hayalleri...', 'Kaçak bir çayı, yudumlamak gibiydi aşkın. Önce biraz acı ama, Sonra has olmanın, farklı olmanın tarifsiz tadı. Demlendiginde sanki, sana, ko...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kacak-cay-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahrum Etme', 'mahrum-etme-erdal-ebem-j2gyc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yılların yorgunluğu var üzerimde,

Sensizliği de yükleme,

Akşamın tenhasında duvara yansıyan

Gölgenle avunuyorum.

Mahrum etme.

Kimsesiz sokakların kaldırımlarında,

Ay ışığından ince ince beliren,

Huzmen vurur yüzüme,

Kalakalırım izlerken donuk bir yüz haliyle.

Şu meczubun yüreğini delip geçmekte aysiman

Mahrum etme.

Küstah bakışların arasında,

Rengarenk kelebekler dolaşıyor gözlerimde,

Uğur böceklerinin ışıltısı altında,

Hayallerime ses oluyorum dizelerimde. 

Belki anlatamam, 

Belki kısır kalır sözlerim,

Elimde değil ki; 

Tek güzel seni gördü gözlerim.

Mahrum etme.

Saatim sana kurulmuş,

Sabah akşam seni gösteriyor

Bıraktım tüm uğraşımı,

İşim de sensin, gücüm de.

Mahrum etme.

Tüm şarkılar seni fısıldıyor kulağıma,

Arabeskte sensin, hüzzamda,

“Bilmiyorum ne haldeyim, yürüyorum gündüz gece” 

Bak işte, şiirler seni yazmış, 

Bizi yazmış mısralara…

Ne zaman bir şiir okusam, 

Yada bir şarkı dinlesem,

Sen düşüyorsun, biz düşüyoruz aklıma.

Mahrum etme.

Yüreğim yorgun, yüreğim suskun

Gözlerinden yedim en büyük vurgun,

Aşka meydan okumaktı hayalim,

Sarsıldım, sendeledim,

Lakin Yıkılmadım, Yılmadım. 

Yorulmadım sevmekten,

Anla artık; 

Dilimde ismin, 

Hayalimde aysiman

Mahrum etme….

Aşık Firgatli  (Erdal Ebem)', 'Yılların yorgunluğu var üzerimde, Sensizliği de yükleme, Akşamın tenhasında duvara yansıyan Gölgenle avunuyorum. Mahrum etme. Kimsesiz sokak...', ARRAY['Türk Edebiyatı','Şiir','Erdal Ebem']::text[], 8.5, '{"poet":"Erdal Ebem","poet_slug":"erdal-ebem","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/mahrum-etme-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Gerçek Ölüm', 'tek-gercek-olum-andelip-mehmet-m75u6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '"Bir gün son bulacak dünya telaşım,

‎Ezelden ebede akarken zaman.

‎Nereye varacak bilmem ki yaşım,

‎Hayatım her zaman olurken hüsran.

‎

‎Ömür dedikleri bir nefeslik yol,

‎Kimi mücrim olur, kimi garip kul,

‎O gün konuşamaz diller olur lal,

‎Ecel şerbetini içerken her can.

‎

‎Ne servet kar eder, ne de saltanat,

‎Hesaba çekilir her türlü hayat.

‎Kalp de ümit olur, dilde münacat,

‎Rahmet kapısını açarken Rahman

‎

‎Günahım dağlardan yüksek olsa da,

‎Ümidim kesilmez günah dolsa da.

‎Gözümden kanlı yaş akıp gelse de,

‎Af dilemek için diz çöker insan.

‎

‎Ne kibir kalır ne de enaniyet,

‎Ne dünya malıyla baki bir servet.

‎Bir avuç toprakta biter bu müddet,

‎Kabre kapı açar şimdi her mekan.

‎

‎Ne diller tercüman olur halime,

‎Ne sözler yetişir suskun dilime,

‎Rabbimden niyazım tek bir kelime,

‎Bir ömür çıkmasın kalbimden iman.

‎

‎Amelim az amma niyetim vardır,

‎Kalbimden çıkmayan ümidim vardır,

‎Hic değil Gaffâr’a inancım vardır,

‎Rahmetini her an, ederdi ihsan.

‎

‎Bir gün açılacak amel defteri,

‎Bilinecek kalbin gizli her yeri,

‎Heyhat bu dünyaya dönülmez geri,

‎Mahşerde hesabın görülür her an.

‎

‎Bir hayır yapmadım yoktur amalim,

‎Kalmadı takata şimdi mecâlim.

‎Affet beni Rabbim perişan halim,

‎Rahmetindir yalnız derdime derman.

‎

‎Ey Rabbim, kapında bir garip kulum,

‎Sensiz karanlıktır şimdi her yolum.

‎Herşey yalan imiş tek gerçek ölüm,

‎Sana kavuşmayı özledim inan."', '"Bir gün son bulacak dünya telaşım, ‎Ezelden ebede akarken zaman. ‎Nereye varacak bilmem ki yaşım, ‎Hayatım her zaman olurken hüsran. ‎ ‎Ömü...', ARRAY['Türk Edebiyatı','Şiir','Andelip Mehmet']::text[], 8.5, '{"poet":"Andelip Mehmet","poet_slug":"andelip-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/tek-gercek-olum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mefluç Bir Sefer', 'mefluc-bir-sefer-erdal-ebem-9v6i8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yol uzun, mekân dar, zamansa kısa,

Bu köhne mekânda ezdirme dünya.

Şafak vakti düştüm, amansız hırsa

Zevk sefa peşinde, gezdirme dünya.

İmtihan başlamış, körpecik yaşta,

Güneşi gözledim, zemheri kışta,

Rızkımı ararken, durmadan taşta,

Yaşama hevesim, bozdurma dünya.

Ömür bir senaryo, seyrettim dizi,

Zaman denen mezar yok etti bizi,

Doğruyu ararken, kaybettim izi,

Meçhule bir sefer, yazdırma dünya…

Meflûç bir adamın gayreti yersiz,

Dolaşır gün be gün kafeste ser’siz,

Öyle bir halde ki, andan habersiz,

Diriye boş mezar, kazdırma dünya.

Ne istersin bilmem, bu garip kuldan,

Bir medet ummadım, paradan puldan,

Yorulmuş bedenim, bellidir halden,

Halimi görüp de bezdirme dünya.

Sitem etmem asla, şükür var dilde,

Derdi veren Mevla’m, götürür yelde,

Firgatli’ye dardır, bu garip belde,

Bu meflûç seferi, sezdirme dünya,

Aşık Firgatli/Erdal EBEM', 'Yol uzun, mekân dar, zamansa kısa, Bu köhne mekânda ezdirme dünya. Şafak vakti düştüm, amansız hırsa Zevk sefa peşinde, gezdirme dünya. İmti...', ARRAY['Türk Edebiyatı','Şiir','Erdal Ebem']::text[], 8.5, '{"poet":"Erdal Ebem","poet_slug":"erdal-ebem","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mefluc-bir-sefer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamana Beyit', 'zamana-beyit-erdal-ebem-kf2lx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zaman ilmek ilmek geçti gönül telimden,

Dur demeye gücüm yok bir şey gelmez elimden.

Küçüktüm henüz; hep yol uzun deyip durdular

Büyüdüm; ne arayıp ne de bir gün sordular.

On beşinde düşersin, baharın kucağına,

Sonra baba olursun, kış düşer ocağına.

Hayat dersin adına, koşarsın ardı sıra,

Akla gelmez nedense; ne Sina nede Hira.

Şöyle dönüp ardına bakarsın geçmiş zaman,

Keşkelerin tükenmez, dönmeye yoktur güman.

Küheylan nidaların, ilham olmaz derine,

Yarım kalır sualler, cevap gelmez birine,

Feryatsız güne kızma, susmak kâr etmez dile,

Dokunmuşlar bir kere, susmak bilmeyen zile.

Geçtik mi? Bilemem ki dünya denen mizandan,

Haber almak zor iştir, katmer katmer yazandan.

Ömür geçip gitmekte, belki meçhule sefer,

Kutlu dava uğrunda, şehit olur her nefer.

Gel kendine uyan bak, uzun yol büyük yalan,

Ağladın, güldün, öldün, budur elde tek kalan.

Aşık Firgatli(Erdal Ebem)', 'Zaman ilmek ilmek geçti gönül telimden, Dur demeye gücüm yok bir şey gelmez elimden. Küçüktüm henüz; hep yol uzun deyip durdular Büyüdüm; ne...', ARRAY['Türk Edebiyatı','Şiir','Erdal Ebem']::text[], 8.5, '{"poet":"Erdal Ebem","poet_slug":"erdal-ebem","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zamana-beyit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ne Ettinki', 'sen-ne-ettinki-erdal-ebem-1dwxc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yok oldu gençliğim, senin uğrunda,

Ben yazı kış ettim, sen ne ettin ki?

Heder oldu ömrüm, bu aşk yolunda,

Ben öldüm, ben bittim, sen ne ettin ki?

Gözlerim gözünden, öteye dönmez,

Yürek yakan bu hal, sevdasız sönmez,

Ne söylersen söyle, feryadım dinmez, 

Çöllere ben gittim, sen ne ettin ki?

Yaz bahar demeden, düştüm peşine,

Bu derbeder adam, sığmaz düşüne,

Diyar diyar gezdim, denk yok eşine,

Meçhulde ben yittim, sen ne ettin ki?

Nedendir sevdiğim, oynadın oyun?

Kadere de kızmaz, eğerdim boyun,

Kem söz edip durdun, betermiş huyun,

Her sözü ben yuttum, sen ne ettin ki?

Laf ettin durmadan, geceye, güne,

Sabahtan başlardın, siteme düne,

Çıkrıkta döndürüp, benzettin yüne,

İğneye ben battım, sen ne ettin ki?

Gözlerinle yaktın, alt ettin beni

Dağıldım ardında, mat ettin beni,

Kötürüm eyleyip, kut ettin beni,

Yatağa ben yattım, sen ne ettin ki?

Sevda için çıktım, bu garip yola,

Felek oyun kurmuş, Firgatli kula,

Sevda gömleğimi, takıp bir dala

Pazarda ben sattım, sen ne ettin ki?

Aşık Firgatli  (Erdal Ebem)', 'Yok oldu gençliğim, senin uğrunda, Ben yazı kış ettim, sen ne ettin ki? Heder oldu ömrüm, bu aşk yolunda, Ben öldüm, ben bittim, sen ne etti...', ARRAY['Türk Edebiyatı','Şiir','Erdal Ebem']::text[], 8.5, '{"poet":"Erdal Ebem","poet_slug":"erdal-ebem","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sen-ne-ettinki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhul Sefer', 'mechul-sefer-erdal-ebem-fqr9f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yolum düştü meçhule, yollar sormaz halimi,

Andan uzak kalmaya, mecal kalmaz bilesin

Namım batsın yerlere, seyre durdum zalimi,

Şaşkın gezen yüreğim, haber salmaz bilesin.

Ay siman gitmez oldu göz ucumda duruyor,

Yalnızlık matem sanma, seni bana kuruyor,

Eğdim başım önüme, gelen geçen soruyor,

Alnım açık pak benim, âlem gülmez bilesin.

Raydan çıktım bir kere meçhuldür artık adres,

Recm edilmiş kalbimi, saklamaz kemik kafes,

Yollar bitmek bilmiyor, yolculuk büyük heves,

Nemrut ateş yaksa da, maşuk ölmez bilesin.

İnce ince dokudum aşk denen bu kilimi,

Islanmaz gözyaşıyla, böyle yazdım ilimi,

Lale sümbül ekledim, yok eyledim ölümü,

Şanı kalsın bu aşkın, ilmek yılmaz bilesin,

Mahrum kalmışlığım var, sırra kadem bildiğim,

Levh-i mahfuzda saklı, en son nasıl güldüğüm,

Elem ince bir nakış, gözyaşımla sildiğim,

Eller görür halimi, aşkım solmaz bilesin.

Derdim büyük dedikçe, aklım gider ahtıma,

Divane bir haldeyim, melal düşmüş bahtıma,

Yar görmesin yaramı, yaram merhem tahtıma,

Ram olmuş olsam bile, kimse bilmez bilesin.

Elden ayaktan düştüm, korkarım ecel yakın,

Irgat oldum meydanda, görünce düşme sakın,

İlk sana yârim dedim, nedir bilmem merakın,

En tutkulu aşktın sen, eller silmez bilesin.

Nice zaman oldu bak, aklım kalmış gözünde,

Matem değil bendeki, gözüm durur yüzünde,

Merhamet beklemedim, aşkın yanan közünde,

Firgatli sevdam demiş, sensiz olmaz bilesin.

Aşık firgatli/Erdal EBEM', 'Yolum düştü meçhule, yollar sormaz halimi, Andan uzak kalmaya, mecal kalmaz bilesin Namım batsın yerlere, seyre durdum zalimi, Şaşkın gezen ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Ebem']::text[], 8.5, '{"poet":"Erdal Ebem","poet_slug":"erdal-ebem","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/mechul-sefer-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazze''de Bir Çocuk', 'gazze-de-bir-cocuk-erdal-ebem-vusbl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vicdanıyla savaşan insanlığın yoksunluğu,

Dakika dakika, büyütmekte zulme suskunluğu,

Uzaklarda bir çocuk ağlıyor, hıçkıra hıçkıra,

Hangi vicdan bu zulme bilmem nasıl haykıra,

Düşlerim karanlığa gömüldü bu gece,

Gök kubbe çocuk çığlıklarıyla inlemekte,

Koca görünümlü dünya bu sesi dinlemekte,

Istıraba mahkûm edilmiş annelerin feryadı,

Bu cılız haykırışlar hangi sistemin gerçek adı,

Üstelik mazlumun sesinden çok zalimin sesi,

Yetmedi ne hikmetse hiçbir kralın cüssesi,

Yetim kalmış Feryatlar, öksüz çocuklara acıyor,

Bir Siyonist sistem tüm dünyaya kan saçıyor.

Her gece Gazze semalarında kan kızılı bir renk var,

Zulmü görmek istesen de, göstermez büyük duvar.

İNSANLIK! vicdanı cüzdanına sıkıştırılmış, İnsanlık 

MERHAMET! Esaretten kurtulamamış merhamet,

CESARET! Varlığın büyüğünü inkâr eden cesaret,

Ey insan; görmez misin cihat eder mazlum zalimle,

Neden zulme çanak tutarsın o mukaddes elinle,

II

Gazze’li cesur çocuk şehadet için arşa koşmakta,

Yığın yığın, doludizgin atlarla sınırları aşmakta,

Bombaların ardında koşuyor körpe canlar,

Ve tarumar olmuş odasının penceresinden,

Anlamsızca insanlığı gözleyen o masum çocuk

Bir umut diyerek bir daha semaya bakarak

İnsanlığı arıyor…..

Bekleme çocuk;

İnsanlık; Siyonist bir kafede esir vicdanıyla savaşta,

Gazze filim setinde zalimin filmini seyirde,

Bekleme yorulursun.

Düşlerin de yorulmasın boş yere,

Sen açlık nedir bilirsin,

Yokluk nedir bilirsin,

Açlığın pençesinde dünya,

Çok görme çocuk,

Ben seninle konuşmaya utanıyorum çocuk,

Gözlerimi gözlerine değdirmeye korkuyorum.

Korkutmuşlar bizi çocuk,

Senin korkmadığın açlıktan,

Senin korkmadığın susuzluktan,

Senin korkmadığın yaşamaktan,

Bizi korkutmuşlar çocuk,

Kendime ne kadar acısam bilmiyorum,

Körpe bedenine sığdırdığın cesaretini,

Cüzdanlara sığdırıp boykot bile edemedik,

Anlayacağın masivaya meftun düş ağır bastı,

Sığdıramadık, sığmıyor çocuk,

III

Düşlerim karanlıkla boğuşuyor bu gece,

Şimdi sen sırtın pek bir şekilde tok yatarken

Ben açlığa nasıl direneyim, 

Ben nasıl uyuyayım çocuk,

Sen dayalı döşeli odanda oyuncaklarınla oynarken,

Ben bombalardan nasıl oyuncak yapılır bilmem ki,

Ve en kıymetlisi;

Sen annenin merhametine sarılıp dinlenirken,

Ben öksüzlükle nasıl mücadele edeyim,

Sen söyle;

Bunca yoksunluğa nasıl dayanayım,

Ne olur bir akıl ver bana çocuk

Düşlerim karanlıkla boğuşuyor bu gece,

Sen de bize üzülüyorsun, 

Üzülme çocuk,

Biz zaten insanlık dersinden sınıfta kaldık,

Yarım yamalak vicdanımızla da başımız büyük dertte,

Yani ne insanlığımız tam, 

Ne de vicdanın kıvılcımları içimizde.

Lazım olmaz diyerek merhameti de söküp attık içimizden,

İşimize geldi birazda neme lazım dedik.

Eksik yanımız çok anlayacağın.

Senin geçtiğin tedrisattan bizi geçirmediler

Boş ver gitsin biz böyleyiz işte.

Sen de bize üzülüyorsun. 

Üzülme çocuk

IV

Sen yüreğini serin tut çocuk,

(Hz) İbrahim’i bir duayla muhatapsın,

(Hz)Muhammed’i bir şefkatle seviliyorsun,

Sen (Hz) Davud’un hikâyesini benden iyi bilirsin,

Taş deyip geçme çocuk,

Az biraz sabret.

Mutlak gelecektir gelmesi gereken 

Yakındır elbet o büyük diriliş.

Erdal EBEM', 'Vicdanıyla savaşan insanlığın yoksunluğu, Dakika dakika, büyütmekte zulme suskunluğu, Uzaklarda bir çocuk ağlıyor, hıçkıra hıçkıra, Hangi vi...', ARRAY['Türk Edebiyatı','Şiir','Erdal Ebem']::text[], 8.5, '{"poet":"Erdal Ebem","poet_slug":"erdal-ebem","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/gazze-de-bir-cocuk-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Aşk', 'yalniz-ask-hakan-dincel-y5rih', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'En deli çağımın kizilliginda sevdim seni,

hesapsız, kitapsız ve delice.

Dağların yucesinde yakılan ateşler gibi büyük, 

bir o kadar da kahpe dumanlar içinde.

Bahceli'' de dökülen damlalar, Eylül de  yapraklara yoldaş olurdu,

Kim bilirdi ki,  gün gelirde en sevdiğin, hiç  acımadan vururdu.

Avına çökmüş bir çakalın,  kanli  dişleriyle,

Lime lime edilirken  bedenim,

seneler süren bir rüyaya dalan,

akillanmaz, zavallı 

delikanlı yüreğim...

Ve ben hâlâ, kızıllığın gölgesinde,

yitik yüreğimle dolaşıyorum sokaklarda.

Senin adın, dudaklarımda lanetli bir şarkı,

her nefeste içimde bir fırtına koparıyor.

Gözlerim hâlâ seni arıyor kalabalıklarda,

her bakış, bir yılanın sinsiliği gibi.

Ama artık biliyorum…

Aşk, bazen en büyük kahramanlık değil,

en acımasız savaştır,

ve ben seninle kaybetmeyi öğrendim.

Ruhum lime lime olurken,

anlıyorum ki…

Bazen sevmek, sadece acıyı taşımaktır,

ve en delice aşklar,

en sessiz yalnızlıkta yankılanır.', 'En deli çağımın kizilliginda sevdim seni, hesapsız, kitapsız ve delice. Dağların yucesinde yakılan ateşler gibi büyük,  bir o kadar da kahpe...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yalniz-ask-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mülkiyet Kasidesi', 'mulkiyet-kasidesi-erdal-ebem-m6udl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İhtişamlı o cüssede, gördüm hoş bir gül-i zar

Âmâ olmuş göremez ki, siyaset-i ihtiyar,

Korkular ki sebepsizdir, faydasızdır ah-u zar,

Yıllar oldu görmedik şahım, şah-ı cihan bu diyar.

Arz-ı milletten alınmış temsil-i bir yetkide,

Keyfiyet değil ki bu hal, niyedir bu intizar.

Bir ses vardır uzaklardan, gelecek mesut bahar,

Dalgalara set olmak değil, maharet denen duvar.

Viran haldedir ortalık, hayaller tozpembe, kor

İspata hükme ne gerek, fikir yoksun, akıl dar,

İmtiyaz hakkı kimdedir, sorgular nasıl biter,

Kuşbakışı haykırışlar, gök kubbeden bihaber.

Vicdanı saklayan köle, her yolu mubah sayar? 

Evlat ceddine öfkeli, zaman arşa hilekâr,

Gördüm ki ahkâm-ı cenin, kâbus dolu rüyada,

Şu Vatan-ı mukaddese, kimler niye kin duyar,

Söz büyük sanat olsa da, hüküm vermek zor olur,

Zalimler neylesin sesi, düzen mazluma kıyar.

Fatihten kalma izleri, yaşamak size kaldı,

Asra köleliğe dur de, düşme sonunda bizar.

Zamansa, senin zamanın, dur demeli vurguna,

Hayat senin, gelecek sen, kimler sana ne sorar.

Ey genç! Hak’tan yana yürü, hain meydan bulmasın,

Unutma ferman bellidir, ihanetin bin bir yolu var.

Korkular ki sebepsizdir, faydasızdır ah-u zar,

Yıllar oldu görmedik şahım, şah-ı cihan bu diyar.

Firgatliyi saran derde, merhem olmaz bu düzen,

Söylemek kâfi gelmez, söylesem kime yarar,

Aşık Firgatli /Erdal Ebem', 'İhtişamlı o cüssede, gördüm hoş bir gül-i zar Âmâ olmuş göremez ki, siyaset-i ihtiyar, Korkular ki sebepsizdir, faydasızdır ah-u zar, Yıllar...', ARRAY['Türk Edebiyatı','Şiir','Erdal Ebem']::text[], 8.5, '{"poet":"Erdal Ebem","poet_slug":"erdal-ebem","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/mulkiyet-kasidesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Başına', 'tek-basina-hakan-dincel-qtfz6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gelmişiz ötelerden,

geri dönmek için Allah''a,

Bilinmez nerede, ne zaman, hangi yaşta.

Bir ağaç gibi kök salsak da dünyaya, yaprak olur düşeriz,

sıra sıra ve bir bir toprağa.

Göz yaşlarıyla gelip,  kahkahalarla yaşadık ama,

alamadık  giderken cebimize,  ummandan bir damla dahi yanımızda .

Herşey onun,

can da, mal da,

bunu anlamasak, benim sansak da.

En büyük hazinedir, 

kalbinde, dilinde  iman varsa son anda.

Herşey boş, tek dostta o,

Yakınlar uzakta kalır,  bilinmez bir sonla.

tek başına geldik,

tek başına gidecegiz huzura...', 'Gelmişiz ötelerden, geri dönmek için Allah''a, Bilinmez nerede, ne zaman, hangi yaşta. Bir ağaç gibi kök salsak da dünyaya, yaprak olur düşer...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tek-basina-119-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baba', 'baba-hakan-dincel-9kbyl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Muammalar içinden, 

gelmişken bir keşmekeşin ortasına, 

ve el kadar bir umutla,

var olduğumuz,

bu uçsuz bucaksız   dünyada.

Ulu bir çınar gibi,

gölgesinde dinlendirip, 

korur, kollar,  büyütür,

dertten kederden nasır bağlayan  kalbinin,

en gizli odacığında.

Adam gibi durur, 

her an arkanda,  varlığını hissettirir yıllar yılı, 

çocukda olsan, büyüsen, ev kurup,  çoluk çocuğa karissanda, 

yakından da,

uzaktan da olsa, 

ya da bulutların üzerinden,

seni seyre dalsa da ,

güç verir daima sana. 

Masallarda okuyup,

ne olduğunu  öğrenemeden daha, 

gözümüzün gördüğü, 

ilk kahramanimizdir hayran olduğumuz, 

etiyle, kanıyla, canıyla.

Hissetmesekte, bilmesek de  bunu o varken, 

ama  iliklerimize kadar, özleme boguluruz, 

gittiğinde o uzaklara.

Milyonlarca yıl,  yol yürümüş gibi, yorgun ve  çekingen adımlarla, 

düşe kalka  yürüdüğümüz, 

hayat denilen bu acımasız yolda,

ve bir yudum su  bulamadığımızda, okyanuslar ortasında,

Erinmez, çekinmez, kucaklar,

sırtına alır,

düştüğün yerden kaldırır defalarca. Can suyu olur, mahcup, 

duygulu bakışlarla,

sevgisizlikten çatlamış dudaklarına.

Rüzgar gibi yetişir,

bir bakarsın, koşmuş gelmiş,

bin yıllık yoldan, son sürat, sıkıntılı anında yanina.

Bir bakarsın, 

uyanmani bekliyor hastayken, 

atıyor mu kalbi, nefes alıyor mu diye telaslidir, gizlice başucunda, 

bir bakarsın, 

parlıyor nurların içinde,  gülümsüyor rüyalarinda.

Dinmese de sıkıntısı, 

göğsünü dağlasa da  acısı, 

bildirmez kimseye, 

meraklı gözlerden  kaçırdığı  yaşlarla,

içindeki yanardağı söndürmeye çalışır, damla damla.

İncinir söyleyemez,

uyku tutturmayan elemi,  kederi, 

dışardan gören, hiçbir derdi yok sanir, 

ateşlerden gömlek giymiş olsada.

Nede olsa,

güçlü olmalıdır dağ gibi, 

gayreti, mutluluğun, beraberliğin alameti, 

sofrada varlığı bereket, 

gören gözler kusur etmez saygıda.

Usulca, sessizce, vakarla

yediği helal lokması, 

ders verir sayfalarca.

Cimridir,  kendisine harcamakda,

sesi sedası duyulmadan, 

seviyorlar mi beni diye aldırmadan, ayırır tüm varlığını yavrusuna.

Emanet edilen canlar  icin kendisine, 

gerekirse , 

tüm varını satar, 

onlar mutlu olsun diye,

kış gününde soğuk odalarda, titreyerek uyanir tek başına .

Layık olunan duası, 

cennetin anahtarı,

evinin yıkılmaz direğidir, 

kaç zelzele atlatmış olsa da.

Bakışlarıyla sever, konuşur , dokunmadan   okşar, 

fark edilmeyen,

gözlerinden çıkan sevginin ışığıyla.

Tehlikenin önünde, 

bir set gibi durur,

ailesini korur,

yok olmak pahasina.

Sanki,  söylerken  boşuna yorulmasin hiç kimse diye istediğinden, 

2 harf ve 

aynı 2 hece ile  yazılır adı , 

ve 

yürekleri titreterek, 

doya doya  okunur 

BABA ...', 'Muammalar içinden,  gelmişken bir keşmekeşin ortasına,  ve el kadar bir umutla, var olduğumuz, bu uçsuz bucaksız   dünyada. Ulu bir çınar gi...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/baba-735-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumdaki ayak izleri', 'kumdaki-ayak-izleri-ufuk-tan-yoo6t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'her   zaman  gittimiz  yere  gitim

kalbim  kırık  senden  yoksul  ama

oturdum taşa  denizi  seyrettim

umutsuz   düşüncelerle  bekledim

burdayken   hep  elini tutardım

hayallerimizi  konuşurduk bereber

deniz  kıyısında  el  ele  yürürdük  sonsuza

kumda  ayak  izleirmiz  kalırdı  hatırladığım  bu

ömrüm  bebegim  nurtanem  aşkım

ömrüm  bebegim  nurtanem  aşkım

senin  kumdaki  ayak  izlerin  silinmiş

oysaki  şimdi  bakıyorum  senden  kalan

hiç  bir  şey  yok  beraber  yürürken  olan

kumdaki  ayak  izlerimiz bile  yok  yok  yok

denizin  dalgaları  ayak  izlerini  silmiş  ömrüm

hayat   sanki  benim   için  bitmiş  bitmiş  ömrüm', 'her   zaman  gittimiz  yere  gitim kalbim  kırık  senden  yoksul  ama oturdum taşa  denizi  seyrettim umutsuz   düşüncelerle  bekledim burda...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Tan']::text[], 8.5, '{"poet":"Ufuk Tan","poet_slug":"ufuk-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kumdaki-ayak-izleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merdiven', 'merdiven-hakan-dincel-98zqq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'MERDİVEN

Bir merdivende yürür gibi yürüdüğün hayatta, 

Neler neler gördün neler neler  koydun heybene.

Ne acılar, ne mutluluklar,

Ne heyecanlar, ne korkular...

Hayat sana hep zayıf olduğun yerden sınav yaparken,

hep aynı yanlışları yaptın önceleri ısrarla.

Sonra sonra anladın hayatı ve hatanı...

Mutluluğun aslında vermek olduğunu anladın, 

tutmak, almak, saklamak değil de...

Fütursuzca insanlara bilgiçlik taslarken,

Asıl bilgiçligin haddini bilmek,

En büyük erdemin,  her canlıya koşulsuz saygı duymak olduğunu.

Merdivenleri tırmanıp yükselirken hem büyüdün,

hem küçülmek gerektiğini anladın.

En Yüce nin karşısında,

bir zerre bile olmadığının farkına vardın.

Ne mutlu sana ki,

günahsız bir meleğin gönlüne ve dualarına  girebildiysen,

Ne mutlu sana ki,

ihtiyacı olan birinin yardımına koşabildiysen,

Ne mutlu sana ki, 

Yüceler Yücesine, 

bu o,

benim olan o, 

benden olan o,

dedirttirebildinse merdivenlerden inip de, 

geri dönerken geldiğin yere...', 'MERDİVEN Bir merdivende yürür gibi yürüdüğün hayatta,  Neler neler gördün neler neler  koydun heybene. Ne acılar, ne mutluluklar, Ne heyecan...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/merdiven-151-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-hakan-dincel-i55xz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'AYRILIK 

Siyah da bizim, beyaz da,

Mutluluk da bizim,acı da.

Sevda da bizim kavgada,

Seven kalpler ayrılır mı,

Tenler uzak olsa da...', 'AYRILIK  Siyah da bizim, beyaz da, Mutluluk da bizim,acı da. Sevda da bizim kavgada, Seven kalpler ayrılır mı, Tenler uzak olsa da......', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ayrilik-2078-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neylesin', 'neylesin-hakan-dincel-dsgp0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'NEYLESİN

İki gönül sarilmissa dolanmışsa  sıkıca,

ayrılık neylesin, veda neylesin ?

Hasretle kalpler, aşk ile yakılmışsa,

yollar neylesin, yıllar neylesin ?

Yarın hayali düşmüşse aklına, gitmiyorsa kovsanda,

gece neylesin, uyku neylesin ?

Birlikte icilmisse aşk şerbeti,

hesap neylesin, ceza neylesin ?

Aşık gitmek için kalkmissa ayağa,

Akşam neylesin, hazan neylesin...', 'NEYLESİN İki gönül sarilmissa dolanmışsa  sıkıca, ayrılık neylesin, veda neylesin ? Hasretle kalpler, aşk ile yakılmışsa, yollar neylesin, y...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/neylesin-109-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büşra ~', 'busra-gulizar-karatas-k8v7w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BÜŞRA ❤️

Bilmezdim sevdaya düşmeden önce,
Üşümezdi ellerim, yüreğim…
Şahit oldu şimdi kelimelerim.
Ruhuma işledi sana olan sevgim.
Anlamanı hiç beklemedim, tek derdim seni sevmekti benim…

Her gece geldim kapına,
Belki son bir kez görebilmek adına.
Ah, bir göstermedin kendini,
Sakladın kendini…
Yazdım ben de şiirlere adını…
Karaladım, belki bir gün okursun diye…

— Gülizar Karataş', 'BÜŞRA ❤️ Bilmezdim sevdaya düşmeden önce, Üşümezdi ellerim, yüreğim… Şahit oldu şimdi kelimelerim. Ruhuma işledi sana olan sevgim. Anlamanı ...', ARRAY['Türk Edebiyatı','Şiir','Gülizar Karataş']::text[], 8.5, '{"poet":"Gülizar Karataş","poet_slug":"gulizar-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/busra-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok 2', 'yok-2-hakan-dincel-rcm12', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'YOK

Yokluğunun tarifi yok,

yoksan hayatın tadı tuzu, anlamı yok.

Yoksun,

zamanın bile dayanası yok.

Yokluk,

senin gibi bir başkası yok...', 'YOK Yokluğunun tarifi yok, yoksan hayatın tadı tuzu, anlamı yok. Yoksun, zamanın bile dayanası yok. Yokluk, senin gibi bir başkası yok......', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yok-2-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buz', 'buz-hakan-dincel-fhqzp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BUZ

Seninle konuşurken o an,

bir su gibi çağlar kelimeler.

Nasılda tarifsizdir yaşanan,

geçmez,

akmaz,

sanki buz olur,

donar saniyeler...', 'BUZ Seninle konuşurken o an, bir su gibi çağlar kelimeler. Nasılda tarifsizdir yaşanan, geçmez, akmaz, sanki buz olur, donar saniyeler......', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/buz-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARAKTERİMİN HÜKMÜ', 'karakteri-mi-n-hukmu-muhsin-yener-2-jj29b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hiç kimseye kötü söz etmem,
Bu, ne dilime yakışır ne karakterime.
Kin taşımak, gönül karartmak değildir huyum;
Ben hesabı insana değil, vicdanıma veririm.

Şeytan da bir zamanlar melekler arasındaydı,
Lakin yolunu seçmek kendi iradesindeydi.
Benim de önümde nice yollar durur,
Kime uyacağım, hangi yolda yürüyeceğim benim elimdedir.

Allah insana akıl vermiş, fikir vermiş,
Düşünsün, sorgulasın, hakikati bulsun diye.
Her söylenene inanmak, her izden gitmek değil;
İnsanı insan yapan, iradesiyle seçtiği yoldur.

Ben kimseyi kötülemem, kimseye düşman olmam,
Herkesi kendi vicdanıyla baş başa bırakırım.
Çünkü insanın gerçek aynası sözleri değil, özüdür;
Ben de karakterimi kimsenin kötülüğüne değişmem.

Muhsin Yener', 'Hiç kimseye kötü söz etmem, Bu, ne dilime yakışır ne karakterime. Kin taşımak, gönül karartmak değildir huyum; Ben hesabı insana değil, vicd...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/karakterimin-hukmu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok', 'yok-hakan-dincel-sjb9w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'YOK

Ne olur ki,

senin için,

hayal bile olmasam.

Bana bakmasan,

benimle konuşmasan,

yanımda olmasan,

yapayalnız kalsam.

Ne olur ki,

yok mu olur sevdam...', 'YOK Ne olur ki, senin için, hayal bile olmasam. Bana bakmasan, benimle konuşmasan, yanımda olmasan, yapayalnız kalsam. Ne olur ki, yok mu ol...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yok-630-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamam', 'unutamam-hakan-dincel-t8tpz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'UNUTAMAM

Boğazımda takılı kalan,

göğsümü sıkıştıran,

nefesimi tutan,

beni,

tir tir titreten,

gözlerimden,

usul usul süzülen,

nazlı bir aşksın sen.

Biliyorum,

sana kavusamam.

Ama bil  ki ,

birgün,

kaybolsa hafızam,

yine seni unutmam...', 'UNUTAMAM Boğazımda takılı kalan, göğsümü sıkıştıran, nefesimi tutan, beni, tir tir titreten, gözlerimden, usul usul süzülen, nazlı bir aşksı...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/unutamam-207-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Izdırap', 'izdirap-hakan-dincel-09tlk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'IZDIRAP 

Seni görmeden,

duymadan,

nefesin,

yüzüme çarpmadan,

aynı şehirde olmak,

nasıl bir ceza,

nasıl bir ızdırap?', 'IZDIRAP  Seni görmeden, duymadan, nefesin, yüzüme çarpmadan, aynı şehirde olmak, nasıl bir ceza, nasıl bir ızdırap?...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/izdirap-105-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kördüğüm', 'kordugum-hakan-dincel-h7z2z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'KÖRDÜĞÜM 

Son kez,

günaydın dediğinde bana,

bilemezdim,

güneşin bir daha ışıtamayacağını  günümü,

istesede ısıtamayacağını artık  gönlümü,

bilemezdim ki,

hayatımdaki çözülmez  kördüğümü. 

Bilemezdim,

kendini benden alıp,

uzaklara götürdüğünü,

bilemezdim,

üzerimi soğuk Ekim toprağıyla örttüğünü,

boynunu bükmüş,

çaresiz bir başak gibi,

yere düşüp öldüğümü...', 'KÖRDÜĞÜM  Son kez, günaydın dediğinde bana, bilemezdim, güneşin bir daha ışıtamayacağını  günümü, istesede ısıtamayacağını artık  gönlümü, b...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kordugum-393-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Bahar', 'yalanci-bahar-harun-celik-3-gxtol', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlamıyorsun bu hayattan neler çektim

Ya işine gelmiyor ya da beni istemiyorsun

Hep bir bahane hep bir serzeniş var sende

Neden kanıtlamak zorundayım kendimi yine

Ölsem umurunda değil nasıl yalandan sevebildin

Nasıl bu aşkı idare ettin sonunu bile bile

Kalpte derman yürekte ferman kalmadı yalancı bahar

Kaç çiçek soldu bahçemde senden kalan koca bir mezar', 'Anlamıyorsun bu hayattan neler çektim Ya işine gelmiyor ya da beni istemiyorsun Hep bir bahane hep bir serzeniş var sende Neden kanıtlamak z...', ARRAY['Türk Edebiyatı','Şiir','Harun Çelik 3']::text[], 8.5, '{"poet":"Harun Çelik 3","poet_slug":"harun-celik-3","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalanci-bahar-152-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kül', 'kul-hakan-dincel-mtjn7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'KÜL 

Bir baktın ki bana,

kapıldım,

dayanamadım aşkına.

Yaktın,

yavaş yavaş,

her bakışla.

Kül oldum,

gel artık,

savur aşkımı rüzgarlara...', 'KÜL  Bir baktın ki bana, kapıldım, dayanamadım aşkına. Yaktın, yavaş yavaş, her bakışla. Kül oldum, gel artık, savur aşkımı rüzgarlara......', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kul-268-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşun', 'kursun-hakan-dincel-jqubb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KURŞUN 

Yüreğimin yerinde, 

barut ve kan kokusu.

Bir ağırlık göğsümde,

kesiyor sanki soluğu.

Sevgili,

tek kurşunla,

aşk evini vurdu.

Paramparça duygular,

kaybolmuş hayaller,

apansız,

ortalığa savruldu.

Sanki aşk evinde,

kendisinin olduğunu bilmiyordu.

Tek kurşunla,

kalbi vurdu,

tek kurşunla,

ortadan kayboldu...', 'KURŞUN  Yüreğimin yerinde,  barut ve kan kokusu. Bir ağırlık göğsümde, kesiyor sanki soluğu. Sevgili, tek kurşunla, aşk evini vurdu. Parampa...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kursun-114-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen 2', 'sen-2-hakan-dincel-3nkud', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'SEN 

Geldin,

vuruldum,

dondum.

Gittin 

vuruldum,

öldüm...', 'SEN  Geldin, vuruldum, dondum. Gittin  vuruldum, öldüm......', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-2-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Kulesi', 'kiz-kulesi-hakan-dincel-jtvdw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'KIZ KULESİ 

Sen dumanı üstünde tüten bir aşksın.

Kız kulesi kadar güzel, 

kız kulesi kadar yalnız.

Kalabalığın ortasında ,

İnadına dimdik, 

inadına güçlü,

inadına varsın...', 'KIZ KULESİ  Sen dumanı üstünde tüten bir aşksın. Kız kulesi kadar güzel,  kız kulesi kadar yalnız. Kalabalığın ortasında , İnadına dimdik,  ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kiz-kulesi-103-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğul', 'ogul-rumeysa-haksever-ipdli', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zamansız düştüm, sen bana doymadan,

Küçüktü ellerin, kaldırmaya yetmedi oğul.

Şükür ki senin acını göstermedi yaradan,

Sen de ondan gelene şikâyet etme oğul.

​Ana koynu şefkatlidir, elbet sen de ararsın,

Toprak senden önce buldu, arama oğul.

Fotoğrafım yoktu ki yüzümle avunasın,

Mezar taşımda mı sana yetmez oğul?

​Oysa sana yakını dilemiştim, ırağa düştüm,

Alnına gurbet yazılmışsa, kul silemez oğul.

Kahrı da gördüm ben, aşkı da süzdüm,

Sevenlere bunca cefa az gelir oğul.', 'Zamansız düştüm, sen bana doymadan, Küçüktü ellerin, kaldırmaya yetmedi oğul. Şükür ki senin acını göstermedi yaradan, Sen de ondan gelene ş...', ARRAY['Türk Edebiyatı','Şiir','Rumeysa Haksever']::text[], 8.5, '{"poet":"Rumeysa Haksever","poet_slug":"rumeysa-haksever","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ogul-fikriye-yildirim-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-hakan-dincel-nyayd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'AŞK 

Rüyaların, hayallerin içinde,

çıkmaz bir sokaktır aşk. 

Birliktelik, mutluluk gelmez  gittikleri yerden.

Acı çekilir hesapsız,

ve hissedilir ta derinden.

Gözyaşı olmuş kaderi,

görülmedi mutlu biteni.

Tek başına yaşanır,

tek kişiliktir aşk.

Değişmez yorma kendini...', 'AŞK  Rüyaların, hayallerin içinde, çıkmaz bir sokaktır aşk.  Birliktelik, mutluluk gelmez  gittikleri yerden. Acı çekilir hesapsız, ve hisse...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ask-4144-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçeklerim', 'ciceklerim-adnan-hacigumus-i47wa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir saksı fesleğen ektim
bir saksı karanfil
büyüyüp açıyorlar şimdi
önünde penceremin
koklaşarak
konuşarak başlıyoruz güne
düşlerini anlatıyorlar bana
yeşil yeşil pembe pembe
yaşamak doluyor içime', 'bir saksı fesleğen ektim bir saksı karanfil büyüyüp açıyorlar şimdi önünde penceremin koklaşarak konuşarak başlıyoruz güne düşlerini anlatıy...', ARRAY['Türk Edebiyatı','Şiir','Adnan Hacıgümüş']::text[], 8.5, '{"poet":"Adnan Hacıgümüş","poet_slug":"adnan-hacigumus","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ciceklerim-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerze', 'gerze-hakan-dincel-at29l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'GERZE 

Bir martının, 

deryayı ikiye bölen,

kıpkızıl bir çizginin yanıbaşında,

sabahki telaşıdır sanki Gerze.

İnce fikirli insanları gibi,

İncecik simidi ve mis kokulu nokulu ile,

dostun dizinin dibinde,

doyumsuz bir ziyafettir belkide.

Bir balıktır, 

gönüllerde tutulan,

ve ağız tadında sohbetlerde kavrulan.

Boğazdan kayarak  aşağı iner,

muhabbetle gider yutulan.

Bahçesinde fasulye, 

dağlarındaki örtü  kadar yeşil.

Ve gizli bir şelaledir, 

bulun diye bekleyen.

Bir o kadar bakir,

ve bir o kadar da mağrur bir ışıktır, 

hırçın, asil bir denizden,

masmavi gözlere akseden,

ve ansızın misafir yüreklere işlenen...', 'GERZE  Bir martının,  deryayı ikiye bölen, kıpkızıl bir çizginin yanıbaşında, sabahki telaşıdır sanki Gerze. İnce fikirli insanları gibi, İn...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gerze-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ilgaz', 'ilgaz-hakan-dincel-eexkv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ILGAZ 

Havası sert, insanı mert, çayı sımsıcaktır ılgaz`in.

Demlenir gönüllerde, bir karşılık olmaksızın.

Ulu ulu çamlar, sanki sohbet eder,

Yanı başında yüce dağların.

Buz gibi sular çağlar, ortasında 

yemyesil yaylaların.

Temmuzda Kırkpınar''da kar yemek,

saçaklı mantar peşinden kaybolurcasina gitmek,

ellerin dona dona doruktan aşağı inmek.

İlaçtır kadınçayırında çay içmek,

Avucunda bir bardak sıcaklıkla,

ruhunu dinlendirmek.

İlgaz da hem kış, hem de yaz,

maceraya sürükler insanı,

tarifsiz, doyulmaz.

Can dostlarla yaşanır Ilgaz,

ve bir ömür boyu  unutulmaz...', 'ILGAZ  Havası sert, insanı mert, çayı sımsıcaktır ılgaz`in. Demlenir gönüllerde, bir karşılık olmaksızın. Ulu ulu çamlar, sanki sohbet eder,...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ilgaz-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hülâsa-i Muhabbet', 'hul-sa-i-muhabbet-saliha-ravza-olgun-28pk0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Muhabbet;

Bir sadakat ağacı,

Dalları ihtimam,

Yaprakları hürmet,

Meyvesi sevgidir.

Sessiz Şahit', 'Muhabbet; Bir sadakat ağacı, Dalları ihtimam, Yaprakları hürmet, Meyvesi sevgidir. Sessiz Şahit...', ARRAY['Türk Edebiyatı','Şiir','Saliha Ravza Olgun']::text[], 8.5, '{"poet":"Saliha Ravza Olgun","poet_slug":"saliha-ravza-olgun","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hulasa-i-muhabbet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gece daha ğecti', 'bir-gece-daha-gecti-ufuk-tan-bbk1z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bu  ğece   uyumak  için  uzandım

saatler   dakıkalar   sanıyeler  ğecti

uyuyamadım   gece  hep   seni    düşündüm

gözlerimi actım  sabah olmuş  şaşırdım

hayallerimle  dolu     bir  ğece  ğecti

ve  dünde  kaldı  dün  gece  rüya gördum

çok  mutlu   oldum    seni  gördüm  aşkım

bana   elini  uzatıyordun  deniz  kenarında

dün  bitti   bugün  gecti ve  yarın  oldu

hayımızdan  aşkım bir  ğece daha  geçti

birgün  daha bir  ğece  daha  bir  ğece  daha

uyandım  sabah  bir  ğece  daha  gecti

yani   bu  gün  bitti yarın  oldu bebeğim

dün  bu  ğün  yarın  bu  kutsal  üç  gün

beni  bıraktığın yerde  beklicem seni

dün  bitti   bugün  gecti ve  yarın  oldu

hayımızdan  aşkım bir  ğece  daha  geçti

birgün  daha bir  ğece  daha  bir  gece  daha', 'bu  ğece   uyumak  için  uzandım saatler   dakıkalar   sanıyeler  ğecti uyuyamadım   gece  hep   seni    düşündüm gözlerimi actım  sabah olm...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Tan']::text[], 8.5, '{"poet":"Ufuk Tan","poet_slug":"ufuk-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-gece-daha-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz', 'karadeniz-hakan-dincel-hezgb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'KARADENİZ 

Gönlümün derinliğinde, 

gizli kalmış bir aşksın.

Dalgaların kıyıya,

bırak mertçe çarpsın.

Damgasıdir sanki bu,

unutulmaz büyük aşkın.

Nefesleri  keserken buz gibi soğuğun,

ne bir yalan bilirsin,

ne yaparsın bir oyun.

Sinene sarılanı, 

görülmedi kovduğun,

Söylesene bu gönül,

seni nasıl unutsun ?

Göğsüne martılar, 

bir ok gibi girerler.

Nasibinin derdinde,

ağlarını çekenler.

Sevgi dolu,  biraz sert, tertemizdir yürekler.

Neden çekinsin, korksun ki,

seni daim sevenler.

Adın KARA,

soyun engin bir DENİZ.

Dalga dalga gelirsin,

bırakırsın kedersiz.

Yüreğimde aşkındır,

silinmeyen derin bir iz.

Saklı bir giz içimde, 

aşkındır KARADENİZ...', 'KARADENİZ  Gönlümün derinliğinde,  gizli kalmış bir aşksın. Dalgaların kıyıya, bırak mertçe çarpsın. Damgasıdir sanki bu, unutulmaz büyük aş...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/karadeniz-162-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son', 'son-hakan-dincel-12xhc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SON

Çırpınan kollar, emre asi olmak için değilde,

emre rağmen pes etmişken,

yavaş yavaş gömülürken hayaller,

buz gibi soğuk,

bir ayna kadar parlak,

Ve tadıyla ağızlar kurutan,

ve bir anne haykırışında,

yürekler yakan bir gerçeğe ki,

o,  daha yakındır insana,

kendi şah damarından.

Perdeyi aralar gösterir yeniden,

rüya sandığın gerçeği ucundan.

İliklerine kadar hissettirir,

ve kucaklar rahmetiyle,

uzatılan bir elle, 

acizliginde boğar benliğini Yaradan,

ardına bile bakmaya fırsat bulamadan...

Yazmamistir o an için yazıyı yazan,

gelmemiştir vakit,

istesende istemesende alınacak nefes varken,

yenecek rızık, 

konuşacak söz tükenmeden.

Ne olur ki sen tükendi,

ya da hiç tükenmeyecek desen ?

Acziyetini bilmeden kibir dağı olan insan,

ne başlar, ne de biter ömür,

O '' Kün fe yekün '' diye buyurmadan...', 'SON Çırpınan kollar, emre asi olmak için değilde, emre rağmen pes etmişken, yavaş yavaş gömülürken hayaller, buz gibi soğuk, bir ayna kadar ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/son-783-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KİM KONUŞUYOR İŞÇİNİN YERİNE?', 'ki-m-konusuyor-i-sci-ni-n-yeri-ne-muhsin-yener-2-48ksa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Garip bir memlekettir burası,
İşçinin hakkını yönetici savunur,
Fakirin derdini zengin anlatır,
Asgari ücretlinin sofrasından söz eden
Ay sonunda maaşını cebine koyup
Başka bir hayatın kapısını aralar.

Emekçinin nasır tutmuş ellerini
Hiç tutmamış eller kürsülerde konuşur.
Bir lokma ekmeğin hesabını
Hiç yapmamış olanlar,
Yoksulluğun kitabını yazar.

Esnafın siftahsız kapattığı dükkânı
Anlatır başka bir vergi levhasının sahibi.
Kirasını, borcunu, vergisini
Hangi gece düşünerek uyuduğunu bilmeden
Sabah kürsüye çıkar,
Esnafın derdinden söz eder.

Peki, nerede bu insanlar?
Nerede işçinin sesi,
Nerede yoksulun sözü,
Nerede alın teriyle yaşayanların
Kendi hayatını anlatacak cesareti?

Birileri onlar adına konuşur,
Birileri onlar adına karar verir.
Ama nedense
Hep konuşanların hayatı değişir,
Hep susanların kaderi aynı kalır.

Ben derim ki;
İşçinin hakkını işçi anlatsın,
Fakirin derdini fakir söylesin,
Esnaf kendi kepengini açıp
Kendi borcunu, kendi yangınını anlatsın.

Çünkü insan,
Yaşamadığı acıyı ezberleyebilir
Ama o acının ağırlığını bilemez.

Temsil dediğin,
Bir koltuğa oturup
Başkalarının hayatından söz etmek değildir.
Temsil dediğin,
Bir sofrada aç kalanla oturmak,
Bir dükkânda siftah beklemek,
Bir fabrikada alın teri dökmektir.

Ve unutmayın:
Bir memlekette yoksullar susuyor,
Onların yerine varlıklılar konuşuyorsa,
Orada yalnızca temsil eksik değildir;
Orada adalet de eksiktir.

Artık başkalarının hayatını anlatanlar değil,
Kendi hayatını haykıranlar çoğalsın!

Çünkü bu ülkenin
En doğru sözleri,
En yüksek kürsülerden değil,
En nasırlı ellerden yükselecek.

Muhsin Yener', 'Garip bir memlekettir burası, İşçinin hakkını yönetici savunur, Fakirin derdini zengin anlatır, Asgari ücretlinin sofrasından söz eden Ay so...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/kim-konusuyor-iscinin-yerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sel', 'sel-hakan-dincel-jsvnr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SEL

Canlar feda edilir gün gelipde büyüdüğünde,  bir şiir kadar saf, bir yudum su gibi duru güzelliğine, ahlakına, edebine.

En temiz duygular gizlidir, Kırk yıl hatrı olan, o kahverengi göz bebeklerinde.

Yüksek yaylaların karda açan nazlı çiçeği, huzur, sevgi eksik olmaz hiç,  birkez olsun  dilinde.

Leke bulunmaz ne özünde,  ne  de prensesleri kıskandıran bembeyaz teninde.

İliklere işler sesinin tınısı,

söylediği sevda şarkısı yankılanır, pas tutan gönüllerde,

Nasıl hayran etmez ki insanı, zihninin  parıltısı,  narin, naif edası, parmakla gösterilir kalabalıklar içinde. 

Sel olmuş, gürül gürül gelir, apansız doruklardan iner, önünde durulamaz   aşkı,

Elini attığı güzelleşir, renklenir, tatlanır, sanki olur yüksek dağların şifalı balı, 

Lime lime etseler,  ayrılmaz doğrudan,  sevindirmez hayini arsızı,

En sevilendir herzaman, korunur, kollanır dua ile, kem gözlü  deydiremez  nazarı, 

Nasip olsun  gönlündeki, ayrılmasın hak yolundan, hiç bırakmasın elini aşığı', 'SEL Canlar feda edilir gün gelipde büyüdüğünde,  bir şiir kadar saf, bir yudum su gibi duru güzelliğine, ahlakına, edebine. En temiz duygula...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sel-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seçim her zaman sizin.', 'secim-her-zaman-sizin-muhsin-yener-2-igrd4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Toplum içinde insanın en çok etkilendiği şeylerden biri, kimlerle oturup kalktığıdır.
Hz. Mevlana''nın yüzyıllar öncesinden bugüne uzanan bir uyarıda bulunur İnsan, bulunduğu meclisin rengini alır.

Cahil ve düşünmeden konuşan insanların arasında uzun süre kalırsanız, bir süre sonra sizi de kendileri gibi zannetmeye başlarlar.

Üstelik bununla da kalmaz, anlamadıkları her şeyi küçümseyip alaya almayı marifet sayarlar.

Çünkü cehalet çoğu zaman gürültülüdür; kendini bilgi gibi sunar ama içi boştur. Böyle bir ortamda ne düşünce gelişir ne de insan kendini inşa edebilir.

Oysa akıllı, bilgili ve erdem sahibi insanların bulunduğu meclisler bambaşkadır. Orada söz tartılır, fikirler olgunlaşır, insan kendini sorgular ve geliştirir.

Bu tür ortamlarda bulunmak, insanın ufkunu genişletir; onu daha derin, daha anlayışlı ve daha bilinçli bir hale getirir.

Kısacası mesele sadece kimlerle vakit geçirdiğiniz değildir; aslında kim olduğunuzu da belirleyen bir tercihtir bu. Ya sizi aşağı çeken bir kalabalığın parçası olursunuz ya da sizi yukarı taşıyan bir çevrenin.

Seçim her zaman sizin.
Muhsin yener', 'Toplum içinde insanın en çok etkilendiği şeylerden biri, kimlerle oturup kalktığıdır. Hz. Mevlana''nın yüzyıllar öncesinden bugüne uzanan bir...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/secim-her-zaman-sizin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gül', 'kara-gul-hakan-dincel-81z63', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KARA GÜL 

Aşık olduysan kara gözlü, minik elli güzeli Yaratana, 

Yüreğinin derinliklerinden kopan,

bir mutluluk getirmek istersin,

o özene bezene yaratılana.

Senden bir çöp bile istese,

belkide seviyordur dersin, emin olamasanda.

Seviyor ki benden istiyor dersin, 

için kıpır kıpır, mahçup bir umutla, 

Seviyor dersin, benim onu sevdigim kadar olmasada. 

Seversin, vazgecemezsin, gözlerinin önünden gitmez ki hayali.

O kaçsa, görmek istemese, yüz çevirse bile senden.

Sarılıp, doya doya cennet kokusunu almak istersin,

O tertemiz kara gülden,

Bir şimşek gibi çakıp, seni yakmak istemesinden bile çekinmeden.

Ürkek bir tavşan gibi yaklaşırsın,

Dünyanın en güzel çiçeğine.

Sevginle üzmekten, incitmekten korkarsın istemesende. 

Dokunamazsın, bir kuş tüyü kadar hafif ve narin bedenine, 

Ve bakamazsın bir elmas gibi parlayan, 

sanki ceylanlardan ödünç alınmış gözlerine. 

Gün gelip de anlasın diye kalbinde olanı,

Kabul olsun, gecenin sessizliğinde bozmasın diye,

yakarılan duayı,

Bir an susturursun avaz avaz özlemle,

sol yanında çarpıp duran, 

O ipekten yapılmış, usul usul kanayanı...', 'KARA GÜL  Aşık olduysan kara gözlü, minik elli güzeli Yaratana,  Yüreğinin derinliklerinden kopan, bir mutluluk getirmek istersin, o özene b...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kara-gul-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hz. Mevlana', 'hz-mevlana-muhsin-yener-2-wcepb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hz. Mevlana''nın sözü düşer içime
sessiz ama derin bir uyarı gibi
aynı masada oturduğun insanlar
bir gün aynaya dönüşür
ve sen, fark etmeden
onların gözünden bakarsın kendine.

cahilin gürültüsü boldur,
söz çoktur, anlam yoktur
gülüşleri keskin bir bıçak gibi
inceltir insanın saygısını.

bir süre sonra
sen konuşmasan bile
seni de onlar gibi sanırlar
ve en acısı
sen de kendinden şüphe etmeye başlarsın.

oysa akıllı insanın yanında
kelimeler bağırmaz
sessizlik bile öğretir
insan, insanın aynasıysa
orada yüzün derinleşir.

seçtiğin meclis
kaderine yazılmış bir imza gibidir
ya kendini kaybedersin kalabalıkta
ya da kendini bulursun
bir avuç hakikatin içinde.
Muhsin yener', 'Hz. Mevlana''nın sözü düşer içime sessiz ama derin bir uyarı gibi aynı masada oturduğun insanlar bir gün aynaya dönüşür ve sen, fark etmeden ...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hz-mevlana-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İpekten Yaren', 'i-pekten-yaren-hakan-dincel-5tgfr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İPEKTEN YAREN

İpekten narin bir yolda, 

yürürken yareninle  yanyana.

Ve nefes nefese aşıkken,

kalbinde de ufacık bir umutla.

Bilemezsin, fermanın yazılmıştır belkide, 

bir kalemin ucunda.

Masum bir çizgidir, 

dökülür körpe parmaklardan.

Ve seni tutup elinden,

apansız gökyüzüne çıkaran.

Zihninde hayali, kalbinde oyunlar oynar,

mutluluktan uykusuz bırakan.

Gözlerde saklanan gerçektir,

kolları sımsıkı bağlayan.

Dokunamazsın artık , lal olmuştur bülbül gibi şakıyan.

Saf, tertemiz bir ödüldür belkide,

Sanki ipek kozasında saklanan.

Gözünün önünden gitmez tek bir an, 

ne yaren,  ne de  yaran.

Kendi kendine sorup durduğun, 

bir sorudur artık o.

Uykusuz gecelerde, defalarca yüreğine saplanan...', 'İPEKTEN YAREN İpekten narin bir yolda,  yürürken yareninle  yanyana. Ve nefes nefese aşıkken, kalbinde de ufacık bir umutla. Bilemezsin, fer...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ipekten-yaren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöp Torbası Kadar Sevgi', 'cop-torbasi-kadar-sevgi-muhsin-yener-2-a9mul', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '"Ben biraz dışarı çıkıyorum..."
dersin usulca bir gün,
Kapı daha aralanmadan
bir el uzanır o an.

Elinde;
her evin sessiz kahramanı,
bir çöp torbası vardır...
İşte o an anlarsın.

Sevgi bazen
büyük sözlerle gelmez;
Bir poşetin ağzına düğümlenir,
avuçlarına bırakılır.

Çünkü seni düşünen insan,
seni hiçbir zaman
eli boş uğurlamaz;
sevgi bazen budur.

"İyi gez." demek de sevgidir elbet,
ama en içten cümle bazen;
"Şunu da atıver." olur,
yüzünde bir tebessüm belirir.

Evde görev dağılımı
ne toplantıyla yapılır,
ne de kanunla yazılır;
hayat kendi kararını verir.

Kim dışarı çıkıyorsa,
çöp ona emanet edilir.
Bu sessiz anlaşmayı
herkes gülümseyerek bilir.

Özgürlük güzeldir elbet...
Fakat kapıdan çıkarken,
eline tutuşturulan o torba,
özgürlüğünün ince dipnotudur.

Gülümsersin...
Çöpü atarsın,
geri dönersin eve;
ve bir kez daha anlarsın.

Bir evde en çok güvenilen kişi,
anahtarı taşıyan değil;
çöpü itiraz etmeden
götüren kişidir.

İşte bazen
sevginin ağırlığı,
bir çöp torbası kadardır...
Ama değeri, bir ömür eder.

Sevgi bazen çöp torbası kadar sade,
güven ise bir ömür taşıyacak kadar ağırdır.
Muhsin yener', '"Ben biraz dışarı çıkıyorum..." dersin usulca bir gün, Kapı daha aralanmadan bir el uzanır o an. Elinde; her evin sessiz kahramanı, bir çöp ...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/cop-torbasi-kadar-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çay', 'cay-hakan-dincel-awds6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ÇAY 

Şarkılar, şiirler ateşinle yazıldı.

Derdi dinlemene sessizce,

mutluluğu paylaşmana şiirce,

ne ocaklar yakıldı.

Belkide ay, kıskanmiştı yalnızca seni.

Çünkü tek harfle geçtin ondan ileri.

Ve  kıskanırdı,

ağır ağır demlenip beklemeni.

Aşığın sıcacık tutmasını belini,

sıcak sıcak ,

sevenlerin gönlüne girmeni.

Mutluluğa mutluluk eklemeni, mutsuzluğu bölüp eksiltmeni.

Kıskandı belki ay, 

ilk ve son defa seni.

Zümrüt yesiliyken, kapkara kesilmeni,

muhabbetle,  her nefeste içe çekilmeni.

Zenginle, fakirle,

aşıkla, masukla,

dostla, düşmanla bir araya gelmeni,

aşk ile ateşlere girmeni,

aşığın elinde şerbet lezzetini,

dertlinin elinde,

kan kırmızı kesilmeni.

Açıkmış, koyuymuş,

her hali ayrı güzel rengini.

Kıskandı ay belli, 

çok kıskandı seni...', 'ÇAY  Şarkılar, şiirler ateşinle yazıldı. Derdi dinlemene sessizce, mutluluğu paylaşmana şiirce, ne ocaklar yakıldı. Belkide ay, kıskanmiştı ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cay-183-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TOPLUMUN AYNASI', 'toplumun-aynasi-muhsin-yener-2-7r93t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Toplumun aynasına
bakmaya cesaretimiz var mı?

Yoksa gördüğümüz manzarayı
görmezden gelmeyi mi tercih ediyoruz?

Edebiyat yok…
Felsefe yok…
Mantık yok…
Demokrasi kültürü yok…
Adalet yok…
Muhakeme yok…

Peki, ne var?

İnsanı yakacak kadar gözü dönmüş bir vahşet,
çocuklara uzanan kirli eller,
kadına yönelen bitmek bilmez şiddet,
çocuk yaşta evlendirilen hayatlar…

Diğer yanda
yalanı, dolanı ustalık sayanlar;
çıkarı erdem,
sahtekârlığı başarı sananlar…

En acısı da ne biliyor musunuz?

İnsanın kendi özüne,
kendi evladına,
kendi annesine bile
ihanet edebilecek kadar çürümesi…

Bu tabloyu yalnızca suçlular üzerinden okumak kolay.
Oysa asıl mesele;
bu çürümeye göz yuman,
alışan,
hatta onu normalleştiren zihniyettir.

Mafya düzeni,
terörün gölgesi,
uyuşturucunun bataklığı,
rüşvetin kirli çarkı…

Bunların hepsi birer sonuç.

Ya sebep?

Değerlerin sistemli biçimde yok edilmesi,
ahlakın küçümsenmesi,
eğitimin içinin boşaltılması…

Daha da vahimi;

Lüks otel masalarında,
şaşaalı sofralarda,
rüşveti sıradanlaştıran,
yolsuzluğu makyajlayan,
topluma kötü örnek olan
bir anlayışın alkışlanması…

Bugün geldiğimiz noktada
mesele yalnızca kötü insanların varlığı değil.

İyi insanların sessizliği,
vicdanların suskunluğu,
doğrunun sahipsiz bırakılmasıdır.

Çünkü bazen kötülük,
yapanların cesaretinden değil,
karşısında susanların sessizliğinden güç alır.

Unutmayalım…

Bir toplum edebiyatını kaybederse
duygularını,
felsefesini kaybederse
sorgulama yeteneğini,
adaletini kaybederse
vicdanını kaybeder.

Ve sonunda
yalnızca kültürünü değil,
insanlığını da yitirir.

İnsanlığını kaybeden bir toplumda
hiçbir başarı,
hiçbir zenginlik,
hiçbir şaşaalı gösteriş
o büyük boşluğu dolduramaz.

Çünkü bir toplumun gerçek zenginliği
sarayları, sofraları, servetleri değil;
adaleti, ahlakı ve insan kalabilme erdemidir.

Muhsin Yener', 'Toplumun aynasına bakmaya cesaretimiz var mı? Yoksa gördüğümüz manzarayı görmezden gelmeyi mi tercih ediyoruz? Edebiyat yok… Felsefe yok… Ma...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/toplumun-aynasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cellat', 'cellat-hakan-dincel-cbiuc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'CELLAT 

Kimi icin can veren can dostudur,

Kimi için can alan bir cellat.

Var git sen kararını ver, sonra gel bunu vicdanına anlat. 

Doğruyu bilmek acıdır bazen, 

acıtır yüzüne yüzüne  söylenen.

Kulaklarını tıkar, dönersin arkanı, hatanı görmek istemeden.

İster ki pofpoflansin hep nefsin,

yanlışının söylenmesini hiç istemezsin.

Var mı hiç, hatam nedir diye soran,

Egolar olmamış mı  herkeste  tavan.

Unutmuşuz, birlikte olmaz yalanla iman,

Yaratılanların hayrına doğruyu söyle, 

doğruyu yap buyurmadı mı  YARADAN...', 'CELLAT  Kimi icin can veren can dostudur, Kimi için can alan bir cellat. Var git sen kararını ver, sonra gel bunu vicdanına anlat.  Doğruyu ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cellat-65-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aslan Mehmed’in İzinde', 'aslan-mehmed-in-i-zinde-muhsin-yener-2-z3w8e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sabah vaktiydi,
ufukta kara duman,
kapıya dayanmıştı
arsız emperyalist zaman…

Fakat bu topraklarda
uyuyan millet olmazdı,
damarında tarih akan
bir yiğitlik dolaşırdı.

Kimi Mustafa Kemal’di,
kimi adsız bir nefer,
kimi “Aslan Mehmed” olup
yürürdü ölüme kadar.

Edirne’den Kars’a dek
aynı dua yükseldi,
Alevi’si, Sünni’si
aynı safta kenetlendi.

Köylüyle şehirli bir,
aynı sancak altında,
vatan dediler çünkü
ölüm durmuş kapıda.

Top sesleri yankılanır,
yer gök titrerken o an,
yalnız mermi değildi o
haykırıyordu iman.

“Ya istiklal ya ölüm!”
dağ taş duydu sesini,
düşerken bile vurdular
çiğnetmediler izini.

Çanakkale dedikleri
bir savaş değildir yalnız,
bir milletin karakteri,
bir milletin alın yazısıdır biraz.

Kanla sulandı toprak,
bayrak göğe yükseldi,
dünya gördü o gün
Türk milleti diz çökmedi.

“Aslan Mehmed” bir kişi değil,
her yürekte doğan candır,
gerektiğinde kor gibi
milleti ayağa kaldırandır.

Bugün bize düşen görev
o ruhu unutmamak,
geçmişin kutlu izinden
yarınlara yürümektir ancak.

Ruhları şad olsun…
Toprak onları unutmaz,
çünkü vatan uğruna düşenler
ölmez yalnızca bayraklaşır.
Muhsin yener', 'Bir sabah vaktiydi, ufukta kara duman, kapıya dayanmıştı arsız emperyalist zaman… Fakat bu topraklarda uyuyan millet olmazdı, damarında tari...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/aslan-mehmed-in-izinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAVİ BERELİ OLMAK', 'mavi-bereli-olmak-muhsin-yener-2-ok7rh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dağın zirvesinde kurulan bir yuvayı
herkes anlayamaz.
Çünkü orası sadece taşın,
rüzgârın ve sessizliğin değil;

aynı zamanda inancın,
cesaretin ve adanmışlığın mekânıdır.
Kartallarla dost olmak,
bulutlarla konuşmak;

bir hayal değil,
bir yaşam biçimidir mavi bereli için.
O yüksekliklerde insan,
sadece doğayla değil,

kendi yüreğiyle de
baş başa kalır.
Mavi bereli olmak,
dışarıdan bakıldığında bir üniforma gibi görünse de;

aslında bir ruh hâlidir.
Fedakârlığın, disiplinin
ve vatan sevgisinin
en saf hâlidir.

Herkesin uykuda olduğu saatlerde
gözünü kırpmadan nöbet tutmak;
sadece bir görev değil,
bir milletin huzuruna
sessizce sahip çıkmaktır.

Bir elinde silah,
diğer elinde yüreğiyle durur o.
Çünkü bilir ki;
asıl güç, taşıdığı silahta değil,

kalbinde taşıdığı
vatan sevgisindedir.
Gün gelir,
bu sevda uğruna
en ağır bedeli ödemekten çekinmez.

Ya vurur,
ya vurulur.
Ama asla
geri adım atmaz.

Ve bu toprakların
değişmeyen gerçeğidir:
Bir mavi bereli şehit düşerse,
onun yerini dolduracak
binlercesi doğar.

Çünkü bu sevda,
bir kişiye sığmayacak kadar büyüktür.
Bayrak dalgalandıkça,
bu ruh
yaşamaya devam eder.

Bu yüzden
mavi bereli olmak kolay değildir.
Ama bir o kadar da onurludur.

Çünkü onların hikâyesi,
sadece bir askerlik hikâyesi değil;
bir milletin dimdik ayakta kalma hikâyesidir.
Muhsin yener ✍️', 'Dağın zirvesinde kurulan bir yuvayı herkes anlayamaz. Çünkü orası sadece taşın, rüzgârın ve sessizliğin değil; aynı zamanda inancın, cesaret...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/mavi-bereli-olmak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk Ateşi', 'dostluk-atesi-hakan-dincel-f7qyi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'DOSTLUK ATEŞİ

Soğuk bir sonbahar akşamında,

dostluğun ateşi ısıtırken yürekleri doyasıya.

Yaseminlerin, gönülleri bayıltan, o eşsiz  kokusunun yanı başında, 

Çiçeklerin en güzeli, asil bir gülsün sen, çakır da gözlü gülsümüm  ,  diye haykırır gözleriyle  sanki yarenin,

İpekten  örülmüş, 

doyumsuz bir sohbetin ortasında.

Aşkın yüce doruklarından, 

sel en derin duyguları, 

narin,  minik bir dağ berilini sürükleyip getirir gibi getirir, bergenlerin elinden adeta,

sevda vurgunu yiyen gariplerin, 

Hakanının yanına.

Sihirli bir su de, naz de istersen, aşığın çatlayıp kurumuş  dudaklarına

azar azar  damlatılana.

Ali Osmanlı erkanından  gelen bir ruh de istersen,

Aşığın kalbini dağlar, sanki okunun ucu dedem Selçugun , 

otagda oturan masum Begüm Sultan''ın yanında.

Herşeye rağmen,  büyük bir özlemle ve sabırla  beklenilen mesut yarınlarda,

bil al denilen bir sorunun ödülüdür belkide eymene verilen,

ağızlarin  mühürlenip,

sözün bittigi , 

mizanın  başında,  ukbada.', 'DOSTLUK ATEŞİ Soğuk bir sonbahar akşamında, dostluğun ateşi ısıtırken yürekleri doyasıya. Yaseminlerin, gönülleri bayıltan, o eşsiz  kokusun...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/dostluk-atesi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar', 'yollar-hakan-dincel-210up', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'YOLLAR 

Yollar gidilir dikenler engeller arasından,

Gidilir bitmez yollar,

göz gözü görmez,

dost dostu görür,

sisin pusun ortasından.

Varmak için vuslata,

çekilir, dayanılır türlü derde,

türlü acıya.

Yol yürünür sabırla,

vazgeçmeden, dimdik, inatla.

Sırt çevrilince karanlığa,

ulaşılır, varılır, yüz parlatan bir aydınlığa.

Böyle yazılmış zorlu kural,

böyledir bu değişmez sınav.

Olsanda son anda, bir elif gibi yalnız başına ya da kum gibi kalabalıklar ortasında.

Bir yudum  su götürür seni,

uçsuz bucaksız, sonsuz  bir ummana ...', 'YOLLAR  Yollar gidilir dikenler engeller arasından, Gidilir bitmez yollar, göz gözü görmez, dost dostu görür, sisin pusun ortasından. Varmak...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yollar-488-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'FESLEĞEN GİBİ İNSANLAR', 'feslegen-gi-bi-i-nsanlar-muhsin-yener-2-72scw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatta bazı insanlar vardır,
tıpkı fesleğen gibi…

Dokunulmadıkça
kokusunu vermezler.
İçlerinde taşıdıkları cevheri
hemen açığa çıkarmazlar.

İlk bakışta
diğerlerinden ayırt etmek zordur onları.
Herkes gibi yaşar,
herkes gibi konuşur,
herkes gibi yürürler hayatın içinde.

Ne bir iddiaları vardır
ne de kendilerini göstermek gibi bir dertleri…

Ta ki bir gün,
bir an gelir…

Onlara samimiyetle dokunduğunuzda
içlerinde sakladıkları bir kapı aralanır.

İşte o zaman
uzatırlar ellerini size.
Sevgiyle, şefkatle, merhametle
sararlar yüreğinizi.

Verdikleri şey
sıradan bir ilgi değil,
ruhun derinliklerinden gelen
koşulsuz bir kabulleniştir.

Çünkü onlar,
insanı yalnızca görünen yüzüyle değil,
ruhundaki hakikatiyle tanırlar.

Kendilerini de,
başkalarını da
o derinlikten bilirler.

Onlar;
mutlak sevginin izini sürmüş,
aşkın hakikatine dokunmuş
gönül insanlarıdır.

Böyle insanların yanında
kelimeler azalır,
hisler çoğalır.

Çünkü onlar anlatmaz,
yaşatırlar…

Böyle bir insanla karşılaştığınızda
bunu sıradan bir rastlantı sanmayın.

Biliniz ki
bir sırlar bahçesinin
eşiğine gelmişsinizdir.

O eşikten içeri adım atmak mı,
yoksa geri dönmek mi?

İşte bütün mesele budur…

Çünkü o kapıdan içeri giren,
artık yalnızca başkalarını değil,
kendi ruhunu da görmeye başlar.

Muhsin Yener', 'Hayatta bazı insanlar vardır, tıpkı fesleğen gibi… Dokunulmadıkça kokusunu vermezler. İçlerinde taşıdıkları cevheri hemen açığa çıkarmazlar....', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/onlar-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostluk', 'dostluk-hakan-dincel-nna5u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'DOSTLUK 

Dostluk,

ne birlikte gezmede,

ne parada, ne mülkde,

ne de beraber yenilen bir yemekte. 

Dostluk, olabilmektir kara günde,

çok uzaklardayken bile, hep birlikte.

Dostluk, 

aniden çakılan bir kıvılcım,

hissedersin taa iliklerde.

Nefessiz kalmak degil,

soğuk boğar onu,

buz gibi olmuş, kaskatı yüreklerde...', 'DOSTLUK  Dostluk, ne birlikte gezmede, ne parada, ne mülkde, ne de beraber yenilen bir yemekte.  Dostluk, olabilmektir kara günde, çok uzakl...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dostluk-278-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞİİR VE KALP', 'si-i-r-ve-kalp-muhsin-yener-2-fc2yl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kuşlara yazılmıştı çoktan,
uçup giden kanat seslerine...

Ota, toprağa,
çiçeğin sabah çiyine...

Sevgiye yazılmıştı,
sevdaya,
hasrete,
aşka...

İnsan aklına ne gelirse,
neye dokunursa yüreği,
hepsine ama hepsine
çoktan şiirler yazılmıştı.

Ben ne yazayım diye düşündüm.

Sonra anladım;

Şiir,
konunun yeniliğinde değil,
yüreğin sesindeymiş.

Bu yüzden yine yazacağım;

Kuşları da,
çiçekleri de,
sevdayı da,
hasreti de...

Çünkü her kalp,
aynı sözcüklere
başka bir anlam bırakır.
Muhsin yener', 'Kuşlara yazılmıştı çoktan, uçup giden kanat seslerine... Ota, toprağa, çiçeğin sabah çiyine... Sevgiye yazılmıştı, sevdaya, hasrete, aşka......', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/siir-ve-kalp-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ELBET BİR GÜN', 'elbet-bi-r-gun-muhsin-yener-2-fxpc5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevdan değil
başıma gelen
fikrime bir deli kuş konmuş
kanatlarıyla içimi karıştıran
adı konmamış bir rüzgar gibi.

Yüreğimde bir uğultu,
aklımda savrulan tüyler,
her düşünce biraz eksik,
her cümle biraz yarım.

Soruyorum kendime
böyle bir yürekten
zarar gelir mi insana?
Yoksa en çok
kendi yangınında mı ısınır insan?
Belki de bu yüzden
geceler uzun,
kelimeler suskun,
ve ben
kendi içimde dolaşan bir yabancı.

Ama biliyorum
bir gün
bir mısranın ucunda
ben de var olacağım.
Bir şiirin içinde,
adı anılmadan bile tanınan
bir iz gibi,
bir sızı gibi,
bir hatıra gibi.

Elbet ben de
bir gün
bir şiire konu olurum.
Muhsin yener', 'Sevdan değil başıma gelen fikrime bir deli kuş konmuş kanatlarıyla içimi karıştıran adı konmamış bir rüzgar gibi. Yüreğimde bir uğultu, aklı...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/elbet-bir-gun-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-hakan-dincel-556gq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'MERHABA

Geri dönüşler olmasa hayatta,

acıdan, sıkıntıdan mutluluğa,

çekilmez ki bu dünya,

sohbetiyle,

zamanı unutturan,

dostlar olmasa.

Dünyanın nimetlerinden değerlidir,

sıcacık bir selam,

ve samimi bir hatır sorma.

Karnını doyurmaz belki ama,

tüylerin diken diken olur,

dost sana sarıldığında. 

Ne tatlıdır,

dostlarla içilen bir bardak çay.

İçinde şeker olmasa da.

Varlığıyla ömre ömür katan,

yokluğuyla,

çok şeyi  yarım bırakan dostlara,

sımsıcak, 

gönülden bir MERHABA...', 'MERHABA Geri dönüşler olmasa hayatta, acıdan, sıkıntıdan mutluluğa, çekilmez ki bu dünya, sohbetiyle, zamanı unutturan, dostlar olmasa. Düny...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/merhaba-807-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BUZDAN KALELER', 'buzdan-kaleler-muhsin-yener-2-hqb0v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nefret, sevgisizlik ve buz gibi bir soğukluk
Sanki herkes kendi içine çekilmiş, etrafına görünmez duvarlar örmüş.

Kimi zaman bu duvarlar öyle kalınlaşıyor ki, artık insanın insana ulaşması neredeyse imkansız hale geliyor. Herkes kendi buzdan kalesinde yaşıyor; dışarıdan güçlü görünen ama içten içe kırılgan ve yalnız.

Selam yok.
Tebessüm yok.
Hoşgörü yok.
Ve en acısı, kendisinden başka kimseye saygı yok.
Günümüz insanı, işte böyle bir toplumun içinde yaşamaya alışır oldu.

Aynı masayı paylaştığı arkadaşını sevemiyor, aynı işi yaptığı meslektaşını rakip olarak görüp içten içe uzaklaşıyor. Birlikte üretmek yerine birbirini tüketen bir anlayış hakim.

İnsan, insana yabancılaşıyor.
Peki neden?
Çünkü içimizde büyüttüğümüz huzursuzluğu tanımıyoruz. Adını koyamadığımız bir eksiklik, bastırdığımız bir öfke, fark etmediğimiz bir yalnızlık.

Bunlar zamanla sevginin önüne geçiyor. İnsan, kendi içindeki karanlıkla yüzleşemedikçe başkasına ışık olamıyor.
Oysa mesele bu kadar karmaşık değil.

İnsan, insanı sevebildiği kadar insandır.
Bir selamla başlar her şey.
Bir tebessümle yumuşar mesafeler.
Bir anlayışla çözülür düğümler.

Belki de ihtiyacımız olan şey, yeniden hatırlamak.

Sevmenin bir zayıflık değil, aksine en büyük güç olduğunu hatırlamak. İçimizdeki o buzdan kaleleri eritmek ve yerlerine küçük de olsa sıcak birer yuva kurmak.

Ah, bir gerçeğe dönebilsek
Hatalarımızı fark edip, içimizdeki o soğukluğu çözebilsek.

Sevginin sıcaklığını yeniden hissedebilsek…
İşte o zaman, sadece kendimiz değil, içinde yaşadığımız toplum da değişmeye başlayacak.

Çünkü sevgi bulaşıcıdır. Bir kişiden diğerine geçer, çoğalır, büyür.
Ve belki o gün, buzdan kaleler yerini insan sıcaklığına bırakır.
Muhsin yener', 'Nefret, sevgisizlik ve buz gibi bir soğukluk Sanki herkes kendi içine çekilmiş, etrafına görünmez duvarlar örmüş. Kimi zaman bu duvarlar öyl...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/buzdan-kaleler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret 2', 'hasret-2-hakan-dincel-ln4a7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'HASRET 2

Belkide,

kardan sonra en çok,

yaprakların yağması,

mutlu eder çocukları.

Alır,

okşar,

güler, eğlenir,

havalara atarlar onları. 

Bilemezler ki,

her yaprağın üzerinde,

bir ayrılık acısı,

her yaprağın üzerinde,

bir hasret sancısı.

Nereden bilsinler ki çocuklar,

elleriyle anlayamazlar ki,

hüzünleri, acıları. 

Hem de çok seviyor sanırlar,

kendileri gibi başkalarını...', 'HASRET 2 Belkide, kardan sonra en çok, yaprakların yağması, mutlu eder çocukları. Alır, okşar, güler, eğlenir, havalara atarlar onları.  Bil...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hasret-2-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendi Hakikatin', 'kendi-hakikatin-muhsin-yener-2-1fpor', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ömrün boyunca
başkalarının gözünde doğru görünmeye çalışırsan,
kendi hakikatine yabancılaşırsın.

İnsan,
el âlemin alkışıyla büyümez;
vicdanının sessizliğinde var olur.

Çünkü ölüm,
bütün unvanları susturur.
Şöhreti de...
Serveti de...
Övülmeyi de...
Yerilmeyi de...

Geriye birkaç hatıra kalır.
Onlar da,
hatırlayanlarla birlikte
toprağa karışır.

Demek ki insanın asıl meselesi;
başkalarının hayatında iz bırakmak değil,
kendi ruhuna ihanet etmeden yaşamaktır.

Zaman,
herkesi unutur.

Ama insan,
yaşarken kendini unutursa,
aslında ölmeden önce
yok olmuş demektir.

Muhsin Yener', 'Ömrün boyunca başkalarının gözünde doğru görünmeye çalışırsan, kendi hakikatine yabancılaşırsın. İnsan, el âlemin alkışıyla büyümez; vicdanı...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kendi-hakikatin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İNANMAK', 'i-nanmak-muhsin-yener-2-jlu1y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnanmak var olmaktır
Dediler, gönle indirdim sözünü
Bir tohum gibi düştü içime
Karanlığı yaran bir öz oldu

İnanç, kuru bir söz değil
Bir hal, bir yol, bir nefes
Her adımda “O”na varan iz
Her damlada hakikatin sesi

Yaşamak dedikleri nedir ki
Bir avuç zaman, bir gölge misali
Eğer değerle yoğrulmazsa kalp
Savrulur gider rüzgarın dili

Gel ey gönül, uyan artık
Geçici olandan yüz çevir
İnandığın ne varsa hakikatten
Onunla diril, onunla devir

Sevgiyle yoğur her anını
Merhametle dokun cana
İnanç, kuru bir dava değil
Hakk’a yürüyen bir mana

Var olmak istiyorsan eğer
İnancınla ol, özüyle kal
Çünkü insan dediğin sırdır
Çözülür ancak secdeye vardığın da.
Muhsin yener', 'İnanmak var olmaktır Dediler, gönle indirdim sözünü Bir tohum gibi düştü içime Karanlığı yaran bir öz oldu İnanç, kuru bir söz değil Bir hal...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/inanmak-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖNCE VATAN', 'once-vatan-muhsin-yener-2-r9sd5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimisi partim der, kimisi okulum,
Kimisi mezhebim, kimisi cemaatim…
Çizgiler çizerler insanın üstüne,
Dar kalıplara hapsederler ruhu.

Ama vatan yoksa
Ne parti kalır, ne okul,
Ne mezhep tutar insanı ayakta
Ne cemaat avutur düşen yüreği.

Toprak sustu mu,
Bayrak göğe küstü mü,
Diller birbirine düşman kesildi mi
O zaman anlarsın yalnızlığı milletin.

Soruyorum size:
Hangi fikir kurtarır işgal altında bir ülkeyi?
Hangi inanç diker yırtılmış bir sancağı yeniden?

Ey gaflet uykusundakiler!
Uyanın artık bölünmüş adlardan,
Uyanın artık parçalayan sadakatlerden…

Bir tek gerçek var:
Vatan varsa her şey vardır,
Vatan yoksa
Hepsi bir hiçtir.

ÖNCE VATAN.

Muhsin Yener', 'Kimisi partim der, kimisi okulum, Kimisi mezhebim, kimisi cemaatim… Çizgiler çizerler insanın üstüne, Dar kalıplara hapsederler ruhu. Ama va...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/once-vatan-57-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okuyun evladım', 'okuyun-evladim-mustafa-ozkaraalp-z7f3k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Fidan gibi bir çocuktu Fikri, ip ince,

Doktor olacaktı amcası büyüyünce,

Bütün gücüyle dirsek çürüttü,

Gözlerinin ferini masada kuruttu.

Ne meslek öğrendi, ne de hayatı,

Oku demişti ya herkes, ne yapsın sanatı,

Okullar bitince, gerçekler başladı,

Baktı ki açıkta tüm arkadaşları,

Ev desen açık  hava hapishanesi,

Anne gardiyan, baba sorgu eri,

Konu komşu bakışlarıyla taciz eder,

Hal hatır sormaları zehirden beter, 

Şimdi sorarlar: "Ne iş yaparsın?"

Başını eğer, içten yanarsın.

Ne bir baltaya sap olabildin,

Ne  kendi yarana merhem sararsın.

Nihayetinde  düşmüş yolu maden ocağına,

Almış eline baltayı başlamış sallamaya,

Kalem tutan elleri tırmalamış taşları,

Ağlamış gizliden içine dökmüş yaşları, 

Vur Fikri, kazmayı vur, vur, vur,  !

Bütün hıncınla bütün, öfkenle vur, !

Düşenin dostu olmaz, doğrusu budur.', 'Fidan gibi bir çocuktu Fikri, ip ince, Doktor olacaktı amcası büyüyünce, Bütün gücüyle dirsek çürüttü, Gözlerinin ferini masada kuruttu. Ne ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özkaraalp']::text[], 8.5, '{"poet":"Mustafa Özkaraalp","poet_slug":"mustafa-ozkaraalp","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/okuyun-evladim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olursun', 'ne-olursun-mahmut-nazik-r6sex', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönül gitmez yârdan ırak

Aldırma yâr ne olursun

Bu sevdanı yaprak yaprak

Soldurmak yâr ne olursun

Hani ısız bir yol gibi

Güz mevsiminde gül gibi

Permeperişan hal gibi

Oldurma yar ne olursun

Saki''nin aşk yapısında

Fitne fesat sarpısında

Sevdamı el kapısında

Buldurma yar ne olursun

Doldur Saki doldur hele

Bu devranda bitmez çile

Gönlümü gamla dert ile

Doldurma yar ne olursun

Mahmut Nazik 16 11 2026

Sarpısında: ulaşılmayan, sarp yer', 'Gönül gitmez yârdan ırak Aldırma yâr ne olursun Bu sevdanı yaprak yaprak Soldurmak yâr ne olursun Hani ısız bir yol gibi Güz mevsiminde gül ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Nazik']::text[], 8.5, '{"poet":"Mahmut Nazik","poet_slug":"mahmut-nazik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ne-olursun-73-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BELKİ...', 'belki-muhsin-yener-2-9ybh2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Belki yıllar sonra
aynı sokakta,
aynı gökyüzünün altında
yeniden karşılaşacağız.

Belki de
göz göze geleceğiz bir an,
ama birbirimizi tanımadan
yanından geçip gideceğim.

Ne sen dur diyeceksin,
ne ben dönüp bakacağım.

Çünkü zaman,
bazı insanları unutturmaz;
yalnızca birbirine yabancı eder.

Ve biz,
bir zamanlar aynı hikâyenin içinde yürüyen iki insan,
bir gün
birbirinin hatırası bile olmadan
sessizce geçip gideceğiz.

Muhsin Yener', 'Belki yıllar sonra aynı sokakta, aynı gökyüzünün altında yeniden karşılaşacağız. Belki de göz göze geleceğiz bir an, ama birbirimizi tanımad...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/belki-885-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göz Bebeği', 'goz-bebegi-hakan-dincel-sorj2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'GÖZ BEBEĞİ 

En sevdiklerini göz yaşında saklamak,

ağır gelir insana.

Onlar en hak ettikleri yerdedirler aslında.

Gözün içinde,

göz bebeğinin yanında.

Ve birliktedirler,

saf tertemiz damlalarla.

Süreklide aklanıp,  paklanırlar,

göz yaşlarıyla ama,

zaman gelipde damlalar,

toprağa doğru yola çıktıklarında,

sırası gelende gider bir bir onlarla.

Geriye bakmadan,

ve ayrılık çok zor olsada...', 'GÖZ BEBEĞİ  En sevdiklerini göz yaşında saklamak, ağır gelir insana. Onlar en hak ettikleri yerdedirler aslında. Gözün içinde, göz bebeğinin...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/goz-bebegi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimin Hızır, Kimin İlyas Olduğunu Bilemezsin', 'kimin-hizir-kimin-i-lyas-oldugunu-bilemezsin-muhsin-yener-2-qteml', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsan, hayatın telaşı içinde çoğu zaman karşısındakini hızlıca yargılamaya meyillidir. Kimi zaman bir bakışla, kimi zaman bir sözle karar veririz insanlar hakkında.

Oysa unuttuğumuz çok önemli bir hakikat vardır Kimin Hızır, kimin İlyas olduğunu bilemezsin.
Belki de sıradan gördüğün bir insan, en zor anında sana uzanacak eldir.

Belki küçümsediğin biri, yarın senin yolunu aydınlatacak bir ışık olur. İnsan, karşısındakinin iç dünyasını, niyetini, taşıdığı hikayeyi bilemez.

Bu yüzden ölçüyü kaçıran her davranış, aslında kendi insanlığımızdan eksiltir.
Toplum olarak en büyük hatalarımızdan biri de insanlara “hak ettikleri gibi” davranma iddiasıdır.

Oysa kimin neyi hak ettiğini tam anlamıyla bilmek, insanın haddini aşan bir durumdur.

Bizim görevimiz, hesap yapmak değil; insan kalabilmektir. İyiliği şartlara bağladığımızda, aslında iyiliği yok ederiz.
Unutulmamalıdır ki hayat, sürprizlerle doludur.

Dün selam vermediğin bir yüz, yarın kapını çalabilir. Bugün görmezden geldiğin bir insan, yarın en büyük destekçin olabilir. Bu yüzden her karşılaşmayı bir imtihan gibi görmek gerekir.

İnsanlara davranışımız, onların kim olduğundan çok bizim kim olduğumuzu gösterir. Nezaket, saygı ve merhamet; karşılık beklenerek değil, karakter gereği gösterildiğinde anlam kazanır.

Belki de hayatın en büyük erdemi, karşındakinin kim olduğunu bilmeden iyi davranabilmektir.

Kısacası, kimin Hızır, kimin İlyas olduğunu bilemezsin. Ama sen, insan olmanın gereğini her şartta yerine getirebilirsin.

Çünkü gün gelir, birine gösterdiğin küçücük bir iyilik, sana koca bir kapı açar.
Muhsin yener', 'İnsan, hayatın telaşı içinde çoğu zaman karşısındakini hızlıca yargılamaya meyillidir. Kimi zaman bir bakışla, kimi zaman bir sözle karar ve...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kimin-hizir-kimin-ilyas-oldugunu-bilemezsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖZENTİ, GÖSTERİŞ VE KISKANÇLIK', 'ozenti-gosteri-s-ve-kiskanclik-muhsin-yener-2-7qiby', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kimi insan başkasının hayatına özenir,
Kendi kimliğini unutur, başkasına benzemek ister.
Kimi sahip olmadığını varmış gibi gösterir,
Kimi de başkasının mutluluğuna göz diker.

Gösteriştir bazı insanların tek sermayesi,
Dışarıdan süslüdür ama boştur hikâyesi.
Biraz makam, biraz para, biraz da şöhret,
Sanırlar ki bunlarla kazanılır insanlık ve itibar.

Özentiyle yaşanmaz, insan kendisi olmalı,
Her insan kendi yolunda, kendi izini bırakmalı.
Başkalarının hayatına bakıp iç çekmek yerine,
Kendi emeğiyle yükselmeli, alın teriyle büyümeli.

Kıskançlık öyle bir duygudur ki insanı içeriden kemirir,
Dost görünen nice yüzün gerçek niyetini ele verir.
Birinin başarısına sevinemeyen gönül,
Kendi içindeki karanlığa mahkûm olur.

Ben ne gösterişe aldanırım ne sahte alkışlara,
Ne de kıskançlıkla kurulmuş boş yarışlara.
İnsanın büyüklüğü boyunda, posunda değil;
Duruşunda, karakterinde ve vicdanındadır.

Unutmayın, dünya kimseye kalmayacak,
Ne servet ne makam sonsuza dek yaşanacak.
Bugün başkasına tepeden bakanlar da
Yarın bir avuç toprağa karışacak.

Öyleyse bırakın özentiyle yaşayanları,
Bırakın gösteriş uğruna kendini unutanları.
Kıskançlıkla başkasının ışığını söndürmeye çalışanları…

Ben kendi yolumda, kendi doğrularımla yürürüm.
Çünkü insan olmak, insan görünmekten daha değerlidir.

Muhsin Yener', 'Kimi insan başkasının hayatına özenir, Kendi kimliğini unutur, başkasına benzemek ister. Kimi sahip olmadığını varmış gibi gösterir, Kimi de...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ozenti-gosteris-ve-kiskanclik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Birlerinize Şahit Olmadıkça', 'bir-birlerinize-sahit-olmadikca-i-lyas-ates-fnvc7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Batıldan yüz çevirenler Hakka dönmüş olacaktır

Sizler batıl yollardan yüz çevirmedikçe gerçekte

Hakka iman etmiş değilsinizdir 

Sözde İman etmenin ne sizlere nede bir başkalarına

faydası olmayacaktır

Faydasız inanç faydasız iman sadece kuru bir sözdür

İnancınızı hayata geçirmedikçe bir birlerinize şahit

olmadıkça sizler inanmış birer münafıksınızdır', 'Batıldan yüz çevirenler Hakka dönmüş olacaktır Sizler batıl yollardan yüz çevirmedikçe gerçekte Hakka iman etmiş değilsinizdir  Sözde İman e...', ARRAY['Türk Edebiyatı','Şiir','İlyas Ateş']::text[], 8.5, '{"poet":"İlyas Ateş","poet_slug":"i-lyas-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-birlerinize-sahit-olmadikca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efe', 'efe-hakan-dincel-xj5n9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'EFE 

Ay''i kıskandıran, o güzeller güzeli

düşünce fikrime, 

buyurdun geldin birgün, nazikçe girdin gönlüme.

Yüceler yücesi  bir doruktan gelmistin  sanki, 

Köhne bir çukurda, kirin,  çamurun içinde debelenen  nefsime.

Geldin, girdin, yerleştin içime,  vedahi bir daha hiç çıkmamak üzere.

Karıncalar gezinirdi, çekinmeden  ayaklarının altında güvenle, 

dostun ayaklarıdir bunlar deyip de.

Tatlı dilini, hoş sohbetini kıskanırdı zehirli akrepler,  kahpe  yılanlar,

kaçıp gittikleri, girdikleri kapkara deliklerde.

Yanından  gidip ayrılamazdı, mazlum, mahsun canlar, dilsiz muezzalar bir an bile.

Dünyalar onların olurdu, mutlu olurdu sabiler, verdiğin bir tek şeker, bir parça ekmek ile. 

Unutma ki, kar gibi eriyip gitmez menziline varan dostlar,

kar gibi eriyip giden, bu sahte Dünyada, çekilen dertler ve de  tasalar.

Birikti, çığ oldu, yanı başında senin herzaman,  sevdali yürekler, dağ gibi adamlar.

Üstüne yıkılır, ezer, yutar, Dünya nın zalımligini, hayinligini, bir sel gibi  dosta  adanan kurbanlar.

Sen,  sensizligin her bir  zerresinde, her daim var olacaksın.

Sanmasın ki kimse, hiç  hatirlanmayacaksin.

Nasıl unutulsun ki, 

seninle geçen tek bir an, 

sımsıcak bir gülüşün, samimi bir bakışın, bir efe gibi  selamın.

En güzel yurtta, parıldayan, huzurlu,  sonsuz bir ışık altında, 

dostlarınla keyifle oturacaksin.

Çekilen dertlere, sıkıntılara bakıp bakıp uzaklardan,

bir bardak çay gibi  yudum yudum  yudumlarken özlemi, 

ve dumanları gülerek savurur gibi rüzgarlara,

ağız dolusu kahkahalar atacaksın...', 'EFE  Ay''i kıskandıran, o güzeller güzeli düşünce fikrime,  buyurdun geldin birgün, nazikçe girdin gönlüme. Yüceler yücesi  bir doruktan gelm...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/efe-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektep', 'mektep-hakan-dincel-5wko2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'MEKTEP

Mektebin bacaları, ders verir hocaları diyormuş şair ,

Bilemezdik kapısından içeri girmeden, 

mektep ne demek, okul ne demek,

hoca ne demek, öğretmen ne demek bilemezdik.

Çokça çekinerek, 

birazda korkuyla girdik kapısından okulun.

Dedim ya bilemezdik, içeride bizleri nelerin,

Ne günlerin beklediğini,

girmeden iceri bilemezdik.

Minicik bir cocuk dünyasında yaşarken,

okulun hayatımız için ne anlama 

geldiğini tahmin bile edemezdik.

Girdik içeri kapıdan,

karşımıza çıkan  ogretmenin

Bazen bir anne şefkatiyle gözlerimizden opecegini, 

bazen de bir baba edasıyla bize sarılıp, 

yaptigimiz yanlışları bakışlarıyla duzeltecegini,

bize herzaman doğruyu soyleyecegini bilemezdik.

Girdik içeri ama kahrolası salgın günlerinin,

kısa bir zaman sonra,

tam alisiyoruz derken,

okuldan arkadaşlarımızdan 

bizi ayiracagini bilemezdik.

Günler günleri, harfler harfleri kovalarken, 

Sesleri kavrayip kısa zamanda okumaya geçmenin, 

bizi ne kadar mutlu edeceğini, 

hiç ama hic bilemezdik.

Salgın günleri bitipde,

dönüp okula, öğretmenimizle arkadaşlarımızla, hayata dair türlü bilgileri,

Birer birer ogrenecegimizi,

birken 2,

ikiyken 3, ucken 4 olacağımızı,

sonrada ,

kanatlarını açıp masmavi günlere,

kanat cirpan kuslar gibi,

yuvamizdan birgün ucup  gideceğimizi hayal bile edemezdik.', 'MEKTEP Mektebin bacaları, ders verir hocaları diyormuş şair , Bilemezdik kapısından içeri girmeden,  mektep ne demek, okul ne demek, hoca ne...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/mektep-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Beni Benden Aldı', 'askin-beni-benden-aldi-sairul-i-slam-yunus-kokan-d2ur6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sen varsın hayalimde,

Adın yazılı gönlümde,

Seninle anlam bulur nefesi,

Sen oldun bu kalbin tek neşesi.

Derin bir deryaya daldı,

Yâr seninle nefes aldı,

Benim gönlüm sende kaldı,

Aşkın beni benden aldı.

Aşkın delisiyim, ömrün olayım,

Seninle her gün yeniden doğayım.

Dünya yıkılsa umrumda değil,

Sen benim her şeyimsin, bil!

Derin bir deryaya daldı,

Yâr seninle nefes aldı,

Benim gönlüm sende kaldı,

Aşkın beni benden aldı.', 'Bir sen varsın hayalimde, Adın yazılı gönlümde, Seninle anlam bulur nefesi, Sen oldun bu kalbin tek neşesi. Derin bir deryaya daldı, Yâr sen...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askin-beni-benden-aldi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Zamanlar Ben Vardım', 'biz-zamanlar-ben-vardim-dr-yusuf-polat-wevrk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir ömür geçmiş aradan sessizce, 

Ben mi yaşlandım, yoksa ömür mü

Bir zamanlar gülümseyen aynalar, 

Şimdi tanımaz olmuş solan yüzümü.

Nerede o sabahlar, o çocuk sesleri 

Nerede gençliğin deli rüzgârı

Nerede ilk sevdalar,

Nerede hesapsızca yaşanan günler

Cüzdanımda sararmış bir fotoğraf, 

İçinde küçücük bir çocuk var. 

Bana öyle mahzun bakıyor ki, 

Sanki benden alacağı bir hesap var.

Ah çocuk, bilseydin neler yaşadım, 

Kaç dostu bir suskunluğa gömdüm. 

Kaç sözü dudaklarımda eskittim, 

Kaç kez kendime dönmeyi unuttum.

Meğer insan en çok da 

Ertelenen sözün altında yaşlanırmış.

Ve bir gün kendi yüzüne bakınca, 

Tanımazmış aynada görünen yüzünü', 'Bir ömür geçmiş aradan sessizce,  Ben mi yaşlandım, yoksa ömür mü Bir zamanlar gülümseyen aynalar,  Şimdi tanımaz olmuş solan yüzümü. Nerede...', ARRAY['Türk Edebiyatı','Şiir','Dr Yusuf Polat']::text[], 8.5, '{"poet":"Dr Yusuf Polat","poet_slug":"dr-yusuf-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biz-zamanlar-ben-vardim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldiniz', 'hosgeldiniz-hakan-dincel-ssf99', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'HOŞGELDİNİZ

Bir yanda heyecanınız, bir yanda hayalleriniz,

İşte tüm sıkıntılara, zorluklara rağmen benimlesiniz.

Bir ömür boyu silinmeyecek bir macera başlıyor Hüda nın   izniyle,

Şiirler, şarkılar ve gönlüm,  sizi karşılıyor sevgiyle.

Ömrüm olursa, en kötü anınızda bile sizinleyim,

Sizin için herşey, güvenin bana,  söz veririm.

Nice hatıralar biriktireceksiniz bir  bilseniz,

İnanın bana, burayı ikinci eviniz bileceksiniz.

Ağlarsanız burada, sadece mutluluk göz yaşları olacak bunlar,

Bir bir kaydedilecek zihninize, unutulmayacak o günler,  o tatlı hatıralar.

Sizlerle neler neler öğreneceğiz , türlü etkinlikler, eğlenceli geziler.

Sevinçle, gülerek havaya kalkacak , o minik parmaklar, o minik eller.

Okulu, sınıfı, arkadaşlarınızı çok seveceksiniz,

Hatta okula uçarak gelmek isteyeceksiniz.

Hiçbir arkadaşınızı kırmayın, üzmeyin,

Kurallara uyduğunuzda,  güvendesiniz, bunu bilin.

Bir baba gibi, bir anne gibi davranmak isterim size, 

İzin verirde, beni kırmaz, bunu isterseniz sizde.

Gün gelip de,  bu sınıftan ayrılıp gittiğinizde,

Size olan sevgim de gelecek, hiç bırakmamak üzere yanınızda  sizinle. 

Hoşgeldiniz, hoşgeldiniz ne iyi ettiniz  minik meleklerimiz, 

Sizi çok sevecek, sizi görmeden, size şiir yazan öğretmeniniz...', 'HOŞGELDİNİZ Bir yanda heyecanınız, bir yanda hayalleriniz, İşte tüm sıkıntılara, zorluklara rağmen benimlesiniz. Bir ömür boyu silinmeyecek ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hosgeldiniz-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı Olsak Dudaklarda', 'sarki-olsak-dudaklarda-sairul-i-slam-yunus-kokan-e6woo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim gönlüm yandı,

Doktor aramayın, ilaç belli

Bir gülüşü yetti bana,

Bahar geldi her bir yana.

El ele versek sokaklarda,

Şarkı olsak dudaklarda.

Ne ayrılık ne de keder,

Senin aşkın bana yeter.

Bir ömürlük sevdamsın benim,

Sana kurban olsun yüreğim!

Dünya dönsün, zaman geçsin,

Aşkımız hiç bitmesin!

El ele versek sokaklarda,

Şarkı olsak dudaklarda.

Ne ayrılık ne de keder,

Senin aşkın bana yeter.', 'Benim gönlüm yandı, Doktor aramayın, ilaç belli Bir gülüşü yetti bana, Bahar geldi her bir yana. El ele versek sokaklarda, Şarkı olsak dudak...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sarki-olsak-dudaklarda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmen Olmak', 'ogretmen-olmak-hakan-dincel-w1fdu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ÖĞRETMEN OLMAK 

Öğretmen olmak,

sevginin doruklarından aşağı bir çocuğun elinden tutup kaymak,

kim ne dersin deyipte.

Öğretmen olmak,

gözlerden akan masum bir yaşı,

silebilmek yüreğinle.

Mutlu edebilmek minik gözleri,

mutsuzken, keyifsizken bile.

Öğretmen olmak,

hor görülmek çalışmıyor görünürken, 

Ve fakat terlerin içindeyken,

tahtanın başında,

damla damla erirken, rüyalarında bile.

Öğretmen olmak,

boş kalmasın minikler diye,

gitmeyipte bir hekime,

kendi kendine ilaç olup,

iyileşmek belkide.

Öğretmen olmak,

otuz göz ve kulakla görüp, işitip,

bir ağızla konuşmak,

herkesin duyacağı, anlayacağı  şekilde. 

Öğretmen olmak,

yanıp yanıp tükenmek,

karanlığın ortasında,

ve minik bir kalbin yanı başında. 

Öğretmen olmak,

sobası yanmayan soğuk sınıflarda,

suyu akmayan garip okullarda,

öğrencisine bir yudum su olup,

ısıtmak onu sıcacık bakışlarla.

Öğretmen olmak,

doya doya sevmek,

doya doya öpmek,

hiç opulmemekten kirlenmiş 

cennet kokan elleri.

Ve uçabilmek, 

gün gelip de kanatsız meleklerin,

havaya kalkmış ellerinin üzerinde,

geldiğimiz gerçek yurda geri...', 'ÖĞRETMEN OLMAK  Öğretmen olmak, sevginin doruklarından aşağı bir çocuğun elinden tutup kaymak, kim ne dersin deyipte. Öğretmen olmak, gözler...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ogretmen-olmak-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırdım Aşkımı', 'haykirdim-askimi-sairul-i-slam-yunus-kokan-zyxax', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne sen geri gel, ne ben unutayım,

Bırak bu sevdayı içimde yaşayayım.

Bir resmin kaldı bende, bir de hatıran,

Ben hâlâ seninleyim, sen unutsan da çoktan.

Bu gece yine sustum, adını anarak,

Her hatırada hasretinle yanarak,

Duvarlara derdimi anlatarak

Haykırdım aşkımı ağlayarak.

Gözlerim yollarda, ömrüm yarım kalmış,

Gönlüm senin ardından bir mezara dalmış.

Ne yana dönsem sen varsın, kaçamıyorum,

Ben bu sevdanın yükünü taşıyamıyorum.

Bu gece yine sustum, adını anarak,

Her hatırada hasretinle yanarak,

Duvarlara derdimi anlatarak

Haykırdım aşkımı ağlayarak.', 'Ne sen geri gel, ne ben unutayım, Bırak bu sevdayı içimde yaşayayım. Bir resmin kaldı bende, bir de hatıran, Ben hâlâ seninleyim, sen unutsa...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haykirdim-askimi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanatsiz Melekler', 'kanatsiz-melekler-hakan-dincel-dwc7g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'KANATSIZ MELEKLER

Bir eylül sabahı, yine buluştuk,

kanatsız meleklerle mektepte.

Yanıyordu, parlıyordu o güzel gözler,

Işıl ışıl sevgiyle.

Bir serçe yüreği atıyordu sanki, 

hızlı hızlı inip kalkan göğüslerde.

Derin derin nefes alıyordu hepsi,

heyecan içinde.

Tüm hayallerini, çantalarına koyup,

getirmişlerdi belkide.

Saf, tertemiz halleri,

ve nurlu yuzleriyle geldiler, girdiler yeni evlerine.

Hoşgeldiniz, hoşgeldiniz kanatsız melekler, hoşgeldiniz gönlüme.

Sımsıkı sarılıp kalbime,

mutluluk getirdiniz.

Sımsıcak  bakışlarla, kalbimdeki pası sildiniz.

Minicik eliniz, hesapsız, çıkarsız diliniz,

dünyanın en güzel hediyesidir,

cennet kokan teniniz.

Ansızın sarılan,  minik 2 kol ile sarsilmak,

Ve ansızın, gül kokulu öpücüklere boğulmak.

Ne gariptir, çok sevinipde sevinçten ağlamak.

Masum, minicik bir göz bebeğinin içinde ,

yıllarca tutuklu kalmak.

Hiç de zor değil ki aslında,

onları gerçekten anlamak.

Gördüğünü gösteren, 

tertemiz, 

samimi, 

issiz bir aynadır çocuk olmak...', 'KANATSIZ MELEKLER Bir eylül sabahı, yine buluştuk, kanatsız meleklerle mektepte. Yanıyordu, parlıyordu o güzel gözler, Işıl ışıl sevgiyle. B...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kanatsiz-melekler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümün Belalısı', 'gonlumun-belalisi-sairul-i-slam-yunus-kokan-y2u6z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni gördüm bir akşamüstü,

Güneş bile kıskandı yüzünü.

Bir gülüşün yetti be güzelim,

Unuttum tüm dertlerimi.

Gönlümün belalısı,

Sen ömrümün yarısı.

Gönlümün belalısı,

Sensin bu kalbin sevdası.

Âlem duymuş aşkımızı,

Dillere düşmüş sevdamız.

Bir sen, bir ben, bir de bu şarkı,

Huzur olsun aşkımızın adı.

Gönlümün belalısı,

Sen ömrümün yarısı.

Gönlümün belalısı,

Sensin bu kalbin sevdası.', 'Seni gördüm bir akşamüstü, Güneş bile kıskandı yüzünü. Bir gülüşün yetti be güzelim, Unuttum tüm dertlerimi. Gönlümün belalısı, Sen ömrümün ...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonlumun-belalisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Gibi Seviyorum', 'deli-gibi-seviyorum-sairul-i-slam-yunus-kokan-j98tr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilsen de bilmesen de

Aklım sende, kalbim sende.

Taht kurdun gönlümde ,

Bin bahar var gülüşünde.

Senin aşkın bana derman!

Seninle ışıldar dünyam,

Duysun bunu tüm cihan

Deli gibi seviyorum.

Sensiz hayatı neyleyim?

Gül yüzlü nazlı yarim,

Seninle gönlüm gülistan,

Aşkımız dillere destan.

Senin aşkın bana derman!

Seninle ışıldar dünyam,

Duysun bunu tüm cihan

Deli gibi seviyorum.', 'Bilsen de bilmesen de Aklım sende, kalbim sende. Taht kurdun gönlümde , Bin bahar var gülüşünde. Senin aşkın bana derman! Seninle ışıldar dü...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/deli-gibi-seviyorum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abaküs', 'abakus-hakan-dincel-zhxyw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ABAKÜS 

Bir çocuğun gülen gözlerinin içinde,

tutunmak hayata.

Dünyanın türlü pisliğine inat,

tertemiz ve minicik bir kalbi, 

kendine kalkan yaparak.

Öğretirken öğrenmek hayatın bilmecesini,

minicik avuçların içindeki nura,

hayran hayran bakarak.

Yeni dünyalar inşa ederken, 

yorulmuş, nefes bile almaya gücün yokken,

ve uçurumun ucunda,  kendini unutmuşken, 

tutar,  izin vermez minik iki kol,

arkandan sımsıkı sarılarak.

Unutturur her derdi kederi,

en çıkılmaz sanılan karanlıklardan,

gülen gözleriyle çeker alır hiç çaktırmadan, 

hep bir çocukluk yaparak.

Gün gelir, çoğalır  saçta aklar,

yüzde çizgiler.

Ardına  baktığında kaç nesile dokunmuş sesin,

Adım adım yaklaşırken 

son nefesin.

Ve zaman ki, geri gelmez,

hayıflanarak.

Körpe fidan büyüyüp,

koca bir çınar olmuş.

Mahcup bir bakışla, yürekleri dağlayan,

bitirmiş sanki ömrünü, 

usanmadan sıkılmadan,

minicik elleriyle,  abakuste bir bir sayarak...', 'ABAKÜS  Bir çocuğun gülen gözlerinin içinde, tutunmak hayata. Dünyanın türlü pisliğine inat, tertemiz ve minicik bir kalbi,  kendine kalkan ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/abakus-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Kıydın?', 'nasil-kiydin-sairul-i-slam-yunus-kokan-4zacc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir aşk uğruna kaybettim baharı,

Dostlarım soruyor, neden böylesin?

Anlatamam onlara içimdeki yangını,

Söyle, bu kalp bunu nasıl söylesin?

Nasıl kıydın seven yüreğime?

Bu sevdayı bitirdin hiç yere,

Ben hâlâ aynı yerde, aynı aşkın içinde,

Sen çoktan yabancı oldun hikâyemize.

Sana kızamıyorum, kalbime kızdım,

Her gece yokluğuna bir şarkı yazdım.

Sen unuttun belki de beni çoktan,

Ben senin adını kalbime kazdım.

Nasıl kıydın seven yüreğime?

Bu sevdayı bitirdin hiç yere,

Ben hâlâ aynı yerde, aynı aşkın içinde,

Sen çoktan yabancı oldun hikâyemize.', 'Bir aşk uğruna kaybettim baharı, Dostlarım soruyor, neden böylesin? Anlatamam onlara içimdeki yangını, Söyle, bu kalp bunu nasıl söylesin? N...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasil-kiydin-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Damla Mutluluk', 'bir-damla-mutluluk-hakan-dincel-izs4k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BİR DAMLA MUTLULUK 

Gün ağarırken, bir hevesle  koyulup da  yollara,

aydınlatırsın gönlümü,

gözlerindeki sevginin ışığıyla.

Öğreten kim, öğrenen kim birbirine karışsada, 

bırakmak istemez gibi gelirsin, 

beni kör  karanlıkların ortasında.

Tam da sarılmışken  doyasıya seninle,

tenime değen  göz yaşın 

süzülürken, 

usulca yüreğime,

delip geçer ansızın,  zamanı ve  mekanı ince ince. 

Bir damla saf sevgi içinde,   boğulur  sanki ömrüm, 

kim bilir, kaç yürekte canlanır günü gelince.

Zamanı  dondurur,  sımsıcak bir bakışın, 

kavuşan kollar  ayrılmak istemez buluşmuşken, bir an bile.

Göz nuruyla  yapılıp, karşılık beklenilmeden verilen bir hediye,

mutlu eder mi hiç onun kadar,

altın, zümrüt dolu bir hazine bile.

Masum dilinden dökülen hesapsız  kelimeler,

samimi, titreyen,  buğulu   bakışlarda gizlidir, sevgin ve duyduğun keder.

Ne büyük özlemdir,

ne olurdu sanki, bir kere daha birlikte olsaydık, tek bir kez daha,

tek bir sefer.

Saklamak seni, yıllar yılı unutmadan  hafızamda,

Ve unutulmadan bir ömür, yüreğinden çıkmamacasına.

Hatırlanmak bir seher vakti,

en içten  yakarışlarda, 

belkide geriye  kalan,

en güzel duam olmuş,

günahkar avuçlarımda...', 'BİR DAMLA MUTLULUK  Gün ağarırken, bir hevesle  koyulup da  yollara, aydınlatırsın gönlümü, gözlerindeki sevginin ışığıyla. Öğreten kim, öğr...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-damla-mutluluk-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAYATIN GERÇEKLERİ', 'hayatin-gercekleri-muhsin-yener-2-9cq96', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üzgün olma…
İçine çöken karanlığa teslim olma.

Nefret etme,
çünkü en ağır yük,
taşıyana aittir.

Aşkı yaşa
yarım bırakma hiçbir duyguyu,
kalbin korkmasın sevmekten.

Yaşamı sev,
eksikleriyle, kırıklarıyla,
sana rağmen değil, seninle güzel.

Dünü unut
geçmişin gölgesinde üşüme artık,
güneş hep bugünden doğar.

Işığını yansıt,
bir kıvılcım bile karanlığı deler,
sen yeter ki sönme.

Ne olursa olsun,
gülmeyi unutma
çünkü bazen bir tebessüm
yeniden başlatır insanı.

Ve en çok
sevdiklerinle birlikte
bir ömür boyu
mutlu, huzurlu
bir yaşamın içinde kal.
Muhsin yener', 'Üzgün olma… İçine çöken karanlığa teslim olma. Nefret etme, çünkü en ağır yük, taşıyana aittir. Aşkı yaşa yarım bırakma hiçbir duyguyu, kalb...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hayatin-gercekleri-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret 10', 'hasret-10-adsiz-gardenya-r9oh4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Donup kaldığı o an uzadı...
sanki zaman bile
onunla birlikte yavaşladı.
Az önce duyduğunu sandığı o ikinci adım... hâlâ
kulaklarının içindeydi.
Yürümekle kalmak arasındakaidrikayesi...
Sonra kendini zorladı.
Bir adım attı.
Ses geldi.
Durdu.
Yine dinledi.
Bir adım daha attı.
Yine aynı şey...
İki ses var gibiydi.
Kaşları çatıldı. Nefesini tuttu.
 Bu kez daha
dikkatli attı adımını... 
sanki yere değil de boşluğa
basıyormuş gibi.
Ve o an fark etti...
İkinci sandığı ses... aslında kendi adımının
yankısıydı.
Ama garip olan şu ki...
Yankı olması gerektiği gibi dağılmıyordu.
Geri dönüyordu.
Gecikiyordu.', 'Donup kaldığı o an uzadı... sanki zaman bile onunla birlikte yavaşladı. Az önce duyduğunu sandığı o ikinci adım... hâlâ kulaklarının içindey...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hasret-10-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GERÇEK DOST', 'gercek-dost-muhsin-yener-2-dfyqb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gerçek dost
sessiz zamanların içinden çıkar
kalabalıklar dağılırken
yanında kalan o tek gölgedir

İyi günde
gülüşler çoğalır,
eller çoğalır,
dostluklar çoğalır

ama çoğu
rüzgar gibi geçicidir
Asıl dost
gecenin en karanlık yerinde
ışık yakandır

hastalıkta baş ucunda bekleyen
sözsüz anlayandır
Sen düşerken
elini tutan
sen susarken
yüreğini duyan

İşte dostluk
ne zaman güldüğünle değil
ne zaman ağladığında
kimin yanında kaldığıyla ölçülür

Çünkü iyi günde
herkes dosttur
ama gerçek dost
zor günlerin içinden doğar
Muhsin Yener', 'Gerçek dost sessiz zamanların içinden çıkar kalabalıklar dağılırken yanında kalan o tek gölgedir İyi günde gülüşler çoğalır, eller çoğalır, ...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gercek-dost-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Kalbime Yazdım', 'seni-kalbime-yazdim-sairul-i-slam-yunus-kokan-2i2jk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yine anılardan sana sığındım,

Bir eski resmine bakıp ağladım.

Herkese iyiyim, dedim de sustum,

Ben sensiz kendimi yarım bıraktım.

Ne zaman bir şarkı çalsa,

Adını duyarım her nakaratta.

Ben seni kalbime yazdım,

Silinmez izin var ruhumda.

Bir seni unutamadım, bir sana yenildim,

Ben seni nasıl sevdim bir türlü bilmedin.

Bu aşk uğruna ömrümü tükettim,

Belki bir gün dönersin diye.

Ne zaman bir şarkı çalsa,

Adını duyarım her nakaratta.

Ben seni kalbime yazdım,

Silinmez izin var ruhumda.', 'Yine anılardan sana sığındım, Bir eski resmine bakıp ağladım. Herkese iyiyim, dedim de sustum, Ben sensiz kendimi yarım bıraktım. Ne zaman b...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-kalbime-yazdim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahu', 'ahu-hakan-dincel-rofat', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'AHU

Yaralı bir ceylan gibi, 

girdin hayatıma.

Ürkek bakışların,

tatlı bir sohbete döndüğünde,

Akmisti artık deli bir ırmak gibi,

sana doğru tüm duygularım.

Yanyanayken sürekli seninle,

ve hep yanında olmak isterken,

amansız bir ayrılık kaldı ellerimde.

Çıkmıyor hayalin aklımdan,

çınlıyor kulağımda konuşmalarımız.

Ahu gözlere özlem,

inan ki dayanamadığım...', 'AHU Yaralı bir ceylan gibi,  girdin hayatıma. Ürkek bakışların, tatlı bir sohbete döndüğünde, Akmisti artık deli bir ırmak gibi, sana doğru ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ahu-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatasız İnsan Olmaz', 'hatasiz-i-nsan-olmaz-i-lyas-ates-wmln7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günahsızsan korkacak bir şey yoktur

Eğer insansan kendine döndüğünde 

neler yaptığını göreceksin

İnsan hata yapar hatasız insan olmaz

önemli olan hataları görüp hatalardan

ders alabilmektir', 'Günahsızsan korkacak bir şey yoktur Eğer insansan kendine döndüğünde  neler yaptığını göreceksin İnsan hata yapar hatasız insan olmaz önemli...', ARRAY['Türk Edebiyatı','Şiir','İlyas Ateş']::text[], 8.5, '{"poet":"İlyas Ateş","poet_slug":"i-lyas-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hatasiz-insan-olmaz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EGO, ÖZENTİ VE GÖSTERİŞ', 'ego-ozenti-ve-gosteri-s-muhsin-yener-2-49k03', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir insan düşünün,
Kendi gölgesine hayran,
Kendi sesine tutkun,
Başkalarının alkışında arıyor değerini.

Üzerinde marka,
Dilinde büyük laflar,
Yüreğinde koca bir boşluk…
Dışarıdan bakınca ihtişam,
İçine bakınca koca bir hiçlik.

Ego büyümüş,
İnsan küçülmüş.
Özenti çoğalmış,
Özgünlük tükenmiş.
Gösteriş, hayatın başköşesine kurulmuş,
Samimiyet kapının dışında bekler olmuş.

Oysa insan dediğin,
Ne giydiği elbiseyle büyür
Ne oturduğu koltukla
Ne de önünde eğilen kalabalıklarla…

İnsan;
Bir yetimin başını okşarken,
Bir dostun derdini dinlerken,
Kimse görmeden iyilik yaparken
İnsan olur.

Ey gösterişe ömrünü verenler!
Bir düşünün,
Sizin sandığınız o büyük dünya
Bir gün alkışsız kalacak.

Ne makamınız konuşacak
Ne servetiniz sizi anlatacak.
Geriye yalnızca
İnsanlara bıraktığınız iz kalacak.

Çünkü ego bir gün yorulur,
Gösterişin ışıkları söner,
Özentinin modası geçer…

Ama karakter kalır,
Duruş kalır,
İnsanlık kalır.

Ve unutmayın:
İnsan, başkasına benzemeye çalıştıkça kendinden uzaklaşır.

Ben Muhsin Yener olarak
Gösterişin değil, samimiyetin;
Egonun değil, mütevazılığın;
Özentinin değil, özgünlüğün
Yanında durmayı seçiyorum.

Çünkü bu dünyada
En büyük zenginlik,
Kendin olarak kalabilmektir.
Muhsin yener', 'Bir insan düşünün, Kendi gölgesine hayran, Kendi sesine tutkun, Başkalarının alkışında arıyor değerini. Üzerinde marka, Dilinde büyük laflar...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/ego-ozenti-ve-gosteris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gozlerin', 'gozlerin-hakan-dincel-fqbpx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'GÖZLERİN 

Gözlerim gönüllü bir tutsak olmuş  gözlerinde,

dinlemiyorlar ne yapsam beni,  dönmüyorlar geri.

Bal rengi bir rüyadan,

hiç uyanmak istemiyorlar sanki.

Aklım felç olmuş hayalinle,

Umursamaz korkusuz kalbim,

sarilir, sevişir yokluğunda resminle.

Varlığın yıldızlar kadar uzak, 

bir o kadar da yakıcı olsada ancak,

Ne vazgeçilmez bir istektir ki  o, 

birgün konusurken seninle, 

nefesini tenimde  duyumsamak.

Keşkelerden örülü bir hayalin,

en güzel yerindedir gözlerin.

Nazlı bir başaktir,

omuzlara dökülen saçların.

Bembeyaz tenin,

delip geçen bakışların,

celladı olmuş sanki,

sensiz geçen her anın.', 'GÖZLERİN  Gözlerim gönüllü bir tutsak olmuş  gözlerinde, dinlemiyorlar ne yapsam beni,  dönmüyorlar geri. Bal rengi bir rüyadan, hiç uyanmak...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gozlerin-1817-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret 9', 'hasret-9-adsiz-gardenya-e9l1x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kapı eşiğini geçtiği an, 
içeride kalan sıcaklığın aslında ne kadar büyük bir yanılsama olduğunu anladı. 
Sokak... düşündüğü gibi özgürlük değildi. Aksine, üzerine çöken ağır bir sessizlikti. 
Sokak lambaları vardı ama ışıkları yetersizdi. 
Sanki her biri kendi çevresini aydınlatmaktan vazgeçmiş, karanlığa teslim olmuştu. 
Adımlarını attıkça ayak sesleri yankılanıyordu... 
ama garip bir şekilde, o yankı tek başına değildi.
Gece, sandığından daha koyuydu.
Bir an durdu.
Dinledi.
Kendi nefesini duydu önce. 
Sonra... bir şey daha. Çok hafif. Sanki bir adım...
 onun adımına geç kalmış gibi.
Başını çevirdi.
Kimse yoktu.
Ama içi rahatlamadı.
Yürümeye devam etti. 
Bu kez daha yavaş. 
Her adımını kontrol ederek. 
Arkasına bakmamaya çalışarak. 
Çünkü bazı anlarda insan bilir...
arkasına dönerse bir şey göreceğini.
Ve o, görmek istemiyordu.', 'Kapı eşiğini geçtiği an,  içeride kalan sıcaklığın aslında ne kadar büyük bir yanılsama olduğunu anladı.  Sokak... düşündüğü gibi özgürlük d...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hasret-9-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Oldun Benim Dünyam', 'sen-oldun-benim-dunyam-sairul-i-slam-yunus-kokan-yh79a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aman aman, güzelim aman!

Seninle bayram her zaman.

Sen benim gönlümde açan bir rüya.

Kalbim düştü sevdana.

Sen benim nefes alışım.

Sen benim bahtım, şansım,

Sen neşem, sen sevdam,

Sen oldun benim dünyam.

Ne altın isterim ne de saray,

Birlikte geçsin her an, her ay,

Cümle âlem bunu duysun,

Aşkımız bir destan olsun.

Sen benim nefes alışım.

Sen benim bahtım, şansım,

Sen neşem, sen sevdam,

Sen oldun benim dünyam.', 'Aman aman, güzelim aman! Seninle bayram her zaman. Sen benim gönlümde açan bir rüya. Kalbim düştü sevdana. Sen benim nefes alışım. Sen benim...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-oldun-benim-dunyam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-hakan-dincel-q5wv1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'EYLÜL

Yapraklarını dökersin ağaçların, düşerler sarı sarı.

İlla ki bırakman mi gerek,

sevenleri de böyle birbirinden ayrı. 

Geldiğinde hep gözlerde biraz  yaş mi olmalı.

Yok mu hiç vicdanın,  yok mu hiç aşka saygı.

Acımasız, umursamaz bir cellat sanki ,

elinde yağlı urganı.

Çaresiz  bırakır, hiç dinlemez aşığı.

Kıskanır, çekemez sanki mutlu olanı.

Bir aydan fazlası,

aşığın bitmez azabı.

Bilememiş yanılmış,

Eylül koymuşlar adını...', 'EYLÜL Yapraklarını dökersin ağaçların, düşerler sarı sarı. İlla ki bırakman mi gerek, sevenleri de böyle birbirinden ayrı.  Geldiğinde hep g...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/eylul-905-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Dönüyor Seninle Bambaşka', 'dunya-donuyor-seninle-bambaska-sairul-i-slam-yunus-kokan-8imcv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aman aman, nedir bu hâlim?

Seni gördüm, değişti âlemim!

Bir gülüşün yetti be güzelim,

Aşkınla şenlendi gönlüm benim.

Gözlerin başka güzel sözlerin başka,

Düştüm güzelim tatlı bir aşka.

Dünya dönüyor seninle bambaşka,

Çıkar yolumuz büyük bir aşka.

Seni gördüğüm o ilk akşam,

Unuttum derdi, unuttum gamı.

Bir baktın bana, yandı bu can,

Sen oldun ömrümün tek sultanı.

Gözlerin başka güzel sözlerin başka,

Düştüm güzelim tatlı bir aşka.

Dünya dönüyor seninle bambaşka,

Çıkar yolumuz büyük bir aşka.', 'Aman aman, nedir bu hâlim? Seni gördüm, değişti âlemim! Bir gülüşün yetti be güzelim, Aşkınla şenlendi gönlüm benim. Gözlerin başka güzel sö...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dunya-donuyor-seninle-bambaska-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hamdüsenalar Olsun', 'hamdusenalar-olsun-nedim-saatcioglu-9d0o6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Son nefes boğazımdan senin adınla geçsin

Can kurban olsun senin o mukaddes ismine

Ruhumun son seferi rahmetine erişsin

Hamdüsenalar olsun âlemlerin Rabbine

Mahşer günü açılsın amellerin defteri

Güneş gibi parlasın ömrümün son seheri

Rahmetinle silinsin günahımın her kiri

Hamdüsenalar olsun âlemlerin Rabbine

Kâbe''nin eşiğinde gönlümün izi vardır

Zemzemin her damlası içimde bir bahardır

Adını anmayan dil kendi içinde hardır

Hamdüsenalar olsun âlemlerin Rabbine

Yedi kat gök şahittir kudretinin adına

Bizleri kabul eyle o mübarek katına 

Kana kana varalım nur cennetin tadına

Hamdüsenalar olsun âlemlerin Rabbine

Gecenin ortasında nurlu kandiller yansın

Her secdede gönlümün karanlığı arınsın

Yer gök senin müstesna adınla yankılansın

Hamdüsenalar olsun âlemlerin Rabbine

Günahım dağlar kadar, tövbem birkaç damla yaş

Kapında secde eder sana muhtaçtır bu baş

Parçalandı gönlümde kibir denen kirli taş

Hamdüsenalar olsun âlemlerin Rabbine

Kaderimin defteri alnımda mühürlenmiş

Her nefesim ezelden duaya düğümlenmiş

Kirpiğim günahlara siyah perdeler çekmiş

Hamdüsenalar olsun âlemlerin Rabbine

Ahiret terazisi tartar mı gözyaşımı

Rahmetinle aydınlat siyah sabır taşımı

Mahşerin ortasında dik tut benim başımı

Hamdüsenalar olsun âlemlerin Rabbine', 'Son nefes boğazımdan senin adınla geçsin Can kurban olsun senin o mukaddes ismine Ruhumun son seferi rahmetine erişsin Hamdüsenalar olsun âl...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/hamdusenalar-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köle', 'kole-hakan-dincel-y3u9o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KÖLE 

Seni anlatabilmek kelimelerle,

acizliğini  vurmak yüzüne alfabenin.

Senin karşında seni konuşmak nedir,

senden almadan izin.

Gönlüm olmuş yangın yerin,

közündür bedenim.

Yak yakabildigin kadar,

korkusu mu olur kölenin...', 'KÖLE  Seni anlatabilmek kelimelerle, acizliğini  vurmak yüzüne alfabenin. Senin karşında seni konuşmak nedir, senden almadan izin. Gönlüm ol...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kole-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VE SON NEFES', 've-son-nefes-muhsin-yener-2-8zp4o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu dünya, taş yürekli kalabalıkların çarşısı
Merhamet, çoğu zaman garip bir yolcu vardır;
Kalbini göğe emanet etmiş birkaç sessiz insan.

Onlar yürüyünce gürültü susar,
Öfkeler secdeye kapanır.
Bir tebessümleri,
Kırık gönüllere rahmet olur.

Ne gösteriş bilirler,
Ne de alkışın kölesi olurlar.
Yükleri sevgidir,
Azıkları duadır.

Ey gönülleri evirip çeviren Rabbim!
Bizi, kalbinde cennet taşıyan kullarına komşu eyle.
Ruhumuza onların edebinden bir damla,
Muhabbetinden bir nefes nasip et.

Çünkü biliyorum;
Dünya, sert olanlarla değil,
Bir yetimin duasını incitmekten korkanlarla ayakta durur.

Ve son nefeste,
Ne servet, ne şöhret, ne de alkış...
Sadece Sen''in rızana yaslanan temiz bir kalp
Kurtuluşa açılan kapıdır.

Amin.

Muhsin yener', 'Bu dünya, taş yürekli kalabalıkların çarşısı Merhamet, çoğu zaman garip bir yolcu vardır; Kalbini göğe emanet etmiş birkaç sessiz insan. Onl...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ve-son-nefes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan', 'hazan-hakan-dincel-yi1pz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'HAZAN 

Denizin üstünde parlayan ışığın gibi,

O yanındayken,  aşığın da parlardi gözleri.

Senin gibi bembeyaz tertemizdi aşkı.

Işığını aşıklara karşılıksız verişin gibi,

O da aşığına herseyini, yüreğini verdi.

Kurban olduğu gözlerin içine, doya doya bakardı.

Çaktırmadan,  gizlice mutluluktan  ağlardı.

Bir hazan vakti, senin gelişin ve gidişin gibi, 

arkasında aşığını bırakıp o da gitti,

yağmurlu, puslu bir hazan vakti.

Kimsenin anlamadığını, aşık nasıl anlasın ki ?

Yağmur döverken usulca aşığı,

hiç kalkmayacak bir dağ oturdu içine sanki.

Ezildi, eridi...

Git bakalım hazan git,

aşkı da götür.

İki elim yakanda olsun derdi aşık belki,

ama diyemedi.

Aşkına nasıl kiysindi ki ?

Onu hiç unutmaz, 

vazgeçemez asla inan ki.

Git hazan git,

hem onu götür,

hem de aşığın yüreğini...', 'HAZAN  Denizin üstünde parlayan ışığın gibi, O yanındayken,  aşığın da parlardi gözleri. Senin gibi bembeyaz tertemizdi aşkı. Işığını aşıkla...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hazan-316-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel de Gör Hâlimi', 'gel-de-gor-h-limi-sairul-i-slam-yunus-kokan-cnqsv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben seni kendimden bile çok sevdim,

Sen gittin, ben kendimi kaybettim.

Ben hayatımın aşkı sandım,

Meğer hayatımın hatasıymış.

Gel de gör hâlimi, ne kaldı benden?

Bir yaralı kalp, bana eser senden.

Gel de gör hâlimi, ne kaldı benden?

Bir yaralı kalp, bana eser senden.

Ah be zalim, ne yaptın bana?

Bir ömürlük sevda yetmedi sana.

Ben seni kalbimin tahtına koydum,

Sen ettin beni yalnızlığa mahkûm.

Gel de gör hâlimi, ne kaldı benden?

Bir yaralı kalp, bana eser senden.

Gel de gör hâlimi, ne kaldı benden?

Bir yaralı kalp, bana eser senden.', 'Ben seni kendimden bile çok sevdim, Sen gittin, ben kendimi kaybettim. Ben hayatımın aşkı sandım, Meğer hayatımın hatasıymış. Gel de gör hâl...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gel-de-gor-halimi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanarsin', 'yanarsin-hakan-dincel-g1qdn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'YANARSİN

Hep ertelenen,

ve hep yalnız başına kurulan hayallerdesin.

Yalnızlığımın ortağı olmuş resmin.

Gece gündüz dilimde,

düşümde,

bir mühürdür beynimde sanki ismin...

Gözlerimin içinde gürül gürül yanansın.

Yalnızlığın ortasında,

soğuğun kucağında,

cayır cayır yakansin. 

Söyle,

şimdi kim,

beni nasıl anlasın.

Ömrüm tutuşmuş,

sırtını dönsen bana, 

buz gibi baksan ya da,

ateşim donmaz,

ateşim soğumaz,  sıcağımda kalırsın.

Közümü, gözlerinin seli söndürür.

Arkamdan bakıp, 

özümü gördüğünde,

soğuguma dokunur,

parmak uçlarından tutuşur,

sende yanarsın...', 'YANARSİN Hep ertelenen, ve hep yalnız başına kurulan hayallerdesin. Yalnızlığımın ortağı olmuş resmin. Gece gündüz dilimde, düşümde, bir müh...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yanarsin-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık Ettin Bize', 'yazik-ettin-bize-sairul-i-slam-yunus-kokan-jyfxp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine gecelerden sen geçiyorsun,

Ben sustukça içimde büyüyorsun.

Bir fotoğraf kaldı senden geriye,

Yıllar geçti unutamıyorum seni hâlâ ne diye?

Ben seni yazmıştım yüreğime.

Ah be zalim, nasıl kıydın bize?

Kadir kıymet bilmedin,

Yazık ettin bize.

Ben seni kalbime ömür diye yazmıştım,

Sen beni geçici bir heves sanmışsın,

Bir gün adımı duyarsan uzaklardan,

Bil ki geçmedim ben o sokaklardan.

Ben seni yazmıştım yüreğime.

Ah be zalim, nasıl kıydın bize?

Kadir kıymet bilmedin,

Yazık ettin bize.', 'Yine gecelerden sen geçiyorsun, Ben sustukça içimde büyüyorsun. Bir fotoğraf kaldı senden geriye, Yıllar geçti unutamıyorum seni hâlâ ne diy...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yazik-ettin-bize-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalin', 'hayalin-hakan-dincel-3w1mh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'HAYALİN

Kapkara bir sessizlik içinde,

herşeyden vazgeçmenin soğuğunda,

üşürken bile, 

nazlı bir peri gibi,

içimi ısıtır hayalin.

Konuşmasanda benimle, vurulmuşum sanki  gölgene. 

Ne kadar da çaresizim sensizligimle...', 'HAYALİN Kapkara bir sessizlik içinde, herşeyden vazgeçmenin soğuğunda, üşürken bile,  nazlı bir peri gibi, içimi ısıtır hayalin. Konuşmasand...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayalin-114-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜNAYDIN CANIM', 'gunaydin-canim-muhsin-yener-2-rlytr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günaydın canım…

Buralarda gökyüzü bulutlu,
Yağmur ince ince çiseliyor.
Sanki gökyüzü de birini özlemiş,
Söyleyemediği sözleri
Damla damla yeryüzüne döküyor.

Sabah, gri bulutların altında uyandı bugün.
Ne güneş kendini gösteriyor
Ne de yağmur vazgeçiyor yağmaktan.
Bir kararsızlık hâli var gökyüzünde,
Tıpkı insanın içinde sakladığı
Söylenmemiş duygular gibi…

Böyle havalarda insan
Biraz kendine dönüyor.
Düşünceler derinleşiyor,
Sessizlik uzuyor,
Özlem daha çok hissediliyor.
Benim de aklıma sen düşüyorsun
Hiç ummadığım bir anda,
Hiç beklemediğim bir sessizlikte…

Merak ediyorum;
Senin oralarda nasıl sabah?
Güneş yüzünü gösteriyor mu?
Yoksa sen de benim gibi
Gri bulutların altında mı uyandın?

Belki de hava sadece bir bahane…
Asıl mesele insanın içindeki iklim.
Kimi yağmur altında bile çiçek açar,
Kimi güneşin en parlak gününde üşür.
Çünkü gökyüzünün rengi değil,
İnsanın yüreğindeki mevsim belirler
Nasıl bir gün yaşayacağını.

Ve sana soracağım
En sade, en güzel soruyu:

Sen nasılsın?

Bil ki bazen bir insanın
İçtenlikle söylediği iki kelime,
En sıcak güneşten,
En güzel bahar sabahından
Daha çok ısıtır insanın yüreğini.

Günaydın canım…
Dilerim bugün yüzün gülsün,
Yüreğine hiçbir bulut gölge düşürmesin.
Yağmur buralarda yağmaya devam etsin,
Ama senin içinde hep bahar olsun.
Muhsin yener', 'Günaydın canım… Buralarda gökyüzü bulutlu, Yağmur ince ince çiseliyor. Sanki gökyüzü de birini özlemiş, Söyleyemediği sözleri Damla damla ye...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/gunaydin-canim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanamazsin', 'dayanamazsin-hakan-dincel-p9k10', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'DAYANAMAZSIN 

Gecelerdir konuşamam,

susarım.

Ağzımı istersen bir kez açarım.

Ama kaciverir 

içimdeki tutsak aşkın.

Koşar sana sarılır,

altında kalır, ezilir,

dayanamazsın...', 'DAYANAMAZSIN  Gecelerdir konuşamam, susarım. Ağzımı istersen bir kez açarım. Ama kaciverir  içimdeki tutsak aşkın. Koşar sana sarılır, altın...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dayanamazsin-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalın Ayak', 'yalin-ayak-sairul-i-slam-yunus-kokan-gpr77', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir fotoğraf kaldı senden duvarımda,

Bir de sensiz geçen ömrüm avuçlarımda.

Adını anmaya korkar oldum gecelerde,

Ben takılı kaldım ismin geçen hecelerde.

Kalbimi benden aldın, geri vermedin,

Bir ömür sevdim, sen değer bilmedin.

Ben sana gönlümün kapısını açtım,

Sen bu sevdadan yalın ayak kaçtın.

Gözlerim yollarında, ömrüm yarım kaldı,

Sana açtığım bu kalp, kendine daraldı.

Ben seni Allah''tan ne çok dilemiştim,

Sen beni bir yabancı gibi terk etmiştin.

Kalbimi benden aldın, geri vermedin,

Bir ömür sevdim, sen değer bilmedin.

Ben sana gönlümün kapısını açtım,

Sen bu sevdadan yalın ayak kaçtın.', 'Bir fotoğraf kaldı senden duvarımda, Bir de sensiz geçen ömrüm avuçlarımda. Adını anmaya korkar oldum gecelerde, Ben takılı kaldım ismin geç...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalin-ayak-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Liman', 'son-liman-tuncer-olgun-r1io0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Göğün en ıssız yerinde kalmışız,

Yeryüzü çok uzak, sığınaklar yabancı.

Bir zamanlar rüzgârla yarışan kanatlarımız nerede şimdi?

Yalnızca hüzünle, yorgunlukla çarpıyor yüreklerimiz.

​Adını koyamadığımız bir hasretin orta yerindeyiz;

Ne geriye dönecek dermanımız kaldı,

Ne de ileriye atılacak tek bir adım...

Biz bu dünyanın en sessiz mültecileriyiz,

Yaralarımız birbirine benziyor

Ve aynı göğün altında kaybolmuşuz çoktan.

Yine de o kırık kanatlarla yürürüz belki;

Bizi ya düştüğümüz o eski yerlere götürür bu yol,

Ya da ikimizin de bildiği o tek son limana...', 'Göğün en ıssız yerinde kalmışız, Yeryüzü çok uzak, sığınaklar yabancı. Bir zamanlar rüzgârla yarışan kanatlarımız nerede şimdi? Yalnızca hüz...', ARRAY['Türk Edebiyatı','Şiir','Tuncer Ölgün']::text[], 8.5, '{"poet":"Tuncer Ölgün","poet_slug":"tuncer-olgun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-liman-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEN', 'sen-muhsin-yener-2-c5ynr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen
damarlarımda dolaşan kan,
içimde atan hayatın ta kendisisin.

Kalbimin sahibi sensin,
adını her atışta fısıldayan…

Senden öğrendim
arkadaşlığı,
dostluğu,
ve en çok da
sevmeyi.

Seni düşündüm,
her defasında başka sevdim seni.
Gülümsemeyi sende buldum,
ve her gülüşüm biraz sen oldu.

Seni düşündüm,
bir başka aydınlandı içim,
bir başka çoğaldı gülüşlerim.

Sevginle tanıdım sevgiyi,
sevginle sevdim dünyayı…
Ve seni,
defalarca,
yeniden sevdim.

Gülüşünü sevdim,
sesini,
suskunluğunu bile…

Sana dair ne varsa
hepsini sevdim.
Ben seni sevdim,
hayat arkadaşım…

Gözlerimde parlayan ışık,
yüreğimin tek sahibi,
çocuklarımın annesi.

Ben,
bir tek seni sevdim.Sen,
damarlarımda dolaşan kan,
içimde atan hayatın ta kendisisin.
Kalbimin sahibi sensin,
adını her atışta fısıldayan…

Senden öğrendim
arkadaşlığı,
dostluğu,
ve en çok da
sevmeyi.

Seni düşündüm,
her defasında başka sevdim seni.
Gülümsemeyi sende buldum,
ve her gülüşüm biraz sen oldu.

Seni düşündüm,
bir başka aydınlandı içim,
bir başka çoğaldı gülüşlerim.
Sevginle tanıdım sevgiyi,
sevginle sevdim dünyayı…

Ve seni,
defalarca,
yeniden sevdim.
Gülüşünü sevdim,
sesini,
suskunluğunu bile…

Sana dair ne varsa
hepsini sevdim.
Ben seni sevdim,
hayat arkadaşım…

Gözlerimde parlayan ışık,
yüreğimin tek sahibi,
çocuklarımın annesi…

Ben,
bir tek seni sevdim.
Muhsin yener', 'Sen damarlarımda dolaşan kan, içimde atan hayatın ta kendisisin. Kalbimin sahibi sensin, adını her atışta fısıldayan… Senden öğrendim arkada...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/sen-4579-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Unutamam', 'ben-unutamam-sairul-i-slam-yunus-kokan-1z6lk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaç gece adını andım, duymadın sesimi,

Kaç kere öldüm görmedin hâlimi,

Ben sana bir ömürlük sevda vermişken,

Sen neden yarım bıraktın bu yüreği?

Herkes unutur da ben unutamam,

Başkasını senin yerine koyamam.

Herkes unutur da ben unutamam,

Başkasını senin yerine koyamam.

Ah be zalim, ne istedin benden?

Bir canım vardı, onu da aldın elimden.

Ben seni Allah''tan dilerken her gece,

Sen nasıl sildin bu aşkı tek kalemde?

Herkes unutur da ben unutamam,

Başkasını senin yerine koyamam.

Herkes unutur da ben unutamam,

Başkasını senin yerine koyamam.', 'Kaç gece adını andım, duymadın sesimi, Kaç kere öldüm görmedin hâlimi, Ben sana bir ömürlük sevda vermişken, Sen neden yarım bıraktın bu yür...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-unutamam-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞİİR OLMAK', 'si-i-r-olmak-muhsin-yener-2-hysx2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiir yazarım
şiir okurum
şiir düşünürüm
şiir konuşurum

kelimeler değil benimkisi,
içimde yankılanan bir ses
bu yüzden
şiirle kızarım dünyaya

şiirle gülümserim hayata
gözlerim dolduğunda
şiir akar içimden

sessizce, kimse duymadan
ne varsa bende

mısralara sığdırırım
ve her defasında

yeniden doğar içimde
bir şiir…
Muhsin yener', 'Şiir yazarım şiir okurum şiir düşünürüm şiir konuşurum kelimeler değil benimkisi, içimde yankılanan bir ses bu yüzden şiirle kızarım dünyaya...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/siir-olmak-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan Yağmuru', 'hazan-yagmuru-hakan-dincel-4dhjh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'HAZAN YAĞMURU 

Dışarda hazan yağmuru,

temizlerken ortalığı.

içerde aşığın göz yaşı, 

siliyor yürekteki kanı, yarayı,

temizliyor acıyı.

Damla damla gelen hazan yağmuru,

can olmaz ama toprağa düşmüş yaprağa.

Sel olmuş gelen aşığın yağmuru,

nefes olur, can olur,

kalpte tutsak sevdaya...', 'HAZAN YAĞMURU  Dışarda hazan yağmuru, temizlerken ortalığı. içerde aşığın göz yaşı,  siliyor yürekteki kanı, yarayı, temizliyor acıyı. Damla...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hazan-yagmuru-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimi Bulamadım', 'kendimi-bulamadim-sairul-i-slam-yunus-kokan-3a6rn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir fotoğrafın kaldı, duvarda asılı,

Gözlerim arıyor seni, gecenin yarısı.

Sen benim kalbimin dinmeyen yarası,

Sen benim başımın tatlı belası.

Ben seni sevmekten hiç usanmadım,

Sen benim sevgime layık olamadın,

Bir kalbi kırdın da dönüp bakmadın,

Ben seni kaybettim, kendimi bulamadım.

Herkes unutur da ben unutamam,

Başkasını senin yerine koyamam,

Ben seni gönlüme ömür diye yazdım,

Sen bir heves sandın, aldandın.

Ben seni sevmekten hiç usanmadım,

Sen benim sevgime layık olamadın,

Bir kalbi kırdın da dönüp bakmadın,

Ben seni kaybettim, kendimi bulamadım.', 'Bir fotoğrafın kaldı, duvarda asılı, Gözlerim arıyor seni, gecenin yarısı. Sen benim kalbimin dinmeyen yarası, Sen benim başımın tatlı belas...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kendimi-bulamadim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülsün', 'gulsun-hakan-dincel-6sm7e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'GÜLSÜN 

Günler, geceler, ömrüm   birleşmiş seninle,  sımsıkı birleşen eller gibi tıpkı ,

Ümitvar,  mutlu yarınlara, birlikte yürünen tertemiz, sadık bir yol arkadaşı.

Lise aşklarından gelen,  bir esintidir, kalpler ferahlatır, yanından geçerken savurduğu rüzgarı,

Silinir, unutulur mu hiç gönüllerde, yılmadan, yıkılmadan  fedakarca yaptıkları,

Üzmez üzülse bile, göz yaşını içine akıtır, kalplerin hanım  sultanı, 

Masallardan çıkmış gibi tavrı, endamı,  parıldar  kara gözleri, avutur darda kalanı...

Dize dize,  hece hece şiir olmuş ömrüm ayaklarının önüne,

İlham olmuş tatlı dili, sözlerin en güzeline.

Nasıl izin verir, lal olsa dilim, hakkında  bir kötü söz söyleyene,

Cemali benzer , doğarken geceyi delen,  yok eden asil güneşe,

Eritir hilal kaşı, bitirir bir bakışı, aklını alır, döndürür deli  divaneye, 

Lavantalar, güller içinden yürür gelir,  şifadır sözleri,  mahsun kalmış  gönüllere...', 'GÜLSÜN  Günler, geceler, ömrüm   birleşmiş seninle,  sımsıkı birleşen eller gibi tıpkı , Ümitvar,  mutlu yarınlara, birlikte yürünen tertemi...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gulsun-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Nasıl Vicdan?', 'bu-nasil-vicdan-sairul-i-slam-yunus-kokan-90kkb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir seni sevdim, bin derde düştüm,

Gülüşüne kandım, kendimden geçtim.

Ben senin ardından kışlara düştüm.

Sayende sevgiye, aşka küstüm.

Bir damla sevginle yaşardım inan,

Şimdi yaşadıklarımızın hepsi oldu yalan,

Aşkımı duysa ağlar tüm cihan,

Bu nasıl sevmek, bu nasıl vicdan?

Adını andıkça yanar bu yüreğim,

Sendin benim ilk ve son dileğim.

Seni sevmek suç muydu, söyle sevdiğim?

Sana ömrümü verdim, sen terk edip gittin.

Bir damla sevginle yaşardım inan,

Şimdi yaşadıklarımızın hepsi oldu yalan,

Aşkımı duysa ağlar tüm cihan,

Bu nasıl sevmek, bu nasıl vicdan?', 'Bir seni sevdim, bin derde düştüm, Gülüşüne kandım, kendimden geçtim. Ben senin ardından kışlara düştüm. Sayende sevgiye, aşka küstüm. Bir d...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-nasil-vicdan-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınsın', 'kadinsin-hakan-dincel-ud1po', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'KADINSIN 

Kadınsın, anasın, yarsın, hayatsın.

Sevdiğinin yanında olmuşsun her zaman,

Vazgeçilmez bir dayanak.

Çocuklarına gerilmiş ,

sanki çelikten yapılmış,

kırılmaz birer kol kanat.

‌

Yaptığın zor işler,

hem azalmaz, hemde bitmez.

Taş ortadan çatlar da,

sende sabır tükenmez.

Sevgiyle işini yapar.

Seyreden yorulur da,

o bir an bile vazgeçmez.

Hep vardır kuvveti gücü, 

birkez olsun pes etmez.

Süper kahramanların,

ete kemiğe bürünmüş hali.

Zamanı durdurur sanki,

bulaşık suyundan çıkarıp,

havaya kaldırdığı elleri.

Kadınsın, anasın, yarsın, hayatsın.

Can olmuşsun garip kalan canlara.

Varsın hep, gösterilirsin sevdiğinin yanında.

Çıkarsızca  ortaksın,

hem mutluluğa, hem  acıya.

Yaptıkların unutulmaz, 

can tende  oldukça...', 'KADINSIN  Kadınsın, anasın, yarsın, hayatsın. Sevdiğinin yanında olmuşsun her zaman, Vazgeçilmez bir dayanak. Çocuklarına gerilmiş , sanki ç...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kadinsin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boncuk Boncuk', 'boncuk-boncuk-sairul-i-slam-yunus-kokan-ih2cr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu nasıl bir sevdadır?

Hâlim yamandır,

Sen geldin ya güzelim,

Dünya bana bayramdır!

Gözlerin boncuk boncuk,

Bakışların baldan tatlı.

Bir gülüşün bana yetti,

Tüm dertlerim uçup gitti.

Sevmeyi senden öğrendim,

Aşkınla yeniden doğdum.

Ne varsa dünyada güzel,

Hepsini sende buldum.

Gözlerin boncuk boncuk,

Bakışların baldan tatlı.

Bir gülüşün bana yetti,

Tüm dertlerim uçup gitti.', 'Bu nasıl bir sevdadır? Hâlim yamandır, Sen geldin ya güzelim, Dünya bana bayramdır! Gözlerin boncuk boncuk, Bakışların baldan tatlı. Bir gül...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/boncuk-boncuk-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter', 'yeter-hakan-dincel-sxvmn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'YETER 

Atmasın carpmasin yürek senin isminle,

dursun artık sayiklamasin dil,

hece hece ismini gecelerce.

Akmasın artık gözyaşı,

olur olmaz her vakitte.

Yeter,

görmesin gözler seni,

baktıkları her yerde.

Sıkışmasın nefes taa içerlerde.

Ya da son gelsin artık,

gitsin hepsi, 

biran önce gideceği yere...', 'YETER  Atmasın carpmasin yürek senin isminle, dursun artık sayiklamasin dil, hece hece ismini gecelerce. Akmasın artık gözyaşı, olur olmaz h...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yeter-565-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyledi hakim bey valla söyledi', 'soyledi-hakim-bey-valla-soyledi-fatih-tutuk-nk9cw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalancı denirmi insan yüzüne 

Söyledi hakim bey valla söyledi 

Ínanmadi zaten hiç bir sözüne 

Söyledi hakim bey valla söyledi

Sizi silivriye tutup atmalı 

Üstünüze demir kapı yapmalı 

Yemin edenler doğru olmalı 

Söyledi hakim bey valla söyledi

Gelenin yalanlar çıktı koynunda 

Canına tak etti artık onunda 

Para vereyim mi dedi sonunda 

Söyledi hakim bey valla söyledi

Fatih TUTUK

16/11/2026', 'Yalancı denirmi insan yüzüne  Söyledi hakim bey valla söyledi  Ínanmadi zaten hiç bir sözüne  Söyledi hakim bey valla söyledi Sizi silivriye...', ARRAY['Türk Edebiyatı','Şiir','Fatih Tutuk']::text[], 8.5, '{"poet":"Fatih Tutuk","poet_slug":"fatih-tutuk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/soyledi-hakim-bey-valla-soyledi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gülüşün Yeter Bana', 'bir-gulusun-yeter-bana-sairul-i-slam-yunus-kokan-unj6l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aman Allah''ım, bu nasıl sevda!

Gözlerine baktım, döndü dünya!

Ben böyle aşk görmedim ömrümde,

Sen varsın artık hep gönlümde!

Aşkın delisiyim, yana yana,

Gecem gündüzüm, hep sana,

Bir gülüşün yeter bana,

Değişmem tüm dünyaya.

Ne kadehim var ne de meyhanem,

Sen oldun benim en güzel hanem.

Sen baharsın, sen bir gülsün,

Sen gül yeter, gönlüm gülsün!

Aşkın delisiyim, yana yana,

Gecem gündüzüm, hep sana,

Bir gülüşün yeter bana,

Değişmem tüm dünyaya.', 'Aman Allah''ım, bu nasıl sevda! Gözlerine baktım, döndü dünya! Ben böyle aşk görmedim ömrümde, Sen varsın artık hep gönlümde! Aşkın delisiyim...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gulusun-yeter-bana-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-hakan-dincel-fwbyt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SEN 

Aklımda sen,

yanımda yalnızlığım, 

gözümde yaşım,

dilimde adın.

Söyle,

ne anlamı var ki,

sen olmadan yaşamanın  ?

Sen yoksan ,

ekmeğin, aşın,

sen yoksan rüyaların,

konuşmanın, yazmanın,

şiirin, şarkının,

gökteki ayın,

sen yoksan, 

kalpte yananin,

anlamı var mı yaşamanın ?

Gitme diyorsun,

gitmiyorum.

Kapat gözlerini, 

göz yaşında eriyip, 

sende yok oluyorum...', 'SEN  Aklımda sen, yanımda yalnızlığım,  gözümde yaşım, dilimde adın. Söyle, ne anlamı var ki, sen olmadan yaşamanın  ? Sen yoksan , ekmeğin,...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-4578-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın', 'askin-hakan-dincel-00kxk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'AŞKIN

Ağını ağır ağır çeken tayfalar gibi, 

çektim yüreğime aşkını.

Hem aşkını, hem çilesini,

Bir zerresi bile kaçıp gitsin istemedim benden.

Sanki gitse, ardına bakmadan giden küskün bir aşık gibi,

ruhum çıkacak sanırdım bu bedenden.

Vazgeçmek kolay mı hiç, aşkından, senden ?

Zor bile değil,

imkansızımken...', 'AŞKIN Ağını ağır ağır çeken tayfalar gibi,  çektim yüreğime aşkını. Hem aşkını, hem çilesini, Bir zerresi bile kaçıp gitsin istemedim benden...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/askin-90-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-hakan-dincel-yvql9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'HASRET

Ezip dağlarken yüreği ayrılık acısı,

Bir an gitmez gözlerinin önünden sevdiklerinin hayali,

Geçmez yüreğinden hasret sancısı.

Kavuşmak ister tenler ama,

nefesler,  günler kalmışken geride sayılı,

birer birer tükenir ümitler, 

çaresizliktir avuclarda,

eller kollar bağlı, yollar kapalı.

Sadece rüyalarda görebilmek belkide en acısı.', 'HASRET Ezip dağlarken yüreği ayrılık acısı, Bir an gitmez gözlerinin önünden sevdiklerinin hayali, Geçmez yüreğinden hasret sancısı. Kavuşma...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hasret-1967-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delikanlı', 'delikanli-hakan-dincel-798qm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'DELİKANLI 

Kaçak ve kesik bakışlarda buluşan,

aşıkların mutluluğuydu hayat bir zamanlar,

En deli, en delikanlı ve en güzel çağlarında onların.

3 saniyelik bakışı,

3 saatlik hayallere taşırlardı,

sırtüstü yatmışken,

ve kalkamazken bir türlü yataktan.

Hatta gözler ayrılamazdı hiç,

o kireç beyazı tavandan. 

Zorlukları,

kahpece kurulmuş tuzakları, aşmaya güçleri olmasada,

yiğitlerdi onlar.

Yiğit, delikanlı çocuklardı.

Aşk dolu, tertemiz, deli ve kocaman yürekleri olan.

Yarinin elini,  sanki eşinin eliymis gibi tutan,

verdiği sözden dönmeyip,

şerefle, onurla, ölümüne sözünü tutan,

Sevdiğinin hayaliyle yatıp, sevdiğinin hayaliyle kalkan,

tertemiz aşkını kirletmeyen,

aşkına toz kondurmayan ,

deli ve kocaman yüreklerin zamanıydı o zaman.

Gittiler birgün,

kendilerini kimsesiz bir çocuk gibi yapayalnız bırakan,

Sevdalılarının yanında götürdükleri,

çeyizlerin arasında gittiler.

Kokusuna dayanamadiklarinin ,

giysilerinin arasında, 

sevdanın kokusunu koklaya koklaya gittiler.

Gittiler,

tertemiz hayallerin peşinde,

bir uçurumdan düşerken  ve kahkahalarla gülerken gittiler. 

Çığlıklarla susarken yürek,

ağlarken kuytu köşelerde kimse görmeden,

ve akan yaşları gizleyerek,

kimseye eyvallah demeden,

kimseden de birşey istemeden gittiler.

Hayatla bir dargın, bir barışık,

kalplerinde herşeye rağmen,

toz kondurmadiklari vefasız aşık.

Gittiler,

başlar dik, kalpler kırık.

Var görünürlerdi ama yoktular.

Çünkü gittiler onlar, 

onlar çoktan gittiler 

ve var görünen yoktular artık...', 'DELİKANLI  Kaçak ve kesik bakışlarda buluşan, aşıkların mutluluğuydu hayat bir zamanlar, En deli, en delikanlı ve en güzel çağlarında onları...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/delikanli-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Sınav', 'i-lk-sinav-hakan-dincel-bgtxy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İLK SINAV 

Altındağ ın adıyla tezat eteklerinden,

Aydınlıkevlerin adıyla müsemma lisesinde öğrenci olmak için,

her gün yollar tepildi,

o ergen, o asi, o aşık ayaklarla.

Kışın soğuğunda ayaklar dona dona,

yazın sıcağında ter içinde,

çöl susuzluğunda kuruyan bir ağızla.

Yolda giderken hayaller eşlik etti,

dönüşte ise aşklar,

gece karanlığında,

Ankara''nın  sisli, kirli ama romantik akşamlarında.

Kareli etekli aşkla, buluşma heyecanıydı mutluluk.

Gözler parlayarak atılırdı çanta,

minicik evin, minicik odasının, masmavi duvarına,

ergence ve asice bir hışımla.

Hayat, okul, aşkdan ve kahkahadan ibaretti.

Ders yoktu sanki,

dışarıda verilecek olandan başka,

lisenin soğuk duvarları arasında, kocaman ve  kalabalık bir  sınıfda.

Yarın ela gözleri ısıtırdı, 

soğuk duvarlardan üşüyen elleri ve gözleri adeta.

Yarin hayali dersi anlatır,

annesi sınavı yapardı acımasızca.

Kalırdı geçemezdi aşk sınavından.

hayatı ve insanın vahşiliğini bilmeyen ergen yürek,

geçemezdi aşk sınavını asla.

En güzel yıllar,

en güzel anılara şahitlik ederken,

duyguları, kalbi kopardı erkenden,

ham bir meyveyi, açmamış bir çiçeği, değil koparmak,

ayağının altında adeta zıplaya zıplaya ezip bir hışımla yere gömen.

Dersler, zaman adeta bir film şeridi gibi gözünün önünden geçerken, 

hayaller bakıp seyretti, 

bir gazete haberini dehşetle okuyan  zalim, insafsız bir komşu gibi fakirlik kokan mahalleden.

Yenildi minik ergen, yenilmeyi öğrendi erkenden.

Demek ki dedi çok sevmek önemli değildi.

Önemsizdi demek ki, 

deli gibi seven kocaman bir yürek,

zengin, çıkarcı ve sevmeyen minicik  bir yürekten.

Boyuna posuna bakmadan sevmişti ,

yüreğinin büyüklüğüne güvenen.

Ama yenilmişti işte,

uzun boya, dolu bir cebe ve minicik bir yüreğe,

hiç beklenmeyen bir anda 

ve çok erkenden...', 'İLK SINAV  Altındağ ın adıyla tezat eteklerinden, Aydınlıkevlerin adıyla müsemma lisesinde öğrenci olmak için, her gün yollar tepildi, o erg...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ilk-sinav-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-hakan-dincel-ethe0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ANNEM 

Bilsen

gelmek ne zor oldu,

en güzel diyarlari bırakıp da  arkamda , 

bir daha hiç kopmamak üzere  bağlanarak sana,

9 ay 10 gün süren bir yolculukla, 

sürgün olmak  bu sahte dünyaya.

İçindeyken senin,  koyu bir karanlığın,

ve bir dehlizin adeta,

günler hızla sayıldı.

Kokunu alırken, 

ama seni göremezken, 

sanki uzaktaymışım gibi sana.

Hiç  farkına bile varamadan, 

su gibi akan zamanın,

ve huzur dolu, tertemiz bir suyun ortasında.

O gün geldiğinde,

yani indiğimde

en güzel diyarlardan

yeryüzünde yanı başına,

ağladım, yabancı soğuk kollarda, hıçkıra hıçkıra.

Duygular karmakarışık ,

rüyada,

cemali gösterilen meleği, seni görünce karşımda,

bir salı günü,

sabaha karşı doğduğumda,

gül  kokan teninin kokusuyla hatırladım hemen,

Cennetin o eşsiz kokusunu,

ve beni gönderenin kim olduğunu sana.

Ve sustum

ağlarken hıçkırıklarla ,

sımsıcak sarılıp, 

aldığında kollarının arasına.

Sanki, içinden çıktığım meleğin içine, 

geri girebilmek için,

emerken seni büyük  bir hırsla ,

kalbinin attığı yerden, göğsünden,

nefessiz kalıp boğulurcasına.

Ve hayran hayran bakarken

gözlerinin içine,

yaşlar süzüldü,

dayanamadın, ağladın bakarken bana.

Sen ağlıyorsan,

iyi bişeydir sanıp, 

yeniden ağlamaya başladığımda,

başımı okşayışın,

tenime kondurduğun öpücük getirdi

kendime beni bir anda. 

İçime çektim,  içime seni,

hiç ayrılmamacasına.

Birlikte koşarken

seninle kırlarda,

oyunlar oynarken

doyasıya,

hiç bırakmasın beni derken ,

artık ayaklarımın üzerinde durabildiğimde  birgün,

kendi ayaklarımla ayrıldım senden,

kendi ayaklarım ayırdı seni benden.

İnan ki, inan ki bana güzel annem, 

acı yok,

ayrılık yok, 

hasret yok,

mutluluk, kavuşmak var,

geri döneceğimiz gerçek yurtta.

İyi ki doğdun güzel annem,

iyi ki doğdun,

al bu canı, 

al, yine koy  içinde sakla...', 'ANNEM  Bilsen gelmek ne zor oldu, en güzel diyarlari bırakıp da  arkamda ,  bir daha hiç kopmamak üzere  bağlanarak sana, 9 ay 10 gün süren ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/annem-1667-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-hakan-dincel-balkt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mutluluğun bile göz yaşıyla geldiği,

hüzünlü bir hikayedir şiir.

İlmek ilmek örülür duygular,

haykırır aşkını şiir, duymaz sevilen,

sanki olmuş, kör sağır bir duvar...

Özlemdir memlekete, gençliğe, sevgiye,sevgiliye,  çocukluğa, doğaya,

ve  hepsini bir bir Yaratana...

İlahi Aşkdan süzülür gelir şiir,

herhalukarda yürekleri titretir.

Şiir aşka, aşk Allah''a,

Bunu ruhun bilir...', 'Mutluluğun bile göz yaşıyla geldiği, hüzünlü bir hikayedir şiir. İlmek ilmek örülür duygular, haykırır aşkını şiir, duymaz sevilen, sanki ol...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/siir-974-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaylılar kedi köpekten dünyaya gelemiyor', 'uzaylilar-kedi-kopekten-dunyaya-gelemiyor-yusuf-tuna-e9e9i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzaylıların en çok korktuğu kedi ile köpektir,

Uzaylılar kedi köpekten dünyaya gelemiyor.

Uzaylı olanların giydiği elbise ipektir,

Uzaylılar kedi köpekten dünyaya gelemiyor.

Uzaylılar fenerle gök yüzünde ateş yakarlar,

Bazen dünyaya kadar gelip uzaktan bakarlar..

Kedi köpek yüzünden dünyaya gelmeye korkarlar,

Uzaylılar kedi köpekten dünyaya gelemiyor.

Onlar kedi köpeğe bizim kadar düşkün değiller,

Onlar alt yapıda bizim kadar gelişkin değiller.

Onlar kedi ve köpeklere alışkın değiller,

Uzaylılar kedi köpekten dünyaya gelemiyor.

Uzaylılar kedi görünce havaya uçuyorlar,

Uzaylılar köpek görünce kendinden geçiyorlar.

Uzaylılar kedi köpekten korkarak kaçıyorlar,

Uzaylılar kedi köpekten dünyaya gelemiyor.

Yusuf Ahir Zamanda bunlara alışmış olurlar,

Zaman geldiğinde onlar da dünyamızı bulurlar.

Kedi köpek nesli azalınca dünyaya gelirler,

Uzaylılar kedi köpekten dünyaya gelemiyor.', 'Uzaylıların en çok korktuğu kedi ile köpektir, Uzaylılar kedi köpekten dünyaya gelemiyor. Uzaylı olanların giydiği elbise ipektir, Uzaylılar...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Tuna']::text[], 8.5, '{"poet":"Yusuf Tuna","poet_slug":"yusuf-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uzaylilar-kedi-kopekten-dunyaya-gelemiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter Artık', 'yeter-artik-okay-kilic-l6h6v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YETER ARTIK !

Enkaz oldu mescitler,

Enkaz oldu medreseler,

Göz nuru can evi hastaneler.

Virane oldu evler barklar

Kana bulandı kutsal topraklar…

Gözünü yummakla geçmiyor

Filistinlilerin kabusları,

Geçmiyor karabasanları.

Gazze uğruna,Kudüs uğruna

Yandı yok oldu o güzelim canlar…

Silmekle geçmiyor 

Ninelerin dedelerin gözyaşları,

Dinmiyor anaların feryatları.

Babaların kollarında yatıyor 

Parçalanmış kınalı çocuklar…

Yeter artık!

Bitsin sıkılan kurşunlar,

Dursun atılan bombalar.

Duyulsun yakarışlarımız

Helak olsun tüm firevunlar…

Yeter artık!

Yetsin verilen kurbanlar,

Dinsin oluk oluk akan kanlar.

Kabul olsun dualarımız

Sarılsın zalimin açtığı yaralar…

Yeter artık!

İnsafa gelsin tüm insanlar,

Vicdana gelsin Hristiyanlar,

Museviler, Budistler, Hindular

Ağıt yakmasın Müslümanlar…

OKAY KILIÇ', 'YETER ARTIK ! Enkaz oldu mescitler, Enkaz oldu medreseler, Göz nuru can evi hastaneler. Virane oldu evler barklar Kana bulandı kutsal toprak...', ARRAY['Türk Edebiyatı','Şiir','Okay Kılıç']::text[], 8.5, '{"poet":"Okay Kılıç","poet_slug":"okay-kilic","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yeter-artik-178-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlere Dair', 'gozlere-dair-tahir-sariisik-f8ocq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Göz gözlere değdi

Göz nazara değdi

Gözler nâra değdi

Gözler göze geldi

Göz nazara geldi

Gözler nâra geldi.

Gözler değdi geldi

Gözler geldi değdi

Nazar nâra değdi

Nâr nazara geldi

Göz, nâr geldi değdi,

Geldi nazara değdi', 'Göz gözlere değdi Göz nazara değdi Gözler nâra değdi Gözler göze geldi Göz nazara geldi Gözler nâra geldi. Gözler değdi geldi Gözler geldi d...', ARRAY['Türk Edebiyatı','Şiir','Tahir Sarıışık']::text[], 8.5, '{"poet":"Tahir Sarıışık","poet_slug":"tahir-sariisik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlere-dair-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Moruklar', 'moruklar-kasim-kobakci-6ezo0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soğuk ayazda dondu moruklar,

Yüzü buruşuk soldu moruklar,

Hemen içeri doldu moruklar,

Sıcak masayı buldu moruklar.

Titreyen eller çayı tutamaz,

Soğuk ayazı kimse yutamaz.

*

Garson kapıyı kapatıp geldi,

Hohlayan ele içkiyi verdi,

Kış aylarını severek bildi,

Dışarı bakıp şükre yöneldi.

Dışardakiler yuva kuramaz,

Allah yardım et, kimse saramaz.

*

Son gelen moruk saate baktı,

Aynı zamanda evine aktı,

Takvimden yaprak koparıp yaktı,

Erkenden anıp ocağı çaktı.

Kapı çalınmış moruk duramaz,

Bir çay koy, ayaz sana yaramaz.', 'Soğuk ayazda dondu moruklar, Yüzü buruşuk soldu moruklar, Hemen içeri doldu moruklar, Sıcak masayı buldu moruklar. Titreyen eller çayı tutam...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/moruklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Gidi Cimcime Seni', 'seni-gidi-cimcime-seni-tahir-sariisik-kcy9x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni gidi cimcime seni

Söyle vereyim kime seni,

Bitmez oyunun cimcime seni,

Söyle ne edeyim kime seni.

Elin işte gözün oynaşta,

Sabır çatlar taşta,

Kalemi koydun kaşta,

Akıl koymadın başta,

Seni gidi cimcime seni

Söyle vereyim kime seni,

Bitmez oyunun cimcime seni,

Söyle ne edeyim kime seni.

İşine akıl sır ermez,

Dur durak bilmez,

Şeytan tüyü var sanki

Kimse sana hayır demez

Seni gidi cimcime seni

Söyle vereyim kime seni,

Bitmez oyunun cimcime seni,

Söyle ne edeyim kime seni.', 'Seni gidi cimcime seni Söyle vereyim kime seni, Bitmez oyunun cimcime seni, Söyle ne edeyim kime seni. Elin işte gözün oynaşta, Sabır çatlar...', ARRAY['Türk Edebiyatı','Şiir','Tahir Sarıışık']::text[], 8.5, '{"poet":"Tahir Sarıışık","poet_slug":"tahir-sariisik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seni-gidi-cimcime-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisa''nın sevgili annenesi', 'nisa-nin-sevgili-annenesi-muhsin-yener-2-qjjjc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gülüşü güzel,
bakışı içime dokunan kadınım

Saçlarında baharı saklayan,
bir mevsimi omuzlarında taşıyan,
konuşurken kelimeleri
şairlere emanet eden

Sen,
yüce Yaradan’ın
özenerek yazdığı bir cümlesin.

Varlığın,
dertlerime şifa,
yokluğun
ölüme denk bir sessizlik

Yüreğin,
cennetten bir köşe gibi;
huzur kokan,
mis gibi amberle sarılmış.

İki çocuğumun annesi,
torunumuz Nisa''nın sevgili annenesi,
evimizin ışığı,
duvarlarına can veren nefes

Sen,
benim hayat arkadaşım,
ömürlük yolum,
en güzel alışkanlığım

Sabriye’m,
adını her andığımda
kalbim biraz daha
evine dönüyor…
Muhsin yener', 'Gülüşü güzel, bakışı içime dokunan kadınım Saçlarında baharı saklayan, bir mevsimi omuzlarında taşıyan, konuşurken kelimeleri şairlere emane...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/nisa-nin-sevgili-annenesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'London Beauty', 'london-beauty-tahir-sariisik-niwng', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I saw you one Wednesday evening, London beauty

You were so cool, so attractive

You stole my mind, my heart,

You took me away from myself

I couldn''t even ask your name from excitement

For me, your name is London beauty

You were dancing like birds,

You were smiling like flowers,

I melted before you like snow

London beauty who made butterflies flutter in my stomach

I couldn''t even ask your name from excitement

For me, your name is London beauty

Come again on Wednesday nights,

If I have the courage, hear these words from me

You are in my mind, you are in my heart

I think I fell in love with you, London beauty.

-------------------------------------------------------------------

Bir çarşamba akşamı gördüm seni Londra güzeli

Çok havalıydın, çok çekici

Aklımı, kalbimi çaldın,

Beni benden aldın

Adını bile soramadım heyecandan

Benim için ismin Londra güzeli

Dans ediyordun kuşlar gibi,

Gülüyordun çiçekler gibi,

Eridim karşında karlar gibi

İçimde kelebekler uçuran Londra güzeli

Adını bile soramadım heyecandan

Benim için ismin Londra güzeli

Bir daha gel Çarşamba geceleri,

Cesaretim olursa benden duy bu sözleri

Aklımdasın,Kalbimdesin

Seni sevdim galiba Londra güzeli.', 'I saw you one Wednesday evening, London beauty You were so cool, so attractive You stole my mind, my heart, You took me away from myself I c...', ARRAY['Türk Edebiyatı','Şiir','Tahir Sarıışık']::text[], 8.5, '{"poet":"Tahir Sarıışık","poet_slug":"tahir-sariisik","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/londra-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Noktası', 'son-noktasi-ugur-musab-sahin-b7d39', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yahudi sonunun başlangıcı, varlığının sonundadır.

İçten içe çöküşün mimarı, yıkılışının imarındadır.

Allah’ın lanetine muhatap, İblisin nikâhlı zevcesi,

Sıkışmanın son noktası, boşalma başlangıcındadır.

Bunca beddualarla dışlanmak Yahudileri boğmakta,

Bütün dünyanın duyduğu kin ve nefretinde farkında.

Bu korkak kavim gücünü tefecilikten, kapitalden alır.

Vaat edilen topraklar yalanına, dünya inanmamakta.

Bin yılı aşkın horlanmışlığın, itilmişliğin isyanındalar

Bir o kadarda geçmişte, onca ülkelerden kovulmuşlar,

“Zalime merhamet zulme sıra girmektir” derler ya,

Merhamet eden Osmanlı devletini sırtından vurmuşlar.

Bu peygamberler katili, beşeriyetin yüzkarası millet,

Tarih boyunca iyi bakın, kuramamışlar hiçbir devlet.

Atalarıyla, övünemeyen başka bir millet bulamazsınız,

Her milletin yüreğinde kanayan bir nankörlük, ihanet. 

20266', 'Yahudi sonunun başlangıcı, varlığının sonundadır. İçten içe çöküşün mimarı, yıkılışının imarındadır. Allah’ın lanetine muhatap, İblisin nikâ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Musab Şahin']::text[], 8.5, '{"poet":"Uğur Musab Şahin","poet_slug":"ugur-musab-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/son-noktasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
