INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesela', 'mesela-kasim-kobakci-coebz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mesela, köklerde bir toz olsaydım,

Yer çekimi ile yönüm bulsaydım,

Sonsuz karanlıkta öyle kalsaydım,

Seninle birlikte dibe batsaydım.

*

Mesela, karanlık dibi görseydim,

Köklerin üstüne bir ağ örseydim,

Ağırlıkla baş aşağı sürseydim,

Toprağın bağrında sessiz yatsaydım.

*

Mesela, o güne dönüp baksaydım,

Bütün anıları bir bir yaksaydım,

Bir su damlasıyla dibe aksaydım,

Kendimi boşluğa öyle katsaydım.

*

Yerin merkezine usul inseydim,

Karanlık köklere gizli sinseydim,

Fırtına bitince öyle dinseydim,

Acıyı ruhumdan söküp atsaydım.

*

Mesela, kök gibi dibe varsaydım,

Umutları içimde bir sarsaydım,

Karanlık toprağı hemen yarsaydım,

İsyan edip de kaşımı çatsaydım.

*

Mesela, sırları sana sorsaydım,

Kaderimi senin için yorsaydım,

Yeni bir dünyayı senle kursaydım,

Aşkın acısını böyle tatsaydım.

*

Mesela, dağları senle aşsaydım,

Sevginin seliyle taşıp coşsaydım,

Sana kavuşmaya hemen koşsaydım,

Ağırlığım ile son kez batsaydım.', 'Mesela, köklerde bir toz olsaydım, Yer çekimi ile yönüm bulsaydım, Sonsuz karanlıkta öyle kalsaydım, Seninle birlikte dibe batsaydım. * Mese...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/mesela-215-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ovanın Sisinde Bir Uzun Hava', 'ovanin-sisinde-bir-uzun-hava-selam-aykut-lxe8w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağlara kar yağmış, ovaya sis düşmüş,
Evlerin bacasından dumanlar yükselmiş.
Sobanın üstünde kaynayan çaydanlık,
İçimize çocukluğumuzdan bir özlem düşürmüş.
Çayın fokurtusu karışmış sessizliğe,
Bir uzun hava düşmüş eski radyodan.
Sanki biri anlatıyor içimizde kalanları,
Yarım kalmış sevdaları, uzaklarda kalanları.
Pencerenin buğusunda donmuş hatıralar,
Her biri başka bir hikâye, başka bir yara.
Dışarıda kar, içeride sessizlik,
Bir de insanın kimseye anlatamadığı yalnızlığı var.
Dağlar susmuş, ova beyaza bürünmüş,
Zaman durmuş sanki bu sabah memlekette.
Bir bardak çay, bir soba sıcaklığı,
Bir uzun hava ve binlerce hatıra yürekte.
Ah benim güzel memleketim,
Senin kışın bile başka güzel.
İnsan bazen bir ömür arar huzuru,
Oysa bir soba başında saklıdır bütün özlemler...', 'Dağlara kar yağmış, ovaya sis düşmüş, Evlerin bacasından dumanlar yükselmiş. Sobanın üstünde kaynayan çaydanlık, İçimize çocukluğumuzdan bir...', ARRAY['Türk Edebiyatı','Şiir','Selam Aykut']::text[], 8.5, '{"poet":"Selam Aykut","poet_slug":"selam-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ovanin-sisinde-bir-uzun-hava-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuk', 'yolculuk-mahmut-kasapoglu-jplli', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir seher yollandım yad diyarlara,

Yüreğim sığmadı dar duvarlara,

Dönüp bakmadım hiç ağlayanlara,

Dağlara seslendim, yel: "Sağır" dedi.

Bir hana sığındım akşam inerken,

Bir derviş oturmuş, tespih çekerken,

Ben derdimi yutup susup giderken,

"Derdini saklama, sen bağır" dedi.

Issız ovalarda kaldım ben yalnız,

Gece indi, gökte yanar bir yıldız,

Bir çoban yaklaştı usulca, sessiz,

"Tek başına olmaz, dost çağır" dedi.

Atımın nalları aşındı taşta,

Ter döktü yokuşta, tipide, kışta,

Gençlikten yürüdük, geldik bu yaşta,

Seyis atı gördü: "Sırt yağır" dedi.

Köyleri aşarken şafak sökünce,

Ak saçlı bir ana beni görünce,

Bir tas su doldurdu ben yürüyünce,

Ardımdan serperken: "Su uğur" dedi.

Sıladan uzakta geçti yıllarım,

Ne bir haber geldi, ne gelir yârim,

Sararıp soldu da gülüm, baharım,

Gurbet ateş saldı: "Yan bağır" dedi.

Ömrün akşamında vardım son hana,

Hancı karşıladı, yer verdi bana,

Açtım heybemi de döktüm meydana,

Baktı da yüküme: "Çok ağır" dedi.', 'Bir seher yollandım yad diyarlara, Yüreğim sığmadı dar duvarlara, Dönüp bakmadım hiç ağlayanlara, Dağlara seslendim, yel: "Sağır" dedi. Bir ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kasapoğlu']::text[], 8.5, '{"poet":"Mahmut Kasapoğlu","poet_slug":"mahmut-kasapoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yolculuk-621-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasımpatı', 'kasimpati-esma-ozdemir-t5eyb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kasım''da çiçekler açmış 

Heryerde Kasım Çiçekleri var.

Kırlar, yollar, okullar

Hastahaneler...

Vitrinler renk renk çiçeklerle

Dolmuş taşmış...

Sisli bir İstanbul akşamında 

Yine aheste aheste 

Efkâr yüklü damlarında simsiyah

Mışıl mışıl otururken

Yan keyfime kedi gibi

Doldurmuşum rakıyı bir güzel 

Bulut rengi, bembeyaz 

Sana özenerek

Düşmana inat

Hayali bardağıma şimdi...

Bir cigara tüttürmüşüm sonra 

Anlıyor musun 

Kıvrım kıvrım saçlarımdan ta havaya

Yukarı doğru...

Martılar konmuş habire kiremit yüklü

Turuncu çatılara baksana!

Kanatlarında binbir telaşla kuşların

Sonbahar gelmiş ıssız dünyama

İyot kokusu, deniz kokusu

Aha tam şuramda! 

Karaköy Vapur İskelesi''nde bir akşamüstü 

Birbirini iterek inerken insanlar kıyıya

Siren sesi, insan sesi, kuş sesi

Nasıl da hepsi birbirine karışır değil mi?

Sucular, simitçiler, seyyar satıcılar

En çok da kediler ve balıkçılar

Her biri ayrı bir ekmek derdinde şimdi!

İşte şimdi

Kurulup eskitme ahşap masamın başına

Şair gibi...

Kurşun kalemimi alırken dosdoğru elime

Sana öykünerek güzelim

Senden ilham alarak

Seni bilgece düşünüp

Dilden, gönülden

Candan yürekten severek

Seni hatırlamak bu akşam 

Ne güzel bir hadisedir

Benim için bir bilsen!

Orhan Veli''yi düşünüyorum

Şairim...

Gözlerim kapalı...

Önce hafiften bir yağmur yağıyor 

Tozlu hatıraların üstüne

Şiirde, şarkıda, sokakta her an

Seni görüyorum...

İliklerime kadar şiirle dolmuşum

Anlıyor musun?

Bütün varlığımla içtenlikle

Seni düşünürken 

Seni anlamak

Seni anlatmak istiyorum gençlere!

Ama şimdi 

Biraz düşününce...

Hayır! Kabul etmiyorum!

Çünkü, bu memlekette 

Şairden sayılmak için kardeşim 

Sırtında beyaz kürklü aba

Cebi tomar tomar yabancı para

Yetmezmiş gibi bir de

Sıfır kilometre 

Altında sekiz silindir araba

Alman Malı o meşhur 

Mercedes mi olması lazım canım!

Oysa seni düşlemek bile şiir gibi

Senin sesinden İstanbul''u dinlemek

Yağmur yağarken

Usul usul saçaklardan

Ninni gibi

Sonra yavaşça mısralara inmek

Şiire, deftere, kaleme gelmek

Masanın üstünde duran

Sevgiyle, hasretle, özlemle

İlham perilerinden önce 

Seni çağırmak dizelere...

Sen ki mısralara sığmayan 

İmgelerden taşan adam!

Benim şiir diye yazdıklarım var ya

Unuttuğun dalgınlıkla 

Kalemini yontarken birgün 

Ahşap masanın üstünde 

Bıraktığın kırıntılar...

Övündüğüm herşey bugün

Senden artakalanlar...

Ve sen İstanbul''un göbeğinde

Galata Meyhaneleri''nin demirbaş şairi!

Düşünün karşınızda bir an

Dalyan direkleri gibi

Boğaziçi''nin Koskoca Orhan Velisi!

Ölüm günün de aslında 

Sen yokmusun ilahi

Doğumgünü kutlaması gibi mizahi!

Sanki oturmuş da sahilde

Bir bankta iki kişi

Çikolatalı bir dilim pastayla

Gözyaşları içinde 

Yaşgününü kutluyor; 

Dudak dudağa, çıra gibi 

Mum gibi...

Velhasıl şairim

Geçen bütün zamanlara inat sensiz

Hüznün içinde demlenen umut gibi

Sevda içinde filizlenen düş gibi

Şiir dilinde seni hayal edip

Seni anmak

Bir an için zamanı durdurup

Kasım Çiçekleriyle

Seni hatırlamak

Güzeldi be usta!

Hey gidi Şair Orhan Veli..!

Bir de sen bilmezsin onları

Bizim kadar 

İyi ki o kadar yaşamadan

Gittin aramızdan..!

Söylemezsem vallahi içimde kalır

Çiban çıkar bir tarafımdan mazallah!

Ağzında Küba Purosu''yla 

Öyle havalı havalı 

Şairlik taslamak kolay 

Size göre tabi!

Ajitasyon yapmak

Bir yandan da

Ne kârlı bir zanaat değil mi

Salya sümük ağlayarak!

Bir bilsen canım 

Ne ikiyüzlüdür o şeytanlar!

Sanatçı, diye okullarda bize meğerse

Hep zengin züppeleri belletmiş hocalar!

Baba kuvvetiyle

Mastırını koparan Avrupa''dan

Anlıyor musun 

Sanatçı kesilmiş başımıza!

Diyorum

Keşke herkes de

Hasan Ali''nin Oğlu kadar

Zenginliğini saklamadan

Dürüst olabilseydi bu memlekette!

Varsılı bu kadar ağlayınca tabi

İki gözü iki çeşme 

Bize de Kasım Gülleri''yle

Acı bir gülüş kalmış yüzümüzde

Atadan bin yıllık miras gibi adeta!

Yoksul şairlerin zengin dizelerinde...', 'Kasım''da çiçekler açmış  Heryerde Kasım Çiçekleri var. Kırlar, yollar, okullar Hastahaneler... Vitrinler renk renk çiçeklerle Dolmuş taşmış....', ARRAY['Türk Edebiyatı','Şiir','Esma Özdemir']::text[], 8.5, '{"poet":"Esma Özdemir","poet_slug":"esma-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":149,"source_url":"https://www.antoloji.com/kasimpati-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Etek Dolusu', 'etek-dolusu-ali-i-hsan-kaya-2-wibhm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '"Ağaç vakitle büyütür meyvesini, insan 

sabırla devşirir ömrünü."

Ulu ceviz ağacına

Patikadan adım adım yaklaşıyorum

Yolun hemen kıyısında.

Yoruluyor,

Mola veriyorum.

Yaprakları seyrek,

Taşın bağrını yararak

Uzanmış gökyüzüne.

Heybetinden gözümü alamıyor,

Doyasıya seyrediyorum.

Yağmur yağsa bir damla tutmaz yaprağı,

Gölgesi de makbul değildir

Bu ağacın

Altında.

Günden güne, sessizce

Doluyor içi cevizlerin,

Yeşil bir örtüye bürünüyor zaman.

Sonbahar yağmuru silkeliyor ağacı,

Dökülüyor cevizler yol boyunca yere.

Topluyorum;

Sağ cebime,

Kazağımın eteğine

Dolduruyorum. 

Koşuyorum eve;

Sol elimde ekmek, sağımda kına.

Parmaklarımda acı bir leke,

Güneş çıkıyor, seriyorum yere.

Bekle ki kurusun

Havadaki rutubetten.

Kurumadan kırıyorum.

Çetin ceviz ki!

Çıkar içini çıkarabilirsen!

Beyaz.

Taze.

Acı.

Ve ulu bir sabır kalıyor

elimde avcumda.', '"Ağaç vakitle büyütür meyvesini, insan  sabırla devşirir ömrünü." Ulu ceviz ağacına Patikadan adım adım yaklaşıyorum Yolun hemen kıyısında. ...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Kaya 2']::text[], 8.5, '{"poet":"Ali İhsan Kaya 2","poet_slug":"ali-i-hsan-kaya-2","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/etek-dolusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Virane', 'virane-ali-i-hsan-kaya-2-yukvk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '"İnsanın, asıl terk ettiği yerin yine kendi 

gövdesi olması ne garip."

— Bir Yalnızlık Notu

Yol veriyorum uzun sokakların,

Aşınmış, cilalı gibi parlayan kaldırım 

taşlarından...

Sessizliğe. 

Yadırgamıyorum bilmeyenleri,

Bilenler kadar;

Üstüne de bir çizgi çekmiyorum

Simsiyah karakalemle. 

Bazen kenarından, ucundan,

Saçından...

Bazen de kulaklarından

Siliyorum resmimin.

Geriye kalanı bana yetiyor. 

Bazen kravat takıyorum boynuma,

Bazen de kareli bir mendil

Ceketimin sol cebine;

Üstten buruşturup, katlayarak.

Yürüyorum,

Dar ama açılan

Başka bir yola. 

Sezinliyorum hayatın gelişini, gidişini.

Sokaktan yaylı, kanatlı, süratli araçlar 

geçiyor;

Ya o acımasız hıza yetişmek için,

Ya da kanatlı Chevrolet’den sevdiğime

El sallıyorum. 

Ruhum daralıyor, geri dönüyorum. 

Baba yadigârı evimiz;

Yangından çıkmış gibi, karanlık,

Tahta kaplı.

Issız; çıt çıkmıyor,

Tavanın çıkardığı o ahşap esneme hariç. 

İçeri giriyorum;

Zaten anahtar sedirin altında.

Kapı aralanıyor,

Zamanın küf kokusunu taşıyan nemli bir 

rüzgâr

Vuruyor yüzüme. 

Çok kravatlı insan yetiştirdi,

Yıllar eskitse de ruhu tazeydi.

Kaderine terk ettiğimiz viranenin,

Araladığım kapısının eşiğinde

Yol verdiğim aşınmış, cilalı taşların

Sessizliği vardı. 

Ben de alıp başımı gidiyorum,

Terk ettiğim kaldırımların üstüne...', '"İnsanın, asıl terk ettiği yerin yine kendi  gövdesi olması ne garip." — Bir Yalnızlık Notu Yol veriyorum uzun sokakların, Aşınmış, cilalı g...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Kaya 2']::text[], 8.5, '{"poet":"Ali İhsan Kaya 2","poet_slug":"ali-i-hsan-kaya-2","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/virane-88-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonra', 'senden-sonra-servet-balibey-orpm8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İÇMİŞİM ÇOK SARHOŞUM
KADEHİM YORGUN
TAKAT YOK YÜREĞİMDE
SEVMEDEN DURSUN
 
​SAKLAMADAN SÖYLÜYORUM GEL
SEVİYORUM ŞU AŞKINDAN
ÜZÜLMEZMİ ŞU HALİME
O TAŞ KALBİN

AĞARMA EY GÜNDÜZ
GECELER KALSIN
TERKETME KARANLIK
ÖMRÜMÜ ALSIN

​OLMAZ olsun SENSIZLIGIN SESI
OLMAZ OLSUN TÜM EZGILER
SENSIN
BİR NİHAYET BULSUN BENİ AAH
SENDEN SONRA
OLMAZ olsun SENSIZLIGIN SESI
OLMAZ OLSUN TÜM EZGILER
SENSIN
BİR NİHAYET BULSUN BENİ AAH
SENDEN SONRA', 'İÇMİŞİM ÇOK SARHOŞUM KADEHİM YORGUN TAKAT YOK YÜREĞİMDE SEVMEDEN DURSUN   ​SAKLAMADAN SÖYLÜYORUM GEL SEVİYORUM ŞU AŞKINDAN ÜZÜLMEZMİ ŞU HALİ...', ARRAY['Türk Edebiyatı','Şiir','Servet Balıbey']::text[], 8.5, '{"poet":"Servet Balıbey","poet_slug":"servet-balibey","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/senden-sonra-625-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorgulanacaksın', 'sorgulanacaksin-i-lyas-ates-ot44v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kaç kere kahrolduğumun hesabı yoktur

Kahrolursun sözlerle dile getiremezsin 

Kahrolduğunu sözler dile getiremediğinde

gözyaşların konuşacaktır 

Gözyaşların konuştuğunda neden ağlıyorsun

diye yine sorgulanacaksın

Ve şişe şişe sonunda seni çıldırtacaklardır

ve bu adam kafayı yedi delirdi deyip sizleri

terk edeceklerdir', 'Kaç kere kahrolduğumun hesabı yoktur Kahrolursun sözlerle dile getiremezsin  Kahrolduğunu sözler dile getiremediğinde gözyaşların konuşacakt...', ARRAY['Türk Edebiyatı','Şiir','İlyas Ateş']::text[], 8.5, '{"poet":"İlyas Ateş","poet_slug":"i-lyas-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sorgulanacaksin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perde', 'perde-omer-korkmaz-4-rv59v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Perde

Aralandı yine ıssız gecelerde

Karşıki sahili gösteren penceremde

Yeni bir sonata davet ediyor

İcabet edilmemesi mümkün olmayan perde

Kendi kendine macera arıyor herhâlde

Sessiz sedasız gecenin şu vaktinde

Şehir uyku sersemi, ben geceden kalma zaten

Bir rüyada gördüm tam kaldırdı en güzel yerinde

"Haydi araldın anlat," deyiverdim ben de

Belli bir derdi vardı rahatsız etmez şu vakitte

"Hatırlar mısın?" dedi birden, "yine içmiştik bir gece"

"Bir ses geldi sahilden sanki bir bilmece"

"E ne var yani?" dedim,

"İlk kez mi ses duyduk?"

"İlk değil ama," dedi

"En güzeliydi"

Kendi söyleyince ben de

Hayal meyal kanıksadım

Güldüm kahkaha attım birden

"Haklısın, en güzeli"

Ses öyle gelmişti ki

Kış gecesi ateş sesi

Yaz vakti soğuk su

Sonbaharda yaprak sesi

Ses öyle gelmişti ki

Psikoloji bozar cinsten

Hem derinden bir sızı gibi

Hem de kurtarır tüm dertten

"Anladım," dedim, "mesele derin,"

"Rüzgârı bile susturmuş o gece sahilin."

Perde hafifçe sallandı, iç çekti usulca:

"Sorma, o günden beri aklım hep onda..."

Sabaha karşı hafifledi gecenin ayazı,

Kapanırken usulca pencerenin beyazı,

"Yarın gece yine gel," dedi fısıltıyla perde,

"Yarım kalan bu masalı tamamlayalım yerinde."', 'Perde Aralandı yine ıssız gecelerde Karşıki sahili gösteren penceremde Yeni bir sonata davet ediyor İcabet edilmemesi mümkün olmayan perde K...', ARRAY['Türk Edebiyatı','Şiir','Ömer Korkmaz 4']::text[], 8.5, '{"poet":"Ömer Korkmaz 4","poet_slug":"omer-korkmaz-4","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/perde-202-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin Özlemin Saklı Acemim Yeşilova Acem Türkmenleri', 'hasretin-ozlemin-sakli-acemim-yesilova-acem-turkmenleri-yavuz-bayram-caliskan-xgflv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeşilova Acem yurdu yelimde

Ağız sözcükleri uçar dilimde

Nakış nakış izler dokur kilimde

Hasretin, özlemin saklı Acemim 

Anılar doluydu saklı yürekte

Ay gördüm oynardık ışık direkte

Yokluğun acısı, yakar felekte 

Hasretin, özlemin saklı Acemim 

Gurbette, sılanın, özlemi yakar

Acem höyüktende abamız bakar

İsmail emmimde samanı yık''ar 

Hasretin özlemin saklı Acemim 

Sevgim, sevdam, kalbim, senle atıyor

Ebemde böreğe yağı katıyor 

Hacı Abdurrahman alıp yutuyor

Hasretin özlemin saklı Acemim 

Hışırın dibinde sokulup yatan

Ali emmi sohbete değeri katan

Şehidi, gaziyi, unutmaz atan

Hasretin özlemin saklı Acemim 

Yokluğa inadım, başlar azıkla 

İtimiz bağlıdır, demir kazıkla 

Hüseyin dayımda üşür yazık''lâ

Hasretin özlemin saklı Acemim 

Açık pazara da ahraz giderdi

Keçiyi, koyunu, ferik güderdi 

Kınalı keklikler, çölde öterdi

Hasretin özlemin saklı Acemim 

Gamga battı, gazel, otun içinde

Türkmenler geliyor Hoy''un göçünde

Muallim okutur mektep izi''nde

Hasretin özlemin saklı Acemim 

Damlayıp dökülür pınardan sular

Atıma binince, elimde yular

Agamda, soğukta atkıyı dolar

Hasretin özlemin saklı Acemim 

Guşane tandırda içi süt dolu

Çerçi Çapan Zeybek alınca yolu

Yun, Un''nan, buduy''nan, çerçilik dili

Hasretin özlemin saklı Acemim 

Pehlivan Babır''ın Rasim yaşayan

Köyünde ebesi Kozalak, dayan

Erlikten sonrada gel sende uyan

Hasretin özlemin saklı Acemim 

Dağılır sehere çölün dumanı

Hiç bitmez Alinin otu, samanı

Unutulmaz günler, mutlu her anı

Hasretin özlemin saklı Acemim 

Filkeyi açıpta balon doldurdum

Metel anlatıpta uşak güldürdüm 

Bakkal Sıktıya da borcu sildirdim

Hasretin özlemin saklı Acemim 

Abulardan Nuri, kızı Arife 

Komşumuzda vermiş kızı herife 

Ehli sünnet biri saygın Zarife

Hasretin özlemin saklı Acemim 

Sabit kadem Acem can Yeşilova 

Vel cemaat insan kan Yeşilova 

Uçsuz ve bucaksız verimli ova

Hasretin özlemin saklı Acemim 

Ekeciğe Acem dağı derlerdi 

Yeşil başakları ütüp yerlerdi 

Azzığa da  dürüm, pindir korlardı 

Hasretin özlemin saklı Acemim 

Acele et ırgat, işlerin zordur 

Velveleye verme, taşlarım kordur 

Büvelek dutunca danayı durdur

Hasretin özlemin saklı Acemim 

Şamarı yimişte camdan bakıyor 

Gremsiyeyide emmin takıyor 

Abdullah bölemde kurban yık''ıyor 

Hasretin özlemin saklı Acemim 

Gazyağcı''dır Çapan Dinç''de köyümde 

Bekçibaşı Rasim koyun sayımda 

Sürünün büyüğü benim dayımda 

Hasretin özlemin saklı Acemim 

Tollarda kazanı cingan kalaylar

Ulukışla''da esker, ordu, alaylar 

Mutluca, huzurlu geçerdi aylar 

Hasretin özlemin saklı Acemim 

Türküler, bozlaklar, ciğer ağrıtır

Yabayla badası atıp sırıtır 

Pala bıyıklarına bakıp kırıtır 

Hasretin özlemin saklı Acemim 

Babamda eskerde sol yanım soldu 

Kamyonun kasası insanla doldu 

Beyaz cübbe giymiş imam gül''dü 

Hasretin özlemin saklı Acemim 

Sürmeli kızların gözü karadır 

Yokluğun yılları kalpte yaradır 

İmece işleri köyden yanadır 

Hasretin özlemin saklı Acemim 

Ömürler serdim ben, Acem yoluna

Anama sevgim çok, dola koluna 

Arayın insanım Türkmen buluna

Hasretin özlemin saklı Acemim 

Şimşir tarak saçın telini tarar 

Bibim buzağını höyük''te arar 

Göçmen kuşlar gelir gölü sarar

Hasretin özlemin saklı Acemim 

Ardıkürekliler bağı belliyor

Ebemde bahçede sitil küllüyor 

Bu sene elmalar sıkı döllüyor 

Hasretin özlemin saklı Acemim 

Tepeye tepeye Deli Bekir

Köyün sevdiği kedi de Tekir

Abamın gözleri sürmeli çakır

Hasretin özlemin saklı Acemim 

Cerekte örümcek yuva yapıyor 

Anofel kanı da emip kaçıyor 

Karsamba dolu ev insan geçiyor

Hasretin özlemin saklı Acemim 

Lavgar Halil susmaz her an konuşur

Müzevir durmadan deşip gülüşür 

Ayna bakar olçum, fakir bölüşür

Hasretin özlemin saklı Acemim 

Yazaar davarda yazı''da kaldı

Vesayit verepte vagona daldı

Yanaz Ayşe yilfe uçarı duldu

Hasretin özlemin saklı Acemim 

Gumpiri tandırda küle devirdim

Keşşikle çıkrıkta yünü eğirdim 

Karık, mırık, bahça, eve seğirdim

Hasretin özlemin saklı Acemim 

Biçala gelsende görsem yüzünü 

Rastıklı, sürmeli, ela gözünü 

Bohçanda sarıldı anlat özünü

Hasretin özlemin saklı Acemim 

Alle''de temizlik paklık ondadır

Dürrüt, düğün, nişan, bohça yandadır

Baba Elif yetim öksüz candadır

Hasretin özlemin saklı Acemim 

Istar da kadının Eriş elinde

Hana, Ok''lar ,Pavaz, Kirkit dilinde

İp''le, Tokmak,Tarak halı yolunda 

Hasretin özlemin saklı Acemim 

Sinan Uğurlu''da "Turnam" sözleri 

Acem tulumbada yıkar yüzleri

Vecip emminin hatır izleri 

Hasretin özlemin saklı Acemim 

Mahtumkulu Türkmen Firaki şair

Koyuna kurtlarda olaya dair

Türkmenim Türkmenim velhasıl sair

Hasretin özlemin saklı Acemim 

Şiirhan hevesim geçmez burada

İbrahim Karacan, Umran Uslu''da,

Ali Bal sazıyla, sesler orada

Hasretin özlemin saklı Acemim.', 'Yeşilova Acem yurdu yelimde Ağız sözcükleri uçar dilimde Nakış nakış izler dokur kilimde Hasretin, özlemin saklı Acemim  Anılar doluydu sakl...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":148,"source_url":"https://www.antoloji.com/hasretin-ozlemin-sakli-acemim-yesilova-acem-turkmenleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alemin Özüsün Sen', 'alemin-ozusun-sen-tekin-karacoban-9m36z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey gönül niye gamsın?

Tılsımlı hazinesin

Yüce bir varlıksın sen

Güçlü bir canlısın sen

Hoşça bak sen özüne

Âlemin özüsün sen

Kâinatın gözüsün

İnsansın sen canım sen

Aşkın gizli yurdusun

Hidayetin nurusun

Hikmetin mülkü sende

Masiva köle sende

Hoşça bak sen özüne

Âlemin özüsün sen

Kâinatın gözüsün

İnsansın sen canım sen', 'Ey gönül niye gamsın? Tılsımlı hazinesin Yüce bir varlıksın sen Güçlü bir canlısın sen Hoşça bak sen özüne Âlemin özüsün sen Kâinatın gözüsü...', ARRAY['Türk Edebiyatı','Şiir','Tekin Karaçoban']::text[], 8.5, '{"poet":"Tekin Karaçoban","poet_slug":"tekin-karacoban","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/alemin-ozusun-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karalar Bağladı Hüznüm', 'karalar-bagladi-huznum-kenan-gezici-39we3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçime ay düşmesin, 

Haberin olur sevgili şavkından.

Neşeyle karıştırırsın, 

Bilmezsin öldürür beni bu liman 

Hüznüme kara çalarsın.

Anlamadın hiçbir vakit beni.

Işıl ışıl görsen gözlerimi.

Bırakıverirsin, zaten bıraktığın gibi.

Kışa denk gelen ağaç gibisin.

Ne de olsa bir yaprağım senin için.

Yokluğun hep bir yaradır gönlümde.

Dilencisi oldum sevginin, 

Hele bak ki nerede,

Tıkadı sol yanımı büyütemedim.

Lime lime param parça da olsam.

Dönüp bakmadın burnunun ucuyla bile.

Ne su bildin beni ne toprak.

Gelirde bir gün olursun belki bana muhtaç.

Gelmedim, aklına ne bugün nede dün.

Kurudun, soldun olduğun saksıda.

Vermedi sana ne su ne de bir dirhem toprak.

Kenan GEZİCİ   16/11/2026', 'İçime ay düşmesin,  Haberin olur sevgili şavkından. Neşeyle karıştırırsın,  Bilmezsin öldürür beni bu liman  Hüznüme kara çalarsın. Anlamadı...', ARRAY['Türk Edebiyatı','Şiir','Kenan Gezici']::text[], 8.5, '{"poet":"Kenan Gezici","poet_slug":"kenan-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/karalar-bagladi-huznum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamam', 'unutamam-sairul-i-slam-yunus-kokan-2lxvd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yandım, yandım, kül oldum aşkından,

Yaş süzüldü gözümün ucundan.

Sen mutlu ol diye sustum, söylemedim derdimi,

Ama nasıl unutayım sana verdiğim kalbimi?

Şimdi her şarkı bana seni hatırlatır,

Her cümle bir hatıra, her kelime bir anı,

Unutamam seninle yaşanan hiçbiri an''ı,

Unutamam seninle yaşanan hiçbiri an''ı.

Ne sen geri dönersin ne ben olabilirim eskisi gibi,

Kaybettik ikimiz de o güzel günleri.

Ben hâlâ aynı yerde, aynı sokaktayım,

Senin geçtiğin yollarda kendimi aramaktayım.

Şimdi her şarkı bana seni hatırlatır,

Her cümle bir hatıra, her kelime bir anı,

Unutamam seninle yaşanan hiçbiri an''ı,

Unutamam seninle yaşanan hiçbiri an''ı.', 'Yandım, yandım, kül oldum aşkından, Yaş süzüldü gözümün ucundan. Sen mutlu ol diye sustum, söylemedim derdimi, Ama nasıl unutayım sana verdi...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/unutamam-206-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki', 'belki-sairul-i-slam-yunus-kokan-jwx4u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir fotoğrafın kaldı, duvarda asılı

Ben hâlâ aynı yerde, gönlüm yaralı

Sen gittin gideli gülmedi yüzüm

Her gece yüreğimi kaplar bir hüzün.

Bir gün olur da yolun düşerse,

Sorarsan beni anılar sokağından,

Kaybettiğin değeri anlarsın belki,

Gözlerin dolar ağlarsın belki.

Hüzün denizinde adını andım,

Hasretli gecelerde kendimle kaldım,

Ben seni canımdan çok sevmişim meğer,

Sen çekip gittin de ben sende kaldım.

Bir gün olur da yolun düşerse,

Sorarsan beni anılar sokağından,

Kaybettiğin değeri anlarsın belki,

Gözlerin dolar ağlarsın belki.', 'Bir fotoğrafın kaldı, duvarda asılı Ben hâlâ aynı yerde, gönlüm yaralı Sen gittin gideli gülmedi yüzüm Her gece yüreğimi kaplar bir hüzün. B...', ARRAY['Türk Edebiyatı','Şiir','Şairül İslam Yunus Kokan']::text[], 8.5, '{"poet":"Şairül İslam Yunus Kokan","poet_slug":"sairul-i-slam-yunus-kokan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/belki-884-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Şiir', 'guzel-siir-kemal-doganay-ffo4f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güzel şiirler

Sana yakışır.

Ben de;

Sana yakışıyor diye,

Bu güzel şiiri yazdım.

Şiir güzel

Sen de güzelsin.

Benim için bir tanem,

Sen çok özelsin.', 'Güzel şiirler Sana yakışır. Ben de; Sana yakışıyor diye, Bu güzel şiiri yazdım. Şiir güzel Sen de güzelsin. Benim için bir tanem, Sen çok öz...', ARRAY['Türk Edebiyatı','Şiir','Kemal Doğanay']::text[], 8.5, '{"poet":"Kemal Doğanay","poet_slug":"kemal-doganay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/siir-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnşallah Geçer', 'i-nsallah-gecer-ezgi-yapar-czz8s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünya ne kadar büyük bir yer değil mi?

Ama sığamıyor insan.

Şu kocaman dünya da sığabilecek bir yer bulamıyor kendine.

Sığınacak bir limanı olmalı derken rastladım sana.

Yüreğin en güzel sığınağım olsun istedim.

Sevmek istedim,

Sen de sev istedim.

Çok mu şey istedim.

Ömür ne kadar uzun olabilirdi ki,

Birlikte yaşlanalım istedim.

Birlikte gülelim birlikte ağlayalım istedim.

Hayat akıp gitsin,

Dünya telaşından uzak huzurla yaşlanalım istedim.

Birbirimize yoldaş olalım istedim.

Yorulunca omuz olalım istedim.

Birbirimizi her gün yeniden keşfedelim istedim.

Yol seninle bitsin istedim.

Sen de öyle istiyorsun sanmıştım.

Meğer, Avuç içi kadar bile yokmuş yerim.

Olsun…

Öyle olsun…

Dünyaya sığamazken, yüreğine sığacak değildim ya.

Gelen girdi kapından da, bir beni alamadın içeri.

Herkesi misafir ettin de bir bendim ayakta kalan.

Bir gün dağılacak o kalabalık,

Herkes kendi yoluna gidip, tek başına kaldığında aklına geleceğim.

O kalabalığın hengamesine aldanıp yok saydığın beni,

Sana yer yok dercesine bakan o buz gibi gözlerini,

Söz konusu ben olunca, kilitler vurduğun o kalbini,

Sığdıramadığın o dünyanı sana bırakıp,

Yalnızlığımı da alıp gidiyorum.

Aramızda öyle görünmez bir duvar var ki artık,

Aşmaya gücüm yetmez benim.

Ama içimden almaya da yetmez gücü kimsenin…

Kavuşması imkansız, yaşanması imkansız…

Bu sana son seslenişim olsun.

Bundan böyle bir şarkının nakaratında buluşacağız sadece

Ben susacağım şarkılar konuşacak nasıl olamadığımızı.

Ya da bir şiirin dizelerinde,

Yaşanamamış bir aşkın hikayesi olarak geçecek adımız.

Bu da sana vedam olsun….

Bu aşka mutluluk değil, hüzün yakıştırdın ya…

Alacağın olsun…

Sana dair ne varsa, gömüyorum karanlığa, geçmişe….

Bu adresi, bu sokağı, 

Sana çıkan yolları,

Hiç yürümemiş gibi yapacağım…

Sezen’in de dediği gibi kolay olmayacak, üzüleceğim….

Ama bir iz bıraksa da geçecek…

Geçmek zorunda…

Geçmeli…

İnşallah geçer…', 'Dünya ne kadar büyük bir yer değil mi? Ama sığamıyor insan. Şu kocaman dünya da sığabilecek bir yer bulamıyor kendine. Sığınacak bir limanı ...', ARRAY['Türk Edebiyatı','Şiir','Ezgi Yapar']::text[], 8.5, '{"poet":"Ezgi Yapar","poet_slug":"ezgi-yapar","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/insallah-gecer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
