INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksik sayfa', 'eksik-sayfa-franz-charles-hemingway-f2fh3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hafıza siler, zaman kanatır yarayı,

Yıldızlara küskün, kapalı pencereler.

İnsan kalabalığı boğar ruhu sarayı,

Ölümcül bir tutkuyla yanar gölgeler.

Yük ağır, yol dikenli, tahammül az,

Bul sevdiğini, bırak sessizce tükettsin;

Dünya aynı dünya, değişen bu yaz,

İstediğin son nefes, varsın bu etsin.', 'Hafıza siler, zaman kanatır yarayı, Yıldızlara küskün, kapalı pencereler. İnsan kalabalığı boğar ruhu sarayı, Ölümcül bir tutkuyla yanar göl...', ARRAY['Türk Edebiyatı','Şiir','Franz Charles Hemingway']::text[], 8.5, '{"poet":"Franz Charles Hemingway","poet_slug":"franz-charles-hemingway","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/eksik-sayfa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***zorlanır***1', 'zorlanir-1-abdulhamit-gezer-xie56', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önce nazik insan olmak gerek 

Edebi yaşamak yaşatmak gerek

Hemşire Doktor ne fark edecek

İşini iyi yapan her işte sevilecek

Kariyer merdivenini rahat çıkacak

Sizin gibi feminist zihniyetler zorlanır', 'Önce nazik insan olmak gerek  Edebi yaşamak yaşatmak gerek Hemşire Doktor ne fark edecek İşini iyi yapan her işte sevilecek Kariyer merdiven...', ARRAY['Türk Edebiyatı','Şiir','Abdülhamit Gezer']::text[], 8.5, '{"poet":"Abdülhamit Gezer","poet_slug":"abdulhamit-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/zorlanir-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Chp''de', 'chp-de-ozgur-can-kaygisiz-u5d2d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mustafa Kemal''in askerleri CHP''de

Üreten Türkiye neferleri CHP''de

Cumhuriyet de yıkılmaz CHP de

Kurucu parti soranlara CHP de

İnönü''ye minnet, saygı CHP''de

Yavru vatana bitmez sevgi CHP''de

Karaoğlan da zerre korkmaz CHP de

Cesaret nedir soranlara CHP de

Kadın erkek eşitliği CHP''de

Halkların kardeşliği CHP''de

Terazi yanlış tartmaz CHP''de

Bağımsız yargı soranlara CHP de

Millî dış politika CHP''de

Kuvvacı ruh desen CHP''de

Kadın evde oturmaz CHP''de

Hakça düzeni soranlara CHP de

Hak, hukuk ve adalet aşkı CHP''de

Kadına seçme seçilme hakkı CHP''de

Kılıçdaroğlu da utandırmaz CHP de

Temiz siyaset soranlara CHP de

Atatürkçü düşünce CHP''de

Çağdaşlaşma arzusu CHP''de

Oy vermezsen neylesin CHP de

Önüne sandık geldiğinde CHP de

Bütün ümit gençliktedir CHP''de

Ulu çınar dalıyla gürler CHP''de

"Yükselmek ülküm!" de, CHP de

"Ne mutlu ki Türküm!" de, CHP de', 'Mustafa Kemal''in askerleri CHP''de Üreten Türkiye neferleri CHP''de Cumhuriyet de yıkılmaz CHP de Kurucu parti soranlara CHP de İnönü''ye minne...', ARRAY['Türk Edebiyatı','Şiir','Özgür Can Kaygısız']::text[], 8.5, '{"poet":"Özgür Can Kaygısız","poet_slug":"ozgur-can-kaygisiz","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/chp-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız''ımsın Naz''ımsın', 'yildiz-imsin-naz-imsin-ozgur-can-kaygisiz-upsu5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen benim Yıldız''ımsın Naz''ımsın

Hem mutlu hem dertli sazımsın

Gurbette inceden bir sızımsın

Canımdan çok sevdiğim kızımsın

Kah kışım, çoğu zaman yazımsın

Dalgalı saçlı alın yazımsın

Kurban olsun baban kızım sana

Sen kutup Yıldız''ımsın Naz''ımsın

ÖZGÜR CAN KAYGISIZ', 'Sen benim Yıldız''ımsın Naz''ımsın Hem mutlu hem dertli sazımsın Gurbette inceden bir sızımsın Canımdan çok sevdiğim kızımsın Kah kışım, çoğu ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Can Kaygısız']::text[], 8.5, '{"poet":"Özgür Can Kaygısız","poet_slug":"ozgur-can-kaygisiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yildiz-imsin-naz-imsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahte', 'sahte-aydin-cetinkaya-nsd33', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SAHTE

Gölgeye sığmayan sahte halin gölgesi,

Mezar taşında şaşan hüzne mabet gibidir.

Mezardan bile öte sahte halin bilgesi,

Nicesine erken zamana her an rahmet gibidir', 'SAHTE Gölgeye sığmayan sahte halin gölgesi, Mezar taşında şaşan hüzne mabet gibidir. Mezardan bile öte sahte halin bilgesi, Nicesine erken z...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çetinkaya']::text[], 8.5, '{"poet":"Aydın Çetinkaya","poet_slug":"aydin-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sahte-104-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazıklar Olsun', 'yaziklar-olsun-hasan-arpaci-1s6ux', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şairler toplumun derdinden uzak,

Yaşarsa onlara yazıklar olsun.

Sahtekar mazluma kurarken tuzak,

Uyursa ona da yazıklar olsun.

Yazarlar kalemi satar mı bilmem,

Helali harama katar mı bilmem,

Haksızı kayırır tutar mı bilmem,

Tutarsa onlara yazıklar olsun.

Çizerin kalemi kırılsa bile,

Noktası şahlanıp gelmeli dile,

Bir selam vermeli ayla hilale,

Korkarsa ona da yazıklar olsun.

Gazeteci hele nerde durmalı,

Toplumun adına hesap sormalı,

Turnayı gözünden atıp vurmalı,

Susarsa ona da yazıklar olsun.

Hukukçu uyurken finansçı kaçar,

Avukata yeni yolları açar,

Memleket açlığa olunca duçar,

Bakarsa ona da yazıklar olsun.

Filozof bulursan bana haber ver,

Krala her şeyi açıktan söyler,

İbreti alemi Hasan da dinler,

Kaçarsa ona da yazıklar olsun.

Hasan Arpacı, 2026, Üsküdar', 'Şairler toplumun derdinden uzak, Yaşarsa onlara yazıklar olsun. Sahtekar mazluma kurarken tuzak, Uyursa ona da yazıklar olsun. Yazarlar kale...', ARRAY['Türk Edebiyatı','Şiir','Hasan Arpaci']::text[], 8.5, '{"poet":"Hasan Arpaci","poet_slug":"hasan-arpaci","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yaziklar-olsun-323-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gününü Gün Etmeye Bak', 'gununu-gun-etmeye-bak-dursun-alabiyik-2-rln7p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'GÜNÜNÜ GÜN ETMEYE BAK

Neşeli ol mutlu yaşa

Gününü gün etmeye bak

Giyin kuşan paşa-paşa

Gününü gün etmeye bak

Biliyorsun dünya fani

Alıp gider seni beni

Malını yemeyen deli

Gününü gün etmeye bak

Yemezsen yiyen bulunur

Senin çektiklerin kalır

Can bedende çok bunalır

Gününü gün etmeye bak

Çok kazanmışsın var paran

Gezmeye değer koca han

Tabiata neler var can

Gününü gün etmeye bak

ÂŞIK SEFİLİM gezerim

Hem gezer şiir yazarım

Yaşamayana kızarım

Gününü gün etmeye bak

16.11.2026

ÂŞIK SEFİL DURSUN ALABIYIK', 'GÜNÜNÜ GÜN ETMEYE BAK Neşeli ol mutlu yaşa Gününü gün etmeye bak Giyin kuşan paşa-paşa Gününü gün etmeye bak Biliyorsun dünya fani Alıp gide...', ARRAY['Türk Edebiyatı','Şiir','Dursun Alabıyık 2']::text[], 8.5, '{"poet":"Dursun Alabıyık 2","poet_slug":"dursun-alabiyik-2","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gununu-gun-etmeye-bak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O isterse', 'o-isterse-ayhan-maloglu-2-9umpv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O isterse..

Değiştirir..

Güneş..

Batıdan doğar..

Doğuda batar..

O isterse değişir..

İlkbaharda kış olur..

Kışta ilkbahar..

O istedi..

Karışmadı..

Denizlerde..

Tatlı su ile..

Tuzlu sular..

O isterse..

Çekip alırda..

Denizleri..

Her yer çöl olur..

Yağmaz yağmurlar..

O isterse..

Bir gün değil..

Bin yıl yaşar..

Bütün kelebekler..

O isterse..

Gün doğmaz..

Bitmez geceler..

O isterse..

Bir tek ağaçtan..

Tüm insanlık doyar..

Kimse aç kalmaz..

Ama o her şeyi..

Fazlasıyla yaratmış..

Seni var edip..

Akıl ile donatmış..

Bölüşmeyi adaleti..

Seni özgür kılıp..

İradene bırakmış..

Suçlu arama..

O..

Bu dünyada..

Sana karışmaz..

Ayhan M.', 'O isterse.. Değiştirir.. Güneş.. Batıdan doğar.. Doğuda batar.. O isterse değişir.. İlkbaharda kış olur.. Kışta ilkbahar.. O istedi.. Karışm...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Maloglu 2']::text[], 8.5, '{"poet":"Ayhan Maloglu 2","poet_slug":"ayhan-maloglu-2","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/o-isterse-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezan vakitlerini değiştirenleri vurun', 'ezan-vakitlerini-degistirenleri-vurun-sedat-hunker-yil0m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Normal değişim haricinde Ezan namaz vakitlerini değiştirenleri vurun', 'Normal değişim haricinde Ezan namaz vakitlerini değiştirenleri vurun...', ARRAY['Türk Edebiyatı','Şiir','Sedat Hünker']::text[], 8.5, '{"poet":"Sedat Hünker","poet_slug":"sedat-hunker","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/ezan-vakitlerini-degistirenleri-vurun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rabbim Huzuruna Geldim!', 'rabbim-huzuruna-geldim-nihat-malkoc-olq8i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Affa mazhar olmak için 

Rabbim huzuruna geldim!

Günahtan kurtulmak için

Rabbim huzuruna geldim!

Terk eyledim masivayı

Bıraktım heves, hevayı

Sahiplendim hak davayı

Rabbim huzuruna geldim!

Ellerimi açtım sana

Gözyaşımı saçtım sana

Kör şeytandan kaçtım sana

Rabbim huzuruna geldim!

Baltayı vurmuşum taşa

Bahardan dönmüşüm kışa

Kalmak isteyip baş başa

Rabbim huzuruna geldim!

Sana açtım ellerimi

Sen hak söylet dillerimi

İyi eyle hâllerimi

Rabbim huzuruna geldim!

Dünya yükü ağır geldi

Hasretin sinemi deldi

Gönlüm seni hep dost bildi

Rabbim huzuruna geldim!

Sevabımla, günahımla

Hem gecem hem sabahımla

Biriken onca âh''ımla

Rabbim huzuruna geldim!

Çevirme beni kapından!

Kovma ilâhî yapından

Bol ihsan et sevabından!

Rabbim huzuruna geldim!

Affına olmuşum talip

Sen iki cihanda galip 

Nefsimi yanıma alıp

Rabbim huzuruna geldim!

Sensin benim sığınağım

Yoktur başka arka dağım

Boşa geçti gençlik çağım

Rabbim huzuruna geldim!

İntizarda garip kulum

Beyhudedir param, pulum

Sensin gidilecek yolum

Rabbim huzuruna geldim!

Ne mal gerek ne saltanat

Tek zenginliktir kanaat

Bozuldu ağzımdaki tat

Rabbim huzuruna geldim!

Kulluk başımdaki tacım

Maneviyatına açım

Sensin yegâne ilâcım

Rabbim huzuruna geldim!

Hayatımı başa sardım

Günahı, sevabı kardım

Önünde secdeye vardım

Rabbim huzuruna geldim!

Önce afiyet ve sıhhat

Bahşeyle huzur ve rahat

Kötü olan ne varsa at!

Rabbim huzuruna geldim!

Bu dünya barut, ben çıra!

Günahkârım, yüzüm kara

İyileştir, kalbim yara

Rabbim huzuruna geldim!

Nedamet yaşı dökerim

Boynumu sana bükerim

Sensin Rahman, sensin Kerim

Rabbim huzuruna geldim!

Bilirim fânidir dünya

Bir gün bitecek bu rüya

Bizlere ver edep, haya

Rabbim huzuruna geldim!

Kur''an''ını ferman bildim

Dertlerime derman bildim

Rahmetini umman bildim

Rabbim huzuruna geldim!

16 Kasım 2026/Trabzon', 'Affa mazhar olmak için  Rabbim huzuruna geldim! Günahtan kurtulmak için Rabbim huzuruna geldim! Terk eyledim masivayı Bıraktım heves, hevayı...', ARRAY['Türk Edebiyatı','Şiir','Nihat Malkoç']::text[], 8.5, '{"poet":"Nihat Malkoç","poet_slug":"nihat-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/rabbim-huzuruna-geldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürümeyi Unutan Canlar', 'yurumeyi-unutan-canlar-sukrullah-yavuzer-duyus', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mahallemizin sokaklarını geride bırakıp Cuma namazı için adımlarımı o mütevazı camiye doğru çevirdiğimde, havanın serinliğine karışan hayatın o ham ve telaşlı kokusunu içime çektim. Cami yolunun solunda kurulan semt pazarı, o an bütün canlılığıyla önümde uzuyordu. Çeşit çeşit tezgâhların ardında ekmek kavgasının o soluk soluğa koşturmacası vardı. Kimi esnaf elinde tuttuğu bir demet yeşilliği veya meyveyi havaya kaldırarak müşterinin dikkatini çekmek için doğaçlama maniler düzüyor, kimi tezgâhının başında sesini duyurabilmek için bağırıyordu. Cıvıl cıvıl, insan kokan, sesin ve rengin birbirine karıştığı bir pazar yeriydi burası.Ancak bu neşeli curcunanın ve pazarın gürültülü akışının ortasında, yol kenarında sessizce duran bir kamyonet çarptı gözüme. Arkası kasalı, üstü kapalı o kamyonet, sanki bu hayatın dışına itilmiş, acının ve sükûnetin mekânı gibi duruyordu.Kamyonetin kasasına yaklaştığımda manzara bir anda renk değiştirdi. Kasa, tel örgülerle bölünmüş daracık, basık kafeslerle doluydu. Her bir kafesin içine tıkıştırılmış zavallı tavuklar, adeta birer mahkûm gibi boyunlarını bükmüşlerdi. Fakat asıl yürek sızlatan, bu hayvanların görüntüsüydü. Gün ışığına hasret kalmış o bedenlerde tüy adeta kalmamıştı; yumurtlamaktan, sıkışıklıktan ve bitimsiz bir sömürü düzeninden derileri yolunmuştu. Kırmızı, çıplak etleri yer yer açıkta duruyor, tüysüz derileri soğukta ve tozda kalmaktan morarmış gibi görüyordu. Ayakta duracak mecalleri, kanatlarını bir kez olsun şöylece gerecek halleri yoktu. Belli ki ömürlerinin son demindeydiler; artık yumurtadan kesilmiş, verimden düşmüşlerdi. Pazarın bu kalabalığında, bir sofraya çorba veya akşam yemeği olmak üzere getirilmiş canlı birer mezar taşından farksızdılar.Tam o sırada, kalabalığın içinden bir müşteri kamyona yanaştı. Satıcıyla kısa bir pazarlık yapıldı; müşteri parmağıyla kafesteki bitkin bir tavuğu işaret etti. Satıcı, paslı tel kapıyı açtı, o zavallı hayvanı hoyratça yakalayıp kafesten dışarı çekti ve hiçbir önlem almadan, öylece toprağın üzerine bıraktı.Müşteri endişeyle bir adım geri çekilip, "Aman ne yapıyorsun, tavuk kaçar!" diye telaşlandı.Satıcı ise hiçbir şey olmamış gibi, gaddarca bir rahatlıkla elini salladı: "Korkma abê, bunlar yürümeyi unutmuş...Hiçbir yere kaçamazlar." O an, satıcının bıkkın sesinden dökülen bu basit cümle, modern dünyanın ve endüstriyel hırsın bu masum canlara yaptığı zulmün en acı, en çarpık itirafıydı. Adına "yumurta üreticiliği" dedikleri o devasa sömürü çarkı; gün ışığını görmeyen, toprakla buluşmayan, yüzlerce tavuğu daracık tel kafeslere hapsedip önlerine atılan bir avuç yem ve sudan ibaret bir ömre mahkûm etmişti. Hayvanlar, yürümeyi bile unutacak kadar hapsedildikleri o karanlık kutularda, sadece birer yumurta makinesi olarak tüketilmişti.Gözüm, toprağın üzerine bırakılan o zavallı tavuğa takıldı. Gerçekten de yürüyemiyordu. Ayakları taşıyamıyor, gövdesi toprağa doğru yığılıyordu; kafasını bile kaldıracak gücü yoktu. Gökyüzünün o sonsuz maviliğinden, toprağın o taze kokusundan ve özgürlüğün doğallığından; sadece üç beş tane fazla yumurta uğruna koparılıp alınmış bu masum can, içimde tarifi imkansız bir sızı bıraktı.

 Pazarın cıvıltısı, esnafın manileri, insanların ekmek kavgası bir anda kulaklarımdan silindi. O tavuğun yanından geçerken insanlığımdan utandım.  Gözüm yeniden tavuğa odaklandı. Tavuk sarsak hareketlerle yürümeye çalışıyordu. Sanki bacakları bir beden hareketi değil de, paslanmış bir mekanizmanın son çırpınışları gibiydi. Adım atmayı unutmuştu. Zamanı ve mekânı olmayan, sadece durmak için tasarlanmış daracık bir kafeste ömrünü tükettiği her halinden belliydi.Üzerine baktığımda içimden bir şeylerin koptuğunu hissettim. Tüyleri neredeyse tamamen dökülmüştü. Bir tavuktu bu. Ama çocukluğumuzda köylerde sağa sola koşturan, neşeyle toprağı eşeleyen o gür tüylü, canlı yaratıklara hiç benzemiyordu.Atıldığı toprağın üzerinde tuhaf adım atışları,  kanat diplerinde yer yer beliren o kırmızı, tahriş olmuş çıplak deri, uğradığı sessiz şiddetin haritası gibiydi. Başında sadece birkaç cılız tüy kalmıştı. Yorgundu, bitkindi... Yıllarca gün yüzü görmemiş, yapay ışıklar altında, önüne konan bir avuç yem ve paslı su karşılığında gençliğini, enerjisini, canlılığını tel örgülerin ardında bırakmıştı.Her bir yumurta için özgürlüğünü, doğasını ve en temel hareket yetisini elinden almıştık. Yumurtlama süreci bitip "verimsizleştiğinde" ise ona sunulan özgürlük değil, sadece bir sondu: Bedeninin son kırıntılarını da üç beş kuruş karşılığında bir bıçağın ucuna teslim etmek. Birkaç yumurta, bir kahvaltı tabağındaki birkaç dakikalık doyum için bir canlıya bu hezeyanı, bu dramı yaşatmaya değer miydi? Ona doğru bir adım atmak istedim ama utancımdan yaklaşamadım. İnsanoğlunun kurduğu bu acımasız çarkın ortasında, yürümeyi bile yeniden öğrenmeye çalışan o küçük, bükülmüş bedenin önünde kendi türüm adına sadece sessizce başımı eğdim.

                             Şükrullah YAVUZER', 'Mahallemizin sokaklarını geride bırakıp Cuma namazı için adımlarımı o mütevazı camiye doğru çevirdiğimde, havanın serinliğine karışan hayatı...', ARRAY['Türk Edebiyatı','Şiir','Şükrullah Yavuzer']::text[], 8.5, '{"poet":"Şükrullah Yavuzer","poet_slug":"sukrullah-yavuzer","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/yurumeyi-unutan-canlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalp dili', 'kalp-dili-sergen-sayin-iw3qz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül ne kâr bilir ne ziyan,

Aşk ile yanar, etmez figan.

Akıl hesap sorar her dem,

Kalp teslim olur, aramaz nişan.

Kimi vuslat ister, kimi derman,

Kimi bir secdede bulur umman.

Aşkın terazisi olmaz ey can,

Bir damla yaşta gizlidir cihan.', 'Gönül ne kâr bilir ne ziyan, Aşk ile yanar, etmez figan. Akıl hesap sorar her dem, Kalp teslim olur, aramaz nişan. Kimi vuslat ister, kimi d...', ARRAY['Türk Edebiyatı','Şiir','Sergen Sayın']::text[], 8.5, '{"poet":"Sergen Sayın","poet_slug":"sergen-sayin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kalp-dili-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Riyakarlık', 'riyakarlik-andelip-mehmet-2td6r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne desem anlatamam, bu nasıl riyakarlık,

Makam, mansıp deyince, koşuyorsun her zaman.

Hayatında yer etmiş, daima sahtekarlık,

Yalan, sahte sözlerle, şişiyorsun her zaman.

Özünde uğursuzluk, çehresine bakınsan,

Sanki mühür vurulmuş, kalbine bir dokunsan

Şeytanca huyu vardır, hayatına yakınsan

Şöhretle, İhtirasla, coşuyorsun her zaman.

Yalan ve iftirayla, hak yolundan savruldun,

Şiarın, fısk-u fücur, günahlara boğuldun,

Ezan bayrak diyerek, baş köşeye kuruldun,

Şeytanlarla beraber, yaşıyorsun her zaman.

Vatan, millet diyerek, hep nefsine çalıştın,

Lükse ve ihtişama, yavaş yavaş alıştın,

Fitne ektin ruhlara, sözlerinle çeliştin,

Mizanlar kurulunca, şaşıyorsun her zaman.

Düşmanlık var ruhunda, yalan iftira derken,

Efkarı kirletmekte, her an kibre girerken,

Dini sömürmek için gösterişe dalarken,

Öz kardeşin karnını, deşiyorsun her zaman.

İman, itikat deyip, kullanmakta hep nâsı,

Nifak tohumlarıyla, yeşermekte rüyası,

Helallik kapısında, haram oldu dünyası,

Şeytanın tuzağına, düşüyorsun her zaman.

Sürüye kurt dadanmış kimsede yoktur takat,

Bukalemun gibidir, hepsinin rengi sakat,

Ayrılmaz iblislerden, şimdi yese de tokat,

Cehennem ateşinde, pişiyorsun her zaman.', 'Ne desem anlatamam, bu nasıl riyakarlık, Makam, mansıp deyince, koşuyorsun her zaman. Hayatında yer etmiş, daima sahtekarlık, Yalan, sahte s...', ARRAY['Türk Edebiyatı','Şiir','Andelip Mehmet']::text[], 8.5, '{"poet":"Andelip Mehmet","poet_slug":"andelip-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/riyakarlik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perişan', 'perisan-andelip-mehmet-a60lz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalplerden gitmiyor şimdi hıçkırık,

Bu sonsuz kervanda, yollar perişan.

Mübârek kapında gönlümüz kırık,

Yaprağı dökülen, dallar perişan.

Hep senin yoluna sürüldü yüzler,

Çok kez tövbe edip bozuldu sözler,

Şimdi kapanırken günaha gözler,

Rahmetin olmazsa, kullar perişan.

Kapında kul olan, bu gönüllerle,

Karanlık her gece susan dillerle,

Tedirgin, utangaç, mahcup hâllerle.

Her zaman yutkunan, diller perişan.

Çile ve dertlerle geçse de zaman,

Şeytan bir aldatan nefis çok yaman,

Bu ıssız mekanda yollar hep duman!

Her iki cihanda, haller perişan.

Şimdi bu kulların boynu hep bükük,

Omuza yüklenmiş dağlar kadar yük,

Bu âciz fakirin günahı büyük!

Şimdi gözler kalpler, eller perişan.

İlahi kalbim ve ruhum sana aç!

Ne gönle nasihat, ne nefse kırbaç,

İnsan olan herkes rahmete muhtaç!

Bir mucize olan, ballar perişan.

Durmuştum kapında el pençe divan,

Nice yiğitler var yollara revan,

Bir ömür boyunca kayboldu havan.

Ülkeler, beldeler, çöller perişan.

Neşe dolu günler beklerken canı,

Kalplerin içinde erirken kini,

Bu güzel alemin biterken günü,

Solan çiçeklerle güller perişan.

Yıllardır kapında oldum bir geda,

Şimdi her varlığım yoluna feda,

Çiçek bahçesine ederken veda! 

Renk renk çiçeklerde, allar perişan.', 'Kalplerden gitmiyor şimdi hıçkırık, Bu sonsuz kervanda, yollar perişan. Mübârek kapında gönlümüz kırık, Yaprağı dökülen, dallar perişan. Hep...', ARRAY['Türk Edebiyatı','Şiir','Andelip Mehmet']::text[], 8.5, '{"poet":"Andelip Mehmet","poet_slug":"andelip-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/perisan-208-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Olacaksın', 'dus-olacaksin-andelip-mehmet-01nyw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sanki akıyorsun, hep gözlerimden.

Giderken arkamdan, düş olacaksın.

Hala ders almadın, o sözlerimden,

Gözlerimden akan, yaş olacaksın.

Herkesten akıllı, sanma kendini,

Nefse, cehalete, bildir haddini,

Her zaman hasretle ararken beni,

Gözlerin üstünde, kaş olacaksın.

Gerçeklerden uzak, oldun habersiz,

Zihnin sanki donmuş, gözlerin fersiz,

Yaşadığın aşkta, endişen yersiz,

Ayaklar altında, baş olacaksın..

Toprak olamadın, fakat taş oldun.

Kul hakkı yiyerek, büyük baş oldun,

Ateşten gömleği, giyen eş oldun,

Cehennemde yanan, taş olacaksın.

Günahı bırakıp, son ver ecrama,

Şehvete gem vurup, girme harama,

Huri gılman deyip melek arama,

Gönüllere giren, eş olacaksın.

Sefil duygulardan, olsan hep beri,

Kalbinden girmesin, günah içeri,

Tövbeler ederek, dönersen geri,

Cennetlerde uçan, kuş olacaksın.', 'Sanki akıyorsun, hep gözlerimden. Giderken arkamdan, düş olacaksın. Hala ders almadın, o sözlerimden, Gözlerimden akan, yaş olacaksın. Herke...', ARRAY['Türk Edebiyatı','Şiir','Andelip Mehmet']::text[], 8.5, '{"poet":"Andelip Mehmet","poet_slug":"andelip-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dus-olacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede', 'nerede-andelip-mehmet-kang6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu kutlu mekanlar, ruha can katarken,

Bu iman, bu izan, bu vicdan, nerede?

Yaşanan güzellik, heycânı atarken,

Bu hikmet, bu kısmet, bu nalan nerede?

Sevgiden ayrılan, gözlerim ağlarken,

Hasretin yürekte, yaralar bağlarken,

Şimdi gözlerimden kanlı yaş çağlarken,

Bu hasret, bu hüzün, bu hicran nerede?

Ayrı kaldım senden, sen uzak durunca,

Buruktur şimdi kalp, gönülden vurunca,

Etrafı dert, çile, ızdırap sarınca,

Bu gaflet, bu hiddet, bu hüsran nerede?

Aşk gülden ayrılmaz, onda has mâye var

Letâfet cezbeder, aşkta bir gâye var

Cânan muzdaripken, katlanan pâye var.

Bu harman, bu derman, bu ferman nerede?

Bu nasıl gaflet ve dalalet bilmezken,

Üç günlük dünyada, hiç huzur bulmazken,

Sevda dolu kalple, yine de gülmezken,

Bu sevda, bu tutku, bu seyran nerede?

Dertten ve kederden, kalmadı hiç vefâ

Hakka tevekkül et, çekme asla cefâ,

O Rahman Rahîmdir, Ondayken her şifâ,

Bu hüsran, bu hicran, bu derman nerede?', 'Bu kutlu mekanlar, ruha can katarken, Bu iman, bu izan, bu vicdan, nerede? Yaşanan güzellik, heycânı atarken, Bu hikmet, bu kısmet, bu nala...', ARRAY['Türk Edebiyatı','Şiir','Andelip Mehmet']::text[], 8.5, '{"poet":"Andelip Mehmet","poet_slug":"andelip-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/nerede-293-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bir Yerde Ben Başka Yerde', 'sen-bir-yerde-ben-baska-yerde-andelip-mehmet-r5lr1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yunus gibi bir aşk, bulamadık hiç,

Sen bir gülde buldun, ben başka gülde!

Gönül dergahına dalamadık hiç,

Sen bir dilde kaldın, ben başka dilde!

Mahlukatı sevip, hep nazar ettik

Sonsuz iyilikle kaç adım gittik?

Kiminle savaşıp kiminle bittik?

Sen bir çölde soldun, ben başka çölde!

Neden huzur bulup, bir an gülmedik,

Candan bir dost olup, kıymet bilmedik,

Dertleri terkedip, huzur bulmadık,

Sen bir gölde oldun, ben başka gölde!

Sevip nazlamadık gönülden evi

Hiç öldüremedik nefisten devi?

Kimi sünni dedi kimi alevi

Sen bir yelde geldin, ben başka yelde!

Çıbanın başını ezemedik hiç!

Düşmanla kol kola gezemedik hiç!

Gönül denizinde yüzemedik hiç!

Sen bir yolda gittin, ben başka yolda!

Artık gemileri aldık azıya

Çare bulamadık bir tek sızıya

Sevgi kitabında kalan yazıya

Sen bir dalda soldun, ben başka dalda!', 'Yunus gibi bir aşk, bulamadık hiç, Sen bir gülde buldun, ben başka gülde! Gönül dergahına dalamadık hiç, Sen bir dilde kaldın, ben başka dil...', ARRAY['Türk Edebiyatı','Şiir','Andelip Mehmet']::text[], 8.5, '{"poet":"Andelip Mehmet","poet_slug":"andelip-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-bir-yerde-ben-baska-yerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senindir', 'senindir-andelip-mehmet-l8uoy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlahi; kalpleri güllerle doldur,

Bahçeler Senindir, güller Senindir,

Sensiz gönüllere, imanı buldur,

Petekler Senindir, ballar Senindir.

Bahar mevsiminde yeşerir her yer,

Çiçekler açarken coşar denizler,

Gecede yıldız var, nurdur gündüzler

Deryalar Senindir, göller Senindir.

Güllerle sarıldı dört bir yanımız,

Çağlayan sulara aktı kanımız,

Açtığın bu yola feda canımız,

Mekanlar Senindir, yollar Senindir.

Bir duman, bir sis var, garip bir tufan,

Ateşler içinde yanarken zaman,

Sensiz perişanız haller çok yaman,

Gelecek Senindir, haller Senindir.

Artık açılıyor göklerde şehbal,

Ufuklarda bir nur aydındır ikbal,

Mazi geçti artık, şimdi istikbal,

Asırlar Senindir, yıllar Senindir.', 'İlahi; kalpleri güllerle doldur, Bahçeler Senindir, güller Senindir, Sensiz gönüllere, imanı buldur, Petekler Senindir, ballar Senindir. Bah...', ARRAY['Türk Edebiyatı','Şiir','Andelip Mehmet']::text[], 8.5, '{"poet":"Andelip Mehmet","poet_slug":"andelip-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/senindir-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün  günahları  gömdük  bu Gece', 'butun-gunahlari-gomduk-bu-gece-andelip-mehmet-ug3np', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mübarek günlerde, çok af dileyip,

Bu kutlu zamanı, andık, bu gece.!

Bütün duaları, dile dolayıp,

Rahmet deryasında, yunduk bu gece!

Ömür duçar olur, bomboş hevese,

Ruhu hapsederken iblis kafese,

Hep Seni sığdırdık, her bir nefese,

Aşkın ateşiyle, yandık bu gece!

Gönüllere coşku, veren resmini,

Kalpler dua eder, görmez cismini,

Her gece anarken, güzel ismini,

Sonsuz nimetlere, bandık bu gece.!

Çok çileler çektik, baştan bu yana,

Ümidimiz vardır, yine hep sana,

Dualar edince, Rahim, Rahman’a,

Gönüller tahtına konduk bu gece!

Engin rahmetine, verseydik değer,

Dualar ederdik, görseydik eğer,

Sensiz hayatımız, acıymış meğer,

Sanki gök kubbeden, indik bu gece.!

Bir kurtuluş bir can, oldu zamanlar,

Rahmetle huzurla, doldu mekanlar,

Bu gece hep seni, kalpten ananlar,

Bütün günahları, gömdük bu gece!

Çabuk geçti rahmet, dolu bu günler,

Ümitle kalkardı, semaya eller,

Bahçede rengarenk, açardı güller,

Uçan Buraklara, bindik bu gece.!', 'Mübarek günlerde, çok af dileyip, Bu kutlu zamanı, andık, bu gece.! Bütün duaları, dile dolayıp, Rahmet deryasında, yunduk bu gece! Ömür duç...', ARRAY['Türk Edebiyatı','Şiir','Andelip Mehmet']::text[], 8.5, '{"poet":"Andelip Mehmet","poet_slug":"andelip-mehmet","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/butun-gunahlari-gomduk-bu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gardenya...', 'gardenya-adsiz-gardenya-03uyp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bi tek senden ayrılınca kendime
kavuşamıyorum...
sanki ömrümün en güzel yerinde sana rastladım da geri kalan bütün hayatı yanlış bir adreste yaşamaya mahkum kalmışım, adını anmadığım günlerde bile içimde sana ayrılmış bir ömür var. 
ben seni bir sevda gibi değil, 
kendime ait en güzel kader gibi sevdimm....
@dsız&g@rdenya...', 'bi tek senden ayrılınca kendime kavuşamıyorum... sanki ömrümün en güzel yerinde sana rastladım da geri kalan bütün hayatı yanlış bir adreste...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gardenya-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret 8', 'hasret-8-adsiz-gardenya-6apxl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sokak uzuyordu
O yürüdükçe bitmeyen bir hesap gibi
Ayakları ağırdı
Ama durmaya da cesareti yoktu
Çünkü durursa düşünecekti
Düşünürse geri dönecekti
Bir sigara yaktı
Eli hafif titredi
İlk nefesi içine çekerken gözlerini kapattı
sakin ol
dedi kendi kendine
bu da geçer
Ama içindeki o tanıdık ses yine gecikmedi
geçmeyecek
sen taşıyacaksın bunu
Başını iki yana salladı
Sanki o sesi susturabilirmiş gibi
başka çarem yoktu
diye fısıldadı tekrar
bu kez daha inatla
kalsaydım daha kötü olacaktı
her şey daha çok kırılacaktı
Bir banka oturdu
Dirseklerini dizlerine koydu
Başını eğdi
Sokaktan geçen birkaç kişi oldu
Ama kimse ona bakmadı
Ya da o öyle sandı
İçinde bir yer
hala kapının önünde kalmıştı
Bunu hissetti
Ve ilk defa açık açık söyledi
ben aslında tam gitmedim
Bu cümle ağırdı
Kendi omuzlarına çöktü
Çünkü gitmek sadece adım atmak değildi
İçinden de söküp atman gerekiyordu
O ise sadece bedenini uzaklaştırmıştı
Bir an cebinden telefonunu çıkardı
Ekrana baktı
Parmakları kilidin üstünde durdu
arayabilirim
dedi içinden
Sonra hemen geri çekti elini
yok
daha erken
ya da çok geç
Kafası karıştı
Başını kaldırıp boşluğa baktı
pişmanım ama dönemem
dedi bu kez net bir şekilde
Ama o sert iç ses yine oradaydı
dönemezsin değil
dönmeye cesaretin yok
Gözlerini kapattı
Dişlerini sıktı
haklısın
diye mırıldandı bu kez ilk defa karşı çıkmadan
Rüzgar biraz daha sert esti
Gece derinleşti
Ve o gece
Sokakta tek başına otururken
Şunu anladı
Bazen insan
Doğru olanı yapmaz
Sadece yapabildiğini yapar
Ve o
Elinden gelen tek şeyi yapmıştı
Gitmişti
Ama içinden bi şeyler 
hala eksik kalmıştı....
Yada öyle hissediyordu..', 'Sokak uzuyordu O yürüdükçe bitmeyen bir hesap gibi Ayakları ağırdı Ama durmaya da cesareti yoktu Çünkü durursa düşünecekti Düşünürse geri dö...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/hasret-8-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret 7', 'hasret-7-adsiz-gardenya-8mjlj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece ince ince üzerine çökmüş
Sokak lambaları sarı bir yorgunluk gibi vuruyordu yüzüne
Adımlarını rastgele atıyordu
Nereye gittiğini bile bilmiyordu
Ama nereden uzaklaştığını çok iyi biliyordu.
Ceplerine soktu ellerini
Başını hafif eğdi
Sanki yüzünü saklarsa içindekiler de görünmez olacaktı
Bir an durdu
Arkasına bakmadı
Bakarsa döneceğini biliyordu çünkü
Kendi kendine konuştu yine
Hayır hayır dönemezsin
artık olmaz.
bitti.
Sonra hemen ardından başka bir ses
daha yumuşak
daha kırık
-belki de bitmemiştir
-belki de sadece korktun
Yürümeye devam etti
Ayak sesleri gecede yankılanıyordu
Her adım sanki biraz daha ağır
başka çarem yoktu
diye mırıldandı bu kez daha belirgin
kalsaydım daha çok incitirdim
onu da kendimi de
Ama bu cümleleri söylerken dudakları titredi
Çünkü içindeki o sert ses yine susmadı
yok
dedi içinden
sen kendini kurtardın
Bir köşe başına geldi
Rüzgar yüzüne çarptı
Sanki biri yüzüne gerçeği vurmuş gibi
Gözlerini kapattı bir an
Ve ilk defa içinden geçen o kelimeyi açık açık söyledi
pişmanım
Ama hemen ardından başını salladı
Sanki o kelimeyi geri alabilirmiş gibi
hayır
mecburdum
Bu iki kelime arasında sıkıştı kaldı
Her adımında biri diğerini boğmaya çalışıyordu
Sokak uzadıkça içindeki sesler çoğaldı
Ve o gece
Kalbinden ilk defa şu cümle geçti
keşke gitmek zorunda kalmasaydım
Ama en çok da şunu düşündü
keşke kalacak kadar güçlü olsaydım...', 'Gece ince ince üzerine çökmüş Sokak lambaları sarı bir yorgunluk gibi vuruyordu yüzüne Adımlarını rastgele atıyordu Nereye gittiğini bile bi...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/hasret-7-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hocam...', 'hocam-adsiz-gardenya-7eu22', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şöyle bi düşünüyorumda bana göre hayatımda biri var ama sadece hayalimde...
Ne bir plan var ne bir paylaşım uzaktan uzağa beklediğim ama bir bedene bürünemeyen ve sadece ütopik bir sevgili.
Naptığını bilmediğim naptığımdan habersiz... Özlemekle yetindiğim beklemekle ödüllendirildiğim ama hiç ceza kesilmeyen o özel kişiyim...
Verilen kısa zamanlık mutluluğu günlere pay ettirilen bununla yetinmeyi öğreten bir hocanın asla öğrenmeyi bilmeyen öğrencisiyim...
Ben okulu bırakıyorum hocam benden ne mühendis çıkar ne doktor ne de sizin gibi bir öğretmen...', 'Şöyle bi düşünüyorumda bana göre hayatımda biri var ama sadece hayalimde... Ne bir plan var ne bir paylaşım uzaktan uzağa beklediğim ama bir...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hocam-115-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınıfta Kaldık...', 'sinifta-kaldik-adsiz-gardenya-dgwsv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şöyle bir düşünüyorum da…
Bana göre hayatımda biri var ama yalnızca hayaLimde. 
Ne birlikte kurulmuş bir planımız var ne de paylaşılmış bir hayatımız. 
Uzaktan uzağa beklediğim, 
bir türlü ete kemiğe bürünemeyen, 
yalnızca hayallerimde yaşayan ütopik bir sevgiLi…
Ne yaptığından haberim var ne de benim neler yaşadığımdan onun. 
Ben onu özlemekle yetiniyorum, 
beklemekle ödüllendiriliyorum. 
Garip olan şu ki, bu bekleyişin hiç cezası kesilmiyor ama ömrümden her gün bir şeyler alıp götürüyor.
Bana ayrılan birkaç dakikalık mutluluğu günlere bölüp yaşamayı öğreten bir hocanın, bir türlü dersini öğrenemeyen öğrencisiyim ben. 
Bir bakışını haftalarca içimde saklayan, 
bir cümlesini günlerce kendine yoldaş eden, kısacık bir kavuşma ihtimalinden koskoca bir ömür çıkaran bir öğrenci…
Ama artık yoruldum hocam.
Ben okulu bırakıyorum.
Benden ne mühendis çıkar ne doktor ne de sizin gibi bir öğretmen…
Ben bu okulda yalnızca sevmeyi öğrendim, kavuşmayı bir türlü öğretemediniz.
Diplomamı da istemiyorum artık, 
tek dileğim şu,
Bir gün beni de hayalimde değiL, 
birinin hayatında yaşatın hocam.....
@dsız..', 'Şöyle bir düşünüyorum da… Bana göre hayatımda biri var ama yalnızca hayaLimde.  Ne birlikte kurulmuş bir planımız var ne de paylaşılmış bir ...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sinifta-kaldik-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemek...', 'ozlemek-adsiz-gardenya-lz1sh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni beklemek sorun değil de, 
Asıl beni yoran, seni özlemek.. 
Beklerim, gerekirse ömrümden günler eksilir,
ama özlemek var ya..
Sesini duyamadan, gözlerine bakamadan, sana sarılamadan geçen her gün içimde biraz daha büyütüyor hasretini..
Bazen tek bir sözün,
 bazen küçücük bir mesajın yetiyor mutlu olmama..
Ama sen uzaktayken hiçbir şey tamamlanmıyor içimde...
Ben seni beklemeye razıyım da, 
seni bu kadar özleyip sana kavuşamamak,
işte en çokta bu yoruyor beni..
@dsız.. &g@rdenya..', 'Seni beklemek sorun değil de,  Asıl beni yoran, seni özlemek..  Beklerim, gerekirse ömrümden günler eksilir, ama özlemek var ya.. Sesini duy...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozlemek-384-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret 6', 'hasret-6-adsiz-gardenya-gd5zy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayağı eşiğin ötesine değdiği anda, 
geride bıraktığı her şey sessizce üzerine kapandı. Kapı kapanmadı belki... 
ama içindeki bir şey, 
geri dönmemek üzere sustu.
Yürümeye başladı.
Adımları ağırdı. 
Sanki her biri bir hatıraya basıyor, her adımda biraz daha içine gömülüyordu. Gecenin soğuğu artık dışarıdan değil, içinden yükseliyordu.in hikayesi..
Bir an duraksadı.
Arkasına bakmadı...
Çünkü bazı insanlar bilir, 
dönüp bakarsan
gidemezsin.
Ama gitmek de öyle kolay değildi.
İçinde kalanlar vardı. 
Söylenmemiş sözler, yarım bırakılmış cümleler, tutulmamış eller... 
Hepsi birer gölge gibi peşine takıldı. Ne kadar uzaklaşırsa uzaklaşsın, 
karanlık uzadıkça onlar da uzadı.
Belki kalsaydım...
diye geçti içinden.
"Belki bir cümle daha kursaydım...
Ama "belki"ler, en ağır yüktü insanın sırtında.
Yol uzadıkça omuzları çöktü. Attığı her adım,
onu uzaklastırdı evet... 
ama aklını bir türlü
koparamadı o kapıdan. 
Sanki zihni hala o eşikte
durmuş, kendisini bekliyordu.
O ilerledi...
Aklı geride kaldı.
İşte insanı en çok yoran da buydu zaten...
bedeninin gittiği yere, kalbinin gelememesi.
Bir sokak lambasının altında durdu.
Sarı ışık yüzüne vurduğunda fark etti... gözleri doluydu ama ağlamıyordu. 
Çünkü bazı pişmanlıklar gözyaşıyla değil, susarak yaşanırdı.
Derin bir nefes aldı.
İlk defa gerçekten yalnız hissetti kendini.
Çünkü bu kez yalnızlık, birinin yokluğu değil...
kendi eksikliğiydi.
Ve o an anladı
Uzaklaşmak, unutmak değildi.
Sadece...
yanında taşıyamadığın şeyleri geride bıraktığını
sanmaktı.', 'Ayağı eşiğin ötesine değdiği anda,  geride bıraktığı her şey sessizce üzerine kapandı. Kapı kapanmadı belki...  ama içindeki bir şey,  geri ...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/hasret-6-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret 5', 'hasret-5-adsiz-gardenya-632cy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kapının eşiğinde durduğu o an, zaman sanki kendi üzerine çökmüştü.
Gece, soğuk nefesini ensesine bırakırken içerisiyle dışarısı arasında sıkışıp kalmıştı. Bir adım atsa geçmişine dönecekti, bir adım atsa bilmediği bir karanlığa karışacaktı. Ama asıl mesele yol değildi… mesele, hangi yükle yürüyeceğiydi.
Elini kapının kenarına koydu. Tahta soğuktu. Tıpkı içinden geçen o tanıdık his gibi… yabancı ama bir o kadar da yerleşmiş.
İçeriden bir ses yoktu artık. Ne bir hatıra kıpırdıyordu ne de bir umut. Sanki o ev, onun içini çoktan boşaltmış da geriye sadece kabuğunu bırakmıştı.
Başını hafifçe eğdi. Gözleri karanlığa alışmıştı ama içi hâlâ kördü.
“Git…” dedi içinden biri.
“Kal…” dedi bir diğeri.
Ama o, ne gitmeyi becerebilenlerdendi ne de kalmayı taşıyabilenlerden.
Eşiğin tam ortasında durdu. Çünkü bazı insanlar için en gerçek yer, iki dünya arasıdır. Ne geçmişe aittirler ne geleceğe.
Rüzgâr kapının aralığından içeri sızdı. Omzuna değdi, sanki biri dokunmuş gibi. Bir an gözlerini kapattı… belki bir isim geçer diye içinden, belki bir ses geri çağırır diye.
Hiçbir şey olmadı.
İşte o an anladı…
Bazen insanı tutan şey sevgi değil, alışkanlıktır.
Ve bazen en zor vedalar, kimseye söylenmeden edilenlerdir.
Yavaşça doğruldu.
Ayağını kaldırdı…
Ama bu kez eşiğin neresine bastığını kendisi de bilmedi.', 'Kapının eşiğinde durduğu o an, zaman sanki kendi üzerine çökmüştü. Gece, soğuk nefesini ensesine bırakırken içerisiyle dışarısı arasında sık...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hasret-5-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonra...', 'senden-sonra-adsiz-gardenya-blh8n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senden sonra,
Ben hep aynı kaldım…
Bahar geldi, yeşeremedim.
Papatya gibi açamadım.
Viran olmuş bağda sensiz sessiz  kurudum.
Senden sonra ,
Şimdi aylardan Eylül,
Yapraklar ağaçlara,
Kuşlar yaza, küsüp göç ettiler..
Senden sonra,hiç bir şeyin tadı yok,eskisinden daha çok yakıyorum , yaktığım sigaraları,
çaydan, kahveden  soğuyorum...

Düşündüm…
Yoksa yaşam denen o güzellik
Bana uğramayı mı unuttu dersin?

Senden sonra,
Ben hep sende kaldım…
Eşlik ettiler akrep ve yelkovan.
Senli günlere ayak diretdiler,
Akan zamana inat…Ben hep sende kaldım..

Senden sonra,
Alıştım gibi sensizliğe.
Kangren olan yaralarım bile
Kabuk tuttular..
Bir tek, bir tek şuramda
Hafiften bir sızı kaldı sanki...
“Geçer,” dediler… “Olur o,” dediler… Zaman dediler,
Geçer mi sahi? geçer mi.?

Senden önce ben vardım,
Ama ya senden sonra?
Senden sonrası yok işte...

Soruyorum kendime,
Bu sevdadan elimde kalan ne?
Sonra hatırlıyorum birden cevabı;
İçimi acıtan bir yara gibi
Sol yanımda bıraktığın O  sızıyı
Ve buna rağmen hâlâ seni sevdiğimi…

Sen benden gittin ama,
Sanırım ben hep sende kalacağım.
Çünkü,
Senden sonra
Yeminliyim sevmemeye, kimseye inanmamaya, güvenmemeye..
Senden sonra,
Kimseyi yerine koyamadım ki, herkeste seni gördüm , tüm seslerde , sesin vardı sanki, gördüğüm tüm yüzlerde, yüzün vardı, 
Koyamadım kimseyi işte yerine....

Olmamalı…Olmamalı...
O kadar kolay olmamalı...
Elini kolunu sallayarak çekip gitmek.
Sorgusuz sualsiz,
Kafası bozulunca
Bırakıp gitmeye hakkın olmamalı.
Tarumar ettiğin hayata
Bakmalısın zaman zaman, başını çevirip…

Senden sonra
Sevemez oldum kimseyi.
Yokluğun zemheri soğuğu gibi
Dondurdu tüm bedenimi, yüreğimi.
Kendime bile anlatamadım derdimi,
Hâlâ kalbimde olduğunu
Ve hâlâ körkütük seni sevdiğimi…
Anlayacağın, senden sonrası olmadı.
Ben hâlâ sendeyim ve seninleyim.
Çünkü ben senden sonrasını hiç düşünmedim ki.
Hiç senden sonrasını yüreğimde hissetmedim ki.
Senden sonra diye bir kavram kabul edemem ki.
Senden sonra ben zaten yokum ki..

Senden sonra tutunmadım hayata.
Bilirim, belki de yaptığım hata.
Sensizliğim döndü şimdi feryada.
Sitemlerim sessiz…sedasız...

Senden sonra;
Yapraklar bırakıp gider ağaçları.
Nefessiz ve sessiz…
Kara kaşım, ayazım
Sol yanımın ince ağrısı,
Sensiz uyuduğum kaçıncı gece,
Sensiz uyandığım kaçıncı günüm…bilmiyorum..

Her yerde kokun…sesin...
Yüreğimde çaresizce taşıdığım,
Bir bıçaktır özlemin,
Yüreğim vakitli vakitsiz kanar oldu.
Ayaklarım yere daha bir yorgun basar.
Yüreğim yaralar içinde, kimsesiz.
Her şey boş, sen gittikten sonra…
Senden sonra, söz ve şiir sustu...

Nehir yataklarını sular bırakıp gitti,
Baharı unutan ağaçlar kurudu.
Yaz bitti, sonbahar geldi.
Sen giderken baharları da götürdün.
Senden sonra mevsimsizdi zaman.
Senden sonra yağmadı yağmurlar,
Öksüz büyüdü toprak..

Senden sonra değişmeyen tek şey
Ezan sesleriydi...yüreğimde ki yerindi...

Şimdi zeytin ağaçları öksüz,
Bitter çikolatalarının tadı yok.
Sanki sokaklar bomboş,
Denizin dalgaları susmuş, konuşmuyor...

Senden sonra,
Ağustos böceğiyle karıncanın dostluğu bitti.
İncir ağaçlı sokağın tadı kalmadı.
Senden sonra senli dualarım olmadı artık Rabbime.
Senden sonra uzun uzadıya konuşmadım telefonlarla,
Bakmadım gelen aramalara, mesajlara…
Yani, anlayacağın,
Senden sonrasının yolları yoktu.
Baharları yoktu.
Yağmursuzdu…
Susuzluktu…

Artık sanki sen gelecekmişsin gibi
Kalkmıyorum sabahları.
Saçlarımı taramıyorum, Az şekerli kahveyi de içmiyorum artık,
Senden sonrası anlatılmaz… İşte…
Sadece yaşanır...

Sevda denilen illet, bittikten sonra başlıyor,
Gönlü kırar geçirir, tüm yürekleri haşlar.
Sanki bir nehir olur, tükenmek bilmez yaşlar.
Kim der ise yalan der, geçmez vallahi, geçmez, billahi geçmez..

Biliyor musun,
Ben senden sonra,
O parka hiç gitmedim...
Kuşlar, ağaçlar, parktaki çocuklar
Şahit olmadı benim kahkahalarıma…
Bilir misin? Senden sonra,
Senden sonra ben hiç gülmedim.
Senden sonra hiç bir şeyin anlamı olmadı...

Senden sonra…Senden sonrası yok işte....
Senden sonrası... olmadı...
olmadı', 'Senden sonra, Ben hep aynı kaldım… Bahar geldi, yeşeremedim. Papatya gibi açamadım. Viran olmuş bağda sensiz sessiz  kurudum. Senden sonra ,...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":128,"source_url":"https://www.antoloji.com/senden-sonra-624-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoruldum', 'yoruldum-levent-dizdar-gskvc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'YORULDUM

Elmastım, karardım

Üç paralık kor oldum

İnsandım, şaştım 

O cennetten kovuldum

Sana geldim sığındım

Yüreğine vuruldum

Güzel olan her şeyi 

Sen sanmaktan yoruldum.

2026', 'YORULDUM Elmastım, karardım Üç paralık kor oldum İnsandım, şaştım  O cennetten kovuldum Sana geldim sığındım Yüreğine vuruldum Güzel olan he...', ARRAY['Türk Edebiyatı','Şiir','Levent Dizdar']::text[], 8.5, '{"poet":"Levent Dizdar","poet_slug":"levent-dizdar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yoruldum-625-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceler', 'geceler-adsiz-gardenya-t9xur', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen hep beyaz kal olur mu?
Zaten gece yeterince kara...
Sen hep beyaz kal olurmu?
Ben karanlığa razıyım,
Yeter ki sen beyaz kal olurmu?
Kirlenmesin gözlerin dünyanın yükünden, Yorulmasın kalbin insanların gölgesinden. Ben taşırım gecenin bütün ağırlığını,
Yeterki sen beyaz kal olurmu?
Çünkü bazı insanlar karanlıkta kaybol Sen kaybolma olurmu?...
@dsız.. G@rdenya', 'Sen hep beyaz kal olur mu? Zaten gece yeterince kara... Sen hep beyaz kal olurmu? Ben karanlığa razıyım, Yeter ki sen beyaz kal olurmu? Kirl...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/geceler-859-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret 4', 'hasret-4-adsiz-gardenya-2rtc8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kapının eşiğinde durdu…
Gece omuzlarına çökerken, 
içindeki boşluk daha da büyüdü.
Üşüyordu…
Ama bu soğuk dışarıdan değildi,
hala içindeydi.
Ayaz tenine değil, 
doğrudan içine vuruyordu.
Sanki kalbinin attığı her yer biraz daha donuyordu.
Nefes aldı… ciğerleri yandı.
Nefes Verdi… içinden bir şey eksildi.
Sokak susmuştu.
Öyle bir suskunluk ki bu, 
insanın kendi iç sesini bile yabancı gibi duyduğu cinsten.
Adını söylese yankı yapacak, 
dönüp yine onu bulacak gibiydi.
Kapıya baktı…
O kapı artık bir ev değildi.
Bir zamanlar sığındığı ne varsa, şimdi yüzüne kapanmış gibi duruyordu.
Elini uzattı…
parmakları titredi.
Dokunursa kırılacak bir şey varmış gibi çekti kendini.
Çünkü bazı kapılar açılmaz usta…
açılsa bile içeri giren artık aynı olmaz.
Başını duvara yasladı.
Soğuk taş, alnından içeri yürüdü.
Gözlerini kapattı…
ama karanlık değişmedi.
İçeride bıraktıkları geçti aklından,
yarım cümleler, tutulmamış sözler, geç kalınmış anlar…
Hepsi bir bir geldi, 
tam göğsünün ortasına oturdu.
Yutkundu.
Geçmedi.
İnsan bazen ağlayamaz usta…
çünkü gözyaşı bile yetmez içinde olana.
Ayakları sanki yere çivilenmişti.
Ne ileri gidebiliyordu, 
ne geri dönebiliyordu.
Sadece bekliyordu…
ama neyi, kendisi bile bilmiyordu.
Gece uzadı.
Soğuk derinleşti.
Ve o…
hala o eşikteydi.
Sanki biri gelip “kal” dese kalacaktı,
biri “git” dese gidecekti…
Ama kimse gelmedi.
Çünkü bazı yalnızlıklar vardır usta…
başrolünde hep tek kişi olur.
Ve o an anladı…
bu eşik bir kapı değil.
Bu, insanın kendine en uzak olduğu yerdi.', 'Kapının eşiğinde durdu… Gece omuzlarına çökerken,  içindeki boşluk daha da büyüdü. Üşüyordu… Ama bu soğuk dışarıdan değildi, hala içindeydi....', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/hasret-4-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret 3', 'hasret-3-adsiz-gardenya-t0yog', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kapı eşiginde kaldı.
Ne içeri adım atabildi ne de geldigi yere geri donebildi.
Bazen insanın en uzun yolculugu,
 bir eşigi gecmek kadar kısa olur ya iste tam oradaydı.
Elini kapının kenarına koydu.
Parmakları titremiyordu ama ici… 
fırtına gibiydi.
Çünkü biliyordu,
0 kapıdan geçerse sadece bir odaya degil, gecmise girecekti.
Iceriden bir ses gelmedi.
Ne bir adım, ne bir nefes…
Sanki iceride zaman coktan durmustu da, onu beklemeyi bırakmıstı.
Gozlerini kapattı bir an.
Aklına o son gun geldi.
Yarım kalan cumleler, soylenmeyenler, yutulan gurur…
“Bir adım…” dedi icinden.
“Sadece bir adım atarsam her sey degisecek.”
Ama bazı adımlar vardır…
Insanı ileri goturmez, icine ceker.
Ve o an fark etti:
Korktugu sey iceridekiler degildi.
Korktugu, o kapının ardında hala aynı hisleri tasıyan kendisiydi.
Elini yavasca cekti kapıdan.
Esik hala oradaydı… ama o artık aynı yerde degildi.
Tam donecekti ki—
Kapı iceriden aralandı.
Ne ruzgar vardı ne de bir baskası…
Sanki yıllardır susan bir hikaye,
 kendi kendine konusmaya karar vermisti.
Aralıktan sızan o tanıdık koku…
Bir anlıgına butun kararlılıgını kırdı.
Ve iceriden bir ses—
cok tanıdık, cok derin, cok yarım:
“Bu kadar gec kalman…
gelmeyecegin anlamına gelmezdi.”
Kahramanımız dondu kaldı.
Cunku o ses…
unutmaya calıstıgı degil, hic susmayan yerden geliyordu.', 'Kapı eşiginde kaldı. Ne içeri adım atabildi ne de geldigi yere geri donebildi. Bazen insanın en uzun yolculugu,  bir eşigi gecmek kadar kısa...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/hasret-3-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret 2', 'hasret-2-adsiz-gardenya-d5ucj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapıyı açtı.
Soğuk hava yüzüne yüzüne vuruyor du ama geri adım atmadı.
Sanki o rüzgâr, 
içinde biriken her şeyi alıp götürecekti. 
Eşiği geçtiğinde bir şeyin bittiğini değil… 
bir şeyin ilk kez başladığını hissetti.
Ama garip olan şuydu…
Nereye gideceğini bilmiyordu.
hafifce adımlarını sokağa bıraktı.
Her adımda içindeki sesler biraz daha yükseldi.
Ya yanlışsa ...
diye bir korku vardı.
Ama onun hemen yanında, 
daha önce hiç bu kadar net konuşmayan başka bir ses vardı:
Ya ilk defa doğruysa diye...
Durmadı.
Çünkü bu sefer durursa, bir daha hiç yürüyemeyeceğini biliyordu.
Ve gece, onu içine alırken…
aslında ilk defa yalnız olmadığını fark etti.
ve bi an durdu
çivi gibi çakılmıştı kapı eşiğine.........', 'Kapıyı açtı. Soğuk hava yüzüne yüzüne vuruyor du ama geri adım atmadı. Sanki o rüzgâr,  içinde biriken her şeyi alıp götürecekti.  Eşiği geç...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hasret-2-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rosa’nın Vedası', 'rosa-nin-vedasi-mevlut-karakus-es8b6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sok kez bakmıştı gözlerime
Ötelerce kilometreden
Sen ötesindensin demiştim 
Yinemi anlatamadım kendimi
Sen mesafelerin ötesinde
Dokunabilmenin, sarılabilmenin
Sen canımında ötesindesin
Bakma bana öyle

Bir hastane odasında, 
Soğuk duvarlar var önümde 
Böylemi bitecektik Rosa
Yarım, eksik tamamlanmadan daha
Ayrılığın hangisi zor, söylesene
Bir telefon konuşmasında
Yada iki satır yazıyla
En zoru bir hastane odasında…
Soğuk duvarlar arasında
Çaresizliğini yaşıyorum gidişinin
Veda edemeyişimin…

Hasretine de aşinayım oysa
Peki duyduğum acı nedir Rosa
Kemiklerimi kırdın konuşsana
Yeterki bana öyle bakma
Ben bilmem sensizliği 
Öğretmediğin acıları yaşıyorum
Şimdi sen gittin, biz ayrıldıkmı
Bilmiyorum
Söylese Rosa
Yeterki öyle bakma', 'Sok kez bakmıştı gözlerime Ötelerce kilometreden Sen ötesindensin demiştim  Yinemi anlatamadım kendimi Sen mesafelerin ötesinde Dokunabilmen...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Karakuş']::text[], 8.5, '{"poet":"Mevlüt Karakuş","poet_slug":"mevlut-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/rosa-nin-vedasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hakikat Kapısında Bir Garip Ben', 'hakikat-kapisinda-bir-garip-ben-emir-ergin-koc-em18z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'HAKİKAT KAPISINDA BİR GARİP BEN

            ⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

    **Bir Emir Ergin Koç Kalemin ''den**

            ⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂

Bir sır üflendi ruhuma ezelden evvel,

Toprağa emanet edildi bu fâni beden.

Bir nefeslik ömre bin türlü dava sığdırdım da,

Kendimi ararken uzak düştüm kendimden.

Gönül denen dergâhın eşiğine yüz sürdüm,

Her kapıda başka bir imtihan gördüm.

Sandım ki hakikat uzak diyarlarda saklı,

Nice yollar tükettim de, gönlümün sırrına varamadım.

Bir ömür âlemin kapısında kendimi aradım,

Meğer kendi gönlümün eşiğinden dahi geçemedim.

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Bir vakit nefsimi sultan eyledim gönlüme,

Kendi gölgemi bile yoldaş sandım ömrüme.

Dilim zikre vardı da gönlüm gafletten uyanmadı,

Nice hakikatler söyledim, kendim nasipsiz kaldım.

Bir dervişin hırkasında aradım kemali,

Bir âşığın gözyaşında seyrettim cemali.

Meğer hırka giymekle derviş olunmazmış,

Kibirle yürüyen gönül Hakk''ın kapısına varamazmış.

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Hacı Bektaş''ın dergâhına çevirdim yüzümü,

“İncinsen de incitme” sözünde aradım özümü.

Yunus''un dilinde gönül yapmanın sırrını bildim,

Feqiyê Teyran''ın kuşlarla söyleşen aşkında hikmeti sezdim.

Nice kitaplar okudum, nice kelamlar işittim,

Bir garibin gözyaşında bütün ilmimden utandım.

Anladım ki ilmin özü, bir gönlün derdine ermektir,

Hakikate ermek ise incitmeden sevebilmektir.

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Dünya denen pazarda ömür satılırmış,

Kimi altına, kimi makama aldanırmış.

Birinin tahtı yükselirken vicdanı alçalırmış,

Bir başkasının lokması küçülür, gönlü çoğalırmış.

Gördüm ki ipekten kaftanlar örtmezmiş ayıbı,

Taç giyen her baş taşımazmış irfanı.

Bir yoksulun sofrasında öğrendim insanın değerini,

Bir lokmayı bölüşen gönülde buldum irfanın cevherini.

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Mansûr dara yürüdü, ikrarından bir an olsun dönmedi,

Nesîmî can pazarında can verdi, inandığını inkâr etmedi

Pir Sultan''ın sazında zalime başkaldırdı hakikat,

Ne ferman susturabildi onu ne de ölümün dehşeti.

Ben ise bir sözün ardında durmaya cesaret edemedim,

Sustukça kendi vicdanımın yüzüne bile bakamadım.

Anladım ki hakikati bilmek değilmiş asıl hüner,

Bedeli ne olursa olsun ikrarından dönmemekmiş meğer.

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Bir seher vakti dokundu yüzüme hikmetin yeli,

Dedi: “Ey yolcu, evvela kendi gönlünü temizle.

Kırdığın kalbin ahı varken hangi duayla huzur dilersin?

Bir yetimin gözyaşını silmeden hangi menzile erersin?

Kinini taş diye yüklenip nice baharını heba edersin,

Bağışlamayı yenilgi sanıp kendi ömrünü tüketirsin.

Unutma, ömür emanettir, dünya gelip geçici,

Secdelerde aradığın Hakk''ın rızasını, dikkat et de

İncittiğin bir gönlün ahında yitirmeyesin.”

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Ey nefsim, ne zamana dek sürecek bu kavgan?

Bir fani dünya için nedir bunca talan?

Gözün doymadı yıllarca gördüklerinle,

Gönlün huzur bulamadı elde ettiklerinle.

Sen kendini âlemden üstün gördüğün o vakit,

Bir karıncanın hakkı var üzerinde, bunu unuttun lakin.

Söyle ey nefsim, ne kaldı büyüklüğünden,

Kendi aczini bir gün olsun idrak edemedin.

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Şimdi ellerimi açtım huzuruna, ey Rabbim,

Ne erenlik dilerim ne de kullarından üstünlük.

Bana kusurumu gösterecek bir idrak ver,

Haksızlığa susmayacak kadar cesaret,

Haklıyken incitmeyecek kadar merhamet ver.

Dilimle söylediğimi hâlimle inkâr ettirme,

Beni başkalarının günahıyla oyalama,

Kendi noksanımı görecek basiret ver.

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Bir gün sorarlarsa bu uzun seferden ne getirdin diye,

Ne tacım var ne tahtım, ne de övünecek bir makamım.

Biraz pişmanlık, biraz sabır, biraz da umutlarım,

Bir de incittiğim gönüllerin omzumda kalan vebali.

Hepsi bu kadar benim dünyalık azıklarım.

Ben aşkı dillerde aradım, edepte buldum,

İrfanı kitaplarda aradım, merhamette gördüm.

Hakk''a varmak için nice yollar aştım,

Meğer en uzun yol, insanın kendi nefsinden geçermiş.

Şimdi bildim ey gönül,

İrfan, âleme hükmetmek değil, haddini bilmekmiş.

Bir ömür Hakk''a giden yolu aradım,

Kapısına vardığımda anladım ki...

**Meğer Hakk''a varmak için önce kendinden geçmek gerekirmiş.**.

⁂⁂⁂⁂⁂⁂⁂⁂⁂

Söz: Emir Ergin Koç', 'HAKİKAT KAPISINDA BİR GARİP BEN             ⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂     **Bir Emir Ergin Koç Kalemin ''den**             ⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂⁂ Bir sır üflendi ruhu...', ARRAY['Türk Edebiyatı','Şiir','Emir Ergin Koç']::text[], 8.5, '{"poet":"Emir Ergin Koç","poet_slug":"emir-ergin-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/hakikat-kapisinda-bir-garip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimden Öte', 'kendimden-ote-ekrem-olgun-v7fb3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SENİ SEVMEK, KENDİMDEN ÖTE

Seni sevmek, bir kalbe sığdırmak değilmiş seni,
Bir damlada saklamakmış uçsuz bucaksız denizi.
Ben senden önce de yaşadım sanırdım,
Meğer ömür dediğim, beklemekmiş seni.

Sen geldin…
Zaman, asırlardır taşıdığı yükü bıraktı.
Karanlık, kendi gölgesinden utanıp kaçtı.
Ve ben ilk defa anladım;
Bazı insanlar dünyaya doğmaz,
Bir başkasının ruhunda sabah olmak için yaratılır.

Gözlerin…
Bir şairin ömrünce arayıp bulamadığı mısra,
Bir dervişin susarak vardığı en derin mana.
Ben o gözlerde kendimi kaybetmedim sevgilim,
İnsan bazen bir çift bakışta
Ömrünce aradığı kendine rastlarmış meğer.

Sesin, ruhumun unutulmuş bir lisanı,
Gülüşün, kederimin en zarif isyanı.
Sen konuşunca kelimeler değil,
İçimde yıllardır susan bir çocuk uyanır.
Ve dünya, bütün gürültüsüne rağmen
Bir tek senin sesinde anlam kazanır.

Sana güzel demek eksik kalır, bilirim,
Güzellik, zamanın insana verdiği bir emanettir.
Oysa sende sevdiğim şey,
Yılların eksiltemeyeceği bir hakikattir.
Çünkü yüzünü zaman değiştirse de
Ruhunun dokunduğu yerde
Benim için bütün mevsimler bahardır.

Ben seni bir çiçeğin ömrü kadar sevmedim,
Solacağını bile bile kokuna yenilmedim.
Seni toprağın yağmura duyduğu sabırla,
Gecenin sabaha beslediği inatla sevdim.
Ve anladım ki gerçek sevda,
Bir insanı kendine ait kılmak değil,
Onun hürriyetinde bile kendine bir vatan bulmaktır.

Bilirsin, her aşkın içinde biraz korku vardır,
Kaybetmek, sevmenin en sessiz imtihanıdır.
Ama ben seni kaybetmekten önce,
Seni hak ettiğin gibi sevememekten korkarım.
Çünkü bazı kalpler kırıldığında onarılır,
Bazı kalpler kırıldığında
İnsanın kendi vicdanı da parçalanır.

Bir gün ellerin titrerse yılların ağırlığından,
Güzelliğin çekilirse gençliğin aynalarından,
Ben yine aynı hayranlıkla bakacağım sana.
Çünkü ben senin yüzüne değil,
O yüzün ardında sakladığın sonsuzluğa tutuldum.
Ve bil ki sevgilim,
İnsan teniyle yaşlanır,
Ruhuyla sevdiğinde zamana meydan okur.

Sana bir sonsuzluk vadetmeyeceğim,
Çünkü insan ölümlüdür, sözleri de öyle.
Ama sana bir ömür verebilirim,
Her sabah yeniden seçilmiş,
Her gece yeniden hak edilmiş bir ömür.
Zira aşk, bir kez söylenen büyük bir yemin değil,
Bin kez sınanıp yine de bozulmayan bir sözdür.

Ve bir gün sorarsan bana:
“Bunca insan arasında neden ben?” diye,
Sana ne yıldızlardan söz ederim
Ne de kaderin gizemli cilvesinden.
Yalnızca gözlerine bakar, şöyle derim:

Ben seni, sensiz yaşayamayacağım için sevmedim.
Sensiz de yaşardım elbet,
Bir nehir denize varmadan da akabilir.
Ama ben, seninle anladım;
Akmak başka şeymiş sevgilim,
Bir denize kavuşup kendini tamamlamak başka.

Ve eğer bir gün bu dünyadan önce ben gidersem,
Ardımdan yarım kaldı deme sakın.
Çünkü ben, bir insanın bir ömürde yaşayabileceği
En büyük mucizeyi yaşadım:
Senin var olduğun bir dünyada,
Seni sevebilen bir kalbe sahip oldum.

EkOL', 'SENİ SEVMEK, KENDİMDEN ÖTE Seni sevmek, bir kalbe sığdırmak değilmiş seni, Bir damlada saklamakmış uçsuz bucaksız denizi. Ben senden önce de...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Olgun']::text[], 8.5, '{"poet":"Ekrem Olgun","poet_slug":"ekrem-olgun","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/kendimden-ote-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Seviyorum Seni', 'sessiz-seviyorum-seni-adsiz-gardenya-k95yv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sessiz seviyorum seni...
Güneşin doğması,
bulutların dağılması gibi sessiz seviyorum seni. 
Çiçeğin açması, 
yağmurun dinmesi, 
karın erimesi gibi sessiz seviyorum seni.
Azrail''in can alması, 
umutların yıkılması gibi sessiz seviyorum seni. 
Yaprağın dalından düşmesi, 
bebeğin ilk kez ağlaması, 
gözyaşının yanağa süzülmesi gibi sessiz seviyorum seni.
Kanın damarlarda dolaşması, 
kalbin bedene can vermesi, 
cananın cana ihaneti gibi sessiz seviyorum seni.
Şimdi söyle... 
Seviyorum diye haykırayım mı sana, 
yoksa bir ömür kimselere duyurmadan sessiz mi seveyim seni?
@dsız.. gardeny@', 'Sessiz seviyorum seni... Güneşin doğması, bulutların dağılması gibi sessiz seviyorum seni.  Çiçeğin açması,  yağmurun dinmesi,  karın erimes...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sessiz-seviyorum-seni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EylüL', 'eylul-adsiz-gardenya-tteu5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ah be eylül... 
ne kadar çok benziyorsun bana ve ben yine sana bakıp susuyorum...

sen yapraklarını döküyorsun, 
ben içimde kimseye gösteremediğim 
ÖMRÜMÜ...

Ah be Eylül… 
Ben de her dökülen yaprağında kendimden bir parça buluyorum.
Sen mevsimini yaşarken ben içimde çoktan sonbahara dönmüşüm.
Belki de bu yüzden sana bakınca kendimi görüyorum.
Çünkü ben de sustukça çoğalttım içimdeki özlemi, 
kimseye anlatamadığım ne varsa kalbime gömdüm.
Sen yapraklarını döküyorsun, 
ben hâlâ içimde solmayan birini taşıyorum… 🍂

Ah be Eylül… 
Sen yapraklarını döküyorsun,
 ben içimde biriktirdiğim acıları…
Senin sonbaharın geçer belki, 
ama benim içimde bazı mevsimler hiç bitmiyor.
Çünkü insan en çok da kimseye anlatamadığı yerinden kırılıyor. 
Ben de sustum Eylül…
Bir tek kalbim susmadı; 
o hâlâ kimsenin duymadığı bir özlemin adını söylüyor… 🍂

ah be eylül...
ne senin yaprak dökümün biter
ne de benim derdim
sen her sonbahar biraz daha sararırsın
ben her sabah biraz daha içime gömülürüm
sen dallarından ayrılan yapraklara ağlarsın
ben hiç yaşanmamış baharlarımın ardından
hangi toprağa düşeceğimi bile bilmeden savrulurum
senin mevsimin değişir eylül....
senin mevsimin değişir
benim içimde mevsimler yas tutar...
@dsız.. Gardeny@', 'ah be eylül...  ne kadar çok benziyorsun bana ve ben yine sana bakıp susuyorum... sen yapraklarını döküyorsun,  ben içimde kimseye göstereme...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/eylul-904-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bana Bizi Borçlusun Yar', 'sen-bana-bizi-borclusun-yar-adsiz-gardenya-q6dfa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen bana bizi borçlusun yar...
benim içimde kurduğum o dünyayı, 
kimselere anlatmadığım hayallerimi,
 adını anarak ettiğim duaları borçlusun.
ben seni öyle gelip geçici bir hevesle sevmedim.
gönlümün kapısını herkese kapatıp sana açtım. 
bir ömrü sığdırdım adına, 
kendime bile anlatamadığım nice güzel düşü seninle yaşadım.
sen bilmezsin, 
ben kaç gece seninle konuşup sabaha sensiz çıktım. 
kaç defa içimde sana sarıldım da ellerim boş kaldı. 
kaç kez bir mutluluğun kıyısına kadar geldim de sen yanımda olmadığın için geri döndüm.
sen bana bizi borçlusun...
benim hiç yaşayamadığım o güzel sabahları, 
gözlerinin içine bakarak söyleyemediğim seni seviyorumları, 
omzunda dinlendiremediğim yorgunluğumu borçlusun.
ben senden bir dünya istemedim ki yar, 
bir dünyanın içinde seninle yaşayacak küçücük bir yer istedim.
şimdi içimde sana ait bir ömür duruyor. 
ne kapısını kapatabiliyorum ne de içeri girebiliyorum.
ve en çok da buna yanıyorum...
ben seni kaybettiğim için değil, 
seninle yaşayacağım ömrü hiç yaşayamadığım için kederliyim.
sen bana bizi borçlusun yar...
ben bu sevdaya bir kalp değil, 
bir ömür koydum. 
hesabını senden sormaya dilim varmıyor ama içimdeki o yarım ömür de senden başkasına ait değil.
@dsız..', 'sen bana bizi borçlusun yar... benim içimde kurduğum o dünyayı,  kimselere anlatmadığım hayallerimi,  adını anarak ettiğim duaları borçlusun...', ARRAY['Türk Edebiyatı','Şiir','Adsız Gardenya']::text[], 8.5, '{"poet":"Adsız Gardenya","poet_slug":"adsiz-gardenya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sen-bana-bizi-borclusun-yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Anlattım', 'seni-anlattim-adsiz-gardenya-5pi88', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bugün hiç yüz vermedim güneşe,
