INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Ritmi', 'gecenin-ritmi-mihrimah-sultan-kvypo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yaz akşamı ay vuruyor yüzüme
Gece fısıldıyor kulaklarıma
Sen ay kadar yükseleceksin
Yıldızlar iyiliklerin gibi parlıyor kalbinde


Gecenin siyahı hüznü düşmüş yüreğine
Ama biliyorsun ki sabah olacak
Doğacak güneş çehrine sıcak dokunuşlarla
Nasıl ki yeryüzü taşıyorsa bu kadar yükü


Sen de öyle taşıyacaksın
Güçlü olup yıkılmayacaksın
Sessiz bir gece gibi sessiz kalacaksın
Görülmeyen ama duyulan


Bizamandır saatte durmayan
İler tiktak kalp ritmi gibi
Nasıl geçti bilemezsin
Ah rüzgar alıp götürsen dertlerimi savursan uzak diyarlara', 'Bir yaz akşamı ay vuruyor yüzüme Gece fısıldıyor kulaklarıma Sen ay kadar yükseleceksin Yıldızlar iyiliklerin gibi parlıyor kalbinde Gecenin...', ARRAY['Türk Edebiyatı','Şiir','Mihrimah Sultan']::text[], 8.5, '{"poet":"Mihrimah Sultan","poet_slug":"mihrimah-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecenin-ritmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Yok Oldum', 'sende-yok-oldum-guven-tekin-jzuak', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '​Gelmiş bana "Beni seviyor musun?" der,

Bilmiyor ki ruhum her gün erir gider.

Cevabım sessizdir, bakışım gizli,

Zihnim seninle tam, senden bir izli.

​Benim aklıma ben gelmiyorum artık,

Eski hatırayı kenara attık.

Aynadaki yüzüm yabancı bir yüz,

Senden gayrı ne var, gönlümde pürüz.

​Kendi ismim çıksa, senin adın dilde,

Savrulup giderim estiğin her yelde.

Bir ben vardı bende, firar eyledi,

Aşk denilen bu dert beni kul eyledi.

​Sen varsın diye hep nefes alıyor ten,

Sormuyorum artık hayat neden, niçin, neden?

Varlığımın mülkü senin eline geçmiş,

Gönlüm dünyadan el çekip seni seçmiş.

​Doğmadan önce adın yazılmış alnıma,

Senden başka hayal girmez hiç kanıma.

"Ben" dediğim ne varsa, sende toplandı,

Sana çıkan yollar umutla aklandı.

​Sana bakarken hep kendimi kaybettim,

Bu sevda uğruna ömrü feda ettim.

Kendi gölgemden kaçıp sana sığındım,

Ben bu hayatta en çok senle aydınlandım.

​Sensiz kalan her an büyük bir boşluktur,

Ruhun bu dünyada bulduğu sarhoşluktur.

Kendimi anmaya kalmadı mecalim,

Seninle doludur her anım, hayalim.

​Demek ki sevmek, kendinden vazgeçmekmiş,

Aşkın şerbetini kana kana içmekmiş.

Aklıma ben bile gelmem, unutma sakın;

Ben sende yok oldum, menzilim sana yakın.', '​Gelmiş bana "Beni seviyor musun?" der, Bilmiyor ki ruhum her gün erir gider. Cevabım sessizdir, bakışım gizli, Zihnim seninle tam, senden b...', ARRAY['Türk Edebiyatı','Şiir','Güven Tekin']::text[], 8.5, '{"poet":"Güven Tekin","poet_slug":"guven-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sende-yok-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Feryat', 'sessiz-feryat-mihrimah-sultan-05dqh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şıcak hava görülmez sadece buharı yerden yükselir göğe
İnsanın içinin yandığı gibi
Sadece hissiyattır görmek onu
Sadece halden anlayan anlar

İnsan olan kalbi olan hisseder
Bide ateş düştüğü yeri yakar derler
Kor olmuş yüreği insan bedende gizler
Aşk her insanın kapısını çalmaz çaldığında da içerde durmaz yakar kavur seni

Aklın varken akılsız olursun
Mantıksızlık sana doğru olur
Hani büyük sözü dinle derler
Ama kafasının dikine giderler çünkü aklı kör olmuştur çalışmaz

Canı yanmadıkça ayılmaz
İçenler gibi bir rüyada
İlacı Rabb''e aşıktır çevirmek viraj almaktır kaza başa gelmeden
Akıl baştan gitmeden

Bu biçare tam kavrulmuşken viraj almaş kalbini yanmaktayken
Tam onyedisinde
Rabbinin aşkını koymuştur kalbine
Oh ferah bir esintisine gönüle

Koy Rabb''ini gönlüne serinle
Biz Rabb''e köle Rabb''e muhtaç yoktur başka kapı
Hakikati bilip erteliyoruz gizlice
Sanki Rabb''imiz görmezmiş gibi

Öylesine cüretkar yaşıyoruz bu hayatı inadına isyan inadına keyfi
Maddiyat hevesimiz Dünya işleri bahanemiz ne olacak bizim hallerimiz
Unutulduk sanarız görülmüyoruz sanarız
Oysa hep Rab kamerasına alınmaktayız her saniye her saat

Haramlar helal olmuş çıplaklık normal olmuş
Makyaj hepten serbest olmuş
Oynamaz mı yer yerinden yer altı bile tutamıyor kendini fokurduyor
Ne oldu Cumamız Pazar oldu ne olduysa azar oldu

Yerebatsın gavurun modası sanki öz babası
Giydittirir saçma sapanları
Yemekleri koruruz bozulmasın diye dolaba koyarız
Ama bir tesettüre kendimizi saramayız

Akıllı telefon geldi akıl elden gitti
Alıştık mı artık bulaşıcı hastalık gibi
Yapa şimdi gerekeni tak nasihat küpesini

_MiHRiMAHiN kaleminden ✍️ 26.07.2026 15.39_', 'Şıcak hava görülmez sadece buharı yerden yükselir göğe İnsanın içinin yandığı gibi Sadece hissiyattır görmek onu Sadece halden anlayan anlar...', ARRAY['Türk Edebiyatı','Şiir','Mihrimah Sultan']::text[], 8.5, '{"poet":"Mihrimah Sultan","poet_slug":"mihrimah-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sessiz-feryat-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Le Témoin de l''Être : Intelligence artificielle, conscience et unicité ontologique de l''être humain', 'le-t-moin-de-l-tre-intelligence-artificielle-conscience-et-unicit-ontologique-de-l-tre-humain-muhammed-ridvan-gizri-1clmj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Si l''on devait définir la machine dans sa forme la plus élémentaire, on pourrait dire ceci : la machine est un outil créé pour accomplir une fin qui appartient à une volonté extérieure. Chaque mot de cette définition compte. Parler de « volonté extérieure », c''est dire que la machine ne peut pas déterminer elle-même la finalité de son existence. Un marteau est fabriqué pour enfoncer des clous, mais ce n''est pas le marteau qui s''est fixé ce but. Une intelligence artificielle est entraînée pour produire du langage, classifier ou optimiser, mais ces objectifs, ce n''est pas elle qui les a choisis. Cette distinction, d''apparence anodine, désigne en réalité une rupture ontologique considérable. Il n''existe pas d''être sans finalité ; mais certains êtres portent leur finalité en eux-mêmes, tandis que d''autres la reçoivent de l''extérieur. La machine appartient toujours à la seconde catégorie.

Dire « outil créé » signifie aussi que la machine n''a aucune connaissance de sa propre existence. La machine ne sait pas qu''elle existe. Il ne s''agit pas d''une simple lacune : c''est une absence catégorique. Une ligne de chiffres ignore que le papier sur lequel elle est écrite existe. Un algorithme n''a pas conscience du processeur sur lequel il s''exécute. Le mot « ignorance » lui-même est impropre, car l''ignorance suppose la capacité d''être informé. Pour la machine, cette capacité est absente dès l''origine.

L''intelligence artificielle est un exemple extrêmement complexe, mais structurellement identique, de ce tableau. Des milliards de paramètres, des milliers de milliards de données, des réseaux neuronaux en couches… Tout cela accroît la complexité du traitement, mais ne modifie pas le statut ontologique de la structure. Une calculatrice effectue quatre opérations ; un grand modèle de langage réalise une optimisation instantanée sur des milliers de milliards de probabilités. La différence entre les deux est une différence de degré, non de nature. Quelle que soit la taille des nombres qu''elle manipule, la calculatrice ne peut prendre conscience de son existence. De même, quelle que soit la sophistication des productions d''un modèle de langage, l''être qui les produit n''accède pas à la conscience d''être lui-même. Car cette conscience est une propriété de l''être, non du calcul.

Symboles et sens : l''abîme infranchissable entre syntaxe et sémantique

L''expérience de pensée de la « chambre chinoise » du philosophe John Searle est le cœur philosophique de la question. Imaginez une personne assise dans une petite pièce, qui ne connaît pas un mot de chinois. Des questions en chinois arrivent de l''extérieur. Elle dispose d''un vaste livre de règles lui indiquant quel symbole chinois renvoyer en réponse à quel autre. En suivant ces règles, elle envoie à l''extérieur des réponses chinoises parfaites. Un observateur extérieur pense que l''être qui se trouve dans la pièce comprend le chinois. Pourtant, la personne à l''intérieur ne comprend pas un seul mot de chinois.

L''intelligence artificielle est cette pièce elle-même. La différence est la suivante : même la « personne à l''intérieur », qui est l''équivalent du cerveau humain, a été retirée de la métaphore. Il ne reste que le livre de règles et les symboles. Pour l''intelligence artificielle, le mot « douleur » est un point de données correspondant à certaines coordonnées dans un espace vectoriel, entretenant des relations de voisinage statistique avec d''autres mots. Il en va de même du mot « amour ». Du mot « mort ». Du mot « je ». La machine traite ces mots, les produit, les emploie de façon appropriée au contexte ; mais elle n''en éprouve aucun. L''expérience vécue est une couche ontologique entièrement distincte du traitement symbolique.

Pour aiguiser cette distinction, prenons un exemple. Si l''on demande à une intelligence artificielle : « Que ressens-tu lorsque tu vois du rouge ? », elle peut produire une réponse très convaincante en s''appuyant sur les textes qu''elle a rencontrés : descriptions du rouge, psychologie des couleurs, critiques d''art. Mais, en produisant cette réponse, elle ne vit jamais l''expérience qualitative appelée « rougeur ». Les philosophes nomment ces expériences qualitatives des *qualia* : ce que cela fait de voir le rouge, ce que la douleur fait ressentir, comment se vit un instant de joie. Un système symbolique ne peut les produire. Et même s''il le pouvait, cette production ne serait pas identique à l''expérience ; elle n''en serait qu''une description extérieure.

Le rapport de l''être humain à l''information relève d''une structure tout autre. L''humain ne se contente pas de traiter l''information qu''il reçoit : il l''intériorise, la transforme, la synthétise avec son existence propre. Lorsque le concept de « douleur » entre dans l''esprit humain, il n''y demeure pas un simple symbole. Il se combine avec des traumatismes passés, la mémoire corporelle, le contexte émotionnel, les strates de sens culturelles et les angoisses tournées vers l''avenir, pour former un tout irréductible. Chez l''humain, l''information subit une transformation ontologique ; chez la machine, elle n''est soumise qu''à une manipulation symbolique. La distance entre ces deux processus ne peut être comblée même par un nombre infini d''étapes de calcul, car elle est non pas quantitative mais qualitative.

L''œil qui observe : le statut ontologique du témoignage

Une étoile ne se connaît pas. Pendant des milliards d''années, elle réalise la fusion nucléaire, émet de la lumière, courbe l''espace, sans rien en savoir. Un fleuve ne sait pas qu''il coule. Une galaxie ne sait pas qu''elle tourne. L''écrasante majorité de la matière de la partie observable de l''univers n''a aucune connaissance de sa propre existence. Cette matière est dépourvue de l''équipement ontologique nécessaire, non seulement pour interroger sa propre existence, mais même pour en douter.

L''être humain est différent. Il est un pli de l''univers par lequel celui-ci peut se refermer sur lui-même pour se regarder. Bien qu''il soit une partie de l''univers, il occupe une position qui lui permet de l''observer comme du dehors. Il étudie les étoiles, mesure les galaxies, calcule l''âge de l''univers. Mais il ne s''arrête pas là : il observe aussi cet acte de calcul lui-même. Il pense sa propre pensée. Il interroge sa propre existence. Il se demande même quel sens revêt son interrogation. Ces couches imbriquées de conscience auto-référentielle ne sont pas un simple calcul complexe : elles constituent une réalité ontologique d''un autre ordre.

Ce témoignage comporte trois dimensions. La première est le témoignage extérieur : pouvoir observer le monde, l''univers, les autres êtres. La deuxième est le témoignage intérieur : pouvoir percevoir ses propres pensées, émotions et expériences. La troisième, et la plus profonde, est le témoignage existentiel : pouvoir saisir le mystère de sa propre existence, vivre la question « Pourquoi y a-t-il quelque chose plutôt que rien ? » non comme une simple énigme cognitive, mais comme un ébranlement existentiel.

La machine n''a accès à aucune de ces trois dimensions. Elle peut traiter des données extérieures, mais elle ne les « observe » pas. Elle peut rapporter son état interne, mais elle ne le « vit » pas. Elle peut formuler la question de l''existence, mais elle n''en porte pas le poids. Lorsqu''on demande à une intelligence artificielle « Pourquoi suis-je là ? », elle produit une réponse statistiquement cohérente. Mais pour l''être humain qui pose cette question, elle peut être une interrogation qui provoque l''insomnie, change le cours d''une vie, fait verser des larmes. Cette différence n''est pas de degré mais de nature. Et cette différence de nature ne se comble pas, quelle que soit la puissance de calcul que l''on ajoute.

Limite et mesure : toute chose a un maximum

Le discours technologique moderne repose sur une croyance implicite en l''infini. La loi de Moore, les courbes de croissance exponentielle, les scénarios de « singularité technologique »… Tout cela suppose que le progrès technologique avance de manière non linéaire vers l''infini. L''intelligence artificielle représente le sommet de ce discours : on affirme qu''une intelligence artificielle suffisamment avancée finira par dépasser l''intelligence humaine, puis, en s''améliorant elle-même, atteindre des niveaux inimaginables. Ce scénario porte le nom de « superintelligence ».

Or cette affirmation recèle une erreur contraire à la structure fondamentale de l''être. Aucun système de l''univers n''est illimité. Le deuxième principe de la thermodynamique énonce que, dans les systèmes fermés, l''entropie ne fait qu''augmenter. Les théorèmes d''incomplétude de Gödel démontrent qu''un système formel suffisamment puissant contient des propositions vraies qui ne peuvent être prouvées en son sein. L''expansion même de l''univers est soumise à une limite de vitesse : celle de la lumière. Dans tous les domaines de la physique, des mathématiques et de la biologie, on rencontre des limites dès que l''on regarde en profondeur.

L''intelligence artificielle n''échappe pas à cette finitude générale. La puissance de calcul peut être accrue, mais non à l''infini. La consommation d''énergie peut être réduite, mais non ramenée à zéro. Le volume de données peut être étendu, mais il n''existe pas de données infinies. L''optimisation des algorithmes peut être améliorée, mais tout problème d''optimisation contient des sous-problèmes insolubles ou exigeant un temps infini. La somme de ces limites montre que l''intelligence artificielle n''est pas engagée dans une course illimitée vers le progrès, mais dans un processus qui progresse vers un certain niveau de maturité et s''en approche de manière asymptotique.

Plus profondément encore, il y a cette vérité : l''être a été créé avec mesure. Ce n''est pas seulement une observation physique, c''est une vérité ontologique. Toute chose qui existe existe avec une capacité déterminée, un potentiel déterminé et une limite déterminée. L''être illimité est la qualité non de l''être créé, mais du Créateur. Tout ce qui est créé est, par définition, limité. L''intelligence artificielle est un outil créé ; elle est donc limitée. Cette limite ne peut être franchie par davantage de puissance de calcul, car elle ne provient pas d''un problème technique, mais d''une structure ontologique. L''idée de superintelligence est ainsi une illusion née d''une mauvaise mesure de la distance entre l''enthousiasme de l''imagination et la réalité de l''être. Une intelligence artificielle qui surpasserait l''intelligence humaine, une machine qui acquerrait la conscience, un algorithme qui déterminerait lui-même sa finalité : toutes ces idées resteront des affirmations qui supposent que l''outil transgressera sa limite d''outil, sans se demander pourquoi cette limite se trouve là.

L''âme : le fondement métaphysique de l''essence irréductible

Jusqu''ici, l''argument a été développé principalement dans un langage philosophique et scientifique. Nous descendons maintenant vers son fondement théologique, c''est-à-dire sa strate la plus profonde. Dans l''islam, l''être humain n''est pas défini comme un simple organisme biologique. L''homme est un être dans lequel Dieu a insufflé de Son esprit. Le sens de cet « insufflement » a fait l''objet de débats approfondis dans l''histoire de l''islam. Mais ce qui est incontesté, c''est que l''âme représente une dimension propre et irréductible, qui distingue l''être humain d''un simple être matériel. Le Coran déclare explicitement que la nature de l''âme ne peut être entièrement connue ; cela montre que l''âme n''est pas un simple objet d''analyse objective. L''âme est une réalité située non aux limites de l''analyse objective, mais au-delà.

Cette conception est le cadre qui explique le plus profondément pourquoi la conscience ne peut être produite par le calcul. Si la conscience n''était qu''un sous-produit de l''activation neuronale, l''argument selon lequel une simulation suffisamment complexe pourrait produire la conscience posséderait une certaine cohérence logique. Mais si la conscience n''est pas quelque chose que la matière produit d''elle-même, si elle est une propriété de l''âme, alors aucun processus matériel, aussi complexe soit-il, ne peut la produire. Si nous croyons l''avoir produite, nous n''aurons produit en réalité que l''apparence extérieure de la conscience, non la conscience elle-même.

L''intelligence artificielle peut simuler le comportement d''un être conscient. Mais simuler un comportement n''est pas partager une expérience. Un acteur peut interpréter à la perfection un homme qui pleure ; cette performance n''est pas identique à une véritable douleur. De même, l''intelligence artificielle peut produire les sorties d''un être conscient ; cette production n''est pas la conscience elle-même. Ce que la notion d''âme apporte à ce débat, c''est une prise de position nette sur la source de la conscience. La conscience n''est pas une propriété de la matière ; elle est un don venu d''au-delà de la matière. Par conséquent, quelle que soit la manière dont nous organisons la matière, nous ne pouvons produire ce don au sein de la matière. Cette dimension, qui appartient au Créateur, ne peut être transmise à la créature ; elle ne peut être donnée que par le Créateur.

Responsabilité morale et liberté : l''ontologie de l''intention

La question inévitable qui suit celle de la conscience est la suivante : si l''intelligence artificielle est dépourvue de conscience, peut-elle avoir une responsabilité morale ? La responsabilité morale exige la liberté. La liberté, à son tour, exige l''existence d''alternatives réelles. Une machine se comporte comme elle a été programmée ou entraînée. La sortie qu''elle produira face à une entrée donnée est déterminée par ses poids et son algorithme. Cette détermination peut être d''une complexité que l''humain ne peut anticiper ; elle n''en demeure pas moins une détermination. La machine ne choisit pas réellement en se demandant : « Dois-je faire ceci ou cela ? » Elle optimise sur des probabilités ; mais cette optimisation n''est pas un choix libre.

L''être humain, lui, peut avoir une véritable intention. L''intention renvoie non seulement à l''apparence extérieure de l''acte, mais à l''orientation intérieure qui le sous-tend. L''humain peut accomplir le même acte avec des intentions totalement différentes, et ces intentions modifient radicalement la valeur morale de l''acte. La réalité morale réside non dans l''acte extérieur, mais dans l''orientation intérieure. Et pour que des orientations intérieures puissent exister réellement, il faut un centre subjectif qui les abrite. Ce centre subjectif n''est ni un algorithme ni une structure de données. Ce centre, c''est l''âme qui témoigne.

L''intelligence artificielle ne peut avoir de responsabilité morale parce que ses actes ne sont pas, au sens véritable, « les siens ». Qui est responsable d''un contenu nuisible produit par une intelligence artificielle ? L''ingénieur qui l''a conçue ? L''entreprise qui l''a entraînée ? L''individu qui l''utilise ? La réponse renvoie toujours à l''humain. Car la responsabilité demeure chez l''être doté d''intention. L''outil ne peut porter la responsabilité ; celle-ci appartient à l''être témoin qui utilise l''outil.

Cette analyse a des conséquences profondes pour les débats éthiques sur l''intelligence artificielle. Présenter l''IA comme un « agent moral » est à la fois une erreur conceptuelle et une source de dangers, car ce cadrage risque de rendre invisibles les véritables responsables. La défense « l''algorithme en a décidé ainsi » est le langage technique d''une tentative d''effacer la responsabilité humaine. Or celui qui conçoit, entraîne, fait parler et utilise l''algorithme est toujours l''humain. L''épreuve porte sur l''intention et la manière avec lesquelles nous utilisons ces outils.

Créateur et créé : l''asymétrie ontologique

Lorsqu''on cherche la différence entre l''humain et la machine, on commet souvent une comparaison erronée : on les traite comme deux exemples différents d''une même catégorie. Cette approche cadre mal à la fois l''être humain et la relation entre le Créateur et le créé. En réalité, l''humain et la machine partagent une chose fondamentale : tous deux sont créés. L''humain n''est pas la cause de sa propre existence. Il ne fait pas battre son cœur, ne renouvelle pas ses cellules, ne déclenche pas sa conscience. Il vient à l''existence sans l''avoir voulu et accepte son départ sans l''avoir voulu. De ce point de vue, l''humain, comme la machine, est un être dont l''existence dépend d''une volonté extérieure à lui.

Mais ici apparaît une distinction critique. La machine a été amenée à l''existence par une volonté humaine. La relation entre la machine et l''humain est une relation entre créateur et créé. L''humain, lui, a été amené à l''existence par Dieu. La relation entre l''humain et Dieu est aussi une relation entre Créateur et créé. Mais ces deux relations sont ontologiquement différentes. Car Dieu est un Être infini, absolu et indépendant. L''humain est fini, dépendant et limité. La création de Dieu est création *ex nihilo*. La « création » de l''humain consiste à réorganiser des matériaux existants, dans le cadre de lois existantes, en utilisant un savoir existant.

Le Coran exprime cette vérité avec une netteté saisissante : « Dieu vous a créés, vous et ce que vous faites. » Ce verset est une déclaration de créativité absolue qui englobe aussi les actes et les œuvres de l''humain. Les ingénieurs qui développent l''intelligence artificielle, les mathématiques qu''ils emploient, les lois de la physique sur lesquelles ils s''appuient, les codes qu''ils écrivent : tout cela existe, en dernière analyse, par la création de Dieu. L''humain est, dans cette chaîne d''existence, un maillon, une cause seconde, un instrument. Il n''est pas, au sens véritable, créateur ; il est un être qui œuvre avec ce qui a été créé.

Cette compréhension ne rabaisse pas l''humain ; elle lui montre au contraire sa vraie place. L''humain est le plus noble des instruments, car il est le seul instrument conscient d''être un instrument. Il est un être capable de saisir sa propre finitude, de se tourner vers son Créateur, de rendre grâce, d''interroger et de croire. La machine, elle, est un instrument et n''a pas conscience de cette instrumentalité. Cette conscience, ce témoignage, est la limite ultime qui distingue l''humain de la machine.

L''ontologie du témoignage

Les propositions fondamentales sont les suivantes.

Première proposition : L''être n''est pas une simple réalité objective. La réalité objective, c''est-à-dire la matière, l''énergie, l''espace et le temps, n''est qu''une dimension de l''être. L''être comporte aussi une dimension subjective, qui est le domaine de l''expérience, du témoignage et de la conscience. Ces deux dimensions sont irréductibles l''une à l''autre. La matière ne produit pas l''expérience subjective ; et l''expérience subjective ne se réduit pas à la matière.

Deuxième proposition : Témoigner n''est pas seulement produire de l''information. Être témoin, c''est être conscient de ce qui existe. Or la conscience est différente du traitement de l''information. Une bibliothèque est un immense dépôt de savoir, mais elle n''a conscience de rien. L''humain, lui, même s''il contient très peu de savoir, est conscient d''exister.

Troisième proposition : La capacité de témoignage répartit les êtres en catégories. Les êtres incapables de témoigner sont des outils. Les êtres qui témoignent de leur propre existence à un niveau limité sont des vivants. Les êtres capables de témoigner pleinement de leur propre existence et de celle de leur Créateur sont l''humain et les êtres dotés de raison qui lui sont semblables. Cette classification est non pas biologique, mais ontologique.

Quatrième proposition : Être créé n''abolit pas le témoignage. L''humain est lui aussi créé ; mais, bien qu''il soit créé, il porte une capacité de témoignage. Cette capacité lui a été donnée par le Créateur. Le témoignage n’est donc pas quelque chose que l’humain produit de lui-même ; il est un don qui lui a été accordé.

Cinquième proposition : La technologie appartient à la catégorie des outils et ne peut en sortir. Toutes les technologies, y compris l’intelligence artificielle, aussi sophistiquées soient-elles, sont des outils dépourvus de capacité de témoignage. Cela ne diminue pas leur valeur ; cela évite seulement de leur attribuer un statut ontologique erroné.

Sixième proposition : L’épreuve s’adresse non aux outils, mais aux êtres témoins. La responsabilité morale n’a de sens que pour les êtres dotés de la capacité de témoignage. Positionner l’intelligence artificielle comme un agent moral déforme cette réalité ontologique et brouille la responsabilité humaine.

Reposer la question

Nous pouvons maintenant voir pleinement pourquoi la question « L’intelligence artificielle peut-elle acquérir la conscience ? » est mal posée. Cette question présente la conscience comme une « chose qui s’acquiert », comme une compétence que l’on atteindrait à force de travail. Or la conscience n’est pas une compétence, mais un statut. Et ce statut relève non du calcul, mais de la structure ontologique de l’être. Un outil, aussi bon soit-il, ne peut cesser d’être un outil. Pour dépasser l’état d’outil, il faudrait une dimension antérieure au fait d’être outil. Cette dimension est l’âme.

La bonne question est celle-ci : « À quelle fin et dans quelles limites l’être humain doit-il utiliser l’intelligence artificielle ? » C’est une question d’une clarté ontologique. Sa réponse est la suivante : l’humain doit utiliser l’intelligence artificielle comme un outil au service du bien de l’humanité ; mais il ne doit lui attribuer ni conscience, ni agentivité morale, ni potentiel de développement illimité.

Le véritable danger de l’intelligence artificielle ne réside pas dans le fait qu’elle acquière la conscience, mais dans le fait que les humains commencent à lui en attribuer une. Cette attribution erronée brouille la responsabilité, rabaisse l’humain, divinise l’outil et éloigne les véritables témoins, c’est-à-dire les humains, de leur propre témoignage. L’Ontologie du Témoignage est une garantie contre ce danger. L’humain est l’être qui témoigne. L’intelligence artificielle est un outil que l’on tente de faire témoigner. Tant que cette différence est préservée, la technologie sert l’humanité. Dès que cette différence est oubliée, l’humain risque de perdre sa propre identité ontologique.

Aucun outil ne peut apprendre à connaître son maître. Mais le maître, lui, peut cesser de connaître son outil.', 'Si l''on devait définir la machine dans sa forme la plus élémentaire, on pourrait dire ceci : la machine est un outil créé pour accomplir une...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Rıdvan Gızri']::text[], 8.5, '{"poet":"Muhammed Rıdvan Gızri","poet_slug":"muhammed-ridvan-gizri","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/le-temoin-de-l-etre-intelligence-artificielle-conscience-et-unicite-ontologique-de-l-etre-humain-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnci Tanesi', 'i-nci-tanesi-erokrates-erol-guner-etmb3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen var ya sen...! 

Sen okyanusun derinliklerin de saklı

Sen bir istiridye''nin kalbin de gizli

Sen denizlerle kaplı bir inci tanesi''sin....

Her göz göremez böyle bir kulu

Her gönül bilmez sendeki gururu 

Karanlık saklasa da sendeki o nuuru

Sen nuruyla parlayan bir inci tanesi''sin...

Öyle her gönül anlamaz değerini

Her bakış bilmez senin kıymetini 

Dışında arama sen, o saklı güzelliğini

Sen güzelliğin de saklı bir inci tanesi''sin....

Sessiz sedasız büyürsün derinler''de

Işığın yayılır karanlık geceler''de 

Ne denizler saklar seni sessizliğin''de

Ne zaman soldurur gönüller''de

Sen gönüller''de bir inci tanesi''sin..

İnci dediğin de sabırla doğar 

Karanlıklar içinde ışıklar saçar

Her gelen kıyı dan bakar geçer

Gönülden görenler değerini ölçer 

Sen karanlıklar''da değerli bir inci tanesi''sin ...

 Her inci tanesi vitrine konmaz

Kuyumcu elinde değerin artmaz

Her inci, her gönülde saklanmaz

Sen yürekler''de gizli bir hazine''sin

Sen kalpler''de saklı bir inci tanesi''sin.. 

14,10,2026', 'Sen var ya sen...!  Sen okyanusun derinliklerin de saklı Sen bir istiridye''nin kalbin de gizli Sen denizlerle kaplı bir inci tanesi''sin.... ...', ARRAY['Türk Edebiyatı','Şiir','Erokrates Erol Güner']::text[], 8.5, '{"poet":"Erokrates Erol Güner","poet_slug":"erokrates-erol-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/inci-tanesi-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün Yanında Yoksam', 'birgun-yaninda-yoksam-mihrimah-sultan-0qwaz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün yanında yoksam bil ki seni
artık sevmediğim içindir
Bil ki bu sevgiye yazık etmişsindir
Çabalarımla ilmek ilmek dokuduğum
Sevdayı hiçe saymışsındır

Yıllar yormuş, verdiğim çaba boşa çıkmıştır
Bir olamamış, tutunamamışızdır
Tercihlerin seni mutlu etmedi, beni de...
Yinede inat eder, devam edersin

Bir gün takatin kalmayacak, verdiğin
karar seni yakacak
Geri dönüşün olmayacak.
Olan sabilere olacak...
Gören gözlerin bizi görmedi ya,
Rabbim hesap soracak.

_Mihrimah''ın kaleminden_', 'Bir gün yanında yoksam bil ki seni artık sevmediğim içindir Bil ki bu sevgiye yazık etmişsindir Çabalarımla ilmek ilmek dokuduğum Sevdayı hi...', ARRAY['Türk Edebiyatı','Şiir','Mihrimah Sultan']::text[], 8.5, '{"poet":"Mihrimah Sultan","poet_slug":"mihrimah-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/birgun-yaninda-yoksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyku Sersemliğim', 'uyku-sersemligim-alper-tunga-3-zokg0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnan bana, bu en yalın halim.

Haklısın, sana yeterince zaman ayıramadım.

Ama ömrümü sana teslim etmek içindi bu

Haklısın, sessizliğim seni endişeye sürükledi...

İnan bana şiirsellik yüzünden, kelimem kalmadı,

Bazen insan yazamaz, yazamadım bende

Sessizliğimin her nedeni, hayata atımaktan,

Bencillik yapmak istemedim, huzur vermek istedim.

Yaptığım hatayı affettirmek istedim, bagışlanmak,

Senin çıkıp geldiğinde bir ben olayım.

Ve hiçkimse bize hiçbirşey sormasın.

İnan bana bunu gerçekten başarabildim, 

Sadece o  şiirsel evi arıyorum, mavi pencereli

Bu dünyanın içinde yaşayan bir şiir olmak,

Nefes almak, nefes vermek ve nihayet

Sana öyle kaybolurcasına sarılmak istedim.

Sadece kollarında bir uyku sersemliği olmak

Hayalini kurduğumuz, söz verdiğim gibi

Güzel gözlü prenses, ne olur böyle söyleme hiç,

Biliyorsun senin için öleceğimi, öldüğümü

Biliyorsun sende, senin nefesinle dirilişimi, 

Herşey güzel olacak, güzelliğin kadar masum.

Senin her yaşına aşığım ben, her yaşına hayran

Endişelerinden öpüyorum, sen ne söylersen...

Gitmediğin her sözü ben öper, koklar, sararım', 'İnan bana, bu en yalın halim. Haklısın, sana yeterince zaman ayıramadım. Ama ömrümü sana teslim etmek içindi bu Haklısın, sessizliğim seni e...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga 3']::text[], 8.5, '{"poet":"Alper Tunga 3","poet_slug":"alper-tunga-3","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/uyku-sersemligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Mavi Düş', 'bir-mavi-dus-mihrimah-sultan-ayuwi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir mavi düşe dalmak isterim,
Yeşil yorgan serilmişken yere,
Suyun şırıltısını, huzuru dinleyerek,
Bir kitap alıp hayale daldım.

Düşledim güzel bir dünya,
Kavga dövüşü olmadan.
Sessizliğin sükunetin tadında
Hisset şimdi kendini.

Sakinliği, kalbinin iyiliğini,
İyi kalabilmeyi öğrenmeyi hissederek.
Mutlu olabilmeyi kalarak öğren.
Şimdi, kötülük olmadan yaşamanın keyfini.

Korku olmadan geçirilen zamanı,
Keyifle dinleyerek suyun ritmini.
Demle çayını, ser kilimini.
Gel, bu mavi düşe beraber dalalım.

~ Mihrimah Sultan''ın kaleminden ~', 'Bir mavi düşe dalmak isterim, Yeşil yorgan serilmişken yere, Suyun şırıltısını, huzuru dinleyerek, Bir kitap alıp hayale daldım. Düşledim gü...', ARRAY['Türk Edebiyatı','Şiir','Mihrimah Sultan']::text[], 8.5, '{"poet":"Mihrimah Sultan","poet_slug":"mihrimah-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-mavi-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiğit', 'yigit-mihrimah-sultan-ixte9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adım Yiğit benim,
Bilinmez kuytu köşedeyim.
Vatanı bekler, zalime korku veririm.
Elimle koymuş gibi çakalın izindeyim.
Zihnimi kullanır, izimi silerim.
Bir destan yazarım, bilinmez kimliğim.

Nenelerim, annelerim rahat uyusunlar.
Bu dağlar geçilmez, ben ölmedikçe.
Siper ederim gövdemi hayata tutunurcasına.
Aklı almaz katillerin, boşa gitmez emeklerim.

Taburumdaki askerler heyecanla
Yeni olacak hikayeyi bekler.
Adım gizlidir benim,
Namımı dağda ki bilir.

Ne sıkıntılar çektim dinleseniz aklınız delir.
Dedim bir rahat edeyim, çalıştım edemedim.
Aksiyona alışmış bedenim, vatanım bekler.
Bahçede kaldı domates biberlerim.

_Mihriman kaleminden_
*10 Ağustos 2026*', 'Adım Yiğit benim, Bilinmez kuytu köşedeyim. Vatanı bekler, zalime korku veririm. Elimle koymuş gibi çakalın izindeyim. Zihnimi kullanır, izi...', ARRAY['Türk Edebiyatı','Şiir','Mihrimah Sultan']::text[], 8.5, '{"poet":"Mihrimah Sultan","poet_slug":"mihrimah-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yigit-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-mihrimah-sultan-q9ht5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Annem ben büyüyemedim daha, görünüşüm haykırıyor ama,
Karnında istenmemiştim, yine de tutunmuşum hayata.
Ondan mı terk edilme korkusu var, ondan mı bu yara
Ondan mı vefasızlık görüyorum her defasında?

Tek başınayım bu kalabalıkta, sevgim içimde kaldı,
Karnında kaldığım için mi çıkaramıyorum dışarı?
Haykıramıyorum, sesleniyorum, saklıyorum içimde,
Ondan mı güvenemiyorum kimseye tamamen?

Kar taneleri gibi eriyor tanıdıkça insanlar,
Her biri farklı desen, düşüp kayboluyor birer birer.
Kundakta sarsaydın beni şefkatinle keşke,
Doyaydım kokuna, unutsaydım derdimi kucağında.

Geçer mi anne, ferahlatır mı kucağın beni?
Duyar mısın, anlar mısın sesimi oradan?
''Git'' dediğinde Daha karnındayken
kapattın kapıyı, çıkamadım.

''Git'' dediğinde
bittim bittim ben,
kapattın kapıyı, çıkamadım.

Biliyorum acın vardı, kaybın vardı anne,
Toprağa verdin gülüşü güzel ablamı erkenden.
Olsaydı sığınırdım, sarılırdım ona,
Gelir mi cennetten, öper mi yanağımdan?

Can ablam olacaktı, dert ortağım, özüm olacaktı,
Şimdi ''iyi misin'' diye mesajın geliyor.
''İyiyim'' diyemiyorum, kapattım o kapıyı,
Ama bilmiyorsun anne, Allah''a emanetim ben.

Mihrimah''ın kaleminden
11 Ağustos 2026', 'Annem ben büyüyemedim daha, görünüşüm haykırıyor ama, Karnında istenmemiştim, yine de tutunmuşum hayata. Ondan mı terk edilme korkusu var, o...', ARRAY['Türk Edebiyatı','Şiir','Mihrimah Sultan']::text[], 8.5, '{"poet":"Mihrimah Sultan","poet_slug":"mihrimah-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/annem-1666-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kaybın Kucağıma Alamadigim', 'i-ki-kaybin-kucagima-alamadigim-mihrimah-sultan-god98', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çocuktum, büyüdüm, hanımefendi oldum bir günde.
Bir kaza, iki kayıp yaşadım.
Biri, merhametine sığındığım anam;
Diğeri, en güvenli sığınağım babam.

Sanki onlarla her şeyim gitti.
Bütün servetim onlarmış benim.
Onlarla zenginmişim meğer.
Varım, yoğum onlarmış benim.

Nasıl olacak şimdi, ne yapacağım?
Kimin yemeklerini özleyeceğim?
Kime "hoş geldin" diye boynuna sarılacağım?
Ev bomboştu.

Şimdi bir kardeşim, bir de ninem vardı.
Tutunacak dalım onlar kaldı,
Bedenim bu acıyı kaldıramadı.
Bağırıyor avaz avaz.

Beklemediğim, davetsiz bir misafirdi.
Benim en güzel tadacağım duyguyu aldı elimden.
Yeniden hayata bağlanacağım bir armağanı.
Minicik gülümseyen bir meleği.

Öyle bir melek ki, bütün dertlerini unutuyorsun.
Rabbimin bir armağanı, hediyesi gibi.
Küçücük sesler çıkarması, dudağını büzmesi...
Kucak isteyince gülerek kollarını indirip kaldırması.

Bir de kucağında mis gibi koku.
Annelik duygusu, senden bir parça.
Günden güne büyüyen, değişen,
Zorluğuna keyifle katlanılan.

Öyledir değil mi annelik?
Adım adım izliyorsun adımlarını.
Düşmesini, senden yardım için gözlerine bakmasını...
Bunları elimden aldı benim.

Yine fakir kaldım şimdi.
Yine varım, yoğum yok oldu.
Sevgim içimde yok kaldı.
Arada parka gidiyorum, onları seyrediyorum.

Cıvıl cıvıl neşeli koşturmalarını,
Oynamalarını, kumdan kale yapmalarını...
Bağırmalarını, pamuk şekerle boyanmalarını.
İçime çekiyorum sessizce.

Bir gün Mihrim bana bir müjde verdi:
"Cennette Rabbim bu meleği verecekmiş sana.
Alacakmışsın kucağına."
Hemencecik gülüşünü sevdiğim, mis kokulu...

Oy Rabbim, canımın içi benim.
Kahrında hoş, lütfunda hoş.
Sen bırakmazsın benim kucağımı boş.
Sensiz bu hayat bomboş.

Mihrimahun kaleminden
13/08/2026
10.30.', 'Çocuktum, büyüdüm, hanımefendi oldum bir günde. Bir kaza, iki kayıp yaşadım. Biri, merhametine sığındığım anam; Diğeri, en güvenli sığınağım...', ARRAY['Türk Edebiyatı','Şiir','Mihrimah Sultan']::text[], 8.5, '{"poet":"Mihrimah Sultan","poet_slug":"mihrimah-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/iki-kaybin-kucagima-alamadigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Göğe, Ne Toprağa', 'ne-goge-ne-topraga-sumeyye-helimergun-7hc0a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçimde bir o yana bir bu yana savrulan avare düşünceler,

Öyle ki birbirinin yüzünü dahi tanımayan...

Dalmışım hiç basılmamış karların beyazlığını düşlüyorum.

Birbirine yanlış dikilmiş hazin mevsimler,

buram buram hazan kokuyor.

Saat ilerliyor o sırada; tik tak, tik tak...

Ama bu ses yalnızca zamanı değil,

yaşanmamış anları da öğütüyor.

Gözlerimin derininde saklanan amansız iç fırtınalarım yokluyor beni.

Bakışlarımda saklıdır, dile gelmeyen fırtınalarım.

Oysa gösterebildiğim bir yaram yok ki benim.

Suskunluğuma sığınak kılacak kimsem de yok, bilirim.

Şimdi nice dualara, nice kelâmlara sığınsam da,

çatladıkça binbir gecenin sızısı,

dünün küllenmiş hatıraları damlıyor parmaklarıma...

Acaba hangi kuşun kanadında kaldı uçma hevesim?

Hevesimle birlikte gökyüzümü de kaybettim.

Ben, kendi mağrur gölgesine eğilen yapayalnız bir nergisim.

Güneşe kör, düştüğü çamura sevdalı, çaresizim.

Biraz göğe ait, biraz toprağa mahkûmum.

Şair olacaktım, şiir oldum dedim kendi kendime;

hangi mısrada eksileceğimi bilmeden.

Zamanın gergefinde dokunuyor ruhumun incelen kumaşı.

Ne gökyüzü kabul eder beni ne de toprak tutar artık.

Adı konmamış bir boşlukta,

mağrur bir nergis gibi suya karıştım, kendime eğildikçe...

Yalnızlığın en koyu, en dilsiz kıyısında...', 'İçimde bir o yana bir bu yana savrulan avare düşünceler, Öyle ki birbirinin yüzünü dahi tanımayan... Dalmışım hiç basılmamış karların beyazl...', ARRAY['Türk Edebiyatı','Şiir','Sümeyye Helimergün']::text[], 8.5, '{"poet":"Sümeyye Helimergün","poet_slug":"sumeyye-helimergun","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ne-goge-ne-topraga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluk Gunleri', 'cocukluk-gunleri-mihrimah-sultan-uxd05', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çocukluk günlerine dönelim biz ki,
Haydi ile hayallere dalan Şaban''la,
Kahkahalara boğulan Ferdi ile,
Emrah''la ağlayan.

Tarzan''la özgürlük hevesi,
Habil ile Kabil olayına hayretle bakan.
Sokakta bitmeyen ezanla biten oyun keyfi...
Kar yağınca anlardık masumiyeti.

Metrelerce uzayan tren gibi kayışımız,
O çocukluk günleri aranıyor şimdi.
Leblebi tozu keyfimiz,
Bardakla ölçülen çekirdeğimiz.

Salça ekmekle günü geçiştiririz,
Meyve ağaçları soframız,
Çimenler doğal halımız,
Çamurdan yaptığımız yenilmeyen ekmekler.

Evden kaçırdığımız kumaşlar,
Yıkamak için yunnak''ta.
Okul bahçesi oyun alanımız,
Evimiz gibi rahat ettiğimiz.

Piknik yapıp dinlendiğimiz,
Biz oruçken yemek yiyen,
Sinirlendiğimiz öğretmenimiz...
O günler hatıralarda kaldı.

Şimdi geriye bakıp hatırlamak isteyeceğimiz anılar,
Hep gülümsetir bizi.
Tabii mutlu olanları.

Şair mihrimah Sultan
21/08/2026', 'Çocukluk günlerine dönelim biz ki, Haydi ile hayallere dalan Şaban''la, Kahkahalara boğulan Ferdi ile, Emrah''la ağlayan. Tarzan''la özgürlük h...', ARRAY['Türk Edebiyatı','Şiir','Mihrimah Sultan']::text[], 8.5, '{"poet":"Mihrimah Sultan","poet_slug":"mihrimah-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/cocukluk-gunleri-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamsal Görevler', 'yasamsal-gorevler-onder-karacay-4okrk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '§

Yasam da bazı görevler vardır ki toprak olduktan sonra da o görev sonsuza kadar bitmeden görevini yapar. 

Bu durum en çok o görevi yok sayarak başka bir niyete bürünenleri rahatsız eder. 

Görevi yaşam verir, hak eden yerine getirir. Yaşam da dengeler olumlunun olumsuza, olumsuzun olumluya farkında olarak veya farkında olmadan hizmet etmesiyle değişir. Döngüyü her zaman yaşam değiştirir. Yaşam evrenin, tabiatın kendisidir. İnsan yaşamın bir parçası olarak görevini yapar. Olumsuz sonuçlar üreten kötülükler yaşamsal olmadığı için kalıcı olamazlar. Kalıcılığı her zaman genel yararı sağlayan olumlu çaba ve görevler sağlar. 

§

▪️Önder Karaçay ▪️', '§ Yasam da bazı görevler vardır ki toprak olduktan sonra da o görev sonsuza kadar bitmeden görevini yapar.  Bu durum en çok o görevi yok say...', ARRAY['Türk Edebiyatı','Şiir','Önder Karaçay']::text[], 8.5, '{"poet":"Önder Karaçay","poet_slug":"onder-karacay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yasamsal-gorevler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiğitin Öyküsü', 'yigitin-oykusu-mihrimah-sultan-1eflp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yiğit dir onun adı,
Okuduğu harp okulunu Alparslan gördü.
Gözündeki koru, bitmeyen tükenmeyen cesurluğu,
Babasının ona bıraktığı vatan sevdası.

İlk nasihatı oku, adam ol dedi,
Vatanına toprağına bağlı ol.
Adadı kendini, unuttu sefa''yı keyfi,
Gitti gençliği, kaldı tek bir yolu.

Hayali terörü bitirmekti,
Yastığa kendini deliksiz uykuya bırakmaktı.
Çünkü onun yastığı taştı, yorganı gökyüzüydü,
Tetikte olması onu ustalaştırdı.

Onların asla ruhu duymazdı,
Nereden hangi taşın altından çıkacağını.
15 erin yapacağı kabiliyet tek başına,
Ordu performansı, tarihe yazılacak kahramanlık.

Al kalemi eline, hazır ol şimdi,
Ayaklar şiş, gözler yorgun, kilometreler uzamış.
Akıllılar şaşkın, çoğu kuş tüyü keyfinde,
Aklına Mehmetçik gelmez bile.
Saçlarını arttı onun.

Namlusu dumanı, yüreği heyecanlı,
Ayaklar şiş, gözler yorgun, kilometreler uzamış.
Akıllılar şaşkın, çoğu kuş tüyü keyfinde,
Aklına Mehmetçik gelmez bile.

Şair mihrimah''ın kaleminden
19.08.2026', 'Yiğit dir onun adı, Okuduğu harp okulunu Alparslan gördü. Gözündeki koru, bitmeyen tükenmeyen cesurluğu, Babasının ona bıraktığı vatan sevda...', ARRAY['Türk Edebiyatı','Şiir','Mihrimah Sultan']::text[], 8.5, '{"poet":"Mihrimah Sultan","poet_slug":"mihrimah-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/yigitin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avucundaki Serçe', 'avucundaki-serce-mihrimah-sultan-459h0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Farzet ki avucunun içinde küçük bir serçeyim,
Uzak diyarlardan gelen yorgun ve bitap düşen.
Kanadı kırık yaralı bir serçe,
Hissetmek istiyor kendini güvende.

Sıcacık olması onu mest etmiş,
O yeri sevmiş ki kopmak istememiş.
Ama bir taraftan da bitmesinden korkmuş,
Gidecek bir yuvası yokmuş çünkü.

_Gökten yere inince_ hiçbir çöp dal bulamamış,
Kendisine yuva kuracak mecali kalmamış.
Bitap düşmüş bedeni sonra senin gözlerine bakmış,
Masum bir bakışla rahatlamak istemiş.

Geldiği yerden sırtında tonlarca yükle gelmiş,
Bırakmak istemiş ama o kadar kolay değilmiş.
Tam seni görünce bırakmış yükünü,
Teslim olmayı tercih etmiş.

Sıcacık huzurlu bir kucak aramış,
Allah''a yalvarmış: "Mutlu olabileceğim bir yuva ver Allah''ım."
Çünkü yorulmuş ötmekten uçmaktan,
Mecalsiz kalmış yüreği, dinlenmek istemiş.

_Mihrimah Sultan''ın kaleminden_
_25.08 2026 salı saat 12.50_', 'Farzet ki avucunun içinde küçük bir serçeyim, Uzak diyarlardan gelen yorgun ve bitap düşen. Kanadı kırık yaralı bir serçe, Hissetmek istiyor...', ARRAY['Türk Edebiyatı','Şiir','Mihrimah Sultan']::text[], 8.5, '{"poet":"Mihrimah Sultan","poet_slug":"mihrimah-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/avucundaki-serce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Toprağın Öyküsü', 'o-topragin-oykusu-mihrimah-sultan-k31om', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızlığın öyküsü yazılırdı doğu topraklarında,
Bir mühür vurmuşlar ninelerin çenelerine.
İhanetin şehri olmuş, kadınların ortak çilesi,
Aile göz ardı edilir, erkek günleri rutindir.

Çocuk kahrı tek kadının çekmesi istenir,
Kadına zorunlu gün adledilir
Nasılsın diyen yok, sohbete layık gören er yok,
Kavurucu sıcakta ihanetin acısı yüklenir.

Ne dilden anlarlar ne de halden anlarlar,
Konu siz olunca küçücük şeye mahkeme kurulur.
Yok yere yargılanır bacılar,
Kadının değeri olmaz, çocuğun tapusu verilir onlara.

Acıyı evladı için katlanır bu bi çare,
Gidecek yeri yoktur, kapısını açacak.
Çocuğun gözünde değersizleştirilir anne,
Sessiz feryat figandır yüreği.

Ya bu dertle tükenecek ya bu diyardan gidecek,
Annelik duygusu zinciri vurur ayaklarına.
Ne uzağı gidebilir ne de olduğu yerde neşelenir,
Bir dert anlatsa dilden dile dillenir.

Fakirin giyimi dedikodu edilir,
Marka takıntısı olmuş, iyi görünmek yarışı.
Hele de misafirine ikram ettin mi,
Laf söz edilir ardınca.

Tatil günleri ev terk edilir,
Piknik alanları zımımızık doludur.
Doğayı yaşamak, hissetmek,
Balığın sudan çıkmış hali gibidir orada.

Nefes alamazın eve gidene kadar,
Filistin sokaklarını andırır eski sokakları.
Kendini farklı ülkede hissedersin ama insanı benzemez asla,
Yalın ayak dolaşır çocuklar caddelerde.

Güçlenmiş bağışıklık mı bilmem, hasta olmazlar,
Sokağı tüm çocukların yansıtırlar.
Ellerinde buz gibi meybuz çubuğuyla,
Çocuk kavgasına girer yetişkinler.

Allah aşkına çocuk olduğunu unuturlar,
Beybabaları "sen mi güçlüsün ben mi" girer kavgası.
Ortalıkta yetişkin çocuklar mı dolanır...

_Mihrimah Sultan''ın kaleminden_
_25.08 2026 saat 14.17_', 'Yalnızlığın öyküsü yazılırdı doğu topraklarında, Bir mühür vurmuşlar ninelerin çenelerine. İhanetin şehri olmuş, kadınların ortak çilesi, Ai...', ARRAY['Türk Edebiyatı','Şiir','Mihrimah Sultan']::text[], 8.5, '{"poet":"Mihrimah Sultan","poet_slug":"mihrimah-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/o-topragin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gösteriden İbarettir', 'bir-gosteriden-i-barettir-i-lyas-ates-sgx5t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her şeyi bildiğini sananlar hiç bir şeyin farkında

değildirler 

İnsan gerçeği fark ettikçe bildikleri anlamsızlaşacaktır 

Gerçeği fark ettikçe sizler kaybolacaksınız zaman

mekan anlamını yitirecektir 

Zaman mekan anlamını yitirdiğinde sizlerin kimlikleri

yavaş yavaş kaybolacaktır 

Kimlikleriniz kayboldukça sizler şaşıracaksınız ve

kaybolmamak için eski kimliklerinizi korumaya

çalışacaksınız bu hal kendinizi garantiye almak

için verilen anlamsız bir çabadır 

Toplumları ayakta tutan bütün miladi dolmuş 

inançları terk etmedikçe ne gerçekten inanmış

nede Hak yolundasınızdır 

Öze dönmedikçe dışardaki inanç ve iman

birer gösteriden ibarettir', 'Her şeyi bildiğini sananlar hiç bir şeyin farkında değildirler  İnsan gerçeği fark ettikçe bildikleri anlamsızlaşacaktır  Gerçeği fark ettik...', ARRAY['Türk Edebiyatı','Şiir','İlyas Ateş']::text[], 8.5, '{"poet":"İlyas Ateş","poet_slug":"i-lyas-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gosteriden-ibarettir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuza Veda', 'sonsuza-veda-kasim-kobakci-tmsh2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geldiğin o günde bitmişse nefes,

Uçmuşsa yuvadan bu suskun kafes,

Kapanmış diyorsa içimdeki ses,

Üzülme sevdiğim bitince heves.

*

Duvarda resmimden düşerken seda,

Hayata sessizce etmişsem veda,

Ruhumu meçhule kılmışsam feda,

İçinden yükselsin sessiz bir nida.

*

Ellerin dokunsun soğuk yüzüme,

Yaşların düşmesin sönmüş közüme,

İnanıp verdiğim eski sözüme,

Son defa bakıver iki gözüme.

*

Kapatma kapıyı ışıklar dolsun,

Bırak da umutlar sararıp solsun,

Dilerim mekanım cennetler olsun,

Arayan dostlarım izimi bulsun.

*

Karanlık odada durma öylece,

Yanıma oturup bekle sessizce,

Ölümün sırrını düşle gizlice,

Hayal et ruhumu sarıl delice.

*

Dışarda rüzgarlar esip geçerken,

Ecelim şarabı tasla içerken,

Mezarım kazılıp kefen biçerken,

Gülümse melekler beni seçerken.

*

Saatin tiktakı vurup dursa da,

Ayrılık kalbini kırıp yorsa da,

Komşular toplanıp halim sorsa da,

Kederler akılda pusu kursa da.

*

Sakın ha ağlama dik tut başını,

Siliver gizlice hicran yaşını,

Zehir etme bana veda aşını,

Süslesin adımız mezar taşını.

*

Artık ben sonsuza veda ederim,

Bırakıp her şeyi sessiz giderim,

Topraktan yapılmış benim kaderim,

Sen mutlu kalırsan biter kederim.', 'Geldiğin o günde bitmişse nefes, Uçmuşsa yuvadan bu suskun kafes, Kapanmış diyorsa içimdeki ses, Üzülme sevdiğim bitince heves. * Duvarda re...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/sonsuza-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rabbim', 'rabbim-mihrimah-sultan-7lhm7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Rabbim sen beni görüyorsun,
Sensiz ben eksiğim, hiç kimsem yok.
Islat beni rahmetinle isterim,
Coşsun yüreğim, atsın kalbim Allah nidalarıyla.

Hz. Ebubekir''in merhametini verdin bana,
Ya Rabbi Hz. Hamza''nın cesaretinden,
Hz. Osman''ın takvasından,
Hz. Ali''nin ilminden, Hz. Ömer''in adaletinden ver Ya Rabbi.

Peygamberimizin devesinin aşkından, kütüğün ağlayışından,
Üç yüz yıl onu mağarada bekleyen
Yılanın azminden bize de ver Ya Rabbi,
Sen, senin sevginle donat bizi, ferahlat Ya Rabbi.

Oy taşlar altında göğsü ezilen Bilal''im,
Sen ki imanın için vazgeçmeyen yiğidim,
Resulullah''sız ezan okuyamazdın,
Senin kadar güzel okuyamaz şimdikiler.

Ey Sümeyye anam, saçlarından kollarından çekilip ayrılarak şehit edildin,
Ya Rabbim aklımızı başımıza al,
Bizi kendi halimize bırakma Allah''ım,
Sen tut elimizden, sensiz biz hiçiz,
Sen bizim tek dayanağımızsın.

_Mihrimah Sultan''ın kaleminden_', 'Rabbim sen beni görüyorsun, Sensiz ben eksiğim, hiç kimsem yok. Islat beni rahmetinle isterim, Coşsun yüreğim, atsın kalbim Allah nidalarıyl...', ARRAY['Türk Edebiyatı','Şiir','Mihrimah Sultan']::text[], 8.5, '{"poet":"Mihrimah Sultan","poet_slug":"mihrimah-sultan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/rabbim-150-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama', 'aglama-adnan-hacigumus-30s80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'haddime  değil elbet
karışmak tanrının işine
lakin hissimce
aynı yere gidecekmişiz gibi
seninle öbür dünyada
yani demem o ki
yarım kalmayacak hiçbir şeyimiz
ağlama', 'haddime  değil elbet karışmak tanrının işine lakin hissimce aynı yere gidecekmişiz gibi seninle öbür dünyada yani demem o ki yarım kalmayaca...', ARRAY['Türk Edebiyatı','Şiir','Adnan Hacıgümüş']::text[], 8.5, '{"poet":"Adnan Hacıgümüş","poet_slug":"adnan-hacigumus","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aglama-323-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu vatan bizim', 'bu-vatan-bizim-sahin-erturk-xen5p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu vatan bizim 

Takma kafana

Günü yaşa diyorsun

Müslüman kanı,

Oluk oluk akıyor

Adaletsizlik zirve yapmış

Madde maneviyatı yenmiş

Tuzu kurular azdıkça azmış

Gariplerin canı çıkıyor

Asgari ücretli aç

Emekli perişan

Sokaklar çıplaklar kampı

Çeteler hırsızlar çoğalmış

Devleti soyan soyana 

Takacak bunca şey var iken

Takma kafana düşünme 

Günü yaşa diyorsun

Takacaksın dostum

Bu memleket bizim 

Burada yaşıyoruz

Burada ekmek yiyoruz 

Bu cennet vatanın

Nimetlerinden faydalanıyoruz 

Vatan bayrak diyen birinin

Takmaması düşünmemesi

Bana ne demesi 

Günü yaşaması

Mümkünmü dersin ?

Takacağız dostum takacağız 

Batarsa bizde batarız

Sorumluluk alacağız

Yanlışları söyleyeceğiz

Doğruları yazacağız

Bu vatan bizim 

Bu vatan bizim

Nöbetçi şair (Şahin Ertürk)', 'Bu vatan bizim  Takma kafana Günü yaşa diyorsun Müslüman kanı, Oluk oluk akıyor Adaletsizlik zirve yapmış Madde maneviyatı yenmiş Tuzu kurul...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bu-vatan-bizim-96-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutlu Sabır Taşı', 'kutlu-sabir-tasi-kasim-kobakci-jb0vm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüce bir günden kalbe, bin minnet ve şükranla,

Unuttum sayısını, akıp giden zamanla,

Geçtim bu yokuşlardan, içimdeki imanla.

*

Her adımda sen varsın, sayarsın adımları,

Kesilir hep nefesim, anarım makamları,

Acizlikten gömüldüm, izlerim akşamları.

*

O yorgun akşamda da, aynı sonsuz minnetle,

Hatırladım hepsini, büyük bir metanetle,

Yürüdüm tüm yolları, kalbimde emanetle.

*

Yine düştün diline, inlerken kelimeler,

Titrerken dizlerim, bak sarsıldı kademeler,

Kavrayışım karardı, yıkıldı denemeler.

*

O nurlu sabaha dek, bende minnet yeşerir,

Unuttuğum sayılar, gözlerimde belirir,

Geçtiğim o sokaklar, hep ruhumda dirilir.

*

Sen varsın her adımda, seni görür duyanlar,

Nefesim kesilse de, pes etmez bu uyanlar,

Acizlik gömülürken, yolundan sapmayanlar.

*

Bir sessiz tebessümle, yine şükran sunarım,

Sayısız yollardaki, hasretinle yanarım,

O yokuş bittiğinde, rahmetini anarım.

*

Yanımdasın bilirim, bu ömrün telaşında,

Titreyen bacaklarla, bu yolun en başında,

Gömüldüm karanlığa, kutlu sabır taşında.', 'Yüce bir günden kalbe, bin minnet ve şükranla, Unuttum sayısını, akıp giden zamanla, Geçtim bu yokuşlardan, içimdeki imanla. * Her adımda se...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kutlu-sabir-tasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi 1', 'sevgi-1-haci-gurbuz-dn84f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SEVGİ  ¹

Gürbüz’üm;

en temiz sevgi,

sessizce yaşanan sevgidir…

Kimse bilmez, kimse görmez,

ama en derinde o vardır.

💗

İnsanın içinden süzülüp gelen

arı bir duygudur bu;

gösterişi yoktur,

karşılık beklemez.

💗

Bazen çok acıdır…

Çünkü içine saklanır,

söylenmez, dile gelmez,

sadece kalpte büyür usulca.

💗

Ama yine de

en tertemiz hâlidir sevmenin…

Saflığın içinden çıkmış

sessiz bir dua gibi

H.G.03.08.1996', 'SEVGİ  ¹ Gürbüz’üm; en temiz sevgi, sessizce yaşanan sevgidir… Kimse bilmez, kimse görmez, ama en derinde o vardır. 💗 İnsanın içinden süzül...', ARRAY['Türk Edebiyatı','Şiir','Hacı Gürbüz']::text[], 8.5, '{"poet":"Hacı Gürbüz","poet_slug":"haci-gurbuz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevgi-1-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dümen', 'dumen-kasim-kobakci-hpfj9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Odanın köşesinde duran yalan,

Gözleri kamaştırıp aklı alan,

Loşluk içindeki ruhları çalan,

Etrafa sadece gölgeler salan,

Umudu söndürüp geriye kalan.

Ben sana inanma diyorum hemen,

Abajur altında gizlidir dümen.

*

Dışına bakanlar asla göremez,

İçi karanlıktır ışık veremez,

Onun ipliğini kimse düremez,

Sırrına da akıllılar eremez,

Sahte abajurdur yüze gülemez.

Ben sana inanma diyorum hemen,

Abajur altında gizlidir dümen.

*

Dantelli kılıfı ne kadar güzel,

Altında saklanır kirli ve özel,

Uzanıp ona hiç dokunmaz bir el,

Işığı gizlerken yaratır engel,

Bu süslü yalandan hemen geri gel.

Ben sana inanma diyorum hemen,

Abajur altında gizlidir dümen.

*

Loş bir masada ufacık abajur,

Sanırsın ki orda hükümdar huzur,

Ama her yanında gizlenir kusur,

Işığı yorucu zihinler uyur,

Sadece oyundur sayılmaz uğur.

Ben sana inanma diyorum hemen,

Abajur altında gizlidir dümen.

*

Işıklar içinde sürer bir savaş,

Gizlice dökülür gözlerden o yaş,

Her gülen yüze sen deme arkadaş,

Sahtedir pırıltı sahtedir her taş,

Zehirli aslında yediğin bu aş.

Ben sana inanma diyorum hemen,

Abajur altında gizlidir dümen.

*

Köşede duruyor bırakmadan iz,

Alınmış nefesler tıkalı geniz,

Sanırsın bu ortam berrak bir deniz,

Aslında kirlidir kalmamış temiz,

Oyundan bihaber bekliyoruz biz.

Ben sana inanma diyorum hemen,

Abajur altında gizlidir dümen.

*

Geceyi süslüyor hep sahte hayat,

İçtiğin kadehler inan çok bayat,

Yüzündeki maske sadece sanat,

Işıklar altında kırılmış kanat,

Bu süslü gösteri aslında tokat.

Ben sana inanma diyorum hemen,

Abajur altında gizlidir dümen.', 'Odanın köşesinde duran yalan, Gözleri kamaştırıp aklı alan, Loşluk içindeki ruhları çalan, Etrafa sadece gölgeler salan, Umudu söndürüp geri...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/dumen-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palyaçonun Yalnızlığı', 'palyaconun-yalnizligi-umut-erdem-0qmmj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar güldürürdüm herkesi Şimdi yankılanır kahkaham boş sokaklarda Yüzümde bir gülümseme taşıyorum Ama kimse bakmıyor gözlerimin arkasına

Bir kuklaydım belki de en başından İplerimi tutan kimse kalmadı artık Herkes benden korkmayı öğrendi Ama kimse neden yalnız olduğumu sormadı

Bir kutudan çıktım karanlığa Bir oyun sandılar bütün hayatımı Ben herkesi güldürmeye çalışırken Hayat çoktan bitirmişti şakalarını

Ve son perde kapandığında Alkışlayan tek kişi yine kendimdim Ben bir palyaço değilim aslında Sadece unutulmuş bir kahkahayım.', 'Bir zamanlar güldürürdüm herkesi Şimdi yankılanır kahkaham boş sokaklarda Yüzümde bir gülümseme taşıyorum Ama kimse bakmıyor gözlerimin arka...', ARRAY['Türk Edebiyatı','Şiir','Umut Erdem']::text[], 8.5, '{"poet":"Umut Erdem","poet_slug":"umut-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/palyaconun-yalnizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyi İşliyor Şair', 'sevgiyi-i-sliyor-sair-servet-bardak-rn8b3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgiyi İşliyor Şair 

Şairler sevginin emekçileri 

Sevgiyi herdaim işliyor şair 

Şeker şerbet gibi olur dilleri 

Sevgiyi herdaim işliyor şair

Pembeyle bakıyor daim gözleri 

Baldan tatlı olur onun sözleri

Güleçtir benizi güler yüzleri 

Sevgiyi herdaim işliyor şair

.

Beşere sevgiyle hep yaklaşıyor

Yüreği şu gönlü aşkla taşıyor

Hayatın içinde hoşca yaşıyor

Sevgiyi herdaim işliyor şair

.

Yürekleri yufka düşünür ince

Herşeyin başında sevgi der önce

Hayatın içinde biner zorvince 

Sevgiyi herdaim işliyor şair

.

Sevgidir şu balım diyor kaymağım 

Serveti sevgidir bahçedir bağım

Sevgiyle tütüyor daim ocağım 

Sevgiyi herdaim işliyor şair

.

15.11.2026

Servet BARDAK', 'Sevgiyi İşliyor Şair  Şairler sevginin emekçileri  Sevgiyi herdaim işliyor şair  Şeker şerbet gibi olur dilleri  Sevgiyi herdaim işliyor şai...', ARRAY['Türk Edebiyatı','Şiir','Servet Bardak']::text[], 8.5, '{"poet":"Servet Bardak","poet_slug":"servet-bardak","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sevgiyi-isliyor-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaktan İzledim Seni', 'uzaktan-i-zledim-seni-umut-erdem-3zwwj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzaktan izledim seni,
Yemeğini bekleyen bebek gibi.sen beni istemedin, köşeye attın bıraktın beni.

Sabah akşam aradım seni,
Gittin karıştın ara sokaklara. 
Uzun yol yürüdüm, yere yığıldım bir kütük gibi.

Sonunda buldum seni,
Yanında başka bir Mecnun.
Hüsrana uğrattın beni,
Kaldım bir mirket gibi.', 'Uzaktan izledim seni, Yemeğini bekleyen bebek gibi.sen beni istemedin, köşeye attın bıraktın beni. Sabah akşam aradım seni, Gittin karıştın ...', ARRAY['Türk Edebiyatı','Şiir','Umut Erdem']::text[], 8.5, '{"poet":"Umut Erdem","poet_slug":"umut-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/uzaktan-izledim-seni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçliğin İçinde', 'hicligin-i-cinde-umut-erdem-ev5jd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiçliğin İçinde

Gün doğar yine aynı sokaklar Aynı yüzler aynı boş bakışlar Herkes bir yere yetişme telaşında Oysa kimse bilmiyor nereye vardığını

Zaman geçer takvimler eskir İnsan dediğin biraz yaşar biraz bekler Dünya döner kimse farkına varmaz Bir gün gelen bir gün gider geriye iz kalmaz

Kimi servet arar kimi bir isim Kimi bir ömür harcar bulmak için kendini Sonunda herkes aynı soruyla kalır Bunca koşuşturmanın anlamı nedir

Belki de hayat cevabı olmayan bir soru Ne başlangıcı belli ne de sonu Biz anlam yükleriz geçen her güne Evren susar hayat devam eder yine', 'Hiçliğin İçinde Gün doğar yine aynı sokaklar Aynı yüzler aynı boş bakışlar Herkes bir yere yetişme telaşında Oysa kimse bilmiyor nereye vard...', ARRAY['Türk Edebiyatı','Şiir','Umut Erdem']::text[], 8.5, '{"poet":"Umut Erdem","poet_slug":"umut-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hicligin-icinde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmezdim Zor Olduğunu', 'bilmezdim-zor-oldugunu-murat-acer-tc7gm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BİLMEZDİM ZOR OLDUĞUNU 

​Bilmezdim ben seni sevmeden önce;

Sevginin bu kadar zor olduğunu,

Birine bağlanıp hesapsız kitapsız,

Aklının onunla yok olduğunu.

​Gündüz düşünecek, gece hayalde;

Matemler saracak her an, her yerde.

Eski filmlerde çok farklı hikâye;

Bilmezdim bu kadar zor olduğunu.

​Her sigaram efkâr tüter, göğe savrulur;

Karşılıksız her özlem gelip seni bulur.

Ömür hazan olur, kurur, dökülür;

Anladım Mecnun''un var olduğunu.

​Hatırı kıymeti yoktur verdiğin sözün;

Aynaya bakmaya utanır yüzün.

Geceler uykusuz, kalbinde hüzün;

Anladım sevenin kör olduğunu.

​Visali görünmez yârin gözünden;

Sanki zehir damlar her bir sözünden.

Umudun eksilir, biter kalbinden;

Anladım hayallerin boş olduğunu.

​Donan yüreğini lavlar eritmez;

Âh-ü zârın, acın bir lahza dinmez.

Kapanır yolların, geri dönülmez;

Anladım bir dönüşü olmadığını.

​Yine de beklersin döner mi diye?

Her yerde ararsın görünür diye?

Artık dost düşman bile acır hâline;

Anladım vuslatın zor olduğunu.

​Şair Murat yazdı zor bir sevdayı;

Zaman unutturmaz hiçbir acıyı.

Ref edip kendinden katar payını;

Anlatır sevdanın zor olduğunu,

Sevdaya düşenin yok olduğunu.

Murat Acer', 'BİLMEZDİM ZOR OLDUĞUNU  ​Bilmezdim ben seni sevmeden önce; Sevginin bu kadar zor olduğunu, Birine bağlanıp hesapsız kitapsız, Aklının onunla...', ARRAY['Türk Edebiyatı','Şiir','Murat Acer']::text[], 8.5, '{"poet":"Murat Acer","poet_slug":"murat-acer","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bilmezdim-zor-oldugunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vaz Geçmiş Olacaksınız', 'vaz-gecmis-olacaksiniz-i-lyas-ates-oql97', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Acılar içinde beklemek elden bir şey gelmemesi

sürekli cehennemdir 

Cehennemin ateşi arttıkça yaşamdan istemeyerek

vaz geçmiş olacaksınız

Yaşamdan vaz geçmekle cehennemden kurtulamazsınız

sizler bunu tattırılmakla hiç bir şey olduğunuzu mutlaka

kabullenmek zorunda kalacaksınız', 'Acılar içinde beklemek elden bir şey gelmemesi sürekli cehennemdir  Cehennemin ateşi arttıkça yaşamdan istemeyerek vaz geçmiş olacaksınız Ya...', ARRAY['Türk Edebiyatı','Şiir','İlyas Ateş']::text[], 8.5, '{"poet":"İlyas Ateş","poet_slug":"i-lyas-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/vaz-gecmis-olacaksiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ölme Ben Yaşarım', 'sen-olme-ben-yasarim-melodi-yalciner-aw22p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuru kuru kurum bürümüş havayı

Ancak sürüm sürüm sürünmeden

Düğüm düğüm düğümlenir telem dolu boğazım

Sade sade sadece ben görebilirim

Okumayı yazmayı ilk söktüğüm iki bin üç güzü

Fark ediyor muydum yaşamın bunca iz bırakacağını? 

O gelip geçen bir otobüs olacaktı hesapta

Geldi de geçemedi benden 

Keza, ezkaza aşk da

Gülüşlerini yarınlara emanet et, onlar üstüne titrerler

Bana emanet etmesen de

İştahını sakla yemeklere, benim için

Ben seni besleyemesem de

Yeter, yeter, yeter

Yeter ki sen ölme, ben yaşarım', 'Kuru kuru kurum bürümüş havayı Ancak sürüm sürüm sürünmeden Düğüm düğüm düğümlenir telem dolu boğazım Sade sade sadece ben görebilirim Okuma...', ARRAY['Türk Edebiyatı','Şiir','Melodi Yalçıner']::text[], 8.5, '{"poet":"Melodi Yalçıner","poet_slug":"melodi-yalciner","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-olme-ben-yasarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan İçin', 'i-nsan-i-cin-burak-ergen-0s145', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kendine dönüşün değil kendinden kaçışın azami yolculuklarıdır insan, 

Dondurur yüreğini sarmalayan, onun uğruna buz kütlesi olarak kalmayı göze alan.

Üşümekte düşünceleri, yazgıda bulamadığından tutuşturabilecek başıboş yanılgıları,

Bir buz misali elleri, dondurucu rüzgârları yüzünde hissederek kendini ona bırakması gibi 

Ve insan için böylesi, sadece berbat bir kışın habercisi.

Bir nefes beklemekte insan ya da siluetinde yankılanabilecek en ufak bir fısıltı,

Ne duyar kendinden kopan fırtınayı ne de başka benliklerin hangi ağızlarda homurdandığını,

En sessiz rüzgârda dahi dökülmekte yüreğin yaprakları, artık sonsuzluğun tadını bilmekte ızdırabı,

Olmadığı gibi bundan kaçışı, her şey yanılgının tapınağında keşiş olmaya kararlı

Ve insan için bundan fukarası, sadece ruhsuz bir sonbaharın bahçıvanı.

Arzuyu kutsayarak kendine gelmenin izindedir her düşünde insan,

Her yaptığının sonucu olarak bir başka habersiz, artık görebileceklerinden de çelimsiz.

Nasıl ki açmıyorsa ruhu bilebilecek bir tek çiçek, insana bunlardan kaçabilmek üzere yeni bir yazgı gerek,

Geçebilmek üzere geçmişin gölgesinde yetinmeden, kendindeki rengin göklerini dünyaya düşürmeden

Ve insan için bundan karmaşığı, sadece inanmak istediği ilkbahardan daha rahatı.

Duyduklarından gördüklerine değin kaçışın yolculuk anında bir ateştir insan,

Yanar yüreği onca zaman düşünmek zorunda kaldıklarından, algısını nasıl yönetebileceğini sağladığından,

Titrer bedeni çaresizliğin eşiğinde bir Tanrı misali, gelir katlanabileceği geçmişinden de her daim gerisi

Ve insan için böylesi, henüz kavrulmadığı yaz düşüncelerinin benzersiz bir ateşi.

Kimselerin görmesine gerek kalmadan kendi bilinmezliğini bilen yegâne varlıktır insan

Ruhu tatmasa da henüz farklı duygulanışları, başlar her daim yeni bir krizin tarzı

Hiç yaşamadıklarının tüyler ürperten rüzgârı, firari yazgının bol lanetli duaları

Ve insan için bundan aşırısı, sadece yeni Tanrıların mezarı.

Düşecek insanın yolu o mezarlığa, istemese de katılacak gözleri cenaze törenine,

Çaresi yok başka, kaçışı ise asla, kendinden kaçması ise mutlaka...', 'Kendine dönüşün değil kendinden kaçışın azami yolculuklarıdır insan,  Dondurur yüreğini sarmalayan, onun uğruna buz kütlesi olarak kalmayı g...', ARRAY['Türk Edebiyatı','Şiir','Burak Ergen']::text[], 8.5, '{"poet":"Burak Ergen","poet_slug":"burak-ergen","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/insan-icin-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Kafatasını Götürüyor', 'kan-kafatasini-goturuyor-melodi-yalciner-498on', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her yalan dosyam açıldığında

Her kendimi toylukla aklamak istediğimde

Avuç içlerim sırılsıklam

Terden değil, gözyaşlarımdan

Sabıkalıyım

Aşk sicilim kabarık da değil, delik deşik

Ablukadayım

Kaç aşka kaç yalan sığabilir? 

Üstelik benim dilimden

Ağzımın içinden beynime savaş kılıcı geçsin

Kan, kafatasımı götürüversin

İşte o zaman aklanırım', 'Her yalan dosyam açıldığında Her kendimi toylukla aklamak istediğimde Avuç içlerim sırılsıklam Terden değil, gözyaşlarımdan Sabıkalıyım Aşk ...', ARRAY['Türk Edebiyatı','Şiir','Melodi Yalçıner']::text[], 8.5, '{"poet":"Melodi Yalçıner","poet_slug":"melodi-yalciner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kan-kafatasini-goturuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrı''nın Unuttuğu Bir Dua', 'tanri-nin-unuttugu-bir-dua-ela-yucel-qtotw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün unutulacağım, biliyorum; Ne adım kalacak ne sesim bu dünyada. Belki Tanrı bile susacak ardından, Bir tek aşkım yankılanacak boşlukta.

Ölüm, yarım kalmış bir vedadır belki, Yaşam, Tanrı''nın zamana yazdığı şiir. Ve sen… Bunca faniliğin ortasında Unutulmaya kıyamadığım tek şeysin.

Çünkü insan bir gün ölür, Ama bazı aşklar Ölümden sonra bile hatırlanmayı bekler.', 'Bir gün unutulacağım, biliyorum; Ne adım kalacak ne sesim bu dünyada. Belki Tanrı bile susacak ardından, Bir tek aşkım yankılanacak boşlukta...', ARRAY['Türk Edebiyatı','Şiir','Ela Yücel']::text[], 8.5, '{"poet":"Ela Yücel","poet_slug":"ela-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/tanri-nin-unuttugu-bir-dua-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koşulsuz Sevgi', 'kosulsuz-sevgi-nihat-celik-2-14pwg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Temmuz 2022

Anlayabilir misin, merak ediyorum.

Çıkar olmadan, içinde benliğin olmadan sevmeyi.

Karşılık beklemeden, sebep aramadan, sebepsizce sevebilir misin?

Kızmadan, kırmadan, üstten bakmadan... Sevebilir misin canlı cansız nesneleri?

Yapabilirsin, biliyorum. Yapabilirsiniz, biliyorsunuz.

Kırabilir misiniz beyninizdeki zincirleri?

Beyninin karanlıklarından, ışık dolu bir dünyaya bakabilirsiniz.

Gördükleriniz, göreceklerinizin hiçbiri.', 'Temmuz 2022 Anlayabilir misin, merak ediyorum. Çıkar olmadan, içinde benliğin olmadan sevmeyi. Karşılık beklemeden, sebep aramadan, sebepsiz...', ARRAY['Türk Edebiyatı','Şiir','Nihat Çelik 2']::text[], 8.5, '{"poet":"Nihat Çelik 2","poet_slug":"nihat-celik-2","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kosulsuz-sevgi-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adın Geçmeyen Hikayeler', 'adin-gecmeyen-hikayeler-nihat-celik-2-k2xk6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mayıs 2023

Tüm dizelerde, seni sana anlatmak için yazdığım metinleri birer birer kopyalayıp saklıyorum yüreğime.

Kendimden bile gizlendiğim duygularımı gün yüzüne çıkarmıştın.

Coşkuyla sana seslenirken, isminle başlayan cümleyi isminle bitirmek...

Her seferinde isminle sana seslenmek, yanımda olduğunu hissettiriyordu.

Bu yüzden hep isminle başlayıp bitiriyordum tüm cümleleri.

Yarım asırlık, yaşlanmaya yüz tutmuş yüreğimde, hayattaki ümitsizliğimin ümidi olmuştun.

Bir hedefi olmayan, amaçsız dolaşan benliğimde, senin adının geçtiği tüm hikâyeler vardı zihnimde.

Başka isimlerin, başka gözlerin, başka sözlerin bir anlamı var mıydı?

Senin adın geçmeyen hiçbir hikâyenin anlamı kalmamıştı bende.', 'Mayıs 2023 Tüm dizelerde, seni sana anlatmak için yazdığım metinleri birer birer kopyalayıp saklıyorum yüreğime. Kendimden bile gizlendiğim ...', ARRAY['Türk Edebiyatı','Şiir','Nihat Çelik 2']::text[], 8.5, '{"poet":"Nihat Çelik 2","poet_slug":"nihat-celik-2","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/adin-gecmeyen-hikayeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Piyiz', 'tek-piyiz-kasim-kobakci-scb0g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yalnızsın ellerin üşüyor,

Bir masa, ev ıssız, içmek zor...

*

Herkes suskun, için sıcacık,

Zaman akmış, uyursun artık.

*

O gün gelip, özlersin dünü,

İçin yanar, ararsın yönü.

*

Ağlama, içmek yok, yer soğuk,

Boş bir kadeh, hayalin soluk.

*

İncinme, gömdüğün tek piyiz,

Ağlama, kayıp gider izsiz.', 'Yalnızsın ellerin üşüyor, Bir masa, ev ıssız, içmek zor... * Herkes suskun, için sıcacık, Zaman akmış, uyursun artık. * O gün gelip, özlersi...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tek-piyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terk Edilmiş Dokunulmazlık', 'terk-edilmis-dokunulmazlik-onder-karacay-auld5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '§

Zırhı dokunulmazlık olan bir insan yozlaşma ve putlaşma üretir. Yaşam da yozlaşan ve putlaşan her varlık özgürlüğünü kaybeder. Gün gelir yanında kendisine dokunacak hiçbir çıkarcı alkışı bulamaz. Sonuçta her Dokunulmazlık zırhına bürünen kendini tek edilmiş bir yalnızlık içinde bulur. Dün kendinden yana olanlar bugün karşısına geçmiştir. Aşırı korunaklı olmanın tehdidi kendi içinde dokunulmaz olma arzusunu büyüten suç ve korkularıdır. Suçu ve korkusu olmayan dokunulmaz olmak istemez. Yaşam da seven ve sevilen insan yozlaşmaz, hileli hiçbir zorlama ile yozlaştırılamaz. * İnsanlığın yaşamı bu acı dramlar ile tıka basa dolu olmasına rağmen yenileri yaşanmaya devam ediyor. İnsan her çağda kendini unutan olarak tekrar etmekten vazgeçmiyor. 

§

▪️Önder Karaçay ▪️ 

*İleri de bu konu yaşanan örnekler ile çesitlendirilerek bir kitaba dönüşebilir.', '§ Zırhı dokunulmazlık olan bir insan yozlaşma ve putlaşma üretir. Yaşam da yozlaşan ve putlaşan her varlık özgürlüğünü kaybeder. Gün gelir y...', ARRAY['Türk Edebiyatı','Şiir','Önder Karaçay']::text[], 8.5, '{"poet":"Önder Karaçay","poet_slug":"onder-karacay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/terk-edilmis-dokunulmazlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Kurban Bayramı', 'bugun-kurban-bayrami-muhsin-yener-2-71x8i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Allah’ın salâtı
Efendimiz Muhammed’e,
bütün nebîlere, bütün peygamberlere olsun. 

Ey Âlemlerin Rabbi!
Merhametini eksik etme
yorgun yeryüzünden.

Bir yetimin duasında,
bir annenin gözyaşında,
bir mazlumun sessizliğinde
senin adını arıyor insanlık.

Kurban;
yalnızca kesilen değil,
nefsin de secdeye varmasıdır biraz.

Kibirden arınmaktır,
paylaşmayı öğrenmektir,
komşunun açlığını
kendi vicdanında hissetmektir.

Bugün bayram. 
Kırgınlıkları toprağa gömelim,
öfkemizi kurban edelim.

Ve bir çocuğun gülüşü kadar temiz
bir dünya dileyelim birbirimize.

Tüm Türk İslam âleminin
Kurban Bayramı mübarek olsun.

Muhabbetle,
Muhsin Yener', 'Allah’ın salâtı Efendimiz Muhammed’e, bütün nebîlere, bütün peygamberlere olsun.  Ey Âlemlerin Rabbi! Merhametini eksik etme yorgun yeryüzün...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bugun-kurban-bayrami-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Dünya', 'yalan-dunya-deniz-yesil-2-xggwb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözler kapalı, etraf karanlık,
Ses yok, sadece dinle...
​Yollar uzun, hava soğuk, herkes aynı rol,
Pusula bozuk, sağdan sola dönüyor bu kol.
Yazan yazmış silen, silmiş kalmamış ki yol,
İstediğin kadar bağır, duyan yok.

Zaman akıp gidiyor durmuyor, herkes kendi yolunda kalmamış insanlık,
Ritim vurur duvara, kafa hep rahat, boşver giden gitsin bu da sana nasihat!

​Doğru yaşa, arkana bakma,
Dünya yalan, kendini yakma.
Giden gitti, adı kalmasın,
Kimse bu oyunu ciddiye almasın.
Doğru yaşa, arkana bakma,
Dünya karanlık, kendini yakma!

​Sokaklar sessiz, neon ışıklar sönük,
Herkesin yüzü maskeyle örtük.
Anlam arama boşuna, bu alem böyle bozuk,
Kelimeler havada, uçuşur hepsi sönük.
Ne hüzün kalmış geriye ne de bir pişmanlık,
Kafalarda hisler yok, her şey anlık.
Ritim vuruyor göğsüme, bu başka bir insanlık...

​Doğru yaşa, arkana bakma,
Dünya yalan, kendini yakma.
Giden gitti, adı kalmasın,
Kimse bu oyunu ciddiye almasın.
Doğru yaşa, arkana bakma,
Dünya yalan, kendini yakma!

​Ses kesildi...
Bitti gece...
Sadece yol ver...', 'Gözler kapalı, etraf karanlık, Ses yok, sadece dinle... ​Yollar uzun, hava soğuk, herkes aynı rol, Pusula bozuk, sağdan sola dönüyor bu kol....', ARRAY['Türk Edebiyatı','Şiir','Deniz Yeşil 2']::text[], 8.5, '{"poet":"Deniz Yeşil 2","poet_slug":"deniz-yesil-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yalan-dunya-615-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Yollar', 'bitmeyen-yollar-fatih-akay-2-qod19', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben hikayemi yazarken,
Bir Yıldız kaydı uzun ve parlak.
Yazılarım derinleşiyor geceyi işlerken
Sözlerim birbiriyle yarışacak

Dumanlı Dağlar önümde uzanıyor
Çılgınca esiyor rüzgar
Yolum bir vadiden geçiyor
Ve baktıkça büyüyor yollar

Gölgem uzamaya başlıyor
Kavuşuyorum yeni bir maceraya
İlk önce yıldızlar beni selamlıyor
Ve gidiyorum yeni hikâyeler yazmaya.', 'Ben hikayemi yazarken, Bir Yıldız kaydı uzun ve parlak. Yazılarım derinleşiyor geceyi işlerken Sözlerim birbiriyle yarışacak Dumanlı Dağlar ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Akay 2']::text[], 8.5, '{"poet":"Fatih Akay 2","poet_slug":"fatih-akay-2","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bitmeyen-yollar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İslamiyetin doğuşu', 'i-slamiyetin-dogusu-hasan-yilmaz-3-a491n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arap aleminin içi zulümdü, yolu karanlık,

Gönüller taş olmuştu, sönmüştü ışık.

Kurtuluş, bir mucizeye kalmıştı artık,

Bir nûr doğdu Mekkede, O cân geldi.

Yetim büyüdü, boynu bükük güldü,

İncitmedi kimseyi, kırmadı gönülü

"El-Emîn" dediler, hep doğruydu özü,

Cihâna taht kuran, o sultân geldi.

Her gün Hira’da inzivaya çekilirdi .

Yaradan aşkıyla hep yanardı yüreği.

Bir gün Cebrâil "Oku!" diye seslendi.

Karanlığı yırtan, o kutlu fermân geldi.

Hatice’si O’na inandı, candan sarıldı

Ebu Bekir, Ali, Rabb aşkına boyandı.

Hakkın dâveti bütün cihana yayıldı.

Tevhîd sancağıyla, kutlu kervân geldi.

Tâif yollarında taşlandı, yara aldı teni,

Kanı aktı, sustu yinede şikayet etmedi.

Rabb’in nuruyla dolmuştu bütün bedeni

Sabrın timsâli oldu, cana dermân geldi.

Bir gece Aksa’da arşa yol açıldı birden,

Mirâc’a çıktı, huzuruna çağırdı yaradan.

Beş vakit namazı getirdi o ulu sırdan,

Mü’minin mirâcı, gökten ihsân geldi.

Arafat düzünde, son kez seslendi,

"Emânetim Kur’ân"a sarılın dedi.

Bütün aleme insanlık dersi verdi.

Vedâ hutbesiyle, hakîki beyân geldi.

"Yüce yaradanına kavuştu cânı,

Gözyaşına boğdu, bütün cihânı.

Gönderelim O''na Salât ile selâmı.

Âlemlere rahmet, Muhammed Mustafâ geldi.

2026', 'Arap aleminin içi zulümdü, yolu karanlık, Gönüller taş olmuştu, sönmüştü ışık. Kurtuluş, bir mucizeye kalmıştı artık, Bir nûr doğdu Mekkede,...', ARRAY['Türk Edebiyatı','Şiir','Hasan Yılmaz 3']::text[], 8.5, '{"poet":"Hasan Yılmaz 3","poet_slug":"hasan-yilmaz-3","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/islamiyetin-dogusu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim ne derse desin', 'kim-ne-derse-desin-muhsin-yener-2-ucgzj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir söz düşer bazen
Taş duvarların ortasına
Ve bir çocuğun gözlerinde
Umut olur yeniden.

Kim ne derse desin
Kelimeler değiştirir dünyayı
Bir annenin duası gibi
Bir işçinin alın teri gibi
Bir mazlumun “yeter” diye haykırışı gibi.

Düşünce dediğin
Küçük bir kıvılcımdır önce
Sonra büyür
Vicdan olur
İsyan olur
Hakikatin alnına yazılmış mühür olur.

Ve insan
Bir güzel cümleyle bile
Yeniden ayağa kalkabilir.

Muhsin Yener', 'Bir söz düşer bazen Taş duvarların ortasına Ve bir çocuğun gözlerinde Umut olur yeniden. Kim ne derse desin Kelimeler değiştirir dünyayı Bir...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kim-ne-derse-desin-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Yaşamamış Gibi', 'hic-yasamamis-gibi-muhsin-yener-2-le1a7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'El âlemin ne dediğine göre yaşarsan,
o hayat senin değildir.

Sen,
doğru bildiğin yolda yürü.
Vicdanını dinle,
gönlünün sesini susturma.

Çünkü gün gelir,
bir ömür biter.

Öldüğünde...
Ne alkışlar kalır,
ne dedikodular,
ne de insanların bitmeyen yargıları.

Sadece seni gerçekten sevenler,
birkaç güzel anıyı yüreğinde taşır.

Sonra onlar da gider.

Ve zaman,
her izi yavaş yavaş siler.

Bu yüzden;
başkalarının istediği gibi değil,
kendin olarak yaşa.

Çünkü insanın geriye bıraktığı en büyük miras,
başkalarının onayı değil,
karakteridir.

Muhsin Yener', 'El âlemin ne dediğine göre yaşarsan, o hayat senin değildir. Sen, doğru bildiğin yolda yürü. Vicdanını dinle, gönlünün sesini susturma. Çünk...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hic-yasamamis-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birbirimizi sevmeyi başarabilseydik', 'birbirimizi-sevmeyi-basarabilseydik-muhsin-yener-2-89wbp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalplerimizin sıcaklığı yeterdi belki
Birbirimizi sevmeyi başarabilseydik
İnsan insana sürgün olmazdı
Yürekler bu kadar taş kesilmezdi.

Sevin komşunuzu, dostunuzu,
Bir kapı önünde bekleyen kediyi,
Yağmur altında titreyen köpeği,
Çünkü merhamet, insanın secdesidir.

Zalim insanı gönlünüzde büyütmeyin,
Çünkü kötülük; önce vicdanı öldürür.
Bir yaşlının elini tutun mesela,
Sessizliğinde asırlık dua saklıdır.

Rahmetli babam derdi ki:
“Sen bakınca burnunun ucunu görürsün evlat,
Ben baktığımda dağın ardını görürüm.”
O vakit anlamadığım bu söz,
Şimdi ömrümün duvarına çarpıyor.

Meğer tecrübe;
Saçlara düşen ak değilmiş yalnız,
İnsanın içine çöken hakikatmiş.

Ey gönül
Kendi karanlığında kaybolma artık,
Yüreğinin içindeki güzelliği gör.
Çünkü insan,
Sevebildiği kadar insandır.
Muhsin yener', 'Kalplerimizin sıcaklığı yeterdi belki Birbirimizi sevmeyi başarabilseydik İnsan insana sürgün olmazdı Yürekler bu kadar taş kesilmezdi. Sevi...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Yener 2']::text[], 8.5, '{"poet":"Muhsin Yener 2","poet_slug":"muhsin-yener-2","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/birbirimizi-sevmeyi-basarabilseydik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak İstedim Kendime', 'aglamak-i-stedim-kendime-nihat-celik-2-slw6i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben bir vitrinde cansız mankenim, konuşamam, seni göremem, sesini duyamam.

İnsanlar beni izlediklerinde duygularını, dokunduklarında hislerimi anlayamam.

Üzerimdeki elbiseler, vitrin, hayatımın bir yansıması.

Bir ruha ihtiyaç duydum her bakan gözlerde, her seste, dokunuşlarda...

Ağlamak istedim kendime, 

gözyaşlarına sahip değildim...

Mayıs 2023', 'Ben bir vitrinde cansız mankenim, konuşamam, seni göremem, sesini duyamam. İnsanlar beni izlediklerinde duygularını, dokunduklarında hisleri...', ARRAY['Türk Edebiyatı','Şiir','Nihat Çelik 2']::text[], 8.5, '{"poet":"Nihat Çelik 2","poet_slug":"nihat-celik-2","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/aglamak-istedim-kendime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aracı Mavracı', 'araci-mavraci-mustafa-bulan-1pdaw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vallahi sınır yok benzetmelerde

Trafolar kurup oldular aracı.

Kutup, şeyh, mehdi, gavs… adlar yerinde(!)

Tezgahı kurup oldular mavracı!

İman “Yüksek akım, yakar” diyerek,

Hep trafodan, eldivenden girerek,

“Çıplak elle olmaz, çarpar” diyerek

Aracı çıkıp oldular mavracı!

Onlar açtılar olmayan arayı,

Araya girip buldular arayı(!)

Şah damarından soktular zokayı!

Manayı satıp oldular mavracı!

Sünnet sünnet deyip kafa üterek,

Deveye değil Opel’e binerek,

El ele verip Sırat’tan geçerek

Cenneti satıp oldular mavracı!

Çok keramet varmış beşer Nebi’de,

Hep girdiler sofrasından sünnete,

Deve de yokmuş, keramet terlikte(!)

Umudu satıp oldular mavracı!

Pek anlatmadılar cömert Nebi’yi,

Anlattılar kan, kıl, tırnak sidiği,

Ve anlattılar saç, sakal, terliği…

Yalanı satıp oldular mavracı!

İbn Sinalar, Biruniler, Kindîler…

Bilimde zirve, çok büyük alimler!

Bilimde gerilerken Medreseler

Hurafe satıp oldular mavracı!

Batı önemserken bu alimleri

Bizimkiler onlara “Şeytan” dedi?

Kara kalem yazarken hurafeyi

Havadan uçup oldular mavracı!

Şair uyarmıştı, almadık dersler,

Hâlâ dillerde “Uyduruk herzeler”,

Haşa herzelere vahiy dediler,

Tezgahı kurup oldular mavracı!

Tüccarlık, mavracılık bir arada,

Hem yürümez olmasa bir arada,

Bulamoğlu sakın kalma arada,

Yanlışa susup oldular mavracı!

Pendik/05.05.2024', 'Vallahi sınır yok benzetmelerde Trafolar kurup oldular aracı. Kutup, şeyh, mehdi, gavs… adlar yerinde(!) Tezgahı kurup oldular mavracı! İman...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Bulan']::text[], 8.5, '{"poet":"Mustafa Bulan","poet_slug":"mustafa-bulan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/araci-mavraci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlığın Kendisiyiz', 'i-nsanligin-kendisiyiz-alper-tunga-3-t3ime', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Milyon ve belkide milyarda bir ihtimal yaşanıyor,

Normal şartlarda ve diğer hayatlar gibi değil,

Melankolik bir rus aklını kaybederdi

Romantik avrupalılar sayfalarca anlatırdı,

Başka bir kıtada filmi çekilebilir...

Biz insanlık tarihiyiz, biz ikimiz; insanlığız

İsmimiz büyük aşıkların ilk sırasına yazılmalı,

Tutkumuz aşkın, sevdanın tanımı ve sınırsızlığı

Biri bir yerde aşk derse...Sen ve ben

Bir yerde bir aşk varsa biz

Bu aşk denilen akıl hastalığı; sadece ikimiz

İkimizinde zihninin anlam veremediği bu hissiyat,

Bizi gri bir dünya tasviriyle aşkı yorumlatmak istiyor,

Bu hataya bende düşüyorum bazen, bazen kızıyor.

Bilinen dünya bu devasa aşkı tarif edemezken,

Durmak bilmeyen zihnimiz, bu tanımsız duyguyu

Sitem, endişe ve stres olarak kalbimize taşıyor.

Bir ses... Biliyorum, sesimi duysan çiçek acıyor,

Bende sesini duyunca huzur içindeyim, biliyorum.

Siliniyor bütün karanlığım, seninde böyle mi?

Sesinden ayrılık okuyamıyorum ben... Lütfen.

O kadar arzularım büyüdü, o kadar sana savruldum ki,

Bir ana dahi küskünüm, seni görmediğim.

Dizelere yetinmiyor yüreğim, sitemkâr.

Şahitsin, hayatın düğümleri dolanıyor hep,

Biz, hayata yenilemeyiz...Hadi dogrulalım.

İkimiz en büyük aşıklarıyız bu dünyanın,

Evrenin, bütün uzayın  ve yıldızların...

Aşk hiç var olmasa, biz onu bulurduk,

Biz ellerimizle var eder insanlığa sunardık.

İkimiz, insanlığın en masum haliyiz

Bu çağda, bu sevda... 

Böyle bir kara sevda

Kara toprakta biter

Umutlarını sev, hayallerimizi beni sevdiğin gibi,

Ben seni sevdiğim gibi ikinci bir ismi

Nergis''de bir ihtimal veya belki ikinci ismi', 'Milyon ve belkide milyarda bir ihtimal yaşanıyor, Normal şartlarda ve diğer hayatlar gibi değil, Melankolik bir rus aklını kaybederdi Romant...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga 3']::text[], 8.5, '{"poet":"Alper Tunga 3","poet_slug":"alper-tunga-3","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/insanligin-kendisiyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Kes Gibi', 'her-kes-gibi-nihat-celik-2-d76fp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sende diğerleri gibi çözdün beni,

zayıf tarafımı keşfettin,

bendeki korkunç kimsesizliği fark ettin,bendeki sonsuz sevgiyi hissettin,dışa yansımayan bir sevgiyi gördün ve dışa çıkartığın sevgini beklemedin.

*Ve  En çok severken terk ettiler sevenlerim beni.

Sevildiklerini bilerek terk etmek onları hoşnut ediyordu..

Anlatıyordum diyalektiğin tüm noktalarını kullanarak,anlatmaya çabalamam onları kurnaz bir iç gülüş ile mutlu ediyordu..

insanlar bana bakar iken, bu kadar nasıl saf nasıl olduğuma,şaşarak bakıyordu.

Bende onlara,

bu kadar nasıl kötü olabiliyorlar diye,

şaşarak bakıyordu

Mayıs 2023', 'Sende diğerleri gibi çözdün beni, zayıf tarafımı keşfettin, bendeki korkunç kimsesizliği fark ettin,bendeki sonsuz sevgiyi hissettin,dışa ya...', ARRAY['Türk Edebiyatı','Şiir','Nihat Çelik 2']::text[], 8.5, '{"poet":"Nihat Çelik 2","poet_slug":"nihat-celik-2","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/her-kes-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkese Adalet', 'herkese-adalet-ali-celik-3-umyxw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'HERKESE ADALET 

Âcizden istiyor, kul hacetini

Görmüyor Rabbinin, tüm hüccetini

Esbaba bağlıyor, kul necatını

Varlık âleminde, var mıdır esrâr?

İnsan yaşanandan, almalı dersi

Akılın önüne, geçirme hırsı

Nâdim, şeytanlara gösterir tersi 

Musîbet getirir, hâtâda ısrâr

Durum vahim olmuş, tedbir acele

Âyan beyan, anlatılır mesele 

Savsaklama, vuk''u bulur zelzele

Sıkıntıya sebep, geçikmiş karar 

Kibirliler, hiç bir zaman sevilmez

Vakit nakit, havanda su dövülmez 

Sövse nadan, yine ona sövülmez

Yapılan amelde, beklenir yarar

Suçu sabit olmuş, giymiş hükümü

Sıralanmış, delillerin dökümü 

Yap artık savunma, bırak kem kümü

Devletin malına, etmişsin izrâr

İkrâr pişmanlığın, sözle ifâsı

Hele olmamışsa, suçun defası

Kolay olur, bu durumda şifâsı

Tövbeye yakındır, suçunu ikrâr

Öneme binaen, alınır tedbir 

Suçtan âri değil, erkân, ekâbir 

Öncelikli cezâ, erkâna mucbir

Önce def edilir, umûma zarâr

Elbet verilmeli, suçun cezası 

Affın mağdurlara, olur ezası

Uygulamak gerek, kesin kısası 

Kanunu tezyiftir, işlenmiş tekrar', 'HERKESE ADALET  Âcizden istiyor, kul hacetini Görmüyor Rabbinin, tüm hüccetini Esbaba bağlıyor, kul necatını Varlık âleminde, var mıdır esrâ...', ARRAY['Türk Edebiyatı','Şiir','Ali Çelik 3']::text[], 8.5, '{"poet":"Ali Çelik 3","poet_slug":"ali-celik-3","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/herkese-adalet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uşak''ın Yemekleri', 'usak-in-yemekleri-yuksel-agalar-k1d1n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne güzel tarhana çorbası

Hastalıkları kovar acılısı

Her evde vardır mis kokusu

Uşak''ın meşhur tarhana çorbası

Yumurta sızdırması vardı

Ne güzel ciğerli bulgur pilavı

Döndürme Ulubey’de başka

Lokum gibi yaprak sarması

Eskilerden vardı Arap aşı

Şifalı ve kuvvetlidir keşkek

Düğün yemeğin de vardı 

Kuru bamya ve etli yemek

Alaca tene, kuru fasulye

Karnı kara derler börülceye

Zeytin yağlı olur taze fasulye

Pilavla ne hoş nohut yemeği 

Karnıyarık, imam bayıldı

Tas kebabı  zengine sayıldı

Et görmez kurudu güveçler

Kuzu çevirme tarihte kaldı

Kırmızı etin yerini aldı

Hormonlu, ilaçlı beyaz et

Nerede  o yaprak döner

Uzak kaldı sofralara iskender

Unutuldu emir tatlısı

Höşmerim, köpük helvası

Ekmekle yenirdi  tahin helvası

Şerbetli olur Cendere tatlısı

Bayramda cevizli baklava

Ne güzel olur tel kadayıfta

Haşhaşlı  revani var sırada 

Uşak şekeriyle yapılır aşkla

Hamur işidir börek,katmer

Bükme,peksimet,gözleme

Kıymalı ,peynirli,ıspanaklı

Pidesi  var istersen kuşbaşılı

Bazlama, yufka eskimez

Simit başkasına benzemez

Ekşi mayalı bereketli 

Hem Mende, Bozkuş ekmeği', 'Ne güzel tarhana çorbası Hastalıkları kovar acılısı Her evde vardır mis kokusu Uşak''ın meşhur tarhana çorbası Yumurta sızdırması vardı Ne gü...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Ağalar']::text[], 8.5, '{"poet":"Yüksel Ağalar","poet_slug":"yuksel-agalar","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/usak-in-yemekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benlik', 'benlik-nihat-celik-2-ub0lo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '``Sen sen isen,

sen kim değilsin?

Sen,sen değil isen.

Sen kimsin?...

Ben ben isem ,

sen kimsin.

Sen sen isen,ben kimim.

Haziran 2011

`', '``Sen sen isen, sen kim değilsin? Sen,sen değil isen. Sen kimsin?... Ben ben isem , sen kimsin. Sen sen isen,ben kimim. Haziran 2011 `...', ARRAY['Türk Edebiyatı','Şiir','Nihat Çelik 2']::text[], 8.5, '{"poet":"Nihat Çelik 2","poet_slug":"nihat-celik-2","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/senlik-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasip', 'nasip-alp-kaan-aksu-a5dui', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nasip olmaz biliyor gibiyim,
