INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mis-lerim', 'mis-lerim-yavuzcan-pinar-i8bhj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ben sizi affettim.

ben sizi altettim,

ben sizi affettim.

ben sizi yok ettim, 

his-lerim.

...

siz beni görmediniz 

siz beni duymadınız 

siz bir kere öpmediniz ki beni

siz beni sevmediniz

...

ben sizi affettim.

ben sizi altettim,

ben sizi affettim.

ben sizi yok ettim,

mis-lerim.

...

ben buydum da değişmedim.

ben konuştum da gizlemedim

ben anladım da söylemedim. 

siz beni hak etmediniz.

... 

ben sizi affettim.

ben sizi altettim,

ben sizi affettim.

ben sizi yok ettim, 

hiç-lerim.', 'ben sizi affettim. ben sizi altettim, ben sizi affettim. ben sizi yok ettim,  his-lerim. ... siz beni görmediniz  siz beni duymadınız  siz b...', ARRAY['Türk Edebiyatı','Şiir','Yavuzcan Pınar']::text[], 8.5, '{"poet":"Yavuzcan Pınar","poet_slug":"yavuzcan-pinar","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/mis-lerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Pare Sessizliğin Şerhi.', 'bir-pare-sessizligin-serhi-duhan-keskin-nz5ns', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabahı var mı?
Yâr karyolaya sığar mı?
Babasız evin çerçevesi var mı?
Moran suda albemoralar yaşar mı?
Cehl-i Mik''abın şerhi var mı?
Zat-ı şahanelerini yakından tanır mı,
Yusuf misali zindanlara atılır mı?
Şehrin zıttı ila benim farkımı yaşayanlar anlar mı?
Ve kısa sürede büyüyen göz bebeklerin beni olmuş sayar mı?
Yaşar mı tatlı suda tatsız balık?
Hayata imzamızı attığımız mürekkep elime bulaşır mı?
Veya hut kainatta olmasaydı bir düzen, zemheri göklerde tutunabilir miydi düzülen?
Düzgün ve üzülen bilmez mi bir pare göklerin sessizliğini?
Şartlı tahliyeler şartsız insanlığımızla takıştığında,
Dürtüsel adaletlerimiz de girecek mi
Mezara?
Sana dair ne varsa onları da Tanrım tarumar edecek mi, yoksa
Atmosfer rengi beyaz şarabımızla,
Ten gürültülerimizle
Varacak mıyız sona?', 'Sabahı var mı? Yâr karyolaya sığar mı? Babasız evin çerçevesi var mı? Moran suda albemoralar yaşar mı? Cehl-i Mik''abın şerhi var mı? Zat-ı ş...', ARRAY['Türk Edebiyatı','Şiir','Duhan Keskin']::text[], 8.5, '{"poet":"Duhan Keskin","poet_slug":"duhan-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-pare-sessizligin-serhi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok', 'yok-kenan-gezici-7lxsu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İki yitik ziyade zaman.

Bitik anlar işkencedir.

Karanlık dehliz.

Kırık aynalarda yansır gölgesi.

Pırıl pırıl gülüşlerin sahibi.

Ne hatıralar sana anlatacaktım.

Nefesim nefesin oluşunu.

Yüreğim avuçların içinde kalsın ses etme.

Bitir bu işkenceyi benden artık.

Kurur bu, bereketi yazık olur.

Her şeyi hissediyorum iliklerime kadar.

Nefes alamıyorum nefessizim.

Acı verir güzel günlerimin anısı.

Ben kendi cennetimin özlemindeyim.

En derin acım bu.

Benden alınanda bu.

Yok sığınakların limanı.

Kaldım en kabuslu günlerin içinde.

Işık da ses de şimdi yok.

Kenan GEZİCİ   15/11/2026', 'İki yitik ziyade zaman. Bitik anlar işkencedir. Karanlık dehliz. Kırık aynalarda yansır gölgesi. Pırıl pırıl gülüşlerin sahibi. Ne hatıralar...', ARRAY['Türk Edebiyatı','Şiir','Kenan Gezici']::text[], 8.5, '{"poet":"Kenan Gezici","poet_slug":"kenan-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yok-629-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülü unutma', 'gulu-unutma-selami-tiraslar-6vfqt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevildiğini bil haline şükret

Sevgiyi özleyen gülü unutma 

Derdini anlatan diline şükret

Genzinde gizleyen gülü unutma 

Kimisi süslenir övülmek için 

Kimi de kapısı dövülmek için 

Aylardır sadece sevilmek için 

Ateşi közleyen gülü unutma 

Çık gel yakından gör sorma yapımı 

Tarifle anlatmak bozar çapımı 

Akşam sabah zevkle gönül kapımı

Uzaktan izleyen gülü unutma 

Dostluğa sağımı aşka solumu 

Ne kalbimi boş koy nede kolumu

Tercihin yap yoksa bu kış yolumu 

Dört gözle gözleyen gülü unutma 

Bu güne bak artık bırak dününü

Benle geçir bu yıl doğum gününü

Aşk geliyor diye kapı önünü

Gururla düzleyen gülü unutma 

Selami Tıraşlar

15.11.2026', 'Sevildiğini bil haline şükret Sevgiyi özleyen gülü unutma  Derdini anlatan diline şükret Genzinde gizleyen gülü unutma  Kimisi süslenir övül...', ARRAY['Türk Edebiyatı','Şiir','Selami Tıraşlar']::text[], 8.5, '{"poet":"Selami Tıraşlar","poet_slug":"selami-tiraslar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gulu-unutma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Âlem ne derse desin', 'el-lem-ne-derse-desin-hakan-durhan-l6j7j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayan beyan seviyorum, gönlüm sana apaçık.

Öyle kuytu köşelerde saklanır mı hiç âşık?

Seni yanımda görenler çoktan bize alışık.

El âlem ne derse desin, ben seni seviyorum.

Gel, yanıma otur şöyle, dinleyeyim sözünü.

Omzumda başın dinlensin, kapat yorgun gözünü.

Sabah uyanır uyanmaz okşayayım yüzünü.

El âlem ne derse desin, ben seni seviyorum.

Elimden geldiği kadar hep kolluyorum seni.

Canıma can katarsın sen, bağrına bas, sar beni.

Yüzün gülsün yeter bana, istemem incinmeni.

El âlem ne derse desin, ben seni seviyorum.

Ne kalbimi gizlerim ben ne de saklarım seni.

Elini tuttuğum zaman mutlu görürsün beni.

Başımı öne eğmeden selamlarım göreni.

El âlem ne derse desin, ben seni seviyorum.

Hangi sofraya otursam sana yer ayırırım.

Güzel bir haber alınca ilk seni çağırırım.

Yorulduğun akşamlarda yükünü kaldırırım.

El âlem ne derse desin, ben seni seviyorum.

Bu sevdaya ayıp diyen hiçbir söze inanmam.

Bir sevgiyi saklamayı onu korumak sanmam.

Gözlerimi kaçırmam ben, sevmekten hiç utanmam.

El âlem ne derse desin, ben seni seviyorum.

Daha seni uğurlarken dönüşünü gözlerim.

Yerin boşken yarım kalır dilimdeki sözlerim.

Gün doğarken, gün batarken yine seni özlerim.

El âlem ne derse desin, ben seni seviyorum.

Gözyaşımın yetmediği yerde mısralar akar.

Yanağımda kalan yaşın tuzu tenimi yakar.

Her satırda gözlerin var, her kelimeden bakar.

El âlem ne derse desin, ben seni seviyorum.

Adını yazdığım sayfa duruyor ellerimde.

İçimden geçen ne varsa yazılı defterimde.

Sözüm yarıda kalsa da varsın dizelerimde.

El âlem ne derse desin, ben seni seviyorum.

Sana verdiğim bu sözü hiçbir gün geri almam.

Adın anıldığı yerde sessiz, sedasız kalmam.

Eller görmesin diyerek gece kapını çalmam.

El âlem ne derse desin, ben seni seviyorum.

Şiir : Hakan DURHAN', 'Ayan beyan seviyorum, gönlüm sana apaçık. Öyle kuytu köşelerde saklanır mı hiç âşık? Seni yanımda görenler çoktan bize alışık. El âlem ne de...', ARRAY['Türk Edebiyatı','Şiir','Hakan Durhan']::text[], 8.5, '{"poet":"Hakan Durhan","poet_slug":"hakan-durhan","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/el-alem-ne-derse-desin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adın Üç Hâli', 'adin-uc-h-li-es-ra-9szr5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adımı kalemin kamışına yazsınlar...

Yemyeşil bir rüyadan uyandırıp gövdemi

Yıllar süren sükûtun koynunda kurutsunlar.

Ben,

“Yedi boğumlu zindanında körelen...”

Bağrımı 

Bir çeliğin elleriyle oysunlar!

Aksın, 

Yağmur gibi simsiyah gözyaşları.

Acımı bandırsınlar.

Mim düşsün,

Dokunduğu her sathın sîmasına.

Bembeyaz bir sahraya savursunlar adımı

Adımı

Kalemin kamışında

Unutsunlar...

Adımı bir kuşun yuvasına yazsınlar...

İncecik dallardan diktiğim tüneğimi

Gökyüzüne en yakın uçuruma kursunlar.

Ben,

“Annesinin unuttuğu bir kabuk...”

Karanlığın sabaha çatladığı vakitte

Kanatlarımı doğmamış yavrulara taksınlar.

Yedi göğe birden ulaşsın haykırışım.

Adımı harf harf rüzgâra uçursunlar.

Adımı...

Arduvaz bir semada

Vursunlar!

Adımı bir bebeğin kundağına yazsınlar...

İpekten ipliklerle ördüğüm kefenimi

Masivanın en ücra köşesine atsınlar.

Ben,

“Bir damla su: nutfe ve alaka...”

Sırrımı merhametin ak sütüne katsınlar.

Taşsın pınarı masumiyetin.

Yaramı Rahman''ın adıyla dağlasınlar.

Ezan ile salâ arası üç kez 

Kulağıma okusunlar.

Adımı...

Bir bebeğin kundağında

Yeniden

Doğursunlar...

EsRa', 'Adımı kalemin kamışına yazsınlar... Yemyeşil bir rüyadan uyandırıp gövdemi Yıllar süren sükûtun koynunda kurutsunlar. Ben, “Yedi boğumlu zin...', ARRAY['Türk Edebiyatı','Şiir','Es Ra']::text[], 8.5, '{"poet":"Es Ra","poet_slug":"es-ra","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/adin-uc-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göğe Kırgın Bir Türün Hikayesi (kolera saati..', 'goge-kirgin-bir-turun-hikayesi-kolera-saati-i-slam-cakmak-t58zx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'GÖĞE KIRGIN BİR TÜRÜN HİKÂYESİ 

İnsan, kendini evrenin merkezine koyacak kadar kibirli,

bir avuç yıldız tozundan ibaret olduğunu unutacak kadar aciz.

Göğe bakıyor, bir cevap bekliyor.

Bazen küfrediyor, bazen diz çöküyor.

Ne garip bir ilişki bu;

hem sevdiğine küsecek kadar mağrur

hem de vazgeçemeyecek kadar muhtaç.

Belki insanın Tanrı''yla meselesi inanç değil, aşktır.

Biraz sitem, biraz hasret, biraz da kırgınlık.

Ulaşamadığı bir sevgiliye mektup yazar gibi

her gece aynı gökyüzüne içini döküyor.

Birileri açlıktan ölürken birileri servet biriktiriyor.

Birileri özgürlük ararken birileri zincir üretiyor.

Sonra adına medeniyet deyip göğsümüzü kabartıyoruz.

Ne garip, kendi felaketimize alkış tutuyoruz.

İnsan hem bir çocuğun gözyaşını silebilecek kadar merhametli,

hem de bir şehri haritadan silebilecek kadar vicdansız.

İçimizde tanrılarla canavarlar aynı masada oturuyor.

Kimi sevgiyi kutsuyor, kimi nefreti meslek edinmiş.

Kimi yaratıcısına kırgın,

kimi geçici bir tenin içinde bulmuş ebediyeti.

Evren gelişimizi beklemedi,

gidişimizle de yas tutmayacak.

Ama biz hâlâ bir çift gözde sonsuzluk,

bir duada merhamet arıyoruz.

Belki de bütün mesele budur:

İnsan, ulaşamayacağı şeylere âşık olacak kadar hayalperest,

kaybedeceğini bile bile sevecek kadar deli.

İnsanlığın en büyük devrimi, başka bir gezegeni fethetmek değil; kendi içindeki o piç kurusu canavarı tahttan indirmektir.

Çünkü insan bazen Tanrı''ya kızar, hayata söver, aşka yenilir.

Ama bütün bu cehennemin ortasında hâlâ sevmek ister.

Yaratıcısına kırgın, dünyaya yabancı, ölüme mahkûm bir varlığın hâlâ sevgi beklemesi...

İşte bu dünyanın en güzel ve en kahrolası çelişkisi.. 🖤', 'GÖĞE KIRGIN BİR TÜRÜN HİKÂYESİ  İnsan, kendini evrenin merkezine koyacak kadar kibirli, bir avuç yıldız tozundan ibaret olduğunu unutacak ka...', ARRAY['Türk Edebiyatı','Şiir','İslam Çakmak']::text[], 8.5, '{"poet":"İslam Çakmak","poet_slug":"i-slam-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/goge-kirgin-bir-turun-hikayesi-kolera-saati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasta', 'hasta-alp-kaan-aksu-vd4m5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasta ruhunun dahi farkında değilsin,
Tedavi olmak nedir bunu dahi bilmezsin.
Üstüne üstlük dünya evine girersin,
Yaptığına bir ortak bul da seni evlendirsin.', 'Hasta ruhunun dahi farkında değilsin, Tedavi olmak nedir bunu dahi bilmezsin. Üstüne üstlük dünya evine girersin, Yaptığına bir ortak bul da...', ARRAY['Türk Edebiyatı','Şiir','Alp Kaan Aksu']::text[], 8.5, '{"poet":"Alp Kaan Aksu","poet_slug":"alp-kaan-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hasta-103-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acizin ipi', 'acizin-ipi-kahraman-metin-lthag', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'uzun süren suyunla

ağız karası belasın

kusulmayacak kadar

zahmete değmez

midemde işlenmeyecek kadar

değersizsin

yarın, ipini bolluklarla

doladığın boynun gibi

ince ve yakın!

güya güneşe uzaksın ama, 

aciz kız şeytanın boynuna

dolanmış namazınla

yakınsın', 'uzun süren suyunla ağız karası belasın kusulmayacak kadar zahmete değmez midemde işlenmeyecek kadar değersizsin yarın, ipini bolluklarla dol...', ARRAY['Türk Edebiyatı','Şiir','Kahraman Metin']::text[], 8.5, '{"poet":"Kahraman Metin","poet_slug":"kahraman-metin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/acizin-ipi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berbatsın!', 'berbatsin-kahraman-metin-bkhrm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'berbatsın! gözün körlerin bile

ayna karşısında nefret edeceği kadar koyu,

bu kadar koyu bir gözle

insan içine nasıl çıkarsın?

utanmalısın! kusurlarınla var olduğuna

inanamazsın.

Salaklığın yüzünden öldüğün gibi

dönüşün olamayacağını fark etmemen kadar

aptallığınla bir hiçsin.

krallar bile diz çöker

iğdam için mahkumu', 'berbatsın! gözün körlerin bile ayna karşısında nefret edeceği kadar koyu, bu kadar koyu bir gözle insan içine nasıl çıkarsın? utanmalısın! k...', ARRAY['Türk Edebiyatı','Şiir','Kahraman Metin']::text[], 8.5, '{"poet":"Kahraman Metin","poet_slug":"kahraman-metin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/berbatsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandırma', 'kandirma-alp-kaan-aksu-ce4su', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kandırma kendini herşey mükemmel diye,
Başından yanlış olan ulaşır mı hedefe?
Neden bilinç varken haddi aşarsın,
Problemi hala dışarıda ararsın.', 'Kandırma kendini herşey mükemmel diye, Başından yanlış olan ulaşır mı hedefe? Neden bilinç varken haddi aşarsın, Problemi hala dışarıda arar...', ARRAY['Türk Edebiyatı','Şiir','Alp Kaan Aksu']::text[], 8.5, '{"poet":"Alp Kaan Aksu","poet_slug":"alp-kaan-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kandirma-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytanın vaadi.', 'seytanin-vaadi-kahraman-metin-qdm07', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölüyorum! acılar içinde

kalbimin fitilini

duvara çiviyle çakan

aşk yüzünden ölüyorum

şeytanın en güvenilir

dostu olan, insanı

en güzel vaatmiş gibi

dolandıran aşk yüzünden

ölüyorum! kalbimin sesini

dinlemeye tahammülüm yok

ve tuhaf bir şekilde

hiçbir şeyden korkmuyorum!

Ben gidiyorum; cehenneme

gidiyorum kazanın tövbeyle

affedilmediği yere, yer yüzünün

tanrısı Rabbin bile unuttuğu

kötülüklerin doğduğu

o eve, gidiyorum!', 'Ölüyorum! acılar içinde kalbimin fitilini duvara çiviyle çakan aşk yüzünden ölüyorum şeytanın en güvenilir dostu olan, insanı en güzel vaatm...', ARRAY['Türk Edebiyatı','Şiir','Kahraman Metin']::text[], 8.5, '{"poet":"Kahraman Metin","poet_slug":"kahraman-metin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seytanin-vaadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lafügüzaf/içerisinde Bolca Anlat Var', 'lafuguzaf-icerisinde-bolca-anlat-var-maltepeli-kutay-mhgnw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana yalnızım deme 

Yalnızlığı anlat 

Bana kırıldım deme, kalp kırıklığının

Yankısını, tesirini anlat 

Umudunu söyleme

Karda, kışta çiçek açan 

Kardeleni anlat 

Öfkeni söyleme 

Öfkenin sonrası yaşanan

Ölüm sessizliğini 

Anlat

Bana limandan ayrılmayı değil 

Kıyıda duran halatı anlat

Fincandaki kahveyi değil 

Fincanın kırılan kulbunu anlat 

Bana evdeki perdeleri değil 

Pencereden bakanın 

Hikayesini 

Anlat', 'Bana yalnızım deme  Yalnızlığı anlat  Bana kırıldım deme, kalp kırıklığının Yankısını, tesirini anlat  Umudunu söyleme Karda, kışta çiçek aç...', ARRAY['Türk Edebiyatı','Şiir','Maltepeli Kutay']::text[], 8.5, '{"poet":"Maltepeli Kutay","poet_slug":"maltepeli-kutay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/lafuguzaf-icerisinde-bolca-anlat-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derya ile Sözleşmek', 'derya-ile-sozlesmek-i-shak-koseoglu-fcfgc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akşam oluyor yine.

Her zamanki gibi ahşap kulübemin kapısını çekip çıkıyorum.

 Önümde dolambaçlı bir yol uzanıyor;

 inişleriyle çıkışlarıyla,

 taşları yılların yorgunluğunu sırtlamış.

Hava ağır.

 Yağmur yağacakmış da vazgeçmiş gibi.

 Gökyüzü nefes aldırmıyor.

Elimde yarım kalmış bir sigara,

 ayaklarım ezberlediği yolu benden önce biliyor.

 Ben yürümüyorum sanki,

 sahil beni kendine çağırıyor.

Derya görününce uzaktan

 içimde bir şey çözülüyor.

Bedenim canlanan suların ritminde sallanırken

 her zamanki taşın üstüne oturuyorum.

 Karşımda günü omuzlarında taşıyan güneş,

 yavaş yavaş ufka gömülüyor.

Bakıyorum.

Öyle uzun bakıyorum ki...

Bir ara gözlerim güneşte kayboluyor,

 bir ara düşüncelerimde.

Beni kendime getiren yine dalgalar oluyor.

 Kayalara çarpıp parçalanan sesleriyle

 omzuma dokunur gibi dürtüyorlar beni.

Sonra susuyorum.

Deniz konuşuyor.

Kimi zaman içimdeki taşlar ağırlaşıp dibe çöküyor,

 kimi zaman savrulup dalgalara karışıyor.

 Adını koyamadığım duyguların hepsi

 birer köpük olup uzaklaşıyor kıyımdan.

O anların huzurunu anlatamam.

Sanki dünya biraz uzağa çekiliyor da

 ben hayatın gürültüsünden kurtuluyorum.

Aklımdan bütün insanlar geçip gidiyor,

 bütün hesaplar, bütün yarım kalmışlıklar...

Geriye yalnızca

 denizin bitmeyen senfonisi kalıyor.

Saatlerce bakışıyoruz onunla.

Ben derdimi anlatmıyorum,

 o zaten biliyor.

Sessizliğimden okuyor içimi.

Kimi gün kaybettiklerimi bırakıyorum önüne,

 kimi gün sevinçlerimi.

O da her seferinde

 aynı sabırla dinliyor.

Bir dost gibi...

Bir sırdaş gibi...

Bir ömürlük yoldaş gibi...

Gece çökerken ayrılık vakti geliyor.

Ayağa kalkıyorum.

Son bir kez dönüp bakıyorum deryaya.

O dalgalarını gönderiyor ardımdan,

 ben gözlerimi bırakıyorum onda.

Sonra sessizce sözleşiyoruz:

Yarın yine geleceğim.

Çünkü ne ben onsuz tamamım,

 ne o bensiz eksik.

Ama ikimiz de biliyoruz ki

 bu dünyada beni en iyi anlayan şey,

 kıyıya vuran o eski deniz sesi.', 'Akşam oluyor yine. Her zamanki gibi ahşap kulübemin kapısını çekip çıkıyorum.  Önümde dolambaçlı bir yol uzanıyor;  inişleriyle çıkışlarıyla...', ARRAY['Türk Edebiyatı','Şiir','İshak Köseoğlu']::text[], 8.5, '{"poet":"İshak Köseoğlu","poet_slug":"i-shak-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/derya-ile-sozlesmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizliden sevmek de neymiş', 'gizliden-sevmek-de-neymis-suleyman-ozguven-t3r46', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'GİZLİDEN SEVMEK DE NEYMİŞ!

Gizliden sevmek de neymiş be gönül!

Delikanlı adam sevdi mi saklamaz sevgisini, çıkar karşısına sevdiğinin, gözlerinin içine bakarak söyler sevdiğini.

Öyle köşe bucak saklanmaz, üç beş kişinin ne diyeceğini düşünerek sevgisinden utanmaz.

Seviyorsa avazı çıktığı kadar haykırır, ben bu kadını seviyorum diye.

Ne el âlemin sözü korkutur onu ne de insanların yargısı.

Çünkü adam gibi seven, sevdiğini yüreğinde saklar ama sevgisini kimseden saklamaz.

Adını anarken başını öne eğmez, aksine göğsünü gere gere söyler.

Benim sevdam der, benim gönlümün sahibi der, benim en güzel duam der.

Zira gerçek sevda gizlenmekten değil, sevdiğiyle gurur duymaktan beslenir.

Delikanlı adam sevdi mi, susarak değil; yüreğiyle, sözüyle, özüyle sever.', 'GİZLİDEN SEVMEK DE NEYMİŞ! Gizliden sevmek de neymiş be gönül! Delikanlı adam sevdi mi saklamaz sevgisini, çıkar karşısına sevdiğinin, gözle...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Özgüven']::text[], 8.5, '{"poet":"Süleyman Özgüven","poet_slug":"suleyman-ozguven","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gizliden-sevmek-de-neymis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lodos Vurgunu - 2', 'lodos-vurgunu-2-jet-murat-yucel-b9q79', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seneler seneler geçti

O “lodos vurgunu”nun üstünden

Ne o deniz aynı kaldı

Ne ben o günkü ben

Takılı kalsam da

Yalnızlığın ağlarında bir vakit

Duruldu o deniz

Şimdi biliyorum

Her fırtına yıkmaz insanı

Bazısı öğretir susmayı

Kendi kıyını bulmayı

O lodos çoktan dindi de

Tuzu kaldı tenimde

Kalbimin attığı her ritimde

Bir eski şarkı gibi

Hâlâ çalar gecenin bir yerinde.

Ne seni suçluyorum artık

Ne de sorular soruyorum kendime.

Bazı sevdalar tamamlanmadan

Ömürden geçip gidermiş.

Yıllar sonra anlıyorum ki

Bazı yollar yarım kalırmış

Kaybettiğini sandığın şeyler

Aslında kendini bulduğun anlarmış.', 'Seneler seneler geçti O “lodos vurgunu”nun üstünden Ne o deniz aynı kaldı Ne ben o günkü ben Takılı kalsam da Yalnızlığın ağlarında bir vaki...', ARRAY['Türk Edebiyatı','Şiir','Jet Murat Yücel']::text[], 8.5, '{"poet":"Jet Murat Yücel","poet_slug":"jet-murat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/lodos-vurgunu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lodos Vurgunu - 1', 'lodos-vurgunu-1-jet-murat-yucel-qn3ts', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Takıldın yine ağlarına sevdanın

Nereden çıktı bu fırtına

Nereden düştün

O zümrütten gözlerin derinliklerine

İçini ısıtan birkaç güzel söze kandın

Zamansız bir “lodos vurgunu” daha yedin.

Oysa sen özgürdün bir uçtan bir uca

Açık denizler senindi

İstediğin gibi dalabilirdin enginlere

Gömebilirdin yorgun kalbini

Yalnızlığın serin sularına

Şimdi sen vurgun yemiş

Yaralı bir balığı andırmaktasın

Yalnızlığın ağlarında.', 'Takıldın yine ağlarına sevdanın Nereden çıktı bu fırtına Nereden düştün O zümrütten gözlerin derinliklerine İçini ısıtan birkaç güzel söze k...', ARRAY['Türk Edebiyatı','Şiir','Jet Murat Yücel']::text[], 8.5, '{"poet":"Jet Murat Yücel","poet_slug":"jet-murat-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/lodos-vurgunu-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Zamanların', 'bir-zamanlarin-emir-acikgoz-5n6hc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben bir zamanların şairiydim,

seni yazardım satırlarda,

sen bir zamanların şiiriydin,

hece hece dönen akıllarda.

Ben bir zamanların yolcusuydum,

cesaret isteyen yollarda,

sen varılmayan bir duraktın,

uçsuz bucaksız satıhlarda.

Ben bir zamanların seveniydim,

neşeli bir rüzgardım saçlarında,

sen bir zamanların sevileniydin,

nazlı bir çocuğun edasında.

Biz bir zamanların gecesiydik,

parlaşırdık hislerimizin ışığıyla,

sen doğan güneş, ben batan ay''dım,

paylaşırdık gökyüzünü aramızda.

Artık ne sen şiir ne ben şair,

ne ben seven ne sen sevilen,

ne sen beklenen, ne ben bekleyen,

artık ne biz varız, ne de bizden bir iz.', 'Ben bir zamanların şairiydim, seni yazardım satırlarda, sen bir zamanların şiiriydin, hece hece dönen akıllarda. Ben bir zamanların yolcusuy...', ARRAY['Türk Edebiyatı','Şiir','Emir Açıkgöz']::text[], 8.5, '{"poet":"Emir Açıkgöz","poet_slug":"emir-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-zamanlarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vedalara Bulaşmayalım', 'vedalara-bulasmayalim-alper-tunga-3-yo42h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gelirim hemen senin ardından, aynı saat, aynı gün.

yaşamak bizi aynı evde buluşturmazsa gelirim.

mahşer için, o buluşmada bulurum seni inan bana,

hakkımı helal bile etmem, orada karşılaşmak için.

çünkü orada tekrar soracaklar. sende bilirsin.

ben, senin canını yakmak istemedim.

kendi hassasiyetimi belirtmek istedim sadece

senin sevgin beni, kollarında saklayacak kadar büyük,

ne olur kollarından beni ayırma hiç, bunu böyle bil.

günlerdir, yüzünü ezberliyorum seviyorum.

kıskançlığım beni mağlup etti, bu kadar kızma...

o sevimli halini inan, minik minik seviyordum.

bir aralıkta merak ettim işte ve sonrası

sen, bütün gizli arzularımın birleştiği kadınsın,

gözlerinden dudaklarına kadar ve saçlarına

ruhunun naifliğinden, kelimelerinin keskinliğine kadar.

seni üzmek istemeyeceğimi sende biliyorsun,

ne olur siz gözlerini, gözlerini kocaman öpmek istiyorum.

şu mekana ve zamana yayılan inatlarımızı bırakalım.

ben, sen okumuyorsun diye çok kırılıyordum.

biraz teşvik olamadığımda bir gerçek...

seni suçlamıyorum, inan bana bir kırgınlık işte...

şu kırgınlığı ne olur bağışlayalım içimizde,

vedaların dilinden arındıralım kendimizi

ne olur, vedalara bulaşmayalım, kurtaralım kendimizi', 'gelirim hemen senin ardından, aynı saat, aynı gün. yaşamak bizi aynı evde buluşturmazsa gelirim. mahşer için, o buluşmada bulurum seni inan ...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga 3']::text[], 8.5, '{"poet":"Alper Tunga 3","poet_slug":"alper-tunga-3","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/vedalara-bulasmayalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimin Ölmesi Gerek', 'kalbimin-olmesi-gerek-i-shak-koseoglu-lx0ad', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Doğarken içime bir mum bıraktın,

 kimse görmedi.

 Ben bile ne zaman yandığını anlamadım.

 Bir baktım, gecelerimin ortasında

 adın kadar sessiz,

 yokluğun kadar inatçı bir ışık büyüyor.

Yıllar geçti.

Yüzüm değişti, sesim değişti,

 aynaya bakan çocuk eskidi.

 Ama o ilk kıvılcım,

 sanki zamanın geçmediği bir yerde kaldı.

Ne kadar kış gördüysem üstümden,

 hep sana çıkan bir sıcaklık buldu içimde.

Ölsem de söneceğini sanmıyorum.

Toprak tenimi alabilir,

 rüzgâr ismimi silebilir.

 Ama sana değen tarafımın nasıl öleceğini bilmiyorum.

Çünkü seni bir gün sevmedim sadece,

 seni hayatıma karıştırdım.

Suya karışan boya gibi değil,

 kana karışan nefes gibi.

Şimdi seni söküp atmaya kalksalar,

 yarınlarımdan bir parça gider.

 Hatıralarımdan değil,

 benliğimden eksilir bir şeyler.

Kalbimin ölmesi gerek içimde kaybolman için.

Öyle uzaklaşmakla olmaz.

 Bir daha görüşmemekle olmaz.

 Yılların üstünden geçmesiyle de olmaz.

Kalbimin durması,

 damarlarımın seni taşımaktan vazgeçmesi gerekir.

Aklımın bir kuş olup uçması gerekir,

 gittiği göğü unutması.

 Hatırlamanın ne demek olduğunu bilmediği

 başka bir ömre göçmesi gerekir.

Yoksa bir ses duyarım, sen çıkarsın.

 Bir sokağa girerim, sen geçersin.

 Bir rüzgâr eser, saçların gelir.

 Bir yağmur düşer, gözlerin konuşur.

İnsan bazen unutmak istemez aslında.

Sadece canı daha az yansın ister.

Ben de çok denedim.

Adını susturdum,

 hatıranı değil.

Gözlerini anmamaya çalıştım,

 özlemini değil.

Sonra anladım;

Sen artık bir anı değilsin.

Bir anı unutulur.

Sen, unutmaya çalışan tarafın içine yerleşmişsin.

Bu yüzden korkmuyorum zamandan.

Çünkü zaman eskitir,

 ama bazı insanlar eskimez.

Hayatımıza girmez onlar,

 hayatın kendisine karışırlar.

Ve sen...

Bir gün yoluma çıkmış biri değilsin.

Benim içimde hâlâ yanan,

 kimin yaktığını unutmadığım

 o ilk ateşsin.', 'Doğarken içime bir mum bıraktın,  kimse görmedi.  Ben bile ne zaman yandığını anlamadım.  Bir baktım, gecelerimin ortasında  adın kadar sess...', ARRAY['Türk Edebiyatı','Şiir','İshak Köseoğlu']::text[], 8.5, '{"poet":"İshak Köseoğlu","poet_slug":"i-shak-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/kalbimin-olmesi-gerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hem Suyum Hem Boğuluşum', 'hem-suyum-hem-bogulusum-i-shak-koseoglu-bbdjb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Suda balık gibiyim,

 Yokluğunda nefesim eksik,

 Varlığında ise sarhoş.

 Bir damla gözlerine düşsem,

 Kendimi unutacak kadar kaybolurum.

Yolunu şaşırmış bir avareyim belki,

 Belki de aşkın haritalarında adı silinmiş bir yolcu.

 Ne gidecek başka bir kıyı biliyorum,

 Ne de senden başka bir liman.

En aşka yabancı yüreğim derdim kendime,

 Meğer senden önce hiç sevmemişim.

 Kalbim duvar sanmış kendini yıllarca,

 Sen gelince öğrendi kapı olmayı.

Şimdi ne sensiz yaşayabiliyor bedenim,

 Ne de sana doymayı biliyor ruhum.

 Yokluğunda susuz kalan bir denizim,

 Varlığında taşan bir nehir.

Sen gelince dünya başımdan geçer,

 Sen gidince zaman yerinde donar.

 Bir sana yaklaşırım kendimi kaybederim,

 Bir senden uzaklaşırım kendimi bulamam.

Belki de bütün mesele budur;

 Ne tamamen bende kalabilmek,

 Ne de tamamen sende kaybolmak.

 İki kıyı arasında çırpınan bir balık gibi,

 Hem suyum sensin,

 Hem boğuluşum.', 'Suda balık gibiyim,  Yokluğunda nefesim eksik,  Varlığında ise sarhoş.  Bir damla gözlerine düşsem,  Kendimi unutacak kadar kaybolurum. Yolu...', ARRAY['Türk Edebiyatı','Şiir','İshak Köseoğlu']::text[], 8.5, '{"poet":"İshak Köseoğlu","poet_slug":"i-shak-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hem-suyum-hem-bogulusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kadar Çok Sevmiyormuşsun?', 'ne-kadar-cok-sevmiyormussun-maltepeli-kutay-joeb4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kurtarıcı aramıyorum artık 

Elimi tutup göğe çıkaracak 

Çöllenmiş yüreğime 

Hayat suyu olacak 

Bir kurtarıcı aramıyorum artık 

Ahı gitmiş vahı kalmış halime

Geçici duraklara yer yok artık 

Bir kurtarıcı aramıyorum artık 

Hiçbir şeyin önemi yok 

Dünün, bugünün, yarınının

Gelsen ne olur gelmesen ne 

Kapımı çalsan ne olur çalmasan

Sana ihtiyacım yok artık 

Sorma 

Merhem olamazsın ki yarama 

Seni ne anarım ne de sorarım artık 

Şimdi beni dinle: Bu sana son veda 

Kurtarıcı aramıyorum artık', 'Bir kurtarıcı aramıyorum artık  Elimi tutup göğe çıkaracak  Çöllenmiş yüreğime  Hayat suyu olacak  Bir kurtarıcı aramıyorum artık  Ahı gitmi...', ARRAY['Türk Edebiyatı','Şiir','Maltepeli Kutay']::text[], 8.5, '{"poet":"Maltepeli Kutay","poet_slug":"maltepeli-kutay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ne-kadar-cok-sevmiyormussun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın Kürek Mahkumu', 'sevdanin-kurek-mahkumu-i-shak-koseoglu-hi9d0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben sevdanın kürek mahkûmuyum,

 Yol uzun, hayat kısa.

 Bu koca deryada neye sürüklenecektim,

 Eğer sana çıkan akıntılar olmasaydı?

Her darbe küreğe değil,

 Biraz daha sana varma ümidine vurulur.

 Çünkü mahkûmu diri tutan ekmek değil her zaman,

 Bazen bir hayaldir,

 Bazen uzakta bekleyen bir çift göz,

 Bazen de adını taşıyan bir kıyı.

Beni ayakta tutan da sensin,

 Göğsümde çarpan sabır da.

 Deryanın içinden yükselen bir ses gibi çağırırsın beni,

 Hem güzel bir kıyı gibi sessiz,

 Hem fırtına gibi sert ve sarsıcı.

Rüzgârın yönü seslerinde gizlidir,

 Dalgalar ismini taşır kıyılara.

 Tüm balıklar şahittir,

 Bu denizde attığım her kulaç,

 Aslında sana doğru çekilen bir hasretin izidir.

Sevdanın çetrefilli yollarında yürürken,

 Kıskanmasın doğa seni benden.

 Güneş ışığını eksik etsin istemem yüzünden,

 Rüzgâr saçlarına dokunurken bile kıskanır yüreğim.

 Ne kalbimden alsın seni zaman,

 Ne deryadan silsin sesini yıllar.

Ömür boyu kürek mahkûmu olsam da,

 Pas tutsun zincirlerim,

 Eskisin ellerim,

 Yorulsun omuzlarım,

 Ama kader etmesin beni senden ayrı.

Varsın ömrümün sonuna kadar aynı denizde çekeyim küreği,

 Varsın ufuk hiç yaklaşmasın,

 Yeter ki her dalganın ardında sen ol,

 Yeter ki her akşamın karanlığında adın yansısın suya.

Çünkü özgürlük dediğin nedir ki?

 Ben çoktan senden yana tutsak olmuşum.', 'Ben sevdanın kürek mahkûmuyum,  Yol uzun, hayat kısa.  Bu koca deryada neye sürüklenecektim,  Eğer sana çıkan akıntılar olmasaydı? Her darbe...', ARRAY['Türk Edebiyatı','Şiir','İshak Köseoğlu']::text[], 8.5, '{"poet":"İshak Köseoğlu","poet_slug":"i-shak-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sevdanin-kurek-mahkumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-orpheus-ve-eurydike-us6rp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elveda

Ne menem şey bu elveda

El vedası mı

El ve sonrası dağ mı

Ne olursa olsun

Kabim elimde kalıyor

Giden de olsam

Kalan da

Ayrılıktan gayrısı

Elveda şarkısı', 'Elveda Ne menem şey bu elveda El vedası mı El ve sonrası dağ mı Ne olursa olsun Kabim elimde kalıyor Giden de olsam Kalan da Ayrılıktan gayr...', ARRAY['Türk Edebiyatı','Şiir','Orpheus Ve Eurydike']::text[], 8.5, '{"poet":"Orpheus Ve Eurydike","poet_slug":"orpheus-ve-eurydike","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/elveda-161-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandan Kaleler', 'kandan-kaleler-i-shak-koseoglu-jm7ci', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbime kandan kaleler yaptım,

 Duvarlarını özlemimle ördüm,

 Burçlarına umutlarımı diktim,

 İçinde yaşayan prenses de sendin,

 Avlusundan geçen hayat da sen...

Damarlarımda yürüyen heyecanın sebebi sen,

 Göğsümde çarpan telaşın adı sen,

 Bir gülüşünle taşan nehirler de sen,

 O nehirlerin sürüklediği kıyılar da...

Sanırdım seni seviyorum diye böyleyim,

 Sonra anladım;

 Sevda da sensin,

 Sevdanın bıraktığı iz de.

 Yangını yakan da sensin,

 O ateşte beni ısıtan da.

Kalbimde kurduğum her şehir sana açılıyor,

 Her sokak senin adına çıkıyor,

 Kapılarını çaldığım bütün düşler,

 Yine senin sesinle aralanıyor.

Meğer yalnızca kalbimde değilmiş yerin,

 Beni sana çeviren her duyguda da sen varmışsın.

 Çünkü seni değil sadece,

 Sende bıraktığım beni de sevmişim.', 'Kalbime kandan kaleler yaptım,  Duvarlarını özlemimle ördüm,  Burçlarına umutlarımı diktim,  İçinde yaşayan prenses de sendin,  Avlusundan g...', ARRAY['Türk Edebiyatı','Şiir','İshak Köseoğlu']::text[], 8.5, '{"poet":"İshak Köseoğlu","poet_slug":"i-shak-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kandan-kaleler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelimelerin Yetmediği Yerdesin', 'kelimelerin-yetmedigi-yerdesin-i-shak-koseoglu-uo75c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni her mısraya dökmeye çalıştığımda aklım karışır,

 Düşünceler birbirine dolaşır, kelimeler yönünü şaşırır.

 Başımdan gider bütün tarifler,

 Çünkü seni anlatmaya kalkınca kalbim dilimden önce konuşur.

Say say bitmez güzelliğin,

 Kalbimden taştığı gibi taşar dudaklarımdan adın.

 O kadar çoksun ki içimde,

 Saydıklarımın yarısını unuturum daha söylerken.

 Her hatırlayış yeni bir seni doğurur,

 Her unutuş bir başka güzelliğini saklar derinlerde.

Ne kelimeler yeter sana,

 Ne de zamana sığar hikâyen.

 Hangi tarifin ucunu tutsam,

 Gelir sana çıkar yolları.

 Her tanım yarım kalır yanında,

 Çünkü sen sonu olmayan bir cümle gibisin.

Her saydığım özelliğin kıskanır seni,

 Birbirleriyle yarışır varlığına yaklaşabilmek için.

 Gözlerinin yanında gülüşün susar,

 Gülüşünün yanında yüreğin mahcup olur,

 Yüreğinin yanında merhametin,

 Merhametinin yanında sabrın eksik hisseder kendini.

Sen varsın diye can bulur benzetmeler,

 Sen varsın diye çiçekler baharı anlatır,

 Denizler maviyi öğrenir ufuklardan,

 Rüzgârlar yönünü bulur saçlarının gölgesinde.

Hayat gibi akarsın hem dizeden hem gönülden,

 Bir nehir gibi değil,

 Sanki bütün nehirlerin varmak istediği deniz gibi.

 Gören göze tarif olursun,

 Bakan kalbe umut olursun,

 Ama körelmiş gözlere sıradan görünmezsin,

 Çünkü seni görmek bakmakla değil,

 Biraz sevmekle mümkündür.

Ve ben ne zaman seni anlatmaya kalksam,

 Yine eksik bırakırım içimde bir yerleri.

 Çünkü seni anlatmak,

 Gökyüzünü avuçlara sığdırmaya benzer.

 Ne kadarını göstersem az,

 Ne kadarını söylesem yarım kalır.

 Sen anlatıldıkça büyüyen,

 Sustukça derinleşen,

 Sevildikçe çoğalan bir tarifsizliksin', 'Seni her mısraya dökmeye çalıştığımda aklım karışır,  Düşünceler birbirine dolaşır, kelimeler yönünü şaşırır.  Başımdan gider bütün tarifler...', ARRAY['Türk Edebiyatı','Şiir','İshak Köseoğlu']::text[], 8.5, '{"poet":"İshak Köseoğlu","poet_slug":"i-shak-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/kelimelerin-yetmedigi-yerdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Çocuğum Ben', 'o-cocugum-ben-alper-tunga-3-6ctor', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir şeye veda edelim, seni asla üzmemeye

ne olur ben taşta taşısam, suyunu da sıksam.

hep yanaklarına kelebek gibi konarım.

ikimiz bir olup seni üzmeyelim olur mu?

ama önce sen kendini artık...Lütfen üzülme

seni çok sevdiğimi söyle bütün aynalara

ne olur yanımda ol, izlerini esirgeme hiç

ben, hayatın içinde yenilmedim bir gün bile

gecelere yenildim, bir izine rastlamadım diye

sen, ben varken kimsesiz değilsin,

ben ise sen varken devasayım.

eski halimize dönelim birlikte el ele

söylediklerimizi, inatlarımızı unutalım.

ben, senin yokluğuna hiç alışamadım ki...

ben zaten sensizde yaşayamadım, yaşamadım.

portakal neneyi anlattım diye mi o renk

hepsini anlatırım ben inan bana

yemin ediyorum, bu yemin gözlerin için

çünkü, benim kutsalım tamamen senin gözlerin.

bu yüzden gözlerini kıskandım,

bu yüzden aklımı kaybeder gibi oldum.

gözlerine yemin ederim ki...

seni sevmekten bir gün bile vazgeçmedim.

bir yıldırım gibi karşıma dikildiğin günden bu güne

ben, sana ait olduğumu yaşayıp öğrendim.

sensiz bir yaşamın mümkün olmadığını bilerek geldim.

benim boyum kısa, aklımsa kıt biraz

seni sevip sayıklayacak kadar büyüyebildim.

hissettim, yetişmeye çalıştım... Ne olur

senin karşında ve avuçlarında miniciğim.

hep söylüyorum, beni sen var edip, nefes verdin.

bir önceki sesin gibi gür ve güçlü olmalısın.

senin başını eğdiğin yerde ben varım.

çünkü ben hep senin karşında diz çökmüş haldeyim.

bu, gizli bir arzuya ait bir itiraf asla değil,

ruhumdan gelen bir tutku ve sadakat

seni geçmişte ve gelecekte çok seviyorum.

senden başkasına atmayan bir kalp bu sesin sahibi

bu ses, zaman algısını yitirmiş bir adamın sesi

bu ses, o ilk günü her gün yaşayan biri

ben hala senin o pencereden baktığın çocuğum.

seni görünce donup kaldığımı hatırlıyorsan eğer,

ben o sınıfta, o pencerede kilitli kaldım

ne olur, dizlerine yazdım kendimi ve sarıldım.

affet ne olur, ne olur gitme, yalvarırım.

sana adadığım ruhum benim en büyük gururum.

seni taparcasına seviyorum. bana kızma ne olur.

ben sağ salim çıkmak istiyorum, hep istedim.

beni bu hayatta sensiz bırakma...Ne olur,

Ne olur tut ellerimi, ne olur...

sende başını alıp gitme...Ne olur', 'bir şeye veda edelim, seni asla üzmemeye ne olur ben taşta taşısam, suyunu da sıksam. hep yanaklarına kelebek gibi konarım. ikimiz bir olup ...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga 3']::text[], 8.5, '{"poet":"Alper Tunga 3","poet_slug":"alper-tunga-3","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/o-cocugum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pamuk Ellerinde Huzur', 'pamuk-ellerinde-huzur-i-shak-koseoglu-8ldcr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkından yanarken gölgene sığınıp serinlemek ne güzel,

 Kalpte onca korku varken pamuk ellerine dolanmak hayat.

 Yangınlardan kaçıp yine sana çıkıyor bütün yollarım,

 Küllerim bile adını fısıldıyor rüzgâra usul usul.

Bir tarafım uçurumlara düşerken sessizce,

 Bir tarafım senin avuçlarında çocuk kalıyor,

 Dünya karanlığıyla üstüme yürürken,

 Sen bir tek gülüşünle sabah ediyorsun içimi.', 'Aşkından yanarken gölgene sığınıp serinlemek ne güzel,  Kalpte onca korku varken pamuk ellerine dolanmak hayat.  Yangınlardan kaçıp yine san...', ARRAY['Türk Edebiyatı','Şiir','İshak Köseoğlu']::text[], 8.5, '{"poet":"İshak Köseoğlu","poet_slug":"i-shak-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/pamuk-ellerinde-huzur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçme', 'gecme-erdem-gumus-2-lhkf9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şayet rastgelirsek bir gün bir yerde,

Beni bir yabancı, bilerek geçme.

Sevda selamını, saklayıp ser''de,

İçinden gizlice, alarak geçme.

Beraber yaşadık, en güzel aşkı,

Birlikte söyledik en güzel meşki,

İkimiz kurduk ya, o sırça köşkü,

Maziye kayıtsız, kalarak geçme.

Bensiz yürümezsin, sevgi yolunda,

Benden başkası da, olmaz kolunda,

Ben varken yâd olmaz, senin solunda,

İçin kan ağlarken, gülerek geçme.

Gönül gözlerimiz, mutlak bakışır.

Görünce ağlama, kalbin sıkışır,

Gülmek en güzel, sana yakışır,

Gözyaşını gizli, silerek geçme.

Seni ilk gün gibi, severim hâlâ,

Yok ki bizim gibi, aşka müptelâ,

Ölmemiş sevdaya, verilmez selâ,

Ecel namazımı, kılarak geçme.

Eğilmesin başın, karşıya bakın,

O onurlu kadın, tavrını takın,

Gördüğüne pişman, olup da sakın;

Figani''ye çalım, çalarak geçme.', 'Şayet rastgelirsek bir gün bir yerde, Beni bir yabancı, bilerek geçme. Sevda selamını, saklayıp ser''de, İçinden gizlice, alarak geçme. Berab...', ARRAY['Türk Edebiyatı','Şiir','Erdem Gümüş 2']::text[], 8.5, '{"poet":"Erdem Gümüş 2","poet_slug":"erdem-gumus-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gecme-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağır Özlem', 'agir-ozlem-fatih-kusku-zr0yc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eski bir zaman gelir aklıma,

Hatırlamak acıtır zamanla.

İşim artık ölülerle benim,

Benim için sen hep diriydin.

Lütfen o günler geri dönsün,

O gülüşler, o kahkahalar...

Ben doğuştan komiğim,

Ama o sadece doğuştandı.

Eğer bir gün ölürsem bil ki,

Seni çok sevdim ben.

Ne kadar reddetsen de,

Rüyalarıma girdin sen.

O tatlı yüzün hatırlatıyor bana

Güzel bir gülün kokusunu.

Tıpkı seni sevdiğim gibi,

Katlandım dikenine sevgimle.', 'Eski bir zaman gelir aklıma, Hatırlamak acıtır zamanla. İşim artık ölülerle benim, Benim için sen hep diriydin. Lütfen o günler geri dönsün,...', ARRAY['Türk Edebiyatı','Şiir','Fatih Küskü']::text[], 8.5, '{"poet":"Fatih Küskü","poet_slug":"fatih-kusku","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/agir-ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükürülen Aşk', 'tukurulen-ask-fatih-kusku-q4tjs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beklettim aşkımı ağzımda,

Devam ettim çiğnemeye.

Sonra tam şişirirken,

Tükürdüm ağzımdan aşkımı.

Bunu görünce iğrendin,

Beni sevmedin, reddettin.

Ama şunu bil ki,

Senin için o sakızı tekrar çiğnerdim.

Teker teker ölüme yol alıyorum,

Attığım her adımda yaşamımı sorguluyorum.

Ölüp gitmek istiyorum dünyadan,

Tıpkı tükürdüğüm aşk gibi.

Lütfen, lütfen geri dön,

Yeniden başlayayım, lütfen!

Yeniden şişireyim, yeniden çiğneyeyim;

Ama o sakız artık yerde ve sıra bende.

Tadı dünyalara bedeldi,

Çiğnerken ağzım sulanırdı,

Sevgiden boğulurdum,

Tükürüp üzerine basmadan önce...', 'Beklettim aşkımı ağzımda, Devam ettim çiğnemeye. Sonra tam şişirirken, Tükürdüm ağzımdan aşkımı. Bunu görünce iğrendin, Beni sevmedin, redde...', ARRAY['Türk Edebiyatı','Şiir','Fatih Küskü']::text[], 8.5, '{"poet":"Fatih Küskü","poet_slug":"fatih-kusku","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tukurulen-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ezelden Aşina Aşk', 'ezelden-asina-ask-sevgi-gul-i-lkan-jq8tq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Desen ki ''''Geliyorum, ezel bağım'''' 

Bütün saatleri sana kurarım 

Kanayıp duran hazin zamanlara 

Bir bakışını merhemim yaparım 

Hep sana uyur, sana uyanırım

Hüznü sevinç gözyaşımla yıkarım

İçimi seninle derleyip toplar

Bize devasa aşk yeri açarım 

Çay olur gözlerine demlenirim

Tatlı dilini şekerim ederim 

Ruha balım peteğim öz sevdiğim 

Kalp, ekmeğine seni katık eder

El ele, göz göze geldiğimizde 

Sözlerimizi eşlediğimizde 

Ruhumuzu bütün ettiğimizde 

Şu fasfakir cihandan tok gideriz 

Gelsen, çiçekleri birlikte sular 

Kuşlara birlikte yem, su veririz 

Bir el susar, iki elden ses çıkar 

Bizden bir olur aşka ses ederiz

Gönül ocağımızda aşk pişeriz 

Nefsin çiğliklerini gideririz 

Şu evrenden süt taşar, pak gideriz 

Toprağımız burcu burcu aşk kokar 

Alnıma vurduğun aşkın mühründen 

Yürek kulağıma eğildin birden 

''''Geliyorum ki'''' dedin kalp dilinden 

Öz emeği nur aşkla bekliyorum

Başını secdeye eğmiş rüzgardan

Kır sümbülü kokunu alıyorum

Rayihanı içime çekiyorum 

Ruhumun libasına işliyorum

Sesimin çatlağından sızan aşkla 

Ayak sesin duyuyorum yağmurdan 

Öyle nahif, öyle ben aşk çoğalan

Zeytini sayan, incitmekten korkan

Sazı ağlatan, narda şelale yar 

Yürek gözümle baktım tüm zamana 

Özünde ismim, cebinde resmim var 

Ben sana Kâlübelâ''dan aşina...', 'Desen ki ''''Geliyorum, ezel bağım''''  Bütün saatleri sana kurarım  Kanayıp duran hazin zamanlara  Bir bakışını merhemim yaparım  Hep sana uyur...', ARRAY['Türk Edebiyatı','Şiir','Sevgi Gül İlkan']::text[], 8.5, '{"poet":"Sevgi Gül İlkan","poet_slug":"sevgi-gul-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/asina-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Secdeye Gel Secdeye', 'secdeye-gel-secdeye-hatice-erturk-fd8zy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Allah''ın emri

Dinin direği

Ruhun şifası

Secdeye gel secdeye

İslamın şartı

İmanın tadı

Başların tacı

Secdeye gel secdeye

Abdesti alsan 

Namazı kılsan

Miraca varsan

Secdeye gel secdeye

Gözlerin feri

Yüzlerin nuru

Kalbin huzuru

Secdeye gel secdeye 

Anla bu sözü 

Aç artık gözü 

Görürsün özü 

Secdeye gel secdeye

Hakikat dili 

Manalar seli

Rahmetin yeli

Secdeye gel secdeye 

Dertlerin sonu

Cennetin yolu

Vuslatın sırrı

Secdeye gel secdeye', 'Allah''ın emri Dinin direği Ruhun şifası Secdeye gel secdeye İslamın şartı İmanın tadı Başların tacı Secdeye gel secdeye Abdesti alsan  Namaz...', ARRAY['Türk Edebiyatı','Şiir','Hatice Ertürk']::text[], 8.5, '{"poet":"Hatice Ertürk","poet_slug":"hatice-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/secdeye-gel-secdeye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülzârım In Feryadı', 'gulz-rim-in-feryadi-gul-yildirim-6k9zx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yıllardır geçmedi geçmiyor nârı

‎Sinemde sönmeyen harlı közüm var

‎Dilimden düşmedi ahımın zârı

‎Bağrımda kapanmaz derin izim var 

‎

‎Zifire boyandı günler karılmaz

‎Neylesin bu gönül gayrı arılmaz

‎Akan gözyaşlarım bir an durulmaz

‎Tabip el vurmasın acı sızım var

‎

‎Gönül bahçesinde güllerim soldu

‎Sevinçlerim bitti  kederle doldu

‎Zaman kör bıçakla sinemi deldi

‎Sorulmaz halim ne kara yazım var

‎

‎Garip bülbül gibi figan eylerim

‎Derdimi kimlere nasıl söylerim 

‎Ben bu kör talihle bilmem neylerim

‎Dağlarıma gelmez bahar yazım var

‎

‎Ne kimseler gelip halimi sordu

‎Ne de bu yarama dermanı sürdü 

‎Yürek aşk sevgiden bi haber durdu

‎Hayatta ne heves ne de nazım var

‎

‎Gülzârım  feryadın göğe dayandı 

‎Bütün bu dertlerim Hakk''a ayandı

‎Sebep olan yansın yüreğim yandı 

‎Semaları sarsan bir avazım var

‎

‎Gül Yıldırım ✍️ 14.11.2026

‎

‎', 'Yıllardır geçmedi geçmiyor nârı ‎Sinemde sönmeyen harlı közüm var ‎Dilimden düşmedi ahımın zârı ‎Bağrımda kapanmaz derin izim var  ‎ ‎Zifire...', ARRAY['Türk Edebiyatı','Şiir','Gül Yıldırım']::text[], 8.5, '{"poet":"Gül Yıldırım","poet_slug":"gul-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gulzarim-in-feryadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz sandığımız tüm sokaklardan çıkmaktır Ölüm', 'cikmaz-sandigimiz-tum-sokaklardan-cikmaktir-olum-canan-eren-z2vyy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölmek, küçük bir nefes sanırsın teslim edilecek.

Oysa

koca bir dünya içinden çıkıp gidecek.

Tespih taneleri gibi dizilmiş,

yükü sırtında yıllar veda edecek.

Ve aşk,

işte gerçekten o zaman bitecek.



✍️ Canan Eren

14 Kasım 2026 /Balıkesir', 'Ölmek, küçük bir nefes sanırsın teslim edilecek. Oysa koca bir dünya içinden çıkıp gidecek. Tespih taneleri gibi dizilmiş, yükü sırtında yıl...', ARRAY['Türk Edebiyatı','Şiir','Canan Eren']::text[], 8.5, '{"poet":"Canan Eren","poet_slug":"canan-eren","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cikmaz-sandigimiz-tum-sokaklardan-cikmaktir-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur Üzme Bizi', 'ne-olur-uzme-bizi-alper-tunga-3-0w2l1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'senden başkasını tanımayan ruhum için...

ne olur gitme, benim evim, yerim yurdum sensin.

gitme böyle...Ben geldim denizlerin şehrine

yetişmek istedim, senin dizelerine sen yazmadan,

hırsızlar çaldı mutluluğumu, aklıma sahip olamadım.

gülen gözlerin için, renklerin için. bizim için...

sen...Sen gitmesen olmaz mı

ben kendi imkansızlığımı yenilmedim hiç.

bir yuvanın hayali içindi, her şey bizim için.

ve kalbine saklanmak istedim, ilk günden itibaren.

kayıp gitmek istemedim ama kayboluyordum.

ne çok sevinçle geldim bu şehre bir bilsen,

her yer o şiir tasviri gibi nazarlık ve mavi boyalı

ilk anımda  dahi senin geleceğin günü hayal ettim,

anlatmıştım, ben buraya sevinçle geldim.

bu kadar yakınız birbirimize...Öyle deme ne olur,

ben biliyorum, ben şahitim, Tanrı şahit...

aldığım nefeste hayalin gezinmiyorsa...

attığım adımda sen yoksan...Adam değilim.

olmayan evimin kapısını aralayamadım,

bir vakitte zaten bende sokağa atıldım.

meleğim ne yapayım, karalar bağlamadım ki

senden zamanı diledim işte...Şimdi buradayım.

inanmayacağın mesailere karıştım.

uyuyabilecek kadar zamanımın olduğu günlere...

ben sana milyonlarca sabah dizesi yazardım.

oysa, bir kahvaltı masasını hayali için,

oysa bir pencere önünde sana sarılmak için...

böyle yapma elini kalbine götürdüğün yerdeyim.

sana öylesine saklandım, öyle sığındım.

lütfen ikimiz bu hayatta çok acı çektik...

ne olur, birbirimizi böyle bırakmayalım.', 'senden başkasını tanımayan ruhum için... ne olur gitme, benim evim, yerim yurdum sensin. gitme böyle...Ben geldim denizlerin şehrine yetişme...', ARRAY['Türk Edebiyatı','Şiir','Alper Tunga 3']::text[], 8.5, '{"poet":"Alper Tunga 3","poet_slug":"alper-tunga-3","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ne-olur-uzme-bizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köle', 'kole-alp-kaan-aksu-xdq3e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Öğrende bil hakiki kulluk ne demek,
Kulluk nedir bilmeyen kendini köle zannedecek.', 'Öğrende bil hakiki kulluk ne demek, Kulluk nedir bilmeyen kendini köle zannedecek....', ARRAY['Türk Edebiyatı','Şiir','Alp Kaan Aksu']::text[], 8.5, '{"poet":"Alp Kaan Aksu","poet_slug":"alp-kaan-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kole-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başka Sabah', 'bir-baska-sabah-buse-nur-manga-k2xd0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akan bir nehrin içinde,

Bir bahar esintisiyle,

Hiç güneş görmemiş ufak bir filizin sezgisiyle...

Ruhum yeniden karışıyor varoluşun içine,

Bir başka sessiz sabahın ilk ışıklarıyla,

Yorgun bir yaprağın boyun eğmesiyle,

Sıradan bir orman toygarının ezgisinde...

Ve ben,

Bir damla su, bir tutam rüzgâr, bir parça toprakla,

Yeniden katılıyorum hayatın sonsuz akışına.

Usulca, sessizce,

Varlığın o hafif güzelliğine...', 'Akan bir nehrin içinde, Bir bahar esintisiyle, Hiç güneş görmemiş ufak bir filizin sezgisiyle... Ruhum yeniden karışıyor varoluşun içine, Bi...', ARRAY['Türk Edebiyatı','Şiir','Buse Nur Manga']::text[], 8.5, '{"poet":"Buse Nur Manga","poet_slug":"buse-nur-manga","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-baska-sabah-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadığın odalarda', 'olmadigin-odalarda-gulcan-arikan-cuq40', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni bekledim 

Ardında bana miras  bıraktığın boşluğun köşelerinde oturarak...

Duvarlar sayıklıyordu adını usulca

Adımlarını çağrıştırıyordu koridor pervasızca,

Mamafih beklemekten vazgeçmeyi öğrendiğim gibi içinde sessizliğin,

Öğrendim boş odaların da nefes alabileceğini,

Ve çok sesli bu sessizliğin cilvesini vaveyla içinde,,

Kaçınılmaz finalde 

bitti bu güzel hikaye,

Giden sen oldun, 

Artık senin yerinin olmadığı odalarda 

Kalansa ben,biçare...', 'Seni bekledim  Ardında bana miras  bıraktığın boşluğun köşelerinde oturarak... Duvarlar sayıklıyordu adını usulca Adımlarını çağrıştırıyordu...', ARRAY['Türk Edebiyatı','Şiir','Gülcan Arıkan']::text[], 8.5, '{"poet":"Gülcan Arıkan","poet_slug":"gulcan-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/the-empty-room-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Gizli', 'gizli-gizli-aydin-cetinkaya-rdtst', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'GİZLİ GİZLİ

Her mevsimde eserken eseri olmaz rüzgâr,

Dağdan dağa her sesi her sese gizli nazar.

Hevesli nazlı ova beklerken bereketi,

Rüzgâra seslenişi gizli gizli intizar.', 'GİZLİ GİZLİ Her mevsimde eserken eseri olmaz rüzgâr, Dağdan dağa her sesi her sese gizli nazar. Hevesli nazlı ova beklerken bereketi, Rüzgâr...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çetinkaya']::text[], 8.5, '{"poet":"Aydın Çetinkaya","poet_slug":"aydin-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gizli-gizli-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giden Sevgilinin Ardından', 'giden-sevgilinin-ardindan-gulcan-arikan-i7du0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ah sevgili,

Ne ara uzak kaldık bu kadar 

Bu uzaklar daha ne kadar canımı yakar

Şiirler vazgecmişken artık sana yazılmaktan,

Fotoğrafların silinmişken telefonumdan

Oysa sen istemiştin tüm mesafeleri,

Zaman affetmedi bak 

Hem seni hem de beni...

Rüzgar savurdu hatıraları...

Ah sevgili,

ben çekince senden elimi eteğimi 

Kimler üzdü bu kadar

Kimler bıraktı atıl seni

Ne ara yorgun düştün bu kadar

Ah sevgili 

Böyleymiş yazgı, böyleymiş kader,

Daha ne kadar yakar canımı

Bana bıraktığın bu keder...', 'Ah sevgili, Ne ara uzak kaldık bu kadar  Bu uzaklar daha ne kadar canımı yakar Şiirler vazgecmişken artık sana yazılmaktan, Fotoğrafların si...', ARRAY['Türk Edebiyatı','Şiir','Gülcan Arıkan']::text[], 8.5, '{"poet":"Gülcan Arıkan","poet_slug":"gulcan-arikan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/giden-sevgilinin-ardindan-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde Bir Hayat Daha Vardı', 'i-cimde-bir-hayat-daha-vardi-yunus-emre-kulakoglu-d7qvf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle bir hayat vardı ki içimde,

Kimse bilmedi nasıl yaşamak istediğimi.

Ben herkese yetişmeye çalışırken,

Hayat bir kez olsun bana yetişmedi.

Ben de sevilmek isterdim mesela,

Birinin aklına gelmek, özlenmek isterdim.

Her gece güçlü görünmek zorunda kalmadan,

Bir sabah gerçekten iyi uyanmak isterdim.

Benim de yarına dair düşlerim vardı,

Bir gün güzel şeyler olacak sanırdım.

Meğer insan en çok kendi hayallerine yenilirmiş,

Ben yaşamak istediğim hayata yenildim.

Bir gün ben de mutlu olurum diye bekledim,

Her sabah içimde yeni umutlar biriktirdim.

Herkes kendi yolunda bir yerlere varırken,

Ben aynı yerde yıllarımı tükettim.

Ne zaman kendime bir gelecek çizsem,

Geçmiş çıkıp karşıma duvar ördü.

Ben daha güzel yarınların hayalini kurarken,

Zaman bütün umutlarımı birer birer gömdü.

Kimse sormadı içimde nelerin öldüğünü,

Hangi hayalimin son kez gözlerime baktığını.

Herkes gördü ayakta durduğumu,

Bir ben bilirim kaç kez içime yıkıldığımı.

Bazen düşünüyorum, başka türlü olsaydı,

Belki gözlerimde bu kadar keder olmazdı.

Belki ben de hayatı severdim yeniden,

Belki içimdeki çocuk bu kadar erken ölmezdi.

Şimdi içimde iki insan yaşıyor sanki,

Biri hâlâ hayal kuruyor, diğeri inanmıyor.

Biri güzel günlerin geleceğini bekliyor,

Diğeri artık hiçbir şey beklemiyor.

İçimde bir hayat daha vardı,

Benim de kendime ayırdığım yarınlarım vardı.

Ben bu ömrü yaşadım mı, inan bilmiyorum,

Kendi hayatımda kendime hiç rastlamadım.

#Emre', 'Öyle bir hayat vardı ki içimde, Kimse bilmedi nasıl yaşamak istediğimi. Ben herkese yetişmeye çalışırken, Hayat bir kez olsun bana yetişmedi...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre Kulakoğlu']::text[], 8.5, '{"poet":"Yunus Emre Kulakoğlu","poet_slug":"yunus-emre-kulakoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/icimde-bir-hayat-daha-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Where the Windflowers Grow', 'where-the-windflowers-grow-buse-nur-manga-uuilo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I have lost myself in the middle of endless meadows,

Where golden sunlight dances softly with the shadows.

I wander through the fields beneath the endless skies,

Searching for the girl I left behind in time.

I am looking for somewhere to take root,

Where love grows wild and life bears fruit.

Where gentle winds will call me home,

And I will never feel alone.

I am searching for myself again, once more,

Through quiet fields and paths I knew before.

With every step, with every sigh,

I chase the dreams that never die.

I find hope like a river flowing gently on a spring day,

Washing all my darkest memories away.

Through winding roads, through skies of blue,

The river whispers, you will bloom anew.

I breathe again amidst the lush green

leaves in the coolness of spring,

And hear the waking earth begin to sing.

The flowers rise, the branches sway,

And all my fears begin to fade away.

I am here, where wildflowers softly grow,

Where tender roots find strength below.

Still made of dreams, still learning when,

To lose, to bloom, to start again.

And if the winds should call my name,

I''ll walk through fields and storms the same.

For every ending holds a door,

And I am searching for myself again, once more.', 'I have lost myself in the middle of endless meadows, Where golden sunlight dances softly with the shadows. I wander through the fields benea...', ARRAY['Türk Edebiyatı','Şiir','Buse Nur Manga']::text[], 8.5, '{"poet":"Buse Nur Manga","poet_slug":"buse-nur-manga","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/where-the-windflowers-grow-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Gönlüm', 'ey-gonlum-hunturk-han-06egg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey gönlüm, yine kendine dön bu gece,
Her gidişi bir kader sanma.
Nice kapılar yüzüne kapandı diye
Ömrünü bir eşiğin önünde bırakma.
Sen ne fırtınalar gördün de devrilmedin,
Bir sükût vardı, dağlardan ağır.
Kimse bilmedi içindeki harbi,
Sen yaralarını bile kendinden sakladın.
Bazen bir şehre sığmadı kederin,
Bazen kendi gölgende gurbet kaldın.
Güruh-ı âlem içinde nâmın işitilmedi,
Sen yine dahi nefsine bîgâne kalmadın,
Şimdi mâzîye dönüp nazar etme,
Her hâtıranın bir hesâbı olmaz.
Bâzı insanlar ömrüne uğrar,
Bâzı yaralar ömrüne nakşolur.
Ey gönül, bundan böyle kendini noksân etme.
Kimsenin muhabbetine muhtâc olma, ey gönül.
Bir gün cümle varlık senden el çekerse,
Sen yine nefsine sığın.
Zîrâ insanın en uzun gurbeti,
Kendi nefsinden dûr düştüğü gecedir.

HUNTÜRK', 'Ey gönlüm, yine kendine dön bu gece, Her gidişi bir kader sanma. Nice kapılar yüzüne kapandı diye Ömrünü bir eşiğin önünde bırakma. Sen ne f...', ARRAY['Türk Edebiyatı','Şiir','Huntürk Han']::text[], 8.5, '{"poet":"Huntürk Han","poet_slug":"hunturk-han","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ey-gonlum-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serencâm', 'serenc-m-hunturk-han-crfg2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sabah uyandım, yıllar önümde,
Çocukluğum kalmıştı uzak bir günde.
Ne çok şey değişmiş insanın ömründe,
Meğer hayat, dönüp kendini aramakmış.
Gençliğinin ateşi diner zamanla,
Düşlerinin yerini düşünce alır.
İnsan büyüdükçe anlar dünyayı,
Her kazanç yanında bir bedel taşır.
Nice yüzler gördüm de yıllar boyunca,
Kimi gönül aldı, kimi yaraladı.
Kimi bir ömrünü sevdaya verdi,
Kimi sevdiğini kendi elleriyle kaybetti.
Ne malın kıymeti, ne tacın kalır,
Gün gelir saraylar virana kalır.
İnsan ne yaşarsa gönlünde kalır,
Ömür, kendisine dönünce bilinir.
Bir gün aynaların hükmü değişir,
Gençlik dediğin de bir anda geçer.
Dünya ne verirsen onu geri ister,
İnsan sonunda kendi hesabını öder.
Sonra bir akşamdır, gökyüzü kararır,
Bir kapı kapanır, bir başka açılır.
İnsan bu dünyadan ne ile ayrılır?
Adı değil, gönüllerdeki hâli kalır.
Ve ben, son nefes göğsüme dolunca,
Ne dünün peşinden, ne yarın sorunca;
Başımı koyarım toprağın bağrına,
“Yaşadım.” derim… gerisi Allah’a kalır.

HUNTÜRK', 'Bir sabah uyandım, yıllar önümde, Çocukluğum kalmıştı uzak bir günde. Ne çok şey değişmiş insanın ömründe, Meğer hayat, dönüp kendini aramak...', ARRAY['Türk Edebiyatı','Şiir','Huntürk Han']::text[], 8.5, '{"poet":"Huntürk Han","poet_slug":"hunturk-han","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/serencam-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun Hali', 'yoklugun-hali-hunturk-han-wn9m2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Akşam oluyor,
eve döndüm.
Çorba soğumuş,
masa biraz dağınık.
Yine Sen yoksun.
Pencereyi açtım,
sokaktan çocuk sesleri geliyor
Bir kaç çocuk top oynuyor aşağıda,
bir kadın balkondan sesleniyor.
Hayat devam ediyor yani.
Ben de oturdum
senin bıraktığın sandalyeye.
Ne garip;
insan bir sandalyeyi bile
birine benzetebiliyor.
Sonra çay koydum kendime.
İki şeker attım alışkanlıktan.
Güldüm.
Meğer insan
en çok böyle zamanlarda
kendi haline gülüyormuş.
Neyse işte 
Gece ilerledi.
Lambayı kapattım.
Karanlıkta düşündüm seni.
Öyle büyük laflar etmedim.
Özledim, dedim sadece.
Sonra sessizlik çöktü odama .
Bazı sevgiler
anlatılacak kadar uzun,
unutulacak kadar kısa değil.

HUNTÜRK', 'Akşam oluyor, eve döndüm. Çorba soğumuş, masa biraz dağınık. Yine Sen yoksun. Pencereyi açtım, sokaktan çocuk sesleri geliyor Bir kaç çocuk ...', ARRAY['Türk Edebiyatı','Şiir','Huntürk Han']::text[], 8.5, '{"poet":"Huntürk Han","poet_slug":"hunturk-han","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yoklugun-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizden Geriye Kalan', 'bizden-geriye-kalan-i-rem-acar-jkrel', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'günlerden 8 kasım hava buz gibi
ama biz sevgimizle ısınacak kadar aşığız
şuan ise birbirini tanıyan iki yabancıyız
 
çok şey anlatmak istedim sana
ne takatım kaldı ne bir aşina
aldı götürdü zaman bizden bir parça 
senden gitmek istemedim asla

kayboldum bıraktığım şekilde 
 hep aradım seni bulamadım yine de
aşkı öğrendiğimde on beştim
şimdi bastım on sekize

tekrar gelsem dünyaya
bilsem sonumuzun böyle biteceğini
yine severim seni
hiç pişman olmayacakmış gibi

o gün hayaller kurduk maziye daldık
gözlerimiz konuştu biz susakaldık
anladım bizim başka yolumuz kalmadı
bak hayallerimiz ve biz yarım kaldık', 'günlerden 8 kasım hava buz gibi ama biz sevgimizle ısınacak kadar aşığız şuan ise birbirini tanıyan iki yabancıyız   çok şey anlatmak istedi...', ARRAY['Türk Edebiyatı','Şiir','İrem Acar']::text[], 8.5, '{"poet":"İrem Acar","poet_slug":"i-rem-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bizden-geriye-kalan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Sana', 'benden-sana-i-rem-acar-1lujc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yürüdüğümüz bu yolun sonu
elbette ki gül bahçesi olmayacaktı
seninle başlayan güzel bir baharın yaprakları 
basit bir sonbahar mevsimine solmamalıydı

başlarken her şey çok güzeldi
ne olduysa sensizlik içimi deldi ve geçti
yanımızda çocuklaşan iki aşık
artık sevmekten vazgeçti

olduk artık iki yabancı 
ama denk gelirsek hatırlanacak onca anı
belki unutursun o güzel hatıralarımızı
bende kaldı vazgeçmenin göğsüme verdiği sızı

şimdi ise çok uzaklardan bakıyorum sana
sessiz sakin bir fırtına kopuyor içimde
sesini bazen unutuyorum ama
aklımda senle yaşadığımız onca hatıra

gitmek zorımdayım senden uzaklara
çıkacağım yine o çıkmaz sokaklara
ve bir sevda bırakıyorum sana
yalnız saf kalbinin ardında

uzak duruyorum senden istemsiz
biliyorum daha iyi olacağız ikimiz
sezen aksu ne güzel söylemiş
şimdi sensizim sen de bensiz', 'yürüdüğümüz bu yolun sonu elbette ki gül bahçesi olmayacaktı seninle başlayan güzel bir baharın yaprakları  basit bir sonbahar mevsimine sol...', ARRAY['Türk Edebiyatı','Şiir','İrem Acar']::text[], 8.5, '{"poet":"İrem Acar","poet_slug":"i-rem-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/benden-sana-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Meclise Uğramasın', 'bizim-meclise-ugramasin-ali-aksu-3-5gqrb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düzenden yana saf tutanlar

Lokmasına haram katanlar

Bütün kutsalını satanlar

Bizim meclise uğramasın 

Milletin sırtındaki bitler

Doymak bilmeyen parazitler

Doğru söze havlayan itler

Bizim meclise uğramasın

Günahta şeytanla yarışan

Vurguna, soyguna karışan

Bebek katiliyle barışan

Bizim meclise uğramasın 

Halkın emeğini sömüren

Sömürdükleriyle semiren 

Varıp hazineyi kemiren

Bizim meclise uğramasın 

Rant, talan peşinde koşanlar

Menzile varınca coşanlar 

Bozkurt iken, mankurtlaşanlar

Bizim meclise uğramasın 

Fonuna kadar halkı soyan

Donuna kadar halkı soyan

Sonuna kadar halkı soyan 

Bizim meclise uğramasın', 'Düzenden yana saf tutanlar Lokmasına haram katanlar Bütün kutsalını satanlar Bizim meclise uğramasın  Milletin sırtındaki bitler Doymak bilm...', ARRAY['Türk Edebiyatı','Şiir','Ali Aksu 3']::text[], 8.5, '{"poet":"Ali Aksu 3","poet_slug":"ali-aksu-3","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bizim-meclise-ugramasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefesim', 'nefesim-zeynel-berk-g56tm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen benim nefesim, 

Sen benim yüreğimsin. 

Attığım her adımda, 

Benimle yürüyenimsin.

Sen benim gecem, gündüzüm, 

Kalbimin özlemi en güzel sözüm.

Bir an sensiz kalmak karanlık 

Sen aşkım, bitmeyen özlemimsin.

Nefesim seninle anlam bulur, 

Yüreğim senin sevdanla kavrulur.

Dünyada ne isterim senden başka, 

Sen ömrüm, bitmeyen hevesimsin…', 'Sen benim nefesim,  Sen benim yüreğimsin.  Attığım her adımda,  Benimle yürüyenimsin. Sen benim gecem, gündüzüm,  Kalbimin özlemi en güzel s...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Berk']::text[], 8.5, '{"poet":"Zeynel Berk","poet_slug":"zeynel-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nefesim-81-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey can', 'ey-can-zeynel-berk-uphbm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey canımın cananı

Sana  naz makamı 

Bana tahammül

Yaraşır...

Naz duyguya

Tahammül 

Akla tabiyse

Gel ey aklım 

Duyguyu tanı

Kullan aklını

Naz haz olsun

Tahammül ise

Gönül süruru...', 'Ey canımın cananı Sana  naz makamı  Bana tahammül Yaraşır... Naz duyguya Tahammül  Akla tabiyse Gel ey aklım  Duyguyu tanı Kullan aklını Naz...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Berk']::text[], 8.5, '{"poet":"Zeynel Berk","poet_slug":"zeynel-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ey-can-133-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin ile', 'senin-ile-zeynel-berk-2q1mg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdan kurşun gibi 

Saplandı yüreğime

Damarımda dolaşırsın

Kanım ile...

Gör bak seviyorum

Seni  ölümüne

Yetmedi  bir ömür

Senin ile...

Ver elini elime 

Dokunsun 

Yüreğin yüreğime

Daldım yine...

Hayaline gözlerine

Sessizce susuyorum 

Sözlerine...

Acıları bırakalım

Koşalım mutluluğa 

Senin ile ....

Gel bak adım adım ileriye 

Yürüyelim kime ne

Yağmurda yaş ile

Boranda kış ile

Sar beni 

Hayal ile düş ile...', 'Sevdan kurşun gibi  Saplandı yüreğime Damarımda dolaşırsın Kanım ile... Gör bak seviyorum Seni  ölümüne Yetmedi  bir ömür Senin ile... Ver e...', ARRAY['Türk Edebiyatı','Şiir','Zeynel Berk']::text[], 8.5, '{"poet":"Zeynel Berk","poet_slug":"zeynel-berk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/senin-ile-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlarım Sana da', 'baslarim-sana-da-vildan-berra-m9j83', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbimi halden hale sokan

Aşkıma hor gözle bakan

Aklımı aklına yoldaş yapan

Zihnime de başlarım sana da 

Kör değilse bu göz nasıl görmedi

Bahar yağmuru gibi başlayıp ta dinmedi

Sevilen kalp keramete ermedi

Aşkıma da başlarım sana da

Aşkmış şu dünyada en büyük illet

Meftun ve perişan hali zillet

Kalsın her zerren sevgiye hasret

Kalbime de başlarım sana da 

Sen misin aslıma kafa tutan mert

Aşkıma aşina korkak namert

Yüreğin de artık kayadan sert

Düne de başlarım yarına da 

Güldürme beni ah edemem her mala

Hak var hesap var mizan zaten benden yana

Kor var yüreğimde yanıp durur senden yana

Külüme de başlarım sana da', 'Kalbimi halden hale sokan Aşkıma hor gözle bakan Aklımı aklına yoldaş yapan Zihnime de başlarım sana da  Kör değilse bu göz nasıl görmedi Ba...', ARRAY['Türk Edebiyatı','Şiir','Vildan Berra']::text[], 8.5, '{"poet":"Vildan Berra","poet_slug":"vildan-berra","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/baslarim-sana-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Eser', 'i-lk-eser-gorkem-kuyumcu-8zhzl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yabancıyla tanıştım
Yüzü tanıdık, adı unutulmuş...

Sorular sıralandı hemen
"Nesin? Necisin? Kimlerdensin?"
Bir ses yankılandı, ben bitirmeden
"İşte ben, kaybettiğin ilk eserin."

Kaybettiğin senin, seni bulması korkutucudur, bilirim
İnanmak istemesen de özün korkunun aynasıdır
Sen ne kadar değiştim dersen de
İçindeki çocuk hâlâ oradadır
Güneşli, yeşil çayırlarda değil
İçindeki karamsar ruhtadır
Şimdilerde, başka zamanda değil
Zamanın akmadığı andadır', 'Bir yabancıyla tanıştım Yüzü tanıdık, adı unutulmuş... Sorular sıralandı hemen "Nesin? Necisin? Kimlerdensin?" Bir ses yankılandı, ben bitir...', ARRAY['Türk Edebiyatı','Şiir','Görkem Kuyumcu']::text[], 8.5, '{"poet":"Görkem Kuyumcu","poet_slug":"gorkem-kuyumcu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ilk-eser-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceleyin Sabahı Düşünmek', 'geceleyin-sabahi-dusunmek-melik-koroglu-yvdza', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geceleyin Sabahı Düşünmek

Gece çökmüş yine şehrin üzerine,

Sokaklar susmuş, yıldızlar nöbette…

Bir ben uyanığım belki,

Bir de içimde hiç uyumayan yarınlar.

Düşünüyorum…

Acaba sabah nasıl doğacak?

Hangi hayalim gözlerime güneş olacak,

Hangi beklentim sessizce düşecek

Gecenin karanlık bir köşesine?

Yarınlar diyorum,

İnsanın en güzel yalanı mı,

Yoksa yaşamak için sakladığı

En kıymetli gerçeği mi?

Biriktirmişiz içimizde nice düşler,

Kimi bir gün gerçekleşir diye beklemiş,

Kimi daha adını bile koyamadan

Ömrümüzün bir yerinde kaybolup gitmiş.

Beklentilerimiz var hayattan,

Bir telefon sesi, bir kapı tıklaması,

Birinin içtenlikle nasılsın demesi,

Bir yolun sonunun mutluluğa çıkması…

Kimi beklentiler karşılık bulmuş,

Kimi avuçlarımızda kırılmış bir dal gibi.

Kimi hayaller gerçeğe dönüşmüş,

Kimi de yalnızca geceleri gelmiş aklımıza,

Biraz hüzün, biraz tebessüm bırakıp gitmiş.

Ama yine de vazgeçmemişiz yarından.

Çünkü insan dediğin,

En karanlık gecede bile

Bir sabahın ihtimaline tutunur.

Belki yarın her şey değişir,

Belki hiçbir şey değişmez.

Belki beklediğimiz gelir,

Belki de gelmeyeceğini nihayet anlarız.

Ama olsun…

Her yeni sabah,

Hayatın bize yeniden uzattığı bir kâğıttır.

Üzerine ister bir umut yazarsın,

İster yarım kalmış bir hayali,

İster hiç gerçekleşmeyecek bir özlemi…

Ben bu gece yine yarını düşünüyorum.

Gerçekleşmemiş düşlerimi de alıp yanıma,

Kırılmış beklentilerimi incitmeden,

Henüz yaşanmamış güzelliklere yer açarak…

Ve biliyorum ki

Hayat, yalnızca kavuştuğumuz şeylerden ibaret değil.

Biraz beklemek, biraz özlemek,

Biraz kaybetmek, biraz yeniden başlamak…

Belki de yaşamak tam olarak bu.

Şimdi geceye bir dilek bırakıyorum:

Sabah olduğunda herkesin yüreğine

Bir parça huzur, bir parça cesaret düşsün.

Çünkü ne kadar yorulursa yorulsun insan,

İçinde bir umut kaldığı sürece

Gece ne kadar uzun olursa olsun

Sabah olmaktan asla vazgeçmez.

Melik Köroğlu (Salihi)

Şair ve yazar', 'Geceleyin Sabahı Düşünmek Gece çökmüş yine şehrin üzerine, Sokaklar susmuş, yıldızlar nöbette… Bir ben uyanığım belki, Bir de içimde hiç uyu...', ARRAY['Türk Edebiyatı','Şiir','Melik Köroğlu']::text[], 8.5, '{"poet":"Melik Köroğlu","poet_slug":"melik-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/geceleyin-sabahi-dusunmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varlık', 'varlik-atilla-atakan-bolat-34a5a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Varlığın efendisi
Ne çok güruh dolaşıyor öyle teninde
Silik silik görüntüler canlanıyor gökyüzünde
Neşeli ayakkabılar dans ettiriyor
Yarım mı kalmış sanki hikayesi
Ne de densiz ne de çenesi düşük
Adayamamış kendini efendisine
Sahi çok mu zor kanatlarıyla adamak
Çok mu zor mısralara adını kazımak
Hele bir de şu berceste sözlerine bakın
Zannı ne de kutsal ne de denli
Kutsallığı saklı
Sanki oturmuş koca kırmızı bir tahta
O soluk bakışlarıyla hükmediyor karanlığa
Ey karanlığın efendisi
Sen misin tüm bunların en yücesi
Ey varlığa pencere açmış zat
Sen değil misin yokluğun tecellisi
Attığın kahkahalar
İçtiğin şaraplar her biri
Dolmuyor mu odanın duvarında damla damla
Akmıyor mu damarlarında sözlerinin zehri
Dudakların sanki uzak iki dağ gibi
Nefes geçmiyor mu her dirilişinde
Geçmiyor mu canının acısı son demlerinde
Sahi acının hangi rengine kastın var
Ey varlığın efendisi
Ey yokluğun kendisi
Arafların uçsuz bucağına
Ben her daim en uçlarda cambaz olacağım', 'Varlığın efendisi Ne çok güruh dolaşıyor öyle teninde Silik silik görüntüler canlanıyor gökyüzünde Neşeli ayakkabılar dans ettiriyor Yarım m...', ARRAY['Türk Edebiyatı','Şiir','Atilla Atakan Bolat']::text[], 8.5, '{"poet":"Atilla Atakan Bolat","poet_slug":"atilla-atakan-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/varlik-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tunç Çağının Ardından', 'tunc-caginin-ardindan-ersin-gulezer-k25uo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ve belki bir gün,
gelecek nesiller tarih kitaplarını açtığında
tunçtan yapılmış silahları görecekler
camların ardında, sessiz ve anlamsız.
Bir zamanlar bunlarla birbirlerini öldürdüklerini okuyacaklar
ve inanmakta güçlük çekecekler.
İşte o gün,
insanlık gerçekten yeni bir çağa girmiş olacak.
Ne demirin, ne tunçun, ne de barutun çağına;
birbirinin yarasını kendi yarası bilenlerin,
bir sofrada ekmeği bölüşenlerin,
bir çocuğun gülüşünü bütün zaferlerden üstün tutanların çağına.
Ve barış,
ilk kez bir kelime olmaktan çıkıp
insanlığın ortak evi olacak.
O evin kapısında da
ne bir kralın adı yazacak
ne bir ordunun mührü.
Yalnızca şu cümle:
Burada insan, insana düşman değildir.', 'Ve belki bir gün, gelecek nesiller tarih kitaplarını açtığında tunçtan yapılmış silahları görecekler camların ardında, sessiz ve anlamsız. B...', ARRAY['Türk Edebiyatı','Şiir','Ersin Gülezer']::text[], 8.5, '{"poet":"Ersin Gülezer","poet_slug":"ersin-gulezer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tunc-caginin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahkeme', 'mahkeme-alp-kaan-aksu-ux4q5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Onca tecelli varken ve mahkemeler,
