INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Quiet Blue', 'quiet-blue-ezgi-nisan-akgul-aavk1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I wonder where your thoughts hide,

to distant worlds beyond my sight.

And whether, in the quiet blue,

a little of me reaches you.

Is the real me in your head,

or someone you have made instead.

I keep returning to what’s true,

to all the things I ask from you.

I let my love slip away

with all the words I couldn’t say.

I give you more than I can feel,

yet ache for something real.', 'I wonder where your thoughts hide, to distant worlds beyond my sight. And whether, in the quiet blue, a little of me reaches you. Is the rea...', ARRAY['Türk Edebiyatı','Şiir','Ezgi Nisan Akgül']::text[], 8.5, '{"poet":"Ezgi Nisan Akgül","poet_slug":"ezgi-nisan-akgul","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/quiet-blue-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Bir Defterdi.', 'sadece-bir-defterdi-kenan-mert-gulveren-qw36q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SADECE BİR DEFTER

