INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın olmak', 'kadin-olmak-nevzat-tekmen-2-wr9bf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşama bağlanmanın yolu,

Her halde,her şekilde,

Kimseye bağlanmamaktan geçer.

Peki,

Kadın veya erkek olmak,

Fark eder mi bu işte?

Eder ise,

Buyur bakalım,

Kadın mı,Erkek mi,

Daha şanslı,

Bağlanmama meselesinde?

Kadınsan bu ülkede;

Zordur hayat,

Hele de evli isen...

Sevdiğini sandığın,

Veya,

Sevildiğini sandığının,

Altına yatacaksın,

Bacaklarını açacaksın,

Fantazilerine de ,

Sırf kocamdır diye katlanacaksın....

Bazen,

Gecenin bir yarısı,

Küfelik bir şekilde,

Yanağında ki,

Kan kırmızı bir ruj lekesi ile,

Eve gelen kocan,

Zıbarıp yattığında,

Lekeyi silip,

Yanına uzanacak,

Sabaha da,

Kahvaltı hazırlayacaksın.

Zira,

Kadınsın dır,

Yoktur gelirin,

Ve gidecek bir yerin...

Yüreğinin sızısı,

Kocanın yanağındaki,

Arsız fondaki,

Ruj lekesi ile sınırlı değildir,

Onun iki dudak arasından,

Her gün tıslar gibi söylediği,

Seçme saçma cümleler,

Ve aşağılamaları ile ilgilidir .

Her şeye rağmen,

Yemek yaparken,

Kıymadan biraz aşırır,

Banyoyu çamaşır suyu yerine,

Arap sabunu ile temizler,.

Semt pazatına ucuz olur diye,

Son deminde gider,

Dişinden tırnağından arttırdıklarınla,

Bir pazar günü kocana,

Rakı sofrası hazırlarsın...

O akşamın bir saatinde,

Çakırkeyf olan kocan,

Yeni bir ruj lekesi için,

Evden çıkar,

Sen ise ,

Aptal bir şekilde bakakalırsın.

Sözün özü;

Bağlanmamak zordur ,

Kadın için bu ülkede,

Bir de evli ise ve de çocuklu....

                   26 temmuz 2025', 'Yaşama bağlanmanın yolu, Her halde,her şekilde, Kimseye bağlanmamaktan geçer. Peki, Kadın veya erkek olmak, Fark eder mi bu işte? Eder ise, ...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Tekmen 2']::text[], 8.5, '{"poet":"Nevzat Tekmen 2","poet_slug":"nevzat-tekmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/kadin-olmak-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Gerçek', 'tek-gercek-yildiz-yilmaz-q8u66', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçimde eksikliğini hissediyorum,

Kaderimde yollarımızın kesiştiğini biliyorum.

Defterimin boş sayfalarında ismini arıyor,

Seni bir kere daha görmenin umuduyla yaşayıp kendi bitişimi izliyorum.

Sessizliğim, sana söylediğim son sözdü,

Sana olan hissimin son ışığı da söndü.', 'İçimde eksikliğini hissediyorum, Kaderimde yollarımızın kesiştiğini biliyorum. Defterimin boş sayfalarında ismini arıyor, Seni bir kere daha...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yılmaz']::text[], 8.5, '{"poet":"Yıldız Yılmaz","poet_slug":"yildiz-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tek-gercek-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukça', 'cocukca-hakan-dincel-x9440', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biz ne mutlu çocuklardık,

onca zorluğumuz, yoksulluğumuz ve imkansızlığımizla,

biz ne mutlu çocuklardık.

Harçlığımız olmazdı gülerdik,

oyuncakları uzaktan severdik, karşılıksız bir aşk gibi mesela.

Bayramliklarimizla koyun koyuna yatan çocuklardik, 

bembeyaz bir güvercindi,

bizim için hayat,

ayağından bağlı, küçücük balkonumuzda.

Bir sabah uçup gittiğinde o,

yine mutlu çocuklardik,

içten içe aglasak da.

Nerden bilirdik ki sevmenin,

çok sevmenin sonunun hep ayrılık olduğunu.

Hep severdik,

karşılıksız seçerdik dostluğu. 

Hamamda bayılmış taklidi yapan ayıcıklarımız vardı sokaklarda,

allı güllü macun yer,

mantara ateş ederdik tüfeklerle.

Kız kovalardik torpillerle,

kız kovalayanlarla.

Kovalayamazsak kızları,

usulca yanlarına yaklaşır,

laf atardık delikanlıca.

Birlikte yürüyelim mi derdik,

hayır derse, o zaman koşalım deyip gülerdik,

hiç zorlamaz, espri yapardık,

centilmence ve delikanlıca.

Kolasına maç yapardık,

mahalle aralarında.

Ağzımız açık izlerdik yarin balkonunu,

bir umuttu, ya cama çıkarsa ?

Heyecanı, mahalle maçlarında,

ve okul pikniklerinde yaşadık ilk defa.

Külah dürüp borumuzla atar gibi,

Dürer dürer atardık sıkıntılarımızı çok uzaklara.

Biz ne mutlu ve delikanlı çocuklardik.

Okula gittiğimizde yürüyerek, araçsız, servissiz,

saçı uzunlar kuyruğuna alinirdik,

soğuktan donmuş saçımızla.

Oturamazdik sevgiliyle, kafelerde, barlarda.

Ancak gezerdik

karlı, soğuk, kirli bir havada 

Ankara''nın  sabahlarinda parklarda.

Büyüdük, bir yanımız hep çocuk kaldı, 

ama yeni nesil,

bunu hiç anlamadı.

Belkide yaşadığımız bir hayaldi, 

bir romandı.

Onlar için başka bir anlamı da olmadı.

Olsun, biz hala aynı çocuğuz,

gönlünü emanet edene,

gönül dostuyuz...', 'Biz ne mutlu çocuklardık, onca zorluğumuz, yoksulluğumuz ve imkansızlığımizla, biz ne mutlu çocuklardık. Harçlığımız olmazdı gülerdik, oyunc...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dincel']::text[], 8.5, '{"poet":"Hakan Dincel","poet_slug":"hakan-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/cocukca-102-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçluluk Evresi', 'sucluluk-evresi-mehmet-mert-kandemir-a1q4k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bozulmuş bedeninin dokunulmazlığı,
Sebepsizdir bakışların okunuşmazlığı
Yitirmiş ruhun mütevazılığı,
Körelmişsin kesmiyorsun haksızlığı.

Değişmesinden korkardım çehrenin,
Bana yabancılaştıran çevrenin,
Aşkın suçluluğun kaçıncı evresinin,
Kaçıncı kolusun fitne devriyesinin.

Masumiyetin girmiş çıkmazlara,
Gözlerin hasım kesilmiş anılara,
Geceleyin sebep oluyor sancılara,
Bağlanmışsın kötülüğe kancalarla.

Eskiden duyardın fısıldamalarımı,
Şimdi ise duymazsın feryatlarımı,
Ne değişti o günden bugüne,
Masumluğun mu ilgi odağın mı?', 'Bozulmuş bedeninin dokunulmazlığı, Sebepsizdir bakışların okunuşmazlığı Yitirmiş ruhun mütevazılığı, Körelmişsin kesmiyorsun haksızlığı. Değ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Mert Kandemir']::text[], 8.5, '{"poet":"Mehmet Mert Kandemir","poet_slug":"mehmet-mert-kandemir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sucluluk-evresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşzaman', 'eszaman-ezgi-nisan-akgul-e88vi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bebek uzak bir ülkede doğdu

yüzünü büzdü ve ağladı

ilk çığlığı yankılanırken

arkadaş grubu şakalaşıyordu

bir adam çanta çaldı ve kaçtı

kadın yardım çağırdı

grup dönüp bakmadı

kadın başını eğdi ve yoluna devam etti

adam bir süre koştuktan sonra

çantadan cüzdanı çıkardı 

parayla çocuğuna oyuncak aldı

çocuğu babasına sarıldı

kadın eve dönerken ekmek alamadı

komşularına iyi akşamlar diledi

evren bütün bunları taşıdı

ertesi gün hiçbirini hatırlamadı', 'bebek uzak bir ülkede doğdu yüzünü büzdü ve ağladı ilk çığlığı yankılanırken arkadaş grubu şakalaşıyordu bir adam çanta çaldı ve kaçtı kadın...', ARRAY['Türk Edebiyatı','Şiir','Ezgi Nisan Akgül']::text[], 8.5, '{"poet":"Ezgi Nisan Akgül","poet_slug":"ezgi-nisan-akgul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eszaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niyet Okuma İhtiyacı', 'niyet-okuma-i-htiyaci-onder-karacay-1j78i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '§

Bir eylemin sonucu eylemin kendisinden daha önemli ise o eylemin eylemi gerçekleştirenlerden gizli bir niyeti olduğunu gösterir. O niyetin arkasında kim olduğunu bulan sebebini de bulur ve o eyleme alet olmaz. Tek bir kişinin hakim olduğu örgütlü kötülükler gizli nihai hedeflerine bu yolla ulaşmak ister. Bir ulusun böyle bir tuzağa düştüğünü düşündüğünüzde yasal hakları kullanmak ve yaşam mücadelesi vermek bile dolaylı bu art niyete bir müddet hizmet edebilir. Bu çağın insanı niyet okumak ihtiyacını aldatılarak dolandırılmaktan baktığı için öğrenmek zorunda kaldı. Bilim ve teknolojik tüm gelişmelerde bu kötülüğe hizmet ettiği için niyet okuma farkındalığı büyüdü ve çağı değiştiren insanlık iradesi ete kemiğe bürünüyor. 

§

▪️Önder Karaçay ▪️', '§ Bir eylemin sonucu eylemin kendisinden daha önemli ise o eylemin eylemi gerçekleştirenlerden gizli bir niyeti olduğunu gösterir. O niyetin...', ARRAY['Türk Edebiyatı','Şiir','Önder Karaçay']::text[], 8.5, '{"poet":"Önder Karaçay","poet_slug":"onder-karacay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/niyet-okuma-ihtiyaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde Kayboluş', 'gozlerinde-kaybolus-yildiz-yilmaz-oihz4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Boğazımı yakıp beni ateşe iten senin ellerin,                      

Ne gözlerin kaldı ne de dudağından dökülen o kelimelerin.

Arkana bakmadan bırakıp gitmene var mıydı gerek?

Senden iz yok artık, bende de seni bekleyecek yürek.

Ben de sensizliğin zindanlarında yok oluyorum,

Ölerek...

Yok oluyorum, görmüyorsun.

Gözlerinin içinde kaybolarak eriyorum,

Hissetmiyorsun.

Arkana bakmadan beni bırakıp gidiyorsun.

Anlıyorum ki sadece seni değil, gururumu da kaybediyorum.

Gözlerin ona bakıyor,

Sözlerin onun etrafında şekilleniyor.

Kalbim, gururumu  kaybetmenin korkusuyla yüzleşiyor,

Senin onunla olman beni kül ediyor.', 'Boğazımı yakıp beni ateşe iten senin ellerin,                       Ne gözlerin kaldı ne de dudağından dökülen o kelimelerin. Arkana bakmada...', ARRAY['Türk Edebiyatı','Şiir','Yıldız Yılmaz']::text[], 8.5, '{"poet":"Yıldız Yılmaz","poet_slug":"yildiz-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gozlerinde-kaybolus-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül''dü', 'eylul-du-fahrein-m9lgk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eylül''dü

Dalından kopan yaprakların

Sararan yanlarına yazdım adını

Sahte bir gülüşten ibarettin oysa.

Ve hiç bilmedin ellerimin soğuğunu.

Eylül''dü.

Di ‘li geçmiş bir zamandı yaşadığımız

Adımlarımızın kısalığı bundandı

Bundandı gözlerimin durgunluğu.

Sarı sıcak cümlelerde sözün kadar yalan,

Ellerin kadar ıssız,

Sen kadar zamansız molalar veriyordum

Ve çocuksu bir bencillikti hüznümüz.

Eylül''dü.

İzlerini çizdiği zaman ansızın gidişin,

Şimdi yoktu bir anlamı suskunluğun.

Çırılçıplak kalakaldım sessizliğin orta yerinde.

Sonra sesime yankı vermeyen uçurumlar kıyısında yürüdüm bir zaman

En çok sesini aradım.

Gözlerinse asılı bıraktığın yerdeydiler hala.

Gözlerini sildi zaman..

Dedim ya…

Eylül''dü.

Savruluşu bundandı kimsesizliğimin', 'Eylül''dü Dalından kopan yaprakların Sararan yanlarına yazdım adını Sahte bir gülüşten ibarettin oysa. Ve hiç bilmedin ellerimin soğuğunu. Ey...', ARRAY['Türk Edebiyatı','Şiir','Fahrein']::text[], 8.5, '{"poet":"Fahrein","poet_slug":"fahrein","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/eylul-du-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Müsade Et', 'bir-musade-et-fahrein-48yyu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir müsaade et ne olur...

Seni bir süre anmayayım da dünya yerinde dursun.

Kalbim şu an servise alınsın,

Adın her atışta ekrana düşüp durmasın.

Çünkü seni sevmek,

Vardiyalı bir iş gibi üstüme kaldı.

Bir müsaade et ne olur...

Gözlerim seni aramaktan bugüne bir mesai düşürsün.

Her kalabalıkta yüzünü seçmeye çalışmayayım,

Her şarkıda adını yakalayıp "tesadüf" diye kendimi kandırmayayım.

Güldüm halime,

Hasretin eve sipariş poşeti gibi birikti.

Bir müsaade et ne olur...

Bu gönül biraz rolünü unutup kenara çekilsin.

Yokluğunun ortasında dolaşmaktan

Ayaklarım değil, sabrım fiş kesti artık.

Ben seni severken,

Kendi kapı numaramı bile karıştırdım.

Bir müsaade et ne olur...

Ya gel, şu ayrılığı kapat.

Ya da bırak,

Seni bekleyen bu yüreği

Sessizce raf ömrüne sokayım...

Çünkü sensiz geçen her gün,

Beni bana biraz daha komik ediyor.', 'Bir müsaade et ne olur... Seni bir süre anmayayım da dünya yerinde dursun. Kalbim şu an servise alınsın, Adın her atışta ekrana düşüp durmas...', ARRAY['Türk Edebiyatı','Şiir','Fahrein']::text[], 8.5, '{"poet":"Fahrein","poet_slug":"fahrein","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-musade-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vah', 'vah-duran-bukulmez-didx5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ömürü tüketir eceli bekler.

Bu dünyada yüzü gülmeyenim vah.

Bin derdin üstüne bin derdi ekler.

Dünyada huzuru bulmayanım vah.

Viran olan bağda bülbülü ötmez.

Çektiği çileler bir türlü bitmez.

Çalışır çabalar maaşı yetmez.

Cebinde parası olmayanım vah.

Bu dünyada yoksul oldum olası.

Gurbetten uzakta durur sılası.

Başından eksilmez yokluk belası.

Varlığın adını bilmeyenim vah.

Ayları yılları gam ile geçer.

Kahpe felek bile hep onu seçer.

Eceli gelmeden dünyadan göçer.

Tatlı hayallere dalmayanım vah.

Halini sorunca çatar kaşını.

Zalimin zulmünden eğer başını.

Bulamaz içmeye bulgur aşını.

Gözünün yaşını silmeyenim vah.

Bükülmez’im derki bağlar karalar.

Sabahtan akşama kendin paralar.

Nedense sarılmaz kanar yaralar.

Dünyada kaderi olmayanım vah.

13.11.2026

Erbaa', 'Ömürü tüketir eceli bekler. Bu dünyada yüzü gülmeyenim vah. Bin derdin üstüne bin derdi ekler. Dünyada huzuru bulmayanım vah. Viran olan bağ...', ARRAY['Türk Edebiyatı','Şiir','Duran Bükülmez']::text[], 8.5, '{"poet":"Duran Bükülmez","poet_slug":"duran-bukulmez","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/vah-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rehberini İzle', 'rehberini-i-zle-eyup-dalkilic-2-43vs8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bırak nefsi hevâ ile yaşamak, 

Zîrâ seni nâra çeker son durak. 

Nefis heves ile cihânı ister, 

Vesvese iblîsten, kurtul kaçarak!

Rehberini izle, yolda kalma sakın, 

Sonra vardığında elin boş olmasın! 

Kitab-ı Hak inmiş de meydandadır, 

Oku da sır perdesi hiç kalmasın.

Ol Nebî sana sakın darılmasın, 

Cânâ yola çık bir dem sünnet ile. 

Yoksa kabrin nâr olur, dar olmasın, 

Arkanda dua odan boş olmasın.

Rehberini izle, yolda kalma sakın, 

Sonra vardığında elin boş olmasın! 

Kitab-ı Hak inmiş de meydandadır, 

Oku da sır perdesi hiç kalmasın.

2026', 'Bırak nefsi hevâ ile yaşamak,  Zîrâ seni nâra çeker son durak.  Nefis heves ile cihânı ister,  Vesvese iblîsten, kurtul kaçarak! Rehberini i...', ARRAY['Türk Edebiyatı','Şiir','Eyüp Dalkılıç 2']::text[], 8.5, '{"poet":"Eyüp Dalkılıç 2","poet_slug":"eyup-dalkilic-2","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/rehberini-izle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzülme Be Abu *', 'uzulme-be-abu-hasan-oz-39gik', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gül benzin, ne için sarardı soldu

Bitti sabrım, eridim deme be abu

Desen ki dert bir idi binlerce oldu

Kaderin çekilecek üzülme be abu

Hayır şer gün gibi kudret ondadır

Zor olan sabırsa hikmet bundadır

Kim bilir ol gerçek iman, kimdedir

Mizanda seçilecek üzülme be abu

Rabbim, malı verir denemek için

Az, ya da çok sunar sınamak için

Kul hakkı, yiyenleri denemek için 

Şu sırat geçilecek üzülme be abu

Mülkün; maliki Rab, biz de kiracı

Hedef, değişince maldır baş tacı

Gönül kırma, mal ise olmaz ilacı

O, yemin içilecek üzülme be abu

Ceza olmaz evlat soy sop üresin

Sebebi hilkat, ne? nerden bilesin 

Her derdine, bin bir deva eylesin

Kitaplar, açılacak üzülme be abu

Kem söz rücu, eder acı hasmına

Aslını görür kesin baksa resmine

Helallik; şart olur namert kısmına 

Ezadan, kaçılacak üzülme be abu 

Bilen rızkı bitenleri, melek Mikail

Haber verdi bunları, kula Cebrail

Zengin fakir demeden gelir Azrail

Son çare göçülecek üzülme be abu ..

H.C.ÖRS (Cemali), Ankara - 12.4.2010 20:29:00   (Arşiv-70)', 'Gül benzin, ne için sarardı soldu Bitti sabrım, eridim deme be abu Desen ki dert bir idi binlerce oldu Kaderin çekilecek üzülme be abu Hayır...', ARRAY['Türk Edebiyatı','Şiir','Hasan Öz']::text[], 8.5, '{"poet":"Hasan Öz","poet_slug":"hasan-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/uzulme-be-abu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizliğin kül olduğu yer', 'sessizligin-kul-oldugu-yer-serhat-gazi-wfp7g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SERHAT GAZİ.

İnsanın kalbi bir kez kasvetle sarılıp mühürlendiğinde,

karşısındaki can çekişirken bile yalnızca bir gölgeyi izler.

Oysa bu yalan dünyada herkesin sırtında taşıdığı

üç ağır yara, üç derin mühür vardır;

zamanın bile dokunmaya cesaret edemediği...

Birincisi;

en güvendiğin yerde savunmasız kalmaktır.

Sırtını yasladığın o dağın,

en güvendiğin yamacından kopup

sessizce üzerine yıkılması gibi...

İkincisi;

boğazında düğümlenen o yarım kalmışlıktır.

Ne gidenin ardından “git” diyebilirsin,

ne de kalana “kal” diyecek kadar gücün vardır.

Bir cümle eksik kalır,

bir veda yarım,

bir hikâye sonunu bulamadan susar.

Ve üçüncüsü...

En acısı, en ağır olanıdır.

Senin koca bir dünyan yerle bir olurken,

o enkaza sebep olan insanın

göğsünden kopan feryatlara kulaklarını kapatmasıdır.

Sen geceleri kendi yaralarınla boğuşurken,

onun hiçbir şey olmamış gibi

hayatına kaldığı yerden devam etmesidir.

İşte insanı asıl öldüren budur...

Darbe değil yalnızca,

darbeyi vuranın ardından dönüp bakmamasıdır.

Bir zamanlar “canım” dediğinin

senin canından kopan parçaları görmezden gelmesidir.

Çünkü merhametini kaybeden bir kalp,

başkasının acısına sağırlaşır.

Ne gözyaşını görür,

ne titreyen sesini duyar,

ne de gecenin içinde sessizce parçalanan ruhunu...

Taştan bir duvar gibi durur karşında;

sen içinden yıkılırken

o, yalnızca sessizliğini duyar.

Oysa insanı tüketen

aldığı yaraların derinliği değildir her zaman.

Bazen en büyük yara,

yarayı açanın

senin kanadığını bile bile

hiçbir şey olmamış gibi uzaklaşmasıdır.

Ben bunu öğrendim...

İnsan kendi yıkımına

uzaktan bakabiliyormuş meğer.

Bir zamanlar içinde hayat olan yerlerin

nasıl birer enkaza dönüştüğünü,

kendi gözlerinle görebiliyormuşsun.

Ben de baktım...

Gözlerimin önünde dağıldı

inandığım ne varsa.

Bir sevda sustu,

bir güven öldü,

bir ömür birkaç sessizliğe bölündü.

Şimdi göğsümün orta yerinde

sönmeyen bir yangın,

dilimde söylemeye gücümün yetmediği

boynu bükük bir veda var.

Kimse bilmiyor...

Ben artık acımı anlatmıyorum.

Çünkü bazı acılar anlatılınca küçülmüyor;

insanın içinde daha da büyüyor.

Bu yüzden susuyorum.

Susuyorum ki

içimdeki enkazın altında kalan

son güzel hatıraları da

kendi sesimle ezmeyeyim.

Ve anladım ki...

Bazı yaralar kabuk bağlamaz.

Bazı vedalar bitmez.

Bazı insanlar gider ama

ardında bıraktığı sessizlik

ömür boyu bizimle kalır.

İnsan bazen ölmez...

Sadece içindeki bir parçasını

bir yerde bırakır

ve hayatına eksik devam eder.

Ben de öyle yaptım.

Gidenin ardından bakmadım...

Kalanın yüzüne de dönemedim.

Çünkü bazı kırgınlıkların

ne affı vardır

ne de vedası.

Sadece insan susar...

İçinde bir yangın,

gözlerinde eski bir hayat,

yüreğinde kapanmayan bir kapıyla...

Ve gün gelir,

herkes seni iyileşmiş sanır.

Oysa sen çoktan öğrenmişsindir:

Bazı yaralar iyileşmez...

Sadece insan, acısını taşımayı öğrenir.

Ve en acısı da budur...

Seni en çok yaralayan insan,

senin bir zamanlar en çok güvendiğin insandır.

Çünkü insan yabancının darbesinden değil,

kendi eçinde açılan yaradan kanar.', 'SERHAT GAZİ. İnsanın kalbi bir kez kasvetle sarılıp mühürlendiğinde, karşısındaki can çekişirken bile yalnızca bir gölgeyi izler. Oysa bu ya...', ARRAY['Türk Edebiyatı','Şiir','Serhat Gazi']::text[], 8.5, '{"poet":"Serhat Gazi","poet_slug":"serhat-gazi","theme":"Türk Şiiri","is_hero":false,"total_lines":100,"source_url":"https://www.antoloji.com/sessizligin-kul-oldugu-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-alp-kaan-aksu-oxayv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bekletme beni,
