INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kitapla Düzgünleşmek', 'kitapla-duzgunlesmek-kazim-karagoz-5stwt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eski türk filmlerinde düzgün yürümek için

Başına kitap koyup idman yaptırırlardı.

Düşünsenize o kitabı bir de okusa;

Hem içi hem dışını düzgün yaptırırlardı.', 'Eski türk filmlerinde düzgün yürümek için Başına kitap koyup idman yaptırırlardı. Düşünsenize o kitabı bir de okusa; Hem içi hem dışını düzg...', ARRAY['Türk Edebiyatı','Şiir','Kazım Karagöz']::text[], 8.5, '{"poet":"Kazım Karagöz","poet_slug":"kazim-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kitapla-duzgunlesmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zümrüdü Anka (hamza caymazdan hediye)', 'zumrudu-anka-hamza-caymazdan-hediye-serpil-ersoy-zumruduanka-blhcx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nor=Hamza caymaz kardeşimin şahsıma yazdığı kalem.... 

Ben küllerinden doğan bir hikâyeyim, 

Yanmışım, yıkılmışım, yine de bitmemişim. 

Herkes sonumu yazarken sessizce, 

Ben yeniden başlamanın adını öğrenmişim.

Bir zamanlar gökyüzüne küsmüştüm,

Kanatlarım kırık, yüreğim yaralıydı.

Ne uçacak hâlim kalmıştı 

Ne de bir dala konacak umudum…

Ama insan bazen,en çok düştüğü yerde

Kendini yeniden tanırmış.

 En karanlık gecenin içinde 

Kendi güneşini yakarmış.

Ben Zümrüdü Anka’yım...

Beni ateşle sınayanlar oldu,

Küllerime bakıp bitti sananlar oldu. 

Oysa kimse bilmedi; 

Ben her yanışımda biraz daha güçlendim.

Ne geçmişime yenildim 

Ne de yarınlardan vazgeçtim. 

Kaybettiklerimi kalbime gömdüm, 

Kazandığım sessizliği kendime yoldaş ettim.

Şimdi gökyüzüne bakıyorum, 

Arkamda duman, önümde sonsuzluk… 

Beni yakan ateşe bile kırgın değilim, 

Çünkü o ateş öğretti bana 

Kendi kanatlarımla uçmayı.

Ben Zümrüdü Anka’yım… 

Herkesin bitti dediği yerde başlayan, 

Her düşüşte yeniden ayağa kalkan, 

Küllerinden kendi kaderini yazan 

Bir avuç umut, bir ömür direnişim.

Çok teşekkürler üstadım

Hamza caymaz kalemidir

14.11.2026', 'Nor=Hamza caymaz kardeşimin şahsıma yazdığı kalem....  Ben küllerinden doğan bir hikâyeyim,  Yanmışım, yıkılmışım, yine de bitmemişim.  Herk...', ARRAY['Türk Edebiyatı','Şiir','Serpil Ersoy Zümrüdüanka']::text[], 8.5, '{"poet":"Serpil Ersoy Zümrüdüanka","poet_slug":"serpil-ersoy-zumruduanka","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/zumrudu-anka-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Asillik', 'sessiz-asillik-dr-yusuf-polat-631ef', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seninle sustuğum o eski kendimi…

Kimseye anlatamadım

Hayatın o en unutulmuş yerinde

Kimse görmedi belki de gerçeği 

Oysa bazı insanlar suskun doğmaz,

Dünya 

Onların ruhuna yetişemediği için

Onları kirletmemek adına 

Kendi halinde sensiz ve sesiz bırakır.', 'Seninle sustuğum o eski kendimi… Kimseye anlatamadım Hayatın o en unutulmuş yerinde Kimse görmedi belki de gerçeği  Oysa bazı insanlar susku...', ARRAY['Türk Edebiyatı','Şiir','Dr Yusuf Polat']::text[], 8.5, '{"poet":"Dr Yusuf Polat","poet_slug":"dr-yusuf-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sessiz-asillik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Bağdat Koydular', 'adini-bagdat-koydular-h-yusuf-sahan-u1hcr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neslihan kız 

o daha on dördünde

sevdalandı Hacı Hasan denen gence

Karadam köyünde düğün kuruldu

düğün tüm köylülere duyuruldu

beyaz at üstünde gelin oldu

zaman çok çabuk geçti

Hacı Hasan iyi bir eşti

Çocukları oldu ardı ardına

Bekir, Mahmut Sait Balı

çocuk ağlamaları sardı dört bir yanı

aralarında birer ikişer yaş

beklenmedik bir anda çıktı savaş

Hacı Hasan askere çağırıldı

birden neşeleri dağıldı

çift çubuk ortada kaldı

Neslihan’ı bir hüzün sardı

dedi sayılı gün nasıl olsa geçer

oldu hem ana hem rençper

sarı, kara öküzlere deh dedi

Dünya savaşı başladı

Hacı Hasan Bağdat cephesinde

İngiliz’e karşı yurdunu savundu

Neslihan’ın hayali ile avundu

siperine düştü bir el bombası

Şehit oldu Hacı Hasan

Çöl kumları ile buluştu kanlı bedeni

Acı haber köye çabuk ulaştı

tüm köy yasa büründü

zor günlerin

daha zoru göründü

Şehit eşi Neslihan gelin

topal Hacı Ali''ye nikâh kıydı

Hacı Ali topal olduğundan asker olmamıştı

Hacı Ali''den bir oğlu oldu

Şehit Bağdat''ta öldüğü için

Çocuğa şehrin adı verildi, Bağdat

Köyde kıtlık vardı

Hacı Ali Gülşehir''e buğday getirmeye gitti

eşeğin sırtında bir torba

İşte olanlar oldu yolda

eşkıyalar yol kesti

bir çuval buğday için Hacı Ali''yi kesti

Neslihan Gelin yine yalnız kaldı

üstelik köyün muhtarlığı da ona kaldı

tüm zorluklara rağmen

Çocuklarını büyüttü

Neslihan gelin muhtar olmuş duydunuz mu

dediler tüm çevre', 'Neslihan kız  o daha on dördünde sevdalandı Hacı Hasan denen gence Karadam köyünde düğün kuruldu düğün tüm köylülere duyuruldu beyaz at üstü...', ARRAY['Türk Edebiyatı','Şiir','H Yusuf Şahan']::text[], 8.5, '{"poet":"H Yusuf Şahan","poet_slug":"h-yusuf-sahan","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/adini-bagdat-koydular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Kokar Bu Mevsim', 'huzun-kokar-bu-mevsim-fusun-dudurga-zbdfl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Buram buram hüzün kokar bu mevsim

İlkbahar, yaz. sonbahar, kış derken

İliklerimize kadar hissederiz mevsimleri

Maviler, pembeler, yeşiller, allar

İlkbahar ve yaz rengarenk çiçeklenir dallar

Hazan''sa hüzün mevsimidir biliriz

Yine de efsununa kapılırız

Çünkü;

Biliriz her mevsimin ayrı bir güzelliği olduğunu

Ağaçlarda yeşilin, sarının, kırmızının bütün tonları

Yapraklar ise pamuk ipliğinin ucunda

Dalından düştü düşecek...

Güneş tribe girmiş, küstü küsecek

Bazen yağmur yağacak

Bazen rüzgar çıkacak

Bazen güneş açacak

Güz mevsimidir bu, aslını yaşatacak

Yazın gölgesinde oturduğumuz çınar ağaçları

Her şeye rağmen dimdik ayakta duracak

Gelen geçen sırtını yaslayacak

Bilmezler ki bu mevsim bir yaprak daha düşecek

Bir hayat daha sona erecek...

Doğanın kanunu bu;

Sırası geldiğinde birileri doğacak,

 Birileri ölecek...

Demem o ki;

Hiçbir şey aynı kalmayacak...

İstemesek bile;

İnsanlar da, mevsimler gibi değişecek

Bu kısır döngü böyle geldi, böyle gidecek.........', 'Buram buram hüzün kokar bu mevsim İlkbahar, yaz. sonbahar, kış derken İliklerimize kadar hissederiz mevsimleri Maviler, pembeler, yeşiller, ...', ARRAY['Türk Edebiyatı','Şiir','Füsun Dudurga']::text[], 8.5, '{"poet":"Füsun Dudurga","poet_slug":"fusun-dudurga","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/huzun-kokar-bu-mevsim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendine Dönüş', 'kendine-donus-dr-yusuf-polat-tjtf0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir bilsen, ben seni unutabilmek için

Kaç sevdanın kapısını çaldım.

Her kapıda 

Biraz daha kendimden uzaklaştım.

Bana gelenleri sevdim sanma sakın…

Her birinin gözlerinde seni aradım.

Birinin gülüşünde 

Çocuksu masumiyetini,

Birinin sesinde yarım kalmış duanı

Bir başkasının susmasında, kelamını

Kimseyi de senin yerine koyamadım

Yalnızca senden sonra

Eksilen hevesimin peşine düştüm.

Şimdi anlıyorum…

Benim aradığım yalnızca sen değildin

Senin yanında huzur bulan ben

Ben sana geldiğim her yolun sonunda

Kendime rastladım aslında

Belki de aşk,

Bir başkasında kendini bulmak değil,

Onla birlikteyken kaybettiğin kendine

Bir ömür boyu geri dönmeye çalışmaktır.', 'Bir bilsen, ben seni unutabilmek için Kaç sevdanın kapısını çaldım. Her kapıda  Biraz daha kendimden uzaklaştım. Bana gelenleri sevdim sanma...', ARRAY['Türk Edebiyatı','Şiir','Dr Yusuf Polat']::text[], 8.5, '{"poet":"Dr Yusuf Polat","poet_slug":"dr-yusuf-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kendine-donus-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Tanığım Ben', 'hep-tanigim-ben-kasim-kobakci-1dqnx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mahkeme kurulmuş, masum aklanmış,

Bazen sır verilmiş, bazen saklanmış,

Kul olan şaşsa da, özü paklanmış,

Davacı, davalı, hep tanığım ben.

*

Kulların kalemi, hükmünü yazar,

Aklanıp gelince, ezberi bozar,

Kim kimi ne diye, yargılar kızar,

Hakimim, savcıyım, tek sanığım ben.

*

Mahkeme duvarı, sert soğuk yüzler,

Sanki dar köprüde, aklanmış gözler,

Her insan bir dava, ayrıdır sözler,

Mübaşir, avukat, kor yanığım ben.

*

Eksik kalır bazen, kulun dengesi,

Adalet insanın, temiz simgesi,

İlimle silinir, cehlin gölgesi,

Şahidim, davayım, hem kanıtım ben.', 'Mahkeme kurulmuş, masum aklanmış, Bazen sır verilmiş, bazen saklanmış, Kul olan şaşsa da, özü paklanmış, Davacı, davalı, hep tanığım ben. * ...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hep-tanigim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelecek Bahar', 'gelecek-bahar-musli-soyler-ci347', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgi buhar oldu, damlası aşk...

Yalanla gıybet misali, kendi kendini yiyen yılan oldu. 

Kuraklık çöktü aşk''a sevgiye...

Sağanaklar gerek temizlenip yeşermeye...

Eskiler çok düşünür öz konuşurdu. 

Şimdiler düşünmeden yaygara koparır. 

Aşk buhar oldu göğe uçtu, 

bize kalan bir anlık suçtu, 

buharı gelecek bahara verdik.

Söyler bu feryadı ben gördüm,

Sevgiler bir çiçek dedik, onuda aşka kurban ettik. 

Aşkı yaşamayı bile beceremeden sevgiye mezar kazdık. 

Bereketli yağmurların yerini, kaybolan sevginin gözyaşları aldı. 

Bir damla bir damla daha, aşk sular altında kaldı.

Aşk buhar oldu göğe uçtu, 

bize kalan bir anlık huştu, 

buharı gelecek baharlara verdik.

Söyler bu feryadı ben gördüm,

Ne sevgiyi geri alabildik, ne aşkı yaşayabildik. 

Söyler bunu böyle gördü, gördüğünü de görmezden gelemezdi.', 'Sevgi buhar oldu, damlası aşk... Yalanla gıybet misali, kendi kendini yiyen yılan oldu.  Kuraklık çöktü aşk''a sevgiye... Sağanaklar gerek te...', ARRAY['Türk Edebiyatı','Şiir','Müsli Söyler']::text[], 8.5, '{"poet":"Müsli Söyler","poet_slug":"musli-soyler","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gelecek-bahar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu nasıl ülke.', 'bu-nasil-ulke-fehmi-tazegul-3xafl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Solmasın yüzler yaşlıdır gözler.

Çalınmış duygular yok hayaller.

Yetim çocuklar annelerini özler.

Bu nasıl bir ülke ne oldu böyle.

Ortalıkta dolaşır hırsız katiller.

Kalmadı yatacak yeriniz reziller.

Yalancı yalaka duyarsız insanlar.

Bu nasıl bir ülke ne oldu böyle.

Ölmesin çocuklar yüzler solmasın.

Canlara kıyanlara yazıklar olsun.

Bu ülkede herkes hür eşit yaşasın.

Bu nasıl bir ülke ne oldu böyle.

Fehmi.

Yaşasın dünyada bütün çocuklar.

Sokaklarda parkta evde oynasınlar.

Kardeşlikle can insanlığı öğrensinler.

Bu nasıl bir ülke ne oldu böyle.', 'Solmasın yüzler yaşlıdır gözler. Çalınmış duygular yok hayaller. Yetim çocuklar annelerini özler. Bu nasıl bir ülke ne oldu böyle. Ortalıkta...', ARRAY['Türk Edebiyatı','Şiir','Fehmi Tazegül']::text[], 8.5, '{"poet":"Fehmi Tazegül","poet_slug":"fehmi-tazegul","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-nasil-ulke-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgalıyım', 'dalgaliyim-musli-soyler-peui1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dalgalıyım bu aralar,

Gelgitler var yüreğimde.

Ne kıyıya vurabiliyorum,

Ne de huzur var derinimde.

Ne yağmurlar geldi geçti,

Ne seller aldı götürdü.

Herkes fırtına dindi sandı,

İçimdeki deniz büyüdü.

Sevda desem sevda değil,

Aşk desem hiç değil bu hâl.

Kendimle savaş içindeyim,

Yüreğimde bitmeyen bir hâl.

Ellerim var, tutamıyorum,

Gözlerim var, göremiyorum.

Kendi içimde kaybolmuşum,

Bir türlü yol bulamıyorum.

Ben dalgalıyım, ben yaralıyım,

Kendi kendime mahkûm kalmışım.

Ne gidebiliyorum, ne kalabiliyorum,

Kendi içimde kaybolmuşum.

Vur beni kıyılara, ey kader,

Ya da al götür uzaklara.

Bir gün diner mi bu fırtına?

Yoruldum artık dalgalara!

Güneş doğar, içim karanlık,

Günler geçer, bitmez yalnızlık.

Bir yanımda umut bekler,

Bir yanımda eski kırgınlık.

Ne zincirim var, ne duvarım,

Yine de çıkmaz sokaklardayım.

Özgür gibi görünsem bile,

Kendi içimde mahkûmum.

Ben dalgalıyım, ben yaralıyım,

Kendi kendime mahkûm kalmışım.

Ne gidebiliyorum, ne kalabiliyorum,

Kendi içimde kaybolmuşum.

Vur beni kıyılara, ey kader,

Ya da al götür uzaklara.

Bir gün diner mi bu fırtına?

Yoruldum artık dalgalara!

Ben dalgalıyım, kim anlar beni?

Kim duyacak içimdeki sesi?

Ne kıyı benim, ne deniz benim,

Kendime bile yabancıyım şimdi...', 'Dalgalıyım bu aralar, Gelgitler var yüreğimde. Ne kıyıya vurabiliyorum, Ne de huzur var derinimde. Ne yağmurlar geldi geçti, Ne seller aldı ...', ARRAY['Türk Edebiyatı','Şiir','Müsli Söyler']::text[], 8.5, '{"poet":"Müsli Söyler","poet_slug":"musli-soyler","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/dalgaliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedim de dedim...', 'dedim-de-dedim-raif-kemal-taner-taeur', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben bu hayatta en çok susmayı sevdim.

Gidenin arkasından bakana,

yolu kaybetmiştir, döner, dedim.

Gözündeki yaşı saklayan dosta,

gözüme toz kaçtı, neşeden, dedim.

Yalnızlığını odalara sığdıramayana,

kalabalıklar yorucu, en iyisi bu, dedim.

Yarınına karanlıkta bakan adama,

sabahı pek yakındır, görürsün, dedim.

Tükendiğini belli etmeyen insana,

enerjin harika, maşallah, dedim.

Son ümidini de cebine koyana,

daha çok yolumuz var, acele etme, dedim.

Sonra bana da iyi gelecektir, dedim.

Yoruldum ama alışıyorum, dedim.

Birazdan geçer, dedim.

Hepsini yuttum, dedim.

Dedim, dedim, dedim…', 'Ben bu hayatta en çok susmayı sevdim. Gidenin arkasından bakana, yolu kaybetmiştir, döner, dedim. Gözündeki yaşı saklayan dosta, gözüme toz ...', ARRAY['Türk Edebiyatı','Şiir','Raif Kemal Taner']::text[], 8.5, '{"poet":"Raif Kemal Taner","poet_slug":"raif-kemal-taner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dedim-de-dedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Etkinlik Zamanları', 'etkinlik-zamanlari-kasim-kobakci-cmx0t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Durgun geçti sıcak yazda etkinlik zamanları,

Ödedi ağır bedeli bu şehrin mekanları,

Kuruldu zihin sahnesi çaldı saz kemanları,

Doydu sanırım sanata okulun akranları.

*

Andıkça sessiz göründü yazın boş meydanları,

Taşıdı buruk yükünü güneşin dermanları,

Dizildi fikir ordusu yazdı öz destanları,

Avundu bence hünerle beldenin insanları.

*

Solgun başladı sahilde yaz günü seyranları,

Çekti bu durgun çileyi körfezin limanları,

Uyandı duygu korosu açtı sır divanları,

Kanmıştı artık ezgiye bahçenin fidanları.

*

Yorgun anıldı yaylada sıcak kamp kervanları,

Karşıladı tüm cefayı yörenin ormanları,

Toplandı hayal meclisi dizdi renk harmanları,

Erişti sanırım zevke köylerin mihmanları.

*

Issız geçti kavurucu temmuzun devranları,

Bölüştü sessiz kederi konağın eyvanları,

Canlandı sanat kurgusu serdi dil fermanları,

Gönenmiş oldu sanatla sahnenin hayranları.

*

Sönük kaldı hatırada şenliğin dumanları,

Yüklendi bütün tasayı mevsimin hicranları,

Söz aldı gönül heyeti coştu halk ozanları,

Yetindi herhalde sesle yurdun genç ceylanları.

*

Ağır ilerledi yazın törenli bostanları,

Örtüldü yaz şefkatiyle günlerin hüsranları,

Açıldı hüner perdesi giydi süs kaftanları,

Huzura kavuştu bence gençlerin vicdanları.

*

Böylece anıldı geçti yazın kor ummanları,

Kapatmış oldu borcunu sıcak yaz sultanları,

Duyuldu aklın bestesi sundular şükranları,

Doldu taşkın bir sanatla okulun kaptanları.', 'Durgun geçti sıcak yazda etkinlik zamanları, Ödedi ağır bedeli bu şehrin mekanları, Kuruldu zihin sahnesi çaldı saz kemanları, Doydu sanırım...', ARRAY['Türk Edebiyatı','Şiir','Kasım Kobakçı']::text[], 8.5, '{"poet":"Kasım Kobakçı","poet_slug":"kasim-kobakci","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/etkinlik-zamanlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alın Teri Yolcusu', 'alin-teri-yolcusu-sadik-kocabas-mz8w1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Alın Teri Yolcusu

Seher vakti kalktım, vurdum sabana,

Umut ektim şu verimli yabana,

El açıp yalvardım yüce Sübhan''a, 

Alın teri için düştüm yollara.

Güneş yaktı teni, rüzgâr savurdu,

Kara toprak beni böyle yoğurdu,

Sabrım nice zorlukları devirdi,

Helal lokma için düştüm yollara.

Ne hile bilirim ne de bir yalan,

 Gönülden verilir elde ne kalan,

Hak katında makbul, göklere salan,

Temiz kazanç için düştüm yollara.

Bir buğday tanesi bin umut taşır,

Kışın ayazında terimle pişer,

Sofraya gelince şükürler aşar,

Bereket uğruna düştüm yollara.

Kalemsiz Şair der, emek baş tacı,

Haramla beslenen duymaz o acı,

Helal lokma oldu derdin ilacı,

Çiftçinin izinde düştüm yollara.', 'Alın Teri Yolcusu Seher vakti kalktım, vurdum sabana, Umut ektim şu verimli yabana, El açıp yalvardım yüce Sübhan''a,  Alın teri için düştüm ...', ARRAY['Türk Edebiyatı','Şiir','Sadık Kocabaş']::text[], 8.5, '{"poet":"Sadık Kocabaş","poet_slug":"sadik-kocabas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/alin-teri-yolcusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakılacak Şiirler', 'yakilacak-siirler-i-brahim-cosar-6ekrl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sendin yüreğimdeki yangının müsebbibi

Adını andığımda gönlüm aşkınla doldu

Her gece yavrusunu yoklayan ana gibi

Sabahları ilk işim sayfana bakmak oldu

Aşkımı dikebilsem kalbinin toprağına

Gözyaşım şebnem olur kardelen yaprağına

Hiç alışkın değilim sevdanın ırağına

Kaderim sabır ile hasreti çekmek oldu.

Zamanla yükseldikçe hırsındaki ateşin

Sebepsizce el oldu sevdiğin gönül eşin

Aşkın kibrine yenik düştüğünde ilk işin

Vuslat için beslenen umudu yıkmak oldu

Coşari’nin gönlünde sevgili yatırı var

Gideni suçlayamam aşkının hatırı var

Her şiirin derdimi anlatan satırı var

Son işim şiirleri kalbimde yakmak oldu

14.11.2026/Samsun', 'Sendin yüreğimdeki yangının müsebbibi Adını andığımda gönlüm aşkınla doldu Her gece yavrusunu yoklayan ana gibi Sabahları ilk işim sayfana b...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Coşar']::text[], 8.5, '{"poet":"İbrahim Coşar","poet_slug":"i-brahim-cosar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yakilacak-siirler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Deli', 'i-ki-deli-fani-fena-1yi9y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu dünya da iki deli var ise 

O deli nin biri sensin biri ben 

İki deli birbirine yâr ise 

O deli nin biri sensin biri ben 

Uzaklaşır yaklaştıkça elimiz 

Olmayınca eksik olur birimiz 

Soranlar var, nerde bizim delimiz 

Çık ortaya! Biri sensin biri ben 

Birbirini yokluğuyla yaşatan 

Ta uzaktan çevreleyip kuşatan 

Kör kuyuya iki de bir taş atan

Delilerin biri sensin biri ben', 'Şu dünya da iki deli var ise  O deli nin biri sensin biri ben  İki deli birbirine yâr ise  O deli nin biri sensin biri ben  Uzaklaşır yaklaş...', ARRAY['Türk Edebiyatı','Şiir','Fani Fena']::text[], 8.5, '{"poet":"Fani Fena","poet_slug":"fani-fena","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iki-deli-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gîhant', 'g-hant-zandar-amari-20hfd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dema çavên te dikenin

Rojên tarî tev direvin

Xem û êş û kulên li min

Hemî ji min dur dikevin.', 'Dema çavên te dikenin Rojên tarî tev direvin Xem û êş û kulên li min Hemî ji min dur dikevin....', ARRAY['Türk Edebiyatı','Şiir','Zandar Amari']::text[], 8.5, '{"poet":"Zandar Amari","poet_slug":"zandar-amari","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gihant-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu devran değişecek', 'bu-devran-degisecek-ayhan-maloglu-2-zf6ey', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bütün gerçekler..

Darbe aldı..

Yenik düştü..

Örtülü yalanlara..

Adalet..

Ahlaksızların..

Soyguncuların..

Elinde..

Bir oyuncak..

Bu nasıl..

Yavşak bir çağ..

Yoksulun..

Bir dilim..

Ekmeğinin bile..

Yarısına..

Göz diktiler..

Ne yeseler doymuyor..

Hayasız şerefsizler..

Birkaç azılı firavun..

Dünyayı ele geçirmiş..

Zar atar gibi..

Eğleniyorlar..

Canları sıkılıyor..

Savaş çıkartıyorlar..

Çocuklar..

Açlıktan..

Yokluktan..

Savaşlarda ölüyor..

Zalimlerde olanları..

Köşklerinden seyredip..

Havyar yiyor..

Barıştan söz ediyor..

Silahlar üretip..

Barışı ilk vuranlar..

Dillerinde..

Pelesenk olmuş..

Bin bir yalanlar..

Elbet bir gün..

Diğer firavunlar gibi.. 

Sizin de..

Sonunuz gelecek..

Hiçbir zulüm..

Sonsuz değil..

O gün geldiğinde..

Bu devran değişecek..

Ayhan M.', 'Bütün gerçekler.. Darbe aldı.. Yenik düştü.. Örtülü yalanlara.. Adalet.. Ahlaksızların.. Soyguncuların.. Elinde.. Bir oyuncak.. Bu nasıl.. Y...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Maloglu 2']::text[], 8.5, '{"poet":"Ayhan Maloglu 2","poet_slug":"ayhan-maloglu-2","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/bu-devran-degisecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fillehbavê', 'fillehbav-zandar-amari-ouc64', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Evîndar bûm mal wêran bûm 

Li dûv gûlek bi êşan bûm 

Berî şad û wek paşan bûm 

Lê piştî wê perîşan bûm.

Ji ber destê dilê qeşmer 

Bûme behra kul û keser 

Mêze bike ji ber esmer

Her tişt danî li ber hember.

Dil û hişê''m bê şîret bûn 

Sergerdan û bi wê mest bûn 

Li xweşiyê bi hesret bûn 

Bi destê dil tev bin dest bûn

Li bîra min herî gava 

Li vê jînê wek gerrava

Bûye axîn bûye qarîn 

Bûya dilop li nav çava.

Tev demên min bi şînîne 

Heja jînê êdî nîne 

Dil bê hiş û bi evîne 

Gora sarî xweş hêlîne.', 'Evîndar bûm mal wêran bûm  Li dûv gûlek bi êşan bûm  Berî şad û wek paşan bûm  Lê piştî wê perîşan bûm. Ji ber destê dilê qeşmer  Bûme behra...', ARRAY['Türk Edebiyatı','Şiir','Zandar Amari']::text[], 8.5, '{"poet":"Zandar Amari","poet_slug":"zandar-amari","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/fillehbave-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökkubbede Hoş Sada', 'gokkubbede-hos-sada-muzaffer-uzunkaya-sho55', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Son çırpınışlarıdır hastaların,

Annelerin çırpınışları yürek dağlıyor,

Elden geldiğince yardım edelim,

Böykece Hak''kın rızasına erelim.

Şefkat pınaridır dertli analar, 

Gözyaşlarıyla erir solan goncalar,

Bir cana el uzat, bir derman ol ki,

Gökkubbede kalsın hoş sadalar.

14.11.2926

Kuşluhan köyü

Bulancak/Giresun

Not : İş bu şiir şair Muzaffer Hzunkaya ile Gemini yapay zeka işbiliği ile organ çalışma sonucu oluşturulmuştur.', 'Son çırpınışlarıdır hastaların, Annelerin çırpınışları yürek dağlıyor, Elden geldiğince yardım edelim, Böykece Hak''kın rızasına erelim. Şefk...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Uzunkaya']::text[], 8.5, '{"poet":"Muzaffer Uzunkaya","poet_slug":"muzaffer-uzunkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gokkubbede-hos-sada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gardaşım1', 'gardasim1-servet-bardak-aj9if', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gardaşım 

Satılmışım İnan beş on kuruşa 

Gelen vurdu beni İnan gardaşım 

Hüzünler yürekte dert çıkmış başa 

Gelen yordu beni İnan gardaşım

.

Çekilmez hayatım İçim kanıyor 

Gözlerim yaş ile yürek yanıyor

Beni gören inan dertsiz sanıyor 

Gelen kırdı beni inan gardaşım

.

Sinsi idi dostum düşman akrabam 

Acı''ma tuz kattı cahildi babam

Isıtmıyor artık şu yırtık abam 

Gelen yardı beni İnan gardaşım

.

Çeke çeke inan hasta yüreğim 

Gözlerim yaşarır yasta yüreğim

Hayallerim viran başta yüreğim

Gelen yerdi beni İnan gardaşım

.

Acımadı kimse akan yaşıma 

Dert kederler geldi garip başıma

Sitemler ederim şu yoldaşıma

Gelen vurdu beni İnan gardaşım

.

Serveti sırtından almış mavzeri

Ciğeri yanıyor sönmüyor harı

Kışla geçti günü görmez baharı

Gelen serdi beni inan gardaşım

.

14.11.2026

Servet BARDAK', 'Gardaşım  Satılmışım İnan beş on kuruşa  Gelen vurdu beni İnan gardaşım  Hüzünler yürekte dert çıkmış başa  Gelen yordu beni İnan gardaşım ....', ARRAY['Türk Edebiyatı','Şiir','Servet Bardak']::text[], 8.5, '{"poet":"Servet Bardak","poet_slug":"servet-bardak","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gardasim-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bundan Sonra Şiir Yazmam', 'bundan-sonra-siir-yazmam-i-smail-malatya-4xgxq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Defterim şiirle doldu

Bundan sonra şiir yazmam

Yazdım yazdım da ne oldu

Bundan sonra şiir yazmam.

Kalpler olmuş mezar taşı

Yalnız geçirdim tüm kışı

Sadece duygu akışı

Bundan sonra şiir yazmam.

İsmail MALATYA bize

Göre değil dörtlük dize

Söylüyorum şimdi size

Bundan sonra şiir yazmam.', 'Defterim şiirle doldu Bundan sonra şiir yazmam Yazdım yazdım da ne oldu Bundan sonra şiir yazmam. Kalpler olmuş mezar taşı Yalnız geçirdim t...', ARRAY['Türk Edebiyatı','Şiir','İsmail Malatya']::text[], 8.5, '{"poet":"İsmail Malatya","poet_slug":"i-smail-malatya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bundan-sonra-siir-yazmam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkıldı Tüm Hayalimiz', 'yikildi-tum-hayalimiz-ahmet-kolecioglu-nymbo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ne güneş ne ay doğuyor

karanlık beni sarıyor

yüreğim kabus doluyor

yokluğun inan  boğuyor

böyle değildi kavlimiz

perişan oldu halimiz

kavuşamadık ikimiz

yıkıldı tüm hayalimiz

açtım ellerimi sana

yalvarıyorum yaRabbim 

revamıydı bu ayrılık

nedir bizim günahımız

tek arzu tek muradımız

kavuşmaktı dileğimiz

hasrete mahkum edildik

ayrılıklar sebebimiz

kölecioğlu der sevgili

böyle değildi kavlimiz

perişan oldu halimiz

kavuşamadık ikimiz

yıkıldı tüm hayalimiz

Ahmet kölecioğlu     2015', 'ne güneş ne ay doğuyor karanlık beni sarıyor yüreğim kabus doluyor yokluğun inan  boğuyor böyle değildi kavlimiz perişan oldu halimiz kavuşa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kölecioğlu']::text[], 8.5, '{"poet":"Ahmet Kölecioğlu","poet_slug":"ahmet-kolecioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yikildi-tum-hayalimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alnımın Terini Sileyim Yeter', 'alnimin-terini-sileyim-yeter-sadik-kocabas-gnpu8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ALNIMIN TERİNİ SİLEYİM YETER

Mutlu olacaksan yükle sırtıma,

Gerek yok isyana, dur de aklıma.

Su taşıtma bana zengin çarkına,

Nefesim alırken güleyim yeter.

Çocuk yaşta bana alış mı dedin,

Acıyla dert ile tanış mı dedin,

Kapı kapı dolaş çalış mı dedin,

Alnımın terini sileyim yeter.

Eğdirdin başımı namert kullara,

Sattırdın onurum para pullara.

Düşürdün ömrümü en sarp yollara,

Dostun bir selamın alayım yeter.

Yıllar geçip gitti ne kaldı elde,

Koskoca bir hiçim değerim yerde.

Felekle efkârı sırt sırta ver de,

Takdiri ilahi bileyim yeter.

Kalemsiz Şair’im budur tek sözüm,

Dünyanın malında kalmadı gözüm.

Köz olup tütse de şu garip özüm,

İnsanlık yolunda öleyim yeter.

🖋️ Kalemsiz Şair', 'ALNIMIN TERİNİ SİLEYİM YETER Mutlu olacaksan yükle sırtıma, Gerek yok isyana, dur de aklıma. Su taşıtma bana zengin çarkına, Nefesim alırken...', ARRAY['Türk Edebiyatı','Şiir','Sadık Kocabaş']::text[], 8.5, '{"poet":"Sadık Kocabaş","poet_slug":"sadik-kocabas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/alnimin-terini-sileyim-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicran Şerbeti', 'hicran-serbeti-zeyno-garagiz-tpjgz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mevsimler değişti, açmıyor güller,

Adını anmaktan yoruldu diller,

Bizi ayırmaya yeminli eller,

Sarmayacak beni o zalim kolun,

Yabana mı düştü uzadı yolun.

Hicranı şerbetle içirdin bana,

Yine de beddua etmedim sana,

Gülmedi şu talih hiç benden yana,

Özlemin dumanı göğe yürüdü,

Sensizlik ruhumu gama bürüdü.

Hasretin yükünü sırtıma vurdun,

Beni benden alıp uzakta durdun,

Ayrılık saâtini kalbime kurdun,

Bütün umutları gömdüm toprağa,

Döndürdün ömrümü gazel yaprağa,

Geceler karanlık gündüz dayanmaz,

Sensiz kalan kalbim renge boyanmaz,

Gözlerim ufukta vuslat uyanmaz,

Bilinmez yollara savruldu bahtım.

Ölsem de vazgeçmem sensin tek tahtım.

Kapandı kapılar  yollarım ırak, 

İçimde sönmeyen  yangınlar bırak. 

Kurudu bağlarım her taraf kurak

Bıraktın ya beni dertle baş başa, 

Mevsimim döndü bak  zamansız kışa. 

Fısıldadım sana her bir heceyi,

Seninle unuttum gündüz geceyi,

Çözemedim gitti bu bilmeceyi,

Zehir ettin bana baharı güzü,

Geriye bıraktın bir yığın közü.

Garagız''ım Firkât sinem paralar,

Kapanmaz içimde derin yaralar,

Aşkının uğruna giydim karalar,

Önce sarayımdın şimdi talanım.

Sen cennet bahçemdin şimdi yalanım.

Zeyno Garagız kãlemi 🖊

Zeynep Senem

Muhammes kalıbı', 'Mevsimler değişti, açmıyor güller, Adını anmaktan yoruldu diller, Bizi ayırmaya yeminli eller, Sarmayacak beni o zalim kolun, Yabana mı düşt...', ARRAY['Türk Edebiyatı','Şiir','Zeyno Garagız']::text[], 8.5, '{"poet":"Zeyno Garagız","poet_slug":"zeyno-garagiz","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/hicran-serbeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fonlayıp Gitti', 'fonlayip-gitti-hasan-arpaci-9ve8v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu yıl kabakları sam yeli vurdu,

Soğanları soğuk donlayıp gitti.

Hıyarlar plaza deyip kudurdu,

O da gelenleri zonlayıp gitti.

Ekinden yulaftan para kazandık,

Bazen şarkı söyler bazen ozandık,

Hali ahvallere destan yazandık,

Oğullar damatlar anlayıp gitti.

Kasalara sığmaz oldu paralar,

Yurt dışına kaçar oldu danalar,

Arkasından ağıt yakan analar,

Ağlarken kulaklar çınlayıp gitti.

Basiretsiz memur hırsızdan amir,

Olunca karıştı cümlede zamir,

Çalanlar Müslüman çalmayan kafir,

Olunca hayaller vınlayıp gitti.

Hasan yaza yaza bitmez bu dertler,

Çalanlar şehzade kutsal bu fertler,

Lakin dolmuyor ki delik sepetler,

Garip gurubayı fonlayıp gitti.

Hasan Arpacı, 2026, Üsküdar', 'Bu yıl kabakları sam yeli vurdu, Soğanları soğuk donlayıp gitti. Hıyarlar plaza deyip kudurdu, O da gelenleri zonlayıp gitti. Ekinden yulaft...', ARRAY['Türk Edebiyatı','Şiir','Hasan Arpaci']::text[], 8.5, '{"poet":"Hasan Arpaci","poet_slug":"hasan-arpaci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/fonlayip-gitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Binimiz Bizim', 'binimiz-bizim-ozcan-kurt-tkvct', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BİNİMİZ BİZİM
‎
‎Sulari, soluğu, Hasret, kolunda, 
‎AKARSU ileyiz, Sivas yolunda, 
‎Nesimi üç telli, cura tınında, 
‎Yeniden yazılır, yazgımız bizim., 
‎
‎Hallaç göğe atar, yanan külümüz, 
‎Topraktan aldık GÖR, Veysel izimiz, 
‎Ölümüz yoktur ki.. Özde dirimiz, 
‎Bir giderse gelir..Binimiz bizim.. 
‎
‎O''nun yeri gönül, gönül kırmayız, 
‎Gendimizde arar, hata bulmayız, 
‎Mahzuni ve Sultan, ABDAL, olmuşuz, 
‎Vazgeçtik de durur..Serimiz bizim.. 
‎
‎Teni darda koduk, bildik bir hiçiz.. 
‎Tevhit meyi ile,bizden geçmişiz, 
‎Nesimi Ser-ü pa, serdik derimiz, 
‎Zikreder Enel Hak..Özümüz bizim.. 
‎
‎Perdeler silindi,  buldum LA perde.. 
‎Bir damla idim ben, yittim denizde, 
‎ZAHİT boğulma sen, yönüm derinde, 
‎Hatayi kandilden, gücümüz bizim.. 
‎
‎Özvecan naçarım, döndüm gendime, 
‎İç yüzüme yönüm, gönül pirime,
‎Kav ettim tenimi, gökte cürmüme, 
‎Bir Kaadirden gelir, közümüz bizim..', 'BİNİMİZ BİZİM ‎ ‎Sulari, soluğu, Hasret, kolunda,  ‎AKARSU ileyiz, Sivas yolunda,  ‎Nesimi üç telli, cura tınında,  ‎Yeniden yazılır, yazgım...', ARRAY['Türk Edebiyatı','Şiir','Özcan Kurt']::text[], 8.5, '{"poet":"Özcan Kurt","poet_slug":"ozcan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/binimiz-bizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Okul Okumuş da Olsa,', 'okul-okumus-da-olsa-huseyin-cubuk-0hgd1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Okul okumuş da olsa,

 Bizim köyün kara eşeği!

 Nereden bilecek Atatürk''ü, hasan emmi!

 Onun, mutlaka çok kıskandığı ve sevmediği insanlar vardır, Atatürkçü bildiği.. 

 Yani, ondandır; Onun, olur olmaz zamandaki Atatürk tepksi!

  Hem, eşekdiiiiir; Eşek utanmayı bilir mi, hasan emmi!" /h.ç', 'Okul okumuş da olsa,  Bizim köyün kara eşeği!  Nereden bilecek Atatürk''ü, hasan emmi!  Onun, mutlaka çok kıskandığı ve sevmediği insanlar va...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Çubuk']::text[], 8.5, '{"poet":"Hüseyin Çubuk","poet_slug":"huseyin-cubuk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/okul-da-okumus-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇOCUKLAR II.', 'cocuklar-ii-hasan-savas-2-1iq96', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ÇOCUKLAR II.
I

Ey hayat!

Çok şey istemiyorum senden.

Bakkala gönderdim çocuk,

Elinde ekmek,

Bir de kapıyı açtığımda,

Yüzünde o bildik gülümsemeyle dönsün

Yeter....
II
Ben çocuklara gülmeyi öğrettim

Bir de kuşlara uçmayı 

Ölsem de gam yemem...


III
Sizi leylekler getirmiş çocuklar, leylekler

Ne de güzel olmuş 

Sağ olsun leylekler 

Sağ olsun...


IV

Umurunda değil artık 

Kaç bahar göreceğim

Kaç kış geçireceğim

Hiç bir şikayetim yok, olmayacak da

Soframda gülüşen çocuklar yetiyor bana..


Hasan Savaş / Almanya', 'ÇOCUKLAR II. I Ey hayat! Çok şey istemiyorum senden. Bakkala gönderdim çocuk, Elinde ekmek, Bir de kapıyı açtığımda, Yüzünde o bildik gülüms...', ARRAY['Türk Edebiyatı','Şiir','Hasan Savaş 2']::text[], 8.5, '{"poet":"Hasan Savaş 2","poet_slug":"hasan-savas-2","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/cocuklar-ii-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülün Unuttuğu Koku', 'gulun-unuttugu-koku-seyrani-gol-cj4vi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonbahar, aynalarda çürüyen bir renk;

bir gül, gecenin yakasında kanıyor.

Kokusu hâlâ gönül bahçeme sinmiş,

Kim bilir şimdi o, hangi ayrılığa gömülü?

Hangi rüzgâr çevirdi yüzünü benden,

hangi susuş ördü aramıza bu kışı?

Sen giderken bir yaprak bile kıpırdamadı;

demek ki en derin vedalar sessizmiş.

Söyle, hangi mevsimde unuttun beni?

Hangi bahçede yeniden açtı yüzün?

Ben hâlâ aynı dalın gölgesindeyim;

senin yokluğun, bütün güllerden eski.

Gece, son yaprağı da toprağa bırakıyor.

Ayaz, taşların hafızasına işliyor.

Bir gülün kokusu kalır mı ölümünden sonra,

yoksa bahçe mi unutur kendi baharını?

Şimdi ne gül eski kokusunda,

ne de bahçe eski yerinde.

Bir tek şu sitem kaldı zamana:

İnsan, hangi yoklukta çiçek açar bir daha?

S.GÖL', 'Sonbahar, aynalarda çürüyen bir renk; bir gül, gecenin yakasında kanıyor. Kokusu hâlâ gönül bahçeme sinmiş, Kim bilir şimdi o, hangi ayrılığ...', ARRAY['Türk Edebiyatı','Şiir','Seyrani Göl']::text[], 8.5, '{"poet":"Seyrani Göl","poet_slug":"seyrani-gol","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gulun-unuttugu-koku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm', 'gonlum-murat-acer-p2x0s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir çıkmaza düştüm sorma 

Öyle yanar tüter gönlüm 

Ne haldeyim gelip görme 

Dertli bülbül öter gönlüm 

Bağrımda yaralar benim 

Yok gücüm dermanım benim 

Bir yar sevdim o da zalim 

Felek krar kolum benim 

Kaldım bir zalim eline 

Merhamet etmez gönlüme 

Dertli sazım bu döşüme 

Vurup vurup ağlar gönlüm 

Tütmüyor ocağım benim 

Kalmadı dermanım benim 

Bir zalim sevdi yüreğim 

Anam ağlar ne söyleyim

Viraneler yurdundayım 

Yıkık dökük gönlüm benim 

Hep o yarin derdindeyim 

Ne çekerim bilmez zalim 

Hürmeti yokmuş aşkıma 

Acımaz Gözde yaşıma 

Kan kattı tatlı aşıma 

Zehir etti ne söyleyeyim', 'Bir çıkmaza düştüm sorma  Öyle yanar tüter gönlüm  Ne haldeyim gelip görme  Dertli bülbül öter gönlüm  Bağrımda yaralar benim  Yok gücüm der...', ARRAY['Türk Edebiyatı','Şiir','Murat Acer']::text[], 8.5, '{"poet":"Murat Acer","poet_slug":"murat-acer","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gonlum-342-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***HARAMLARI HELAL SAYARLAR***', 'haramlari-helal-sayarlar-abdulhamit-gezer-v2nut', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sizin şeref meyhanelerde gezer

Zihniyette yalan iftara öğretirler

Sapıkları hainlikleri çok severler

Rahmani yasaları hiç istemezler

Şeytani yasalarla çok eğlenirler

Haramları helal sayar lanetlikler', 'Sizin şeref meyhanelerde gezer Zihniyette yalan iftara öğretirler Sapıkları hainlikleri çok severler Rahmani yasaları hiç istemezler Şeytani...', ARRAY['Türk Edebiyatı','Şiir','Abdülhamit Gezer']::text[], 8.5, '{"poet":"Abdülhamit Gezer","poet_slug":"abdulhamit-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/haramlari-helal-sayarlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***KURARLAR-KORURLAR***', 'kurarlar-korurlar-abdulhamit-gezer-d15mf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Onursuzlar yalakalık peşinde gezer

Arsız şerefiniz meyhanelerde gezer

Namusları cadde sokaklarda gezer

Şeytani oyunlarla tuzaklar kurarlar

Bu hain zihniyet yalan iftara öğretirler 

Sapıklara hainlere kalkan yol verirler

Rahmani yasalarla yaşamayı istemler

Şeytani yasalarla kendilerini korurlar', 'Onursuzlar yalakalık peşinde gezer Arsız şerefiniz meyhanelerde gezer Namusları cadde sokaklarda gezer Şeytani oyunlarla tuzaklar kurarlar B...', ARRAY['Türk Edebiyatı','Şiir','Abdülhamit Gezer']::text[], 8.5, '{"poet":"Abdülhamit Gezer","poet_slug":"abdulhamit-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kurarlar-korurlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Düştüm', 'yorgun-dustum-cinar-demir-ekyv7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Agırlaştı bedenim bu gece
Senli düşünçelere kapılarak 
Senli hayallere dalarak 
Yorgun düşmeye  başadı senin yoklugunda bedenim

Ustam 
Alatsam anlatılmıyor 
Sussam yüregim susmuyor
Uyusam uyku tutmuyor

Yar
Yoklugun cekilmez olmuş 
Yalan dünya yaşanmaz olmuş
Ben ise sensiz kalmışım 

Benligim
Kendine gelmelisin 
Gecelerin uykusuzlugu 
Yarın yoklugu 
Yalan dünyanın kahrı 
Yoruyor  kendine gel kendine', 'Agırlaştı bedenim bu gece Senli düşünçelere kapılarak  Senli hayallere dalarak  Yorgun düşmeye  başadı senin yoklugunda bedenim Ustam  Alats...', ARRAY['Türk Edebiyatı','Şiir','Çınar Demir']::text[], 8.5, '{"poet":"Çınar Demir","poet_slug":"cinar-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yorgun-dustum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Zamanımı', 'al-zamanimi-mikail-cekim-etch1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayatımız gün gün
Sevgimiz dümdüz
Burası yokuştur
Dikkat et gündüz

Ölüyorum aşkından
Ölüyorum sevginden 
Neredeydi bu aşk
Hiç görmedim seni

Ağlar mısın benim için
Ölürmüş benim için
Hayatımı sana verdim
Harcama günlerini

Kaleme  vurdum aşkı
Kağıda yazdım sevgiyi
Unutulmaz o günleri
Nerdesin sen gülüm
.....', 'Hayatımız gün gün Sevgimiz dümdüz Burası yokuştur Dikkat et gündüz Ölüyorum aşkından Ölüyorum sevginden  Neredeydi bu aşk Hiç görmedim seni ...', ARRAY['Türk Edebiyatı','Şiir','Mikail Çekim']::text[], 8.5, '{"poet":"Mikail Çekim","poet_slug":"mikail-cekim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/al-zamanimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Bu Mektubu', 'al-bu-mektubu-mikail-cekim-k5rvl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yazdım sana satır satır
Okudum şiirini takır takır
Noldu o şiirine 
Bekledim Asır Asır

Gönderdim hep mektubu
Okumadın sen hepsini
Küstüm biz dünyadan
Akar hep gözümde yaş 

Hitap ederim hep sana
Okumadın mı o mektubu
Ayrıldığı burada
Terk ettin benim gönlümü

Anlattım sana derdimi
Bilmem anladın mı? 
Aldatıldım 1 kere
Yıkıldım bin kere

Kul ister , Allah verir
Putt''tan ister ,Allah verir 
Gönlümü ister ben vermem
Göz yaşı döker giderim buradan.', 'Yazdım sana satır satır Okudum şiirini takır takır Noldu o şiirine  Bekledim Asır Asır Gönderdim hep mektubu Okumadın sen hepsini Küstüm biz...', ARRAY['Türk Edebiyatı','Şiir','Mikail Çekim']::text[], 8.5, '{"poet":"Mikail Çekim","poet_slug":"mikail-cekim","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/al-bu-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Kötü Zamanda Yaşıyoruz Biz', 'ne-kotu-zamanda-yasiyoruz-biz-dursun-alabiyik-2-ic88y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'NE KÖTÜ ZAMANDA YAŞIYORUZ BİZ

Kanaat kalmadı insanoğlunda

Ne kötü zamanda yaşıyoruz biz

Bile-bile haram lokma yiyorlar

Ne kötü zamanda yaşıyoruz biz

Hiç mi gözü doymayacak kulların

Neden sapıttılar doğru yolların

Durulmak bilmiyor gözü pınarın

Ne kötü zamanda yaşıyoruz biz

Hakkına kanaat eden kalmadı

Fakirler yaşıyor kimse aç ölmedi

Çoğu yakalandı çoğu gelmedi

Ne kötü zamanda yaşıyoruz biz

Kimi ev kiralar para koymaya

Halkı soymak için gelmiş oraya

Bilmiyorum götürecek nereye

Ne kötü zamanda yaşıyoruz biz

ÂŞIK SEFİL daha en iyi günler

Gitmekte yorulduk çok çetin yollar

Kiminin sofrasında kaymaklar ballar

Helal lokma kuru soğan yaşıyoruz biz

14.11.2026

ÂŞIK SEFİL DURSUN ALABIYIK

AĞLAMA GÖZÜNE YAZIK', 'NE KÖTÜ ZAMANDA YAŞIYORUZ BİZ Kanaat kalmadı insanoğlunda Ne kötü zamanda yaşıyoruz biz Bile-bile haram lokma yiyorlar Ne kötü zamanda yaşıy...', ARRAY['Türk Edebiyatı','Şiir','Dursun Alabıyık 2']::text[], 8.5, '{"poet":"Dursun Alabıyık 2","poet_slug":"dursun-alabiyik-2","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ne-kotu-zamanda-yasiyoruz-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutlu Toprağım Güzel Köyüm', 'kutlu-topragim-guzel-koyum-faruk-tosun-tnmi5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ruhlar aleminden

Yeryüzüne indiğim

İlkleri yaşadığım

Kutlu toprağım

Güzel köyüm

İlk nefes aldığım 

İlk su ile yıkandığım

Gökyüzüne baktığım

Yıldızların altında kaldığım

Kutlu toprağım

İlk emeklediğim

İlk yürüdüğüm

Kuzularla koştuğum

Bağlarında çoştuğum

Güzel köyüm

Kirazların içinde

Dutların dibinde

Derelerin içinde

Tepelerin zirvesinde 

Kutlu toprağım

Bağların arasında yuvarlandığım

Pekmezle yoğurduğu karıştırdığım

Ağ tepeden Erciyes’e baktığım

Toprağında taşında dolaştığım

Güzel köyüm 

İlk sana kulluğa başladığım

Secdeye vardığım 

İftar yaptığım

Bayramlaştığım

Kutlu toprağım

Güzel köyüm', 'Ruhlar aleminden Yeryüzüne indiğim İlkleri yaşadığım Kutlu toprağım Güzel köyüm İlk nefes aldığım  İlk su ile yıkandığım Gökyüzüne baktığım ...', ARRAY['Türk Edebiyatı','Şiir','Faruk Tosun']::text[], 8.5, '{"poet":"Faruk Tosun","poet_slug":"faruk-tosun","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/kutlu-topragim-guzel-koyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet', 'i-hanet-mikail-cekim-zljxt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '4 duvarda kala kaldı
Aşkımızın kalbi kuru kaldı 
Nolfu hayatımıza
Vazgeç bu aşktan

Senden geçti bu aşk
Suda aktı zaman
Söndürdüm gönlümü
Kül ettin kalbimi

Güzelliğin başka 
Aşkın başka 
İhanetin başka 
Gelme yanıma

Nurda yattım 
Toprağa gittim
Hatırlama beni
Uğraşma benle


Saçının güzelliği hepsi yalan
İhanet ettin bana 
Gidiyorum sensiz', '4 duvarda kala kaldı Aşkımızın kalbi kuru kaldı  Nolfu hayatımıza Vazgeç bu aşktan Senden geçti bu aşk Suda aktı zaman Söndürdüm gönlümü Kül...', ARRAY['Türk Edebiyatı','Şiir','Mikail Çekim']::text[], 8.5, '{"poet":"Mikail Çekim","poet_slug":"mikail-cekim","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ihanet-618-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaktın Beni', 'yaktin-beni-mikail-cekim-7poub', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Oturdum yalnız
Durdu zamanım
Kalbim atar mı?
Gelmez o âşk bidaha

Nazım durdu
Yüreğimde kanlar var
Gönlümde sönmüş ateş,
Yaktır o gönlü

Kül olan aşk alev alır mı?
Kapanmış kalbi açabilir mi?
Nerde o günler
Özledim seni

Yalnız yürüyorum
Hüzünlü aşkı 
Kaleme aldım ihaneti 
Aldattın sen beni.', 'Oturdum yalnız Durdu zamanım Kalbim atar mı? Gelmez o âşk bidaha Nazım durdu Yüreğimde kanlar var Gönlümde sönmüş ateş, Yaktır o gönlü Kül o...', ARRAY['Türk Edebiyatı','Şiir','Mikail Çekim']::text[], 8.5, '{"poet":"Mikail Çekim","poet_slug":"mikail-cekim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yaktin-beni-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıralar', 'hatiralar-mikail-cekim-0vlqc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geçer bizim güzel günler
Geçerdi bizim anılarımız
Kayboldu geçmişte
Şimdi ise çerçevede

Geldi geçti günler
Nerde o neşeler
Okundu bizim hatıralar
Yazıldı bizim kaderimiz

Çok özledim o günleri  canlandırak anılarımızı

Neden bitirdik aşkımızı
Neden bitirdik sevgiyi
Hoşakal sevgili
Hoşakal küçüklüğüm', 'Geçer bizim güzel günler Geçerdi bizim anılarımız Kayboldu geçmişte Şimdi ise çerçevede Geldi geçti günler Nerde o neşeler Okundu bizim hatı...', ARRAY['Türk Edebiyatı','Şiir','Mikail Çekim']::text[], 8.5, '{"poet":"Mikail Çekim","poet_slug":"mikail-cekim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hatiralar-312-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazıldı', 'yazildi-mikail-cekim-izl0c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yazıldı aşkımız
Yazıldı kalbime
Silme o kaderi
Duanın faydası yok

Yazıldı önceden kaderin
Silemezsin o anıları
Ölücez biz  dünyada
Yardım et banada

Yazılır o ihanetler,
Yazılır o aşkımız
Mecnunmu oldum ben
Aşkıma kavuşmaları


Yazılır o hayat
Yazılır o günahlar
Neden beni istemiyorsun
Git sil beni kalbinde.', 'Yazıldı aşkımız Yazıldı kalbime Silme o kaderi Duanın faydası yok Yazıldı önceden kaderin Silemezsin o anıları Ölücez biz  dünyada Yardım et...', ARRAY['Türk Edebiyatı','Şiir','Mikail Çekim']::text[], 8.5, '{"poet":"Mikail Çekim","poet_slug":"mikail-cekim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yazildi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Geçmişi', 'hayatin-gecmisi-mikail-cekim-etd4e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geldi,ben seninle
Tarih yazdık seninle
Okuyacağız hep birlikte
Pes etme o gönlünde


3.başlığa geldim
Anlamadım hayatı
Nasıl böyle olduysa
Bahsetme sen bana


Bırakacan o kitabı 
Bırakacan o hayatı
Bitti gönül aldırma
Kimse yardım etmez sana


Nerde kaldın sen
Güzelliğimemi kaldın
Bitti bu aşk  
Kapandı o kitap.', 'Geldi,ben seninle Tarih yazdık seninle Okuyacağız hep birlikte Pes etme o gönlünde 3.başlığa geldim Anlamadım hayatı Nasıl böyle olduysa Bah...', ARRAY['Türk Edebiyatı','Şiir','Mikail Çekim']::text[], 8.5, '{"poet":"Mikail Çekim","poet_slug":"mikail-cekim","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hayatin-gecmisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buzlar', 'buzlar-serkan-alakus-610pd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kimlere yazılıyor bu kelimeler cümleler 

Hangi diyara uzanıyor uzunca yollardan

Neler bekliyor acaba o uzak diyarlarda 

Ne dertler taşıyorlar hep bir gam bir figan 

Kızlardan çok buzlara yazarmış birileri 

Söyleyin bana hangi buzu eritebilmiş 

Ben kaçıyorum her birinden birer birer 

Yüreğim ne soğuğa ne acıya dayanabilmiş 

Döküyorum harfleri mısraların tam ortasına 

Bir iç çekip nefes veriyorum arkasından 

Hüzünlü bir tını ulaşıyor kulaklarıma 

Daha hiç bahsetmedim içimin yarasından', 'Kimlere yazılıyor bu kelimeler cümleler  Hangi diyara uzanıyor uzunca yollardan Neler bekliyor acaba o uzak diyarlarda  Ne dertler taşıyorla...', ARRAY['Türk Edebiyatı','Şiir','Serkan Alakuş']::text[], 8.5, '{"poet":"Serkan Alakuş","poet_slug":"serkan-alakus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/buzlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Yağmuru', 'sevgi-yagmuru-guliz-ardilli-vlakc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seviyorum sevgilimi,

Seviyor sevgilim beni,

Düşünüyoruz hep birbirimizi. :)

13-14 Kasım 2026  İstanbul', 'Seviyorum sevgilimi, Seviyor sevgilim beni, Düşünüyoruz hep birbirimizi. :) 13-14 Kasım 2026  İstanbul...', ARRAY['Türk Edebiyatı','Şiir','Güliz Ardilli']::text[], 8.5, '{"poet":"Güliz Ardilli","poet_slug":"guliz-ardilli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgi-yagmuru-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceden', 'geceden-aydin-cetinkaya-kfhjc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'GECEDEN

Bin mana gelirse geceden hece hece

Her mana hecede bilinmeyen bilmece.

Yıldızları göz edip göz kırpsa gündüzlere,

Her mana geceden gündüzlere gülmece.', 'GECEDEN Bin mana gelirse geceden hece hece Her mana hecede bilinmeyen bilmece. Yıldızları göz edip göz kırpsa gündüzlere, Her mana geceden g...', ARRAY['Türk Edebiyatı','Şiir','Aydın Çetinkaya']::text[], 8.5, '{"poet":"Aydın Çetinkaya","poet_slug":"aydin-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/geceden-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Yeniden Doğdum', 'seninle-yeniden-dogdum-taha-bilal-mustafa-kekec-zcyw1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gece indi üstüme sessizce,

Ayazdı içim, karanlık ince ince.

Sonra gözlerin değdi kalbime,

Bir anda değişti kaderim seninle.

Kalbim adını fısıldar her nefeste.

Aşkın çiçek açar en karanlık yerde.

Ben sende eridim usulca teninde,

Sen bende yeniden doğdun kalbimde.

Gülüşün güneş gibi doğar içime,

Bir öpücük kalır dudak izimde.

Başını koy göğsüme yavaşça,

Zaman dursun ikimizin arasında.

Yanımda kal, dünya dursun isterim,

Gözlerinde kaybolup evim derim.

Bir tek sen anla hâlimden,

Bu kalp seninle tamam, eminim.

Ellerin ellerimde, korkum yok artık,

Geçmişin izleri silindi bir bir.

Ne fırtına söndürür içimdeki ateşi,

Adını yazdım kalbime derin derin.

Bir sen bilirsin içimdeki çocuğu,

Kırık yanımı, sustuğum korkuyu.

Sar beni, dağılsın bütün gölgeler,

Adınla başlasın sabahlarım her sefer.', 'Bir gece indi üstüme sessizce, Ayazdı içim, karanlık ince ince. Sonra gözlerin değdi kalbime, Bir anda değişti kaderim seninle. Kalbim adını...', ARRAY['Türk Edebiyatı','Şiir','Taha Bilal Mustafa Kekeç']::text[], 8.5, '{"poet":"Taha Bilal Mustafa Kekeç","poet_slug":"taha-bilal-mustafa-kekec","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seninle-yeniden-dogdum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canın cennete', 'canin-cennete-emine-genc-lxl6y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Metazori olmaz işler.

Hakmış, bilhasa

Sevilmek ister.

Ne göğün göynü kişner

Ne murad''ı onu diler..

Olmasa da, o duâya amin der.

Ömür iflas etmiş.

Zaar, on sekizmiş(!)

Koşmak ister.

Dereye inmez taylar

Arpaya gülmez, bizâr..

Yürü, soyun sürü..

Akla gelmez, fak

Desise türlü, türlü..

Çapın dar,  yüze lâzım astar.

Nasıl gelirse işine..

Düzü ters, tersi düz eder.

Uymaz hesabı

Kısa kalır niyaz''ı.

İşte bu kadar!

Benden ırak, cennete türâb.

14 Kasım 2020/ 05:40', 'Metazori olmaz işler. Hakmış, bilhasa Sevilmek ister. Ne göğün göynü kişner Ne murad''ı onu diler.. Olmasa da, o duâya amin der. Ömür iflas e...', ARRAY['Türk Edebiyatı','Şiir','Emine Genç']::text[], 8.5, '{"poet":"Emine Genç","poet_slug":"emine-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/canin-cennete-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilime', 'sevgilime-mevlut-karakus-qubvv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aştığım yollar değil Çektiğim hasret yaktı
Giderken değil gelmediğin de yandım
Mesafe değilmiş tüketen aklımı
Ya Sensizlik alacak canımı
Ya ben alacağım canımdan öte olanı
Şimdi ezgisinde hasret çalan bu türkünün
Son bendinde vuracak tellerine vuslat’ı
Güzelimmm, ben ve gök; masmavi
Bulutlar sevgilim, dağılmışlar koşa koşa
Düşmesin diye vuslatımıza gölgesi
Semadan izlenir bu sevginin gösterisi
İkimizde özlemedik mi birbirimizi
Henüz yanyanayken halbuki
Demekki hasret değilmiş bizimki 
Kokunu duyunca anladım ki
Bilinen binlerce lügatta yok bunun tarifi
Kaç şiir daha yazarım bilmem 
Ama her yazdığımda anla ki
İlk günki gibi çok seviyorum seni', 'Aştığım yollar değil Çektiğim hasret yaktı Giderken değil gelmediğin de yandım Mesafe değilmiş tüketen aklımı Ya Sensizlik alacak canımı Ya ...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Karakuş']::text[], 8.5, '{"poet":"Mevlüt Karakuş","poet_slug":"mevlut-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sevgilime-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Haramdır Bana', 'askin-haramdir-bana-alparslan-karagoz-k9v1s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uçan kuştan her gün seni sorduğum

Yetsin bu gönlün aklına uyduğum

Taş bile olsa başımı koyduğum 

Dizin haramdır bana bundan böyle

Düşmesin yoluma bir daha yolun

Gelmeye tutmasın kanadın kolun

Dursa da canımda sıktığın kurşun

Sızın haramdır bana bundan böyle

İstemem senden gelecek merhemi 

Son soluğumda elinden Zemzemi

Kırdım hatrını anacak kalemi

Adın haramdır bana bundan böyle 

Kapına gelecek olursam bir an

Taş kesilsin bedenim , ayağım kan

Varmadan göçürsün beni bu cihan

Yurdun haramdır bana bundan böyle

Bir gün bükülmüş ihtiyar bedenimle 

Ak dolmuş saçım , kırışmış tenimle 

Hep yaşayacak olsan da benimle

Aşkın haramdır bana bundan böyle

14 Kasım 2026', 'Uçan kuştan her gün seni sorduğum Yetsin bu gönlün aklına uyduğum Taş bile olsa başımı koyduğum  Dizin haramdır bana bundan böyle Düşmesin y...', ARRAY['Türk Edebiyatı','Şiir','Alparslan Karagöz']::text[], 8.5, '{"poet":"Alparslan Karagöz","poet_slug":"alparslan-karagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/askin-haramdir-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlatlarıma [nasihat]', 'evlatlarima-nasihat-ozan-ahmet-zile-la2ij', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığı çöktüğü zaman

Bittim tükendim dediğin an.

Sade ona yönel ,ona inan .

çareler önunde diz coker oğul.!

Dersin buymuş kaderim buymuş yazım .

Ana ,baba kardaş ,bir yanda bacım 

Çaresizlik içimde geçmeyen sızım .

Sabırla koruk helva olur kızım 

Dostuna paranı deme, düşmana sırrını,

Alsanda dünyaları ona verme yarını .

Acı rüzgarlara vermiş bağrını 

Yel gibi savurup atarlar oğul !

 Kol kırılır yen içinde kalır.

Aile sırların yerinde durur.

Deme ellere  sakın seni oradan vurur 

Îki kişinin bildiği sır, sır değil kızım .

Her yüze gülene derdini açma, 

muhannet çok zor gerisi saçma .

Ara gazla, takma kanatla havada uçma .

Düşüşün sert olur bilesin oğul.!

Geceler sabahlara kadar kuzum. 

Dertlere çare arar ,bir lahza 

Bir ışık bize  artar. bir lokma 

Bir hırka da bize yeter .

Huzur kanaatte saklıdır kızım .

Bilirim nasihat gençleri sıkar.

Kısadan keseden herşey  olsun ister 

Dünya müsallim insanlar zalim, 

Ne yazık ki gerçekler budur yavrularım 

[Ozanahmet]', 'Gecenin karanlığı çöktüğü zaman Bittim tükendim dediğin an. Sade ona yönel ,ona inan . çareler önunde diz coker oğul.! Dersin buymuş kaderim...', ARRAY['Türk Edebiyatı','Şiir','Ozan Ahmet Zile']::text[], 8.5, '{"poet":"Ozan Ahmet Zile","poet_slug":"ozan-ahmet-zile","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/evlatlarima-nasihat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyiki Varsın Cancağızım', 'i-yiki-varsin-cancagizim-nobetci-sair-s5ukx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seninle beraber her zaman mutlu oldum 
Ne kadar derdim varsa hepsini unuttum 
Gönlümün prensesini sonunda buldum 
İyi ki hayatıma girdin sen cancağızım 

Yıldızlar sönük kalır o tatlı yüzüne,
Can kurban olsun senin her bir sözüne,
Esir oldum o masum, gülen gözüne,
İyi ki hayatıma girdin sen cancağızım

Adını kazıdım kalbimin ta derinine,
Hiç kimse sığmaz inan ki yerine,
Canım kurban olsun senin sevgine,
İyi ki hayatıma girdin sen cancağızım.

Yolumuz aşk ile nurlarla dolsun,
Mutluluğumuz ebedi, daim olsun,
Kıskananlar çatlasın, alem duysun,
İyi ki hayatıma girdin sen cancağızım.', 'Seninle beraber her zaman mutlu oldum  Ne kadar derdim varsa hepsini unuttum  Gönlümün prensesini sonunda buldum  İyi ki hayatıma girdin sen...', ARRAY['Türk Edebiyatı','Şiir','Nöbetçi Şair']::text[], 8.5, '{"poet":"Nöbetçi Şair","poet_slug":"nobetci-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iyiki-varsin-cancagizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusurdan Yaratılan Yeryüzü', 'kusurdan-yaratilan-yeryuzu-ersin-gulezer-tpuuj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '​Ne gök vardı o vakit, ne kara yer,
Ne ay doğmuştu henüz, ne gün batardı.
Sadece su vardı;
Uçsuz, bucaksız, dipdiri, karanlık bir su...
Rüzgâr bile bilmezdi nereden eseceğini,
Zaman bile bulmamıştı daha kendi sesini.
​İki ak kaz gibi süzülürdü boşlukta
Biri yüce Kayra Han, biri ilk gölgesi Erlik.
Kanat çırptıkça köpürürdü kadim deniz;
Konacak bir dal yoktu, basacak bir taş yoktu,
Yalnızca bitmeyen bir uçuş,
Yalnızca derinden gelen o büyük susuş...
​Tam o vakit yarıldı suların göğsü,
Köpüklerden doğdu Ak Ana,
Saçları ışık, bakışı duru.
Seslendi boşluğa:
"Ey Kayra!
Yaratmak istersen eğer,
Sözün ateş olsun, nefesin kudret!
''Yarat!'' de ki dikilsin göğün direği,
''Oldu!'' de ki yeşersin yerin yüreği."
​Kayra Han "Yarat!" dedi,
Suların karnından kabarıp yükseldi toprak.
Daldı derinlere Erlik,
Avuç avuç kara balçık çıkardı dipten.
Lakin bir tutamını sakladı ağzında;
"Benim de gizli bir dünyam olsun" dedi içinden,
Hırs bürüdü gözünü, kibir doldu özüne.
​Kayra "Büyü!" dedikçe toprağa,
Şişti Erlik''in ağzındaki gizli balçık;
Boğulacak gibi oldu, tükürdü karanlığa.
O tükürükten doğdu sarp kayalar, bataklıklar,
Düz olan yeryüzü o gün kırıldı,
Işık ile karanlık işte o an ayrıldı!
​Böyle kuruldu gök çadır, böyle gerildi yer yayı,
Ülgen ışıkla ördü dokuz katlı sarayı;
Erlik ise çekildi yerin yedi kat dibine,
Karanlık bir taht kurdu kendi kibrine.
O günden beri ne zaman çalsa bir kamın davulu,
Titrer yerin altı, uyanır göğün ulu yolu;
Su hatırlar ilk sözü, toprak hatırlar közü,
Ve rüzgâr hâlâ taşır bozkırda o eski', '​Ne gök vardı o vakit, ne kara yer, Ne ay doğmuştu henüz, ne gün batardı. Sadece su vardı; Uçsuz, bucaksız, dipdiri, karanlık bir su... Rüzg...', ARRAY['Türk Edebiyatı','Şiir','Ersin Gülezer']::text[], 8.5, '{"poet":"Ersin Gülezer","poet_slug":"ersin-gulezer","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kusurdan-yaratilan-yeryuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitti Sevdam', 'bitti-sevdam-cihan-berdibek-d7y6d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anla artık vefasız yar

Bitti her şey bitti sevdam

Dönme geri hayırsız yar

Bitti her şey bitti sevdam

Kinim yanar yakar beni

Kefen gibi sıkar beni

Hayalinden çıkar beni

Bitti her şey bitti sevdam

Gönlüm sevdi gözüm değil ,

Bu ayrılık çözüm değil,

Canım yandı özüm değil

Bitti her şey bitti sevdam', 'Anla artık vefasız yar Bitti her şey bitti sevdam Dönme geri hayırsız yar Bitti her şey bitti sevdam Kinim yanar yakar beni Kefen gibi sıkar...', ARRAY['Türk Edebiyatı','Şiir','Cihan Berdibek']::text[], 8.5, '{"poet":"Cihan Berdibek","poet_slug":"cihan-berdibek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bitti-sevdam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiroshima’nın Kıskandığı Kadın', 'hiroshima-nin-kiskandigi-kadin-arda-keskinkilic-35ldy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hiroshima’ya atılan bomba değil de,

İloshima’dan gelecek mesafe yaralar beni.

Bir şehrin gündüzü savrulur dağılır,

bir kadının adı kalır gecenin içinde;

ne mesafe söndürür onu

ne de zamanın eli.

Chicago’da bir akşamüstü,

Michigan Gölü’ne eğilir gökyüzü.

Rüzgâr, uzak ülkelerin bütün kelimelerini

senin saçlarında uyutur.

Gökdelenler yükselir, şehir küçülür;

tebessümün ecnebi caddelerde yürür,

ansızın mimari bir detaya dönüşür.

Ah, İloshima!

Saçlarında tabiatın kendiyle kavgası,

bir tutam gece, biraz sonbahar…

Ben bu gece bir aşk şiiri yazmadım.

Korkma, saçlarına bakarken

gözlerinde kaybolmadım.

Böyle bir hukuki ihtilafımız yok.

Yalnızca içimde, kıtaları aşındıran

o ihtiyar hayret,

adını duyunca yeniden gençleşti.

Hâlbuki İloshima diye bir yer yok haritalarda.

Yok öyle bir kent, bir beşer;

ne bir liman ne bir cadde,

ne de bir ruha sığan suret…

Oysa bilirim,

bazı coğrafyalar bir kadının isminden doğar.

Ve bütün mesafeler

biraz da senin yüzünden icat edilmiş olabilir.

Seni gecelerde yeniden Hiroshima diye anarım,

tarihin en büyük yanılgısını hatırlamak için:

Bir şehri yıkmak kolaymış meğer,

bir kadının adını dünyaya sığdıramamak

daha büyük bir meseleymiş.

Ve ben, bütün bu kıyametin ardından…

Hiroshima’ya düşen gölgeyi değil,

İloshima’nın saçlarına düşen akşamı kıskanırım.', 'Hiroshima’ya atılan bomba değil de, İloshima’dan gelecek mesafe yaralar beni. Bir şehrin gündüzü savrulur dağılır, bir kadının adı kalır gec...', ARRAY['Türk Edebiyatı','Şiir','Arda Keskinkılıç']::text[], 8.5, '{"poet":"Arda Keskinkılıç","poet_slug":"arda-keskinkilic","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/hiroshima-nin-kiskandigi-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ufuk Çizgisi', 'ufuk-cizgisi-tolga-gunhan-6atmm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalabalık şehirlerde uykulu gözler

Kendini kandıran hain düşler

Samimi sandığın yalancı yüzler

Hep ardımda vefalı gölgem

Bilinçsiz bir yere doğdum

Akıllı olmayı umdum

Yerdekiyle gökteki arasında

Yığınla hayal kurdum', 'Kalabalık şehirlerde uykulu gözler Kendini kandıran hain düşler Samimi sandığın yalancı yüzler Hep ardımda vefalı gölgem Bilinçsiz bir yere ...', ARRAY['Türk Edebiyatı','Şiir','Tolga Günhan']::text[], 8.5, '{"poet":"Tolga Günhan","poet_slug":"tolga-gunhan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ufuk-cizgisi-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkarcıdır Zorbalar', 'cikarcidir-zorbalar-kenan-gezici-ynsv3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zorbalar için kendilerinden başka yoktur can.

Her şey evrilir, değiştirilir onlara muhalif olan.

Kaç kitap değişti, sayamazsın kaç yasa.

Yalanlandı, öldürmeyeceksin denen emir.

Kendini kutsal sayar, anası babası belli değil.

Öldürüldü, kendilerine emri getiren resul.

Sakınmaz azgın, fitne çıkarmak etmiş şiar.

Yediği insandır, bir tekine etmez merhamet.

Sataşır sağa sola bir dirhem eksilse çıkar.

İnsan hayatı peh, onlar için daima bir kaynak.

Medet bekleyen onlara olmuş kol kanat.

Yüzleri, dilleri benzer bize yani insana.

Tanımak için kendinden olana sen bakma.

Elinde kötülük var, yalnız kendine yaşıyorsa bak.

Bir de düşün ki inanmak onun ağız alıştırdığı.

Ateşe veriyorsa bir damla çıkarı için sen ona bak.

Kenan GEZİCİ   14/11/2026', 'Zorbalar için kendilerinden başka yoktur can. Her şey evrilir, değiştirilir onlara muhalif olan. Kaç kitap değişti, sayamazsın kaç yasa. Yal...', ARRAY['Türk Edebiyatı','Şiir','Kenan Gezici']::text[], 8.5, '{"poet":"Kenan Gezici","poet_slug":"kenan-gezici","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cikarcidir-zorbalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bahar Gibiydin', 'bir-bahar-gibiydin-arif-vefik-cinar-co31d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir Bahar Gibiydin

Bir bahar gibiydin

Çiçeklerini kokunu saçtın

Bir bahar gibiydin 

Damla damla yağmur oldun

Gönül toprağıma

Irmak ırmak nehir nehir taştın

Bir bahar gibiydin

Hem gülüşümdün benim

Hem gözümde yaştın

Bir bahar gibiydin

Ilık ılık bakışlarınla

İçimde ne yaralar açtın

Bir bahar gibiydin sen

Bir bahar gibi

Çok erken kaçtın.

Arif Vefik ÇINAR 

13.11.2026 Bünyan/KAYSERİ', 'Bir Bahar Gibiydin Bir bahar gibiydin Çiçeklerini kokunu saçtın Bir bahar gibiydin  Damla damla yağmur oldun Gönül toprağıma Irmak ırmak neh...', ARRAY['Türk Edebiyatı','Şiir','Arif Vefik Çınar']::text[], 8.5, '{"poet":"Arif Vefik Çınar","poet_slug":"arif-vefik-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-bahar-gibiydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Bir İklimin Saklısı', 'uzak-bir-i-klimin-saklisi-ersin-gulezer-c648e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Engin bir yalnızlığın ortasında, gün batımına dönük yüzün,

Gök rengi bir atlasın ucunda saklıdır şimdi bütün hüzün.

Lalelerin toprağı ilk kez yardığı o uzak ve serin baharda,

İsmini rüzgâra fısıldar gurbet, kimsesiz kalan sokaklarda.

İlim peşinde tüketirken ömrünün en güzel, en taze çağını,

Satır aralarında örersin kendi yarınlarının o görkemli ağını.

Sonsuz bir maviliğin altında süzülürken altın kanatlı bir kartal,

Benden çok uzaklarda, bambaşka bir göğün altında huzurla kal.

Ayazı camlara vururken o uçsuz bucaksız, mağrur bozkırın,

Sıcaklığı hiç sönmesin içinde, geçmişten kalan o güzel sırrın.

Bir elma çiçeğinin beyazında saklıdır şimdi eski bir mevsim,

Ne zaman rüzgâr esse doğudan, dudaklarımda titrer o malum isim.

Eski masallardan kalma bir asaletle mağrur ve derin,

Kendi destanını yazarsın şimdi, uzağında bütün bildik yerlerin.

Tanrı dağlarının zirvesinden süzülen o berrak ve serin rüzgâr,

Fısıldasın saçlarına, benden habersiz, sana adanmış ne kadar dua var.

Hiç bilmeyeceksin bu mısraların aslında sana adandığını,

Yalnızca gökyüzü bilecek, bir ömür kalbimde saklandığını.', 'Engin bir yalnızlığın ortasında, gün batımına dönük yüzün, Gök rengi bir atlasın ucunda saklıdır şimdi bütün hüzün. Lalelerin toprağı ilk ke...', ARRAY['Türk Edebiyatı','Şiir','Ersin Gülezer']::text[], 8.5, '{"poet":"Ersin Gülezer","poet_slug":"ersin-gulezer","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/uzak-bir-iklimin-saklisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç işte .', 'hic-iste-lena-clever-ecbre', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ruh yoksa

Kalp hiç sızlar mı? 

Zeka yoksa kalp karar verir mi? 

Bin kapı aşındırsan

İyiyle, kötü 

Hiç bir olur mu?.. 14.11.2026', 'Ruh yoksa Kalp hiç sızlar mı?  Zeka yoksa kalp karar verir mi?  Bin kapı aşındırsan İyiyle, kötü  Hiç bir olur mu?.. 14.11.2026...', ARRAY['Türk Edebiyatı','Şiir','Lena Clever']::text[], 8.5, '{"poet":"Lena Clever","poet_slug":"lena-clever","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hic-fikrim-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eve Dönen Yabancı', 'eve-donen-yabanci-ersin-gulezer-q1m5u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Söyle bana ey rüzgâr, Ege’nin tuzlu hafızası,

Bir şehrin küllerinden kaç ömür savrulur göğe?

Troya düştü dediler, tunç surlar eridi ateşte,

Oysa bilmezdi kimse: Savaş bittiğinde başlar asıl yenilgi.

Tahta bir atın karnında saklanan o karanlık öfke,

Zafer çığlıklarıyla bindi kara gövdeli gemilere;

Ve denize açılan her yelken, ardında yanan bir dünyanın

İsini taşıdı dönüş yolunun bitmek bilmeyen gecelerine.

Odysseus, kurnaz akıl, İthaka’nın yorgun kralı,

On yıl kılıç salladı yabancı bir toprağın göğsüne,

On yıl da dalgalarla boğuştu evine varabilmek için;

Ama dönen adam, giden adam değildi artık.

Kiklop’un mağarasında kör ettiği o tek göz,

Savaşın insana bıraktığı körlüktü aslında;

İsimsiz kalmıştı kahraman, "Hiç Kimse" demişti kendine—

Çünkü cephede adını yitiren, evinin yolunu da unuturdu.

Lotos yiyenlerin kıyısında duraksadı yoldaşları,

Tek bir çiçekle silmek istediler belleklerindeki kanı;

Unutmak, en sarp sığınaktı artık en cesur savaşçıya bile.

Direğe bağlattı kendini Odysseus, kürekçilerin kulakları balmumuyla tıkalı;

Sirenlerin ezgisi eski zaferlerin zehirli şarkısıydı çünkü:"Gel," diyordu sesler, "ne kadar yüceydin surların önünde!"

Oysa geçmişin ihtişamına kulak veren her gemi,

Kendi kemiklerinin kayalığında parçalanmaya mahkûmdu.

Hades’in sisli kıyısına indiğinde gördü eski dostlarını;

Akhilleus bile fısıldadı karanlığın içinden o çıplak gerçeği:"Ölülerin kralı olmaktansa, yeryüzünde bir köylünün tarlasındaGündelikçi olmayı yeğlerdim, ey Odysseus!"

Kahramanlık dedikleri, mezar taşlarına kazınan soğuk bir avuntuydu.

Denizlerin ötesinde İthaka, taşlı ve suskun bir ada,

Savaşın kılıcı uzanmamıştı belki kıyılarına

Ama ağır gölgesi çökmüştü Penelope’nin tezgâhına.

Gündüz dokuduğu kefeni gece söken o yorgun eller,

Zamanı durdurmaya çalışan bir kadının sessiz çığlığıydı.

Telemakhos, babasının yüzünü hiç bilmeyen bir çocuk,

Tanımadığı bir adamın efsanesiyle büyüdü;

Çünkü savaş, yalnızca cephede düşenleri değil,

Evde bekleyenlerin de ömründen çalar yıllarını.

Talipler sofralarda tüketirken adanın bereketini,

Her kapı gıcırtısında bir umut doğup ölüyordu eşikte.

Ve bir sabah, dalgalar çıplak ve tuzlu bir bedeni attı İthaka kumlarına.

Ne miğferi vardı başında, ne parlayan tunç zırhı;

Bir dilenci kılığında girdi kendi sarayının avlusuna.

Sadık köpeği Argos tanıdı onu yalnızca,

Son bir kez kuyruğunu sallayıp kapattı gözlerini—

Savaşın geciktirdiği bir kavuşmaya ancak bu kadar dayandı kalbi.

Yay gerildi, oklar konuştu, salon yeniden kızıla boyandı;

Ama kılıçlar indiğinde geriye kalan yine derin bir sessizlikti.

Penelope gözlerine baktığında o eski delikanlıyı aradı,

Bulduğu ise saçlarına denizlerin akı düşmüş,

Göz bebeklerinde yanan şehirlerin gölgesini taşıyan bir yabancıydı.

Kâhin Tiresias’ın sözü çınladı kulaklarında son kez:"Al omzuna bir gemi küreğini," demişti ölüler diyarında,"Ve yürü karaya doğru, denizi hiç bilmeyen insanların diyarına dek.Ta ki biri durdurup seni: ''Omzundaki o harman savurma küreği de ne?'' diyene kadar."

İşte o an anlayacaktı Odysseus asıl kurtuluşu:

Savaşın izi ancak, bir savaş aracının

Toprağı besleyen bir emeğe benzetildiği yerde silinirdi.

Bırak artık omzundaki o tuzlu küreği toprağın kalbine,

Ateşin külleri değil, başakların altını örtsün ovaları;

Rüzgâr kılıç şakırtısı yerine zeytin dallarını okşasın artık,

Irmaklar kan rengini unutup gökyüzünün mavisini taşısın denize,

Şafak, hiçbir annenin kapısına yas getirmeden doğsun İthaka’ya.', 'Söyle bana ey rüzgâr, Ege’nin tuzlu hafızası, Bir şehrin küllerinden kaç ömür savrulur göğe? Troya düştü dediler, tunç surlar eridi ateşte, ...', ARRAY['Türk Edebiyatı','Şiir','Ersin Gülezer']::text[], 8.5, '{"poet":"Ersin Gülezer","poet_slug":"ersin-gulezer","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/eve-donen-yabanci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçin için...', 'i-cin-icin-kalender-kalem-gokp0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Konuşunca çok olmamak gerek

Çok ileri gitmemek için

Susunca da çok ölmemek gerek

Acılara kapanmamak için için...

Kalender Kalem', 'Konuşunca çok olmamak gerek Çok ileri gitmemek için Susunca da çok ölmemek gerek Acılara kapanmamak için için... Kalender Kalem...', ARRAY['Türk Edebiyatı','Şiir','Kalender Kalem']::text[], 8.5, '{"poet":"Kalender Kalem","poet_slug":"kalender-kalem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/icin-icin-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasan''a Mektup - 9', 'hasan-a-mektup-9-abdurrahim-karakoc-n612l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çok oku, çok düşün, çok şeyler anla,

Aha bu mektubu alınca Hasan.

Manalar iplikten incedir amma,

Kelimeler biraz kalınca Hasan.

Gene ağzımızı açmıyor bıçak,

Huzur size ömür..... Dert salkım saçak.

Oyuna kalkıyor yüzlerce köçek,

Batıdan bir hava çalınca Hasan.

Kök saldı bahçede ayrık otları,

Yemler pay edildi, sattık atları.

Biz kovalım derken baştan bitleri,

Sülükler yapıştı, kulunca Hasan.

Süt dolu güğümü çalarız taşa,

Kutsal görevimiz ''Sağol çok yaşa! ''

Mülkte hakikati aramak boşa,

Tüm suçlular güçlü olunca Hasan.

Derisini yüzdük demokrasinin,

İşi iştir imtiyazlı asinin.

Hakikatte vahşi, sözde ''vasinin''

Dörtnala gidilir yolunca Hasan.

Canım Hürriyeti koydunsa ara,

Ekmek yalınayak kaçtı dağlara.

Çevremize küsmüş kardeşlik var ya,

Haber ver, izini bulunca Hasan.

Soysuzlar taş atar mukaddesata

Karşı duramazsak bizdedir hata.

Tahammül teşviktir, böyle hayata,

Öl... İnsan küçülmez ölünce Hasan.

(Vur Emri)', 'Çok oku, çok düşün, çok şeyler anla, Aha bu mektubu alınca Hasan. Manalar iplikten incedir amma, Kelimeler biraz kalınca Hasan. Gene ağzımız...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hasan-a-mektup-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Haber', 'kara-haber-abdurrahim-karakoc-zjix5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerin yurdunda çiçek açarken

Bizim İl''e kar geliyor gardaşım.

Bu hududu kimler çizmiş gönlüme? 

Dar geliyor, dar geliyor gardaşım.

Gazel olmuş sıra sıra söğütler

Dağ ardında unutulmuş şehitler

Hürriyete seymen giden yiğitler

İki gidip bir geliyor gardaşım.

Üç aylık bebekler tutuldu taşa

Düşmanlar geriden eyler temaşa

Yaratan böylesin vermesin başa

Zor geliyor, zor geliyor gardaşım.

(Vur Emri)', 'Ellerin yurdunda çiçek açarken Bizim İl''e kar geliyor gardaşım. Bu hududu kimler çizmiş gönlüme?  Dar geliyor, dar geliyor gardaşım. Gazel o...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kara-haber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terketmedi Sevdan Beni', 'terketmedi-sevdan-beni-ahmed-arif-idwsi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Terketmedi sevdan beni,

Aç kaldım, susuz kaldım,

Hayın, karanlıktı gece,

Can garip, can suskun,

Can paramparça…

Ve ellerim kelepçede,

Tütünsüz, uykusuz kaldım,

Terketmedi sevdan beni…', 'Terketmedi sevdan beni, Aç kaldım, susuz kaldım, Hayın, karanlıktı gece, Can garip, can suskun, Can paramparça… Ve ellerim kelepçede, Tütüns...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Arif']::text[], 8.5, '{"poet":"Ahmed Arif","poet_slug":"ahmed-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/terketmedi-sevdan-beni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'umut', 'umut-sabri-keskin-ygmtz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uçmak için kanat çıpsanda uzaklara

Gönül bu hemen koyuverirmi dersin

Bir vuruşta kıyılırmı gülüm sevdalara

Vursan bile sevdalar ölürmü dersin

Gözler görmez, eller tutmasa bile

Kelimeler durup, kelepçe vursa dile

Karanlık yüreği dertli viran şehire

Sevda güvercinleri uçururmu dersin

Haber versem kara gözlü esmerim 

Sonkez olsun ellerime gelirmisin

Sonsuz bir uyku için kapandı gözlerim

Göz yaşları mezarıma dökülürmü dersin', 'Uçmak için kanat çıpsanda uzaklara Gönül bu hemen koyuverirmi dersin Bir vuruşta kıyılırmı gülüm sevdalara Vursan bile sevdalar ölürmü dersi...', ARRAY['Türk Edebiyatı','Şiir','Sabri Keskin']::text[], 8.5, '{"poet":"Sabri Keskin","poet_slug":"sabri-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu', 'bu-sabri-keskin-v96ku', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saman alevi gibi, soğuk bir ateş bu

Son bakış, maziye son dokunuş bu

Ağlayan bir rüya, ağlatan sevda bu

Leyla''nın gözleri, mecnun''un çölleri bu

Hasretin bittiği, kalbin nefreti bu

Acımasız yılların kahbe kurşunu bu

Başlangıcın sonu, sonun başlangıcı bu

Ölüm bu, yaşam bu, sevda bu', 'Saman alevi gibi, soğuk bir ateş bu Son bakış, maziye son dokunuş bu Ağlayan bir rüya, ağlatan sevda bu Leyla''nın gözleri, mecnun''un çölleri...', ARRAY['Türk Edebiyatı','Şiir','Sabri Keskin']::text[], 8.5, '{"poet":"Sabri Keskin","poet_slug":"sabri-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ozlem', 'ozlem-sabri-keskin-cxbd9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dudaklarını özledim yanaklarını

bakışlarını, sıcak dokunuşlarını özledim

özlediğim zannettiğim günleri özlediim

saçlarını özledim, rüzgarda dağışlarını

seni özledim birtanem yalnız seni

telefondaki sesini, suskunluğunu

seni beklediğim yerleri özledim

geç kalmanı yalanlarını, mazeretlerini

ellerini özledim, parmaklarını, tırnaklarını

seni özledim bir tanem yalnızca seni

ağlamanı özledim, beni ağlatmanı

kızdığın zaman bağırmanı kaçmanı

sonu özledim, sonunda sunsuzluğu

gidişini, sessiz ve duygulu gidişini özledim

seni özledim aşkım yalnızca seni', 'dudaklarını özledim yanaklarını bakışlarını, sıcak dokunuşlarını özledim özlediğim zannettiğim günleri özlediim saçlarını özledim, rüzgarda ...', ARRAY['Türk Edebiyatı','Şiir','Sabri Keskin']::text[], 8.5, '{"poet":"Sabri Keskin","poet_slug":"sabri-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ozlem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıyrılıp Gelen', 'siyrilip-gelen-ahmet-telli-24t5z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SOLUK BİR AY DOLANIYOR

KENTİN ÜSTÜNDE HER GECE

HER GECE BİLGE BİR GEZGİN

TAVRIYLA ADIMLIYOR YOLUNU

GÜZ YANIĞI BİR DURGUN

SESSİZLİKLE ÖRTÜLÜ HER ŞEY

VE YIRTILMIŞ BİR TÜL GİBİ 

SAVRULUP DURUYOR ZAMAN

SULARIN SESİNİ DİNLE ŞİMDİ

ORMANIN FISILDAYIŞLARINI

USULCA YARILIYOR DAĞLARIN GÖĞSÜ

BİR AŞKI DİNLENDİRMEK İÇİN

VE GÖZLERİ UZAK YAMAÇLARDA 

ARANIP DURURKEN BİR ŞEYLERİ

SESSİZ VE SAKİN BEKLEMEKTE

BEKLEDİKÇE BİLEYLENEN BİR YÜREK

BELLİ Kİ DAĞLARIN DENİZLERİN 

VE GÖLLERİN ÜZERİNDEN

SIYRILIP GELMEKTEDİR SEHER

BELLİ Kİ YAKINDIR

BELLİ Kİ YAKINDIR DOĞAYI 

VE HAYATI SARSACAK SAAT', 'SOLUK BİR AY DOLANIYOR KENTİN ÜSTÜNDE HER GECE HER GECE BİLGE BİR GEZGİN TAVRIYLA ADIMLIYOR YOLUNU GÜZ YANIĞI BİR DURGUN SESSİZLİKLE ÖRTÜLÜ ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/siyrilip-gelen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansız', 'i-mkansiz-atilgan-alemdar-plydm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bizim evin orada martılar vardı

Büyük beyaz vapurlar 

ama,

bizim evin orada 

            deniz yoktu

Yıkılıp giden bir kalbim vardı 

içinde sen vardın 

ama,

sen yoksun', 'Bizim evin orada martılar vardı Büyük beyaz vapurlar  ama, bizim evin orada              deniz yoktu Yıkılıp giden bir kalbim vardı  içinde ...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/imkansiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun', 'yoklugun-atilgan-alemdar-3eu2o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimi zaman beklemek 

yaşamaktan daha iyi değil mi?

imkansızlığın bilmecesi

hangi kapıya çıkar bilir misin?

Çamurdan yapılmış bir çocuk heykeli

nasıl ağlar yağmurda bilir misin?

Bilir misin gözleri bir mum gibi erir

saçları sabun gibi akar ensesinden

sonra ağzı kırılır çenesi hüzünlenir

bilir misin tek kelime söyleyemeden

bir suçlu gibi yaşayıp ölmek nedir?

Saat sabahın beşi beş geçesi diyor

sokaklarda köpek bile kalmamış

başına böyle bir belanın gelmesi için

imkansızlık kapısında ağlaman gerektiğini

                                                   hiç bilmeyeceksin

O çocuğun haline kim olsa ağlar

hele yokluğuna hedef olmuşsa', 'Kimi zaman beklemek  yaşamaktan daha iyi değil mi? imkansızlığın bilmecesi hangi kapıya çıkar bilir misin? Çamurdan yapılmış bir çocuk heyke...', ARRAY['Türk Edebiyatı','Şiir','Atılgan Alemdar']::text[], 8.5, '{"poet":"Atılgan Alemdar","poet_slug":"atilgan-alemdar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yoklugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sabah', 'bir-sabah-bahadir-yurteri-glnx6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sensiz bir günün sensiz bir akşamı

Saat hasretini hasret geçerken 

Dışarıda bir ağacın boş kalmış kolları

Bir deli içerde çok çekmiş senden

O deli ki uykuları kaçarmış her gece

Vazgeçmek mümkün olmazmış senden

Sayıklarmış ismini her bir nefeste

Kazımış yüreğine seni gerçekten

Şiirler yazarmış belki okursun diye

Okur da birgün döner diyerekten

Bekliyormuş bir gün döneceksin diye

Yağmurlu bir günde bir sabah erkenden', 'Sensiz bir günün sensiz bir akşamı Saat hasretini hasret geçerken  Dışarıda bir ağacın boş kalmış kolları Bir deli içerde çok çekmiş senden ...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Yurteri']::text[], 8.5, '{"poet":"Bahadır Yurteri","poet_slug":"bahadir-yurteri","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıklar Prensi', 'karanliklar-prensi-bahadir-yurteri-0pb29', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecelerin boşluğunu 

Mısralarımla doldurdum

O günlerin hoşluğunu 

Sen gidince unuttum

Artık sevmiyorum güneşi

Tiksiniyorum ışıklarından

Karanlığa sığınıyorum

Kaçıp hatıralardan

Dalıyorum kuytu sokaklara

Unutmaya çalışıyorum seni

Yalnızlığın karanlığında

Ben ''Karanlıklar Prensi''', 'Gecelerin boşluğunu  Mısralarımla doldurdum O günlerin hoşluğunu  Sen gidince unuttum Artık sevmiyorum güneşi Tiksiniyorum ışıklarından Kara...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Yurteri']::text[], 8.5, '{"poet":"Bahadır Yurteri","poet_slug":"bahadir-yurteri","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karanliklar-prensi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükendi Artık Sözler', 'tukendi-artik-sozler-bahadir-yurteri-qpehg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tükendi artık sözler

Sana diyecek lafım yok

Bu yazdığım son şiir

Gidiyorum üzgünüm çok

Gün geçtikçe kanayan

Yaramın dermanı yok

Yürekte hep çırpınan

Çocuğun günahı yok

Yok bu aşkın günahı

Yok dönmenin imkanı

Yok ölse ağlayanı

Yok bu garibin yok', 'Tükendi artık sözler Sana diyecek lafım yok Bu yazdığım son şiir Gidiyorum üzgünüm çok Gün geçtikçe kanayan Yaramın dermanı yok Yürekte hep ...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Yurteri']::text[], 8.5, '{"poet":"Bahadır Yurteri","poet_slug":"bahadir-yurteri","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tukendi-artik-sozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Hece Aşk', 'tek-hece-ask-cemal-safi-dsqfv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Var mı beni içinizde tanıyan

Yaşanmadan çözülmeyen sır benim

Kalmasa da şöhretimi duymayan

Kimliğimi tarif etmek zor benim

Bülbül benim lisanımla ötüştü

Bir gül için can evinden tutuştu

Yüreğine Toroslar’ dan çığ düştü

Yangınımı söndürmedi kar benim

Niceler sultandı, kraldı, şahtı

Benimle değişti talihi, bahtı

Yerle bir eyledim taç ile tahtı

Akıl almaz hünerlerim var benim

Kamil iken cahil ettim alimi

Vahşi iken yahşi ettim zalimi

Yavuz iken zebun ettim Selimi

Her oyunu bozan gizli zor benim

Yeryüzünde ben ürettim veremi

Lokman Hekim bulamadı çaremi

Aslı için kül eyledim Keremi

İbrahim’in atıldığı kor benim

Sebep bazı Leyla bazı Şirin''di

Hatırım için yüce dağlar delindi

Bilek gücüm Ferhat ile bilindi

Kuvvet benim, kudret benim, fer benim

İlahimle Mevlana’yı döndürdüm

Yunusumla öfkeleri dindirdim

Günahımla çok ocaklar söndürdüm

Mevladanım hayır benim, şer benim

Benim için yaratıldı Muhammed

Benim için yağdırıldı o rahmet

Evliyanın sözündeki muhabbet

Enbiyanın yüzündeki nur benim

Kimsesizim hısmım da yok hasmım da

Görünmezim cismimde yok resmim de

Dil üzmezim tek hece var ismimde

Barınağım gönül denen yer benim

Benim adım aşk!', 'Var mı beni içinizde tanıyan Yaşanmadan çözülmeyen sır benim Kalmasa da şöhretimi duymayan Kimliğimi tarif etmek zor benim Bülbül benim lisa...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/tek-hece-ask-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lanet Olsun İstanbul', 'lanet-olsun-i-stanbul-bahadir-yurteri-p21ht', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Apansız geçti yıllar öylesine

Bu yaşta yetmişi devirdim sanki 

Yalnızmışım usanmışım kimin neyine

İstanbul da kasım ayı bir gece vakti

Ellerim yapışmış buğulu cama 

Büyük harflerle ismini yazıyorum

Şu koca şehirde ben yalnız odamda

Sensiz geçen günleri saymaya korkuyorum

İki mi iki bin mi kaç yıl oldu bilmem 

Sana ''Git!..'' dediğim güne kahrediyorum

Ölenle ölünmezmiş isteyen çok yaşasın

Lanet Olsun İstanbul ben ölmek istiyorum', 'Apansız geçti yıllar öylesine Bu yaşta yetmişi devirdim sanki  Yalnızmışım usanmışım kimin neyine İstanbul da kasım ayı bir gece vakti Eller...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Yurteri']::text[], 8.5, '{"poet":"Bahadır Yurteri","poet_slug":"bahadir-yurteri","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/lanet-olsun-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göre', 'gore-ataol-behramoglu-huqr1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözlerimiz birbirine göre

ellerimiz,dudaklarımız

ve aşk bize göredir

gece tam aşka göre

rüzgar geceyegöre

ve yağmur rüzgara göredir

öpüşlerimiz yağmura göre

odamız öpüşlerimize göre

ve dünya odamıza göredir

ve biz dünyaya göreyiz', 'gözlerimiz birbirine göre ellerimiz,dudaklarımız ve aşk bize göredir gece tam aşka göre rüzgar geceyegöre ve yağmur rüzgara göredir öpüşleri...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gore-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Nikahı', 'gonul-nikahi-cemal-safi-q07ok', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İlk görüşte başlar, kalplerde telaş 

Çok erken kıyılır gönül nikahı 

Sevgiyi yudumlar, göz yavaş yavaş 

Bakarken kıyılır gönül nikahı... 

Beklenen karşına çıkar bir sabah, 

Belki yeşil gözlü, belki simsiyah, 

Daha ilk gürüşte yürekten bir ah, 

Çekerken kıyılır gönül nikahı... 

Neler uydurursun gör daha neler 

Nice mazaretler, ne bahaneler 

Kederli gözlerden billür taneler, 

Dökerken kıyılır gönül nikahı... 

Alnında sevecek yazdıktan sonra 

Eninde sonunda senindir sıra 

Bir vesile olur kibrit sigara 

Yakarken kıyılır gönül nikahı 

Düşürür sevdaya yaşı onücü 

Tanımaz günahı, kanunu, suçu 

Gururun belini sevginin gücü 

Bükerken kıyılır gönül nikahı...', 'İlk görüşte başlar, kalplerde telaş  Çok erken kıyılır gönül nikahı  Sevgiyi yudumlar, göz yavaş yavaş  Bakarken kıyılır gönül nikahı...  Be...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gonul-nikahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelsin...', 'guzelsin-cemal-safi-gjvwr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Görenler kendini beğenmiş sansın,

Sen böyle havalı pozla güzelsin.

Varsın âşıkların bıksın usansın,

Sen böyle cilveyle, nazla güzelsin...

Göz göre gelince aklım şaşıyor,

Yüreğim koşmaktan yorgun düşüyor,

Sığmıyor gönlüme aşkın taşıyor,

Sen benim haddimden fazla güzelsin...

Vadesi yakına eğleme meyil,

Sen sen ol zamanı zengine eğil,

Ben gibi hüzünlü hazanla değil,

Sen, taze baharla yazla güzelsin...

Aşk hevesle başlar, hasret, gurbetle.

Solmasın gençliğin gamla, kasvetle.

Çünkü sen her zaman sen muhabbetle,

Şiirle, şarkıyla, sazla güzelsin...', 'Görenler kendini beğenmiş sansın, Sen böyle havalı pozla güzelsin. Varsın âşıkların bıksın usansın, Sen böyle cilveyle, nazla güzelsin... Gö...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guzelsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satılır Diye', 'satilir-diye-cemal-safi-bgic3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adını kâğıda yazamıyorum,

Gün olur yerlere atılır diye.

Ellerim tutmuyor çizemiyorum,

Resmini görenler tutulur diye...

Gençliğim aksa da ömür çeşmemden,

İçemem, korkarım dile düşmenden! 

Yaşını gizlerim dosttan düşmandan,

Duyanlar gülmekten katılır diye...

Uğrunda kaç kalbi kırık bıraktım! 

Kırk yıllık dostları nârına yaktım! 

Tek senin incinip küsmenden korktum; 

O hilâl kaşların çatılır diye...

Aşkın bedelliyse peşin öderim.

Sen infaz edersen ipe giderim.

Kapında bir ömür kulluk ederim; 

Bastığın yerlerde yatılır diye...

Önceden kölenin suçunu göster,

Sonra''da al götür pazarla ister,

Kaç para derlerse saçını göster; 

Bunun bir teline satılır diye! ...', 'Adını kâğıda yazamıyorum, Gün olur yerlere atılır diye. Ellerim tutmuyor çizemiyorum, Resmini görenler tutulur diye... Gençliğim aksa da ömü...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/satilir-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklım Almıyor', 'aklim-almiyor-cemal-safi-vzp58', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Unutmak sevmekten kolay demiştin;

Olmuyor sultanım, kolay olmuyor.

Hepsi bir mevsimlik olay demiştin;

Dolmuyor sultanım, zaman dolmuyor...

Sen gittin kaderim düşman kesildi;

Alnına simsiyah mührü basıldı.

Bütün aynaların yüzü asıldı;

Gülmüyor sultanım sensiz gülmüyor...

Ben Allah''tan sonra seni överim

Seninle var oldu benim değerim.

Senden başkasını nasıl severim!

Almıyor sultanım, aklım almıyor...', 'Unutmak sevmekten kolay demiştin; Olmuyor sultanım, kolay olmuyor. Hepsi bir mevsimlik olay demiştin; Dolmuyor sultanım, zaman dolmuyor... S...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aklim-almiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git Güle Güle', 'git-gule-gule-cemal-safi-kahj7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dudağından onmaz derdi kaptığım

Gözümde gönlümde ilah yaptığım

Sevmek ne demek haşa taptığım

Çıktım yörüngenden git güle güle

Galipsin ödülü hak ettin yeter

Saçımı sakalımı ak ettin yeter

Çekil git, canıma tak ettin yeter

İstemem, görünme düşümde bile

Çıktım yörüngenden git güle güle

Benden beter aşka duçar ol emi

Daha da çaresiz naçar ol emi

Dilerim dünyada gör cehennemi

Sende muhannetten merhamet dile

Çıktım yörüngenden git güle güle

Kara gözlerinden dinmesin biran

Kanlı yaş, daima yaslı gibi yan

Erme muradına, Aslı gibi yan

Dile destan olsun, çektiğin çile

Çıktım yörüngenden git güle güle

Dönmeği deneme gözümde yoksun

Gönlümde, özümde sözümde yoksun

Günahıma giren, zehirli oksun

Çıkarttım kalbimden, attın yad ile

Çıktım yörüngenden git güle güle', 'Dudağından onmaz derdi kaptığım Gözümde gönlümde ilah yaptığım Sevmek ne demek haşa taptığım Çıktım yörüngenden git güle güle Galipsin ödülü...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/git-gule-gule-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anıt Mezar', 'anit-mezar-ramazan-dincer-z7d69', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'barut gibi bir akşam üstü 

bir sarı lambanın üst katında 

çilingir sofrası kurmuşlar

fırçalarını ormana batırıp

enginar yeşilini koşmuş çocuklar

aşka gelmiş ki deyyuslar

bir şiirin pimini çekerek 

topluca anıt mezar olmuşlar', 'barut gibi bir akşam üstü  bir sarı lambanın üst katında  çilingir sofrası kurmuşlar fırçalarını ormana batırıp enginar yeşilini koşmuş çocu...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Dinçer']::text[], 8.5, '{"poet":"Ramazan Dinçer","poet_slug":"ramazan-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anit-mezar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Doğum Günüm', 'bugun-dogum-gunum-mehmet-hanifikaya-pn3ga', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Evet sevgilim bugün doğum günüm,

Bugün doğduğum başkalarının gözünde,

Ama kahretsin öldüğüm işin özünde,

En çok yandığım acı dolu günüm gülüm.

Bugün sarhoş etmiyor içkiler nedense,

İçimde dinmeyen yangın her neredense,

Bir acı telefon çalıyor her kimdense,

Çekerim ben acıları eğer sendense.

Bugün uyku olmaz bu gece uyunmaz,

Ayrılık var içimde acı dolu durulmaz,

Sevgiye hasretlik var acılar yorulmaz,

Aşka giden yolda birden böyle durulmaz.

Ölünmezde bu gece sabah olmadan,

Can çıkmak istemez seni son kez görmeden,

Gözlerim kapanmaz sevgilim inan ki,

Seni doya doya bir daha sarmadan.

Bu gün benim ölüm günüm gülüm,

Yalan söylemişler bana sevgilim,

Ben sensiz bir günde nasıl doğarım,

Söğle aşkım yardım et bu ayrılığı nasıl boğarım.', 'Evet sevgilim bugün doğum günüm, Bugün doğduğum başkalarının gözünde, Ama kahretsin öldüğüm işin özünde, En çok yandığım acı dolu günüm gülü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet HanifiKaya']::text[], 8.5, '{"poet":"Mehmet HanifiKaya","poet_slug":"mehmet-hanifikaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bugun-dogum-gunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '26 Ağustos', '26-agustos-yahya-kemal-beyatli-0e4qi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu kopan fırtına Türk ordusudur ya Rabbi,

Senin uğrunda ölen ordu budur ya Rabbi,

Ta ki, yükselen  ezanlarla müeyyed namın

Galib et, çünkü bu son ordusudur İslamın.', 'Şu kopan fırtına Türk ordusudur ya Rabbi, Senin uğrunda ölen ordu budur ya Rabbi, Ta ki, yükselen  ezanlarla müeyyed namın Galib et, çünkü b...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatlı']::text[], 8.5, '{"poet":"Yahya Kemal Beyatlı","poet_slug":"yahya-kemal-beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/26-agustos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım', 'askim-hakan-akyurt-4klew', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkımı anlatsam dinler misin ki?

Yazdığım herşeyi okur musun ki?

Çarçabuk sen bana söyler misin ki?

'' Aşığım ben sana güzel sevgilim....''

Ayrılık çok çok zor ah bir bitirsem.,

Yalnızlıktan kurtulup seninle gezsem,

Çıldırana dek söyleyebilsem;

'' Aşığım ben sana güzel sevgilim....''', 'Aşkımı anlatsam dinler misin ki? Yazdığım herşeyi okur musun ki? Çarçabuk sen bana söyler misin ki? '' Aşığım ben sana güzel sevgilim....'' Ay...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/askim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tanem', 'bir-tanem-hakan-akyurt-3oore', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günlerin getirdikleri her zaman acı olmaz,

Seversen bir kere bırakmak kolay olmaz,

Dürüst olduktan sonra birşeyden korkun olmaz,

Sen beni sev birtanem,ben seni seveceğim...

Suratını astın mı yanında kalan olmaz,

Gözlerin bir baktı mı canı gitmeyen olmaz,

Gülüşünü attın mı canı gitmeyen olmaz,

Sen beni sev birtanem, ben seni seveceğim...

Aşık olmak kolaysa,sevenler niye olmaz,

Birden kapılıp kanma sevda hemencik olmaz,

İyice düşündün mü kalbinde yaran olmaz,

Sevsende sevmesende, ben seni seveceğim.....', 'Günlerin getirdikleri her zaman acı olmaz, Seversen bir kere bırakmak kolay olmaz, Dürüst olduktan sonra birşeyden korkun olmaz, Sen beni se...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-tanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşlüyorum', 'seni-dusluyorum-hakan-gulec-5wr6e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sesler geliyor, ayaklarımın altındaki

  Lodos kokulu yapraklardan..

  Bir sonbahar akşamı, yollarda yürüyorum.

  Seni yürüyorum gönlüme.

  Gönlümü gözlerine sürüyorum.

  Geceyi  gözlerime...

  Ve herzamanki gibi gözlerini aratmıyor gece.

  Ilık bir rüzgar esiyor.

  Ben seni düşünüyorum...

  Ayaklarımla ezdiğim yapraklardan çıkan sesler,

  Seni de içine alarak,

  Karışıyor bozacının çıngırak seslerine...

  Ve ben her adımda sonbaharı dinliyorum.

  İliklerime kadar duyuyorum seni.

  Rüzgar ılık esiyor ama,

  Ben üşüyorum.

  Seni düşlüyorum....', 'Sesler geliyor, ayaklarımın altındaki   Lodos kokulu yapraklardan..   Bir sonbahar akşamı, yollarda yürüyorum.   Seni yürüyorum gönlüme.   G...', ARRAY['Türk Edebiyatı','Şiir','Hakan Güleç']::text[], 8.5, '{"poet":"Hakan Güleç","poet_slug":"hakan-gulec","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-dusluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlar mısın?', 'aglar-misin-hakan-gulec-0uasj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlatsam anlarmısın aşkımı?

Kimsenin duymadığı o kelimeler,

Dökülüverse dilimden hece hece,

Ve haykırsam kalbimin içine sinmiş o deli sevdayı

Dağlar büyüklüğünce,

Sesimi duyarmısın?

Bir sevda yükü bıraksam sana

Taşırmısın ölümüne.

Bir gece seni düşünsem,

Geceyi içimde bulsam.

Ve seni bulsam gecede,

Gel desem gelirmisin?

Ölmektir deseler aşkın delili.

Ve bir gece vazgeçsem canımdan.

Aniden ölüversem,

Uğrunda canımı versem bana inanımısın?

Bir yaprak düşse ağaçtan,

Derken bir, bir daha.

Gözümden bir yaş düşse.

Ay girse buluta, bulut dünyaya küsse.

Sol yanımdan kan düşse.

Bir kalp ki kan kesilmiş;

Al kalbine koy desem,

Kalbimi almazmısın?

Bende bir gece var, bir de güneş.

Sen varsın bir de.

Bende bir aşk var sevgilim.

Anlatsam, Ağlarmısın?', 'Anlatsam anlarmısın aşkımı? Kimsenin duymadığı o kelimeler, Dökülüverse dilimden hece hece, Ve haykırsam kalbimin içine sinmiş o deli sevday...', ARRAY['Türk Edebiyatı','Şiir','Hakan Güleç']::text[], 8.5, '{"poet":"Hakan Güleç","poet_slug":"hakan-gulec","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/aglar-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterdim', 'i-sterdim-answer-pegasus-27yiw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İsterdim,güllere yazmak güzel günleri

               ömür boyu unutulmaması için...

İsterdim,karlara yazmak kötü günleri

               bir süre sonra eriyip kaybolması için...

İsterdim,gökyüzüne kazımak sevgimi

               sonsuza dek yaşaması için...

İsterdim,ölmek;biten aşkımızla beraber

               başka kimseye bağlanmamak için...

İsterdim,bir şans daha vermeni bana

               yeniden başlamak için...

                                          (Ekim,1995,Ankara)', 'İsterdim,güllere yazmak güzel günleri                ömür boyu unutulmaması için... İsterdim,karlara yazmak kötü günleri                bir ...', ARRAY['Türk Edebiyatı','Şiir','Answer Pegasus']::text[], 8.5, '{"poet":"Answer Pegasus","poet_slug":"answer-pegasus","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/isterdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Ertesi', 'ayrilik-ertesi-answer-pegasus-t639i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nefreti arttıran sevgiyi arttırır

Nefreti körelten sevgiyi köreltir

Ve sevginin sesi son kez çınlattığında kulağımızı

Son kez dalgalandırdığında ayrılık rüzgarı saçlarımızı

Artık kalmamıştır düşlerin,yaşananların,hayatın bir anlamı

Üstümüze ölüm gibi çöker efkarımızın ağırlığı! 

                                                       (3 Mart 1999,Ankara)', 'Nefreti arttıran sevgiyi arttırır Nefreti körelten sevgiyi köreltir Ve sevginin sesi son kez çınlattığında kulağımızı Son kez dalgalandırdığ...', ARRAY['Türk Edebiyatı','Şiir','Answer Pegasus']::text[], 8.5, '{"poet":"Answer Pegasus","poet_slug":"answer-pegasus","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ayrilik-ertesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadım', 'anlatamadim-answer-pegasus-ynz58', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her dolunayda denize baktım...

Her sabah yüzüme vuran meltemde dönüp bir de arkama baktım...

Her okuduğum kitabın sayfalarında seni aradım...

Her akşam baktığımda gökyüzüne seni hatırladım...

Her telefon çalışında umutla ona,sana,sesine sarıldım...

Her bakışımda cebimdeki resmine bir şeyi anladım...

Her şeyi herkese anlattımda güzel kız;

Bir tek kendimi ve sevgimi sana anlatamadım!

                                                (3 Mart 1999,Ankara)', 'Her dolunayda denize baktım... Her sabah yüzüme vuran meltemde dönüp bir de arkama baktım... Her okuduğum kitabın sayfalarında seni aradım.....', ARRAY['Türk Edebiyatı','Şiir','Answer Pegasus']::text[], 8.5, '{"poet":"Answer Pegasus","poet_slug":"answer-pegasus","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/anlatamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgilim', 'sevgilim-nazim-hikmet-ran-5wzjc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgilim yalan söylersem sana 

Kopsun ve mahrum kalsın dilim

Seni seviyorum demek bahtiyarlı
..........
..........', 'Sevgilim yalan söylersem sana  Kopsun ve mahrum kalsın dilim Seni seviyorum demek bahtiyarlı .......... .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevgilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilenci gibi...', 'dilenci-gibi-murat-vatansever-i6lgi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şu an gecelerin en kahpesindeyim

Elimde kül olmuş sigara 

Senin yolunu gözlerken

Buhulanmış camın isini yok ediyor dumanı

Ben ise;

Kendinden geçmiş bir dilenci gibi içiyor, İçiyorum...

Şu içkiyi içmek için mi, 

Yoksa sarhoş olmak için mi içiyorum,

Bilmiyorum.

Belki boşalacak bu kadeh,

Belki hiç bitmeyecek bu sevdam,

Ama ben yine de seni seveceğim.

17/07/1996-İzmir-Murat Vatansever', 'Şu an gecelerin en kahpesindeyim Elimde kül olmuş sigara  Senin yolunu gözlerken Buhulanmış camın isini yok ediyor dumanı Ben ise; Kendinden...', ARRAY['Türk Edebiyatı','Şiir','Murat Vatansever']::text[], 8.5, '{"poet":"Murat Vatansever","poet_slug":"murat-vatansever","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dilenci-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadisene', 'hadisene-metin-eloglu-b49y9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kıyımız mı kaldı bu şehirde onuda batır hadi

Çiçeğimizi yol, rüzgarımızı bur, suyumuzu acıt

Gökyüzümüz mü hani nerede? Sahi nerde bizim gökyüzümüz

hani lokman bulutlarımızda güvercin lekelerimiz?

Gözümüzü körelt hadi içimiz börtsün ellerimizi yırt

Bak ıslağımızda kurudu,kurumuz yamyaş

Sanki bönüz,sanki debelenen sıpayız çayırda

Yeşili hiç görmemiş,hiç şenlik görmemiş

Ko yarın sabah ortalık da  ışımayıversin

Ko buluşmayalım şu kuytu haziranda

O salı gecesi hiç sevişmeyelim mi?peki

Sevişmeyelim

Ne çıkar?

Ne mi çıkar!!!!!', 'Bir kıyımız mı kaldı bu şehirde onuda batır hadi Çiçeğimizi yol, rüzgarımızı bur, suyumuzu acıt Gökyüzümüz mü hani nerede? Sahi nerde bizim ...', ARRAY['Türk Edebiyatı','Şiir','Metin Eloğlu']::text[], 8.5, '{"poet":"Metin Eloğlu","poet_slug":"metin-eloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hadisene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüveyda', 'ruveyda-nurullah-genc-6zk13', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'fezayı bağlayarak yorgun kanatlarına 

bir güvercin uçurup kıtalar arasından

çağırdın beni

geçerek birer birer sürgün kanyonlarını

derbeder koşup geldim ışıldayan tahtına

yarım koyup bir bardak kurşun rengi çayımı

yıkarak yalnızlığa kurduğum sarayımı 

yetim çığlıklarımı duyurmak üzre sana

koşup geldim; iliştir beni memnu bahtına 

adını söylemek istemiyorum 

her hecesi amansız bir kor dudaklarımda

her harfine yıllardır şimşeklerle yarıştım

zindanlara karıştım, ölümlerle tanıştım

adını söylemek istemiyorum

rüveyda dediğim zaman 

anla ki, senin için yürüyor kelimeler

çığlığımın atardamarlarından 

hangi yıldızdır bilmem, gözlerin

kayar da üzerime rüveyda

önce tuhaf bir deprem yayılır bedenime

sonra açılır önümde ıstırab vadileri

silik renkleriyle adımlarıma 

çözülmeye yüz tutan bir mazi mühürlenir

hayalin bittiği menfeze doğru 

alaca bir at koşar içimde

zamansız, mekansız nefese doğru 

uslanmaz bir yürek taşıdığıma dair

yaygın bir kanaat dolaşır aynalarda

oysa rüveyda

baştanbaşa ben

kevser akan, gül kokan bir kalbin filiziyim. 

kitaplara sürdüğüm kapkara lekelerden 

bir anlatsam nasıl utandığımı

bir doğrulsam eğildiğim yerlerden

ağarır tanyeri nilüferlerin

alaca bir at koşar içimde

ezer toynakları ile anılarımı 

sular köpürmemeliydi rüveyda

kırılmamalıydı ıslak dalları hasret selvilerinin

ben zehire alışkınım, şerbete değil

rüyalar hefret eder avare duruşumdan

kabuslar çeker ancak derdimi yeryüzünde

sen gün boyu simsiyah bir ufukla beraber

ben her gece bir Mehdi türküsüyle çilekeş

yargılamak için zeval kayıtlarını

inkılab bekliyorum 

hangi umut çiçeğidir bilmem, ellerin

uzanır da gönlüme rüveyda

derinden bir ok saplanır bağrıma 

beynimi çağıran bir sese doğru

alaca bir at koşar içimde

zamansız, mekansız nefese doğru 

varlığın cinayettir memleketimde işlenen

akıtır kanını en asil pehlivanların

yokluğun sükunettir kuşatır evrenimi

varlığın ve yokluğun ölümüdür baharın 

artık eskisi gibi bakamıyorsun

göklerinde bir belkıs otururdu rüveyda

binlerce gökkuşağı olurdu kirpiklerin

güneş bir anne gibi dururdu başucunda

artık dokunamıyor kakülün bulutlara

karalara bürünmüş saçlarında dolunay

ben bu kadar zulme layık mıyım rüveyda 

hangi ressamı vurur bilmem, endamın

sarar da benliğimi

ben beni tanımam kaldırımlarda

kafesleri yutan kafese doğru

alaca bir at koşar içimde

zamansız, mekansız nefese doğru 

kırmızı bir kurdela bağlayarak alnına

duydun mu orkideye dua eden birini

bu ısmarlama yüzler yok mu rüveyda

bu yapmacık bebekler

gözyaşı akıtırken gülenler yok mu

beni kahrediyor geceler boyu 

hangi çağın gelişidir bilmem, gülüşün

soluk bir dünyanın mezarlarına

gömerek gurbetimi

kapadı karanlığa Yesrip, kapılarını

meydan okuyuşun çağın ordularına

bilmem hangi mevsimin başlangıcıdır

doruklardan öte hevese doğru

alaca bir at koşar içimde 

zamansız, mekansız nefese doğru 

yasını tutuyorum kararttığım düşlerin

yıpranmış divaneler gibiyim sokaklarda

amansız bir ütopya üfleyen pencereler

lif lif yoluyor dram seyyahı bedenimi

önümde, haksızlığın hesaba çekildiği

hiç kimsenin kimseyi tanımadığı mahşer

arkamda, kare kare ömrümü belirleyen

hatırladıkça yanıp tutuştuğum resimler 

söyle, nasıl aşarım pişmanlık dağlarını

yeniden bir nil olup taşar mıyım çöllere

kim giydirir başıma tacını nihayetin

kim takar bileğime hürriyet künyesini

karada balık gibi nasıl yaşarım, söyle 

rüveyda, seziyorum; tahammülün kalmadı

ama dur, boşaltayım bütün çığlıklarımı

asırlardır köhne barınaklarda

küflenen, çürüyen çığlıklarımı 

at vuruldu; içim paramparça rüveyda

gölgelerin ardına sakladım kusurumu

sen orda kayıtsızca gülümsüyor gibisin

ben burda damla damla eriyip akıyorum

yine de, çiğnetemem kimseye gururumu

istenmediğim yeri sessizce terkederim

hatıra kalsın diye bırakır da ruhumu

mahzun bir derviş gibi boyun büker, giderim', 'fezayı bağlayarak yorgun kanatlarına  bir güvercin uçurup kıtalar arasından çağırdın beni geçerek birer birer sürgün kanyonlarını derbeder k...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":109,"source_url":"https://www.antoloji.com/ruveyda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sessiz dünyam', 'sessiz-dunyam-mehmet-seckin-vfqz8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bırakın Gözyaşlarım istediği gibi aksın

Ruhum dinlensin ıssız gecelerde

Ne olur üstüme gelmeyin dertler

Bana sessiz  sedasız bir dünya verin

Alıştım  kaderin cilvelerine 

Çaresizlik içinde hep susuyorum

Gözyaşlarım kurudu hep ağlamaktan

Ben birgün değil hergün ölüyorum', 'Bırakın Gözyaşlarım istediği gibi aksın Ruhum dinlensin ıssız gecelerde Ne olur üstüme gelmeyin dertler Bana sessiz  sedasız bir dünya verin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Seçkin']::text[], 8.5, '{"poet":"Mehmet Seçkin","poet_slug":"mehmet-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sessiz-dunyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünmek', 'seni-dusunmek-nazim-hikmet-ran-19oss', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni düşünmek güzel şey, ümitli şey.

Dünyanın en güzel sesind
..........
..........', 'Seni düşünmek güzel şey, ümitli şey. Dünyanın en güzel sesind .......... .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seni-dusunmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Seninle Güzel', 'her-sey-seninle-guzel-mehmet-hanifikaya-doiez', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaşamak seninle, öğle güzel öğle doyulmaz ki,

Gözlerin sular kadar berrak,

Gülüşün bir çocuğunki kadar sıcak,

Ruhumun derinliklerine işliyor sanki.

Bana benden ayrı geçirdiğin her anı anlat,

Sensiz geçirdiyim saatlerde beraber,

Yaşamış gibi hissetmeliyim kendimi,

Seni dinledikçe o zaman;Başım.......

Göysüne yaslı olmalı,

Sarhoşlara inat ben içmeden sarhoş olamlıyım,

Sıcaklığında başka bir alemde ,

Başka bir evrende yaşat beni ,

                      NE OLURSUN!!!!!!!!', 'Yaşamak seninle, öğle güzel öğle doyulmaz ki, Gözlerin sular kadar berrak, Gülüşün bir çocuğunki kadar sıcak, Ruhumun derinliklerine işliyor...', ARRAY['Türk Edebiyatı','Şiir','Mehmet HanifiKaya']::text[], 8.5, '{"poet":"Mehmet HanifiKaya","poet_slug":"mehmet-hanifikaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/her-sey-seninle-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'hayat', 'hayat-mehmet-geckin-szcum', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çocuktum ne oldu birden büyüdüm

Gençliğin ateşi yandırdı beni

İhtiyarlık başıma müsallat oldu 

Ne yapayım geriye dönüş olmuyor', 'Çocuktum ne oldu birden büyüdüm Gençliğin ateşi yandırdı beni İhtiyarlık başıma müsallat oldu  Ne yapayım geriye dönüş olmuyor...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Geçkin']::text[], 8.5, '{"poet":"Mehmet Geçkin","poet_slug":"mehmet-geckin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'dunya', 'dunya-mehmet-geckin-jr7yf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne insanlar geçecek burdan 

şimdi hepsi rüya gibi

Başı sonu belli değil 

Akıp giden nehir gibi', 'ne insanlar geçecek burdan  şimdi hepsi rüya gibi Başı sonu belli değil  Akıp giden nehir gibi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Geçkin']::text[], 8.5, '{"poet":"Mehmet Geçkin","poet_slug":"mehmet-geckin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Dünyam', 'sessiz-dunyam-mehmet-geckin-ljjre', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bırakın Gözyaşlarım istediği gibi aksın 

Ruhum dinlensin ıssız gecelerde 

Ne olur üstüme gelmeyin dertler 

Bana sessiz sedasız bir dünya verin 

Alıştım kaderin cilvelerine 

Çaresizlik içinde hep susuyorum 

Gözyaşlarım kurudu hep ağlamaktan 

Ben birgün değil hergün ölüyorum', 'Bırakın Gözyaşlarım istediği gibi aksın  Ruhum dinlensin ıssız gecelerde  Ne olur üstüme gelmeyin dertler  Bana sessiz sedasız bir dünya ver...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Geçkin']::text[], 8.5, '{"poet":"Mehmet Geçkin","poet_slug":"mehmet-geckin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sessiz-dunyam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sensizlik Anı', 'bir-sensizlik-ani-ahmet-ocal-h6ybt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'olmayınca yüzünün yanılası kıvrımları...

olmuş olmanın ne anlamı var.

bir bahar...

ama yaşanılması gereken yüzünün hüzün mevsimi

şöylesine kıvrılıp yanına sığınmak

bu mültecilik senin ülkende güzel

dermensız bir yara 

ama ölmemek ölesiye kanamak

bu işte sensizliğin anlamı kalabalıklarda yalnız başına kalmak

ellerinde gördüm hayatı

nasırsız çizgilerinde 

hissedilen... görülmeyen o titreme

 bir çocuğun soluk yüzünde; aynı titreyiş

bir gülün figanında 

avuçlarına sığabilirdim.

utangaç bir ciddiyetle bir araya gelen parmaklarına

hapsolabilirdim.

yoksunluğunda hiç bir zindan yetmiyor bana

mühimdeğil böyle hayatın ortasında kalmak

günlerin geçme gayreti boşuna

gecelere yenilmek kanıma dokunuyor

geceler ki

karanlığı bana helalliği 

ve tafra tanımazlığıyla aynı gözlerin

bütün veballeri gözlerin saklar

bakışınla yaktığın meydan okumaların

o zamansız rest çekmelerin haddi hesabı yok

o kıpırdanma

suskunluğunla uyumlu karatı

bütün hesapları ödeten o replik...

o gemlik zeytini karasına eşlik

o tanıdık bildik ...

eziklik...

eğer o kara feryat rüyalarıma dolmasaydı 

sana nasıl aşık olurdum gözlerin olmasaydı

şimdi bir sensizlik anındayım

bir savaş dansında

ölüm gelmeden evvel

aşkalede bir ırgat yatağında

bir mavzerin sabırsızlığındayım 

tüm tetikler bakışlarından yana

her hissedişimde yokluğunu her dalışımda uzaklara

mermiler dökülür kirpiklerimden

ben meçhul zamanların katili

sen cümlelerimin gizli öznesi

her şiirde unutup adındaki gizli harfleri 

yüreğimdeki bu sevdayla her vakit sana kurulurum

beynimi mıhlayıp seni düşünme tutsaklığına 

vurup hayatın taşanılası yanlarını

her sabah sana vurulurum

bütün kinleri yanıma alıp

hesaba katmam bir çok şeyi

tek sende durur

tek sende durulurum

(1999 Edirne)', 'olmayınca yüzünün yanılası kıvrımları... olmuş olmanın ne anlamı var. bir bahar... ama yaşanılması gereken yüzünün hüzün mevsimi şöylesine k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öcal']::text[], 8.5, '{"poet":"Ahmet Öcal","poet_slug":"ahmet-ocal","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/bir-sensizlik-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Don Kişot', 'don-kisot-mehmet-karatas-j2gzp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Savaş açmışım yel değirmenlerine 

Elimde tahta bir kılıç

Vurmuşum amansızca kendimi şövalye  sanıp

Sevdalarıma engel tüm kötülüklere,

Bir Fatih haşmetiyle...

Oysa insanlar Don Kişot bu  diye gülmüşler anne...

Ben bir mecnun, 

Ben bir zavallı,

Ben içi boş, içi kof bir kovaymışım.

Bari bunu bana sen söyleseydin anne.

Bir gönül devleti kurmuşum kendimce,

Bir oyun oynamışım yıllar yılı...

Erkekler ağlamazmış,

Biliyor musun  ben ne kadar ağladım anne

Yapamıyorum, ben artık istemiyorum

Ne olur dua et, 

Sen annesin,

Tez alsın beni yanına 

O  var eden, anne...', 'Savaş açmışım yel değirmenlerine  Elimde tahta bir kılıç Vurmuşum amansızca kendimi şövalye  sanıp Sevdalarıma engel tüm kötülüklere, Bir Fa...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karataş']::text[], 8.5, '{"poet":"Mehmet Karataş","poet_slug":"mehmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/don-kisot-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Diye Bir Son', 'olum-diye-bir-son-i-lhan-yuksel-23xrs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bende bilmezdim ölümün 

İnsana yakın olduğunu 

Ana rahminden alınıp 

Kabir’e konulduğunu 

Bunca yıllık şu ömrümüz 

Değersiz akçe imiş de 

Öğrenirmiş de şu insan 

Onu da bu son gidiş de 

Bir yaprak gibi dökülür 

İnişi başlar yavaştan 

Yaprak döker insan ölür 

Ne farkımız var ağaçtan 

Alıp buradan götürdüğün 

İki tahta bir top kefen 

Eş bildiğin dost gördüğün 

Kimse gitmezmiş giderken 

Adin şöhretin varlığın 

Çabuk unutur kalanlar 

Eşim dostum bildiğin 

İşte şu gülendir ağlayanlar 

Bu tabuta aldıkların 

Dar bir yere götürülür 

Yürümezse adımların 

Ağı, ağır yürütülür 

Bizim gibi şu yatanlar 

Ağır akça yiğittiler 

Üstüne toprak atanlar 

Sırası geldi gittiler 

Bu yolculuğun sonunda 

Ne var geri dönmez giden 

Yoksa işler mi yolunda 

Köşk mü taht mı var inciden', 'Bende bilmezdim ölümün  İnsana yakın olduğunu  Ana rahminden alınıp  Kabir’e konulduğunu  Bunca yıllık şu ömrümüz  Değersiz akçe imiş de  Öğ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/olum-diye-bir-son-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadığım', 'anlatamadigim-mehmet-karatas-qge4z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sevda bahçesiydi anlatamadığım,

Bir sevda bahçesiydi anlamadığınız...

Gülleri umut, dikeni kahır,

Suyu gözyaşım...

Ezilen karanfiller değil, yüreğim

Bu bahçeki benim hayat emeğim...

Gün doğuşu bir muştu

Batışı hüzün,

Bir can kadar gerçek benim bu bahçem... 

Her gece  talan etse de onu çilenin yaramaz çocukları

Gündüzleri sevdamla yeni baştan yeşerecek

Bu bahçenin tüm tomurcukları...

Ve bir gün ben oraya defnolacağım sevdalarımla...

Ve işte o gün yalnızca sevdalı gönüllerin gireceği bu kabristanda,

Sevdalı, samimi, dualar  duyacağım...', 'Bir sevda bahçesiydi anlatamadığım, Bir sevda bahçesiydi anlamadığınız... Gülleri umut, dikeni kahır, Suyu gözyaşım... Ezilen karanfiller de...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karataş']::text[], 8.5, '{"poet":"Mehmet Karataş","poet_slug":"mehmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/anlatamadigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esme Rüzgar', 'esme-ruzgar-mehmet-karatas-ra8h8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dur rüzgar, dur, sert esip de böyle üzme beni

Bırak hazan yaprağı dallarında çürüsün.

Topraklara karışıp yok olmadan bedeni,

İnsancıklar sürüsü hep altında yürüsün...

Görmez misin,duymaz mısın,garip bir diyarda

Bir hıçkırık,bir çırpınış şimdi son bulmakta,

Minik serçeciğin kanatları kırılmakta.

Sevda çiçekleri solmakta hoyrat ellerde...

Ne olur susun ey ölümlüler! 

Anlatmayın bana ölümsüz sevdalarınızı.

Biz öteler ötesinde,mor ötesinde

Bir gonca güle gönül koymuşuz...

Bir sevda çiçeği,bir hazan yaprağı

Bu iklimde ikisinin işi ne? 

Biri umutlara, sevdalara yelken açmış,

Diğeri ki damardaki öz suları kurumuş.

Biz dilemedik karanlıklara çığlık atmayı,

Biz istemedik kara sevdalara düçar olmayı

Gelene değil,gönderene baktık,

Gündüzleri güldük geceleri ağladık...', 'Dur rüzgar, dur, sert esip de böyle üzme beni Bırak hazan yaprağı dallarında çürüsün. Topraklara karışıp yok olmadan bedeni, İnsancıklar sür...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karataş']::text[], 8.5, '{"poet":"Mehmet Karataş","poet_slug":"mehmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/esme-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir', 'bu-sehir-hakan-dikici-1su19', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu şehride eskittik ya dostum...

hani yıldızlar göz kırpardı 

hani bahar geldi diye sevinirdik

hani  güneş gibi doğmuştu ya gecemize...

bu şehri de eskittik ya dostum,

acıyorduk acınacak halimize

ve kendi kendimize yarenlik ederdik

şarkılarla doğardık ya gecelerine bu şehrin,

bu şehride eskittik ya dostum herşey gibi

sanki bir yalan

yalandı yaşadığımız

belkide yaşamıyorduk, sadece yaşadığımızı sanıyorduk

bu yaşamıda eskittik ya dostum...

yıllarınıda eskittik,

yollarınıda eskittik,

ama eskitemediğimiz bir şey vardı kalan

ümitleri eskitememiştik ya...

ümitleride eskittik ya dostum bu şehirle beraber

bu şehride eskittik ya dostum...

herşey yalanmıydı

herşey hayalmıydı yoksa

bir gün uyanınca belki

geriye kalan sadece bu şehrin ışıltılarının gözlerimizi kamaştırması olacaktı

belki gözlerimizde bir nem,

bir ışıltı kalacaktı...

eskimemiş,yıpranmamış ve her bakışımızda bizimle beraber bakacak hayata

bir ışıltı kalacaktı belki...

bu şehride eskittik ya dostum herşey gibi...

bu şehride eskittik...', 'bu şehride eskittik ya dostum... hani yıldızlar göz kırpardı  hani bahar geldi diye sevinirdik hani  güneş gibi doğmuştu ya gecemize... bu ş...', ARRAY['Türk Edebiyatı','Şiir','Hakan Dikici']::text[], 8.5, '{"poet":"Hakan Dikici","poet_slug":"hakan-dikici","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bu-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umuda Yürümek', 'umuda-yurumek-mehmet-karatas-41usk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umuda  yürüyorum...

Ufuk çizgisini kara bulutlar örtse de

Çoban yıldızlarım gizlense de semada.

Sevdalarımdan pusulalar yaparak,

Umuda yürüyorum....

Varsın gülsün insanlar,

Dünya denilen şu tiyatro salonunda 

Dramlarını komedi sanarak,

Umuda yürüyorum,

Onların şuh kahkahalarına, onlar için ağlayarak...

	

	Nurlu iklimlere,

                Ölümsüz sevdalara,

                Umuda yürüyorum...', 'Umuda  yürüyorum... Ufuk çizgisini kara bulutlar örtse de Çoban yıldızlarım gizlense de semada. Sevdalarımdan pusulalar yaparak, Umuda yürüy...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karataş']::text[], 8.5, '{"poet":"Mehmet Karataş","poet_slug":"mehmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/umuda-yurumek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda', 'elveda-mehmet-karatas-4qqh0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'O yol size geliyordu çocuklar,

Eğer eşkıya kesmeseydi yolumu,

Fırlamasaydı o kahpe kurşun namlusundan.

Ben size geliyordum çocuklar...

Elveda  kuzucuklar,elveda şirin şeyler

Bana elveda...

Oysa daha dün gibiydi ilk merhabamız,

İlk heyecanımız,ilk dersimiz,

O yarısı yıkık binada...

Ama bu kez elveda.

Elveda canlar,elveda gonca güller, bana elveda...

Kızmayın,darılmayın,ağlamayın,

Uzun upuzun bir yaz tatili sayın, 

Veya giriş zili hiç çalmayacak bir tenefüs; bana elveda...

Üzülmeyin,daha çok merhabalar duyacaksınız.

Ziller çalacak,dersler başlayacak...

Bahçeniz bağbansız kalmayacak,

Ama benim giriş zilim bir daha hiç çalmayacak...

Tomurcuklar, canlar,kuzucuklar bana elveda...

Hani diyorum canlar hiç değilse  beni

Kasımlarda unutmayın,

Çünkü ben,

Şehir çıkışındaki o kabristanda hep sizleri bekliyor olacağım

Sizlere son bir hayat dersi daha anlatmak için...', 'O yol size geliyordu çocuklar, Eğer eşkıya kesmeseydi yolumu, Fırlamasaydı o kahpe kurşun namlusundan. Ben size geliyordum çocuklar... Elved...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karataş']::text[], 8.5, '{"poet":"Mehmet Karataş","poet_slug":"mehmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/elveda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Uyandırdınız', 'neden-uyandirdiniz-mehmet-karatas-bah3f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir düştü belki benim ki

Ama ben inanmıştım.

İnanmak,yaşamaktı belki de

Ben yıllarca o hayalle yaşamıştım...

Neden uyandırdınız ki.

Dünya bir karanfil bahçesiydi,

Kan yoktu, 

Gül suları kokardı sokaklarında.

Gecelerinde yarasalar dolaşmazdı,

Karanlıklarında da bülbül öterdi.

Bir şifa havuzum vardı ki,

Bütün dertliler kana kana o sulardan içerdi.

Ulvi sevdalarda yanmış aşıklarım vardı.

Yıktınız,

Yaktınız,

Viran ettiniz,

Düşlerin en güzelinden uyandırdınız...

Şimdi gül bahçemde karanfil yerine

Diken bitmekte,

Gecelerimde vampirler kol gezmekte,

Söyleyin, ne olur 

Neden uyandırdınız...', 'Bir düştü belki benim ki Ama ben inanmıştım. İnanmak,yaşamaktı belki de Ben yıllarca o hayalle yaşamıştım... Neden uyandırdınız ki. Dünya bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karataş']::text[], 8.5, '{"poet":"Mehmet Karataş","poet_slug":"mehmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/neden-uyandirdiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilir misin', 'bilir-misin-mehmet-karatas-r881y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilir misin,

Çok uzaklarda ne dünyalar kuruldu

Senden habersiz...

Ne köşkler ne saraylar yapıldı,

Sultanı senin olduğun,

Ama hiçbir zaman göremeyeceğin...

Bahçesindeki hasret çiçekleri, göz yaşlarımla sulandı,

Senden habersiz...

	Bütün gonca güllere senin adını verdim.

	Sonra dönüp onları sen diye sevdim.

	Sen diye kokladım,

	Senden habersiz...

Sonra yıktım bütün binaları,

Kopardım kökünden gonca gülleri,

Güneşin önüne bir perde gerdim; 

Gündüzleri karanlığa çevirdim,

Senden habersiz...', 'Bilir misin, Çok uzaklarda ne dünyalar kuruldu Senden habersiz... Ne köşkler ne saraylar yapıldı, Sultanı senin olduğun, Ama hiçbir zaman gö...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karataş']::text[], 8.5, '{"poet":"Mehmet Karataş","poet_slug":"mehmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bilir-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Çiçeği', 'kir-cicegi-mehmet-karatas-tlhkp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Git bu elden,

Yalvarırım uzaklara git

Kır çiçeği...

Bembeyaz yaprakların siyaha döner,

Bahara ermeden gülyüzün solar...

Çoraktır bu toprak, su vermez sana; 

Bir başka eser bu beldenin rüzgarı,

Savurur seni kökünden çok uzaklara...

Dur, çıkarma başını,

Bırak toprağın altında kalsın,

Nasıl olsa açsan da yaşayamayacaksın...

	Burdan çok uzaklarda,

	Güneşin hiç batmadığı bir yer var.

                Orda bir el ki  siyahı allara boyar.

	Var git, açacaksan orda aç kır çiçeği...

	Boş ver sen beni...', 'Git bu elden, Yalvarırım uzaklara git Kır çiçeği... Bembeyaz yaprakların siyaha döner, Bahara ermeden gülyüzün solar... Çoraktır bu toprak, ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karataş']::text[], 8.5, '{"poet":"Mehmet Karataş","poet_slug":"mehmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kir-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sen', 'sen-mehmet-karatas-inezy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir güneşsin sen benim ufkumda,

Bir arşın yaklaştıkça, bin arşın uzaklaşan...

Beni hayata bağlayan hayallerimdeki meleksin,

İnan bana yaşama gayemsin...

Nazlı bir çiçeksin bilirim,

Bahçemde hiç açmayacak.

Bahçıvanı başka, sahibi başka...

Okuduğum son romansın,

Sonunu asla göremeyeceğim.

Bir şiirsin sen,

Daha ilk mısralarında hüzünlendiğim,

Ve asla tamamlayamadığım...

Bir gün ansızın boşalacak kansın damarlarımda,

Beni bir külçe gibi yere yığacak...

Sevdiğimsin, canımsın

Cansın, canansın

Asla kavuşamadığım.

Sadece hayallerimde benim olan sen...', 'Bir güneşsin sen benim ufkumda, Bir arşın yaklaştıkça, bin arşın uzaklaşan... Beni hayata bağlayan hayallerimdeki meleksin, İnan bana yaşama...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karataş']::text[], 8.5, '{"poet":"Mehmet Karataş","poet_slug":"mehmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Sevmişim', 'ben-seni-sevmisim-mehmet-karatas-5bzg4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben, seni sevmişim bir kez.

Sana ısınmışım...

Sende yeniden doğmuşum.

Ben senin hayallerini,

O buz şehrin gecelerinde dondurup,

Yazlarıma getirmişim

Evimde misafir etmişim yıllar yılı

Ben, seni sevmişim bir kez

	Mazimi tel örgülerle çevirmişim

	Hatıranı oraya hapsetmişim

	Gardiyanın yüreğim olmuş; 

	Cezansa müebbet...

	Ben seni sevmişim bir kez...

Ben seni sevmişim bir kez...

Mezarda seni saracak toprağı kıskanarak

Aldığın havaya, yediğin aşa kendimi katarak...

Ben seni sevmişim bir kez...

	İstemem istemem asla vuslat! 

	Senin isteyebilirimine  inat

	Zaten, sen hep benle benimlesin

	Hayallerimsin, gidemezsin.

Bilirim, bilirim ki; 

Sen beni sevmez, sevemezsin', 'Ben, seni sevmişim bir kez. Sana ısınmışım... Sende yeniden doğmuşum. Ben senin hayallerini, O buz şehrin gecelerinde dondurup, Yazlarıma ge...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karataş']::text[], 8.5, '{"poet":"Mehmet Karataş","poet_slug":"mehmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ben-seni-sevmisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalimsin', 'hayalimsin-mehmet-karatas-affky', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir şarkı duyuyorum uzaklardan,

Gözlerimden iki damla yaş akıyor.

Bir kadın çığlık atıyor karanlıklardan,

Çığlıklar çığlığa karışıyor,

Evim, sensiz yeni bir akşama daha başlıyor...

	Sen varsın bu hiç görmediğin mekanın her yerinde,

	Çünkü ben seni uzun kış gecelerinde,

                Her köşesinde ayrı ayrı hayal etmişim,

	En çok da pencere önünde duruşunu sevmişim.

Ben seni bu kadar severken sevdalım,

Sen beni, hayallerimde bile terk etmişsin...

Bana gülümsediğin pencere önünde saatlerce ağlamışım

Sen beddua sanırken; 

Ben o huzurda senin için yalvarmışım...', 'Bir şarkı duyuyorum uzaklardan, Gözlerimden iki damla yaş akıyor. Bir kadın çığlık atıyor karanlıklardan, Çığlıklar çığlığa karışıyor, Evim,...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karataş']::text[], 8.5, '{"poet":"Mehmet Karataş","poet_slug":"mehmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayalimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşündüm', 'seni-dusundum-mehmet-karatas-roku2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimi en onulmaz acılar sardığı anda 

Ben hep seni düşündüm.

Girdikçe girdapların en zorlusuna

Boğuldukça küfrün karanlıklarında 

Ben hep seni düşündüm...

	Gülüp geçti insanlar yüce sevdama

	Açmasın diye tomurcuklarımı kırdılar,

	Vakitsiz gecelerde...

	Yüreğimi dağladılar

	Umut çiçeklerimi kökünde kopardılar

	Sonra bana dünyaları verdiler

	Gel vazgeç sevdandan diye

	Ben yalnızca seni düşündüm...

Düşlerimde çarmıha geriliyorum

Acımasız ellerde kor yüreğimi dağlıyor

Derken bedenden bir İsa çıkageliyor 

Sabır sabır diye fısıldıyor yaralarımı temizlerken

Ben seni düşünüyorum...

	Gönül kafesimden bir kuş uçuyor

	Umutlarım uçuyor gönül kafesimden

	Nemrutlar ateşten dağlar yığarken

	Bir meltem esiyor derinlerden

	Bir İbrahim çıkıyor ateşlerden

	Ben seni düşünüyorum...

Sonunda yeniyorum onları yüce sevdanla

Nurunla kuruyor tüm bataklıklar

Yeniden yeni baştan karanfiller yetişiyor

Ben seni düşünüyorum...', 'İçimi en onulmaz acılar sardığı anda  Ben hep seni düşündüm. Girdikçe girdapların en zorlusuna Boğuldukça küfrün karanlıklarında  Ben hep se...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karataş']::text[], 8.5, '{"poet":"Mehmet Karataş","poet_slug":"mehmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/seni-dusundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Batımında', 'bir-gun-batiminda-mehmet-karatas-p9g0e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün batımın da,

Gözlerimden süzülen iki damla yaşla akıp gitti,

Yıkıldı bendeki sevgi sarayları,

Ümit binaları,

Mutluluk çiçekleri...

Bir gün batımın da karardı

Benim aydınlık dünyam...

İki damla gözyaşı

Bir ömre bedelmiş,

Bir gün batımın da aktı o göz yaşlarım...

Bir gün batımın da öldü,

Benim duygularım...', 'Bir gün batımın da, Gözlerimden süzülen iki damla yaşla akıp gitti, Yıkıldı bendeki sevgi sarayları, Ümit binaları, Mutluluk çiçekleri... Bi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karataş']::text[], 8.5, '{"poet":"Mehmet Karataş","poet_slug":"mehmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-gun-batiminda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-mehmet-karatas-pg7xf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O mini ellerinle sımsıkı tuttuğun

Kuru, katıksız ekmeğini,

Buzlarla bütünleşen ayaklarını,

O garip elbiseni, unuttum...

Ama o bakışlarını...

O bakışlarını unutmak,

Bu mümkün değilmiş çocuk...

Dokunsalar ağlayacak gibi duruşun,

Dilenci olmadığını asaletinle haykırışın,

Çocuk denecek yaşta ihtiyarlayışın,

Ve o kara gözlerinde acı acı bakışın

Bunları unutmak mümkün değilmiş çocuk...

	Sana diyorum ki çocuk; 

	Bütün dertlerini, gözyaşlarına versen,

	Bağrımda ağlasan,

                Acıların  gönlüme aksa; 

	Söz verir miydin? 

	Bir daha öyle bakmayacağına,

	Söz verir miydin? 

	Bir daha asla ağlamayacağına,

	Ve söz verir miydin? 

	Hep, benle kalacağına...', 'O mini ellerinle sımsıkı tuttuğun Kuru, katıksız ekmeğini, Buzlarla bütünleşen ayaklarını, O garip elbiseni, unuttum... Ama o bakışlarını......', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karataş']::text[], 8.5, '{"poet":"Mehmet Karataş","poet_slug":"mehmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalarınız Bir Dert Olur', 'sevdalariniz-bir-dert-olur-mehmet-karatas-s7zkv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün gelir sevdalarınız bir dert olur,

Panzehiri olmayan bir ağu misali

Damarlarınızda dolaşırlar.

Acıların en onulmazı sararken tüm bedeninizi

Kimse bilmez, kimse anlamaz derdinizi.

Geceler çöl olur, mecnuncasına dalarsınız

Karanlıkların en derinine,

Halinizi anlayacak bir Leyla’nız bile yokken...

Sevdanız, sevdalarınız bir melek yüzde simgeleşir

Avuçlamak istersiniz bir gül yüzü

Ya da mısralardaki Mehlika Sultanı.

Zamansız doğan güneşler eritiverir karlarınızı

Kuruyan gözlerinizden yaş bile akmaz....

Kaybolurken Mehlika Sultan Kaf dağının ufkunda

Mehlika Sultan’a aşık yedi genç

Sekiz genç oluverir ansızın sizinle

Ve gurbet başlar onlarla birlikte...

Şuh kahkahalar, şehvet dolu iltifatlar

Kulaklarınızı tırmalar

Kızgın bir kurşun gibi beyninize akar akar...

Geceye, gecelere yumruk sallarsınız...

Anlamaz kutsal sevdaları

Damarlarında şehvet kanı dolaşanlar

Kanatırcasına yumruklarsınız taş duvarları

Gündüz çiçek tutan ellerinizle

Kanla yıkarsınız gül kokularını ıstırap dolu gecelerinizde

Ölümün bir nimet olduğunu düşünürken...

Gündüzün işveli bülbüllerine inat

Gecelerin yarasaları ile dost olursunuz

Yarasalar yudum yudum emerken kanınızı

Sesiniz bile çıkmaz

Sessiz bir ölümün pençesinde ağır ağır can verirsiniz

Çakallar, sırtlanlar bakışırken...

Uğrunda öldüğünüz sevdalar sesinizi bile duymaz

Bir çocuk hıçkırır mevtanızın yanında

Dostlarınız toplanır kabir başında

Ve sonsuz bir uyku başlar o karanlık çukurda...', 'Gün gelir sevdalarınız bir dert olur, Panzehiri olmayan bir ağu misali Damarlarınızda dolaşırlar. Acıların en onulmazı sararken tüm bedenini...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karataş']::text[], 8.5, '{"poet":"Mehmet Karataş","poet_slug":"mehmet-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sevdalariniz-bir-dert-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey Boşuna', 'hersey-bosuna-i-lhan-yuksel-mqs90', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dolu, dolu sandım tükendi vaktim 

Yürü, yürü çabuk koş ta boşuna 

Yüküm dolsun dedim bu idi ahtım 

Doluda boşuna boşta boşuna 

Akıl hesap kitap tıkandı baktım 

Ağarmış ne saçlar başta boşuna 

Şu hayat boşuna yanarmış yaktım 

Kuruda boşuna yaşta boşuna 

Yazılmış kaderde yıkılsa tahtım 

Beklemek boşuna kaçta boşuna 

Bütün lezzetleri geçtim bıraktım 

Ölümlü şu başta taçta boşuna', 'Dolu, dolu sandım tükendi vaktim  Yürü, yürü çabuk koş ta boşuna  Yüküm dolsun dedim bu idi ahtım  Doluda boşuna boşta boşuna  Akıl hesap ki...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hersey-bosuna-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Monna Rosa -I- Aşk ve Çileler', 'monna-rosa-i-ask-ve-cileler-sezai-karakoc-td557', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mona Rosa. Siyah güller, ak güller. 

Geyve''nin gülleri ve beyaz yatak.

Kanadı kırık kuş merhamet ister. 

Ah senin yüzünden kana batacak. 

Mona Rosa. Siyah güller, ak güller.

Ulur aya karşı kirli çakallar, 

Ürkek ürkek bakar tavşanlar dağa.

Mona Rosa bugün bende bir hal var. 

Yağmur iri iri düşer toprağa,

Ulur aya karşı kirli çakallar.

Açma pencereni perdeleri çek, 

Mona Rosa seni görmemeliyim.

Bir bakışın ölmem için yetecek. 

Anla Mona Rosa ben bir deliyim. 

Açma pencereni perdeleri çek.

Zeytin ağaçları, söğüt gölgesi, 

Bende çıkar güneş aydınlığına.

Bir nişan yüzüğü bir kapı sesi. 

Seni hatırlatır her zaman bana.

Zeytin ağaçları, söğüt gölgesi.

Zambaklar en ıssız yerlerde açar 

Ve vardır her vahşi çiçekte gurur.

Bir mumun ardında bekleyen rüzgar, 

Işıksız ruhumu sallar da durur.

Zambaklar en ıssız yerlerde açar.

Ellerin, ellerin ve parmakların 

Bir nar çiçeğini eziyor gibi.

Ellerinden belli olur bir kadın, 

Denizin dibinde geziyor gibi.

Ellerin, ellerin ve parmakların.

Zaman ne de çabuk geçiyor Mona. 

Saat onikidir söndü lambalar

Uyu da turnalar girsin rüyana, 

Bakma tuhaf tuhaf göğe bu kadar.

Zaman ne de çabuk geçiyor Mona.

Akşamları gelir incir kuşları, 

Konarlar bahçemin incirlerine.

Kiminin rengi ak kiminin sarı. 

Ah beni vursalar bir kuş yerine.

Akşamları gelir incir kuşları.

Ki ben Mona Rosa bulurum seni 

İncir kuşlarının bakışlarında.

Hayatla doldurur bu boş yelkeni. 

O masum bakışların su kenarında.

Ki ben Mona Rosa bulurum seni.

Kırgın kırgın bakma yüzüme Rosa. 

Henüz dinlemedin benden türküler.

Benim aşkım uymaz öyle her saza. 

En güzel şarkıyı bir kurşun söyler.

Kırgın kırgın bakma yüzüme Rosa.

Artık inan bana muhacir kızı, 

Dinle ve kabul et itirafımı. 

Bir soğuk, bir mavi, bir garip sızı 

Alev alev sardı her tarafımı.

Artık inan bana muhacir kızı.

Yağmurdan sonra büyürmüş başak, 

Meyvalar sabırla olgunlaşırmış.

Bir gün gözlerimin ta içine bak 

Anlarsın ölüler niçin yaşarmış.

Yağmurdan sonra büyürmüş başak.

Altın bilezikler o kokulu ten 

Cevap versin bu kuş tüyüne.

Bir tüy ki can verir gülümsesen, 

Bir tüy ki kapalı geceye güne.

Altın bilezikler o kokulu ten.

Mona Rosa. Siyah güller, ak güller. 

Geyve''nin gülleri ve beyaz yatak.

Kanadı kırık kuş merhamet ister, 

Ah senin yüzünden kana batacak. 

Mona Rosa. Siyah güller, ak güller.', 'Mona Rosa. Siyah güller, ak güller.  Geyve''nin gülleri ve beyaz yatak. Kanadı kırık kuş merhamet ister.  Ah senin yüzünden kana batacak.  Mo...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/monna-rosa-i-ask-ve-cileler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutuş', 'unutus-octavio-paz-vadas', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yum gözlerini, yitir kendini karanlıkta 

gözkapaklarının kırmızı yaprakları altında. 

Gömül vızıldayan sesin 

düşen sesin halkalarına 

ve uzaklarda yankılan 

dilsiz bir çağlayan gibi, 

davulların çalındığı yerde. 

Bırak kendini karanlığa, 

kendi etine gömül, 

kendi yüreğine; 

kemik, o mor şimşek, 

kamaştırsın gözlerini, kör etsin, 

mavi göğsünü göstersin akşam ışığı 

körfezler ve gölgeli koyaklar arasında. 

O sıvı karanlığında uykunun 

ıslat çıplaklığını; 

kıyıya kimbilir kimin bıraktığı 

gövdeni, o köpük danteli unut. 

Sonsuz kadın, yitir kendini 

kendi benliğinin sonsuzluğunda, 

bir başka denizle buluşan bir deniz gibi 

unut kendini, beni unut. 

Dudaklar, öpüşler, aşk, her şey yeniden doğar 

o ölümsüz, o yalın unutuşta: 

gecenin kızlarıdır yıldızlar. 

(Türkçesi: Ülkü Tamer)', 'Yum gözlerini, yitir kendini karanlıkta  gözkapaklarının kırmızı yaprakları altında.  Gömül vızıldayan sesin  düşen sesin halkalarına  ve uz...', ARRAY['Türk Edebiyatı','Şiir','Octavio Paz']::text[], 8.5, '{"poet":"Octavio Paz","poet_slug":"octavio-paz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/unutus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana, Bana, Vatanıma, Ülkemin İnsanlarına Dair', 'sana-bana-vatanima-ulkemin-i-nsanlarina-dair-erdem-bayazit-dc6jc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '``Telgrafın tellerini kurşunlamalı’’

Öyle değildi bu türkü bilirim

Bir de içime

-Her istasyonda duran sonra tekrar yürüyen-

Bir posta katarı gibi simsiyah dumanlar dökerek

Bazan gelmesi beklenen bazan ansızın çıkagelen

Haberler bilirim mektuplar bilirim.

Gamdan dağlar kurmalıyım

Kayaları kelimeler olan

Kırk ikindi saymalıyım

Kırk gün hüzün boşaltan omuzlarıma saçlarıma

Saçlarının akışını anar anmaz omuzlarından

Baştan ayağa ıslanmalıyım

Gam dağlarına çıkıp naralar atmalıyım.

İçimde kaynayan bir mahşer var

Bu mahşer birde annelerinin kalbinde kaynar

Çünkü onlar yün örerken pencere önlerinde

Ya da çamaşır sererken bahçelerinde

Birden alıverirler kara haberini

Okul dönüşü bir trafik kazasında 

Can veren oğullarının.

Bir de gencecik aşıkların yüreklerini bilirim

Bir dolmuşta yorgun şoförler için bestelenmiş

Bir şarkıdan bir kelime düşüverince içlerine

Karanlık sokaklarına dalarak şehirlerin 

Beton apartmanların sağır duvarlarını yumruklayan

Ya da melal denizi parkların ıssız yerlerinde

Örneğin Hint Okyanusu gibi derin

İsyanın kapkara sularına dalan.

Nice akşamlar bilirim ki

Karanlığını

Bir millet hastanesinde

Dokuz kişilik kadınlar koğuşu koridorunda

Başını kalorifer borularına gömmüş

Beyaz giysilerinden uykular dökülen tabiplerden

Haber sormaya korkan

Genç kızların yüreğinden almıştır.

Bir de baharlar bilirim 

Apartman odalarında büyüyen çocukların bilmediği bilemeyeceği

Anadolu bozkırlarında

İstanbul’dan çıkıp Diyarbekir’e doğru

Tekerleri yamalı asfaltları bir ağustos susuzluğu ile içen

Cesur otobüs pencerelerinden

Bilinçsiz bir baş kayması ile görülen 

Evrensel kadınların iki büklüm çapa yaptıkları tarla kenarlarında

Çıplak ayakları yumuşak topraklara batmış ırgat çocuklarının

Bir ellerinde bayat bir ekmeği kemirirken

Diğer ellerinde sarkan yemyeşil bir soğanla gelen.

Yazlar bilirim memleketime özgü

Yiğit köy delikanlılarının

İncir çekirdeği meselelerle birbirlerini kurşunladıkları

Birinin ölü dudaklarından sızan kan daha kurumadan

Üstüne cehennem güneşlerde göğermiş mor sinekler konup kalkan

Diğeri kan ter içinde yayla yollarında

Mavzerinin demirini alnına dayamış

Yüreği susuzluktan bunalan

İçinden mahpushane çeşmeleri akan

Ansızın parlayan keklikleri jandarma baskını sanıp

Apansız silahına davranan

Nice delikanlıların figüranlık yaptığı

Yazlar bilirim memleketime özgü

Güzler bilirim ülkeme dair

Karşılıksız kalmış bir sevda gibi gelir 

Kalakalmış bir kıyıda melül ve tenha

Kalbim gibi

Kaybolmuş daracık ceplerinde elleri

Titreyen kenar mahalle çocukları

Bir sıcak somun için, yalın kat bir don için

Dökülürler bulvarlara yapraklar gibi.

Kadınlar bilirim ülkeme ait

Yürekleri Akdeniz gibi geniş, soluğu Afrika gibi sıcak

Göğüsleri Çukurova gibi münbit

Dağ gibi otururlar evlerinde 

Limanlar gemileri nasıl beklerse 

Öyle beklerler erkeklerini

Yaslandın mı çınar gibidir onlar sardın mı umut gibi.

İsyan şiirleri bilirim sonra

Kelimeler ki tank gibi geçer adamın yüreğinden

Harfler harp düzeni almıştır mısralarında

Kimi bir vurguncuyu gece rüyasında yakalamıştır

Kimi bir soygun sofrasında ışıklı sofralarda

Hırsızın gırtlağına tıkanmıştır.

Müslüman yürekler bilirim daha

Kızdı mı cehennem kesilir sevdi mi cennet

Eller bilirim haşin hoyrat mert

Alınlar görmüşüm ki vatanımın coğrafyasıdır

Her kırışığı sorulacak bir hesabı

Her çizgisi tarihten bir yaprağı anlatır.

Bütün bunların üstüne

Hepsinin üstüne sevda sözleri söylemeliyim

Vatanım milletim tüm insanlar kardeşlerim

Sonra sen gelmelisin dilimin ucuna adın gelmeli

Adın kurtuluştur ama söylememeliyim

Can kuşum, umudum, canım sevgilim.', '``Telgrafın tellerini kurşunlamalı’’ Öyle değildi bu türkü bilirim Bir de içime -Her istasyonda duran sonra tekrar yürüyen- Bir posta katarı...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/sana-bana-vatanima-ulkemin-insanlarina-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine Sevmiştim', 'oylesine-sevmistim-i-brahim-sadri-4bss2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi gidiyorsun, git

Bütün sabahları üşüdüğüm

Bütün gördüğüm senli günlerim, onlar da gitsin

İçimde bir şarkı

Gözümde bir ışık kalmıştı herşeye inat

Kapat gözlerimi, sevdiğim anlar da gitsin

Yıldızları da alsana yanına gökyüzünden

Sevdiğimiz şarkıları da 

Pencereme konan yusufcukları da

Bana karanlığı bırak

Beni bırak, beni böyle bırak

Böyle ansızın, böyle yakışıksız

Böyle anlamsız, böyle dağınık

Öyle kapıda susuşun

Öyle sarsak, öyle serkeş, öyle çerkes duruşun

Koy beni sensizliğe

Ve otursun içime kül gibi kor yangının

Şimdi gidiyorsun, git

Hadi git

Hepsi hepsi bir sevda benimkisi, al da git

Hadi kanatma

Hadi yıkma

Hadi dokunma

Zaten ben seni öylesine sevmiştim

Şimdi gidiyorsun, git

Bütün sabahları üşüdüğüm

Bütün gördüğüm senli günlerim, onlarda gitsin

İçimde bir şarkı

Gözümde bir ışık kalmıştı herşeye inat

Kapat gözlerimi, sevdiğim anlar da gitsin', 'Şimdi gidiyorsun, git Bütün sabahları üşüdüğüm Bütün gördüğüm senli günlerim, onlar da gitsin İçimde bir şarkı Gözümde bir ışık kalmıştı her...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sadri']::text[], 8.5, '{"poet":"İbrahim Sadri","poet_slug":"i-brahim-sadri","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/oylesine-sevmistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Nedir Bilir Misin?', 'sevmek-nedir-bilir-misin-zulkar-ozkan-iymj6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaslandığım bu duvar, ciğerlerim kadar nemli; belki benden de yaşlı

Büyük bir şehirde, kurulu bir evde duvar olmak zor olmalı

Benim gibi anlaşılmaz, gösterişten uzak düşüncelerim kadar sade

Severim kireçli duvarları

Ak ve temiz duvarlara çizerim resmini

Gözlerin, istedigim gibi çizilmiyor, çizemedim

Ağlamasınlar, dalıp gitmesinler diye

Bakmadım, baktırmadım kimseye sarhoş olurcasına dek kendim ağladım

Senin kalbinin bir şiiri vardı hani; ümitsiz Aşkları anlatan

Ve canım şu şarkıyı okudum kısık sesle;

''''Dönülmez Akşamın Ufkundayım Vakit çok geç,

''''Bu son fasıldır Ey Ömrüm Nasıl Geçersen Geç,

Ve düşündüm; feyfetullaha yakılmalı bu ağıt diye

Zect olurcasına, bitap düşene dek

Kor ateşler gibi sarmalı kollarından 

Ayaklarını prangalamalı

Yobazlaşan neslin ardından 

Ninelerin, dedelerin yakalrına yapışmalı

Nerede o eski Adab-ı Maşeret diye

Mezardakilerden hesap sormalı

Bırakıp gidenlere bağlılığı, aşkı, ağlamayı anlattırmalı

Yıkılmadan, yanmadan, usandırmadan

Yine, yeni, yeniden başlamalı biten sevdalar

Senin bir gülüşün vardı önceden Ay kadar parlak geceler kadar sukut içinde

Öldürmeden önce sevmeli sonra can vermeli

Oysa ölmedin benim için

Geçen bunca zamanı sensiz uğurluyorum

Yaz aylarında bile üşüyerek gidiyorum

Sitem etmiyorum bak yine;

AŞKIN için yazıyorum

Ama hep severek, yine severek

Kül tabaklarını doldurmakla saramazsın yaralı efkarını

Bir anlık zevk aldığın şey doldurmaz yüreğini

Neyse nasıl olsa haberin yok ya yazdıklarımdan

Yeniden diriliştir seni sevmek

Ne kötü ömrümün son yıllarında sana gelmek

Üzüntüm nedendir bilirmisin ?

Gençliği seninle yaşamak varken ;

Yan kesici yıllara çaldırdım 

Ölümlerimle, sana gelmek zoruma gider

Zoruma gider deli taylar gibi koşamamak

Senin elerininde bir şiiri vardı beni sinir eden

Ellerini tutmadan yazmayacağım diye

Yosunlaşmış dişleri dirilten,

Biten sevdaları körükleyen,

Yanan gönüllere gün ve gün kor köz süren,

Ne harika ne de güzel,

Acı olan ise; Seni kırmak, üzmek

Kırıcı sitem dolu sözleri

Susarcasına çocuk gibi

DİNLETMEK SANA!.....', 'Yaslandığım bu duvar, ciğerlerim kadar nemli; belki benden de yaşlı Büyük bir şehirde, kurulu bir evde duvar olmak zor olmalı Benim gibi anl...', ARRAY['Türk Edebiyatı','Şiir','Zülkar Özkan']::text[], 8.5, '{"poet":"Zülkar Özkan","poet_slug":"zulkar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/sevmek-nedir-bilir-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hürriyet''e Dair', 'hurriyet-e-dair-nazim-hikmet-ran-tqdyo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Onlar,  ümidin  düşmanıdır,

Sevdiğim, 

Akarsuyun  meyve  çağında  ağacın

Serpilip  gelişen  hayatın   düşmanıdır.

Çünkü,  
..........
..........', 'Onlar,  ümidin  düşmanıdır, Sevdiğim,  Akarsuyun  meyve  çağında  ağacın Serpilip  gelişen  hayatın   düşmanıdır. Çünkü,   .......... .........', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hurriyet-e-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'utansin', 'utansin-rukneddin-akbas-i91z0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzel yaşatmayan hayat utansın

Utanmak bilmeyen surat utansın

Zulümden zevk alan kat kat utansın

Pisliği hoş gören berbat utansın

Sultansız olan taç taht utansın

Şahsa yar olmayan her baht utansın.

(Şanlıurfa-2000)', 'Güzel yaşatmayan hayat utansın Utanmak bilmeyen surat utansın Zulümden zevk alan kat kat utansın Pisliği hoş gören berbat utansın Sultansız ...', ARRAY['Türk Edebiyatı','Şiir','Rükneddin Akbaş']::text[], 8.5, '{"poet":"Rükneddin Akbaş","poet_slug":"rukneddin-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/utansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Çürüdü', 'su-curudu-ahmet-telli-vo72l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '1

Yetmiş iki gündür bir dolapta kilitliyim. Yalnızca anahtar

deliğinden hava giriyor ve ölü bir ışık sızıyor içeri. Yalnızlık

hiç de tanrısal değil, görkemli değil. O yalnızca geçmişle

gelecek, ölümle yaşam arasında kocaman bir karanlık nokta.

Geçmişi ve geleceği olmayan, ölümle yaşam arasında irinli bir

leke yalnızlık denilen. Şimdi ne varsa, anahtar deliğinden sızan

havayla ışıkta... (Farkına varsalar, kapatırlar mıydı onu da?) 

Bütün belleğimdekileri yokettim. Elektrikli bir aygıtla yaktım,

jiletle kazıdım. Çığlıkların aralığından uçurdum hepsini, kül

edip savurdum.

Adımdan gayrısını bilmiyorum.

2

Zamanı yiyip bitirdi karanlık. Gece yoktu. Güneş çoktan

kömürleşmiş ve yeryüzü yapışkan bir karanlıkla örtülmüştü.

Yabanıl sesler geliyordu derinlerden ve karanlığı ince bir bıçak gibi

yırtıyordu. Saklayan kırbaç gibi... Acı duvarını aşan bu

sesler, madeni bir gürültüye dönüyor ve yerkabuğunu

zorluyordu artık. Sesim yoktu. Karanlığın karnında yitirdim

sesimi. Kör bir kuyuda unutulan Yusuf''tum belki. Ama

durmadan soruyorlardı. Tanrılar bilmiyordu sordukları şeyleri,

peygamberler büsbütün hain çıkmıştı. Ama yine de soruyorlar,

soruyorlar, soruyorlar...

Adımdan gayrısını bilmiyorum.

3

İki şeyi bilmek istiyorum. (Belki aynı şeyi iki kere bilmek

istiyordum.)  Duvarların rengi neydi? Derimin rengi neydi? 

Dokunuyorum duvarlara; parmak uçlarımla, avuçlarımla,

dilimle dokunuyorum. Duvarların bir rengi olmalı. Ama hiçbir

duvarcının, hiçbir ressamın bu rengi bildiğini sanmam. Adı

yoktu bu rengin, kimyası yoktu. Belki renksizliğin rengiydi bu.

Çürüyen bir bedenin kokusuydu duvarların rengi...

Adımdan gayrısını bilmiyorum.

4

Bir böcek gibi antenlerimi gezdiriyorum bedenimde. Anahtar

deliğinden sızan ölü ışıkta ellerime bakıyorum. Ellerim... Sanki

bir kadının memelerini hiç okşamamış, sicaklığını duymamış.

Ellerim... Her dizesi çığlık olan şiirleri hiç yaratmamış sanki. Ne

beyaz tenliyim artık, ne esmer, ne de kara... Cüzzamlının,

vebalının bir rengi vardır. İrinin bir rengi... Ölünün bile bir

rengi vardır ama derimin rengi yoktu. Belki çürüyen bir kentin

rengiydi bu. Çürüyen bir dünyanın...

Adımdan gayrısını bilmiyorum.

5

Killi, ayakları üzerinde duramayan bir yaratıktım artık.

Soyumun neye benzediğini unuttum. ''İnsana benziyorlardı''

diye duymuştum bir vakitler. Demek ki şimdi maymun

halkasında insanlık...

Adımdan gayrısını bilmiyorum.

6

Ağzımı anahtar deliğine dayayıp havayı emiyorum. Böcek

sokması gibi bir yanma duyuyorum boğazımda. Oysa kuru bir

yaprağı bile dalından düşürecek gibi değil bu esinti. Belki

çöle dönmüş toprağa tek yağmur damlasının düşüşü yalnızca.

Çamur gibi bir yağmur damlası... Ama toprak, bu damlayla

çatlatacak bağrındaki tohumu. Çöl, bütün vahalarını bu

damlayla yeşertecek... Genzim yanıyor. İnce bir kan şeridi

sızıyor dudaklarımdan. Kirli, sıcak ve simsiyah...

Adımdan gayrısını bilmiyorum.

7

Suyum, bir litrelik karton süt kutusu içinde. Yetmiş iki gündür

sakındığım ve hergün ancak bir kere dudaklarımı

değdirdiğim... Dilimi bir köpek gibi değdirdiğim. (Dilin suya

dokunuşu... Bir süngerin denizi yutuşu yani. Bir çölün seraba

kesilmesi bir an için.)  Her gün ancak bir kere değdiriyorum

dudaklarımı suya. Dilimi kaçırıyorum artık. Sünger, bütün

vantuzlarını birden uzatmasın diye... Bataklıktaki suyun da bir

su yanı vardır. Çürüyen bir bedenin bile dayanılabilir

kokusuna. Kutuda kalan son bir yudum su, bu bile değildi

artık. Küstü, öldürdü kendini su...

Su çürüdü...

Adımdan gayrısını bilmiyorum', '1 Yetmiş iki gündür bir dolapta kilitliyim. Yalnızca anahtar deliğinden hava giriyor ve ölü bir ışık sızıyor içeri. Yalnızlık hiç de tanrısa...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/su-curudu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşün Eklenir Kimliğime', 'gulusun-eklenir-kimligime-ahmet-telli-2srv6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün biter gülüşün kalır bende 

anılar gibi sürüklenir bulutlar 

Ömrümüz ayrılıklar toplamıdır 

yarım kalan bir şiir belki de 

Aykırı anlamlar arayıp durma 

güz biter sular köpürür de 

kapanmaz gülüşünün açtığı yara 

uçurum olur cellat olur her gece 

Her gece yeniden bir talan başlar 

acı ses olur, ses deli bir yağmur 

eski bir eylüle gireriz böylece 

Sığındığım her yer adınla anılır 

ben girerim, sokağı devriyeler basar 

bir de gülüşün eklenir kimliğime', 'Gün biter gülüşün kalır bende  anılar gibi sürüklenir bulutlar  Ömrümüz ayrılıklar toplamıdır  yarım kalan bir şiir belki de  Aykırı anlamla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gulusun-eklenir-kimligime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuksun Sen', 'cocuksun-sen-ahmet-telli-liwhz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '1

Dünyanın dışına atılmış bir adımdın sen 

Ömrümüzse karşılıksız sorulardı hepsi bu 

Şu samanyolu hani avuçlarından dökülen 

Kum taneleri var ya onlardan birindeyim 

Yeni bir yolculuğa çıkıyorum kar yağıyor 

Bir aşk tipiye tutuluyor daha ilk dönemeçte 

Çocuksun sen sesindeki tipiye tutulduğum 

Dönüşen ve suya dönüşen sorular soruyorsun 

Sesin bir çağlayan olup dolduruyor uçurumlarımı 

Kötü bir anlatıcıyım oysa ben ve ne zaman 

Birisi adres sorsa önce silaha davranıyorum 

Kekemeyim en az kasabalı aşklar kadar mahçup 

Ve üzgün kentler arıyorum ayrılıklar için 

Bir yanlışlığım bu dünyada en az senin kadar 

Ve sen kendi küllerini savuruyorsun dağa taşa 

Bir daha doğmamak için doğmak diyorsun 

Ölümlülerin işi bir de mutlu olanların 

Onların hep bir öyküsü olur ve yaşarlar 

Bırakıp gidemezler alıştıkları ne varsa 

Çocuksun sen her ayrılıkta imlası bozulan 

Susan bir çocuktan daha büyük bir tehdit 

Ne olabilir, sorumun karşılığını bilmiyor kimse 

Kötü bir anlatıcıyım oysa ben ve ne zaman 

Bir kaza olsa adı aşk oluyor artık 

Aşksa dünyanın çoktan unuttuğu bir tansık 

Seni bekliyorum orda, o kirlenen ütopyada 

Kirpiklerime düşüyorsun bir çiy damlası olarak 

Yumuyorum gözlerimi gözkapaklarımın içindesin 

Sonsuz bir uykuya dalıyorum sonra ve sen

Hiç büyümüyorsun artık iyi ki büyümüyorsun 

Adınla başlıyorum her şiire ve her mısrada 

Esirgeyensin bağışlayansın, biad ediyorum. 

Çocuksun sen ve bu dünya sana göre değil 

2

Çocuksun sen sesinin çağlayanına düştüm 

Bir çiçeğe tutundum düşerken, ordayım hâlâ 

Sallanıp durmaktayım bir saatin sarkacı

Nasıl gidip geliyor gidip geliyorsa öyle 

Zaman benim işte, nesneleşiyor tüm anlar 

Dursam ölürüm paramparça olur dünya 

Çocuksun sen sesinin çağlayanına düştüğüm 

Uçurum diyordun bir aşk uçurum özlemidir 

Bırakıyorum öyleyse kendimi sesinin boşluğuna 

Tutunabileceğim tüm umutları görmiyeyim için 

Gözlerimi bağlıyorum geceyi mendil yaparak 

(Gözlerim bir yerlerde daha bağlanmıştı, bunu 

Unutmuyorum unutmuyorum unutmuyorum hiç)

Bir rüzgâr esse ellerin fesleğen kokuyor 

Kırlangıçlar konuyor alnına akşamüstleri 

Bu yüzden bir kanat sesiyim yamaçlarda 

Üzgün bir erguvan ağacıyla konuşuyorum 

Ayrılığın zorlaştığı yerdeyim ve dalgınlığım 

Bir mülteci hüznüne dönüyor artık bu kentte 

Çocuksun sen alnına kırlangıçlar konan 

Bir bulutun peşine takılıp gittiğimiz yer 

Okyanus diyelim istersen ya da sen söyle 

Batık bir gemiyim orda, seni bekliyorum 

Upuzun bir sessizliğim fırtınalar patlarken 

Gövdem köle tacirlerinin barut yanıkları içinde 

Ve gittikçe acıtıyor yaralarımı tuzlu su 

Çocuksun sen, büyümek yakışmazdı hiç 

Gülüşünün kokusuyla yeşerdi bu elma ağacı 

(Soluğunun elma kokması bundandı belki)

Bir elma kokusuna tutundum düşerken 

Sallanıp durmaktayım bir saatin sarkacı 

Nasıl gidip geliyor gidip geliyorsa öyle 

Çocuksun sen, çocuğumsun', '1 Dünyanın dışına atılmış bir adımdın sen  Ömrümüzse karşılıksız sorulardı hepsi bu  Şu samanyolu hani avuçlarından dökülen  Kum taneleri va...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":68,"source_url":"https://www.antoloji.com/cocuksun-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Varmak', 'sana-varmak-binay-donmez-stt2g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgisizlik ölüm olsa ,gözlerimdeki umut sönerdi

     Umutsuzluk sonum olsa , sevgim beni gömerdi

     Akan gözyaşım sel olsa

     Sevgimin  şiddeti yel olsa 

     Sana varmak saniyeler sürerdi .

     Kalbim  paramparça bile olsa 

     Bölecek sevgim kalmasa 

     Ben yine de seni severdim

     Elimde avucumda bir tek yüreğim

     Gözlerim kalbinde , ellerim sende olsa da 

     Sana varacak bacaklarım kalmasa da 

     Sana varmak ,  saniyeler sürerdi.', 'Sevgisizlik ölüm olsa ,gözlerimdeki umut sönerdi      Umutsuzluk sonum olsa , sevgim beni gömerdi      Akan gözyaşım sel olsa      Sevgimin ...', ARRAY['Türk Edebiyatı','Şiir','Binay Dönmez']::text[], 8.5, '{"poet":"Binay Dönmez","poet_slug":"binay-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-varmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahmaran', 'sahmaran-ahmet-telli-vj9nz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sedef, safir ve kör uyku, dünden

Kalan bir aynaya vuruyor düş gibi

Ve kâhinin her remil atışında ölüm

Kara değil, karada havada ve suda

Ağlayan narım da çatladı çünkü ben

Çocuklarımı kaybediyorum dağlarda

Dağlar ki ceylan yurdu, bir gülistan

Olsun içindi düşerse yolu Şahmaran''ın

Ve anılardır diye bilinen Şahmaran

Belleğin derin kuyusundaki uykusunu

Bir hançerle kesip çıkmalıdır günyüzüne

Ve bırakarak derisini çöl iklimlerine

Tozlaşan ve durmadan tozlanan keder

Sedef, safir ve kör bir uykuya dönerken

Çöl hep çöldür, daima çöl, gri söylence

Ve buhurun incelttiği ölümcül bir büyü

Gülen ayvamı soruyorum ağlayan kızımı

Nerdesin bunca zaman ey Şahmaran

Dağlar ceylan yurdudur, bir gülistan

Düş yollara, keder öcünü almalıdır çünkü

(Çocuksun Sen)', 'Sedef, safir ve kör uyku, dünden Kalan bir aynaya vuruyor düş gibi Ve kâhinin her remil atışında ölüm Kara değil, karada havada ve suda Ağla...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sahmaran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölesiye', 'olesiye-binay-donmez-mznyc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölesiye seviyorum seni

Kurumuş yaprağın suya hasretindeki

Çimenin toprağa bağlanmasındaki 

Ölüm gibi , ölesiye !

Ölesiye özlüyorum seni

İsyanımın dağlara yankısındaki 

Ayrılığın acı gözyaşındaki 

Ölüm gibi , ölesiye !

Ölesiye istiyorum seni

Gözlerinin karasındaki

Kollarımın hasretinin arzusundaki

Ölüm gibi , ölesiye !', 'Ölesiye seviyorum seni Kurumuş yaprağın suya hasretindeki Çimenin toprağa bağlanmasındaki  Ölüm gibi , ölesiye ! Ölesiye özlüyorum seni İsya...', ARRAY['Türk Edebiyatı','Şiir','Binay Dönmez']::text[], 8.5, '{"poet":"Binay Dönmez","poet_slug":"binay-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olesiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Kuş', 'deli-kus-ahmet-telli-kjsrj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Deli kuş bilir misin nedir  

türküler kadar sevdalanmak   

duyabilmek yüreğinde   

bir depremin uğultusunu 

Suya düşen bir karanfilse yüreğin

bırak kendini ırmağın türküsüne gülüm

vursun seni o taştan bu taşa

o çağlayandan bu çağlayana

Kavgadan uzak kalmışsan

sevdadan da uzaksın demektir

devinmez yüreğinin mağması

çatlamaz sabrın kara taşı

(Huznun isyan olur)', 'Deli kuş bilir misin nedir   türküler kadar sevdalanmak    duyabilmek yüreğinde    bir depremin uğultusunu  Suya düşen bir karanfilse yüreği...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/deli-kus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçıncı Gece', 'kacinci-gece-hakan-akyurt-v5dbi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yarısı,

Gözlerim uykuya dargın,

Bilmem kaçıncı küskünlük bu,

Kaçıncı geceleri kendime dost bilişim,

Bu kaçıncı gece?

Kaç gecedir aynı sahne,aynı seneryo,

Kaçıncı aynı oyunu oynayışım.......

Gecenin bir yarısı,

Kendim kendimle dargın,

Bilmem kaçıncı kızışım kendime,

Kaç gecedir aynı yemin , aynı söz veriş,

Kaçıncı vazgeçemeyişim senden.......

Gecenin bir yarısı,

Şarkılar şarkılara dargın,

Bilmem kaçıncı aynı şarkıyı dinleyişim,

Kaç gecedir aynı acı,aynı gözyaşı,

Kaçıncı hayalinle dans edişim..........

Gecenin bir yarısı,

Kaçıncı sohbetlerdeyim,

Kaçıncı söz edişim senden geceye,

Kaç gecedir aynı sohbet, aynı bıkışı benden gecenin,

Kaçıncı hesaplaşışım kendimle..........

Gecenin bir yarısı,

Şu sokak ve ben ?

Kaçıncı başbaşa kalışımız,

Kaç gecedir aynı soluk,aynı ayak sesleri beklediğim,

Kaçıncı başka sokaklardan geçişim...........

Bir gece yarısı,

Herşey herşeye dargın,

Kaçıncı yalnız kalışım,

Kaç gecedir aynı duvar, aynı buğulu cam aramızda,

Kaçıncı ellerimin arasından kayışın,

Ve sokak , ve gece ve ben...

Bir şeye dargın..:

SANA ! SEN OLMAYANA.....!!!', 'Gecenin bir yarısı, Gözlerim uykuya dargın, Bilmem kaçıncı küskünlük bu, Kaçıncı geceleri kendime dost bilişim, Bu kaçıncı gece? Kaç gecedir...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kacinci-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorma', 'sorma-hakan-akyurt-te81k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bana dünya '' yı sorma sakın...!

Çünkü ben ; onunla dönmüyorum...

Bana insanları sorma sakın...!

Çünkü ben ; onlardan uzak yaşıyorum...

Bana kendimi sorma sakın...!

Çünkü ben ; kendimi sende arıyorum...

Bana sevdiğin kim diye sorma sakın...!

Çünkü ben ; onu sana şiirlerimle anlatıyorum........', 'Bana dünya '' yı sorma sakın...! Çünkü ben ; onunla dönmüyorum... Bana insanları sorma sakın...! Çünkü ben ; onlardan uzak yaşıyorum... Bana ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sorma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seçim Senin', 'secim-senin-fatih-i-stanbullu-bcq1b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ya tut ellerimi hiç bırakmadan,

yada bırakgit ellerimi hiç tutmadan.

Ya bak gözlerime içimi yakarak,

yada dön git ben sana alışmadan.

Seveceksen sev,beni ta derinden,

eğer sevmeyeceksen çık git yüreğimden.

Ya sabah güneşim,  gecede ayım, gökte yıldızım ol,

yada kayan bir yıldız gibi ufukarda kaybol.', 'Ya tut ellerimi hiç bırakmadan, yada bırakgit ellerimi hiç tutmadan. Ya bak gözlerime içimi yakarak, yada dön git ben sana alışmadan. Sevece...', ARRAY['Türk Edebiyatı','Şiir','Fatih İstanbullu']::text[], 8.5, '{"poet":"Fatih İstanbullu","poet_slug":"fatih-i-stanbullu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/secim-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lütfen', 'lutfen-hakan-akyurt-euutl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ellerin ellerime değmesin lütfen..!

Yoksa bu eller ; ellerini arar olur...

Gözlerin gözlerime bakmasın lütfen..!

Yoksa bu gözler gözlerine tutkun olur...

Kalbin kalbimi sevmesin lütfen..!

Yoksa bu seven kalp ; ayrılırsa kahrolur........', 'Ellerin ellerime değmesin lütfen..! Yoksa bu eller ; ellerini arar olur... Gözlerin gözlerime bakmasın lütfen..! Yoksa bu gözler gözlerine t...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/lutfen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneme', 'anneme-hakan-akyurt-nvb2l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kızını hep mutlu sanırsın anne..!

Kızın ızdırap çeker, haberin var mı..?

Gülümseyen gözlerimi mutlu sanırsın anne..!

Kızın üzgündür, haberin var mı..?

Geceleri kızının uyuduğunu sanırsın anne..!

Sessizce ağladığından, haberin var mı..?

Kızını hep çocuk mu sanırsın anne..!

Kızın aşık, bundan haberin var mı.......?', 'Kızını hep mutlu sanırsın anne..! Kızın ızdırap çeker, haberin var mı..? Gülümseyen gözlerimi mutlu sanırsın anne..! Kızın üzgündür, haberin...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşler Sokağı', 'dusler-sokagi-hakan-akyurt-9i9u7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gece vakti karşılaşmıştık seninle,

Pembe taşlı kaldırımda yürürken..

Bir gece vakti konuşmuştuk seninle,

Pembe masalı bir kafenin bahçesinde..

Bir gece vakti düğünümüz için karar almıştık,

Pembe pembe hayallerimiz vardı...

Bir gece vakti ilk kavgamızı yapmıştık,

Pembe duvarlı odamın içinde..

Ve ; bir gece vakti ayrıldık seninle,

Pembe evlerin bulunduğu ;

DÜŞLER SOKAĞINDA.....', 'Bir gece vakti karşılaşmıştık seninle, Pembe taşlı kaldırımda yürürken.. Bir gece vakti konuşmuştuk seninle, Pembe masalı bir kafenin bahçes...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dusler-sokagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Olacak', 'bir-gun-olacak-hakan-akyurt-jnf8c', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün olacak ; seveceksin sende çılgınca..

Bir gün olacak ; yaşayacaksın aşkı doya doya..

Bir gün olacak ; beni unutup dalacaksın yarınlara..

Bir gün olacak ; kahrolacaksın benden ayrıldığına..

Ama her ne olursa olsun..;

Bir gün olacak ve ; sende gireceksin herkes gibi ;

Kara Toprağa...........', 'Bir gün olacak ; seveceksin sende çılgınca.. Bir gün olacak ; yaşayacaksın aşkı doya doya.. Bir gün olacak ; beni unutup dalacaksın yarınlar...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-gun-olacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sensin', 'sensin-alper-uluses-l7l0t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'üzüntülerin içinde seni ararken

kendimi terkettim birden

nasılsa sen oradaydın

yanıbaşımda benimle birlikte yeniden

anladım ki kendimi kaybettiğimde buluyorum seni

seni kaybetmek istediğimde kendimi arıyorum', 'üzüntülerin içinde seni ararken kendimi terkettim birden nasılsa sen oradaydın yanıbaşımda benimle birlikte yeniden anladım ki kendimi kaybe...', ARRAY['Türk Edebiyatı','Şiir','Alper Uluses']::text[], 8.5, '{"poet":"Alper Uluses","poet_slug":"alper-uluses","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dörtlüklerim', 'dortluklerim-hakan-akyurt-q12k9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tepeler üstünde bir fırtına gibi esen,

Uzak ufuklar misali gözüken,

Tıpkı bir tabiat harikasına benzeyen,

Ay yüzlü bir güzel varsa ; O SENSİN........

*************************************

Arzu edebilirsen eğer sevdayı ömrünce,

Sadece bir ufak çaban ona yeter.

Lüzum bulmazsan eğer sevdayı gönlünde,

Işıksız bir oda bile sana yeter..............

****************************************

Çıldırsam da sesini duymadan,

Ellerim uzansa da telefonun tuşlarına,

Seni üzmemek için sevdiğim,

kahrolsam da seni aramayacağım.......

******************************************

Benim ben ki; kapına gelen dilenci,

Ellerini değil, gönlünü açan biri..

Biliyorum beni anlamayacaksın amma,

Bil ki dilendiğim ; sadece senin sevgin idi.....

*********************************************

Ben sana seni seviyorum demedim,

Sadece saygımla seni seveceğimi söyledim..

Ben seni kaşın, gözün için sevmedim,

Sadece seni sen yapan tüm özelliklerini sevdim....

***********************************************

Gözyaşlarına hükmetmemeli insan,

Bırakmalı özgürce taneleri..

Kendini sıkmadan...

Rahatça.. 

Sevgisi için ..

Ağlayabilmeli.................

*************************************************

Sen ki; gözlerinde sevdanın parıltısı olmayan biri,

Ben ki ; bu ışıltıyı farkeden bir kişi,

Ne ömrün geçer gizlenmekle senin,

Ne de seni sevmekle ömrüm biter benim........

***************************************************

Geceler geceleri kovalıyor yine,

İçimde hüzün ve aklımda sen varsın..

Seni hiç aramayacak olsam bile,

Aklımda , fikrimde yine sen varsın...........

****************************************************

Çıldırmamak elde değil, kavuşmakta çare,

Söylesem sevdiğimi bilmem düşerim ne hale..!

Ya sevigini bastıracak bulacaksın bir tane,

Ya da oturup bekleyeceksin,birgün olacak diye....!

*********************************************************

Senin için ağlayacağım en sonunda....

Düşünüyorum..!

Acaba yazık mı olacak gözyaşlarıma..?

Yoksa bu kadar gözyaşı..;

Bir başlangıç mı olacak....

Seni Hatırlamaya.....................

*********************************************************

Sen ; toprağı sevgi olan,

Sevgi suyuyla beslenmesi gereken,

Bazende severek şımartılması,

Şımardıkça da çiçekleri açan,

Kızınca da dikenlerini batıran,

Henüz yeni açan..,

Nazlı bir gül gibisin.................', 'Tepeler üstünde bir fırtına gibi esen, Uzak ufuklar misali gözüken, Tıpkı bir tabiat harikasına benzeyen, Ay yüzlü bir güzel varsa ; O SENSİ...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/dortluklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Gelebilirim', 'bir-gun-gelebilirim-sinem-erdogan-fgnwx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Birgün gelebilirim sevgilim,

Her geçen gün içimde büyüyen

O sonsuz sevginin esiri olup,

Ansızın çıkıp gelebilirim birgün... 

Soğuk ve karanlık gecede,

Pencerenin önüne oturup,gelmeni bekleyebilirim..

Yanımda o çok sevdiğin,

Mor menekşelerden de getiririm...

Sensiz ve yalnızken,

Yokluğunun acısıyla yorgun düşen bedenim

Son nefesini verir belki...

       Kim bilir belkide sevgilim,

                 

                        Pencerenin önünde ölebilirim...', 'Birgün gelebilirim sevgilim, Her geçen gün içimde büyüyen O sonsuz sevginin esiri olup, Ansızın çıkıp gelebilirim birgün...  Soğuk ve karanl...', ARRAY['Türk Edebiyatı','Şiir','Sinem Erdoğan']::text[], 8.5, '{"poet":"Sinem Erdoğan","poet_slug":"sinem-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-gun-gelebilirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Yeter', 'bana-yeter-hakan-akyurt-7ll3v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aydınlık gönlünün bahçesinde,

Sığınsan bir yere bana yeter...

Leylak kokulu güzel çehrende,

Isınsam bir dakka bana yeter...

Otursabilsem seninle bir saniye,

Kuracağım hayal bile bana yeter...

Umursamadan bana baksan bile,

Renkliliği bile bana yeter........', 'Aydınlık gönlünün bahçesinde, Sığınsan bir yere bana yeter... Leylak kokulu güzel çehrende, Isınsam bir dakka bana yeter... Otursabilsem sen...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bana-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeyimsin', 'herseyimsin-hakan-akyurt-x0jxa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen canım değilsin..!

Sana canmsın diyemem..!!

Çünkü ben canımı önemsemem...

Tek gerçek var ki..:

Sen ; benim için canımdan da ötesin,

Sen ; tek sevdiğim, tek aşkım, bir tanemsin...

Kısacası  sen ;

HERŞEYİMSİN.........', 'Sen canım değilsin..! Sana canmsın diyemem..!! Çünkü ben canımı önemsemem... Tek gerçek var ki..: Sen ; benim için canımdan da ötesin, Sen ;...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/herseyimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-hakan-akyurt-ex5lp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen ; gönlümde ırmak misali akan....

Sen ; gözlerimde bir yıldız misali kayan....

Sen ; düşündüğüm, vazgeçemediğim....

Sen ; tek sevdiğim, bir tanecik..;

PAMUK PRENSESİMSİN.........', 'Sen ; gönlümde ırmak misali akan.... Sen ; gözlerimde bir yıldız misali kayan.... Sen ; düşündüğüm, vazgeçemediğim.... Sen ; tek sevdiğim, b...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Sen', 'sadece-sen-hakan-akyurt-mj71r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen varsın aklımda, sadece sen....

Gözlerimi kapatsam gözlerin,

Yüzünü görmesem yüzün gelir aklıma...

Unutmaya çalışsam, unutamam seni...

Anladım ki ; seni sen yapan herşeyi seviyorum...

Anladım ki ; aklımda da , fikrimde de sadece sen...

Sen varsın , sadece sen........', 'Sen varsın aklımda, sadece sen.... Gözlerimi kapatsam gözlerin, Yüzünü görmesem yüzün gelir aklıma... Unutmaya çalışsam, unutamam seni... An...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sadece-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usta', 'usta-mustafa-hatipoglu-g8cvb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne olacak  böyle  usta

Ne diyorsun bu hususta.

Konuşamadık bir türlü,

Ne temmuzda, ne Ağustosta..

İşte bir yıl daha geçti 

Heyelan gibi üstümüzden

İşte bir yıl daha geçti

Yaşamadan gençliğimizden

İşte bir yıl daha geçti

Şu kısacık ömrümüzden

Kimimiz evlenecek

Kimimiz boşanacaktı

Kimimiz ev alacak....

Araba alacaktı kimimiz...

Kimimiz iş kuracaktı

Ne umutlarımız, 

Ne hayallerimiz vardı be  usta

Ne diyorsun sen bu hususta

Konuşamadık bir türlü bunu

Ne temmuzda, ne Ağustosta..

Usta olmak kolaymı? 

Dürüstlüğün kalmadığı,

Dertsiz başın olmadığı,

Nice sevgilerin bir pula satıldığı,

Soğan kabuğundan yapılmış

Cüzdanların göz yaşarttığı,

Bir zamanda usta olmak kolaymı? 

Konuşsana be usta konuşsana

Neden her gün zayıflıyor bedenin.

Neden titriyor hep kalem tutan ellerin

Neden ıslak ıslak oldu gözlerin..

Yoksa, yoksa, tükendi mi? 

Bize umut veren sözlerin.

Söylesene be usta söylesene

Kedinin Aslanı boğduğu yerde

Sen paradan haber ver.

Parayı ver de,

Kaldımı delikanlılık serde

Kadın bir gül, Aşk bir mevsim

Hayat bir oyun yaşadığın yerde

İşte başlıyor PERDE be Usta PERDE', 'Ne olacak  böyle  usta Ne diyorsun bu hususta. Konuşamadık bir türlü, Ne temmuzda, ne Ağustosta.. İşte bir yıl daha geçti  Heyelan gibi üstü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Hatipoğlu']::text[], 8.5, '{"poet":"Mustafa Hatipoğlu","poet_slug":"mustafa-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/usta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-mustafa-hatipoglu-dywvn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seninle yaşadığım her günü özel bir güne dönüştürdüğün için,

Beni değiştirmeye çalışmadan, olduğum gibi sevdiğin için

Sadece sesimi duymak için aradığın için

Hayatın monotonluğunu ortadan kaldırdığın için

Kendimi keşfetmeme yardımcı olduğun için,

Bir şey söylemeden, bakışlarınla bile sevgini hissettirdiğin için

En iyi dostum, arkadaşım, sırdaşım olduğun için

Yanımdayken bile seni çok özlediğim için,

En önemlisi  '' BENİM SEVGİLİM ''  olduğun için

SENİ SEVİYORUM', 'Seninle yaşadığım her günü özel bir güne dönüştürdüğün için, Beni değiştirmeye çalışmadan, olduğum gibi sevdiğin için Sadece sesimi duymak i...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Hatipoğlu']::text[], 8.5, '{"poet":"Mustafa Hatipoğlu","poet_slug":"mustafa-hatipoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seni-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur', 'ne-olur-fatih-i-stanbullu-wz4eg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben sevdimya seni,

sen sevsen neolur? Sevmesen ne?

Şu yüreğime kazıdımya seni, istesen ne olur? istemesen ne?

Bir yere yazadım ezberledim ismini,

silip unutturamasınlardiye.

Kimseye demedim yazdım seni kalbime.

Koparım seni benden alamasınlar diye.

Hiç söylemedim sevdiğimi,

hiç manalı bakmadım gözlerine,

hiç sarmadım belini,

ve hiç tutmadım tutamadım ellerini,

alı?ırsam hasretin yaka diye bedenimi.

Hep uzaktan seviyorum seni,

Çünkü; yakla?ırsam alı?acağım sana.

Her kavgamızda hergidi?inde sana ağlayacağım.

Ben seni ağlamak için sevmedim cennet gözlüm,

seni ağlatmak içinde sevmedim.

Kıyamam saçının bir teline ve dokunamam incinirsin diye tenine.

Benseni yürekten sevdim sen bunu anlayamazsın.

Hem anlasan ne olur anlamasan ne?

Hiç bilemessin ne yazar bu yürekte.

Hiç bilemezsin kime ağlar bu gözler.

Sen ?ımarır bana ağlar dersin enayi.

Bilemezsin tatlı belam bilemezsin güzel rüyam bilemezsin

Ama yinede söyleyeyim sana.

Basit bir a?k değil destan yazar yüreğimde.

Sana değil olan a?kıma ağlar bu gözler.

Sana değil sevmesini bilene bu sözler.

Anlayamazsın güne? yüzlüm anlayamazsın gece gözlüm anlayamazsın. 

Anlasan erir mi ta? kalbin?sevmesini öğrene bilirmi? 

Hasretle geçen geceleri, offf çekilerek yakılan sigaraları,

O anlatılmaz ölümden beter anları, anlaya bilirmi ha!

Anlasana benim gibi seve bilirmi?

Arık dediğim olsa ne olur olmasa ne?

Gerçek ortada. 

   SENY SEVYYORUM.

      SENY SEVYYORUM.

             SENY SEVYYORUM....', 'Ben sevdimya seni, sen sevsen neolur? Sevmesen ne? Şu yüreğime kazıdımya seni, istesen ne olur? istemesen ne? Bir yere yazadım ezberledim is...', ARRAY['Türk Edebiyatı','Şiir','Fatih İstanbullu']::text[], 8.5, '{"poet":"Fatih İstanbullu","poet_slug":"fatih-i-stanbullu","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ne-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çüğdürüveririm', 'cugduruveririm-koray-askin-qrg04', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'darbe üstüne darbe yemiş,

kaçın kurası kelek kavunlar gibi...

delik ve deşik bir ceket üstünde

ve sidik kokulu pantolonumla

ve aldırmadan

sarhoş gibi

can yakmayan uyuşuk günlerde

o şişe dibi kendini bulmuşda;

güneşlenirken tosur tosur,

bir daha da gelse çişim;

ne kalkarım sana kadar, ah be o duvar,

ben çüğdürüveririm şu yamacıma;

sana gelene kadar...', 'darbe üstüne darbe yemiş, kaçın kurası kelek kavunlar gibi... delik ve deşik bir ceket üstünde ve sidik kokulu pantolonumla ve aldırmadan sa...', ARRAY['Türk Edebiyatı','Şiir','Koray Aşkın']::text[], 8.5, '{"poet":"Koray Aşkın","poet_slug":"koray-askin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cugduruveririm-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelek', 'kelek-koray-askin-35oc0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yoksa bir çividir eline batmış

ve kandır çivide o acıyla

feleğin keleği gecelerden ve günlerden

ve belki yalnız geçen ve belki

dertsiz geçen,ama mutsuz geçen gecelerden

kış dayanacak kapı bulamayıpta

işlemiştir iliğine

ve sarılmak ite,sıcaklığında uyumaktır.

sobanın gürültüsü yoktur belki ama sıcaktır

ve şarap gibi kanım çivinin ucundayken

ne gece ne keleği feleğin

nede kıştır beni ürküten

bir damla kanım vardır

o da artık paslı bir çivide...

18 şubat 2000 2:33', 'yoksa bir çividir eline batmış ve kandır çivide o acıyla feleğin keleği gecelerden ve günlerden ve belki yalnız geçen ve belki dertsiz geçen...', ARRAY['Türk Edebiyatı','Şiir','Koray Aşkın']::text[], 8.5, '{"poet":"Koray Aşkın","poet_slug":"koray-askin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kelek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Ne Çok Sevmişim Seni', 'ah-ne-cok-sevmisim-seni-yasar-gunacgun-je23e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen desem seni bilir misiniz?

Sen diye bir desen çizebilir misiniz?

Bir mesken bulamadım kalbime 

BÜYÜK AŞKLAR vardır bilir misiniz?', 'Sen desem seni bilir misiniz? Sen diye bir desen çizebilir misiniz? Bir mesken bulamadım kalbime  BÜYÜK AŞKLAR vardır bilir misiniz?...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Günaçgün']::text[], 8.5, '{"poet":"Yaşar Günaçgün","poet_slug":"yasar-gunacgun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ah-ne-cok-sevmisim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gece', 'bir-gece-yasar-gunacgun-hj676', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gece hafif serin;

 ışıklar istiyorum ama başka şehirlerin.

Tuttuğum her şeyi aşk belliyorum ama; 

Aşk başka seyirlerin', 'Bir gece hafif serin;  ışıklar istiyorum ama başka şehirlerin. Tuttuğum her şeyi aşk belliyorum ama;  Aşk başka seyirlerin...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Günaçgün']::text[], 8.5, '{"poet":"Yaşar Günaçgün","poet_slug":"yasar-gunacgun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi marşı', 'sevgi-marsi-i-smail-hakki-kavurmaci-5573g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ellerde bayraklar

 dillerde marşlar

 bayrak bayrak dünya

 çoğaldıkça bayraklar

 ayrılıyor yürekler

 bayrakları yakın

 sınırları yıkın

 isimleri silin

 tek bir bayrak dalgalansın

 SEVGİ BAYRAĞI

 tek bir sınır aşılmasın

 İNSAN HAKLARI

 tek bir isim kalsın

 SEVGİ DÜNYASI', 'ellerde bayraklar  dillerde marşlar  bayrak bayrak dünya  çoğaldıkça bayraklar  ayrılıyor yürekler  bayrakları yakın  sınırları yıkın  isiml...', ARRAY['Türk Edebiyatı','Şiir','İsmail Hakkı Kavurmacı']::text[], 8.5, '{"poet":"İsmail Hakkı Kavurmacı","poet_slug":"i-smail-hakki-kavurmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevgi-marsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmene', 'gitmene-serdar-ertugrul-8xj5h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben bir beden,

Sen ise candın.

Gitmeni istemedim

Gidişin ölümüm oldu.

Yokluğun çürüttü sevdamı.

Çürüdüm  artık,

Dönsende

Çürümüş bedene can neye yarar?', 'Ben bir beden, Sen ise candın. Gitmeni istemedim Gidişin ölümüm oldu. Yokluğun çürüttü sevdamı. Çürüdüm  artık, Dönsende Çürümüş bedene can ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Ertuğrul']::text[], 8.5, '{"poet":"Serdar Ertuğrul","poet_slug":"serdar-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gitmene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Yokken Affedemem Seni', 'gozlerin-yokken-affedemem-seni-serdar-ertugrul-bvt2s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sığınmaktı aşkın diğer adı...

Dev dalgalardan kaçan bir kayık gibi,

Bir sahil aramaktı aşkı aramak...

Nasıl bilecektik ki,

Kaçtığımız dalgaların anası var sahilde.

Nasıl bilecektik,

Dalganın karadan geleceğini.

Fırtınaların en azgını bekliyormuş bizi.

Nerden bilecektik...

Göz yaşlarını silmekten kaçarken,

Gözyaşı yağmurlarına yakalanacağımızı,

Eskiden üzüntüler fayda verirdi.

Nasıl bilecektik ki,

Uzaktan mutluluğa benzettiğimiz şehrin,

Faydası yok hüzünler şehri olduğunu.

Gözlerine tutunmak geldi aklıma,

Kurtuluşum gözlerindi.

Gözlerin herşeyimdi...

Fakat nereden bilebilirdim ki,

Gözlerini daha yolculuğa çıkmadan kaybetmişim.

Her vadide seni farklı gördüm.

Farkın benim farklı görüşümden kaynaklanmıştı

Bilemedin.

Ben büyüttüm,sen büyüdün.

Büyüdün ve kocaman oldun.

Oysa bir balon gibiydi.

Üflersin ve büyür.

Üzüntümün senin için olduğunu,

Bir gün öğreneceksin.

Ve işte herşeyi biliyorum

Ama artık seninle ilgili hiç bir şey bilmiyorum.', 'Sığınmaktı aşkın diğer adı... Dev dalgalardan kaçan bir kayık gibi, Bir sahil aramaktı aşkı aramak... Nasıl bilecektik ki, Kaçtığımız dalgal...', ARRAY['Türk Edebiyatı','Şiir','Serdar Ertuğrul']::text[], 8.5, '{"poet":"Serdar Ertuğrul","poet_slug":"serdar-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gozlerin-yokken-affedemem-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-i-smail-hakki-kavurmaci-21w7a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne varlığına alışabildim

Geldin geleli

Ne yokluğuna dayanabildim

Gittin gideli

Varlığını kaybetmek korkusuyla yaşadım

Yokluğunda taş bastım yüreğime yanarım', 'Ne varlığına alışabildim Geldin geleli Ne yokluğuna dayanabildim Gittin gideli Varlığını kaybetmek korkusuyla yaşadım Yokluğunda taş bastım ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Hakkı Kavurmacı']::text[], 8.5, '{"poet":"İsmail Hakkı Kavurmacı","poet_slug":"i-smail-hakki-kavurmaci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tünel', 'tunel-haydar-ergulen-67oan', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ateşçi gelir, kömür atar ve tren

deler sizin karanlığınızı

ateşçi gelir, kömürü karıştırır ve tren

çıkar sizin karanlığınızdan

Sizn tünelinizi hatırlıyorum sanki 

tren değil yolcular geçiyordu 

ve hatırlamıyorum bundan 

daha karanlık bir yolculuğu

Nasılsa kendi karanlığınızdan 

bir gün siz de geçersiniz 

çıkar karşınıza bir avuç kül 

ve söndü sönecek ateşiniz', 'Ateşçi gelir, kömür atar ve tren deler sizin karanlığınızı ateşçi gelir, kömürü karıştırır ve tren çıkar sizin karanlığınızdan Sizn tünelini...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar-ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tunel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın Gece', 'yarin-gece-haydar-ergulen-cipgb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yarın gece gideceğim bu kentten

Bir ırmağa yolcuyum sular çekiyor beni

Yüreğimden başka taşıyacak yüküm yok

Sayılmazsa göğsümden düşen kuş ölüleri

Sözüm yok işte yüzüm işte akşam

Sesimde anıların sessizliği

İçimde acıyla yürüyorum yolları

Çoktandır yolumu ayırdığım bu kentten 

Yorulsam da bir daha binmem o trenlere

Kimse karşılamasın istasyonlarda beni

Kuşsuz bir kent gizli uzayan saçlarımda

Aşktan ve anılardan bir avuç külüm şimdi

Ardımda usulca akan küçücük sular

Bir onlar uğurluyor varacağım ırmağa

Sözüm yok işte yüzüm işte akşam

Sesimde anıların sessizliği

Sonunda bir soru gibi kaldım yine kendimle 

Kentin kırık aynasında eksildikçe düşlerim

Söyle benim ömrüm bu kente uğradı mı

Sahi ben hiç ömrümü kendime yaşadım mı', 'Yarın gece gideceğim bu kentten Bir ırmağa yolcuyum sular çekiyor beni Yüreğimden başka taşıyacak yüküm yok Sayılmazsa göğsümden düşen kuş ö...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar-ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yarin-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyoğlu''ndan Dolmabahçe''ye Taşınan Bir Aralık Akşamı', 'beyoglu-ndan-dolmabahce-ye-tasinan-bir-aralik-aksami-yilmaz-erdogan-oyrqa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sus pus olmuş puslu bir İstanbul muydu yüzünyoksa çok bildik hüzünler mi taşınmıştı yüzüne.

Dolmabahçe''de, çay tadında...

Divit ucuyla yazılmış bir aşkın sureti vardı avuçlarında, tarih bir başka iklimin kıvamını gösteriyordu.

Ben rehnedilmiş yelkovan gibi...Hani akrep''i seven ama yüreği takvim yokuşlarında...

       Sinemada elinin elimde terleyişinin bir anlamı olmalı, sesinin sesimde yankılanmasının...Sanki perdedekine üzülmüş ya da sevinmişsin de tesadüfen akmış yüzün içime...Yalan! Sen perdeye bakıyorsun, fikrin benim seyir defterimde...Ve ben amerikanca bir filmi kürtçe seyrediyorum.

Kadın, Beyoğlu''nda bir kış akşamında, üstündeki deri montun sahibine küs, soğukluğundan muzdarip yürüyordu...Adam da...Yürümek hiçbir şeyi çözmüyordu, bazı aralık akşamlarında...Parmağında yaralı bir öyküyü taşıyordu adam...Kadının yüzünde bir hüzün...Hüzünlü aralık akşamında bir yüzük...Yüzüğün yüzünde dünya güzeli bir kadının kehaneti...Soğuğun ve karanlığın vehameti! 

       Hayatı, bir başkasının pantolonu gibi küçültülmüş, daraltılmış..İlk sahibinin o pantolonla yaşadığı şeyler, yani pantolonu pantolon yapan anılar, bazı ilkbahar bereleri yüzünden yapılan yamalar, ter tüketen yazlar...Yaşananlara bir beden büyük geliyor artık hayat! 

        Bir aşkı paylaşmak için çok geç, bir paylaşıma aşık olmak içinse erken...Beni sevda yerimden vurdu yine zaman...Şimdi sana söylenecek tek cümle: 

      BENDE SANA YETECEK KADAR BEN KALMADI...', 'Sus pus olmuş puslu bir İstanbul muydu yüzünyoksa çok bildik hüzünler mi taşınmıştı yüzüne. Dolmabahçe''de, çay tadında... Divit ucuyla yazıl...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Erdoğan']::text[], 8.5, '{"poet":"Yılmaz Erdoğan","poet_slug":"yilmaz-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/beyoglu-ndan-dolmabahce-ye-tasinan-bir-aralik-aksami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Duvarı', 'sevgi-duvari-can-yucel-tn81f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen miydin o yalnızlığım mıydı yoksa

                 kör karanlıkta açardık paslı gözlerimizi

                  dilimizde akşamdan kalma bir küfür

                    salonlar piyasalar sanat sevicileri

               derdim günüm insan içine çıkarmaktı seni

                      yakanda bir amonyak çiçeği

                   yalnızlığım benim sidikli kontesim

                    ne kadar rezil olursak o kadar iyi

                   kumkapı meyhanelerine dadandık

              önümüzde altınbaş altın zincir fasulye pilakisi

                aramızda görevliler ekipler hızır paşalar

                  sabahları açıklarda bulurlardı leşimi

                     öyle sıcaktı ki çöpçülerin elleri

                    çöpçülerin elleriyle okşardın beni

                    yalnızlığım benim süpürge saçlım

                   ne kadar kötü kokarsak o kadar iyi

                    baktım gökte bir kırmızı bir uçak

                      bol çelik bol yıldız bol insan

                      bir gece sevgi duvarını aştık

                     düştüğüm yer öyle açık seçik ki

                 başucumda bir sen varsın bir de evren

                  saymıyorum ölüp ölüp dirilttiklerimi

                   yalnızlığım benim çoğul türkülerim

                 ne kadar yalansız yaşarsak o kadar iyi', 'sen miydin o yalnızlığım mıydı yoksa                  kör karanlıkta açardık paslı gözlerimizi                   dilimizde akşamdan kalma bi...', ARRAY['Türk Edebiyatı','Şiir','Can Yücel']::text[], 8.5, '{"poet":"Can Yücel","poet_slug":"can-yucel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sevgi-duvari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Borçlu', 'borclu-hasan-huseyin-korkmazgil-7imnn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Erik çiçek açmış da bahçenin kıyısında 

Sen ona hiç bakmadan geçmişsen oracıktan 

Leylek dansa durmuş da bacanın tepesinde 

O baharlım laklakını durup dinlememişsen 

Şakır şakır bir tren bir gece köprüsünden 

Islıkla dalmamışsan gurbet türkülerine 

Akasya mor akasya ak akasya sarı sarı sarkmış da bahar mavilerinden 

Yaşamak ne güzel şey diye ağlamamışsan 

Çocuklar birdirbir oynuyorlar da çöplük arsada 

Dikilip yanıbaşlarına göğüs geçirmemişsen 

Yanından geçip gitmiş de çilekçinin arabası 

Kaçtan veriyorsun hemşerim diye yutkunmamışsan 

İskelenin tepesinden türkü döken gurbetçi gence 

Varolasın koçum benim diye el sallamamışsan 

Bahar dalı gömleğiyle utangaç bir uçurtma 

Bu ne şıklık delikanlım diye laf atmamışsan 

Ve çapkınca bakmamışsan 

Göğsü domur domur yeniyetmeye 

Sesi bambam 

Sesi ramazan topu 

Kendini herkül sanan delikanlıyı 

Yaştaşınmışcasına süzüp selamlamamışsan 

Öpmemişsen gözlerine bakıp duran bir gözleri şenlikliyi 

Yaşama itmemişsen iter gibi denize 

Girmemişsen koluna bir yıkılmışın 

Yalanla da olsa avutmamışsan umutsuzu 

Su diyene bir avuç su 

Bir yaralı parmağa işememişsen 

Kolay gelsin dememişsen taş kıranlara 

Günaydınsız bırakmışsan bahçe bezeyenleri 

Eğilip koklamamışsan çitten gülen çiçeği 

Bayram bayram donanmamışsan 

Sevinciyle dostlarının 

Acısını dostlarının 

Yüreğinde duymamışsan 

Kapı kapı dolaşmamışsan iş dilenerek 

İşsizliğe düşmemişsen hakkım dedikçe 

Ve bayraklı pankartlı yürüyüşlere 

Halaylı horonlu grev şenliklerine 

Katılmayı aşk gibi duymamışsan şuranda 

Ağrın ağrım 

Acın acım 

Dememişsen insan kardeşlerine 

Ve dilinin en görkemli 

Ve dilinin bando-davul sövgülerini 

Sıralayıp sallamamışsan deyyuslar saltanatına 

Hangi yaşta olursan ol 

Kardeşim 

Kaptırıp gönlünü sevda fırtınasına 

Evin yolunu şaşırmamışsan 

Sende iş yok be kardeşim 

Sen artık hapı yutmuşsun 

Borçlusun sen ağaçlara kuşlara 

Borçlusun sen trenlere otobüslere 

Yağan kara esen yele borçlusun 

Borçlusun sen herşeye 

Gözdeki ışıltıya 

Alındaki çizgiye 

Eldeki şaşkınlığa 

Borçlusun herşeye 

Kardeşim 

Yaşamın kendisine', 'Erik çiçek açmış da bahçenin kıyısında  Sen ona hiç bakmadan geçmişsen oracıktan  Leylek dansa durmuş da bacanın tepesinde  O baharlım lakla...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Korkmazgil']::text[], 8.5, '{"poet":"Hasan Hüseyin Korkmazgil","poet_slug":"hasan-huseyin-korkmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/borclu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demedim Ki', 'demedim-ki-hasan-huseyin-korkmazgil-te9tc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu kenti sevdim dedim 

Benim olsun demedim ki 

Sevdim dedimse akşam kızıllığını 

Gönlüm gibi akıp giden şu çayı 

Şu ormanı şu denizi şu dağı 

Benim olsun demedim ki 

Vuruldumsa gözlerinin gül bahçesine 

Yürek çizen şimşeklerse kaçamak bakışları 

İşte buna sevmek derler dedimse 

Çattımsa acıların en güzeline 

Yedirdimse uykuları o tatlı kuşa 

Benim olsun demedim ki 

Bu akşam kankırmızı şarap istiyor canım 

Bu akşam dünyanın bütün şarkılarını 

Bu akşam dünyanın bütün özlemlerini 

Bu akşam beni yalnız bırakın 

Bu akşam yalnızca onu düşüneceğim 

Onu ve kendimi yalnızca', 'Bu kenti sevdim dedim  Benim olsun demedim ki  Sevdim dedimse akşam kızıllığını  Gönlüm gibi akıp giden şu çayı  Şu ormanı şu denizi şu dağı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Korkmazgil']::text[], 8.5, '{"poet":"Hasan Hüseyin Korkmazgil","poet_slug":"hasan-huseyin-korkmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/demedim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filizkıran Fırtınası', 'filizkiran-firtinasi-hasan-huseyin-korkmazgil-em3tb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gün doğmadan başladı filizkıran fırtınası 

evler yemen türküsü 

sokaklar seferberlik 

öyle bir gariplik ki 

öyle bir tedirginlik 

yaz başında güz sonrası 

ayvalar çiçekteydi 

güller daha tomurcuk 

açıl demişti güneş 

açılmıştı kıraçta kış elmaları 

çözül demişti güneş 

çözülmüştü yılanlar karanlık odalarında 

dallarda yuvalar tüy kokuyordu 

düğünçiçekleri şenlikli 

gün doğmadan başladı filizkıran fırtınası 

ne dal kaldı ne tomurcuk 

yerden yere çaldı otları ağaçları 

insan yüzlü bir korkuluk 

üşüdüm dünyalarca 

baskın yemiş bir kent gibi üşüdüm 

sergen etti filizleri sapsarı bir karanlık 

bahardan kışa düştüm 

acılı günler gördüm 

sığdıramam bir tek günü bir koca yıla 

geceler geçirdim yoz kentlerin bulvarlarında 

nice baharları kışlara gömdüm 

uzak düştüm yelinden yelvesinden acılı yurdun 

uzak düştüm umudundan mutundan 

yomundan uzak düştüm 

bunaltının böylesini görmedim 

severim fırtınanın her türlüsünü 

ormanlar uğultulu sular dalgalı 

severim filizkıran fırtınası''nı 

kırıp kanatmıyorsa sevincin türküsünü 

nerde benim baharım 

dalım yaprağım nerde 

gece çökmüş üstüne kerpiçsel yalnızlığın 

sanki kaplan pençesinde bir manda böğürtüsü 

ne kuş kalmış ne çiçek 

ne kırmızı ne yeşil 

sapsarı karanlıkta yerler bahar ölüsü', 'gün doğmadan başladı filizkıran fırtınası  evler yemen türküsü  sokaklar seferberlik  öyle bir gariplik ki  öyle bir tedirginlik  yaz başınd...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Korkmazgil']::text[], 8.5, '{"poet":"Hasan Hüseyin Korkmazgil","poet_slug":"hasan-huseyin-korkmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/filizkiran-firtinasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işıklarla Oynamayın', 'isiklarla-oynamayin-hasan-huseyin-korkmazgil-so4ld', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'başımı döndürüp bakamıyorum 

nasıl kaldı gerilerde onca yıl 

karanlık bir gömütlüğü düşte geçmiş gibiyim 

tatmadığım bir içkiyi bir akşam 

afrikasal bir törende içmiş gibiyim 

birdenbire kan yağmurlu bir bulut 

birdenbire kan kokulu bir duman 

şaşkınlıktan gemileri yakmış gibiyim 

ışıklarla oynamayın / dedim ben size 

yararı yok karanlıkta sürek avının 

dedim ben size 

yanlış kalemlere kayar elleri yazıcıların 

tutanaklar yanlış yazar 

dedim ben size 

karanlığı az kullanın / kirliler kokar birgün 

birgün yanar bu ışıklar sırıtır suratlarınız 

kirlilere sığınmayın / dedim ben size 

yararı yok oynaşmanın törensel aklıklarda 

kaçın kaçabilirseniz uzak sulara 

ışıklarla oynamayın / dedim ben size', 'başımı döndürüp bakamıyorum  nasıl kaldı gerilerde onca yıl  karanlık bir gömütlüğü düşte geçmiş gibiyim  tatmadığım bir içkiyi bir akşam  a...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Korkmazgil']::text[], 8.5, '{"poet":"Hasan Hüseyin Korkmazgil","poet_slug":"hasan-huseyin-korkmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/isiklarla-oynamayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal Kokusu', 'masal-kokusu-hasan-huseyin-korkmazgil-jh69k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben bu kapıları bir bir açarım açmasına ama kırarım 

Şehzadelerle gitti ölü devin altın anahtarları 

Masallara dönük yüzlerinizde o hiç eksilmeyen kaygu 

O donuk maviliği masal cennetlerinin 

Bırakın işte gözleriniz alın işte yumruklarınız 

ama siz aptalsınız aptalsınız 

Birgün masallaşırsam görün işte cüceliğimi 

Aktıkca büyüyen sulardı benim şarkılarda aradıklarım

Ben bu kapıları bir bir kırarım kırmasına ama siz korkaksınız 

Daha çocuk bile değilsiniz siz 

Devler çizersiniz altın sarayların kapılarına 

sonra durup ağlarsınız ağlarsınız 

Bu kan sizin kanınız , evet ama ya siz kimsiniz 

Neden böyle yorgunsunuz neden böyle aldatılmış 

Alıcıkuşlar döner ürpertili etlerınize 

Mumyaların gölgesinde piramitler dikersiniz 

Atı otu iti eti bırakıp gerçek saraylarda 

sürülerle kaçarsınız kaçarsınız 

Aktıkça büyüyen sulardı benim şarkılarda aradıklarım', 'Ben bu kapıları bir bir açarım açmasına ama kırarım  Şehzadelerle gitti ölü devin altın anahtarları  Masallara dönük yüzlerinizde o hiç eksi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Korkmazgil']::text[], 8.5, '{"poet":"Hasan Hüseyin Korkmazgil","poet_slug":"hasan-huseyin-korkmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/masal-kokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oranlama', 'oranlama-hasan-huseyin-korkmazgil-89yun', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir sen eksiktin sarıyıldız hoşgeldin 

Geç bakalım karşıma benimle içer misin 

Ağlar mısın içince burnuna çeker misin 

Gözyaşların yakabilir mi dudaklarımı 

Ama neden titriyorsun öyle sarıyıldız 

Bak ben su taşıyorum ince elekle 

İğne deliğinden dünyayı geçiriyorum 

Bak ben aklıma uyup sarıyıldız 

Durmadan aklımı saşırıyorum 

Sen beni kaçıncı binden tanıyorsun ki 

Hadi bana çelik mavisi bir gece getir 

Hadi dostlukları tek tek koparıp getir 

Alnımdan öp beni e mi, yitik sıcaklığımı getir 

Gençliğimi çılgınlığımı deli günlerimi getir 

Ne o sarıyıldız sen de mi ağlıyorsun', 'Bir sen eksiktin sarıyıldız hoşgeldin  Geç bakalım karşıma benimle içer misin  Ağlar mısın içince burnuna çeker misin  Gözyaşların yakabilir...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Korkmazgil']::text[], 8.5, '{"poet":"Hasan Hüseyin Korkmazgil","poet_slug":"hasan-huseyin-korkmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/oranlama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sabah', 'bu-sabah-fatih-i-lker-can-kgqr5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Selanik''te bir güneş

Bir ışıltı saçıldı

Altın saçlı bir çocuk

Hayata gözünü açtı

1881 yılında

Aydınlandı ufuklar

Selanik semalarından

Kalktı kara bulutlar

Atatürk''tü bu insan 

Eşsiz güçlü kumandan

Milletiyle beraber 

Çalıştı yorulmadan

Genç ihtiyar demeden

Güçlü bir ordu kurdu

Ordunun önünde de 

Düşmana siper oldu

Atatürk büyük insan

Güçlü çevik kumandan

Milletiyle beraber

Çalıştı yorulmadan.', 'Selanik''te bir güneş Bir ışıltı saçıldı Altın saçlı bir çocuk Hayata gözünü açtı 1881 yılında Aydınlandı ufuklar Selanik semalarından Kalktı...', ARRAY['Türk Edebiyatı','Şiir','Fatih İlker Can']::text[], 8.5, '{"poet":"Fatih İlker Can","poet_slug":"fatih-i-lker-can","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-sabah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçun Kuşlar', 'ucun-kuslar-hasan-huseyin-korkmazgil-0sdmm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'insandır suda akan yaprakta yeşil gülde kırmızı 

zorlu bir dal gibi eğleniriz de fırtınalarla 

ince bir sızı birdenbire kırar kollarımızı 

ve bir akşam kuşlar gibi elimizden uçup giden mutluluk 

bir sabah ebemkuşaklarının altından dörtnala gelir 

yaşayalım çocuklar 

her şey bizimdir 

bir giysi örtüsünde buldum ben bu yedi satırı 

bozkırda yüzükoyun bir hitit kasabası 

yedi satır yedi bülbül yavrusu 

vurmuşlar anasını da kalmış yavrusu 

bir sürgün şair yazmış vaktin birinde 

bir genç kız işlemiş onu örtüye 

yedi renk ipek iplik, yedi bülbül yavrusu 

ak örtüde yedi satır, gökkuşağı iğrisi 

bu yalnızlık bu sürgün, insan olmak acısı 

aldım yedi yavrucuğu koydum buraya 

yaşıyor mu bilmiyorum o sürgün şair 

yaşıyorsa bilsin diye o sürgün şair 

bir gün çıkıp gelsin diye o sürgün şair 

‘uçun kuşlar’ 

‘uçun kuşlar’ 

koydum adını 

bir giysi örtüsünde yedi bülbül yavrusu 

yedi satır, yedi renk, gökkuşağı iğrisi', 'insandır suda akan yaprakta yeşil gülde kırmızı  zorlu bir dal gibi eğleniriz de fırtınalarla  ince bir sızı birdenbire kırar kollarımızı  v...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Korkmazgil']::text[], 8.5, '{"poet":"Hasan Hüseyin Korkmazgil","poet_slug":"hasan-huseyin-korkmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ucun-kuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sana Anlattım', 'seni-sana-anlattim-fatih-i-stanbullu-tqjup', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Saçlarında güneş doğar...

Gözlerinde gece...

Yüzünde çiçekler açar...

Güvercinler konar ellerine...

Üzerine yıldızlar yağar geceden.

Her yanın bir parça taşır bahardan.

Kalbin daha temizdir yağan kardan.

Güzeliğin daha güzeldir çıkan gök kuşağından.

Kıskanır bülbüller sesini...

Çekemez çiçekler güzelliğini...

Deniz susar, güneş batmaz, gördümü gözlerini...

Rüzgar bile esmes incitmemek için teninini...

Kıskanır denizler seni,kıskanır dünya seni,

ben bile kendimden kıskanırım seni.', 'Saçlarında güneş doğar... Gözlerinde gece... Yüzünde çiçekler açar... Güvercinler konar ellerine... Üzerine yıldızlar yağar geceden. Her yan...', ARRAY['Türk Edebiyatı','Şiir','Fatih İstanbullu']::text[], 8.5, '{"poet":"Fatih İstanbullu","poet_slug":"fatih-i-stanbullu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-sana-anlattim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Ses Yükselirdi Kubbeye (TUNA ya AĞIT)', 'ayni-ses-yukselirdi-kubbeye-tuna-ya-agit-i-lhan-yuksel-yojdg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gidip maziye gezindiğimde

Baktım şüheda secdede uyur 

Kılıç sesiyle başlayıp yerde 

Tekbir getirip göklere duyurur 

Gökten ceddime sancak olmaya 

Gördüm hilali önüne düşmüş 

Gidip tarihe mühür vurmaya 

Bir yürüyüşki Allaha Yürüyüş 

Ne günlerdi Kızılırmak Tuna 

Diyar diyar gezer bize akardı 

Bir yerde buluştuğun unutma 

Nil diye Fırat kardeşin vardı 

Hicazdan başlayıp Budine dek 

Aynı ses yükselirdi kubbeye 

Belki bin yıl nesiller gerek 

Tarihi halka halka dizmeye 

Tunam garip misin bu yollarda 

Kartal diyar diyar hür uçardı 

Doğan bebekler akıncılarda 

Kılıç sesi nal sesi duyardı 

Yürü ki Tunam tarih yazılsın 

Değişmez bu neslin kan aynı kan 

Nakış vur taşa mühür kazılsın 

Geçmişe varıp atiye uzan 

Şehit askerin yerine asker 

Doğursun analar Tuna önünde 

Akıncı doğsun doğsun serasker 

Gökte hilalim görüldüğünde 

Yık garabeti silkinip bir an 

Çarpıp çınla bu dağdan o dağa 

Şahlan Tunum bir daha şahlan 

Tekbir sesini al git uzağa', 'Gidip maziye gezindiğimde Baktım şüheda secdede uyur  Kılıç sesiyle başlayıp yerde  Tekbir getirip göklere duyurur  Gökten ceddime sancak ol...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ayni-ses-yukselirdi-kubbeye-tuna-ya-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önemli Not', 'onemli-not-ali-kemal-6y1zx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yalnızın bütün halleri vardı bende

şimdi de özleminkileri öğreniyorum...

sensizkende seviyorum seni

sevdikçe coşkulanıyor yüreğim

daha çok kafa tutuyorum hayata...

                        

                     (18 ocak 2000-izmir)', 'yalnızın bütün halleri vardı bende şimdi de özleminkileri öğreniyorum... sensizkende seviyorum seni sevdikçe coşkulanıyor yüreğim daha çok k...', ARRAY['Türk Edebiyatı','Şiir','Ali Kemal']::text[], 8.5, '{"poet":"Ali Kemal","poet_slug":"ali-kemal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/onemli-not-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam', 'sevdam-abdurrahman-firat-yt4n6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne kalem dayanır,ne katip yazar

Elvanlı renk giyimiş şu karşı dağlar.

Bu dünya  kimseye olmaz yurdu yar

Arayıp bulmalı derde bir çare

Hasret oku derin açtı yaramı 

Artık göç eyledi gönül kervanı

Tecelli eyledi sevda yarası

Yaralı bu gönül sözden almadı

İstanbuldan gelmiş,bu gözler gördü

Güldende güzeldi o masum yüzü

İki günde tıtıldu almadan sözü

Tecessüs eylemedi kalbimin özü

( 21.04.95 )

( Yukaradan aşşagı ismine işaf ettiğim kişinin adı ve soyadı mevcut )', 'Ne kalem dayanır,ne katip yazar Elvanlı renk giyimiş şu karşı dağlar. Bu dünya  kimseye olmaz yurdu yar Arayıp bulmalı derde bir çare Hasret...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Fırat']::text[], 8.5, '{"poet":"Abdurrahman Fırat","poet_slug":"abdurrahman-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakut Gözlüye', 'yakut-gozluye-abdurrahman-firat-9bgfg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arzın güzelini görmez olaydım

Yakuttan  gözlerine bakmaz olaydım

Şeytana uyupta sevmez olaydım

Esiriyim aşkının olmaz olaydım

( 07.10.97 )', 'Arzın güzelini görmez olaydım Yakuttan  gözlerine bakmaz olaydım Şeytana uyupta sevmez olaydım Esiriyim aşkının olmaz olaydım ( 07.10.97 )...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Fırat']::text[], 8.5, '{"poet":"Abdurrahman Fırat","poet_slug":"abdurrahman-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yakut-gozluye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzın Meleğine', 'arzin-melegine-abdurrahman-firat-5heua', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tuba dallarında solmayan çiçeksiniz

Ufkun ötesinde batmayan güneşsiniz

Bulunması çok zor bedelsiz cevhersiniz

Arzın meleklerinden bir melekte sizsiniz', 'Tuba dallarında solmayan çiçeksiniz Ufkun ötesinde batmayan güneşsiniz Bulunması çok zor bedelsiz cevhersiniz Arzın meleklerinden bir melekt...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Fırat']::text[], 8.5, '{"poet":"Abdurrahman Fırat","poet_slug":"abdurrahman-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/arzin-melegine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığım Sana', 'asigim-sana-abdurrahman-firat-mcb7v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşığım ben sana sensiz olamam ben 

Yıllar gecsede seni unutamam ben

Feşeyledin kalbimi sensiz olamam ben

Ey güzel ister gel, ister öl de bana 

Razıyım her halime,yeterki kavuşayım sana', 'Aşığım ben sana sensiz olamam ben  Yıllar gecsede seni unutamam ben Feşeyledin kalbimi sensiz olamam ben Ey güzel ister gel, ister öl de ban...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Fırat']::text[], 8.5, '{"poet":"Abdurrahman Fırat","poet_slug":"abdurrahman-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/asigim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ela Gözlüye', 'ela-gozluye-abdurrahman-firat-j20e7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ela gözlerine bakmaz olaydım

Savrulan saçlarını görmez olaydım

Rezil oldum millete  olmaz olaydım

Aşkının yüzünden yanmaz olaydım', 'Ela gözlerine bakmaz olaydım Savrulan saçlarını görmez olaydım Rezil oldum millete  olmaz olaydım Aşkının yüzünden yanmaz olaydım...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Fırat']::text[], 8.5, '{"poet":"Abdurrahman Fırat","poet_slug":"abdurrahman-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ela-gozluye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-abdurrahman-firat-d2kgw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Evvala gözlerin sonra gülüşlerin

Sarhoş ediyor beni o bakışların

Razıyım ateşlere yansın bu kalbim

Aşkının şarabıyla dolsun  bu kalbim', 'Evvala gözlerin sonra gülüşlerin Sarhoş ediyor beni o bakışların Razıyım ateşlere yansın bu kalbim Aşkının şarabıyla dolsun  bu kalbim...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Fırat']::text[], 8.5, '{"poet":"Abdurrahman Fırat","poet_slug":"abdurrahman-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kül', 'kul-cemre-cerem-6h3ix', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'uykularına 

kapkara bir güz taşır kuşlar

bir karanlığı örter gibi ellerin

apansız kapanıverir yüzüne

gözlerinde uzak suskunluklardan

yağmurdur çiseleyen korkularıyla

umutlarını silip süpüren yağmur...', 'uykularına  kapkara bir güz taşır kuşlar bir karanlığı örter gibi ellerin apansız kapanıverir yüzüne gözlerinde uzak suskunluklardan yağmurd...', ARRAY['Türk Edebiyatı','Şiir','Cemre Cerem']::text[], 8.5, '{"poet":"Cemre Cerem","poet_slug":"cemre-cerem","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balkondan Düşme Denemeleri', 'balkondan-dusme-denemeleri-cemre-cerem-fr131', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'eksildi korkuluklarda 

elveda eksenli elöpenler

9.

ah, uyurken, yere düşen yarasa,

açınca kötürüm melek kanatlarını;

ellerin hep böyle mi paramparça

ellerimize iniyorsun,

havaya çizdiğin telaşlı resimlerle?

6.

gün ortasında ters doğan çocuk,

dokunuyorum gizlendiğin resimlere;

içine çiçekler sarılı

yüzü yırtık bir kadın,

elden ele gezdiriyor:

sırnaşık bir baykuşu.

3.

dokunuyorum gizlendiğin resimlere;

bir gemi geçiyor boğazımdan

bıçağı boynunda bir yalnızlık

cambazların kışkırtan bilmeceleri içinde

vecde gelen bir duahan

korku ile bağırıp çağırıyor:

kuşluk vakti ölümler

çiçeklerden uzak olmalı,

uzak olmalı!', 'eksildi korkuluklarda  elveda eksenli elöpenler 9. ah, uyurken, yere düşen yarasa, açınca kötürüm melek kanatlarını; ellerin hep böyle mi pa...', ARRAY['Türk Edebiyatı','Şiir','Cemre Cerem']::text[], 8.5, '{"poet":"Cemre Cerem","poet_slug":"cemre-cerem","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/balkondan-dusme-denemeleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karagözlü Kız', 'karagozlu-kiz-hakan-kivanc-uoccr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sırf senin için 

sırf sen ordasındiye

antalyayı özledim dün gece

dün gece kuş olmaı istedim

sırf seni koklamaya toroslarla beraber

uçmak istedim

sırf sen 

sırfsana

ulaşmak için', 'sırf senin için  sırf sen ordasındiye antalyayı özledim dün gece dün gece kuş olmaı istedim sırf seni koklamaya toroslarla beraber uçmak ist...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kıvanç']::text[], 8.5, '{"poet":"Hakan Kıvanç","poet_slug":"hakan-kivanc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/karagozlu-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmirname', 'i-zmirname-suat-taser-e3zyi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bi bulutun altında durdum

olmayacak hayaller kurdum izmirde kordonda

kız oturmuş roman okuyordu 

sevda üstüne hemde

adam sende yaşamak günah işlemeye değmez bu şehirde

hamal hamdide sevdi

gültepede evinde

..............', 'bi bulutun altında durdum olmayacak hayaller kurdum izmirde kordonda kız oturmuş roman okuyordu  sevda üstüne hemde adam sende yaşamak günah...', ARRAY['Türk Edebiyatı','Şiir','Suat Taşer']::text[], 8.5, '{"poet":"Suat Taşer","poet_slug":"suat-taser","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/izmirname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Kalbin Haykırışı', 'kirik-kalbin-haykirisi-mustafa-ozgur-simsek-so9s6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'uykularım karısık

hayatım japonyada eyfel kulesi

öyküler devsiz hiç çekilmez

peki hayat sensiz?

mum kokulu taslar biriktirdim sana

uykusuz aksamlar hatıra defterimde...

bide...

neskafeli bardaklar

bozuk lehceli birseyler söyleyen kürt kadını

belli dertli 

belli cok cekmiş cok cektirilmiş

belli hayat onada arka sayfasından şans defterini

kırık vazolar vermiş solmus çiçekler için

olmamıs asklar vermiş yaralı kalbine

Ben aksam olmaktayım istanbula hüzün salmaktayım

bira kapaklarına aşıgım 

kum tanelerinde saklı aşkım

korkmuyorum hayattan 

ama hayattayım ya korkuyorum korkum ondan

herhangi bir gezegendeki 

herhangi biruzay mekiginin 

herhangi bir dugmesiyim ''kırmızı''

üstüme bassalar patlayacagım

cihanı yok edecegim...

ebabil kusunun amniyon kesesiyim

bereket tanrısının bekaret kemeri

aşkı ben dagıtırım eros''la bir

spartacus''ün can yoldaşıyım

aşıkların arasındaki elektrigim şimdi

en cok bunu sevdim gerilim ikiyuzyirmi

kız oglana bakıyor

kuslar bir hoş kokuyor ılık bir meltemken izmir''de.', 'uykularım karısık hayatım japonyada eyfel kulesi öyküler devsiz hiç çekilmez peki hayat sensiz? mum kokulu taslar biriktirdim sana uykusuz a...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özgür Şimşek']::text[], 8.5, '{"poet":"Mustafa Özgür Şimşek","poet_slug":"mustafa-ozgur-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kirik-kalbin-haykirisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağıyor Yağmur', 'yagiyor-yagmur-mustafa-ozgur-simsek-rd5w4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yagmur yagıyor 

gozlerım ıslak saclarım yuregım ıslak 

ıslak ıslak yuruyorum kaldırımlarda 

yıldızlara basıyorum 

aya dokunuyorum 

yagmur yagdıya... 

ıcım eksılıyor yuregım cosuyor 

yagmurla yarıs edıyor damlalarım 

usuyorum... 

derın bır nefes alıyorum 

derın bır off 

sana dokunuyorum azot ve amonyak 

kokuyor gok 

sana dokunuyorum 

karsımdasın,gozlerımde 

ben agladım ya... 

yuregım buyuyor sınapslarım artıyor 

simsekle yarıs ediyor sinirlerim 

titriyorum.. 

nasılda topluyor sımdı 

damlaları bır bır 

nasılda zahmetsızce toprak? 

bulutla toprak sevisiyor 

ilk biten hep yagmur oluyor.. 

yagmur bıttı ıste 

bulutta pekı ya toprak? 

pekı ya ben? 

goz yaslarım tukenmıyor parafınlerım 

sevım tukenmıyor sınapslarım 

hucrelerımde olusan 

pekı ya ben? 

seni seviyorum 

seni seviyorum sevgilim 

aglıyorum aht edıyorum 

vah edıyorum benımle evlenırmısın??', 'yagmur yagıyor  gozlerım ıslak saclarım yuregım ıslak  ıslak ıslak yuruyorum kaldırımlarda  yıldızlara basıyorum  aya dokunuyorum  yagmur ya...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özgür Şimşek']::text[], 8.5, '{"poet":"Mustafa Özgür Şimşek","poet_slug":"mustafa-ozgur-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yagiyor-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Made In U.S.A.', 'made-in-u-s-a-refik-durbas-jnqkt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eski karanlık. Sarı toprak. Hey abidin

Yaşlı kubbe. Ağaçlar

- Yılların yüzüme aşıladığı rüzgar

Mübarek su

Amasya''da elmanın alınterini biçen kim

Zonguldak''ta kömürün alınterini biçen kim

Zeytinin, üzümün, petrolün alınterini

Devrimci kardeşlerimin kanını biçen kim

Kim ışıldıyor hey abidin bu sabah

şanlı mavzerde, aydınlık kanda.', 'Eski karanlık. Sarı toprak. Hey abidin Yaşlı kubbe. Ağaçlar - Yılların yüzüme aşıladığı rüzgar Mübarek su Amasya''da elmanın alınterini biçen...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/made-in-u-s-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başına Tanyeli', 'bir-basina-tanyeli-refik-durbas-i99co', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen ki ne hüzünler yaşadın bir başına

erisin artık yüreğinde çırpınan tanyeli

ne belaymış deme zındanda kararmak

acı da aynı imbikten çekiliyor, umut da şimdi', 'Sen ki ne hüzünler yaşadın bir başına erisin artık yüreğinde çırpınan tanyeli ne belaymış deme zındanda kararmak acı da aynı imbikten çekili...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-basina-tanyeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resimli Küçük İlanlar''dan', 'resimli-kucuk-i-lanlar-dan-refik-durbas-m4ahv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Acının çeyizini işleyen kızlarla mektuplaşacağım

şiiri çalınmış, emeği yetim, aşkı ıssız olan yazmasın', 'Acının çeyizini işleyen kızlarla mektuplaşacağım şiiri çalınmış, emeği yetim, aşkı ıssız olan yazmasın...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/resimli-kucuk-ilanlar-dan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renklerim', 'renklerim-oruc-aruoba-41kms', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aklaşan grilikte duruyorum -

yeşilleşen mavilik

kararan saydamlık

azalan tirşe:

o mor

hiç olmadı

mı? 

O tek renk

bulunmadı

mı? 

Kızıltılı

kahve

rengi

*

Siyah

Beyaz.

Ah,

az -

hiç olmadım

mı? 

Bulunamadım

mı?', 'Aklaşan grilikte duruyorum - yeşilleşen mavilik kararan saydamlık azalan tirşe: o mor hiç olmadı mı?  O tek renk bulunmadı mı?  Kızıltılı ka...', ARRAY['Türk Edebiyatı','Şiir','Oruç Aruoba']::text[], 8.5, '{"poet":"Oruç Aruoba","poet_slug":"oruc-aruoba","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/renklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mumun', 'mumun-oruc-aruoba-k6rkj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bütün ışıklara karşı geldi

  yaktığın bu mum

Neyin nereden nereye geçişiydi

  aktığım o mum

Bir aydınlık geçit, bir kedi

  sakladığım o kurum

Zamanın ötesinde bir şimdi

  sakındığım bu durum', 'Bütün ışıklara karşı geldi   yaktığın bu mum Neyin nereden nereye geçişiydi   aktığım o mum Bir aydınlık geçit, bir kedi   sakladığım o kuru...', ARRAY['Türk Edebiyatı','Şiir','Oruç Aruoba']::text[], 8.5, '{"poet":"Oruç Aruoba","poet_slug":"oruc-aruoba","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mumun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otuz Üç Kurşun', 'otuz-uc-kursun-ahmed-arif-ndpbd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu dağ Mengene dağıdır

Tanyeri atanda Van’da

Bu dağ Nemrut yavrusudur

Tanyeri atanda Nemruda karşı

Bir yanın çığ tutar, Kafkas ufkudur

Bir yanın seccade Acem mülküdür

Doruklarda buzulların salkımı

Firarı güvercinler su başlarında

Ve karaca sürüsü,

Keklik takımı…

Yiğitlik inkâr gelinmez

Tek’e – tek döğüşte yenilmediler

Bin yıllardan bu yan, bura uşağı

Gel haberi nerden verek

Turna sürüsü değil bu

Gökte yıldız burcu değil

Otuzüç kurşunlu yürek

Otuzüç kan pınarı

Akmaz,

Göl olmuş bu dağda…



2.

Yokuşun dibinden bir tavşan kalktı

Sırtı alaçakır

Karnı sütbeyaz

Garip, ikicanlı, bir dağ tavşanı

Yüreği ağzında öyle zavallı

Tövbeye getirir insanı

Tenhaydı, tenhaydı vakitler

Kusursuz, çırılçıplak bir şafaktı

Baktı otuzüçten biri

Karnında açlığın ağır boşluğu

Saç sakal bir karış

Yakasında bit,

Baktı kolları vurulu,

Cehennem yürekli bir yiğit,

Bir garip tavşana,

Bir gerilere.

Düştü nazlı filintası aklına,

Yastığı altında küsmüş,

Düştü, Harran ovasından getirdiği tay

Perçemi mavi boncuklu,

Alnında akıtma

Üç topuğu ak,

Ekşini hovarda, kıvrak,

Doru, seglâvi kısrağı.

Nasıl uçmuşlardı Hozat önünde! 

Şimdi, böyle çaresiz ve bağlı,

Böyle arkasında bir soğuk namlu

Bulunmayaydı,

Sığınabilirdi yüceltilere…

Bu dağlar, kardeş dağlar, kadrini bilir,

Evvel Allah bu eller utandırmaz adamı,

Yanan cigaranın külünü,

Güneşlerde çatal kıvılcımlanan

Engereğin dilini,

İlk atımda uçuran

Usta elleri…

Bu gözler, bir kere bile faka basmadı

Çığ bekleyen boğazların kıyametini

Karlı, yumuşacık hıyanetini

Uçurumların,

Önceden bilen gözleri…

Çaresiz

Vurulacaktı,

Buyruk kesindi,

Gayrı gözlerini kör sürüngenler

Yüreğini leş kuşları yesindi…

3.

Vurulmuşum

Dağların kuytuluk bir boğazında

Vakitlerden bir sabah namazında

Yatarım

Kanlı, upuzun…

Vurulmuşum

Düşüm, gecelerden kara

Bir hayra yoranım çıkmaz

Canım alırlar ecelsiz

Sığdıramam kitaplara

Şifre buyurmuş bir paşa

Vurulmuşum hiç sorgusuz, yargısız

Kirvem, hallarımı aynı böyle yaz

Rivayet sanılır belki

Gül memeler değil

Domdom kurşunu

Paramparça ağzımdaki…

4.

Ölüm buyruğunu uyguladılar,

Mavi dağ dumanını

ve uyur – uyanık seher yelini

Kanlara buladılar.

Sonra oracıkta tüfek çattılar

Koynumuzu usul – usul yoldayıp

Aradılar,

Didik – didik ettiler

Kirmanşah dokuması al kuşağımı

Tespihimi, tabakamı alıp gittiler

Hepsi de armağandı Acemelinden…

Kirveyiz, kardeşiz, kanla bağlıyız

Karşıyaka köyleri, obalarıyla

Kız alıp vermişiz yüzyıllar boyu,

Komşuyuz yaka yakaya

Birbirine karışır tavuklarımız

Bilmezlikten değil,

Fıkaralıktan

Pasaporta ısınmamış içimiz

Budur katlimize sebep suçumuz,

Gayrı eşkiyaya çıkar adımız

Kaçakçıya

Soyguncuya

Hayına…

Kirvem, hallarımı aynı böyle yaz

Rivayet sanılır belki

Gül memeler değil

Domdom kurşunu

Paramparça ağzımdaki…

5.

Vurun ulan,

Vurun,

Ben kolay ölmem.

Ocakta küllenmiş közüm,

Karnımda sözüm var

Haldan bilene,

Babam gözlerini verdi Urfa önünde

Üç de kardaşını

Üç nazlı selvi,

Ömrüne doymamış üç dağ parçası.

Burçlardan, tepelerden, minarelerden

Kirve, hısım, dağların çocukları

Fransız Kuşatmasına karşı koyanda

Bıyıkları yeni terlemiş daha

Benim küçük dayım Nazif

Yakışıklı,

Hafif

İyi süvari

Vurun kardaş demiş

Namus günüdür

Ve şaha kaldırmış atını.

Kirvem hallarımı aynı böyle yaz

Rivayet sanılır belki

Gül memeler değil

Domdom kurşunu

Paramparça ağzımdaki…', 'Bu dağ Mengene dağıdır Tanyeri atanda Van’da Bu dağ Nemrut yavrusudur Tanyeri atanda Nemruda karşı Bir yanın çığ tutar, Kafkas ufkudur Bir y...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Arif']::text[], 8.5, '{"poet":"Ahmed Arif","poet_slug":"ahmed-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":142,"source_url":"https://www.antoloji.com/otuz-uc-kursun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretinden Prangalar Eskittim', 'hasretinden-prangalar-eskittim-ahmed-arif-vnbkx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni, anlatabilmek seni.

İyi çocuklara, kahramanlara,

Seni, anlatabilmek seni,

Namussuza, haldan bilmez,

Kahpe yalana.

Ard-arda kaç zemheri,

Kurt uyur, kuş uyur, zindan uyurdu.

Dışarda gürül-gürül akan bir dünya...

Bir ben uyumadım,

Kaç leylim bahar,

Hasretinden prangalar eskittim.

Saçlarına kan gülleri takayım,

Bir o yana,

Bir bu yana...

Seni bağırabilsem seni,

Dipsiz kuyulara,

Akan yıldıza.

Bir kibrit çöpüne varana,

Okyanusun en ıssız dalgasına

Düşmüş bir kibrit çöpüne.

Yitirmiş tılsımını ilk sevmelerin,

Yitirmiş öpücükleri,

Payı yok, apansız inen akşamdan,

Bir kadeh, bir cigara, dalıp gidene,

Seni, anlatabilsem seni...

Yokluğun, cehennemin öbür adıdır

Üşüyorum, kapama gözlerini...', 'Seni, anlatabilmek seni. İyi çocuklara, kahramanlara, Seni, anlatabilmek seni, Namussuza, haldan bilmez, Kahpe yalana. Ard-arda kaç zemheri,...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Arif']::text[], 8.5, '{"poet":"Ahmed Arif","poet_slug":"ahmed-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hasretinden-prangalar-eskittim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temmuz Sıcağı', 'temmuz-sicagi-ahmet-emin-atasoy-8chiq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güneş, bir çılgın

Gök, tımarhane

Çatlayan toprak,

Pişmiş kestane

Yükselen cemre,

Ejderha müşiş;

Düşen taneler,

Birer çürük diş.

Boğucu bir ruh

Kızgın havada,

Yanıyor yavru

Kuşlar yuvada.

Irmak tıpkı bir

Körlenmiş pınar,

Ölünce çirkin

Güzel balıklar.

Bayır dilenci,

Rüzgara muhtaç;

Gölgesinden nem

Umuyor ağaç.

Kabulü çok zor

Bunu bir aklın:

Gök tımarhane,

Güneşse çılgın.', 'Güneş, bir çılgın Gök, tımarhane Çatlayan toprak, Pişmiş kestane Yükselen cemre, Ejderha müşiş; Düşen taneler, Birer çürük diş. Boğucu bir r...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Emin Atasoy']::text[], 8.5, '{"poet":"Ahmet Emin Atasoy","poet_slug":"ahmet-emin-atasoy","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/temmuz-sicagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Saman Hatıra Defteri', 'sari-saman-hatira-defteri-kucuk-i-skender-4ax60', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ihsan y.''e

ısrarlı bir çocuk gömleği var bu gece üstümde

siyah, cepsiz, buruşuk ve kirli

okuldan mı kaçtım, evden mi, söyleyemem

titrerdi ellerim uzanıp düzeltirken yüzünü

dudakların Bastille''di, yanılmıyorum,

gözlerin, en çok o körkütük gözlerin devrilir ve

uzun uzun susardı, gözlerine su veremezdim,

tek bir imge taşımazdı birbirimize duyduğumuz his

şiirsizdik, bunu biliyorduk, bunun için ağlamıştık,

bakardık karşı karşıya geçip, hatırlıyor musun,

yalnızca bakardık!

dipsiz, yalansız, ölüme davet eden bir bakmaydı bu

hepsi hepsi aşk!

senyör aşk, mösyö aşk, mister aşk, bay aşk!

şiirsizdik, bunu biliyorduk, bunun için ağlamıştık

bunun için terasa çıkıp aşağı bir gül atmıştık

bunun için rıhtıma inip denize bir gül atmıştık

çaresizdik, sevda biraz da soygundur, işte

sevda biraz yakayı ele vermektir, mahkemelere düşmektir,

ben masumum diyebilmektir biraz da sevda,

bunu biliyorduk, bunun için ağlamıştık,

uyanır uyanmaz başlıyorduk ağlamaya

sarılıp sarılıp ağlıyorduk

yorulup uyuyana kadar ağlıyorduk sevgilim

dokunuyorduk su deyip suya deyip su içen kelebekler gibi

susuz kalan gözlerimiz gitgide ağır ağır soluyordu

o gül, gitgide ağır ağır soluyordu rüzgarla

tenlerimizde tenlerimize ait birşeyler dokuyorduk

oysa ısrarlı bir çocuk gömleği var bu gece üstümde

siyah, cepsiz, buruşuk ve kirli

dayak mı yedim, dayak mı attım, söyleyemem

senden bana seken bir yürek

ki yürekler sarı samandan hatıra defterleridir

senden bana yansıyan bir ışık

ki ışıklar elele tutuşup geri çekilirler 

senden bana damlayan bir çiy tanesi

ki çiy taneleri ancak biri öldü mü dağılırlar sessizce

komşularım senin hakkında konuşmuyorlar

başlar öne eğik, dudaklar bükük, omuzlar çökmüş

resmini indirdim duvardan, adını unuttum ne tuhaf!

karakolda kaydın yok! hastanelerde yok!

mezarlıklarda yok!                         gittin!.

bir gecede hazırlanıp bir gecede gittin!

bana bir gece bırakıp yanına bir gece alıp da gittin!

kırmızı çoraplarından birinin teki kalmış!

mor çoraplarımdan birinin tekini götürmüşsün!

ben de mi gitmeliydim

yürüdüm! bir kentten bir başka kente yürüdüm!

gittin! inanılmaz!

sana abi diyecektim, dedirtmedin

sana oğlum diyecektim, dedirtmedin

bunun için ağlamıştık, komşular bizi şikayet etmişti

eve gelen ziyaretçiler üzülmüştü

bize gül getirmişlerdi

bize üzüm getirmişlerdi

bize aşk getirmişlerdi

bizi kendimize getirmişlerdi, bunu biliyorduk

bunun için ağlamıştık

tuvalette bıraktığın atleti buldum!

kokladım! köpekler gibi kokladım!

yola çıkıp kokunu aradım izini bulurum diye!

gittin! inanılmaz!

senden bana seken bir yürek

ki yürekler zaman zaman dengesini kaybeder

senden bana yansıyan bir ışık

ki ışıklar küstüler mi bir daha barışmazlar

senden bana damlayan bir çiy tanesi

ki çiy taneleri daima acıya müdahele ederler

oysa ısrarlı bir çocuk gömleği var bu gece üstümde

siyah, cepsiz, buruşuk ve kirli

senin bu gömlek

senin bu pantolon

artık yalnızca eşyaların

artık yalnızca eşyalarını sevebilirim

artık yalnızca eşyalarınla ağlıyoruz

en fazla seni özlüyoruz

bunu komşularım da öğrendi

ziyaretçiler de öğrendi

bir sen..

bütün aşk şarkılarını söylerdin

bütün aşk şarkıları sana yazılırdı

fakat artık sen yoksun

ölüm koynuma sokulsun, beni soksun,

zehirle beni ey peygamberim!

tanrısıyla sevişen peygamberlere kitap iner

bu gece üstümde ısrarlı bir çocuk gömleği var

galiba düğmelerini çözeceğim!', 'ihsan y.''e ısrarlı bir çocuk gömleği var bu gece üstümde siyah, cepsiz, buruşuk ve kirli okuldan mı kaçtım, evden mi, söyleyemem titrerdi el...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/sari-saman-hatira-defteri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafatası', 'kafatasi-sunay-akin-7mezj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yurdundan çok uzaklarda

ölmüş bir askerin kafatası

kendisini bulan

çocukların ellerinde

hiç bilmediği oyunlara

alet oluyordu

ikinci defa.', 'Yurdundan çok uzaklarda ölmüş bir askerin kafatası kendisini bulan çocukların ellerinde hiç bilmediği oyunlara alet oluyordu ikinci defa....', ARRAY['Türk Edebiyatı','Şiir','Sunay Akın']::text[], 8.5, '{"poet":"Sunay Akın","poet_slug":"sunay-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kafatasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Olan Şiirlerim', 'sensiz-olan-siirlerim-vakkas-arslan-zscjl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gece olurken şakırdar suskun olan  dilim

Dirilir kalem tutan ,nasırlı titrek ellerim

Sonsuzluğa uzanır, ağlayan ahu gözlerim

Mutluluğu anlatır, mutlu olmayan şiirlerim

Sıcaklığını arar, yalnızlıkta üşüyen ellerim

Ruhuna mahkum olmayı her zaman isterim

Gizemli aşkınla  her zaman ahu efgan ederim

Sensizliği anlatır sensiz olan şiirlerim

Büyümeye devam edecek devasa özlemlerim

Tek dileğim boşa gitmesin bütün emeklerim

Sanma ki arkana bakmadan çekip giderim

Yalnızlığı anlatır yalnız olan şiirlerim', 'Gece olurken şakırdar suskun olan  dilim Dirilir kalem tutan ,nasırlı titrek ellerim Sonsuzluğa uzanır, ağlayan ahu gözlerim Mutluluğu anlat...', ARRAY['Türk Edebiyatı','Şiir','Vakkas Arslan']::text[], 8.5, '{"poet":"Vakkas Arslan","poet_slug":"vakkas-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-olan-siirlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhul Dost', 'mechul-dost-vakkas-arslan-wurjw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostluğu öğreniyordum sonsuza doğru 

Dostluğu seninle buldum ey vefalı  dost

İradeler kayboluyordu bilinmeyen yöne doğru

Bütün dostlar sahipsiz kalıyordu ey dost

Nice dost kervanlarını dolaştım yıllarca

Bana kendi olamadılar yalan çıktılar ey dost

En karanlık anlarda aradım seni günlerce

Bana seni yaşattıramadılar hiç oldular ey dost

İradem hep seni istiyordu bunu perçinliyordu

Daralıyordu içim sen olmayınca ey dost

Gidemiyordum sensiz bir yere kalbim inliyordu

Mezarım bile güzel olurdu sen olunca ey dost', 'Dostluğu öğreniyordum sonsuza doğru  Dostluğu seninle buldum ey vefalı  dost İradeler kayboluyordu bilinmeyen yöne doğru Bütün dostlar sahip...', ARRAY['Türk Edebiyatı','Şiir','Vakkas Arslan']::text[], 8.5, '{"poet":"Vakkas Arslan","poet_slug":"vakkas-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mechul-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Benim Sevgilimdi', 'yagmur-benim-sevgilimdi-i-dris-elibol-wd8vn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kiraz ağacına tırmanırken çıkardığım

Çorabım ve ayakkabım kadar

Yüreğimi ve aklımı

Senden gayrısına çıkardım geldim!

Ay gecesini aradı

Ben seni aradım

Kurutulmuş bitkilerin dumanıyla

Ciğerlerimi çürüttüm

Kurşun rengi gecelerde

Damarlarımı kuruttum

Hicranın ipekli kozasıyla

Saçlarımı ağarttım geldim

Ben sana aşkı,

Senden gayrısına çıkardım geldim!

Düşmandı gökyüzü,

Düşmandı güneş

Ay gecesini karşıladı ayakta

Güneşi bir köşeye attılar ama

Yıldızlar bana yetmedi

Yüreğim yalınayaktı

Cehennemin narına bastım geldim

Ben sana aşkı senden gayrısına çıkardım geldim!

Bırak vursun yüzüme yağmur

Toprağa düşememenin acısını çıkarsın

Yine sana geldiğim gibi döneceksem

Kader diyeceksem;

İtiraf edeceğim ve öğreneceksin:

Yağmur benim sevgilimdi

Ben ona aşkı,

Ondan gayrısına çıkarıp gelmiştim!', 'Kiraz ağacına tırmanırken çıkardığım Çorabım ve ayakkabım kadar Yüreğimi ve aklımı Senden gayrısına çıkardım geldim! Ay gecesini aradı Ben s...', ARRAY['Türk Edebiyatı','Şiir','İdris Elibol']::text[], 8.5, '{"poet":"İdris Elibol","poet_slug":"i-dris-elibol","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yagmur-benim-sevgilimdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelmedin', 'sen-gelmedin-i-dris-elibol-y5c8k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbimin buluşma yerine gelmediğin gün,

Birer birer kırıldı umut aynalarım!

Analar benden öğrendi

Bağırlarına taş basmayı

Boğazımda sigara öksürükleri

Kahroldum da,

Sen gelmedin!

Uzandım siyah asfaltına yolların

Kan verdim üşüyen kaldırımlara

Karar verdim artık benim için

Yaşamak da bir, ölmekte

Rüzgar geldi üstüme,

Kar geldi de

Sen gelmedin!

Ezilmişliğimle

Yenilmişliğimle,

Ve iliklerime işlediğim şairliğimle

Sana şiirler yazdım da

Sen duymadın!', 'Kalbimin buluşma yerine gelmediğin gün, Birer birer kırıldı umut aynalarım! Analar benden öğrendi Bağırlarına taş basmayı Boğazımda sigara ö...', ARRAY['Türk Edebiyatı','Şiir','İdris Elibol']::text[], 8.5, '{"poet":"İdris Elibol","poet_slug":"i-dris-elibol","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sen-gelmedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesaj', 'mesaj-ozdemir-asaf-37kqx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'MESAJ

Ölebilirim bu genç yaşımda, 

En güzel şiirlerimi söylemeden götürebilirim.

Şimdi kavakyelleri esiyorken başımda, 

Sevgilim, 

Seni bir akşam-üstü düşündürebilirim.', 'MESAJ Ölebilirim bu genç yaşımda,  En güzel şiirlerimi söylemeden götürebilirim. Şimdi kavakyelleri esiyorken başımda,  Sevgilim,  Seni bir ...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mesaj-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duvara Astığım', 'duvara-astigim-ozdemir-asaf-uzcwz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'DUVARA ASTIĞIM

Ölünceye kadar seni bekleyecekmiş,

Sersem.

Ben seni beklerken ölmem ki..

Beklersem.', 'DUVARA ASTIĞIM Ölünceye kadar seni bekleyecekmiş, Sersem. Ben seni beklerken ölmem ki.. Beklersem....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/duvara-astigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yön', 'yon-ozdemir-asaf-6odjj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'YÖN

Sen bana bakma,

Ben senin  baktığın yönde olurum.', 'YÖN Sen bana bakma, Ben senin  baktığın yönde olurum....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/yon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tentation', 'tentation-ozdemir-asaf-x0icw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'TENTATION

Bana yaşadığın şehrin kapılarını aç..

Sana deyeceklerim söylemekle bitmez

Yıllardır yaşamamdan çaldığım zamanlar

Adına düğümlendi.

Bana yaşadığın şehrin kapılarını aç..

Başka şehirleri özleyelim orada seninle.

Bu evler, bu sokaklar, bu meydanlar

İkimize yetmez.', 'TENTATION Bana yaşadığın şehrin kapılarını aç.. Sana deyeceklerim söylemekle bitmez Yıllardır yaşamamdan çaldığım zamanlar Adına düğümlendi....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tentation-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlam', 'anlam-ozdemir-asaf-r0rmx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen bana

Sen desen de, demesen de olur.

Ama ben sana sen deyeceğim.

Düşün dur.', 'Sen bana Sen desen de, demesen de olur. Ama ben sana sen deyeceğim. Düşün dur....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/anlam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlış Anladın', 'yanlis-anladin-i-dris-elibol-06tcs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbimde bir yaraydı gözlerin,

Merhem vermedin kangren ettin!

Söz gerekmez zulmünü anlatmaya

Zulümden öte beni kahrettin!

Hançeri mertçe sapladın da,

Vurduğun yerde yarım bıraktın!

Ben seni çok iyi anladım da,

Sen beni yanlış anladın!', 'Kalbimde bir yaraydı gözlerin, Merhem vermedin kangren ettin! Söz gerekmez zulmünü anlatmaya Zulümden öte beni kahrettin! Hançeri mertçe sap...', ARRAY['Türk Edebiyatı','Şiir','İdris Elibol']::text[], 8.5, '{"poet":"İdris Elibol","poet_slug":"i-dris-elibol","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yanlis-anladin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sildim-seni', 'sildim-seni-i-dris-elibol-ji01e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nazına sürgün ettim suçsuz kalbi,

Aşkı müebbet bildim sildim seni

Seni seviyorum sanmadan beni

Yazdığım son defterden sildim seni

Gönül sahiline yıktım dağları,

Gözlerine çevirdim bütün yolları

Adını yazdığım ıslak kumları

Avuçlarımda boğdum sildim seni!

Anlamadın gitti sevgiden aşktan

Bin yara açtın bağrıma taştan

Ben ki ölmüşüm gülüm ta doğuştan

Büründüğüm kefenden sildim seni

Bendim sevda denizinin derini

Sayende çöle döndüm süzdün beni

Ben sana emanet etmişken seni

Sende ihanet buldum sildim seni!', 'Nazına sürgün ettim suçsuz kalbi, Aşkı müebbet bildim sildim seni Seni seviyorum sanmadan beni Yazdığım son defterden sildim seni Gönül sahi...', ARRAY['Türk Edebiyatı','Şiir','İdris Elibol']::text[], 8.5, '{"poet":"İdris Elibol","poet_slug":"i-dris-elibol","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sildim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Kollarında', 'senin-kollarinda-mehmet-hanifikaya-abufo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölürken sevgilim senin kolların arasında olmak,

Ölürken sevgilim gülen gözlerine derince bakmak,

Ölürken sevgilim seni doya doya koklamak,

Ölürken sevgilim aaah SENİ SEVİYORUM demek.

Ölüm vız gelir sevgilim kollarında öleceksem,

Günlerim ızdırap acı dolu sensiz geçireceksem,

Seni sevip sana yakın ve uzak olacaksam,

Öleyim ben bırak sevgilim sensiz kalacaksam.

Ama bana bir iyilik daha yap sevgilim ne olursun,

İnan bu son isteğim sende artık bensiz rahat olursun,

Ya beni sen öldür kör bir bıçak bulabilirsen,

Yada gel ben önce seni öldüreyim kıyabilirsem.

Ölürken sevgilim ölürken yazıyorum bunları sana,

Keşke okusan okuyabilsen kaçıncı şiirim bak sana,

Yanlızlık bana ağır gelir taşıyamam elini uzatsana,

Beraberdik beraber olacağız ölürkende anlasann', 'Ölürken sevgilim senin kolların arasında olmak, Ölürken sevgilim gülen gözlerine derince bakmak, Ölürken sevgilim seni doya doya koklamak, Ö...', ARRAY['Türk Edebiyatı','Şiir','Mehmet HanifiKaya']::text[], 8.5, '{"poet":"Mehmet HanifiKaya","poet_slug":"mehmet-hanifikaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senin-kollarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Nedir', 'hayat-nedir-adem-yavuz-d0sfy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana sen kimlerdensin? diye soracak olursan;

Ben hayata boş verenlerdenim;

Bana hayat nedir? Diye soracak olursan;

Ben hayat deryasında yüzenlerdenim.

Arama beni lüks meyhanelerde;

Ben aşk şarabı içenlerdenim.

bana sevgili nedir?diye soracak olursan;

İşte ben onun için ölüme gidenlerdenim!', 'Bana sen kimlerdensin? diye soracak olursan; Ben hayata boş verenlerdenim; Bana hayat nedir? Diye soracak olursan; Ben hayat deryasında yüze...', ARRAY['Türk Edebiyatı','Şiir','Adem Yavuz']::text[], 8.5, '{"poet":"Adem Yavuz","poet_slug":"adem-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayat-nedir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Arkadaş', 'aglama-arkadas-yuksel-alkan-2tsal', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Görüyorum ağlıyorsun Arkadaş,

Aşk yalandır ağlamaya değmez.

Seversin fakat kıymetin bilinmez,

Boş ver be Arkadaş,

Aşk ağlamaya değmez.

Sevildiğini sanırsın aylar boyunca,

Anlarsın yanıldığını geçte olsa,

Aşk bahçenin bütün gülleride solsa,

Boş ver be Arkadaş,

Aşk ağlamaya değmez.

Ben ağladım yıllar boyunca.

Benimki Aşk değil,Kara Sevda.

Bu sevdaya tutulan ömür boyu gülemez.

Boş ver be Arkadaş,

Aşk ağlamaya değmez.', 'Görüyorum ağlıyorsun Arkadaş, Aşk yalandır ağlamaya değmez. Seversin fakat kıymetin bilinmez, Boş ver be Arkadaş, Aşk ağlamaya değmez. Sevil...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Alkan']::text[], 8.5, '{"poet":"Yüksel Alkan","poet_slug":"yuksel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aglama-arkadas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Dedikleri', 'ask-dedikleri-yuksel-alkan-pe3tz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk dedikleri kalpleri yakan,

Ateşten başka bir şey değildir.

Gönülden gönüle akan,

Sevgiden başka bir şey değildir.

Uykuları kaçırır, rüyalara girer,

Aşık olan günden güne erir gider,

Sonu mutlaka acıyla biter,

Aşık Yüksel bunu söyler.', 'Aşk dedikleri kalpleri yakan, Ateşten başka bir şey değildir. Gönülden gönüle akan, Sevgiden başka bir şey değildir. Uykuları kaçırır, rüyal...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Alkan']::text[], 8.5, '{"poet":"Yüksel Alkan","poet_slug":"yuksel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-dedikleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Çocuğa', 'i-cimdeki-cocuga-bahar-selman-gfgzq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Ruhunum derinliklerindeki cocuga''

Ruhumun derinliklerinde,

Çocuk sana sesleniyorum.

Eğer çıkmak istiyorsan,

Durma artık çık.

Hep seni susturmaya çalıştım,

Ama sen asla susmadın.

Hep sen benlendin.

Yaptığım herşeyde,

Muhakkak bir çocuksuluk vardı,

İşte bu sendin çocuk.

Artık çıkmanın zamanı geldi.

Çocuk sus artık,

İçimde volkanlar kopuyor sayende,

Sus artık sus!

İçimde dinmeyen fırtınalar,

Arayışlarım,

Hepsinin sorumlusu sensin çocuk.

Çok muzursun sen.

Her zaman yaramaz mı olmalısın ha?

Uslan be cocuk,

Yorulda otur artık biraz,

Nefeslen.

Bende artık sorumluluklar almalıyım,

Senle uğraşamıyorum be cocuk.

Git artık benden

Bırak beni,

Artık farklı olmam lazım!

Sözümü dinlede uslan cocuk.

Ya git ya da uslan!', '''Ruhunum derinliklerindeki cocuga'' Ruhumun derinliklerinde, Çocuk sana sesleniyorum. Eğer çıkmak istiyorsan, Durma artık çık. Hep seni sustu...', ARRAY['Türk Edebiyatı','Şiir','Bahar Selman']::text[], 8.5, '{"poet":"Bahar Selman","poet_slug":"bahar-selman","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/icimdeki-cocuga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yasam', 'yasam-feriha-korkmaz-p7i7m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Başlerken her sabah yeni bir güne

Aydınlanmalı tüm gönüller

Geri dönüp baktığında şöyle bir düne

Solmuş olmamalı bir gül gibi sevgiler

Yaşamalı insan her anını dolu dolu

Sevmeli her canlıyı,kucak açmalı

Bağlanmamalı zorluklarda eli,kolu

Neşeyle yaşamalı ve neşe saçmalı

Yaşanılan her gün bir anı bırakır arkasında

İyi ya da kötü yorumlanır bunlar yıllar sonra

Kaybolup giden yılların olamazsın yaşarken farkında

Uzun ömrün bittiğini hissedersin 

Bir değneğe tutunduktan sonra

Her insanın istediği gibi yaşaması dileğiyle...........

(30/05/2000-salı)', 'Başlerken her sabah yeni bir güne Aydınlanmalı tüm gönüller Geri dönüp baktığında şöyle bir düne Solmuş olmamalı bir gül gibi sevgiler Yaşam...', ARRAY['Türk Edebiyatı','Şiir','Feriha Korkmaz']::text[], 8.5, '{"poet":"Feriha Korkmaz","poet_slug":"feriha-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar', 'i-nsanlar-metin-altiner-bq2en', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökyüzünden boşalan,toprağa değince yok olan

Biz insanlar üzerine:

Yağmur kadar hırçın

İnsanlar kadar aptal olmamalı

Seller kadar taşkın kalpler

Nefret dolu olmamalı

İncitmemeli sevenleri ve sevilenleri

İnsanlar,yok olurken beyinleri

Kaybetmemeliler kalplerini ve sevgilerini

Yağmur kadar hırçın

İnsanlar kadar aptal olmamalı.

(30/05/2000-salı)', 'Gökyüzünden boşalan,toprağa değince yok olan Biz insanlar üzerine: Yağmur kadar hırçın İnsanlar kadar aptal olmamalı Seller kadar taşkın kal...', ARRAY['Türk Edebiyatı','Şiir','Metin Altıner']::text[], 8.5, '{"poet":"Metin Altıner","poet_slug":"metin-altiner","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ana', 'ana-rehman-ali-nqnhq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elinde gördüğüm kabar izleri

Ağır zehmetinin nişanesidir,

Ak saçta görürem xına izleri,

Saçlarının henasına kurbanam.

Ana, ben borcluyam ak saçlarına 

Besledin böyüttün yandın halıma ,

Yukusuz geceler düşüb payına 

Gözlerinin yukusuna kurbanam.

Geceler yatmayıb oyak kalanda

Beşiğimin başında layla çalanda

Yukusuz geceleri yola salanda 

Gözlerinin yukusuna kurbanam.

Menim şan şöhretim yazım baharım

Sensen bu dünyada dövletim varım,

Laylandan okunur hoş arzuların

Dodaklarının laylasına kurbanam.

Ana vügarını eymemiş hesret,

Karşında diz çökür koca tebiyyet,

Böyüttün rahmanı çektin eziyyet

Üreyinin duyğusuna kaurbanam', 'Elinde gördüğüm kabar izleri Ağır zehmetinin nişanesidir, Ak saçta görürem xına izleri, Saçlarının henasına kurbanam. Ana, ben borcluyam ak ...', ARRAY['Türk Edebiyatı','Şiir','Rehman Ali']::text[], 8.5, '{"poet":"Rehman Ali","poet_slug":"rehman-ali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ana-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Şair Olamam Usta', 'ben-sair-olamam-usta-i-dris-elibol-tyl01', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şairler ağlamaz demiş bir usta

Oysa ağlamadık zamanım olmadı benim

Zaten ben şair olamam be usta

Gözyaşlarım şiir yazamaz ki

Ben şair olamam usta

Ağlarsam;

Ağlamayan şairler ne der sonra

Sen şair olamazsın demezler mi

Suçum ağlamaksa usta

Ben şair olamam usta

Ama usta;

İnsanlar ağlarmış,

Gözleri ıslandıkça yürekleri kanadıkça...

Hem ağlamayan insanların,

Yürekleri olmazmış,

Hiç yüreksiz şair olur mu be usta

Ağladım!

Ve küfür yedim şairliğime 

Ne yapayım be usta 

Gözlerim ıslanıyor yüreğim kanıyor...

Şairler ağlamaz olur mu hiç

Onlar da ağlamaz sa kim ağlar

Şairler ağlar be ustam

Şairler ağlar...', 'Şairler ağlamaz demiş bir usta Oysa ağlamadık zamanım olmadı benim Zaten ben şair olamam be usta Gözyaşlarım şiir yazamaz ki Ben şair olamam...', ARRAY['Türk Edebiyatı','Şiir','İdris Elibol']::text[], 8.5, '{"poet":"İdris Elibol","poet_slug":"i-dris-elibol","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-sair-olamam-usta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalemin Ağlatırsa Hüznü!..', 'kalemin-aglatirsa-huznu-i-dris-elibol-1bvfg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İhtilal büyütmeye hazır bir gecenin

Sabahında çözülmüş kirpiklerim.

Hüzün kokan bir güldü annem

Taşıdığı yükü Eylül''e teslim etmesi  bu yüzdendi.

Ayaklarına koyduğu yastıkta sallayarak uyuturdu.

Elleriyle başımı okşaması, 

Bir güvercinin kanatlarıyla yavrusunu örtüp

Uyutması gibiydi. 

    	

Oyuncaklarımın kalem olduğunu anladığım  zaman

Çocuk olduğumu anlamıştım.

Ve ne zaman ki kırdılar kalemimi,

İşte o zaman büyüdüğüme karar verdim.

Kalemimi kırmışlardı oysa,

Çocukluk oyuncağımı kırmışlardı.

Derken, aşkı öğretmeye çalışıyordu birileri.

Yarı hüzün,

Yarı sevinç çığlığı atmayı öğretiyordu,

Böyle olmalı diyordu!

Giderken,

Öğrettiği aşkı,

Unutturmayı öğretmeden gidiyordu.

Nikotine alıştırdılar sonra,

Ben yürüdükçe, uzayıp giden

Gece lambalarının aydınlığında

Havaya kalkardı tütün dumanları... 

 	

Yoruldukça mısralar dökülürdü  düşlerimden. 

Ve ben geceye döner ağlardım,

Hüzün ağlatan kalemimden!.. 

Sonra şairliğimi haber veriyordu kanayan yanlarım...

Kanayan yanlarım,

İçimde koşan küheylanları dizginliyordu.

Güneşin batışını düşlerdim 

Üniversitenin kalabalık yollarında...

Çayımın deminin koyu olması bundandı belki. 

    	

İstanbul''u neden çok sevdiğimi

Anlayamadım bir türlü,

O da anlayamadı.

Aşkı öğretenler çekip giderken,

''Bu böyle olmalı'' diyordu.

Öğrendiğimi unutmadığımı,

Dünyanın bütün annelerini sevdiğim

Ve ülkemin bütün kızlarına ayrı ayrı

Aşık olduğum gün hatırladım!

	

Yine bir gece vakti

Kalabalıklar ortasında bırakıp bedenini,

Yalnız bir odaya götürdü ruhunu dedem. 

Miras olarak bana

Hayatın acılarını bıraktı ardından... 

Ve ben,

Ben kalemimin kırıldığı gün kırdım acıları,

Orada,

Kırık dökük hala!..', 'İhtilal büyütmeye hazır bir gecenin Sabahında çözülmüş kirpiklerim. Hüzün kokan bir güldü annem Taşıdığı yükü Eylül''e teslim etmesi  bu yüzd...', ARRAY['Türk Edebiyatı','Şiir','İdris Elibol']::text[], 8.5, '{"poet":"İdris Elibol","poet_slug":"i-dris-elibol","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/kalemin-aglatirsa-huznu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek Gibi Yaşamak Vakti', 'olmek-gibi-yasamak-vakti-i-dris-elibol-v3l54', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi ölmek gibi yaşamak vakti

Solgun bir gül gibi dökülmenin

Kavruk toprakların seyir vakti

Şimdi Nisan kadar masum 

Düşlerimi bıraktım

ilk göz ağrım, sevgilim,

Yalnızlığı bıraktım!

Gün ortasında çarmıha çekilmiş,

Ellerim, ayaklarım ve bütün bedenim

Kıpırdasam yaşadığımı sanacaklar

Oysa yok yere yaşamak bu

Şimdi yok yere 

Yaşamak gibi  ölmek vakti

Şimdi yüreğim ağzıma gelmiş gibi

Kaderimi çizen bıçkın bir Eylül

Yıldızlara dokunsam ellerim yanacak

Karşı koyamadığım bıçkın bir Eylül

Yavrusunu arayan 

Ceylanın yavrusu yine o!

Şehrayini bozan el yine o!..

Bir kere de ben mızrabımı 

Senin için vurmak istedim

Benim türküm hiç söylenmedi

Oysa ağlarken gülmek bu...

Erken doğmak isteyen çocuk gibi

İçimde yalvarma Yaradan aşkına!

Yüreğim ağzıma gelmiş gibi!..', 'Şimdi ölmek gibi yaşamak vakti Solgun bir gül gibi dökülmenin Kavruk toprakların seyir vakti Şimdi Nisan kadar masum  Düşlerimi bıraktım ilk...', ARRAY['Türk Edebiyatı','Şiir','İdris Elibol']::text[], 8.5, '{"poet":"İdris Elibol","poet_slug":"i-dris-elibol","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/olmek-gibi-yasamak-vakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzun Bir Öykü', 'uzun-bir-oyku-ozdemir-asaf-ueodq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'UZUN BİR ÖYKÜ

Hiç kimsenin kafesine

Koyamayacağı bir kuş..

Kaçmasını öylesine 

Uçmasını böylesıne 

Unutmuş.

Bir insan sesine 

Gelip konmuş.', 'UZUN BİR ÖYKÜ Hiç kimsenin kafesine Koyamayacağı bir kuş.. Kaçmasını öylesine  Uçmasını böylesıne  Unutmuş. Bir insan sesine  Gelip konmuş....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uzun-bir-oyku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
