INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-nabi-keskin-w49b2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaş otuzbir ne yaz ne de ilkbahar

Geçmişten meçhule esen sanki bir rüzgar', 'Yaş otuzbir ne yaz ne de ilkbahar Geçmişten meçhule esen sanki bir rüzgar...', ARRAY['Türk Edebiyatı','Şiir','Nabi Keskin']::text[], 8.5, '{"poet":"Nabi Keskin","poet_slug":"nabi-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ozlem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmak Demiştin', 'olmak-demistin-suleyman-arif-emre-x714c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hayat olmaktır demiştin

hayat sevmek ve olmaktır

demiştinki gündüz ölmek

gece ise doğmaktır

ölüm savmaktır sıranı sırası gelince

ölüm yaşam kuşunu kafesinden salmaktır

gözlerime öyle bakma demiştin

gözlerin ateşe dalmaktır

ne çıkar misk-u amber sacmasan etrafına

gülün karı solmaktır

değişir iklimler mesafeler seninle

ve hüzün sevdanla dolmaktır

bu beden her mihnete her belaya katlanır

lakin maksat ne olmaktır ne ölmektir ne solmaktır

maksat olmaksa demiştin

olmak onu bulmaktır', 'hayat olmaktır demiştin hayat sevmek ve olmaktır demiştinki gündüz ölmek gece ise doğmaktır ölüm savmaktır sıranı sırası gelince ölüm yaşam ...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Arif Emre']::text[], 8.5, '{"poet":"Süleyman Arif Emre","poet_slug":"suleyman-arif-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olmak-demistin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmak Kolay mı?', 'unutmak-kolay-mi-asik-serkan-4z0bp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O kadar kolaymı unutmak seni

O kadar kolaymı unutabilmek

O kadar kolaymı unut demek

O kadar kolaymı unuttun beni

Unut gitsin diyorsun,bulursun başkasını

Sensizliği unutamadım,seni unutmakmı

Kolaymı unutmak,kolaymı seni

O kadar kolaymı unuttun beni

Mazilerimiz,hayallerimiz vardı seninle

Unut gitsin diyorsun,unutulurmu

Hani mutluydun,huzurluydun benimle

O kadar kolaymı unuttun beni

Bir evimiz olacaktı çiçekli,bahçeli

Çocuklarımız olacaktı cıvıl cıvıl,neşeli

Davetiyelerimiz vardı baş harflerimiz kaşeli

O kadar kolaymı unuttun beni

Bir sözümüz vardı bizim hatırla

Allah''ım sen bizi ayırma diye

Bir sözün vardı senin hatırla

Sevgilim sakın beni unutma diye

O kadar kolaymı unuttun beni

O kadar kolaymı unutmak seni.......', 'O kadar kolaymı unutmak seni O kadar kolaymı unutabilmek O kadar kolaymı unut demek O kadar kolaymı unuttun beni Unut gitsin diyorsun,bulurs...', ARRAY['Türk Edebiyatı','Şiir','Aşık Serkan']::text[], 8.5, '{"poet":"Aşık Serkan","poet_slug":"asik-serkan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/unutmak-kolay-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyeceğim', 'bekleyecegim-asik-serkan-8g6r1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bambaşka bir duygu seni düşünmek

Hayal peres bir duygu bekleyeceğim

Her gece rüyalarda sana kavuşmak

Hayal peres bir gece bekleyeceğim

Ne kadar imkansız olsun,bilsemde

Alnıma yazılmamış olsun,görsemde

Bir gün tutmuş evlenmiş.duysamda

Yatağa girmeden bekleyeceğim

Hasret rüzgarlarıda esse

Sevdiğim bu eldende gitse

Bana bir yol,bir ümit verse

O hevesle yollarını gözleyeceğim

Kollarına girmese başkalarının

Usanmadan yılmadan beklerim

Bir anlamı olmasa bakışlarının

Hiç durmam buralarda,çeker giderim', 'Bambaşka bir duygu seni düşünmek Hayal peres bir duygu bekleyeceğim Her gece rüyalarda sana kavuşmak Hayal peres bir gece bekleyeceğim Ne ka...', ARRAY['Türk Edebiyatı','Şiir','Aşık Serkan']::text[], 8.5, '{"poet":"Aşık Serkan","poet_slug":"asik-serkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bekleyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-musa-ozgun-o9c1q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen kırk yılda bir gibisin. 

      Sen içimdeki çocuğun sessiz çığlığı, 

      Sen içimdeki yaşlı adamın yalnızlığındaki görünmeyen yüzsün. 

      Sen yazılmamış ve ve belkide hiç yazılmayacak alın yazımsın,

      Ve hiç yaşayamayacağım ikinci hayatımsın.

      Sen ilksin... 

      İlk aşık olduğum, ilk çıktığım, ilk üzüldüğüm değilsin

      Ama sadece ilksin.

      İlk değil geceler boyu düşünmem ve dalmam boş tavana

      Ama sadece ilksin.

      Kimsin?

      Nerden geldin ve nereye gidiyorsun bilmiyorum,

      Ama biliyorum ''Gideceksin''.

      Yüzüne baktığım zaman gördüklerimi bağırmak istiyorum

      Ama korkuyorum bir daha görememekten.

      Ve susuyorum...

      Bu ben değilim aslında

      Korkan, susan.

      Kimbilir belkide bu senin hayat boyu üzerinde çalıştığın,

      Usta hareketlerle şekil verdiğin,

      Ruhunun bir kısmını üzerine üflediğin,

      Ve bana verdiğin bir sanat eseri.

      Sen en az ortak özelliği olanımsın,

      Sen en küçüğüsün hayatımın

       Ve en büyüğü kalbimin.

       Kalabalıkta ki yalnızlığım,

       Gürültünün ortasındaki sessizliğim,

       Unutmadığım birkaç isimden biri,

       Ve sen ilk sustuğumsun.

       Sen, hep hayalini kurduğum

       Kimselerin ve benim de bilmediğim o yerde

       Denize bakan ağaçların arasındaki ahşap evimin önünde 

       Yakamozu seyreden kişisin...

       Sen ilk yazdığım değil

       İlk sakladığım şiirsin.

      Sen bu kokuşmuş dünyada yıllardır aradığım ve geç bulduğum

      Masum çocuk yüzüsün.

      Uzağımdaki yakınım, yakınımdaki uzağımsın.

      En yakınında olmak istediğim ama en uzağında olmam gerekensin.

     Ve sen hayatımın ilk ikibuçuğusun...

                                        16 Mayıs 1999 - Ankara', 'Sen kırk yılda bir gibisin.        Sen içimdeki çocuğun sessiz çığlığı,        Sen içimdeki yaşlı adamın yalnızlığındaki görünmeyen yüzsün. ...', ARRAY['Türk Edebiyatı','Şiir','Musa Özgün']::text[], 8.5, '{"poet":"Musa Özgün","poet_slug":"musa-ozgun","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırf Sen', 'sirf-sen-hasan-kucuk-up24p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çığlıklara boğduğumda ismini,

Senin kadar güzeldi gözlerin…

Bakışlarındaki kıvılcımla başlamıştı

İçimdeki cehennem.

Yüreğime serpilen

Gülücüklerinle harlandı.

Sonra bir baktım

bir çiçek açtı gözlerinde,

Bir çocuk güldü

Güz pembesi yüreğime ..

Bir kuş kanatlandı

Yalnızlık şiirlerine inat.

Bir kız girdi

Mısralarıma…

Yanıbaşımdaki düşlere

Bir kılavuz aradım

Gözbebeklerine kanıp.

Sana inanıp, sana sarılıp.

Seni düştüm yalnızlıktan…

Yağmur damlasına 

Sordum avcundaki çiçeği.

Kar tanesiyle paylaştım

Sana sakladığım sevgimi.

Yaşanılası anılarla 

Ördüm geleceği.

Ağlarıma düştüğünde

Yine ben sardım seni

Rüzgarlardan önce…

Mavi iklimler boyadım

Sana ellerimle.

Papatyalar topladım

Her yaprağında ''seviyor'' yazan.

Gri bulutlarla kaplıyken sen,

Yıldızları taşıdım çaresizlikten.

Sırf sen gül diye,

Sırf ışıklar hiç sönmesin diye…

Hani sen korkarsın ya 

Yalnızlıktan,

Kaçarsın ya sevgiden.

Sırf sen sev diye

Koskoca bir yürek getirdim sana

Aşkımın doğduğu yerden.

Bakışınla cehenneme dönen

Bir kalp getirdim sana...

Sırf sen

Ben olduğum için 

Sev Diye……', 'Çığlıklara boğduğumda ismini, Senin kadar güzeldi gözlerin… Bakışlarındaki kıvılcımla başlamıştı İçimdeki cehennem. Yüreğime serpilen Gülücü...', ARRAY['Türk Edebiyatı','Şiir','Hasan Küçük']::text[], 8.5, '{"poet":"Hasan Küçük","poet_slug":"hasan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/sirf-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ansızın', 'ansizin-hasan-kucuk-0x1qz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece olur.

Uyuyamıyorumların balkonundan,

Dünyayı seyredersin.

Gördüğün her gölgeyi

Kuşkuyla selamlarsın..

Farkedemezsin,

Gözlerin kapanır.

Uykuyla uyanıklık arasında

Gidemediğin 

Bütün sokakların.

Rüyalarına uyanırsın…', 'Gece olur. Uyuyamıyorumların balkonundan, Dünyayı seyredersin. Gördüğün her gölgeyi Kuşkuyla selamlarsın.. Farkedemezsin, Gözlerin kapanır. ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Küçük']::text[], 8.5, '{"poet":"Hasan Küçük","poet_slug":"hasan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ansizin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolanıyorum', 'dolaniyorum-hasan-kucuk-om5vf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sonbahar ağlıyor.

Elinde kırık dökük bir bulut.

Ne yağmur yağıyor fidelere.

Ne de sevdaya dair

Bir damla umut.…

Ölü bir gece vuruyor kıyıya.

Alışılmaz bir acının ayak izleri.

Martıların çığlıkları.

Oyun bozan dalgalar.

Ve hafif bir şiir,

Lodosların içinde,

Islık misali dolanıyor..', 'Sonbahar ağlıyor. Elinde kırık dökük bir bulut. Ne yağmur yağıyor fidelere. Ne de sevdaya dair Bir damla umut.… Ölü bir gece vuruyor kıyıya....', ARRAY['Türk Edebiyatı','Şiir','Hasan Küçük']::text[], 8.5, '{"poet":"Hasan Küçük","poet_slug":"hasan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dolaniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ona', 'ona-huseyin-ufuk-5i6os', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen camın olduğu köşede

Bende karşı köşedeydim

Ben sana bakar,dalıp dalıp giderdim gözlerine

Sen ise koyu sohbetlere dalar,

Devrim yapardın hep bu ülkede

Yollarımız

Anlayışlarımız

Mekanlarımız

Yaşlarımız 

Hep farklıydı

Ama sana doğru bir şey çekerdi hep beni

Belki gözlerindi o çeken şey

Belki kıvrım kıvrım saçların

Belkide içinde dönen tüm fırtınaları sakladığın 

O masum bakışların

Ama ne olurasa olsun 

Sen benim yüksekokuldaki ilk hayal kırıklığım

Ve de ilk aşkımsın', 'Sen camın olduğu köşede Bende karşı köşedeydim Ben sana bakar,dalıp dalıp giderdim gözlerine Sen ise koyu sohbetlere dalar, Devrim yapardın ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ufuk']::text[], 8.5, '{"poet":"Hüseyin Ufuk","poet_slug":"huseyin-ufuk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ona-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Gardaş', 'hadi-gardas-huseyin-ufuk-p7bjw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hadi gardaş gel gidelim buralardan

Gidelim uzak diyarlara

Çıplak ayak basalım toprağa

Aşkımızı haykıralım buz gibi sakarya suyuna', 'Hadi gardaş gel gidelim buralardan Gidelim uzak diyarlara Çıplak ayak basalım toprağa Aşkımızı haykıralım buz gibi sakarya suyuna...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ufuk']::text[], 8.5, '{"poet":"Hüseyin Ufuk","poet_slug":"huseyin-ufuk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hadi-gardas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün gelir', 'gun-gelir-huseyin-ufuk-8zru0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün gelir;

Kara bulutlar gider,güneş doğar bu kente

Ve o zaman

Daha çok ihtiyaç olur 

Sevmeye

Sevilmeye!!!', 'Gün gelir; Kara bulutlar gider,güneş doğar bu kente Ve o zaman Daha çok ihtiyaç olur  Sevmeye Sevilmeye!!!...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Ufuk']::text[], 8.5, '{"poet":"Hüseyin Ufuk","poet_slug":"huseyin-ufuk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gun-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'korku', 'korku-alacan-yagmur-idwyy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sensizlere karıştım korkuyorum..

sensizlerden  bir  köprüde yürüyorum..

sensizliği tanıyorum..

sensizlikten korkuyorum..

sensizliği yanıma aldım.. 

artık yoksun..

sensizlik bana bunu öğretti..', 'sensizlere karıştım korkuyorum.. sensizlerden  bir  köprüde yürüyorum.. sensizliği tanıyorum.. sensizlikten korkuyorum.. sensizliği yanıma a...', ARRAY['Türk Edebiyatı','Şiir','Alacan Yağmur']::text[], 8.5, '{"poet":"Alacan Yağmur","poet_slug":"alacan-yagmur","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/korku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahtı', 'sabahti-serdar-ozturk-3ui9l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabahtı,

ve dinginliği örtmüştü gecenin tüm gizemini.

Ben,

buklelerini bozdum sahilde kumların,

dalgalarsa,

rahatını martıların…

Gurbete giden,

eski bir türkü geçirdim içimden.

Adına radyoda hiç istek yapılmamış sevgililere.

Belki dinledin,

hatta gülümsedin,

kimden geldiğini bilmeden…

Sabahını giydim üstüme baharın.

Görünce bir telaş masumiyetini,

yanlış ilikledim düğmelerini sevdanın…

Ve o sabah ben,

bir başıma,

baştan başa sensiz sahili,

dolaştım yine düşünmeden halimi…

2000', 'Sabahtı, ve dinginliği örtmüştü gecenin tüm gizemini. Ben, buklelerini bozdum sahilde kumların, dalgalarsa, rahatını martıların… Gurbete gid...', ARRAY['Türk Edebiyatı','Şiir','Serdar Öztürk']::text[], 8.5, '{"poet":"Serdar Öztürk","poet_slug":"serdar-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sabahti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-serdar-ozturk-5wahg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk,

eylülde sevdim Dicle’yi ben,

Fırat’a inat…

Eylülde yattım kollarına,

içinde ninni saklı akşamların…

Uykuyu peşkeş çeken geceleri,

ilk eylülde tattım.

Eylülde şair oldum ilkin,

ve

''özlemek, yarını bugünden ekmektir…'' dedim.

Oysa,

bir eylül bilmez, ki ben eylülün çiftçisiyim…

1998', 'İlk, eylülde sevdim Dicle’yi ben, Fırat’a inat… Eylülde yattım kollarına, içinde ninni saklı akşamların… Uykuyu peşkeş çeken geceleri, ilk e...', ARRAY['Türk Edebiyatı','Şiir','Serdar Öztürk']::text[], 8.5, '{"poet":"Serdar Öztürk","poet_slug":"serdar-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/eylul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğru Bakış', 'dogru-bakis-zeren-cangert-miqo7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Baktım toprağın rengine, senin rengin

Göğe yöneldim maviye, oda sendin

Gözüm gördü, kalbim inandı.

Hayatta senden başkası yalandı.

Denizde gördüm seni, dağlarda

Yeşil ovalarda, ağaç yapraklarında

Seni görsem bu kadar tanıyamazdım.

Bunlar sana özgü senin tarzın.

Her şey değişti, kullandığımız her şey

Kullanan değişmedi değişemedi.

Uçağa biniyoruz şimdi faytona değil, 

Ama elma ağacı kiraz vermedi daha, 

Kuşlar hala gagasında taşıyor suyu çocuklarına.

Irmaklar gürül gürül çağlıyor.

Toprak yine anam kokuyor.

Ben yine benim.

Seviyorum, acıyorum, üşüyorum.

Değişmeyen ben değişen dünyaya bakıyorum

Sonra o dünyadaki o koskoca dünyadaki

Rüzgara doğru kanat çırpan kuşlara bakıyorum

Seni görmek ümidi ile 

Sonra seni görüyorum sanatınla 

Kalbimi temizliyorum boş şeylerden 

Sana yer açıyorum.

Sen geliyorsun kalbimin en güzel odacığına 

Ve ben her şeye emin bakıyorum.

Ya Rab seni çok seviyorum.', 'Baktım toprağın rengine, senin rengin Göğe yöneldim maviye, oda sendin Gözüm gördü, kalbim inandı. Hayatta senden başkası yalandı. Denizde g...', ARRAY['Türk Edebiyatı','Şiir','Zeren Cangert']::text[], 8.5, '{"poet":"Zeren Cangert","poet_slug":"zeren-cangert","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/dogru-bakis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte O', 'i-ste-o-zeren-cangert-ycni5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zamanın en güzel çağında gelip ,

Kondun gönüllere.

Aşkın en büyük aşktı alemlere.

Senden öğrendim bir ağacın kardeşim olduğunu.

Hep vermeyi karşılıksız sevmeyi kalbe dolan

Hoş görmeyi.

Bir gün ölüpte görebilirsem seni

Yanından ayırma beni.', 'Zamanın en güzel çağında gelip , Kondun gönüllere. Aşkın en büyük aşktı alemlere. Senden öğrendim bir ağacın kardeşim olduğunu. Hep vermeyi ...', ARRAY['Türk Edebiyatı','Şiir','Zeren Cangert']::text[], 8.5, '{"poet":"Zeren Cangert","poet_slug":"zeren-cangert","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/iste-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey İnsan', 'ey-i-nsan-mustafa-i-slamoglu-yvjwm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ey insan 

ey yüz akı gönül aydınlığı 

kabul olmuş sadaka kadar güzel 

bir duygu sarıyor seni anan yüreğimi 

bastığın toprakla yıkadığın gözüme 

şimdi güneş bile siyah görünüyor 

ey yüz akı gönül aydınlığı

ben kendime ağlarken Uhud da ağlar mıymış 

Hıra''yı mahzun gördüm soramadım sevgili 

hasretinin dışında başka derdi var mıymış? 

ey insan 

içimde büyüttüğüm tüm çiçekleri 

sana adıyorum 

ıtırları, yaseminleri, menekşeleri 

lale bana kalsın 

kapına çiçeklerin karalısını sunmaktan 

utanıyorum

dua çıkmayan göğe sevdalar çıkar mıymış? 

bülbülünü kaybetmiş bu evrensel bahçede 

dikenler bile bir hoş, gayrı gül kokar mıymış? 

ey insan 

göklerin öğrencisi, yerlerin öğretmeni ey 

sen öğrettin taşa konuşmayı 

ağaca selam vermeyi 

aya yarılmayı, toprağa dürülmeyi 

göklere kurulmayı, durmayı zamanı 

yılana ve deveye sevmeyi 

yaşamayı ve ölmeyi sen öğrettin insana

o bengisu gözünden fışkıran pınar mıymış? 

baharların kaynağı ve yolunu gözleyen 

bir ben sevda şehidi, bir de şu çınar mıymış? 

ey insan 

senin sırrın 

gözyaşının terkibinde saklıymış 

bu gerçeği bir denizin dudağından öğrendim 

gecenin bir vaktinde bir sevgili ağlarken 

bir dişi varlığını varlığına adarken 

bir erkeğin ellerinde 

ölüm havlu atarken 

haklıymış

söyle gönlüm bu sevda mahşere kalır mıymış? 

alışılmış sözcükler yükleyip kanadına 

ona doğru uçursam katına alır mıymış? 

ey 

ey ins 

ey insan 

hıncını hıncıma kat 

sancını sancıma kat 

pamuktan ellerini geçir yürek halkama 

ister ayağın katına çek 

istersen yerlere at. 

1990-91, Medine-Kahire', 'ey insan  ey yüz akı gönül aydınlığı  kabul olmuş sadaka kadar güzel  bir duygu sarıyor seni anan yüreğimi  bastığın toprakla yıkadığın gözü...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İslamoğlu']::text[], 8.5, '{"poet":"Mustafa İslamoğlu","poet_slug":"mustafa-i-slamoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/ey-insan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Takdim', 'takdim-mustafa-i-slamoglu-imdit', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özlemekten yorulmuşum, kapında durdur beni 

Ucu sana dek ulaşan bir zincire vur beni 

Beni çöllerden sorma, ki sonra Mecnun yerinir 

Aşksızlıktan taş kesilmiş şehirlere sor beni 

Karanlık yerlerimi bir bir soyundum asfaltlara 

Şimdi yüreğim üşüyor, giyindir ey nur beni 

Ben Leyla’ma gidiyorum, çekil önümden Leyla 

Gayrı, cennet olsan durmam, bak çağırıyor beni 

Toprağımın gözlerinden çöllerin yanağına 

Süzülen bir damlayım yar, kabul buyur beni 

Hangi denize attımsa tutuştu saçlarından 

Bir kez bak, yoksa bu yürek yarı yolda kor beni', 'Özlemekten yorulmuşum, kapında durdur beni  Ucu sana dek ulaşan bir zincire vur beni  Beni çöllerden sorma, ki sonra Mecnun yerinir  Aşksızl...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İslamoğlu']::text[], 8.5, '{"poet":"Mustafa İslamoğlu","poet_slug":"mustafa-i-slamoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/takdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur Gel', 'ne-olur-gel-taner-atam-8vvce', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yar!

Seni bekleyen gözlerim,

İncindi seni anan şu dilim.

Sensizliği içtim çaresizce,

Bin kez öldüm sensiz, senden habersiz...

Ne olur gel artık, kucakla beni

Şefkatinle kov şu kara geceleri.

Rüzgâr gibi, uçuşan yaprak gibi

Savrulurum, bırakma yalnız beni

Feryad eden sessiz dalgalar

Seni anan, sana hasret dudaklar

Ne olur gel acele et ey canan,

Sen gökyüzü değilsen, uçar mı kuşlar?..', 'Yar! Seni bekleyen gözlerim, İncindi seni anan şu dilim. Sensizliği içtim çaresizce, Bin kez öldüm sensiz, senden habersiz... Ne olur gel ar...', ARRAY['Türk Edebiyatı','Şiir','Taner Atam']::text[], 8.5, '{"poet":"Taner Atam","poet_slug":"taner-atam","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ne-olur-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-taner-atam-yo43n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Isıtırsın beni her an, gecenin ayazında

Sevdalara bürünmüş, o sımsıcak koynunda

Nası dayanır ki bu can, sensiz geçen günlere

Kan ağlayan gözlerim senin içindir anne...

Beni burda bırakıp nereye gidiyorsun

Beni burda böylece unutup gidiyorsun

Yaşamın tek anlamı, sende hayat buluyor

Sensiz geçen akşamlar bana zindan oluyor.

Yaşanan tüm acılara,

Göğüs geren şu bağrıma

Dinmeyen bu efganıma,

Sorun beni...', 'Isıtırsın beni her an, gecenin ayazında Sevdalara bürünmüş, o sımsıcak koynunda Nası dayanır ki bu can, sensiz geçen günlere Kan ağlayan göz...', ARRAY['Türk Edebiyatı','Şiir','Taner Atam']::text[], 8.5, '{"poet":"Taner Atam","poet_slug":"taner-atam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçer mi?', 'gecer-mi-turgay-kivrak-t6h0w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Diner mi acılar kaçmakla

Varken yürümek üstüne üstüne;

Biter mi yollar yatmakla

Varken yürümek düşe kalka;

Geçer mi ölüm senden

Çareler peşinde koşmakla

Varken yaklaşmak dakika dakika an an

Bilemezsin ki neleri getirir zaman.

                           

14 ekim''97', 'Diner mi acılar kaçmakla Varken yürümek üstüne üstüne; Biter mi yollar yatmakla Varken yürümek düşe kalka; Geçer mi ölüm senden Çareler peşi...', ARRAY['Türk Edebiyatı','Şiir','Turgay Kıvrak']::text[], 8.5, '{"poet":"Turgay Kıvrak","poet_slug":"turgay-kivrak","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gecer-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçerde', 'i-cerde-ahmed-arif-ag75s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'haberin var mı taş duvar

demir kapı, kör pencere, 

yastığım, ranzam, zincirim

uğruna ölümlere gidip geldiğim, 

zulamdaki mahzun resim, 

haberin var mı? 

görüşmecim yeşil soğan göndermiş

karanfil kokuyor cigaram

dağlarına bahar gelmiş memleketimin', 'haberin var mı taş duvar demir kapı, kör pencere,  yastığım, ranzam, zincirim uğruna ölümlere gidip geldiğim,  zulamdaki mahzun resim,  habe...', ARRAY['Türk Edebiyatı','Şiir','Ahmed Arif']::text[], 8.5, '{"poet":"Ahmed Arif","poet_slug":"ahmed-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/icerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahpushane Türküsü', 'mahpushane-turkusu-sabahattin-ali-1t77e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Başın öne eğilmesin 

    Aldırma gönül aldırma 

    Ağladığın duyulmasın 

    Aldırma gönül, aldırma 

    Dışarda deli dalgalar 

    Gelip duvarları yalar 

    Seni bu sesler oyalar 

    Aldırma gönül, aldırma 

    Görmesen bile denizi 

    Yukarıya çevir gözü 

    Deniz dibidir gökyüzü 

    Aldırma gönül, aldırma 

    Dertlerin kalkınca şaha 

    Bir sitem yolla Allah''a 

    Görecek günler var daha 

    Aldırma gönül, aldırma 

    Kurşun ata ata biter 

    Yollar gide gide biter 

    Ceza yata yata biter 

    Aldırma gönül, aldırma', 'Başın öne eğilmesin      Aldırma gönül aldırma      Ağladığın duyulmasın      Aldırma gönül, aldırma      Dışarda deli dalgalar      Gelip d...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Ali']::text[], 8.5, '{"poet":"Sabahattin Ali","poet_slug":"sabahattin-ali","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mahpushane-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ustaçırak', 'ustacirak-kucuk-i-skender-gfzlk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölüm mü, ölüm, hayatın gençken çektirdiği yakışıklı resimler

hafif bir gülümseme yerleşmiş mavi taş çeşme gözlerine

içelim, diyor/ yağmurun, terkettiği manitadır gökyüzü!

Öyle çok ki imgeleri, şaşkınlığa düşüyorum

- abi, diye fısıldıyorum rakı kadehi kanyonundan,

hiç mi sevdalanmadın sen?! ...duruyor :biri vardı elbette, diyor

sen ortaya bir karışık salata daha söyle,şöyle rast makamı bir salata

Gecenin Orhan''ları, Ferdi''leri, Müslüm''leri gibidir bak yıldızlar!

sen daha gençsin, çükünden önce sustalı tuttun

bekaret kanından önce haybeci kanı gördün!

Benden sana nasihat oğlum

sevdiğini anladın mı çekip vuracaksın hiç acımadan :aleme namın,

kullandığın aletin şık ışıltılarıyla çığ gibi bir aşkla inecek!

dinecek göğsünde dört başı mamur bir şimşek gibi dolanan hiddet!

Sevdiğimin gözleri .. hükümet gibiydi

sevdiğimin elleri .. anlatsam, ellerinden utanırsın!

sevdiğimin elleri .. ellere yağmur olup gitti!

Harcadım allah seni inandırsın......

kan ağladım kan tükürdüm kan yutkundum günlerce......

on yıl yattım mapushanelerde, bambaşka alemlerin parlak

                                                                                 güvertesinde!

sen ortaya bir büyük daha söyle, şöyle .. boş ver lan, ağlama!

                                                                  (ocak-temmuz, 1998)', 'Ölüm mü, ölüm, hayatın gençken çektirdiği yakışıklı resimler hafif bir gülümseme yerleşmiş mavi taş çeşme gözlerine içelim, diyor/ yağmurun,...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ustacirak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanlı Masal', 'kanli-masal-kucuk-i-skender-lil6e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'aklım, haklıyım, et firarını! 

ovdun ve okşadın beni

çıktı içimdeki cin; 

ondan ölümümü diledin.

mayıstı.

seni o yüzden bağışladım! 

ben en çok mayısta su içerim

derinim balık kaynar derinim kanımı kaynar

ben en çok mayısta öne eğerim başımı

içimden felçli bir göçebe gökyüzüne bakar.

avuçlarımda yaralı kelebek taşımayı

mayısta öğrenmiştim; 

ve teraslarda bach dinlemek en çok mayısa yakışırdı

ve kim bilir

mayıs artık en çok senin tanrılarına yakışır

tiril tiril bembeyaz bir giysiyle

             rüzgarda ayakların çıplak

öyle başın öne eğik yıllarca o boş terasta durmak

kartpostallardan tanıdığın bir şehri düşünmek gibi

bir yaraya kabuk olmayı kabullenmek gibi

eksik, yarım, farkına varmaktan kaçınılan

tam

tam yaza girecekken

yazın omzuna yüzünü dayayacakken

çekip giden

ayaklarının altından o son sığınak terası da 

acılarının veliahtı bach''ı da çekip

gitmiştir işte, yalnızca gitmiştir

yani.. anlıyor musun.. mayıstı..

seni o yüzden bağışladım! 

bir sesim vardı gölgenden ikmale kalan

biliyorum, büyük çocukluktu birbirimizi sevmemiz

cesaret işiydi, delikanlıcaydı,

bu korkunç sevgide

     yanlışlarımızı yeniden keşfedişimiz

el deymemiş yalnızlıklara kalkışmamız

yalnızlıklarımızı değiş tokuş etmemiz

bu evcilik oyununda bile duldum

hatırla

sana dizlerimi

sana tabi bileklerimi ve topuklarımı sundum; 

çevirdikçe ruhunun radyo dalgalarında

cazdı, bluesdu, klasik kemandı, klasik aşktı

boktu püsurdu

hatırla, senin gözlerin çokulusluydu

senin gözlerin ham kadınsızdı

çamurdandı

ağzımda getirdiğim karsuyunu

kalbine kaçırdım! ovdun ve okşadın beni

çıktı içimdeki cin

yatağa döküldü

             yatağıma döküldün

                              yatağına döküldüm

ve bu sonsuz savruluşta

o gece 

bütün eski sevgililerimden ince ince söküldüm! 

senin oldum! 

ihanetinle pislenen küçük dolaşımımdaki kanla

karalar çekerek ölümsüz kirpikdiplerine senin

senin mahşer atlısı dudaklarına

en çok da dudaklarına sokuldum! 

üşüyordum,

üstüme doğru çekip o kedi dudaklarını

bir tay sığınırcasına anasına

bana ölünle uyudum! anlıyor musun.. işitiyor musun..

cesedine yeni baştan hayat verebilmek için

ihtiyarladım.. ihtiyarladım..

ben zaten kendimi aşklarda

hep kalkışılınmış müşiş intiharlarla yaraladım! 

koştum sürekli

bir hüzünden bir tersliğe dokunarak koştum

bazı sevdalarda hafızasını kaybeder ya insan

telaşlanır, ağlar

babasını sorar çevresindekilere

                  öldüğünü bildiği halde

adını unutur, yolunu kaybeder oturduğu evin

bir titreme gelir yerleşir ya ortasına mayısın

bir dikilir bir çöker ya

kalbine secde eden intikam

tam

tam yaza girecekken

yaza bir ekmek bıçağı tutuşturacakken

sapı plastik kötü bir ekmek bıçağı

-geri döner.. döner değil mi.. diye

birkaç kırık sözcük.. buruşuk..

-öldürürüm o zaman, kurtulurum.. deyip sustuğun

-kaçarım sonra, kimse sormaz.. deyip yığıldığın

nisandan hazirana doğru bir su kayakçısı

gibi süzülürken mayıs, ah bach! 

ah benim bir kangurunun cebine yerleştirdiği yavrum! 

talanım! artanım! eksik kalanım! yarım kalanım! 

nasıl yedirirdim ihanetini kendime

o dev hisle sen mayıstın ben mayıstım

herşey ama herşey elele mayıstı

seni o yüzden bağışladım! 

uzanıp topraktan çıkardın beni

tozumu sildin, hohladın, parlattın

ovdun ve okşadın beni

çıktı içimdeki cin; 

ondan

-gidecektin, mecburdun, hepsi gibi-

affını diledin.

mayıstı.mecburdum.

seni o yüzden bağışladım!', 'aklım, haklıyım, et firarını!  ovdun ve okşadın beni çıktı içimdeki cin;  ondan ölümümü diledin. mayıstı. seni o yüzden bağışladım!  ben en ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":104,"source_url":"https://www.antoloji.com/kanli-masal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sormuyorum Artık', 'sormuyorum-artik-ahmet-telli-avwts', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sesim soğuk bir sis

Gittikçe grileşen dalgınlıklar oluyor

Sormuyorum bir yolculuğa kimle çıkılır

Ve kim yırtıp atabilir elindeki son dönüş biletinide 

Tüm yalnızlıkları mümkün kılan birileri olmalı

Yada kalbini kederle onaran bir göçebe 

Özlemek ozaman bir çığlık olabilir belki, bir çığlık

Sormuyorum artık biliciyede bilginede 

Aşkın darası nedir

Ve mutsuzluk mümkünmüdür ki o,

Bir kırlangıç ikindisiydi belkide,gümüşte ve hüzne gizlenen

Ödünç sevişlerden bize kalan sonsuz grilikler oluyor yalnız

Ve bir çocuğun hüznüne kazınıyor ,gülüşlerimizin paramparçalığı

Sesimin sislenmesi bundandır

Karşılığı yok hiçbir acının

Herşey gölgesi kadar ağır

Sormuyorum artık sormuyorum

Hergün yeniden kodlanan umutlarla kirletiliyor dünya', 'Sesim soğuk bir sis Gittikçe grileşen dalgınlıklar oluyor Sormuyorum bir yolculuğa kimle çıkılır Ve kim yırtıp atabilir elindeki son dönüş b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sormuyorum-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-i-smail-yesilbas-wm3fg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Daha yolun başındayım

Bir yaşında

Tüm vasiyetim sevgimdir.

Elveda dostlara...', 'Daha yolun başındayım Bir yaşında Tüm vasiyetim sevgimdir. Elveda dostlara......', ARRAY['Türk Edebiyatı','Şiir','İsmail Yeşilbaş']::text[], 8.5, '{"poet":"İsmail Yeşilbaş","poet_slug":"i-smail-yesilbas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat Sabahın Altısı', 'saat-sabahin-altisi-fatih-i-stanbullu-lexpq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saat sabahın altısı,

aklımda sen varsın,dışarıda yağmur.

İki damla göz yaşı akıyor,sana olan hasretimden.

Bide mahrum ya ellerim ellerinden,

işte bu yakıyor yüreğimiderinden,

Baş başa kalmak, bir anlam çıkarmak isterken gözlerinden

yaşlarımı siliyorum elindeki mendillen.

İşte bu yüzden sıyrılmak istiyor ruhum bedenimden,

Saat sabahın altısı, bir volkan taşıyor  yüreğimden,

yağmuru bile hisset miyorum yolda yürüken.

Aklımda sen , içimde sen,her par çamla seni hissederken,

ağlıyorum.

Saat sabahın altısı

gecer ken sensiz öksüz kalmış sokaklardan,

sanki her şey seni çağırıyor. 

Çaresiz kalıyor duygularım,

vefasız oluyor umutlarım,

çöküp bir köşeye, ağlıyorum.

saat sabahın altısı........', 'Saat sabahın altısı, aklımda sen varsın,dışarıda yağmur. İki damla göz yaşı akıyor,sana olan hasretimden. Bide mahrum ya ellerim ellerinden,...', ARRAY['Türk Edebiyatı','Şiir','Fatih İstanbullu']::text[], 8.5, '{"poet":"Fatih İstanbullu","poet_slug":"fatih-i-stanbullu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/saat-sabahin-altisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutup Yıldızı', 'kutup-yildizi-fatih-i-stanbullu-49nio', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün geceyıldızlarla arkadaş olduk.

Bana bir iyilik yaptılar.

Gecenin karanlığında ismini göğe yazdılar.

Ve buna  KUTUP YILDIZI adını verdi insanlar...

Sonra gece,ay ve denizde geldi yanıma.

onlarda gece karanlığında denize yazdılar ismini

bunada YAKAMOZ dendi', 'Dün geceyıldızlarla arkadaş olduk. Bana bir iyilik yaptılar. Gecenin karanlığında ismini göğe yazdılar. Ve buna  KUTUP YILDIZI adını verdi i...', ARRAY['Türk Edebiyatı','Şiir','Fatih İstanbullu']::text[], 8.5, '{"poet":"Fatih İstanbullu","poet_slug":"fatih-i-stanbullu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kutup-yildizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yalnizlik', 'yalnizlik-umut-mat-7mir7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dokunsalar aglayacaktım

Aglasam rahatlayacaktım

Yalnızdım...

Aglayamadım

İstanbul/2000', 'Dokunsalar aglayacaktım Aglasam rahatlayacaktım Yalnızdım... Aglayamadım İstanbul/2000...', ARRAY['Türk Edebiyatı','Şiir','Umut Mat']::text[], 8.5, '{"poet":"Umut Mat","poet_slug":"umut-mat","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz Her Gece', 'sensiz-her-gece-sair-pureguy-x3rk6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece yine karanlık elbiselerini giymeye başladı.

Bugünüm de sensiz geçti.

Yine olağan şeyleri yapacağım yatmadan önce 

Sana dair ve bana dair dualar edeceğim bu gecede.

Sonra oyuncağı elinden alınmış çocuklar gibi ağlayacağım 

Sessizce.', 'Gece yine karanlık elbiselerini giymeye başladı. Bugünüm de sensiz geçti. Yine olağan şeyleri yapacağım yatmadan önce  Sana dair ve bana dai...', ARRAY['Türk Edebiyatı','Şiir','Şair Pureguy']::text[], 8.5, '{"poet":"Şair Pureguy","poet_slug":"sair-pureguy","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sensiz-her-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-sair-pureguy-aqr4n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '- manolyama -

seni seviyorum,

çünkü seni sevmeyi seviyorum

seni seviyorum çünkü  ,sadece seni sevmeyi biliyorum

seni seviyorum çünkü ,

seni severken yaşamayı seviyorum

seni seviyorum çünkü,

seni sevmem gerekdiğini hissediyorum,

seni seviyorum çünkü, seni severken sevmeyi seviyorum.

Seni seviyorum çünkü, sana seni seviyorum demem gerek

Seni seviyorum...', '- manolyama - seni seviyorum, çünkü seni sevmeyi seviyorum seni seviyorum çünkü  ,sadece seni sevmeyi biliyorum seni seviyorum çünkü , seni ...', ARRAY['Türk Edebiyatı','Şiir','Şair Pureguy']::text[], 8.5, '{"poet":"Şair Pureguy","poet_slug":"sair-pureguy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/seni-seviyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön Kara Gözlüm', 'don-kara-gozlum-ahmet-ucmak-nkyz5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O mahmur bakışın sinemi deldi.

Bırak ağlamayı gül kara gözlüm.

Firakınla gönlüm biharab oldu,

Bitir şu hasreti dön kara gözlüm.

Güller hazar oldu yeşil bahçemde,

Bu divane gönlüm yine matemde.

Tüm dertlerim biter gelsen şu demde,

N''olur anla beni dön kara gözlüm.

Bu garip huzuru sende bulurdu,

Gülüşünle dünya onun olurdu.

Bir buseye sana  canın verirdi,

Yalvarırım artık dön kara gözlüm.', 'O mahmur bakışın sinemi deldi. Bırak ağlamayı gül kara gözlüm. Firakınla gönlüm biharab oldu, Bitir şu hasreti dön kara gözlüm. Güller hazar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Uçmak']::text[], 8.5, '{"poet":"Ahmet Uçmak","poet_slug":"ahmet-ucmak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/don-kara-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Usuldan Usuldan', 'usuldan-usuldan-sabit-i-nce-xj0kq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabah oldu gün doğuyor usuldan,

Yine efkar bastı deli gönlümü...

Bıktım usanmadım ben bu fasıldan,

Boşa harcadımda bütün ömrümü...

Her seher her sabah böyle olurum,

Donar el ayağım öyle kalırım.

Ahdim kalmaz vallahi de alırım,

Koymam kapımada zalim ölümü...

Güneş doğdu amma geri batacak,

Hayal çarkı kimi ezip atacak..

Varı yoğu birbirine katacak,

Gene solduracak benim gülümü..

Yeni mi başladı nasıl bitecek,

Zaman suyu akıp nere gidecek.

Nasıl çevrilecek nere dönecek,

Başlayış mı sonu mu bu, önümü...

Zırvalama artık bırak kalemi,

Sen mi düşünürsün koca alemi.

Ayırt edemezsin çürük sağlamı,

İNCE gelir elbet günün dönümü...

5.1.1999 kayseri', 'Sabah oldu gün doğuyor usuldan, Yine efkar bastı deli gönlümü... Bıktım usanmadım ben bu fasıldan, Boşa harcadımda bütün ömrümü... Her seher...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/usuldan-usuldan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostumla', 'dostumla-sabit-i-nce-bvggn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Girdik muhabbet bagina

Caldik söyledik dostumla

Vardik pirler ocagina

Kelam eyledik dostumla

Aski muhabbet tatlidir

Hayat yolu firkatlidir

Kul olanlar hep dertlidir

Figan eyledik dostumla

Söylestik biz telleriyle

Hep yerinde karar ile

Yaralandik biz yar ile

Bir mesk eyledik dostumla

Gönülleri sad eyledik

Gecmisi biz yadeyledik

Bizim türküyü söyledik

Eyi eyledik dostumla

Seherlerde bülbül olduk

Dolanip gecmise daldik

INCE bir cizgide bulduk

Kavil eyledik dostumla

05.01.1999 kayseri', 'Girdik muhabbet bagina Caldik söyledik dostumla Vardik pirler ocagina Kelam eyledik dostumla Aski muhabbet tatlidir Hayat yolu firkatlidir K...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dostumla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avşar Güzeli', 'avsar-guzeli-sabit-i-nce-c18w2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'AR GÜZELİ

Kirpikleri kalem gözleri hurma,

Ben başka görmedim avşar güzeli.

Gözleri süzerek bakışıp durma,

Gönlüm yenemedim avşar güzeli.

Kara gözlerinde zindana girdim,

Direndim dayandım göğsümü gerdim,

Cehenneme götürseydin giderdim,

Kıyıp soramadım avşar güzeli.

Hurilerin hepisini topladım,

Güzelleri söyle bir hesapladım,

Ayıldımda bir kendimi topladım.

Adın soramadım avşar güzeli.

Güneş yere mi''ndi ay mı parladı,

Gönül laf dinlemez inan zorladı,

Dengeyi bozdu da akıl zırladı,

Orda duramadım avşar güzeli.

Sekiz cennet on sekiz bin alemde,

Nasıl yazdı seni levhi kalem de? 

Güzelliğin parça parça bölem de,

El''e veremedim avşar güzeli..

Eşin menendini görmedim billah,

Seni hangi nurdan yarattı allah? 

İNCE aşk elinden dedi illallah,

Ondan sevemedim avşar güzeli..', 'AR GÜZELİ Kirpikleri kalem gözleri hurma, Ben başka görmedim avşar güzeli. Gözleri süzerek bakışıp durma, Gönlüm yenemedim avşar güzeli. Kar...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/avsar-guzeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'dost', 'dost-sabit-i-nce-6omh5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acı danslar raksediyor gözümde,

Uyku girmez oldu gözlerime dost.

Bir ateş ki sönmez yanar özümde,

Derman gelmez oldu dizlerime dost.

Kahbe felek hallerime gülüyor,

Sanki bir nefeste bini ölüyor.

Ben kaçtıkça o üstüme geliyor,

İman etmez oldu sözlerime dost.

Kara bahtım kör talihim elinden,

Akort tutmaz ses çıkmıyor telimden.

Fizan ülkesinden Yemen çölünden,

Alev yetmez oldu közlerime dost.

Aşkın kemendini boynuma attı,

Cehennem harıyle özüm dağlattı.

Öncüler cıkartıp yolum bağlattı,

Teller ötmez oldu sazlarıma dost.

Seherlerde bülbül gibi öttürdü,

Karen ellerinde koyun güttürdü,

Nem var ise haraç mezat sattırdı,

Taşlar yetmez oldu tuzlarıma dost.

Karakuşak girdim bitmez güreşe,

Derdim anlatamam aya güneşe,

Akıl sır ermiyor bu INCE işe,

Kulak vermez oldu nazlarıma dost.

25.12.1998 kayseri', 'Acı danslar raksediyor gözümde, Uyku girmez oldu gözlerime dost. Bir ateş ki sönmez yanar özümde, Derman gelmez oldu dizlerime dost. Kahbe f...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yoruldum', 'yoruldum-sabit-i-nce-7bdcm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Su fani dünyaya geldim geleli,

Bir sevda pesinde kostum yoruldum.

İnsan olup kendim bildim bileli,

Azgin seller gibi costum duruldum.

Sevgi sevgi diye türküler yaktim,

Sevda ülkesinde ben bir duraktim.

Nem var nem yokise size biraktim,

Sarmasik misali actim sarildim.

Bir güzel görünce figanim artti,

Askin kantarina cikarip tartti.

Kum tanesi gibi sacti firlatti,

Sevda cöllerinden astim yoruldum.

Kırkbesinde koca belim büküldü,

Saclarim yolundu tel tel döküldü.

Umutlarim iplik iplik söküldü,

Buzdaglari gibi dondum kirildim.

Hayat penceresin kapayip actim.

INCE bir han idi cok gelip gectim.

Sevda irmagindan bir zerre ictim,

Vefasiz bir yare taptim vuruldum.

(Kayseri)', 'Su fani dünyaya geldim geleli, Bir sevda pesinde kostum yoruldum. İnsan olup kendim bildim bileli, Azgin seller gibi costum duruldum. Sevgi ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yoruldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yapayım', 'ne-yapayim-sabit-i-nce-bw3h0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dünya girdabına attin firlattin,

Bu girdabda ne yapayim sevdigim.

Kolay kil dedikce sen hep zorlattin,

Zor dünyada ne yapayim sevdigim.

Dünya mesakkatli cile yeridir,

İnsani bitirir yakar eridir.

Lesini cöllerde cakal sürüdür,

Ben cöllerde ne yapayim sevdigim.

Seni sevdim her nazina katlandim,

Yaya yürüttürdün sonra atlandim,

Beni sever diye cok umutlandim,

İlahim ol gel tapayim sevdigim.

Yeter artık cevri cefa nazlarin,

Sayisizmis ördeklerin kazlarin.

Huri gilmanlarin bakir kızlarin,

Senin olsun ne yapayim sevdigim.

Biliyorum günah benim suc benim,

Cana can gelince seni sevenim.

Dilimle gönlümle seni överim,

Bundan baska ne yapayim sevdigim.

Bir canim var ister isen al gitsin,

Kainatda senin ocagin tütsün.

Cemalin seversen bu oyun bitsin,

İNCE petek bal yapayim sevdigim.

11.08.1998 kayseri', 'Dünya girdabına attin firlattin, Bu girdabda ne yapayim sevdigim. Kolay kil dedikce sen hep zorlattin, Zor dünyada ne yapayim sevdigim. Düny...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ne-yapayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'gulum', 'gulum-sabit-i-nce-yz8lz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kadehlerde yudum yudum

Seni içiyorum gülüm

Kalmasada hiç umudum

seni seçiyorum gülüm

Koklamaya kıyamadım

Sevgine hiç doyamadım

Kaç yıl geçti sayamadım

Seni seviyorum gülüm

Arayıp sormasan bile

Uğraşlarım hep nafile

Sen yaşa tek güle güle

Seni istiyorum gülüm

Yıllar oldu neredesin

Bilmem şimdi kiminlesin

Bilmiyorum ne haldesin

Seni kokluyorum gülüm

İnce közde yanıyorum

Seni benim sanıyorum

Hep kendimi sınıyorum

Seni bekliyorum gülüm

24.12.1998', 'Kadehlerde yudum yudum Seni içiyorum gülüm Kalmasada hiç umudum seni seçiyorum gülüm Koklamaya kıyamadım Sevgine hiç doyamadım Kaç yıl geçti...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tahiroğlu', 'tahiroglu-sabit-i-nce-dztg7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çobanoğlu''nun yerine,

Çıktık geldik Tahiroğlu,

Şu dünyanın ayarına,

Baktık geldik Tahiroğlu.

Bu dünyanan cennetine,

Bakıp kaldık hayretine.

Ozanlığın niyetine,

Yaktık geldik Tahiroğlu.

Efelerin diyarına,

Şu Simav''ın dağlarına,

Akıp giden çağlarına,

Çıktık geldik Tahiroğlu.

14.5.2000 AliFakı köyü', 'Çobanoğlu''nun yerine, Çıktık geldik Tahiroğlu, Şu dünyanın ayarına, Baktık geldik Tahiroğlu. Bu dünyanan cennetine, Bakıp kaldık hayretine. ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/tahiroglu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başıma', 'basima-sabit-i-nce-ky0ez', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Erciyes başında kar var, bora var

Yüreğimde bir kapanmaz yara var.

Ne arayıp, ne hatırım soran var,

Yuvasız kuş gibi kaldım başıma,

Denizler dayanmaz şu gözyaşıma.

Erciyes bir gelin salınır durur,

Zirvesinde garip gönlüm oturur,

Esen yeller senden selam getirir,

Yuvasız kuş gibi kaldım başıma,

Denizler dayanmaz şu gözyaşıma.

Bülbül idim diken battı gülüme,

Kanlı mendilimi bastım gönlüme,

Aşk atını sürdüm kattım önüme,

Yuvasız kuş gibi kaldım başıma,

Denizler dayanmaz şu gözyaşıma

28.5.2000 kayseri', 'Erciyes başında kar var, bora var Yüreğimde bir kapanmaz yara var. Ne arayıp, ne hatırım soran var, Yuvasız kuş gibi kaldım başıma, Denizler...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/basima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eyledi', 'eyledi-sabit-i-nce-1kqox', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İkibin mayısın on ikisiydi,

Simav''ı bir ordu işgal eyledi,

Bu nasıl istila, neyin nesiydi,

Mitoloji bile hayret eyledi.

Asım Kısbet pos bıyıklı dost idi,

Bu ne nefis tablo, ressam kim idi,

Şairi çoşturan bu dağlar mıydı,

İlk defa gelenler feryat eyledi.

Mustafa yılmazla, Memduh Şenollar,

TGRT FM Birsen yamaklar,

Sevgiyle süslenmiş yangın dudaklar,

Çok aşığı yaktı zulmet eyledi.

Mine-Osman çifti ateşe gibi,

Şiirler, şarkılar muhteşem idi.

Sekizinci dedim, harika dedi,

Hele birisi var Ferhat eyledi.

Tayyar hoca Akçeken''i ararken,

Kimi pot üstüne potlar kırarkan,

Soyuer, soygüder, Mutlular varken,

Bazı şairler de berbat eyledi.

Satoğlu, Yurdabak, filozof doktor,

Keyifler yerinde oh ki ne oh oh.

Kütahya, Simavli kavgası çoh çoh,

Zehir kusan dudak dehşet eyledi.

Fırça yok ki renklerini göstersem,

Ela, yeşil, mavi neler istersen.

Anı mı, fıkra mı, şiir mi dersen

İNCE''ledi, yazdı derdest eyledi.

14.5.2000 5. Simav şairler şöleni', 'İkibin mayısın on ikisiydi, Simav''ı bir ordu işgal eyledi, Bu nasıl istila, neyin nesiydi, Mitoloji bile hayret eyledi. Asım Kısbet pos bıyı...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/eyledi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyorum', 'diyorum-sabit-i-nce-od30w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-Aşık Seziniye- 

Çok bekle ki güleceksin,

Bunu böyle bileceksin.

Sen de böyle öleceksin,

Diyorum sana Sezini.

Sevda dediğin hayalle,

Uğraştın evlat, iyalle,

Kendini aldat o yolla,

Diyorum sana Sezini.

Yar dediğin yar mı ola,

Öyle biri var mı ola

Kimler öle, kimler kala,

Diyorum sana Sezini.

Demek yaş ile yoruldun,

Bilmem ki neye sarıldın,

Eğilmedin ya , kırıldın

Diyorum sana Sezini.

Hep yarınları bekledin,

Dert üstüne dert ekledin,

Hep yar diye pinekledin,

Diyorum sana sezini.

Çileler son bulacak mış,

Söyle bana nolacak mış,

Say ki adın kalacak mış,

Diyorum sana Sezini.

Çatlasa da sabır taşı,

Acı olur onun aşı,

İNCE'' dir dünya telaşı,

Diyorum sana Sezini.

31.5.2000 kayseri', '-Aşık Seziniye-  Çok bekle ki güleceksin, Bunu böyle bileceksin. Sen de böyle öleceksin, Diyorum sana Sezini. Sevda dediğin hayalle, Uğraştı...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/diyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz mı Sandın', 'olmaz-mi-sandin-sabit-i-nce-f0zb4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çile ile geçen ömür yolunda,

Güz gelirde güller solmaz mı sandın.

Hangi çicek kaldı kendi dalında,

Bir hoyrat el değip yolmaz mı sandın.

Boşuna ağlama, boşa da yanma,

Dost gibi söylenen söze aldanma.

Nefsine hoş gelen güzele kanma,

Seni tek başına koymaz mı sandın.

Kurulan tuzağı sezerim sanma,

Uğruna canını verse inanma.

İNCE şu girdap da boşa dolanma,

Kuduran bir dalga almaz mı sandın.

kayseri 18.5.2000', 'Çile ile geçen ömür yolunda, Güz gelirde güller solmaz mı sandın. Hangi çicek kaldı kendi dalında, Bir hoyrat el değip yolmaz mı sandın. Boş...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olmaz-mi-sandin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gardaşım', 'gardasim-sabit-i-nce-aj8j9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-ömer Albayrak''a-

Ne kadar densiz donsuz olsa da,

Vatan, millet diyen bitmez gardaşım,

Düzenbazlık, hilebazlık çoksa da,

Doğruluğa hiç güç yetmez gardaşım.

Örf, adet, anane ölmez biz varız,

Türk''ü, Kürdü hep beraber yaşarız,

Biz herşeyden önce insan ararız.

İnsanlığın nesli bitmez gardaşım.

Düzeni düzse de o düzenbazlar,

Rejime göz koysa ırkçı yobazlar,

Kırk elekten geçse şu hokkabazlar,

Bil ki boruları ötmez gardaşım.

Beynelmilel ajan dolsa da yurda,

Nice kanlar döktük biz bu uğurda,

Laik, yobaz, marksist herşey olsa da,

Cennet yurtta baykuş ötmez gardaşım.

Nerden geldik, kimliğimiz bellidir,

Sazlarımız vardır sırma tellidir,

Aslımı sorarsan Türkmek ellidir,

Çalışır durmadan yatmaz gardaşım.

Biliyorum sıla derdi çekersin,

Sitem edip sen belimi bükersin,

Gülbahçeye neden diken ekersin,

Anasam''a ayrık tutmaz gardaşım.

Bilirim ben dost, dostunu sorardı,

Arayı uzatmaz tezden arardı.

Bir düş görse onu hayra yorardı,

Ne deseler o kül yutmaz gadaşım.

Başımda boran var, dardayım darda,

Yaz hele kağıda neler var orda.

Yolunu bekleriz biz ilkbaharda,

İNCE kelam efkar atmaz gardaşım.

27.5.2000 kayseri', '-ömer Albayrak''a- Ne kadar densiz donsuz olsa da, Vatan, millet diyen bitmez gardaşım, Düzenbazlık, hilebazlık çoksa da, Doğruluğa hiç güç y...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gardasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diye Diye', 'diye-diye-sabit-i-nce-kf7hm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anadolu diye diye,

Düştüm yollara, yollara.

Anasam olsun hediye,

Verdim kullara, kullara.

Gece gündüz yorulmadım,

Hiç kimseye darılmadım.

Eğilmedim, kırılmadım,

Girdim hallara, hallara.

Kimi dedi, deli misin

Cahil misin, Ali misin?

Şu ışığın pili misin,

Vurdum dallara, dallara.

Kiminin çıkarı bitti,

Kimileri oyun etti,

Dedim bu iş cana yetti,

Sordum güllere, güllere.

Can dostlarım destek oldu,

Coğunun renkleri soldu,

Herkesin muradı oldu,

Sardım kollara, kollara.

Vasiyetimdir dostlara,

Yer vermeyin o astlara,

Çıkarın ki en üstlere,

Yardım ellere, ellere.

İnce dileğini söyle,,

Allahım hep yardım eyle,

Bir arzudur bitti böyle,

Verdim sellere, sellere..

31.5.2000 kayseri', 'Anadolu diye diye, Düştüm yollara, yollara. Anasam olsun hediye, Verdim kullara, kullara. Gece gündüz yorulmadım, Hiç kimseye darılmadım. Eğ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/diye-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sezini', 'sezini-sabit-i-nce-5ekot', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşk yolunda gideriken

Gördüm sezini, sezini.

Dostla ben çenk ederiken

Vurdum sezini, sezini.

Bilirim aman vermedi,

Aşık olan hiç gülmedi.

Hiç kimse gülü dermedi,

Sordum sezini, sezini.

Harabî Âma da buldu,

Ferhat ki o dağlar deldi.

Mecnun da Leyla da bildi,

Çöl''düm sezini sezini.

Sanma ki çilen bitecek,

Bekleme, bülbül ötecek.

Bu nar herkese yetecek

Közdüm sezini, sezini.

Su da balık gibi gördüm,

Düşte görüp hayra yordum,

Bir yere geldim de durdum,

Yozdum sezini, sezini.

Ne ararsan hep sendedir,

Onda, bunda ve bendedir.

Sor, ara her nedendedir,

Gezdim sezini, sezini.

İNCE''yim ince söyledim,

Yakaladım da peyledim.

Oynadım gönlüm eyledim,

Yazdım sezini, sezini.

31.5.2000 kayseri

Dostla ben çenk ederiken

Vurdum sezini, sezini.

Bilirim aman vermedi,

Aşık olan hiç gülmedi.

Hiç kimse gülü dermedi,

