INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevdiğim İçin', 'seni-sevdigim-i-cin-celal-kabadayi-q7jj1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'özgürlük tadına doyulmaz pınardı

başıma gelmedik dert kalmadı

suyundan içtiğim için

nice nice sevgilere gidecektim

savaşlar yoluma taş koydu

barışı seçtiğim için

ne kitabım var ne peygamberim

tanrılarsa çoktan terketmiş beni

dinsiz olduğum için

herkesin para için çıldırdığı çağda

işe yaramaz dediler bana

yazıp çizdiğim için

yüreğimi eğittim şiirlerle romanlarla

gücümü yaşamdan aldım

kötüleri yenmek için

yoksulluk çektim yalnızlık çektim

katlandım aşkın da acısına

seni sevdiğim için', 'özgürlük tadına doyulmaz pınardı başıma gelmedik dert kalmadı suyundan içtiğim için nice nice sevgilere gidecektim savaşlar yoluma taş koydu...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seni-sevdigim-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzakta Bir Akşam', 'uzakta-bir-aksam-celal-kabadayi-digwz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'akşamın kapısına dayandım

bütün ışıklar sensizliği yanıyordu

cırcır böcekleri delerken sessizliği

benim sesim soluğum tıkanıyordu

perdeler çekilmemişti odalarda henüz

gözlerim taradı tek tek evleri

birinin içinde olayım istedim

ana sevgisi,ev yemeği,arkadaşlar

ve bekleyişlerle güzelleşen sevgili yüreği

uzak olan ne varsa canımı yakmıştı

gecenin kapısına dayandım

uykular ürkek bir yalnızlığa bürünmüştü

bir yer aradım kendime

bütün ışıklar beni sönmüştü', 'akşamın kapısına dayandım bütün ışıklar sensizliği yanıyordu cırcır böcekleri delerken sessizliği benim sesim soluğum tıkanıyordu perdeler ç...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uzakta-bir-aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günün', 'dogum-gunun-i-nan-arslanbogan-91dge', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugünmü dogdun ?

Doğum Gününün

Şimdi sen bugün mü doğdun kanlar içinde?

Yani bugün bilmediğin bu saatte 

Anan iki kat çay dökerken ve sana kanarken...

Soluk alıyorsun ana rahmine düştüğün ilk andan itibaren 

Soluk alıyorsun ortaokul 

Soluk alıyorsun baban ölür 

Soluk alıyorsun zindan

Soluk alıyorsun sevgilinin dudakları 

Soluk bir resme bakıyorsun ailen bir yanda, bir yanda sen 

Ve sana dair ne varsa...

Yani şimdi sen bugün mü doğdun?

Bugün mü öleceksin?

Yaşadığın kadar gülecek misin?

Yada adam gibi biriyle evlenebilecek misin?

Bilemezsin güzelim 

Bir tarafta güzel bir güneş doğar ama karanlık 

Peki ya bu Ay ’ a ne demeli bu karanlığın içinde doğan güzelim Ay ’ a

Bu karanlığın içinde neden bu kadar aydınlık

Yada neden sarhoşken söylenir güzel sözler 

Ben pek yapamam sen sürekli can simidi

Gitmekte var kalmakta 

Hayatı insanca yaşamakta 

Sen şimdi bugün mü doğdun?

Cebinde beş parasız

Cebin yine astarınla baş başa 

Ve benim cebimde beş kuruş yokken 

Yani cebim astarla sevişirken

Yani şimdi bu saatte sen doğmak zorunda mısın?

Seni buyur etmek istedim soyadıma 

Benden önce davrandın 

Haylaz çocuk gibi bu işi bile bana bırakmadın 

Film değil yaşanan

Yangın dolu kalbim 

Yanımda çocuğumun annesi olacak kadın 

Film değil yaşanan

Aşkta var sevinç ,gözyaşı, sigarasız ,çaysız zifir gibi karanlık ayrılmak, kaçmak kovalamak, ve belki kokmuş çoraplarda 

Kavga dövüş , ve birde rüya gibi yaşamakta 

Bellimi güzelim 

Bu aşk kaadir mi dersin her şeye?

Aşk her zaman şarkılar gibimi? 

Hiç kamburu çıkmaz mı dersin aşkın

Yağmur yarken ağladığın belli olmaz

Çatışırken sokaklarda

Mermin bitmez sanırsın 

Şarjörde biter hayatta

Gemiler bilerek mi oturur karaya 

Şimdi sen bugün mü doğdun?

Sen bir adamı bu saatte mi sevdin 

Bu yılda mı seviştin gözlerini kapatırken 

Ve birileri işkencede çığlık atarken 

Ağzı köpürürken diğerlerinin... 

Ve bilmem neredeki adamın ciğerini deşerken mafya 

Yada gazeteciler birilerini sürekli baş sayfalara taşırken 

Bazıları kör sokakta şarabını iyi bir devirirken 

Düşünmeden nerede yatacaklarını 

Ve aslında bildikleri, kaldırımın yine onlara döşek olacağı ve yazılan bir ton ıvır zıvır gazetenin onların yorganları olacağı 

Gecenin köründe polisin o adamı alacağı ve çığlık atarken polislerin köpekçe sulanan ağızları...

Yani bu geceyi mi seçtin 

Sevdin ve seviştin... 

Saçında kepeğinde oldu yüzünde sivilcende 

Eline elde değdi gözüne gözümde 

Sigaranın dumanı gibi gittiğinde oldu zıplaya hoplaya döndüğünde

İlk aşkını unutmadın, ilk eylemini, ilk öpüldüğün zamanı da 

Yani sen şimdimi doğdun? 

Yani bu saatte mi? 

23 yaşına bastığında 

Ve pastanı keserken 

Hediye veremeyen bir sevgiliye bakarken 

Pastanı yiyen sonrada yanına  bir yağmur gibi fütursuzca göğsüne uzanan 

Ve kabuslar içindeyken seni uyandıran 

Ağzı içki kokan 

Bir buçuk yıl ayrı kalacağın adamdan hediye almadan 

Yani sen şimdi bugün mü doğdun 

Yani bu gün mü? İnsan oldun 

Nice yıllara sevdiğim kadın, çocuğumun annesi 

İyi ki insan oldun ve iyi ki, iyi ki doğdun', 'Bugünmü dogdun ? Doğum Gününün Şimdi sen bugün mü doğdun kanlar içinde? Yani bugün bilmediğin bu saatte  Anan iki kat çay dökerken ve sana k...', ARRAY['Türk Edebiyatı','Şiir','İnan Arslanboğan']::text[], 8.5, '{"poet":"İnan Arslanboğan","poet_slug":"i-nan-arslanbogan","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/dogum-gunun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekler Kolay Ölmez', 'cicekler-kolay-olmez-celal-kabadayi-uymj9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'siz alsanız da satsanız da

çiçekler kendini satmaz

onca ağlar ağlar da 

çiçekler kimseyi ağlatmaz

renkleri gerçeğin rengidir

çiçekler yalan söylemez

açlıktan susuzluktan solsalar da

çiçekler insanı sömürmez

özgürlükle güzelleşir çiçekler

umutsuz uykulara yatmaz

dillerin en güzelini konuşur da

çiçekler gürültü yapmaz

suyunu kesseniz yapraklarını sonra

güneşsiz hücrelere kapatsanız

dalından koparsanız,ezseniz bile

çiçekler kolay ölmez', 'siz alsanız da satsanız da çiçekler kendini satmaz onca ağlar ağlar da  çiçekler kimseyi ağlatmaz renkleri gerçeğin rengidir çiçekler yalan ...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cicekler-kolay-olmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Gözlerinde Birşey Var', 'senin-gozlerinde-birsey-var-celal-kabadayi-ou26p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'senin gözlerinde bir şey var

bunu yüreğim söylüyor

düşüncelerim çarmıha gerili sanki

dizlerimde nice ordular çözülüyor

seninleyken ateş basıyor bedenimi

gözlerinin kahvesi köpük köpük taşıyor

içimi yakıyor saçlarının kokusu

sen gittikten sonra üşüyorum

senin gözlerinde bir şey var

sanki bir sürgün yurduna dönüyor

bastırılmış bir çığlık gibi sesin

dudaklarından gizli yankısı yükseliyor

işciler greve gidiyor yaşama sevinciyle

gözlerinin bahçesinde çocuklar koşuyor

yağmurlu bir akşam sonrası hüznüyle

liseli gençler acıklı bir şeyler konuşuyor

senin gözlerinde bir şey var

ayla güneş yanyana,sabaha yakın

ağlarsam senin gözlerinle ağlayayım

beni de gözyaşlarına kat,unutma sakın', 'senin gözlerinde bir şey var bunu yüreğim söylüyor düşüncelerim çarmıha gerili sanki dizlerimde nice ordular çözülüyor seninleyken ateş bası...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/senin-gozlerinde-birsey-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Mutlu Oldun mu?', 'simdi-mutlu-oldun-mu-simge-atakan-oahom', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Söyle beni unuttun mu?

Aşkımızı kuruttun mu?

Boşluğumu doldurdun mu?

Şimdi mutlu oldun mu...

Sensiz çok daha güzel dedin

Ellerini kelepçeledin

Unutma sen istedin

Şimdi mutlu oldun mu...

Aşkımdan deli, divaneydin

Ne oldu ki bu noktaya geldin

Duydum ağlar yüreğin

Şimdi mutlu oldun mu...

Herşeyi bilmeni istedim

Kendini harap etme dedim

Herşey boş kendini mahfettin

Şimdi mutlu oldun mu...

Zamanı geçti geriye dönmenin

Sen bunu hiç düşünmedin

Ben çoktan seni sildim

Şimdi mutlu oldun mu...

Ben şimdi çok mutluyum

Sonuna geldim, ufuktayım

Sen benim en eski dostum 

Şimdi mutlu oldun mu...', 'Söyle beni unuttun mu? Aşkımızı kuruttun mu? Boşluğumu doldurdun mu? Şimdi mutlu oldun mu... Sensiz çok daha güzel dedin Ellerini kelepçeled...', ARRAY['Türk Edebiyatı','Şiir','Simge Atakan']::text[], 8.5, '{"poet":"Simge Atakan","poet_slug":"simge-atakan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/simdi-mutlu-oldun-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazin Bir Hikaye', 'hazin-bir-hikaye-i-nan-arslanbogan-7v969', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küçüktüm yalnız kalmamaya yenin edenlerden değildim 

Kolumda plastik bir saat zamanın geçmesini bekliyordum. O zaman ki beni gençliğime götürecek olan o zaman ki yaşadığım çocukluğu silmek üzere olan saatime her baktığımda geçen saniye dakikalara, dakikalar saatlere, saatler günlere günler hayatıma kastediyordu. Bundan sen hoşnut olabilir miydin? 

Bunu bilemezsin 

Ta ki yıllardan sonra 

O bakmaya kıyılmayan 

Yüzünde eskir ve cebinde paran olmaz 

Paran olsa da yanında kimse olmaz 

Başın omzuna yorgunca yaslanırken göz yaşların içine akar 

Kimse görmez seni 

Senin onları gördüğün gibi 

Artık benim için o iç gıcıklayan müzik demetleri yoktur

Yada beatles’ ın yesterday’ i zaten mayakovsky de intihar etmiştir 

Eski bir şair aklıma gelir, 

Ta eskilerde kalmış 

Belki kızıllığından ötürü  geçmiştir 

Usta derlerdi ona 

Ben akraba derim ustaya 

Kızıllığımız aynıdır bu saatten sonra 

İkisi de geçmiştir nasıl olsa

Aynı plastik saatimin yaşamın sonuna doğru ilerlemesi gibi 

Bunu bilerek yapmadı zavallı o sadece işini biliyordu 

Ve yorulmadan belki bizlerden daha fazla isteklice 

İşini yapıyordu. 

Fotoğraflarım şimdi tam yanımda 

Şu kırmızı sepetin içinde duruyor 

Her sabah kalktığımda bir fotoğrafı koyuyorum 

Tam hasta yatağımın karşısındaki 

Yani beni yıllarca sırtında taşıyan 

Beni sensiz gecelerce aynı senin gibi saran 

Canım yatağımın karşısındaki tahta iskemlenin üzerine 

Koyuyorum...

Şimdi sen bana hak verebilir misin?

Şimdi seni ilk öptüğüm gün yada gece 

Her neyse...

Benim için her öpücük ilk zaman

          yani saatin ilerlememesi 

          yani orada hayatın durması 

          alabildiğine sıcaklık 

ve gül kokan memeler 

Artık geriye dönmekte olmaz 

Yatmanın tam sırasıdır

Yani hayatı tamamen bizim için durdurmanın...

İşte böyle... 

Bir dağ gibi yaşamak kolay mı sanıyorsun? 

Bir maden gibi 

Tehlikelerden uzak mı kalacağını sanıyorsun 

Gece ben yürürken

Kaç kez arkama bakarım bunları bilmiyorsun 

Ve dünyanın en kötü yerinde yaşadığımızı 

En boktan zamanında seviştiğimizi bilmiyorsun 

Kokular yükseliyor tehlikeler yamacına yaklaşıyor 

Bir dağ olmaya çalışanın 

Bin yıldır buralardayım bin yıldır aşık 

Bin yıl diyorum 

Bin yıldır savaşan 

Kolay mı sanıyorsun? 

Giden bir saniyeyi geri getirmek 

Bak Beyazıt hala yalnız 

Neler gördü bir başına 

Kendine rağmen

Soluk verdi onların sesine 

Kaç kez suratına kanlar sıçradı

Her 16 martta 

Beyazıt kan ağlar 

Kan diyorum kan kan kan...     

Zaman böyle geçiyor işte 

Benim zamanım

Geçiyor işte 

Bir hazin hikaye 

Bana hak veriyor musun?

Bak çok önemli değil hak versen de olur verme sende 

Beni anlıyorsun değil mi?

Bir arkadaşım var

Şimdi  odamda vızıldıyor 

Sen tanımazsın ben yeni tanıştım 

Penceremi açtım güneş girsin diye bir baktım güneşle beraber o da geldi beni ziyarete ve o gündür peşimde 

Kim mi? Küçük bir arı  

Anladı onu bırakmayacağımı 

Bana da hayli kızgın onu esir aldım 

Beni sokmaya çalışıyor bazı zamanlarında 

Ama ben kaçıyorum 

Biraz kaçıyorum biraz kovalıyorum 

Bazen ona üzülüyorum 

Pencereyi açıyorum gitmek istemiyor 

Gitmek istese açık pencereden çıkmaz mı?

Yani senin gibi kapıyı çarpıp kaçmaz mı?    

Başlarken olur mu demiştik ?

Olur mu acaba? 

Hiç olmayacakmış gibi gelen şeyler bir çırpıda oluyor 

Bunu bilmediğimden değil 

Bilirim aşık olmasını çelik suyuna eşdeğer 

Bilirim kaçamak bakışları, sesiz sokakta beklenen gibi

Bilirim aldatmasını zar zor yaşamayı becerdiğim gibi 

________             ________          _________    

Şimdi gece yarısı oldu 

Tam gecenin yarısı ve şarkılar çalınıyor kulaklarıma 

Sensizliğin şarkıları 

Zaten hep böyle olmaz mı ?

Değiştik artık her yaşta aşk başka yaşanıyor 

Yaş otuz beş değil ama yolun yarısı gibi 

Yada geçti...

Elini tutmak güzeldi 

Soluğundan dünyaları yaratmak 

Gözyaşında en demli zamanları geçirmek 

Ve sıcaklığın bana yadigar kalan 

Yaşanmaz mı? sanıyorsun sensizliğinde

Yaşanıyor ellerin olmadan 

Dünyasız, demsiz, 

Yadigarsız.... 

                                                                   30.mayıs.2000 

                                                                          00:16', 'Küçüktüm yalnız kalmamaya yenin edenlerden değildim  Kolumda plastik bir saat zamanın geçmesini bekliyordum. O zaman ki beni gençliğime götü...', ARRAY['Türk Edebiyatı','Şiir','İnan Arslanboğan']::text[], 8.5, '{"poet":"İnan Arslanboğan","poet_slug":"i-nan-arslanbogan","theme":"Türk Şiiri","is_hero":false,"total_lines":111,"source_url":"https://www.antoloji.com/hazin-bir-hikaye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taşlar ve Kuşlar', 'taslar-ve-kuslar-celal-kabadayi-9oaxp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dalgın su boylarının kıyısında

yalnızlık köprüsünün başındayım

gözlerinin ılık suları akarken içime

seni sevmemek çabasındayım

adınla kilitlediğim duygular

sanma seni unuttular

senden kilometrelerce uzakta

adını sınır taşlarına yazdılar

uzaklık değil beni durduran

o çılgın yüreğimi uslandıran

üç kuruşa sattın ya şiiri

budur umudumu solduran

adresim taşlar telefonum kuşlar

dönüşsüz yolumsun seni aramam

sen arasan da neye yarar

ben taşlarla kuşlarla konuşamam', 'Dalgın su boylarının kıyısında yalnızlık köprüsünün başındayım gözlerinin ılık suları akarken içime seni sevmemek çabasındayım adınla kilitl...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/taslar-ve-kuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Vurdular', 'beni-vurdular-celal-kabadayi-ekfil', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni bir akşam  sokak ortasında vurdular

muştayla vurdular,sopayla vurdular

dükkan dükkan dolaşıp toplandılar

ülkücü köpekler,faşist bozkurtlar

Nusret Abi''nin yanından geliyordum

ne güzel başlamıştım pusu akşamına

sıcak bir hoşbeş,sıcak çay,sarma tütün

Necla Abla''yı arayacaktım postaneden

yağmurlu bir evde oturan eşsiz bir yürek

iki çiçek bekliyordu kapının eşiğinde

biri gül biri karanfil

biri sarıydı,biri kızıl

kırılmış gibi gücenik duruyorlardı

umutsuz bir aşktan solgun düşmüş

bana vurduklarında çiçekleri düşünüyordum

gülü,karanfili ve postanaye uğramayanları

papatyayı,laleyi,menekşeyi

bir de çiğdemi

kafama sopalar inip sopalar kalkıyordu

ılık kanım su gibi boynuma akıyordu

vuranların yüzünü bile anımsamıyorum

vurulurken gözlerim yalnızca seni arıyordu

bana vurdular,vurdukça aklıma sen geldin

aklıma,başıma,bilincime geldin

canım hiç acımadı,yalnızca kanım akıyordu

seni sevmek ne mutluluktu kanlar içinde

seni sevmek korkuyu unutturdu pusular içinde 

demek ben çok şeydim

demek ben çok sevdim

düşüncemle sevgimle düşmanı deli ettim

düşüncemi öldürmek için

sevgimi öldürmek için 

hep başıma vuruyorlardı

başımı kollarıma aldım

sokaktaydım,direndim,bağırdım

yerlerde yuvarlandım,ellerimi kullandım

Buca''da, Ümraniye''de olsaydım

kesin ölürdüm

Diyarbakır''da, Ulucanlar''da olsaydım

kesin ölürdüm

hem de on kez ölürdüm', 'Beni bir akşam  sokak ortasında vurdular muştayla vurdular,sopayla vurdular dükkan dükkan dolaşıp toplandılar ülkücü köpekler,faşist bozkurt...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/beni-vurdular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Bu Havalar Mahvetti', 'beni-bu-havalar-mahvetti-orhan-veli-kanik-pyyte', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni bu güzel havalar mahvetti, 

Böyle havada istifa ettim 

Evkaftaki memuriyetimden. 

Tütüne böyle havada alıştım, 

Böyle havada aşık oldum. 

Eve ekmekle tuz götürmeyi; 

Böyle havalarda unuttum. 

Şiir yazma hastalığım; 

Hep böyle havalarda nüksetti. 

Beni bu güzel havalar mahvetti.', 'Beni bu güzel havalar mahvetti,  Böyle havada istifa ettim  Evkaftaki memuriyetimden.  Tütüne böyle havada alıştım,  Böyle havada aşık oldum...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/beni-bu-havalar-mahvetti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ayrilik', 'ayrilik-sabri-knak-i4qo7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ayrılık adını nereden çıkardın,

Bir değil bin defa canımı aldın,

Bu beden sensiz yzşarmı sandın,

Hata yaptın sevgilim!

Burada yanıldın.', 'Ayrılık adını nereden çıkardın, Bir değil bin defa canımı aldın, Bu beden sensiz yzşarmı sandın, Hata yaptın sevgilim! Burada yanıldın....', ARRAY['Türk Edebiyatı','Şiir','Sabri Knak']::text[], 8.5, '{"poet":"Sabri Knak","poet_slug":"sabri-knak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Geliyoruz', 'biz-geliyoruz-taner-atam-pdjtv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Açan lalelerden gül bahçelerinden

Ümit pınarından sesleniyoruz

Hem ülfetle kaynaşıp, o galu beladan

Yürekleri avuçlayıp BİZ GELİYORUZ.

Silinir gözümüzden karamsar tablo

Allah''ın ihsanı görünür, öyle ki sonsuz

Hele şu fani dünya gördük ki susuz

Irmaklarla coşarak, BİZ GELİYORUZ.

Ana, yar, ser bilmez hep doğru gideriz

Dilde aynı seda arşı titretiriz

Neyki bir can, O''na binlercesi feda

Allah''ın ipine sarılıp BİZ GELİYORUZ.', 'Açan lalelerden gül bahçelerinden Ümit pınarından sesleniyoruz Hem ülfetle kaynaşıp, o galu beladan Yürekleri avuçlayıp BİZ GELİYORUZ. Silin...', ARRAY['Türk Edebiyatı','Şiir','Taner Atam']::text[], 8.5, '{"poet":"Taner Atam","poet_slug":"taner-atam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biz-geliyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Bitti', 'ask-bitti-ahmet-telli-w0wms', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'F.E.S. ve öbürleri için 

Bir aşk nasıl biterse öyle bitti bu aşk da 

      Uzun bir hastalık gibi 

      Aralıksız dinlediğim alaturka bir fasıl gibi 

      Gökyüzüne bakmayı, dostlara mektup yazmayı 

      Çiçekleri sulamayı unutmuşluğum gibi 

Bitti. 

Bir aşk nasıl biterse öyle bitti bu aşk da 

Yürümeyi yeniden öğrenen felçli bir çocuk gibi 

Sokağa çıkmalıyım şimdi ve çoktandır 

İhmal ettiğim dostlara yeni bir adres bırakmalıyım 

Pencereleri açmalı, kitapları düzenlemeliyim 

Belki bir yağmur yağar akşama doğru 

Yarıda bıraktığım şiirleri tamamlarım 

Aşk da bitti diyordu ya bir şair 

Aşk bitti işte tam da öyle', 'F.E.S. ve öbürleri için  Bir aşk nasıl biterse öyle bitti bu aşk da        Uzun bir hastalık gibi        Aralıksız dinlediğim alaturka bir f...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Haber', 'ne-haber-mehmet-kuskun-86nos', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haberin bile yok 

Senin uğruna  çektiklerimden

Sen orada bir  yerde . 

Ben buralarda 

Bahar dışarda 

Senin saçların yine nemli

Gözlerinde o mükemmel buğu

Ellerim  nerdeler 

Haberim bile yok', 'Haberin bile yok  Senin uğruna  çektiklerimden Sen orada bir  yerde .  Ben buralarda  Bahar dışarda  Senin saçların yine nemli Gözlerinde o ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Küskün']::text[], 8.5, '{"poet":"Mehmet Küskün","poet_slug":"mehmet-kuskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ne-haber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonra', 'sonra-sair-oedipius-rqg0v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçimden ne ağlamak ne de gülmek geliyor artık

Duygularımı mı yitirdim nedir?

Sadece seni, yaşadıklarımızı

Bana söylediklerini ve sana söylediklerimi düşünebiliyorum

Seni her düşündüğümde

Sadece güzel anılar geliyor aklıma

Seninle kurduğumuz hayaller

Evimizi nasıl düzenleyeceğimiz

Yaşantımızın nasıl olacağı,

Hayatımı öyle dolduruyordun ki

Sen gidince bomboş kaldı içim

Günler, aylar hatta yıllar geçtiğinde bile 

Seni silebileceğimi sanmıyorum içimden

Birgün, belki çok uzun zaman sonra

Aklına düşeceğim ve merak edeceksin beni

Olur ya arasın belki

Sesini duyduğumda

Aynı bugün gibi yıkılacağım

Ama herşeye rağmen konuşacağız seninle

Sonra gün gelip rastlayacağım sana bir köşe başında

Oğlunun elini tutmuş, şakalaşıyor olacaksın onunla

Hemen saklanacağım

Seni rahatça ve sessizce seyredebilmek için,

Sonra eşinde kızınla beraber yanına gelecek

Özeneceğim aile tablonuza

Kafanı kaldırdığında,

Fark edeceksin seni uzaktan, saklanarak seyrettiğimi

Beni gördüğün anda kaçacağım hızla oradan

Sense hareketsizce bakacaksın ardımdan

Sonra düşündüğünde

Anlayacaksın seni ne çok sevdiğimi

Ve hala sevmekte olduğumu....', 'İçimden ne ağlamak ne de gülmek geliyor artık Duygularımı mı yitirdim nedir? Sadece seni, yaşadıklarımızı Bana söylediklerini ve sana söyled...', ARRAY['Türk Edebiyatı','Şiir','Şair Oedipius']::text[], 8.5, '{"poet":"Şair Oedipius","poet_slug":"sair-oedipius","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilebilir misin?', 'bilebilir-misin-sair-oedipius-j0t53', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen bilebilir misin?

Her akşam senden ayrılıp

Eve gitmenin ne kadar zor olduğunu

Evde insanlar varken bile

Sesizliğin yalnızlığını çekmenin

Ne kadar korkunç oluğunu bilebilir misin?

Peki

Her akşam kafamı yastığıma koyduğumda 

Seninle rüyalara dalmanın güzelliğini

Ve mutluluğunu bilebilir misin?

Sana kavuşmama an kaldığı anlarda

Rüyadan uyanmanın hüznünü

Bu hüznün getirdiği gözyaşlarını bilebilir misin?

Gün boyu seni düşünerek

Avare avare dolaşmayı,

Seni gördüğümde yaşadığım heyecanı

Ve akşam olup

Sana kavuşmayı sevinçle bekleyen

Sevgi dolu kalbimin sabırsızlığını bilebilir misin?

Kollarının arasında duyduğum şevkati,

Dudağında hissettiğim sıcaklığı

Ve gözlerinde gördüğüm sevginin

Beni her dakika sana daha çok bağladığını bilebilir misin?

Peki ya

Sana olan sevgimin

Ne kadar büyük

Ve ne kadar derin olduğunu bilebilir misin?

Tabii bilemezsin

Çünkü sen, seni benim kadar SEVEMEZSİN...', 'Sen bilebilir misin? Her akşam senden ayrılıp Eve gitmenin ne kadar zor olduğunu Evde insanlar varken bile Sesizliğin yalnızlığını çekmenin ...', ARRAY['Türk Edebiyatı','Şiir','Şair Oedipius']::text[], 8.5, '{"poet":"Şair Oedipius","poet_slug":"sair-oedipius","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bilebilir-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözde Ayrılık', 'sozde-ayrilik-birol-akin-g9riv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Haykırışlarımı duyabiliyormusun gökyüzündeki bulutlarda

Islak kaldırımlardaki ayak seslerimi

Sokak lambalarında görebiliyormusun gözyaşlarımı

Yaşayabiliyormusun soğuk telefon tellerinde

                                                   sımsıcak sevgilerimi

Ellerinde ellerimin yangınını hissedebiliyormusun

Kar mavisi gözlerinde gözlerimi

Nefesinde bütünleşen sıcacık nefesimi

Dudaklarında yaşıyormusun kar tanelerini

Duyabiliyormusun tenimde esen ayrılık yelini

Saçlarında gezinen hoyrat parmaklarımı

Teninde tenimin çöl ayazı kokusunu

Ve seninle bütünleşen benliğimi duyabiliyormusun

Söyle bir tanem

Söyle Kınalı Yapıncağım

Görebiliyormusun gözyaşlarımı

Hissedebiliyormusun yangınımı

Yaşıyabiliyormusun sevgilerimi

Duyabiliyormusun benliğimi

söyle', 'Haykırışlarımı duyabiliyormusun gökyüzündeki bulutlarda Islak kaldırımlardaki ayak seslerimi Sokak lambalarında görebiliyormusun gözyaşlarım...', ARRAY['Türk Edebiyatı','Şiir','Birol Akın']::text[], 8.5, '{"poet":"Birol Akın","poet_slug":"birol-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sozde-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savrulan Külleri Ömrümüzün', 'savrulan-kulleri-omrumuzun-ahmet-telli-9hgov', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir kızın kocaman gözlerinde gördüm 

bulutların dağlara sessizce çöküşünü 

Çocuksu susuşları gördüm, kırılan sevinci 

Ve kalbimi puslu yamaçlardaki pusulara saldım 

çobanlar çoktan inmişlerdi ovaya 

bense yapayalnız bir ağaçtım doruklarda 

Harelenen sularda bir yanık kokusu 

ve uzun boyunlu bir kızın gülümseyişi 

Işık zamana bağlı zamansa onun 

kocaman gözleridir artık 

Anladım tarih de yazılmaz 

bir aşkın sayfalarına düşmüyorsa gün 

Yalnızdım, yapraklarım dökülmüştü bir bir 

deryalara savrulup çöllere düşmüştü 

Bir duman tütüyor yine hangi kent yandı 

hangi sokakta vuruldu sevgilim 

Bir demet menekşe bir avuç toprak 

burkulan bir yürek miyim hep 

Sesimde bir yanma bir kekrelik 

uzayıp giden bir çöl yalnızlığı 

Gazeteleri okumuyorum başım dönüyor 

sulanmamış çiçekler gibi kuruyor her şey 

her şey bir yolculuğun hüznünü taşıyor 

gidip de gelmemek üzere bütün yüzler 

Puslu yamaçlarda bir çakal gölgesi 

bir dağ suskunluğu yürüyor kentlere 

yenilen biz miyiz yoksa aşklar mı 

bir kızın kocaman gözlerinde görüyorum 

savrulan küllerini ömrümüzün 

Bu kenti ayrılıklar yıkacak birgün biliyorum 

Ölümden şikâyeti yok ölüp gidenlerin 

ama bir kızın kocaman gözlerinde yangınlar çıkıyor 

Acılar dehşetli kinlendiriyor beni 

Kabarıp duruyor içimde, kabarıp duran bir okyanus 

yurdumu arıyorum batık bir tekne değilim 

yurdumu arıyorum kızgın küller ortasında', 'Bir kızın kocaman gözlerinde gördüm  bulutların dağlara sessizce çöküşünü  Çocuksu susuşları gördüm, kırılan sevinci  Ve kalbimi puslu yamaç...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/savrulan-kulleri-omrumuzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Gelmeden', 'guz-gelmeden-ahmet-telli-yvyg8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sırtında taşıdığın kıl heybe 

dağ rüzgârı ve lor peyniri 

gibi doluysa kır çiçekleriyle 

sesler türkülere dönecektir 

üzünçse ışıklı bir sevince 

Dudaklarında özlem türküleri 

ve gözlerinin menevşesinde aşk 

çağıldıyorsa çavlanlar gibi 

usulca gir umudun menziline 

hüznü gerilerde bırak 

Türküler paylaşılıyorsa eğer 

dağ rüzgârları paylaşılıyorsa 

sevinç de dahildir buna 

ve o zaman bütün bir yaşam 

paylaşılacak kadar güzeldir artık 

Heybendeki kır çiçekleri 

bir yangındır güze doğru 

tutuşturur yüreğinde 

uzak özlemlerin külünü 

hiç beklemediğin bir anda 

Güz gelip de yangın başlamadan 

tutmalısın doğanın yelesinden 

yüreğindeki seher yeli 

varmalıdır sabah olmadan 

gül bahçesine sevda hevengine', 'Sırtında taşıdığın kıl heybe  dağ rüzgârı ve lor peyniri  gibi doluysa kır çiçekleriyle  sesler türkülere dönecektir  üzünçse ışıklı bir sev...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/guz-gelmeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz de Sararır', 'soz-de-sararir-ahmet-telli-bixpw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Olur, aramam seni ve kimseyi 

Anıları pas tadında bırakırım 

Konuşacak ne kaldıysa kalsın 

Susmaktır birşeylere saygılı kılan 

Ayrılık da bir olanaktır bilirsin 

İnce bir sis, bir hüzün örtüsü 

Dumanlı bir ıslık yakışır şimdi 

Dudaklarıma, bırakıp giderim 

Söz / de sararır biterken bir aşk 

Kediye iyi bak çiçekleri sula 

Diyorsam da aldırma sözlerime 

Alışkanlık işte başka birşey değil 

Söz / de sararır biterken bir aşk', 'Olur, aramam seni ve kimseyi  Anıları pas tadında bırakırım  Konuşacak ne kaldıysa kalsın  Susmaktır birşeylere saygılı kılan  Ayrılık da bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/soz-de-sararir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız Aşk', 'zamansiz-ask-tugba-ucar-aptb4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkları yoksul,kimsesiz zamanlara saklama zamanı

bak kadının yüzü sade,cılgın sözcüklerle kaplı

seviyor , yaklasıyor

seviyor , okşuyor

kah bir kuğu, kah bir kuzgun

deli ediyor onu derindeki sözcük tartısmaları

süzülüyor soguk rüzgarlarla dolu gecmisine

koyu karlı bir denizde soyunup,yıkıyor zihnini

buz kesiyor kibirli,ukala sevgisi

nefreti emiyor tüm sarkılarını

emiyor biriktirdigi gece yarıısı süvarilerini

kah bir kuğu , kah bir kuzgun

seviyor ,  uzaklasıyor

seviyor,seviyor,seviyor...', 'Aşkları yoksul,kimsesiz zamanlara saklama zamanı bak kadının yüzü sade,cılgın sözcüklerle kaplı seviyor , yaklasıyor seviyor , okşuyor kah b...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Uçar']::text[], 8.5, '{"poet":"Tuğba Uçar","poet_slug":"tugba-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zamansiz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam Ziyareti', 'aksam-ziyareti-tugba-ucar-zadn4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ekmek arası bir kac ask sözcügü

yiyorum,bogazıma diziliyor her lokma

elimi uzatıyorum bakıyor manasız gözlerle

o unutmus asklarını derin bir kuyuda

beni de boguyor

bakıyorum ,soruyorum sessizligimle''''seviyor musun?''''

anlamıyor....

hareketleri bende,aklı uzaklarda

diziyor bogazıma tekerleklı cümleleri

kaymıyor ,tıkıyor aksine

kalbım ise sahur vakti calınan imansız bir davul

cıkmaz bir sokak onun gozleri

takılıp kalıyorum

boguluyorum sözlerin arasında

o unutmus asklarını derin bir kuyuda....', 'Ekmek arası bir kac ask sözcügü yiyorum,bogazıma diziliyor her lokma elimi uzatıyorum bakıyor manasız gözlerle o unutmus asklarını derin bir...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Uçar']::text[], 8.5, '{"poet":"Tuğba Uçar","poet_slug":"tugba-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aksam-ziyareti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlar Sonbahar', 'kadinlar-sonbahar-attila-i-lhan-bphf9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kadınlar sonbahar yapraklarını dökmeye başlar

Titrek dudaklarında sarışın bir keder

Nabız kaybolur kan susar dolaşım yavaşlar

Sisli bir nebuloz gökte yazılmamış şiirler

Dargın sevgililer yalnızlıklarına uzaklaşıyor

Anlaşılmaz çoçukluğun ortaokullarından ders zilleri

Kilitli defterlerde kurutulmuş menekşeler

Tehlikeli yolculukların kanat çırpan mendilleri

Sazdan saza azalan hicranlı köçekçeler

Dünkü delikanlıları yaşlılığa taşıyor

Eylül şehirleri yağmurlu gürültülerle alır yerlerini

Deniz kahvelerinde son kadehlerde bulutlar birikir

Ilık bir aydınlıkla yıkayıp yorgun ellerini

Görgülü ihtiyarlar bir bir ortalıktan çekilir

Yaşlandıkça insan dünya başkalaşıyor.', 'Kadınlar sonbahar yapraklarını dökmeye başlar Titrek dudaklarında sarışın bir keder Nabız kaybolur kan susar dolaşım yavaşlar Sisli bir nebu...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kadinlar-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Bir Sevmek (Ne Kadınlar Sevdim)', 'boyle-bir-sevmek-ne-kadinlar-sevdim-attila-i-lhan-rtupx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne kadınlar sevdim zaten yoktular

Yağmur giyerlerdi sonbaharla bir

Azıcık okşasam sanki çocuktular

Biraksam korkudan gözleri sislenir.

Ne kadınlar gördüm zaten yoktular

Böyle bir sevmek görülmemiştir  

Hayır sanmayın ki beni unuttular 

Hala arasıra mektupları gelir 

Gerçek değildiler birer umuttular 

Eski bir şarkı belki bir şiir 

Ne kadınlar sevdim zaten yoktular 

Böyle bir sevmek görülmemiştir  

Yalnızlıklarımda elimden tuttular 

Uzak fısıltıları içimi ürpertir 

Sanki gökyüzünde bir buluttular 

Nereye kayboldular şimdi kimbilir

Ne kadınlar sevdim zaten yoktular 

Böyle bir sevmek görülmemiştir.', 'Ne kadınlar sevdim zaten yoktular Yağmur giyerlerdi sonbaharla bir Azıcık okşasam sanki çocuktular Biraksam korkudan gözleri sislenir. Ne ka...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/boyle-bir-sevmek-ne-kadinlar-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Gemi', 'sessiz-gemi-yahya-kemal-beyatli-3zx93', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Artık demir almak günü gelmişse zamandan, 

Meçhule giden bir gemi kalkar bu limandan. 

Hiç yolcusu yokmuş gibi sessizce alır yol; 

Sallanmaz o kalkışta ne mendil ne de bir kol. 

Rıhtımda kalanlar bu seyahatten elemli, 

Günlerce siyah ufka bakar gözleri nemli. 

Biçare gönüller. Ne giden son gemidir bu. 

Hicranlı hayatın ne de son matemidir bu. 

Dünyada sevilmiş ve seven nafile bekler; 

Bilmez ki, giden sevgililer dönmeyecekler. 

Bir çok gidenin her biri memnun ki yerinden. 

Bir çok seneler geçti; dönen yok seferinden', 'Artık demir almak günü gelmişse zamandan,  Meçhule giden bir gemi kalkar bu limandan.  Hiç yolcusu yokmuş gibi sessizce alır yol;  Sallanmaz...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatlı']::text[], 8.5, '{"poet":"Yahya Kemal Beyatlı","poet_slug":"yahya-kemal-beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sessiz-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Samandira', 'samandira-sunay-akin-k985s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayirsiz ogluyum babamin

hic buyumeyen

hala Topkapi''ya dogru uzanir

kimsecikler gormeden

hinzir bir cocuk gibi

kapisini calip

kacarim Istanbul''un

Hayirsiz ogluyum babamin

ticareti sevmeyen

para icin kosturulan

yaris atlarinin terlerini

bir akvaryumda toplar

icinde denizati

beslerim

Hayirsiz ogluyum babamin

yollarda dalgin yuruyen

ama adliyenin coplugunde

buldugu dolmakalemi

cocuklarina getirmek icin

ortasindan yapistiran temizlik iscisi

kacmaz gozlerimden

Hayirsiz ogluyum babamin

bir parka

dikilirse bir gun sairlerin heykelleri

benim yerim bos kalsin

ve payima hayirsiz ada aciklarina

bir samandira birakin', 'Hayirsiz ogluyum babamin hic buyumeyen hala Topkapi''ya dogru uzanir kimsecikler gormeden hinzir bir cocuk gibi kapisini calip kacarim Istanb...', ARRAY['Türk Edebiyatı','Şiir','Sunay Akın']::text[], 8.5, '{"poet":"Sunay Akın","poet_slug":"sunay-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/samandira-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turan', 'turan-yavuz-bulent-bakiler-fl5bf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-Sadık Kemal Tural kardeşimize-

Ben Altay dağlarından koparak geldim

Yüreğimde Türkistan''dan binbir nakış var.

Çok şükür aslım da neslim de belli.

Türküm müslümanım o dağlar kadar.

Dokuz tuğ taşıdım ben, dokuz davula vurdum.

Dokuz evliya gücüyle yürüdüm geldim.

Büyüdü benimle mübarek yurdum.

Ebed-müddet bu devleti ben kurdum.

Nevruz toylarımızda ateşler tutuşturdum.

Orhun''dan, Seyhun''dan, Ceyhun''dan geçtim.

Yol gösterdi kükreyerek bana Bozkurt''um.

Atımla hep yanyana gözelerden su içtim.

Baykal''da da çimdimben, Hazar Denizi''nde de

Toprağıma bağdaş kurup oturdum.

Ben ki Alper Tunga''ya gönül verenlerdenim.

Yurt uğruna dolu dizgin göğüs gerenlerdenim.

Sonra durgun sulara Bismillahlarla.

Kilim seccadesini serenlerdenim.

Yani hem Alplerdenim, hem Alperenlerdenim.

Ben Türkmen''im, Özbek''im, Kazak''ım, Kırgız''ım ben.

Azerbaycan Türkleriyle aynı kandanım.

Kıpçakları, Uygurları aşkla duyanlardanım

Ben ki Tatarlardan, Gagavuzlardan

Çuvaşlardan, Bozkurtlardan, Oğuazlardanım.

Kalem de tuttum çok şükür, kılıç da, gül de.

Güvercin bakışlı sıcak türküler de söyledim.

Anlayan anladı kim olduğumu.

Aman dileyeni sevdim, öfkemi yendim.

Övdü büyük peygamber İstanbul Başbuğumu

Kur''an''la da müjdelendim.

Sevsem gözbebeğim olur ne varsa

Öfkelensem öfkem dağları ezer.

Dilim bazan suların çağlamasına

Bazan da bülbüllerin şakımasına benzer.

İşte bilge Tomyukuk, Kültikin, Bilge Kağan

Hepsi birbirinden daha mübarek

Süzme asaletimin nurdan kefili

İşte Dede Korkut, kaftanı ipek

Soyumun-sopumun bin yıllık dili

Ve Yusuf Hashacib, Mahdum Kulu, Fuzuli

Hepsi de peygamber soyunca asil

Sonra Kaşgarlı Mahmut; gönlüme düşen çemre

Ali Şir Nevai, Gaspıralı İsmail

Şiiri bir bakraç süt gibi Yunus Emre.

Cengiz Aytmatov ki, Cengiz Dağcı ki

Ayın ondördündenden sağılan huzur

Sabir Rüstemhanlı... ruh kadar eski

Ve daha binlerce nur üstüne nur.

Servetim Buhari''nin, Yusuf Hamedanî''nin

Ahmet Yesevî''nin nur servetinden

Güzelliğim, merhametim, şefkatim

Hep Şah-ı Nakşibent hazretlerinden.

Hunlardan, Göktürklerden alıp getirdim.

İpek ipliğimi altın tığımı

Mintanıma minyatürler işledim durdum

Selçuklu çinisine gönül mührümü vurdum.

Osmanlı ebrusuyla süsledim yastığımı

Mustafa Kemâllerle yeni baştan doğruldum.

Kim demiş 75 yaşıma bastığımı.', '-Sadık Kemal Tural kardeşimize- Ben Altay dağlarından koparak geldim Yüreğimde Türkistan''dan binbir nakış var. Çok şükür aslım da neslim de ...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bülent Bakiler']::text[], 8.5, '{"poet":"Yavuz Bülent Bakiler","poet_slug":"yavuz-bulent-bakiler","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/turan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülkü', 'ulku-sair-yarem-hohgg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üzülme sen ey dilber, sen gülşende bir gülsün

Lutfet maşuk ismini de,ağlayan gözler gülsün.

Kalpler aşkınla mest olsun bitap düşsün,

Ümitlerde reh-i aşkta yegane peri sensin.

                                          (Nisan 98)', 'Üzülme sen ey dilber, sen gülşende bir gülsün Lutfet maşuk ismini de,ağlayan gözler gülsün. Kalpler aşkınla mest olsun bitap düşsün, Ümitler...', ARRAY['Türk Edebiyatı','Şiir','Şair Yarem']::text[], 8.5, '{"poet":"Şair Yarem","poet_slug":"sair-yarem","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ulku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bahar Böyle Geldi', 'bir-bahar-boyle-geldi-i-dris-elibol-syk3b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bahar böyle geldi

Çiçek açtı ümit dallarım

Gözlerinin kirpiği ruhuma değdi

Korkuttu ruhumu bedenden etti

Bir bahar böyle geldi

Böyle geldi bir bahar

Sıyrıldı yeşilden yaprak aşklarım

Önce güldü yüzüme nar gözlerin

Sonra baharı mevsimden etti

Ve bir bahar böyle geldi', 'Bir bahar böyle geldi Çiçek açtı ümit dallarım Gözlerinin kirpiği ruhuma değdi Korkuttu ruhumu bedenden etti Bir bahar böyle geldi Böyle gel...', ARRAY['Türk Edebiyatı','Şiir','İdris Elibol']::text[], 8.5, '{"poet":"İdris Elibol","poet_slug":"i-dris-elibol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-bahar-boyle-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan Ve Aşk IV.', 'nisan-ve-ask-iv-i-dris-elibol-yec7y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sıradağlarıma meltemler vurmadan

Nisanların yağmuru vurmuş başıma

Bir damla kalbime basmış ayağını

Artık isyan vurmuş incecik dalıma', 'Sıradağlarıma meltemler vurmadan Nisanların yağmuru vurmuş başıma Bir damla kalbime basmış ayağını Artık isyan vurmuş incecik dalıma...', ARRAY['Türk Edebiyatı','Şiir','İdris Elibol']::text[], 8.5, '{"poet":"İdris Elibol","poet_slug":"i-dris-elibol","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nisan-ve-ask-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla Beni İstanbul', 'anla-beni-i-stanbul-i-dris-elibol-8hmbj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boğazda aşikar ay ışığı

Ensende köpüklü dalgaların çığlığı

Sen ihtirasımın muamma çölü

İdam mahkumunun son dileği

Gelincik yaprağım, yediveren toprağım

Karasevdalım

Çevirme gözlerini benden

Su gibi döküleyim

Çek beni toprağının kılcallarına

Oy mavi yazmalım

Akşam çayım

Aşığımın zârı, damarımın kızıl kanı

Beynimi mavi sularına

Bilmece gibi yorduğum şehir

Ya martıların sesini getir

Ya da mehtabınla doğ bana

Kapama gözlerini ne olur

Gözlerin açık olmalıdır senin

İstanbul,

Bakışların ruhu oynatır

Nabzını saysın serseri kaldırımlar

Kalp gece öksüzünü karartır

Vuslatın mumu yanağımı yaksın

Anla beni İstanbul

Anla ki yürek kansın

Ne olmuş sana İstanbul,

Nice ağladığın gözlerinden belli

Yorgun musun, dargın mısın ah şehir!

Ağlatıyor beni gözlerin

Söyle düşmanın mıdır geceler

Zifiri geceleri

Aç kurtlar yesin!

Sen ey türküme nakarat şehir

Ya kafiyelerini topla gel,

Ya da kendin kal bana!', 'Boğazda aşikar ay ışığı Ensende köpüklü dalgaların çığlığı Sen ihtirasımın muamma çölü İdam mahkumunun son dileği Gelincik yaprağım, yediver...', ARRAY['Türk Edebiyatı','Şiir','İdris Elibol']::text[], 8.5, '{"poet":"İdris Elibol","poet_slug":"i-dris-elibol","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/anla-beni-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve İstanbul', 've-i-stanbul-i-dris-elibol-r6zbm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tütünün olayım, sar beni

Sevdanın en olunmazına çek beni

Kendine ram ettin, ah beni

Elim kolum bağlı çöz beni

Alıkoy bütün şehirlerden tut beni

Giryan oldum gözlerine güldür beni

Yanıyorum diyorum söndür beni

Toprağına yüreğim tohumdur ek beni

Ey varlığın ve yokluğun şehri

Kafiyeler anladı, mısralar anladı

Bir sen anlamadın!

Varlığın kevser, kandır beni

Yokluğun ölüm, dirilt beni

Oy İstanbul!

Saatler vuslatı vurmuyor, anla beni

Anla beni!..', 'Tütünün olayım, sar beni Sevdanın en olunmazına çek beni Kendine ram ettin, ah beni Elim kolum bağlı çöz beni Alıkoy bütün şehirlerden tut b...', ARRAY['Türk Edebiyatı','Şiir','İdris Elibol']::text[], 8.5, '{"poet":"İdris Elibol","poet_slug":"i-dris-elibol","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ve-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaka', 'saka-sema-akin-p66ug', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ben seni sevmiyorum

hatta nefret ediyorum

seni hiç düşünmüyorum

ben başkasını seviyorum

inandınmı bana

nasıl yaparım ben bunu sana

anlasana be güzelim

şaka yaptım şaka', 'ben seni sevmiyorum hatta nefret ediyorum seni hiç düşünmüyorum ben başkasını seviyorum inandınmı bana nasıl yaparım ben bunu sana anlasana ...', ARRAY['Türk Edebiyatı','Şiir','Sema Akın']::text[], 8.5, '{"poet":"Sema Akın","poet_slug":"sema-akin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/saka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereden Bileceksin', 'nereden-bileceksin-nurullah-genc-l7s2t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O eski hülyaların sahile vurduğunu

Yakama bir muamma taktığım gün hatırla

Gurbetin mahşerimde bir sıla bulduğunu

Dağlar gibi eriyip aktığım gün hatırla

Nereden bileceksin, şehrin sokaklarında

Kaybolan ışıkların gözlerim olduığunu 

Her seher yüreğimde açan karanfillerin

Her akşam ellerimde sararıp solduğunu

Nereden bileceksin

Kim bilir, belki bir gün kapıma geleceksin

Siyah tüylü martılar  yorgun pencerelerde

Benimle ağlayacak benimle güleceksin

Göğsümde ızdırabı Deniz fenerlerinin

Hayatımdan fışkıran hüzne gömüleceksin

Her şairin bir gülle bahtiyar olduğunu

Bir sana bir göklere baktığım gün hatırla

Gönlümün kahrın ile ihtiyar olduğunu 

Sigaramı sessizce yaktığım gün hatırla

Bilemezsin içimde bir denizdir yaşamak

Sen denizin en uzak noktasında şen şakrak

Ben kırgın dalgalarla avunurum derinde

Gemilere yosunlu mendiller bağlayarak

Nereden bileceksin fesleğen köklerinin 

Hecai bulutlardan bıkıp usandığını

Ansızın kayıveren yıldızların ardında

Vuslatı bekleyen bir kalbin yandığını

Nerdem bileceksin

Yağmura boyun büken susuz topraklar gibi

Kim bilir belki bir gün kapıma geleceksin

Sinesinde bi-vefa bir sırrı saklar gibi

İnfazına yürüyen ölü tutsaklar gibi

Gözlerinin hicranlı yaşını sileceksin

Tatlı bir rayihanın göklere dolduğunu

Irmaklara karışıp aktığım gün hatırla

Gölgelerin ruhumu görüp kaybolduğunu

Mavi bir şimşek gibi çaktığım gün hatırla

Gülümse ve uzaklaş çünkü anlayamazsın

Bu kopan fırtınayı Yusuf''un yüreğinde 

Koyu bir çaresizlik ayinidir yalnızlık

Züleyha''nın menekşe büyüyen gözlerinde

Nereden bileceksin kayalara tutunan 

Devlerin birer birer vurulup öldüğünü

Rüyaları süsleyen eşsiz mücevherlerin

Bir dervişi görünce yere döküldüğünü

Nereden bileceksin

Kim bilir belki bir gün kapıma geleceksin

Kollarında rüzgarlı bir deprem karanlığı

Kapı aralığında sessizce gireceksin

Işıldayan bu gönül şahikası önünde 

El pençe divan durup sen de eğileceksin

Bülbülün lalezardan neden kovulduğunu

Bu hayal zindanını yıktığım gün hatırla

Balığın susuz kalıp suda boğulduğunu

Acılar evreninden çıktığım gün hatırla', 'O eski hülyaların sahile vurduğunu Yakama bir muamma taktığım gün hatırla Gurbetin mahşerimde bir sıla bulduğunu Dağlar gibi eriyip aktığım ...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/nereden-bileceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geriye Bakamam', 'geriye-bakamam-hakan-kivanc-tcvyh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Külçe gibi yığılırım

Ne zaman bir trene

Binsem

Dönüp o şehre bakamam

Islıklarım geçtiğim

Dağı taşı.

Islıklarım,geçtiğim 

Dağı,taşı

Islıklarım. tükürüklercesine

Ama yinede cılızlaşır,tizleşir

An gelir

Geri dönüp bakasım gelir

Dostlara

Umutlara,

Sevgiliye,

Unuturum çağlayan bir suya

Sarıldığımı

Sevgilimsin dediğime

Geriye dönüp bakamam ben

Yenik bir sporcunun bitkin beyniyim.....



Aynı caddeden

Aynı şehirden

Aynı aşktan 

Bir daha geçemem

Daralır ufacık dağınık odam gibi

Yüreğim...

Orda duruyormu diye bakamam

Biri, 

Körüklerim ciğerimi dumanla

Bulanık sisin arsında

Bir zayıf

Bir şişman

Bir uzun insan

arar günboyu 

arar birbirini

Onlar beni görürü

Ben onları

Ama onlar birbirini............', 'Külçe gibi yığılırım Ne zaman bir trene Binsem Dönüp o şehre bakamam Islıklarım geçtiğim Dağı taşı. Islıklarım,geçtiğim  Dağı,taşı Islıkları...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kıvanç']::text[], 8.5, '{"poet":"Hakan Kıvanç","poet_slug":"hakan-kivanc","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/geriye-bakamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Korkusuzluk Meleğim', 'sana-korkusuzluk-melegim-hakan-kivanc-xew21', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İstanbul seni bekler gibi

Göz kırptı bana...

Hoş geldin dedi

İnan bana duydum bebekte

Halk vapurunda....

İstanbulladım seni aşkımla

Aşkımıda istanbulladım

Ve ilk defa hissettim

Seni kıskandığımı onbeşmilyonundan istanbulun

Tut elimi tutki unutmayı öğrenmeyelim hiç

Tek unuttuğumuz geçmişe gömdüğümüz

Sevgisizlik  olsun

Tut bebeğim tut elimi

Bırakma hiç.........', 'İstanbul seni bekler gibi Göz kırptı bana... Hoş geldin dedi İnan bana duydum bebekte Halk vapurunda.... İstanbulladım seni aşkımla Aşkımıda...', ARRAY['Türk Edebiyatı','Şiir','Hakan Kıvanç']::text[], 8.5, '{"poet":"Hakan Kıvanç","poet_slug":"hakan-kivanc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sana-korkusuzluk-melegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Orda Bir Çocuk... Burda Ben', 'orda-bir-cocuk-burda-ben-yavuz-bulent-bakiler-cfgej', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ana gülümserken yorgun ve güzel

Yüreği müjdelerle tüy gibi hafiflerken,

Orda, bir çocuk doğar sımsıcak dünyamıza

Burda ben...

Dal nasıl, yaprak nasıl, ekin nasıl büyürse

Toprak nasıl uyanırsa bir incecik yağmurdan

Orda bir  çocuk büyür yumak yumak bir nurdan,

Burda ben...

Koştuğu, atladığı, durduğu, uzandığı,

Düşüp kaldığı yerlerde gözbebeğim var.

Orda, toz-toprak içinde bir çocuk ağlar,

Burda ben...

Ne oyun oynamak ister, ne uyku ne su,

Ne elişi resimleri gönlünü alır.

Orda, bir uzak evde bir çocuk yetim kalır,

Burda ben...

Dokunsam, martı gibi uçup gidecek sanki,

Solgun yüzlü bir avuç kar.

Orda, bir gece yarısı, bir hasta çocuk sayıklar,

Burda ben...

Birden bire uyanır bir ana uykusundan,

Sapsarı bir korkuyla bakakalır nefessiz.

Orda, sabaha karşı bir çocuk ölür sessiz,

Burda ben...', 'Bir ana gülümserken yorgun ve güzel Yüreği müjdelerle tüy gibi hafiflerken, Orda, bir çocuk doğar sımsıcak dünyamıza Burda ben... Dal nasıl,...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bülent Bakiler']::text[], 8.5, '{"poet":"Yavuz Bülent Bakiler","poet_slug":"yavuz-bulent-bakiler","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/orda-bir-cocuk-burda-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiklâl Marşı', 'i-stikl-l-marsi-mehmet-akif-ersoy-wor5d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '-Kahraman Ordumuza-

Korkma, sönmez bu şafaklarda yüzen al sancak; 

Sönmeden yurdumun üstünde tüten en son ocak.

O benim milletimin yıldızıdır, parlayacak; 

O benimdir, o benim milletimindir ancak.

Çatma, kurban olayım, çehreni ey nazlı hilâl! 

Kahraman ırkıma bir gül... Ne bu şiddet, bu celâl? 

Sana olmaz dökülen kanlarımız sonra helâl; 

Hakkıdır, Hakk’a tapan, milletimin istiklâl.

Ben ezelden beridir hür yaşadım, hür yaşarım.

Hangi çılgın bana zincir vuracakmış? Şaşarım! 

Kükremiş sel gibiyim: Bendimi çiğner, aşarım; 

Yırtarım dağları, enginlere sığmam taşarım.

Garb’ın âfâkını sarmışsa çelik zırhlı duvar; 

Benim îman dolu göğsüm gibi serhaddim var.

Ulusun, korkma! Nasıl böyle bir îmânı boğar,

«Medeniyyet! » dediğin tek dişi kalmış canavar? 

Arkadaş! Yurduma alçakları uğratma sakın; 

Siper et gövdeni, dursun bu hayâsızca akın.

Doğacaktır sana va’dettiği günler Hakk’ın...

Kim bilir, belki yarın, belki yarından da yakın.

Bastığın yerleri «toprak! » diyerek geçme, tanı! 

Düşün altındaki binlerce kefensiz yatanı.

Sen şehîd oğlusun, incitme, yazıktır, atanı:

Verme, dünyâları alsan da, bu cennet vatanı.

Kim bu cennet vatanın uğruna olmaz ki fedâ? 

Şühedâ fışkıracak toprağı sıksan, şühedâ! 

Cânı, cânânı, bütün vârımı alsın da Hudâ,

Etmesin tek vatanımdan beni dünyâda cüdâ.

Rûhumun senden İlâhî şudur ancak emeli:

Değmesin ma’bedimin göğsüne nâ-mahrem eli; 

Bu ezanlar -ki şehâdetleri dînin temeli-

Ebedî, yurdumun üstünde benim inlemeli.

O zaman vecd ile bin secde eder -varsa- taşım; 

Her cerîhamdan, İlâhî, boşanıp kanlı yaşım,

Fışkırır rûh-i mücerred gibi yerden na’şım! 

O zaman yükselerek Arş’a değer, belki, başım.

Dalgalan sen de şafaklar gibi ey şanlı hilâl! 

Olsun artık dökülen kanlarımın hepsi helâl.

Ebediyyen sana yok, ırkıma yok izmihlâl:

Hakkıdır, hür yaşamış, bayrağımın hürriyyet; 

Hakkıdır, Hakk’a tapan, milletimin istiklâl.', '-Kahraman Ordumuza- Korkma, sönmez bu şafaklarda yüzen al sancak;  Sönmeden yurdumun üstünde tüten en son ocak. O benim milletimin yıldızıdı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Ersoy']::text[], 8.5, '{"poet":"Mehmet Akif Ersoy","poet_slug":"mehmet-akif-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/istiklal-marsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melhem', 'melhem-mukerrem-mete-lbs8q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşka melhem aranmaz

Aşk melhemler sultanıdır

Bu derde derman aranmaz

Bu dert dertler dermanıdır

Aşka melhemler aranmaz

Aşk melhemler sultanıdır', 'Aşka melhem aranmaz Aşk melhemler sultanıdır Bu derde derman aranmaz Bu dert dertler dermanıdır Aşka melhemler aranmaz Aşk melhemler sultanı...', ARRAY['Türk Edebiyatı','Şiir','Mükerrem Mete']::text[], 8.5, '{"poet":"Mükerrem Mete","poet_slug":"mukerrem-mete","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/melhem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyorlar', 'diyorlar-metehan-sariyakutoglu-qj2fl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgi diyorlar, sevda diyorlar,

Kavrulup bir ateşte yanma diyorlar.

Umutsuz bir yolculuktur çıktığın,

Bahtın kara olur, yapma diyorlar.

Aşk koymuşlar adını, belki sevi.

Talan olup tutuşurmuş can evi.

Güneşin karı yendiği gibi,

Eriyip gidersin aşkta diyorlar.

Bak, dün yaşayandı bu gün bir masal.

Hiç olmazsa bir bak da ibret al.

Mecnun''a, Ferhat''a maloldu bu hal.

Düşüp tutuşursun, etme diyorlar.

Kiminin ekmeğiydi kiminin aşı,

Kiminin uğruna can koyduğu, başı...

Sonunda toprak kazanır vahim savaşı,

Aşkın sonu yoktur, düşme diyorlar.

Sarıyakutoğlu da vuruldu kalpten,

İflah etmez derdi götürür hepten,

Bir kulu sevmiş de yanarmış içten,

Bu yüzden durmadan ağlar diyorlar.

(İstanbul: 01/04/2000)', 'Sevgi diyorlar, sevda diyorlar, Kavrulup bir ateşte yanma diyorlar. Umutsuz bir yolculuktur çıktığın, Bahtın kara olur, yapma diyorlar. Aşk ...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/diyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benle Savaş', 'benle-savas-neslihan-yilmaz-9tibt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seninle uzlasayim derken, benle savastim.

Bilemezdim savasin seninde icinde oldugunu.

Yuregim kent sokaklari gibi simdi,

Karisik, gurultulu, bogucu

Her taraf karbodioksit,

Boguluyorum.

Oysa dingin huzurlu bir vadiydim senden once.

Daglarim vardi,

Arindigim irmaklarim,

Kosup,costugum yaylalarim.

Memleketinden kopmus gurbet cocugu gibiyim.

Anlasilamiyorum...

Seni degil yureksiz,ben vadimi ozluyorum.

Bulutlarimin beyazi yok,

Doralarimin isiklari coktan gitmis.

Vadim bir asir kadar uzak.

Kalakaldim bu kent cikmazinda...

                                                   

                                                            27-05-2000', 'Seninle uzlasayim derken, benle savastim. Bilemezdim savasin seninde icinde oldugunu. Yuregim kent sokaklari gibi simdi, Karisik, gurultulu,...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Yilmaz']::text[], 8.5, '{"poet":"Neslihan Yilmaz","poet_slug":"neslihan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/benle-savas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızlanış', 'sizlanis-metehan-sariyakutoglu-2hc4k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine haykırıyor dingin, sessiz dalgalar,

Duyumsuz kulağımda balyoz gibi iniltisi.

Bu genel sineme, kaçıncı uzun bahar?

Berraklığa paydos etmiş turnanın sesi.

Çarpmakta göğsüme ılık bir rüzgar,

Yüreğimde yine, matem var, hüzün var.

Umutlarımın önünde dikilen dağlar,

Yine ensemde mi feleğin nefesi?

Bak güneş doğuyor bütün umutlara,

Açan her çiçeğin selamı var mutluluğa,

Bir ben yokum sanki, kayıtlarda,

Öylesine buruk ki kalbimin sesi...

Belki başımı alıp dalsam uzaklara,

Kaç bilinmeyenli ses düşer peşime hatta,

Boş versem dünyayı çıksam dağlara,

Birer kurt olur her şey kemirir içimi...

(İstanbul: 10/05/2000)', 'Yine haykırıyor dingin, sessiz dalgalar, Duyumsuz kulağımda balyoz gibi iniltisi. Bu genel sineme, kaçıncı uzun bahar? Berraklığa paydos etm...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sizlanis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tasvir', 'tasvir-metehan-sariyakutoglu-nqdkg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bak yine rüzgar dondu.

Buz savrulmakta her yan.

Şelaleler kurudu.

Hüzün nerde? Ağlayan? 

Bir hasır attım yere,

Yalın ayak üstünde,

Bir de kalbimi koydum,

Binbir hüzün içinde...

Elimde Kuru Soğan,

Ekmektir katık olan,

Yüreğim ferah olsun,

Azığımsa hep yavan...

Bildiğim budur dostlar,

Güneşim belki doğar,

Doğmazsa da tasam yok,

Dostumdur karanlıklar.

(İstanbul: 10/06/2000)', 'Bak yine rüzgar dondu. Buz savrulmakta her yan. Şelaleler kurudu. Hüzün nerde? Ağlayan?  Bir hasır attım yere, Yalın ayak üstünde, Bir de ka...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tasvir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kül''den Güzel', 'kul-den-guzel-i-lhan-dogan-eq2tz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sanat geceyi yırtarak geçti

İçimden bir ''sen'' geçti

Sürterek saçlarını tenime

İçimden bilsen ateş geçti

Uzun uzadıysa yandı

Ardın sıra külü geçti.

Uzak şehirlere çok vardı

Aklımdan yolculuklar geçti

Gözlerim bir otobüs aradı

İçimde otoyollar,

Araçlar durmaksızın geçti

Soğuk yemiştim, beter üşümüştüm

Orta yerde düşmüştüm

Gözlerini düşünmüştüm

İçimden bir ''ısınmak'' geçti

Düşünmesem ölmüştüm.

Sevsem.

Vakit çok geçti

O saatte bütün sevdalar kapalıydı

Ben telaşta sağı solu aranırken

İçimden nöbetçi bir aşk geçti.

''Yar'' diye başladım

Bütün cümlelerime

Dilimden bir eski gazel geçti

Mürekkep bulaşır mı

Hokkayla yazsan bir kalbin üstüne

Kalbime bulaştı ismin

İçimden bir özge güzel geçti.', 'Sanat geceyi yırtarak geçti İçimden bir ''sen'' geçti Sürterek saçlarını tenime İçimden bilsen ateş geçti Uzun uzadıysa yandı Ardın sıra külü ...', ARRAY['Türk Edebiyatı','Şiir','İlhan Doğan']::text[], 8.5, '{"poet":"İlhan Doğan","poet_slug":"i-lhan-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kul-den-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüsek Seninle Ne Var', 'yurusek-seninle-ne-var-mehmet-turan-yarar-hrxay', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yürüsek seninle ne var 

Şöyle çağlardan dışarı

Zincirde eller ayaklar

Yürek bağlardan dışarı

Unutulsak unutarak

Varı yokla bir tutarak

Bütün ölmüşlerden ırak

Bütün sağlardan dışarı

Tutma kurtulsun heceler

Uçuyor bak birer birer

Zihnimdeki düşünceler

Yanardağlardan dışarı', 'Yürüsek seninle ne var  Şöyle çağlardan dışarı Zincirde eller ayaklar Yürek bağlardan dışarı Unutulsak unutarak Varı yokla bir tutarak Bütün...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Turan Yarar']::text[], 8.5, '{"poet":"Mehmet Turan Yarar","poet_slug":"mehmet-turan-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yurusek-seninle-ne-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni mi Sevdim Ben', 'seni-mi-sevdim-ben-neslihan-yilmaz-acije', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neden seni sevdim ben bilmem.

Neden bilmem bu unutamayisim, 

Kendime kizisim,sende kalisim.

Anlasilmaz bu,

Sana sevgili derken ki kendimi suclayisim...

Ikiye boldun beni,

Eksilerde buldum seni...

Basit ask varsa ben onu istiyorum.

Sev ve cok sevil.

Dusunme,carpma,bolme,

Eldeki bucuklarda kalma.

Dolu dolu yasa.

Supheler,ikilemler, 

Kendime kizislar,

Ona kizamamayi sevgi sanislar.

Hepsi hata !

Bilmem ki niye kandirdim beni...', 'Neden seni sevdim ben bilmem. Neden bilmem bu unutamayisim,  Kendime kizisim,sende kalisim. Anlasilmaz bu, Sana sevgili derken ki kendimi su...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Yilmaz']::text[], 8.5, '{"poet":"Neslihan Yilmaz","poet_slug":"neslihan-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seni-mi-sevdim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bize Bugün Yeter', 'bize-bugun-yeter-metehan-sariyakutoglu-u4lyk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neyin var?

Üşüdün mü?

Karnın mı aç yavrum?

Bir dilim ekmeğimin yarısı senin.

Belki de hepsi... ne diyeyim?

Yırtık kabanımı da vereyim,

Sen mahsun olma,

Ağlama yeter....

Işıldayan yıldızlardan bize ne?

Ne anlarız sevgilinin dudaklarından?

Ekmeğin yanında soğana bayram ederiz.

Nasır tutmuş çöplüklerde ellerimiz.

Rahat olsun vicdanımız ve de;

Açık olsun alnımız yeder.

Bak şanslıyız bu gün;

Kediden artan peynir var yemekte,

Birkaç ekmek kırıntısıyla beraber,

Yarısı çürük yeşil biber...

Tuz yok taştan masamızda,

Bir bardakda su olsun yeter.

Yarınlar belki yok,

Esmerleşen ellerimizin arasında.

Belki umutlarımız sönük durur ufuklarda,

Biz dertlenmeyelim, isyan etmeyelim yine.

Şükredelim halimize,

Bize bu günümüz yeter.

(İstanbul: 10/06/2000)', 'Neyin var? Üşüdün mü? Karnın mı aç yavrum? Bir dilim ekmeğimin yarısı senin. Belki de hepsi... ne diyeyim? Yırtık kabanımı da vereyim, Sen m...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bize-bugun-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresizim', 'caresizim-sair-leyli-7ul3z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nedir bu cektigim izdirap?

Artik dayanacak gücüm kalmadi!

Ben seni cok severken,

Sen bundan habersiz sürdürüyorsun hayatini..

Oysa ne kadar cok isterdimki,

Sana hic olmazsa bir telefon acip,

Azda olsa konusmayi..

Fakat kendimemi, yoksa sana

Güvenemedigimdenmi bilmiyorum..?

Icimde bu cesareti bile bulamiyorum..

(Caresizim; yinede seviyorum..)', 'Nedir bu cektigim izdirap? Artik dayanacak gücüm kalmadi! Ben seni cok severken, Sen bundan habersiz sürdürüyorsun hayatini.. Oysa ne kadar ...', ARRAY['Türk Edebiyatı','Şiir','Şair Leyli']::text[], 8.5, '{"poet":"Şair Leyli","poet_slug":"sair-leyli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/caresizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılara Tutunuyorum', 'acilara-tutunuyorum-estrella-epcot-8h108', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yarın yine seni görmek umuduyla

Yatıyorum boş yatağıma

Yanımda, verdiğin o küçük yastığa

Sarılıyorum sımsıkı

Acılara tutunuyorum

yatağımın bir ucunda

Bana gülümseyişini 

Göz kırpışını hatırladıkça

Darılıyorum anılarıma 

ve sonra canım, sen geliyorsun aklıma

Ağlıyorum yastığımda

Bataniyem ısıtmıyor beni 

Sevgiyi veremiyor baş ucumdaki bebeğim

Acılara tutunuyorum

Yatağımın bir ucunda

Gözlerini görüyorum

Ellerini tutuyorum 

Sonra kızıyorum sana', 'Yarın yine seni görmek umuduyla Yatıyorum boş yatağıma Yanımda, verdiğin o küçük yastığa Sarılıyorum sımsıkı Acılara tutunuyorum yatağımın b...', ARRAY['Türk Edebiyatı','Şiir','Estrella Epcot']::text[], 8.5, '{"poet":"Estrella Epcot","poet_slug":"estrella-epcot","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/acilara-tutunuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Olmalıyım', 'ben-olmaliyim-caglar-tanrikut-x60eh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kar tanesi olmalıyım,saçlarına yağan,

Pırıl pırıl parlamalıyım siyah saçlarında,

Bir rüzgar olmalıyım,sabahları esen,

Saçlarını dağıtmalıyım,gün ortasında.

Bir karanlık olmalıyım,ışıklar içinde,

Korkutmalıyım seni,ağlatmalıyım belkide,

Ardından gözyaşların olmalıyım,

Silmelisin beni,anden yok olmalıyım.

Ben olmalıyım,umudum,sevdiğin,

Geceleri seyrettiğin yıldızlar olmalıyım,

Yağmurlu bir akşamda beklediğin,

O sarhoş adam ben olmalıyım.', 'Bir kar tanesi olmalıyım,saçlarına yağan, Pırıl pırıl parlamalıyım siyah saçlarında, Bir rüzgar olmalıyım,sabahları esen, Saçlarını dağıtmal...', ARRAY['Türk Edebiyatı','Şiir','Çağlar Tanrıkut']::text[], 8.5, '{"poet":"Çağlar Tanrıkut","poet_slug":"caglar-tanrikut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-olmaliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Benim Sarhoşluğumsun', 'sen-benim-sarhoslugumsun-nazim-hikmet-ran-6sjwg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen benim sarhoşluğumsun

ne ayıldım

       ne ayılabilirim


..........
..........', 'Sen benim sarhoşluğumsun ne ayıldım        ne ayılabilirim .......... .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-benim-sarhoslugumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulut', 'bulut-cahit-irgat-30ntz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir damla düştü gözlerime

Geçen buluttan,

Hatırladım inanmanın ne olduğunu

Yaşamaya,şiire

Su yolundan uzaklaşmış

Ben su muyum,yol muyum?

Ok yayından uzaklaşmış

Ben ok muyum,yay mıyım?

Ben,buluttan gözlerime

Düşüveren bir damlayım.', 'Bir damla düştü gözlerime Geçen buluttan, Hatırladım inanmanın ne olduğunu Yaşamaya,şiire Su yolundan uzaklaşmış Ben su muyum,yol muyum? Ok ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Irgat']::text[], 8.5, '{"poet":"Cahit Irgat","poet_slug":"cahit-irgat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bulut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmuşum', 'sen-olmusum-emrah-mercan-tgjp8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne varsa aradığım, bilki sende bulmuşum 

Senden öncesi yoktu, seninle var olmuşum 

Sende bütün ümitler, sende bütün özlemler 

Beni bende arama, ben artık SEN olmuşum', 'Ne varsa aradığım, bilki sende bulmuşum  Senden öncesi yoktu, seninle var olmuşum  Sende bütün ümitler, sende bütün özlemler  Beni bende ara...', ARRAY['Türk Edebiyatı','Şiir','Emrah Mercan']::text[], 8.5, '{"poet":"Emrah Mercan","poet_slug":"emrah-mercan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-olmusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tahirle Zühre Meselesi', 'tahirle-zuhre-meselesi-nazim-hikmet-ran-ki8vk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tahir olmak da ayıp değil Zühre olmak da

hattâ sevda yüzünden ölmek de ayıp değil,

bütün iş Tahirle Zühre olabilmekte

yani yürekte.

Meselâ bir barikatta dövüşerek

meselâ kuzey kutbunu keşfe giderken

meselâ denerken damarl
..........
..........', 'Tahir olmak da ayıp değil Zühre olmak da hattâ sevda yüzünden ölmek de ayıp değil, bütün iş Tahirle Zühre olabilmekte yani yürekte. Meselâ b...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tahirle-zuhre-meselesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Yağmurları', 'guz-yagmurlari-murat-cicek-hjedz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bakışların üzgün

Gözlerin nemli

Ne o sevgilim ağlıyor musun?

Yüreğin kederli

Ömrün gam dolu

Yoksa kahroluyor musun?

Hasretin bağrımda yanıyor

Alevler içindeyim

Bulutlar bile haline ağlıyor

Güz yağmurları senin için yağıyor 

Ağlamak istiyorum 

Gözlerim şişinceye dek

Takatım kalmadı artık yaşamaya

Ne yana baksam seni görüyorum

Seni sensiz yaşamak ızdırap 

Seni sensiz yaşamak zulüm 

Anlıyorum sevgilim 

Seni sensiz yaşamak ölüm

Hiç kimsem yok şu yalancı dünyada

Sarılacak dostum

Halime ağlayacakbir bulutum bile yok

Sen şanslısın, senin kaderin güzel', 'Bakışların üzgün Gözlerin nemli Ne o sevgilim ağlıyor musun? Yüreğin kederli Ömrün gam dolu Yoksa kahroluyor musun? Hasretin bağrımda yanıyo...', ARRAY['Türk Edebiyatı','Şiir','Murat Çiçek']::text[], 8.5, '{"poet":"Murat Çiçek","poet_slug":"murat-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/guz-yagmurlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnciTanem', 'i-ncitanem-gokay-gokulu-rqvkx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'nasıl da bakmıştık birbirimize

unuttun mu yoksa ?

ben mi

ben unutamadım seni incitanem

ben hayatla dalga geçtim

derinlere daldım

maymun iştahlıydım

çünki derinlerde en güzel inci var dı ama çıkamadım

yardım et bana inci tanem

yardımet ki seni derinlerden çıkarayım

yardım et ki seni kalbimin içine koyayım

yardım et ki seni o tuzlu sudan kurtarıp

kızıl kanıma bulayım

yardım et bana 

yardım et bana inci tanem', 'nasıl da bakmıştık birbirimize unuttun mu yoksa ? ben mi ben unutamadım seni incitanem ben hayatla dalga geçtim derinlere daldım maymun işta...', ARRAY['Türk Edebiyatı','Şiir','Gökay Gökulu']::text[], 8.5, '{"poet":"Gökay Gökulu","poet_slug":"gokay-gokulu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/incitanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedenlere Karıştım', 'nedenlere-karistim-alacan-yagmur-56ruc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nedenlere karıştım..

Vede gitmeler sonum..

..

Nedenlere sordum..

Sösüz cevapsız..sesizlikler

gece bitişi kapmda..

...

Çalan yok.. uzun bir zaman oldu..

Oysa ..

Cevap geleli çok zaman olmuştu..

Bu çaba neye...

....

Vaz geçmişilik bende olsun dedim..

Sabahlara karıştım..

Uyumak ne haddime..

...

Ben sevgilere karıştım..

Kör düğüm oldum..

Çözmek sadece 

Dondurucu gidişlerse..

Bu da benden olsun.......', 'Nedenlere karıştım.. Vede gitmeler sonum.. .. Nedenlere sordum.. Sösüz cevapsız..sesizlikler gece bitişi kapmda.. ... Çalan yok.. uzun bir z...', ARRAY['Türk Edebiyatı','Şiir','Alacan Yağmur']::text[], 8.5, '{"poet":"Alacan Yağmur","poet_slug":"alacan-yagmur","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nedenlere-karistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Sevdaya Dahil 2', 'ayrilik-sevdaya-dahil-2-attila-i-lhan-rswio', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yalnızlık

hızla alçalan bulutlar

              karanlık bir ağırlık 

hava ağır toprak ağır yaprak ağır

su tozları yağıyor üstümüze

özgürlüğümüz yoksa yalnızlığımız mıdır

              eflatuna çalar puslu lacivert

                       bir sis kuşattı ormanı

              karanlık çöktü denize

yalnızlık 

çakmak taşı gibi sert

              elmas gibi keskin

ne yana dönsen bir yerin kesilir

              fena kan kaybedersin

kapını bir çalan olmadı mı hele

elini bir tutan

bilekleri bembeyaz kuğu boynu

              parmakları uzun ve ince

sımsıcak bakışları suç ortağı

              kaçamak gülüşleri gizlice

yalnızların en büyük sorunu

tek başına özgürlük ne işe yarayacak

bir türlü çözemedileri bu

              ölü bir gezegenin

                        soğuk tenhalığına

                               benzemesin diye

özgürlük mutlaka paylaşılacak 

              suç ortağı bir sevgiyle', 'yalnızlık hızla alçalan bulutlar               karanlık bir ağırlık  hava ağır toprak ağır yaprak ağır su tozları yağıyor üstümüze özgürlüğü...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ayrilik-sevdaya-dahil-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Soldu', 'dus-soldu-mustafa-korkmaz-dincer-7xxbi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karanlıklara gömüldü

Umutları suların

Gün güzelliğinin

Doruğunda boğuldu

Her gece

Düşlerine girdim sevdiklerimin

Takılıp kaldığım 

Anılarım da oldu

Ne varsa topladım

Sevdadan yana

Yüreğim senden uzaklarda

Çilelerle doldu

Sular daldı

Derin bir uykuya

Günün yarattığı 

Düş soldu', 'Karanlıklara gömüldü Umutları suların Gün güzelliğinin Doruğunda boğuldu Her gece Düşlerine girdim sevdiklerimin Takılıp kaldığım  Anılarım ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Korkmaz Dinçer']::text[], 8.5, '{"poet":"Mustafa Korkmaz Dinçer","poet_slug":"mustafa-korkmaz-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dus-soldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereden Sevdim', 'nereden-sevdim-mustafa-korkmaz-dincer-nh3jk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çırpındım uçmak için

Kırık kanatlarımla

Bata çıka takalarla

Umut taşıdım sevdalılara

Yeniden çiçek açtım 

Solan kırlarda

Düşkırıklıklarıyla 

Çıkma karşıma

Umudumu kırmasın gözlerin

Sevmeseydim keşke

Nereden sevdim

İlkbahar akşamlarında

Ya bulutlara takıldım 

Ya kuşlara

Senden uzaklarda

Soluksuz kalsam da

Bulutların tülbent gibi

Sarıldığı dağlarda

Ayrılığın acısını 

Seni sevdim de öğrendim 

Sevmeseydim keşke

Nereden sevdim 

Toprağı uyandırır

Bir sancı baharla

Düşlerinde vurgun yemiş

Sevdalılarla

Güvercinler gibi

Aldandım sevdaya

Batan güneşin rengi

Düşerken sulara

Yeniden tutuştu

Küllenen ateşi yüreğimin

Sevmeseydim keşke

Nereden sevdim', 'Çırpındım uçmak için Kırık kanatlarımla Bata çıka takalarla Umut taşıdım sevdalılara Yeniden çiçek açtım  Solan kırlarda Düşkırıklıklarıyla ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Korkmaz Dinçer']::text[], 8.5, '{"poet":"Mustafa Korkmaz Dinçer","poet_slug":"mustafa-korkmaz-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/nereden-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şeyler Kalmamış Eskilerden', 'bir-seyler-kalmamis-eskilerden-mustafa-korkmaz-dincer-23m91', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdasız geçen günler

         kayıp ömürden

Ne bir gülüş

Ne de bir düş

         gecelerimi süsleyen

Ne bulursam toplayıp

Dünden bugünden

Uzaklara kaçmak geçer 

         gönlümden

Yalnız anılar kalmış

Susmak bilmeyen gecelerden

Su içerek büyümüş

         sevdalar yüreğimden

Unutttum günün yorgunluğunu

Güvercinlerin dönüşlerini

         beklerken

Ne tanıdık bir yüz

Ne de bildik bir ses

Sokaklardaki insan selinden 

Çiçekler ayaklara serilmiş

         bahar kapıları aralarken

Silmiş süpürmüş

         zaman her şeyi

Bir şeyler kalmamış

         eskilerden', 'Sevdasız geçen günler          kayıp ömürden Ne bir gülüş Ne de bir düş          gecelerimi süsleyen Ne bulursam toplayıp Dünden bugünden Uz...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Korkmaz Dinçer']::text[], 8.5, '{"poet":"Mustafa Korkmaz Dinçer","poet_slug":"mustafa-korkmaz-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-seyler-kalmamis-eskilerden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen de Her Şey Gibi', 'sen-de-her-sey-gibi-cahit-sitki-taranci-7h6q0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen de her şey gibi,yakınımda iken,

Sen de oluyorsun gözlerimde diken.

Git,git benden uzak,uzak bir yere git;

Ne olur,içimde her zaman bir ümit,

Her uzak şey gibi öyle yalnız hayal,

Yalnız rahiya,renk,şarkı halinde kal.', 'Sen de her şey gibi,yakınımda iken, Sen de oluyorsun gözlerimde diken. Git,git benden uzak,uzak bir yere git; Ne olur,içimde her zaman bir ü...', ARRAY['Türk Edebiyatı','Şiir','Cahit Sıtkı Tarancı']::text[], 8.5, '{"poet":"Cahit Sıtkı Tarancı","poet_slug":"cahit-sitki-taranci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-de-her-sey-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizlerin Beklediği', 'denizlerin-bekledigi-afsar-timucin-n6vrw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni sevmek mor denizlerdi biraz

Ne kadar gidilse bir o kadar bitmeyen

Umutlar ve yıkılmalar ardında direnilen 

Seni sevmek mevsimler içinde en güzel yaz 

Seni sevmek yaşamın aşılmaz büyüklüğü 

Seni sevmek kan dolu yüzyılları korkutan 

Ve sığınıp ılık kıyı kentlerinde biraz akşam 

Seni sevmek çocukların düşlerinde gördüğü

Varılırdı daha saydam günlere isteseler 

İsteseler yalnızlık giremezdi evlere 

Seni sevmek bir kırlangıç olacak bekleseler 

Ve uçacak durmadan adasız denizlere 

Kim bulacak cam kırığı gözlerinde sevgimi 

Sonra yalnız kalmak gibi yoksulca uğuldayan 

Bütün okyanusların baş eğdiği tek kaptan 

Sana verdim geç diye bütün denizlerimi', 'Seni sevmek mor denizlerdi biraz Ne kadar gidilse bir o kadar bitmeyen Umutlar ve yıkılmalar ardında direnilen  Seni sevmek mevsimler içinde...', ARRAY['Türk Edebiyatı','Şiir','Afşar Timuçin']::text[], 8.5, '{"poet":"Afşar Timuçin","poet_slug":"afsar-timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/denizlerin-bekledigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karabiber', 'karabiber-bedri-rahmi-eyuboglu-787fa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İzmir''de bir ağaç gördüm

Adı karabiberdi karabiber

Yaprağının ucunu ısırdım

Tadı karabiberdi karabiber.

Bir yaşıma daha girdim

Biber dediğin tuzluğa yaraşır

Fidesi olur fidan olur

Bir çınar boyunda karabiber

İnsanın başı döner

Çiçek mi, meyva mı, tohum mu nedir

Nar tanesi gibi pırıl pırıl

Çingen pembesinden sıcak

Karabiber ağaçlar dolusu

Karabiber sebil

Karabiber salkım saçak

İzmir''de bir ağaç gördüm

Adı karabiberdi

Ya karabiber türküsü Allahım

Necati Cumalı söylerdi

Soba borusu gibi bir sesi vardı

Karabiberim, derdi karabiberim

Candarmalar geliyor kalk gidelim

İzmir´de bir ağaç gördüm

Adı karabiberdi

Benim,avuç içi kadar saksılarda

Asma kütükleri,yeşerten anam

Bu ağacı görse sevincinden ağlardı

İzmir´de bir ağaç gördüm

Adı karabiberdi

Dalını,meyvasını,gölgesini

Getirdi masamıza serdi

Yapraklarını görsen bayılırsın

Bir yazma oyası kadar ince

Söğüt dallarından narin

Saçlarının arasında dolaştığını duyarsın

İncecik biberli ellerin', 'İzmir''de bir ağaç gördüm Adı karabiberdi karabiber Yaprağının ucunu ısırdım Tadı karabiberdi karabiber. Bir yaşıma daha girdim Biber dediğin...', ARRAY['Türk Edebiyatı','Şiir','Bedri Rahmi Eyüboğlu']::text[], 8.5, '{"poet":"Bedri Rahmi Eyüboğlu","poet_slug":"bedri-rahmi-eyuboglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/karabiber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni HergünSevmek', 'seni-hergunsevmek-turgut-yuca-iawdq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni hergün sevmek

En kötü kader olsa gerek 

Seni hergün sevmek

Boş ağızlarda ki demsiz öpücük.

Seni hergün sevmek

Belalı bir gün olsa gerek

Nereye uğrasan toz, duman, kargaşa

Ve sensizlikse söylenmeyen söz.

Seni hergün sevmek 

Hergün parçalanmak demek,

Bu sonsuz gidişte bir an soluklanmadan

Gitgide erimek, seni sevmek..

Seni hergün sevmek

Dost ağızlarda aşağılanmak demek

Dostlukların bile para etmediği

Bu köhne, çürümüş çatı altında.

Seni hergün sevmek

Hergün ölmek demek,

Yatağa her uzanışımda

Üzerimde yığınca toprak.

Seni sevmek olmadan

Hergün.

Seni sevmek gün be gün

Ve yeterince ölünce 

Bir daha bir daha ölmek.

Ne kötü bir kader olsa gerek.', 'Seni hergün sevmek En kötü kader olsa gerek  Seni hergün sevmek Boş ağızlarda ki demsiz öpücük. Seni hergün sevmek Belalı bir gün olsa gerek...', ARRAY['Türk Edebiyatı','Şiir','Turgut Yuca']::text[], 8.5, '{"poet":"Turgut Yuca","poet_slug":"turgut-yuca","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-hergunsevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım', 'askim-tarik-akbaba-5uoh9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben susuz çöller misali,sen yağmurumsun,

Ben karanlık geceler misali, sen gündüzümsün,

Ben mejnun misali, sen hasretimsin,

Nerelerdesin ey karagözlüm, nerlerdesin.', 'Ben susuz çöller misali,sen yağmurumsun, Ben karanlık geceler misali, sen gündüzümsün, Ben mejnun misali, sen hasretimsin, Nerelerdesin ey k...', ARRAY['Türk Edebiyatı','Şiir','Tarık Akbaba']::text[], 8.5, '{"poet":"Tarık Akbaba","poet_slug":"tarik-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/askim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaş 25, Yolun yarısından 10 eksik', 'yas-25-yolun-yarisindan-10-eksik-ozlem-tasdemir-2h278', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaş 25, yolun yarısından 10 eksik 

(C.Sıtkı Tarancı’ yı baz alırsak) 

Kaç hayat sığdı, kaç sevgi, 

kaç hazan ? 

kaç ? kaç? 

Daha fazlasını yaşamak için 

Uğraşmak gereksiz. 

Bu saatten sonra, 

Seyr hali güzel 

Yaşamakta olanların çabasını...

Bu yaşam, 

Kitap gibi....

Sen bir iki günde okursun 

O, bir iki ayda

Sen 25 yılda yaşarsın, tüketirsin 

O, 55 inde hala çabalar, açtır, eksiktir.

Sen birkaç kitap yazarsın.

O, sadece sayfalarca müsfette.

Yolun yarısına varmadan

Yarıladın hayatı. 

Sadece seyr hali güzel 

Diğer yaşayanları.

Artık çekilmelisin köşene

Ve dalmalısın arşivlenen fotoğraflara.

Renkleri uçuncaya kadar...

(haziran,2000)', 'Yaş 25, yolun yarısından 10 eksik  (C.Sıtkı Tarancı’ yı baz alırsak)  Kaç hayat sığdı, kaç sevgi,  kaç hazan ?  kaç ? kaç?  Daha fazlasını y...', ARRAY['Türk Edebiyatı','Şiir','Özlem Taşdemir']::text[], 8.5, '{"poet":"Özlem Taşdemir","poet_slug":"ozlem-tasdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yas-25-yolun-yarisindan-10-eksik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Basitçe', 'basitce-ozlem-tasdemir-ghjv8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Günlük bulmaca gibisin;

soldan sağa,yukarıdan aşağıya

çok kolay çözülüyorsun.

Seyrettiğim televizyon gibisin;

tam ayarın yok

tüm kanallarda sen varsın

görüntüler bozuk...

Yaptığım tablosun;

tüm siyah boyalar

senin için kullanılmış.

Meyve gibisin,

çürüklerin atıldığında 

geriye pek bir şeyin kalmamış.

(Nisan,97)', 'Günlük bulmaca gibisin; soldan sağa,yukarıdan aşağıya çok kolay çözülüyorsun. Seyrettiğim televizyon gibisin; tam ayarın yok tüm kanallarda ...', ARRAY['Türk Edebiyatı','Şiir','Özlem Taşdemir']::text[], 8.5, '{"poet":"Özlem Taşdemir","poet_slug":"ozlem-tasdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/basitce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutursun Mihribanım', 'unutursun-mihribanim-abdurrahim-karakoc-c14p5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '“Unutmak kolay mı? ” deme

Unutursun Mihriban’ım.

Oğlun, kızın olsun hele

Unutursun Mihriban’ım.

Zaman erir kelep kelep..

Meyve dalında kalmaz hep.

Unutturur birçok sebep 

Unutursun Mihriban’ım.

Yıllar sinene yaslanır

Hâtıraların paslanır.

Bu deli gönlün uslanır...

Unutursun Mihriban’ım.

Süt emerdin gündüz-gece 

Unuttun ya, büyüyünce...

Ha işte tıpkı öylece

Unutursun Mihriban’ım.

Gün geçer, azalır sevgi 

Değişir her şeyin rengi.

Bugün değil, yarın belki

Unutursun Mihriban’ım.

Düzen böyle bu gemide

Eskiler yiter yenide.

Beni değil, sen seni de

Unutursun Mihriban’ım.

(Dosta Doğru)', '“Unutmak kolay mı? ” deme Unutursun Mihriban’ım. Oğlun, kızın olsun hele Unutursun Mihriban’ım. Zaman erir kelep kelep.. Meyve dalında kalma...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/unutursun-mihribanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşı Çiçekleri', 'gozyasi-cicekleri-adnan-adiguzel-xkrou', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Keske zaman acisa bana

geri donsem o yillara

anlatsam eski dostlara

okudugum kitabi

sokaklar bensiz kalsa

sigaramin dumani artik bir son bulsa

sevdiklerim keske beni anlasa

ama olmuyor iste 

yine masamda kitabimla basbasa

yine karanlik sokaklarda

sigaramla dudak dudaga

dolastim yalnizligin sehirlerinde

bazen bir kaldirima sarildim

paylastim ruyalarimi

birde yagmur yagardi hatirlayinca eski dostlari

yagardim belkide aglardim

anlamazdi kaldirim 

ha yagmur yagmis ha ben aglamisim 

ne farkeder bir damla su belki bir cicege bedel

bir cicek benden eski dostlara 

bir cicek yasanmamis eski yillara

bir ahh belkide 

can verirken soguk kaldirimda

neden diye sormadan saril

belki anlarsin yagmur mu yoksa ben miyim yagan

anlamazsan eski dostum

kurak bir mevsimde gel mezarima

gorursun o rengarenk gozyasi ciceklerini', 'Keske zaman acisa bana geri donsem o yillara anlatsam eski dostlara okudugum kitabi sokaklar bensiz kalsa sigaramin dumani artik bir son bul...', ARRAY['Türk Edebiyatı','Şiir','Adnan Adıgüzel']::text[], 8.5, '{"poet":"Adnan Adıgüzel","poet_slug":"adnan-adiguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gozyasi-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlığın Adı', 'yanlizligin-adi-seckin-sibreli-o2w8s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yanlızlığın adını sordun mu hiç?

Dostlarından,sevdiğinden ayrı kaldın mı...

Uyuyamadığın geceler oldu mu hiç?

Kendi kendine dertleştiğin oldu mu...

Sabahlara kadar düşündüğün oldu mu hiç?

Güneşin doğuşunu seyrettin mi pencereden...

Yanlızlıktan sıkılıp günleri saydın mı hiç?

Takvim yapraklarını kopardın mı sırayla...

Sokaktan geçen yabancıya bağırdın mı hiç?

Sevdiğine benzettiğin zamanlar oldu mu...

Çaresiz kalıp sigaraya,içkiye sarıldın mı?

Yanlızlığa,kadere isyan ettin mi hiç?

Neden diye sordun mu kendine...

Yanlızlığı sevebildin mi benim gibi...

Yanlız kalmayı öğrenebildin mi...

Peki ya yanlızlığın adını...

                                         (04.11.1999-Tekirdağ)', 'Yanlızlığın adını sordun mu hiç? Dostlarından,sevdiğinden ayrı kaldın mı... Uyuyamadığın geceler oldu mu hiç? Kendi kendine dertleştiğin old...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Sibreli']::text[], 8.5, '{"poet":"Seçkin Sibreli","poet_slug":"seckin-sibreli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yanlizligin-adi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünmeden', 'dusunmeden-seckin-sibreli-uh76b', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Denizin dalgaları seni benden alıp gitti

Yanlızlığımı hiç düşünmeden

Rüzgar elimi ellerinden fırtınalarla çekti

Sensiz yapamıyacağımı hiç düşünmeden

Kuşlar anılarımızı kanatlarına katıp gitti

Hasretini hiç düşünmeden

Ecel canımdan can alıp gitti

Seni sevdiğimi düşünmeden...', 'Denizin dalgaları seni benden alıp gitti Yanlızlığımı hiç düşünmeden Rüzgar elimi ellerinden fırtınalarla çekti Sensiz yapamıyacağımı hiç dü...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Sibreli']::text[], 8.5, '{"poet":"Seçkin Sibreli","poet_slug":"seckin-sibreli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dusunmeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Doğuşu', 'gunesin-dogusu-seckin-sibreli-ybjcb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben hiç güneşin doğuşunu izlemedim pencremden

Sabahlara kadar düşündüğüm sevgilimde olmadı zaten

Ben hiç güneşin doğuşunu dostlarımla karşılamadım

Konuşacak,dertleşecek dostumda yoktu zaten

Ben güneşin doğuşunu sokaklarda karşılamadım

Sıcak simitin yanında çayda içmedim zaten

Ben hiç güneşin doğuşunda balık tutmadım boğazda

Olta alacak kadar paramda yoktu zaten

Ben hiç güneşin doğuşunda mutluluk bulamadım

Yanlızlığımıda gideremedim zaten

Ben hiç güneşin doğuşundan haberdar değildim

Güneşin nasıl battığından da haberim yok zaten

Ben hiç güneşin doğuşunu görmedim ki

Güneşin doğduğuna da inanmıyorum zaten...', 'Ben hiç güneşin doğuşunu izlemedim pencremden Sabahlara kadar düşündüğüm sevgilimde olmadı zaten Ben hiç güneşin doğuşunu dostlarımla karşıl...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Sibreli']::text[], 8.5, '{"poet":"Seçkin Sibreli","poet_slug":"seckin-sibreli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gunesin-dogusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Gibi', 'olum-gibi-seckin-sibreli-wmbqi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çocuksu bir tebessümle öğrendim sevgiyi seninle

Sensizliği toprak dudaklarında duydum

Ölüm gibi...

Tükenmiş yüreğimde yaşadım ayrılığı

Gözyaşlarımla ıslattım yanlızlığımı

Yağmurlar gibi...

Gökyüzündeki kuştan öğrendim özgürlüğü

Gözlerinde yaşadım yıllarca esareti

Tutsak gibi...

Hüzünlü şarkılarda anlattım sevgimi

Satırlara döktüm anılarımı yüreğimle

Şiir gibi...

Yanlızlığı sevdim hasretinde

Yokluğunun acısını bir ben çektim

Ölüm gibi...', 'Çocuksu bir tebessümle öğrendim sevgiyi seninle Sensizliği toprak dudaklarında duydum Ölüm gibi... Tükenmiş yüreğimde yaşadım ayrılığı Gözya...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Sibreli']::text[], 8.5, '{"poet":"Seçkin Sibreli","poet_slug":"seckin-sibreli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olum-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ben', 'sen-ve-ben-sair-leyli-02228', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzun bir yol var aramizda; 

bir ucunda sen, bir ucunda ben.

Bir ates yaniyor icimde;

alevi sen, dumani ben.

Senin icin yazdigim  siirler;

kalemi sen, kagidi ben.

Ümitsiz gözyaslarim;

aglatan sen, aglayan ben.

Bekledim, bekleyecegim yillari;

..........    sen, ...........   ben.', 'Uzun bir yol var aramizda;  bir ucunda sen, bir ucunda ben. Bir ates yaniyor icimde; alevi sen, dumani ben. Senin icin yazdigim  siirler; ka...', ARRAY['Türk Edebiyatı','Şiir','Şair Leyli']::text[], 8.5, '{"poet":"Şair Leyli","poet_slug":"sair-leyli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliğin Ertesinde', 'sensizligin-ertesinde-seckin-sibreli-rvq4s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hafif bir rüzgar esti bu sokakta

Gittiğinin ertesinde...

Ardından ağlarcasına boşaldı yağmur

Usulca,ince ince...

Gözlerimden iki damla yaş aktı

Sensizliğin ertesinde', 'Hafif bir rüzgar esti bu sokakta Gittiğinin ertesinde... Ardından ağlarcasına boşaldı yağmur Usulca,ince ince... Gözlerimden iki damla yaş a...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Sibreli']::text[], 8.5, '{"poet":"Seçkin Sibreli","poet_slug":"seckin-sibreli","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sensizligin-ertesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Kızı', 'deniz-kizi-orhan-veli-kanik-n0w3a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Denizden yeni mi çıkmıştı neydi; 

Saçları, dudakları

Deniz koktu sabaha kadar; 

Yükselip alçalan göğsü deniz gibiydi.

Yoksuldu, biliyorum

-Ama boyna da yoksulluk sözü edilmez ya-

Kulağımın dibinde, yavaş yavaş,

Aşk türküleri söyledi.

Neler görmüş, neler öğrenmişti kim bilir,

Denizle buğaz buğaza geçen hayatında! 

Ağ yamamak, ağ atmak, ağ toplamak,

Olta yapmak, yem çıkarmak, kayık temizlemek...

Dikenli balıkları hatırlatmak için 

Elleri ellerime değdi.

O gece gördüm, onun gözlerinde gördüm; 

Gün ne güzel doğarmış meğer açık denizde! 

Onun saçları öğretti bana dalgayı; 

Çalkandım durdum rüyalar içinde.', 'Denizden yeni mi çıkmıştı neydi;  Saçları, dudakları Deniz koktu sabaha kadar;  Yükselip alçalan göğsü deniz gibiydi. Yoksuldu, biliyorum -A...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/deniz-kizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tahattur', 'tahattur-orhan-veli-kanik-mjp1m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Alnimdaki biçak yarasi 

Senin yüzünden;

Tabakam senin yadigarin;

''Iki elin kanda olsa gel'' diyor

Telgrafin;

Nasil unuturum seni ben,

Vesikali yarim?', 'Alnimdaki biçak yarasi  Senin yüzünden; Tabakam senin yadigarin; ''Iki elin kanda olsa gel'' diyor Telgrafin; Nasil unuturum seni ben, Vesikal...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tahattur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altın Dişlim', 'altin-dislim-orhan-veli-kanik-gxn2t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gel benim canimin içi, gel yanima;

Ipek çoraplar alayim sana;

Taksilere bindireyim,

Çalgilara götüreyim seni.

Gel,

Gel benim altin dislim;

Sürmelim, ondüle saçlim, yosmam;

Mantar topuklum, bopsitilim, gel.', 'Gel benim canimin içi, gel yanima; Ipek çoraplar alayim sana; Taksilere bindireyim, Çalgilara götüreyim seni. Gel, Gel benim altin dislim; S...', ARRAY['Türk Edebiyatı','Şiir','Orhan Veli Kanık']::text[], 8.5, '{"poet":"Orhan Veli Kanık","poet_slug":"orhan-veli-kanik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/altin-dislim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşlar da Uçtu Bu Kentten', 'kuslar-da-uctu-bu-kentten-kemal-tastekin-5drz8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevdanın ve korkunun imgeminde 

kar yangını bir geceydi zaman 

kekeme ve hırçın caddelerde

gecenin iz düşümünde

sonrası (z)bir yaşamdı doğum

sakalım, dünya ve intihar

birdaha tekrarlanmyacak

bir şarkı şimdi

    hem kuşlar da uçtu bu kentten', 'Sevdanın ve korkunun imgeminde  kar yangını bir geceydi zaman  kekeme ve hırçın caddelerde gecenin iz düşümünde sonrası (z)bir yaşamdı doğum...', ARRAY['Türk Edebiyatı','Şiir','Kemal Taştekin']::text[], 8.5, '{"poet":"Kemal Taştekin","poet_slug":"kemal-tastekin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kuslar-da-uctu-bu-kentten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Özgürlük', 'mavi-ozgurluk-kemal-tastekin-q9h77', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Halkım benim esaretimde

ben halkımın özgürlüğündeyim

yeryüzü suskun , öfkeli

ve özgürlüğe gebe

silahlar vahşete, dehşete

ve özgürlüğe giden yolda

ve toprakta

kan, barut, gözyaşı, zulüm

ve hepsinin içinde

kara toprakta yeşeren mavi özgürlük

ve gökte, denizde

ve kavganın ortasında yeşeren

boy atan asi sevdalar', 'Halkım benim esaretimde ben halkımın özgürlüğündeyim yeryüzü suskun , öfkeli ve özgürlüğe gebe silahlar vahşete, dehşete ve özgürlüğe giden ...', ARRAY['Türk Edebiyatı','Şiir','Kemal Taştekin']::text[], 8.5, '{"poet":"Kemal Taştekin","poet_slug":"kemal-tastekin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mavi-ozgurluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeyim''e', 'herseyim-e-hulya-yilmaz-38552', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerine şiir yazmayı denedim..

güzelliğini ifade edecek söz bulamadım.

Ellerinden bahsedeyim dedim..

sıcaklığını yansıtamadım.

Saçlarını anlatayım dedim..

yine başaramadım.

En sonunda gülümseyerek,

kocaman bir ''Seni Seviyorum''

kondurdum boş sayfaya ki

bunu asla tarif edemezdim....', 'Gözlerine şiir yazmayı denedim.. güzelliğini ifade edecek söz bulamadım. Ellerinden bahsedeyim dedim.. sıcaklığını yansıtamadım. Saçlarını a...', ARRAY['Türk Edebiyatı','Şiir','Hülya Yılmaz']::text[], 8.5, '{"poet":"Hülya Yılmaz","poet_slug":"hulya-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/herseyim-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine', 'oylesine-hulya-yilmaz-8kz35', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün yine herzamanki gibi seninle başladım güne

Çayımı yudumlarken, sigaramı içerken 

hep sen vardın içimde, hep sen varsın içimde

Bugün yine herzamanki gibi paramparça uyandım.

Yokluğunla kavrulan bu garip kente hiç alışamadım.

seni seviyorum diyorum yine, seni seviyorum diyorum

karşımda duran silik hayaline,

binlerce cansız nesnenin ortasında hiç kıpırtısız duruyorsun öylece.

Donuk gözlerinde bir ışık arıyorum, bir gözlerin aklımda zaten

birde ellerin, gerisi hikaye..

Birde dokunduğun iki üç nesne..

ben seni öylesine sevdim aslında, öylesine ağladım

sensiz soğuk gecelerde senden uzak bu şehirde..

Yürüdüğün caddelerde seni aradığım bile öylesineydi..

Üşüdüğüm yokluğunda, titrediği tüm bedenimin aklıma her geldiğinde.

Öylesineydi öylesine..

Öylesine sevdim ben seni, sırf sevmiş olmak için birilerini.

Sen inanma gülüm söylenenlere,

Adına şarkılar bestelediğim, şiirler yazdığım gözlerine,

dokunmaya kıyamadığım ellerinin izini taşıyan nesnelere dokunduğum yalan! ellerin diye..

Sen inanma gülüm söylenenlere

ben seni öylesine sevdim öylesine..

Sırf yanmış olmak için birilerine...', 'Bugün yine herzamanki gibi seninle başladım güne Çayımı yudumlarken, sigaramı içerken  hep sen vardın içimde, hep sen varsın içimde Bugün yi...', ARRAY['Türk Edebiyatı','Şiir','Hülya Yılmaz']::text[], 8.5, '{"poet":"Hülya Yılmaz","poet_slug":"hulya-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/oylesine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş Geceler', 'sarhos-geceler-hulya-yilmaz-0lqrf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bazen bir çığlıktır bozar sessizliği

bazen aşıkların şarkı sesleri

ya yıldızlar kayar gökten onu sayarsın

yada biran öylece bakar dalarsın

Bazen uykun kaçar da bir sigara yakarsın

ansızın geçmişine dalar ağlarsın

Kimi tanır seni kimine yalansın

Sen herşeyi bilirsin Sarhoş geceler.

Kıyamadım yatmaya bak uykum kaçtı.

Yine doldu gözlerim hüsranla taştı.

Dostlarım bağrımda yaralar açtı,

sen herşeyi saklarsın Sarhoş geceler.

İnsan bir sevdalandımı dost olur gecelere,

ismi dudaklarında bölünür hecelere,

birden burkulur kalbin dalarsın düşüncelere,

Sen yokmusun sen Sarhoş geceler..

E-mail: [email protected]', 'Bazen bir çığlıktır bozar sessizliği bazen aşıkların şarkı sesleri ya yıldızlar kayar gökten onu sayarsın yada biran öylece bakar dalarsın B...', ARRAY['Türk Edebiyatı','Şiir','Hülya Yılmaz']::text[], 8.5, '{"poet":"Hülya Yılmaz","poet_slug":"hulya-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sarhos-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm', 'gonlum-burak-barutcu-2vlio', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönlüm, 

İçindeki sevgi ateşini söndür. 

Yanıyorsun, kül olacaksın. 

Bir işe yaramayacaksın. 

Gönlüm, 

İçindeki korku buzlarını erit. 

Donuyorsun, taş olacaksın. 

Bir işe yaramayacaksın. 

Gönlüm, 

Cesaretini topla, yolundan git. 

Yoruluyorsun, tıkanıp kalacaksın. 

Bir işe yaramayacaksın. 

Gönlüm, 

Yaşanacak çok yılın var. 

Gidilecek çok yolun var. 

Verilecek çok sevgin var. 

Üzülme artık, 

Yıkıldın, yıkılacaksın. 

Sonra bir işe yaramayacaksın.', 'Gönlüm,  İçindeki sevgi ateşini söndür.  Yanıyorsun, kül olacaksın.  Bir işe yaramayacaksın.  Gönlüm,  İçindeki korku buzlarını erit.  Donuy...', ARRAY['Türk Edebiyatı','Şiir','Burak Barutçu']::text[], 8.5, '{"poet":"Burak Barutçu","poet_slug":"burak-barutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gonlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-burak-barutcu-9pkd1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün gökyüzüne baktığımda 

Çocukluğumun maviliği ile karşılaştım. 

Daldığımda; 

O mavilikte uçurduğum uçurtmamı, 

Ve babamın aldığı o mavi ayakkabıyı gördüm. 

Uyandığımda ise; 

Artık o tatlı maviliği bulamayacağımı, 

Ve herşeyden önce, 

Yaşadığımı, hayatı.. 

Sonunda ise ağladığımı gördüm. 

Ben, şimdide uçurtma uçurmak, 

Yeşil üzerinde doya doya uyumak, 

Uyandığımda babamla karşılaşmak istiyorum. 

Biliyorum, uzansam dokunacak, 

Birdaha bırakmayacağım... 

Ama uzan demiyor! 

Hep içinden, uzaktan seviyor, 

Ben uyurken beni sevdiğini anlıyor, 

Saçımı okşuyor başımda ağlıyor. 

Bu kadar zormu seni seviyorum demek, 

Bu kadar zormu beni sevmek? 

Ama herşeye rağmen seni çok seviyorum, 

Ben hep senin için uykusuz kaldım, 

Ve kendime; 

''''Niye ağlıyorsun'''' sorusunu sordum.. 

Biliyorum yanıtı, 

Baba olan, babası olan herkeste. 

Ve şimdi sende benim sarılığımda dal, 

Yokluğumda uyan sevgili BABAM', 'Bugün gökyüzüne baktığımda  Çocukluğumun maviliği ile karşılaştım.  Daldığımda;  O mavilikte uçurduğum uçurtmamı,  Ve babamın aldığı o mavi ...', ARRAY['Türk Edebiyatı','Şiir','Burak Barutçu']::text[], 8.5, '{"poet":"Burak Barutçu","poet_slug":"burak-barutcu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/babam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir şehirdir Ankara...', 'bir-sehirdir-ankara-emre-engin-mmdo6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aşksız ve kuraktır Ankara yalnızın,

Sahipsiz bakışlar gezer gölgelerde,

Anlamsız olur sevişmeler her vakit...

Bir hesap sorar gibidir esintileri,

Umarsızdır boş gezene Ankara.

Dalga geçer gibidir bazı zamanlar,

Hayatın tüm yükünü atar omuzlarına,

Özletir memleketini şuurlara,

Zahmetsizce çek git der arasıra,

Tiryaki olursun gidemezsin.

Ne kadar boş olsa da içtiğin çayın buharı,

Çektiğin cigaranın dumanı ve efkarı,

Seni çeker içine adeta Ankara...

Emsalsiz bir şaraptır,kadındır,

Senin olmasa da bir başka bakarsın...

Bazı gerilmiş ok olursun,bazı susamış yaz,

Hep bir tasa bir özlem sorar sana,

Ama yoktur, elin boş avcun boştur...

Ondandır dertsizliğinin derdi,

Ne memleketim diyebilirsin ne cennetim,

Yanan bir yürek olursan sönemezsin...

Erirsin sevda yükü taşıyosan,

Yamalı bir harita çizersin kendine,

İki sokak arası koşar durursun...

Gözlerindeki parıltı söner günden güne,

Anlamsızlaşır bakışların...

Hep bir uğultuya cevap verirsin,

Gereksiz dizeler dökülür kaleminden...

Duygusuz bir herif olu gözüne bazı,

Bazı platonik bir aşkla yaklaşırsın...

Bozuk asfaltında yürümesi hoşuna gider,

Sahil kenarı gibi gelir yüreğine...

Cafelerde geçen boş vakitleri doldurursun,

Özlersin hasretleri,asfaltsız patikaları,

Her sabah uyandığında şehri koklarsın...

Güneş bile ısıtmaz yüreğini bazı,

Merhametsiz yağmurlar yıkasada bedenini,

Kirli hissedersin kendini...

Gözyaşların boşa akar gider,

Bir hiçbirşey uğruna rahmet olurlar...

Dumanı var bir de Ankara''nın,

Zehir eden sana hayatı...

Tertemiz ormanlara gitsen de zehir eden sana,

Her soluyuşta geridekileri hatırlatan,

Ruhunu sımsıkı saran bir şehirdir Ankara... 

15-06-00', 'Aşksız ve kuraktır Ankara yalnızın, Sahipsiz bakışlar gezer gölgelerde, Anlamsız olur sevişmeler her vakit... Bir hesap sorar gibidir esinti...', ARRAY['Türk Edebiyatı','Şiir','Emre Engin']::text[], 8.5, '{"poet":"Emre Engin","poet_slug":"emre-engin","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/bir-sehirdir-ankara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin', 'ellerin-turgut-yuca-0totr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ellerin kokuyor her yer

Cennetin güllerini andırıyor

En bilinmedik köşesinde dünyanın;

Halimi anlatsam anlar mısın?

Ağladığım günleri hatırlar mısın?

Nasıl gülersin ben olmadan

Islak ellerin kokuyor, güller gibi

Melankolik bir yaz geçiyor aklımdan.', 'Ellerin kokuyor her yer Cennetin güllerini andırıyor En bilinmedik köşesinde dünyanın; Halimi anlatsam anlar mısın? Ağladığım günleri hatırl...', ARRAY['Türk Edebiyatı','Şiir','Turgut Yuca']::text[], 8.5, '{"poet":"Turgut Yuca","poet_slug":"turgut-yuca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ellerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serseri', 'serseri-necip-fazil-kisakurek-6uadx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeryüzünde yalnız benim serseri,

Yeryüzünde yalnız ben derbederim.

Herkesin dünyada varsa bir yeri,

Ben de bütün dünya benimdir derim.

Yıllarca gezdirdim hoyrat başımı,

Aradım bir ömür, arkadaşımı.

Ölsem dikecek yok mezar taşımı;

Halime ben bile hayret ederim.

Gönlüm ne dertlidir, ne de bahtiyar;

Ne kendisine yar, ne kimseye yar,

Bir rüya uğrunda ben diyar diyar,

Gölgemin peşinden yürür giderim...', 'Yeryüzünde yalnız benim serseri, Yeryüzünde yalnız ben derbederim. Herkesin dünyada varsa bir yeri, Ben de bütün dünya benimdir derim. Yılla...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/serseri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey Boş', 'hersey-bos-mine-yavas-2yrsp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biliyorum ki herşey boş 

Fakat şu yalan dünyaya niye geldik ki?

Herşeye boş vermek için mi?

Sevgi diye birşey varsa,

Niçin ben bunu göremiyorum?

Niçin bende herkes gibi sevemiyorum?

Ya insanlar beni anlamıyorlar

Yada ben onları,

Buralardan gitmek istiyorum

Herşeyi bırakıp gitmek

Tahtadan yatağımı,

Bahçeli bir odalı evimi,

Beni sevdiğini zanneden insanları,

Dışarıda leş gibi kokan havasıyla Istanbul''u,

Birbirini kullanan sahte insanları,

Hepsini bırakıp gitmek,gitmek...

Hiçkimsenin olmadığı sadece,

Gerçek insanların olduğu tertemiz bir dünyaya,

Yalanın, sahteliğin,isyanın, üç kağıtçılığın,

Olmadığı bir dünyaya gitmek, gitmek....', 'Biliyorum ki herşey boş  Fakat şu yalan dünyaya niye geldik ki? Herşeye boş vermek için mi? Sevgi diye birşey varsa, Niçin ben bunu göremiyo...', ARRAY['Türk Edebiyatı','Şiir','Mine Yavaş']::text[], 8.5, '{"poet":"Mine Yavaş","poet_slug":"mine-yavas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hersey-bos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mataramda Tuzlu Su', 'mataramda-tuzlu-su-i-smet-ozel-4fa12', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'West Indies,Kızıl Elma,İtaki,Maçin!

Uzun yola çıkmaya hüküm giydim.

Beyazların yöresinde nasibim kalmadı

yerlilerin topraklarına karşı şuç işledim

zorbaların arasında tehlikeli bir nifak

uyrukların arasında uygunsuz biriyim

vahşetim

beni baygın meyvaların lezzetinden kopardı

kendime dünyada bir

acı kök tadı seçtim

yakın yerde soluklanacak gölge bana yok

uzun yola çıkmaya hüküm giydim.

Uzak nedir?

Kendinin bile ücrasında yaşayan benim için

gidecek yer ne kadar uzak olabilir?

Başım açık, saçlarımı ikiye

ortadan ayırdım

kimin ülkesinden geçsem

şakaklarımda dövmeler beni ele verecek

cesur ve onurlu diyecekler

halbuki suskun ve kederliyim

korsanlardan kaptığım gürlek nara

işime yaramıyor

rençberlerin o rahat

ve oturmuş lehçesinden tiksinirim

boynumda

bana yargı yükleyenlerin

utançlarından yapılma mücevherler

sırtımda sağır kantarı gizli bilgilerin

mataramdaki suya tuz ekledim, azığım yok

uzun yola çıkmaya hüküm giydim.

Bir hayatı,ısmarlama bir hayatı bırakıyorum

görenler üstünde iyi duruyor derdi her bakışta

askerken kantinden satın aldığım cep aynası 

bazı geceler çıkarken

uçarı bir gülümseyişle takındığım muşta

gibi lükslerim de burda kalacak

siparişi yargıcılar tarafından verilmiş

bu hayattan ne koku, ne yankı, ne de boya

taşımamı yasaklayan belgeyi imzaladım

burada bitti artık işim, ocağım yok

uzun yola çıkmaya hüküm giydim.', 'West Indies,Kızıl Elma,İtaki,Maçin! Uzun yola çıkmaya hüküm giydim. Beyazların yöresinde nasibim kalmadı yerlilerin topraklarına karşı şuç i...', ARRAY['Türk Edebiyatı','Şiir','İsmet Özel']::text[], 8.5, '{"poet":"İsmet Özel","poet_slug":"i-smet-ozel","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/mataramda-tuzlu-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezarcı', 'mezarci-ceren-sever-0kydu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevenler sevdiğini unutmaz mezarcı

Gidenler geriye gelmez mezarcı

Bir değil bin metre kazsan da

Sevgililer hiç bir zaman ölmez mezarcı

Güller kırmızı menekşeler mor

Seni ne kadar sevdiğimi gel de kalbime sor', 'Sevenler sevdiğini unutmaz mezarcı Gidenler geriye gelmez mezarcı Bir değil bin metre kazsan da Sevgililer hiç bir zaman ölmez mezarcı Gülle...', ARRAY['Türk Edebiyatı','Şiir','Ceren Sever']::text[], 8.5, '{"poet":"Ceren Sever","poet_slug":"ceren-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/mezarci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sonbahar', 'sonbahar-ceren-sever-aba5s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Birgün beni arayacaksın

Arkadaşlarıma soracaksın

Sana tuhaf bakacaklar

O anda ezan sesini duyacaksın

O ezan sesi değil sela diyecekler

O ÖLDÜ!!!

Mezarıma getirecekler

Bir gül arayacaksın

Ama bulamayacaksın

Çünkü mevsim 

SONBAHAR', 'Birgün beni arayacaksın Arkadaşlarıma soracaksın Sana tuhaf bakacaklar O anda ezan sesini duyacaksın O ezan sesi değil sela diyecekler O ÖLD...', ARRAY['Türk Edebiyatı','Şiir','Ceren Sever']::text[], 8.5, '{"poet":"Ceren Sever","poet_slug":"ceren-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardeşim', 'kardesim-ceren-sever-49v56', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elma yanaklı

Kiraz dudaklı

Armut suratlı

Canım kardeşim', 'Elma yanaklı Kiraz dudaklı Armut suratlı Canım kardeşim...', ARRAY['Türk Edebiyatı','Şiir','Ceren Sever']::text[], 8.5, '{"poet":"Ceren Sever","poet_slug":"ceren-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kardesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlı Sevgili', 'tatli-sevgili-ceren-sever-skbtg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabah kalktığımda

Soğuktu hava

Soğuk havada 

Seni getirdim aklıma

Aklımda bir tek sen vardın

Kalbimi bir sen çaldın

Birtek sana inandım

Benim tatlı sevgilim', 'Sabah kalktığımda Soğuktu hava Soğuk havada  Seni getirdim aklıma Aklımda bir tek sen vardın Kalbimi bir sen çaldın Birtek sana inandım Beni...', ARRAY['Türk Edebiyatı','Şiir','Ceren Sever']::text[], 8.5, '{"poet":"Ceren Sever","poet_slug":"ceren-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tatli-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atatürk', 'ataturk-ceren-sever-zfq7e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Atatürk liderdi

O birinciydi

Bütün savaşlarda

Hep galip geldi

Atatürk hep iyiydi

İyi düşünceliydi

Planlı çalışırdı

Savaşları kazanırdı

Eski çağlarda olsak

Yine savaşlar olsa

Atatürk''de olmasa

Bu devlette olmazdı

Sadece Atatürk değil

Silah arkadaşları da vardı

Onları da unutmayalım

Hep saygı duyalım', 'Atatürk liderdi O birinciydi Bütün savaşlarda Hep galip geldi Atatürk hep iyiydi İyi düşünceliydi Planlı çalışırdı Savaşları kazanırdı Eski ...', ARRAY['Türk Edebiyatı','Şiir','Ceren Sever']::text[], 8.5, '{"poet":"Ceren Sever","poet_slug":"ceren-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ataturk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deprem', 'deprem-ceren-sever-wr7bu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Deprem deprem diyorlar

Bana neden söylemiyorlar

Sen çocuksun küçüksün 

Sen anlamazsın diyorlar

Ahmet Mete Işıkara

Akrabamız sayıldı

Bir artçı şokta

Telefonlara sarılındı

Görüşemedik telefonla

Telefonlar kilitlendi

yetkililer aramayın bu kadar dedi', 'Deprem deprem diyorlar Bana neden söylemiyorlar Sen çocuksun küçüksün  Sen anlamazsın diyorlar Ahmet Mete Işıkara Akrabamız sayıldı Bir artç...', ARRAY['Türk Edebiyatı','Şiir','Ceren Sever']::text[], 8.5, '{"poet":"Ceren Sever","poet_slug":"ceren-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/deprem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmenler', 'ogretmenler-ceren-sever-lseo3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bizi severler

Bilgi verirler

Öğrenmemiz için 

Emek verirler

Yaptıkları planlar

Hep bize yarar

Geleceğimiz için

Dersleri anlatırlar

Bilgi veren onlar

Sevgi veren onlar

Hayatı anlatırlar

Başarılı olalım diye', 'Bizi severler Bilgi verirler Öğrenmemiz için  Emek verirler Yaptıkları planlar Hep bize yarar Geleceğimiz için Dersleri anlatırlar Bilgi ver...', ARRAY['Türk Edebiyatı','Şiir','Ceren Sever']::text[], 8.5, '{"poet":"Ceren Sever","poet_slug":"ceren-sever","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ogretmenler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk Masalı', 'bir-ask-masali-dilek-i-nci-9e0sc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen tatlı bir kış güneşi gibi

Ansızın içimi titreten

Ilık bir yaz yağmuru kadar

Kısa sürüp bir anda bitiveren

Ve bir sonbahar yaprağının 

Yere süzülüşü gibi yalnızlığı

Hüznü anlatan bir masaldın

Mevsimler geçip gitsede böyle

Seni binbir sitemle anımsayarak

Gecelerin matemi acıtsa da içimi

Ağlamanın ardından duyulan 

Huzur ve rahatlık gibisin bana sen

Sakın sorma hüznümün sebebini

Anlatamam anlamanı bekleyemem

Öylesine bir savaş var ki içimde

Silah sesleri çığlıklar haykırışlar

Ve boğazıma dayanan bir yalnızlık

Kim kovabildi ki onu sen kovacaksın?

Hoş! Kovsanda gitmez ya

Bırakmaz peşimi lanet olası

Adı içimde saklı yalnızlık

Garp bir aşktı yaşadığım.Ruhumun onunla paylaşımları anlıktı ama hatada olsa güzeldi.

Yüreğinizdeki sevgileri acıda olsa sonuna dek yaşamanız dileğiyle, 

Anlayacağın hep yalnızdım

Tıpkı bugün seni sensiz yaşadığım gibi

Mutluluk heyecan çılgınlık vaad etsende bana

Aşkı vaad edemezsin ya

Hiçbirşey bilmesem de hakkında

Şunu biliyorum emin ol

Sonu olmayan bu aşkı 

Birgün sen de satıp terkedip 

Bir anda sileceksin

İşte bu yüzden bırakta

Ben seni bugüne dek olduğu gibi

Yine sensiz yaşayayım', 'Sen tatlı bir kış güneşi gibi Ansızın içimi titreten Ilık bir yaz yağmuru kadar Kısa sürüp bir anda bitiveren Ve bir sonbahar yaprağının  Ye...', ARRAY['Türk Edebiyatı','Şiir','Dilek İnci']::text[], 8.5, '{"poet":"Dilek İnci","poet_slug":"dilek-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bir-ask-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama Götür Beni', 'babama-gotur-beni-hulya-yilmaz-raash', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kötü kullarının yanına bırakma beni

Rabbim sen kucak aç sen yanına al beni

Yüzümü güldürmek istemeyenlerden

Sen kurtar allahım sen koru beni

Dünyada kahrolan yorgun bedenimi,

durmak dinmek bilmeyen gözüm selini,

burada bırak solgun tenimi,

Yüce kudretinle tutda elimi,

Babamın yanına sen götür beni..', 'Kötü kullarının yanına bırakma beni Rabbim sen kucak aç sen yanına al beni Yüzümü güldürmek istemeyenlerden Sen kurtar allahım sen koru beni...', ARRAY['Türk Edebiyatı','Şiir','Hülya Yılmaz']::text[], 8.5, '{"poet":"Hülya Yılmaz","poet_slug":"hulya-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/babama-gotur-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar Başlangıcında', 'sonbahar-baslangicinda-hulya-yilmaz-r9u2f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çekip gitti bir yaz daha,

Bitti deli aşkların yaşandığı yakan mevsim.

Şimdi sonbahar

Daha çok yağmur, daha deli rüzgarlar ve daha çok ayrılık var bu mevsimde.

Sarı yapraklar dökülmüş taş kaldırımarın üzerine

bir deli rüzgar eserde alır götürür onu çook uzaklara..

o gelmez belki geriye ama

yeni yapraklar yeşerir yeni baharlarda.

Bir umut gibi, bir aşk gibi, biri biter yerine başkası gelir.

Birbirinin aynıdır hep yeni umutlar, yeni yapraklar ve yeni aşklar da.

hep aynı mevsimde başlar filizlenmeye,

sonra yeşerir,sonra yaşar ve ölür işte sonbaharlarda.

Ne olur peki sonra? 

Olan ağaca olur, bıkar birgün yeşermekten,

çünkü bilir sonunu solup gidecektir hazanlarda...

Ve olan bana olur.

Bıkar birgün gönlüm sevmekten, yalancı sevgilerden.

Çünkü bilir sonunu.

gidecektir yaşlı gözlerle bırakıp beni ardında bir sonbaharda..

İşte yine çekip gitti bir yaz daha,

Bir Sonbahar Başlangıcında.........

E-mail: [email protected]

(Eylül 96)', 'Çekip gitti bir yaz daha, Bitti deli aşkların yaşandığı yakan mevsim. Şimdi sonbahar Daha çok yağmur, daha deli rüzgarlar ve daha çok ayrılı...', ARRAY['Türk Edebiyatı','Şiir','Hülya Yılmaz']::text[], 8.5, '{"poet":"Hülya Yılmaz","poet_slug":"hulya-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sonbahar-baslangicinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Umuttur Yaşamak', 'bir-umuttur-yasamak-hulya-yilmaz-j17w3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmek sevmek sevmek,

Ve sevmek sınırsızca..

Mühürlemek kalbine sevgisini ki alamasın 

hiç kimse onu oradan.

silmek acılar, bomboşluğu doldurmak herşeyle,

ve yok etmek sevgisizliği,

Kaldırabilmek benliğinden yanlızlığı,

gecelere daha farklı yaklaşmak, 

karanlığını değil gizemini yaşamak.

Acı duymamak artık akan gözyaşlarından,

bir sigarda bile kendine gelebilmek içerken yudum yudum.

Özlem duymamak ilk günlere,daha

güzelini yaşamak sevdanın.

Ve ağlamamak hçkırarak yağarken yağmur,

benide benide al götür eyyy deli rüzgar diye haykırmamak..

Mutluyum diyebilmek ve tutabilmek artık o küçük umut serçesini...', 'Sevmek sevmek sevmek, Ve sevmek sınırsızca.. Mühürlemek kalbine sevgisini ki alamasın  hiç kimse onu oradan. silmek acılar, bomboşluğu doldu...', ARRAY['Türk Edebiyatı','Şiir','Hülya Yılmaz']::text[], 8.5, '{"poet":"Hülya Yılmaz","poet_slug":"hulya-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-umuttur-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Yağmuru', 'guz-yagmuru-celal-kabadayi-8ecnn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yaprakların hüzün saçtığı zaman

kaçınılmazlığın dönemidir aşktan

ne yana kaçsan yağmurlanırsın

yağmurlar ki birer notadır her damlası

yalnızlığın ince tellerine damlayan 

hep ama hep yağmur yağar anılarına 

adımlarını bekler kentin bütün sokakları

ama beklemez köşe başlarında seni 

aşkından sırılsıklam olduğun kız

gerçeği yağmurdan bir tül sanırsın

oysa perdelerin ardına gizlenmiştir düşlerin

çağrışım okları saplanır uslanmaz yüreğine

acının tutsağıdır vurgun yemiş bakışların

ne yana baksan sevilenirsin

seviler ki

çoktan gitmiştir kendileri

yalnızca hüzün kalmıştır geriye

öyle bir hüzün ki 

ne sokaklar ne sen

taşıyamazsın

yağmur mu yağar sokaklar mı ağlar

anlayamazsın', 'yaprakların hüzün saçtığı zaman kaçınılmazlığın dönemidir aşktan ne yana kaçsan yağmurlanırsın yağmurlar ki birer notadır her damlası yalnız...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/guz-yagmuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-celal-kabadayi-b5psz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gözlerin,yitik düşlerin geri dönüşü

gözlerin,yüreğimdeki düğümlerin çözülüşü

gözlerin,gülmeyi unutmuş yüzümün gülüşü

gözlerin,mutluluğun gözleri

gözlerin,derin bir denizin dibindeki yakut

gözlerin,ölmüş duygular için yeni umut

gözlerin,susmuş şarkıların yükselen sesi

gözlerin,sevginin gözleri

gözlerin,unutulmaz duyguların yaşandığı yer

gözlerin,arkamda bıraktığım en yüce değer

gözlerin,yokluğuyla beni perişan eder

gözlerin,ayrılığın gözleri

gözlerin,özlemi kor kor içimi yakar

gözlerin,gözyaşı olur gözlerimden akar

gözlerin,kimbilir şimdi kimlere bakar

gözlerin, ihanetin gözleri', 'gözlerin,yitik düşlerin geri dönüşü gözlerin,yüreğimdeki düğümlerin çözülüşü gözlerin,gülmeyi unutmuş yüzümün gülüşü gözlerin,mutluluğun göz...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimde Olsa', 'elimde-olsa-simge-atakan-q9a6i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Elimde olsa seni yeniden severdim

Şu ufacık kalbime hapsederdim

Elimde olsa alırdım karşıma

Herşeyi sil baştan derdim

Elimde olsa bile yüreğim kabul eder mi?

Elimde olsa öfkemi unutup

Suçunu affeder sızımı dindirirdim

Elimde olsa varmısın birdaha derdim

Acımı kalbime gömerdim

Elimde olsa bile yüreğim kabul eder mi?', 'Elimde olsa seni yeniden severdim Şu ufacık kalbime hapsederdim Elimde olsa alırdım karşıma Herşeyi sil baştan derdim Elimde olsa bile yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Simge Atakan']::text[], 8.5, '{"poet":"Simge Atakan","poet_slug":"simge-atakan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/elimde-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Yalvarış', 'son-yalvaris-simge-atakan-4k4do', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son yalvarış fayda etmez bunu bil...

Bu davranış sence asillik midir?

Benden evet gelmez aklından sil...

Sözlerine dikkat et geridir!', 'Son yalvarış fayda etmez bunu bil... Bu davranış sence asillik midir? Benden evet gelmez aklından sil... Sözlerine dikkat et geridir!...', ARRAY['Türk Edebiyatı','Şiir','Simge Atakan']::text[], 8.5, '{"poet":"Simge Atakan","poet_slug":"simge-atakan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/son-yalvaris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Bir Sevdaysa...', 'nasil-bir-sevdaysa-attila-i-lhan-l2uun', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ay çok mu gecikti neredeyse çıkar

sen yanlızlığıma varır varmaz

az sonra yağmuru durduracaklar

rüzgarı değiştirdim

    ustura ağzı poyraz

yok canım yıldızları unutmadık

mutlaka yerlerinde bulunacaklar

kenarı yaldızlı mavi bir karanlık

sütlü çıplaklığını örtecek kadar

senin için olduğu asla bilinmeyecek

yapraklarını birden dökecek dutlar

şafak sökerken sekiz on kadar şimşek

balkonda işlemeli müstesna bulutlar

ayak bastığın an şehir de değişebilir

yoksa Moskova mı

    belki berlin belki dakar

belki 30''lardan mehtap yorgunu izmir

körfez''de şerefine donatılmış vapurlar

nerede ne zaman kaç kere yasadık

nasıl bir sevdaysa eskitememiş yıllar

bitirdiğimiz herşeye yeniden başladık

dudaklarımızda birbirimizden mısralar', 'ay çok mu gecikti neredeyse çıkar sen yanlızlığıma varır varmaz az sonra yağmuru durduracaklar rüzgarı değiştirdim     ustura ağzı poyraz yo...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/nasil-bir-sevdaysa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmek Yasak', 'olmek-yasak-attila-i-lhan-6xptx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'daha önce bıçaktan hiç su içmedim

hiç kısılmadı kerpetene bıyıklarım

gururlu bir gemiyim oldum bittim

sabah olur yelkenlerimi saklarım

özgürlük dediğim yerde demirledim

üstüme varma bulutları tutamam

böyle paldır küldür gideceklerdir

gelmezsen farketmez kimseyi aramam

asıl sevdiklerim en içimdekilerdir

onlarla yaşarım eğer yaşarsam

olurmu gecemi yesile çalmak

yıldız çivilemek parmakuçlarıma

ölüm kadar çabuksa eğer yaşamak

hiç doğmamayı isterdim ama

bir kere doğmuşum ölmek yasak', 'daha önce bıçaktan hiç su içmedim hiç kısılmadı kerpetene bıyıklarım gururlu bir gemiyim oldum bittim sabah olur yelkenlerimi saklarım özgür...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olmek-yasak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kerem Gibi...', 'kerem-gibi-nazim-hikmet-ran-jwg6o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hava kurşun gibi ağır! ! 

Bağır

     bağır

             bağır

                     bağırıyorum.

Koşun

      kurşun

             erit-

                 -meğe

                         çağırıyorum...

O diyor ki bana:

— Sen kendi sesinle kül olursun ey! 

                                             Kerem

                                                  gibi

                                                       yana

                
..........
..........', 'Hava kurşun gibi ağır! !  Bağır      bağır              bağır                      bağırıyorum. Koşun       kurşun              erit-       ...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kerem-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıl Gözü', 'akil-gozu-ozdemir-asaf-ajbl2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni bulmaktan önce aramak isterim.

Seni sevmekten önce anlamak isterim.

Seni bir yaşam boyu bitirmek değil de, 

Sana hep, hep yeniden başlamak isterim.', 'Seni bulmaktan önce aramak isterim. Seni sevmekten önce anlamak isterim. Seni bir yaşam boyu bitirmek değil de,  Sana hep, hep yeniden başla...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/akil-gozu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haziran', 'haziran-alp-arslan-2-8ntut', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'düş gezginiyim gecenin kovuğunda uyurum haziranın düşünü görürüm 

tam da kiraz vaktidir yüreğimin dalları toprağa değer toprak çağırır

dalbastı kirazların kan tadında umarsız bir yol ayrımıdır haziran

ben yürürüm bu yolda hüzünlü şarkılar yürür belki haziran yürür 

sağanak yağmurlar altında göç arifesidir haziran yağmurun türküsüdür 

akşam olur karanlık hüküm sürer gecenin gergefinde bir şiir dokunur

toprağın sesi çınlar kulaklarımda dalgalar yüreğime değer deniz çağırır

bütün tekneler hazirandan geçer şarabın kırmızısıdır damarlarıma yürür

kırlangıç baharıdır düşlerin kıyısında umudun saçağında ceviz ağacı 

yalnızlığın kuşatmasında yalın ölümler ayıdır haziran hasretin öyküsüdür

tilki uykusu bu en küçük kıpırtıda depremler olur yer yerinden oynar

dönüşü olmayan bir haziran yangınıdır artık gemiler yanar köprüler yanar

hüzün bir tel örgüdür yüreğimi sarar bağdaş kurup oturur can evime korkular

dursam duramam koşsam koşamam dizelere sığınırım haziran beni saklar 

yangınlar ortasında bir nefes fesleğendir haziran korkuların örtüsüdür

haziran olsaydım böyle olurdum tarih olurdum güncesini tutardım şiirlerin

ölümlerin yasını tutardım haziran gezginiyim uçurumların kıyısında dururum

atsam kendimi atamam zincirler prangalar bir de deniz kokusu bir de haziran

mevsimler biter zaman biter karanlıkta gökyüzüne bakarım yıldızlar çağırır

yolculuk öncesinde veda sözcüğüdür haziran yolculuğun yakılacak köprüsüdür

her nasılsa haziran sabahlarına uyanırım hep yastığım tütün kokar düş kokar

acının nöbetini tutarım ölümün arka bahçesinde yüzyıllardır ellerim kanar

sokaklarım ortaçağ sokağı duvarlar örülür dört bir yanımda yollarım kesilir

saatlerin durduğu bir anda sigaramın dumanı savrulur yine yollara düşerim

intiharın kül tortusunda küçük bir tereddüttür haziran ömrümün törpüsüdür

haziranın nöbetini tutarım sayılıdır günlerim haziran bitti bitecek

pişmanlık değil bu öfkem yaşamadığıma yangın çıkacak vakit geldi gelecek

mağara duvarında bir resim şimdi anılar neredeyse güneş batar gece çağırır

incecik bir duadır hastalığın son safhasında ıssız bir cenaze sessiz bir ağıt 

günbatımının çağrısında şakaklarda namludur haziran mezar taşlarının süsüdür', 'düş gezginiyim gecenin kovuğunda uyurum haziranın düşünü görürüm  tam da kiraz vaktidir yüreğimin dalları toprağa değer toprak çağırır dalba...', ARRAY['Türk Edebiyatı','Şiir','Alp Arslan 2']::text[], 8.5, '{"poet":"Alp Arslan 2","poet_slug":"alp-arslan-2","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/haziran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ihlamur Bardağını...', 'ihlamur-bardagini-edip-cansever-h6bg8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ihlamur bardağını yana itince

Başını kaldırınca ıslak saç kokusundan 

Olgun bir kayısının içeriğidir sende

Senin gözlerin.

Dün akşamki yere serili gölgen 

Bu akşamki gölgenle üst üste

Cebinde bir avuç ayçiçeği

Geri dönmüş elinden nasıl döndüyse

Mutluluğun sana verdiği tatili yaşıyot

Bir açılıp kapanıyor kirpiklerin

Bilmem alınır mısın söylersem

Unutulmuş bir çirkinlikten başlıyor güzelliğin.', 'Ihlamur bardağını yana itince Başını kaldırınca ıslak saç kokusundan  Olgun bir kayısının içeriğidir sende Senin gözlerin. Dün akşamki yere ...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ihlamur-bardagini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisin', 'bilirmisin-beyazit-cenan-8wet1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilirmisin farkedilmemenin ne oldığunu 

Bilirmisin hep düşünüp hiç düşünülmemeyi

Anlarmısın halimden ne hissettiğimi

Farkeder misin beni ve seni sevdiğimi

Koşar mısın delice nereye bilmeden 

Ağlar mısın geceleri sessizce içinden

Susar mısın konuşmak gelsede içinden

Ve yaşar mısın yaşamak olmasada yalnızken', 'Bilirmisin farkedilmemenin ne oldığunu  Bilirmisin hep düşünüp hiç düşünülmemeyi Anlarmısın halimden ne hissettiğimi Farkeder misin beni ve ...', ARRAY['Türk Edebiyatı','Şiir','Beyazıt Cenan']::text[], 8.5, '{"poet":"Beyazıt Cenan","poet_slug":"beyazit-cenan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bilirmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emine', 'emine-beyazit-cenan-qu8z6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eski bir şarkıyı söylüyorum 

Meğer hep seni söylüyormuşum

İçinde bir seven var şarkımın

Ne olduğunu bilmeyen

En güzel sevilen var', 'Eski bir şarkıyı söylüyorum  Meğer hep seni söylüyormuşum İçinde bir seven var şarkımın Ne olduğunu bilmeyen En güzel sevilen var...', ARRAY['Türk Edebiyatı','Şiir','Beyazıt Cenan']::text[], 8.5, '{"poet":"Beyazıt Cenan","poet_slug":"beyazit-cenan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/emine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-aycin-dogan-nxlm9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum yine 

Elimde sigaram yanımda hasret

Neler geçiyor  içimden neler

İçimde kor gibi yanan özlem

Çekiyor beni yalnızlığın kollarına 

O yalnızlık  rüya birtanem

Korkutuyor ürkütüyor

Sensizlik yakıyor tüm benliğimi

Eritiyor bir mum misali yavaş yavaş

Varsın eritsin yok etsin beni

İnan inan bana birtanem

Yeneceğiz sevgimizle bütün herşeyi

Olmazdeme sakın dayan bunlara

Razı olma bizi ayırmalarına

Unutma söz vermiştin bizi ayırmalarına

Mutluluk inan çok yakında', 'Seni düşünüyorum yine  Elimde sigaram yanımda hasret Neler geçiyor  içimden neler İçimde kor gibi yanan özlem Çekiyor beni yalnızlığın kolla...', ARRAY['Türk Edebiyatı','Şiir','Ayçin Doğan']::text[], 8.5, '{"poet":"Ayçin Doğan","poet_slug":"aycin-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevmek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aktif', 'aktif-lutfi-cetintepe-7i2m7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seviyorum birini

Bir de aktifim ya

Hipotezler kuruyorum ya aşk üstüne

Sevgi üstüne

Önce tip mesele mi diyorum

Gelenekler görenekler mi

Uzak mesafeler mi bizi ayıracak olan

Yoksa başka biri mi

Bilemiyorum

Bildiğim tek şey

Seviyorum, çok seviyorum

Bu sevgi kronikleşmiş

İlacıysa ömür boyu sevgi', 'Seviyorum birini Bir de aktifim ya Hipotezler kuruyorum ya aşk üstüne Sevgi üstüne Önce tip mesele mi diyorum Gelenekler görenekler mi Uzak ...', ARRAY['Türk Edebiyatı','Şiir','Lütfi Çetintepe']::text[], 8.5, '{"poet":"Lütfi Çetintepe","poet_slug":"lutfi-cetintepe","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aktif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Asıl Suskunluklarımı Dinle', 'sen-asil-suskunluklarimi-dinle-vahap-akbas-s1xvx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir ırgat gibi çalıştım çok sesler biriktirdim

dağıttım sonra hepsini bilmiyorum ne kadarı sende

sende olmayan avare sözlerim 

hangi şarkıda ağlıyor şimdi bilmiyorum

sen asıl suskunluklarımı dinle

söndürmeye kıyamadığım yangınlar ordadır

depremlerin şiddetini düşürür sözcükler

sözcükler deli suları yatağına çeker

uyutur usulca budur en büyük maharetleri

sen asıl uykudaki ağzımı dinle

gör nasıl açılır sır bahçelerine pencereler

sen asıl suskunluklarımı dinle

ordadır yazılmamış tarihi âşıklığımın

çılgınlıklarımın boy fotoğrafları ordadır

sen asıl suskunluklarımı dinle

ve anla anla ki ne maceralardasın benimle', 'bir ırgat gibi çalıştım çok sesler biriktirdim dağıttım sonra hepsini bilmiyorum ne kadarı sende sende olmayan avare sözlerim  hangi şarkıda...', ARRAY['Türk Edebiyatı','Şiir','Vahap Akbaş']::text[], 8.5, '{"poet":"Vahap Akbaş","poet_slug":"vahap-akbas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-asil-suskunluklarimi-dinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebebi Sensin', 'sebebi-sensin-esra-kiranli-ofbqe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin kör bir vaktinde

cikarsam eger sokaklara,

atarsam yanliz yüregimi ciplak karanliga,

Anlaki sebebi Sensin!

Gökyüzüyle paylastigim hüzün

aktirir gözyasini bu gecede,

yagmurun sel oldugu an kederimle bogulurum icinde.

Tek dostum ölümse bu gece,

Anlaki sebebi Sensin!

Günesin kari erittigi gibi,

kör gecelerde kayip olursam eger,

isyanim senden ibaret kaderim eyse eger,

Anlaki sebebi Sensin!

Bir volkan dag misali patlarsam,

boynu bükük ucurum kiyisinda

son adimim yanlizliga olursa,

elveda dersem hayata,

Anlaki sebebi Sensin!

Kursun yarasi gibi sizlarsa kahrolan sevgim,

acisi dinmeyi degil,ölümü bilirse cagre,

param parca olup dalarsam eger ebedi uykuya,

Anlaki sebebi sensin!', 'Gecenin kör bir vaktinde cikarsam eger sokaklara, atarsam yanliz yüregimi ciplak karanliga, Anlaki sebebi Sensin! Gökyüzüyle paylastigim hüz...', ARRAY['Türk Edebiyatı','Şiir','Esra Kıranlı']::text[], 8.5, '{"poet":"Esra Kıranlı","poet_slug":"esra-kiranli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sebebi-sensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Gözlü Dev', 'mavi-gozlu-dev-nazim-hikmet-ran-569nc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O mavi gözlü bir devdi.

Minnacık bir kadın sevdi.

Kadının hayali minnacık bir evdi, 

                             bahçesinde ebruliii

                             hanımeli

                             açan bir ev.

Bir dev gibi seviyordu dev.

Ve elleri öyle büyük işler için

                             hazı
..........
..........', 'O mavi gözlü bir devdi. Minnacık bir kadın sevdi. Kadının hayali minnacık bir evdi,                               bahçesinde ebruliii       ...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mavi-gozlu-dev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oy Dağlar', 'oy-daglar-nihat-behram-m3ayj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yazlar kışlar uçan kuşlar tanığımdır

Ayrılıklar yolum oldu

Can yoldaşlar dil sırdaşlar tanığımdır

Ölümlerden gülüm soldu

Anam bacım arkadaşlar tanığımdır

Zulüm gelip beni buldu

Oy dağlar yalçın dağlar

Dumanı hırçın dağlar

Gün olur devran döner 

Ağlayan bayram eyler

Oy dağlar haber verin

Sılamı özledim yine

Kuş olun kanat gerin

Yolunu gözledim

Yolunu gözledim yine oy dağlar oy dağlar

Kın olup bıçak verin

Anamı özledim yine

Kuş olup kanat gerin 

Yolumu gözledim yine', 'Yazlar kışlar uçan kuşlar tanığımdır Ayrılıklar yolum oldu Can yoldaşlar dil sırdaşlar tanığımdır Ölümlerden gülüm soldu Anam bacım arkadaşl...', ARRAY['Türk Edebiyatı','Şiir','Nihat Behram']::text[], 8.5, '{"poet":"Nihat Behram","poet_slug":"nihat-behram","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/oy-daglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Ki', 'umut-ki-nihat-behram-hqydq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Umut ki yüreğimdir

Halk olmuş yüreğimdir

Adını Onur koyduğum kavga

Büyü de umudu doğur

Kimi gün düşüm olur

Sese döner beni söyler

Kimi gün rüzgarlanır

Kuşa döner göğü söyler

Bileğim kelepçeli

Kolum zincirli olsa

Dudağım filizlenir

Kırılmış dalı söyler', 'Umut ki yüreğimdir Halk olmuş yüreğimdir Adını Onur koyduğum kavga Büyü de umudu doğur Kimi gün düşüm olur Sese döner beni söyler Kimi gün r...', ARRAY['Türk Edebiyatı','Şiir','Nihat Behram']::text[], 8.5, '{"poet":"Nihat Behram","poet_slug":"nihat-behram","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umut-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metris''in Önü', 'metris-in-onu-metris-ceza-evi-tutsaklari-h41pm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu Metris''in önü bir uzun alan

Bir tek seni sevdim gerisi yalan

Senin hasretindir hücreme dolan

Bir tek seni sevdim gerisi yalan

Hücremdeyim hasretinle yanarım

Senin için hergün ağlarım

Kanım hep içime akar kanarım

Bizi anlamadın ona yanarım', 'Şu Metris''in önü bir uzun alan Bir tek seni sevdim gerisi yalan Senin hasretindir hücreme dolan Bir tek seni sevdim gerisi yalan Hücremdeyim...', ARRAY['Türk Edebiyatı','Şiir','Metris Ceza Evi Tutsakları']::text[], 8.5, '{"poet":"Metris Ceza Evi Tutsakları","poet_slug":"metris-ceza-evi-tutsaklari","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/metris-in-onu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlara Çıkarım', 'daglara-cikarim-sair-reber-jd237', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dağlara çıkarım idarem için

Yollara düşerim idarem için

Bir tabip gelirse yaramı açın

Yaram çaresizdir kefenim biçin

Nasıl dayanayım ben bu yaraya

Dağların başını duman bürümüş

Felek vurmuş kolum kanadım kırmış

Gençlikte ölümü bana mı vermiş

Nasıl dayanayım ben bu acıya

Möftemi yıkıyor Turabi kendi

Suyumu döküyor dede efendi

Bozulmuş bağım erkanım bendim

Nasıl dayanayım ben bu acıya

Kıyma felek kıyma bir dal çınarım

Evde yalnızdır anam biçare

Yıkılmış hanesi dönmüş virane

Oy ben ağlamayım kimler ağlasın

Hey hey hey hey hal yaman dert kıran

Hoy hoy hoy hoy hal yaman dert kıran', 'Dağlara çıkarım idarem için Yollara düşerim idarem için Bir tabip gelirse yaramı açın Yaram çaresizdir kefenim biçin Nasıl dayanayım ben bu ...', ARRAY['Türk Edebiyatı','Şiir','Şair Reber']::text[], 8.5, '{"poet":"Şair Reber","poet_slug":"sair-reber","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/daglara-cikarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ez Nizanım Dijmin Ki Ye', 'ez-nizanim-dijmin-ki-ye-sair-reber-3unz2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ez nizanım dijmin ki ye

Xwinmi ji ü dostani çi ye

Reya rasti winde kiri me 

Reber were ez nizamın

Ez nizamıke gundi me

Civanek nexwendi me

Lı çol ü çepera mayi me

Reber were ez nizamın

Ya gundi ya bajari me

Faşi aqil je biri me

Nezaniye bindest kiri me

Reber were ez nizamın

Hin kirin be hosta nabe

Zane bün be xwendin nabe

Niştiman be reber nabe 

Reber were ez nizamın

Reber dıbe pir bawer be 

Li bo milleté şerwan be

Reber dıbe pir bawer be

Li bo şebo şera şerwan be', 'Ez nizanım dijmin ki ye Xwinmi ji ü dostani çi ye Reya rasti winde kiri me  Reber were ez nizamın Ez nizamıke gundi me Civanek nexwendi me L...', ARRAY['Türk Edebiyatı','Şiir','Şair Reber']::text[], 8.5, '{"poet":"Şair Reber","poet_slug":"sair-reber","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ez-nizanim-dijmin-ki-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şafak Türküsü', 'safak-turkusu-nevzat-celik-wnftv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1 

beni burada arama anne 

kapıda adımı sorma 

saçlarına yıldız düşmüş 

koparma anne 

ağlama

kaç zamandır yüzüm tıraşlı 

gözlerim şafak bekledim 

uzarken ellerim 

kulağım kirişte 

ölümü özledim anne 

yaşamak isterken delice 

2 

bugün görüş günü 

günlerden salı 

ıslak 

sarı bir yağmur 

ülkemin neresine bakarsa ay 

orada yitik bir anne ağlıyor 

sen aralıyorsun yağmuru 

acıdan sırılsıklam alnına siper edip elini 

sonra bir umut koşuyorsun 

yüreğin avucunda 

ısırırken 

çırpıntı gözlerini 

(ah verebilseydim keşke 

yüreği avcunda koşan 

her bir anneye 

tepeden tırnağa oğula 

ve kıza kesmiş 

bir ülkeyi armağan 

koşma anne 

birdenbire batacak olan 

düş denizinde yarattığın umut sandalıdır 

oysa benim için gece 

ışık hızıyla koşan 

kısa ve soğuk bir zamandır 

bu yüzden boğuk seslerle geldiler bir şafak 

uykusuz 

yorgun 

ve korkak 

3 

sanırım baytardı 

yüreğimin depreminde righter ölçeği çatlarken 

ölebilir raporu veren beyaz önlüklü doktor 

boş ver hypocrite amca 

üzülme ne olur 

sen de anne 

sen de üzülme 

hücremin dört bir köşesinde el ayak izlerimi 

ciğerlerimde yırtılan bir çığlıkla hazır beklediğim 

ve korkunç bir sabırla birbirine eklediğim 

korkak kahraman gecelerimi 

düşlerimle sınırsız 

diretmişliğimle genç 

şaşkınlığımla çocuk devrederken sıradakine 

usulca açılıverdi 

yanağımda tomurcuk 

pir Sultanı düşün anne 

şeyh Bedrettin''i 

börklüce''yi 

torlak Kemal''i düşün anne 

hala kanaması nedendir faşizmin göğsünde 

utangaçlığı bile vuramadan yanaklarına yasının 

on sekizinde ölümüne pervasız yürüyen 

ince bilekli çıplak ayaklı Tanya''nın 

deniz''i düşün anne 

her mayıs şafağında uzun 

uzun döverken darağaçlarını 

ve o şafaktan doğma 

on bir yaşını çiğneyip yürüyen çocukları 

insanları düşün anne 

düşün ki yüreğin sallansın 

düşün ki o an 

güneşli güzel günlere inanan 

mutlu bir yusufçuk havalansın 

4 

sıcak omuzlar değerken omzuma 

buz üstünde yürüdüm yıllar boyu 

bayraklar ve türkülerle 

kopunca memelerinden o mükemmel yaşama 

kurşunlar sıktılar alnıma 

açık alanlarda ağır 

kartalların konup kalktığı 

yalçın kayalardan biriydim 

ölüp dirildim yeniden 

güneşli güneşsiz akşamlarda 

mutlu yarınlar adına 

özgürlük adına ekmek adına 

üstüne vardım kuyruğu kanlı itlerin 

dirilip dönmesin diye Hiroşimalar 

tahtadan atların boynuna çıplak 

ölümlerle yatmasın diye çocuklar 

aç gözlerle bakmasın diye çocuklar 

kardeşlik adına 

havadaki kuş denizdeki balık adına 

yürüdüm yıllar boyu 

dönüp bakmadım arkama 

ıraktı gözlerim çok ırak 

izim kalır mı bilmem yürüdüğüm yolda 

kalsa da silinir gider 

yalnızca bir ağıt gibi çakılır 

ardımca gelenlere gözlerimi yaktığım yer 

5 

tören adımlarıyla ölmek 

ne garip şey anne 

kanlı karanlık bir oyunda baş oyuncuyum 

bütün gözler üstümde 

sürüyor gecenin karnında şafağa bakan oyun 

masa üstünde üşüyen bir sigara 

yanında küçücük bir cam bardak 

içinde rengi bu gecenin 

cılız titrek bir kibrit 

kağıt kalem 

sandalye 

geride flu 

yağlı 

büküm büküm bir ip 

ve çingene kuralına uygun 

değişmez dekoru mudur 

idam mahkumunun 

6 

kırılacak cammışım gibi davranıyorlar 

yüzlerinde zoraki çatılmış bir hüzün 

oysa birazdan boynumu kıracaklar 

pul pul dökülecek yaz Sivas’ı Eylül''ün 

ben ölümü asıl az ötede titreyen 

çingenenin kara kıllı ellerinde gördüm 

anladım ki küllenen sigaradır 

soğuyan bir bardak çaydır benim ömrüm 

yani benim güzel annem 

alaca şafağında ülkemin 

yıldız uçurmak varken 

oturup yıldızlar içinde 

kendi buruk kanımı içtim 

7 

ne garip duygu şu ölmek 

öptüğüm kızlar geliyor aklıma 

bir açıklaması vardır elbet 

giderken darağacına 

8 

geride 

masa üstünde boynu bükük kaldı kağıt kalem 

bağışla beni güzel annem 

oğul tadında bir mektup yazamadım diye kızma bana 

elleri değsin istemedim 

gözleri değsin istemedim 

ağlayıp koklayacaktın 

belki bir ömür taşıyacaktın koynunda 

usul adımlarla yürüdüm ömrümü 

karşımda kurum kurumlaşan darağacı 

(tarlakuşu korkmaz ki korkuluktan 

ökse de olsa dört bir yanı) 

birdenbire acıdı boynum 

gelecekler var birbiri ardınca genç 

yakışıklı 

ne olur işçi kadınım 

az yumuşak dik 

şu kefenin yakasını 

9 

yaşamak ağrısı asıldı boynuma 

oysa türkü tadında yaşamak isterdim 

çiçekleri kokmak ırmakları akmak 

yaz boyu çobanaldatanlara aldanmak 

su başlarında aylak sektirmek kavalımı 

sonra bir çocuğun afacan bacaklarında 

canavarca kayalıklarına tırmanmak isterdim 

o güzel günleri görenler arasında 

bir soluk ben de yaşamak isterdim 

bir de Lure müzesinde seyretmek gizliden 

öperken siya-u Jakond''u tebessümünden 

işte o an saçlarından yakalamak dolunayı 

bir de yirmi beş kilometreden görebilmek 

Nazımın gözleriyle pırıl pırıl Moskova''yı 

ölmek ne garip şey anne 

bayram kartlarının tutsaklığından aşırıp bayramı 

sedef kakmalı bir kutu içinde 

vermek isterdim çocukların ellerine 

sonra 

sonra benim güzel annem 

damdan düşer gibi 

vurulmak isterdim bir kıza 

10 

künyemi okudular 

suçumuz malum 

gecenin kıyısında durmuşum 

kefenin cebi yok 

koynuma yıldız doldurmuşum 

koşun çocuklar çocuklar koşun 

sabah üstüme 

üstüme geliyor 

yanlış mı duydum yoksa 

erkenci bir horoz mu ötüyor 

keskin bir acı bilenmiş 

gitgide yaklaşıyor sonum 

iri sözlerim yoktu söyleyecek 

usulca baktım yüzlerine 

bin yıllık iskeletleri çatırdayarak 

göçtü ayaklarının dibine 

korkutamadılar beni anne 

avlunun ortasında çatık bir kaş gibi duran 

darağacı 

bir zaman rüzgarda 

saçını tarayan telli kavak değil mi 

boynumdaki kemendi bir öğle sonu bükerken o kız 

sarı sıcak sevdasını düşünmedi mi 

söyle anne 

o çingene 

bir çiçek bahçesi kadar sıcak sokağımızdan 

bağıra çağıra geçen bohçacı kadını 

sevmedi mi çılgınca 

11 

kurulmuş tuzaklar yok artık yolumda 

işkenceler zindanlar hücreler 

savunmak yok mutlu tok bir yaşamı 

açlık grevlerinde beynimi bir sıçan gibi kemiren 

mideme karşı 

kısacası 

bir çiçeği düşünürken ürpermek yok 

gülmek umut etmek özlemek 

ya da mektup beklemek 

gözleri yatırıp ıraklara 

ölmek ne garip şey anne 

artık duvarları kanatırcasına tırnağımla 

şaşkın umutlu şiirler yazamayacağım 

mutlak bir inançla gözlerimi tavana çakamayacağım 

baba olamayacağım örneğin 

toprak olmak ne garip şey anne 

ceplerimde el yerine balyoz taşırken 

korkunç bir merakla beklerken kurtuluş haberlerini 

ve yüreğimin ırmakları taştı 

taşacakken 

ölmek ne garip şey anne 

uçurumlar ki sende büyür 

dağdır ki sende göçer 

ben yaprak derim çiçek derim 

cam diplerinde açmış kanatlarını kozalak derim 

gül yanaklı çocuğa benzer 

yine de 

oğlunu yitirmek kim bilir 

ne garip şey anne 

12 

beni burada arama anne 

kapıda adımı sorma 

saçlarına yıldız düşmüş 

koparma anne 

ağlama 

kırıldıysa düş evinin kapısı 

bütün kırık kapıların çağrılısıyım 

kızların yanaklarında çukurlaşan 

biten başlayan aşkların ortasındayım 

her kavgada ölen benim 

bayrak tutan çarpışan 

her kadın toprağı tırnaklayarak doğurur beni 

özlem benim kavga benim aşk benim 

bekle beni anne 

bir sabah çıkagelirim 

bir sabah anne bir sabah 

acını süpürmek için açtığında kapını 

umarım kurtuluş haberleriyle dönmüş olur 

cam ve kekik kokuları içinde acı yüzlü çocuklar 

o zaman nasıl indirilmişlerse şen şakrak 

öylece kalkar uykudan şalterler 

dişleyip tükürmeden sigaralarını 

türkü tadında giyinirken işçiler 

bir sabah anne bir sabah 

acını süpürmek için açtığında kapını 

adı başka sesi başka nice yaşıtım 

koynunda çiçekler 

çiçekler içinde bir ülke getirirler 

başlarını koymak için yoğun dizine 

sen hazır tut dizini anne 

o mükemmel güne 

Ağustos-Ekim 1983 

Şafak Türküsü,1984)', '1  beni burada arama anne  kapıda adımı sorma  saçlarına yıldız düşmüş  koparma anne  ağlama kaç zamandır yüzüm tıraşlı  gözlerim şafak bekl...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Çelik']::text[], 8.5, '{"poet":"Nevzat Çelik","poet_slug":"nevzat-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":275,"source_url":"https://www.antoloji.com/safak-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyanür Yüzükte Kalsin', 'siyanur-yuzukte-kalsin-guvenc-dagustun-8jemw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Siyanür yüzükte kalsin

yüzük benden uzakta

söyle Ella...

söyle Ella...

söyle Ella...', 'Siyanür yüzükte kalsin yüzük benden uzakta söyle Ella... söyle Ella... söyle Ella......', ARRAY['Türk Edebiyatı','Şiir','Güvenc Dagüstün']::text[], 8.5, '{"poet":"Güvenc Dagüstün","poet_slug":"guvenc-dagustun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/siyanur-yuzukte-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dreams', 'dreams-langston-hughes-tyq87', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hold fast to your dreams

For when dreams die

Life is a barren field

Frozen wiş snow 

Hold fast to your dreams

For when dreams go

Life is a broken winged bird 

That cannot fly', 'Hold fast to your dreams For when dreams die Life is a barren field Frozen wiş snow  Hold fast to your dreams For when dreams go Life is a b...', ARRAY['Türk Edebiyatı','Şiir','Langston Hughes']::text[], 8.5, '{"poet":"Langston Hughes","poet_slug":"langston-hughes","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dreams-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ayrılış Hikayesi', 'bir-ayrilis-hikayesi-nazim-hikmet-ran-3y8lb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Erkek kadına dedi ki: 

- Seni seviyorum, 

ama nasıl? 

avuçlarımda camdan bir parça gibi kalbimi sıkıp 

parmaklarımı kanatarak 

kırasıya, 

çıldırasıya... 

Erkek kadına dedi ki: 

- Seni seviyorum, 

ama nasıl? 

kilometrelerce derin, kilometrelerce dümdüz, 

yüzde yüz, yüzde bin b
..........
..........', 'Erkek kadına dedi ki:  - Seni seviyorum,  ama nasıl?  avuçlarımda camdan bir parça gibi kalbimi sıkıp  parmaklarımı kanatarak  kırasıya,  çı...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-ayrilis-hikayesi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri Babalar Günü Biri Gittiğin Gündü', 'biri-babalar-gunu-biri-gittigin-gundu-hulya-yilmaz-t4jsp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşte bir babalar günü daha sensiz geçiyorSensiz,yanlız ömrümden..bir bilsen nasıl hasretim sana,sana ve gül kokuna.bir bilsen ne acı şu yokluğun,ne acıdır bu zamansız ayrılıklar.Yokluğunda neler çektim bir bilsen. her babalar günü ve 24 şubat ta....Vuruyor beni taa derinlerden bir yerden.bir çocuk ağlıyor içimde sessiz hıçkırıklara boğulmuş,o her akşam pencerede gelmeni bekleyen çocuk..Kokuna hasret,sesine hasret,sana hasret her yanım..Alışılmıyor bu acıya, hergün biraz daha yakıyor yüreğimi sessiz gidişin,sessiz,kimsesiz,öksüz gidişin..İki damla yaş saklarım gözlerimde,dökülürler onlarda her babalar günü ve 24 şubat ta.. Biri babalar günü biri gitiğin gündü! Bir bilsen nasıl hasretim sana, sana ve gül kokunaBir gece rüyamda gördüm elin değdi saçıma,tam 1 yıl yeti bana...Bir bayram sonrasıydı gidişin soğuk bir kış günüydü..Bir hastahane kapısında öğrendim gittiğini..Çöktüm basamaklarına...yaş dökülmedi gözlerimden dökülemedi..Ah bir bilsen nasıl hasretim sana, sana ve o gül kokuna İki damla yaş birikir gözlerimde ve dökülür işte.. her babalar günü ve 24 şubat ta..Biri babalar günü biri gittiğin gündü..-Öğrettiğin hiçbirşeyi unutmayacağım-', 'İşte bir babalar günü daha sensiz geçiyorSensiz,yanlız ömrümden..bir bilsen nasıl hasretim sana,sana ve gül kokuna.bir bilsen ne acı şu yokl...', ARRAY['Türk Edebiyatı','Şiir','Hülya Yılmaz']::text[], 8.5, '{"poet":"Hülya Yılmaz","poet_slug":"hulya-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/biri-babalar-gunu-biri-gittigin-gundu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tasvir', 'tasvir-orhan-polat-gasjg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bekliyor ve tasvir diyorum;

belki anadoludan başlamalıyım,

kısadan kesmek için tasviri...

yolları duman duman ,

taşları umut olsun diye,

kendimin...

kendimdir konum bugün,

masada yatıyor kendim,

sorgulanıyor...

analizi yanlı olsada,

çoğu kelime bana göre,

kendimce ile başlayacak...

ve bunun içinle bitecek.

süzgeç zaman ve ben,

umut,beklenti,zaman,

hırs,zaruret,heyecan,

aktarma,yönelim ve ....

ve lerin hakim olacağı ,

ama duyuramayacağı,

taşımak,yüklenmekle ilgili,

anlaşılmaz ve derinler..

çözümler içinde çözümsüzlükler,

başarının yanında başarısızlıklar,

anlaşılamayan ilişkiler..

adına çetrefil diyorlar,

soyadına değişim.

orta asyadan gelen bir haykırış olsa gerek,

gelişi güzele başkaldırı...

gözler anlatmalı,

dudaklar ve hareketlerdeki duyguları.

kapandımı anlamalısın gözlerdekini,

utanarak kaçırmalısın,

kendini elevermeden,

yoksası bol olsun diye ,

kandırdım demelisin...

ama hiç kandıramadığın hep kendinsin,

uzaklara uçuvermelisin,

o anda atlamalısın hendekten,

sonra karşı kıyıya..

bağırmalısın oradan sende diye,

halbuki köprü yok, tahtaları senin elinde,

mazeretin olsun diye,

sokakta lambalar istediğin yerde,

düğmeleri senin elinde...

ve bir gün köprüler,sokaklar,

ve de lambaları buluverirsin oturumda,

kendinle aynı masada sonra da dersin adına tasvir...

( 21/01/2000

ankara  )', 'bekliyor ve tasvir diyorum; belki anadoludan başlamalıyım, kısadan kesmek için tasviri... yolları duman duman , taşları umut olsun diye, ken...', ARRAY['Türk Edebiyatı','Şiir','Orhan Polat']::text[], 8.5, '{"poet":"Orhan Polat","poet_slug":"orhan-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/tasvir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Masalı', 'ask-masali-seckin-sibreli-9ejcl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevginin tükendiğini gördüm

Garip bir aşk masalında

Sevgiliye verilmiş solan bir gül buldum

İnce bir kitap arasında

Gözyaşlarıyla ıslanan bir yüreğin feryadını duydum

Buğulu pencereli odalarda

Yanlızlıkla dost olanları tanıdım

Bir ışık süzmesinin aydınlattığı sokaklarda

Hasretleri kalbine gömen aşıklar gördüm

Sevgilinin gelmediği zamanlarda

Hıçkırarak ağlamayı öğrendim

Sensiz kaldığım karanlık gecelerde

Bir tek...

Seni sevdiğimi haykırarak söylemeyi özledim

Hasretine katlandığım günlerde', 'Sevginin tükendiğini gördüm Garip bir aşk masalında Sevgiliye verilmiş solan bir gül buldum İnce bir kitap arasında Gözyaşlarıyla ıslanan bi...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Sibreli']::text[], 8.5, '{"poet":"Seçkin Sibreli","poet_slug":"seckin-sibreli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ask-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Yasak,Aşk Günah,Aşk Ceza', 'ask-yasak-ask-gunah-ask-ceza-seckin-sibreli-i22lm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Büyük bir göç var yüreğimde

İsyan niteliğinde bir göç

Yüreğim kendi kendine ceza veriyor

Yasaklarla dolu bir ceza

Büyülü aşk bile yetmiyor

Çünkü...

Aşk yasak,aşk günah,aşk ceza

Her şeye rağmen seviyorum

Fakat aşk bana yakın değil

Hala deli gibi korkuyorum

Çünkü...

Ölüm bana uzak değil', 'Büyük bir göç var yüreğimde İsyan niteliğinde bir göç Yüreğim kendi kendine ceza veriyor Yasaklarla dolu bir ceza Büyülü aşk bile yetmiyor Ç...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Sibreli']::text[], 8.5, '{"poet":"Seçkin Sibreli","poet_slug":"seckin-sibreli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-yasak-ask-gunah-ask-ceza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varamadık', 'varamadik-cevahir-evren-v4m92', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüyamdaydı eleleydik

Koşuyorduk

Ateş vardı

Gül vardı yaprak vardı

Su vardı

Sevgi vardı özlem vardı

Sen vardın 

Ben vardım gözler vardı

Biz varamadık...', 'Rüyamdaydı eleleydik Koşuyorduk Ateş vardı Gül vardı yaprak vardı Su vardı Sevgi vardı özlem vardı Sen vardın  Ben vardım gözler vardı Biz v...', ARRAY['Türk Edebiyatı','Şiir','Cevahir Evren']::text[], 8.5, '{"poet":"Cevahir Evren","poet_slug":"cevahir-evren","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/varamadik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-engin-gurpinar-ucwhf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönül müphem hislerin bulunduğu bir handı

Şetaretle matemin sarıldığı cihandır

Hancının şişesinden boşalan umut kadar

Yolcunun gözlerinden akan bir damla kandır', 'Gönül müphem hislerin bulunduğu bir handı Şetaretle matemin sarıldığı cihandır Hancının şişesinden boşalan umut kadar Yolcunun gözlerinden a...', ARRAY['Türk Edebiyatı','Şiir','Engin Gürpınar']::text[], 8.5, '{"poet":"Engin Gürpınar","poet_slug":"engin-gurpinar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gonul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Şiiri', 'ask-siiri-sabahattin-kudret-aksal-v06fb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu şiirin ilk mısraı

Senin için yazıldı

İkincisini söylerken

Bilinmez kimi düşüneceğim

Gel de inan şimdi sen

Aşk şiirine', 'Bu şiirin ilk mısraı Senin için yazıldı İkincisini söylerken Bilinmez kimi düşüneceğim Gel de inan şimdi sen Aşk şiirine...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Kudret Aksal']::text[], 8.5, '{"poet":"Sabahattin Kudret Aksal","poet_slug":"sabahattin-kudret-aksal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altıncı Gün', 'altinci-gun-ozdemir-asaf-zgz2s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ALTINCI GÜN

Benim söylemek için çırpındığım gecelerde,

Siz yoktunuz.', 'ALTINCI GÜN Benim söylemek için çırpındığım gecelerde, Siz yoktunuz....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/altinci-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ultra', 'ultra-ozdemir-asaf-zel5o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ULTRA

Bir kelimeye

Bin anlam yüklediğim zaman

Sana sesleneceğim.', 'ULTRA Bir kelimeye Bin anlam yüklediğim zaman Sana sesleneceğim....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ultra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğmamış Bir Günün Ardından', 'dogmamis-bir-gunun-ardindan-cevahir-evren-nuo02', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'doğmamış bir günün ardından sonuna kadar suya 

batacak kadar güneşe

ve yanacak kadar ateşe 

ihtiyacı var bensizliğin

senki yalnız geçen günlere sitem et benim için 

belki gerek kalmaz o zaman dünyaya

yaşamak için.

Karanlığın içinden yükselen 

küçük bir mum alevi

öyle aydınlatıyorki beni sen orada 

milyonlarca yıldızın içinde

arasan bulamazsın 

böyle gerçekten seveni

/aşk ile tığlar çekip minkire

karşı durmuşuz

ol sebepten kavm-i süfyan eşkiya 

derler bize/

anlaşılanı oysa

ne güzeldir gül

bir de olmasa dikeni...', 'doğmamış bir günün ardından sonuna kadar suya  batacak kadar güneşe ve yanacak kadar ateşe  ihtiyacı var bensizliğin senki yalnız geçen günl...', ARRAY['Türk Edebiyatı','Şiir','Cevahir Evren']::text[], 8.5, '{"poet":"Cevahir Evren","poet_slug":"cevahir-evren","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dogmamis-bir-gunun-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Işık Işık', 'i-stanbul-isik-isik-umit-yasar-oguzcan-1vvxw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstanbul rüzgar rüzgar sevdiğim

Kah bir lodos denizlerden esen

Ilık mı ılık

Kah ustura gibi bir deli poyraz

Bırak saçlarını rüzgarına İstanbul''un

Bu şehirde aşksız ve rüzgarsız yaşanmaz

İstanbul bulut bulut sevdiğim

Kimi beyaz mı beyaz

İnce gül gibi

Kimi katran misali kapkara

Bulutları da insanlarına benzer İstanbul''un

İnanma sevdiğim inanma bulutlara

İstanbul yağmur yağmur sevdiğim

Kah ince ince

Kah bardaktan boşanırcasına

Hele bir yağmur yağmaya görsün

Ölürcesine yaşanır bu şehirde sevdiğim

Ve bir gün ölünür yaşanırcasına

İstanbul deniz deniz sevdiğim

Bir çakır mavi

Bir camgöbeği tuzlu su

Üstünde irili ufaklı tekneler

Kayıklar,yelkenliler,mavnalar

Kalleştir denizleri İstanbul''un sevdiğim

İstanbul kadar

İstanbul kadeh kadeh sevdiğim

İçtikçe içesi gelir insanın

Sarhoşluğu tutuşup yanmaya benzer

Ve bir gölgedir yalnızlık meyhanelerinde

Seninle dolaşır,seninle gezer

İstanbul şarkı şarkı sevdiğim

Üsküdara gidersin hava güneşli

Beklersin ada sahillerinde yağmur yağar

Her dakika depreştirir derdini

Köhne gramofonlar,eski plaklar

Nice güzeller,nice şairler görmüş

Artık kanıksamış dertlerimize

İstanbul herşeye alışık sevdiğim

Yine de bütün mihnetleri bir yana

Sen yaşadıkça İstanbul ışık ışık sevdiğim', 'İstanbul rüzgar rüzgar sevdiğim Kah bir lodos denizlerden esen Ilık mı ılık Kah ustura gibi bir deli poyraz Bırak saçlarını rüzgarına İstanb...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/istanbul-isik-isik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üstüme Varma İstanbul', 'ustume-varma-i-stanbul-umit-yasar-oguzcan-g3ld6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana geldim içim ümitlerle dolu

Beni sarhoş etme İstanbul,ne olur

Bir gün ben de eririrm caddelerinde

Çürür kemiklerim adım unutulur

Yine sen kalırsın dipdiri,sımsıcak

Göğün bulutların,denizlerin kalır

Oynama İstanbul,benimle oynama

Bir gün öldürür beni bu dert,bu kahır

Ezilmiş ellerimin arasında başım

Bu yeryüzünde başka çarem kalmamış

İşte gelip kapılarına dayanmışım

Karşında yıkılmış duvar gibiyim

Beni sarhoş etme,başım dönüyor

Üstüme varma İstanbul,kederliyim', 'Sana geldim içim ümitlerle dolu Beni sarhoş etme İstanbul,ne olur Bir gün ben de eririrm caddelerinde Çürür kemiklerim adım unutulur Yine se...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ustume-varma-istanbul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gonca Gülmüsün?', 'gonca-gulmusun-sair-uninvited-1596e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akmam diyerek buharlaşıyorsun 

Kokmam diyerek yaprak kapatıyorsun 

Filizlenmem diyip güneşe burun kıvırıyorsun 

Söyler misin? Sen hangi dünyadasın 

Dikenlerin narin ve yumuşak

Yoksa sen bir gonca gül müsün? 

Toprağımda değilim diyorsun 

Yoksa sanal kafesinde misin? 

Ovuşturduğum gözler mehtapta her tenefüsümde 

Vuran ay’ın parıltısından, gül 

Ay, güneş doğduğunda yok mu olacak, kayıp mı? 

Yokluğun varsa kamaştırma gözlerimi!!! 

Kayıpsan... 

Kayıpsan, tut ellerimi güneşin olup ta doğayım, hilal’im ol bat bende 

Arkadaş mısın, adını sen koy 

Adımların şu an senin izinde... 

Acele etme ama hızlı ol 

An bu, tıpkı zaman gibi, sabun gibi eriyip gider gözlerinin içinden 

Yüreğinin kor olduğu anlar sönüpte biter... 

Demiri ateşin har zamnında döv 

Köfteni ise köz olduğunda cızırtdat 

İşte hayat, vazgeçilmez tat 

Ay çehrende, ürkek bakışlar 

Isıtmak için yola çıkan ışınlar 

Öyle bir eda öyle naz saçıyor ki 

Isıtmıyor, yakıyor arkadaş... 

Nice kara delikler var ki seni senden 

Seni o’ndan alır, ışınların bile ulaşamadığı fezalara fırlatır... 

Başkaları için yaşamak niye 

Bu kalış, bu kaçış kime 

Farkında olmadan açtığın kara deliğe 

Bir an önce elveda de...', 'Akmam diyerek buharlaşıyorsun  Kokmam diyerek yaprak kapatıyorsun  Filizlenmem diyip güneşe burun kıvırıyorsun  Söyler misin? Sen hangi düny...', ARRAY['Türk Edebiyatı','Şiir','Şair Uninvited']::text[], 8.5, '{"poet":"Şair Uninvited","poet_slug":"sair-uninvited","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gonca-gulmusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'seni-sevmek', 'seni-sevmek-ozlem-turhan-6pe2w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni sevmek 

yeniden bulmaktı hayatın anlamını

yalan yanlış,saçma sapan

seni sevmek

hep aradığım şeyin aslında hep yanımda olduğunu farketmekti

yeniden çocukca sevinçlere boğmaktı yüreğimi

seni her görüşümde baştan ayağa titremekti

seni sevmek 

öyle beş on kelime ile iki satır şiirle anlatılamayacak bir şeydi

asla uygun sözcük bulunamayacaktı ve de

seni sevmek 

sonu olmayan bir masala inanmaktı

masaldaki çocukla

dev bir kuşun kanadında dünyayı dolaşmaktı

seni sevmek 

yaşadığım şehrin maviden uzaklığına inat

bütün rüyalarımda deniz kenarında bulmaktı kendimi

neyin düs neyin gerçek olduğunu bilemeyip

kıyıya vuran dalgalardan biri olmaktı

seni sevmek

aslında bir yalana inanmaktı

ve inadına peşinden gitmekti o yalanın

dünyanın en güzel yalanına

aşk yalanına

seni sevmek...', 'Seni sevmek  yeniden bulmaktı hayatın anlamını yalan yanlış,saçma sapan seni sevmek hep aradığım şeyin aslında hep yanımda olduğunu farketme...', ARRAY['Türk Edebiyatı','Şiir','Özlem Turhan']::text[], 8.5, '{"poet":"Özlem Turhan","poet_slug":"ozlem-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutsuzluk Rüzgarları', 'mutsuzluk-ruzgarlari-cevahir-evren-qc0d2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mutsuzluk rüzgarları esiyor

yalnız gecelere sıkıntı yüklü vapurlar eşlik ediyor

açık sonsuz mavilik derin seher sancıları

dalıyorsun milyonlarca yine dibe ulaşamıyorsun

yoksa diyorsun güneş hiç yanlış anlatır mı gölgeyi

dokunabilir misin eteklerine duyabilir misin dağların sesini

ağlatabilir misin

güzellik yalın kalmamalı

gözlerin yeşilini görmek için gözlerin açık olmalı

dahası var 

yok olmaya yüz tutmuş onlarca bitki

nane kokusu duyuyor musun

mademki diyorsun yaşayalım

yaşamak insan için değil

yaşayan için olmalı

yaşayan olamıyorsan ne anlamı var insan olmanın

sevgi treni geçiyor bütün vagonları tıka basa dolu

en sonuncusu sevda masalıyla

masal ama gerçek anlatım bozukluğu değil

anlamsızlık içinde var olma çabası

Mutsuzluk rüzgarları hala esiyor 

hissediyor musun duyguları

kar yağıyor ama kırmızı 

kan bulaşmış kaynağına 

kazımışlar yarasını

derken sımsıcak bir bahar havası

yeşilleniyor dünyası kapısı bacası

ilk aşklarını olmak isteyen gönül

ve onu gamsız anası...

localara çekilip saatlerce kitap okumak 

bile insanı yormaya başlıyor

deki ne oldu bizim şarkılar

şiirler yoksa beğenmedin mi

beğendim diyemedin değil mi

sana yaptığın yanlışın acımasız karanlığında 

sesleniyorum

söylediklerinin beni götürüp

getirmediği yerden

sanki bir daha hiç çıkamayacakmışım gibi

üstüme geliyor hamam böcekleri

tanesi bilmem kaç milyondan sigaralarla

çarşaflara sarın beni

bembeyazından olsun

gücüm yetmesin siyaha

fakir kalayım şu salak dünyanın

anlamsız savaşının

bitmek bilmeyenliğin ortasında

deve postu demedim

bembeyaz bir çarşaf

anasını bile demeden vurun beni

ağlamaktan yorgun düşeyim

soluk soluğa.

Dante misali sinekleri yapıştırın

piç olsun geceleri

memeleri sarksın aşağıya...

Bitti mi, 

Bitmek mi yeni başladım

sarhoş olacaksın öpüşmekten

rüyalarına giremeyecek 

bir şey yapacaksın diye

elini tutacaksın sıkacaksın

ağlamaya başlayacak

ama dur demeyecek

hayal değil gerçek

ertesinde kalkınca güleceksin 

sanki ben değildim

öldürdüm seni

senin katlini verdim düşlerime

orada vurdular seni

acımak mı

komiksin...

Bıraksaydın seveydim seni

sevda kuytularında öpeydim dudaklarını

görenler mutlu deseydi

biz mutlu olsaydık

şans verseydin hiç olmasa elini tutsaydım

deki neyine gerek 

kimsin ki bunları söylüyorsun

doğrudur diyemem 

ama diyeceksem eğer:

''küçüksün sen gözlerin bebek

ben sonsuz yaşlı ve yorgunum

ben gidilmez ırak bir yolum

ıssızlara kaçarım yüreğimde''

beklemiyorum beni anlamanı

bu hataya bir kere düşmüştüm bir daha mı

asla...

Sana hep yanındayken doğal olmadığımı söylerim

evet doğal olamıyorum

ama bundan sonra sen de benim yanımda olamayacaksın

olmaya çalışma yorulursun

geceleri ağlarsın

uykusuz ve aç kalırsın bugün seni mutlaka görmeliyim

anlamasan da konuşmalıyım

bir umut dersin

merhaba-dan

iyi günler-den

görüşürüz-den

hep o umdun çevresinde hayaller kurarsın

olmayacağını hiç düşünmezsin

taki sana hiçbir şey hissetmiyorum deyinceye kadar 

sonra mı 

o çok daha basit

sonra her şeyin benim bildiğim gibi olmadığını

beni gerçekten sevdiğini

yanımda bir garip olduğunu

seni anlamam gerektiğini

böyle durumlara benim de düşmüş olabileceğimi

falan söylersin.

Rus kargo uçakları var bilir misin 

haftada bir kere kalkar 

sonra çok gürültülüdür

kulaklarını tıkarsın

burnundan ağzından ses içine işler

ses bir dakika boyunca sürer

ama sen o sesi bir gün boyunca yanında taşırsın

aynı sende olduğu gibi

seni de haftada bir kere görüyorum

her seferinde senden kaçıyorum

ama o arlarda bir yerlerden içime girip

öteki haftayı sabırsızlıkla bekletiyorsun

sence aşk bunun neresinde...', 'Mutsuzluk rüzgarları esiyor yalnız gecelere sıkıntı yüklü vapurlar eşlik ediyor açık sonsuz mavilik derin seher sancıları dalıyorsun milyonl...', ARRAY['Türk Edebiyatı','Şiir','Cevahir Evren']::text[], 8.5, '{"poet":"Cevahir Evren","poet_slug":"cevahir-evren","theme":"Türk Şiiri","is_hero":false,"total_lines":122,"source_url":"https://www.antoloji.com/mutsuzluk-ruzgarlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Konçertosu -1-', 'siyah-koncertosu-1-turgut-erdogan-1vwpd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu aralar 

Bir siyah tutturmuşum

her şey siyah olsun istiyorum

Bir güneş doğuyor

Simsiyah

Aydınlanıyor dünya

Geceleri

Mehtabın şavkı vuruyor

Siyah denizler üstüne

Kara selviler büyüyüor tepelerde

Siyah papatyalar, gelincikler

Issız bayırlarda.

Bir kara sevda yürüdü damarlarıma

Koşuyor şimdi

Tâ yüreğimin oralarda...', 'Bu aralar  Bir siyah tutturmuşum her şey siyah olsun istiyorum Bir güneş doğuyor Simsiyah Aydınlanıyor dünya Geceleri Mehtabın şavkı vuruyor...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/siyah-koncertosu-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Konçertosu -2-', 'siyah-koncertosu-2-turgut-erdogan-9f3vo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Siyah

Hüzündür derler hep

Yalnızlıktır

Kötüdür

Yalan bunların hepsi

Siyah olmalı denizlerin mavisi

Siyah olalı dağların yeşili

Rodrigo''da değiştirsin

Tüm konçertolarını

Bütün bestelerini

Yeniden

Siyah üzerine yazsın

Yeşil, mavi, çakır göz istemiyorum

Artık

Bütün gözler siyah olsun...', 'Siyah Hüzündür derler hep Yalnızlıktır Kötüdür Yalan bunların hepsi Siyah olmalı denizlerin mavisi Siyah olalı dağların yeşili Rodrigo''da de...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/siyah-koncertosu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Konçertosu -3-', 'siyah-koncertosu-3-turgut-erdogan-u7x3y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Siyah bir entari giymişsin

Siyah eskarpinler ayağında

Bana koşuyorsun

Kara sevdalına

Sarılıyoruz

Sütbeyaz oluyor

Ne varsa dünyada...', 'Siyah bir entari giymişsin Siyah eskarpinler ayağında Bana koşuyorsun Kara sevdalına Sarılıyoruz Sütbeyaz oluyor Ne varsa dünyada......', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/siyah-koncertosu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Konçertosu -4-', 'siyah-koncertosu-4-turgut-erdogan-ogotz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aydınlansın prangalı gecelerim

Hüzünler birer birer yok olsun

Artık anlamı yok ebem kuşağının

Anlamı yok çarşafların beyazlığının

Kaderim aydınlık

Kefenim siyah olsun...', 'Aydınlansın prangalı gecelerim Hüzünler birer birer yok olsun Artık anlamı yok ebem kuşağının Anlamı yok çarşafların beyazlığının Kaderim ay...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/siyah-koncertosu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mumcu''nun Ardından', 'mumcu-nun-ardindan-turgut-erdogan-03kwj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uyuyordum bir süredir

Bir süredir

Halkım uyumaktaydı.

Kahpe dünya yatağımız

Kara gök yorganımızdı

Yıl 1993

Günlerden 24 Ocak''tı

Parçalandı bir yıldız

Dağıldı yeryüzüne

Yüzbinlerce, milyonlarca meşalenin

Şavkı vurdu gökyüzüne

Unutulmayacaksın UĞUR MUMCU

Kırılmaz kalemle yazdık

Adını yüreğimize', 'Uyuyordum bir süredir Bir süredir Halkım uyumaktaydı. Kahpe dünya yatağımız Kara gök yorganımızdı Yıl 1993 Günlerden 24 Ocak''tı Parçalandı b...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mumcu-nun-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Gibi Adam -2-', 'adam-gibi-adam-2-turgut-erdogan-cvbcf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adam gibi adam

Demiştik ya

Bir zaman...

Biz de çalışıyoruz

Öyle olmaya

Tabii

Kendimizce...', 'Adam gibi adam Demiştik ya Bir zaman... Biz de çalışıyoruz Öyle olmaya Tabii Kendimizce......', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/adam-gibi-adam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Gibi Adam -3-', 'adam-gibi-adam-3-turgut-erdogan-lx7ky', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adam gibi adam

İnsan olalım dedik

Biz farkında değilmişiz anlaşılan

Anlaşılan farkında değilmişiz

Maskeli bir baloda olduğumuzun

Çoğu insan 

Adam maskesi altında!!!

Biz habersizmişiz anlaşılan

Anlaşılan habersizmişiz

İnsanın 

Nasıl adam olduğundan...

Ya da adamın

Nasıl insan olduğundan...

Belli değil mi?

İnsanlar tarafından

Her zaman

Vurulduk sırtımızdan...

Sonuç;

Bütün ''adam''lar insandır

Ama...

Bütün insanlar

Adam değil', 'Adam gibi adam İnsan olalım dedik Biz farkında değilmişiz anlaşılan Anlaşılan farkında değilmişiz Maskeli bir baloda olduğumuzun Çoğu insan ...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/adam-gibi-adam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Nice Olur', 'olum-nice-olur-yasin-aksakal-b9ffq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elbet bir gün göçeceğiz bu yalan dünyadan 

Belki cennet belki cehennem ağırlayacak bizi

Sevipte kavuşanların ruhu şad olsun

Lakin sevipte kavuşamayanların

Onların ruhları ne olacak !

Gökyüzünde gezecekler mahşere kadar 

Nerede sevgili görseler başında  duracak

Ne zaman kavga etseler canı  yanacak 

Aglayacak göz yaşları yagmur olup düşecek 

Gül bahçesinin tam ortasına 

Güller hiç bir zaman solmayacak 

Aşkta göz yaşı  ve kavga bitecek', 'Elbet bir gün göçeceğiz bu yalan dünyadan  Belki cennet belki cehennem ağırlayacak bizi Sevipte kavuşanların ruhu şad olsun Lakin sevipte ka...', ARRAY['Türk Edebiyatı','Şiir','Yasin Aksakal']::text[], 8.5, '{"poet":"Yasin Aksakal","poet_slug":"yasin-aksakal","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olum-nice-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Hüzün', 'sari-huzun-the-devil-0zhn1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sari huzun

Baktigim ama goremedigim dakikalarda

Sininrlarimi zorlarken gokyuzunde

Nice yilidizlar kayar...

Tutunamadigim dallar kirilir

Basamadigim yerler yarilir aysiz gecelerde

Sanssizligim sebep olur da

Sesini dinledigim kuslar donuverir soguktan

Sinirlerde yasarim

Yapiskan saatlerde

Sari sari yapraklar duser gozlerime

Sanbahar huznunde

Kendime verdigim sozleri tutamam gozlerimle

Utangac gunes sokuluverir kosesine ben gecerken

Dunyam karariverir bir anda

Ellerim titrer

Sarsilirim!

Gunlugumden kara bir sayfa kopar

Ucuverir yine

Titrerim sari günlerde

Bir yanim guler, bir yanim aglar sessizken

Ezilir, büzülürüm kesir saatlerinde

Tanimadigim sinirlar engel olur hayallerime

Ve ben yine kalirim bedenimde', 'Sari huzun Baktigim ama goremedigim dakikalarda Sininrlarimi zorlarken gokyuzunde Nice yilidizlar kayar... Tutunamadigim dallar kirilir Basa...', ARRAY['Türk Edebiyatı','Şiir','The Devil']::text[], 8.5, '{"poet":"The Devil","poet_slug":"the-devil","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sari-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Tadında Mektup', 'mavi-tadinda-mektup-soner-tozkoparan-3veh8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'istediğim zaman degil

güldüğün zaman gelmelisin bana

tıpkı gülen resmin gibi olmalı yüzün

herşeyinle güldüğün zaman gelmelisin...

çöplük çocukları nın öyküsünü anlatmalısın

boyacı çocukların ellerindeki

 boya lekeleri ,gelmeli gözlerimizin önüne

gemisini kaybetmiş kaptanın 

hüznü dalmalı belki de gecemize

yıldızları vuran kahbe kurşunların 

yüreğimizi titretmesiyle akmalı göz yaşlarımız

güldüğün zaman olmalısın 

sensizlik kokan odamda

gözyaşların bile gülerken akmalı

gülerken anlatmalısın düşlerini

istersen beni sevdiğini söyleme 

bilirimki hüznünde ben yokum

sevmeye değer verdiğin ,

bir şeyler ağlatmalı seni

sen ağlarken saçlarını okşamalıyım

omuzumda uyumalısın

benden cesaret almalı hayallerin

istediğim zaman değil

güldüğün zaman gelmelisin 

benimle hüzünlenmeli benimle gülmelisin

belki çok şey istedim senden 

anlattığın doğrular korkuttu belkide

ama sen yinede gülmelisin benimle

güneş ellerimizin arasında doğmalı 

sen ellerimin arasında uyumalısın

üzülüyorum...

yıkık bir kentin son gerçeğiyim belkide

yanlızlık çökmemeli omuzlarıma

senin düşlerin çökmeli

yazdığım yanlız lık romanını okumalısın bana 

hep sen değil ,birazda ben gülmeliyim

birazda ben anlatmalıyım çöplük çocuklarını

biraz da ben ağlamalıyım senin omuzlarında 

biraz sen , birazda ben sevmeliyim yıldızları

istediğim zaman değil 

güldüğün zaman gelmalisin 

sensizliğin olduğu her yerime', 'istediğim zaman degil güldüğün zaman gelmelisin bana tıpkı gülen resmin gibi olmalı yüzün herşeyinle güldüğün zaman gelmelisin... çöplük çoc...', ARRAY['Türk Edebiyatı','Şiir','Soner Tozkoparan']::text[], 8.5, '{"poet":"Soner Tozkoparan","poet_slug":"soner-tozkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/mavi-tadinda-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye', 'niye-sinem-buru-2jgj3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Belkide eylüldendir bu hüzün 

İçim feşedilmemiş zor bir kale

Çözümsüz.

Kime?

Niye?', 'Belkide eylüldendir bu hüzün  İçim feşedilmemiş zor bir kale Çözümsüz. Kime? Niye?...', ARRAY['Türk Edebiyatı','Şiir','Sinem Buru']::text[], 8.5, '{"poet":"Sinem Buru","poet_slug":"sinem-buru","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/niye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül', 'gul-adil-koruyan-qyff8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güneşle beraber umutla doğdun;

Canlıydın, diriydin, yaşam doluydun.

Kavuşmak, ellere ulaşmaktı umudun.

Oysa gelmedi, kaldık birlikte mahsun.

Gül, sana gülmek yakışır, durma solgun

Yaşam, ölmekse doğuşta, bil ki yoksun.', 'Güneşle beraber umutla doğdun; Canlıydın, diriydin, yaşam doluydun. Kavuşmak, ellere ulaşmaktı umudun. Oysa gelmedi, kaldık birlikte mahsun....', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaradana İsyan', 'yaradana-i-syan-adil-koruyan-xwq88', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beni yaratan sensin, can verensin,

Kaderimi çizen, yön verensin.

Sevgiyi gönüllere düşüren,

Kor gibi yakan ve yaktıransın.

Nedir öyleyse, cennet ve cehennemin?

Sevgiliyle birliktelik cennetse eğer,

Ayrılığın kendisi cehenneminden beter.

Bu aşk, bir ömre ve ölümsüzlüğe değer.

Nedir öyleyse, alınyazısı ve kader?

Sevin ve sevilin diyorsun,

Elçiler, kitaplar gönderiyorsun,

Sonra sevgiyi, sevgilileri hor görüyorsun.

Nerede büyüklüğün, vuslatı çok görüyorsun.', 'Beni yaratan sensin, can verensin, Kaderimi çizen, yön verensin. Sevgiyi gönüllere düşüren, Kor gibi yakan ve yaktıransın. Nedir öyleyse, ce...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yaradana-isyan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalet', 'hayalet-nahit-ulvi-akgun-sxsa3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sokaktan insanlar geçiyor

benim aklımdan hep sen

tramvayda yanımdasın

sofrada beraberiz

çatalı öyle tutma

sigara içme diyorsun

üzülüyorsun benim için

bak gömleğin kirlenmiş

bu sakalda neden

niye mahzun yüzün

tam konuşacağım seninle

kayboluyorsun', 'sokaktan insanlar geçiyor benim aklımdan hep sen tramvayda yanımdasın sofrada beraberiz çatalı öyle tutma sigara içme diyorsun üzülüyorsun b...', ARRAY['Türk Edebiyatı','Şiir','Nahit Ulvi Akgün']::text[], 8.5, '{"poet":"Nahit Ulvi Akgün","poet_slug":"nahit-ulvi-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayalet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayfer''e', 'ayfer-e-ekrem-akbaba-2z6xx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin en koyu renginde

Gökte bir  yıldız  kayar

Bilirsin o an  herkes bir  dilek tutar

Bende  farkında olmadan seni tutmuşum

Oysa  yıldızlar tutulamaz  unutmuşum

Ben mehlika yıldızını çok severim ve süreyya yı

Hatırladığımda unutmayı

Unuttuğumda bile sana şiir yazmayı

Ben mevlanadan öğrendim insanları anlamayı

Ve yunustan sevgiyle bağlanmayı

Bir  üveyik  kuşundan sevgiyi  aşkı

Depemde öğrendim yıkılmayı

Ve her yıkılışımda dimdik ayakta durmayı

Her şeyi rabbimden isterken avuç açmayı

Ve dedemden öğrendim  ilk duayı', 'Gecenin en koyu renginde Gökte bir  yıldız  kayar Bilirsin o an  herkes bir  dilek tutar Bende  farkında olmadan seni tutmuşum Oysa  yıldızl...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Akbaba']::text[], 8.5, '{"poet":"Ekrem Akbaba","poet_slug":"ekrem-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ayfer-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayferi aramak', 'ayferi-aramak-ekrem-akbaba-9p6wc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gece yarısı aklıma  düşersin de

Tavana  çakılı kalır  gözlerim

Beni de  götürseydin gidişinle öldürseydin

Gidince ebediyyen gitseydin..

Belki kalkar bir gece yarısı neskafe içerim

Yada sen seviyorsun diye papara yerim

Kahrolayım elimde değil kahrolayım

Hala telefona gider gözlerim ellerim

Sana NİSAN da bahar bana kar

Ölümü  hiç bu kadar istememiştim 

En az  seni istediğim kadar

Şimdi bir  bekar evim oldu bak

Ve hatta ağlayacak  odam bile  var

İçtiğim sigara mı bile değiştiririm

Belki senin gibi layt  içerim bende

Şeker hastası olduğun gelir aklıma

Tatlı olan ne varsa  yasaklarım kendime

Seni nasıl yasakladıysam yüreğime 

Seni aramadan surabilirim sanma

Ellerim durur yüreğim de  durur

Yüreğimden düşen her damla

Bir  kurşun gibi gelip yüreğimi vurur

Ve bir gün şu kalbimde  durur

İşte o  zaman  her şey unutulur

Belki kalkar bir gece yarısı neskafe içerim

Yada sen seviyorsun diye papara yerim

Kahrolayım elimde değil kahrolayım

Hala telefona gider gözlerim ellerim

Her gece sana şiir  yazacak değilim yaa

Bakarsın bir gece ben de uyurum

Bir gece dedim bir  gece untur beni yıldızlar

İşte o zaman beni ebedi bir  uyku tutar', 'Bir gece yarısı aklıma  düşersin de Tavana  çakılı kalır  gözlerim Beni de  götürseydin gidişinle öldürseydin Gidince ebediyyen gitseydin.. ...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Akbaba']::text[], 8.5, '{"poet":"Ekrem Akbaba","poet_slug":"ekrem-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ayferi-aramak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Sana Şiirlerim', 'hep-sana-siirlerim-ekrem-akbaba-gtv0u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu kalbimden geçenleri sana anlata bilsem

İşte o zaman en güzel şiirleri sana yazardım

Kim bilir bir şiirin arkasına saklanır

Yüreğimdekileri sana şiir diye yazardım

Belki  şiirimin başlığı olmazdı

Ama  sonu da hiç gelmezdi

Her seferinde  çok güzel dersin

Sana yazıldığını bilmeden teşekkür edersin

Oysa şiirlerimin arkasına  saklandığımı

Şiirlerimden başkası bilmezdi

Ömrümün şiirine ilk kez istedim dokunmak

Ve bir üveyiğin kalbinde ki..Dedim.

Aşkların en güzelini çalmak

Bir şirin ardına da sana varmak istedim

Bir  şarkıda der ki

'''' Nefes almak hüner değil

  Seninle  ölmek istiyorum  ''''

Oysa ben seninle  ölmek değil

Seninle hayatı göze almak istiyorum

Kim bilir bir şiirin arasına saklanır

Yüreğimdekileri sana şiir diye yazardım

Şiirlerimin arkasına  saklandığımı

Şiirlerimden başkası bilmezdi

Dedim ya bu şiirlerin sonu hiç gelmez di

Geceleri seni düşünür sana şiir yazar

Her gecenin sabahında güneşi yakalardım

Sevgilerin  en güzelini yüreğimden süzer

Her gün batımın da sana ağlardım

Kim bilir bir şiirin arasına saklanır

Yüreğimdekileri sana şiir diye yazardım

Şiirlerimin arkasına  saklandığımı

Şiirlerimden başkası bilmezdi

Dedim ya bu şiirlerin sonu hiç gelmez di', 'Şu kalbimden geçenleri sana anlata bilsem İşte o zaman en güzel şiirleri sana yazardım Kim bilir bir şiirin arkasına saklanır Yüreğimdekiler...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Akbaba']::text[], 8.5, '{"poet":"Ekrem Akbaba","poet_slug":"ekrem-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hep-sana-siirlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlediğim Akdeniz', 'ozledigim-akdeniz-i-lke-tunali-czemp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzanmışım,rahat gönlüm

bir  türkü  varmış bildiğim.

Sadece  çayın ritmi  kulaklarımda

sevda  şiirlerini okumuşum

kendi  başıma.

Özlediğim  akdeniz,bir bahar günü

-tatil  sabahıydı  hem  de-

yanaklarımdan  meltemine  öptürmüş.

Nasıl bir  deniz kokusuydu  duyduğum?

Uzanmışım....

Ada  kokusu  balık  olmuş

değiyor  yüreğime.

akdeniz ah,yoksun kendin

ama

izlerini buldum  yedi  tepede.

Sıcak bir gün,özlem dolmuş yüreğim.

Nasıl bir akdenizdir beklediğin?

Çayın şarkısı gibi sade.....

Güneşin  rengi kadar parlak

Düşüncem kadar uzak ve karmaşık

Düşlerim kadar gerçek ve  tekdüze

Nasıl bir sevdadır düşlediğin?

Derim:

Akdeniz kadar işte!', 'Uzanmışım,rahat gönlüm bir  türkü  varmış bildiğim. Sadece  çayın ritmi  kulaklarımda sevda  şiirlerini okumuşum kendi  başıma. Özlediğim  a...', ARRAY['Türk Edebiyatı','Şiir','İlke Tunalı']::text[], 8.5, '{"poet":"İlke Tunalı","poet_slug":"i-lke-tunali","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ozledigim-akdeniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Beni Kahretsin', 'allah-beni-kahretsin-ekrem-akbaba-1ai70', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçimden Allah  seni  kahretsin demek geçiyor

Bazan da sen geçiyorsun  ayfer

Sonra bir  sürü akrep geçiyor

Şimdi dinlediğim şarkıdasın 

Seyrettiğim filmdesin benimlesin

Oysa sen yazdığım şiirlerdesin

Benimle bir barakada bir çadırdasın

Yıkık tarumar bir şehirdesin

Ve dahası  hala yüreğimdesin

İçimden  Allah seni kahretsin demek geçiyor

Sonra bir  sürü akrep geçiyor

Biliyorsun ben sana Allah kahretsin diyemem

İçimden akrepler hep bu yüzden geçiyor

Bu gece de dün gece gibi

İçimden geçen akreplerim

Uykusuz gözlerim

Ve seni seven yüreğim

Bilirsin ki sana yazmakla bitmez  şiirlerim', 'İçimden Allah  seni  kahretsin demek geçiyor Bazan da sen geçiyorsun  ayfer Sonra bir  sürü akrep geçiyor Şimdi dinlediğim şarkıdasın  Seyre...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Akbaba']::text[], 8.5, '{"poet":"Ekrem Akbaba","poet_slug":"ekrem-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/allah-beni-kahretsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunmak İnceliktir', 'dokunmak-i-nceliktir-sina-akyol-slys9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dokunsam incinir misin?

Tüfeğini

kendine doğrultan

ve doğrultunca

pam diyen

sesim soruyor:

Dokunsam 

incinir misin?', 'Dokunsam incinir misin? Tüfeğini kendine doğrultan ve doğrultunca pam diyen sesim soruyor: Dokunsam  incinir misin?...', ARRAY['Türk Edebiyatı','Şiir','Sina Akyol']::text[], 8.5, '{"poet":"Sina Akyol","poet_slug":"sina-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dokunmak-inceliktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam İçin', 'babam-i-cin-sina-akyol-y247a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaz bahçesi!Sefalı vakitler!

Rüzgar narin! Hayat ince!

Zamanın rengi

kıvamına erince,

sofraya ardıç

dalı değerdi.

Sen, olgun kavun!

Ben, delikanlı peynir!

Hemhal olur söyleşirdik.

Genç babam,gencecik babam.', 'Yaz bahçesi!Sefalı vakitler! Rüzgar narin! Hayat ince! Zamanın rengi kıvamına erince, sofraya ardıç dalı değerdi. Sen, olgun kavun! Ben, del...', ARRAY['Türk Edebiyatı','Şiir','Sina Akyol']::text[], 8.5, '{"poet":"Sina Akyol","poet_slug":"sina-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/babam-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yumdum Gözlerimi', 'yumdum-gozlerimi-nazim-hikmet-ran-5vfbn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yumdum gözlerimi

Karanlıkta sen varsın

Karanlıkta sırtüstü yatıyorsun

Karanlıkta bir alt
..........
..........', 'Yumdum gözlerimi Karanlıkta sen varsın Karanlıkta sırtüstü yatıyorsun Karanlıkta bir alt .......... .............', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yumdum-gozlerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sısyphe', 'sisyphe-ozdemir-asaf-7n1e0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'SISYPHE

Seni öylesine düşündüm ki,

Öylesine, yaşama’dan önce.

Senden başka bir şey yok sanki.

Ama nasıl da varsın derim sana,

Düşüncelerimce.

Seni öylesine, buldum ki,

Öylesine, kendimden fazla.

Yalnız sensin gölgesiz, 

Ayrılmamacasına, yanımda..

Akların arasında karan,

Karaların ortasında akınla.

Öylesine istedim ki seni, 

Senden önce..

Öylesine, her şeyin içinde,

Öylesine dışında,

Gün, gece.

Seni öylesine yaşadım ki,

İnan..

Artık nereye baktığım belli değil,

Ne yaptığım belli değil,

Vardığım sonrasızlıktan.', 'SISYPHE Seni öylesine düşündüm ki, Öylesine, yaşama’dan önce. Senden başka bir şey yok sanki. Ama nasıl da varsın derim sana, Düşüncelerimce...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sisyphe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giden', 'giden-ozdemir-asaf-pqyo3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gecedir bütün geceler gibi

Saçlarında,tanıdığın ellerin en ağırı

Gözlerinde maceraların en derini...

Sana anlatırlar geçenle kalandan

Bir gecedir bütün geceler gibi

Karanlıklardan,aydınlıklardan

Ne varsa kendincedir

Pencere camlarında ışıklar parlar

Halıda yatar eşyanın gölgesi

İç içedir artık sokaklar,evler,odalar

Duvarlar bakışları keser,kapılar sesi

Ne varsa kendincedir

Ve senin,üzerinde binbir düşünce,günden

Oynaşır hatıranla,kalbinle,ümitlerinle

Herşey düşünmektedir seninle

Birden,bir rüzgar eser,sana doğru senden

Seninle çoğalmaya başlar kendisiyle bitenler

Hatırlayan ellerinle,unutmayan gözlerinle

Değişir sezilecek kadar yavaştan

Değişir istenen istenmeyen

O koruyan zor yalanlar silinir

Büyür kolay bir doğru,bilinen,söylenmeyen

Uyuyanlar uyanmış,ölüler dirilmiştir

Bir gecedir sana doğru senden

Bir gecedir sana doğru senden...

Geçen yaşadığındır,yaşarken anlamadan

Kalan bir gerçektir belki

Bir iğne gibi kaybolan,bir bardak gibi kırılan

Gelen sanki beklediğindir

Ve giden,en tatlı,en sıcak,en kocaman..', 'Bir gecedir bütün geceler gibi Saçlarında,tanıdığın ellerin en ağırı Gözlerinde maceraların en derini... Sana anlatırlar geçenle kalandan Bi...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/giden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor', 'zor-adil-koruyan-5p27v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Duygu selindeyim. Doyumsuz ve öldüresiye.

          Zor, seni senden dilenmek,

          Sevgini istemek, sevmeni beklemek.

Duygu doluyum. Sensiz ama çoşkulu.

          Zor, yaşama meydan okumak,

          Özgürce sevmek ve sevilmek

Zor; varken, yoku kabullenmek.', 'Duygu selindeyim. Doyumsuz ve öldüresiye.           Zor, seni senden dilenmek,           Sevgini istemek, sevmeni beklemek. Duygu doluyum. S...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/zor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel', 'guzel-adil-koruyan-c7ml6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir tanrı yaratmıştım, ben de bir zamanlar

Güzelsiz, güzeldi bütün güzellikler o’nda.

Şimdi o güzellikler ki, güzel yanında sönük

Tanrım, o tanrı değil artık.

Güzele güzel diyemem Tanrım, güzelin varlığında 

Güzel neye gerek Tanrım, 

                O’nun güzelliğinin sonsuzluğunda .....', 'Bir tanrı yaratmıştım, ben de bir zamanlar Güzelsiz, güzeldi bütün güzellikler o’nda. Şimdi o güzellikler ki, güzel yanında sönük Tanrım, o ...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Öğrendiklerim', 'senden-ogrendiklerim-ali-murat-celebi-ejque', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok şey öğrendim senden

Hayalleri öğrendim hayalkırıklığını da

Avunmayı öğrendim küçük mutluluklarda gömerek büyük emelleri

İhanetin bedelini sadakatimden öğrendim

Issızlığı öğrendim senin gecende

Taşkalpliliği sahte duygusallağından öğrendim

Ümitsizliği öğrendim sendeki umutlarımdan

Beklentiler bitince terkedilmeyi öğrendim

Unutulmayı öğrendim yeni anılar bulununca

Cehennemi öğrendim yalancı cennetinde

Bağlanmayı öğrendim aptalcasına ''senden vazgeçememlerden''

Yalanı öğrendim senin doğrularından

Sevgisizliği öğrendim senin BÜYÜK! sevginden

Umursamazlığı beni önemseyişinden! öğrendim

Birtek şey kaldı öğrenemediğim

Aşkın anlamını?', 'Çok şey öğrendim senden Hayalleri öğrendim hayalkırıklığını da Avunmayı öğrendim küçük mutluluklarda gömerek büyük emelleri İhanetin bedelin...', ARRAY['Türk Edebiyatı','Şiir','Ali Murat Çelebi']::text[], 8.5, '{"poet":"Ali Murat Çelebi","poet_slug":"ali-murat-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/senden-ogrendiklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neydi Dostluk?', 'neydi-dostluk-ali-murat-celebi-tfsji', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neydi dostluk?

Bir düşü paylaşmak mı umarsızca zamanın tortusunda bırakılan

Yıpranışa, kaybetteklerine ve acılara direnipte

Bir paylaşımda aramak mı herşeyi

Anıların yüklediği zorunluluklarda mı

Hayatın içinde paylaşılmış özlemleri, izleri aramak mı yoksa?

Sorularda bir giz mi

Yoksa cevaplardaki huşumu

Karşılaşmalardaki ürperti mi

Ayrılışlardaki buğulu hüzün mü yoksa

Sığınmak mı kuytusuna 

Bulamayıpta her aradığında yine dönüp sarılmak mı labirentine

Sorunları mı yoksa çözümsüzlüğü mü tüketmek her seferinde

Sevinçleri, güzellikleri;anılası, anlatılası kılmak mı

Gündoğumunda yeniden doğmak mı günbatımında koşmak mı ölüme

Bir güneş aramak mı, bir yıldız olmak mı çoğu zaman kayarken görünebilen

Ayna bile olabilmeyi başaramdığının farkındalığından uzak

Dostluğa adanmış bir şiirin dizelerinde

Ne çok unutup yazıdaki esaretin gözyaşlarını

Mahkum ettiğimiz umutları ruhumuzdan söküp atarak

Düşle gerçeği ayrımlaştırdığımız gün irkilmek mi

Tırnıklarımızla toprağı kazımak gibi

Sevginin emeğiyle kalbimize kazıdığımız küçük mutluluklar mı

Tükeneceğimizi hatıra getirmeksizin

Aldanma ve aldanışlarda ördüğümüz saklı bir hayal mi gönlümüzün kuytusunda

Bizi birlşetirdiğinisandığımız paylaşımlar mı

Filmlerde, kitaplarda, şiirlerde güzel yanlarında hayatın

Bütün bunları paylaşmanın asgariyetinde mi hep

Batağa saplandığımızda bir el aramak mı

Dert ortağı olurken, hep dertleri paylaştığını farketmeksizin

Hüzün olur artık bize en yakışan

Hüznün zorlamasıyla sorgusuzca sürüklenirken

Bütünüyle hiçbiri, belkide beyitlerdeki

Arayış mı keşfediş mi belli belirsiz

Söylemekten çok daha zorlaşır anlama

Belkide en anlamlısı da bu anlamsızlık

Emekle yoğrulan şeyse haykırılası ama hiç belki de hiç konuşmadan gözlerinin ufkunda

Hep orada olduğunu bilmektir, en uzakta olduğunda bile...

Bir yürek mesafede', 'Neydi dostluk? Bir düşü paylaşmak mı umarsızca zamanın tortusunda bırakılan Yıpranışa, kaybetteklerine ve acılara direnipte Bir paylaşımda a...', ARRAY['Türk Edebiyatı','Şiir','Ali Murat Çelebi']::text[], 8.5, '{"poet":"Ali Murat Çelebi","poet_slug":"ali-murat-celebi","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/neydi-dostluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oysa', 'oysa-zeren-cangert-c1rjm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sabah bakacaksın ki ,güneş senin için batmış.

Boşuna arama etrafın artık  karanlık.

Oysa kalbindeki taşın ilacı,

Eğer ağlayabilseydin İki damla göz yaşı.

Zaman su gibi akarken,

Güneşin senin için doğduğunu

Yağmur evinin camına damla damla vururken,

Aslında senin için yağdığını unuttun.

Kendini uçsuz bucaksız bir tarlanın ortasında,

Sırf gölgesinden belki birazda 

Serinliğinden yararlanılmak için

Dikilen bir ağaç gibi gördün ,

Kök Salmıştın dünyaya

Köklerin ekinleri kurutuyordu,

Kolların altındaki çiçeklere engel oluyordu

Denizi özlemedin hiç martının sesini bile bilemezsin

Ah bir bilseydin hayatı anlayabilseydin.

O zaman tatmadığın tatlar , koklamadığın kokular,

Dokunmadığın güzellikler heder olmayacaktı.

Sen olacaktın birde O 

Alın yazını parçalayacaktın,

Zaten Kader ne ki  senin kendi yazın.

Zamanında silebilirdin ,baştan kurardın cümleleri.

Noktayı virgülü boş verirdin .

Önemli olan hatanı silmek değil mi defterinden.

Kalemde sende idi , silginin birazı da sende

Şimdi bak ne haldesin güneşin yok, 

Dağlara özlemin yok ,yok işte koskoca bir yok

Köklerin söküldü dünyadan faydan sadece gölgendi,

Belki biraz serinlikti .

Yerine çok talip var ,onlarda arkandan gelecek

Ve onlarda unutacaklar, 

Varlıklarının kaç bahara mal olduğunu

Bu hikaye böyle sürüp gidecek.', 'Bir sabah bakacaksın ki ,güneş senin için batmış. Boşuna arama etrafın artık  karanlık. Oysa kalbindeki taşın ilacı, Eğer ağlayabilseydin İk...', ARRAY['Türk Edebiyatı','Şiir','Zeren Cangert']::text[], 8.5, '{"poet":"Zeren Cangert","poet_slug":"zeren-cangert","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/oysa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçeler', 'serceler-orhon-murat-ariburnu-z88gw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Serçeler sessizce uçamaz mısınız

Merak ediyorum cıvıltınızı

Serçeler yuvanızı nasıl yaparsınız

Akşamları tatlı mı yersiniz serçeler

Tuzlu mu yersiniz

Yuvalarınıza 

Eli boş döner misiniz benim gibi

Yavrularınıza hicab yalanları düzer misiniz

Sıkılmayın serçeler bana da söyleyin

Gözyaşlarınızı nasıl silersiniz', 'Serçeler sessizce uçamaz mısınız Merak ediyorum cıvıltınızı Serçeler yuvanızı nasıl yaparsınız Akşamları tatlı mı yersiniz serçeler Tuzlu mu...', ARRAY['Türk Edebiyatı','Şiir','Orhon Murat Arıburnu']::text[], 8.5, '{"poet":"Orhon Murat Arıburnu","poet_slug":"orhon-murat-ariburnu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/serceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşeye Karşın', 'herseye-karsin-celal-kabadayi-p31pu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gece gözlerine perdedir kiminin

kara tortudur kiminin yüreğine

karanlık kirli işler için güvence

acı bir çığlıktır kiminin sesine

sorarım size 

kavunumu bölüştüğüm karıncalar

sütümün gediklisi minik kedi

yemişini sevdiğim incir ağacı

hangi onurlu insanın çığlığıdır

sesimin tonunda çınlayan bu acı

aşkların yaşanamadığı yerler vardır

orada aşklar ancak şiirlerde yaşanır

elleri insan gözleri insan

binlerce insan yalnızca umuda yaslanır

bütün ışıkları söndürülse de aydınlık yolumuzun

senin korkusuz gözlerinde ışıldayan parıltı

ışık tutar işkenceleri idamları yararak

büyümesinin ilk gecesindeki tomurcuğa

ölürsek ölünmez bir yaz gecesi dostum

ağaç gövdeleri olsun gömütlerimiz

dallarında ötsün kuşlar başımızda ağlarcasına

yapraklar yellerle sevişsin aşkımızın anısına

sesleri insan yüzleri insan

binlerce insan arkamızdan el sallasın

belki toz oluruz belki toprak

üzerimizde taze filizleri yeşerir bilincin

inancın dereleri akar durur denizlere

dalgalar döver kıyılarını karanlığın

yıkılsa da geleceğe kurduğumuz köprüler

biliyorum ki her şeye karşın

ayışığının sevi çağrıları

umutların her demde çiçeklenmesi

sürünerek yaşamanın son bulduğu

insanın insan olduğu bir ülke özlemi

yitmeyecek ve yitirilmeyecek

güneş dünya defterini kapayıncaya dek

düşlerin gerçekleştiği yerler vardır

orada insanlar güvercin sesleriyle yıkanır

yaşam acı ve gözyaşı olarak sunulsa da

gözyaşlarının arasından milyonlarca gülücük ayaklanır', 'gece gözlerine perdedir kiminin kara tortudur kiminin yüreğine karanlık kirli işler için güvence acı bir çığlıktır kiminin sesine sorarım si...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/herseye-karsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güller Kararmasın', 'guller-kararmasin-celal-kabadayi-slosf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çekirgeler öterken sen sus

dudakların yorulmasın

ışığını söndürme bahçenin

güller kararmasın

yanında taşıma geceyi

sabahlar bozulmasın

yıldızları akşamdan sula 

karanlık çoğalmasın', 'çekirgeler öterken sen sus dudakların yorulmasın ışığını söndürme bahçenin güller kararmasın yanında taşıma geceyi sabahlar bozulmasın yıldı...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/guller-kararmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Öte Yüzü', 'gecenin-ote-yuzu-celal-kabadayi-mg0dv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kaldırımlarda yalnızlık izmaritleri

yarım kalmış mutluluklar gibi

kadehlerde yaşanmamış ilk aşklar

sevgisiz dudaklardan içiliyor şimdi

ellerinde suskunun yıllanmış şarabı

doğum gününü kutluyor seni öldürenler

salyalı ağızlarda iğrenç kahkahalar

yaşasın orospular diye bağırıyor pezevenkler

temiz çarşaflar seriliyor yataklara

üzerine gelincik kanı dökülüyor

gölgesinde asalak devlerin

minicik kızlar karanlığa gömülüyor

uyuyor ezilen emekçiler herşeyden uzak

sokaklarda çocuklarının geleceği kanıyor

gecenin bir yüzünde yaşamak 

öte yüzünde ozanlar ağlıyor', 'kaldırımlarda yalnızlık izmaritleri yarım kalmış mutluluklar gibi kadehlerde yaşanmamış ilk aşklar sevgisiz dudaklardan içiliyor şimdi eller...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecenin-ote-yuzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misilleme', 'misilleme-abdurrahim-karakoc-tjo1p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''İki kere iki dört'' ediyorsa, 

Ben de seni seviyorum, darılma. 

Bir de ''Her gecenin sabahı var'' sa, 

Ben de seni seviyorum, darılma. 

Demişler ki: ''Çivi, çiviyi söker'' 

Her eşek çamura bir defa çöker. 

Madem ''Kar üşütür, ateş te yakar'' 

Ben de seni seviyorum, darılma. 

''Her yokuşun bir inişi olur'' sa, 

''Aka aka, su çukuru bulur'' sa, 

İnsan doğar, yaşar, sonra ölürse, 

Ben de seni seviyorum, darılma. 

Durup dinlenmeden akarsa pınar, 

Her yıl kıştan sonra gelirse bahar, 

Balıkların suyu sevdiği kadar, 

Ben de seni seviyorum, darılma. 

Dikkat eyle geçmiyorum sırayı; 

Bozar ise kader bozsun arayı. 

Aç ekmeği sever, fakir parayı... 

Ben de seni seviyorum, darılma.

(Dosta Doğru)', '''İki kere iki dört'' ediyorsa,  Ben de seni seviyorum, darılma.  Bir de ''Her gecenin sabahı var'' sa,  Ben de seni seviyorum, darılma.  Demişl...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/misilleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Kızı Sevgili', 'deniz-kizi-sevgili-soner-tozkoparan-eb5ef', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seninle gülmeyi özledim sevgili

bütün göz yaşlarını unutarak zamanın

şehrin cümle sokaklarını 

aydınlatarak yürümeyi

solumayı özledim sevgili

bütün hasretleri içimize alarak

sesinin yankısını arıyor kulaklarım

bütün özlem çığlıkları gibi

ellerini özledim sevgili

gözlerindeki sabahları

tenindeki bütün çiçeklerin kardeş kokusunu

düşlerini,yüreğinin ateşini

omuzunda uyurken gördüğüm düşleri

saçlarımı okşamanı

en güzeli sevgini

deniz kızı sevgili

özledim seni 

ve seninle gelen bütün günleri', 'seninle gülmeyi özledim sevgili bütün göz yaşlarını unutarak zamanın şehrin cümle sokaklarını  aydınlatarak yürümeyi solumayı özledim sevgil...', ARRAY['Türk Edebiyatı','Şiir','Soner Tozkoparan']::text[], 8.5, '{"poet":"Soner Tozkoparan","poet_slug":"soner-tozkoparan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/deniz-kizi-sevgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zindandan Mehmed''e Mektup', 'zindandan-mehmed-e-mektup-necip-fazil-kisakurek-xkigz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zindan iki hece, Mehmed''im lâfta! 

Baba katiliyle baban bir safta! 

Bir de, geri adam, boynunda yafta...

     Halimi düşünüp yanma Mehmed''im!         

     Kavuşmak mı? .. Belki... Daha ölmedim!                                           

Avlu... Bir uzun yol... Tuğla döşeli,

Kırmızı tuğlalar altı köşeli.

     Bu yol da tutuktur hapse düşeli...

     Git ve gel... Yüz adım... Bin yıllık konak.

Ne ayak dayanır buna, ne tırnak!         

Bir âlem ki, gökler boru içinde! 

Akıl, olmazların zoru içinde.

Üstüste sorular soru içinde:

     Düşün mü, konuş mu, sus mu, unut mu? 

     Buradan insan mı çıkar, tabut mu? 

Bir idamlık Ali vardı, asıldı; 

Kaydını düştüler, mühür basıldı.

Geçti gitti, birkaç günlük fasıldı.    

     Ondan kalan, boynu bükük ve sefil; 

     Bahçeye diktiği üç beş karanfil...

Müdür bey dert dinler, bugün ''maruzât''! 

Çatık kaş.. Hükûmet dedikleri zat...

Beni Allah tutmuş, kim eder azat? 

     Anlamaz; yazısız, pulsuz, dilekçem...

     Anlamaz; ruhuma geçti bilekçem! 

Saat beş dedi mi, bir yırtıcı zil; 

Sayım var, maltada hizaya dizil! 

Tek yekûn içinde yazıl ve çizil! 

     İnsanlar zindanda birer kemmiyet; 

     Urbalarla kemik, mintanlarla et. 

Somurtuş ki bıçak, nâra ki tokat; 

Zift dolu gözlerde karanlık kat kat...

Yalnız seccâdemin yününde şefkat; 

     Beni kimsecikler okşamaz mâdem; 

     Öp beni alnımdan, sen öp seccâdem! 

Çaycı, getir, ilâç kokulu çaydan! 

Dakika düşelim, senelik paydan! 

Zindanda dakika farksızdır aydan.

     Karıştır çayını zaman erisin; 

     Köpük köpük, duman duman erisin! 

Peykeler, duvara mıhlı peykeler; 

Duvarda, başlardan, yağlı lekeler,

Gömülmüş duvara, baş baş gölgeler...

     Duvar, katil duvar, yolumu biçtin! 

     Kanla dolu sünger... Beynimi içtin! 

Sükût... Kıvrım kıvrım uzaklık uzar; 

Tek nokta seçemez dünyadan nazar.

Yerinde mi acep, ölü ve mezar? 

     Yeryüzü boşaldı, habersiz miyiz? 

     Güneşe göç var da, kalan biz miyiz?                                                 

Ses demir, su demir ve ekmek demir...

İstersen demirde muhali kemir,

Ne gelir ki elden, kader bu, emir...

     Garip pencerecik, küçük, daracık; 

     Dünyaya kapalı, Allaha açık.                                                               

Dua, dua, eller karıncalanmış; 

Yıldızlar avuçta, gök parçalanmış.

Gözyaşı bir tarla, hep yoncalanmış...

     Bir soluk, bir tütsü, bir uçan buğu; 

     İplik ki, incecik, örer boşluğu.                                                             

Ana rahmi zâhir, şu bizim koğuş; 

Karanlığında nur, yeniden doğuş...

Sesler duymaktayım: Davran ve boğuş! 

     Sen bir devsin, yükü ağırdır devin! 

     Kalk ayağa, dimdik doğrul ve sevin!                                                 

Mehmed''im, sevinin, başlar yüksekte! 

Ölsek de sevinin, eve dönsek de! 

Sanma bu tekerlek kalır tümsekte! 

     Yarın, elbet bizim, elbet bizimdir! 

     Gün doğmuş, gün batmış, ebed bizimdir! 

                                                               (1961)', 'Zindan iki hece, Mehmed''im lâfta!  Baba katiliyle baban bir safta!  Bir de, geri adam, boynunda yafta...      Halimi düşünüp yanma Mehmed''im...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/zindandan-mehmed-e-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konya''da', 'konya-da-bekir-sitki-erdogan-x2n92', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim yarim bezden kilim

Dokur Konya`da Konya`da

Bülbül olmuş dertli dilim 

Şakır Konya`da Konya`da

Kardeşim kendinden geçmiş

Nur çeşmesinden su içmiş

Hasret kitabını açmış

Okur Konya`da Konya`da

Gurbet ekmek ben katığım

Nişansız düşmüş tetiğim

Yazılmış nüfus kütüğüm

Şükür Konya`da Konya`da

Mevlana`nın sezmediği

Mantıkları çözmediği

Kitapların yazmadığı

Fikir Konya`da Konya`da

Ayrılıktan yemiş tekme

Yakma gurbet onu yakma

Burda gezdiğine bakma 

Bekir Konya`da Konya`da', 'Benim yarim bezden kilim Dokur Konya`da Konya`da Bülbül olmuş dertli dilim  Şakır Konya`da Konya`da Kardeşim kendinden geçmiş Nur çeşmesinde...', ARRAY['Türk Edebiyatı','Şiir','Bekir Sıtkı Erdoğan']::text[], 8.5, '{"poet":"Bekir Sıtkı Erdoğan","poet_slug":"bekir-sitki-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/konya-da-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi', 'sevgi-simge-atakan-lu400', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Herşeyden önce sevmeyi, sevilmeyi bil..

Bu hayatın oluşu, düzenidir.

Gözlerinde yaş olması iyimidir?

Sitem etmeden sözlerini bitir.

Herşey boştur fani dünyada

Ne arkadaşlık akılda nede sevda

insanların gözünü bürümüş para

Sen onlara bakmadan yoluna başla..

Sevgisiz hayat hiç olur mu?

Dünyanın düzeni bozulur mu?

Arda kalan boşluk doldurulur mu?

Söyle bensiz durulurmu?

                                      19/6/2000', 'Herşeyden önce sevmeyi, sevilmeyi bil.. Bu hayatın oluşu, düzenidir. Gözlerinde yaş olması iyimidir? Sitem etmeden sözlerini bitir. Herşey b...', ARRAY['Türk Edebiyatı','Şiir','Simge Atakan']::text[], 8.5, '{"poet":"Simge Atakan","poet_slug":"simge-atakan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevgi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efkarlı Şiir', 'efkarli-siir-turgut-yuca-cl30p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi burada yağsam gözlerimden

Damla damla, yaş yaş.

Kim görür? kim anlar ki beni yeterince?

Boşa gider mi damlalarım?

Yoksa birikip göl mü olurlar?

Birikir mi sevdalar da böyle içimizde?

Ya birikirse! sonra taşar mı gönlümüzde?

Sevda bu dayanır mı?

Yoksa o da korkusundan ağlar mı?

Sevdam ağlarsa ben ne yaparım?

Ne yaparım tek başıma?

Nasıl sustururum sonra bilmem ki

Ben bilemem ki.

Oysa sen anlarsın be!! ha 

Hani bi gelsen söyle okşasan

Nasıl olur bilirsin.

Oysa... sen olsan...

Ahh bi olsan..

(23/05/200 05:00)', 'Şimdi burada yağsam gözlerimden Damla damla, yaş yaş. Kim görür? kim anlar ki beni yeterince? Boşa gider mi damlalarım? Yoksa birikip göl mü...', ARRAY['Türk Edebiyatı','Şiir','Turgut Yuca']::text[], 8.5, '{"poet":"Turgut Yuca","poet_slug":"turgut-yuca","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/efkarli-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna', 'ayna-tugrul-tanyol-b7iej', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir büyük boşluk muydu

hangi ayak sesleri

zalim, yırtıcı ve alabildiğine kirli

gecenin yüreğinden kanatırcasına geçen

Bir büyük aynaydı, hayır

dansıyan hep kendi korkumuz

döküldü bir bir tüm sırlar

camın ardında ne gördünüz', 'Bir büyük boşluk muydu hangi ayak sesleri zalim, yırtıcı ve alabildiğine kirli gecenin yüreğinden kanatırcasına geçen Bir büyük aynaydı, hay...', ARRAY['Türk Edebiyatı','Şiir','Tuğrul Tanyol']::text[], 8.5, '{"poet":"Tuğrul Tanyol","poet_slug":"tugrul-tanyol","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ayna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdalar Tüneli', 'sevdalar-tuneli-cengiz-karatas-y0jhq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gül Bülbül Misali

Çocukluk Aşkımdın sevdalar tünelinde

Ruhumun temizliği yansımış gözlerine

Aşk ateşiyle kendinden geçmiş o tende 

Biz beraber büyüdük ayrılamazdık

Çocukluk aşkımdın sevdalar tünelinde 

hâlâ hayalimde el ele koştuğumuz anlar

göz göze gelip konuştuğumuz anlar

Biz beraber büyüdük ayrılamazdık

Çocukluk aşkımdın sevdalar tünelinde

Karşılıklı vefa içinde büyüdük bir beldede

Aşık olmanın suç olduğu bir ülkede

Biz beraber büyüdük ayrılamazdık

Çocukluk aşkımdın sevdalar tünelinde

Dedin ki bir gün:verecekler beni ele

Bu bizim son buluşmamız el ele

Bir daha görüşemezsek ''güle güle''

Çocukluk aşkımdın sevdalar tünelinde 

Sonra beraber büyüdük biz seninle 

Kalplerimiz gözyaşı oldu birden

Ayrılık vakti gelende...', 'Gül Bülbül Misali Çocukluk Aşkımdın sevdalar tünelinde Ruhumun temizliği yansımış gözlerine Aşk ateşiyle kendinden geçmiş o tende  Biz berab...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Karataş']::text[], 8.5, '{"poet":"Cengiz Karataş","poet_slug":"cengiz-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevdalar-tuneli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık', 'ayrilik-serhan-topal-jkzwy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökyüzünde bulut yok, bu ne karanlık

Sahilde bir ses acı bir ıslık

Gözlerimden akan yaşlar süzülürken ılık ılık

Söyleyin uzun yıllar bu mudur bu mudur AYRILIK........', 'Gökyüzünde bulut yok, bu ne karanlık Sahilde bir ses acı bir ıslık Gözlerimden akan yaşlar süzülürken ılık ılık Söyleyin uzun yıllar bu mudu...', ARRAY['Türk Edebiyatı','Şiir','Serhan Topal']::text[], 8.5, '{"poet":"Serhan Topal","poet_slug":"serhan-topal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ayrilik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece Rüyamda Gördüm Seni...', 'dun-gece-ruyamda-gordum-seni-filiz-salihoglu-xjr0p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün gece rüyamda gördüm seni...

Demeye varmiyor dilim

Perisan bir haldeydin

Üzerinde eskimis bir pantolon

Rengi solmus bir ceket

Yirtilmis bir gömlek

Ayaklarinda ise her biri baska 

Baska bir istikamete bakan cizmeler vardi

Dün gece rüyamda gördüm seni...

Demeye varmiyor dilim

Duruyordun ölye mahsun

Mahsun bir sekilde yol kenarinda

Sönen fenerle dayanip uzatmistin kollarini

Kollarini rüzgara  savurup sokagin ortasina

Bak yar,  günesin dogmasina yakin

Gökyüzünde yüzlerce kus ucusmakta

Bak yar, gömülmüs bu sehir

Kaldirimlarini issizca bahar sarmakta

Sen ise dalmissin derin derin, ah kim bilir

Ne hülyalara ne hülyalara...

Dün gece rüyamda gördüm seni...

Demeye varmiyor dilim

Saclarina ak düstüren yillarin izi vardi sanki avuclarinda

Bir elinde mutlu günlerin bir elinde ise

Kederli gecen günlerin hatiralarini tasiyordun adeta

Ah kim bilir,  nasil isterdin hencerlemek...

Hencerlemek kendini o güzel anilara

Dün gece rüyamda gördüm seni...

Demeye varmiyor dilim

Duruyordun öyle mahsun

Mahsun bir sekilde yol kenarinda

Duyulmayan bir feryad sinmis

Sinmis gizlice dudaklarina

Gözlerinden ise bir bezginlik

Bezginlik okunuyurdu adeta

Nefret dolu bakislar yansiyor

Yansiyor kirilan aynalarda

Dün gece rüyamda gördüm seni...

Demeye varmiyor dilim...

Söyle simdi yüzünde pismanlik mi okunmakta

Bagis dilegin yüregin mi son demini yasamakta

Bunca yil kaderdi yollarimizi ayirmakta

Simdi ise yüce Tanri mi bizi ayri koymakta

Dün gece rüyamda gördüm seni...

Demeye varmiyor dilim...

Uyandim bir aci rüzgar esiyordu disarda

Birseyler fisildiyor gibiydi kullagima...

''O gözlerini yumdu artik hayata''

''Son deminde sen yanindaydin korkma''

''Göremiyeceksin onu bir kez daha''

''Ama isyan etme bu yakismaz kullara''

... diyordu bana...

Son dilegi neydi biliyormusun sordugunda

Haykirmak istedim, bu olamaz, olamaz

Sen yalancisin dedim

Sonra usul usul sokulup esen rüzgari dinledim

''Mahsere kadar sürsün kendisi unutulmamakta''

''Adi hic düsmesin sevenlerin dilinden varsin anilmakta''

''Bitsin artik dökülen gözyaslar dinsin yerime aglanmamakta''

''O sadece sevdigimi bilsin herzaman kalbim yaninda olmakta''

Dilemis benden bunca yillar sonra...

20.06.00', 'Dün gece rüyamda gördüm seni... Demeye varmiyor dilim Perisan bir haldeydin Üzerinde eskimis bir pantolon Rengi solmus bir ceket Yirtilmis b...', ARRAY['Türk Edebiyatı','Şiir','Filiz Salihoğlu']::text[], 8.5, '{"poet":"Filiz Salihoğlu","poet_slug":"filiz-salihoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/dun-gece-ruyamda-gordum-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzün Soğuktur', 'yuzun-soguktur-onur-baki-3fts3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüzün soğuktur ,

Senin olduğun yerde açmaz ne gül ne çiçek

Ve sonsuzluktur ihtişamlı gözlerin,

Kaybeder canlılığını sana uzunan her renk

Bazen ayrılık acısından bezenler çalar kapını,

Bazen de şu hayat yolunda yalnız, perişan kalanlar,

Tek kurtuluş sayarlar da solgun dünyanı,

Silinir senin uğruna bir anda

Yaşanmış onca güzel anlar.', 'Yüzün soğuktur , Senin olduğun yerde açmaz ne gül ne çiçek Ve sonsuzluktur ihtişamlı gözlerin, Kaybeder canlılığını sana uzunan her renk Baz...', ARRAY['Türk Edebiyatı','Şiir','Onur Baki']::text[], 8.5, '{"poet":"Onur Baki","poet_slug":"onur-baki","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yuzun-soguktur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Turnaya', 'uc-turnaya-huseyin-cayikli-xega2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi turnalara 

metristen selam söyleyin

ölümü bekleniyor deyin

bir DENİZ yolunda

sevdası uçurum deyin Hüseyi''nin yolunda

Yusuf ''ada  bekle deyin

şafakla gelecek gökyüzü aydınlığına

Herşey özgürce olurdu darağcında

neydi sizden istedikleri 

fötür şapkalarında

bütün bunlarmıydı 

Gezmişi öldürmekmiydi

ne oldu sonunda

ağıt ağıt dediniz ağıdımızı yaktık

sevda sevda dediniz 

sevdamızı harcadık

isterseniz ölürüzde bu yolda...', 'Şimdi turnalara  metristen selam söyleyin ölümü bekleniyor deyin bir DENİZ yolunda sevdası uçurum deyin Hüseyi''nin yolunda Yusuf ''ada  bekle...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/uc-turnaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğin Günden Beri 1', 'gittigin-gunden-beri-1-huseyin-cayikli-3xkwq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gittiğin günden beri 

masada ekmek yok

camlar desen kirli

okul yolu sessiz

körfezde balık yok 

boş dönüyorum geceleri.

neden diye sordum kendime 

herşey bu kadarmıydı

güvercin 

her sabah ki gibi geliyor

sana ve hasrete dair gidiyor

kapı çalıyor 

bakıyorum

yine sen yoksun

aradan saatler geçmiş akşam olmuş

ben ben değilim

Rakı şişesine ya meze

yada balıklara yem olmuşum

akşama olunca balıkçılara gidiyorum

dertleşiyoruz onlar bana aşklarını yani denizi, maviyi anlatıyorlar

bende onlara seni anlatıyorum.

artık balıkta çıkmıyormuş sen gittiğinden beri.', 'gittiğin günden beri  masada ekmek yok camlar desen kirli okul yolu sessiz körfezde balık yok  boş dönüyorum geceleri. neden diye sordum ken...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gittigin-gunden-beri-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giderken 2', 'giderken-2-huseyin-cayikli-i9pio', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık bavullarımı topladım

burda ki eşyalarıda öyle bıraktım

yanıma almadım seni hatırlatmasınlar diye.

Şimdi gidiyorum,güle güle diyecek birisi yok

yalnızım boş yollardayım

tekrardan başka şehir dediğim yer

gidiyorum hoşçakal

artık sen yoksun ve olmayacaksın 

beni sakın arama çünkü artık 

bende olmayacağım burda.

yeni insanlar olacak kapımda ve ben olacağım orada

biliyormusun birdaha geçmeyeceğim kapından.

ve sana son sözüm,giderken

GİDEN YOLCUYA BAKMA AĞLATIR HER andığında', 'Artık bavullarımı topladım burda ki eşyalarıda öyle bıraktım yanıma almadım seni hatırlatmasınlar diye. Şimdi gidiyorum,güle güle diyecek bi...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/giderken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimizdeki Ses', 'i-cimizdeki-ses-alp-i-coz-lq10w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bizim gozyaslarimiz

Yagmurun sesidir…

Ciglik cigliga haykiran sesimiz

Caglayanin coskusudur.

Ofkemiz icimizde

Cakan simseklerdir.

Biz birer yagmur damlasiyiz

Topragi opunce baslar

Cocuklarimiz dogmaya…

Sabahin ilk isiklariyla 

Cicek acan cicekler oluverir

O icimizde alev alev yanan ates…

Bizim gozyaslarimiz

Icimizdeki o sessiz dunyadir!

O delicesine coskulu ve duygulu

Sessiz dunya!', 'Bizim gozyaslarimiz Yagmurun sesidir… Ciglik cigliga haykiran sesimiz Caglayanin coskusudur. Ofkemiz icimizde Cakan simseklerdir. Biz birer ...', ARRAY['Türk Edebiyatı','Şiir','Alp İçöz']::text[], 8.5, '{"poet":"Alp İçöz","poet_slug":"alp-i-coz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/icimizdeki-ses-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İse', 'i-se-cem-ozarna-794tx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uçsuz bucaksız, yaz kumsallarında,

Doludizgin koşmak,

Değdirmek kamçının ucunu ,kalbimin derinliklerine

Kumsallardaki denizin mavisi sen olsan,

Koya bakan doğanın yeşili benim kollarım,

İsterdimki uzansın denizin taşkınlığı ,

Kucaklasın doğamı..', 'Uçsuz bucaksız, yaz kumsallarında, Doludizgin koşmak, Değdirmek kamçının ucunu ,kalbimin derinliklerine Kumsallardaki denizin mavisi sen ols...', ARRAY['Türk Edebiyatı','Şiir','Cem Özarna']::text[], 8.5, '{"poet":"Cem Özarna","poet_slug":"cem-ozarna","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ise-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-lutfi-cetintepe-7qaox', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sendeki yeşil gözleri

Bahardaki yeşiller kıskanır

Sakın ha onlara 

Seni çok seven biri olduğunu söyleme

Söylersen 

Seni daha çok kıskanırlar

Kıskanırlar da 

Senden öç almak isterler 

Ve birgün öç alırlar

O zaman

Utanmaz mı güneşler sensiz doğmaktan

Utanmaz mı çiçeğe can veren su

Utanmaz mı bütün güzellikler

Sen olmadan güzel sayılmaktan

Utanır elbet

Utanır da

Yediremezler gururlarına

Seninle birlikte

Onlarda can verirler', 'Sendeki yeşil gözleri Bahardaki yeşiller kıskanır Sakın ha onlara  Seni çok seven biri olduğunu söyleme Söylersen  Seni daha çok kıskanırlar...', ARRAY['Türk Edebiyatı','Şiir','Lütfi Çetintepe']::text[], 8.5, '{"poet":"Lütfi Çetintepe","poet_slug":"lutfi-cetintepe","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sensiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittim, Sevdim ve Döndüm', 'gittim-sevdim-ve-dondum-cem-salih-un-g8a1q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gittim;

Yabancı bir hasret kaldı yaşanmışlıklardan

Koca bir şehir bıraktım geride

Birde dönüş için bir parça yürek

Ürkek ve yalnızdım geçmişini bilmediğim sokaklarda

Beni çeken birşeyler vardı yine

Sanki herşey biranda bitecek gibiydi

Dönerim diyordum, yüreğime güvenerek 

Sonra bir haziran bir ihanet

Gittim

Anı oldu her yaşanmışlık

Hepsini geçmişini bilmediğim sokaklarda kaybettim

Sevdim;

Duvarda bir fotoğraf ağlıyordu

Eksik bir yürekle baktım ona

Kalabalık oluyordu bazen meydanlar

Eski bir coşku kaplıyordu dingin bedenleri 

Bir parça coşku sürdüm yaralarıma

İçimde dağıldı bütün yürüyüşler

Sonra yine yalnızdı

Ekmeğinde bölünecek yeri kalmayanalar

İçimdeki coşkudan vermek isterdim onlara

Ama başkaydı yaraları, kapanacak gibi değildi

İnce bir gülümsemeyle örtüp yüzümü ağladım sadece

Bir kavgada inat edenleri sevdim ben

Ekmneğini bölemediğinden yüreği bölünenleri

Alıp coşkuma koydum hepsini

Sevgimi sende topladım sonra

Seni sevdim

Dağılmak bilmeyen bir yürüyüş gibiydin içimde

Döndüm;

Bir yürüyüş günü coşkumu toplayıp döndüm

Faili haziran bir yürek duruyordu

Bir şehri bıraktığım yerde

Sürgün edilmiş zamanlarda buluştuk dostlarla

Bir yürek gibi atmayalı çok oldu

Bir solukta içime çektim bakışlarını

Sonra bir veda sahnesinde 

Başka bir ayrılık sonuna gün kestik

Başka başka yollara vururken ömrümüzü

Anladımki çok geçti artık dönüşler için

Şimdi sürgün edilmiş bütün zamanları toplayıp

Gün biriktiriyorum, gitmek için', 'Gittim; Yabancı bir hasret kaldı yaşanmışlıklardan Koca bir şehir bıraktım geride Birde dönüş için bir parça yürek Ürkek ve yalnızdım geçmiş...', ARRAY['Türk Edebiyatı','Şiir','Cem Salih Ün']::text[], 8.5, '{"poet":"Cem Salih Ün","poet_slug":"cem-salih-un","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/gittim-sevdim-ve-dondum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Tanıklığı II', 'gece-tanikligi-ii-salih-bolat-8q4we', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'her taş yürümek istiyor, baksana 

anımsamak istiyor kül, ateşin başlangıcını 

yeşermek istiyor kan, gecenin kollarında 

gülmek istiyor ölüler, baksana. 

eşilmiş toprak, bulunmuş tohum, küf 

kim anlatabilir ki hüznün mesafesini 

dağ öyle durmuşsa, bir bildiği olmalı 

bir bildiği olmalı, deniz çıldırmışsa 

şu yalnızlık, şu aşk, şu ölüm 

geceyi deliyor kuşun soluğu, baksana', 'her taş yürümek istiyor, baksana  anımsamak istiyor kül, ateşin başlangıcını  yeşermek istiyor kan, gecenin kollarında  gülmek istiyor ölüle...', ARRAY['Türk Edebiyatı','Şiir','Salih Bolat']::text[], 8.5, '{"poet":"Salih Bolat","poet_slug":"salih-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gece-tanikligi-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Tanıklığı XXVII', 'gece-tanikligi-xxvii-salih-bolat-0zri3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gecikmiş karla döküldüğünde ağaçların sırı

çekildiğinde fırtınanın elimizden aldığı deniz

gecenin saldırısına uğramış bir kıyı kaldığında

kendini hangi ışıkla sınayacak ölüler kelebeği,

nasıl bakacak anıların aşındırdığı aynaya

anılar ki şimdi penceresinde uyuyan kedilerdir

ağaçlı bir yolda tek başına yürüyen bir kadının', 'gecikmiş karla döküldüğünde ağaçların sırı çekildiğinde fırtınanın elimizden aldığı deniz gecenin saldırısına uğramış bir kıyı kaldığında ke...', ARRAY['Türk Edebiyatı','Şiir','Salih Bolat']::text[], 8.5, '{"poet":"Salih Bolat","poet_slug":"salih-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gece-tanikligi-xxvii-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leyla', 'leyla-muhsin-i-lyas-subasi-pugke', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönlümdeki bulutlar,

Dökerken göz yaşını,

İçimde ırmak olup

Sana taşıyor leyla.

Aynaların kalbine

Hapsolan güzelliğin,

Beni, benden koparıp

Sende coşuyor Leyla.

Gurbet türküleriyle

Bana zulmeden hasret,

Düşlerimde uyanıp

Sana koşuyor Leyla.

Rabbım hilkat gününde

Vadettiği  cemali,

Niçin bende değil de,

Sende yaşıyor Leyla?..', 'Gönlümdeki bulutlar, Dökerken göz yaşını, İçimde ırmak olup Sana taşıyor leyla. Aynaların kalbine Hapsolan güzelliğin, Beni, benden koparıp ...', ARRAY['Türk Edebiyatı','Şiir','Muhsin İlyas Subaşı']::text[], 8.5, '{"poet":"Muhsin İlyas Subaşı","poet_slug":"muhsin-i-lyas-subasi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/leyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülün Olayım', 'gulun-olayim-muhsin-i-lyas-subasi-eni1t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostluğa uzanan elin olayım,

Sevgiyi anlatan dilin olayım,

Bahçende yetiştir besle, büyüt de,

Yakana takılan gülün olayım', 'Dostluğa uzanan elin olayım, Sevgiyi anlatan dilin olayım, Bahçende yetiştir besle, büyüt de, Yakana takılan gülün olayım...', ARRAY['Türk Edebiyatı','Şiir','Muhsin İlyas Subaşı']::text[], 8.5, '{"poet":"Muhsin İlyas Subaşı","poet_slug":"muhsin-i-lyas-subasi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gulun-olayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Sen', 'sen-ve-sen-beyazit-cenan-mz3la', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sen varsın 

Birde bendeki sen

Sen her gidişinde

Ben senle başbaşayım

Sen hiç senle kaldın mı

Ben hep seninleyim

Sen hiç yalnız kaldın mı

Ben yalnız seninleyim', 'Bir sen varsın  Birde bendeki sen Sen her gidişinde Ben senle başbaşayım Sen hiç senle kaldın mı Ben hep seninleyim Sen hiç yalnız kaldın mı...', ARRAY['Türk Edebiyatı','Şiir','Beyazıt Cenan']::text[], 8.5, '{"poet":"Beyazıt Cenan","poet_slug":"beyazit-cenan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tac - Mahal', 'tac-mahal-unal-tayfur-3em3z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hatırana  diksem  Tac-Mahal  gibi  türbe,

Sen  Ercüment  Banu, bense Şah-ı Cihan.

Yokluğundu  ağaran  saçlar, yaşlar  gözünde  sürme,

Duysun  bizi  insanlık, ağlasın  bütün  cihan..', 'Hatırana  diksem  Tac-Mahal  gibi  türbe, Sen  Ercüment  Banu, bense Şah-ı Cihan. Yokluğundu  ağaran  saçlar, yaşlar  gözünde  sürme, Duysun...', ARRAY['Türk Edebiyatı','Şiir','Ünal Tayfur']::text[], 8.5, '{"poet":"Ünal Tayfur","poet_slug":"unal-tayfur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tac-mahal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karlar Ülkesinde Çocuk', 'karlar-ulkesinde-cocuk-ridvan-memi-dyq9f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'karlar yağan ülkede bir anne

elindeki güller ile her akşam

çocuğunun kalbine vurur 

çocuk ağlar gözlerinde kan

karlar ülkesinde çocuk her gece

taştan yorganlara sarılır düşler kurar

bir anne... elleri güller kokan

ve bir çocuk... üstünde ipekten fısıltılar', 'karlar yağan ülkede bir anne elindeki güller ile her akşam çocuğunun kalbine vurur  çocuk ağlar gözlerinde kan karlar ülkesinde çocuk her ge...', ARRAY['Türk Edebiyatı','Şiir','Rıdvan Memi']::text[], 8.5, '{"poet":"Rıdvan Memi","poet_slug":"ridvan-memi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/karlar-ulkesinde-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğinde Tut Beni', 'yureginde-tut-beni-unal-tayfur-p9m6r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu türkünün güftesinde senin hüznün rakseder,

Nice gönül cemresine bin umutla serpildin.

İçimdeki tunç yeleli atlar gönlüne  gider,

Beni çarmıha germedin, kırk canlı güle dildin,

Sevmek bir umutsa eğer, kurtar beni, at beni,

Düşüyorum, düşüyorum yüreğinde tut beni.

Kendi içine kapanmış bir umudun feryadı,

Heyecanlarını saklar en mahrem kuytularda.

Melaline kahır yükler kumruların kanadı,

Arzuların çiçeklere sevdalı bu bahar da,

Onların engin hazzında kokla beni, tat beni,

Düşüyorum, düşüyorum yüreğinde tut beni.

Gözlerin ifşa ederken, dudakların sır saklar,

Sular ırmakta yıkanır, yanağında boyanır.

Kucağında köpüklerin dili yok, feryadı var,

Acıların etrafında bir uyur, bir uyanır,

Artık kendine taşı da macerana kat beni,

Düşüyorum, düşüyorum, yüreğinde tut beni.', 'Bu türkünün güftesinde senin hüznün rakseder, Nice gönül cemresine bin umutla serpildin. İçimdeki tunç yeleli atlar gönlüne  gider, Beni çar...', ARRAY['Türk Edebiyatı','Şiir','Ünal Tayfur']::text[], 8.5, '{"poet":"Ünal Tayfur","poet_slug":"unal-tayfur","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yureginde-tut-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiyacım Yok', 'i-htiyacim-yok-simge-atakan-rvj3p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eskisi gibiyim  ama sevmiyorum seni artık

çaresizlikler artık vurmuyor yüreğimden 

çok bitkinim  ama ihtiyacım yok sana 

dinleme artık beni

çünkü bende dinlemeyeceğim bundan sonra seni 

engeler engel değil artık 

özlemler bende yok

hasretler biittii 

dinleme artık beni 

çünkü bende dinlemeyeceğim bundan sonra seni 

yalnızlıklar unuttu beni artık mutsuzluklar terkketti 

tadım tuzum kalmadı ama

ihtiyacım yok sana 

dinleme artık beni 

çünkü bende dinlemeyeceğim bundan sonra aşkı sevgiyi ve seni', 'Eskisi gibiyim  ama sevmiyorum seni artık çaresizlikler artık vurmuyor yüreğimden  çok bitkinim  ama ihtiyacım yok sana  dinleme artık beni ...', ARRAY['Türk Edebiyatı','Şiir','Simge Atakan']::text[], 8.5, '{"poet":"Simge Atakan","poet_slug":"simge-atakan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ihtiyacim-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmekten İnan Hiç Pişman Olmadım', 'seni-sevmekten-i-nan-hic-pisman-olmadim-bilal-celik-6dyi7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni inan çok sevdim, 

Ve bundan da pişman değilim.

Gün oldu gittin uzaklara

Ben kendime yenildim.

Geceler boyu seninleydi ruhum,

Uykular haram oldu gecelerime.

Sana yenilmedim, sensiz yenilmedim.

Kendimi harcadım gecelerimle

Ve şiirlerimle seni yaşadım.

Gün oldu, yoluna düştü bedenim.

Kilometreleri saatleri aştım senin için.

Sana geldim.

Geri dönüşü olmayan yollardaydın

Ben seni aradım günlerce, gecelerce.

Bulunca seni bir öptüm,

sonra bir kurşun sıktın alnıma.

Beynime saplandı kaldı.

Ölmedim. 

Onunla yaşadım,

Zaman oldu canım yandı, seni hatırladım

Unutmadım.

şiirlerimden çıkaramadım seni.

Yoktun, bak bu yalan.

Benimleydin her zaman.

Sendin şiirlerimde yazan sevgili!

Hep sendin.

Bir an oldu bıktım seni sevmekten.

Aldattım seni, pişmanda değilim.

Konstantinapolis gibi güzeldin, senindim.

Ve pişman değildim.

Hasretin ekmeğim oldu, suyum oldu.

Yandım, kana kana hasretini içirdin bana.

Haketmedim.

Bütün bu yaşananlara, tüm yalanlara rağmen

Direndim, ölmedim.

Seni bekledi gözyaşlarım ve boşaydı yakarışlarım.

Gelmedin.

Bilirsin ben ilk seni bildim, seni gördüm, seni sevdim.

Ve pişman da değilim.

Gözlerim yoruldu yollarına bakmaktan

Yoruldum seni aramaktan deli divane.

Yollarım yıllarım oldun,

Yarınlarımı senin yaptım, pişman da değilim.

Bundan sonraki yıllar da senin olsun.

Haram olsun günler bana sensiz ve geceler.

Gözlerinin karanlığı düştü saaatlere, gecelerime.

yarasalar emdi kanımı, 

kurtaranım yoktu, bitkindim

Hayatımı harcadım aşkına ve şiirlere, pişman da değilim.

Çok zaman oldu yalnızım!

Adaletin bu senin, biliyorum.

Ve artık gelmeni de beklemiyorum.

Gelmeyeceksin çünkü, biliyorum artık.

Bunca zamandır bilmiyorum seni

Bilmiyorum ne alemdesin, kiminlesin?

Uzaksın bedenimden, ruhumdan değil.

Pişman değilim sensizliğimden

Ben hiç pişman olmadım ki zaten.

Hiç bitmez sanırız bu hayat, sonsuz gibi gelir.

Ne zaman ki aynadaki yüz yorulur.

Ve biz olmayız o yüz.

O zaman anlarız ki bu son demdir.

Bir yudum daha almak isteriz hayattan, beceremeyiz.

Bir acı sarıverir o zaman bedeni

Dayanılmaz olur yalnızlığımız.

Eller o eller değil, saçlar o saçlar değil.

Kimin bu takatsiz dizler.

Anlarız ki, ömür çizgisinin sonundayız biz.

Ve bir film şeridi olur yaşanmışlar.

Beğenilmeyenleri makasla kesemeyiz.

Bir yerde olur ya 

Keşke dersek -ki mutlaka deriz-

O gün çok geçtir pişman olmak için

Ve sevmek için.

Pişmanlık sadece bir avuntudur o zaman

Evet çiçeğim,

Bu sabah aynadaki yüz ben değildim,

Ve inan bana sonbaharım

Senin sevdiğim için,

Hala pişman değilim.', 'Seni inan çok sevdim,  Ve bundan da pişman değilim. Gün oldu gittin uzaklara Ben kendime yenildim. Geceler boyu seninleydi ruhum, Uykular ha...', ARRAY['Türk Edebiyatı','Şiir','Bilal Çelik']::text[], 8.5, '{"poet":"Bilal Çelik","poet_slug":"bilal-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/seni-sevmekten-inan-hic-pisman-olmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Aşkım Ve ...', 'i-lk-askim-ve-bilal-celik-eh75y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Derdim çok anlayan yok

Dostlarım var dinleyen yok

Bir sevdaya düştüm sonu yok

Sevdim bir kara gözlü yari bilen yok

Düşler kurdum her gece

Onu düşündüm günlerce

Onu düşündüm sevdikçe

O beni düşünmese, Sevmese de

Bir aşk ateşine düştüm

Günlerce aşkınla yandım

Umutla tutuştum kahroldum

Aşkımla alevlendim, Kor oldum

Tek isteğim anlaması

Tek isteğim yanımda olması

Tek isteğim benim olması

Beni sevmesi, Benimle aşk alevinde yanması', 'Derdim çok anlayan yok Dostlarım var dinleyen yok Bir sevdaya düştüm sonu yok Sevdim bir kara gözlü yari bilen yok Düşler kurdum her gece On...', ARRAY['Türk Edebiyatı','Şiir','Bilal Çelik']::text[], 8.5, '{"poet":"Bilal Çelik","poet_slug":"bilal-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ilk-askim-ve-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hıçkırıklar', 'hickiriklar-bilal-celik-3jger', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saatler bitmiyor; yapayalnızım                                          Gülmek istiyorum, gülemiyorum                                              Sensiz olmak midir hep alin yazım                                  Bilmek istiyorum, bilemiyorum                                                Esirgedin nazlı, hilal kaşını                                                  Harap ettin çiçek kokan başını                                        Yüreğime akan gözüm yasini                                                 Silmek istiyorum, silemiyorum                                                   Sanki her şey efsaneydi, masaldı                                      Ayrılık ruhumu elimden aldı                                                          Gözlerim yollara takılıp kaldı                                                   Gelmek istiyorum, gelemiyorum                                              Göğüs germek için acılarıma                                             Titreyişlerime sancılarıma                                                       Seni bir kez olsun avuçlarıma                                                 Almak istiyorum, alamıyorum                                                 Saçılan bir köpük olmak dilinde                                                Boğulmak saçının ince telinde                                                  Sır gibi sonsuza değil kalbinde                                         Kalmak istiyorum, kalamıyorum                                        Unutuyor beni sırlı gözlerin                                                      İçimde bir yara isliyor, derin                                              Kulakların, dudakların, ellerin                                                  Olmak istiyorum, olamıyorum                                              Bölerek uykunu, rüyalarına                                                           O kucak dolusu hülyalarına                                                        Gece gündüz uçup aynalarına                                                     Konmak istiyorum, konamıyorum                                             Deli gibi aşık olsa da güle                                                          Kim acır çöllerde öten bülbüle                                                   Bir gün alev alev yanıpta küle                                                   Dönmek istiyorum, dönemiyorum                                          Hıçkıra hıçkıra ağlamaktansa                                                     Başına karalar bağlamaktansa                                                    Bu yüreği her gün dağlamaktansa                                              Ölmek istiyorum, ölemiyorum', 'Saatler bitmiyor; yapayalnızım                                          Gülmek istiyorum, gülemiyorum                                       ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Çelik']::text[], 8.5, '{"poet":"Bilal Çelik","poet_slug":"bilal-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/hickiriklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Akşam Üstü ...', 'bir-aksam-ustu-bilal-celik-0jo9g', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ilık bir rüzgar esiyor dudaklarından dudaklarıma...

Oysa kış ortasındayız daha

Ve ılık akşamlara daha var sevdiğim...

İşte ben bir ırmağın deltasında seni soluyorum...

Nefes oluyorsun uykusuz gecelerime

Ve tükürüp ayrılığın yüzüne şafağa adımlayacağım seni...

Ve dolanacak boynuma sevda

Ellerine tutunacağım

Ne zaman uçurum olsa çıkmaz sokaklar

Ben ellerine uzanacağım', 'Ilık bir rüzgar esiyor dudaklarından dudaklarıma... Oysa kış ortasındayız daha Ve ılık akşamlara daha var sevdiğim... İşte ben bir ırmağın d...', ARRAY['Türk Edebiyatı','Şiir','Bilal Çelik']::text[], 8.5, '{"poet":"Bilal Çelik","poet_slug":"bilal-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-aksam-ustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Bu Delikanlı ?', 'kim-bu-delikanli-bilal-celik-2awgl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sokaklar gülüm,İstanbul''da sokaklar...

ayaklarını bekleyemeyecek belki bir daha..

Aşkı en narin yerinden çiğnediğin için...

Nevroz''da sokaklara çıkma sakın...

Ayakların 3000 yıl öncesine gider...

Ve çiğnenirse aşklar en narin yerinden

Bilki Nevrozda kendini yakar gelinler..

Ve kızlar ağıt yakar ,gül tenine dokunmadan

Bu acıya dayanabilirmisin?

Alıp götürseler seni 3000 yıl öncesine

Çadırda oturan bir ışıktır kadın

Bilge gözleriyle bakar güzel yüzüne

Belki de çatar kaşlarını,kim bu delikanlı...?

...', 'Sokaklar gülüm,İstanbul''da sokaklar... ayaklarını bekleyemeyecek belki bir daha.. Aşkı en narin yerinden çiğnediğin için... Nevroz''da sokakl...', ARRAY['Türk Edebiyatı','Şiir','Bilal Çelik']::text[], 8.5, '{"poet":"Bilal Çelik","poet_slug":"bilal-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kim-bu-delikanli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutulmuş Biri', 'unutulmus-biri-bilal-celik-xkvdu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yanımdan geçtin dün tanıyamadın

Boş gözlerle baktın konuşamadın

Unutmam diyordun hatırlamadın

Demekki beni unutmuşsun sen

Giderken ardımdan ağlayan sendin

Kolunu boynuma bağlayan sendin

''Ne olur unutma!'' diyen hep sendin

Demekki birçok şeyi unutmuşsun sen

Gördüm ki ne varsa artık değişmiş

Bana olan aşkın gerçek değilmiş

Mektubum yırtılmış,resmim yakılmış

Demekki herşeyi unutmuşsun sen', 'Yanımdan geçtin dün tanıyamadın Boş gözlerle baktın konuşamadın Unutmam diyordun hatırlamadın Demekki beni unutmuşsun sen Giderken ardımdan ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Çelik']::text[], 8.5, '{"poet":"Bilal Çelik","poet_slug":"bilal-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutulmus-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İntikam', 'i-ntikam-bilal-celik-ttl0b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ardında hiç iz bırakma

Gittiğin bile anlaşılmasın

Tekrar canımı yakma

Sonra seninki de yanmasın

Vefasız olduğun belli 

Hala yüreğim yanıyor

İntikamım tek teselli

Aşkım kine dönüşüyor

Sanmaki sana acırlar

Ben gibi olduğun zaman

Seni alaya alırlar

Seviyorum dediğin an

Affımı çok beklersin

Sende benim gibi yan

Tekrar sevmemi istersin

Sende yalanlarına kan', 'Ardında hiç iz bırakma Gittiğin bile anlaşılmasın Tekrar canımı yakma Sonra seninki de yanmasın Vefasız olduğun belli  Hala yüreğim yanıyor ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Çelik']::text[], 8.5, '{"poet":"Bilal Çelik","poet_slug":"bilal-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/intikam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışacağım', 'alisacagim-bilal-celik-c6jyq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adın düşmesede benim dilimden

Seni unutmaya çalışacağım

Kalbim titresede hep hasretinle

Sensiz yaşamaya çalışacağım

Kolay olmayacak seni unutmak

Belki gündüz gece ağlayacağım

Ne olursa olsun artık sevdiğim

Sensiz yaşamaya alışacağım

Dönmeyeceksin

Artık sana şarkılar yazıp ağlamıyorum

Rüyalarda fallarda seni aramıyorum

Yüzüm avuçlarımda yollara bakmıyorum

Biliyorum bir daha dönmeyeceksin

Aşkımı nefes nefes rüzgara savurdum

Sensiz doğup batan güneşe darıldım

Bir öksüz gibi sensiz yapayalnız kaldım

Biliyorum bir daha dönmeyeceksin', 'Adın düşmesede benim dilimden Seni unutmaya çalışacağım Kalbim titresede hep hasretinle Sensiz yaşamaya çalışacağım Kolay olmayacak seni unu...', ARRAY['Türk Edebiyatı','Şiir','Bilal Çelik']::text[], 8.5, '{"poet":"Bilal Çelik","poet_slug":"bilal-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/alisacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamadım', 'unutamadim-bilal-celik-kn81e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaç kadeh kırıldı sarhoş gönlümde

Bir türlü kendimi avutamadım

Kaç gece ağladım böyle gizlice

Ne yaptımsa seni unutamadım

Kim bilir kimler var şimdi kalbinde

Sen beni unuttun çoktan belkide

Yer yokmuş bana senin sevginde

Ama ne yaptımsa seni unutamadım

Aşkımı nefes nefes rüzgara savurdum

Sensiz doğup batan güneşe darıldım

Bir öksüz gibi sensiz yapayalnız kaldım

Biliyorum bir daha dönmeyeceksin', 'Kaç kadeh kırıldı sarhoş gönlümde Bir türlü kendimi avutamadım Kaç gece ağladım böyle gizlice Ne yaptımsa seni unutamadım Kim bilir kimler v...', ARRAY['Türk Edebiyatı','Şiir','Bilal Çelik']::text[], 8.5, '{"poet":"Bilal Çelik","poet_slug":"bilal-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hilal Kaşlım', 'hilal-kaslim-can-cizmecioglu-upw5c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hilal Kaşlım

Okul Aşkım

Senden Küsünce Şaştım

Yeter Artık Barışalım.

Gel Dedim Gelmedin

Sen Beni Deli Eyledin

Hilal Kaşlım 

Okul Aşkım.', 'Hilal Kaşlım Okul Aşkım Senden Küsünce Şaştım Yeter Artık Barışalım. Gel Dedim Gelmedin Sen Beni Deli Eyledin Hilal Kaşlım  Okul Aşkım....', ARRAY['Türk Edebiyatı','Şiir','Can Çizmecioğlu']::text[], 8.5, '{"poet":"Can Çizmecioğlu","poet_slug":"can-cizmecioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hilal-kaslim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sözlerim Yalan Olsa da', 'sozlerim-yalan-olsa-da-ozer-bal-hc0xe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sözlerim yalan olsa da

söze gelmez ama

düşlerim değil

adına düşler kurmayalı

inan hiç bir şey 

eskisi gibi değil.', 'Sözlerim yalan olsa da söze gelmez ama düşlerim değil adına düşler kurmayalı inan hiç bir şey  eskisi gibi değil....', ARRAY['Türk Edebiyatı','Şiir','Özer Bal']::text[], 8.5, '{"poet":"Özer Bal","poet_slug":"ozer-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sozlerim-yalan-olsa-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce Sözcükler Arıyorum Geceler Boyu Kırılganım', 'i-nce-sozcukler-ariyorum-geceler-boyu-kirilganim-ozer-bal-v5puj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İnce sözcükler arıyorum geceler boyu-kırılganım

koynunda unuttum herşeyi-unutkanım

sevmedim desem yalan

öyle bakma alınganım.', 'İnce sözcükler arıyorum geceler boyu-kırılganım koynunda unuttum herşeyi-unutkanım sevmedim desem yalan öyle bakma alınganım....', ARRAY['Türk Edebiyatı','Şiir','Özer Bal']::text[], 8.5, '{"poet":"Özer Bal","poet_slug":"ozer-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ince-sozcukler-ariyorum-geceler-boyu-kirilganim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çingenem', 'cingenem-cagri-duman-q08qy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çingenem, gözler siyah saçlar belde

Kadıköy''de akşam ve sessiz iskele

Yaralı asker merhem beklemede

Gözleri kapanacak sensiz, soğuk gecede

Çingenem, gözler siyah saçlar belde

İklim yaz bahar bitmiş

Yağmaz olmuş yağmur , deniz sessiz

Çingenem etrafımı kapladı bir sis

Dünyadaki herkes kifayetsiz

İklim yaz bahar bitmiş

Ne olur dur köşende

Attığın her adım beni öldürmede

Kağıt kalem bir tek hece

Yazdığım her şiir bilmece

Ne olur  dur köşende

Güller var beyaz pembe

İkisi de ayrılık sende bende

Gökkuşağı gibi pencerende

Durmak isterdim çingenem

Güller var beyaz pembe

Elbisen ne güzel çingenem

Ama bana süslenmedin ki sen

Bana bakıp bir gülsen

Neyse boşver

Elbisen ne güzel çingenem

Nesiller vardı aşk görmüş

Sevgi görmüş, tat almış

Ben bu treni çoktan kaçırdım

Tek tesellim göz yaşlarım

Nesiller vardı aşk görmüş

Elleme göz yaşlarıma, çek ellerini

Boşa akmıyor onlar sebebi belli

Bedenimdeki alev sönmedi

Boşa yanmıyor o ateş çingenem

Elleme göz yaşlarıma çek ellerini

Merak eyleme beni çingenem

Sen mutlu ol yeter

Ben değil miydim gerçek aşkı isteyen

Aşk dediğin seni düşünmektir

Merak eyleme beni çingenem...', 'Çingenem, gözler siyah saçlar belde Kadıköy''de akşam ve sessiz iskele Yaralı asker merhem beklemede Gözleri kapanacak sensiz, soğuk gecede Ç...', ARRAY['Türk Edebiyatı','Şiir','Çağrı Duman']::text[], 8.5, '{"poet":"Çağrı Duman","poet_slug":"cagri-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/cingenem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilhun', 'dilhun-ekrem-kaftan-kd7aj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nerde bir Elif görsem yer açarım sinemde

Zira hepsi yârimin endâmını anlatır

Yeni Elifler büyür gözümdeki her nemde

Ve yazılır sineme bu sevda satır satır

Habîb''in Mirac''daki yolu kadar uzundur

Kalbimde büyüttüğüm Elif''imin endâmı

Bu yüzden halk içinde benim adım dilhundur

Biter mi bu sevdanın bir lahza olsun gâmı

( 5 Haziran 2000 )', 'Nerde bir Elif görsem yer açarım sinemde Zira hepsi yârimin endâmını anlatır Yeni Elifler büyür gözümdeki her nemde Ve yazılır sineme bu sev...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Kaftan']::text[], 8.5, '{"poet":"Ekrem Kaftan","poet_slug":"ekrem-kaftan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dilhun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elif''in Sevdası', 'elif-in-sevdasi-ekrem-kaftan-3boss', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zülfesinden dökülen iksiri içtiğim an,

Anladım sevdasını kıyamdaki Elif’in.

Kaç bin melek Elif’çe kıyamdadır göklerde

Kaç bin Elif koruyor, gökleri devrilmekten

Bir Elif etrafında dönüyor cümle âlem

Ve Elif’ler yazıyor, yaralı nice kalem

Dağların hayalinde Elif’çe durmak vardır

Kuşların aradığı Elif’in zülfesidir

Serviler Elif’çe bir teslimiyet içinde

Eğilir rûzigârın mest eden huzurunda

Balıklar deryalarda kayıp Elif’ler arar

Dalgaların arzusu Elif’çe yükselmektir

Mücerred Elif idi Mecnûn’un aradığı

Elif’i sinesine batırıp yandı Leylâ

Fuzûlî’nin gözünden akan yaş Elif oldu

Elif Elif yükseldi gönüllerden vâveylâ

Saf saf oldu şiirler huzurunda Elif’in

Bâkî’nin musallâda son gördüğü Elif’di

Sen ki Elif yazansın, boyunca güzel olan,

Zülfesi zülfün gibi, sevdalar tutuşturan…

Bir kere “âh” yazanda, yıldızları yandıran,

Cennette her hûrinin gıbta ile andığı

Ve Elif’i yaratan Rabbimin nimetisin

Seni kanlı sineme Elif diye çekeyim…

Kaç Elif mikdârınca haykırayım sevdiğim

Gönlümde ummanlarca büyüyen bu sevdamı…

Bir “He” gibi kıvrılıp, seyretsem endamını…

Beraber bir “âh” olup yükselsek ötelere,

Bilmem ki, bu sevdayı anlatmış olur muyuz,

Kıyamette huzura çıktığımız vakitte…', 'Zülfesinden dökülen iksiri içtiğim an, Anladım sevdasını kıyamdaki Elif’in. Kaç bin melek Elif’çe kıyamdadır göklerde Kaç bin Elif koruyor, ...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Kaftan']::text[], 8.5, '{"poet":"Ekrem Kaftan","poet_slug":"ekrem-kaftan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/elif-in-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halimden şikayetçi değilim', 'halimden-sikayetci-degilim-simge-atakan-3n7xx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben esmesini bilmeyen rüzgarım

Kim ne derse o yöne giderim

Sürüklenirim gecelerde bilinmedil yerlere

Ama halimden şikayetçi değilim işte

Ben yalnızca karanlıkla buluşan ay''ım

Sadece etrafımı aydınlatabilirim

Sabah olunca herşey biter benim için

Ama halimden şikayetçi değilim

Ben dört mevsimden kış''ım

Beyazı sevenlerle buluşurum günlerce

Bazen nefret edilirim belkide

Ama halimden şikayetçi değilim işte

Ben herzaman gülümsemesini bilirim

Mutluluk ve sevgi ağzımdan düşmez benim

Merak etmeyin zararım yok ben Simge''yim

Asla halinizden şikayet etmeyin...', 'Ben esmesini bilmeyen rüzgarım Kim ne derse o yöne giderim Sürüklenirim gecelerde bilinmedil yerlere Ama halimden şikayetçi değilim işte Ben...', ARRAY['Türk Edebiyatı','Şiir','Simge Atakan']::text[], 8.5, '{"poet":"Simge Atakan","poet_slug":"simge-atakan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/halimden-sikayetci-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karamsarlık', 'karamsarlik-simge-atakan-vbgqt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün yine hüzün doluyum

Daldan düşmüş bir yaprak kadar ince

Kırılmaya hazır yapayalnız tekbaşına

Bir köşede umutla bekliyorum...

Bugün yine ağlamaklı duygular içinde

Sevdiklerimden uzak kalmış

Yanında olanları çaktan kaybetmiş gözünde

Sonsuz sessizlikte soluklanıyorum

Bugün yine aynı yerde

Başka kişilik var bedenimde

Düşüncesiz ve sevgisiz çerçevemde

Yaklaşan ölümüme hazırlanıyorum', 'Bugün yine hüzün doluyum Daldan düşmüş bir yaprak kadar ince Kırılmaya hazır yapayalnız tekbaşına Bir köşede umutla bekliyorum... Bugün yine...', ARRAY['Türk Edebiyatı','Şiir','Simge Atakan']::text[], 8.5, '{"poet":"Simge Atakan","poet_slug":"simge-atakan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karamsarlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamıyorum', 'unutamiyorum-simge-atakan-4fmn3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Unutacağımı sandın değil mi?

Seni ve sana ait sevgimi.

Bunu nasıl düşünebildin,

Seni unutmak mümkün mü?

Elimde değil gözlerim dalıp gidiyor

Seni hatırlatıyor hüzünlü şarkılar

Senin için çarpan kalbimi

Söküp atamıyorum içimden bir türlü

Seni düşünüyorum durmadan

Geceleri yıldızlar içinde seni arıyorum

Özleminle yetiniyorum sadece

Unutamıyorum işte unutamıyorum!!!', 'Unutacağımı sandın değil mi? Seni ve sana ait sevgimi. Bunu nasıl düşünebildin, Seni unutmak mümkün mü? Elimde değil gözlerim dalıp gidiyor ...', ARRAY['Türk Edebiyatı','Şiir','Simge Atakan']::text[], 8.5, '{"poet":"Simge Atakan","poet_slug":"simge-atakan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutamiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusatma', 'kusatma-seref-eker-jum9u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duru ve sakin bir suyun kıyıcığında,

Kanadı kırık,

Ve hatta doyumsuzluğuna çekince koyulan

İleriye dönük,

Bildik,

Bir sevişmenin de içinde yer aldığı ,

Esrikleşen ve kimi zaman hantallaşan

Bedenin ve kederin dili 

Ve neyseki hiçbir zaman gücenmeyecek olan 

O amansız gülüşü,

Uyumak isteyip  - yorgunluktan değil ha-

Görmeyi özlediğimiz için o ironik düşü', 'Duru ve sakin bir suyun kıyıcığında, Kanadı kırık, Ve hatta doyumsuzluğuna çekince koyulan İleriye dönük, Bildik, Bir sevişmenin de içinde y...', ARRAY['Türk Edebiyatı','Şiir','Şeref Eker']::text[], 8.5, '{"poet":"Şeref Eker","poet_slug":"seref-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kusatma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hüzün Şarkışı (2)', 'bir-huzun-sarkisi-2-ekrem-kaftan-yg8g5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdânın neş''esini duyarken vedâ ettim

Kollarından çekilip ey sevgili ben sana.

Aşka hürmet borcumu böylece edâ ettim

Versem de binbir azâb inleyen iki cana

Düşün ki bûse yasak, zülüf yasak, göz yasak

Gözlerinde sönmeyen ateş yasak, köz yasak

“Hep seni seveceğim” diyeceğin söz yasak

Böyle yasak sevdâyı âlemde kimler an’a

Açalım gönlümüzü sevdâ görsün İstanbul

Gıbta etsin sevdâya onu gören nice kul

Gönlümde senin için gizlenen şi’re tutul

Dönmesin nihâyette bu sevdâ akan kana

Yâr için ölmek kolay ma’rifet gâm çekmektir

Önceki sevdâlara bir Elif, Lâm çekmektir

Her gece bûse diye binlerce câm çekmektir

Ererim vuslatına derinden yana yana', 'Sevdânın neş''esini duyarken vedâ ettim Kollarından çekilip ey sevgili ben sana. Aşka hürmet borcumu böylece edâ ettim Versem de binbir azâb ...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Kaftan']::text[], 8.5, '{"poet":"Ekrem Kaftan","poet_slug":"ekrem-kaftan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-huzun-sarkisi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-ekrem-kaftan-1qknk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nice bin yıldız yanan âsumânda yalnızım

Gemiler uğramayan her ummânda yalnızım

Baharlar gelip geçer çiçeklerin üstünden

Güllerde, sümbüllerde ve reyhânda yalnızım

Geceler gündüzlerin peşinden koşturur da

Bir dost gelmez yanıma bu meydânda yalnızım

Ümmetsiz nebilerin kaderini yaşarım

İbadette, tâatta ve imânda yalnızım

Gözgöze sevdalılar gelip geçer yâdımdan

Bir çift gözden mahrûmum ve zindânda yalnızım

Bahtiyar gezer Mecnun çöllerde ceylanlarla

Ben şehirler içinde her mekânda yalnızım

Düşmez kara bahtıma peri suret bir dilber

Sevâba muhtâc olsam o mîzânda yalnızım', 'Nice bin yıldız yanan âsumânda yalnızım Gemiler uğramayan her ummânda yalnızım Baharlar gelip geçer çiçeklerin üstünden Güllerde, sümbüllerd...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Kaftan']::text[], 8.5, '{"poet":"Ekrem Kaftan","poet_slug":"ekrem-kaftan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalnizim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yâre Mektub', 'y-re-mektub-ekrem-kaftan-mpyz4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sadece gözünü görseydim senin

Çekilmez kedere düşmezdim gülüm

Duymasam tadını yakan bûsenin

Zor gelmezdi bana ânî bir ölüm

Dersin ki terkedip kurtulmalıyım

Vuslatın lezzeti öldürür beni

Ölümsüz olmaya yol bulmalıyım

İstemem peşimden her an geleni

Yârin emri deyip hürmet ederim

Sana itâatin saâdeti vâr

Seni görmemeye gayret ederim

Yaksa da hicrânın büyüttüğü nâr

İnkârın ne kolay, geçen yılları

“Ben taze nihâlim” deyip ey gülüm

Bize saâdeti seçen yılları

“Unuttum ve lâl''im” deyip ey gülüm

Tarihin hükmü var yâr denilene

''Ne vefa bulunur, ne aşk dilberde

Beni bir kerecik sar denilene

Pek Elim bir azâb düşer mahşerde''

Kederim İstanbul için sevdiğim

Bir daha göremez böyle bir sevdâ

Şu yüce gönlümden gel in sevdiğim

Olsun bu mektubum sana bir vedâ

Halvet olduğumuz anlar avutur

Tamû kadar çetin yanan gönlümü

Belki senden güzel canlar avutur

Unutturur bana solmaz gülümü

Mektubum götürsün seni mâziye

Yâdındaki her an, ağlatsın gülüm

Bakmasın gözlerin yeni mâziye

Dikenin gönlünü kanatsın gülüm

Eslâf merhametli ve mahzûun idi

Yârine âh etmez, hep âh çekerdi

Gözü de gönlü de her dem hûn idi

Yâr için sayısız günâh çekerdi

Kıyâmet yakındır, devrân değişti 

Ayrılık ardından bin âh getirir

Yâr ile yaşanan hicrân değişti

Bir anlık adâvet aşkı bitirir

Derim ki sevgilim, ayrı düşersek

Ömrünce sarp dağlar üstünde sürün

Bu aşk gönlümüze kâr etmez dersek

Ak kefen yerine siyâhlar bürün

Öldürür âkıbet bu keder beni

Kabrimin üstünde bülbüller öter

Toprakta böcekler gelip yer beni

Cismim de gün görmez ve böyle biter

Sen mahrum kalasın kabirden bile

Toprağım üstünde kapanıp ağla

Düşürsün bu hâlin seni her dile

Zülfünü taşıma gül diye bağla

Çürüsün de cismin toprak üstünde

İdrak et verdiğin azâb nicedir

Olmasın ümidin bensiz düğünde

Nur olsun alnında sevdiğim Bedir', 'Sadece gözünü görseydim senin Çekilmez kedere düşmezdim gülüm Duymasam tadını yakan bûsenin Zor gelmezdi bana ânî bir ölüm Dersin ki terkedi...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Kaftan']::text[], 8.5, '{"poet":"Ekrem Kaftan","poet_slug":"ekrem-kaftan","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/yare-mektub-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuç', 'avuc-lutfi-i-hsan-yazici-t6x0m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Avuçlarımızla birlikte yüreğimizi de değdirdik kara toprağa

Doğurgan bir kadındı toprak

Bir tek aşkları yeşertmedi

Ve aşıkları

Her gece

Kuşlar boyuyorken gökyüzünü;

Buğulu bir sesin son hecesinde

Ve kıvrımlarında çatlamış dudaklarının

Beni oluveriyordum

Anlamsızlıklarımın

Küçük bir kız çocuğunun kokulu silgisiydi mutluluk

Ne hüzün gibi fahişeydi

Ne de ölüm kadar cömert davranmıştı bedenlerimize

Onu gören üç kişiydik

Ve sözleştik yüreklerimizle', 'Avuçlarımızla birlikte yüreğimizi de değdirdik kara toprağa Doğurgan bir kadındı toprak Bir tek aşkları yeşertmedi Ve aşıkları Her gece Kuşl...', ARRAY['Türk Edebiyatı','Şiir','Lütfi İhsan Yazıcı']::text[], 8.5, '{"poet":"Lütfi İhsan Yazıcı","poet_slug":"lutfi-i-hsan-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/avuc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ufuktaki İskele', 'ufuktaki-i-skele-gulnaz-oruc-pk8mb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İskelesiz bir denizdeyim şu an,

Boğuluyorum yok mu kurtaran?

Kimse duymuyor mu sesimi,

Buradayım işte benim o bağıran.

Karışıyor gözyaşlarım denize

Kaldım öyle çaresizlik içinde

Gözyaşlarım denizi,deniz beni ıslatıyor

Ve içimdeki hazine gittikçe batıyor.

Hemen pes etmek yok öyle 

Kurtulmak için uğraşmadın bile

Hadi biraz hızlı yüzsene

Galiba ufuktaki iskele...', 'İskelesiz bir denizdeyim şu an, Boğuluyorum yok mu kurtaran? Kimse duymuyor mu sesimi, Buradayım işte benim o bağıran. Karışıyor gözyaşlarım...', ARRAY['Türk Edebiyatı','Şiir','Gülnaz Oruç']::text[], 8.5, '{"poet":"Gülnaz Oruç","poet_slug":"gulnaz-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ufuktaki-iskele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğinde Tut Beni', 'yureginde-tut-beni-muhsin-i-lyas-subasi-w0aw9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu türkünün güftesinde senin hüznün rakseder,

Nice gönül cemresine bin umutlu serpildin.

İçimdeki tunç yeleli atlar gönlüne gider,

Beni çarmıha germedin, kırk canlı güle dildin.

Sevmek bir umutsa eğer, kurtar beni, at beni,

Düşüyorum, düşüyorum, yüreğinde tut beni.

Kendi içine kapanmış bir umudun feryadı,

Heyecanlarını saklar en mahrem kuytularda.

Melaline kahır yükler kumruların kanadı,

Arzuların çiçeklere sevdalı bu bahar da.

Onların engin hazzında kokla beni, tat beni,

Düşüyorum, düşüyorum, yüreğinde tut beni...

Gözlerin ifşa ederken dudakların sır saklar,

Sular ırmakta yıkanır, yanağında boyanır.

Kucağında köpüklerin dili yok, feryadı var,

Acıların etrafında bir uyur, bir uyanır.

Artık kendine taşı da  macerana kat beni,

Düşüyorum, düşüyorum, yüreğinde tut beni.', 'Bu türkünün güftesinde senin hüznün rakseder, Nice gönül cemresine bin umutlu serpildin. İçimdeki tunç yeleli atlar gönlüne gider, Beni çarm...', ARRAY['Türk Edebiyatı','Şiir','Muhsin İlyas Subaşı']::text[], 8.5, '{"poet":"Muhsin İlyas Subaşı","poet_slug":"muhsin-i-lyas-subasi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yureginde-tut-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kerem', 'kerem-muhsin-i-lyas-subasi-3w9f3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu yıldızlar iyi tanır Kerem''i,

Kaç geceyi birlikte bölüştüler.

Bu sokaklar iyi tanır Kerem''i,

Nice sabahlara yorgun düştüler.

Kerem, bu toprağın aşkta nefesi,

Kerem, külündeki hasretin sesi,

Kerem, Aslıhan''ın en saf bestesi,

Kaç türküyle gönlümüzde piştiler!..', 'Bu yıldızlar iyi tanır Kerem''i, Kaç geceyi birlikte bölüştüler. Bu sokaklar iyi tanır Kerem''i, Nice sabahlara yorgun düştüler. Kerem, bu top...', ARRAY['Türk Edebiyatı','Şiir','Muhsin İlyas Subaşı']::text[], 8.5, '{"poet":"Muhsin İlyas Subaşı","poet_slug":"muhsin-i-lyas-subasi","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kerem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Döngüsü', 'ask-dongusu-cemal-tekmen-jh343', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duyarsızca yaşanmış aşklara..

Karanlığın geceyi giydiyi anda,

Seni sayıklayarak attığım her adımda,

Yine o ilk anki gibi;heyecanla,

Seninle yaşayacağım seni yaşayacağım.

Sensiz geçecek yine günlerim,gecelerim.

Zaman geçsede yine benim,ben benim...

Sen olmasanda yanımda;

Seni yaşatacak hayallerim...', 'Duyarsızca yaşanmış aşklara.. Karanlığın geceyi giydiyi anda, Seni sayıklayarak attığım her adımda, Yine o ilk anki gibi;heyecanla, Seninle ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Tekmen']::text[], 8.5, '{"poet":"Cemal Tekmen","poet_slug":"cemal-tekmen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ask-dongusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkma Sıcaklığında Ölmem', 'korkma-sicakliginda-olmem-muhsin-i-lyas-subasi-d259s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aşkın gözlerine hapsolduğun günden beri,

Ben seni yürek yangını bir vahada ararım.

Ararım serabın aldattığı ufuklar içinde,

Bulmam mümkün mü, bilmem?

Geceleri nasıl sağarsa dişi kurdun yüreği,

Nasıl sağarsa süt anne sabaha yorgunluğunu,

Bendeki bekleyiş de öyle çıplak, öyle yalın.

Uyanır kendi gurbetinde yalnızlığına,

Bilesin ki, başka sevdalara gelmem..

Gel, zamanın savrulan yelesine terk etme beni,

Gel, yoklamasın ruhumu derebeyi atlıları.

Gel, beni umutlarına kuşandır en bakir vaktinde,

İçimde kanasın gülleri zerafetin.

Yıkandıkça dirilir yüreğinde duygularım,

Korkma, sıcaklığında ölmem!..', 'Aşkın gözlerine hapsolduğun günden beri, Ben seni yürek yangını bir vahada ararım. Ararım serabın aldattığı ufuklar içinde, Bulmam mümkün mü...', ARRAY['Türk Edebiyatı','Şiir','Muhsin İlyas Subaşı']::text[], 8.5, '{"poet":"Muhsin İlyas Subaşı","poet_slug":"muhsin-i-lyas-subasi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/korkma-sicakliginda-olmem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biter', 'biter-muhsin-i-lyas-subasi-zzpf7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Umut yorulur, koşmazsa,

Bir köhne kafeste biter.

Gerçek hayali aşmazsa,

Ömür bir nefeste biter.

Bir hevese neler verdik,

Nice hayaller gönderdik,

Kim bilir kaç saf güzellik,

Çirkinleşen süste biter...

Üstüyle altı bir yerin,

Beklemek acılı, derin,

Yaşanmayan sevgilerin,

Heyecanı seste biter.

Umut, zaman, imkân derken,

Yalnızlık gelmişse erken,

Sen koroda yer ararken,

O çalınan beste biter!..', 'Umut yorulur, koşmazsa, Bir köhne kafeste biter. Gerçek hayali aşmazsa, Ömür bir nefeste biter. Bir hevese neler verdik, Nice hayaller gönde...', ARRAY['Türk Edebiyatı','Şiir','Muhsin İlyas Subaşı']::text[], 8.5, '{"poet":"Muhsin İlyas Subaşı","poet_slug":"muhsin-i-lyas-subasi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/biter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Günün Sonunda Arzu', 'bir-gunun-sonunda-arzu-ahmet-hasim-fh4uq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yorgun gözümün halkalarında

Güller gibi fecr oldu nümayan,

Güller gibi... sonsuz, iri güller

Güller ki kamıştan daha nalan; 

Gün doğdu yazık arkalarında! 

Altın kulelerden yine kuşlar

Tekrarını ömrün eder ilân.

Kuşlar mıdır onlar ki her akşam

Alemlerimizden sefer eyler? 

Akşam, yine akşam, yine akşam

Bir sırma kemerdir suya baksam; 

Üstümde sema kavs-i mutalsam! 

Akşam, yine akşam, yine akşam

Göllerde bu dem bir kamış olsam! 

(1921)', 'Yorgun gözümün halkalarında Güller gibi fecr oldu nümayan, Güller gibi... sonsuz, iri güller Güller ki kamıştan daha nalan;  Gün doğdu yazık...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Haşim']::text[], 8.5, '{"poet":"Ahmet Haşim","poet_slug":"ahmet-hasim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-gunun-sonunda-arzu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dikkat Et', 'dikkat-et-abdussettar-yavruturk-da5wp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dikkat et her sozune, sakın yalan olmasın;

Dikkat et her lokmana, sakın haram olmasın.

Cunku yalan Ile Iman, bIr arada durmaz,

Haram lokma yIyenIn, duasI kabul olmaz. 

DIkkat et devlet malIna sakIn elIn uzatma; 

Cunku onda mIlyonlarIn; yetImIn hakkI vardIr.

HelalIn az da olsa yetIn, sakIn ona haram katma;

BIl kI herkesIn rIzkI, RabbIn takdIrI kadardIr. 

Sen rIzkInI değIl de, zengInlIğI ararsIn; 

Haram, helal demeden, her kasaya dalarsIn. 

Sonra da suphe eder, fetvasInI sorarsIn; 

Mal devletIn, ben devletIn, bu da haram mI dersIn.

Esref-I mahlukatsIn sen, serefIne dIkkat et; 

YanlIs bIr Is yaparsan, serefInden olursun. 

Bu unvan, RabbIn tarafIndan verIldI sana; 

Her IsInde, bu unvanI korumaya dIkkat et. 

DIkkat et, her vazIfe, sana bIr emanettIr

Onu hakkIyla yapmamak, emanete IhanettIr.

Eğer tovbe edIp de, hak yoluna domezsen

Dunya ve ahIretI, husrandan IbarettIr.

DIkkat et kul hakkIna, o hakkIn affI yoktur;

Velev kI sahIbInden helallIk almadIkca.

DIkkat et komsu hakkIna, onun vebalI coktur.

Vebalden kurtulamazsIn, komsun razI olmadIkca.

AmIr Isen, emrIndekI Insanlara dIkkat et;

Memur Isen, gorevInI tam yapmaya dIkkat et.

IscI Isen, calIstIğIn saate dIkkat et;

Esnaf Isen, satIslarda durustluğe dIkkat et

Ey fanI Insanoğlu, bu sozlere dIkkat et;

Ey fanI Insanoğlu, bu sozlere dIkkat et;

Sozu benden de olsa, ozu IslamdandIr.

NefsInI haklI gormek IcIn, kendI kendInI avutma;

KIm olursan ol musallaya geleceğIn gunu unutma.

BEYKOZ-AKBABA 1993', 'Dikkat et her sozune, sakın yalan olmasın; Dikkat et her lokmana, sakın haram olmasın. Cunku yalan Ile Iman, bIr arada durmaz, Haram lokma y...', ARRAY['Türk Edebiyatı','Şiir','Abdussettar Yavrutürk']::text[], 8.5, '{"poet":"Abdussettar Yavrutürk","poet_slug":"abdussettar-yavruturk","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/dikkat-et-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşün', 'dusun-abdussettar-yavruturk-68z9o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Otur, dinlen burada, dusun, tefekkur et;

Bir yanda hayat, ortada cami, yanda mezarlik

Dedikodu, giybet yapma, ya hayir konus, ya sukut et;

Oku mevtalarin ruhuna, yapamazsan Rab''bini zikret.

Yuksek sesle konusma, kahkaha ile gulme;

Gulmek kalbi oldurur, gozyasi affa vesile.

Yuce Rab''bine sigin, ondan affini dile;

Selam olsun Yüce Veli, Akbaba Sultan Hazretleri''ne.

Zor bulursun boyle bir yer, sana ilham verecek;

Manevi sikintini, acini dindirecek.

Gercek bir inanisla bakarsan etrafina;

Bu bakis, hayatina yeni bir yon verecek.

Dusun demistik sana, sozumuzun basinda;

Ergec herkes yatacak, su musalla tasında.

Eger durust olursan butun dunya isinde;

Korkma, insallah korkma, bu omrun bitisinde.

Bak, soldaki agaclik, mezarliktir orasi;

Genc, ihtiyar demeden, gider gelen sirasi.

Kelime-i Tevhit''le, verirsek son nefesi;

Kurtulusa erenlerden, oluruz insallah.

Cami, turbe, mezarlik, musalla birarada;

Bilinmez ki yarin acap, hangimiz var sirada.

Daha siram var deme, bakarsin beklenen sira bozulur;

Buyukbaba dururken, torunun kabri kazinir.

Bu ne hikmettir ki ya Rab, sebebi sence malum;

Kabre kondugum zaman, ne olur benim halim

Ne malim fayda verir, ne de evlad-i eyalim;

Benimle gelen sadece, kefenimle amelim.

Iste, bunlari dusun, dusun bak ta ibret al;

Vaktin olursa eğer, ihmal etme gene gel.

Boyle bir yer bulamazsin, tefekkure dalacak;

Sikintidan kurtulup, kalbe huzur dolacak.

BEYKOZ-AKBABA 1993', 'Otur, dinlen burada, dusun, tefekkur et; Bir yanda hayat, ortada cami, yanda mezarlik Dedikodu, giybet yapma, ya hayir konus, ya sukut et; O...', ARRAY['Türk Edebiyatı','Şiir','Abdussettar Yavrutürk']::text[], 8.5, '{"poet":"Abdussettar Yavrutürk","poet_slug":"abdussettar-yavruturk","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/dusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluğum Kendimde', 'mutlulugum-kendimde-leo-buscaglia-romoq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mutluluğum kendimde sizde değil 

Yalnızca gel geç olduğunuz için değil

Olmadığım gibi olmamı istediğiniz için de

Mutlu olamam değişirsem 

Sırf sizin bencilliğinizi doyurmak için

Hoşnut da olamam eleştirdiğinizde beni 

Sizin gibi düşünmediğim ya da görmediğim için

Uyumsuz diyorlar bana oysa sizin inançlarınıza her karşı çıkışımda

Sizde benimkilerine karşı çıkıyorsunuz

Saydam olduğumu söylüyorsunuz ve kolayca unutulcağımı', 'Mutluluğum kendimde sizde değil  Yalnızca gel geç olduğunuz için değil Olmadığım gibi olmamı istediğiniz için de Mutlu olamam değişirsem  Sı...', ARRAY['Türk Edebiyatı','Şiir','Leo Buscaglia']::text[], 8.5, '{"poet":"Leo Buscaglia","poet_slug":"leo-buscaglia","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mutlulugum-kendimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-deli-kiz-512cf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecemin yildizlarini caldilar

Karanliktan korkuyorum Anne!

Hayallerimi yiktilar

Sinirliyim Anne!

Umitlerimi kirdilar

Caresizim Anne!

Ac kollarini, saril bana

Sevgiye, sicakliga, aglamaya

AGLAMAYA IHTIYACIM VAR ANNE!', 'Gecemin yildizlarini caldilar Karanliktan korkuyorum Anne! Hayallerimi yiktilar Sinirliyim Anne! Umitlerimi kirdilar Caresizim Anne! Ac koll...', ARRAY['Türk Edebiyatı','Şiir','Deli Kiz']::text[], 8.5, '{"poet":"Deli Kiz","poet_slug":"deli-kiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/anne-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Aşk Üfle', 'bana-ask-ufle-ozcan-unlu-bik44', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eksildi bir gün daha anne

Bak, büyümüyor yüreğim...

Terkedilmiş şehirlere benziyor

Karanlıkta koşan kederim.

Uzak, çok uzak bir şehre anne

Atmak istiyorum çocukluğumu.

Sırtlan derisi sabrımı kuşanıp

Ölmemiş çocuklara vermek...

Bugün aşkla doldur kalbimi anne

Sendendir sevgilimin kumdan saçları

Beni öp, öp beni doyur kendine

Onsuz yalvarmaya gücüm yok.

Gün kendi şarabını içiyor anne

Bense beyaz bir vadide huysuz

Gözyaşı şerbetimi yudumluyorum

Oğluna sahip çık, ona aşk üfle.

Umulmadık bir sevda bu anne

Ne başı sence, ne de sonu...

Çözdüğüm düğümler kader ipinden

Yeniden yumağa dönüyor anne.

Kirlenen ruhuma sahip çık anne

Ellerin okşasın, dirilsin sevgim.

Kırmadan sırça, ürkek kalbini onun

Beni dürüstlük koyunda durult.

Ben onun masalının sesiyim anne

Bitmesin heyecanlı sevda öykümüz

Hem onu, hem beni çok iyi koru

Çün, sendedir yarının aydınlığı.', 'Eksildi bir gün daha anne Bak, büyümüyor yüreğim... Terkedilmiş şehirlere benziyor Karanlıkta koşan kederim. Uzak, çok uzak bir şehre anne A...', ARRAY['Türk Edebiyatı','Şiir','Özcan Ünlü']::text[], 8.5, '{"poet":"Özcan Ünlü","poet_slug":"ozcan-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bana-ask-ufle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-ozcan-unlu-m4bcs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu hüznü, geceyi kabusa sunan

Bıçak gibi giydim eğnime, yoksun

Her sokak başında çığırtkan, solgun

Bir çocuk ağlaması, şimdi sensizlik.

Aynaya bakmaktan utanıyorum

Aynalar aksimi söylüyor anla.

Anla, neden şimdi sessiz sokaklar

Şarkılar ruhsuz ve dipsiz gece...

Güneş ta içime sokulan hançer

Ay, bu saatlerin kraliçesi..

Kurşun rüyalara döşenen yıldız

Sağnak olup yağar başıma, anla

Anla, bir kerpeten gibi sensizlik

Ve yosun geceler, sonsuz beklenen...

Gittin ki, işte gittin.. İşte sen gittin!

Artık varolmanın zehri yaşanan

Şehre isyan etmek, şehre darılmak

Olmuyor ay yüzlüm, yürümek sensiz

Gelmek, sana koşmak, olmuyor sensiz.

Anla, darağacı ıslığım gülüşüne

Gülüşüm bir kahvede unutulmuş çığlığın...', 'Bu hüznü, geceyi kabusa sunan Bıçak gibi giydim eğnime, yoksun Her sokak başında çığırtkan, solgun Bir çocuk ağlaması, şimdi sensizlik. Ayna...', ARRAY['Türk Edebiyatı','Şiir','Özcan Ünlü']::text[], 8.5, '{"poet":"Özcan Ünlü","poet_slug":"ozcan-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yoksun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göslerin Eylül Eylül', 'goslerin-eylul-eylul-lutfi-i-hsan-yazici-aha96', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hüznümü çıkardım bu sabah naftalin kokulu sandığımdan

Çünkü aşkım;

Hüznün bile daha güzel aşk sandıklarımdan

Ve gözlerin eylül eylül

İstanbul bile daha bir güzel

Daha bir sen', 'Hüznümü çıkardım bu sabah naftalin kokulu sandığımdan Çünkü aşkım; Hüznün bile daha güzel aşk sandıklarımdan Ve gözlerin eylül eylül İstanbu...', ARRAY['Türk Edebiyatı','Şiir','Lütfi İhsan Yazıcı']::text[], 8.5, '{"poet":"Lütfi İhsan Yazıcı","poet_slug":"lutfi-i-hsan-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/goslerin-eylul-eylul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk, mutlaka...', 'ask-mutlaka-ozcan-unlu-goy75', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mutlaka bir aşk vardır herkesin hayatında

Gecelerine düş salan, yıldırımlar çıkaran dudağından

Şarkı sözlerine bulanmış, kaldırımlarda

Paramparça olmuş adımların gittiği bir sevgili...

Mutlaka bir aşk vardır herkesin hayatında

Tutulmamış yeminlerin yerine konulan bir resim

Birkaç şiir, kırık dökük hatıralar

Volkanlara eş tutulmuş dokunuşlar panayırında

Soğuk beklemelere adanmış yağmur bulutları

Kiraz ağaçlarına asılmış yanlış dilek nişanları

Köy sokaklarından devşirilmiş masumluklar

Sokaklara yığılmış terkedilmişlikler

Ve sair...

Mutlaka bir aşk vardır herkesin hayatında

Yüreğe çığ düşüren, akla bulanıklık veren

Gürül gürül çağıldatan ruhun iştahını

Kaybedince kabusa dönülen, sevgiliyi

Özleyince ayrılığın girdabına girilen...

Mutlaka bir aşk vardır herkesin hayatında

Yaşamayı anlamlı kılan...', 'Mutlaka bir aşk vardır herkesin hayatında Gecelerine düş salan, yıldırımlar çıkaran dudağından Şarkı sözlerine bulanmış, kaldırımlarda Param...', ARRAY['Türk Edebiyatı','Şiir','Özcan Ünlü']::text[], 8.5, '{"poet":"Özcan Ünlü","poet_slug":"ozcan-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ask-mutlaka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Öğrendim', 'simdi-ogrendim-ozcan-unlu-zjm0l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağaçların çiçek açtığını sende öğrendim

Gördüm nasıl bir şehirde yaşadığımı

Aslında bir resmi sevmediğimi

Şimdi öğrendim.

Girdim dar kapısından bir evin

Duvarlara sürtünerek yürüdüm

Ürkek yapraklar gibi süzülerek

Ve asılarak ruhumun darağacına

Şimdi öğrendim gözümün gördüğünü

Bu kalbin aşka yenildiğini, şimdi...

Yalnızlar korosunun şefi gibiyim

Bir elimde umut, diğerinde söz

Uladım yokluğu yalnızlığıma

Sana koşan gündüz feneri

Fibi olduğumu şimdi öğrendim.

Türküsü yakılmış kandildi düşüm

Yarıkaranlık zindanlarda

Sensizlikle ölmüşüm.

Gözlerim kamaşıyor küflü gecede

Bırakıp gittiğinden resmin, elimi

Şimdi bir çocuk gibi ağlayacağım

Karanlık çökecek hatıralara.

Bu bahçeyi, hırpalanan kalbimi seninle gördüm

Gördüm nasıl çağladığını ruhumun

Aslında bir resmi sevmediğimi

Şimdi öğrendim.', 'Ağaçların çiçek açtığını sende öğrendim Gördüm nasıl bir şehirde yaşadığımı Aslında bir resmi sevmediğimi Şimdi öğrendim. Girdim dar kapısın...', ARRAY['Türk Edebiyatı','Şiir','Özcan Ünlü']::text[], 8.5, '{"poet":"Özcan Ünlü","poet_slug":"ozcan-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/simdi-ogrendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaldı', 'kaldi-ozcan-unlu-48auq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bildiklerimi sustum, bilmediklerim sende kaldı

Sende kaldı yürek şehrimin cadde ve sokakları

Bu ıstırap treninde dudağıma asılmış dualar

Huysuz gece uykuları ve sensizlik bende kaldı.

Öylece vurdun beni çığ düşmüş şarkı sözlerine

Kıyamet topları terkedişin surlarında kaldı

Çok gördüğüm düşler bile nisyan bulvarlarında

Hüzün, yanağımdaki gözyaşlarında kaldı.

Elifi bitmiş bir kör kuyuda çırpınıyorum

Sesini duysam yeter, ümitlerim dünde kaldı

Mutluluk bulvarından geçmeyecek hatıram

O şiirler, şarkılar vuslat iskelesinde kaldı.

Bildiklerimi sustum, bilmediklerim sende kaldı

Huysuz gece uykuları ve sensizlik bende kaldı.', 'Bildiklerimi sustum, bilmediklerim sende kaldı Sende kaldı yürek şehrimin cadde ve sokakları Bu ıstırap treninde dudağıma asılmış dualar Huy...', ARRAY['Türk Edebiyatı','Şiir','Özcan Ünlü']::text[], 8.5, '{"poet":"Özcan Ünlü","poet_slug":"ozcan-unlu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kaldi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Dili', 'askin-dili-beyazit-cenan-8ueu0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni anlattım dağlara

Yollara,kuşlara

Seni anlattım arkadaşlara

Sana anlatamadım

Seni gördüm havada

Seni söyledim denize

Seni tattım kadehlerde

Senin haberin olmadan

Şarkılar söyledim kendi kendime

Aşkımı mırıldandım kimse duymadan

Bir kuşu dinledim

Dinledim ve ağladım

Kuşta seviyormuş 

Benim gibi

Kuşta ağlıyormuş

Kendi diliyle

Sorsan ki bana

Kuşu nasıl anladın?

Bir tanem

Aşkın dili birdir', 'Seni anlattım dağlara Yollara,kuşlara Seni anlattım arkadaşlara Sana anlatamadım Seni gördüm havada Seni söyledim denize Seni tattım kadehle...', ARRAY['Türk Edebiyatı','Şiir','Beyazıt Cenan']::text[], 8.5, '{"poet":"Beyazıt Cenan","poet_slug":"beyazit-cenan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/askin-dili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmazsan', 'sen-olmazsan-beyazit-cenan-66yei', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni dinlesen 

Neler söylerdim sana

Anlatırdım aşkımı

Dillere destan sevdamı

Kime anlattıysam boş

Kimse anlamadı

Beni yalnız sen anlayabilirdin

Sende anlayamadın

Belkide anlamak istemedin

Kimbilir

Çok uzaksın bana artık 

Gittikçe uzaklaşıyorsun

Kötü hayaller kuruyorum 

Belkide kabus görüyorum

Hiç düşünmemiştim

Sen olmayacaksın diye

Tüm hayallerim 

Senin üstüneydi

Sen olmazsan 

Hayallerimde olmayacak

Hayallerim olmayınca

Ben olmuşum ne çıkar

Hayali olmayan insan

Neden yaşar ki dünyada?

Neyin uğruna?

Neden katlanır bunca acıya?

Bende katlanamıyorum 

Bende dayanamıyorum 

Acılara,yalnızlığa

En kötüsü de sensizliğe', 'Beni dinlesen  Neler söylerdim sana Anlatırdım aşkımı Dillere destan sevdamı Kime anlattıysam boş Kimse anlamadı Beni yalnız sen anlayabilir...', ARRAY['Türk Edebiyatı','Şiir','Beyazıt Cenan']::text[], 8.5, '{"poet":"Beyazıt Cenan","poet_slug":"beyazit-cenan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sen-olmazsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmesede', 'yetmesede-beyazit-cenan-zrhic', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşam boğuyor beni

Sen gidiyorsun diye

Akşam olmasın istiyorum

Hep gündüz olsun

Sen hep burda kal

Zararı yok uzakta ol

Ama uzaktan da olsa

Seni görmek yeter bana

Seni görmek yeter

Yetmesede yeter', 'Akşam boğuyor beni Sen gidiyorsun diye Akşam olmasın istiyorum Hep gündüz olsun Sen hep burda kal Zararı yok uzakta ol Ama uzaktan da olsa S...', ARRAY['Türk Edebiyatı','Şiir','Beyazıt Cenan']::text[], 8.5, '{"poet":"Beyazıt Cenan","poet_slug":"beyazit-cenan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yetmesede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimi Kandırıyorum', 'kendimi-kandiriyorum-firuze-gokce-cicek-omjwe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''''Bak dışarda sana bakıyor'''' diyor bir ses,

Bakdım.

köpeklerden başka kimse yok!

Değil sen beni,

Ben kendimi kandırıyorum

Çalan telefon...

Bu sefer ''O'' diyor bir ses,

Seslerden başka duyulan yok!

Değil sen beni,

Ben hala kendimi kandırıyorum

Ne dudak var

Ne göz

''''Peki neyi öpüyorsun?'''' diyor bir ses,

Boşluğu!

Değil sen beni,

Ben hala kendimi kandırıyorum.

 ( Galata Kulesi- 27.12.99 )', '''''Bak dışarda sana bakıyor'''' diyor bir ses, Bakdım. köpeklerden başka kimse yok! Değil sen beni, Ben kendimi kandırıyorum Çalan telefon... B...', ARRAY['Türk Edebiyatı','Şiir','Firuze Gökçe Çiçek']::text[], 8.5, '{"poet":"Firuze Gökçe Çiçek","poet_slug":"firuze-gokce-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kendimi-kandiriyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimbilir', 'kimbilir-firuze-gokce-cicek-8oud6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sanki o sen değildin

Mazeret bindirmedim kelimelere

Üstüme alınmadım ilk defa

Öylesine gelmişsin.

Özlemişsin,

Kimbilir?

Nereleri,kimleri...

(  Aralık 99 )', 'Sanki o sen değildin Mazeret bindirmedim kelimelere Üstüme alınmadım ilk defa Öylesine gelmişsin. Özlemişsin, Kimbilir? Nereleri,kimleri... ...', ARRAY['Türk Edebiyatı','Şiir','Firuze Gökçe Çiçek']::text[], 8.5, '{"poet":"Firuze Gökçe Çiçek","poet_slug":"firuze-gokce-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kimbilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulanığım', 'bulanigim-firuze-gokce-cicek-57oo3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbim.

Kalp mi bu?

Eline geçer mi?

''''Kimsin? '''' diye,

Sorar mısın?

Umarım.

Kimim ben?

Sence ben miyim?

Bitti diye atar mısın?

Yoksa

Saklar mı?

Hala...

Evet!

Hala...

Herşey senin içindi.

''''Biz'''' vardı , dağalrı taşları delen...

Hepsi bu ,

Yetmez.

Boğuluyorum,nefesim boğuyor!

Unutmadan,

Geldiğinde sana birşey söyliycem.', 'Kalbim. Kalp mi bu? Eline geçer mi? ''''Kimsin? '''' diye, Sorar mısın? Umarım. Kimim ben? Sence ben miyim? Bitti diye atar mısın? Yoksa Saklar ...', ARRAY['Türk Edebiyatı','Şiir','Firuze Gökçe Çiçek']::text[], 8.5, '{"poet":"Firuze Gökçe Çiçek","poet_slug":"firuze-gokce-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bulanigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarısı', 'yarisi-firuze-gokce-cicek-mjgta', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bugün bütün şarkılar senden yana.

Dilinin ucundaki söylediklerin,

Benim devamını getiremediğim,

Duyduğumda içimin sızladığı

Yarısı senin!

 ( 23.01.00)', 'Bugün bütün şarkılar senden yana. Dilinin ucundaki söylediklerin, Benim devamını getiremediğim, Duyduğumda içimin sızladığı Yarısı senin!  (...', ARRAY['Türk Edebiyatı','Şiir','Firuze Gökçe Çiçek']::text[], 8.5, '{"poet":"Firuze Gökçe Çiçek","poet_slug":"firuze-gokce-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yarisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüş', 'donus-firuze-gokce-cicek-5gjmm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Köpürür içimdeki matem

Tüm dalgalar senden yana

Acı acı gülümser sendeki gamzeler

Kahkahaların boydan boya.

Uğraşır dururum içimdeki senle,

Kah birgün gerçekte kah birgün düşümde.

Dün gece bir el dokundu tenime;

Korktum dönemedim geriye,

Sen olamazdın !

Sen beni gömmüştün, 

Onun kalbinde.

Sonu gelmez düşüncelerin çarkındayım,

Bitiremiyeceğim bir son!

Ellerim sadece yalvarmaya kalkıyor,

Gözlerim ağlamaktan buğu.

Ve sana tekrar sana dönüyorum Tanrım...', 'Köpürür içimdeki matem Tüm dalgalar senden yana Acı acı gülümser sendeki gamzeler Kahkahaların boydan boya. Uğraşır dururum içimdeki senle, ...', ARRAY['Türk Edebiyatı','Şiir','Firuze Gökçe Çiçek']::text[], 8.5, '{"poet":"Firuze Gökçe Çiçek","poet_slug":"firuze-gokce-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/donus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir sen bir ben', 'bir-sen-bir-ben-firuze-gokce-cicek-xb5q4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeni çıkan bir rüzgar

Önünde durmalı

Şöyle bi derinden esmeli

Saçlarını dalga dalga yapmalı

İçini üşütmeli

Sarılmanı 

Sımsıkı sarılmanı istetmeli

Gözlerini direk bana döndürmeli

Kalpleri karşı karşıya koymalı

Bir ben yapmalı

Bir seni estirmeli

Estirdikçe kalpleri hissetmeli

Başımı canının üstüne koydurmalı

Dokunan yüzüm içini ısıtmalı

Rüzgar estikçe

Ateş olmalı

Bir sen yanmalı 

Bir beni küllemeli

Ben söndükçe

Sen başlatmalı

Hey rüzgar hey !

Sevmeli! 

Bir ben sevmeli

Bir sen...', 'Yeni çıkan bir rüzgar Önünde durmalı Şöyle bi derinden esmeli Saçlarını dalga dalga yapmalı İçini üşütmeli Sarılmanı  Sımsıkı sarılmanı iste...', ARRAY['Türk Edebiyatı','Şiir','Firuze Gökçe Çiçek']::text[], 8.5, '{"poet":"Firuze Gökçe Çiçek","poet_slug":"firuze-gokce-cicek","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-sen-bir-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'döneceksin', 'doneceksin-sair-armagan-8y6sq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bekliyorum geleceksin birgün

özledim seni diye

sen başkaymışsın diyeceksin

anlayamamışım

affettim seni diyeceksin

geldim geri,dönelim eski günlere

anladım seni diyeceksin

üzülmeyeceksin birdaha

razıyım kıskanclıklarına.

beni ittiğin gün için özür dileyeceksin

o ben diildim diyeceksin

sesin titreyecek

olurmu?sevgilimm diyeceksin

ama sen kazılmayacak bir mezar içinde

öylece yatacaksın benim kalbimde.', 'bekliyorum geleceksin birgün özledim seni diye sen başkaymışsın diyeceksin anlayamamışım affettim seni diyeceksin geldim geri,dönelim eski g...', ARRAY['Türk Edebiyatı','Şiir','Şair Armağan']::text[], 8.5, '{"poet":"Şair Armağan","poet_slug":"sair-armagan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/doneceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günleri', 'gunleri-cemal-safi-tsl4t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hangi kul tanrısına bu kadar saygı duymuş?

Aç kutsal kitapları oku bütün dinleri.

Hangi kalp ayrılıktan bu kadar kaygı duymuş?

Kim yaşamış önünde diz çöktüğüm günleri?...

Meğer aşkı anlatan cümle şarkılar azmış;

tüm besteler çaresiz,nihaventmiş,hicazmış.

Kim görmüş,kim yaşamış,hangi şiir,kim yazmış?

Her cevrine göz yumup,bel büktüğüm günleri?...

Bana sor aşk deneni,nasıl ateş,nasıl kor.

Sor sevgiyle gururun,savaşını bana sor.

Aramak nasıl acı,itiraf ne kadar zor;

Buram buram kan kusup,yaş döktüğüm günleri.

Sanma yanına kalır işlediğin cinayet.

Eden bulur sevdiğim,eden bulur nihayet.

Kim yaşamış,Mecnun mu?Hep yalan,hep rivayet

Aşkın çilegahında kök söktürdüğüm günleri...', 'Hangi kul tanrısına bu kadar saygı duymuş? Aç kutsal kitapları oku bütün dinleri. Hangi kalp ayrılıktan bu kadar kaygı duymuş? Kim yaşamış ö...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gunleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelini Son Arzusu', 'gelini-son-arzusu-bilal-celik-4wpuv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün gözlerin dalacak derinlere

Belki de aklına ben geleceğim

Beraber yaşadığımız güzel günleri  düşüneceksin

Birden her şey mazimizi anlatacak sana,unutamadığını anlayacaksın...

Yanıma gelmeyi düşünebilirsin bir buket gülle

Gideceksin çiçekçiye,

Alacaksın en sevdiğim gülleri

Geldiğin zaman kapım kalabalık olacak.

Düğünüm olduğunu düşünüp kahrolacaksın

Ansızın karşına gözü ağlamaklı anam çıkacak

Seni görünce sıkacak yumruklarını ,vuracak göğsüne göğsüne...

''senin yüzünden,senin yüzünden'' diye haykıracak...

Ne olduğunu bilemeyeceksin,

O an donup kalacaksın elindeki güller tek tek yerlere düşecek... 

Tabutumun üstünde bir duvak göreceksin

İşte o zaman anam yanaşacak yanına,

Vasiyetimi sıralayacak sana:

''ÖLÜRSEM SEVGİLİMLE EVLENMEDEN ÖNCE ANAM

KEFEN YERİNE GELİNLİK GİYDİRİN BANA

GÖRÜNCE SEVGİLİM SAKIN AĞLAMA

BENİ KARA TOPRAKLARDA ARA 

ÖRNEK OLSUN SEVİPTE AYRILANLARA

SENİ SEVDİĞİMİ SAKIN UNUTMA 

SAKIN UNUTMA.............', 'Bir gün gözlerin dalacak derinlere Belki de aklına ben geleceğim Beraber yaşadığımız güzel günleri  düşüneceksin Birden her şey mazimizi anl...', ARRAY['Türk Edebiyatı','Şiir','Bilal Çelik']::text[], 8.5, '{"poet":"Bilal Çelik","poet_slug":"bilal-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gelini-son-arzusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aradığını Bulmak', 'aradigini-bulmak-bilal-celik-nretu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neden hep sevmediklerim sever beni ! 

Bir liman arar azgın suda bu gemi 

Ardından gitsem ateşin yarın kor mu ! 

Lanet olsun bulması bu kadar zor mu !', 'Neden hep sevmediklerim sever beni !  Bir liman arar azgın suda bu gemi  Ardından gitsem ateşin yarın kor mu !  Lanet olsun bulması bu kadar...', ARRAY['Türk Edebiyatı','Şiir','Bilal Çelik']::text[], 8.5, '{"poet":"Bilal Çelik","poet_slug":"bilal-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aradigini-bulmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Ve Sağır', 'kor-ve-sagir-bilal-celik-tdaf5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Paylaşamadınız koca dünyayı 

Her gün yürür sınır telleri 

Vermeyecekseniz eğer 

Koparmayın çiçekleri 

Duymaz mısınız içli ağıtları 

Her gün ağlar yağmur bulutları 

Ulaşıp sevişmek ister 

Tutmayın uçurtmaları 

Silahlar yaksın elinizi 

Tanıştırın artık ''BARIŞ''la dilinizi 

Gülüp oynamak ister 

Salın çocukları 

Vurmayın umutları 

Artık 

       vurmayın umutları ...', 'Paylaşamadınız koca dünyayı  Her gün yürür sınır telleri  Vermeyecekseniz eğer  Koparmayın çiçekleri  Duymaz mısınız içli ağıtları  Her gün ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Çelik']::text[], 8.5, '{"poet":"Bilal Çelik","poet_slug":"bilal-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kor-ve-sagir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Meşk Vesaire', 'ask-mesk-vesaire-bilal-celik-6b6oj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbini yerinden çıkaracak gibi 

Kimlerden gizli yaşanacak gibi 

Seni herkesten kaçıracak gibi 

Yaşadığın AŞK olsa gerek 

Gözlerin yağmurda saçak gibi 

Sevdiğin senden kaçak gibi 

Kalbin yanar ocak gibi 

Yaşadığın MEŞK olmasa gerek 

Sevdiğin çölde serap gibi 

Elinde kaldı bak kum gibi 

Hatırlarsın dün gibi 

Yaşadığına VESAİRE demek gerek.', 'Kalbini yerinden çıkaracak gibi  Kimlerden gizli yaşanacak gibi  Seni herkesten kaçıracak gibi  Yaşadığın AŞK olsa gerek  Gözlerin yağmurda ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Çelik']::text[], 8.5, '{"poet":"Bilal Çelik","poet_slug":"bilal-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-mesk-vesaire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden Doğuş', 'yeniden-dogus-bilal-celik-kau4k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Korkarım 

           geç kalmaktan 

     Sana, 

İşime değil 

Hayata, 

Erken gitmiş olup da 

Beklemek, heyecan 

Hayatlar boyunca 

Böyle dört kez 

Bekledim seni 

Her defasında 

Uzun sürdü 

Dediler; deli ! 

Bu kez yakaladım ! 

Zannettim ... 

Zamanı değilmiş 

Önceden gönderdiler seni ...', 'Korkarım             geç kalmaktan       Sana,  İşime değil  Hayata,  Erken gitmiş olup da  Beklemek, heyecan  Hayatlar boyunca  Böyle dört ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Çelik']::text[], 8.5, '{"poet":"Bilal Çelik","poet_slug":"bilal-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yeniden-dogus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan Haklı', 'i-nsan-hakli-bilal-celik-u9z8j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tanrı mısınız ! 

Yazıyorsunuz diye 

''İnsan Hakları'' 

Kimin için 

           kurdunuz 

O pankartları 

Gerek yok ! 

Vermeye, saklamaya 

       alınmaya ... 

Hak ! 

İçimizde 

             saklı.', 'Tanrı mısınız !  Yazıyorsunuz diye  ''İnsan Hakları''  Kimin için             kurdunuz  O pankartları  Gerek yok !  Vermeye, saklamaya        ...', ARRAY['Türk Edebiyatı','Şiir','Bilal Çelik']::text[], 8.5, '{"poet":"Bilal Çelik","poet_slug":"bilal-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/insan-hakli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül', 'gul-bilal-celik-o669c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlamadım uzun süredir 

Gülmek zevksiz leşti artık 

Ağlamak istiyorum 

Gülmeyi yeniden tatmayı 

Ağlıyorum ve bilmiyordum 

Gülmek için ağlamanın 

Bu kadar güzel olduğunu 

Ağla ağla ve gül 

Gülün dikeni gözyaşı 

Yük taşı ağla 

Mezar taşı !  ağla 

Ve gül çocuk 

Çünkü sen de ağladın 

                           doğduğunda 

Sanma savdın sıranı 

Bir gülücük adına 

    ağlayacaksın ömür boyunca 

Sonunda 

         güldürmek için başkalarını 

Ağlayanlar bırakacaksın ardında.', 'Ağlamadım uzun süredir  Gülmek zevksiz leşti artık  Ağlamak istiyorum  Gülmeyi yeniden tatmayı  Ağlıyorum ve bilmiyordum  Gülmek için ağlama...', ARRAY['Türk Edebiyatı','Şiir','Bilal Çelik']::text[], 8.5, '{"poet":"Bilal Çelik","poet_slug":"bilal-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gul-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerim', 'ellerim-umit-oktay-yilmaz-4yeuv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ellerim bir çocuk gibidir

görünce seni

gizlenecek yer ararlar

al tut onları 

küçük

pamuk ellerinle 

ısıt

aslında senden istedikleri budur 

isteyip söyleyemedikleri 

( Ankara, 18 Haziran 1996 )', 'ellerim bir çocuk gibidir görünce seni gizlenecek yer ararlar al tut onları  küçük pamuk ellerinle  ısıt aslında senden istedikleri budur  i...', ARRAY['Türk Edebiyatı','Şiir','Ümit Oktay Yılmaz']::text[], 8.5, '{"poet":"Ümit Oktay Yılmaz","poet_slug":"umit-oktay-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ellerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta Oğütler', 'dosta-ogutler-umit-oktay-yilmaz-p3jye', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ezilmiş bir insan görürsen

adını Özgür koy

Ezilmişliğin içinde özgürce yaşayan

ezilmişlikte özgür olan



Bir savaşın içinde

sonunu bekleyen bir çocuk görürsen

Adını Barış koy

çok beklemeden gülsün diye



Güneşli bir bahar günü

Kırlarda bir kız görürsen

koşan çiçek toplayan

Onu Burcu diye çağır

Çiçeklerden güzel koktuğunu anlasın diye

Ve dostum

Kavgamızda bitkin düşenleri

Umut diye çağır

Yarının umudu güç verir onlara

savaşma azmi

Onlar bilir yarının bizim olduğunu

( Ankara, 25 Temmuz 1990 )', 'Ezilmiş bir insan görürsen adını Özgür koy Ezilmişliğin içinde özgürce yaşayan ezilmişlikte özgür olan Bir savaşın içinde sonunu bekleyen bi...', ARRAY['Türk Edebiyatı','Şiir','Ümit Oktay Yılmaz']::text[], 8.5, '{"poet":"Ümit Oktay Yılmaz","poet_slug":"umit-oktay-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dosta-ogutler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Beyaz Öyküler', 'siyah-beyaz-oykuler-umit-oktay-yilmaz-u49vr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Siyah 

kirlenme ise

beyaz da 

kirlenmenin habercisi

beyaz 

temizlikse 

siyah da 

yüzü ağartılacak olandır



siyah 

Afrika ise 

utanması gerekendir

beyaz



beyaz 

Türkiyemse

sokaklarında yaşananlar siyahtır

beyaz o insanlarsa 

siyah

yöneticilerin vicdanıdır

( Ankara, Şubat 1996 )', 'Siyah  kirlenme ise beyaz da  kirlenmenin habercisi beyaz  temizlikse  siyah da  yüzü ağartılacak olandır siyah  Afrika ise  utanması gereke...', ARRAY['Türk Edebiyatı','Şiir','Ümit Oktay Yılmaz']::text[], 8.5, '{"poet":"Ümit Oktay Yılmaz","poet_slug":"umit-oktay-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/siyah-beyaz-oykuler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yap Boz/ma', 'yap-boz-ma-umit-oktay-yilmaz-q5sut', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yap boz tahtana 

en son beni koy

son parça olduğundan 

bütüne anlam veren

Yap 

ama bozma 

Yap boz tahtana en son beni koy

sürdürüyorsa ben olmayı bir parça 

Ve ilk beni çıkar

güzü beklerken sararmamak için 

hep yeşil kalmak için

Rize, 28 Ağustos 1997', 'Yap boz tahtana  en son beni koy son parça olduğundan  bütüne anlam veren Yap  ama bozma  Yap boz tahtana en son beni koy sürdürüyorsa ben o...', ARRAY['Türk Edebiyatı','Şiir','Ümit Oktay Yılmaz']::text[], 8.5, '{"poet":"Ümit Oktay Yılmaz","poet_slug":"umit-oktay-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yap-boz-ma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutma Yüreğimi', 'tutma-yuregimi-muhsin-i-lyas-subasi-8ug7c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu yolculuk, bin basamak,

Derinlerden çıkar gelir.

Bu yolculuk, bin basamak,

Ufka sevgiyle yükselir.

Bu yolculuk, ırmakta su,

Gökte yıldız, dağda rüzgâr,

Bu yolculuk, aşk kokusu,

Yolları içime doğar.

Bu yolculuk, ne han ister,

Ne de Arap soylu kısrak.

Bu yolculuk aşka gider,

Tutma yüreğimi, bırak!..', 'Bu yolculuk, bin basamak, Derinlerden çıkar gelir. Bu yolculuk, bin basamak, Ufka sevgiyle yükselir. Bu yolculuk, ırmakta su, Gökte yıldız, ...', ARRAY['Türk Edebiyatı','Şiir','Muhsin İlyas Subaşı']::text[], 8.5, '{"poet":"Muhsin İlyas Subaşı","poet_slug":"muhsin-i-lyas-subasi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tutma-yuregimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün İçime Hiç Doğmadı', 'gun-i-cime-hic-dogmadi-muhsin-i-lyas-subasi-s6kxi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gün içime hiç doğmadı,

Acılara vurgunum ben.

Benimledir nice savaş,

Gündüz savaş, gece savaş,

El değmeyin, yorgunum ben.

Hüzün doğar gülüşümde,

Korku dağdır gelişimde,

Bin can biter ölüşümde,

Azrail''e dargınım ben.', 'gün içime hiç doğmadı, Acılara vurgunum ben. Benimledir nice savaş, Gündüz savaş, gece savaş, El değmeyin, yorgunum ben. Hüzün doğar gülüşüm...', ARRAY['Türk Edebiyatı','Şiir','Muhsin İlyas Subaşı']::text[], 8.5, '{"poet":"Muhsin İlyas Subaşı","poet_slug":"muhsin-i-lyas-subasi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gun-icime-hic-dogmadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz', 'i-simsiz-sevda-turk-9wepb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ansızın uçar gidersin yüreğimden

Konarsın bir bulutun üstüne

Boyarsın gökyüzünü bilinmeyen birrenge

Korkarım bakmaya gökyüzüne', 'Ansızın uçar gidersin yüreğimden Konarsın bir bulutun üstüne Boyarsın gökyüzünü bilinmeyen birrenge Korkarım bakmaya gökyüzüne...', ARRAY['Türk Edebiyatı','Şiir','Sevda Türk']::text[], 8.5, '{"poet":"Sevda Türk","poet_slug":"sevda-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/isimsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Ben', 've-ben-sevda-turk-y4wz1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu şehri düşünüyorum

Büyütüp gözümde kocaman yaptığım şehri

Ve

O büyüdükçe küçülen yüreğimi

Küçülen hayallerimi ve umutlarımı...

Zamanın su gibi akıp geçtiğidünyada

Ömür denen teknemi

Bu koca şehre, küçük yüreğime 

Akıntıya, fırtınaya yani

Herşeye rağmen

Yüzdürmeye çalışıyorum

Ve

Bu yüzden kendimi kahraman ilan ediyorum.

Yeryüzündeki milyonlarca kahramandan biri.', 'Bu şehri düşünüyorum Büyütüp gözümde kocaman yaptığım şehri Ve O büyüdükçe küçülen yüreğimi Küçülen hayallerimi ve umutlarımı... Zamanın su ...', ARRAY['Türk Edebiyatı','Şiir','Sevda Türk']::text[], 8.5, '{"poet":"Sevda Türk","poet_slug":"sevda-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Şehir', 'o-sehir-mujdat-senocak-fu9ep', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aynı suyu içtik,

Aynı yollarda yürüdük,

Aynı güneşle ısındık,

Aynı yağmurla ıslandık.

Anlayacağın yıllar yılı;

Aynı tozu yuttuk.

Aynı baharda,

Çiçek kokularıyla sarhoş olduk.

Benimde ayakkabılarıma çamur yapışırdı,

Ben de karda oynamayı severdim.

Gök gürültüsünde sığınacak yer arardım.

Yeri geldi ağladım,

Yeri geldi güldüm.

Üzüntülerimi ve sevinçlerimi

Bende senin gibi o şehirle paylaştım.', 'Aynı suyu içtik, Aynı yollarda yürüdük, Aynı güneşle ısındık, Aynı yağmurla ıslandık. Anlayacağın yıllar yılı; Aynı tozu yuttuk. Aynı bahard...', ARRAY['Türk Edebiyatı','Şiir','Müjdat Şenocak']::text[], 8.5, '{"poet":"Müjdat Şenocak","poet_slug":"mujdat-senocak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/o-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Buluşmamız', 'i-lk-bulusmamiz-hasan-cifci-5fh7n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilmem hatırlar mısın o günü...

Seninle ilk kez göz göze gelmiştik.

Esen rüzgar saçlarımızı okşarken,

Duygularımız birdi, yüreklerimiz bir.

Umutlarımız birdi, dileklerimiz bir.

İçim titremişti yüzüne bakarken...

Gönlüm bir deli fırtınaydı,

Çağlayan nehir...

Güneşin karanlığa doğduğu kadar,

Gönüllerimize doğmuştu ilkbahar.

Ne zaman seni ansam,

Aklıma hep o gün gelir.

Esiyordu rüzgar, uçuyordu uçurtmalar,

Gün sabahtı, mevsim sonbahar...

( zile 1994)', 'Bilmem hatırlar mısın o günü... Seninle ilk kez göz göze gelmiştik. Esen rüzgar saçlarımızı okşarken, Duygularımız birdi, yüreklerimiz bir. ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çifci']::text[], 8.5, '{"poet":"Hasan Çifci","poet_slug":"hasan-cifci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ilk-bulusmamiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'huzun', 'huzun-halil-i-brahim-percinkaya-7g9k7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimdeki gizli bir şarkının 

bestesini mırıldanmakta dudaklarım

Ama ne çare...

Yok dinleyenim.

Şarkı mahzun,ben mahzun.

Kalbim hıçkırıklarla ağlıyor

 saba makamında

Sesimi duyan yok

gözyaşımı silen yok.

Kalbim mahzun, ben mahzun

Haykırasım geliyor herkese

kalbi yosun tutmuş gönüllere

Tempo tutun şarkıma 

vererek elele,gönül gönüle.

Sesimi duyan yok,

Bana eşlik eden yok.

Gönül mahzun ben mahzun.', 'İçimdeki gizli bir şarkının  bestesini mırıldanmakta dudaklarım Ama ne çare... Yok dinleyenim. Şarkı mahzun,ben mahzun. Kalbim hıçkırıklarla...', ARRAY['Türk Edebiyatı','Şiir','Halil İbrahim Perçinkaya']::text[], 8.5, '{"poet":"Halil İbrahim Perçinkaya","poet_slug":"halil-i-brahim-percinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlkler', 'i-lkler-hasan-cifci-h3gn4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Herşeyin ilki bir başka oluyor.

İlk heyecan, ilk mutluluk, ilk umut...

Okula başladığım ilk gün...

İlk sınıfımı, ilk önlüğümü hatırladım.

İlk kalemim, ilk defterim, 

İlk mezuniyet...

Mevsime düşen ilk kar,

Çiçekler getiren ilkbahar...

Seni ilk gördüğüm anlar,

Gülümseyerek bakışın...

İlk buluşmamız,

İlk el ele tutuşmamız...

Derken ilk kavgamız ve ilk ayrılık!

Mesafe ve zaman seni unutturamaz artık.

İsmini her duyuşta seni hatırlarım.

Çünkü sen de ilktin;

İlk gözağrım!...

(  Cebeci 1994)', 'Herşeyin ilki bir başka oluyor. İlk heyecan, ilk mutluluk, ilk umut... Okula başladığım ilk gün... İlk sınıfımı, ilk önlüğümü hatırladım. İl...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çifci']::text[], 8.5, '{"poet":"Hasan Çifci","poet_slug":"hasan-cifci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ilkler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-hasan-cifci-ygbkr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen gideli kaç ay oldu bilmedim.

Menekşe güller solmadan gel.

Yokluğunda bir an bile gülmedim.

Gönlüme hüzünler dolmadan gel.

Gözlerim uykuya hasret kaldı.

Yüreğimi binbir acı sardı.

Bak işte yapraklar sarardı.

Mevsim sonbahar olmadan gel.

Gayrı saçlarıma aklar düştü.

Gönlümden sevdanın kuşu uçtu.

İçimde sayısız dert buluştu.

Düşmanlar halime gülmeden gel.

Eşim dostum hep seni soruyor.

Gözlerim her yerde seni arıyor.

Deli gönül sevdasız olmuyor.

Yerini başkası almadan gel.

Çok bekletme, sabrım gün olur biter.

Sevdalar gurbet elde ölür biter.

Bakarsın ki gün gelir, ömür biter.

Azrail kapımı çalmadan gel.

	Cebeci (1994)', 'Sen gideli kaç ay oldu bilmedim. Menekşe güller solmadan gel. Yokluğunda bir an bile gülmedim. Gönlüme hüzünler dolmadan gel. Gözlerim uykuy...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çifci']::text[], 8.5, '{"poet":"Hasan Çifci","poet_slug":"hasan-cifci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gel-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzeli Sevince', 'guzeli-sevince-hasan-cifci-ieqsy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün Beytepe''de bir kız gördüm

Otobüsten inince...

Sarı saçlı, mavi gözlü, uzun boylu

Ve ince...

Heyecandan kalbim duracaktı

Gözleri gözlerime değince...

Sebebim olacaktı az kalsın,

Utangaç bir edayla 

Yüzüme bakıp gülünce.

Bilmem nedendir, aklım hala o güzelde.

Bugün bir de rüyamda görünce,

Anladım ki inasan oturur, kalkar gezer de,

Mecnuna dönermiş

Güzeli sevince...

			

( Cebeci 1994 )', 'Dün Beytepe''de bir kız gördüm Otobüsten inince... Sarı saçlı, mavi gözlü, uzun boylu Ve ince... Heyecandan kalbim duracaktı Gözleri gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çifci']::text[], 8.5, '{"poet":"Hasan Çifci","poet_slug":"hasan-cifci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/guzeli-sevince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğum', 'cocuklugum-hasan-cifci-j0wuc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu yağmur bana çocukluğumu hatırlattı.

O zamanlar şen şakrak oynardık yağmurda.

Ağaçlar altında ateş yakardık.

Annem bana bağırırdı ''hastalanacaksın'' diye...

Ben onu dinlemez, oynardım.

Sonra eve gelirdim sırılsıklam.

Annem bana kızardı...

Değişince üstümü, fırlardım dışarı.

Annem yine kızardı.

Gökte yağmur, yerde çamur,

Ateş başında başlardı muhabbetimiz....

Ortalığı seller almış kimin umrunda!

Kimin umrunda evi olmayanlar varmış...

Yağmur yağar, ateş yanar, muhabbet tatlı.

Ah çocukluğum...

Sende ne anılar saklı...

( zile- 1994)', 'Bu yağmur bana çocukluğumu hatırlattı. O zamanlar şen şakrak oynardık yağmurda. Ağaçlar altında ateş yakardık. Annem bana bağırırdı ''hastala...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çifci']::text[], 8.5, '{"poet":"Hasan Çifci","poet_slug":"hasan-cifci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cocuklugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Olsam', 'ben-olsam-hasan-cifci-aipxg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tutsam da elinden koşsam ufuklara,

Ayak  bastığın bir yol da ben olsam.

Bıraksam deli dolu esen rüzgara.

Perçeminde bir tel de ben olsam.

Alsam seni götürsem buralardan,

Geçirsem tozlu yollardan, karlı dağlardan.

Aşıp gelip uzak diyarlardan,

Sana koşan bir kul da ben olsam.

Umutların tükenip bittiği yerde,

Dermandır senin sevdan derde.

Akşam gün batarken, sabah seherde,

Sana değen bir yel de ben olsam.

Nasibini almayan sevda balından,

Derde düşenin anlamaz halinden.

Hasretle sarılıp ince belinden,

Sana uzanan bir el de ben olsam.

( Cebeci-1995)', 'Tutsam da elinden koşsam ufuklara, Ayak  bastığın bir yol da ben olsam. Bıraksam deli dolu esen rüzgara. Perçeminde bir tel de ben olsam. Al...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çifci']::text[], 8.5, '{"poet":"Hasan Çifci","poet_slug":"hasan-cifci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice Yıllara', 'nice-yillara-hasan-cifci-xc675', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gün senin doğum günün.

Sen benden uzaktasın, ben senden uzakta.

''Yıldızlara bakınca hatırla beni ''demiştin...

Seni unutmak mümkün mü!

Kayan yıldızda ararım seni.

Uçan kuşa, esen rüzgara sorarım seni.

Bu akşam doyasıya seyret gökyüzünü.

Yıldızlara bakıp hatırla beni.

Sen de beni sor uçan kuşlara, esen rüzgara...

Güle hasret bülbüller gibi,

Sevgiye hasret gönüller gibi,

Gönlüm sana hasret, yüreğim güllere.

Aklım sana tutsak, gözlerim yollara.

Doğum günün kutlu olsun gülüm,

Nice yıllara...

( Zile-1994)', 'Bu gün senin doğum günün. Sen benden uzaktasın, ben senden uzakta. ''Yıldızlara bakınca hatırla beni ''demiştin... Seni unutmak mümkün mü! Kay...', ARRAY['Türk Edebiyatı','Şiir','Hasan Çifci']::text[], 8.5, '{"poet":"Hasan Çifci","poet_slug":"hasan-cifci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nice-yillara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostuma', 'dostuma-simge-atakan-cj6up', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bizim arkadaşlığımız ölene dek diyemem

Ölümsüzlük içinde beraberiz gidemem

Seni üzgün gününde tek başına terkedemem

Sensiz olmaz dostum inkar edemem

En umutsuz günümde tesellimsin sen benim

Uğrunadır varım,yoğum,herşeyim

Aklımda bir sen bir de sevdiğim

Seni nasıl bensizliğe sürükler giderim.

Senden başka dostum yok benim

Bir sensin sırdaşım diyebildiğim

Üzüntüleri sil baştan da gülelim

Sensiz asla bunu hep bilmelisin...', 'Bizim arkadaşlığımız ölene dek diyemem Ölümsüzlük içinde beraberiz gidemem Seni üzgün gününde tek başına terkedemem Sensiz olmaz dostum inka...', ARRAY['Türk Edebiyatı','Şiir','Simge Atakan']::text[], 8.5, '{"poet":"Simge Atakan","poet_slug":"simge-atakan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dostuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paslı Umutlar', 'pasli-umutlar-cengiz-catalkaya-kgrnd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve umut,

paslı bir ok gibi 

saplanmıştı yüreğimize.

Ne söküp atabiliyorduk,

ne de acısına katlanabiliyorduk...

Umut, senin gözlerindeydi sevgilim,

ben gözlerin olmak istedim.

Oysa bakışların,

hep benden uzaklaraydı,

hiç yakın olamadım.

Biz yaralı bir nesildik

Ve hiçbirşeye inanmıyorduk.

Gözlerimiz kendimizden başkasını görmüyordu,

mutsuzduk

ve umut,

paslı bir ok gibi,

saplanmıştı yüreğimize.

(24 Ocak 2000/Ankara)', 'Ve umut, paslı bir ok gibi  saplanmıştı yüreğimize. Ne söküp atabiliyorduk, ne de acısına katlanabiliyorduk... Umut, senin gözlerindeydi sev...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Çatalkaya']::text[], 8.5, '{"poet":"Cengiz Çatalkaya","poet_slug":"cengiz-catalkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/pasli-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Şiir', 'sessiz-siir-cengiz-catalkaya-itnt0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anılardan dökülen, 

sessiz yaprakların üstüne

seni yazıyorum,sessizce.

Ve onlar 

düşmeye devam ediyor,

sessizce.

Gökyüzü,yırtılırcasına sessiz,

ben,sensiz.

Görüntün,

ipek bir mendilin üzerine,

işleniyor sessizce,

ve bana bakıyorsun,işlendikçe.

Ben susuyorum,

sessizlik olmak için,

acımamak için,

ağlayan gözlerini görmemek için,

sessizce...', 'Anılardan dökülen,  sessiz yaprakların üstüne seni yazıyorum,sessizce. Ve onlar  düşmeye devam ediyor, sessizce. Gökyüzü,yırtılırcasına sess...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Çatalkaya']::text[], 8.5, '{"poet":"Cengiz Çatalkaya","poet_slug":"cengiz-catalkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sessiz-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trizantem 5', 'trizantem-5-necip-hikmet-js9g9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'baktım sanal dünya

başımda şapka 

aldım elime mouse''ı

başladım yazmaya

ne gelirse aklıma

şairim şair

burada var mı bir şiir', 'baktım sanal dünya başımda şapka  aldım elime mouse''ı başladım yazmaya ne gelirse aklıma şairim şair burada var mı bir şiir...', ARRAY['Türk Edebiyatı','Şiir','Necip Hikmet']::text[], 8.5, '{"poet":"Necip Hikmet","poet_slug":"necip-hikmet","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/trizantem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Zaman Yeşertiyorum', 'bos-zaman-yesertiyorum-isil-canitez-lfa94', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüzüme vurur gecenin soğuğu 

Sobanın başındayken bile

seni düşünürüm sık sık

Hüzün dolar yüreğime

Gözyaşlarım çabucak diner sanırım 

Ama kendimi hiç tutamam,

hıçkırmaya başlarım.

Ne tesadüfse, her seferinde,

Ben ağlamaya başlayınca ,

Gökyüzü de dualar etmeye başlar

Şıp şıp da şıp şıp

Aydınlık günler gelir aklıma

Güneşin rüzgarla koro oluşturduğu

Bir pembe bulut yığını geçer

gözbebeklerimin kahvesinden.

Bir de bakarım üzerinde sen ve ben

Bilirsin,hayal kurmazsan zaman hiç geçmez.

Karlar yağarsa birgün umutlarıma

Sırf geleceği süt beyaz yapmak için

Bir gürültüdür kopacağını bilyorum 

Karları eritmek adına.', 'Yüzüme vurur gecenin soğuğu  Sobanın başındayken bile seni düşünürüm sık sık Hüzün dolar yüreğime Gözyaşlarım çabucak diner sanırım  Ama ken...', ARRAY['Türk Edebiyatı','Şiir','Işıl Canıtez']::text[], 8.5, '{"poet":"Işıl Canıtez","poet_slug":"isil-canitez","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bos-zaman-yesertiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trizantem 6', 'trizantem-6-necip-hikmet-u3v69', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşürürlerse şiiri

Böyle ele ayağa

Tabi ki bulurlar kafa

Necip hikmet öncüsü oldu

Bu yolun

Bekler yanına 

Yardımcı dost akraba', 'Düşürürlerse şiiri Böyle ele ayağa Tabi ki bulurlar kafa Necip hikmet öncüsü oldu Bu yolun Bekler yanına  Yardımcı dost akraba...', ARRAY['Türk Edebiyatı','Şiir','Necip Hikmet']::text[], 8.5, '{"poet":"Necip Hikmet","poet_slug":"necip-hikmet","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/trizantem-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Şehirlere Dair', 'olu-sehirlere-dair-erinc-buyukasik-5uxfe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kondularda yaşandı   geçmişlerimiz

Her anı yeni bir kesite gebe

Sessiz, ölüme yakışır çığlıklar,

Bilirim ki dingin geçer ölüler

Yaşamın varoşlarından

Bir çocuk oyunu

Gizlenir yoksul düşlerimize

Kaçışır sokağın darlığı 

evrenin geniş soluklanımlarından

kentin yazgısında

yazılır:

kentin orta yeri

ölü evi

umarsız bekleriz

insanlık muştusunu

ve sessizce ağlar 

köşelerine sinmiş yoksul şehirler

günbegün yıkık kondularda 

şimdi bir ölü yaşar

omuzların üzerinde

( 6-12-1999 )', 'Kondularda yaşandı   geçmişlerimiz Her anı yeni bir kesite gebe Sessiz, ölüme yakışır çığlıklar, Bilirim ki dingin geçer ölüler Yaşamın varo...', ARRAY['Türk Edebiyatı','Şiir','Erinç Büyükaşık']::text[], 8.5, '{"poet":"Erinç Büyükaşık","poet_slug":"erinc-buyukasik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olu-sehirlere-dair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giz', 'giz-erinc-buyukasik-mofd9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Usta bir yontucunun öyküsünü

Anlatıyordu

Söylence

Coğrafyalar gezgininin 

Anlattıklarıyla inşa edildi

Yontu yontucunun belleğine gizlenmişti

Tarih yaratıcılarının günahlarıyla donanmıştı

Yontu günahları besliyordu

Günah kötü bir sevişmeydi

Arzuların yenik düşmesiydi    

Erken büyümüş çocukların 

Erken yaratılmış öyküleriydi

Yeni çağlara gebe 

Halkların büyük yalnızlığına

Ölümcül, suskun korkularına

Bizler mi doğduk, zaman mı gebe kaldı çocuklarımıza

Yontucuda kalan nice gizlerin ardı sıra', 'Usta bir yontucunun öyküsünü Anlatıyordu Söylence Coğrafyalar gezgininin  Anlattıklarıyla inşa edildi Yontu yontucunun belleğine gizlenmişti...', ARRAY['Türk Edebiyatı','Şiir','Erinç Büyükaşık']::text[], 8.5, '{"poet":"Erinç Büyükaşık","poet_slug":"erinc-buyukasik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/giz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mi', 'mi-erinc-buyukasik-hjlae', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sona uzanan bir çizginin öyküdaşlarıydık

Önce

Suçlu çocukluklarımızdan yakınıyordu

Esin perisi

Öylesine bir yakınma değil

Yıkıntıyı miras bırakırdı

Lalezar geceye

sancısı.. göremediğim herhangi bir düşü

uykusuz uyanıp 

geceleri

SONRASI

Yankısı ırak ülke

Sevdası öte şehir

Sancısı düşsel ada

Bir öyküye yelteniyor gibi

Bir doğu içindeki...

“çekingen” bir hayli

rayların köşelerine gizlenmiş çakıltaşları misali

Suçlu çağın yankısından gizli

Ağlaşıyor koca şehir ahalisi

Bir halk yüreği gibi

Kuşatıyor ıssız geceyi

Soru

mi 

Sorular büyütür bizleri

Şehirlere sokulur vebalı ölüler

Dehşetli bir cinsiyetsizleşme vaktidir 

gece

Ölülerine tapınır 

büyük

tapınaklar

buğulanır

doğulanır

Bir ortaçağ sürgünüdür

kuşatmada 

ayin vakti

bayındır şehirler

Gündüze ihanettedir

şehir meydanı

Miskin bir sarhoşluğa

Sığınır 

ay vakti

SORU:

Soru

Mi

Mış gibi 

Şehrin hikayeleri...', 'Sona uzanan bir çizginin öyküdaşlarıydık Önce Suçlu çocukluklarımızdan yakınıyordu Esin perisi Öylesine bir yakınma değil Yıkıntıyı miras bı...', ARRAY['Türk Edebiyatı','Şiir','Erinç Büyükaşık']::text[], 8.5, '{"poet":"Erinç Büyükaşık","poet_slug":"erinc-buyukasik","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-erinc-buyukasik-6e1s2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzun uzadıya düşünmeli

Ölümlerin yitik düştüğü

Son yüzyılın çeyreğini

Yürekte üretmeli kuşkunun sancısını

Ölü doğuran kadınlara söyletmeli 

En diri türküleri

Susturmalı, susmalı

Yılgınlığın bezirganı

Tellalların yalancılığında

Yükselen antenleri

İnanmamalı yalanın sultasına

Yazgıda bekletilmiş intiharlara

Atmalı içten içe yeni yüzyılların korku masallarını

Dizelere düşmeli geçmiş günlerin öyküleri

Dizelere uğramalı bugünün inatçı çocukları

Düşünmeli

  Düşün

     Düş...', 'Uzun uzadıya düşünmeli Ölümlerin yitik düştüğü Son yüzyılın çeyreğini Yürekte üretmeli kuşkunun sancısını Ölü doğuran kadınlara söyletmeli  ...', ARRAY['Türk Edebiyatı','Şiir','Erinç Büyükaşık']::text[], 8.5, '{"poet":"Erinç Büyükaşık","poet_slug":"erinc-buyukasik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman-Çocukluğum', 'zaman-cocuklugum-erinc-buyukasik-ckb5r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzak bir düşlem ülkesi idi içimde yabancılaşan

Uzak kentlerin korkunç yansısıydı

Trajedinin habercisi

Ben yarına adanmış bir yaşama tutunamadım

Sen dünde soluk alan kentlerdin

Uzlaşmaz bir bağ idi

İçimdeki doğurganlık

Ölü evler, ölü sokaklar doğuruyordu

Tükenmiş belleğimde... 

Çığlıklar ölümleri andırıyordu

Evlerin ağıt mevsimini

Unutkan bir toplumun öykülerini yaşıyorduk

Unutkan çocukların öykülerini yazardı..

Çocukluğum 

Biraz Mesnevi kokardı öyküler

Doğunun yitik yüzü... 

Ben biraz Mecnunken 

Sen Leyla ile kavga ederdin sürekli

Kınardın onun bekleyişini

Korkunç yalnızlığıyla hesaplaşırdın

Anlatının edilgen kahramanlarının

Daha çok Juliet ile özdeş 

Batılı bir trajedi olmuştu öykülerin

Ben ise

Hala 

Ölü evlerin 

Koca kalabalığında 

Soruyordum soruları

yansıması

Geniş zamanların

Coğrafyası...', 'Uzak bir düşlem ülkesi idi içimde yabancılaşan Uzak kentlerin korkunç yansısıydı Trajedinin habercisi Ben yarına adanmış bir yaşama tutunama...', ARRAY['Türk Edebiyatı','Şiir','Erinç Büyükaşık']::text[], 8.5, '{"poet":"Erinç Büyükaşık","poet_slug":"erinc-buyukasik","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/zaman-cocuklugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutacağım', 'unutacagim-teoman-karagol-ejvyl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgi deryasında boğulmak varken,

Ayrılığın bahsini duyarsam senden,

Kalbimin pınarlarını kapatacağım,

Sadece gözlerimle ağlayacağım.

Göz yaşlarımın buğusuyla sileceğim, 

Gözlerinin hayalini gözlerimden.

Senin ve senin olan şeylerin,

Seninle ilgisi olan her şeyin

İşgalinden kurtarırsam düşlerimi,

Mütemadiyen sıkacağım dişlerimi,

Sensizliği takacağım koluma,

Bakmayacağım sağıma, soluma,

Sensiz devam edeceğim yoluma.

Seni kaybedince mutluluğu bulacağım,

Serap görmüş kervancı gibi olacağım,

Sevgilim çok güzeldi diyeceğim,

Ama gözleri yoktu, 

Göremedi körleşen kalbini.

Kulakları yoktu,

Duyamadı kalbimin sesini.

Elleri yoktu,

Tutamadı verdiği sözleri.

Kalbi bile yoktu, 

Sevemedi hayallerimdeki halini.

Adınla mahdut olan hafızamdan

Gün gelecek adını da sileceğim 

Bütün ağladıklarıma o gün güleceğim,

Sahte gülüşlerle kendimi avutacağım,

Senin asıl sahteliğini bilince unutacağım.', 'Sevgi deryasında boğulmak varken, Ayrılığın bahsini duyarsam senden, Kalbimin pınarlarını kapatacağım, Sadece gözlerimle ağlayacağım. Göz ya...', ARRAY['Türk Edebiyatı','Şiir','Teoman Karagöl']::text[], 8.5, '{"poet":"Teoman Karagöl","poet_slug":"teoman-karagol","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/unutacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüktük... Büyüdük...(!)', 'kucuktuk-buyuduk-teoman-karagol-9inf5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Küçüktük...

Küçük küçük görüyordu gözlerimiz.

Yaşımızı belli ediyordu sözlerimiz

Küçük küçüktü ayaklarımız, ellerimiz.

Küçüktük, küçücüktük...

Kin, öfke, zulüm nedir bilmezdik

Herkesi severdik, Kalbimizde sevgi gülü beslerdik

Büyük hayaller kurar, büyük olmayı düşlerdik.

Herkese vardı bolca sevgimiz

Küçük olabilir miydi kalbimiz?

Hayır! Fazlasıyla büyüktü 

Nefret kalbimize gereksiz bir yüktü 

Karşılıksız sever, sevgiyle dolar taşardık

Mutluluğumuzu bütün kalplere aşılardık

Azimkardık; 

Bütün nefretleri kovacak kadar 

Bahtiyardık;

Bütün sevgileri kucaklayacak kadar.

Küçüktük...

Kırık değnekten yaptığımız 

Kır atımıza binerdik göğsümüzü kabartarak

Dünyaya adalet dağıtırdık

Haksızlığı yıkar adaleti kurardık 

Mazlumları ezilmekten kurtarırdık

“HERKES SEVİLMEYE LAYIKTIR” derdik

Zalimleri bile layıkıyla severdik.

Küçüktük…

Büyük umutlarımız vardı 

Büyük kalbimizde büyük sevgiler yaşardı 

Büyüdük…

Büyüdü ayaklarımız, büyüdü ellerimiz.

Biz büyüdük, Küçüldü yüreklerimiz.

Kalbimizde yer bulamadı sevgilerimiz.

Büyüdük…Büyüdük diyemiyoruz

Öfkemizi, nefretimizi yenemiyoruz.

Azıcık sevgiye yer veremiyoruz.

Doğruyu yanlıştan seçemiyoruz.

Büyüdük mü, küçüldük mü biz de bilemiyoruz…', 'Küçüktük... Küçük küçük görüyordu gözlerimiz. Yaşımızı belli ediyordu sözlerimiz Küçük küçüktü ayaklarımız, ellerimiz. Küçüktük, küçücüktük....', ARRAY['Türk Edebiyatı','Şiir','Teoman Karagöl']::text[], 8.5, '{"poet":"Teoman Karagöl","poet_slug":"teoman-karagol","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kucuktuk-buyuduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Güllük Sevda', 'bir-gulluk-sevda-teoman-karagol-gco3q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir aşk yaşandı dostlar, böylesi yaşanmayacak

Aşkların en yücesiydi hiç unutulmayacak

Kız ilk gördüğünde güzel gözleriyle masum masum bakıp

Delikanlıya kalpten bir gülümseyişle gülüvermişti

Delikanlı sevdiğinin gül yüzü gibi olmasa da koparıp

Ona aşkının isbatı için en güzel gülü vermişti.

Bir gülle başlamıştı bu sevda ansızın bir sabah.

Aşkları kalplerinde tomurcuklandı tekrar tekrar her sabah

Kısa sürede bu iki kalbi aşkın alevi sardı 

Güzel kız sevdiğinden gülle beraber kalbini de aldı

Yine de sevdiğini özlüyordu bir gün bile görmese

Yollarda kalırdı gözleri her gün yanına gelmese 

Bağlıydılar birbirlerine hem de pek çok 

Derlerdi “Onlar gibi seven hiç mi hiç yok”

Kıza sevdiğinden bir çok hediye gelirdi

O da bildiği en güzel hediyeyi gönderirdi.

Aşkına bahçelerden papatyalar toplardı

Ona göre papatyalarda aşık duası vardı 

Onların yapraklarını birer birer koparırdı 

Son yaprakta muhakkak “seviyor” çıkardı.

Ayrılıklarda gülleri merhem olurdu yarasına

Anılarını canlandırmak için bakardı kitap arasına

Sevgilisinden kalan gülleri bulurdu orada 

Onlarda teselli bulurdu arada sırada 

Her gülün ayrı bir hatırası vardı 

Her birinde sevdiğinin bir parçası yaşardı

Şimdi ise ayrılıklardan en zorunu yaşıyordu

Nasıl dayanabildiğine o da çok şaşıyordu.

Askere uğurlamıştı sevdiğini aylar önce 

Hasretini giderecekti teskereyle dönünce

Geldiğini duysa hemen yollarına koşardı

Bu ümitle bir an için gözceğizi yaşardı 

Ansızın geldi sevdiği hem de vaktinden evvel 

Güller duydu geldiğini gül yüzlüsünden evvel

Duyunca bekleyemedi sabırsızca koştu yanı başına…

Gördü ki gül gibi soldurmuşlar, bakmadan on dokuz yaşında 

Üzerindeki güllerden sevdiğini göremedi 

Feryadını kalbine gömdü bir kelime diyemedi 

Kucakladı bağrına bastı, bir gül de o verdi

Bu vuslat da bir nebze acısını giderdi 

Bu gül sevdiğine verdiği en son gül alacaktı 

Biliyordu ki onun her yanı binlerce gülle dolacaktı.

Verdiği güller içinde sadece bu son gül canlıydı

Tek bunun takdiminde bu denli heyecanlıydı

Avuçlarıyla suladı gülünü solmasın diye 

Çünkü buydu sevdiğine verebileceği en son hediye 

Kalbiyle büyütecekti gülünü solmaması için 

Gülüyle birlikte kalbini de toprağa verdi 

Sevdiğinin kabrinde rahatsız olmaması için 

Sessizce fatiha okudu atmayan kalbiyle “amin” dedi.

Bir gülle başlayan aşkları gül ömürlü olmuştu

Tomurcuk bir gül gibi açılmadan solmuştu

İçin için ağladı kızcağız sevdiği için 

Yüzü güldü bir an Cennette kavuşabileceği için 

Şehit mezarındaki gülü görenler bu aşkı hatırlıyor

Gül ise boynunu bükmüş sanki bir hicrana ağlıyor...', 'Bir aşk yaşandı dostlar, böylesi yaşanmayacak Aşkların en yücesiydi hiç unutulmayacak Kız ilk gördüğünde güzel gözleriyle masum masum bakıp ...', ARRAY['Türk Edebiyatı','Şiir','Teoman Karagöl']::text[], 8.5, '{"poet":"Teoman Karagöl","poet_slug":"teoman-karagol","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/bir-gulluk-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçtim...', 'vazgectim-turgut-yuca-x8w93', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Söyle hayatımın anlamı söyle 

Hiç mi çalmadın hecelerimi..?

Söyle hiç mi almadın canı bu bedenden?

Söyle sönen umudum

Hiç mi ağlatmadın uykusuz geceleri.

Beni terkettiğin gün

Beni çalıp gittiğin gündü.

Söyle hiç mi sızlamadı zalim kalbin?

Beni sensiz koyup gittiğin gün.

Şimdi ben burda.. bu karanlıkta..

Sen bilmek istemesende.

Beni öldürdüğünü görmesende.

Ben herşeyden vazgeçtim senden bile...', 'Söyle hayatımın anlamı söyle  Hiç mi çalmadın hecelerimi..? Söyle hiç mi almadın canı bu bedenden? Söyle sönen umudum Hiç mi ağlatmadın uyku...', ARRAY['Türk Edebiyatı','Şiir','Turgut Yuca']::text[], 8.5, '{"poet":"Turgut Yuca","poet_slug":"turgut-yuca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vazgectim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşver!', 'bosver-turgut-yuca-5r7lm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hadi boşver, herşeyi boşver.

Seni sevdiğimi boşver bir kere,

Damlaları boşver dökülüp ziyan olan.

Kederimi boşver, duyduğum acı mı ? boşver.

Gülmemi değil ağlamamı boşver.

Sevmemi değil sevmediğini boşver.

Sen herşeyi değil aslında.

Sen beni boşver.', 'Hadi boşver, herşeyi boşver. Seni sevdiğimi boşver bir kere, Damlaları boşver dökülüp ziyan olan. Kederimi boşver, duyduğum acı mı ? boşver....', ARRAY['Türk Edebiyatı','Şiir','Turgut Yuca']::text[], 8.5, '{"poet":"Turgut Yuca","poet_slug":"turgut-yuca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bosver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlar', 'yildizlar-turgut-yuca-nnz28', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu akşam yıldızlar düştü avucuma.

Yıldızlar başı boş,

Yıldızlar avare gökyüzünde,

Ama sen yoksun ne çare.

Bu akşam yıldızlar düştü üzerime

Hiç biri ama hiç biri sen değil.

Yıldızlar ne kadar düşer ki üstüme.

Senin düştüğün kadar.

Bu akşam yıldızlar düştü yüreğime

Pare pare içimi yaktılar.

Ama sen yoksun ki içlerinde

Yaksalar ne kadar yakar.

Bu akşam sen düştün gene herşeyime

Bir bilsen nasıl da yalandılar.

Bu akşam sen yine yıldız gibi

Senin aşkın beni yüreğimden yaralar.', 'Bu akşam yıldızlar düştü avucuma. Yıldızlar başı boş, Yıldızlar avare gökyüzünde, Ama sen yoksun ne çare. Bu akşam yıldızlar düştü üzerime H...', ARRAY['Türk Edebiyatı','Şiir','Turgut Yuca']::text[], 8.5, '{"poet":"Turgut Yuca","poet_slug":"turgut-yuca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yildizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Piyano Soloları I', 'piyano-sololari-i-akif-kurtulus-xek0p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'büyütebilir miyiz bir aşkı ayrılırız korkusuyla', 'büyütebilir miyiz bir aşkı ayrılırız korkusuyla...', ARRAY['Türk Edebiyatı','Şiir','Akif Kurtuluş']::text[], 8.5, '{"poet":"Akif Kurtuluş","poet_slug":"akif-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/piyano-sololari-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-erdinc-mukyen-dgo8o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökteki siyah bulutlar gibi

Geçer günlerim

Yağan yağmur akan seller gibi

Ağlar gözlerim

Bilmem benim bu kötü kaderim

Hep ağlamakmı

Senin uğruna senin yoluna

Ölüp gitmekmi

Karanlıklarda ışıldayan 

Mehtap bile

Aydınlatmıyor

Benim bu sensiz gecelerimi

Senden başka biri avutmuyor

Kırık kalbimi

Kimse silmiyor

Artık ağlayan Gözlerimi', 'Gökteki siyah bulutlar gibi Geçer günlerim Yağan yağmur akan seller gibi Ağlar gözlerim Bilmem benim bu kötü kaderim Hep ağlamakmı Senin uğr...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Mukyen']::text[], 8.5, '{"poet":"Erdinç Mukyen","poet_slug":"erdinc-mukyen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensiz-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırk Yaşın Eşiğinde Bir Şiir', 'kirk-yasin-esiginde-bir-siir-ataol-behramoglu-bna92', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Küçük heyecanlara paydos

Çünkü rüzgarla aynı yaşdayım

Çünkü güneş kardeşim

Bir ırmakla şevişmekteyim

Bana artık dingin olmak

Bana yalınlık yaraşır

İçimde şiirin güzelliği

Yaşamak sevinciyle yarışır

Güzeller güzeli ömrüm

Sana gitgide sevdalanıştayım

Nice emeklerle dokunmuş

Bir ince, bir nazlı nakıştayım

Küçük tasalara, tutkulara paydos

Çünkü evrenle aynı yaştayım

Başsız sonsuz doyumsuz

Bir başdöndürücü akıştayım.', 'Küçük heyecanlara paydos Çünkü rüzgarla aynı yaşdayım Çünkü güneş kardeşim Bir ırmakla şevişmekteyim Bana artık dingin olmak Bana yalınlık y...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kirk-yasin-esiginde-bir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tik Tak', 'tik-tak-harun-dogruyol-iuxfp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen on iki rakamısın saatte

Ben avare bir akrebim

Her tur yeni bir heyecandır bana

Her turda daha fazla özlerim seni

Yanına gelince zaman yavaş geçsin isterim

Titrek ve ağır bir geçiş

Usulca

Ürkek ve kaçamak bir bakış

Göz ucuyla

Sen hep ordasın

Hiç istifini bozmadan durursun öyle

Her geçişte merak ederim

Acaba görüyor musun beni

Biliyor musun hissettiklerimi

Bir gün daha var

Koca bir gün daha

Kavuşmaya', 'Sen on iki rakamısın saatte Ben avare bir akrebim Her tur yeni bir heyecandır bana Her turda daha fazla özlerim seni Yanına gelince zaman ya...', ARRAY['Türk Edebiyatı','Şiir','Harun Doğruyol']::text[], 8.5, '{"poet":"Harun Doğruyol","poet_slug":"harun-dogruyol","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/tik-tak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorsan Şanslısın', 'seviyorsan-sanslisin-gulnaz-oruc-jiw2b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani bağırırda sesini duyuramazsın ya

İçinden elveda demek gelir hayata

Gözlerini kapadığın bir anda

Hayali geliverir göz kapaklarının ardına

Eğer varsa onunla bir hatıran

Belki aklına geldiğinde seni ağlatan

Belkide küçük bir bakışma yüreğini hoplatan 

Sen ve onun hayalidir yüreğinde gömülü olan

Eğer öyleyse ne mutlu sana

Düşünebileceğin birisi var yüreğinde,aklında

Bence artık sen hiç tasalanma

Git ve yüreğini dök ona korkusuzca

Bencillik yapma sakın

Bırak sana aldırmasın

Sen seviyorsun yine şanslısın

Ya hiç sevmeyenler ne yapsın?', 'Hani bağırırda sesini duyuramazsın ya İçinden elveda demek gelir hayata Gözlerini kapadığın bir anda Hayali geliverir göz kapaklarının ardın...', ARRAY['Türk Edebiyatı','Şiir','Gülnaz Oruç']::text[], 8.5, '{"poet":"Gülnaz Oruç","poet_slug":"gulnaz-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seviyorsan-sanslisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Seninle Ne De Sensiz Yapamam', 'ne-seninle-ne-de-sensiz-yapamam-gulnaz-oruc-6sekw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İhanet ettin sen bana 

Aşkıma, saf duygularıma

Sen kendince haklı olsan da

Kaldırmadı yüreğim daha fazla.

Sessizce çık git hayatımdan

Atamam seni kalbimden, atamam

Bağlandım sana, birden kopamam

Ne seninle ne de sensiz yapamam.', 'İhanet ettin sen bana  Aşkıma, saf duygularıma Sen kendince haklı olsan da Kaldırmadı yüreğim daha fazla. Sessizce çık git hayatımdan Atamam...', ARRAY['Türk Edebiyatı','Şiir','Gülnaz Oruç']::text[], 8.5, '{"poet":"Gülnaz Oruç","poet_slug":"gulnaz-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-seninle-ne-de-sensiz-yapamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-gulnaz-oruc-a50lc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkım elle tutulabileseydi,

Sana paketleyip verirdim.

Uzun engeller olmasaydı,

Hemen sana gelirdim.

Sevgimi anlayabilseydin,

Seni ömür boyu severdim.

Hatta sevdim ve

Seveceğim', 'Aşkım elle tutulabileseydi, Sana paketleyip verirdim. Uzun engeller olmasaydı, Hemen sana gelirdim. Sevgimi anlayabilseydin, Seni ömür boyu ...', ARRAY['Türk Edebiyatı','Şiir','Gülnaz Oruç']::text[], 8.5, '{"poet":"Gülnaz Oruç","poet_slug":"gulnaz-oruc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-seviyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kosava', 'kosava-ayhan-erdem-m63ys', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günlerdir aç, bitap ve uykusuzsun yollarda, 

                             Uyu ama sakın ölme bebeğim, bu batakta, 

                             Kosava''nın ihtiyacı olacak sana enyakın şafakta, 

                             Sen onlara sabır ver, güç ver Allah''ım.

                             Onlar Sırp katillerce hunharca katledilmekte, 

                             Dünya şaşırmış, boş gözlerle çevreye bakınmakta, 

                             Çaresiz kalmış Kosavam kan gölünde ağlamakta, 

                             Sen bizleri gaflet içinde bırakma Allah''ım.

                             Yavrular bir damla süte muhtaç, aranmakta, 

                             Vahşiler ağızları köpürmüş sağa, sola saldırmakta, 

                             Kosavam yanıyor Sultan Murat Han''lar kahrolmakta, 

                             Sen onları aç ve susuz bırakma Allah''ım.

                             Geride bıraktıkları aç ve sefil, yürüyorlar yalın ayakla, 

                             Bozulmuş bahçelerinde kalan karanfiller ağlamakta, 

                             Ocakları yanmıyor, bacalar tütmüyor yuvalar yıkılmakta, 

                             NATO vurduğunu söylüyor, Sırplar kahkahalar atmakta, 

                             Sen bizleri fidansız, yuvasız bırakma Allah''ım.', 'Günlerdir aç, bitap ve uykusuzsun yollarda,                               Uyu ama sakın ölme bebeğim, bu batakta,                           ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Erdem']::text[], 8.5, '{"poet":"Ayhan Erdem","poet_slug":"ayhan-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kosava-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Çiçeğim', 'kir-cicegim-ayhan-erdem-df43o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bende çirkin yaratmayan bir Allah''a iman  var 

                           Boynu bükük çiçeklere ağlayan güzel beni yaralar 

                           Mecnun''un Leyla''sı için, parçaladığı dağlar 

                           Kalbimde sana ayırdığım yere ismini dağlar, 

                           Kuşlar sevgimizi göklere duyurmaya şakılar 

                           Sular, topraklara, denizlere öğretmeye çağlar. 

                           Bu aşkın zehiri seni bana ölümüne bağlar. 

                           Sevdiceğim, kır çiçeğim, solmuş yüreğim kanağlar. 

                           Acı gurbette, kanıyor kapanmamış yaralar. 

                           Kırgın gönlümde kış oldu nevbaharlar. 

                           Dizi dizi dert ile dolmuş bardaklar, 

                           Masamda solmuş güllerle, leylaklar.', 'Bende çirkin yaratmayan bir Allah''a iman  var                             Boynu bükük çiçeklere ağlayan güzel beni yaralar                  ...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Erdem']::text[], 8.5, '{"poet":"Ayhan Erdem","poet_slug":"ayhan-erdem","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kir-cicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çizim', 'cizim-ozdemir-asaf-jfiky', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ÇİZİM

Ben ağacın resmini çizdim, 

Hiç kimse için..

Daha ne yapraklarını yapıştırdım,

Ne de adını koydum 

Yemişlerin..

Onu

Bir anlama yakıştırdım.

Adınıza büyüyor belleğimde ağaç,

Başka ağaçlar doğuruyor; 

Büyümeyi bölüşüyorlar gölgelerinde..

Dal-dal, yaprak-yaprak öpüşüyorlar..

Çizmez olaydım, bizi soruyorlar..

Dönüp bizlere bakıyorum:

Dövüşüyorlar.', 'ÇİZİM Ben ağacın resmini çizdim,  Hiç kimse için.. Daha ne yapraklarını yapıştırdım, Ne de adını koydum  Yemişlerin.. Onu Bir anlama yakıştı...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Diye', 'gel-diye-lutfi-i-hsan-yazici-sktjv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çizgiler saydım düşümde

Başımı dayayıp buğulu camlara,

Aşk devşirdim kayan yıldızlardan,

Bekledim..

Futursuzca hemde,

Yılmadan.

Ta ki bir sen oluncaya kadar tenimdeki ürperiş,

Ağlamadan bekledim ve kanamadan.

Beklemenin,

Kavuşmak kadar kadar güzel olduğunu dinledim kendimden.

ve aynı yalanı tekrarladım

hiç istemeden..', 'Çizgiler saydım düşümde Başımı dayayıp buğulu camlara, Aşk devşirdim kayan yıldızlardan, Bekledim.. Futursuzca hemde, Yılmadan. Ta ki bir se...', ARRAY['Türk Edebiyatı','Şiir','Lütfi İhsan Yazıcı']::text[], 8.5, '{"poet":"Lütfi İhsan Yazıcı","poet_slug":"lutfi-i-hsan-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Giderken', 'sen-giderken-lutfi-i-hsan-yazici-ya6fr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen giderken

Analar çocuklarını emziriyordu

Babalar metreslerini öpüyordu üçüncü sınıf otellerin günah kokulu odalarında

Pezevenkler hala avaz avaz plastik aşklar devşirmedeydi delikanlılardan

Ben ilmiğin ucunda, ilmik acılarımdan

Sen giderken

Cıvıl cıvıldı çarşı pazar

Vitrinlerde kocaman karflerle yazılmış indirimler

Üç kuruşa beş kuruşluk sevdalar pazarlayan işportacılar

Yüreğimde bileşik faiz gibi artan acılar

Sen giderken

Polisler ürküyordu

Gazeteler faili meçhul bir cinayeti daha yazıyordu satır aralarında

Askerler uygun adım ilerlemekteydi

Özgürlük kimin umrundaydiki, bi şekilde zaman geçmekteydi

Sen giderken

Politik bültenle yayınlanıyor

Bu bültenlerde değme mizah yazarları çatlatılıyordu hasetten

Değerli koltuklara değmeyecek adamlar aranıyordu

Kimse aldırmıyordu

Velhasıl aşkım sen giderken de bişey değişmedi

Hatta gittiğini bile kimse farketmedi

Bitti', 'Sen giderken Analar çocuklarını emziriyordu Babalar metreslerini öpüyordu üçüncü sınıf otellerin günah kokulu odalarında Pezevenkler hala av...', ARRAY['Türk Edebiyatı','Şiir','Lütfi İhsan Yazıcı']::text[], 8.5, '{"poet":"Lütfi İhsan Yazıcı","poet_slug":"lutfi-i-hsan-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sen-giderken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam', 'adam-lutfi-i-hsan-yazici-hd875', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Camdan bakarken gördüğü çocuğa daldı gözleri

O misketlerini toplarken

Belli belirsiz,çocukluğunu yaşadı bi süre

Artık iyice eskimiş koltuğuna oturdu

Ve usulca yumdu gözlerini genç adam

Sessizliği bozan hiç bir şey yoktu

Derin bir nefes aldı sigarasından 

Ve kaybolmak ister gibi üfledi dumanını boşluğa

Doğruldu sonra

Duvarda asılı resme ve son mektuba baktı

Terliklerini gördü

Ne kadarda çok severdi onları

Hep sıcak tutardı ayaklarını..

Ve hep yumuşaktılar ona karşı

Ve hiç itiraz etmemişti

Hediye ederken yanaklarından öpmüştü genç adamı

Genç adam utanmıştı..

Mutfağa yöneldi sonra

Günlerdir yıkanmamış bulaşıklar

Ocağın üzerinde sabahtan kalma sahanda yumurta

Ve ocak!

Gazı açtı

Oysa elinde ocağı yakmak için kibrit yoktu

Yemek pişirmeyide düşünmüyordu

Ve yıllardır büyük bir keyifle içtiği çay saatide deildi

O yinede gazı açmıştı

Derin derin soludu havayı

Artık yeter diyordu içinden

Artık yeter!

Düşünceleri birbirine karışıyordu giderek

Yaşamını yaşıyordu tekrardan

Ve dışardan

Sonra

Sonra birden fal taşı gibi açıldı gözleri

Belli belirsiz bir tebessüm belirdi dudaklarında

Parasını ödemediği için doğalgaz''ı kesmişlerdi

Gülmeye başladı

Paltosunu giydi

Ve misket oynamaya gitti', 'Camdan bakarken gördüğü çocuğa daldı gözleri O misketlerini toplarken Belli belirsiz,çocukluğunu yaşadı bi süre Artık iyice eskimiş koltuğun...', ARRAY['Türk Edebiyatı','Şiir','Lütfi İhsan Yazıcı']::text[], 8.5, '{"poet":"Lütfi İhsan Yazıcı","poet_slug":"lutfi-i-hsan-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesin Olmadıgı Yerde Ben Yokum', 'sesin-olmadigi-yerde-ben-yokum-bahri-karaduman-fs8ot', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ezgilerin bittigi yerdeydi karanlık

 Sessizlik ve yalnızlık

 Uzak iklimlerin soğuklugu içinde her yanım

 Sesleri yitirmemeliyim ben

 ezgi sesi

 dost sesi

 dostluk sesi

 sesler duymalıyım ben

 Önce ses olmalı yaşamda

 sevgili sesi

 sevgi sesi

 insan sesi

 Önce ses olmalı yaşamda

 Sesler duymalıyım ben', 'Ezgilerin bittigi yerdeydi karanlık  Sessizlik ve yalnızlık  Uzak iklimlerin soğuklugu içinde her yanım  Sesleri yitirmemeliyim ben  ezgi se...', ARRAY['Türk Edebiyatı','Şiir','Bahri Karaduman']::text[], 8.5, '{"poet":"Bahri Karaduman","poet_slug":"bahri-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sesin-olmadigi-yerde-ben-yokum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlizligin icinde giden hasretim', 'yanlizligin-icinde-giden-hasretim-emre-erkut-hfwwq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanlizligin yolunda gidilen hasretim 

Sessizligin adinda soylenen bir soz 

Saatler icinde dusuncelerim var sessizligim kadar 

Gunesin isigi ayin rengiyim sicakligi yansitan 

Ozlemlerin arasinda bocalayan gurbetim ben 

Biraktigim issiz coller gidilebilen en uzak yolum 

Sonsuzlugum  var benim yildizlar gibi parlak 

Seni yansitirim arkadas bir ney gibi ugultusunda nefesin 

Turkusunu soylerim soylenmemis en guzelini 

Kokusunu alirim izlerim var benim nice toprak derim 

Asigim bir gece gibi yildizlarina ..

Severim bir deniz gibi yasattiklarimi 

Icten ice kararmis ruhum isigim ben seni aydinlatirim 

Birak gidebildigi kadar gitsin duslerin 

Senide terkeder sabir cektigin dertler

Kendi icinde yarat en guzelini orda dusunme 

Ne geriyi ne ileriyi zaman alip goturmus benligimi 

Nefesiyle yol aliyorum tanrinin bugun öldüm dedigimde yeniden dogmusum 

Yoklugun kara carsaflari dolanmis onume 

Dikenli dedigim her yol bir gul bahcesi oysa 

Pamuklar icinde yurudugum cennetim 

Atesler icinde yokluga alevlere atilmis yasam mektubum 

Yanlizligin icinde giden hasretim ben', 'Yanlizligin yolunda gidilen hasretim  Sessizligin adinda soylenen bir soz  Saatler icinde dusuncelerim var sessizligim kadar  Gunesin isigi ...', ARRAY['Türk Edebiyatı','Şiir','Emre Erkut']::text[], 8.5, '{"poet":"Emre Erkut","poet_slug":"emre-erkut","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yanlizligin-icinde-giden-hasretim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geliyorum', 'geliyorum-yasin-aksakal-1zshq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geliyorum sana çığ gibi tutabilecekmisin?

Gözlerim kapalı ellerim sende tutsak 

Bedenim esir 

Geliyorum sana çığ gibi tutabilecekmisin?

Karşına çıksam  beni anlayabilecekmisin 

Soruyorum sana iyi düşün 

Ben bir kere dünyaya geldim 

Ve bir kere aşık oldum 

Geliyorum sana  sadece 

Bekle', 'Geliyorum sana çığ gibi tutabilecekmisin? Gözlerim kapalı ellerim sende tutsak  Bedenim esir  Geliyorum sana çığ gibi tutabilecekmisin? Karş...', ARRAY['Türk Edebiyatı','Şiir','Yasin Aksakal']::text[], 8.5, '{"poet":"Yasin Aksakal","poet_slug":"yasin-aksakal","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/geliyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimi İstiyorum', 'kendimi-i-stiyorum-tolga-baydar-tzn3o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hatıralarla avunmak yetmiyor artık bana,

''Şimdi'' yi, ''doğru'' yu yaşamak istiyorum,

Koklamak, tadına varmak istiyorum,

Yapamıyorum,

Kendimi istiyorum.

Bir labirentte kaybolmuşcasına,

Bir sağa, bir sola yalpalayan sarhoşmuşcasına,

Uçsuz bucaksız bir deryanın, ortasındaymışcasına,

Yalnız, yapayalnızım ben,

Bulmak istiyorum,

Kendimi istiyorum.

Sevgi ateşi yüreğimde değil,

Beynimde yanıyor,

Vücudum, en ücra köşesine kadar,

Titriyor,

Gaipten bir ses ''kendine gel'' diyor,

Gelemiyorum,

Kendimi istiyorum.

''Ne olacak?'' diye bakınmadan çevreme,

Dalıveriyorum bir girdabın içine,

Dönüyor, dönüyor, dönüyorum,

Ulaşamıyorum,

Kendimi, kendimi istiyorum.....', 'Hatıralarla avunmak yetmiyor artık bana, ''Şimdi'' yi, ''doğru'' yu yaşamak istiyorum, Koklamak, tadına varmak istiyorum, Yapamıyorum, Kendimi i...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kendimi-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deliyim', 'deliyim-tolga-baydar-8bki9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karalar giymiş bir deliyim bu dünyada,

Herşeye el atan, ön plana çıkan,

''Ne olacak, sonu nereye varacak?'' diye sormadan,

Ölümcül bir hastalığa yakalanmış,

Kurtulmaya imkanı olmayan,

Karalar giymiş bir deliyim bu dünyada.

Sorumsuz davrananların ardından,

Sözde insan olan insanların arasından,

Süzülerek geçtim,

Bu hale geldim.

Beynimde şimşekler çakıyor,

Başım dönüyor,

Midem bulanıyor yapılanlar karşısında,

Aptal yerine konmak hoş değil,

Neler dönüyor anlamamak zor değil,

Karalar giymiş bir deliyim bu dünyada.

Yemin etmiştim,

Çalışacağım,

Yararlı olacağım diye söz vermiştim,

Ama midem bulandı yaptıkları karşısında,

Karalar giymiş bir deliyim bu dünyada.', 'Karalar giymiş bir deliyim bu dünyada, Herşeye el atan, ön plana çıkan, ''Ne olacak, sonu nereye varacak?'' diye sormadan, Ölümcül bir hastalı...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/deliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
