INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cigarayı Attım Denize', 'cigarayi-attim-denize-cemal-sureya-oucl2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi bir güvercinin uçuşunu bölüyoruz

Gökyüzünün o meşhur maviliğinde

Uzun saçlı iri memeli kadınlarıyla

Bir akdeniz şehri çıkabilir içinde

Alıp yaracak olsa yüreğini

Şimdi bir güvercinin

Şimdi sen tam çağındasın yanına varılacak', 'Şimdi bir güvercinin uçuşunu bölüyoruz Gökyüzünün o meşhur maviliğinde Uzun saçlı iri memeli kadınlarıyla Bir akdeniz şehri çıkabilir içinde...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cigarayi-attim-denize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Ben', 'daha-ben-cemal-sureya-jpr7t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Daha ben ilk kazmayı vurmadan

Elime gelen Karabitki''li testi,

Nefertiti''nin mutfağı sayılan yerde

Koyu sır yeni h
..........
..........', 'Daha ben ilk kazmayı vurmadan Elime gelen Karabitki''li testi, Nefertiti''nin mutfağı sayılan yerde Koyu sır yeni h .......... .............', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/daha-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dikkat, Okul Var!', 'dikkat-okul-var-cemal-sureya-ujrcb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şanssız mıydık? haksızlık olur şimdi

Düşünsene nasıl geçmiştik hızla

Birleşen iki güvercinin arasından

Hiç dokunmaksızın onlara

Bende tarçın sende ıhlamur kokusu 

Az mı dolandık Başkentin sokaklarında', 'Şanssız mıydık? haksızlık olur şimdi Düşünsene nasıl geçmiştik hızla Birleşen iki güvercinin arasından Hiç dokunmaksızın onlara Bende tarçın...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dikkat-okul-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevap', 'cevap-resul-efe-4x7hq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“Herşey bitti”

dediğin anda,

Bir gül kök salar damarlarında.

Her şey biter, 

Bir şey bitmez...

Sımsıkı sarılman gereken, 

“hayat”...

‘Yazmıştın bana hatırlıyormusun,

İşte sana cevabım

bunu zaten sen de biliyorsun...’

Hayat uğrunda yaşadığın

Bir şey varsa güzeldir.

Ve o gül,

besleyeni varsa gülümser

Hayat’a.

Eğer yoksa;

Solmuş, bitmiş bir halde

Yazılır kara toprağa....

O toprak ki!

Kabul bile etmez seni,

Yaşamakta çok görülmüştür,

Ölmekte 

O’na...

Sevgiliden ‘ah’ almışı

Yatırır mı,

Bağrına?...', '“Herşey bitti” dediğin anda, Bir gül kök salar damarlarında. Her şey biter,  Bir şey bitmez... Sımsıkı sarılman gereken,  “hayat”... ‘Yazmış...', ARRAY['Türk Edebiyatı','Şiir','Resul Efe']::text[], 8.5, '{"poet":"Resul Efe","poet_slug":"resul-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cevap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düello', 'duello-cemal-sureya-kqpiy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir düelloda

Daha büyük bir şey vardır

Ve daha acıdır bu

Ölümden de ölüm korkusundan da

Bakarsın dün en güvendiğin kişi

Karşı tarafı
..........
..........', 'Bir düelloda Daha büyük bir şey vardır Ve daha acıdır bu Ölümden de ölüm korkusundan da Bakarsın dün en güvendiğin kişi Karşı tarafı ..........', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/duello-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlığın acısı mı, Sensizliğin sancısı mı?', 'yanlizligin-acisi-mi-sensizligin-sancisi-mi-resul-efe-dgm9k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'I

Bilmem;

Bir türlü karar veremedim.

Zaten bunun üzerine, 

hiçbir şey de yazamadım.

Kalem aldım unuttum 

bıraktım hatırladım.

Ama yazamadım.

Baş işte, 

bir bölümü böyle geçti şiirin.

İkinciside böyle gider...

                           II

Ama düşünüyorum da,

Her zaman yanızdım.

Ne bir ağrım oldu,

nerde bir sancım.

Fakat,

Sensizliğim oldu 

Şimdi de öyle. 

Bir sancı var kalbimin sol köşesinde

Yok yok

Tam ortasında

Kalbimi tutarak eğiliyorum,

Bu seferde yanlızlığım geliyor aklıma...

Senden olan yanlızlığım.

                         III

Ve karar verdim.

Ey sen!

Evet sen!

Bu ne yanlızlık acısı

Ne de normal bir miğde ağrısı..

Bu sadece ne biliyormusun?

Bu sadece 

Sensizliğin..............', 'I Bilmem; Bir türlü karar veremedim. Zaten bunun üzerine,  hiçbir şey de yazamadım. Kalem aldım unuttum  bıraktım hatırladım. Ama yazamadım....', ARRAY['Türk Edebiyatı','Şiir','Resul Efe']::text[], 8.5, '{"poet":"Resul Efe","poet_slug":"resul-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yanlizligin-acisi-mi-sensizligin-sancisi-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşdeğeriyle Yan', 'esdegeriyle-yan-cemal-sureya-r87vm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eşdeğeriyle yanyana yürürken

