INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Var Bütün Kelimelerin Altında', 'kan-var-butun-kelimelerin-altinda-cemal-sureya-nxiz4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'posta arabalarından söz et bana

kan var bütün kelimelerin altında

ezop''un şu lanetli dilinden söz et

kan var bütün kelimelerin altında

umulmadık bir gün olabilir bugün

aslan kardeşçe uzanabilir kayalıklara

bir çay söyle yağmurların kokusunda

kan var bütün kelimelerin altında

işte durup dururken şurda

bir yelpaze gibi açıldı sesin

güzün en gürültülü kanadında

göğün en ince dalında

kan var bütün kelimelerin altında

umulmadık bir gün olabilir bugün

bir çeşme gibi akabilir cumartesi', 'posta arabalarından söz et bana kan var bütün kelimelerin altında ezop''un şu lanetli dilinden söz et kan var bütün kelimelerin altında umulm...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kan-var-butun-kelimelerin-altinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısa Türkiye Tarihi', 'kisa-turkiye-tarihi-cemal-sureya-qwe8a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'I

Şelaleye

Düşmüştür zeytinin dalı; 

Celaliyim

Celalisin

Celali.

II

Üç anayasa

ortasında büyüdün; 

Biri akasya

Biri gül

Biri zakkum.

III

Türkiye''nin adı, 

Soyadı yasasından ber
..........
..........', 'I Şelaleye Düşmüştür zeytinin dalı;  Celaliyim Celalisin Celali. II Üç anayasa ortasında büyüdün;  Biri akasya Biri gül Biri zakkum. III Tür...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kisa-turkiye-tarihi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Metinlerde Buluştuk', 'metinlerde-bulustuk-cemal-sureya-a6wju', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Metinlerde buluştuk kopkoyu deyimlerde, 

Koşut ve eş zamanlı okuduk kimi kitapları; 

O arada iki de defterimiz ol
..........
..........', 'Metinlerde buluştuk kopkoyu deyimlerde,  Koşut ve eş zamanlı okuduk kimi kitapları;  O arada iki de defterimiz ol .......... .............', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/metinlerde-bulustuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Anne', 'kucuk-anne-cemal-sureya-chr0d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küçük anne, kelepir kız, 

Bir şey söyle bana, 

bana bir laf et ki binlerce, 

Onbinle
..........
..........', 'Küçük anne, kelepir kız,  Bir şey söyle bana,  bana bir laf et ki binlerce,  Onbinle .......... .............', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kucuk-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutsuzluk Gülümseyerek', 'mutsuzluk-gulumseyerek-cemal-sureya-0v0nk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mutsuzluk gülümseyerek gelir, adıyla süslenmiştir; 

Banliyo treninde rastladığımız

Sınav saatini kaçırmış liseli kız,
..........
..........', 'Mutsuzluk gülümseyerek gelir, adıyla süslenmiştir;  Banliyo treninde rastladığımız Sınav saatini kaçırmış liseli kız, .......... .............', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/mutsuzluk-gulumseyerek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
