INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mühür (Anlatmıyorum)', 'muhur-anlatmiyorum-resul-efe-t8igl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acıyorum kendime,

Yokluğunu yediremiyorum

İnsanlara bakamıyorum 

seni görürüm onlarda

bana kızarsın diye...

“Yüzünü bile görmek istemiyorum”

diyiyorsun.

Tutamayıp kendimi,

İki salakça laf söyleyince 

böyle kızıyorsun bana...

Kelimeleri kullanamıyorum sayende,

Sözcükler mühürlenmiş agzima

Cümlelerim zindanda.

Sevgili!

seni haykıramıyorum gönlümce...

İki damla döküyorum gözlerimden

Anlatıyor bu herşeyi. 

Ama ben anlatmıyorum,

Anlatamıyorum seni.

Seni görüyorlar o iki damlada 

düşünüyorum seni verdigim sözleri..

Ama ben anlatmıyorum

Ağlıyorum sızlıyorum 

Ama

Ben anlatmıyorum

Onlar işte onlar,

Sadece iki damla gözyaşi...', 'Acıyorum kendime, Yokluğunu yediremiyorum İnsanlara bakamıyorum  seni görürüm onlarda bana kızarsın diye... “Yüzünü bile görmek istemiyorum”...', ARRAY['Türk Edebiyatı','Şiir','Resul Efe']::text[], 8.5, '{"poet":"Resul Efe","poet_slug":"resul-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/muhur-anlatmiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Piri Reis', 'piri-reis-cemal-sureya-a2m4y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Piri Reis geri çekmiştir haritasını

Azmayı çoktan unutmuştur hayvanlar; 

Başlamıştır Sultanahmet sürüncemesi, 

Kız
..........
..........', 'Piri Reis geri çekmiştir haritasını Azmayı çoktan unutmuştur hayvanlar;  Başlamıştır Sultanahmet sürüncemesi,  Kız .......... .............', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/piri-reis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resim', 'resim-cemal-sureya-ig64g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir savaş: Otlukbeli

Bir mavi: Spartaküs

Bir soru: niçin Spartaküs

Bir kuş: nereye gidiyon kuşu

Bir çiçek: bilmem ki çiçeği

Bir su: şüpheli', 'Bir savaş: Otlukbeli Bir mavi: Spartaküs Bir soru: niçin Spartaküs Bir kuş: nereye gidiyon kuşu Bir çiçek: bilmem ki çiçeği Bir su: şüpheli...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/resim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizin Hiç Babanız Öldü Mü?', 'sizin-hic-babaniz-oldu-mu-cemal-sureya-26dai', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sizin hiç babanız öldü mü? 

Benim bir kere öldü, kör oldum.

Yıkadılar, aldılar, götürdüler.

Babamdan ummazdım bunu kör oldum.

Siz hiç hamama gitt
..........
..........', 'Sizin hiç babanız öldü mü?  Benim bir kere öldü, kör oldum. Yıkadılar, aldılar, götürdüler. Babamdan ummazdım bunu kör oldum. Siz hiç hamama...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sizin-hic-babaniz-oldu-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen''im', 'sen-im-resul-efe-pfl2k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine akşam oldu,

ve sen yine gelmedin...

Etrafımda,

yanlızlığımın rüzgarı.

Bedenim buz kesmiş,

sensizliğimle.

Kalbim, aşkımın şöminesi,

ısıtmaz hiç bir yeri.

O kendi derdinin temsilcisi...

Ellerim,

seni yazar, seni çizer,

Beymin ise zaten hep senle

sen olmasan yaşayamaz

ayaklarım sana götürür beni..

Ecelime.....

Gözlerim,

tüm güzellikleri bırakmış,

senden başka bir şeyi görmez..

Kulaklarım seni işitir...

Ha! Bir de,

seni yaşarım ben

Senim işte!', 'Yine akşam oldu, ve sen yine gelmedin... Etrafımda, yanlızlığımın rüzgarı. Bedenim buz kesmiş, sensizliğimle. Kalbim, aşkımın şöminesi, ısıt...', ARRAY['Türk Edebiyatı','Şiir','Resul Efe']::text[], 8.5, '{"poet":"Resul Efe","poet_slug":"resul-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sen-im-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teknokratlar', 'teknokratlar-cemal-sureya-zfhxh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Butun mimarlar yuksek,muhendisler de

Bir sen kaldin alcak mimar ey Sinan Usta!
..........
..........', 'Butun mimarlar yuksek,muhendisler de Bir sen kaldin alcak mimar ey Sinan Usta! .......... .............', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/teknokratlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimle Sohbet (''O'')', 'kendimle-sohbet-o-resul-efe-0xp4i', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-O''mu geliyor karşıdan?

-Yok, yok.

 O''nun saçları daha düz.

-Ama rüzgar var,

 belki ondandır.

 bak bak O''nun gibi saçlarını düzeltti...

-Ama O''nun beli biraz daha ince.

 Ya baksana bol bişey var üstünde ondandır.

 Ya gerçekten O mu yoksa?

-Yok değil

-O, o

-Yok, yok

-Bu sırt çantasını hiç görmemiştim,

 yeni mi acaba?

-Bak, dedim sana onun böyle çantası yok..

 O değil işte..

-Yeni bence, ya da ben görmedim

-Yok be O değil işte

- O, o baksana

-Yo..., A.. evet O

O,o', '-O''mu geliyor karşıdan? -Yok, yok.  O''nun saçları daha düz. -Ama rüzgar var,  belki ondandır.  bak bak O''nun gibi saçlarını düzeltti... -Ama...', ARRAY['Türk Edebiyatı','Şiir','Resul Efe']::text[], 8.5, '{"poet":"Resul Efe","poet_slug":"resul-efe","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kendimle-sohbet-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üvercinka', 'uvercinka-cemal-sureya-fvve8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Böylece bir kere daha boynunlayız sayılı yerlerinden

En uzun boynun bu senin dayanmaya ya da umudu kesmemeye

Lâleli''den dünyaya doğru giden bir tramvaydayız

Birden nasıl oluyor sen yüreğimi elliyorsun

Ama nasıl oluyor sen yüreğimi eller ellemez

Sevişmek bir kere daha yürürlüğe giriyor

Bütün kara parçalarında

                   Afrika dahil

Aydınca düşünmeyi iyi biliyorsun eksik olma

Yatakta yatmayı bildiğin kadar

Sayın Tanrıya kalırsa seninle yatmak günah, daha neler

Boşun
..........
..........', 'Böylece bir kere daha boynunlayız sayılı yerlerinden En uzun boynun bu senin dayanmaya ya da umudu kesmemeye Lâleli''den dünyaya doğru giden ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uvercinka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Var', 'var-cemal-sureya-ivil2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu senin bulutsu sesin var ya 

Uçtan uca tersyüz ediyor geceyi 

Yataklar var konuşmak için 

Öpüşmek için telefon kulübeleri 

Güneşler var, yıldızlar, samanyolları, 

Karpuzlar gümbür gümbür kapılarda. 

Tanrılar sofrası amma karanlık 

Yiyemem tek lokma yiyemem orda. 


..........
..........', 'Şu senin bulutsu sesin var ya  Uçtan uca tersyüz ediyor geceyi  Yataklar var konuşmak için  Öpüşmek için telefon kulübeleri  Güneşler var, y...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abdal Oldum Şu Alemi Gezerim', 'abdal-oldum-su-alemi-gezerim-cihangir-gulegen-pb3tn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir deniz üstündeyim

içimde bir mevlevi

mor kaftanlar içinde döner döner ha döner

bir sufi nefestir ney

döndükçe semahiler

sürsün deyu arınış üfler üfler ha üfler

eğilir yere derviş

yerden selamlar beni

benim canım bedenden uçar uçar ha uçar

dergaha postu serip

oturmakta keramet

yoksa bağdaşı herkes kurar kurar ha kurar', 'bir deniz üstündeyim içimde bir mevlevi mor kaftanlar içinde döner döner ha döner bir sufi nefestir ney döndükçe semahiler sürsün deyu arını...', ARRAY['Türk Edebiyatı','Şiir','Cihangir Gülegen']::text[], 8.5, '{"poet":"Cihangir Gülegen","poet_slug":"cihangir-gulegen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/abdal-oldum-su-alemi-gezerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara 1', 'ankara-1-cihangir-gulegen-mvwwg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ankara''nın bir köşesi

sokaklardan sakarya

belki çok yakınım

belki de uzaklaşırım gitgide yara

yazdığım hasretimdir

buram buram tüter dumanı

sen beni beklemezsin

ben her türlü düşünü kurarım senin

güneş batar

ay doğar

ay batar

düşümde düşün

tanımadığım şehirlerde daha yalnız

daha aşığım sana', 'ankara''nın bir köşesi sokaklardan sakarya belki çok yakınım belki de uzaklaşırım gitgide yara yazdığım hasretimdir buram buram tüter dumanı ...', ARRAY['Türk Edebiyatı','Şiir','Cihangir Gülegen']::text[], 8.5, '{"poet":"Cihangir Gülegen","poet_slug":"cihangir-gulegen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ankara-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara', 'ankara-cihangir-gulegen-8sr1u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu sokak bana yabancı

Bu şehir sanki düşman

Her köşesi meyhane

İçmesem seni yazacağım

İçsem öleceğim hasretinden

Bu şehri ben hiç sevmedim

Hiç bir yerinde sen yoksun

Gözleri ceylan güzelim', 'Bu sokak bana yabancı Bu şehir sanki düşman Her köşesi meyhane İçmesem seni yazacağım İçsem öleceğim hasretinden Bu şehri ben hiç sevmedim H...', ARRAY['Türk Edebiyatı','Şiir','Cihangir Gülegen']::text[], 8.5, '{"poet":"Cihangir Gülegen","poet_slug":"cihangir-gulegen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ankara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara 2', 'ankara-2-cihangir-gulegen-nacd2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seğmen otel ankara

beşyüzoniki numara 

gönlüm benden çok zengin 

ben gönlümden fukara

düşümde bir ceylan gezer 

derdim ona yaklaşmak 

onun pek kaçtığı yok 

benim yollarım uzak

iki duble rakıyı bir yudumda içmişim 

sevmişim sevilmişim

özleyip özlenmişim 

bir sigara yakmışım 

bir nefeste içmişim 

duman duman tütmüşüm başkent semalarında 

upuzun bir kül kalmış

benden geri tablada

tadım tuzum ıstanbul''da kalmış 

yüreğim nicedir bende değil 

sıcak çayla dağlamışım yaramı 

ondandır ateşimin tüttüğü 

gamı kederi alıp yanıma 

yarimi ıstanbul''da bırakmışım 

bu şehir en büyükse ben kaybolmuşum içinde 

kendimi en çok ıstanbul''da sevmişim

ankara''nın bir köşesi 

iki gözüm göğe dalmış

yarim benden uzaklarda 

iki damla yaşım akmış 

bir kız sevdim haberi yok 

sabah seher vakti yatmış

ne denizdir boğulduğum 

ne dumandır ankara 

bir ceylan gözlü kızdır 

içinde kaybolduğum 

ışıklar yanıl söner 

ben gitgide daha karayım

bulutlar gölgeler yar

ben nicedir bir gölgeyim 

gözleri ceylan güzelim', 'seğmen otel ankara beşyüzoniki numara  gönlüm benden çok zengin  ben gönlümden fukara düşümde bir ceylan gezer  derdim ona yaklaşmak  onun p...', ARRAY['Türk Edebiyatı','Şiir','Cihangir Gülegen']::text[], 8.5, '{"poet":"Cihangir Gülegen","poet_slug":"cihangir-gulegen","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/ankara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bahar Hüznü', 'bir-bahar-huznu-cihangir-gulegen-3s7vm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni sevmek bir bahar hüznü gibi gelip geçmedi 

daima bir köşemde boynu bükük kaldı 

olur olmaz yerde birden geliyordun aklıma 

tamamen hatırlıyordum seni 

bir an olsun taşarcasına yaşıyordum 

uzaktın uzaktım uzaktık 

sen bitirmiştin herşeyi ya bende kalmıştın biraz 

her an seni yaşamak yerine azar azar 

biriktirip dolu dolu yaşıyordum seni bir an bile olsa arasıra 

bir dost gibi ve özlemle sarılırdın bana bir dost gibi ama 

geçmişte hatırlar mıydın bendeki seni 

yoksa tamamen sildiğin beni doğru muydu 

ama bilirim yapmazsın sen öyle şeyler 

ve hatta hiç yapmadın 

beni sevmedin sevgili gibi ama dosttun benimle seni delicesine severken 

ben ölürken gözlerinde sen yanaklarımı okşardın bilirsin 

beni nasıl aşık ettin kendine simsiyah 

nasıl hiç aşık olmadın bana 

seni sevmek bir bahar hüznü gibi gelip geçmedi 

ara sıra bir nisan yağmuru gibi geçerdin ya gözlerimden 

topraklarda mis koku camlarda buğu olurdun ya 

ben seni severken sen nerdeydin peki 

söylerken seni ne çok sevdiğimi söyleylesemde bilmedin 

herşeyi anlardı o cin gibi gözlerin hani 

gözlerin hani şimdi 

erirken hasretinle nerdeydin 

niye öperdin beni her görüşünde özür mü dilerdin geç mi kalmıştın yoksa anlamakta pişman mıydın 

bilir miydin gözlerimin rengini kokumu sıcaklığımı 

seni sevmek bir bahar hüznü gibi gelip geçmedi 

oysa şimdi evlenip gideceksin bilirim 

bir arbesk hüzne bırakacaksın beni yine 

bir an olsun takılacaksın boğazıma 

hiç bir garezin olmadan gayet dostane 

düğününe çağıracaksın beni 

peki ya ben öldürebilecek miyim içimdekileri 

arasıra benim oluyordun hiç değilse düşlerimde arasıra olsa bile ne güzeldin 

hiç kimsenin değildin ya en azından resmen 

seni arasıra öyle yoğun özlüyorum ki herşeyine razıyım kimi zaman beni asla sevmemene bile 

gecelerimde yaşıyorum seni paramparça gecelerime yazıyorum gözlerini 

hele o yaşlı gözlerini 

anlar mısın beni bu küçük çocuğu hatırlar mısın yada 

seni öylesine özlerken uzaktan nasıl koşamazdım nasıl sarılamazdım sana bilir misin 

seni sevmek bir bahar hüznü gibi gelip geçmedi 

ama eğer yazmazsam seni arasıra dayanamazdım asla yokluğuna 

bir an sarhoş olmak gibi seni bir an hatırlamak 

uçmak gibi dağların üzerinde hiç kanat çırpmadan bir kartal gibi uçmak gibi 

seni sevmek güzeldi bir zamanlar 

seni sevseydim eğer hala o kadar deli hayat nasıl olurdu bilmem ya 

arasıra hatırlamak seni ve sanki benim olman bir ağız tadı gibi 

ya evlenmen nasıl olacak onu bilmem seni mutlu görmek nasıl olur acaba 

bir başkasıyla demeye dilim varmıyor ya bir başkasıyla 

yedi yıllık hayalim bir anda toz olacak bir bülbüli evet''le 

bir tek o an sesini sevmeyeceğim eminim 

bahar mıydı bilmiyorum seni ilk sevdiğimde 

ama her mevsimde mutlaka sevmiştim seni 

şimdi arasıra düşünmek seni güzel 

hala büyümedi mi acaba bu çocuk koca doktor oldu hatta 

hala beyaz güle bakamam bilir misin hep seni hatırlatırlar bana 

ya seni görürsem ne olacak bembeyaz bir gül gibi 

seni sevmek bir bahar hüznü gibi gelip geçmedi 

ne yapayım', 'seni sevmek bir bahar hüznü gibi gelip geçmedi  daima bir köşemde boynu bükük kaldı  olur olmaz yerde birden geliyordun aklıma  tamamen hatı...', ARRAY['Türk Edebiyatı','Şiir','Cihangir Gülegen']::text[], 8.5, '{"poet":"Cihangir Gülegen","poet_slug":"cihangir-gulegen","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/bir-bahar-huznu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Vakti Şiiri', 'gece-vakti-siiri-cihangir-gulegen-2qqxh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dolaşır gecede ayak sesleri

birileri bir yerlere gider

sinmiş köşelere börtü, böcek, kuş

korkular karanlığı bekler

rüzgarlar dolaşır caddelerde

herşey hep seni söyleşir

nereye gidilir şimdi

şimdi ne yapılır

kaçsan bile kendinden

kovalarsın kendini

tüm sığınaklarında sen

yine bulursun kendini', 'dolaşır gecede ayak sesleri birileri bir yerlere gider sinmiş köşelere börtü, böcek, kuş korkular karanlığı bekler rüzgarlar dolaşır caddele...', ARRAY['Türk Edebiyatı','Şiir','Cihangir Gülegen']::text[], 8.5, '{"poet":"Cihangir Gülegen","poet_slug":"cihangir-gulegen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gece-vakti-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgeler', 'golgeler-cihangir-gulegen-16xq5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'güneşe giden yol bu gece karanlık

giderek uzuyorum karanlığın içinde

kimileri gölge diyorlar silüetime

oysa ben biliyorum ki gölgeler hep içimde

yaprak dökümü gibi yaşıyorum

dallardan döküle döküle..', 'güneşe giden yol bu gece karanlık giderek uzuyorum karanlığın içinde kimileri gölge diyorlar silüetime oysa ben biliyorum ki gölgeler hep iç...', ARRAY['Türk Edebiyatı','Şiir','Cihangir Gülegen']::text[], 8.5, '{"poet":"Cihangir Gülegen","poet_slug":"cihangir-gulegen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/golgeler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşı Kıyı', 'karsi-kiyi-cihangir-gulegen-sczp6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çıktım 

karşı kıyıya baktım uzun uzun 

deniz vardı 

ay vardı 

sen yoktun 

durdum 

uzun uzun durdum kıyısında denizin 

bekledim 

belki kokunu 

belki bir tel saçını getirir diye rüzgar 

ay 

halimi takmaz gibi kurulmuş 

deniz benden deli 

ben denizden çılgın 

eski dostlar bulutlar da nerdeler 

karşıda simsiyah uzanır karşı kıyı 

deniz, rüzgar, ay burada 

sen yoksun', 'çıktım  karşı kıyıya baktım uzun uzun  deniz vardı  ay vardı  sen yoktun  durdum  uzun uzun durdum kıyısında denizin  bekledim  belki kokunu...', ARRAY['Türk Edebiyatı','Şiir','Cihangir Gülegen']::text[], 8.5, '{"poet":"Cihangir Gülegen","poet_slug":"cihangir-gulegen","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/karsi-kiyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neşeli Şiir', 'neseli-siir-cihangir-gulegen-26hja', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir büyülü karanlIk

çok küçücük yıldızlar

bir tepenin üstünde varlığınla ısındım

birkaç damla ışıkta bakabildim yüzüne

bilirdim yerlerini dalardım gözlerine

sonra parmaklarımla

yüzünün resmini çizdim yine yüzüne

uğramadan inadına elem, keder, hüzüne

neredeyse öpecektim inanıpta kendime

ben çok yokluklar yazdım

hepsi de çok güzeldi

ama bu kez tir-i müjen

kalbimi fena deldi

artyk şiir cıvıdı yap yareme pansuman

nerdeyse öpecektim

şahit buna asuman', 'bir büyülü karanlIk çok küçücük yıldızlar bir tepenin üstünde varlığınla ısındım birkaç damla ışıkta bakabildim yüzüne bilirdim yerlerini da...', ARRAY['Türk Edebiyatı','Şiir','Cihangir Gülegen']::text[], 8.5, '{"poet":"Cihangir Gülegen","poet_slug":"cihangir-gulegen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neseli-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine 1', 'oylesine-1-cihangir-gulegen-unrun', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ellerimde koskocaman kırıklar

camlar ardında kalmış şimdi arzular

yok, biliyorum yok artık umutlar

artık çalınmıyor bu bahçede

ne nihavent ne uşşak şarkılar.....', 'ellerimde koskocaman kırıklar camlar ardında kalmış şimdi arzular yok, biliyorum yok artık umutlar artık çalınmıyor bu bahçede ne nihavent n...', ARRAY['Türk Edebiyatı','Şiir','Cihangir Gülegen']::text[], 8.5, '{"poet":"Cihangir Gülegen","poet_slug":"cihangir-gulegen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/oylesine-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seyirlik', 'seyirlik-cihangir-gulegen-z9qtu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Satırlar yorgun ve dağınık

Çıkmaz sokakalarda dolaşır şimdi şiir...

Karanlık bir ilişkinin şarkısı

Denizler dalgalardan yorgun

martılar uçmaktan...

Sabahlara çıkar geceler

Bir eli çenesinde oturmuş beni seyreder bir güzel

Eli çenesinden

Çenesi elinden güzel

Gözlerime çöker bulutların ağırlığı', 'Satırlar yorgun ve dağınık Çıkmaz sokakalarda dolaşır şimdi şiir... Karanlık bir ilişkinin şarkısı Denizler dalgalardan yorgun martılar uçma...', ARRAY['Türk Edebiyatı','Şiir','Cihangir Gülegen']::text[], 8.5, '{"poet":"Cihangir Gülegen","poet_slug":"cihangir-gulegen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seyirlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sufi 1', 'sufi-1-cihangir-gulegen-w6cpr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir deniz üstündeyim

içimde bir mevlevi

mor kaftanlar içinde döner döner ha döner

bir sufi nefestir ney

döndükçe semahiler

sürsün deyu arınış üfler üfler ha üfler

eğilir yere derviş

yerden selamlar beni

benim canım bedenden uçar uçar ha uçar

dergaha postı serip

oturmakta kermet

yoksa bağdaşı herkes kurar kurar ha kurar', 'bir deniz üstündeyim içimde bir mevlevi mor kaftanlar içinde döner döner ha döner bir sufi nefestir ney döndükçe semahiler sürsün deyu arını...', ARRAY['Türk Edebiyatı','Şiir','Cihangir Gülegen']::text[], 8.5, '{"poet":"Cihangir Gülegen","poet_slug":"cihangir-gulegen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sufi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen misin ? İnanmam', 'sen-misin-i-nanmam-turgut-yuca-x6abw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen misin ? İnanmam bu karşımda duran 

Bütün insaniyetine karşın aldanmam.

Aldanmam sahte sözlere senden sonra

Öyle bitirdin ki beni artık dayanmam.

Bundan sonrasını düşünmeden;

Seni ölüm döşeğinde görmeden 

Sana ''''sensin'''' demeden;

Ve seni öyle bitirmeden

Vallahi aldanmam.

Bilmiyor musun ne yaptığını?

Biliyor; konuşmuyor musun yoksa?

Bildiğin herşeyi saklıyorsun yine 

Eskiden bir gün önce.

Sana bir daha inanmam 

Bu hayatımın hatsı olsada

Sana bir daha kanmam

Masum melek... Hah inanamam.

Sen sen sen .....offf sen

Hayır yaklaşma anılarıma.

Sakın acıtma bir daha canımı

Lütfen yapma bir daha.

Günlerimi çaldın benim en güzel.

En güzel olanlarını benden kopardın.

Neden?

Diye sorsam... Cevap beklemem.

Yalnızlığımla bırak beni.

Acak onunla anlaşabilrim ben 

Sensiz....

Sessizz.

Hiç bir şey istemem ...

Sensizlikten başka. Hiç birşey.

Yalnızca git yeter.', 'Sen misin ? İnanmam bu karşımda duran  Bütün insaniyetine karşın aldanmam. Aldanmam sahte sözlere senden sonra Öyle bitirdin ki beni artık d...', ARRAY['Türk Edebiyatı','Şiir','Turgut Yuca']::text[], 8.5, '{"poet":"Turgut Yuca","poet_slug":"turgut-yuca","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sen-misin-inanmam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ev', 'bir-ev-turgut-yuca-poshj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir evim var benim.

Senin olamayan artık

Eskiden seninleyken..

Şimdi sensizlikten 

Çatısından hüzün damlıyor bak.

Çeşmesinden gözyaşı.

Bahçesinde hüzün var.

Avlusunda matem, yine gözyaşı.

O evin penceresini ellerin açardı.

Kapısını ellerin.

Ellerin senin.

Sadece senin ellerin

Seninleyken çok sevdiğim evim

Şimdi her köşesinden nefret ettiğim.

Bir evim var benim.

Sensiz. Sevmediğim istemediğim.', 'Bir evim var benim. Senin olamayan artık Eskiden seninleyken.. Şimdi sensizlikten  Çatısından hüzün damlıyor bak. Çeşmesinden gözyaşı. Bahçe...', ARRAY['Türk Edebiyatı','Şiir','Turgut Yuca']::text[], 8.5, '{"poet":"Turgut Yuca","poet_slug":"turgut-yuca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-ev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-adil-koruyan-gh41s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mayıs’ın beş’ini...

Gözlerim kapalı, düşünüyorum seni. 

Kokunu, gözlerini, dağılmış saçlarını, 

dudaklarını, dökülen sözcükleri, 

kollarımdaki varlığını. 

Sarılıyorum. 

Sanki o anı yaşıyorum. 

Doyamıyorum. Doyasım gelmiyor. 

Seni arzuluyorum...Özlüyorum... 

Hakkım yok biliyorum, 

Ama seni seviyorum....', 'Mayıs’ın beş’ini... Gözlerim kapalı, düşünüyorum seni.  Kokunu, gözlerini, dağılmış saçlarını,  dudaklarını, dökülen sözcükleri,  kollarımda...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ozlem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aaaa', 'aaaa-edip-cansever-3notv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir Suleyman gordum hicbir yani kimildamiyor

Oturmus bir iskemleye

Pek de oturmuslugu yok iskemle ayaksiz

O nasil sey, bu adam soyut mu ne

Baksan bir ilgisi var elleriyle

Uzamis uzamis uzamis dogrusu elleri

Sevmeye domuzlaniyor gittikce

Konustum konusmuyor

Durttum durtulmuyor

Kizdim, bir bicak salladim karnina

Aaaa!

Yok yahu bana misin demiyor

Sasirdim, yokladim kendimi iyice

Bir cag mi degistik sabah sabah ne

Artik olum insanlardan olmuyor.', 'Bir Suleyman gordum hicbir yani kimildamiyor Oturmus bir iskemleye Pek de oturmuslugu yok iskemle ayaksiz O nasil sey, bu adam soyut mu ne B...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aaaa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönelim', 'donelim-edip-cansever-kmxhr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dönelim

Döndürsün bizi

Kalbin akıp giden bulutlara benzeyen sesi

Yağmursuz bir yağmura açılmış kapılardan

Ve akılda kalan bir yokuştan

Ve yalnız çocuklara özgü o sonsuz sinema koltuklarından

Ve çocukluktan

Dönelim

Dönelim mi biz

Gençlikten, oralardan

Mutluluğu bir kabuk gibi saran mutsuzluklardan

Dönelim mi acıya

Acıya, büyük acıya

Ve soralım mı acaba

Ey büyük yalnızlık insansan eğer

Bir kaya

Dalgalar yalarken onu

O bakarken kaskatı kalabalıklara

Ah, kalbin bulut bulut akan sesi.

Bütünüyle bir semte benziyor Ruhi Bey

Binlerce, on binlerce kedinin hep birden kımıldadığı

Kedilerden örülmüş birsemte

Ve soğuk bir tuvalde yerini bulamamış renkler gibi

Soğuk ve ayakta tutan çelişkileri

Bir görünümden bir başka görünüme kolayca sıçranan

Her şeyin, ama herşeyin çok dıştan farkedildiği

Eh belki de bir satır fazlalığı ya da bir satır eksikliği

Belki de genç bir şairden ödünç laınan.

Yürüyor mu, yürümeyi mi düşünüyor Ruhi Bey

Düşünmesi daha mı sonra koyuluyor yola

Nereye gidecek ama, nereye varacak sanki

Yoksa bir oyun tadı mı buluyor bunda

Oyundan atılmaktan korkmayan bir oyuncu gibi

Boşvermiş de sanki oyunun kurallarına

Üstelik son bölümde, perdenin kapanmasına

Azıcık vakit kalmış

Ya da vakit var daha. Ama ne çıkar

Gövdenin yazgıya başkaldırması mı

Ruhi Beyin

Başkaldırması mı yoksa

Vaktinden önce anlamanın şaşkınlığı mı

Vaktinde anlamanın sevinci mi

Ya da biraz geç kalmanın

O gereksiz tedirginliği mi

Hangisi

Ama belli ki sonundayız her şeyin

En sonunda.', 'Dönelim Döndürsün bizi Kalbin akıp giden bulutlara benzeyen sesi Yağmursuz bir yağmura açılmış kapılardan Ve akılda kalan bir yokuştan Ve ya...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/donelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Funda Oteli Koy', 'adini-funda-oteli-koy-edip-cansever-j52w1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Adini funda oteli koy

Aklindan gelip gecen bir yazin

Ve aksam guneslerinde orda burda

Bir deniz kiyisinda, eski bir yikintida

Ince ince gezinen turuncu adamlarin.

Adini funda oteli koy

Sevdamizin da adini

Ayaklari dibinde gun batiminin.

Ve agzinda binlerce gunesin tadi

Dilinin ucunda yalnizca kendi adin.

Cunku sevdikce beni sen kendini tanidin.', 'Adini funda oteli koy Aklindan gelip gecen bir yazin Ve aksam guneslerinde orda burda Bir deniz kiyisinda, eski bir yikintida Ince ince gezi...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/adini-funda-oteli-koy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aluminyum Dükkan', 'aluminyum-dukkan-edip-cansever-uyvbe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir goz atiyorum denize

Cin cin otuyor baliklar

Bu bir giyilmis ayakkabidir diyorum

Bu bir sulanmis peynirdir diyorum

Bu bir haslanmis patates elinizdeki

Bu insandaki ezgi

Bu insandaki akil

Bu kanundur kanun

Cilegin cilek olusu gibi.

Iste bu gercektir diyorum siz de bilirsiniz gercegi

Bu civinin cakilisi

Bu ekmegin surulusu

Bu askin, bu ayibin, bu insanin bilinisi

Bu duymak, bu duusnmek, bu yuksunmek insanda

Bu toplum icinde, bu toplum disinda

Bu sizin durumunuz, bu tabiattaki is

Bu akilsiz cicek

Bu bilisiz agac

Bu dupeduz ileri gorus

Bu su, bu nehir, bu ruzgar

Bu tas, bu bulut, bu hava

Bu bilinen, bu bilinmeyen

Bu Isa''dan once, bu Isa''dan sonra.

Iste bu yeninin yenisi insan

Dizilmis kutu

Bukulmus teneke

Aluminyum dukkan.', 'Bir goz atiyorum denize Cin cin otuyor baliklar Bu bir giyilmis ayakkabidir diyorum Bu bir sulanmis peynirdir diyorum Bu bir haslanmis patat...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/aluminyum-dukkan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anısındayım', 'anisindayim-edip-cansever-6yryn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hafifce isirilmis bir elmanin dilindeyim

Elmanin kokusundayim

Anisindayim -kimbilir kimin-

Anilarda gorunur, duslerde gorunmez insan

Duslerde gorunen anlamlardir

Ozelliklerdir bir de belli belirsiz.

Ve

Insansiz ani yoktur. Var midir?', 'Hafifce isirilmis bir elmanin dilindeyim Elmanin kokusundayim Anisindayim -kimbilir kimin- Anilarda gorunur, duslerde gorunmez insan Duslerd...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anisindayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Radyoaktivitesi', 'askin-radyoaktivitesi-edip-cansever-9i2k5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aski duydum mu bir basima kaliyorum

Kasiklarimi ovuyorum bir guzel

En kucukleri var ya ayak parmaklarimin

Ilk pesin onlari goruyorum.

Bir celik mavisi damar tam da cenemin ustunde

Cogu zaman gun isiginda sectigim

Tip tip atiyor yuzumun kenarciginda

Saclarim kapkalin geliyor elime.

Gunduzun, ama tam gunduzun oluyor bu is

Kirlerim, pis kokularim belliyken iyice

Soluyup dururken, birseyler gecirirken aklimdan

Uzanip kaliyorum ta pencerenin dibinde.

Yukariyi dusunuyorum, bir asagi katta olusumdan

Dort duvar, bir buz dolabi, naylona benzer bir gok

Butun o zehir gibiligi sogumus seylerin

Anliyorum bir ask akimidir dolaniyor ustumde.

Durmadan asklaniyorum ama hep boyle

Karanfiller gibi taze omzum, dizlerim, ayaklarim

Toplanip gidiyor derken o deli fisek sey

Gun gibi parliyor tirnaklarim.', 'Aski duydum mu bir basima kaliyorum Kasiklarimi ovuyorum bir guzel En kucukleri var ya ayak parmaklarimin Ilk pesin onlari goruyorum. Bir ce...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/askin-radyoaktivitesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakmalar Denizi', 'bakmalar-denizi-edip-cansever-i70au', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bakmalar goruyorum butun gun turlu bakmalar

Pencere bakmasi, sabahlar bakmasi, yesil otlar bakmasi

Hepsi de beni buluyorlar, hepsi de bir yagmur uysalliginda

Gordum suyunki yumusak, gordum agacinki katı

Gordum ama sey, gordum ama nasil, gordum ama bu kadar goz

Ayni bir gozler denizi, ayni bir o kadar canli.

Bakmalar goruyorum, gok ortasi gibi karsimda

Bulutta goz, ucakta goz, derinlikte goz

Goz oluyorlar birden, bu gozler de yataga ic yapanlari

Masaya ust yapanlari bunlar, atlara atca parlaklik

Yilandan coreklenmeyi, kediden uyusmayi cikaran bunlar da

Iste uzunlardan ayak, iste beyazlar beyazindan kalabaligi

Bakmalar goruyorum durmadan goz olan bakmalar

Baslama gozleri, cocuklu, masalli, sinemali.

Oksama gozleri vardi gel git eden parmaklarima

Asklardan gelenleri aski da bir kullanisli yapan

Caz bakmalari, dugun bakmalari, dudaklar tasiyan bakmalar

Bakmalar, ateste, suda havagazinda

_Atesten, sudan, havagazindandi gozleri-

Kar gozleri, soguk -guzel,bugu gozleri hamamlarda

En harlisi bu: savaslarda, en isiksizi olulerdeki

Bitti gozleri onlar bitti.', 'Bakmalar goruyorum butun gun turlu bakmalar Pencere bakmasi, sabahlar bakmasi, yesil otlar bakmasi Hepsi de beni buluyorlar, hepsi de bir ya...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bakmalar-denizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlangıç', 'baslangic-edip-cansever-uzprw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Doğanın bana verdiği bu ödülden

Çıldırıp yitmemek için

İki insan gibi kaldım

Birbiriyle konuşan iki insan.', 'Doğanın bana verdiği bu ödülden Çıldırıp yitmemek için İki insan gibi kaldım Birbiriyle konuşan iki insan....', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/baslangic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belirsizlikler I', 'belirsizlikler-i-edip-cansever-lrrkl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bahceme gelip bahcemi buyutuyor

Uzaniyor golgesine agaclarimin

Goruyorum onu geceyle gunduzun otesinde

Kuskum yok Pan degil bu.

Bateri caliyor havuzun dibindeki kadin

Belirsiz bir gune yaslanmis

Magaralarindan geciyor balik suruleri

Yetmiyor mu ki

Duslerine odunc veriyor kendini ustelik.

Bir tabak buzlu cilegi siire yerlestiriyorum bense

Gizli kalmasin diye belirsizlik.', 'Bahceme gelip bahcemi buyutuyor Uzaniyor golgesine agaclarimin Goruyorum onu geceyle gunduzun otesinde Kuskum yok Pan degil bu. Bateri caliy...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/belirsizlikler-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belirsizlikler II', 'belirsizlikler-ii-edip-cansever-9bnvg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Golge dolasir geceyle esmerligin arasinda

-Bir an- bakislarin mavi denizle gok arasinda

Bir uyumsundur sen -yazlar gezinir kis gunlerinin icinde-

Sabahlari bir seyler noksandir, aksamlari

Noksanlardan olusan bir uzuncluk sende.

Ortalarda bir yerdesin -oylesin-

Bir kavsaksin nedense - birseyle her sey arasinda-

Gunun her saatinde -duyuyor musun-

Imgeler birbirinden korkuyor.', 'Golge dolasir geceyle esmerligin arasinda -Bir an- bakislarin mavi denizle gok arasinda Bir uyumsundur sen -yazlar gezinir kis gunlerinin ic...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/belirsizlikler-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belirsizlikler III', 'belirsizlikler-iii-edip-cansever-p2zwm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soyle boyle bir gunun kurcalanmasindan

Bir tirnak izidir nehir -yuzumde akan-

Bulutlar bulutlar bulutlar -dudak izleri, beyaz-

Otede bir kopru (ustunden gececegim birazdan.

Ocaktaki caydanliktan bakiyor bana

Ekim ortalarinda yagan karlardan

Ben koprunun usutundeyim simdi -iyi mi-

Camlarin bugusundan yapilmis adam.

Geri ceviriyor bakislarini ansizin

Ben kopruden gectim gittim coktan

Peki

Ne olup bittiydi var mi anlayan.', 'Soyle boyle bir gunun kurcalanmasindan Bir tirnak izidir nehir -yuzumde akan- Bulutlar bulutlar bulutlar -dudak izleri, beyaz- Otede bir kop...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/belirsizlikler-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belirsizlikler IV', 'belirsizlikler-iv-edip-cansever-nty7k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O bir ilk yaz sikayetcisidir

Kat kat altindadir bir leylak esintisinin

Gunessiz kussuz bir kayin ormanini buluncaya kadar.

Yitirmis gorunusunu bu yuzden

Sevgi kadar bolunmus

Ve parcalanmis (evet?) 

Hicbir duygu yoktur diyor.', 'O bir ilk yaz sikayetcisidir Kat kat altindadir bir leylak esintisinin Gunessiz kussuz bir kayin ormanini buluncaya kadar. Yitirmis gorunusu...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/belirsizlikler-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belirsizlikler V', 'belirsizlikler-v-edip-cansever-hgos1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Atlar atlar atlar

Gectiler penceremin onunden

Bugulu cam, bugulu cam, bugulu cam

Gectin penceremin onunden.

Attan, bugulu camdan, dusten..', 'Atlar atlar atlar Gectiler penceremin onunden Bugulu cam, bugulu cam, bugulu cam Gectin penceremin onunden. Attan, bugulu camdan, dusten.....', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/belirsizlikler-v-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bu Kadar Değilim', 'ben-bu-kadar-degilim-edip-cansever-7a9qc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben bu kadar degilim

Kislada olu bir zaman

Bir guzel at durdukca gider

Gittikce doner bir bir guzel at durdukca

Askerim, benim agzim kuslardan.

Gunesi sormuyorum lekelenmis dallardan

Dallari sormuyorum dallardan daha iyi

Yuzumu istiyorum bir suvari alayindan

Ne yapsam istiyorum, ama istiyorum

Bir kisi bile degilim yalnizliktan.

Bir kisi bile degilim yalnizliktan

Gozlerim ormanlara asili

Agaclar, kirlar ve sehirler geciyor kaputumdan

O kadar geciyorlar ki, sadece duruyorum

Bir an bir yede olumu tanimazligimdan.

Ben bu kadar degilim

Kislada olu bir zaman.', 'Ben bu kadar degilim Kislada olu bir zaman Bir guzel at durdukca gider Gittikce doner bir bir guzel at durdukca Askerim, benim agzim kuslard...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-bu-kadar-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ruhi Bey Nasılım', 'ben-ruhi-bey-nasilim-edip-cansever-k0rm4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I

Gördün mü hiç suyun yanmasını tuzda

Gördüm ben bu yaşam boyu iniltiyi

Büyük bahçelerin küçük içinde

Saksılardan birinde

Gördüm de

Uyurken uyandırılmış gibi

Beni bir sardunya büyüttü belki.

O ben ki

Bir kadında bir çocuk hayaleti mi

Bir çocukta bir kadın hayaleti mi

Yalnızca bir hayalet mi yoksa.

Ne peki

Yere dökülen bir un sessizliği mi

Göğe bırakılmış bir balon sessizliği mi

İşini bitirmiş bir org tamircisinin

Tuşlardan birine dokunacakkenki

Dikkati ve tedirginliği mi.

Bekler mi beni

Her yanı, ama her yanı çocuklar gibi gülümseyen

Bir sürü yaz gününün içinde

Acaba bekler mi beni

Uykularım, o sonsuz uykularım

Yanmış bir limonluktaki

- Ve limonlar ki her gün bir yaprak ayininde

Sesini hiç eksiltmeyen -

Ama bilmez miyim ben

Bilmez miyim hiç

Böyle sığ hayallerle oyalanmak yerine

Kısacık bir zaman olmalıydı elimde

Turfanda meyva gibi bir zaman

Yollar yollar kateden tadı ve ekşiliği

Geçerek erguvanların dönemecinden

Leylakların dörtyol ağzından

Yapıştırıncaya dek beni dudaklarına

Acının dudaklarına ve geçmişin

Bir yaban gülü yaprağı gibi beni

Ama ne gezer.

Korkmuyorum artık solmaktan

Solmaktan ve solgunluktan

Gelmişim nerelerden böyle

Kurumuş bir dere yatağı gibi

Ya da pek kurumamış da

Baygın, hasta ya da cançekişen

Çırparaktan yüzgeçlerimi dip sularında

Ya da yer tahtaları, muşamba, örtük perdelerin kasvetini

Yorgun düşerek taşımaktan

Ve ne çıkar ayırmasam kendimi

Suların büyük içkilere kavuştuğu koylardan.

Koylardan

Kapsayan o sevimsiz, o küçük aşkları da

Eskiyen turunçlar gibi ilk rengini pek aratmayan

Ayırmasam kendimi

Diyorum ayırmasam

Köhnemiş bir geminin -izine pek rastlanılmayan-

İçindeki bir yolcudan da, değerli taşlarla dolu cepleri

Cepleri yüreği cepleri

Ayırmasam da ben

Kim görürdü o yolcuyu, yani kim farkederdi beni

Sıradan acılardır çünkü bütün ilgileri toplayan

Oysa sıkıntıyı buruşuk bir iç çamaşırı gibi saklayan

Bu kımıltısız gövde

Görülmemiştir ki hiç görülsün şimdi

Görülmediği gibi gündoğumundan havalanan kuşların

Ya da bir oda kapısını açtığınız zaman

O müthiş öğle sıcağında

Pencerenin önünde örgü ören birinin

- Örgü mü, bir çay bardağını başka başka tutan ellerin becerikliliği mi-

Görülmediği gibi

Ama var mıydı sanki görülmek isteyen

Var mıydı bir şeyler bekleyen yüreğimin eskittiklerinden.

II

Ve her şey hızla yetişti sonra

Sarı bir günün kahverengi yarınına.

Yıkılmış bir ağacın üstünde yıllarca oturdum da

Gözleri avına benzeyen bir avcıydım sanki

Ağaç da çürümüş zaten

Kazımış, oymuş bir yerlerinden gelip geçen onu

Ağaç mı, içi yıllarla dolu bir kutu mu

Çözmek için mi acaba içlerindeki bir gizi

-Gizi mi, bir giz gereksinmesini mi-

Yoklamışlar orasından burasından

Kim bilir.

Ama sessizlikten başka ne bulmuşlar

Önemsiz bir iki anıdan başka

Ya insan kılığında ya da bir dekor taşkınlığında

Sorarım ne bulmuşlar

Çoktan yeni bir umuda dönüşmüştür onlar da

Anılar.

Oysa bambaşka şeyler olmalıydı ağaçta

Kazılmış, oyulmuş yerlerinde ağacın

Buruk mayhoş, daha çok da bir zehir tadındaki

Bir şeyler olmalıydı. Ve sanki

Yıllar var ki saklamışım orda ben

Saklamışım anlaşılan

Odasında yapayalnız doğuran bir kadının

Dışa vurmak istemediği

Ya da pek gereksinmediği

O iniltiyi andıran

Duyurulmayan her şeyi.

III

Ve her şey dönüştü işte

Kahverengi bir çarşambadan

Sapsarı bir cumartesiye.

Ansızın bir rüzgar çıktı demin

Çölde yanıt arayan alaycı bir rüzgar

Kolalı bir örtü gibi acıtıyor yüzümü

Yakıyor gözkapaklarımı da

Toplayıp getiriyor anılarımı bir bir

Uzun yolları hiç sevmeyen anılarımı.

(Kaç türlü girilirdi anılardan içeri? 

1 - İşte bir zambağın özsuyunun içilişi gibi

2 - Süt emer gibi bir memeden

Bütün renklerin ve bütün kokuların bir anda bilinişi

3 - Dibini kazıyor alanlar: dünyanın iç çekişi.) 

(Ansak mı anmasak mı

Yeri mi şimdi değil mi

Bir tren yolculuğunda ve her yerde

Her şeyin ya da hiçbir şeyin hiç mi hiç çekilmezliğini

Bir hafta tatilini, bir öğle vaktini, belki bir pazartesiyi

Saatler iyi

Adamlar gülüyorlarsa iyi, gülmüyorlarsa gene iyi

Ve bütün yolcuların dalgın

Koparıp koparıp bir şeyler yediklerini

Görünüşte kararsız

Görünüşte üzgün, endişeli

Görsek mi acaba, görmesek mi

Açıp da kapalı gözlerini arada

Şöyle bir görünümü tek bir solukta

Yalandan, inatla içine çekenleri

Ya da bir köprüden geçerken, bir tünele girerken

Belirtip yüzlerinde çok görmüşlüğün izlerini

Bir tilki çevikliğiyle, acele

Katarak yolculuğa hiç yoktan bir gizemliliği

Bilmem ki, görmesek mi

Durunca tren bir istasyonda

Dudakları çatlamış, ateşli, hasta bir istasyonda

Dünyanın bütün elma satıcılarına bakıp

Bakıp da her şeyi ilk defa tanıyormuş gibi

Uzanıp pencerelerden sarkık gerdanlarıyla

Tutarak parmaklarıyla yalancı

Ve ucuzundan bir kolyeyi

Acaba görmesek mi

Bir treni ve dünyada tren olan her şeyi.

Ansak mı anmasak mı acaba

Yeri mi şimdi, değil mi

Sırasını bekleyen bir kadının, hasta

Gereğinden fazla abartılmış yüzünü

Besbelli iğrenirdiniz

Çevirirdiniz gözlerinizi yer tahtalarına

Bir duvar saatine ya da kapıya

Telefona bakardınız, tırnaklarını incelerdiniz uzun uzun

Kısaca

Kaçınmak isterdiniz o yüzden -ama bitmedi-

Gördünüz, görüverdiniz bir daha

Sıyrılmış acılardan ansızın

Sevecen, durgun, sade

O yüzü

Belki de, orda, acele

Karar verdiniz

Bir anneniz olsun isterdiniz böyle

Ve belki sarılıp öpmek isterdiniz onu

Her neyse...

Söylesek, yeniden mi söylesek şimdi de

Ben uzun yolları hiç sevmem

Doğacak bir çocuk gibi beklemeli anılar

Ansızın doğmalı, ansızın ölmeli saniyelerde.) 

IV

Bırakıp gidiyor anılarımı rüzgar

Denize bırakılmış çöpler gibi

Yol kenarlarında birikmiş gereksiz eşyalar gibi

Geri veriyor ve çekip gidiyor usulca.

Bulanık bir havuzun yanında buluyorum kendimi

Bakımsız, taşları kırık bir havuzun yanında

İçinden koyu yeşil bir çocuğun baktığı

Çürümeye yüz tutmuş yaprak renginde

Ağlaması yağmurlu bir sundurmaya benzeyen

Kırık iskemleleri, çatlamış mermer masasıyla

Yağmurlu bir sundurmaya

Ve pencerelerde belli belirsiz bir kadın

Pencerelerde ve her yanda.

Bir çocukta bir kadın hayaleti mi

Bir kadında bir çocuk hayaleti mi

Yalnızca bir hayalet mi yoksa.

(Nerdeyim

Kelebeklerden dokunuşlar alan bir yaprak gibi inceyim

Para bozduranların az çok bildiği

Adres soranların gene bildiği

Bir sokakta bir aşağı bir yukarı

Saatlerce dolaşanların hemen hemen bildiği

Amansız bir güceniğim.) 

Geri getiriyor bunları rüzgar

Geri getiriyor anılması kırmızı bir konağı da

İniltili, hasta bir konağı da

Çatısında baykuşların tünediği

Birtakım iplerin düğümlendiği tahtaboşlarda

Ve bütün konuşmaların tek bir cümlede toplanıp

Suskunluğu bir anıt gibi yükselttiği

Bir konağı ve konağın olanca görkemini

Geri getiriyor rüzgar.

(Konaksa yandı çoktan

Tertemiz bir asfalt ezip geçti onu

İyi biliyorum tertemiz bir asfalt

Ezip geçti onu

Kırmızı bir konak mezarı gölgesi bırakarak.) 

Ve yıllar ve günler ve saatler ayarlandı

Caddeler, işhanları kahveler ayarlandı

Meyhaneler, genelevler

Pasajlar, dar sokaklar, geçitler

Soğuk biralar ayarlandı, soğuk her şey

Ve bütün ilişkiler

Birden yerini aldı.

Ve her şey yetişti gene

Sarı bir çarşambadan

Kahverengi bir cumartesiye.

V

Ben Ruhi Bey, nasıl olan Ruhi Bey

Nasılım

Bir yaz ikindisinden çıktım geldim

Diyelim bir pazartesiydi, biraz da şöyle geldim

Kapıyı iyice kapadım

- Kapadım mı, evet, kapadım -

Çitlenbik ağacının altından geçtim

Frenk üzümlerinden bir iki salkım kopardım

Dişlerimle sıyırdım

Sardunya renginde ve sardunya tadında idiler

Biri fotoğrafımı çekiyorkenki gibi durdum

Azıcık gülümsedim

Ve dünya bana gülümsedi

Çakılların üstünden yürüdüm

Yürüdüm ki, bir sese benziyordum sanki

Yüzyıllarca önce kırılmış bir kemik sesi

İyice duydum

Çıkarken bahçe kapısını açık bıraktım

- Çok yüksekti. Deniz dibi renginde ve demirdendi. Üstünde aslan başı

kabartmalar vardı. İki yanında çok yüksek iki duvar uzar giderdi.

Dışardan çam ğaçları görünürdü. Bir kırbaç gibi görünürdü. Ve

ağaçların üstünde kırbaç kılıflarına benzeyen ve evlatlıkların mavi

pazen giysilerini andıran kalınlaşmış bir gökyüzü dururdu -

On sekiz on beş trenine yetiştim

Geniş kadife koltuğa oturdum

Puromu yaktım - iki kibrit harcadım -

Akşam gazetelerinde pek bir şey yoktu

Haydarpaşa''ya kadar bulmaca çözdüm

İskelede saçları çok iyi taranmış bir kız bana baktı

Bakışından tedirgin oldum

Giyimsizdi, boyasızdı, bakımsızdı

Vapurla Karaköy''e geçtim

Tokatlı''ya uğradım

Köprüden aldığım Fransız dergilerini karıştırdım

Kirazla bir kadeh rakı içtim

Çıkarken boy aynasında kendime baktım

Oldukça yakışıklıydım

Gömleğim temizdi, beyaz ceketim

Tertemizdi ve ayakkabılarım

Pantolonum ütülü

Yelek cebimde ince altın bir zincir

Sarı ve ince bıyıklarım

Tam Ruhi Bey bıyığıydı

Ve iki parmağın arasında bir çiçek sapı

- Zakkum muydu, değil miydi, belki yazpatı -

Boynumda menekşe rengi bir papyon

Hafifçe sarkık

Dudağımda bitti bitecek bir sigara

Kenarında dudağımın

Dışarı çıktım.

Tünele bindim, Asmalımescit''teki Viyana lokantasına geldim.

Avusturyalı karı koca beni karşıladılar

İkisi de eğilerek ben dimdik durdukça onlar bir kez daha eğilerek beni

karşıladılar

Benden başka oldukça şişman iki adam daha vardı. Beyaz Ruslardandılar, gözleri

necef taşı gibi sert ve parlaktı

Tezgahta bir Leh Yahudisi votka içiyordu, yüzündeki ince damarlar fırçayla

çizilmiş gibiydi, bir silinip bir canlanıyorlardı.

Soğuk et getirdiler bana, omlet, bira filan getirdiler

Üstüne kremalı ahududu getirdiler, likörle kahve getirdiler

Çıkarken bolca bahşiş bıraktım.

Markiz''e uğradım, dört mevsimden süzülmüş bir konyak içtim

Düzeltip arada bir bıyıklarımı

Uçları hafifçe ıslak

Bir ara pencere camında kendime baktım

Baktım ki, ben Ruhi Bey

Nasıl olan Ruhi Bey

Daha nasılım.

Oradan Galatasaray''a kadar yürüdüm

Bir kadının pembe beyaz teni dağılıp uçuşarak

Gezindi ortalıkta bir süre

Ve durdum

Durdum bu güzel yaz ikindisinden çıkıp

Bambaşka bir sonbahar sabahını giyinceye kadar Nasılım.

VI

Nasıl olacaksınız Ruhi Bey

Bugün de erkencisiniz Ruhi Bey

Şarapla bira mı içiyorsunuz Ruhi Bey

Böyle sabah sabah Ruhi Bey

Akşam akşam Ruhi Bey

Akşam sabah Ruhi Bey

Cıgara alır mıydınız Ruhi Bey

Yakalım Ruhi Bey, yakalım

Böyle üşümüyor musunuz Ruhi Bey

Benim de ayakkabılarım su alıyor Ruhi Bey

Ne olur ne olmaz

Önümüz kış Ruhi Bey

Ee, daha nasılsınız Ruhi Bey

- İyiyim, iyiyim.

(Gelsem gelsem bir solgunluktan gelirim

Kızgın bir sardunyanın üstelik üvey çocuğu

Pembe pembe azarlanırım

O ölür ben azarlanırım

Kocaman bir konakta uzarım kısalırım

Ellerim tırnaklarım

Yeni kırpılmış bir koyun derisi gibi pespembe

Ve sıcak

Gözlerim, gözlerim benim

Denizi ilk defa gören bir çocuğun

Birdenbire yaşlanması neyse.) 

Sizinle görüşelim Ruhi Bey

Vaktim yok, vaktim yok

Ruhi Bey, görüşelim

Vaktim yok görüşmeye kimseyle

Ruhi Bey

Kendimle bile, kendimle bile.

(Olmaz ki, kimse kimseyi sevemez

Ama hiç kimse.)', 'I Gördün mü hiç suyun yanmasını tuzda Gördüm ben bu yaşam boyu iniltiyi Büyük bahçelerin küçük içinde Saksılardan birinde Gördüm de Uyurken ...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":324,"source_url":"https://www.antoloji.com/ben-ruhi-bey-nasilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Atlar Sulara', 'beyaz-atlar-sulara-edip-cansever-nqzsl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benim yuzumde her seyler var

Uc dilim ekmek bunlardan biri

Annem bir tasa oturmus bunlardan biri

Sur dislarinda hafif bir eskici olur

Olur ya bir kendil olur biraz da elleri

Insan yalniz mi buna bir care dusunmeli.

Dun biraz aglamistim bunlardan biridir simdi

Cok gulunc bir sekilde kahveye giriyorum

Sorsam ya kapidayken gozyasi girilir mi

Girilmez, girilmez, bunu her mahmut biraz anlatir

Korkuyla anlatir, yuzunu baygin tutar anlatir

Kahveci, seni sevmiyorum bunlardan biri.

Bir deniz yandi gene, yansin ne cikar sanki

Iste horoz ottu yuzumun yarisinda

Yuzumde bir horoz var dunyanin biri

Seni sevmek neden mi, aci ve guzel

Geldikce geiyorlar ellerinin elleri

Odalar! ciplak maslar! buna bir care dusunmeli.

Bu da bir sarap olmali simdi boslugu dolduracak

Icince bir korsan agziyla icmeli

Eskidir, yorgundur, akyiptir diye yuzler

Bir sinek sinek mi vurunca oldurmeli

Ve sinek oldu muydu hafif bir uzaklik olur

Olur ya, hem biraz dargindir hem biraz evli

Insan sevdi miydi buna bir care dusunmeli.', 'Benim yuzumde her seyler var Uc dilim ekmek bunlardan biri Annem bir tasa oturmus bunlardan biri Sur dislarinda hafif bir eskici olur Olur y...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/beyaz-atlar-sulara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmez Miyim Hiç...', 'bilmez-miyim-hic-edip-cansever-a8540', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilmez miyim hiç bütün bu sözler ne der ona

Bu sözler ve bu sözlerin içinde çırpınan uzaklıklar

Dolaşıyorum bir başıma, ortalıkta kimsecikler yok

Kıyılar da bomboş, kır yolları da

Soluğumu duyuyorum ara sıra, bir onu duyuyorum

Duymuyorum belki de, biliyorum yalnızca

Ayaklarımın altında yaban naneleri, kekikler

Yol kenarında bir kapı, tahta

Peki, kim yitirmiş evini, ya da

Hangi yitikle yok olmuş o yapı

Kimbilir

Vuruyorum yokuş aşağı, kıyıya

Bir taşın üstüne oturuyorum

Ben oturur oturmaz

Çıkıyor kuytularından bütün görünümler

Ve ufak bir oyun oynuyor bana doğa

Alıp alıp götürüyor gözlerimi bıkmadan

Kısalıp uzayan bir çift yılan balığını andıran gözlerimi

Güneşin şavkından yuvarlanan çakıllara

Tam o sıra bir vapur yanaşıyor iskeleye uzun sürecek bir sonbahar taslağı gibi

Denize yeni sürülmüs bir tarlaya benziyor, uyanık, diri 

Ve işin tuhafı bense

Alışıyorum gittikçe

Her gün bir parça daha alışıyorum yalnızlığıma

Ürperiyorum bir ara arkamdaki ayak sesinden

Ve bu yüzden mi bilmem

Durup bir süre çevreme bakar gibi yapıyorum

Sürüyle kus havalanıyor defnelerin içinden

Sürüyle, evet, hatırlıyorum birden

Nicedir unutmuşum saymayı bile günleri

Dağılıp gitmişler herbiri bir yana

Kuşlar gibi, onlar da

Benimse ne gidecegim bir yer

Ne de özlediğim bir şey var

Öyleyse neden yazıyorum bu sözleri ona

Bu biraz sevdaya benzeyen, biraz da sevdasızlığa

Böyle gelişigüzel, böyle kırık dökük

Sanki hiç kimselerin kullanmadığı bir gün kalmış bana.

Uzun bir cumartesiyi hatırlıyorum, saat on iki

Dalıp gidiyorum, düsünüyorum da, saat on iki

Bir sigara yakıyorum, bir kağıda bir iki dize yazıyorum

Yerini iyi bilen, onurlu bir iki sözcük daha

Ama hiç kımıldamıyor, akrep de, yelkovan da

Yani tam böyle birşeye benziyor zaman

Yılgın ve çarpıcı renkler içinde pek kımıldamayan

Çıkageliyor sonra, saat on iki.

Anlıyorum

Yaşam elbette uzun biz duyabildikçe sevgiyi

Yalnızca bunun için uzun

Yani sevgiyle de sevebilir insan, sevdayla da

Örneğin

Bir sevgiyi yontup onarmak için

Döğüşmek de sevgidir

Ve benim bildiğim kadarıyla

Her şeydir bir insan, her şeydir

Yalandır kısalığı yaşamın

Ve özellikle insan dediğimiz şey

İnançli bir insan soyunun parçasıysa.

Sonunda başbasa kalıyoruz gene

Başbaşa kalıyoruz doğayla ben

İşte az önce yağmur da başladı, cumartesi günlerden

On temmuz cumartesi

Bir vapur daha kalkıyor iskeleden

Ve yağmur hızlanıyor biraz

Uzanıp yatsam diyorum otların üstünde çırılçıplak

Tam öyle yapıyorum

Şimdi yağmuru seviyorum, şimdi yağmuru seviyorum, yağmuru seviyorum.', 'Bilmez miyim hiç bütün bu sözler ne der ona Bu sözler ve bu sözlerin içinde çırpınan uzaklıklar Dolaşıyorum bir başıma, ortalıkta kimsecikle...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/bilmez-miyim-hic-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ay Aldım Diyarbakır''dan Tokatta Biri Oldu O Zaman', 'bir-ay-aldim-diyarbakir-dan-tokatta-biri-oldu-o-zaman-edip-cansever-a20aa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tokatli diyorlar ya da bir atin baslangici

Egilmis, sakin, ickiler aliyor kalabaliktan

Simdi o mor gozleri mor bir kadinla ilgili

Birazi namuslu iyi, birazi acikca perisan

Ya da bir kadin bir kadini oper gibi

Hicbirsey anlamiyor yasamaktan.

Hicbir sey anlamiyor diyeli anlamiyor

Ama bir yalnizligi tamamliyor durmadan

Askerler geziniyor, her yerde bu goz kahveleri

Ben bu gozlere Tokat''ta rastladimdi bir zaman

Hopali bir vardi, hamalin biri

Daha hic cikmayacak karisinin koynundan.

Bir kadeh olmali ya da bir rakinin baslangici

Ansizin bir gol Anadoludan

Bir yanda bir balikcil ne zaman istese olur

Kocaman iz birakir cilginligindan

Sonra o adamlar ki celimsiz, esmer, biyikli

Ve butun gun sevisirler acilariylan.

Tokatli diyorlar ya da bir ekmegin baslangici

Ezilmis, sakin, onca bir yoksullugu oduyor durmadan

Bu kimin evreni, bu sacina bir el atma saatlerinde

Bu kim ki oluyor, Tokatta oluyor her zaman

Ya da bir erkek bir erkegi oper gibi

Hicbir sey anlamamis yasamaktan', 'Tokatli diyorlar ya da bir atin baslangici Egilmis, sakin, ickiler aliyor kalabaliktan Simdi o mor gozleri mor bir kadinla ilgili Birazi nam...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-ay-aldim-diyarbakir-dan-tokatta-biri-oldu-o-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çiçek Sergicisi Der Ki', 'bir-cicek-sergicisi-der-ki-edip-cansever-mrqik', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bin dokuzyüz on iki miydi, bin dokuz yüz elli iki miydi

Güneşli bir öğle miydi, çiçekler gölgesiz miydi

Ellerim kirli miydi

Neydi

Çiçeklere su mu serpiyordum, bir karanfil çok mu uzaklardan gelmişti

Bilmem ki

Benim bütün yaşamımda hep karanfiller olmuştur

Her zaman hatırlarım

Sanki bir karanfilden sürekli doğmuşumdur

Bin dokuz yüz on iki doğumlu bir karanfili

Karım göğsüme takmıştı. Şimdi ben çok yaşlıyım

Şimdi ben nedense çok yaşlıyım

Herkesi ayrı ayrı tanımam

Ruhi Bey''i İçerenköy''den tanırım

İçerenköy''ü iyi bilirim de ondan

Kaç yıl önceydi, şimdi unuttum

Babasını da tanırım

Kaç yıl önceydi, bilemem

Üryani eriği gibi gözleri vardı

Çizmeleri, kamçısı

Ruhi Bey, benden çiçek alırdı

O zamanlar sokak sokak dolaşırdım

Çiçek alanları iyi bilirdim

Ruhi Bey de çiçek alırdı

Nedense benden alırdı. Çünkü ben çiçekleri çok biçimli tutarım

Kuşkonmazları sevmem, kullanmam

Çiçeklerin aralıklarına bakarım

Sanki ben onları hep yeniden yaratırım, yontarım

Bin dokuz yüz kırk üçde biri öldü

Boynu değil, bir karanfilin sapıydı, yana düştü

Düşünce öldü

Bir ölülük sindi ellerime

Bir ölülük bana sindi

Ona sergimde her zaman bir yer ayırırım

Kimseler bilmez

Ben işte gizli gizli onu sularım

Karanlık bir karanfilliği

Yoklukta bir karanfilliği

O gün bugündür bütün çiçekler

Karanfildir benim için.

Bir gün de bir demet karanfilim yandı

Bir demet karanfilin penceresi, kapısı

Nedense yandı

Önce giyinik bir ev görünümündeydi, öyleydi

Takındı kırmızılarını sonra

Süslendi

Bir boşluk edindi orda kendine

Hemen oracıkta bir boşluk

Açtı şemsiyesini ve gitti.

Ben şimdi oğlumun yanında kalırım

Onun kırmızı yapraklardan yapılmış

Bir zamandışılığı vardır

Beni anlamaz

Anlamaz, niye anlasın

Anlaşılmak -değil mi ama- sanki kimsenin olamaz

Ben kendime bir karanfil mezarı satın aldım

Beni oraya gömecekler

Ruhi Bey cenazeme gelecek

Ama hangi Ruhi Bey

Doğrusu biraz şaşırdım

İçerenköy''deki Ruhi Bey gelmez

Osadece karanfil satın alır

Ölümü pek beğenmez

Şimdiki Ruhi Bey ölümedaha yatkındır

Yaşamaya da

Ölümle yaşam arasında bunalır bunalır

Ben bu kadarını anlarım

O gelir beni kaldırır

Bir karanfil kalabalığına arrtık katılır

Geçen gün gördüm

Acımayı unuttum

Sevinmeyi unuttum

Ben her şeyi artık unutuyorum

Ama ogeçerken ne yalan söyleyeyim şuramda birağrı duydum

Ağrı da değildi belki, hani, nasıl

Gövdemi yeniden buldum

Acılar acılara eklenince ağırlaşıyor

Gövdem de ağırlaşıyor

Ruhi Beyle kocaman bir demet karanfil oluyoruz

Şu üstümdeki boşluk kadar

Bir demet

Yok artık pek konuşmuyoruz

Benim sözlerim eskidi

Onunki de eskidi

Zaten kelimeler sonludur

Öyledeğil mi

Donuk donuk bakışıyoruz

Ben ölüme iyice yakın

O yaşamaktan uzak

Öyle bir gök içinde durmuş gibiyiz

Karanfiller ölürken

Karanfillerden bir deniz.', 'Bin dokuzyüz on iki miydi, bin dokuz yüz elli iki miydi Güneşli bir öğle miydi, çiçekler gölgesiz miydi Ellerim kirli miydi Neydi Çiçeklere ...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":92,"source_url":"https://www.antoloji.com/bir-cicek-sergicisi-der-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Genelev Kadını Ve...', 'bir-genelev-kadini-ve-edip-cansever-5f4lk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Girdi

Sırtında eski bir ceket vardı

Bir yerlerden sızmıştı sanki, gün ışığı gibiydi

Sarışındı

Önce bir süre kapının önünde durdu durdu

Gölgelendi, inceldi, beni gördü

Pek önemsemedim

Baktı, hiç konuşmadı

Oysa bir İsa tasviri gibi uçumluydu, güzeldi

Yer gösterdim, oturmadı

Bir sigara yaktım, ona da verdim

Aldı

Sigarasını ben yaktım

Kısa bir gülümseme yürüdü dudaklarından

Benim dudaklarıma da geçti

Çocuklar gibi kızardım

Öteki kızlar gülüştüler

Ben kendimi sevdim, güvendim

Saçlarımı düzelttim, göğsümü biraz kapadım

Bana elini uzattı, ellerimiz birbirine değdi

Sıcaktı, inceydi, kıskanırım anlatmaya bu eli

Ağır ağır odama çıktık.

Girdi

Açık pencereyi kapadım

Perdeyi çektim

Arkamı döndüm, yavaş yavaş soyundum

Bileğimdeki saati çıkardım

Sigaramı söndürdüm

Tam o zaman..

Zaman da değildi belki

Önce korkunç bir gözyaşı seli

Sonra alabildiğine bir kayalık

Kayaların üstünde bir kertenkele

Ardından bir ormanın uğultusu

Binlerce kanat sesi

Sağ elinde bir bıçak

Yok, hayır, bıçak da değildi

Vuran, ezen, öldüren bir el

Ve eller

Ve dişler

Kendimden geçtim.

Bir daha gelmedi, hayır, bir daha hiç gelmedi

Ama onunla ben

Ne zaman istedimse o zaman yattım.', 'Girdi Sırtında eski bir ceket vardı Bir yerlerden sızmıştı sanki, gün ışığı gibiydi Sarışındı Önce bir süre kapının önünde durdu durdu Gölge...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bir-genelev-kadini-ve-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-edip-cansever-4oik1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'O ''bir gun''

Yuvalanmis sanki icinizde

Bugulu cam tipki

Hicbir sey gorunmuyor

Besbelli disinizdan bakiyor size.

Yokus asagi, yokus yukari

Duzlerde, egrilerde

Yansir ondan size her isik

Birakilmis bir bicaktan doguste.

Beklemek, avuntu--bir silah patladi uzakta--

Yakinda bir tel koptu

Durmanin durgunlugu--yeterse--

Sursun bir sure boyle--ne cikar--

Emzirsin icinizi o sonbahar bulutu.

Gelecekte, dediniz--ama ne zaman--

Kim bilir, belki de gecmiste

Yagmurlardan kalan kimsesizligin

Saklidir acisi o ''bir gun'' de

''Bir gun'' bulusuruz--cok iyi--

:Bir gun'' du, hani nasil--silinti--

Gerisi dokuntu gunler

Ola ki beslemekte ''bir gun''u hepsi', 'O ''bir gun'' Yuvalanmis sanki icinizde Bugulu cam tipki Hicbir sey gorunmuyor Besbelli disinizdan bakiyor size. Yokus asagi, yokus yukari Duz...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bir-gun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Mektup Atanın..', 'bir-mektup-atanin-edip-cansever-sznch', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir mektup atanın o mektubu attıktan

sonraki şaşkınlığı

Izlemekse bir bakima

Yol aldigini mektubunun

Bakar dururum ben de ardindan.

Sana soyluyorum yalniz

O ben ki her turlu bakislarin tarihini

Ogrendim gozlerini hic degistirmeyen bir kaptandan.', 'Bir mektup atanın o mektubu attıktan sonraki şaşkınlığı Izlemekse bir bakima Yol aldigini mektubunun Bakar dururum ben de ardindan. Sana soy...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-mektup-atanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Meyhane Garsonu', 'bir-meyhane-garsonu-edip-cansever-pt2pb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşte

Isınmış parke yolun kokusu

Demek ki ben mutsuzum

Tuhaf bir su içmişim de sanki içim görünüyor

Gözlerim buzdan

İçimde yaz kırıkları.

Eklemek gerek

Büyümesi gibi bir salyongozun

Yıllarla değil, yıllarla değil

Saniyelerle kıvrılmıştır kabuğum.

Aynalıpasaj''ı geçtim

Geçerken sağlı sollu aynalara baktım - her günkü gibi -

Vitrinlere baktım, düğmelere, fremuarlara

Yukardaki taş heykelciklere baktım

Bakmasam ne yapacaktım, açılıp kapanmaya başladı dudaklarım

Gözkapaklarım

Açılıp kapanmaya

Açılan kapanan çözülen

Ne varsa duyuyordum kendimde

Balıkpazarı''na saptım.

Ben balıkpazarı''na sapınca

Dünyada sayılmayan bir adamdım

Nasıl duruyorsa gökyüzü sayılmadan

Boylu boyunca bir duvar

Ve uzay nasıl duruyorsa

- Uzay ki mutluluktur

Ele geçmeyen bir sonsuzluktur uzay -

Ben masallara şunu bunu taşırdım.

Oldukçe dar bir sokağa gelince durdum

Karşıdan karşıya çamaşırlar asmışlardı

Mor, pembe, beyaz çamaşırlar

Kızgın yaz güneşinin altında

Hoşlandım

Anahtarı kilide soktum, bundan da hoşlandım

Çevirdim bir iki kez, kapı titredi

Ben de titredim

Dükkanı açtım.

Karşıki evler çoktan uyanmıştı

Hemen herkesi az çok tanırdım

İki kocakarı, levanten, dama oynuyorlardı gene camın önünde

Çinko balkonda bir kız çocuğu ağlıyordu

Oydu

Bir satıcıya sesleniyordu, oydu

Besbelli yeni uyanmıştı, saçları dağınıktı

Zayıftı, sürekliydi, değişmiyordu

Sesi inceydi, isterikti

Saate baktım dokuz buçuktu.

Ne yaptım da ben, daha sonra ne yapacaktım

Önce helaya girdim, bir süre helada kaldım

Terledim, adını bilmediğim bir kokuyla koktum

Mutfağa girdim

Patatesleri soydum yıkadım

Domatesleri salatalıkları

Soydum yıkadım

Muska böreği sardım kaldırdım

Bira kasalarını, boş şişeleri

Dükkanın önüne çıkardım

Camları sildim, ortalığı süpürdüm

Sonra bir iskemleye oturdum

Orda yüz binlerce cinayeti ben

Ve intiharı

Bir mutluluk gibi dışımda duydum.

Evet, gelirdi

Ruhi Bey mi dediniz, evet, gelirdi', 'İşte Isınmış parke yolun kokusu Demek ki ben mutsuzum Tuhaf bir su içmişim de sanki içim görünüyor Gözlerim buzdan İçimde yaz kırıkları. Ekl...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/bir-meyhane-garsonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Otel Katibi', 'bir-otel-katibi-edip-cansever-wpidp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anlamadığım şu

Ben neden bir otel katibiyim

Eskiyim, renksizim, kimsesizim

Yontulmuş kalemlerden, sosisli sandviçlerden iğrenirim

Papazlardan, homoseksüellerden iğrenirim

Kız kurularından ve saldırgan dullardan

Ve yaşlı adamların sararmış dudaklarından

Ve deli saraylılardan, onların aybaşı kokularından

Kendimden kendimden

Ve nedendir ki ben

Sararmış bir sürahide kirli bir su gibi bekletirim.

Günlerden ne? Pazartesi İyi bilirim

Ama gün nedir bilmem

Çiylerle çiçeklerle çamlarla doldurulmuş gün

Göğsü bir martı göğsü gibi denizlere değen

Parklarda bahçelerde göz dolduran gün

Bir çocuğun gözlerinden gözyaşı içen

Sesini bir ayin gibi uzaklardan duyduğum

Gün nedir.

Kokular vardı ayrı ayrı, ben unutmuşum

Hepsi şimdi bir otelin kokusu

Kullanılmış çamaşırların ve bavulların kokusu

Ve telefonların ve kapısı açık helaların

Ve hasta soluklarının, tozlu yer halılarının

Sabahlara kadar yanan ampullerin kızgın

Birbirine karışmış, değişmeyen kokusu.

Ruhunda kasvetin suyunu buldu

Kimdir

Olsa olsa bir otel katibidir

Bir otel katibi her yerde bir otel katibidir

Gözlüklü ve tedirgindir

Hiç yıkanmamış gibidir, parmakları sarıdır

Ön dişleri çürüktür, avuçları terlidir

Yıllar var ki bir kumaş düşler kendine

Ve bu yüzden olacak sanki biraz terzidir.

Sorarım - ki otel katipleri sorar - bir terlik nedir

Terliğin yenisi yoktur

Geçmişi yoktur, geleceği yoktur

Yeri ve kimliği zaten yoktur

Bir terlik bir terliktir o kadar.

Bilirim kötünün kötüsü bir oteldir burası

Odalarında hamam böcekleri, sinekler

Pis yataklar, lekeler, sararmış çatlak lavabolar

Peki bir insan nedir

Sorarım - ki otel katipleri sorar -

Bir gün gittikçe ufalıyordum

Düş müydü, gerçek miydi, iyi bilemem

Oturmuş bir küvete kuruyup kayboluyordum.

Şarkıcılar, sokak çalgıcıları gelir en çok

Sokak kadınları, serseriler

Evet, ara sıra Ruhi Bey de gelir

Kan renginde gelir, yolunu şaşırmış bir böcek gibi gelir

Sapından eğilmiş bir gelinciğin öğle uykusu gibi

Çocuksu hafif

Tam bizim otelliktir

Sanırım elbisesiyle yatar, ayakkabılarıyla

Sabah olunca erkenden kalkar

Ve kalkar kalkmaz başlar içmeye, doğrusu pek anlayamam

Uçak saatlerini sorar, lüks lokantaları sorar bir de

Pek anlayamam

Şu var ki, kendiyle eğlenir gibi sorar

Elinde vapur tarifeleri, kataloglar

At yarışı listeleri

Yanaşır pencereye, ışığa tutar birer birer hepsini

- Otel her zaman loştur -

Bakar bakar bakar.

Nemli bir havlunun yere bırakılışı gibi

Çöker bir iskemleye sonra

- Çoğu zaman böyle yapar -

Sokağa bakar aralıksız

Öyle bakar ki, sokakta bir şeyler olmuş sanırsınız

Sanki bir cinayet işlenmiş, biri parasını çarptırmış

Ya da terkedilmiş bir kadın yakalamış kocasını

Bağırıp çağırıyordur gebe karnını göstererek

Nerdeyse

Hani nerdeyse polisler gelecek

Nerdeyse

Hani nerdeyse polisler gelecek

- Gerçi her türlü olaya tanığızdır bu sokakta -

Oysa işte Ruhi Bey

Görerek bakmıyordur ki bir şeyler anlasanız

İçer bardağındaki son yudumu da

Topundan boşalan bir kurdele gibi

Sarı bir kurdele gibi

Çekip gider az sonra.', 'Anlamadığım şu Ben neden bir otel katibiyim Eskiyim, renksizim, kimsesizim Yontulmuş kalemlerden, sosisli sandviçlerden iğrenirim Papazlarda...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/bir-otel-katibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Plak Gibi Dönüyor Gökte', 'bir-plak-gibi-donuyor-gokte-edip-cansever-y22tb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir plak gibi donuyor gokte mavilik

Sesi asagida, cok asagida

Ustunde bir duvarin. Duvarsa

Dondurma yiyen bir cocugun eli sanki

Tasmis akiyor

Opuyor topragi kanatan nar ciceklerini.

Opuluyorum bembeyaz cimlerinde yalnizligimin

Sonsuzluk yarin.', 'Bir plak gibi donuyor gokte mavilik Sesi asagida, cok asagida Ustunde bir duvarin. Duvarsa Dondurma yiyen bir cocugun eli sanki Tasmis akiyo...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-plak-gibi-donuyor-gokte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Su Yılı Denebilirdi', 'bir-su-yili-denebilirdi-edip-cansever-ga2zk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir su yılı denebilirdi geldi geçti

Üstünde durmuyorum.

Terledim, bulanık baktım.

Ne varsa kendiliğindendi

Hemen hemen evden çıkmadım.

Sanki avuçlarımda sürekli

Yıkanmış, tabağa konmuş bir meyvenin ellenmişliği,

Ola ki makyajı bir oyuncunun, karışmış gözyaşlarına

Yeni kireçlenmiş bir duvarın kireci

Avuçlarımda sürekli..

Bir su yılı denebilirdi üstünde durmuyorum

Kalmışsa kalmıştır bir çomak gibi

Kuru

Artık kullanılmayan bir demiryolu

Kararmış, kırık dökük

Üstünde bir yük vagonu.

Mavi bir araba kapımın önünde

Bütün yıl

Bir su yılı

Kapısını kimse açmadı

Açıp kapamadı hiç kimse

Aslında mavi de sayılmazdı pek

Balkıyıp duruyordu kırmızı bir şakayığın renginde

Yani sabah güneşlerini denizde

Günbatımını denizde

Severek yaşayan bir balık da denebilirdi ona

Çünkü düşler gerçekle

Gerçekler düşle

Anlayınca bir gün buluştuğunu

Geçirir her günceye kısa bir yolculuğu

Ama bir takı eksik gibidir bir sözcükte

Damağın dudağın alışkanlığına karşı

Kalbin atışlarıyla çok uyumlu bir de.

Hadi anlat deseler anlatamam

Bir yere gidiyorken cayıp bir başka yere gitmeyi

Yani bir kunduzu karşıdan karşıya yüzdüren sezgi

Nedir ben bilemem ki

Belki bir raslantıdır da ondan mı sevdanın yeri

En yakın yeri

En uzak yeri

Bitmeyen yeri

Bitecek yeri

Farkedilmez zaten anlaşılmış sevdanın

Anlaşılmaz sevda ile bütün ekleri.

Gözlerim sevdim seni

Kökleri gözlerimin

Suyunu benden içen ıssız bir kasaba gibi..', 'Bir su yılı denebilirdi geldi geçti Üstünde durmuyorum. Terledim, bulanık baktım. Ne varsa kendiliğindendi Hemen hemen evden çıkmadım. Sanki...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bir-su-yili-denebilirdi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Taş Atarsın', 'bir-tas-atarsin-edip-cansever-dwy00', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir taş atarsın, taş nereye düşerse

Mutlaka bir köşebaşıdır

Çünkü yüreğin daralmıştır ve kıştır

Kullanılmamış bir sicim gibidir soğuk

İşte bak her kestaneciye sapsarı bir köşebaşı kalmıştır.

Şimdi bir şamandıra denizin yüzünde

Durulmamış bir anı gibi kendini salmıştır.

İçimizde birbiriyle konuşan yaprak bolluğu

Yalnızlık bir başına kalmıştır.', 'Bir taş atarsın, taş nereye düşerse Mutlaka bir köşebaşıdır Çünkü yüreğin daralmıştır ve kıştır Kullanılmamış bir sicim gibidir soğuk İşte b...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-tas-atarsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitti O Sevda', 'bitti-o-sevda-edip-cansever-sj70n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bitti o sevda kesildi çığlıkları martıların

Su gibi bitti, suya karşıt gibi bitti

İtti kıyıyı adına deniz dediğimiz şey

Unuttuk ikimiz de her türlü yetinmezliği

Kaybetti kumarda gözlerim

Kaybetti kumarda gözleri.

Bir koru rüzgarlandı göğüs boşluğumuzda sanki

Uzaklaştı ağaçlar birbirlerinden

Yakınlaştı ağaçlar birbirlerine

Yani her soluk alıp verişimizde bizim

Bir mekik gibi kalbin

Bir mekiği gibi kalbim

İşleyip durdu bu yitikliği yeniden.

Ne kaldı

Farkında mısın bilmem

Gündüzler..

Gündüzler biraz azaldı.', 'Bitti o sevda kesildi çığlıkları martıların Su gibi bitti, suya karşıt gibi bitti İtti kıyıyı adına deniz dediğimiz şey Unuttuk ikimiz de he...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bitti-o-sevda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Bu Şafak Vaktinin..', 'biz-bu-safak-vaktinin-edip-cansever-ma8ow', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz bu safak vaktinin neresindeyiz

Oyle bir umut gibi gelip gececek

Yalnizim, yalnizsin, bize kim gulumseyecek.

Ve onlar sevdasini soylemeden bir sokaga sapanlar

Iclerinde nane olan bir yerlerden gececek

Bir soguk yurege oyarak soguklugu

Ya da onlar mi ki aksamlara dek bir bilardo oyuncusu

Biri bir zincirle ya da bir sapka kenariyla ozdesleserek

Birdenbire kaldirabilir ki egik boynunu

Ne cabuk

Evet, ne cabuk, aksam oldu mu.

Arklardan yuze yuze gecen anilar

Toplasak, toplasak, neye benzetsek

Kilosu on liradan elmalar tam sifira dusecek.

Bir yanda yokluk icinde, bir yanda

Ey sonbahar, ey o buyuk cicek.', 'Biz bu safak vaktinin neresindeyiz Oyle bir umut gibi gelip gececek Yalnizim, yalnizsin, bize kim gulumseyecek. Ve onlar sevdasini soylemede...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/biz-bu-safak-vaktinin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Borazan', 'borazan-edip-cansever-qk6u9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sizin bir cift goz olan o seyleri tasidiginiz gibi

Bir borazan tasirdi, ta-tarata, ti-tiriti

O calmiyor muydu, olanca goruntuler ayakta

Uzaklar, cins ulkeler onunla bir giderdi

Daha gormedimdi ben oldum bittim oyle yurek canlisi

Anilar mi, tez gelecekler mi, en guzeldi borazanlardaki.

Kim sevdi, kim niye oyle, yansitir dururdu bir egleniyi

En cogul gokler kipirdar, en yapragi bollar sevinirdi

O calsin gozlere senlik, akinip giderdi baska dunyalar

Oralardan bir kizi ipince sevdirirdi.

Aksamlari maviyi calardi, bilmem ki bilir miyiz o koyu maviyi

Bir ciplakti, ama gormeyin, bir gurultuydu sabahi tutturunca

Ya ne olaydi derseniz bendeki istek biraz garipti

Cikiversin derdim en guzel olacaklari dunyanin

Bir sevinc, bir mut dalgasi, azlarin azi da bir sadelik

Sizin bir cift goz olan o seyleri tasidiginiz gibi.', 'Sizin bir cift goz olan o seyleri tasidiginiz gibi Bir borazan tasirdi, ta-tarata, ti-tiriti O calmiyor muydu, olanca goruntuler ayakta Uzak...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/borazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buz Gibi', 'buz-gibi-edip-cansever-4xsiv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ask iyidir bak

Duyumunu artirir insanin

Hele don gomlek sabahlari

Tiras olacagini duyarsin

Yeni gomlegini giyecegin gelir

Bir yeni bicim eklersin insan olacaga

Masaya, merdivene, aynali dolaba

Derken ardindan sipin isi bir kahvalti

Amanin dersin bu ne delice gidis

Paldir kuldur acar miydi fistik agaci

Ispinoz dusunur muydu

Deli olan kasinir miydi

Kollarin upuzun Walt Whitman''i okumaktan

Agzin desen bir karis acik

Sokaklar yok mu, o sokaklar

Once bir yesile iskilli

Evlerde buyumeler, alip basini gitmeler olacak

Kizip duracaksin ustune basina konan toza

Televizyondaki ise

Usanmak, hizini eksiltmek dendi mi

Cin ifrit kesileceksin birden.

Hey gidi duyumuna yandigimin dunyasi

Alip verecegin olacak ille

Ask mask buz gibi yasayacaksin.', 'Ask iyidir bak Duyumunu artirir insanin Hele don gomlek sabahlari Tiras olacagini duyarsin Yeni gomlegini giyecegin gelir Bir yeni bicim ekl...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/buz-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cenaze Kaldırıcısı Adem', 'cenaze-kaldiricisi-adem-edip-cansever-6yhzh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ölü nedir ki bir ölüm nedir

Acıyla kirlenmektir, acıya sevinmektir.

Siz bilirsiniz, isterseniz biraz gecikiriz

Gelmesine geliriz, birazcık gecikiriz

Ne kadar gecikirsek o kadar iyiyiz

Ben o kadar iyiyim.

Bir zamanlar hamaldım, çelenk taşırdım

En güzel çiçekleri ben sırtımda taşırdım

Caddelerden geçerdim, büyük vitrinlerin önünden

Serlerden bahçelerden güne damlardım

Renklere karışırdım, kentin ışıklarına

İçinden soyulan bir portakal gibi

Kendi içdenizlerimi öper okşardım

Süslenmiş gibi olurdum

Kokular içinde kalırdım.

Sonra bir gün çağırdılar

Sonra bir gün beni gene çağırdılar

Artık hep çağırdılar, dört kişi olduk

Dört kişi gerekliydi, dört kişi olduk

Ölüleri gördük, ölüler koltuktaydılar

Ölüleri gördük ölüler yatakta

Ölüler giyinik, ölüler çıplak

İşte biz dört kişi buna alıştık

Bizi alıştırdılar.

Omuzlarım kesik kesiktir, nasırlıdır

Her zaman bir ölü vardır omuzlarımda

O kadar ölü vardır ki her yanımda benim

- Ölüler içindeyim ölüler içindeyim -

Örneğin bir bardak su içsem bir ölü kayar şuramdan

Su içmeyen bir balık gibi kayar

Ölülere takılmış bir uçurtma gibiyim

Biraz öyleyim.

Ve otel müşterileri, onlar

En inandırıcı ölülerimdir benim

Her biri ölümü her gün yeniden yaşar

Camlara yapıştırılmış yüzler gibi

- Unutmak utanmaktır, siz bilirsiniz -

Hüzünsüz, anlatımsız, soğuk

Akşamüstü rengindedirler ve yorgundurlar.

Siz daha iyi bilirsiniz, Hıristiyanları soyarlar

Ölüleri çıplaktır onların

Ne yalan söyleyeyim görünce huylanırım

Yeni ölmüş genç kızlar yeni doğmuş çocuklara benzerler

Görünce huylanırım

Bunu karıma da anlatırım, su dökünürüm

Adım mı, Ademdir, iyi adamımdır.

Karıma anlatırım ya, size de anlatırım

Bir gün bir ölü kaldırdık, Aşkenazlardan

Heni şu Leh Yahudilerinden işte

Gözleri o kadar mavi olan, mavi bir suda yüzer gibi gövdesi

Saçları tütün renginde

Her neyse, uzatmayalım, bir de baktık ki ölünün arka cebinde

Dolarlar, marklar, sterlinler

Önce paylaşmayı düşündük, yalan söylemeyeyim

Götürüp geri verdik az sonra

Götürüp geri verdik, yüz lira aldık

Hepsi hepsi yüz lira

Bir gün bir ölüye asılı iki torba

Torbalar kalçalara inmiş, askılar omuzlarda

İçleri altın dolu

Ölüyse bir kocakarı, Ermeni

Çoluk çocuğu

Elbette geri verdik altınları da.

Ve genç bir kız ölüsünden ametist bir kolye çıkardım

Doğrusu sakladım onu gizlice

Karımdan bile sakladım, karımdan

Niye mi sakladım, uğurdur diye.

Bir karım, iki çocuğum, dört kişiyiz

Kimseler bizimle konuşmaz

Mahallede kahveye çıkmam, anlarsınız

Giderek alıştım içkiye de

Demin de söyledim ya, iyi adamımdır

Benden kötülük gelmez

İnanır mısınız, bir gün gene bir ölüyü kaldıracağız

Tam kaldıracağız, birden farkına vardım

Adam düpedüz yaşıyor

Oysa raporlar filan tamam

Buzluğa girdi mi o anda işi bitik

Başında mirasçılar yas giysileri içinde

Dedim ya, birden farkına vardım

Evet, o gün bugündür yaşıyor

Cihangir''de oturur, zengindir

Bir iki kez evine de uğradım

Beni pek sevmez.

Ne de olsa herkes biraz ölüdür

Otel müşterileri en önde gelir

Kendileri soyar kendilerini kendileri giydirir

Büyük kentlerin büyük tabutlarıdır oteller

Nedense işte onlar gökyüzüne gömülür.

Bu sabah on birde bitirdim işimi

Gidip uyuyacağım

Belki de

Ya karımla ya da

Bir başka ölüyle yatacağım.', 'Bir ölü nedir ki bir ölüm nedir Acıyla kirlenmektir, acıya sevinmektir. Siz bilirsiniz, isterseniz biraz gecikiriz Gelmesine geliriz, birazc...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/cenaze-kaldiricisi-adem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cüceler', 'cuceler-edip-cansever-7diqy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceler gecmiyor ki, agir agir kaliyor

Hircin! siziyor camlardan deli

Cucelerse sarki soyluyorlar mutfakta

Dillerini catallariyla yirtarak

Kandan ve sinirden urpertilmis sarkilar.

Yuzumu icime kirbacliyorum, korkunc yuzumu

Guluyorum orda aciya

Gulmuyorum bile aciya

Cok kollu bir deniz hayvani gibi

Cildirtiyorum onu sehvetten

Cuceler sarki soyluiyorlar mutfakta.

Icelim ey cuceler, icelim

Vaktimiz var nasil olsa

Dogacak yeni acilar icin.', 'Geceler gecmiyor ki, agir agir kaliyor Hircin! siziyor camlardan deli Cucelerse sarki soyluyorlar mutfakta Dillerini catallariyla yirtarak K...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cuceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dipsiz Testi', 'dipsiz-testi-edip-cansever-8u1pq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni dinlersen Uskudar''a gitme

Ibrahim''i gorme siir yazma

Su herkesin bildigi duzluk

Bu deli alacasi cayir

Ardic kusu turkulu sokak

Senin icin degil.

Sen yoksun

Cevrende kimseler yok

Zengin de olsan

Yoksullugun gitmez.', 'Beni dinlersen Uskudar''a gitme Ibrahim''i gorme siir yazma Su herkesin bildigi duzluk Bu deli alacasi cayir Ardic kusu turkulu sokak Senin ic...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dipsiz-testi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Güneş', 'dort-gunes-edip-cansever-rxuy1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her sey o kadar anlamsizdi ki, yaz

Bunu bir daha pekistirdi

Avuclarimi sicak tutar, bulundururdum

Sevgisiz ve gereksiz kalmak icin

Oyle, kendime yorgun hazirlamislar beni.

Sehir ki aydinliktan gorunmeyen birini

Acilmis iskambiller gibi bilerken

Orada, icimde simdi

Dort gunes bir arada

Gozlerimde hic bitmeyen bir deli', 'Her sey o kadar anlamsizdi ki, yaz Bunu bir daha pekistirdi Avuclarimi sicak tutar, bulundururdum Sevgisiz ve gereksiz kalmak icin Oyle, ken...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dort-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostlar', 'dostlar-edip-cansever-y1kzi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Fethi Naci''ye

Geldin mi, iyi

Yollarından yürüyüsler sızdıran sonbahar

Bir tenhalığı eskisinden çok sezmeyi

Bakımsız bahçeler mi olur, büyük ahşap boş odaları mı olur

Ne olur

Ey bana sevmeme gücü veren güzellik

Eski bir kadını eski bir park kanepesinde bırakan sonbahar

Aldatılmış bir yüzü yağmur oluklarında

O yüz ki bir denizin tekrar tekrar bittiği

Gece yarısı kokularında

Yosunlu bir kıyıda ancak

Dilinde çakılların ve derinliğin en son tadı

İşte

Bir vakit daha geçti, şimdi ne yapsak

Ne yapsak, bir vakit geldi ve geçti

Ey bana sevmeme gücü veren güzellik

Sonbahar

Sen mi kaldın bir

Yok birşey yapacak.

Bin dokuz yüz yetmiş bir yazı, ey unutulmayan yaz

Bıraktığın gibi mi kalsak

Bir çiçek milyon kere katılaştı eridi

Açtı dağıldı

Yaşamadı hiç belki

Bir ışık olsun yakmadı

Tuzlu ve ıslak bir ışık

Tankerler geçti kıyılardan gene

Suyu zonklataraktan

Gül koktu saçlarında taşıdikları benzin

Senin saçlarında

Alnın üstünden kuzular inen bir tepe gibi eğildi

Boynun bir uçurumdan çekiliyormuş gibi gergin

Bitti o yaz, şimdi

Yerleşti çoktan

Bize sevmeme gücü veren güzellik.

Tenha bir meyhanede oturuyorduk sevgilim

İzmir''in eski rıhtımında

Bilirsin, severim çok İzmir''in eski rıhtımını

Hani bir çesit kuşlar vardır bulanık denizinin

İnsanlar gibi konuşur o kuşlar bazen

Ve unutulmuş diller gibi pek anlaşılmaz ne konuştukları

Millerce yıl öteden bir tenhalığı sözlendirirler

Hatırla

Ne demiştim o gün ben sana

''Her tenha semtte kurulmamış bir saat yakışır''

Benim o bunaltılı günlerimden kalma bir mısra

Ve sense bana Aragon''un

-Parisli şair, yüzü aslan dolu-

Sımsıcak, dipdiri bir mısrasını anlatmıştin

Seninle ve parmaklarınla

Bardakta duran suyun bir akarsuyu

Nasıl kıskandığını anlatmıştın boyuna

Nasıl mı

Dedim ya, seninle ve parmaklarınla

Neden olmasın, yeni yakilan bir sigarayla da anlatılabilir şiir

Apansız bir yolculukla da 

Bir karpuzu ikiye bölmekle, bir portakalı dilim dilim ayırmakla

Anlatılabilir

Ama bizim memleketimizde şiir

Yazık ki ölümle anlatılır biraz

Ölümle anlaşılabilir

Olsun, diyeceksin ne çıkar bundan

Biz hayatı şiirden

Şiiri hayattan özümlemedik mi

Ölümde girse araya

Sahici aşklar kurmadık mı seninle

Tertemiz, dosdoğru aşklar

İzmir''de

İzmir''in eski rıhtımında 

Unutmak için şimdilik

Kolayca unutulmaz ya

İçimizdeki bin dokuz yüz yetmiş bir yazını.

Yeni bir yüzmüydü ne

Kuru bir bozkırı çıkarıp göğsünden

Yeni yazdığı bir şiiri düzeltiyordur Ahmet Oktay

Alnını dayayaraktan cama

Kalemsiz kağıtşiz yazar çünkü Ahmet Oktay

İçinden geldiği gibi

Ve mısra çeker durmadan, hafifçe eğri sırtını doğrultarak

Nemlenir kimi zaman da gözleri

Şiir yürür, şiir sever, şiir içer mi

Şiir mi

Yürür de, sever de, içer de elbet.

Kocaman bir sevgi miydi ne

Dünyanın bütün zamanlarını dolaşan

Bastırıp gögsüne bozkırın

Ey, baksana, diyor, ne biçim kent bu

Geçerek caddelerinden

Dalarak meyhanelerine

Ne biçim kent bu

Bilmiyor ki nice insan kolsuzdur

Sevgisizliğe, bir sevgisizliğe kullanırlar kolu.

Hohlayıp siliyorum iyice

Gözlüğümün camlarını

Göğe bakıyorum gözlerimi kısarak

Güneye gidiyor bir leylek sürüsü

Yeni Caminin üstünde

Son bir defa daha süzülerekten

Erimeye yüz tutuyor kentin pembe kapıları

Günbatımı! 

Günbatımı! yeni konuşmaya başlayan bir çocuğun diliyle

Kolumu tutuyor Feşi Naci, şu manzaraya bak, diyor

Tam Galata Köprüsünün üstünde

Diyor ya, biz alıştık, yüreklerimize bakıyoruz gene de

Uykusuz gecelerimize bakıyoruz: onurun uykusuzluğu

Susturulmanın

Ve gün batımıyla leylek sürüsü 

Hüzünlü bir görüntüyü akıtıyorlar Naci''nin yüzüne

Kırılmak ama birlikte

Birlikte, ama kırılmamak

ve sanki kalplerimiz her yani dökülen bir otobüste

Öyle

İşte son damlalarını da bırakıyor güneş

Karanlık bastiracak neredeyse

Tırmaniyoruz Yüksekkaldırımı

İyi biliyoruz, sevgimiz de öfkemiz de yalnız bizim olmamalı

Güneş çekiliyor iyice

Ne manzara kalıyor, ne göğün evlerindeki kızartı

Ak bulutlar kara bulutlar

Ötede bir bulut yavrusu

Bilinmeli, diyoruz yeniden

Yeniden başlamalı, yeniden

Dostum, görüyorsun ya işte

Bozuldu birkere umudun ordusu.

Gelsene, diyordu İzmir''deki sevgilim

Son mektubunda

Kemetaltındaki kahveleri anlatıyordu

İnce belli çay fincanlarını

Kim bilir, belki de avutmak istiyordu beni

Unutup kendi mahzunluğunu

O kadar çabuk yeşerir ki, diyordu umut

Öyle çabuk çiçeklenir ki

Güçtür çünkü, herşeyden daha güç

Denize, göğe toprağa karışmış bir kalebentlik

Üstelik biliyorsun da

Öfkeliyiz, öfkeyse sonuçtur er geç

Bir aşk gibi yaşamak gerek öfkeyi

Sevginin ağıtıdır bir bakıma

Ve bir gün de gelebilir ki sevgilim

Kapkara bir davet olabilir kin

Zulmün ve tutsaklığın diyeti olabilir

Sen bunu bilemezsin

Bilsen de şairsin, havalar da, soğudu, kendine iyi bak

Ve sakın unutma: sıra öfkenin.

Bin dokuz yüz yetmiş bir yazı

Yok böyle bir sevgilim benim

Ama dayanıklı, ama gözü pek, ama umutla dolu

Olunca böyle bir sevgilim olsun isterdim.

Elimde bir çanta, şurda burda dolaşıyorum

Hep bir yerlere gideceğim sanki

Güvercinler konuyor saçlarıma bileklerime

Uçuşuyorlar

Bir çınar yaprağı düşüyor ayaklarımın dibine

Kupkuru

Elime alıyorum, çiziyorum üstüne kalbimi

Kalbim, diyorum

Yorgunsa da, yaralıysa da, hepimizin', 'Fethi Naci''ye Geldin mi, iyi Yollarından yürüyüsler sızdıran sonbahar Bir tenhalığı eskisinden çok sezmeyi Bakımsız bahçeler mi olur, büyük ...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":158,"source_url":"https://www.antoloji.com/dostlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ek', 'ek-edip-cansever-ip8ep', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Silik bir izlenim gibi kaliyordum kendimde

Elimle filan bir seyler yaptigimi goruyordum

Seyrek de olsa konusuyordum, ornegin

Eski bir efsaneyi anlatiyordum birilerine

Ya da bir yerleri tarif ediyordum yuzumu burusturarak

Icki de iciyordum, hem de sert ickiler iciyordum

Bazan bir iki bardak

Bazan da sabahtan aksama kadar

Durmadan iciyordum

Canim elbette, diyordum, nasilsa

Otel batacak, otel batacak!

En onemlisi de tanistirilir gibiydim biriyle

Hic kimselerin ilgilenmedigi

Bazi olaylarin tarihcisi olarak.', 'Silik bir izlenim gibi kaliyordum kendimde Elimle filan bir seyler yaptigimi goruyordum Seyrek de olsa konusuyordum, ornegin Eski bir efsane...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlüyor Ölümünü Ruhi Bey', 'dusluyor-olumunu-ruhi-bey-edip-cansever-pk1ym', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Niye ölmemeli öyleyse

Yaşamak mutlu bir devinimse.

Ölüsünü bekliyor Ruhi Bey

Bir yanda Ruhi Bey bir yanda ölü

Ve görmemek ister gibi ölüyü

Oturmuş bir iskemleye.

Ben ki bir ölüyü beklemekle geçirdim geceyi

Bir ölüyü ve ölünün bütün inceliklerini.

Getirdiler beni sayrılar evine bir sabah

Asansörle yukarı çıkardılar

Tertemiz bir yatağa yatırdılar - ben böyle istedim böyle oldu -

Oda numaran 283''dü aklımda doğru kaldıysa

Pencereden tepeler görünüyordu, bulutlar ve birtakım kuşlarla devinen tepeler

Yakınımdan geçiyordu bazı kuşlar da

Beyaz bir saat asılıydı duvarda. Duvarın her yerinden

Bembeyaz saatler asılıydı

Ve her şey o kadar beyazdı ki, ayrıntılar

Yılların eklem yerlerini gösteriyordu sanki

Ve bütün eklem yerlerinde koskocaman bir ölü

Ruhi Beyin ölüsü

Hepsi de ur gibi beni

Sarmıştı ur gibi Ruhi Beyi

O gün sigara içtim akşama kadar

- İkinci gün aldılar sigaramı -

Ve saatler biraz sarardı

Sarardı bütün ayrıntılar.

Ve otuz sekizin altına düşmedi ateşim

Yataktan kalkamadım

O gece uyuyamadım sabaha kadar

Koridorlarda ayak sesleri, bağrışmalar

Kapı gıcırtıları ve acayip sesler

Bilmem böylece kaça çıktı beklediğim ölüler.

Üçüncü gün kan şişeleri, tüpler, serumlar

Doktorlar, hastabakıcılar

Aralıksız girip çıkmalar

Gidip gelmeler

Tepelerden pencereye akan kuşlar

Pencereye sıvanan kuşlar

Ve benim mutluluğumun altında

Kararıp yitti bütün ayrıntılar

Bir daha görünmedi

Ve artık hiç görünmeyen

Şişeler, tüpler, serumlar.

Ve o gün ilk defa ölüsünü gördü Ruhi Bey

Soğumuşgövdesini gördü

Donuk gözlerini, durmuş kalbini

Gördü neye benzerse bir ölü.

- Ben Ruhi Bey nasılım

- Mutlusunuz Ruhi Bey.

Yarın gazetelerde çıkacak ilanlarım

Ruhi Bey öldü

Bu ölüm töreninde mutlaka bulunacağım

Bir daha görmek için ölümü

Çelenkler yığılacak avluya

Ki benim sayısız ölülerime

Yaldızlı yapraklarını kıpırdatarak bakacaklar

Sevgiyle

Ve babam elinde gümüş kırbacıyla

Bir başına bir ölü

Annem bir limon görüntüsünün önünde giyinmiş ölümlüğünü

Ölüler halinde duracak onlar da

Dışımdaki ölüler, içimdeki ölüler

Bir alaşım halinde, donuk güneşin altında

Ve benim mutluluğumun altında

Akıp gidecek bütün kötülükler

Ölümün armaları gibi

Akıp gidecekler en sonunda

Niye ölmemeli öyleyse

Yaşamak mutlu bir devinimse.

KORO

(Çiçek sergicisi, meyhane garsonu, meyhane patronu, kürk tamircisi Yorgo,

Hayrünnisa, genelev kadını, otel katibi, cenaze kaldırıcısı Adem, akordeoncu

kadın, emekli postacı, vb.) 

Çelenklerimizle geldik, yoktunuz

Ara sokaklarda, pasajlarda aradık, yoktunuz

Meyhanelere baktık, otellere sorduk, yoktunuz

Nerdesiniz, Ruhi Bey? 

RUHİ BEY

O kadar bekledim ki, geliyorum

Ölümümü bekledim, geliyorum

Bir ölüyü ve ölünün bütün inceliklerini

Bekledim geliyorum.

Ben Ruhi Bey, mutlu olan Ruhi Bey

Ölümü gömdüm, geliyorum

Bir sonbahar günüydü, geliyorum

Güneşler buz gibiydi, geliyorum

Ve bütün kötülükler

Ölümün armaları gibiydi

Size anlatırım, geliyorum.

Hepsini, hepsini gömdüm, geliyorum

Havuzun kırık taşlarını - siz bilmezsiniz -

Limonluğu ve kırmızı konağı - siz bilmezsiniz -

Aynalarda kendini seven Ruhi Beyi - siz bilmezsiniz -

Ve bildiğiniz Ruhi Beyi -ya da pek bilmediğiniz -

Gömdüm ben, geliyorum.

KORO

İyi biliriz sizi biz, iyi biliriz

Nerdesiniz Ruhi Bey.

RUHİ BEY

Gömdüm hepsini, geliyorum

Bütün ölülerimi gömdüm, geliyorum.

KORO

Peki ya sonuç, Ruhi Bey, ya sonuç

Biz sizi tanımaz mıyız

Siz ne yaparsınız bundan sonra, biz ne yaparız

Bir bütünün parçalarıyız, bir bütünün parçalarıyız.

RUHİ BEY

Sonuç mu dediniz, ne dediniz, ne dediniz

Sonuç hiç gömülür mü, geliyorum

Ben yalnız ölülerimi gömdüm, geliyorum.

KORO

Doğrusu anlamıyoruz Ruhi Bey

Her insan biraz ölüdür

Biz ki bir bütünün parçalarıyız, biliriz

Her insan biraz ölüdür.

RUHİ BEY

İnsan yaşıyorken özgürdür

Yaklaştım iyice, geliyorum.

KORO

Her insan biraz ölüdür

Biz de biraz ölüyüz.

RUHİ BEY

Ölüler ki bir gün gömülür

İçimizdeki ölüler, dışımızdaki ölüler

İnsan yaşıyorken özgürdür

İnsan

yaşıyorken

özgürdür.', 'Niye ölmemeli öyleyse Yaşamak mutlu bir devinimse. Ölüsünü bekliyor Ruhi Bey Bir yanda Ruhi Bey bir yanda ölü Ve görmemek ister gibi ölüyü O...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":128,"source_url":"https://www.antoloji.com/dusluyor-olumunu-ruhi-bey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey', 'ey-edip-cansever-ashor', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu boyle kimin gittigi? Sen dur ey!

Belki de ellerimiz mi? biraz ince, biraz da cok kelimeli!

Bu sanki niye durdugumuz mu? acikken sevisme bolgeleri

Ay, pencere, goz! Siz git ey!

Kim bilir neyi saldigimiz bu da, yalnizligimiz gel

Yirtici kuslari mi gozlerimizin, onlar mi bu suruylen

Yoksa onlar mi iste seninle sevisme biciminde

Oysa sevgimiz yerde, kara sevda sen uc ey!

Sen usul, ben yavas, kime yarasir bu sessizlik

Kim biner bu gemiye insandan kiyilar yapilirken

Yetmez mi dalgasi vursundu azicik gozlerimize

Gozlerin gozlerime, siz bak ey!

Su sen de olmasan insan cildiracak mi

Hic yoktan bir yerlere mi gidecek belki

Olsun neresi olursa, git karanlik ama git

Gecemizde durani sen kal sey!

Benim bu cok elli, bu cok gozlu delismen

Cok bildim sana yarasir olmayi gunlerce

Sunu sevdim, suna ozendim, sununla yetindim sonunda

Ben miyim simdi nerede, ben cok ey!', 'Bu boyle kimin gittigi? Sen dur ey! Belki de ellerimiz mi? biraz ince, biraz da cok kelimeli! Bu sanki niye durdugumuz mu? acikken sevisme b...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelincikler', 'gelincikler-edip-cansever-euosa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gelincikler tek tek gorundu mu cayirlarda

isi is kasabanin

su yuzlu cocugun isi is

bir de poyraza dondu mu hava

baslar masmavi damarlar fiskirmaya yanaklarindan

faytonlarin turuncu tekerlekleri

yansir gaz tenekeleriyle cevrili bahcelerde

asili camasirlarindan bir tutam civit kokusu alip gider

gelincikler tek tek gorundu mu cayirlarda.

saat onikilerde

postanede mektup yazan adamlara bakar bir semt delisi

durmadan bakar

ki o mektuplar nereye giderse gitsin

oylesine uzundur ki kasaba

gelinciklerden bukulmus bir ibrisim gibi

gidip gelen mektup zarflariyla tarif edilebilir ancak

iclerinde kar serpintisi

iclerinde bozkir

iclerinde herkesin bir guneyi olan

ve marangozlar upuzun kayiklar yaparlar bunun icin

kesersiz, civisiz, elsiz

sadece ruhlarindan

o kayiklari icinde domates dogranan bir aksamustunde yuzdururler

canlanir suya degince hemen

bordalarindaki nakislar

bir derya gulu alip basini gider.

yeter ki gorunsun gelincikler

once tek tek gorunsun sonra topluca

usta bir dogramaci gibi kirmizilar dograr kasaba

gelincikler indi mi cayirlardan

su bardaklarina, berber dukkanlarina girdi mi

duvarlara sicimle tutturulmus siselere

girdi mi bir kere

-aynalari bogacak neredeyse

-tasliklari basacak sel gibi

o zaman...

tam o zaman

marangozlar mis gibi rakilar icerek kayiklarinda

konustukca binlerce kayik

konustukca binlerce kopuk, binlerce kiyi olurlar

ve nedense bir vapur bizi alip goturecekmis gibi bakariz bir-

birimize

unuturuz sonra alip basini gitmeyi de

yeter ki iki dudak arasina konsun gelincikler

ipince bir isliga yerlestirilsin

turkuler suzsun tuveyclerinden

kahveler eski renklerine boyanir yeniden

biralar cig isikta bile parlak

yikanir tertemiz oluncaya kadar yasamak.

gercekte bir sevinc, bir mutluluk yok degildir yureklerimizde

sevgiler umutlar yok degildir

oyleyse neden cabuk kuseriz birbirimize

cabuk ofkeleniriz

durup durup boyle huzunlenmemiz neden

anlamiyoruz da ondan mi yoksa

bir butun oldugunu mutlulugun

umudun bir butun oldugunu

seziyor muyuz yalnizca

baktikca gelincik tarlalarina uzaktan

oyle bir arada guzel

yasamanin lezzetini

kanimizi tutusturdukca gun gunden

bugusunu saldikca

bir tutun dumani gibi yaktikca genzimizi.', 'gelincikler tek tek gorundu mu cayirlarda isi is kasabanin su yuzlu cocugun isi is bir de poyraza dondu mu hava baslar masmavi damarlar fisk...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/gelincikler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmiş Bulundum', 'gelmis-bulundum-edip-cansever-3q4fi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben misim---neymis?---su sesiymis

Oymus---cam kiriklari gibi govdemi yakan---

Yanaginda sardunya kokusuyla yazdan

Kimmis o gelen ya giden kimmis

Bir yabanci mi, yoksa bir ermis

Degilmis, bir cagri bile yokmus uzaktan.

Gunes mi batarmis bir ozel isim bitirir gibi

Yanmis bir agacin yapraklari miymis kimildayan

Ne kalmis bir onceden ya da bir sonradan

Kim koparmis dalindan bu yabani incirleri

Ya kimmis kiyiya ceken hayalet gemileri

Ne yazilmis nereye bu garip kargasadan.

Yildizlar, buyulu ulke, adimi unutturan

Bir kaya, bir ot, bir akarsu

Hangi yaz sarkicilarinin urpertili korosu

Ki butun oluleri siga cikaran

Ve kenti bir olum derinligine salan

Yani bir gul solarken bir gulun acma korkusu.

Siirler yazdim, kitaplar okudum

Elime bir bardak aldim, onu yeniden oydum

Derinlerde kaldim boyle bir zaman

Kim bulmus ki yerini, kim ne anlamis sanki mutluluktan

Ey yagmur sonralari, los bahceler, aksam sefalari

Soylesin benimle biraz bir kere gelmis bulundum', 'Ben misim---neymis?---su sesiymis Oymus---cam kiriklari gibi govdemi yakan--- Yanaginda sardunya kokusuyla yazdan Kimmis o gelen ya giden ki...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gelmis-bulundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidemeyiş', 'gidemeyis-edip-cansever-tv46g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Guz ve kis ve ilkbahar gecti

Yaz carcabuk gecti

Hepsi tekrar tekrar gectiler

Bu bana uzun geldi

Gecem avurtlarim gibi coktu

Ve coktum

Sabahim, sabahlarim

Kabindan tasan sutler gibi buyudu

Ve tastim

Gun gune tasindi, yil yila

Gitmedim, gidemedim', 'Guz ve kis ve ilkbahar gecti Yaz carcabuk gecti Hepsi tekrar tekrar gectiler Bu bana uzun geldi Gecem avurtlarim gibi coktu Ve coktum Sabahi...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gidemeyis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökanlam', 'gokanlam-edip-cansever-wr5kf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(X)

ben buyurum ne zaman her yerde hep deniz olana

yarisi kesik inceden bir parmakla

ondan ki yaslisiyim durup durup sevmenin

ondan ki coraklarda buyudum bir dilim tatli kavunla.

seni bir care yaptim sana ozendim

bazi siirler yirttim yenilerini edindim.

gectimse bir durumdan bir baska duruma hizla

kanla olumle degil bir cesit sokulganlikla

artik ki guclusuyum bir kisiden fazla olmanin

bir anidir susmamsa bakinca kesik parmagima.

acinca gozlerimi ipe cekilmis gunesler varsin

mavi bir cocuksun askimiz mavi bir ambarin ortasindan bakarsin.', '(X) ben buyurum ne zaman her yerde hep deniz olana yarisi kesik inceden bir parmakla ondan ki yaslisiyim durup durup sevmenin ondan ki corak...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gokanlam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözleri', 'gozleri-edip-cansever-4cxqf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sanki hicbir sey uyaramaz

Icimizdeki sessizligi

Ne soz, ne kelime, ne hicbir sey

Gozleri getirin gozleri.

Baska degil, anlasiyoruz boylece

Yapragin daha bir yapraga degdigi

O kadar yakin, o kadar uysal

Elleri getirin elleri

Diyorum, bir seye karsi komaktir gunumuzde ask

Birlesip saliverelim iki tek golgeyi.', 'Sanki hicbir sey uyaramaz Icimizdeki sessizligi Ne soz, ne kelime, ne hicbir sey Gozleri getirin gozleri. Baska degil, anlasiyoruz boylece Y...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Kokuyorsun', 'gul-kokuyorsun-edip-cansever-ynnxy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gul kokuyorsun bir de

amansiz, acimasiz kokuyorsun

gittikce daha keskin kokuyorsun, daha yogun

dayanilmaz birsey oluyorsun, biliyorsun

hircin hircin, pembe pembe

ofkeli ofkeli gul

gul kokuyorsun nefes nefese.

gul kokuyorsun, amansiz kokuyorsun

ve aci ve yigit ve nasil gerekiyorsa oyle

sen koktukca dusumde goruyorum onu

dusumde, yani her yerde

yuzu sararmis, titriyor dudaklari

sakaklari ter icinde

tam alninin altinda masmavi iki ates

iki su

iki deniz bazan

bazan iki damla yaz yagmuru

mermerini emerek daglarinin

siirler soyluyor gene

olumunden bu yana yazdigi siirler

kizaraktan birtakim siirlere

buyuk sular buyuk gemileri sever cunku

ve odur ki buyukluk

siir insanin icinden dopdolu bir hayat gibi gecerse

o zaman olunce de siirler yazar insan

olunce de yazdiklarini okutur elbet

ve senin boyle amansiz gul koktugun gibi

yasamanin herbir yerinde.

gul kokuyorsun, amansiz kokuyorsun

bu koku dunyayi tutacak nerdeyse

gul, gul! diye bagiracak cocuklar butun

herkes, hep bir agizdan: gul! 

ve herseyin ustune bir gul islenecek

saclarin, alinlarin, goguslerin ustune

yureklerin ustune

bembeyaz kemiklerin

mezarsiz olulerin ustune

kurumus gozyaslarinin

titreyen kirpiklerin ustune

kenetlenmis cenelerin

agarmis dudaklarin

unutulmus cigliklarin ustune

kederlerin, yaslarin, sevinclerin

ve herseyin ustune bir gul islenecek.

bir ruzgar, bir firtina gibi esecek gul

yillarca esecek belki

ve ansizin dunyamizi gorecegiz bir sabah

gorecegiz ki

biz dunyamizi gercekten gormemisiz daha

geceyi, gunduzu, yildizlari

gormemisiz hic

tanismaya komamislar bizi guzelim dunyamizla.

oyleyse dostlar birakin bu yalnizliklari

bu umutsuzluklari birakin kardesler

goreceksiniz nasil

guller guller guller dolusu

nasil gul kokacagiz birlikte

amansiz, acimasiz kokacagiz

dayanilmaz kokacagiz nefes nefese.', 'gul kokuyorsun bir de amansiz, acimasiz kokuyorsun gittikce daha keskin kokuyorsun, daha yogun dayanilmaz birsey oluyorsun, biliyorsun hirci...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/gul-kokuyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Atomların Yaptığı Ayak', 'guzel-atomlarin-yaptigi-ayak-edip-cansever-zaj1z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir menekse duyuyorum ellerimsiz

O kadar guzel ki, Amerika bile guzel

Sen bile guzelsin bensizce

Atomlar bile guzel

Molekuller bile

Toplanip ayak oluyorlar bende

Agiz oluyorlar biraz

Dis oluyorlar keskince

Iki goz parlakca

On tirnak sivrice.

Bir menekse duyuyorum ellerimle

Bir molekul duyuyorum

Bir atom

Korkunc

Birlesip ayak olmuyorlar bende

Agiz, dis, tirnak

Goz olmuyorlar

Hep birden,

Hep birden bir sey oluyoruz iste

Agzi, burnu, elleri, kollari

O korkunc guzellige karsi.', 'Bir menekse duyuyorum ellerimsiz O kadar guzel ki, Amerika bile guzel Sen bile guzelsin bensizce Atomlar bile guzel Molekuller bile Toplanip...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/guzel-atomlarin-yaptigi-ayak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Bir Pul Hiç Bir Zarfa Yakışmıyor', 'hic-bir-pul-hic-bir-zarfa-yakismiyor-edip-cansever-9717x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hicbir pul hicbir zarfa yakismiyor

Hicbir zarf ucbes satira

Ne zaman yanyanayiz iste o zaman

Doyamiyoruz tenlerimizin bitmez tukenmez sorgusuna.

Birakmak birakilmak demeyelim

Durmadan yer degistiriyor anlamlar da

Ben ki bir bosluk kadar buyumusum bu yuzden

Sanki kis aylarinda bir ucurumda.

Anlarim sedir agacinin dilinden

Ve usta bir aslan terbiyecisinin ruhundan da

Hic anlamaz olur muyum opusunu de kalbimi

O open sensen bir de dalgalari cekistiren bir kiz cocguyla.

Hepsini biliyorum, hepsi aklimda

Hepsi de hic kimildamayan bir duman gibi havada.', 'Hicbir pul hicbir zarfa yakismiyor Hicbir zarf ucbes satira Ne zaman yanyanayiz iste o zaman Doyamiyoruz tenlerimizin bitmez tukenmez sorgus...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hic-bir-pul-hic-bir-zarfa-yakismiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Güzeldi', 'gece-guzeldi-zeki-demir-8sa5t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tüm gece güzeldi,

sonu böyle bitmese,

o soğuk rüzgar esmese,

beni benden etmese..

Tüm gece güzeldi,

ulaşırken zirveye,

ramak kala bitmeye,

takıldım o kelimeye..

Tüm gece güzeldi,

hayali bile yeterdi,

ne olurdu çok görmeseydin,

sanal olduğunu düşünseydin.....', 'Tüm gece güzeldi, sonu böyle bitmese, o soğuk rüzgar esmese, beni benden etmese.. Tüm gece güzeldi, ulaşırken zirveye, ramak kala bitmeye, t...', ARRAY['Türk Edebiyatı','Şiir','Zeki Demir']::text[], 8.5, '{"poet":"Zeki Demir","poet_slug":"zeki-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gece-guzeldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilincimdeki kelepçe', 'bilincimdeki-kelepce-ergun-yildiz-rakge', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BİLİNCİMDEKİ KELEPÇE

Hep korkarak yaşadım.

Namlunun ucunda ceylan

oltada balık,çırpınan.

Bir kelepçe bilincimde nakış,

Bir parmaklık

bir yanı bahar,öte yanı karakış.

Her yüksek duvarı hapishane,

Her karanlık köşeyi zindan sandım

Öyle geceler bilirimki,

Ölüme gittim rüyalarda.

Alnımda boncuk boncuk terle uyandım.', 'BİLİNCİMDEKİ KELEPÇE Hep korkarak yaşadım. Namlunun ucunda ceylan oltada balık,çırpınan. Bir kelepçe bilincimde nakış, Bir parmaklık bir yan...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilincimdeki-kelepce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam sana...', 'selam-sana-ergun-yildiz-07ycf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Selam sana mücadeleme bayrak olan,

ve bu günüme,ve yarınıma çağlayan.

Bana yaşama direnci veren,

selam sana.

Yanıbaşımda işkenceler gören,

Ve benimle zindanlara giren,

Selam sana.

Gerçeklerimin dayanağı,

Mücadelemin sancağı.

Yitmeyen,

bitmeyen,

beni hiç terketmeyen.

Yarınlarımın umudu,

İnsanlık onuru selam sana.', 'Selam sana mücadeleme bayrak olan, ve bu günüme,ve yarınıma çağlayan. Bana yaşama direnci veren, selam sana. Yanıbaşımda işkenceler gören, V...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/selam-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başımın belası', 'basimin-belasi-ergun-yildiz-3ycb8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben yorgun

Ben biçare,

ve ben...

Meşgalesiz avare.

Ben bakan,göremeyen.

Yaşamayan,ölemeyen.

Bir tuhaf ben,

ve bir de sen.

Başımın belası.', 'Ben yorgun Ben biçare, ve ben... Meşgalesiz avare. Ben bakan,göremeyen. Yaşamayan,ölemeyen. Bir tuhaf ben, ve bir de sen. Başımın belası....', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/basimin-belasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülerek öleceğim', 'gulerek-olecegim-ergun-yildiz-ldwlh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşaret ederek ezilenlerin safını,

Güle güle dediler.

Gülerek düştüm yollara.

Ve yalnız yürüdüm

büyük şehirlerin bulvarlarında.

Koca koca parkların bir küçük köşesinde,

hesabını yaptım hedefe ulaşmanın.

Beni hiç terketmeyen dostu anımsayıp,

Başarısızlığı düşündüm genellikle.

Ve zorluğunu,varmanın güzelliklere.

Gerçekçi adımlarla başladım 

Gerçeğin yolculuğuna.

Doğrultamadım belimi bir türlü.

Yıkılmadımda...

Ama çok tökezledim.

Bir başkası oldum kimi zaman,

Kendimi gözledim.

Ve güldüm.

Oturup ağlayacak yerde,

hep güldüm çaresizliğime.

Durumumu göremediğim için değil.

Zincirimi kıramadığım için,

Olayı kavrayamadığım için değil,

Kendi gerçeğime ağlayamadığım için güldüm.

Hırslandıkça güldüm.

Gülerken üzüldüm.

Böyle direneceğim sonuna kadar.

Kimse gülemeyecek gözyaşlarıma.

Ben güleceğim.

Ezene inat,

Ezildikçe güleceğim.

Ve gülerek öleceğim.

Ergun YILDIZ', 'İşaret ederek ezilenlerin safını, Güle güle dediler. Gülerek düştüm yollara. Ve yalnız yürüdüm büyük şehirlerin bulvarlarında. Koca koca par...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gulerek-olecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni nasıl göreyim', 'ben-seni-nasil-goreyim-ergun-yildiz-pfpfy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen ki herşeyi bilendin.

Neden beni unuttun.

Ben bunca küçükmüyüm.

Merhametli olduğunu söylersin hep.

Herkeste doğrular bunu.

Beni neden ayırdın peki,

Sana yükmüyüm.

Adil olduğunu söylersinde,

Bildim bileli hakkım yenir.

Hadi söyle,

Buna ne denir.

Her şeyi görüyorsunda,

Beni neden görmüyorsun.

Bir kez kolladınmı beni,

Evet de;

Deki canımı vereyim.

Darılma ama,

Sen ki beni görmüyorsun,

Ben seni nasıl göreyim.', 'Sen ki herşeyi bilendin. Neden beni unuttun. Ben bunca küçükmüyüm. Merhametli olduğunu söylersin hep. Herkeste doğrular bunu. Beni neden ayı...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ben-seni-nasil-goreyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmazda...', 'cikmazda-ergun-yildiz-b48t4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Göğsümde bir kuş nefesince nefes.

Sıkıyor ruhumu bir pençe gibi.

Bu duvar,bu kahrolası kafes,

Ve parmaklıklar.

Bir kan denizi görüyorum düşümde.

Bir nöbetçi kulede,

Gözleri hep peşimde...

Kendimi görüyorum bir an

Telörgünün dışında.

Yüzükoyun yere yatmış,

Sırtında altı kurşun deliği,

Tepeden tırnağa kana batmış.', 'Göğsümde bir kuş nefesince nefes. Sıkıyor ruhumu bir pençe gibi. Bu duvar,bu kahrolası kafes, Ve parmaklıklar. Bir kan denizi görüyorum düşü...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cikmazda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne oldu bana', 'ne-oldu-bana-ergun-yildiz-0vsx3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanlıktayım.

Ellerim gözlerim.

Yaban elde, unutulmuş,yitik.

Acılarla sarmaş dolaş

Dipsiz bir bataktayım şimdilik.

Nefret doluyum kimi zaman.

Tüm değerlere düşman,

İnanmışlığıma pişman.

İnan hep böyle kalacağım,

Sen de olmasan.

Denizlerce azgın ruhum,

Okyanuslarca deli.

Bir tuhaf oldum ben 

Senden uzaklara gideli.

Gözlerimde doruklarca duman,

Bir taş kadar cansızım kimi zaman.

Öylece bakıyorum 

Ufka akan akşama

Ağlayamadan.', 'Karanlıktayım. Ellerim gözlerim. Yaban elde, unutulmuş,yitik. Acılarla sarmaş dolaş Dipsiz bir bataktayım şimdilik. Nefret doluyum kimi zama...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ne-oldu-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapabilirmisin', 'yapabilirmisin-ergun-yildiz-e3cm8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben karanlıklardan geldim.

Sen beni anlayabilirmisin.

Hadi söyle,

Yüzün ıslanmadan ağlayabilirmisin.

Bana ait ne varsa seni korkutuyor.

Yinede seni arıyorum.

Sana ait hiçbir şey benim değil.

Sen beni arayabilirmisin.

Sana sevdam,

Uykularımı çiğniyor.

Ama dayanacağım.

Ne kadar sürer bilmiyorum.

Belki bir gün…

Ölmek hakkımı kullanacağım.', 'Ben karanlıklardan geldim. Sen beni anlayabilirmisin. Hadi söyle, Yüzün ıslanmadan ağlayabilirmisin. Bana ait ne varsa seni korkutuyor. Yine...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yapabilirmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkma', 'korkma-zeki-demir-2vbai', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Korkma,

Mutluluğu tatmaktan,

kendin için yaşamaktan,

aşkı bulmaktan,

sevdiğinle olmaktan...

korkma,

ödün vermiyorsun

ne karekterinden,

ne kişiliğinden,

anla artık

sadece seviyorsun

vaz geçmiyorsun ilkelerinden.......', 'Korkma, Mutluluğu tatmaktan, kendin için yaşamaktan, aşkı bulmaktan, sevdiğinle olmaktan... korkma, ödün vermiyorsun ne karekterinden, ne ki...', ARRAY['Türk Edebiyatı','Şiir','Zeki Demir']::text[], 8.5, '{"poet":"Zeki Demir","poet_slug":"zeki-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/korkma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavgada sevmek', 'kavgada-sevmek-ergun-yildiz-r96td', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bağışlayın dostlar.

Ozan,Mahir,Yeliz,

Devrim,Ebru,Deniz.

Ne olur bağışlayın hepiniz.

Birisini sevdim ben,

Hemde sevilmeden.

Onu sizden başka sevdim.

Sizleri satmatım,

Kavgamızı unutmadım ama

Ara verdim.

Ne olur affedin.', 'Bağışlayın dostlar. Ozan,Mahir,Yeliz, Devrim,Ebru,Deniz. Ne olur bağışlayın hepiniz. Birisini sevdim ben, Hemde sevilmeden. Onu sizden başka...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kavgada-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk kez', 'i-lk-kez-ergun-yildiz-82gmr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerimde ateş,

Yüreğimde kin.

İlk kez kendimde yaşıyorum

Nefret''e yenilişini sevginin.', 'Gözlerimde ateş, Yüreğimde kin. İlk kez kendimde yaşıyorum Nefret''e yenilişini sevginin....', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ilk-kez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsi senin', 'hepsi-senin-ergun-yildiz-dvvue', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Al hepsi senin.

Yaşadığım,yaşayacağım.

Sevdiğim,değer verdiğim,

Ne varsa hepsi senin.

Bir tek şey var isteyemeyeceğin.

Onurum.

Onu istersen 

kahrolurum.', 'Al hepsi senin. Yaşadığım,yaşayacağım. Sevdiğim,değer verdiğim, Ne varsa hepsi senin. Bir tek şey var isteyemeyeceğin. Onurum. Onu istersen ...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hepsi-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir yürek ki bu bendeki', 'bir-yurek-ki-bu-bendeki-ergun-yildiz-yrm1n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir yürek,

cehennemlerce sıcak.

Ve susuz topraklar gibi,

Ahh desem çatlayacak.

Bir yürek ki karanlığı,

Ülkemin zindanlarından beter.

Onu aydınlatmağa ne güneş,

Nede yıldızlar yeter.

Bir yürek ki

Bu bendeki; 

Savunulan son cephe gibi.

Düştü düşecek.

Bir yürek ki

kahkahalarda can çekişmede.

Durdu duracak.

Ergun YILDIZ', 'Bir yürek, cehennemlerce sıcak. Ve susuz topraklar gibi, Ahh desem çatlayacak. Bir yürek ki karanlığı, Ülkemin zindanlarından beter. Onu ayd...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-yurek-ki-bu-bendeki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi artık', 'hadi-artik-ergun-yildiz-ttywa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin tam ortası.

Gelişin için erken,

Gidişin için geç.

Sabahın üçünde

İki dünya kurdum

Senin için.

Hadi kalk birini seç.

Birazdan gün doğacak.

Hadi bul yerini artık.

Ya benimle kal,

Ya da …

Öteye geç.', 'Gecenin tam ortası. Gelişin için erken, Gidişin için geç. Sabahın üçünde İki dünya kurdum Senin için. Hadi kalk birini seç. Birazdan gün doğ...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hadi-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Ardından', 'senin-ardindan-ergun-yildiz-78sdt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir yanardağ olmuşum da 

Başım duman duman, 

Yüreğim ateş. 

Bilincim çakılı kaldı ardından. 

Sensizlik, sessizliğimle özdeş. 

Sürdükçe kervanını yokluğunun, 

Günleri geceye bağlıyorum. 

Çiğ düşen yapraklar gibi içerim. 

Yüzüm ıslanmadan ağlıyorum. 

Bir yolcu eyledin beni bilinmeyene. 

Pusulasız,yorgun, susuz 

Seni arıyorum geçtiğim yerlerde. 

Günlerdir direnişte gecelerdir uykusuz.', 'Bir yanardağ olmuşum da  Başım duman duman,  Yüreğim ateş.  Bilincim çakılı kaldı ardından.  Sensizlik, sessizliğimle özdeş.  Sürdükçe kerva...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/senin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun Ya', 'sen-yoksun-ya-ergun-yildiz-q2g1m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen yoksun ya,

Geçmiyor zaman.

Senden uzakta,

Tad vermiyor yaşam.

Anlamsız geliyor doğan güneş,

Ayışığında akşam.

Sen yoksun ya,

Öylece kalıverdim ortada.', 'Sen yoksun ya, Geçmiyor zaman. Senden uzakta, Tad vermiyor yaşam. Anlamsız geliyor doğan güneş, Ayışığında akşam. Sen yoksun ya, Öylece kalı...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-yoksun-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nereden bilirdim', 'nereden-bilirdim-ergun-yildiz-ksb2n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nereden bilirdim gülüm,

Son dediğim noktadan başlayacağımı.

Tükenmişliğimi bile umursamazken,

Sana rastlayacağımı; 

Nerden bilirdim.

Sevdamı toprağa verip ellerimle,

Yanıbaşına gömmüşken yüreğimi,

Nereden bilirdim,

Seni seveceğimi.

Kendimden kaçarken sana yakalanacağımı,

Taş kıldığım kalbimin

Sana açılacağını nereden bilirdim.

Belamı ararken

Sevdamı bulacağımı,

İnan hiç düşünmemiştim.', 'Nereden bilirdim gülüm, Son dediğim noktadan başlayacağımı. Tükenmişliğimi bile umursamazken, Sana rastlayacağımı;  Nerden bilirdim. Sevdamı...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nereden-bilirdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürmeli...Sürecek', 'surmeli-surecek-ergun-yildiz-uyp0r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sürecek mücadelemiz dostum.

Kimi yeni başlayacak,

Kimisi yeniden,

Dünün tecrübesiyle katılacak.

Bu günde can vereceğiz,

İşkencelere gireceğiz dün gibi.

Ama sürecek.

Biliyorum,

Ya sen öleceksin,ya ben.

Belkide,

ikimiz birden.

Gökteki güneşi bir daha göremeden,

Biz gideceğiz ama

Başkaları gelecek.

Ve ülkemin üzerine öyle bir gün doğacakki,

Kurşun sıkılmayacak yüreklere,

Kelepçe vurulmayacak bileklere.

Biz o günü yaşamasakta,

Çiçek olarak yeşereceğiz,

Can olarak düştüğümüz toprakta.

Yeşereceğiz,

Hürriyete uyanan bir alacaşafakta.', 'Sürecek mücadelemiz dostum. Kimi yeni başlayacak, Kimisi yeniden, Dünün tecrübesiyle katılacak. Bu günde can vereceğiz, İşkencelere gireceği...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/surmeli-surecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yorumsuz', 'yorumsuz-ergun-yildiz-v05dm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ranza,

Bir battaniye,

Ve bir yatak.

Haa unuttum;

Bir de elektrikli ocak.

Eksi yirmi derecede,

Elektrikli ocak.

Oooh lükse bak.

İnsanca yaşamak dedikleri,

Herhalde bu olacak.', 'Bir ranza, Bir battaniye, Ve bir yatak. Haa unuttum; Bir de elektrikli ocak. Eksi yirmi derecede, Elektrikli ocak. Oooh lükse bak. İnsanca y...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yorumsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne diyeceğim', 'ne-diyecegim-ergun-yildiz-dsb65', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hatırlasana.

Birlikte büyüdük seninle.

Aynı beşikte uyuduk,

Aynı eşikten atladık.

Birlikte güldük,

Birlikte ağladık.

Düğünlere birlikte girdik seninle; 

Azmı oynadık,azmı dalıp gittik

Mızıkanın sesinde.

Eskilerden dinlediğimiz

O masal ülkesine,

Azmı ant içtik 

Birgün döneceğimize.

Dün gibi hatırlıyorum; 

Sen bebek kadar uysal,

Seteneyce bilge.

Sen örste kıvılcımdın yeri geldiğinde.

Sen oyuna kalktığında,

Savaşçılar at binerdi.

Gün doğardı gözlerinde.

Şimşekler susar,

Gök durulur,

Yağmur dinerdi.

Her dönüşünde,

Bin gökkuşağı doğardı saçlarından.

Bin çiğdem,bin menekşe,bin papatya,

Bir anda yeşerirdi topraktan.

Sen böylemiydin o zaman.

Bir militan kadar kararlı,

Bilim kadar kesin.

Sen kalkıp konuştuğunda,

Ruhları paklardı sesin.

Dua kadar yumuşak,

Ölüm kadar keskin,

Gerçeği yüzlere çarpardı sözlerin.

Ve bir anda

Umursamazlığın yerini alırdı hüzün.

Acısı sarardı yürekleri,

Sürülmüşlüğün.

Bir çoğu başını önüne eğerken,

Sen devam ederdin anlatmağa,

Kaldığın yerden.

Şarkılarım senin dilinde güzeldi.

Senin dilinde sevda,

Senin dilinde kavgaydı.

Ama sen bile,

En ummadık anda.

Bırakıverdin bizi yarı yolda.

Sattın...

demeğe varmıyor dilim.

Kavganı değiştin ya sevdanla.

Hemde bir yabancıya.

Ama aldanma.

Daha ilk günden,

bir başka kavgadasın.

Ya o sen,

Ya sen o olacaksın.

Artık şarkılarını anlamayacaklar.

Sen söyledikçe gülecekler; 

Bizi ağlatan nağmelere.

Sen oyuna kalktığında,

Savaşçılar at binmeyecek artık.

Dönüşünde,

Gök renklere bezenmeyecek.

Şunu iyi bil ki,

Sen onlara özeneceksin.

ve fakat,

onlar sana özenmeyecek.

Eskiden biz derdin

Artık diyemeyeceksin.

Gün gelecek 

Bir de çocuğun olacak.

Ayşe,Fatma,yada Ali.

Fakat bize benzemeyecek hali,

Bize benzemeyecek dili.

Kucağında bir masum; 

O sana,

Sen ona mahkum.

Artık dönülmezin eşiğinde

Ruhunda bir kelepçe ile,

Öylesine yaşayacaksın.

Fakat çare yok; 

Bu iklime uyacak,

Bu toprağa kök salacaksın.

Bir gün biz dönüp giderken,

Sen burada kalacaksın.

Lütfen söyle; 

Seni sorduklarında ne diyeyim.

Bir hata ettiğini,

Yokolup gittiğini nasıl söyleyeyim.

Öldü desem olurmu? ...', 'Hatırlasana. Birlikte büyüdük seninle. Aynı beşikte uyuduk, Aynı eşikten atladık. Birlikte güldük, Birlikte ağladık. Düğünlere birlikte gird...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/ne-diyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürgün', 'surgun-ergun-yildiz-r9poh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elbruz''un Tepesinden doğdu güneş

Yavaş yavaş eteklerine indi.

Ama ne''ye yarardıki

Isıtamayacak,

sevindiremeyecekse insanları

İsterse ayakları dibine insindi.

Güneş Elbruz''un tepesinde doğarken

Eteklerinde battı.

Ve yıllar süren savaşı bitirip,

Kafkasyada göçü başlattı.

Gün doğarken yürüdü konvoy

At.Koyun,sığır.at....kağnı.

At...erkek başı önünde.

At...çocuk herşeyden habersiz

At...gözü yaşlı bir sürü dişi

Üç güneş doğdu Elbruz''un tepesinden

Üç gün karanlık kaldı etekleri.

Ve sonunda terketti karanlığı

Bir buçuk milyon kişi.

Boş; bomboş kaldı evleri.

Böyle başladı bilinmeyene yolculuk

Yollara döküldü bir çok çaresiz insan

Erkek,kadın,çoluk çocuk.

İmamlar var önde

Biz Naip deriz onlara

Din,Vatan için savaşın derken

Onlar kaçmayı öğütlüyor insanlara.

Artık zayıf düşmüşüz

Düşman girecekmiş yurda

Ve o zaman yaşamak,

barınmak günahmış burda

Hay senin dinini.....

diyerek kalkıyor birisi

Fakat susturuyorlar

Çabuk kesiliyor sesi.

Vaz geçiyor bir yiğit ben kaçmam diye.

Burada öleceğim deyip dönüveriyor,

Atını kamçılıyor geriye.

Kafir diyor bir ağızdan İmamlar.

Sıkılmadan bir kahramanı lanetliyorlar.

İlerliyor konvoy.

Önden arkası,arkadan önü görünmez.

Hedef neresi? 

bilinmez.

Arkadan sürükleniyor aldananlar.

Din adına vatanı bırakanlar

çaresiz,aldatılmış insanlar.

Şamil''in,Hacı Murat''ın çocukları

Kafir olmamak için kaçan kahramanlar.

Söyledik ya.

Önde İmamlar

Arkasında servetini,mülkünü kaçıran

kendini kurtaran ağalar.

Derken hastalık başlıyor birden

Bir rüzgar gibi esip geçiyor salgın

Gücü bitmiş insanların içinden.

Günlerce çekilen acı,eziyet,zulüm

Ve vatandan uzakta gelen son.

Pişmanlık,çaresizlik...

ve ölüm.

Artık mezarlığa dönüyor her konak yeri.

Birer birer toprağa veriyorlar ölüleri.

Önce yaşlılar,sonra çocuklar, daha sonra kadınlar

Ve her konak yerinde bir mezar

Ölüler,mezarlar....mezarlıklar

Ağlayan analar,yetim çocuklar.

Çaresizlik içinde

İleri gidemeyen

geriye dönemeyen zavallı insancıklar.

Ağır ağır ilerliyor konvoy.

Önde imamlar,arkada ağalar

Daha arkasında aç,açık,hasta,çıplak insanlar

Yarısı yolda ölmüş aileler

Yaslı analar,babalar....

Ve sonunda denize iniyorlar

Dağılıyorlar buradan dört bir yana

Kucak açıyorlar guruplar halinde; 

Her gurup ayrı bir zaman''a.

İmamlar birer kurtarıcı gibi,

Din''i kurtarmanın sevabını anlatıyor herbiri.

Zavallı halk seviniyor.

Çektiği acıya bakmadan.

Halifenin ülkesindeler artık.

Burası yeni vatan.

Dağılıyorlar ülkenin dört yanına.

Kafkas kültürünü gömmek üzere getiriyorlar

Türk vatanına.

Değişen bir şey olmuyor.

Ağalar yine ağa gibi yaşıyor,

Yoksul yine yoksulca.

Ve zaman geçip tarih olduğunda,

Din adına vatanı terkedenler,

Dillerinide unutuyorlar birer birer.

Ergun YILDIZ', 'Elbruz''un Tepesinden doğdu güneş Yavaş yavaş eteklerine indi. Ama ne''ye yarardıki Isıtamayacak, sevindiremeyecekse insanları İsterse ayaklar...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/surgun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son İstasyon', 'son-i-stasyon-ergun-yildiz-z77a6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akültürasyon

Ajitasyon

Asimilasyon

Dilsiz halk

Ruhsuz sürü

Tarihin bataklığı

Son İstasyon.', 'Akültürasyon Ajitasyon Asimilasyon Dilsiz halk Ruhsuz sürü Tarihin bataklığı Son İstasyon....', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/son-istasyon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumdaki hapishane', 'ruhumdaki-hapishane-ergun-yildiz-f0xur', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Herşeyden yüce bellediğim,

Uğruna canımı verdiğim,

ve hain damgası yediğim ülkem.

Ömrümce yücelttiğim,

Ama beni aşağılayan; 

ve yokolmağa zorlayan ülkem

Dilimin,kültürümün mezarı.

vatandaşı olduğum

Ama bana vatan olamayan ülkem.

Ruhumdaki hapishane.', 'Herşeyden yüce bellediğim, Uğruna canımı verdiğim, ve hain damgası yediğim ülkem. Ömrümce yücelttiğim, Ama beni aşağılayan;  ve yokolmağa zo...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ruhumdaki-hapishane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilim', 'dilim-ergun-yildiz-5ewug', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dilim

Zor günlerimde sığındığım kale,

Düşman''a karşı zırhım,kalkanım.

Ve dilim,

Yolumu aydınlatan meşale.

Dilim,öksüz evladım.

Bildiğim ama konuşamadığım,

Ve yazamadığım.

Unutmamağa yemin ettiğim alfabe.

Zavallı dilim.

Her gün biraz daha yitirdiğim.', 'Dilim Zor günlerimde sığındığım kale, Düşman''a karşı zırhım,kalkanım. Ve dilim, Yolumu aydınlatan meşale. Dilim,öksüz evladım. Bildiğim ama ...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben unutmadım', 'ben-unutmadim-ergun-yildiz-2rk70', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep unuttun,unuttun diyorsun.

Hep beni suçluyorsun da

Neden,nasıl demiyorsun.

Benmi istedim sanıyorsun.

Dilimi koparttılar be.

Dilimi...

Lanet olsun; 

Hafızamı yırtıp aldılar 

Bir yaprak gibi.

Yüz yıl boyu yonttular beni,

diledikleri biçime sokmak için.

Yüzyıl.

Geriye baktığımda boşluk gördüm.

İleriye baktığımda boşluk.

Köküm yokmuydu benim; 

göktenmi düştüm be,

Söylesene...

Kara yığdılar pencereme

Kara.

Güneşi görürsem uyanırım diye.

Uyanırda kapılarına dayanırım diye.

Beni saraylarına hizmetçi,

sınırlarına bekçi koydular.

Bedenimi kullanmak için,

ruhumu soydular be; 

Ruhumu...

Yinede direndim.

Ama,bunca direnebildim.

Bir daha unuttun deme.

Ben unutmadım; 

Bu kadar öğrenebildim.', 'Hep unuttun,unuttun diyorsun. Hep beni suçluyorsun da Neden,nasıl demiyorsun. Benmi istedim sanıyorsun. Dilimi koparttılar be. Dilimi... Lan...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ben-unutmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yurtsuz', 'yurtsuz-ergun-yildiz-joj5m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anasız büyüdüm.

Ve babasız...

El kapılarında yetiştim.

Ayağım çarıksız,sırtım urbasız.

Yurtsuz derlerdi bana,

Böyle çağırırlardı beni.

Ve ben ilk kez; 

Bu sözcükte tanıdım seni.

Dedim ya; 

Açtım,açıktım.

Öksüzdüm,ufacıktım,

Bazen günlerce karnım doymazdı.

ama bunların hepsi birden; 

Daha o çağda bile 

Yurtsuzluk kadar koymazdı', 'Anasız büyüdüm. Ve babasız... El kapılarında yetiştim. Ayağım çarıksız,sırtım urbasız. Yurtsuz derlerdi bana, Böyle çağırırlardı beni. Ve be...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yurtsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-ergun-yildiz-jm2bh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kanımla yoğurduğum,

Tarihimle doğurduğum,

Ellerimle yarattığımsın.

Ve bu gün herşeye rağmen,

Yüz küsur yıl ötelerden 

Yüreğimde yaşattığımsın. 

Sen; 

Çocuk olup koşamadığım,

Genç olup yaşamadığım,

Ölümde kucaklaşamadığım topraksın.

Sen bana çok yakınsın,

Ve pek çok uzaksın.

Eylül 1983', 'Kanımla yoğurduğum, Tarihimle doğurduğum, Ellerimle yarattığımsın. Ve bu gün herşeye rağmen, Yüz küsur yıl ötelerden  Yüreğimde yaşattığımsı...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir dağ ki o', 'bir-dag-ki-o-ergun-yildiz-qvczy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir dağ''ki o başında dört mevsim kar.

Bir kar''ki beyazı gözleri yakar.

Bir dağki o doruklarında efkar,

Etekleri bahar.

Yaylalarında halkım yaşar.

Bir dağki o; 

kucağı ana gibi sıcak.

Yiten yavrularına ağlar yüzyıldır.

Irmak ırmak.

Bir dağ ki o

masallardaki gibi.

Başı yıldızlarla yanyana,

Gögsü cennet yeşili.

Bir dağki o; 

Deniz gelmiş ayaklarına.', 'Bir dağ''ki o başında dört mevsim kar. Bir kar''ki beyazı gözleri yakar. Bir dağki o doruklarında efkar, Etekleri bahar. Yaylalarında halkım y...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bir-dag-ki-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz bize ettik', 'biz-bize-ettik-ergun-yildiz-ybxfc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biz sökemedik yüreğimizden 

Yüz yıllık ezilmişliğin acısını.

Sökemedik,

ismimize iliştirilen hain damgasını.

Biz yalanlara,yalancılara değil; 

kendimize darıldık.

Halklar zincirlerini kırarken

Biz zincirlerimize sımsıkı sarıldık.

Ve sustuk...

Boğazımızı sıkan zinciri gevşetip

haykıramadık gerçeği.

Biz susmakla kabullendik herşeyi.', 'Biz sökemedik yüreğimizden  Yüz yıllık ezilmişliğin acısını. Sökemedik, ismimize iliştirilen hain damgasını. Biz yalanlara,yalancılara değil...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/biz-bize-ettik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anımsamak', 'animsamak-ergun-yildiz-hd6l3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir çocuk gördüm bu gün,

Zorla kopartılıp götürülen,

Anasından,yuvasından.

Dedemi düşümdüm bir an

Gayriihtiyari.

Dolaşıverdi hafızam

yüzyirmibeş yıl öteleri.', 'Bir çocuk gördüm bu gün, Zorla kopartılıp götürülen, Anasından,yuvasından. Dedemi düşümdüm bir an Gayriihtiyari. Dolaşıverdi hafızam yüzyirm...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/animsamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben...veya sen', 'ben-veya-sen-ergun-yildiz-9lu72', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben,etten sökülen tırnak.

Kopartılan anasından,ağlayarak.

Ve ben...

Kendinden kaçırılan,

zorla göçürülen,

bir sürünün bir kuzusu.

Başkası olamayan,

kendini bulamayan ben.

Daha çocuk çağında Ethem''i öğrenen

Ama gerçeği öğrenemeyen.

Ethem''den utanan,

Rauf''u,Yusuf''u tanımayan ben.

Ergenekon''u ezberleyen,

Halkının sürgününü bilmeyen.

İki yabancı dil bilen,

kendi dilini öğrenemeyen

ve öğretemeyen. 

Günden güne tükenen,

geçmişi olan,

Geleceği olmayan ben.

Veya sen...

Ergun YILDIZ', 'Ben,etten sökülen tırnak. Kopartılan anasından,ağlayarak. Ve ben... Kendinden kaçırılan, zorla göçürülen, bir sürünün bir kuzusu. Başkası ol...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ben-veya-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Genksiz Gül', 'genksiz-gul-yalniz-kurt-33b54', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'rensiz gül

salıver ortalığa burcu kokunu

konakla içime

vakit

geçiş vakti olsada

kuşlar kanat kelebekler kanat

ve sevdalar kanatlanırken kokuna

konar kimbilir

senden uzak 

nice aşkın kucağına

renksiz gül

gülebildiğince

birgün senide bulur

haziran çiçekleri bahar kokuları

bulursun saçlarına

buket buket

seviyor  nidaları

beyaz papatyaları

rensiz gül

gece dönüşümü 

            dönüşünü

               düşünü unutmuşsun

sesimi sesini

    ses  siz liğimizi  unutmuşsun

renksiz gül

kaç deneyim 

yaşamak böyle

hangi pazarda  tahta tezgahta

nasırlı ellerde yanık yüzlerde

aç gönüllerde

devrimlerimin çoşkusu gecelerde

yanyana dizdize

elele gözgöze 

hangi pazarda tahta tezgahta sunuldun

bir kesinti oldun

öbek öbek

tomurcuk veren yediveren

ne olduğunu bilmeyen

renksiz  gül

sen ne zaman büyüdün 

bir  selamda kaç baharda 

çiçekleri soldururken 

umursamaz havanda

renksiz  gül

gülebilirsen

özlersin içinden 

üstündeki güneşi

                    rengini

bu sana

enson söz 

    enson göz

       enson ses

enson şiirimdir

renksiz  gül

kalemim bile susmuşken şimdi

al renklerin engüzelini kendince

döllen

dön etrafında dönebildiğince

çiçek bozuğu yarınlara

                        öylece', 'rensiz gül salıver ortalığa burcu kokunu konakla içime vakit geçiş vakti olsada kuşlar kanat kelebekler kanat ve sevdalar kanatlanırken koku...', ARRAY['Türk Edebiyatı','Şiir','Yalnız Kurt']::text[], 8.5, '{"poet":"Yalnız Kurt","poet_slug":"yalniz-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/genksiz-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlar', 'onlar-ergun-yildiz-85bzg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Onlar bizim çocuklarımız.

bak,yüzlerinde güneş,gözlerinde ışık.

Aldanma gülüşlerine sen,

Yüreklerinde yüz yıllık ayrılık.

Kolay değil gizlemek 

Bu gecenin karası gibi,

Yürek yarası gibi hüznü.

Onlar atalarımızın enkazı dünden kalan

onlar yarınımzın umudu yeşerecek olan.

Dünü ve bugünü

Bir Çerkes süvarisi gibi yarına taşıyan,

Bizim çocuklarımız onlar.

Kazaska''da,Şımka''da

Atlarımız gibi şahlanan.', 'Onlar bizim çocuklarımız. bak,yüzlerinde güneş,gözlerinde ışık. Aldanma gülüşlerine sen, Yüreklerinde yüz yıllık ayrılık. Kolay değil gizlem...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/onlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Problem', 'problem-ergun-yildiz-i4651', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Türk Türkiye''de,

İspanyol İspanya''da

Arap Suriye''de

Halkım Türkiye''de

Halkım İspanya''da

Ve halkım suriye''de.

Bir hata var bu denklemde,

bir hata var. 

Ama nerede?', 'Türk Türkiye''de, İspanyol İspanya''da Arap Suriye''de Halkım Türkiye''de Halkım İspanya''da Ve halkım suriye''de. Bir hata var bu denklemde, bir ...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/problem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşıyorsan ses ver', 'yasiyorsan-ses-ver-ergun-yildiz-e62u6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Neden görmüyorsun

Neden ses vermiyorsun

bir taş gibi durma öyle

hadi uyan artık

bir şey söyle.

Toprağını alıyorlar

özgürlüğünü çalıyorlar

heeeeeeey! 

uyan lütfen', 'Neden görmüyorsun Neden ses vermiyorsun bir taş gibi durma öyle hadi uyan artık bir şey söyle. Toprağını alıyorlar özgürlüğünü çalıyorlar he...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yasiyorsan-ses-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzünü görmek istiyorum', 'gokyuzunu-gormek-istiyorum-ergun-yildiz-peg8x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dün ekmek istiyordum,

Hakkımı istiyordum.

Yumruğum havada yürüyordum caddelerde.

Söke söke alıyordum benim olanı.

Ama çok sürmedi.

Kaderimizi çizenler buna''da izin vermedi.

Tanklar yürüdü gecenin karanlığında,

Bir namlu hissettim şakağımda.

Ve geri aldılar herşeyi.

Yıllarımı verdiğim bahçeye girip; 

Pervasızca çiğnediler çiçeklerimi.

Ve emeğimi...

Ve ekmeğimi...

Onlar kışlalarına döndüler,

Ben bahçeme dönemedim.

Dün ekmek istiyordum 

Bugün...

GÖKYÜZÜNÜ GÖRMEK İSTİYORUM', 'Dün ekmek istiyordum, Hakkımı istiyordum. Yumruğum havada yürüyordum caddelerde. Söke söke alıyordum benim olanı. Ama çok sürmedi. Kaderimiz...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gokyuzunu-gormek-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'diyalektik', 'diyalektik-yalniz-kurt-vqr3m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen

bende 

düşünce

diyalektığinin

en 

şaşaalı

yanı

bir

gece

kuruntum

         alyakuz', 'sen bende  düşünce diyalektığinin en  şaşaalı yanı bir gece kuruntum          alyakuz...', ARRAY['Türk Edebiyatı','Şiir','Yalnız Kurt']::text[], 8.5, '{"poet":"Yalnız Kurt","poet_slug":"yalniz-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/diyalektik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Netekim siyah olmalı kağıtlar', 'netekim-siyah-olmali-kagitlar-ergun-yildiz-tit38', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Değerli hemşehrilerim, 

Netekim

Kırmalı yazan kalemlerin ucunu

Gördüğü herşeyi yazmasın diye.

Demirden kafese koymalı kağıdı,

Kimse okumasın, çizmesin diye.

Kaldırmalı bu aleti yeryüzünden

Toplatıp yoketmeli bütün kalemleri.

Netekim bu kalemler döküyor ak kağıda

gereksiz,bölücü,zararlı fikirleri.

Nesine gerek köylünün,işçinin okumak.

Herkes işiyle uğraşsın, ne gerek kitap gazete.

Yüzde ikiyüz vergi koymalı halk yararına; 

Kalem kağıt üreten her şirkete.

Değerli hemşehrilerim.

Netekim; 

Beyaz kağıt üretimini yasaklamalı.

Siyah,simsiyah olmalı bütün kağıtlar.

O zaman herkes okusun okuyabildiğince.

Kara kalem kara kağıda nah yazar.', 'Değerli hemşehrilerim,  Netekim Kırmalı yazan kalemlerin ucunu Gördüğü herşeyi yazmasın diye. Demirden kafese koymalı kağıdı, Kimse okumasın...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/netekim-siyah-olmali-kagitlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben kim olsam', 'ben-kim-olsam-ergun-yildiz-io45s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '.....

.....

Ezmesem,ezilmesem.

Acıkmasam,çalışmasam.

Beynimi kullanmağa zamanım kalsa.

Ruhumu dinlemeğe bir anım olsa.

Kul olmasam,şah olmasam.

Ayağa çarık,başa külah olmasam.

Ben yalnızca ben olsam.

.....

.....', '..... ..... Ezmesem,ezilmesem. Acıkmasam,çalışmasam. Beynimi kullanmağa zamanım kalsa. Ruhumu dinlemeğe bir anım olsa. Kul olmasam,şah olmas...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ben-kim-olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şikayetname', 'sikayetname-ergun-yildiz-xg27c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Başbakanım,başbakanım

Ortadirek bel veriyor.

Yıkılıyor sabır bendi

kalk toparlan sel geliyor.

---

Ortadirek yaşar dedin

kasa dolar taşar dedin

Enflasyon düşer dedin

Ne desen masal geliyor

---

Sattın bütün memleketi

sefil ettin bu milleti

insana bir kilo eti 

alamamak zül geliyor

---

halkın yüreği yaralı

dertler üstüste sıralı

köprüler yollar paralı

başımıza hal geliyor

---', 'Başbakanım,başbakanım Ortadirek bel veriyor. Yıkılıyor sabır bendi kalk toparlan sel geliyor. --- Ortadirek yaşar dedin kasa dolar taşar ded...', ARRAY['Türk Edebiyatı','Şiir','Ergun Yıldız']::text[], 8.5, '{"poet":"Ergun Yıldız","poet_slug":"ergun-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sikayetname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Yüz', 'i-ki-yuz-mert-egemen-yemenoglu-cw0kw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin iki yüzün var;

Birisiyle beni,

Ötekisiyle kendini aldatıyorsun...

Senin iki yüzün var;

Biliyor musun?

Gördüğüm en büyük yüzsüzsün...', 'Senin iki yüzün var; Birisiyle beni, Ötekisiyle kendini aldatıyorsun... Senin iki yüzün var; Biliyor musun? Gördüğüm en büyük yüzsüzsün......', ARRAY['Türk Edebiyatı','Şiir','Mert Egemen Yemenoğlu']::text[], 8.5, '{"poet":"Mert Egemen Yemenoğlu","poet_slug":"mert-egemen-yemenoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/iki-yuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümseyeceğim', 'gulumseyecegim-yalniz-kurt-loepk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gülümseyeceğim

seni topladımya 

masalların ötesinden

kanatlandım

bir çırpı sokaklara

dilimde sen varsınya 

solgun çiçek

sanki zetin dalı 

zeytin dalı yanımda

bana en yakın 

                en uzak

söyle şimdiçiçek

öyle kolay dokunsam

güler yüzlü gövdene

okşasam belini

elbette

severdin beni

gülümseyeceğim

içi

mdeki ağlamaklı dehşete karşın

güler yüzlü biçimledimya seni

inançtır bu

inancımın doğurganı

bir haziran sonrasında

tüm erincim direncim sevgim

tatlı sevdiğim

gülümseyeceğim

senden uzak yanında

yanımda umut

umut um sen

sende kalbim

kalbim kayıp

kayıp sevdiğim

sevdiğim illede sen

illede sen

gülümseyeceğim

kocaman tebessümler yüzümün ortasında sensiz

nekadar sahte durur

üstelik irigözleriniz sönmüş yıldızlar gibi parlamıyorlar

bilmem kaç yüzyıldır

farkında bile değilsiniz

oysa kaç yüzyıldır bekliyorum sizi

değilsiniz farkında değilsiniz

gülümseyeceğim

beceremesemde

eriyip giderken düşlerimde

yaşamın o en can alıcı yanı

bu kederden ayrılıktan yana gece

nasılda hain  nasılda kıydı bana

gülen gök gözlerim yolda

haydi gül bana

haykır sevgini dünyaya

haydi çık karşıma

gülmek insanlara özgüyken

sende gülümse

çılgınca

           alyakuz', 'gülümseyeceğim seni topladımya  masalların ötesinden kanatlandım bir çırpı sokaklara dilimde sen varsınya  solgun çiçek sanki zetin dalı  ze...', ARRAY['Türk Edebiyatı','Şiir','Yalnız Kurt']::text[], 8.5, '{"poet":"Yalnız Kurt","poet_slug":"yalniz-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/gulumseyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Misin', 'sen-misin-fatih-erili-fpcnx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'aşksa bu

gecelerce seni düşünmek

haberin bile olmadan

sensizliğe kanmak yudum yudum

zehirlemeli,zehirlesin beni alabildiğine

yalnızlıksa bu 

aşina suratlar içinde 

yürümekse kalabalık bir caddede 

attığım her adım ölüme

götürmeli,götürsün beni alabildiğine

gözlerinse bu

bir karanfil kokusu gibi

her görüşte içime işleyen 

cennet yeşili gözlerin

vurmalı her defasında,vursun beni albildiğine

ve sen isen bu 

gecelerce gölgesini beklediğim 

farkına bile varmadın 

evrene yetecek sevgimin 

üzülmeli,ağlamalısın alabildiğine', 'aşksa bu gecelerce seni düşünmek haberin bile olmadan sensizliğe kanmak yudum yudum zehirlemeli,zehirlesin beni alabildiğine yalnızlıksa bu ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Erili']::text[], 8.5, '{"poet":"Fatih Erili","poet_slug":"fatih-erili","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bil Ki', 'bil-ki-fatih-erili-smi3d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'geceleri uyuyorsam artık

çok zamandır düşlerime girmiyorsan

güneş aydınlatıyorsa gündüzümü

bil ki seni unutmuşum demektir

gülmeye başladıysa dudaklarım 

kalbim sevmeye başladıysa 

varsa biri hayatımda

bilki seni unutmuşum demektir

fazla kalmıyorsam odamda 

karışıyorsam insan içine

gitmiyorsam artık meyhaneye

bilki seni unutmuşum demektir

şarkılar efkar vermiyorsa nicedir

bırakmışsam sigarayı eğer 

ve unutmuşsam seni

bilki KABİRDEYİM demektir', 'geceleri uyuyorsam artık çok zamandır düşlerime girmiyorsan güneş aydınlatıyorsa gündüzümü bil ki seni unutmuşum demektir gülmeye başladıysa...', ARRAY['Türk Edebiyatı','Şiir','Fatih Erili']::text[], 8.5, '{"poet":"Fatih Erili","poet_slug":"fatih-erili","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bil-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umrumda Değil..!', 'umrumda-degil-hakan-akyurt-xhpjv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaderde varmış seninle olmak,

Elimde değil, sevdim bir kere.

Mutluluk sadece seninle olmak,

Anlamasan da sen ; sevdim bir kere. 

Kalbin bensiz mutlu olacaksa,

Uzak duracağım emin ol senden.

Sensizlikten inan kahrolsam da,

Kaçacağım daima, emin ol senden.

Anladımki; hayatının manası başka,

İstediğin ben değil, sevgim değil.

Göremez ki bu gönül senden başka,

Sevmesende, seveceğim seni umrumda değil...!', 'Kaderde varmış seninle olmak, Elimde değil, sevdim bir kere. Mutluluk sadece seninle olmak, Anlamasan da sen ; sevdim bir kere.  Kalbin bens...', ARRAY['Türk Edebiyatı','Şiir','Hakan Akyurt']::text[], 8.5, '{"poet":"Hakan Akyurt","poet_slug":"hakan-akyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umrumda-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Brak Beni', 'brak-beni-sair-armagan-dol32', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bırak beni yeter aldattın yeter bırak beni

Deli ettin artık çek git bu nasıl sevgi

Sen kendine asıksın sen yalancısın

Hatta sevişirken bile yabancısın

Sen kimsin sen ne rahat insansın bırak

Bırak benim için ne mümkün ayrılmak 

Ben ayrılamam sen beni bırak

Seviyorum kahretsin

Seviyorum elimde değil

Çok seviyorum ah neden

Yasadığım en derin aşksın sen

Çok, istedim unutmak istedim esmer ellerini

Gözlerini, kokunu, yanık tenini

Bana dokunduğun anda hislerini unutmadım 

Oysa sen bir yalancısın

Sen kimsin sen ne rahat insansın bırak

Bırak benim için ne mümkün ayrılmak 

Ben ayrılamam sen beni bırak', 'Bırak beni yeter aldattın yeter bırak beni Deli ettin artık çek git bu nasıl sevgi Sen kendine asıksın sen yalancısın Hatta sevişirken bile ...', ARRAY['Türk Edebiyatı','Şiir','Şair Armağan']::text[], 8.5, '{"poet":"Şair Armağan","poet_slug":"sair-armagan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/brak-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Aşkını Ne Seni', 'ne-askini-ne-seni-sair-armagan-gmxa9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dilimi bağlasalar anmasam hiç adini

Gözümü bağlasalar görmesem hiç yüzünü

Elimi bağlasalar tutmasam ellerini

Silemezler gönlümden ne askını ne seni

Dünyamı karartsalar görmemem için seni

Büyüler yaptırsalar sevmemem için seni

Gurbete gönderseler kan doldursa içimi

Silemezler gönlümden ne askını ne seni', 'Dilimi bağlasalar anmasam hiç adini Gözümü bağlasalar görmesem hiç yüzünü Elimi bağlasalar tutmasam ellerini Silemezler gönlümden ne askını ...', ARRAY['Türk Edebiyatı','Şiir','Şair Armağan']::text[], 8.5, '{"poet":"Şair Armağan","poet_slug":"sair-armagan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-askini-ne-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçime Sinmiyor', 'i-cime-sinmiyor-sair-armagan-ajedu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her sabah güneş doğarken

Yeni bir güne baslarken

Ne zaman ki güzel bir şey görürüm

Sensiz içime sinmiyor

Gözlerim arıyor seni

Benim çocuk sevgilimi

Bir ateş ki yüreğimi ah

Alev yakıyor

Seni bana vermediler 

Seni bana vermediler 

Mutlu olsunlar diyorum

Elbet onlar da severler

Bazen bir çiçek açarken

Bazen bir çocuk gülerken

Ne zaman ki içim tasar sevinçten

Sensiz içime sinmiyor

Dönüp TED baktığım zaman

Hatıralar ağlaşıyor

Bir yara ki her yanımı ah 

İnce sızlatıyor', 'Her sabah güneş doğarken Yeni bir güne baslarken Ne zaman ki güzel bir şey görürüm Sensiz içime sinmiyor Gözlerim arıyor seni Benim çocuk se...', ARRAY['Türk Edebiyatı','Şiir','Şair Armağan']::text[], 8.5, '{"poet":"Şair Armağan","poet_slug":"sair-armagan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/icime-sinmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'neye-yarar', 'neye-yarar-sair-armagan-630bc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saklasa da gözlerim 

Gizleyemez derdini

Gizleyemez gözlerim

Deli gibi sevdiğini

İçimde bir sevinç var

Senelerdir tatmadığım

Bir burukluk

Bir heyecan

Doyasıya yasamadığım

Ne kavga ne ümitsizlik

Ne ağlayan insancıklar

Ne de başka düşüncem var

Bir duygu kasırgası bu

Sardı bütün benliğimi

Karsı koymak neye yarar

Bir yanımda doğrular

Hatalarımsa bir yanımda

Aklim yapma diyorsa da 

Gönlüm bir kez düştü aşka

Simdi ne söyleseler

Aşka dair bilinen 

Su yalan dünyada ne var

Yasamadan öğrenilen', 'Saklasa da gözlerim  Gizleyemez derdini Gizleyemez gözlerim Deli gibi sevdiğini İçimde bir sevinç var Senelerdir tatmadığım Bir burukluk Bir...', ARRAY['Türk Edebiyatı','Şiir','Şair Armağan']::text[], 8.5, '{"poet":"Şair Armağan","poet_slug":"sair-armagan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/neye-yarar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HP- Yarın Olmayacak', 'hp-yarin-olmayacak-sami-bagci-3wady', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Artık benim için 

Yarın diye bir gün olmayacak. 

Belki birdaha görmeyecek 

Güneşin doğuşunu gözlerim. 

Karanlık bir gece de

Meçhule yelken açıp gideceğim. 

Umuda yolculuk deyilse de 

Bir daha sızlamayacak yaralı yüreğim. 

Izdırap dolu yarına uyanmaktansa

Beni bekleyen meçhule 

Korkmadan yürüyüp gideceğim. 

Yarın demek: 

Elem dolu ayrılık demek. 

Yarın demek: 

Tüm ümitlere elveda demek. 

Yarını görmektense 

En iyisi, 

Güneş doğmadan çekip gitmek. 

(', 'Artık benim için  Yarın diye bir gün olmayacak.  Belki birdaha görmeyecek  Güneşin doğuşunu gözlerim.  Karanlık bir gece de Meçhule yelken a...', ARRAY['Türk Edebiyatı','Şiir','Sami Bağcı']::text[], 8.5, '{"poet":"Sami Bağcı","poet_slug":"sami-bagci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hp-yarin-olmayacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HP- Aşk', 'hp-ask-sami-bagci-t1yzb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana aşktan sorarlarsa eğer

Onlara deki:

O lirik bir efsanedir.

Kaf dağının ardında yetişen

Sihirli bir elma gibidir.

Gökyüzünde parlayan

Yıldızlara dokunmak gibidir.

Hep bir adım ötende sanırsın

Yaklaştıkça uzaklaşan

Serap gibidir.

Onu kutsal kılan

Erişilmezliğidir.

Hiçbir aşık kavuşmamış daha

Ne gerçek hayatta

Ne de masallarda.

Yine de

Hiç eksik olmaz heveslisi

Biri gelir biri gider

Fareli köyün kavalcısı gibi

Sihirli nağmeleriyle

Yanık yürekleri

Peşine takar gider.', 'Sana aşktan sorarlarsa eğer Onlara deki: O lirik bir efsanedir. Kaf dağının ardında yetişen Sihirli bir elma gibidir. Gökyüzünde parlayan Yı...', ARRAY['Türk Edebiyatı','Şiir','Sami Bağcı']::text[], 8.5, '{"poet":"Sami Bağcı","poet_slug":"sami-bagci","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hp-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HP- Bakma Sen', 'hp-bakma-sen-sami-bagci-lj14o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mevsimi kış sanıp sakın kahretme

Daha kışa çok var.

Kapatıp oturma gönlünün kapısını

Yaşanacak daha çok baharlar var.

Bakma sen her tarafın

Karlarla kaplı olduğuna

Hele bir güneş vursun da bak

Eriyip seller gibi

Nasıl da gürül gürül akacak.

Bakma sen gönlünün durgunluğuna

Hele bir sıcak vursun da bak

Fokur fokur nasıl da kaynayacak.

Bekle az kaldı

Sana hayat verecek güneşi.

Bak yükseliyor bile

 Bulutların ardından

Göründü görünecek şimdi.', 'Mevsimi kış sanıp sakın kahretme Daha kışa çok var. Kapatıp oturma gönlünün kapısını Yaşanacak daha çok baharlar var. Bakma sen her tarafın ...', ARRAY['Türk Edebiyatı','Şiir','Sami Bağcı']::text[], 8.5, '{"poet":"Sami Bağcı","poet_slug":"sami-bagci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hp-bakma-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HP- Aynalar', 'hp-aynalar-sami-bagci-4gsnm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sürüklenir durursun peşinden

Alır götürür seni arzular.

Zamanın dişlileri çalışırken

Kemirir durur ömründen azar azar.

Hep aynı günü yaşadığını sanırken

Su gibi akıp gider yıllar.

Derken gün gelir

Yolunu kesiverir aynalar

Hayret edersin! 

Tanıyamazsın aynadaki seni

Kim bu adam da der şaşırıverirsin

Hep bir delikanlı arar gözlerin.

Ne yazık ki

Çok sular aktı köprülerin altından

Gitti artık O, sana kaldı bu beden.

Şimdi O

Dönüşü olmayan bir zaman yolcusu

Aranıza aşılmaz duvar ördü yıllar.

Artık ne köprü kaldı

Ne de altından akan sular.', 'Sürüklenir durursun peşinden Alır götürür seni arzular. Zamanın dişlileri çalışırken Kemirir durur ömründen azar azar. Hep aynı günü yaşadığ...', ARRAY['Türk Edebiyatı','Şiir','Sami Bağcı']::text[], 8.5, '{"poet":"Sami Bağcı","poet_slug":"sami-bagci","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hp-aynalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AD- Nasıl Anlatsam', 'ad-nasil-anlatsam-sami-bagci-lm29x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana nasıl anlatsam

Seni sevdiğimi

Bilemiyorum

Hiçbir lügatte bulamadım

Aşkımı ifade edecek kelimeyi

Hiçbir besteci bestelememiş

Sana serenat yapacak şarkıyı

Hangi çiçek anlatır

Sana olan aşkımın yüceliğini

Hiçbir şairin şiiri

Dile getiremez

Yüreğimin coşku dolu sesini.

Ama

Bakarsan gözlerime

Taa gözümün bebeğine

Orada göreceksin

Ölümsüz bir aşkla sevildiğini.', 'Sana nasıl anlatsam Seni sevdiğimi Bilemiyorum Hiçbir lügatte bulamadım Aşkımı ifade edecek kelimeyi Hiçbir besteci bestelememiş Sana serena...', ARRAY['Türk Edebiyatı','Şiir','Sami Bağcı']::text[], 8.5, '{"poet":"Sami Bağcı","poet_slug":"sami-bagci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ad-nasil-anlatsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yalan-dunya', 'yalan-dunya-mukerrem-mete-z8zbs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu yalan dünyayı sonsuza bölsen

Bir parça ne sana ne bana kalır

Haramdan kaçıpta şu nefsi delsen

Cennette ebedi bir yer ayrılır', 'Şu yalan dünyayı sonsuza bölsen Bir parça ne sana ne bana kalır Haramdan kaçıpta şu nefsi delsen Cennette ebedi bir yer ayrılır...', ARRAY['Türk Edebiyatı','Şiir','Mükerrem Mete']::text[], 8.5, '{"poet":"Mükerrem Mete","poet_slug":"mukerrem-mete","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalan-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İncesin İnce', 'i-ncesin-i-nce-ahmet-asmagil-db40d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabit’sin, ince’sin, inceden ince

Yücesin duyguca, imanca, dince.

İşin uzmanısın, vallahi bence,

İnsan sevilirse diller açılır...

“birlik” kurulunca hızlandı işler,

gerceğe dönüştü hayaller düşler,

parlak ufuklara doğru gidişler,

rehberin olursa yollar açılır.

Usta gemicinin gemisi batmaz,

Çalışkan insanın işleri bitmez.

“ANASAM” güçlüdür, ona güç yetmez,

diller dua eder, eller açılır...

şiirler okunur, çalınır sazlar,

kitaplar basılır, duyulur hazlar.

Kapımızı açtık herkese bizler,

Üstadın elinde teller açılır....

Fırtınalar dindi, başladı rahmet,

Dost için çekilir yorgunluk, zahmet,

Başka ne söylesin Asmagil Ahmet,

Güneş dik vurursa, güller açılır....

30.6.2000 Kayseri', 'Sabit’sin, ince’sin, inceden ince Yücesin duyguca, imanca, dince. İşin uzmanısın, vallahi bence, İnsan sevilirse diller açılır... “birlik” k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Asmagil']::text[], 8.5, '{"poet":"Ahmet Asmagil","poet_slug":"ahmet-asmagil","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/incesin-ince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustukça', 'sustukca-abdullah-donmez-vvti9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sustukça semâ kalbime hicranı fısıldar,

Bülbül gül ismini, o güzel anı fısıldar.

Gönül der ki tek çare unutmak,

Ey hat! UNUTMAK bile sevgiliyi fısıldar.

(29.03.2000 Çarşamba 16:15)', 'Sustukça semâ kalbime hicranı fısıldar, Bülbül gül ismini, o güzel anı fısıldar. Gönül der ki tek çare unutmak, Ey hat! UNUTMAK bile sevgili...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Dönmez']::text[], 8.5, '{"poet":"Abdullah Dönmez","poet_slug":"abdullah-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sustukca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemal Safi’YE', 'cemal-safi-ye-ali-bas-cjeuf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çileye dost olup boyun eğerek,

Aşk ile tutuşup yanan bir yürek,

Zehiri sunsalar bade diyerek

İçmeyen anlamaz Cemal  Safi’yi..

Aşkı bilen aşka canını adar,

Muhabbet bağını bülbüller budar.

Gönül kapısını ardına kadar,

Açmayan anlamaz Cemal Safi’yi...

Mürekkebi gözyaşıyla kanından,

Sevdasını üstün tutar canından,

Makamdan, maddeden, dünya malından

Geçmeyen anlamaz Cemal Safi’yi...

Saygıyla ellerinizden öperim üstadım.

Acizane duygularımı iletmek istedim.', 'Çileye dost olup boyun eğerek, Aşk ile tutuşup yanan bir yürek, Zehiri sunsalar bade diyerek İçmeyen anlamaz Cemal  Safi’yi.. Aşkı bilen aşk...', ARRAY['Türk Edebiyatı','Şiir','Ali Baş']::text[], 8.5, '{"poet":"Ali Baş","poet_slug":"ali-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/cemal-safi-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce''ye Cevap 5', 'i-nce-ye-cevap-5-ali-bas-t7ghf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir tutmuşsun yazdıranı, yazanı

Derinlere dalıyorsun sabit bey.

Çok kazdım da bulamadım kazanı,

Yardıma mı geliyorsun sabit bey.

Seni yakar ısınırım közünle,

Sevdalısın, kabuğunla özünle.

Şu gönlümü sohbetinle sözünle,

Mızrak gibi deliyorsun sabit bey.

Sırrı ayan edip açma pazara,

Muhabbeti kurban verme nazara.

Maddeyi ben çoktan gömdüm mezara,

Adresini biliyorsun sabit bey.

Anladım ben gibi serden geçersin,

Aşkın kadehinden zehir içersin.

Kolayı bırakır zoru seçeresin,

Kırk elekten eliyorsun sabit bey.

Vuslattan önce mi sonra mı gusül,

Söyle de bileyim nasıldır usul.

Güzeller yapmacık gizlenir asıl,

Kör kılıncı biliyorsun sabit bey.

Pınar kurumadan doldur tasını,

Bu garip ölse de tutma yasını,

Aşığın eliyle gönül pasını,

Yavaş yavaş siliyorsun sabit bey.

Elli yıldır ödemedim kiramı,

Mülkün sahibiyle bozdum aramı,

Farkında olmadan gönül yaramı,

Liğme liğme diliyorsun sabit bey.

Gül anlarmış bülbüllerin sözünden,

Bunca zaman yar dedin mi özünden?

Sel misali yaş akıyor gözümden,

Sense bana gülüyorsun sabit bey.

Karga leşe hasret bülbülse güle,

Büyüktür duygular sığmıyor dile,

Benden fazla mı ki sendeki çile,

Pay edip de bölüyorsun sabit bey,.

Seziniyim deş demişsin deşiyom,

Çaresizim gam yükünü taşıyom.

Kırk senedir dolu dizgin koşuyom.

Sen yürürken soluyorsun sabit bey,', 'Bir tutmuşsun yazdıranı, yazanı Derinlere dalıyorsun sabit bey. Çok kazdım da bulamadım kazanı, Yardıma mı geliyorsun sabit bey. Seni yakar ...', ARRAY['Türk Edebiyatı','Şiir','Ali Baş']::text[], 8.5, '{"poet":"Ali Baş","poet_slug":"ali-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ince-ye-cevap-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Yaşama', 'hic-yasama-abdullah-donmez-z0e28', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Allah için birini sevemiyorsan,

Gözyaşlarında kendini göremiyorsan,

Dünyaya bakıp gerçeği göremiyorsan,

Allah''tan hidayetini iste, yada hiç yaşama.

(01.06.2000 perşembe)', 'Allah için birini sevemiyorsan, Gözyaşlarında kendini göremiyorsan, Dünyaya bakıp gerçeği göremiyorsan, Allah''tan hidayetini iste, yada hiç ...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Dönmez']::text[], 8.5, '{"poet":"Abdullah Dönmez","poet_slug":"abdullah-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hic-yasama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce''ye Cevap-2', 'i-nce-ye-cevap-2-ali-bas-gsomx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kılı kırka yardım netice küsur,

Sağlam sonuç alamadım Sabit bey.

Bilmem yarimde mi bende mi kusur,

Ummanlara dalamadım Sabit bey..

Henüz yeni geldim azap çağına,

İnce karlar yağdı gönül dağıma.

Bağban oldum amma bülbül bağına,

Diken battı yolamadım Sabit bey...

Aşk ateştir demiş aşkı bilenler,

Kavuşmuş mu yare dağlar delenler.

Gerçek dost mu sandın yüze gülenler,

Henüz dostu bulamadım Sabit bey...

Bana bir ödüldür bu çile, bu yük.

Yazdığın şiirin manasıbüyük,

Bir şiirim yok ki şaire layık,

Daha aşık olamadım Sabit bey...

Gördüğün rüyayı edersin tabir,

Başlangıç arınmak sonuçsa kabir.

Aşkın badesini dolan binde bir,

Bense boşum, dolamadım Sabit bey...

Belli ki gözünde büyüttün beni,

Oysa benim aşkım daha çok yeni,

Özür diliyorum üzdüysem seni,

Bir kararda kalamadım Sabit bey...

Seziniyim cevabını saldım da,

Çok sevindim mektubunu aldım da,

Her sorunun cevabını buldum da,

Bir tek sazı çalamadım Sabit bey...

31.5.2000 Kayseri', 'Kılı kırka yardım netice küsur, Sağlam sonuç alamadım Sabit bey. Bilmem yarimde mi bende mi kusur, Ummanlara dalamadım Sabit bey.. Henüz yen...', ARRAY['Türk Edebiyatı','Şiir','Ali Baş']::text[], 8.5, '{"poet":"Ali Baş","poet_slug":"ali-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ince-ye-cevap-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsce''ye Cevap-1', 'i-nsce-ye-cevap-1-ali-bas-7mmul', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu gönlüme baksan gönül gözünden,

Benim güldüğümü görürdün ince.,

Değişik mesajlar aldım sözünden,

Aşkın ardı sıra görürdün ince...

Gece karanlıkta gözyaşı döksen,

Çile çeke çeke genç yaşta çöksen,

Her türlü siteme boynunu büksen,

O zaman bana hak verirdin ince...

Yare yaklaştıkça yarim kaçıyor,

Kanımı kadehe koyup içiyor,

Hasret durağında ömrüm geçiyor,

Yerimde sen olsan erirdin ince...

Sezini uzatma bu kadar yeter,

Ne güllerim açar, ne bülbül öter.

Sevdam mecnun ile keremden beter,

Aşk çeksen inan ki çürürdün ince...

31.5.2000', 'Şu gönlüme baksan gönül gözünden, Benim güldüğümü görürdün ince., Değişik mesajlar aldım sözünden, Aşkın ardı sıra görürdün ince... Gece kar...', ARRAY['Türk Edebiyatı','Şiir','Ali Baş']::text[], 8.5, '{"poet":"Ali Baş","poet_slug":"ali-bas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/insce-ye-cevap-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göremem', 'goremem-sabit-i-nce-0mmsx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Varolan gözümle göremedim ki,

Gönül gözü nasıl görsün Ali Baş,

Belki de niyetim diyemedim ki,

Tanrı dileklerin versin Ali Baş.

Aşk ardından gide gide yoruldum,

Aşka maya oldum öyle dürüldüm.

Kovuldum da aşk evinden sürüldüm,

İster yerden yere sersin Ali Baş..

Gecelere gözüm yaşı kalmadı,

On sekiz bin alem derman olmadı.

Kimi kaçamadı, kimi bulmadı,

Buna nasıl cevap versin Ali Baş.

Yare yaklaşmadım ayrı değilim.

Ondan başkasına olmadı meylim.

Çağırdım adını hep leylim leylim,

İstersin önüne sersin Ali Baş.

Çileleri katık ettim, aş ettim,

Yar dedim yanarak yolundan gittim.

Ne eridim, ne tükendim, ne bittim,

Ne tür yemeklerden yersin Ali Baş...

Kah gül olur bülbüllerde şakırım,

Kah gevherim, aslında bir bakırım.

Aslına bakarsan ben tamtakırım,

Dilerim ki halık versin Ali Baş...

Mecnun gibi ben çöllerde gezmedim,

Ummanlara dalıp yalnız yüzmedim.

Dolu içemedim, bade ezmedim,

Belli bu sevdada pirsin Ali Baş...

İNCE kuru lafla gemi yürümez,

Cevherler hep saftır asla erimez.

Onu gören gözler bil ki ferimez,

Hallerin iyidir sürsün Ali Baş...

2.6.2000 Kayseri', 'Varolan gözümle göremedim ki, Gönül gözü nasıl görsün Ali Baş, Belki de niyetim diyemedim ki, Tanrı dileklerin versin Ali Baş. Aşk ardından ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/goremem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leb Demeden', 'leb-demeden-sabit-i-nce-twdl5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sezişin kuvvetli bilirim seni,

Leb demeden leblebiyi anlarsın.

Yaralıyım deyip de öldürme beni,

Ben ölürsem Sezini’yi yanlarsın...

Ayrılma diyorsun aşkın ardından,

Uyku girmez gece yarin derdinden,

Selam mı var yoksa canan yurdundan,

Esen yelden ne kokular dinlersin...

Pay çıkarmaz mıyım dostun derdinden,

Bu yüzden ayrıldım il’im, yurdumdan,

Hep koşturdum gonca gülün ardından,

Az sözümden sen çoğunu anlarsın.

Yüz çevirmem mah cemalden, güzelden,

Kertme yaptım zaten levh-i ezelden.

Bir cevap yazayım sana tez elden,

Belki Zeki gibi beni tanlarsın...

Bir bilirdim yedi imiş kapısı,

Hangi maddedendir acep yapısı,

Bir de mevcut değil mi ki hepisi,

Herşeyi söylersem beni Çanlarsın...

Deş bakalım körelenmiş közümü,

İyi baksan seyrederdin özümü,

Türkçe yazar Türkçe derim sözümü,

Kuşmuyum ki beni Süleymanlarsın..

Gülün özündeki şerbet aramam,

Haddimi bilirim fazla varamam.

Mutluluğun adresi ne soramam,

Hüzün durağında niye sonlarsın...

Arslan zannedirdim, korkuyor musun?

Pir kelimesinden ürküyor musun,

Yoldan şarampole sarkıyor musun,

İNCE anlatmazsam nasıl anlarsın???

6,6.2000 Kayseri', 'Sezişin kuvvetli bilirim seni, Leb demeden leblebiyi anlarsın. Yaralıyım deyip de öldürme beni, Ben ölürsem Sezini’yi yanlarsın... Ayrılma d...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/leb-demeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aydan Kopmuş', 'aydan-kopmus-sabit-i-nce-d6lm8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Ayşegül’e-

Aydan kopmuş ateş misin yakarsın,

Yeter imdat eyle yanıyorum ben.

Ak gerdana neden fular takarsın,

Bağlanmış bir köle sanıyorum ben.

Kağıt bitti kelimeler yetmiyor,

Mecnunum çöllerim git git bitmiyor,

Versen de bir buse gönlüm etmiyor.

Canımı aşk için sunuyorum ben.

İnce’dir bu gönül kırılmaz sanma,

Ben sönüyüm, ben yanıyım, sen yanma.

Sözüm haktır, ister inan, inanma,

Sevgin pervanemdir dönüyorum ben.

4.6.2000 Ankara', '-Ayşegül’e- Aydan kopmuş ateş misin yakarsın, Yeter imdat eyle yanıyorum ben. Ak gerdana neden fular takarsın, Bağlanmış bir köle sanıyorum ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aydan-kopmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım kalmalı', 'yarim-kalmali-i-hsan-murat-w9edj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostum belki de yarım kalmalı güzellikler,tamamına doyup bıkmadan.

Söz aşınmamalı son sınıra varıp

Sevda tüketilmemeli arsızca

            Bakışlar yerini bulmamalı hiçbir zaman,bakacak yer kalmalı bozulmamış

            Duygular tadılmamalı ucuz zanlar ve gibilere

             Silinmemeli yanlışlıkla gönül yazıları

             Maksut kalmalı ömür bitmeli asilce ve hayat asil.

              Dalınmamış denizler,görülmemiş rüyalar olmalı 

              Alınmamış tepeler  kalmalı

              Girilmemiş şehirler.

              Nefret sulanmadan

              İhtiras kazanmadan  küheylan çatlamalı,intikam doymadan

              Ne bileyin işte yarım kalmalı çok şeyler ve belki her şey ağız tadında

              Cennet yarım kalmalı 

               Dikecek çiçeğimiz olsun  kavuşursak

               Gibi ye kanıp yamalamadan ruhu

               Yarım kalmalıyız boğazda düğümlenen çığlık misali

 Davudî ses yarım olmalı bir hıçkırıkla

Gözde yaş düşmeden yere 

Törenler bitmemeli sonuna kadar

Devam etmeli destanlar

Yaslanmamış dizler olmalı hayatımızda

Başlanmamış dizeler

Güzeller kalmalı geride el değmemiş saçlarına

Miras gibi, yarım kalan yarına

                 Sonra sofralar olmalı tüketilmemiş

                 Elmalar yarım,içmeler yarım

                  Bir kamelyada bitmemeli arzular

                  İçilmemiş sigaralar olmalı efkardan kalma

                  Çekilmemiş AH lar

                  Öğütülmesin tüm günahlar

                  Ağustos sıcağında

                  Uykumuz gelsin masal sona ermeden 

                   Ihlamur kokulu bahçelerde

Beklemeli hasretle bir  şeyleri

Çarpmalı gönül seslere

Aramalı her çehrede

Her çevrede

YARIM KALANI

                                     Öğrenmeden seveni,sevileni

                                      Papatyalar yolunmamalı

                                       Yollar bitmemeli

                                        Hasret eksilmeden

                                        Dalında kalmalı üzümler

                                        Yaşanmadan tün üzüntüler

                                        Ve yazılmalı kenara harfler tükenmeden

Tılsımlı kutu açılmamalı

Acele iştaha

Ecel gelmemeli

Bitince her şey

          Ansızın gelmeli hızırla melek

          Kazılmadan mezar

          Yazılmadan taşı

           Ve vasiyetler

            Yarım kalmalı gelecekler cenazeye

            Duyulmadan ölüm denen güzel

            Gitmeliyim kalan yarısına

             Ülkemin,hayalimin kalanına

             Sevdamın,aşkımın,arzumun ülkesine ............................16/06/00', 'Dostum belki de yarım kalmalı güzellikler,tamamına doyup bıkmadan. Söz aşınmamalı son sınıra varıp Sevda tüketilmemeli arsızca             B...', ARRAY['Türk Edebiyatı','Şiir','İhsan Murat']::text[], 8.5, '{"poet":"İhsan Murat","poet_slug":"i-hsan-murat","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/yarim-kalmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelir', 'gelir-sabit-i-nce-dayc2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiir de sanat da bir ahenk var kı,

Kargası, yılanı cümbüşe gelir.

Ahenkli duygulu şiirler var ki,

Bulanı, çalanı cümbüşe gelir.

Ahenkli bir ekip oluşturulmuş;

Şiiri, bestesi buluşturulmuş,

Çok güzel bir ekip çalıştırılmış,

Kulunu, palanı cümbüşe gelir.

Sevgiler yoğrulup, dertler dillenir,

Onu tutan eller güler, güllenir.

Dertli gönüllerde sevda eğlenir,

Gelini, oğlanı cümbüşe gelir.

Uğraşılmış, güzel ahenk verilmiş,

Şairlerden ince gergef örülmüş,

Sevgilerden aşktan sergi serilmiş,

Yananı, söneni cümbüşe gelir.

İNCE''ledim baştan sona okudum,

Duramayıp mısraları dokudum.

Aradım taradım bir ben yok idim,

Bulanı, alanı cümbüşe gelir...

4.8.l999 kayseri', 'Şiir de sanat da bir ahenk var kı, Kargası, yılanı cümbüşe gelir. Ahenkli duygulu şiirler var ki, Bulanı, çalanı cümbüşe gelir. Ahenkli bir ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmadımı?', 'olmadimi-sabit-i-nce-0eoq0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nedir bu eziyet ettiğin cefa,

Eğilip kapında kul olmadım mı?

Anladım ki sende zerre yok vefa,

Harcanıp elinde pul olmadım mı?

Durmadım ben hep peşinde yeldirdim,

Sevgimi ben yeller ile bildirdim.

Adını hep teller ile çaldırdım,

Serilip önünde yol olmadım mı?

Gökteki yıldız da ay da aradım,

Rüzgarın sesiyle zülfün taradım,

Mutlu olmak idi senle muradım,

Çoşup derelerde sel olmadım mı?

Dünyada gülmedim ahreti bilmem,

Sen cennette yoksan billahi gelmem,

Azraile bile bu canı vermem,

Sevdayın peşinde del''olmadım mı?

İnce bir sızıdır gönlümde adın,

Kavlimiz var idi, bu mu muradın.

Ben koştukca sen hep kaçıp ıradın,

Sevda türkümüzde dil olmadım mı?

31.7.l999  kayseri', 'Nedir bu eziyet ettiğin cefa, Eğilip kapında kul olmadım mı? Anladım ki sende zerre yok vefa, Harcanıp elinde pul olmadım mı? Durmadım ben h...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olmadimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taktirname', 'taktirname-sabit-i-nce-74a13', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nevşehirliler derneğinin başkanı,

Anasam''ın başı, damarı kanı,

Birliklerin en sevilen insanı,

Dostum oluşudur en güzel yanı,

Bilmiyorsan yakınına gel tanı,

O''na ait takdirname destanı..

Allahım koymasın darda başını,

Layıktır, her zaman tüm safa senin.

Vakitli, vakitsiz geldim, kaşını

Çatılmış görmedim bir defa senin.

Öncüsün herkese örnek bir insan

Kimseyi kırmayan ince bir lisan.

Saygı, sevgi,görgü sendedir irfan,

Yanında cücedir bil deha senin...

Mübala yok sen saygıya layıksın,

Tanrım her belayı kökünden yıksın

Sana kem bakanın gözleri çıksın,

Rastlanmaz eşine bir daha senin..

Olamaz hiç kimse sen gibi çömert,

Var ise kahrolsun arada namert,

Dilerim allahtan vermesin bir dert,

Bulunmaz emsalin vallaha senin...

Hayatta gönlünce şen ol, mutlu ol

Ömrün uzun olsun gül, umutlu ol,

Her zaman her yerde her yıl kutlu ol,

Yaptığın hoş gelir allah''a senin...

Gönül Dostu

H. Recep Çalkaner.', 'Nevşehirliler derneğinin başkanı, Anasam''ın başı, damarı kanı, Birliklerin en sevilen insanı, Dostum oluşudur en güzel yanı, Bilmiyorsan yak...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/taktirname-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Dostuna', 'gonul-dostuna-sabit-i-nce-fbu5w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sn. Sabit bey dostumun 

3.1.l999 günlü Övgüsüne yanıt

mısraları dantel dantel örüyür,

bağda esen yel oluyor Sabit bey,

iylik ettiğinden kemlik görüyür,

bağlama da tel oluyor Sabit bey.

İncitmeden mor koyunun tüyünü,

Silip atmış kekik kokan köyünü,

Dışlayarak ağasını beyini,

Akrabaya el oluyor Sabit bey...

Bilmem hoşnut mudur huzurdan yana,

Sevecen bakışı can katar cana.

Sıkıntısı olan başvurur ona,

Yolsuzlara yol oluyor Sabit bey...

Emeklidir yoktur maddi tasası,

Nevşehirli derneğinin kasası,

Masası var Demirel''in masası,

Her gelene kul oluyor Sabit bey.

Muhabbet arıyor bir fincan çayda,

Pek de işi olmaz körfez de koy da,

Kayseri''yi mekan tutup ne fayda,

Bir revnakda gül oluyor Sabit bey.

Sırmadan da Abdullah''ım sırmadan,

Ötesini hiç kimseye sormadan,

Şiir yazıp0 saz çalıyor durmadan,

Çoşup, coşup sel oluyor sabit bey.

27/8/999 Kayseri', 'Sn. Sabit bey dostumun  3.1.l999 günlü Övgüsüne yanıt mısraları dantel dantel örüyür, bağda esen yel oluyor Sabit bey, iylik ettiğinden keml...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gonul-dostuna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kos Koca Dünyada', 'kos-koca-dunyada-sabit-i-nce-vbw1r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu koskoca dünyada,

Kala kaldım yalınız.

Gönlümde hep sevda da,

Açma dursun falınız.

Yaşıyor mu diri mi,

Sağ mı yoksa ölü mü,

Ben kaybettim gülümü,

Gene kaldım yalınız.

Acep güneş doğdu mu,

Bulut yere ağdı mı,

Ay yalınız kaldı mı,

Ne haldedir ölünüz?

Ses vermiyor geceler,

Fink atıyor cüceler,

Kifayetsiz heceler,

Bilmem nedir haliniz.

İnce''ledim aradım,

Bu değildi muradım,

Bir şeyler karaladım,

Saçmaladı deyiniz.

25.9.1999 kayseri', 'Şu koskoca dünyada, Kala kaldım yalınız. Gönlümde hep sevda da, Açma dursun falınız. Yaşıyor mu diri mi, Sağ mı yoksa ölü mü, Ben kaybettim ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kos-koca-dunyada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Gayrı Sen', 'gel-gayri-sen-sabit-i-nce-mjk73', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar oldu neredesin,

Gel sevdiğim, gel gayrı sen.

Neden sen beni üzersin,

Gel sevdiğim, gel gayrı sen.

Yıllar oldu haber gelmez,

Arayıp hiç halim sormaz.

Ömür biter gider durmaz,

Gel sevdiğim, gel gayrı sen.

İNCE yanar aşk oduna,

Dayanılmaz yar acına,

Çıkardılar darağcına,

Gel sevdiğim, gel gayrı sen.

26.10.1999 kayseri', 'Yıllar oldu neredesin, Gel sevdiğim, gel gayrı sen. Neden sen beni üzersin, Gel sevdiğim, gel gayrı sen. Yıllar oldu haber gelmez, Arayıp hi...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gel-gayri-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dillere Dillere', 'dillere-dillere-sabit-i-nce-t47vc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben duyguları yükledim,

Çalan tellere tellere..

Derdime dertler ekledim,

Düştüm dillere dillere...

 Hayat mektebin okudum,

Bülbül olup da şakıdım.

Hiç bu alemde yokudum,

Kondum dallara dallara..

A dem oldum göle düştüm,

Sırat köprüsünden geçtim.

Kendi ellerimle seçtim,

Vardım güllere güllere...

Yumak yumak çile ördüm,

Varım yogum sele verdim.

Yusufla zindana girdim,

Düştüm hallere hallere..

Gündüzü geceye soktum,

Kayan yıldız gibi aktım..

Türlü nişaneler taktım,

Sattım pullara pullara...

Keklik gibi kanadım yok,

Dünya senden muradım yok.

Kıratım var ayvazım yok,

Sürdüm bellere bellere...

İNCE bin kez gelip gitsem,

Varlığım kaldırıp atsam,

Dünyayı bir pula sattım,

Düştüm çöllere çöllere..

17.01.1999 kayseri-', 'Ben duyguları yükledim, Çalan tellere tellere.. Derdime dertler ekledim, Düştüm dillere dillere...  Hayat mektebin okudum, Bülbül olup da şa...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/dillere-dillere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimilere', 'kimilere-sabit-i-nce-7pfve', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimin gördüm değirmenin döndürür,

Kimileri çok ocaklar söndürür.

Kimisi var dostun bile kandırır;

Kuduz itler gibi saldırır durur.

 para ilahıdır tapar durmadan,

Giyinir kuşanır ipek sırmadan.

Pacasını sıvar dere görmeden,

Kevser şarabını doldurur durur.

Tanrı onun malı kimseye vermez,

Kendi alır satar kimseye sormaz.

Gayya kuyusuna kendisi girmez,

Harem kurar huri aldırır durur..

İmanı dilinde türküsün söyleri,

Cennet hevesiyle gönlünü eğler.

Merdi kıpti gibi sirkatın söyler,

Eveler geveler güldürür durur.

Kıldan İNCE imiş kılıçdan keskin,

Gerceğe yaklaşmaz ilime küskün,

İnşaallah maaşallah eyliyor teskin,

Menkıbe hurafe bildirir durur...

5.1.1999 kayseri-', 'Kimin gördüm değirmenin döndürür, Kimileri çok ocaklar söndürür. Kimisi var dostun bile kandırır; Kuduz itler gibi saldırır durur.  para ila...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kimilere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Gülüm', 'gel-gulum-sabit-i-nce-vulmu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel gülüm gelde gidelim,

Bizim ellere ellere...

Biz başkasını nidelim,

Konak güllere güllere...

Bizim elde sarmasıklar,

Sarmış dallara dallara...

Ciğeri yanık aşıklar,

Vurmuş tellere tellere...

Seherde öten bülbüller,

Düşmüş dillere dillere...

Aşka susamış gönüller,

Dönmüş sellere sellere...

Sevdalandım bir güzele,

Sordum ellere ellere...

Kurudum döndüm gazele,

Verdim yellere yellere...

Bir gülün aşkı yolunda,

Yandım narlara narlara...

İNCE sevda okulunda,

Bindim taylara taylara...

5,1.1999 kayseri-', 'Gel gülüm gelde gidelim, Bizim ellere ellere... Biz başkasını nidelim, Konak güllere güllere... Bizim elde sarmasıklar, Sarmış dallara dalla...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gel-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitiremedim', 'bitiremedim-sabit-i-nce-r555j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yesil ördek gibi yüzemedim ben,

Dünya sonsuz imis bitiremedim

Gönlümce alemi gezemedim ben

İstedim yanima getiremedim

Coskun seller gibi caglayamadim

Gönlünü gönlüme baglayamadim

Kılıcım paslandi yaglayamadim

Bu ise bir akil yetiremedim

Cagir türküleri söyle hallerin

Bal serbet akitsin tatli dillerin

Kahri cekilmiyor gurbet ellerin

Bir tek su hasreti bitiremedim

Yoruldum da bu yollarda yoruldum

Ese, dosta, yarenime darildim

INCE''cik bir daldım cabuk kirildim,

Bir isi hal yola yatiramadim

03.01.1999 kayseri -', 'Yesil ördek gibi yüzemedim ben, Dünya sonsuz imis bitiremedim Gönlümce alemi gezemedim ben İstedim yanima getiremedim Coskun seller gibi cag...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bitiremedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetmez Mi', 'yetmez-mi-sabit-i-nce-bldks', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Halk müzigi diye halka sunulan,

Sacmalardan usandik biz yetmez mi? 

Allanip pulanip cama konulan

Özgün deyip özümüze el atan,

Söz bilmeyip sözümüze söz katan

Kazanc amacıyla klipler yapan

Ucmalardan usandik biz yetmez mi?



Arabeskle türklügüme yan bakan

Kültürümü yakip ocagim yikan

Türküme cesitli isimler takan

Picmalardan usandik biz yetmez mi? 

Baragim, bozlagim, halayim barim, 

Türkümde söylenir cilem efkarim

Gözlerimden cağlar o agitlarim

Tasmalardan usandik biz yetmez mi? 

Firat kenarinda munzur daginda,

Agitlar yaktim ben gesi baginda

Kopuzlar calardim Tanri daginda

sacmalardan usandik biz yetmez mi? 

INCE ince karlar gibi yagardim

Yaylalarda gezer koyun sagardim 

Veysel idim her gönüle sigardim

cosmalardan usandik biz yetmez mi? 

03.01.1999 kayseri', 'Halk müzigi diye halka sunulan, Sacmalardan usandik biz yetmez mi?  Allanip pulanip cama konulan Özgün deyip özümüze el atan, Söz bilmeyip s...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yetmez-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İffet', 'i-ffet-kayserili-tuna-7r7l2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaftası zemzem,şarap dolu ne şişeler gördük;

Özü hicran olan,ne sahteler gördük;

Adına bakıpta,aldanma dostum;

Biz adı ''İFFET'' olan,ne ''KAHPELER'' gördük.', 'Yaftası zemzem,şarap dolu ne şişeler gördük; Özü hicran olan,ne sahteler gördük; Adına bakıpta,aldanma dostum; Biz adı ''İFFET'' olan,ne ''KAHP...', ARRAY['Türk Edebiyatı','Şiir','Kayserili Tuna']::text[], 8.5, '{"poet":"Kayserili Tuna","poet_slug":"kayserili-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/iffet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyorsun', 'diyorsun-adil-koruyan-coz60', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir haziran sabahının alacakaranlığında

Yazılmış bir şiirin satırlarında,

Sessiz haykırışlarla karışan

Özlem dolu sevginin yankılandığı odada,

''Seni kader çizgisiyle alnıma yazan Hak''tır.''

Pırıltıların canlandığı günün ilk ışıklarında

Sabah rüzgarının tenine her dokunuşunda,

Bütün benliğini kaplayan

Yüreğini kor gibi yakan sevgi doyumsuzluğunda,

''Seni çılgın gibi sevmek, yaşamaktır.''', 'Bir haziran sabahının alacakaranlığında Yazılmış bir şiirin satırlarında, Sessiz haykırışlarla karışan Özlem dolu sevginin yankılandığı odad...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/diyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarınlarda Doğmak', 'yarinlarda-dogmak-adil-koruyan-z3h7k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben her sabah yeniden doğarım,

Kozadan çıkmışçasına diri ve özgür.

Gözlerim günün ilk ışıklarını arar,

Tenimde sabahın tatlı esintisi.

Bir kırlangıçın kanatlarında,

Komrunun masum sevgisinde,

Ruhumu saran yaşama sevicinde,

Kendimi bulurum.

Ve ''yarın'' derim,

Bir kez daha doğmak için.', 'Ben her sabah yeniden doğarım, Kozadan çıkmışçasına diri ve özgür. Gözlerim günün ilk ışıklarını arar, Tenimde sabahın tatlı esintisi. Bir k...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yarinlarda-dogmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay'' ımı Geri Alıyorum', 'ay-imi-geri-aliyorum-fidan-aykut-psjbh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana Yeni Cami'' deki güvercinleri hediye ediyorum,

Eğer görebilirsen.

Rüzgarın ıslığını, yaprakların şarkısını hediye ediyorum,

Eğer duyabilirsen.

Sana ''Feride'' yi hediye ediyorum,

Eğer hatırlayabilirsen.

Sana yüreğinin derinliklerinde gizlediğin çocuğu hediye ediyorum,

Eğer arayabilirsen.

Sana ''Seni'' hediye ediyorum,

Eğer bulabilirsen.

Fakat Ay'' ımı geri alıyorum,

Eğer anlayabilirsen.

22.11.1999/ İstanbul', 'Sana Yeni Cami'' deki güvercinleri hediye ediyorum, Eğer görebilirsen. Rüzgarın ıslığını, yaprakların şarkısını hediye ediyorum, Eğer duyabil...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ay-imi-geri-aliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Asker', 'yalniz-asker-fidan-aykut-7aqlj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnız olmayacaksın.

Oralarda, bugünkinden yalnız olmayacaksın.

Geçmişin, anıların hep seninle olacak.

Yaptıkların, yapmadıkların,

Yapamadıkların hep seninle olacak.

''İyi ki'' ler, ''Keşke'' ler hep seninle olacak.

Umutların, özlemlerin, 

Hasretlerin hep seninle olacak.

Belki kendinden bile gizlediğin '' SEN'' 

Hep seninle olacaksın.

Ve dua etki Rabbim;

Rabbim hep seninle olacak.

6.12.1999/ İstanbul', 'Yalnız olmayacaksın. Oralarda, bugünkinden yalnız olmayacaksın. Geçmişin, anıların hep seninle olacak. Yaptıkların, yapmadıkların, Yapamadık...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalniz-asker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağustos Çıkmazı', 'agustos-cikmazi-attila-i-lhan-ku439', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'beni koyup koyup gitme

ne olursun

durduğun yerde dur

kendini martılarla bir tutma

senin kanatların yok

düşersin yorulursun

beni koyup koyup gitme

ne olursun

bir deniz kıyısında otur

gemiler sensiz gitsin bırak

herkes gibi yaşasana sen

işine gücüne baksana

evlenirsin çocuğun olur

sonun kötüye varacak

beni koyup koyup gitme

ne olursun

elimi tutuyorlar ayağımı

yetişemiyorum ardından

hevesim olsa param olmuyor

param olsa hevesim

yaptıklarını affettim

seninle gelemeyeceğim attilâ ilhan

beni koyup koyup gitme

ne olursun', 'beni koyup koyup gitme ne olursun durduğun yerde dur kendini martılarla bir tutma senin kanatların yok düşersin yorulursun beni koyup koyup ...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/agustos-cikmazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aysel Git Başımdan', 'aysel-git-basimdan-attila-i-lhan-y62vb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aysel git başımdan ben sana göre değilim 

Ölümüm birden olacak seziyorum. 

Hem kötüyüm karanlığım biraz çirkinim 

Aysel git başımdan istemiyorum. 

Benim yağmurumda gezinemezsin üşürsün 

Dağıtır gecelerim sarışınlığını 

Uykularımı uyusan nasıl korkarsın, 

hiçbir dakikamı yaşayamazsın. 

Aysel git başımdan ben sana göre değilim. 

Benim icin kirletme aydınlığını, 

hem kötüyüm karanlığım biraz çirkinim 

Islığımı denesen hemen düşürürsün, 

gözlerim hızlandırır tenhalığını 

Yanlış şehirlere götürür trenlerim. 

Ya ölmek ustalığını kazanırsın, 

ya korku biriktirmek yetisini. 

Acılarım iyice bol gelir sana, 

sevincim bir türlü tutmaz sevincini. 

Aysel git başımdan ben sana göre değilim. 

Ümitsizliğimi olsun anlasana 

hem kötüyüm karanlığım biraz çirkinim. 

Sevindiğim anda sen üzülürsün. 

Sonbahar uğultusu duymamışsın ki 

içinden bir gemi kalkıp gitmemiş, 

uzak yalnızlık limanlarına. 

Aykırı bir yolcuyum dünya geniş, 

Büyük bir kulak çınlıyor içimdeki. 

Çetrefil yolculuğum kesinleşmiş. 

Sakın başka bir şey getirme aklına. 

Aysel git başımdan ben sana göre değilim, 

ölümüm birden olacak seziyorum, 

hem kötüyüm karanlığım biraz çirkinim. 

Aysel git başımdan seni seviyorum...', 'Aysel git başımdan ben sana göre değilim  Ölümüm birden olacak seziyorum.  Hem kötüyüm karanlığım biraz çirkinim  Aysel git başımdan istemiy...', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/aysel-git-basimdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ölürsem Akşamüstü Ölürüm', 'ben-olursem-aksamustu-olurum-ataol-behramoglu-536bl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben ölürsem akşamüstü ölürüm 

Şehre simsiyah bir kar yağar 

Yollar kalbimle örtülür 

Parmaklarımın arasından 

Gecenin geldiğini görürüm 

Ben ölürsem akşamüstü ölürüm

Çocuklar sinemaya gider 

Yüzümü bir çiçeğe gömüp 

Ağlamak gibi isterim 

Derinden bir tren geçer 

Ben ölürsem akşamüstü ölürüm 

Alıp başımı gitmek isterim 

Bir aksam bir kente girerim 

Kayısı ağaçları arasından 

Gidip denize bakarım 

Bir tiyatro seyrederim 

Ben ölürsem akşamüstü ölürüm 

Uzaktan bir bulut geçer 

Karanlık bir çocukluk bulutu 

Gerçeküstücü bir ressam 

Dünyayı değiştirmeye baslar 

Kus sesleri, haykırışlar 

Denizin ve kırların 

Rengi birbirine karışır 

Sana bir şiir getiririm 

Sözler rüyamdan fışkırır 

Dünya bölümlere ayrılır 

Birinde bir pazar sabahı 

Birinde bir gökyüzü 

Birinde sararmış yapraklar 

Birinde bir adam 

Her şeye yeniden baslar', 'Ben ölürsem akşamüstü ölürüm  Şehre simsiyah bir kar yağar  Yollar kalbimle örtülür  Parmaklarımın arasından  Gecenin geldiğini görürüm  Ben...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ben-olursem-aksamustu-olurum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özleyiş', 'ozleyis-huseyin-nihal-atsiz-hkwe9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Özledim... Yanıklık canıma değdi...

Özledim, yıllarca daha özlerim.

Hasret türkü olsa, ben onu çalsam,

Kırılıp giderdi nice sazlarım...

Yatın ümitlerim, uykuya yatın!

Bitin hasretlerim, tükenip bitin!

Ayrılık ateşi çetinmiş, çetin;

Onunla dikleşir bütün düzlerim.

Yanımda sanrım, bakarım düştür;

Güldüm zannederken gözlerim yaştır.

Umduğum ne varsa hepside boştur;

Yinede bekliyor onu gözlerim.

Sazlar var: Durmadan gurbeti çalar;

Hayal var: Gözümü, gönlümü çeler.

İçimde bir bülbül şakıyıp çiler:

Özledim, yıllarca daha özlerim...', 'Özledim... Yanıklık canıma değdi... Özledim, yıllarca daha özlerim. Hasret türkü olsa, ben onu çalsam, Kırılıp giderdi nice sazlarım... Yatı...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Nihal Atsız']::text[], 8.5, '{"poet":"Hüseyin Nihal Atsız","poet_slug":"huseyin-nihal-atsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozleyis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'aşk', 'ask-kadir-mutlu-x5sbx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kalbim ilk defa böylesine atıyor

geceleri sadece bir kız yüzünden uykularım kaçıyor

biliyor hissediyorum aşık olduğumu

hayaller içinde yok olduğumu 

kör olsaydım diye düşünüyorum

seni görmezdim bu acıları çekmezdim

ama  düşününce de iyi mi kötü mü diye karar veremiyorum

kalsın ben kör olmadığıma şükür edeyim

çünkü senin gibi güzel birini gördüm

nasıl bir şey bu aşk 

daha adını bilmiyordum inanmıyordum bir görüşte...

aslında aşk budur işte

sanki deniz maviliğine bakarsın kalırsın

aşkta öyle gözlerinin içine bakarsın donakalırsın

düşünüyorum da aşkıma karşılık verse nasıl olur

aslında bırakın aşkıma karşılığı 

onunla tanışsam birbirimizi görsek 

hani olurya günlerce su yüzü görmeyen çiçeğe su verirsiniz

benim içinde o an dünyaları verirsiniz

onu seviyorum

aşkımı anlasa karşılık verse

belkide bendeki ızdıraplar sona erer

hemde güvendiğim inandığım sevdiğim biri olur', 'kalbim ilk defa böylesine atıyor geceleri sadece bir kız yüzünden uykularım kaçıyor biliyor hissediyorum aşık olduğumu hayaller içinde yok o...', ARRAY['Türk Edebiyatı','Şiir','Kadir Mutlu']::text[], 8.5, '{"poet":"Kadir Mutlu","poet_slug":"kadir-mutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ask-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'N e zaman Ne e', 'n-e-zaman-ne-e-fikret-kaplan-92w0e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevgiye zamanı kalmayanlara (sezen''e)

Sana ait bir iz buldum

           sensizliğin yollarıda.

Bir sen çizdim benliğime, yaşanmamış.

           Umutlarım birden söndü.

Bir bugün kaldı kollarımda

           /yüzüme vuruldu gerçekler/

Yaşanacak zaman kalmamış.

Belki bir anı geride kalan

          Buğulu camlar üstünde

O eski günlerden eser kalmamış.

Karanlıklar perde perde canlanıyor önümde

Sen ömrümden yitik bir sayfa

                                 /bildim/

Satırları yazılmamış.

Sen bana ait belkide hiç yaşanmamış

Umut hep o yarında

Sevgiye zaman kalmamış.

(16/01/1992)', 'Sevgiye zamanı kalmayanlara (sezen''e) Sana ait bir iz buldum            sensizliğin yollarıda. Bir sen çizdim benliğime, yaşanmamış.        ...', ARRAY['Türk Edebiyatı','Şiir','Fikret Kaplan']::text[], 8.5, '{"poet":"Fikret Kaplan","poet_slug":"fikret-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/n-e-zaman-ne-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı', 'yabanci-fikret-kaplan-2861w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Selam yabancı

Selam...

Değişmişsin , yüzün daha bir soluk

Ben seni böyle anımsamazdım

Değişmişsin...

Neden yabancı ?

Yabancı diyorum çünki artık öylesin

Neden ?

Duyguların bile artık farklı

Seni bilen varsa söylesin

Ne değiştiki senden sonra buralarda

Hep aynı kır kahvesi , sokaklar ,

Yağmur bile aynı

Oysa sen değişmişsin

Neden ?

Söyle yabancı neden ?

8/10/1993 Cuma 14:00/14:25', 'Selam yabancı Selam... Değişmişsin , yüzün daha bir soluk Ben seni böyle anımsamazdım Değişmişsin... Neden yabancı ? Yabancı diyorum çünki a...', ARRAY['Türk Edebiyatı','Şiir','Fikret Kaplan']::text[], 8.5, '{"poet":"Fikret Kaplan","poet_slug":"fikret-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yabanci-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatlı Cadı', 'tatli-cadi-semra-celik-tgimw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerinin rengine vurgunum

Kara değil, mavi değil

Yosun yeşili hiç değil,

Aşık oldum gözlerine

Rengi ela değil.

Saçlarına vurgunum

Saçları, dalgalı ve uzun değil

Kirpiklerine vurgunum,

Kirpikleri ok, kaşları yay değil

Boyu kısa, selvi boylu hiç değil.

Çirkinim, diye seviyorum onu

Çünkü; güzel değil

Huysuz mu huysuz, aksi mi aksi

Hırçın mı hırçın,

Uysal desem, hiç değil.

Düşündüm de, kaprisli ama şirin

Üstelik edalı, hoş bakışlı yarim

Gönlü zengin, fikri güzel

Kabul, cadı biraz

Ama o benim tatlı cadım.', 'Gözlerinin rengine vurgunum Kara değil, mavi değil Yosun yeşili hiç değil, Aşık oldum gözlerine Rengi ela değil. Saçlarına vurgunum Saçları,...', ARRAY['Türk Edebiyatı','Şiir','Semra Çelik']::text[], 8.5, '{"poet":"Semra Çelik","poet_slug":"semra-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tatli-cadi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevme Başkasını', 'sevme-baskasini-semra-celik-q24ny', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Niye ağlarsın,

Soramam ki, bilirim anlatmazsın

bir kalem elindedir,

Bir el başında,

Yazarsın ama, okutmazsın.

Roman oldu artık yazdıkların

Çekmecende saklarsın

Bilirim, bir sevda gömülü yüreğinde

Bir kaleme, bir deftere anlatır

Bana anlatmazsın.

Bir gün seninle ölecek,

Bitecek bu sevda

Kaleme aldıklarını,

Herkes okuyacak mutlaka

Ben, bilerek okumayacağım.

Sevme başkasını, sevdiğim

Dayanamaz ki buna yüreğim,

Gözüm göre göre,

Kalbim bile bile,

Seni nasıl vereyim ellere.', 'Niye ağlarsın, Soramam ki, bilirim anlatmazsın bir kalem elindedir, Bir el başında, Yazarsın ama, okutmazsın. Roman oldu artık yazdıkların Ç...', ARRAY['Türk Edebiyatı','Şiir','Semra Çelik']::text[], 8.5, '{"poet":"Semra Çelik","poet_slug":"semra-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevme-baskasini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdim', 'sevdim-semra-celik-80fbn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Türkülerde sevdim ben seni,

Halaylarda, çifte tellide

Ellerini birbirine vuruşunu, oynamanı

İmalı imalı bakışını, çatık kaşlarını

Olduğun gibi olmanı, sevdim ben senin

Konuştuğun her kelimeyi

Daha, ağzından çıkmadan sevdim,

Seni dinlerken, gözlerimi yumdum

Çocukken, en sevdiğim masalı

Dinler gibi, dinledim seni

Ben seni Bolu''da Sevdim

Şimde sen yoksun, uzaklardasın

Ben senin, olduğun her yeri sevdim

Çünkü, ben hiçbirşeyi değil

Yalnız seni sevdim.

Kaprisini sevdim, birde gülüşünü

Arkanı dönüp, bazen çekip gidişini

Herkese kızdığım, bir okul gününde

Her şeyi boş vermişken, silmişken bir kalemde

Senin, beni sevmeni sevdim.

Ağlayınca yeşil olan gözlerinin

Güldüğünde ela olduğunu bilmeden

Hassas ve duygulu yüreğini

Sinirlenince, inciteceğimi düşünmeden

Ben, seni hiç tanımadan sevdim.

El ele tutuştuğumuzda

Heyecanlanan kalplerimizi sevdim

Beş parasız kaldığımızda,

Birlikte aç kalışımızı,

Seninle, her şeyi paylaşmamızı sevdim.

Kar yağdığında, mutluluğumuzu

İlk kez görmüş gibi, seyretmemizi

Sevgimizi anlatacak, kelime bulma yarışında

Bulduğumuz o güzel sözü sevdim

Ben seni o günden beri hep,

''Kar tanelerinin sonsuz katı kadar''

Sevdim.', 'Türkülerde sevdim ben seni, Halaylarda, çifte tellide Ellerini birbirine vuruşunu, oynamanı İmalı imalı bakışını, çatık kaşlarını Olduğun gi...', ARRAY['Türk Edebiyatı','Şiir','Semra Çelik']::text[], 8.5, '{"poet":"Semra Çelik","poet_slug":"semra-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cuma', 'cuma-hakan-kucukkaralar-n0ki6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günlerden cuma

Sormuşlar adama

Nezaman buluşursun Allahla

Cumadan cumaya', 'Günlerden cuma Sormuşlar adama Nezaman buluşursun Allahla Cumadan cumaya...', ARRAY['Türk Edebiyatı','Şiir','Hakan Küçükkaralar']::text[], 8.5, '{"poet":"Hakan Küçükkaralar","poet_slug":"hakan-kucukkaralar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cuma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp İlanı', 'kayip-i-lani-gizem-bilgin-1uf3s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hiç dalga geçmedim yüreğinizle

Yaptığınız, küstüğünüz, çözdüğünüz

hiçbir aşka gülmedim

Ben sizden, bestesiz, ağıtsız aşklar da istemedim

Hep dört üçlük ritmler yarattım aşk için

Çünkü o zamanlar sokaklarda darbuka çalan çocuklar vardı

Ağlayan

Şaşkın şaşkın bakan

Dilenen gözleri vardı

Ben şiirsiz aşklar istemedim sizlerden

Sırtınızı dönmüşken Mecnuna deli diye

Ben içinizdeki Juliet’i avutmaya çalıştım

Ve cebinizdeki tüm parayı verdiniz

Fenerbahçe sahilindeki bir çingene kadına

Umutlarınızı geri versin diye

Oysa benden başka kim bilebilirdi

Bir fırıncının ununa sakladığı düşlerinizi

Bir tinerciye ekmek diye sattığını

Hiç dalga geçmedim yüreğinizle

Siz düşlerinizi kaybetti kaybedeli…

2000 İSTANBUL', 'Hiç dalga geçmedim yüreğinizle Yaptığınız, küstüğünüz, çözdüğünüz hiçbir aşka gülmedim Ben sizden, bestesiz, ağıtsız aşklar da istemedim Hep...', ARRAY['Türk Edebiyatı','Şiir','Gizem Bilgin']::text[], 8.5, '{"poet":"Gizem Bilgin","poet_slug":"gizem-bilgin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kayip-ilani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birini Ararsan', 'birini-ararsan-suat-atar-znlyr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seven birini ararsan gel

Benden cok seni seveni bulamasin

Hasret kalacak birini ararsan gel

Benden cok sana hasret kalani bulamasin

Aglayan birini ararsan gel

Benden fazla sana aglayani bulamasin

Ölecek birini ararsan gel

Benden cok ugruna öleni bulamasin

Aldatacak birini ararsan ''HAYIR GELME''

Zaten yeteri kadar aldatilmisim ben !!!!!!!', 'Seven birini ararsan gel Benden cok seni seveni bulamasin Hasret kalacak birini ararsan gel Benden cok sana hasret kalani bulamasin Aglayan ...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/birini-ararsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt', 'agit-huseyin-nihal-atsiz-doy49', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönlümde yazdığım bu son ağıta 

Nazire yaparak coşan dalgalar! 

Hastası olup da geç vakit hekim

Arayanlar gibi koşan dalgalar! 

Sizin de elbette var bir sızınız, 

Bundan mı geliyor korkunç hızınız? 

Benide beraber alır mısınız? 

Kederle kabarıp şişen dalgalar? 

Sizile paylaşsak bu korkunç gamı,

Bitmiyor bu sonsuz ecel akşamı.

Bilmem ki bundan mı titriyor gemi? 

Ey dalgakıranı aşan dalgalar? 

Hey ATSIZ çöküyor eski bir direk.

Baksan da dünyaya titremeyerek,

Hepimiz beraber haykırsak gerek

Ey bela dehrinde pişen dalgalar! ..', 'Gönlümde yazdığım bu son ağıta  Nazire yaparak coşan dalgalar!  Hastası olup da geç vakit hekim Arayanlar gibi koşan dalgalar!  Sizin de elb...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Nihal Atsız']::text[], 8.5, '{"poet":"Hüseyin Nihal Atsız","poet_slug":"huseyin-nihal-atsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asik oldum', 'asik-oldum-suat-atar-i5qas', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adini andikca gözlerim doldu

seni düsününce kalbim carpti

sesini duyunca icime bir hüzün cöktü

ben sana heralde asik oldum.

Gözlerindi bana hayat ümit veren 

elma gibi yanaklarindi beni asik eden

ey gülüsünile beni eriten

ben sana heralde asik oldum.

Bir baktin kalbimi yaktin

bir baktin kalbimi caldin

bir kelime söz söyledin

beni kendine kul eyledin.

Kiz, ben sana heralde asik oldum! ! ! !', 'Adini andikca gözlerim doldu seni düsününce kalbim carpti sesini duyunca icime bir hüzün cöktü ben sana heralde asik oldum. Gözlerindi bana ...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/asik-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Gördüm', 'seni-gordum-umut-can-i17bf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni gecenin üstüme ağdığı vakitlerde 

ay ışığının sulardaki şavkında gördüm.

Bir elinde güneşlerin yangın izi,

bir elinde sular vardı

Seni gecenin üstüme ağdığı vakitlerde 

çekirge ezgileri,kurt sesleri arasında

bir çoban yıldızının kıvılcımında gördüm 

gözlerin dolu dolu yağmur

saçların lapa lapa kardı.

öpsem dudaklarımı

öpmesem yüreğimi yakardı...', 'Seni gecenin üstüme ağdığı vakitlerde  ay ışığının sulardaki şavkında gördüm. Bir elinde güneşlerin yangın izi, bir elinde sular vardı Seni ...', ARRAY['Türk Edebiyatı','Şiir','Umut Can']::text[], 8.5, '{"poet":"Umut Can","poet_slug":"umut-can","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/seni-gordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Hatiran', 'senin-hatiran-suat-atar-4dzu6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ellerim baglanmis gönlümse hasta ,

Zavalli gözlerim yollarda yasta ,

Dökerim Derdimi kadehe dosta ,

Ickili masalarim senin Hatiran .

Umutlar ölüyor hayaller yorgun ,

Hayatim tükenmis hislerim dargin ,

Birlesme günü gelmez diye üzgünüm ,

Dökülen gözyaslarim senin Hatiran!!!!!!!', 'Ellerim baglanmis gönlümse hasta , Zavalli gözlerim yollarda yasta , Dökerim Derdimi kadehe dosta , Ickili masalarim senin Hatiran . Umutlar...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senin-hatiran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazel', 'gazel-umut-can-0vyct', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gamzen mezarım olsun başka birşey istemem

Gözlerin zindan olsun taş duvarlar istemem 

Güneş ilham olmuşken yine seher vaktinde

Sensiz doğmuşsa eğer yere batsın istemem

Derdin kederin ahın ne varsa yükle bana

Sırtımda Nemrut olsa sen yorulma istemem

Ölmek çareyse eğer vur hançeri bağrıma 

Lakin elinden olsun Azrail''i istemem

Koca Firavun kim ki sen gönlümün sultanı

Muhteşem Süleyman''a hünkar demek istemem

Umut odlara düşmüş hani var mı haberin 

Bu aşk-ı ızdırapla sen de yanma istemem', 'Gamzen mezarım olsun başka birşey istemem Gözlerin zindan olsun taş duvarlar istemem  Güneş ilham olmuşken yine seher vaktinde Sensiz doğmuş...', ARRAY['Türk Edebiyatı','Şiir','Umut Can']::text[], 8.5, '{"poet":"Umut Can","poet_slug":"umut-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gazel-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmiş Vakitti', 'gecmis-vakitti-tolga-baydar-axrcu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçmiş vakitti,

Akşam hüzünlerinin,

Damla damla gözümden aktığı,

Saniyelerin ard arda gelip,

Boğazıma dolandığı,

Akdeniz sahillerinde esen,

Meltemin sıcak nefesiydi,

Geçmiş vakitti.', 'Geçmiş vakitti, Akşam hüzünlerinin, Damla damla gözümden aktığı, Saniyelerin ard arda gelip, Boğazıma dolandığı, Akdeniz sahillerinde esen, ...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gecmis-vakitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruyalar', 'ruyalar-tolga-baydar-lsn5p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ruyalarda ölmek ne demek bilir misiniz?

Ankebut çöker de üzerimize,

Nefes alamayız,

Geçmişin hesabına dalarız,

Ve nedendir ki bilinmez,

Hep kötü anılar gelir aklımıza,

İşlediğimiz günahlar,

Ne can sıkıntısıdır şu ruyalar.', 'Ruyalarda ölmek ne demek bilir misiniz? Ankebut çöker de üzerimize, Nefes alamayız, Geçmişin hesabına dalarız, Ve nedendir ki bilinmez, Hep ...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruyalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-fatih-i-stanbullu-s9w0w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerimizi beraber açmadık.

Ama bir zamanı birlikte yaşadık.

Hayat acımasızdı, bizde acıklıydık...

Kısa pantolonlarımız balkonlarda asılı kaldı.

Elleri boyalı küçüklüğümüzü sandıklar aldı.

Gözü yaşlı çocukluğumuz mendilere saklandı.

O masun umutbakışlı yüzlerimiz özlemlere demir attı.

Tututuğumuz defterler,okuduğumuz kitaplar,oturduğumuz sıralar nerede şimdi..?

Duvarlara,ağaclara,sıralara yazdığımız yazılar nerede şimdi..?

Giydiğimiz kara önlükler,gardolaplarda kayboldu...

Beraber aşık olduk,aşktan kovulduk,ağladık,büyüdük.

Yılları eskittik,bu şehri eskittik,özlemlerde yeşerdik...

Şimdi nerelerdeyiz?

O günlerde büyümek isterdim;Şimdi ise ogünleri özlüyorum be arkadaş...', 'Gözlerimizi beraber açmadık. Ama bir zamanı birlikte yaşadık. Hayat acımasızdı, bizde acıklıydık... Kısa pantolonlarımız balkonlarda asılı k...', ARRAY['Türk Edebiyatı','Şiir','Fatih İstanbullu']::text[], 8.5, '{"poet":"Fatih İstanbullu","poet_slug":"fatih-i-stanbullu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/arkadas-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daldım Yine', 'daldim-yine-fatih-i-stanbullu-590ak', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dalıp gittim yine ufukların yalnızlığına.

Gene düştün,takıldın aklıma.

Oysa söz vermiştim kendime,hatırlamayacaktım sensiz seni.

Ama o sözde kuş olup uçtu anılara.

Seni düşünmeden gitmiyor elim kaleme..

Ve karalayamıyorum bir kaç satırda olsa beyaz sayfalara...

Kokladığım bir çiçeğin renkelerinde bile,

senden bir benzerlik arıyorum.

Ve yine dalıp gidiyorum sensizliğin gözlerine...

Seni bana kavuşturması isteğiyle,

özlüyorum sende kalan yanlarımı delicesine

yoksa:gözlerim sende kalmış,

ellerim sende kalmış,

yüreğim sende kalmış, bana ne.

Sensiz neye yarar onlar?

Özlüyorum, özlüyorum, özlüyorum seni...

Sensizlik canımı yakıyor...

nerelerdesin?', 'Dalıp gittim yine ufukların yalnızlığına. Gene düştün,takıldın aklıma. Oysa söz vermiştim kendime,hatırlamayacaktım sensiz seni. Ama o sözde...', ARRAY['Türk Edebiyatı','Şiir','Fatih İstanbullu']::text[], 8.5, '{"poet":"Fatih İstanbullu","poet_slug":"fatih-i-stanbullu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/daldim-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağışla', 'bagisla-fatih-i-stanbullu-7x1h0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ellerimin titrekliğini bağışla,

çünkü; korkuyorlar sana uzanmaya

Sen tutunca onları susuyorlar.

Bırakınca dönüyorlar en başa.

Bağışla gözlerimin çoğu zaman yere bakmasını

Bağışla gözlerine odaklanmamalarını.

Çünkü;Korkuyorlar hayal olmandan,

bide sana baktıklarında kaybolmandan...

Bağışla kalbimin titrekliğini,bağışla çekingenliğimi,

bağışla sana olan sevgimi

Bağışla beni. Çünkü seviyorum seni :))', 'Ellerimin titrekliğini bağışla, çünkü; korkuyorlar sana uzanmaya Sen tutunca onları susuyorlar. Bırakınca dönüyorlar en başa. Bağışla gözler...', ARRAY['Türk Edebiyatı','Şiir','Fatih İstanbullu']::text[], 8.5, '{"poet":"Fatih İstanbullu","poet_slug":"fatih-i-stanbullu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bagisla-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanma', 'aldanma-fatih-i-stanbullu-d2x97', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerimin renklerine aldanma,

duygularıma göre değişir onlar.

Sana söylediğim kelimelere kanma,

çünkü;Bana karşı hissettiklerindir onlar.

Sana bakışlarıma dal ama unutma,

bana baktığın gibi sabkıyorlar sana.

Beni görselliğimle anla,

çünkü;Ben bir aynayım kendini görürsün baktığında', 'Gözlerimin renklerine aldanma, duygularıma göre değişir onlar. Sana söylediğim kelimelere kanma, çünkü;Bana karşı hissettiklerindir onlar. S...', ARRAY['Türk Edebiyatı','Şiir','Fatih İstanbullu']::text[], 8.5, '{"poet":"Fatih İstanbullu","poet_slug":"fatih-i-stanbullu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aldanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Göründü', 'kara-gorundu-zeki-demir-r45u7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zamansız bir aşka düştük ,

yarınsız bir sevdaya.

belki biz geleceğe küstük,

umutsuz baktık dünyaya..

Zaman yanlış,mekan yanlış,

bunlar teselli.

Bu olay baştan yanlış,

sonu önceden belli..

Tayfalardan biri bağıracak,

kara göründüüüü.

Hayal gemisi karaya oturacak,

gerçek göründü.....', 'Zamansız bir aşka düştük , yarınsız bir sevdaya. belki biz geleceğe küstük, umutsuz baktık dünyaya.. Zaman yanlış,mekan yanlış, bunlar tesel...', ARRAY['Türk Edebiyatı','Şiir','Zeki Demir']::text[], 8.5, '{"poet":"Zeki Demir","poet_slug":"zeki-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kara-gorundu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklıma Geliyor', 'aklima-geliyor-metehan-sariyakutoglu-bvuwk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşünüyorum da,

Uykulu gözlerim yanıyor,

Bir garip sevdalar geliyor aklıma.

Ahengini tahayyül edemediğim

Mısra bahçelerindeki,

Masum, ama nazlı güllerin

Ilık rüzgarlarda dans edişi geliyor.

Değmeyin keyfime; 

Kara gözlü sevgiliyi hayal ediyorum.

Hayalimde...

Bir yanan köşe var kalbimde,

Dönüp dolaşıp; 

Oraya takılıyor aklım.

Sen varsın orada çünkü,

Sensin oradan yakan beni.

Bir sevgili değilsin sen,

Sevgililerden de öte,

Kalbimi çekip alamadığım biri...', 'Düşünüyorum da, Uykulu gözlerim yanıyor, Bir garip sevdalar geliyor aklıma. Ahengini tahayyül edemediğim Mısra bahçelerindeki, Masum, ama na...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aklima-geliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suizan', 'suizan-metehan-sariyakutoglu-8iakn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir güneş doğdu bu gün,

Yalnız sevda bahçelerine.

Ben, karanlıkta kaldım,

Düşmedi sevda nasibime.

Bin günümü bir gün yapıp,

Vursam taşlara başımı,

Bir bebek masumluğunda gel,

Dindirirsin göz yaşımı.

Ne güneşler doğar bahtıma,

Ben, karanlıklarda yürürüm,

Nice yollar var ki önümde,

Sana gelenin yolcusuyum.', 'Bir güneş doğdu bu gün, Yalnız sevda bahçelerine. Ben, karanlıkta kaldım, Düşmedi sevda nasibime. Bin günümü bir gün yapıp, Vursam taşlara b...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/suizan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serzeniş', 'serzenis-metehan-sariyakutoglu-73auu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir meltem eser sanki doğudan,

Ilık tenini getirir hayalime.

Ve bir yaprak kopar dalından,

Salınarak iner topraktan sevgilisine.

Azgınca söker ne varsa bağrımdan,

Bir ara, seni sakladığım yeri bulur içimde,

Yılgın yıllar görünür ufuktan,

Öylesine hazırlıksızımdır ki, sensizliğe...

Asice haykırışlar kopar dudaklarımdan,

İtiraz ederim sensizliğin her zerresine,

Sanki mahkumum hatta doğuştan,

Kurban giderim, bir sürü çaresizliğe...', 'Bir meltem eser sanki doğudan, Ilık tenini getirir hayalime. Ve bir yaprak kopar dalından, Salınarak iner topraktan sevgilisine. Azgınca sök...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/serzenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'merhaba', 'merhaba-metehan-sariyakutoglu-hefhr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merhaba güzelim;

Sana burdan, taa kalbimden sesleniyorum.

Asi yüreklerin şaha kalktığı zaman,

Benim yüreğimde volkan patlar,

Temmuz güneşi yakar sanki içimi.

Bir yaman deli olurum o zaman,

Kırlangıçların iniltisi gelir aklıma,

Zalim bir ses tırmalar kulağımı,

Ray gıcırtılarında bile hasret kokar.

Bir yaman hançer deler kalbimi,

Uğultulu sesler gelir bağrımdan,

Yokken elimde hiç bir çare,

Kahrolası vicdan zındanlarında boğulurum,

Tıkanır boğazıma, kelime namına ne varsa,

Hasret öylesine acı ki,

Sensizliği senleymiş gibi düşünüyorum, inatla...

Acı bir tebessüm kaplar yanağımı,

Aslında anlattıklarım;

Bir hiç kalır anlatamadıklarımın yanında.

-Ne asi, ne kötü kader- deyip,

Haykırasım gelir sonsuzluğa.

Analamanı beklerim son bir umutla,

Kara gözlü yare ak şiirler yazar,

Oyuncaklar ararım bir müddet avunacak,

Balçıkla sıvanamazmış ya güneş,

Yine aklıma sen gelir,

Yine kaplarsın dünyamı mağrurane,

Yine kendine beni esir edip,

Yine boğdurursun beni girdaba.....', 'Merhaba güzelim; Sana burdan, taa kalbimden sesleniyorum. Asi yüreklerin şaha kalktığı zaman, Benim yüreğimde volkan patlar, Temmuz güneşi y...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/merhaba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birden bire', 'birden-bire-metehan-sariyakutoglu-fr2rk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özlediğim aşkımsın,

                   Kalbimin köşesinde,

Mısralarıma yansıyan sevgi gibi,

                  Birden bire.

Taa yüreğimden sökülüp gelen,

Koskocaman bir umut,

Hatta bir avuç gözyaşı gibi,

                  Avuçlarımın içinde.

Suskunluk yemini etsem,

Bin defa kırsam kalemimi,

Yeminim bana inat, suskunluksa kalkanı,

                  Set çeker önüme.

''Seviyorum'' diye haykıracağım gelir,

Derin bir nefes çekerim kırlardaki rüzgardan,

Aynı heyecanla dudaklarımdan,

                   Sessizce dökülür içime.

Yangın başlar bir ara,

Ne gelirse yakar önüne,

Yüreğimi atacakken hışımla,

                    Susuzluk belirir birden bire.

Bir bebe umudu saflığında,

Yüreğimde ararken seni,

Her zerremde bin tane,

                    Seni bulurum benle...', 'Özlediğim aşkımsın,                    Kalbimin köşesinde, Mısralarıma yansıyan sevgi gibi,                   Birden bire. Taa yüreğimden sö...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/birden-bire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dimağımın Bozkırları', 'dimagimin-bozkirlari-metehan-sariyakutoglu-ly80t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüya aleminden uyanır gibiyim,

Yalpalanırken istekli bir densizlik.

Çelişmekte duygularım; tekme tokat,

İçime rağmen etrafa hakim, sessizlik...

Yorgun bir edayla kıvranırken ay,

Gökyüzüne bak, karanlık mı karanlık,

Acizane gözyaşlarıma set çeker gibiyim,

Tam cephe saldırmakta hissizlik.

Acımasız bir rüzgar tokatlamakta yüzümü,

Kalkarken dolu bombardıma şaha,

Hat zincirleriyle gelip göğüs göğüse,

Kaplar dimağımın bozkırlarını densizlik.

Sesiz bir film seyretmekteyim o an,

Ne varsa acı namına saldırmakta maziden,

Usulca umacalarım göz kırpar bir ara,

San çalar dimağımı ve bir sessizlik...', 'Rüya aleminden uyanır gibiyim, Yalpalanırken istekli bir densizlik. Çelişmekte duygularım; tekme tokat, İçime rağmen etrafa hakim, sessizlik...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dimagimin-bozkirlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Getir', 'getir-metehan-sariyakutoglu-nqut7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ve bir gün koştuğunda yürekten,

Bana yalnızca sevgi getir.

Hatta kendin gel, sade, gerçekten,

Mutluluğa çalaran rengi de getir.

Denizdeki kum fırtınasından,

Çöldeki vahşi dalgalara dek,

İki büklüm olmayan sinelerden,

Bir selam, bir kelam, tebessüm getir.

Var kur otağını Ağrı Dağın''a,

Çorum''a, Samsun''a, belki Bursa''ya

Hatta her yer bizimdir vatanda,

Muhabbete dalmaya biraz gül getir.

Deliyim, meliyim, sevgi doluyum,

Bir hüzünlü, bir neşeliyim,

Aşkından yanıp tutuşan şakiyim,

Bağrımı ıslatmaya biraz su getir.

Rüzgarda inlerler koca dağlar hey,

Buz gibi güneşse anlamı ney,

Gönlüme sade fermanla gelme,

Yanında yalnızca kendini getir.', 'Ve bir gün koştuğunda yürekten, Bana yalnızca sevgi getir. Hatta kendin gel, sade, gerçekten, Mutluluğa çalaran rengi de getir. Denizdeki ku...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/getir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meçhul', 'mechul-metehan-sariyakutoglu-f52n0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen de görürsün rüyaların da öldüğünü,

Deniz, simsiyah bir çelenk koyar önüne.

Gökyüzü kızıla çalar o vakit,

Yer, kül rengine döner umutlarınla birlikte.

Nere baksan saldıracağı tutar hatıraların,

Kendinden bile korkarak sıvışmaya yeltenirken,

Korkunç bir dev olur, bütün senler önünde....

Ne umudun kapısını çalabilir,

Ne de dost olabilirsin yalnızlık denen illetle,

Suskunluğu bile içine atarsın o vakit,

O bile korkunç bombalarla saldırır kalbine.

Kahkahalarla gülmek istediğin olur belki,

Kan kokusuyla götürür seni maziye.

En yakın düşmanın sana karşı senle olur,

Şeytanın azgın ciyaklaması yer tutar beyninde.

Kaç umut boyu düşünürsün karanlığın kinini? 

Ancak, birinin hıncı öbüründen de şiddetli.

Bir kış gecesidir belki bembeyaz karlarla,

Meçhul bir istikamete yol alırsın, yalnız ceketinle...', 'Sen de görürsün rüyaların da öldüğünü, Deniz, simsiyah bir çelenk koyar önüne. Gökyüzü kızıla çalar o vakit, Yer, kül rengine döner umutları...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mechul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elif''te Yolculuk', 'elif-te-yolculuk-ekrem-kaftan-6q1oz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elif’le başlamıştı ilk emir Ol Habîb’e

Sonu da başı gibi Elif idi İkra’nın

Habîb’in  okuduğu evvelâ Elif oldu

Göğsüne Elif yazdı, sıktığında Cebrâil

Ve karanlık mağara, binlerce Elif doldu

Dedi ki, Resûlüsün sen Allah’ın, bunu bil…

Ah idi belki o an mağaradan yükselen

Kaç bin yıllık hasretin vuslata dönmesinden

Duyduğu saadeti göklere duyurmuştu

Habîb’e kanat geren o karanlık mağara…

Cebrâil’in nidâsı yükseldi Elif Elif,

Alemlere Rahmet’in nurla dolu kalbinde…

Yıkıldı hep sütunlar yükseldikçe Elifler

Yere indi Melekler, duymak için bir Elif

Elif Elif dökülen ol Habîb’in sesinden…

Çöllerde dalga dalga Elif esti Rûzigâr,

Elif idi kameri ortasından şakk eden

Yükselip dalga dalga Habîb’in parmağından…

Görünce gözlerinde Elif’lerin nurunu

Anladı ol Habîb’in Son Resûl olduğunu

Ve yandı ciğerleri, can dostu Ebu Bekr’in

Yayıldı râyihası gecelerin üstüne…

Beyt-i Ma’mur üstünden uzandı nice Elif

Devirdi yüz üstüne Ka’be’deki putları

Kan bürüdü gözünü Ebu Cehl’in, görünce

Yükselen Elif’leri Mekke semâlarında…

Elif oldu Ömer’in elindeki kılıcı

Mekke sokaklarını dolaşıp Elif yazdı

Toplayıp kırk mü’minin kalbinden birer birer

Ve uzandı zülfesi Elif’in tâ Yesrib’e…

14 Şubat 2000', 'Elif’le başlamıştı ilk emir Ol Habîb’e Sonu da başı gibi Elif idi İkra’nın Habîb’in  okuduğu evvelâ Elif oldu Göğsüne Elif yazdı, sıktığında...', ARRAY['Türk Edebiyatı','Şiir','Ekrem Kaftan']::text[], 8.5, '{"poet":"Ekrem Kaftan","poet_slug":"ekrem-kaftan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/elif-te-yolculuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özde Yalnızlık', 'ozde-yalnizlik-fidan-aykut-bfoiy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En büyük yalnızlık;

Kalabalık içinde yalnızlıktır.

''Kendin'' olamamak,

Hissettiğin zaman ağlayamamaktır.

Sevdiğini bilememek,

Sevdiğine sevildiğini söyleyememektir.

Sevdiğine dokunamamak,

Küçültüp yüreğine sokamamaktır.

Akıldaki,

Yürekteki yalnızlıktır.

Bedendeki değil,

Ruhtaki yalnızlıktır.

21.10.1999/ İstanbul', 'En büyük yalnızlık; Kalabalık içinde yalnızlıktır. ''Kendin'' olamamak, Hissettiğin zaman ağlayamamaktır. Sevdiğini bilememek, Sevdiğine sevil...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozde-yalnizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberim Yokmuş', 'haberim-yokmus-fidan-aykut-oekie', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana sevgimi vermişim de;

Ne senin, ne de benim haberim yokmuş.

Senden sevgini, seni istemişim de;

Yüreğinin derinliklerinde kaybolmuş.

15.11.1999/ İstanbul', 'Sana sevgimi vermişim de; Ne senin, ne de benim haberim yokmuş. Senden sevgini, seni istemişim de; Yüreğinin derinliklerinde kaybolmuş. 15.1...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/haberim-yokmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yara', 'yara-fidan-aykut-q255y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ülkenin öbür ucunda da olsam,

Hissederim gözlerindeki hüznü,

Yüreğindeki acıyı.

Sevginle, sevgimle sar yaralarını.

11.9.1999/ Mersin', 'Ülkenin öbür ucunda da olsam, Hissederim gözlerindeki hüznü, Yüreğindeki acıyı. Sevginle, sevgimle sar yaralarını. 11.9.1999/ Mersin...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Seni Buldum', 'sende-seni-buldum-fidan-aykut-p9kco', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Buğulu mavi gözlerinde 

Hüznü,

Uzaklara dalan bakışlarında

Endişeyi,

Söyleyemediğin sözlerinde

Korkuyu,

Dokunamadığın ellerinde

Tutkuyu,

Haykıramadığın dizelerinde

Aşkı,

Ve sakladığın yüreğinde

Sevdayı buldum.

17.8.1999/ İstanbul', 'Buğulu mavi gözlerinde  Hüznü, Uzaklara dalan bakışlarında Endişeyi, Söyleyemediğin sözlerinde Korkuyu, Dokunamadığın ellerinde Tutkuyu, Hay...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sende-seni-buldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzünde Düğün Var', 'gokyuzunde-dugun-var-fidan-aykut-j4tbk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağaçlar soyunmuş,

Denize gökyüzünün aksi vurmuş.

Deniz gri,

Bulut gri, 

Yüreğim gri...

O da ne?

Gri bulutların arasından

Parlak bir ışık süzülmeye çalışıyor.

Birde ne göreyim,

Dostum güneş;

Gri bir battaniye ile kaplı gökyüzünde

Kendine bir açıklık bulmuş bana göz kırpıyor.

Yine bana,

Çok yukarılarda,

Görünen bu gri bulutların bile üzerinde,

Masmavi bir gökyüzünün olduğunu hatırlatıyor.

Günümü aydınlatıyor.

''Gökyüzünde düğün var'' diyor.

''Haydi gel,

Gel ve katıl bize.

Mavi kırlar üstünde,

Beyaz bulutlarla danset.''

Gözlerimi kapatıyorum

Ve gidiyorum.

22.12.1998/ İstanbul', 'Ağaçlar soyunmuş, Denize gökyüzünün aksi vurmuş. Deniz gri, Bulut gri,  Yüreğim gri... O da ne? Gri bulutların arasından Parlak bir ışık süz...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gokyuzunde-dugun-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gavur Aller', 'gavur-aller-halit-butun-8krqq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep aradım durdum dünya da bir sevgi bulayım diye

İçimdeki feryadı biraz durdurayım diye

Ah ah gavur eller nereden çıktın sen

Yıllardan beri beklediğimi biranda alıp götürdün sen

Zalim gavur eller bir dünya değil bir dünya daha olsa

İçindekilerin hepsini bana versen

Gönlümdeki sevgiyi yok edemezsin sen

Belki o sarı saçı, o güzel gözleri, o güzel dudakları, o güzel endamı

Bana göstermeyebilirsin

Ama asla gönlümden silemezsin sen onu.

Öldüğümde bile musalla taşına koyduklarında 

Senin anlayamadığın bir şeyler olur.

Elimin içinde gizlice seyredip ağladım  onun resmini

Ve boynundaki muskadan okşayıp kokladığım onun saçından bir tel göreceksin

Ve sen o zaman sevgime inanacaksın zalim gavur eller.

1958 Halit BÜTÜN', 'Hep aradım durdum dünya da bir sevgi bulayım diye İçimdeki feryadı biraz durdurayım diye Ah ah gavur eller nereden çıktın sen Yıllardan beri...', ARRAY['Türk Edebiyatı','Şiir','Halit Bütün']::text[], 8.5, '{"poet":"Halit Bütün","poet_slug":"halit-butun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gavur-aller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'gitme', 'gitme-baris-avci-kgo6u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gitme...

Beni terk etme

Emin olmadıkça bundan

Perde deyip veda etme

Güzel değildir gözlerini kaçırmak

Anıları sandığa doldurmak

Biz çocuk değildik  sevdamız oyun değil

Her ne kadar  çocukça davrandıysak

Gitme...

Dilim başka söz söylemez oldu

Sana bunu binlerce kez söyleri

Sen beni birincide anla

Ve hiç bir zaman hoşça''kalma

Kalmak istiyorsan benimle kal

Ama...

Çok istiyorsan  git

Nasılsa bir gün döneceksin

Ve  sen bana gitme diyeceksin!!', 'Gitme... Beni terk etme Emin olmadıkça bundan Perde deyip veda etme Güzel değildir gözlerini kaçırmak Anıları sandığa doldurmak Biz çocuk de...', ARRAY['Türk Edebiyatı','Şiir','Barış Avcı']::text[], 8.5, '{"poet":"Barış Avcı","poet_slug":"baris-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gitme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Başına Bir Ayçiçeği', 'tek-basina-bir-aycicegi-ahmet-gumustekin-58vmz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Büyük bir tarlanın ortasında,

Tek başına bir ayçiçeğiydi.

Tekdüze bir toplumda farklı bir kişilikti o.

Kızfın güneş üzerine vurdukça,

Sırtını güneşe dönmüş ve boynunu bükmüştü.

Toplumun üzerinde kurduğu baskılar karşısında,

Topluma küsmüş ve ondan uzaklaşmış bir kişilik gibi.', 'Büyük bir tarlanın ortasında, Tek başına bir ayçiçeğiydi. Tekdüze bir toplumda farklı bir kişilikti o. Kızfın güneş üzerine vurdukça, Sırtın...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gümüştekin']::text[], 8.5, '{"poet":"Ahmet Gümüştekin","poet_slug":"ahmet-gumustekin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tek-basina-bir-aycicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızılay', 'kizilay-ahmet-gumustekin-otrfu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gece bir farklı oluyor Kızılay,

Şimdi bir üst geçitin üzerinden Kızılay''ı seyrediyorum.

Yanan ışıklar sanki bir kadının takıları gibi yakışıyor ona.

Barlardan ve cafelerden çeşit çeşit müzik yayılıyor sokaklara.

İnsanlar sokaklara  dökülmüş adeta.

Kimisi sevgilisini,

Kimisi arkadaşını bekliyor.

Kimisi gitar çalıyor,

Kimisi efkarlanıyor.

Bu çeşitlilik ona güzel bir tat katıyor.', 'Gece bir farklı oluyor Kızılay, Şimdi bir üst geçitin üzerinden Kızılay''ı seyrediyorum. Yanan ışıklar sanki bir kadının takıları gibi yakışı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gümüştekin']::text[], 8.5, '{"poet":"Ahmet Gümüştekin","poet_slug":"ahmet-gumustekin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kizilay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Vaktimi Bekliyorum', 'gitme-vaktimi-bekliyorum-ahmet-gumustekin-7b8vb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kızılay''da geziniyorum.

Gitme vaktim yaklaşmış.

Kalan vakit geçmek bilmiyor.

Saniyeler dakika,dakikalar saat gibi geliyor.

İçimdeki hasret ve özlem beni çağırıyor.

Son bir tur atıyorum.

İnsanları izliyorum,

Herkes kendi havasında,

Biri mutlu,biri üzgün,

Biri biryere yetişmeye uğraşıyor,

Biri vakit geçiriyor.

Yavaş adımlarla hareket ederek,

Tüm bu duyguları hissetmeye çalışıyorum.

Çiçekçilerin önüne geliyorum.

Rengarenk çiçekler gözümü alıyor.

O renk cümbüşünün içinde gözüm bir noktaya takılıyor.

Kırmızı bir gülgoncası gözümü alıyor.

Diğer çiçeklerin arasında öyle güzel görünüyorki.

Onu almak istiyorum.

Biraz düşününce almaktan vazgeçiyorum.

Onun solmasına izin vermeyecek,

Kıymetini bilecek kişilere layık olduğuna karar veriyorum.

Bu kararımın vermiş olduğu,

Rahatlık ve mutlulukla gezintime devam ediyorum.', 'Kızılay''da geziniyorum. Gitme vaktim yaklaşmış. Kalan vakit geçmek bilmiyor. Saniyeler dakika,dakikalar saat gibi geliyor. İçimdeki hasret v...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gümüştekin']::text[], 8.5, '{"poet":"Ahmet Gümüştekin","poet_slug":"ahmet-gumustekin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gitme-vaktimi-bekliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nadas 2', 'nadas-2-baris-avci-hr7ex', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir tohum atıyorsun

Tarlanın en olmadık yerine

Birşeyler filizleniyor

Olmadık zamanlarda hep

Gübresi sensizlik oluyor

Suyu hep zaman', 'Bir tohum atıyorsun Tarlanın en olmadık yerine Birşeyler filizleniyor Olmadık zamanlarda hep Gübresi sensizlik oluyor Suyu hep zaman...', ARRAY['Türk Edebiyatı','Şiir','Barış Avcı']::text[], 8.5, '{"poet":"Barış Avcı","poet_slug":"baris-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nadas-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Güldü Bugün Göçük', 'dun-guldu-bugun-gocuk-berceste-ozkan-lno9u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Saat 3''te durdu,

İşte büyük deprem oldu.

Çogu gitti azı kaldı,buraların yarısını

Dün güldü bu gün göçük,

Hayat yorgun ve sessiz.

Felaketten arda kalan,

İşte şimdi savaşmalı.

Küçük bir çümleile,

Büyük önlem almalı

Düşünüp demeli ki;

Dün güldü bugün göçük

Hayat yorgun ve sessiz

Şimdi biz savaşmalı,büyük önlem almalı..', 'Saat 3''te durdu, İşte büyük deprem oldu. Çogu gitti azı kaldı,buraların yarısını Dün güldü bu gün göçük, Hayat yorgun ve sessiz. Felaketten ...', ARRAY['Türk Edebiyatı','Şiir','Berceste Özkan']::text[], 8.5, '{"poet":"Berceste Özkan","poet_slug":"berceste-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dun-guldu-bugun-gocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sen-olmayinca', 'sen-olmayinca-fidan-aykut-3j3rz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duyan olmayınca;

Kuşlar ötmez

Yapraklar söylemez oldu.

Dinleyen olmayınca;

Rüzgar esmez

Dalgalar coşmaz oldu.

Bakan olmayınca,

Ay görünmez;

Sen olmayınca,

Gönül sevmez oldu.

12.1.2000/ İstanbul', 'Duyan olmayınca; Kuşlar ötmez Yapraklar söylemez oldu. Dinleyen olmayınca; Rüzgar esmez Dalgalar coşmaz oldu. Bakan olmayınca, Ay görünmez; ...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-olmayinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Dünya', 'butun-dunya-fidan-aykut-fnepj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beraber güldük, beraber ağladık.

Onca yıldan sonra birbirimizi tanıdık.

Senden seni öğrendim bana kattım.

Benden beni öğrendin sana kattın.

Böylece tamamladık diğer yarımızı,

Bütünledik dünyamızı.

4.11.1999/ İstanbul', 'Beraber güldük, beraber ağladık. Onca yıldan sonra birbirimizi tanıdık. Senden seni öğrendim bana kattım. Benden beni öğrendin sana kattın. ...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/butun-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmanın', 'unutmanin-berceste-ozkan-8vwd9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Unutmanın kolayı var,

Yorgunluğun olayı.

Kişinin yalanı var.

Boşlugundan dolayı,

Sevginin şevkati var.

Mutluluktan dolayı.', 'Unutmanın kolayı var, Yorgunluğun olayı. Kişinin yalanı var. Boşlugundan dolayı, Sevginin şevkati var. Mutluluktan dolayı....', ARRAY['Türk Edebiyatı','Şiir','Berceste Özkan']::text[], 8.5, '{"poet":"Berceste Özkan","poet_slug":"berceste-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/unutmanin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-ozlem-isik-8j7yk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben Yalnızlığımı ayak seslerinden tanırım

Bazen parmak uşlarına basarak gelir odama

Ansızın habersizce yakalanırım.

Perdeleri çeker ,camları örter hayata

Güneşi dağların ardına kadar kovalar,

karanlığın ellerinden tutup,binbir kandırmacayla odama sokar

Dalgalar çocukluk hayallerimi avutur kıyılarda,

uçarı rüyalarım bulutlar üzerinde,

gümüş renkli ufukları kovalar.

Ya sonra?

Sonra yalnızlığım sarar onları

Ölesiye korkarlar mutlu olmaktan

rüyalarım ele avuca sığmaz olur,

hayallerim paramparça.

Ben yalnızlığımı ayakseslerinden tanırım

Veda bile etmeden çıkar odamdan

Teypte bir halk şarkısı,dilimde yalnızlık türküsü

Sabah olur ,gün doğar ve ben yalnız kalırım.', 'Ben Yalnızlığımı ayak seslerinden tanırım Bazen parmak uşlarına basarak gelir odama Ansızın habersizce yakalanırım. Perdeleri çeker ,camları...', ARRAY['Türk Edebiyatı','Şiir','Özlem Işık']::text[], 8.5, '{"poet":"Özlem Işık","poet_slug":"ozlem-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yalnizligim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlayınca', 'hatirlayinca-pinar-ergun-r364d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hatırlayınca o masum çocuk oyunları oynayan,

O saf umutlarımı,

Hatırlayınca bir tuhaf olurum.

Ne kadar da vicdansız,

Suratsızmış bu hayat,

En somurtkan çocukları güldürdüm ben,

Bir hayat gülmedi.

Ne zaman pamuk helva bulutlara baksam,

Bir tuhaf olurum,

Aklıma, şeker yediğim,

Eski günler gelir.

Ne zaman okula gelmediğim günkü dersler gelince aklıma,

Hani o sıkıntıdan patladığım dersler gelince,

Bir tuhaf olurum.

Ne kadar da çocukmuşum,

Sana çorba pişirip getirmeyi hayal ettiğim günlerde...

Hatırlayınca eskileri,

Anlarım aslında hep çocuk olduğumu

Ve özlerim çocuk olduğum günleri.

Özlemleri toplarım geçmişten

Ve kurumuş çiçek demetleri yaparım,

Seni yaşayınca...', 'Hatırlayınca o masum çocuk oyunları oynayan, O saf umutlarımı, Hatırlayınca bir tuhaf olurum. Ne kadar da vicdansız, Suratsızmış bu hayat, E...', ARRAY['Türk Edebiyatı','Şiir','Pınar Ergun']::text[], 8.5, '{"poet":"Pınar Ergun","poet_slug":"pinar-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hatirlayinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiiri Okumak', 'siiri-okumak-muhsin-i-lyas-subasi-9dz26', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mısralar şairini yükselten bir kanattır,

Şiiri yazmak kadar okumak da sanattır.', 'Mısralar şairini yükselten bir kanattır, Şiiri yazmak kadar okumak da sanattır....', ARRAY['Türk Edebiyatı','Şiir','Muhsin İlyas Subaşı']::text[], 8.5, '{"poet":"Muhsin İlyas Subaşı","poet_slug":"muhsin-i-lyas-subasi","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/siiri-okumak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hala İnsanım', 'hala-i-nsanim-fidan-aykut-7frt5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine gri bir İstanbul sabahı.

Korkuyla sarılmışım; duygularıma, umutlarıma, heyecanlarıma.

Telaşlı bakışlarla görmeye çalışıyorum;

Yemyeşil çimenleri en değerli mücevherlerden bile değerli kılan çiğ tanelerini,

Özgür ve mağrur uçan martılara yolaçan bulutları,

Binaların arasında sıkışıp kalmış, yine çiçek açmış ağaçları,

İnsanların üzerlerine basmasından korkarak saklanmış, sarı beyaz papatyaları.

Şehrin uğultusu arasından seçmek istercesine duymaya çalışıyorum;

Yandaki harabe binaya yuva yapmış kuşların sabah sohbetlerini,

Alt komşunun çocuklarının neşeli seslenişlerini,

İnsanı hafif ürperten rüzgarın, huzura çağıran seslenişlerini.

Derin bir ''Oh'' çekip rahatlıyorum.

''Hala görebiliyorum, duyabiliyorum'' diyorum.

Hala yazabiliyorum,

Hala insanım!', 'Yine gri bir İstanbul sabahı. Korkuyla sarılmışım; duygularıma, umutlarıma, heyecanlarıma. Telaşlı bakışlarla görmeye çalışıyorum; Yemyeşil ...', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hala-insanim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Benim', 'yok-benim-muhtalip-turkmen-dqcee', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dolaşırım vatanımı, yurdumu

Seyyah olmak istediğim yok benim.

Başkasına söyle dostum derdini 

Doktorluktan anladığım yok benim.

Düşünürüm köşelerde, kıyıda

İhtiyacım yoktur fazla öğüde

Gönlüm güzellerde aklıj iyide

Namerte verecek vaktim yok benim

Dünya bahçe olsa, çiçekler açsa

Hayat bayram olsa, çocuklar koşsa

Herkes seviğini kendisi seçse

Başka birşey diyeceğim yok benim

Her toplumda tek başıma gezerim

İnsanlarla alay etme kızarım

Şaka olsun diye şiir yazarım

İnan şairlikte gözüm yok benim', 'Dolaşırım vatanımı, yurdumu Seyyah olmak istediğim yok benim. Başkasına söyle dostum derdini  Doktorluktan anladığım yok benim. Düşünürüm kö...', ARRAY['Türk Edebiyatı','Şiir','Muhtalip Türkmen']::text[], 8.5, '{"poet":"Muhtalip Türkmen","poet_slug":"muhtalip-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yok-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke''ler', 'keske-ler-fidan-aykut-csqnh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ha bugün, ha yarın derken,

Ömür bitti tahmininden erken.

Ne yaptım ben bir ömür boyu derken,

Rastladın ''Keşke'' lere sonu beklerken.', 'Ha bugün, ha yarın derken, Ömür bitti tahmininden erken. Ne yaptım ben bir ömür boyu derken, Rastladın ''Keşke'' lere sonu beklerken....', ARRAY['Türk Edebiyatı','Şiir','Fidan Aykut']::text[], 8.5, '{"poet":"Fidan Aykut","poet_slug":"fidan-aykut","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/keske-ler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemiyoruz', 'i-stemiyoruz-muhtalip-turkmen-zxq08', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne kara bulutlar ne yıldırımlar

Zehir olmuş hayat istemiyoruz

Sizin olsun tüm nükleer silahlar

Ümitsiz yarınlar istemiyoruz

Asitler yağmasın toprağımıza

Radyasyon yazmayın sözlüğümüze 

Ne nükleer silah ne top ne füze

Korka korka yaşamak istemiyoruz

Seviyoruz bilimi ve bilgiyi

Tabiat anamızdır anlar sevgiyi

Bir yudum temiz su bir kır çiçeği

Kurşunu mermiyi istemiyoruz

Çiçeği koparma koru dalında

Savaşı silahı bırak bir yana

Sevdiğini göster sevgi ver bana

Yunusu unutmak istemiyoruz', 'Ne kara bulutlar ne yıldırımlar Zehir olmuş hayat istemiyoruz Sizin olsun tüm nükleer silahlar Ümitsiz yarınlar istemiyoruz Asitler yağmasın...', ARRAY['Türk Edebiyatı','Şiir','Muhtalip Türkmen']::text[], 8.5, '{"poet":"Muhtalip Türkmen","poet_slug":"muhtalip-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istemiyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görmek İstememiştim', 'gormek-i-stememistim-orhan-polat-4wp0s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hayatın inişinde ve çıkışında;

hep sorular sordu insanlar,

yarınlar üzerine rastgele veya bile bile,

yanıtladım aklımın yattığınca.

bazen başarılı bazen de başarısız...

seviyormusun? dediler, korktum ve dedimki;

-neyi? düşünceleri evet, insanları hayır...

içimde bir çocuğun haykırışını duydum...

-sıra bende diyordu bağırarak.

neyin sırası şaşırdım kendimce...

yanıtlasın isterdim özgürce,

yalnız beni bana yasaklamıştım,

uzun yıllar önce.....

yine haykırmıştı o çocuk ,

umulmadık bir yerde 

ve umulmadık bir zamanda.

sırası değildi, konuşmamalıydı,

ve de yasaklanmalıydı, yasaklandı....

süresi de müebbetti...

oysaki o çocuk içimde hep parmak kaldırmıştı.

ve ben görmemiştim...

belki anlatmaya çalışacaktı korkularını,

belki  de içimdeki çocuğu,

ve duygularını,

hasretini anlatacaktı mısralarla ....

belkide yarınlarımızı anlatacaktı...

oysa ben o çocuğu hiç görmemiştim,

görmüştümde görmemezlikten gelmiştim,

belki isteyerek, belkide istemeyerek...

içimdeki o çocuğu küçük yaşta hapsetmiştim,

parmak kaldırışını da hiç görmemiştim,

çünkü görmek istememiştim....

ekim 1999

ankara', 'hayatın inişinde ve çıkışında; hep sorular sordu insanlar, yarınlar üzerine rastgele veya bile bile, yanıtladım aklımın yattığınca. bazen ba...', ARRAY['Türk Edebiyatı','Şiir','Orhan Polat']::text[], 8.5, '{"poet":"Orhan Polat","poet_slug":"orhan-polat","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gormek-istememistim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sigara', 'son-sigara-guney-ayisit-4vcnp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Son sigaramı içiyorum 

Sahilin izbe karanlığı altında

Yarı eğrilmiş bir direğe yaslanmış,

Senin gidişini düşünüyorum.

Sular bir gelip, bir çekliyor

İşte sen de böylesin diyorum içimden.

Dalga dalga gelip,

Usulca çekiliyorsun.

Mazide yaşanmış unutulan anılar gibi

Sularda kumdaki izleri koparıp

Birer birer siliyordu yavaşça

Kime ait olduğunu sormadan

Sigara, parmak uçlarımı yakmaya başlıyor

Nedir ki bu! Senin aşk ateşinin yanında.

Parmaklarım titreyerek aralanıyor

Ateş parçası yavaşça yere savruluyor 

İşte!! sular yine geliyor haince

Düşüncelerimi ve bitöiş izmaritimi alıp götürüyor.

Hayatın benden kopardığı diğer şeyler gibi.

(12.02.19998  01:45)', 'Son sigaramı içiyorum  Sahilin izbe karanlığı altında Yarı eğrilmiş bir direğe yaslanmış, Senin gidişini düşünüyorum. Sular bir gelip, bir ç...', ARRAY['Türk Edebiyatı','Şiir','Güney Ayısıt']::text[], 8.5, '{"poet":"Güney Ayısıt","poet_slug":"guney-ayisit","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/son-sigara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özeleştiri', 'ozelestiri-salih-bolat-daafe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'beklenmedik bir şafak gibi parlıyor ellerimizde bıçaklar

fazla buluyoruz ışığı ve tek başına bırakıyoruz.

bacaya konmuş güvercinle konuşuyor yağmur, en yalın diliyle

yazık, hiçbir şey anlamıyoruz bu konuşmadan, yoksun kalıyoruz

çeliğin şarkısını dinlemekten, düş görmekten.

gökyüzü kılıcını bırakıyor bir süre için 

bizse sürekli istiyoruz onu: üzülmüşüz bir kez

asma dalındaki tomurcuğun yer değiştirmesine, ateşle', 'beklenmedik bir şafak gibi parlıyor ellerimizde bıçaklar fazla buluyoruz ışığı ve tek başına bırakıyoruz. bacaya konmuş güvercinle konuşuyor...', ARRAY['Türk Edebiyatı','Şiir','Salih Bolat']::text[], 8.5, '{"poet":"Salih Bolat","poet_slug":"salih-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozelestiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-baris-avci-iqec6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'senden  son bir dileğim 

olsaydı eğer

göz yaşlarınla ıslanan yanaklarına

sıcak  bir buse koymak

isterdim

bir akşam bir rakı tadında

yiğitçe 

aniden

korkmadan

beni sevmeni  isterdim

senden son bir dileğim

olsaydı eğer

bu

son dileğimin olmamasını

                                isterdim!!', 'senden  son bir dileğim  olsaydı eğer göz yaşlarınla ıslanan yanaklarına sıcak  bir buse koymak isterdim bir akşam bir rakı tadında yiğitçe ...', ARRAY['Türk Edebiyatı','Şiir','Barış Avcı']::text[], 8.5, '{"poet":"Barış Avcı","poet_slug":"baris-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dilek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-haydar-ergulen-iiw8a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kadın gider ve bunun şiir olduğu söylenir 

kadın gider ve bir şair doğar bundan 

(Ben hangi kadından şair olduğumu bilirim)

"Yazın bittiği her yerde söylenir"se 

kadının gittiği de her yerde söylenir 

kadın gittiği her yerde şiir diye söylenir: 

Kadının gittiği yazın bittiğidir, her yerde 

yaz biter kadın giderse, bunun sonu şiirdir, 

yazın sonu şiirdir, şiirdir aşkın sonu... 

Şehir her semtiyle yazın peşine düşse 

yaz uzar bundan ve aşklar da nasiplenir, 

yazın peşinde şehir, kadının peşinde şiir 

eylülün semtine kadar böyle gidilir 

bir gecede gittimdi hazirandan eylüle 

eylül yazdan terkedilmişti, şiirse haziranda 

kadın tarafından terkedildi o söylenceye: 

Bütün oğullar anneyi bir şiire terkeder! 

O kadın beni terkederse şair olurum 

oğul olduğum kadın sakın beni terketme, 

şiirdir söylenir, yazdır biter, kadındır gider 

Bütün kadınlar şiiri bir kadına terkeder!', 'Kadın gider ve bunun şiir olduğu söylenir  kadın gider ve bir şair doğar bundan  (Ben hangi kadından şair olduğumu bilirim) "Yazın bittiği h...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar-ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/eylul-440-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp', 'kayip-muzaffer-gezer-56fq5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Direniş, destan yazarken zindanlarda

Sloganlar yırtarken sessizliğini 

Plaza Del Mayo''nun

Ben vardım bebelerin ilk gülüşlerinde

Namluya mermiyi süren de bendim

Düştüğünde müfreze it pususuna

Çocuğunu emziren ananın umudunda,

İlk aşk, ilk heyecan

Genç kız utangaçlığında

Göz kırpan yine bendim aydınlıklara

Emeğin adımları aşarken yolları,

Tereddütsüz,korkusuz ve kararlı

Bir elim pankartı kavradı

Nöbetler tuttum sabahlara dek

Barikatlarda

Gece ayazdı.

Oysa ne kadar emindi

Öldürdüğünden beni.

Elinde çelik teli ile

Çöktüğünde boğazıma

Kara gömlekli it dölü

Kurşunlar saplandıkça bedenime

Büyüdüm.

Üstümde söndürülen sigaranın ateşini

Söndürdü,

Bastırdı kavganın ateşi.

Adım  Ayşenur''du,

Hasan''dı

Ne farkeder.

Tutsaktım zındanlarda

Kaybedildim

Kaybetmedim anne.

DİRENDİM.', 'Direniş, destan yazarken zindanlarda Sloganlar yırtarken sessizliğini  Plaza Del Mayo''nun Ben vardım bebelerin ilk gülüşlerinde Namluya merm...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kayip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Milis Kızı', 'milis-kizi-muzaffer-gezer-k1ch8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne kadar benziyorsun ülkeme

ey güzel kız

Sarı, mavi, yeşil, mor,

kırmızı çiçeklerin.

Ne kadar can alıcı

Şirin tatlı dillerin.

Dost selamı, dost gülüşü

Dost sözü türkülerin.

Bir çocuk kurşuna dizilir,

Gözlerinden kan boşalır, ağlarsın.

Anayla ağıt yakarsın

benimle mermi.

Saçlarında esiyor rüzgarlar

Dağlarında ateş yakmış şahanlar

Saçların alev alev,

Alev alev dağları.

Ne kadar benziyorsun ülkeme ey güzel kız 

Ey seva gözlüm 

ey kavga sözlüm

Ben sevdikçe seni

Bana yasaktır ölüm.', 'Ne kadar benziyorsun ülkeme ey güzel kız Sarı, mavi, yeşil, mor, kırmızı çiçeklerin. Ne kadar can alıcı Şirin tatlı dillerin. Dost selamı, d...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/milis-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Varmış...', 'bir-varmis-muzaffer-gezer-7b4zk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Selanik''ten gelmiş dedelerim

Bir at arabasının üzerinde

Şavaş sonrası

mübadelede

İttihatçıymış büyük dedem Yunus Ali

Onun torunu

Yani dedem Ali

Eskicilik yaparak sağlamış geçimini

Eskimiyen İstanbul''da

Sırtında beyaz bir çuvalla

Hala süsler düşlerini çocukluğumun

Bir sedir üzerinde 

Cam kenarında

Yanında pastırma sucuk

Ve şarap

''''Papaz karısı''''

Lambalı Grundig''den

Arapça-Rumca şarkılar

İlk kavgamdan kazandığım,

arap çocuğu dövdüm diye

Dedemde aldığım,

Kocataş marka

Türk gazozu

Çeyrek ekmek arası parmak sucuk....

Kavgalarla büyümüş babam 

Hücrelerle

Karntilarla

Ve tabii sevdalarla

Bir zamanlar vatan haini

Şimdilerin iade-i itibarlası Adnan

Yıktırınca gecekonduyu

Daha doğrusu tenekeden barakayı

Kucak açmış bizimkilere Gültepe

Gültepe

O yıllarda bir tuğla harmanı.

Devir;

Delikanlılık devri

Mahalledeki kıza asıldı diye

Adam marizleme 

Sokak lambası altında barbut

Zorbalarla köşe kapmaca

Yani; delikanlı alemi

Yanlış olmaz.

Taş taşımış arsalar almış 

Bir gariban gelmiş kapısına

Kız kaçırmış

Sırtında döşek yorgan

Ardında belalılar

Birlik olmuş meydan okumuş

Bir ufak rakı parasına 

Arsalar satmış

Evler satmış babam.

Racon kesmiş

Adı Baba''ya çıkmış

Adımız Baba''nın oğluna çıkmış

Kumar

White Horse viski

Kömürlü Lark

Kumkapı''dan bir takadan alınma

Beyaz çarşafa sarılı

Kaçak Marlboro....

Derken anama sevdalanmış.

Sınırsız

Kuralsız

Ve Korkusuz

Dünyalara eğilmeyen başı 

Anamın yanağına eğilmiş

Ölümün üstüne atlayıp

Kaçırmış anamı

Sonra ben olmuşum

Bir Zafer Bayramı öncesi

Saati Maarif yaprağından

Koymuşlar adımı

''''Oğlun olursa Muzaffer olsun

ersin zafere''''

Kapkara bir oğlanmışım

Dedem severmiş kara oğlan diye

o yıllarda

''''sahte'''' umut Eco

Henüz Karaoğlan adını almamışım

Ve 

Eco mavisi diye bir renk de

Yok gökkuşağı içinde

Gazetelerde manşet

''''Anarşist avı başladı''''

Duvarlarda ''''aranıyor'''' ilanları

Muhbirlere vaatler

Sokaklarda

Beyaz miğferli polis

Panzer, reo

Ve askerler

Radyolarda anons

''''..........Kızıldere''de kuşatıldılar.''''

Babamın anneme söylediği 

''''Örf-i idare ilan olmuş Hanım'''' sözü

Hala kulaklarımda

Sonra sıradan çokcukluk

Her çocuğun ki gibi sıradan

Her çocuğun ki gibi büyülü

Her çocuğun ki gibi

Hatırlandıkça hüzünlü

Ama ülkemdeki her çocuğun ki gibi de

Erkenden büyümeye tutsak.....

Yağmurlu bir pazar akşamıydı

Günaydın dedim

Eskisinin Asker-i Tıbbiyesi

Şimdilerin Marmara Üniversitesi

o yılların en iyisi

Devrimin kalesi

Haydarpaşa Lisesi''ne.

Yatılı okul 

Yatakhaneler

Yemekhaneler

Kara şimşek mercimek

Kumlu ıspanak

En önemlisi ayrılık........

Önce Leo Humberman''la tanıştım

İlk okuduğum kitap

''''Sosyalizmin Alfabesi''''

Sonra 

''''İşçi neden ve nasıl sömürülür?''''

Sınıf 

Artı-Değer

Burjuvazi

Ve proterler.

Sonra ilk boykot

İlk yürüyüş

İlk job

İlk dipçik

Bir acı haber

''''Dedem kanlar içinde, alnında kurşun yarası''''

Sonra sürgün

Bandırma

Balıkesir...

Bir sabah Hasan Mutlucan''la uyandım.

Bir yazılıma sonrası yorgunluğuyla

İdamlar

Postallar

İşkence

Aklımda kalanlar o yıllardan.

Bir de eli kanlı birilerinin sözleri

''''Fikriyatımız iktidarda biz zindandayız.''''....

Sonra ilk aşk 

İlk hüsran....

En büyük aşkım İstanbul

''''Dönülmez  aşkamın ufkundayız''''

Galata köprüsünde köpek öldüren

Sarı tuzlu leblebi

Etrafa ihanet

Sevgisizlik

İtiraf

Yani ölümün kıyısındayız.....

Sonra bir kadın çıktı karşıma

Ömrünü sundu bana

Kendini sundu

Bir Haziran akşamı oğlumu

''''Fatih''imi yani''''

.........

İşçiler grevde 

Dört yiğit ölüme yatmış

Tutsaklar direnişte

Kavganın ateşi diri

Kulaklarımı yırtan bir ses haykırıyor

Duyuyorum

Büyüyorum

''''Haklıyız-Kazanacağız''''

....

...

..

.

Şimdi yemin etmişim ölüme

Ölümüne sevmeye

Sınırsız

Kuralsız

Ve korkusuz direnmeye

..

Sevdanın emekçisi

Kavganın hamalı olmak için

Güneşi içmeye......', 'Selanik''ten gelmiş dedelerim Bir at arabasının üzerinde Şavaş sonrası mübadelede İttihatçıymış büyük dedem Yunus Ali Onun torunu Yani dedem ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":179,"source_url":"https://www.antoloji.com/bir-varmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim İçin', 'benim-i-cin-metehan-sariyakutoglu-zhjro', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dördüncü adımı da at benim için,

Belki de beşincisini……

Bu akıl, bu mantık, bu fikir senin,

Binlerce yol katedip de ola ki dönersen,

Yıllar sonra hala, bıraktığın yerdeyim…

Bir nebzecik bak bana, hatta biraz da fazla,

Belki de bir umutla….

Bu gözler, bu bakış, bu şuur senin,

Her geçen gün dost sayına yenisini eklerken,

Binlerce el arasında unuttuğun dost benim…

Gülüşüne gülüş kat, bana yolla biraz da,

Belki bebe saflığında….

Bu istek, bu dilek, bu yürek senin,

Serüvenli hayalin, bir başka ok ararken,

Kalbine sapladığım yerden kırdığın ok benim….', 'Dördüncü adımı da at benim için, Belki de beşincisini…… Bu akıl, bu mantık, bu fikir senin, Binlerce yol katedip de ola ki dönersen, Yıllar ...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/benim-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buruk', 'buruk-metehan-sariyakutoglu-87j0z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu gördüğün mavi deniz,

Mavi öfkenin diğer adı.

Şu gördüğün mavi de gök,

O''nun kızıldır hıncı .......

Sapsarı kesilmiş simalar,

Konuşmayan belirsiz ifadelerle,

Aynı şeyi düşünüp de susmak,

Gökten anlam inecekmiş gibi,

Acizane mi yoksa akılcı?

Mırıldandığın;

Son şarkı yahut besteden,

Çıkarmaya çalıştığın sözü hatırlarken,

Kırkıncı yıla tesadüf ederse suskunluğun,

Hangi gerçek ne kadar acı?

Koşarken;

Yorulmamak için tek başına,

Mırıldandığın namelere yakıştıramadığın,

Dört dünya büyüklüğündeki,

Hayalden de öte hayellerin,

Belki bir gün,

Sana da olacak davacı...

Yalnızlık;

Tan yerinden kaldırırken başını,

Ben yoktum.

Avuç dolusu umacalardan,

Tek başına kalan,

Tanımadın mı o haykırışı.....', 'Şu gördüğün mavi deniz, Mavi öfkenin diğer adı. Şu gördüğün mavi de gök, O''nun kızıldır hıncı ....... Sapsarı kesilmiş simalar, Konuşmayan b...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/buruk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Değil', 'bu-degil-metehan-sariyakutoglu-tb7l1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son haykırışın bu değil,

Islak bakışlarla anlattığın.

Saatler belirsizliği gösteri zaten,

Bir hatıra ki umursamazlığın.

Karanlık köşelerin tavrı bu değil,

Yaldızlı dakikalara yansıyan,

Sessizliğin canavarı,

Meydandaki yelkovan sesleri...

Ümide sürülen törpü bu değil,

Sessiz ve hüzünle adımladığın yol,

Kan içercesine,

İçine akıttığın göz yaşların.

Sevdanın anlamı bu değil,

Korkuyla karışık ve umutsuz,

Dalgın, maziden,

Ala ümitli ağaran kızıllık.

Yaşamın anlamı bu değil,

İç çekip boyun eğiş kadere,

El pençe divanla,

Gönülsüz bir ''EVET'' tüm isteklere.

Mehtabın haykırışı bu değil,

Ortaya çıkıp zifiri karanlıkta,

Bir dakika sonra

Saplanmak kara buluta.....', 'Son haykırışın bu değil, Islak bakışlarla anlattığın. Saatler belirsizliği gösteri zaten, Bir hatıra ki umursamazlığın. Karanlık köşelerin t...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-metehan-sariyakutoglu-co2gd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biz, susuz çöllerde; 

Güneş tepemizi yakarken yeşerdik.

Kızgın kumlar ayağımıza kor misali,

Ağu akıttıkça kendimize geldik.

Hayale kapılmadık,

Umut ettik.

Rüya değil, Serap değil,

Bitkinin yeşermesinden yeşerdik.

Can geldi; 

Kokuşmaya çalaran beynimize,,

Biz o zaman ancak, 

Biz olduğumuzu bildik.

Yalınayak düştük yollara,

Bulutlardan yağmur bekleyerek,

Buluttaydı gerçi gözümüz,

Devamettik yolumuza Allah''dan ümit ederek.

Tökezlendik; 

Yolumuzu kesti yılanlar, çıyanlar,

Kanlarımızla doyurduk onları.

İlerledik ''Bizimdir hedef'' diyerek,

Yılmadık, yıldırdık.

Bir iken; bin olduk, yüzbin olduk,

Dün iken; bu gün olduk, yarın olduk,

Ben iken; biz olduk, bizler olduk,

Özgür birliğe giden yolları,

Tümseklerden düzler olduk.', 'Biz, susuz çöllerde;  Güneş tepemizi yakarken yeşerdik. Kızgın kumlar ayağımıza kor misali, Ağu akıttıkça kendimize geldik. Hayale kapılmadı...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nar Ağacının Gölgesinde Bulamadığım', 'nar-agacinin-golgesinde-bulamadigim-haktan-murat-keskin-2p8a1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'doğarken içimdeki yalnızlık

derinden sessizce

sahiplenmişti seni

kılıfına uyduramadığım aşkının 

sevgi yokuşları yordu kalbimi;

sisli gecelerde 

kaybettiğim gölgem

içimde eskitemediğim aşkının 

yansımasıydı belki de

biliyormuydum, hatırlamıyorum

dur demeliydim her anına seninle

kolay olmayan unutmak seni

nar ağacının gölgesinde.', 'doğarken içimdeki yalnızlık derinden sessizce sahiplenmişti seni kılıfına uyduramadığım aşkının  sevgi yokuşları yordu kalbimi; sisli gecele...', ARRAY['Türk Edebiyatı','Şiir','Haktan Murat Keskin']::text[], 8.5, '{"poet":"Haktan Murat Keskin","poet_slug":"haktan-murat-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nar-agacinin-golgesinde-bulamadigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hangisi...?', 'hangisi-tolga-kose-usl9k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üç seçeneğiniz var;

Hangi insandan daha çok korkarsınız desem,

Kendini küçük gören insanlardan mı...?

Yoksa kendini bir şey sananlardan mı...?

Ya da bunları size söyleyenlerden mi?

.

.

Seçiminiz bu üç seçenekten biriyse;

Yanıldınız....!

.

.

En korkulacaka olanları;

Bunları bile bile hala sizinle arkadaşlık edenlerdir....!', 'Üç seçeneğiniz var; Hangi insandan daha çok korkarsınız desem, Kendini küçük gören insanlardan mı...? Yoksa kendini bir şey sananlardan mı.....', ARRAY['Türk Edebiyatı','Şiir','Tolga Köse']::text[], 8.5, '{"poet":"Tolga Köse","poet_slug":"tolga-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hangisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Tomurcuklari', 'sevda-tomurcuklari-deli-kiz-swv02', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen icimde sevda tomurcuklari

Yagmurdan sonra dogan gunessin

Koklamaya kiyamadigim bir gul

Bakmaya doyamadigim sevgimsin

Karanliktan cikip gelen

ve bir turlu ''SENI SEVIYORUM'' diyemedigimsin 

ve birtanem sen,  ugrunda herseyi feda edebilecegimsin', 'Sen icimde sevda tomurcuklari Yagmurdan sonra dogan gunessin Koklamaya kiyamadigim bir gul Bakmaya doyamadigim sevgimsin Karanliktan cikip g...', ARRAY['Türk Edebiyatı','Şiir','Deli Kiz']::text[], 8.5, '{"poet":"Deli Kiz","poet_slug":"deli-kiz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevda-tomurcuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geliyorum', 'geliyorum-deli-kiz-x5yl8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kral icin

Uyandirin yarimi soyleyin geliyorum

Yollumu gozlesin onu cok seviyorum

Sevdigim bunu bilsin

Elinde gul yureginde sevgi beni beklesin', 'Kral icin Uyandirin yarimi soyleyin geliyorum Yollumu gozlesin onu cok seviyorum Sevdigim bunu bilsin Elinde gul yureginde sevgi beni bekles...', ARRAY['Türk Edebiyatı','Şiir','Deli Kiz']::text[], 8.5, '{"poet":"Deli Kiz","poet_slug":"deli-kiz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/geliyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gotur Beni', 'gotur-beni-deli-kiz-njnqc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sicak bir yaz gunu karsilasirsak

Sevgi dolu yuregimle ''Merhaba'' dersem sana 

Bir yabanciya bakar gibi bakma yuzume

Kimligimi sorma 

Bu merhabaya ac yuregini ve sonra....

Al, al gorut beni nereye istersen oraya', 'Sicak bir yaz gunu karsilasirsak Sevgi dolu yuregimle ''Merhaba'' dersem sana  Bir yabanciya bakar gibi bakma yuzume Kimligimi sorma  Bu merha...', ARRAY['Türk Edebiyatı','Şiir','Deli Kiz']::text[], 8.5, '{"poet":"Deli Kiz","poet_slug":"deli-kiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gotur-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne olur?', 'ne-olur-muhtalip-turkmen-4bwfy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mevsimler peşpeşe geçip giderken,

Baharları yaza katsak ne olur?

Şarkılardan fal tutarken ben sana, 

Nağmeleri söze katsak ne olur?

Yağmur yağıp gökkuşağı çıkınca,

Sular kayalardan şırıldayınca,

Gül yaprağı dmlaları tutunca,

Bizbize,elele olsak ne olur?

O bahar başkaydı yaz bir başkaydı,

Şarkılar bir alem saz bir başkaydı,

Sevdan deli dolu naz bir başkaydı,

Gönülden gönüle aksak ne olur?

Candan sevdim canım dedim ben sana,

Sevdalandım gönül verdim ben sana,

Döndüm döndüm gene geldim ben sana,

Şimdi aynı yolda gitsek ne olur?', 'Mevsimler peşpeşe geçip giderken, Baharları yaza katsak ne olur? Şarkılardan fal tutarken ben sana,  Nağmeleri söze katsak ne olur? Yağmur y...', ARRAY['Türk Edebiyatı','Şiir','Muhtalip Türkmen']::text[], 8.5, '{"poet":"Muhtalip Türkmen","poet_slug":"muhtalip-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-olur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırıldım', 'kirildim-muhtalip-turkmen-y7ggp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşım dokuz oldu okumuyorum,

Okula gitmedim ben hiç bilmiyorum.

Düğünde bayramda giyinmiyorum,

Şuna bak dediler fena kırıldım.

Ayağımda lastik, çoraplarım yok,

Yollar çamur olsa içimde bir ok,

Söylemek istemem benim derdim çok,

Pis çocuk dediler buna kırıldım.

Benimle oynamaz öbür çocuklar,

Onların hep yeni giyisileri var,

Hastayım burnumdan hep sular akar,

Sümüklü dediler gene kırıldım.

Öksüz koymuş beni anamı bilmem,

El kahkaha atar bense hiç gülmem,

Rızkım kuru ekmek sıcak aş bulmam

Bana hor bakarsan sana kırıldım.', 'Yaşım dokuz oldu okumuyorum, Okula gitmedim ben hiç bilmiyorum. Düğünde bayramda giyinmiyorum, Şuna bak dediler fena kırıldım. Ayağımda last...', ARRAY['Türk Edebiyatı','Şiir','Muhtalip Türkmen']::text[], 8.5, '{"poet":"Muhtalip Türkmen","poet_slug":"muhtalip-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kirildim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bildiri', 'bildiri-afsar-timucin-0o2ws', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir mavide birden değişmek olur 

Bakışın bakışıma vurunca

Ölüp denizlere karışmak olur

Bakışın bakışımdan yorulunca

Daha beyaz sabahlar var

Alıp gitme bütün gülüşlerimi

Götürme düşlerimi

Sardunyalar güllere dokununca

(Sinsi zehirler tatlı

Senin her şeyin güneş)

Gelip ışığında ısınıyorum

Yaşamak ölüm gibi koyulunca', 'Bir mavide birden değişmek olur  Bakışın bakışıma vurunca Ölüp denizlere karışmak olur Bakışın bakışımdan yorulunca Daha beyaz sabahlar var ...', ARRAY['Türk Edebiyatı','Şiir','Afşar Timuçin']::text[], 8.5, '{"poet":"Afşar Timuçin","poet_slug":"afsar-timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bildiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökkuşağı', 'gokkusagi-pinar-ergun-ec4cx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Martı Jonaşan gibi,

Hep daha yükseklere uçmak isterken,

Seni buldum gökkuşağının içinde.

Sen, gökkuşağının sarı rengisin,

Sıcaklığının önünü zaman zaman sisler kapatsa da.

Martının uzaklarda bulup,

Hemen dost olduğu kişiler gibisin,

Ama birşey var şimdi beni korkutan,

Jonaşan ayrılmak zorunda kalmıştı dostlarından...

Yakında biz de öyle ayrılacağız,

Biliyorum aynı değil,

Ama nedense bana aynı geliyor

Ve ayrılık,

Sevginin her çeşidinde zor geliyor,

Zor geliyor...', 'Martı Jonaşan gibi, Hep daha yükseklere uçmak isterken, Seni buldum gökkuşağının içinde. Sen, gökkuşağının sarı rengisin, Sıcaklığının önünü...', ARRAY['Türk Edebiyatı','Şiir','Pınar Ergun']::text[], 8.5, '{"poet":"Pınar Ergun","poet_slug":"pinar-ergun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gokkusagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar İçinde', 'anilar-i-cinde-suat-atar-df0ma', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Simdi kimsezizim yalnizim

Sen gittin kaldin anilar icinde

Fakat bilmeni isterdim

Sarkimiz caliyor halen kalbimde

Yine yildizlar serilmis yakamoz üstüne

Munzur yikilmis dag etegine

Bak her sey yerli yerinde 

Bir sen yoksun kaldin anilar icinde

Gün doguyor yine kuslar ötüyor

Benin icimde firtinalar dinmiyor

Kuzey rüzgari götür beni savur tözumu dört yana

Yarim gitti kaldim yalniz, sarildim anilara

Sevmedim kimseyi seni sevdigim kadar

Vermedim deger kimseye sana verdigim kadar

Kapattim kapisini kalbimin sen giderken ardindan

Simdi yoksun, kalacaksin anilarimda ben ölene kadar! ! !', 'Simdi kimsezizim yalnizim Sen gittin kaldin anilar icinde Fakat bilmeni isterdim Sarkimiz caliyor halen kalbimde Yine yildizlar serilmis yak...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anilar-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adını Dağlardan Bile Kıskandım', 'adini-daglardan-bile-kiskandim-gokmen-ozturk-3h8up', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sadece sana

Yine uykusuzum bu gece gözlerim yorgun ve agrili,

Ama yine uyku girmiyor gözlerime.

Oturdum,dolaştım,uzandım olmuyor,

Gitmiyor varligin aklımdan,

Her dakika seni anıyorum,

İsmin düşmez dolu dudaklarımdan.

Zaman oldu ağlamak istedim.

Ama yokluğumdan ağlayamadım.

Göz yaşlarıma gizli olan hayalin, 

Gözlerimden düşerek sandım.

Adını haykırmak istedim:

Karşımdaki ıssız dağlara.

Birden durdum uzun uzun düşündüm.

Adını dağlardan bile kıskandım.', 'sadece sana Yine uykusuzum bu gece gözlerim yorgun ve agrili, Ama yine uyku girmiyor gözlerime. Oturdum,dolaştım,uzandım olmuyor, Gitmiyor v...', ARRAY['Türk Edebiyatı','Şiir','Gökmen Öztürk']::text[], 8.5, '{"poet":"Gökmen Öztürk","poet_slug":"gokmen-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/adini-daglardan-bile-kiskandim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'dogum-gunun-kutlu-olsun', 'dogum-gunun-kutlu-olsun-suat-atar-tqmiv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzaktan yazarim bu siiri sana 

Yanimda yoksun öpeyim be ana

Darilma gelemiyorum diye yanina 

Dogum günün kutlu olsun, nice yillara

Unutamam ana yaptigini senin bana

Sacini süpürge ettin benim yoluma

Yanimdaydin her agladigimda

Dogum günün kutlu olsun, nice yillara

Her derdimize bir derman buldun

Cocuklarin icin hep calistin, kosturdun

Simdi Nenelik yapiyorsun torunlara

Dogum günün kutlu olsun, nice yillara

Bizleri her kötülükten geri tutun 

Ama sen Ana, sen kendini unuttun 

Simsiyah sacini beyaza tutturdun

Ellerinden öperim, dogum günün Kutlu olsun nice yillara! ! ! !', 'Uzaktan yazarim bu siiri sana  Yanimda yoksun öpeyim be ana Darilma gelemiyorum diye yanina  Dogum günün kutlu olsun, nice yillara Unutamam ...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dogum-gunun-kutlu-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Bedduam', 'sana-bedduam-suat-atar-54otc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönlümdeki duygular taşsın diline yalvarsin,

dilindeki kelimeler coşsun kaleme sarilsin,

elindeki kalemler kitaplara Roman yazsin,

kitaplardaki Romanlar hep beni anlatsin,

beni okuyan o gözler dilerim boncuk boncuk damlasin,

o damlayan yaşlar tüm dudaklari islatsin,

islak islak dudaklar aşkımla alev yansin, 

yüz cevirsin Romani okuyan tüm dostlar,

umudun bir cift kalemle kalsin,

iz biraksin hatiralar anilar ömrünce tek beni anasin,

andikca dilerim yüregin kanasin

kanasinki hasrete tutsak olasin,

hasretlik icine daglansin, bana ettiklerine pisman olasin 

pismanliginla perisan yasayasin,yasadikca rezil olasin,

iste belki ozaman bana yaptiklarini sende anlarsin! ! ! ! ! ! !', 'Gönlümdeki duygular taşsın diline yalvarsin, dilindeki kelimeler coşsun kaleme sarilsin, elindeki kalemler kitaplara Roman yazsin, kitaplard...', ARRAY['Türk Edebiyatı','Şiir','Suat Atar']::text[], 8.5, '{"poet":"Suat Atar","poet_slug":"suat-atar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sana-bedduam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An''lar', 'an-lar-adil-koruyan-yyt01', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşamak güzel bugünü, 

         Dünden güzelse eğer,

Yarınlar, hayal ürünü;

         Yaşamak, ömre değer.

Sevgiliye aç gönlünü,

         Sevgin doruğa erer.

Yaşam, sonuçta ölümlü,

         Düşünmek neye değer.

							An’lar, bir ömre yeter...', 'Yaşamak güzel bugünü,           Dünden güzelse eğer, Yarınlar, hayal ürünü;          Yaşamak, ömre değer. Sevgiliye aç gönlünü,          Sev...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/an-lar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyku Tutmuyor;', 'uyku-tutmuyor-selcuk-coskun-l1fe0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'YOKLUĞUN

Uyku tutmuyor;

Ay kadar eski,

Ay kadar yorgunum.

Nafile uyku tutmuyor.

Dalar gibi

oluyorum

ama çok kısa,

nöbetçi gibi.

Oda 7 adım,

dolaşıyorum.

Yokluğunla konuşup,

Yokluğunla sevişiyorum

O kısa rüyalarda...

	03.06.1995

	ANKARA', 'YOKLUĞUN Uyku tutmuyor; Ay kadar eski, Ay kadar yorgunum. Nafile uyku tutmuyor. Dalar gibi oluyorum ama çok kısa, nöbetçi gibi. Oda 7 adım, ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uyku-tutmuyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanmak Kolay', 'yanmak-kolay-selcuk-coskun-p8enm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimsenin postuna bürünmedim ki ben!

Yalan söyleyeyim Sana...

Evet ilk aşkım değilsin.

Ve son kavgam değil ki bu;

Paylaşmadan bilemezsin.

Özlemek, yanmak kolay!

Şarkılar söyleye bilir misin bana?

Hiç duymadığım.

Ağlata bilir misin durup dururken.

Ve Sen de sevebilir misin benim gibi....

	ANKARA', 'Kimsenin postuna bürünmedim ki ben! Yalan söyleyeyim Sana... Evet ilk aşkım değilsin. Ve son kavgam değil ki bu; Paylaşmadan bilemezsin. Özl...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yanmak-kolay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oldum', 'oldum-metehan-sariyakutoglu-062rp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Virane olmuşda o benim köyüm,

Selamın vermeden alamaz oldum.

Eski dostluğumuza yoktur bir sözüm,

Bir çağrı almadan varamaz oldum.

Şu haber sineme bir kurşun gibi,

Candan sevilenler orada yok ki,

Garip anam sormuş benim halimi,

Mektubuma cevap alamaz oldum.

Hani benim orda eski dostlarım?

Garip elden, ordan haber sorarım,

Derdim teselliye muştu ararım,

Sılam unutmuş da varamaz oldum.

Şu yalan dünyanın türlü haline,

Bir nefretim vardır cazip malına,

Beni uzak koyan budur sılaya,

Sıladan gittim de varamaz oldum,

Derdime bir çare bulamaz oldum.', 'Virane olmuşda o benim köyüm, Selamın vermeden alamaz oldum. Eski dostluğumuza yoktur bir sözüm, Bir çağrı almadan varamaz oldum. Şu haber s...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye', 'niye-metehan-sariyakutoglu-lgz9i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yılların maziden parladığı an,

Gülerek karşıma gelirsin, niye?

Yüzyüze konuşmak istediğim an,

Sadece rüyamda olursun, niye?

Dilerim her zaman yüzün göreyim,

Ben de senin kalbine gireyim,

Dilersen aşkıma kurban vereyim,

Benden uzaklarda olursun, niye?

Uğuldar kulağım sesin duymazsa,

Yanmaz kuru ağaç ateş olmazsa,

Gözlerim kararır seni görmezse,

Aşkıma saygısız kalırsın, niye?

Ararım seni gittiğim yerde,

Bu halde yürürüm garip menzile,

Cehennem azabı sensizlik bende,

Sen hep kaçarsın, acaba niye?', 'Yılların maziden parladığı an, Gülerek karşıma gelirsin, niye? Yüzyüze konuşmak istediğim an, Sadece rüyamda olursun, niye? Dilerim her zama...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/niye-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle', 'soyle-metehan-sariyakutoglu-qlg2c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derdimi dindireyim diye geldim.

Bu yolda bir müddet ömür verdim.

Bazen takıldım yollarda,

Bazen adresini sordum...

Şimdi yanındayım, burada.

Söyleyeceğim birazdan derdimi.

Hiç olmazsa dinler gibi yap,

Çok sayın Dertçi Baba...

Sakın sakal sıvazlama,

Bir de ''hımm'' çekeyim deme.

Alışılmışın ötesinde söyle,

İlk gelen neyse aklına...

Üzüleceğimi katma hesaba,

Çaresiz kalacağımı da.

Sonra, ne olacağını düşünme,

Hemen söyle, neyse aklında?

Gözlerini süzüp bakma,

Görme heyecanlı halimi,

Sakın el işaretleri de yapma,

İlk ne varsa söyle aklında.

İlla sevinmem gerekmez,

Sert olma ben bakarken,

Nasihat edeyim de deme,

Aklında ne varsa söyle.

Söyle hemen öyle bön bön bakma,

Açık konuş, anlamam Arif''likten,

Ve susma dakikası yıllar kadar,

Durmadan söyle, neyse aklında?

Hatta oflayıp, poflayım deme,

Kısacası fazla bekletme,

Benim aceleciliğimi irdemeden,

Aklına ilk geleni söyle...

Beklersen üzülürsün,

Halim biraz acıdır terazide,

Dolusu almaz, boşu dolmaz,

Hemen söyle o yüzden, birden.

Yanılsan da önemli değil,

Ben hep yanılmışımdır zaten,

Karşında suskun beklerken,

Neyse, hemen söyle aklından geçen.', 'Derdimi dindireyim diye geldim. Bu yolda bir müddet ömür verdim. Bazen takıldım yollarda, Bazen adresini sordum... Şimdi yanındayım, burada....', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/soyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevimli', 'sevimli-metehan-sariyakutoglu-0wy6s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O yalnızlığı kendine sor,

Kendinde ara içindeki savaşı,

Neden suskunsun, neden yalnız?

Hatta neden hep hüzünlü?...

Susacağın yere konuş dilim;

Elbette bir şeyler bulursun anlatmaya,

Hiç olmazsa de bir ''merhaba,''

Mutlu nameler söyle ya da...

Ve gözlerim; bir yere dikilmiş,

Bıraksam, öylece kalacak yıllarca.

Hüzün, yalnızlık her halinden belli,

Nedir bu halinin sebebi?

Ağlayacağın yere gül biraz,

Elbet bir sebep bulursun ışıldamağa.

Kırpışıver bir kez hiç olmazsa,

en azından canlı ve mutlu bak.

Hatta yüz hatlarım;

Neden hiç anlamsız duruyorsun?

Nedir seni gergin tutan?

Ne korkar gibisin, ne de,

Yılmış gibi bir halin var hasmından.

İfadesiz olacağına biraz gül,

Elbet bir sebep bulursun yumuşamağa.

Gülümseyiver birkez iç olmazsa,

En azından mutluluk okunsun görünüşünden.

Elbette sizlerle yargılayacaklar beni.

Bu halime baktıklarında;

Kimi der; zalim, kimi der; cani.

Hiç olmazsa neşeli olursanız biraz;

Ben de olurum, sözde; SEVİMLİ....', 'O yalnızlığı kendine sor, Kendinde ara içindeki savaşı, Neden suskunsun, neden yalnız? Hatta neden hep hüzünlü?... Susacağın yere konuş dili...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/sevimli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kemal Sunal', 'kemal-sunal-fevzi-tokbas-jjlib', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Evimizde,  içimizde  yüreğimizde  bir  yer  ettin,

Küçükten    büyüğe,   gönüllerimizi   feşettin,

Böyle   zamansız mı bizi  bırakıp   gidecektin,

Halk  kahramanımız  sevgili  KEMAL  SUNAL !...

Ağlayan   dertli   yüzleri   bile   hep   güldürdün,

İçimizdeki   gam  ve  stres çemberini   öldürdün,

Kahkahalara   boğdun   bazen de   düşündürdün,

Halk  kahramanımız  sevgili  KEMAL  SUNAL !...

Hem    neşe   verdin,   hem de    dersler  verdin, 

Bu     topluma     bir     çok    şeyleri     öğrettin, 

Biri   yanlış    yapsa      eşşoğlueşşek      derdin,           

Halk  kahramanımız  sevgili  KEMAL  SUNAL!...', 'Evimizde,  içimizde  yüreğimizde  bir  yer  ettin, Küçükten    büyüğe,   gönüllerimizi   feşettin, Böyle   zamansız mı bizi  bırakıp   gidec...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Tokbaş']::text[], 8.5, '{"poet":"Fevzi Tokbaş","poet_slug":"fevzi-tokbas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kemal-sunal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakın Artık Beni Bana', 'birakin-artik-beni-bana-aziz-ekici-dt3vf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karşınızda aciz bir insan vardı

Eğitim de o gün

Onuruyla oynadınız, gururunu kırdınız.

Sevgisini aldınız elinden,

Topaç gibi yuvarladınız, sakız gibi çiğnediniz.

Gözüme baka baka.

Vurdunuz beni gücüm yetmedi size,

Aldığınız sevgi güç vermez size,

O bana aittir.

Sizde biçare kalır, boynu bükük kalır.

Üniversite de, Eğitimde bırakın onu.

Doğayla kucaklaşsın güneş koruyacaktır onu.

Sevgimi korumaya muhtaç bıraktınız,

Ancak sonsuz derinlikler yeter ona,

Buhar olup yağmurla birlikte gelecektir bana.

Tekrar sevdamla sarmaş dolaş,

Sevdam bana muhtaç ben sevdama.

Bırakın artık beni bana.', 'Karşınızda aciz bir insan vardı Eğitim de o gün Onuruyla oynadınız, gururunu kırdınız. Sevgisini aldınız elinden, Topaç gibi yuvarladınız, s...', ARRAY['Türk Edebiyatı','Şiir','Aziz Ekici']::text[], 8.5, '{"poet":"Aziz Ekici","poet_slug":"aziz-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/birakin-artik-beni-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Gelen Mektup', 'geri-gelen-mektup-huseyin-nihal-atsiz-nd2h2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ruhun mu ateş, yoksa o gözler mi alevden? 

Bilmem bu yanardağ ne biçim korla tutuştu? 

Pervane olan kendini gizler mi hiç alevden? 

Sen istedin ondan bu gönül zorla tutuştu.

Gün, senden ışık alsa da bir renge bürünse; 

Ay, secde edip çehrene, yerlerde sürünse; 

Her şey silinip kayboluyorken nazarımdan,

Yalnız o yeşil gözlerinin nuru görünse...

Ey sen ki kül ettin beni onmaz yakışınla,

Ey sen ki gönüller tutuşur her bakışınla! 

Hançer gibi keskin ve çiçekler gibi ince

Çehren bana uğrunda ölüm hazzı verince

Gönlümdeki azgın devi rüzgarlara attım; 

Gözlerle günah işlemenin zevkini tattım.

Gözler ki birer parçasıdır sende İlahın,

Gözler ki senin en katı zulmün ve silahın,

Vur şanlı silahınla gönül mülkü düzelsin; 

Sen öldürüyorken de vururken de güzelsin! 

Bir başka füsun fışkırıyor sanki yüzünden,

Bir yüz ki yapılmış dişi kaplanla hüzünden...

Hasret sana ey yirmi yılın taze baharı,

Vaslınla da dinmez yine bağrımdaki ağrı.

Dinmez! Gönülün, tapmanın, aşkın sesidir bu! 

Dinmez! Ebedi özleyişin bestesidir bu! 

Hasret çekerek uğruna ölmek de kolaydı,

Görmek seni ukbadan eğer mümkün olaydı.

Dünyayı boğup mahşere döndürse denizler,

Tek bendeki volkanları söndürse denizler! 

Hala yaşıyor gizlenerek ruhuma ''Kaabil''

İmkanı bulunsaydı bütün ömre mukabil

Sırretmeye elden seni bir perde olurdum.

Toprak gibi her çiğnediğin yerde olurdum.

Mehtaplı yüzün Tanrı''yı kıskandırıyordur.

En hisli şiirden de örülmez bu güzellik.

Yaklaşması güç, senden uzaklaşması zordur; 

Kalbin işidir, gözle görülmez bu güzellik...', 'Ruhun mu ateş, yoksa o gözler mi alevden?  Bilmem bu yanardağ ne biçim korla tutuştu?  Pervane olan kendini gizler mi hiç alevden?  Sen iste...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Nihal Atsız']::text[], 8.5, '{"poet":"Hüseyin Nihal Atsız","poet_slug":"huseyin-nihal-atsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/geri-gelen-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serenad', 'serenad-ahmet-muhip-diranas-c255p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeşil pencerenden bir gül at bana,

Işıklarla dolsun kalbimin içi.

Geldim işte mevsim gibi kapına

Gözlerimde bulut, saçlarımda çiğ.

Açılan bir gülsün sen yaprak yaprak

Ben aşkımla bahar getirdim sana;', 'Yeşil pencerenden bir gül at bana, Işıklarla dolsun kalbimin içi. Geldim işte mevsim gibi kapına Gözlerimde bulut, saçlarımda çiğ. Açılan bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Muhip Dıranas']::text[], 8.5, '{"poet":"Ahmet Muhip Dıranas","poet_slug":"ahmet-muhip-diranas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/serenad-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri Söylemiştir', 'biri-soylemistir-ozer-bal-fqg6i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'O kadar hiçkimseye ait değilim ki

O kadar herkese ait sevgim

Birinden vazgeçemeyecek kadar senin...

Birinin olamayacak kadar hiçkimseye aitim.', 'O kadar hiçkimseye ait değilim ki O kadar herkese ait sevgim Birinden vazgeçemeyecek kadar senin... Birinin olamayacak kadar hiçkimseye aiti...', ARRAY['Türk Edebiyatı','Şiir','Özer Bal']::text[], 8.5, '{"poet":"Özer Bal","poet_slug":"ozer-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/biri-soylemistir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorsam', 'seviyorsam-ozer-bal-vvh2v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasılsa öyle yaşanacaktı

Söylenecek bir bahane hep vardır

Ha bugün yalnız

Ha günün ötesi

Seni sevmek

Beni harcamak olmayacaktı

Sana yüklediğim anlamları

Senmişsin gibi düşünme

Aldanırsın.

Sen o anlamlarla

Sadece bende varsın

Ben seviyorsam

Sen bahanesin', 'Nasılsa öyle yaşanacaktı Söylenecek bir bahane hep vardır Ha bugün yalnız Ha günün ötesi Seni sevmek Beni harcamak olmayacaktı Sana yüklediğ...', ARRAY['Türk Edebiyatı','Şiir','Özer Bal']::text[], 8.5, '{"poet":"Özer Bal","poet_slug":"ozer-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seviyorsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azrail''in Oyunu', 'azrail-in-oyunu-mustafa-cakmak-h5h4d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kara kaşların, bronz teninle,

Kara gözlerin, pamuk elinle,

Hepsi olacak elbet birgün benimle;

Azrail’in bir oyununa gelmezsem eğer!

Baldan tatlı onca güzel sözünle,

Kalbindeki tutuşup yanan közünle,

Beni bile yaktığın o tertemiz özünle,

Beraberiz; Azrail bir oyun etmezse bize!

Beraber ol hep nazınla, cilvenle,

Işıltısı tükenmeyen gözünle,

İhtimal yok, ‘olmaz’ diye seninle,

Azrail’in bir oyununa gelmezsem eğer!

Biliyorum kızacaksın bu sözlerime,

Engel olamıyorum ‘sana’ sonsuz sevgime,

Sen olmazsan bilmem ne olur nefsime,

İşte o zaman Azrail’e bırakmam işi inan!!…

(Ankara-2000)', 'Kara kaşların, bronz teninle, Kara gözlerin, pamuk elinle, Hepsi olacak elbet birgün benimle; Azrail’in bir oyununa gelmezsem eğer! Baldan t...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakmak']::text[], 8.5, '{"poet":"Mustafa Çakmak","poet_slug":"mustafa-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/azrail-in-oyunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alt Tarafı', 'alt-tarafi-mustafa-cakmak-1o4s7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düşünüyorum da; 

“Senden ayrılmak pek koymaz” diyorum “bana.”

En fazla; kalbim silindirin altında kalmış gibi parçalanır,

Gözlerim kan çanağına döner!

Senden ayrılınca en fazla;

Beynim işlevini yitirir;

Devamlı seni düşüneceği için.

En fazla; ellerim tutmaz;

Sana bir daha dokunamayacağı için.

Alt tarafı; dışarı çıkamam, insan içine karışamam.

Ayaklarım adım atmayı unutur; Adımlarım sana gelemediği için.

Kulaklarım sesi unutur belki; o sesi senden beklediği için.

Başka ne olabilir ki? 

Bir de; 

Sanki kurşuna dizilmişim gibi bir his,

Alt tarafı mengenede kalmış gibi ezilen bir başım olur,

Belki;

Sensizliğin yerine kor ateşler dolar kalbimin içine.

Senden ayrılmak fazla bir üzüntü yaratmaz bende!

Belki kafamın bir giyotinle bedenimden ayrılması için dua ederim;

“Belki daha az acı verir” diye!

Alt tarafı;

Her tarafıma bıçaklar saplanıyormuş gibi,

Alt tarafı;

Dünyanın en yüksek gökdeleninden atmışlar gibi olur.

Alt tarafı;

Bir okyanusun ortasındaymışım gibi yalnız hissederim kendimi,

Belki;

Bir daha Ay’a bakmamak için kendi gözlerimi oyarım!

Başka ne olabilir ki?…

Dedim ya;

Senden ayrılmak “pek” koymaz bana… ( ??? )

(Ankara-1999)', 'Düşünüyorum da;  “Senden ayrılmak pek koymaz” diyorum “bana.” En fazla; kalbim silindirin altında kalmış gibi parçalanır, Gözlerim kan çanağ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakmak']::text[], 8.5, '{"poet":"Mustafa Çakmak","poet_slug":"mustafa-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/alt-tarafi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek İhtimal', 'tek-i-htimal-mustafa-cakmak-feymm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seninle ilişkimiz,

Sadece bir ihtimale dayanarak başladı;

İmkansız bir ihtimale!

Şu anda ise;

Senden ayrı olmak

Ve 

Sensiz yaşamak imkansız hale geldi.

Seni çook sevdim

Ve 

Artık tek ihtimalim;

“SENSİN”

(Ankara-2000)', 'Seninle ilişkimiz, Sadece bir ihtimale dayanarak başladı; İmkansız bir ihtimale! Şu anda ise; Senden ayrı olmak Ve  Sensiz yaşamak imkansız ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakmak']::text[], 8.5, '{"poet":"Mustafa Çakmak","poet_slug":"mustafa-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tek-ihtimal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleyiş', 'bekleyis-mustafa-cakmak-mmboj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir tohum tanesiydin sen;

Büyük bir umutsuzlukla kalbime ektiğim.

Su yerine, sevgi verdim, saygı verdim,

Ve en önemlisi; 

“herşeyden çok” sevgi verdim.

Bir zaman oldu;

Hiç beklemediğim bir anda,

Kalbimde bir kıpırdanma,

Hani;

Bitkinin güneşe ulaşmak için

Toprağı yırtışı var ya? İşte, 

Öylesi bir kıpırdanma.

O bitki,

Büyüdü, büyüdü, büyüdü,

Ve yeşerdi;

Eşsiz güzellikteki,

Haz veren yeşili ile.

Büyüdükçe; yeşeriyor,

Yeşerdikçe; 

beni sabırsızca 

ve heyecanlı bir bekleyiş alıyor;

Dünya’nın en güzel bitkisinin,

Dünya’nın en güzel meyvelerini bekleyiş!!!…', 'Bir tohum tanesiydin sen; Büyük bir umutsuzlukla kalbime ektiğim. Su yerine, sevgi verdim, saygı verdim, Ve en önemlisi;  “herşeyden çok” se...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakmak']::text[], 8.5, '{"poet":"Mustafa Çakmak","poet_slug":"mustafa-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bekleyis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzum', 'arzum-mustafa-cakmak-qbdik', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sevgilim var;

Adı; kendinin bende uyandırdığı duyguya çok uygun,

Hatta aynı!

Güzel;

Hem de; 

Gözü çarpanın bir daha gözünün çarpması için dua ettiği,

Ona bakanın gözünü hiç çekmek istemediği kadar güzel!!

Sesini duyanın, hiç susmasını istemediği,

Sadece sesini duyabilmek için konuyu uzatıp,

Konudan konuya geçtiği,

Dudaklarının arasından süzülen kelimelerin

Ve 

Onlara hayat veren o sesin 

Bir bülbül edasıyla çıkması,

Onu vazgeçilmez kılan 

Ufak nedenlerden “sadece” birkaçı!

Onu çook seviyorum!

Çünkü O;

Bunu hak edecek kadar güzel,

Bunu hak edecek kadar; 

Zeki, saf, temiz, sevecen, 

Tabii “biraz”da; kapris ve cilve!

En soğuk günlerde bile;

Ayazdan insanların ilikleri 

Kutuplardaki bir buz parçasından farksızken 

Ve 

Tükürüklerinin ağızlarında donduğu soğuklarda bile;

Teninin tenime değdiği anda,

Vücudumun gözeneklerinden;

Çok,

Bir o kadar tatlı, hoş, 

Dünyada tarifi yapılamayacak kadar

 muhteşem bir duygunun ispatı gibi boşalır terler!

Kaşlar “kara”,

Gözler “kara”,

(daha ne ister bu fukara?)

Bunca güzelliğin üstüne;

Bir de o gamzesi eklenince …

İşte o zaman bitiriyor beni “o güzellik”.

“BİRAZCIK” kaprisli ve cilvelide olsa;

O; benim “sevgilim”

O; benim “bitanem”

O; benim “vazgeçilmezliğim”

O; benim “meleğim”

Kalbimin sahibi,

“HASRETİM”

O; benim “miss’im”

O; benim “canım”

O; benim “tek arzum”

“O; BENİM “ARZU’M”', 'Bir sevgilim var; Adı; kendinin bende uyandırdığı duyguya çok uygun, Hatta aynı! Güzel; Hem de;  Gözü çarpanın bir daha gözünün çarpması içi...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakmak']::text[], 8.5, '{"poet":"Mustafa Çakmak","poet_slug":"mustafa-cakmak","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/arzum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda', 'sevda-pako-orhan-aj0iv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sevdalar kumsalı diye bir yer duydunmu hiç?

tabiki duymassın yaşamadığın şey bu senin.

yaşasan beni anlarsın..!

karşıkı dağdan bana seslenirsin.

bende sana seslenirim sevgilim

hadi sevda denizinde buluşalım sevdalım.', 'sevdalar kumsalı diye bir yer duydunmu hiç? tabiki duymassın yaşamadığın şey bu senin. yaşasan beni anlarsın..! karşıkı dağdan bana seslenir...', ARRAY['Türk Edebiyatı','Şiir','Pako Orhan']::text[], 8.5, '{"poet":"Pako Orhan","poet_slug":"pako-orhan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahramanlık', 'kahramanlik-huseyin-nihal-atsiz-u7og4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kahramanlık ne yalnız bir yükseliş demektir,

Ne de yıldızlar gibi parlayıp sönmemektir.

Ölmezliği düşünmek boşuna bir emektir; 

Kahramanlık; saldırıp bir daha dönmemektir.

Sızlasa da gönüller düşenlerin yasından

Koşar adım gitmeli onların arkasından.

Kahramanlık; içerek acı ölüm tasından

İleriye atılmak ve sonra dönmemektir.

Yırtıcılar az yaşar... Uzun sürmez doğanlık...

Her ışığın ardında gizlidir bir karanlık.

Adsız şansız olsa da, en büyük kahramanlık; 

Göz kırpmadan saldırıp bir daha dönmemektir.

Kahramanlık ne yalnız bir yükseliş demektir,

Ne de yıldızlar gibi parlayıp sönmektir.

Bunun için ölüme bir atılış gerekir.

Atıldıktan sonra bir daha dönmemektir...', 'Kahramanlık ne yalnız bir yükseliş demektir, Ne de yıldızlar gibi parlayıp sönmemektir. Ölmezliği düşünmek boşuna bir emektir;  Kahramanlık;...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Nihal Atsız']::text[], 8.5, '{"poet":"Hüseyin Nihal Atsız","poet_slug":"huseyin-nihal-atsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kahramanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emanet', 'emanet-tibet-avci-a5eiv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''''Sen daima iyi ve doğru olmalısın; 

                          bensizken bile...''''

Aydınlığını hiçbir kötülük karartmamalı

Hiçbir yalan yoldan çıkarmamalı seni.

Ve kendine iyi bak, beni de unutma sakın

Bilirsin kimselere güvenemem

Bu yüzden seni sana emanet ettim ben', '''''Sen daima iyi ve doğru olmalısın;                            bensizken bile...'''' Aydınlığını hiçbir kötülük karartmamalı Hiçbir yalan yold...', ARRAY['Türk Edebiyatı','Şiir','Tibet Avcı']::text[], 8.5, '{"poet":"Tibet Avcı","poet_slug":"tibet-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/emanet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parmaklarımın Ucunda Hayat', 'parmaklarimin-ucunda-hayat-tibet-avci-qtz80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Can canın nihayetidir

Az önce hayat verdim

Parmaklarımın ucunda

Bir bebeğe

Can canın felaketidir

Az önce ölüm verdim

Parmaklarımın ucunda

Bir böceğe', 'Can canın nihayetidir Az önce hayat verdim Parmaklarımın ucunda Bir bebeğe Can canın felaketidir Az önce ölüm verdim Parmaklarımın ucunda Bi...', ARRAY['Türk Edebiyatı','Şiir','Tibet Avcı']::text[], 8.5, '{"poet":"Tibet Avcı","poet_slug":"tibet-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/parmaklarimin-ucunda-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Tanımışken', 'seni-tanimisken-sair-bogac-mlyc8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıldız ve güneş 

Gece ile gündüz gibiyiz.

Öyle imkansız ki bir aşkı yaşamak

Seni tanımışken yaşayamamak

Ne büyük acı ama,

uzakta olsan bile varlığın öyle güzel ki....', 'Yıldız ve güneş  Gece ile gündüz gibiyiz. Öyle imkansız ki bir aşkı yaşamak Seni tanımışken yaşayamamak Ne büyük acı ama, uzakta olsan bile ...', ARRAY['Türk Edebiyatı','Şiir','Şair Boğaç']::text[], 8.5, '{"poet":"Şair Boğaç","poet_slug":"sair-bogac","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seni-tanimisken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey İlahi!', 'ey-i-lahi-i-dris-kosaca-lhpov', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ey İlahi! Senin kudretine hayranım;

Şu gördüğün arş-u aleme gıpta eyleyen

Bir nebze senin kudretinden kenarda olsam yanar kül olurum, kalmaz dermanım

Hala; gaflete gözüm dalmış hülyaya,

Sıcak olur oflarız, soğuk olur üşürüz,

Bir tutku ki, gönül dalmış rüyaya,

Oysa biz aslında, kör kütürümüz.

Ey Nefis! Uysallaş artık, kendine gel!

Yırtıcı olma sakinleş ki körlüğün gitsin,

Akıbetin bir hiçtir, sonun perişan,

Bu bedbaht yokluğun iyilikle bitsin.', 'Ey İlahi! Senin kudretine hayranım; Şu gördüğün arş-u aleme gıpta eyleyen Bir nebze senin kudretinden kenarda olsam yanar kül olurum, kalmaz...', ARRAY['Türk Edebiyatı','Şiir','İdris Koşaca']::text[], 8.5, '{"poet":"İdris Koşaca","poet_slug":"i-dris-kosaca","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ey-ilahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deymem', 'deymem-batuhan-ogunlu-g7n86', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni sevdiğimi söylemek için

Çok acılar çektim

Elbet bir gün öğreneceksin 

Belki o zaman sende beni

Seveceksin

Belkide güleceksin

Ama mutlaka öğreneceksin

Belki duyunca bana 

Kızacaksın

Belki üzüleceksin

Hayır üzülme üzülme canım

Benim için

Bilirsinki deymem

Deymem böyle şeyler için', 'Seni sevdiğimi söylemek için Çok acılar çektim Elbet bir gün öğreneceksin  Belki o zaman sende beni Seveceksin Belkide güleceksin Ama mutlak...', ARRAY['Türk Edebiyatı','Şiir','Batuhan Öğünlü']::text[], 8.5, '{"poet":"Batuhan Öğünlü","poet_slug":"batuhan-ogunlu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/deymem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '16 Şubat 1989''a', '16-subat-1989-a-metehan-sariyakutoglu-h6jan', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '(16/02/1989''da ölen kardeşime) 

Bir başka doğdu o gün güneş,

Biraz sönük, eskisinden köhne...

Hatta alışılmıştan da öte,

Mazlum da değildi hali,

Sanki garip bir haberci gibi...

Hatta sakınır gibi hali vardı gözükmekten,

Üzgün gibiydi akşam üzeri gelecek haberden..

Bir başka doğdu o gün güneş,

Alışılmışın da ötesindeydi hatta,

Biraz sönüktü önünde yoktu bulutta.

Mat bir rengi vardı.

Kızıldan da öteydi parlaklığı.

Bu halde baktım güneşe,

Biraz hüzünlüydüm, nedense? 

Bir başka doğdu o gün güneş,

Hatta alışılmışın da ötesinde,

Kafam karmakarışık, çözümsüzlük beynimde,

Konuşulanları bile anlamıyorum çevremde.

Herkes garip bakıyor ne varsa halimde? 

Akşama kadar üzgün duruyorum, sade.

Her zamanki halim de diyemiyorum bu gün,

Belki ben de farkındayım garipliğin.

Salınıyorum bir boşluğa doğru,

Üzgün mü üzgün...

Bir başka doğdu o gün güneş,

Akşam da aynı halde salınıyor ufka,

Alışılmışın da ötesinde hatta,

Sinsi bir gariplik var daha fazla.

Bir ruh haliyle oturuyorum yatağa...

Yüzümde aynı duygusuz eda...

Gürültüyle biri beliriyor kapıda,

''Acele'' diyor, ''Kendini topla''

Kalbim adeta fırlıyor yerinden,

Düşünmeye başlıyorum ilerden, geriden.

Sonra, ''toplanma'' emrine uyuyorum yavaşça,

Duracak halim yok ki ayakta...

Kolumdan tutuyorlar bir akşamüstü,

Batan güneşi seyrediyorum, hüzünlü.

Bir başka doğuyor o gün güneş,

Akşam da aynı halde salınıyor ufka.

Alışılmışın da ötesinde hatta....

Meğer yol ne kadar da uzunmuş,

Tükenmiyor gitmekle böyle günlerde.

Altımızda vınlayan o büyük dolmuş,

Meğer ne kadar da durgunmuş.

Bir mahşeri kalabalık evin önünde,

Çoluk, çocuk, yaşlı bir biri üstünde,

Aman Yarabbi, ne var bizim evde? 

Yeşil tabut gözüküyor soğuk yüzle,

Şimdi birimizi ayıracak içimizden,

Getirmeyecek bir daha götürdüğünü,

Kopartıp alacak onu kalbimizden...

Kıyamete dek götürecek yolcusunu,

Döndürmeyecek bir daha, bilse de özlediğimizi.

Bir başka doğuyor o gün güneş,

Akşam da aynı halde salınıyor ufka,

Alışılmışın da ötesinde hatta...

Yeşil bir tabut duruyor soğuk bir yüzle,

''Ölen kim? '' diye soruyorum hemen.

Yok bir cevap hiç kimseden.

Sadece diyorlar matemle; 

''Pek de şu bizim rahmetli''

Tüm gücümle haykırıyorum aleme,

Kendimi atıyorum aynı şekilde yere.

Yaşlı gözlerim dönmüşçesine,

Boşalıyor ırmak, ırmak.

Beni de götürüyorlar bir kenara,

Aynı odada toplanıyoruz, komşularla.

Onlardan öğreniyorum abimin,

Ölmüş olduğu gerçeğini...

İşte o zaman anlıyorum bu günkü garipliği...

Bir başka doğuyor o gün güneş,

Akşam da aynı halde salınıyor ufka,

Alışılmışın da ötesinde hatta...

Yeşil bir tabut duruyor soğuk bir yüzle,

O zaman anlıyorum bu günkü garipliği...', '(16/02/1989''da ölen kardeşime)  Bir başka doğdu o gün güneş, Biraz sönük, eskisinden köhne... Hatta alışılmıştan da öte, Mazlum da değildi h...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/16-subat-1989-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abim', 'abim-metehan-sariyakutoglu-qwpf4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(18/10/1991''den 16/02/1989''a) 

Bu gün seni gördüm rüyamda,

İlk işin beni kucaklamak oldu.

Seni böyle yakın görmek ne âlâ,

Bu görüşme pek kısa oldu.

Çekindim senden hatta ürperdim,

Adım adım kendimi geri çektim,

Yüz hatların gergindi, halsizdi,

Saçlarına ak düşmüştü, ürperdim.

Sonra, sana adeta haykırdım; 

Üç yıldır kafamdakini sordum,

''Nerdeydin, niçin gittin, nereye? ''

Sonra bakışlarımı senden çevirdim.

Cevabın; ''ben yapmadım'' oldu.

Sen anlattıkça içim burkuldu.

''Tek, dedemin haberi yok.'' diyordun,

Bu arada gözüm annemi buldu.

Annem; sevinçliydi, neşeliydi.

Yılların hüznünü attığı belliydi.

Tüm ızdırapları çıkarmıştı sinesinden,

Hatta bir günlük gelin gibiydi.

Ah o sarsıntı... rüyamın sonu oldu,

Biraz daha, saatlerce sürse ne olurdu? 

Çatlarsam çatlayaydım bu rüyadan,

Hiç olmazsa ızdırabın belli olurdu.

Ne olur geceleri rüyaları bırak,

Gerçekten gel yanıma ap ak.

''Abiciğim'' diye sarılayım sana,

Öpeyim seni; ölmediğini anlayarak...', '(18/10/1991''den 16/02/1989''a)  Bu gün seni gördüm rüyamda, İlk işin beni kucaklamak oldu. Seni böyle yakın görmek ne âlâ, Bu görüşme pek kıs...', ARRAY['Türk Edebiyatı','Şiir','Metehan Sarıyakutoğlu']::text[], 8.5, '{"poet":"Metehan Sarıyakutoğlu","poet_slug":"metehan-sariyakutoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/abim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevdim', 'seni-sevdim-simge-atakan-q0p33', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni seveceğimi nerden bilebilirdim

Çağırsan bir kere koşa koşa gelirdim

Duysan başkasınınım inanma ben hep senindim

Aldanırdım sözlere kendime yenilirdim

Sensiz olmaz bunu ben hep söyledim

Nedense sen kadere yenildin

İnan değerini bir ben bilirdim

Gör artık gerçekleri sadece seni sevdim', 'Seni seveceğimi nerden bilebilirdim Çağırsan bir kere koşa koşa gelirdim Duysan başkasınınım inanma ben hep senindim Aldanırdım sözlere kend...', ARRAY['Türk Edebiyatı','Şiir','Simge Atakan']::text[], 8.5, '{"poet":"Simge Atakan","poet_slug":"simge-atakan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seni-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorum Yok', 'yorum-yok-aziz-ekici-etkot', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kır çiçeğim, zambağım, mor sümbülüm, sarı zeybeğim.

Beyaz teninde tüm güzellikleri taşıyan efelim benim.

Sevmeğe doyamadığım güzelim benim.

Şiirim, türküm, şarkım benim. 

Kalemimle, beyaz sayfalara taşıdığım sevdam benim.

Kana kana içtiğim suyum, ekmeğim aşım,

Bakmaya doyamadığım güzelim benim.

Tutuldum güzel sesine, sözüne, sohbetine,

Güzel yüzüne, saçının her teline tutuldum.

Sana koştum çöllerde sensizim.

Kaktüs çiçekleri topladım acım sensizim.

Sarardım soldum, savruldum sensizim.

 (16.07.1999)', 'Kır çiçeğim, zambağım, mor sümbülüm, sarı zeybeğim. Beyaz teninde tüm güzellikleri taşıyan efelim benim. Sevmeğe doyamadığım güzelim benim. ...', ARRAY['Türk Edebiyatı','Şiir','Aziz Ekici']::text[], 8.5, '{"poet":"Aziz Ekici","poet_slug":"aziz-ekici","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yorum-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sultan', 'sultan-yasin-caglar-93km4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hatırladım onu sunurdan

Ta istanbuldan

Birini tanıyorum 

Adı sultan

Kendini şair sanan

Şiir yazan zaman zaman

Birini seviyorum 

Adı sultan

Hep kendi yazdığını söyleyen

Hazır şiiri beğenmeyen

Beni sevmeyen

Adı sultan

Seviyorum seni dünyalar kadar

Sana kar bana zarar

Bir dostum var

Adı sultan', 'Hatırladım onu sunurdan Ta istanbuldan Birini tanıyorum  Adı sultan Kendini şair sanan Şiir yazan zaman zaman Birini seviyorum  Adı sultan H...', ARRAY['Türk Edebiyatı','Şiir','Yasin Çağlar']::text[], 8.5, '{"poet":"Yasin Çağlar","poet_slug":"yasin-caglar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sultan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Gözlüm', 'guzel-gozlum-fevzi-tokbas-dveig', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir    Temmuz  akşamıydı   tanıştık  seninle,

İçim   bir  tuhaf    oldu   o  tatlı    sohbetinle,

Gönül  dağımı  feşettin   büyülü  gözlerinle,

Kalbimden   vurdun    beni   güzel   gözlüm !....

Her   bakışın    kalbime   ayrı    bir  darbe,

Gönlüm    ne   zamandır,   zaten    harabe, 

Yaşam    verdin    bu   yıkık,    ölü     kalbe, 

Kalbimden   vurdun   beni   güzel  gözlüm!....

Kalbim   unutmuştu   sevginin  sıcaklığını,

Seninle  öğrendim   yaşamanın   anlamını,

Dünyalara  değişmem   tatlı  bir  bakışını,

Kalbimden   vurdun  beni   güzel  gözlüm!....', 'Bir    Temmuz  akşamıydı   tanıştık  seninle, İçim   bir  tuhaf    oldu   o  tatlı    sohbetinle, Gönül  dağımı  feşettin   büyülü  gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Tokbaş']::text[], 8.5, '{"poet":"Fevzi Tokbaş","poet_slug":"fevzi-tokbas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guzel-gozlum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deney', 'deney-selcuk-coskun-jqh79', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor şehrime,

Yollar yıkanmış, çatılar parlıyor. 

Herkes bir saçak altına sıvışıyor,

Ben cadde ortasında, 

damlacıkların şarkısını dinliyorum.

Şimşekte çakıyor toprakananın böğrüne aydınlığıyla...

Müjdeci bu yağmurlar, bahar geldi! 

Hissediyorum...

(19.04.00-ANKARA )', 'Yağmur yağıyor şehrime, Yollar yıkanmış, çatılar parlıyor.  Herkes bir saçak altına sıvışıyor, Ben cadde ortasında,  damlacıkların şarkısını...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/deney-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ciglik', 'ciglik-selcuk-coskun-egj5s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kelimeler, kelimeler;

Ne boş şeylermiş meğerse...

Yaşadıklarım gereksizmiş,

Seçmesini bilmediniz,

Geldiniz, konuştunuz, 

hiç dinlemediniz, hep öldünüz...

(06.04.00-ANKARA )', 'Kelimeler, kelimeler; Ne boş şeylermiş meğerse... Yaşadıklarım gereksizmiş, Seçmesini bilmediniz, Geldiniz, konuştunuz,  hiç dinlemediniz, h...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ciglik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanç', 'utanc-selcuk-coskun-79j69', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Siz seçtiniz günü ve bitimini,

Kim gelin dedi yanıma!

Payım yok ki sofranızdan, 

Anlayacak mısınız ki düşlerimi?

Duvarın arkasındasınız, 

nasıl bakacaksınız yüzüme...

( 16.04.00-ANKARA)', 'Siz seçtiniz günü ve bitimini, Kim gelin dedi yanıma! Payım yok ki sofranızdan,  Anlayacak mısınız ki düşlerimi? Duvarın arkasındasınız,  na...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/utanc-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satılık Düşler', 'satilik-dusler-selcuk-coskun-ueepu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Katillerimin yüzüne bakıyorum,

gözlerinde ölüm.

Ve o an anlıyorum bozuk paraymış hayallerim, 

gelişi güzel harcanan.

Dost da değilmiş sevdiklerim.

Şimdi tek başınayım yarattığım dehlizlerde.

Gelip geçenlere bakıyorum, gönül defterimden,

Yüzleri, isimleri silinmiş.

Azrail''in tırpanı;

çoktan bilenmiş...

( 16.04.00-ANKARA)', 'Katillerimin yüzüne bakıyorum, gözlerinde ölüm. Ve o an anlıyorum bozuk paraymış hayallerim,  gelişi güzel harcanan. Dost da değilmiş sevdik...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/satilik-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ismarladığım Ölüm', 'ismarladigim-olum-selcuk-coskun-cd25a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Derdim tek değil;

Onu ben tek yapıyorum belki de.

Gönül verilecek şey değil kadınlar,

Biliyorum.

Aşık oluyorum da sonra,

Umarsız, yalın düşler kuruyorum.

Tam anlattım, anladı sanıyorum,

Gidiyor, gidecek, bitecekler,

Bilmiyorum;

Gömütlerinde bana ne zaman yer seçecekler...

( 16.04.00-ANKARA)', 'Derdim tek değil; Onu ben tek yapıyorum belki de. Gönül verilecek şey değil kadınlar, Biliyorum. Aşık oluyorum da sonra, Umarsız, yalın düşl...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ismarladigim-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklambaç', 'saklambac-selcuk-coskun-u0o5x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saklambaç oynuyorum kendimle,

Saklanan hep korkak yanım...

Öyle bir gizlenmişim ki bulana aşk olsun;

İçimde ki beni...

( 09.04.00-ANKARA)', 'Saklambaç oynuyorum kendimle, Saklanan hep korkak yanım... Öyle bir gizlenmişim ki bulana aşk olsun; İçimde ki beni... ( 09.04.00-ANKARA)...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/saklambac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adora', 'adora-selcuk-coskun-s37hk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yılan çöreklenmiş gözlerinin içine,

Hem de tam bebeğine.

Akrep beslermişsin hep koynunda, kendi beben gibi.

Sığırtmaçmış sevgilin sonra; 

at sırtında, elinde şaklayan kamçı...

Hiç kavuşmamışsınız da.

Onu götürmüşler harbe,

Senide vermişler bir haramiye.

( 08.04.00-ANKARA)', 'Yılan çöreklenmiş gözlerinin içine, Hem de tam bebeğine. Akrep beslermişsin hep koynunda, kendi beben gibi. Sığırtmaçmış sevgilin sonra;  at...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/adora-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman', 'pisman-selcuk-coskun-rx6k2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnız ben gördüm !

Şahit de tuttular hiç istemeden.

Sordular, söyledim.

Sustular söyledim.

Yeter dediler, yetinmediler.

Git dediler, neden dedim.

Bitti dediler, yeni başlıyor dedim.

		08.04.00

		ANKARA', 'Yalnız ben gördüm ! Şahit de tuttular hiç istemeden. Sordular, söyledim. Sustular söyledim. Yeter dediler, yetinmediler. Git dediler, neden ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/pisman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız Kaydığında Dilediğim Dilekler', 'yildiz-kaydiginda-diledigim-dilekler-selcuk-coskun-ul9z4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalk gidelim ! 

durulmaz artık.

Bırak vursunlar,

Gocunmayalım, vursunlar.

Bırak yenildik sansınlar.

Kalk uçalım !

Kanatsız, bir defalığına.

Bırak gülsünler ardımızdan.

Bırak öldük sansınlar.

Yo otur konuşalım !

Yarenlerin dostluğu hatırına.

Bırak sustuk, sindik sansınlar...

08.04.00

ANKARA', 'Kalk gidelim !  durulmaz artık. Bırak vursunlar, Gocunmayalım, vursunlar. Bırak yenildik sansınlar. Kalk uçalım ! Kanatsız, bir defalığına. ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yildiz-kaydiginda-diledigim-dilekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik Kadınlarım', 'yitik-kadinlarim-selcuk-coskun-c40y7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'YİTİK KADINLARIM

Ağladım ve hep ağlayacağım,

Benden kopup gidenlere...

Verdiklerime hiç üzülmedim hayır.

Yitikliğim alamadıklarımdı sizden.

Oysa vahşi hayvanlar gibi, 

taze et değildi istediğim.

Hep onu sürdünüz önüme; 

iyi pişmemiş bir yemek gibi.

Oysa ne çok istedim; 

sizin duruşlarınızı çözmek, 

karşınızda değil içinizde...

Hep içinizden size baktım, 

görmediniz ki...

			05.04.00

			ANKARA', 'YİTİK KADINLARIM Ağladım ve hep ağlayacağım, Benden kopup gidenlere... Verdiklerime hiç üzülmedim hayır. Yitikliğim alamadıklarımdı sizden. ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yitik-kadinlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kinim Yok ki!', 'kinim-yok-ki-selcuk-coskun-8fz6v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beklemeyin beni gelmeyeceğim!

Yükümü çoktan sırtıma vurdum,

Ve çıkınım kuru ekmek, su...

Yetineceğim.

Sormayın; cevap vermeyeceğim!

Bir ben bilirim gittiğim yolu.

Ve ben tanırım, beni çepeçevre saran

Eli, kolu.

Boşuna vurmayın; ölmeyeceğim.

Kinimi çoktan kustum denize.

Ve bir ben yelken açarım,

İçinizde ki sevginize...

		02.04.00

		ANKARA', 'Beklemeyin beni gelmeyeceğim! Yükümü çoktan sırtıma vurdum, Ve çıkınım kuru ekmek, su... Yetineceğim. Sormayın; cevap vermeyeceğim! Bir ben ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kinim-yok-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk Hırsızları', 'cocuk-hirsizlari-selcuk-coskun-myv20', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her sabah inip çıktığım yokuş,

Ve sevdiğim köpek yavruları,

Şimdi sadece bir anı eski şehrimden.

Tuhaf ! insan nasıl da özlüyor,

Yitip gittiği varoşları.

Orada; 

at arabasının üstünde, 

bağıran satıcı; 

o günlere taşıyor çocuk tarafımı.

Koşup, 

arkasına takılmak arabanın,

Belimde tahta kılıç. 

Ve elimde mukavva kalkanım. 

Oysa,

şimdi çocukluğumu çalıyorlar,

sadece silah veriyorlar. 

Yalan savaşlarda öleyim diye,

Onların uğruna...

		02.04.00

		ANKARA', 'Her sabah inip çıktığım yokuş, Ve sevdiğim köpek yavruları, Şimdi sadece bir anı eski şehrimden. Tuhaf ! insan nasıl da özlüyor, Yitip gitti...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cocuk-hirsizlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşunlarınız Değmez Bana', 'kursunlariniz-degmez-bana-selcuk-coskun-cjyel', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dirilişim yakın!

Toprağı az kaldı deleceğim.

Sizin şaşkın bakışlarınıza aldırmadan,

Sevgi şarkıları haykıracağım,

Maskeli suratlarınıza.

Ve o zaman anlayacaksınız,

Kurşunlarınız değmez bana!

Belki o zaman gömeceksiniz silahlarınızı...

			02.04.00

			ANKARA', 'Dirilişim yakın! Toprağı az kaldı deleceğim. Sizin şaşkın bakışlarınıza aldırmadan, Sevgi şarkıları haykıracağım, Maskeli suratlarınıza. Ve ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kursunlariniz-degmez-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-selcuk-coskun-qewyf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eski resimlere bakıyorum çocukluğumdan kalan.

Bazısı siyah-beyaz, bazısı rengarenk.

Karadeniz''de bir kayıktayız;

Babam ve ben,

Elinde, ellerimizde misina...

Ben babamın hemen yanında, 

onun kopyası ve papağanı...

Ne yaparsa peşi sıra.

Dün gibi o siyah-beyaz fotoğraf.

Sevgim anlatılmaz bunlar boş laf...

		01.04.00

		ANKARA', 'Eski resimlere bakıyorum çocukluğumdan kalan. Bazısı siyah-beyaz, bazısı rengarenk. Karadeniz''de bir kayıktayız; Babam ve ben, Elinde, eller...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/babam-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizin Çocukları', 'denizin-cocuklari-selcuk-coskun-pirku', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hani bir limandan öbürüne koşturan,

Balıkçı tekneleri vardır ya !

İçinde; denizle gırtlak gırtlağa boğuşan

Balıkçılarıyla...

Sensiz kalınca bende onlara katıldım; 

takalarında tayfa misali.

Dolaştık Karadeniz''de;

Günlerce, haftalarca, aylarca ağlarımız bomboş !

Ama yinede mutluyduk çünkü;

Tuzlu suyla yıkardı yüzünü, 

Sabahları denizin çocukları..

             30.03.00

	ANKARA', 'Hani bir limandan öbürüne koşturan, Balıkçı tekneleri vardır ya ! İçinde; denizle gırtlak gırtlağa boğuşan Balıkçılarıyla... Sensiz kalınca ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/denizin-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayraç', 'ayrac-selcuk-coskun-kb06n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Korkmuyorum yengilerimden artık.

Sabrım, taşları çatlatır.

Gözlerim deniz mavisi değil biliyorum.

Ama içinde dalgalar köpürür.

Sana bakıyorum ta içinden,

Görüyorum da sanrılarını ve utkunu.

Sormuyorum da gülüm, cevabını biliyorum.

Farkın yok senin de benden.

Ve bilmiyorum kim arındıracak bizi;

Kim kaldıracak sizi, bizi...

				

				

01.04.00

ANKARA', 'Korkmuyorum yengilerimden artık. Sabrım, taşları çatlatır. Gözlerim deniz mavisi değil biliyorum. Ama içinde dalgalar köpürür. Sana bakıyoru...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayrac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saf Bilirdim Hayallerini', 'saf-bilirdim-hayallerini-selcuk-coskun-vpzd7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eskidendi o kavga ve nefret.

Sen şimdi tek başınasın,

Bildiğim sanrıların dinmeyecek!

Doğan güneş hiç senin olmadı ki.

Ölesiye sevmedin ki hayatı, hayatımızı.

Hünerin hiç olmadı bir kelebek kadar;

Seni kaplayan zarı aşamadın ki.

Farkında da değilsin hiç benzeşmezsin

Olmak istediklerine...

Gelincik zannederdim seni,

Saf bilirdim hayallerini,

Ve ölürdüm de belki gülüşüne,

Boşunaymış, boşunaymış çırpınışlarım.

Benim yolum köy yolu, senin ki yoz bir şoseymiş.

		27.03.00

		ANKARA', 'Eskidendi o kavga ve nefret. Sen şimdi tek başınasın, Bildiğim sanrıların dinmeyecek! Doğan güneş hiç senin olmadı ki. Ölesiye sevmedin ki h...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/saf-bilirdim-hayallerini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemeye Başladım da Seni', 'ozlemeye-basladim-da-seni-selcuk-coskun-ofsne', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ÖZLEMEYE BAŞLADIM DA SENİ

Günüm sensiz geçti,

Hem de senle...

Aklımdan çıkmıyorsun ki!

Çiçekçilerin önünden geçiyorum Sakarya''da sen geliyorsun aklıma.

Biliyorum da kentimdesin.

Duraklara, geçen otobüslere bakıyorum;

İçinde misin?

Elim telefona gidiyor, vazgeçiyorum.

Oysa sesini duymaya o kadar ihtiyacım var da, cesaretim yok.

Hem ne söylenir ki tellerin içinden.

Eve varıyorum şiir yazıyorum işte bu kadar...

				30.03.00

				ANKARA', 'ÖZLEMEYE BAŞLADIM DA SENİ Günüm sensiz geçti, Hem de senle... Aklımdan çıkmıyorsun ki! Çiçekçilerin önünden geçiyorum Sakarya''da sen geliyor...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ozlemeye-basladim-da-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramak', 'aramak-selcuk-coskun-vgp9f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bahar da geldi sonunda kentime

Varoşlardan yükselen sesler uğuldar.

Ve kentin kumarbazları biraz daha rahat

Döner evlerine.

Bense dalların tomurcuklarının patlamasını beklerim.

Açmış çiçekleri düşlerim allı-morlu

Sevmekte isterim sonra...

Yollara söylerim şarkılarımı, senle geçip gittiğimiz.

Ve hayat çok tekdüze, baharda gelse bildiğimiz...

			26.03.00

			ANKARA', 'Bahar da geldi sonunda kentime Varoşlardan yükselen sesler uğuldar. Ve kentin kumarbazları biraz daha rahat Döner evlerine. Bense dalların t...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/aramak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolum', 'anadolum-selcuk-coskun-8o084', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ANADOLUM

Arabaların üstü saman yüklü,

Samanın üstünde köy kızları,

Al, mor, sarı yazmaları.

Yolun iki yanı başak ve günebakan

Yağız delikanlılar harmanda ellerinde tırpan.

Bilmezsiniz siz nasıl yakar insanı 

Ağustos sıcağında harman.

				27.03.00

				ANKARA', 'ANADOLUM Arabaların üstü saman yüklü, Samanın üstünde köy kızları, Al, mor, sarı yazmaları. Yolun iki yanı başak ve günebakan Yağız delikanl...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/anadolum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum Bu da Gelecek Başıma', 'biliyorum-bu-da-gelecek-basima-selcuk-coskun-mwr4m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni bekliyorum,

Kentinde, ümitsiz çırpınışlardayken,

Biliyorum gözlerin buğulu,

Kucağında, siyah-beyaz kedin,

Biliyorum benden iyi huylu.

Uyumuyorum sensiz gecelere ve uyanmıyorum güne.

Kınamıyorum da insanlarımı 

Ve artık korkmuyorum da 

Yabanıl kabuslarımdan.

Sadece bekliyorum.

Biliyorum çok yakın.

Biliyorum,

Buda gelecek başıma çok yakın...

		19.03.00

		ANKARA', 'Seni bekliyorum, Kentinde, ümitsiz çırpınışlardayken, Biliyorum gözlerin buğulu, Kucağında, siyah-beyaz kedin, Biliyorum benden iyi huylu. U...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/biliyorum-bu-da-gelecek-basima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek Açtı Bahçemde', 'cicek-acti-bahcemde-selcuk-coskun-a4ciy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Durup arkasına bakanlardan değilim,

Seslenmelerinize kulak asayım.

Neler gördü gözlerim bilemezsiniz.

Anlattıklarım düş gelir size.

Ve çiçeklerim her bahar yeniden açar,

Her bahar ayrı renk...

Ne karanfil ne de gül,

Açan bahçemde;

Kızıl Gelincik...		

                  19.03.00

	ANKARA', 'Durup arkasına bakanlardan değilim, Seslenmelerinize kulak asayım. Neler gördü gözlerim bilemezsiniz. Anlattıklarım düş gelir size. Ve çiçek...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cicek-acti-bahcemde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Yazmadınız Hayatımı', 'siz-yazmadiniz-hayatimi-selcuk-coskun-sj7ab', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kurallar koymayın önüme, uymam ki,

Yalanlarla avutmayın beni, kanmam ki,

Silah vermeyin elime, öldürmem ki,

Barış isterim, kardeşlik ve sevgi

Sabırsızım, kızgınım karşımda duruşlarınıza

Kavgam yüzyılın başında ki 

gibi yılmam ki,

sonra tek de değilim dünyamda

kardeşlerim var her renkte; kırmızı, sarı beyaz, siyah.     

Her diyarda ve her dilde...

		17.03.00

		ANKARA', 'Kurallar koymayın önüme, uymam ki, Yalanlarla avutmayın beni, kanmam ki, Silah vermeyin elime, öldürmem ki, Barış isterim, kardeşlik ve sevg...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/siz-yazmadiniz-hayatimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Endişe', 'endise-selcuk-coskun-86znx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geçtiğim sokaklar eskiydiler.

Salaş dükkanların kapılarında yaşlı esnaflar.

Ve çınarların gölgesinde, ağustos sıcağında;

Nargile içip, tavla oynayanlar.

Sol yanımda lacivert, hırçın Karadeniz''im.

Hayır siz bilmezsiniz.

HAYIR, SİZ BİLMEZSİNİZ..!

Siz düşünmezsiniz, denize dalıp...

Kardeşlik, eşitlik, barış istemezsiniz.

Durup durunken...

Hayır siz öfkelenmezsiniz bu gidişe,

İşte beni yiyip bitiren endişe...

		4.03.00

		ANKARA', 'Geçtiğim sokaklar eskiydiler. Salaş dükkanların kapılarında yaşlı esnaflar. Ve çınarların gölgesinde, ağustos sıcağında; Nargile içip, tavla...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/endise-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maça Ası', 'maca-asi-selcuk-coskun-jvr74', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kartlarım elimde hep 

Ve ben tabi ki joker

Gömlek cebimde maça ası

Hayır güzelim ben başlatmadım

Bu savaşı ve tutulan yası

Evet sen istersin bir araba,

Birde pembe panjurlu ev

Bense sadece özgürlük...

	04.02.00

	ANKARA', 'Kartlarım elimde hep  Ve ben tabi ki joker Gömlek cebimde maça ası Hayır güzelim ben başlatmadım Bu savaşı ve tutulan yası Evet sen istersin...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/maca-asi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otuz', 'otuz-selcuk-coskun-rctlm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kan dolar gözlerime,

sabahın esininde.

Yönümü yitirdiğimde;

Kuzeyi, denizimin

Martıları gösterir.

Ve gelincik gibidir

Kadınlarım kızıl saçlı,

Kızıl yürekli...

Düşüm çoktur özgürlük adına

Kavgam tek...

			

                04.02.00

	ANKARA', 'Kan dolar gözlerime, sabahın esininde. Yönümü yitirdiğimde; Kuzeyi, denizimin Martıları gösterir. Ve gelincik gibidir Kadınlarım kızıl saçlı...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/otuz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'olsun-be', 'olsun-be-selcuk-coskun-wuw80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şarkılar söyleyeceğim sana,

Hiç duymadığın.

Masallar anlatacağım;

Rüyalarımda yaşadığım.

Gün gelecek; 

gideceğim!

Yolunu, izini bilmediğim,

Mesut diyarlara göçeceğim.

Aklımda sen. 

Belki de hiç söylemeden, 

sevdiğimi seni,

Öleceğim.

Olsun !

Olsun be güzelim...

								    10.09.1999

	   ANKARA', 'Şarkılar söyleyeceğim sana, Hiç duymadığın. Masallar anlatacağım; Rüyalarımda yaşadığım. Gün gelecek;  gideceğim! Yolunu, izini bilmediğim, ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olsun-be-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceyarısı', 'geceyarisi-selcuk-coskun-x5vwh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine yalnız dönüyoruz eve;

Ne yapalım yollar ayrı.

Esat caddesinden kendimi salmışım,

Sigara parmaklarımı yakıyor.

Bitmiş efkardan.

Farkında değilim saatin.

Bir ben varım caddede, 

Bir de polis amcalar.

Onlar suçlu arar.

Ben aşkımı. 

				

                 10.09.199

   	ANKARA', 'Yine yalnız dönüyoruz eve; Ne yapalım yollar ayrı. Esat caddesinden kendimi salmışım, Sigara parmaklarımı yakıyor. Bitmiş efkardan. Farkında...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/geceyarisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Bu Değil mi?', 'ask-bu-degil-mi-selcuk-coskun-aempv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çınarları düşlüyorum;

Dalları gövdem kadar.

Ve senin ellerin ellerimde...

Yollar, denizler, 

Kent bizim.

Gözlerinin içinde aşkım.

Düşler görüyorum sana dair;

Hep iyiye yorduğum.

Korktuğum;

Bir gün çekip gitmen.

Söylesene;

Aşk bu değil mi? 

	11.09.1999

  	ANKARA', 'Çınarları düşlüyorum; Dalları gövdem kadar. Ve senin ellerin ellerimde... Yollar, denizler,  Kent bizim. Gözlerinin içinde aşkım. Düşler gör...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ask-bu-degil-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-selcuk-coskun-vk1if', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Evet !

Doğum günüm bu gün.

Sen yanımda;

Sen gözlerimin içinde gülücük.

Ben bayram çocuğu;

Şımarmış ve haylaz yanında.

Nazlı ellerin dokunduğunda;

Aşkın mideme saplanan ağrılar.

Evet !

Doğum günüm bu gün.

Sen aklımda;

Sen gözlerimin içinde gülücük...

	15.09.1999

	ANKARA', 'Evet ! Doğum günüm bu gün. Sen yanımda; Sen gözlerimin içinde gülücük. Ben bayram çocuğu; Şımarmış ve haylaz yanında. Nazlı ellerin dokunduğ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bugun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulu', 'bulu-selcuk-coskun-2npef', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben seçmedim seni,

hiç aklımda da değildin.

İlkin rüyalarda görmeye başladım;

Seni yıllar önce, hiç tanımadan.

Saçındaki papatyalara aşkım; 

o zamanlardan. 

Ve işte karşımdasın;

İsmin dudaklarımda...

Aşkın dilimin ucunda.

Korkum;

Seni yitirmek bulmuşken.

       17.09.1999

      ANKARA', 'Ben seçmedim seni, hiç aklımda da değildin. İlkin rüyalarda görmeye başladım; Seni yıllar önce, hiç tanımadan. Saçındaki papatyalara aşkım; ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollarıma Çıkan', 'yollarima-cikan-selcuk-coskun-xddn4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yükselden geçiyorum.

Ağaçları rengârenk olmuş;

Sonbahar bu!

Yapraklar allı, sarılı ayaklarımın altında hışırdıyor.

Şarkılar çalıyor gitarında,

Yeni yetme bir genç.

Aklıma düşüyorsun.

Çay çekiyor canım Sakarya’da...

Yolları bitiriyorum.

Akşam oluyor, evin yolu görünmekte.

Usumda;

evde Sen.

Ne desem bilmiyorum.

							20.09.1999

	ANKARA', 'Yükselden geçiyorum. Ağaçları rengârenk olmuş; Sonbahar bu! Yapraklar allı, sarılı ayaklarımın altında hışırdıyor. Şarkılar çalıyor gitarınd...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yollarima-cikan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'gercek', 'gercek-selcuk-coskun-jncf1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kısır döngüler aramaktan bıkan,

yollar gitmiş seyyah gibiysem 

kime ne! 

Ben seçtim hayatımı!

Ve bitiren de ben tabi...

Yaşarken ölmek çok kolay.

Zor olan sevmek.

Aşkı ben icat etmedim,

Doğam bu.

Güneş nasıl sıcaksa, Sen nasıl dişiysen.

Gerçek bu,

Hayat bu,

Aşk bu...

	20.09.1999

	ANKARA', 'Kısır döngüler aramaktan bıkan, yollar gitmiş seyyah gibiysem  kime ne!  Ben seçtim hayatımı! Ve bitiren de ben tabi... Yaşarken ölmek çok k...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gercek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Gelse ve Sen Gülsen', 'bahar-gelse-ve-sen-gulsen-selcuk-coskun-86r2i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu baharda açar mı çiçekler.

Yoksa boşuna mı tohumun savaşı

Ve Seni görür müyüm 

Nisan güneşinde, sabah, sabah

Bekler misin beni hiç nedensiz.

Sever misin korkusuz...

Özler misin hiçbir şey beklemeden.

Ölürsün belki de benim gibi...

Soluk alırken.

Aşkından...  

	26.09.1999

	ANKARA', 'Bu baharda açar mı çiçekler. Yoksa boşuna mı tohumun savaşı Ve Seni görür müyüm  Nisan güneşinde, sabah, sabah Bekler misin beni hiç nedensi...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bahar-gelse-ve-sen-gulsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müzik, Sen ve Yine O Bar', 'muzik-sen-ve-yine-o-bar-selcuk-coskun-euwdu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zor yarını beklemek.

Zamanın tıkırtıları beynimi yiyor; 

Daralmışım.

Geçti be bizden, 

yarın korkusu içimizde...

Seviler hep yarım yamalak.

Özlediğin yanında;

yüzler farklı suratları aramakta...

O müdavim barda,

Hovarda çalıyor gitarda...

Benim içimde bir sıkıntı;

Kadehten alıyorum hırsımı

Karşımda;

Apaçık gönlümün hırsızı...

Ve yan masada bir adam paylıyor aldatan karısını...

    								              29.09.1999

		ANKARA', 'Zor yarını beklemek. Zamanın tıkırtıları beynimi yiyor;  Daralmışım. Geçti be bizden,  yarın korkusu içimizde... Seviler hep yarım yamalak. ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/muzik-sen-ve-yine-o-bar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Denizin Düşü de Görülmeli', 'gece-denizin-dusu-de-gorulmeli-selcuk-coskun-qcyk3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Küçükken hiç korkmazdım uçurumlardan.

Oysa hayatım şimdi,

o kenarlarda dolaşıyor.

Hayaller uçtu uçacak,

korkuyorum yarim gitti gidecek ellere...

Rüyalarımda denizde görmüyorum;

İyiye yorduğu falcıların.

Kan kırmızı tarlalar,

karanlıklar geçiyorum kabuslarımda...

Bilmediğim, duymadığım savaşlarda ölüyorum, 

her gece...

Sayıklıyormuşum, kardeşim söylüyor;

o da çözememiş haykırdığım sözler nece...

		29.09.1999

 		ANKARA', 'Küçükken hiç korkmazdım uçurumlardan. Oysa hayatım şimdi, o kenarlarda dolaşıyor. Hayaller uçtu uçacak, korkuyorum yarim gitti gidecek eller...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gece-denizin-dusu-de-gorulmeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz''in Bakılçısıyım Ben.', 'karadeniz-in-bakilcisiyim-ben-selcuk-coskun-ixht0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağ atılır bu saatlerde benim denizime,

Rast gele denip.

Ardından nazlı yarin gelişi gibi beklenir ağlardaki nafaka.

Sabahın ayazında bir kuru çayla kahvaltı edilir.

Çapa atılır;

Gözlerde umutla, 

patalya çözülür anasından.

Takada tayfalar, babalar, oğullar.

Patalyada uşaklar; 

aşkından ıslık çalan.

Ağlar çekilir bu saatlerde benim denizimde.

				

                                 29.09.1999

		ANKARA', 'Ağ atılır bu saatlerde benim denizime, Rast gele denip. Ardından nazlı yarin gelişi gibi beklenir ağlardaki nafaka. Sabahın ayazında bir kur...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karadeniz-in-bakilcisiyim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Iovana Iovanka (Balkanlar)', 'iovana-iovanka-balkanlar-selcuk-coskun-b0hrn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Pikapta Iovano Iovanka çalıyor

Kadehim boşalmış,

Balkanlara geldiğim yerlere ağlıyorum; ve bir de aşkıma,

Sana...

Biliyorum bu gecede 

Ben mum misali az kaldı 

Bitecek...

Pikapta Iovano,Ivanka çalıyor

Kadehim boşalmış,

Seninle olduğum yarınları düşlüyorum.

gitar çalıyorum uzaktan Sana 

biliyorum bu şarkıda bitecek...

								29.09.1999

	ANKARA', 'Pikapta Iovano Iovanka çalıyor Kadehim boşalmış, Balkanlara geldiğim yerlere ağlıyorum; ve bir de aşkıma, Sana... Biliyorum bu gecede  Ben m...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/iovana-iovanka-balkanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Yoksa', 'sevgi-yoksa-muhtalip-turkmen-g0y5v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uykumun kaçtığı uzun geceler,

Seni özlediğim zamanlardadır.

Gün gelir de ayrı kalırsak eğer,

Aklım burda olsa gönlüm ordadır.

Duymadım görmedim sen gibisini

Anlatmak imkansız güzelliğini,

Söyleme istersen geleceğini,

Ben seni bulurum gözüm yoldadır.

Ne olur hep burda yanımda olsan,

Yatsan da başını dizime koysan,

Aşkı mutluluğu benimle bulsan,

Benim gönlüm zaten sevdalardadır.

Yaşadıkça sevdan beni bırakmaz, 

Seni sevdiğimi saklasam olmaz,

Cennet hurileri yerini tutmaz,

Kokan karanfilde tadın baldadır.

Sevmek ne günahtır ne de bir hata,

Sevgi yoksa giremeyiz cennete,

Öyle bir cansın sen canımdan öte,

İkimizin gönlü aynı haldedir.', 'Uykumun kaçtığı uzun geceler, Seni özlediğim zamanlardadır. Gün gelir de ayrı kalırsak eğer, Aklım burda olsa gönlüm ordadır. Duymadım görme...', ARRAY['Türk Edebiyatı','Şiir','Muhtalip Türkmen']::text[], 8.5, '{"poet":"Muhtalip Türkmen","poet_slug":"muhtalip-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevgi-yoksa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Duyamadın', 'sen-duyamadin-muhtalip-turkmen-rxji0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözümde hurisin gönlümde melek,

Cesaret edipte söyleyemedim,

Yanlış anlar küstürürüm diyerek,

Bir öpücük bile isteyemedim.

Gönlüm yandı yandı kül bağlamadı,

Bence böyle sevgi hiç yaşanmadı,

Artık ne tahammül,ne sabır kaldı,

Sarılıp öpmeyi deneyemedim.

Sen çıkana kadar benim karşıma ,

Böyle bir şey gelmemişti başıma,

Öyle sevdim seni gittin hoşuma,

Bir gonca gül idin koklayamadım.

Binbir hayal kurdum hepsi seninle,

Derin uykularda sen düşlerimde,

Gözlerime baksan olsan benimle,

Sohbetin tatlıydı ben doyamdım.

Bak yaratan en çok sana özenmiş,

Gözlerin has bahçe koynun cenntmiş,

Gülümsemen seviyorum demekmiş,

Kusuruma bakma anlayamadım.

Özlemim artıyor  her geçen günde,

Gelmeye hazırdım istediğinde,

Yüzüme baktığın her saniyede,

Kalbim feryat etti sen duyamadın.', 'Gözümde hurisin gönlümde melek, Cesaret edipte söyleyemedim, Yanlış anlar küstürürüm diyerek, Bir öpücük bile isteyemedim. Gönlüm yandı yand...', ARRAY['Türk Edebiyatı','Şiir','Muhtalip Türkmen']::text[], 8.5, '{"poet":"Muhtalip Türkmen","poet_slug":"muhtalip-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sen-duyamadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yapacaksın?', 'ne-yapacaksin-muhtalip-turkmen-3iu0x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevem desem nazlanırsın bilirim,

Söyle bu güzelliği ne yapacaksın?

Yıllar yılı ben arzunu çekerim,

Söyle bu güzelliği ne yapacaksın?

Yıllarca bu gönlüm özlemle doldu', 'Sevem desem nazlanırsın bilirim, Söyle bu güzelliği ne yapacaksın? Yıllar yılı ben arzunu çekerim, Söyle bu güzelliği ne yapacaksın? Yıllarc...', ARRAY['Türk Edebiyatı','Şiir','Muhtalip Türkmen']::text[], 8.5, '{"poet":"Muhtalip Türkmen","poet_slug":"muhtalip-turkmen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ne-yapacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Yeniden Aşk', 've-yeniden-ask-selcuk-coskun-vt5ok', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Denizimin üzerinde uçan;

Martılarımı çaldılar 

benden önce...

bozkıra attılar daha aklım ermezken.

Bildik yalan masallarla avuttular.

Ama aşkı kendim öğrendim kitaplarımdan ne olduğunu yaşamadan.

Kimi zaman hayali kadınları sevdim, Hiç görmeden.

Sonra güzel kadınlarım da oldu; içleri çirkin, çürümüş.

Ve çirkin kadınlarımda oldu;

İçleri cennet kadar, ananım yüreği kadar güzel ve temiz.

Ve yeniden aşk;

Sen oldun Sen...

	12.10.1999 

 	ANKARA', 'Denizimin üzerinde uçan; Martılarımı çaldılar  benden önce... bozkıra attılar daha aklım ermezken. Bildik yalan masallarla avuttular. Ama aş...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ve-yeniden-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müziğimiz Aşktır', 'muzigimiz-asktir-selcuk-coskun-rb1te', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Akordeon çalıyordu Dinleyeni de yoktu.

Aşıktı belki de ümitsizce.

Gitarımı kaptım gittim yanına.

Selam bile vermedik.

Çaldığım ilk akor merhaba.

Ve ilk yolculuk tabi ki balkanlara...

Alaycı bir gülücük fırlattık yanımızdan kalkanlara.

Sabaha kadar çaldık,

Masada kadeh,

Kadeh de şarap ve aşkımız.

O gece hiç kanmadık yalanlara...

								    02.10.1999

	   ANKARA', 'Akordeon çalıyordu Dinleyeni de yoktu. Aşıktı belki de ümitsizce. Gitarımı kaptım gittim yanına. Selam bile vermedik. Çaldığım ilk akor merh...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/muzigimiz-asktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakın', 'yakin-selcuk-coskun-lvmon', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cevaplara aç çocuklar,

Usumda çöreklenmişler.

Ha babam sorarlar;

Ne zaman, ne zaman?

Cevabım basma kalıp;

Yakında...

Dağda gezinen yabanıl hayvanlar kadar,

Vahşi ve özgür bırakırım

Yitik düşlerimi,

Ve hep aklıma Sen ve gözlerin gelir;

Akşamında Ankara’nın. 

		15.10.1999

		ANKARA', 'Cevaplara aç çocuklar, Usumda çöreklenmişler. Ha babam sorarlar; Ne zaman, ne zaman? Cevabım basma kalıp; Yakında... Dağda gezinen yabanıl h...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin', 'sensin-selcuk-coskun-ftmwo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir istasyon;

Sabahın körü belki de !

İnsanlar yarı sarhoş,

Gözler raylarda...

Gidilecek yol aynı.

Benim beklediğim;

Değil varılacak menzil.

Benim özlediğim;

Değil aş yada nafakam.

Benim aradığım;

Sensin,

Sensin,

SENSİN !

	17.10.1999

	ANKARA', 'Bir istasyon; Sabahın körü belki de ! İnsanlar yarı sarhoş, Gözler raylarda... Gidilecek yol aynı. Benim beklediğim; Değil varılacak menzil....', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sensin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkından', 'askindan-selcuk-coskun-yu4ut', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana aldığım mor çiçekler;

Solmazlar!

Onlar aşkından...

Kış geldiyse ne olmuş.

Yollarda çamur varmış,

Soğukmuş hava olsun!

Sen varsın ya kentimde...

Baharsın ya gönlümde...

İnadına severim ya yokluğunu.

Mumlar yakarım ya gözlerinin ışığına...

Korkarım, çocukça ve delice

İçimi de dökemem Sana;

Şiir yazarım ya.

Yazdıklarım saklı;

Kaybolmaz, bir gün okursun;

Onlar aşkından...

	17.10.1999

	ANKARA', 'Sana aldığım mor çiçekler; Solmazlar! Onlar aşkından... Kış geldiyse ne olmuş. Yollarda çamur varmış, Soğukmuş hava olsun! Sen varsın ya ken...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/askindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğrenen', 'ogrenen-selcuk-coskun-bve0a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nazım’ dan öğrendim;

Memleket için,

İnsanlar için,

Aşk için, Senin için

Yanmayı...

Ve uzaktan sevmeyi,

Sılanın yollar ardında

Olmadığını, içimde olduğunu.

Nazım’ dan öğrendim; 

Memleket için,

İnsanlar için,

Aşk için, Senin için

Yaşarken ölmeyi...

		17.10.1999

		ANKARA', 'Nazım’ dan öğrendim; Memleket için, İnsanlar için, Aşk için, Senin için Yanmayı... Ve uzaktan sevmeyi, Sılanın yollar ardında Olmadığını, iç...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ogrenen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiraz Çiçeği', 'kiraz-cicegi-selcuk-coskun-fp420', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kulak kesilmiş iblisler

İçinden geçtim düşümde;

Ellerinde günahlarım koz.

Yoz bir hayat sürmedim hayır!

Utkularım hep aynıydılar.

Hani derler ya!

Sevgiden bir dünya;

Benim beynimde fidanları...

Ve Sen açtın;

yazında utkumun

Erkenci Kiraz çiçeği.

								21.10.1999

	ANKARA', 'Kulak kesilmiş iblisler İçinden geçtim düşümde; Ellerinde günahlarım koz. Yoz bir hayat sürmedim hayır! Utkularım hep aynıydılar. Hani derle...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kiraz-cicegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoluma Çıkanlar', 'yoluma-cikanlar-selcuk-coskun-l9onr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yol gittim,

Yayan, omuzum yüklü.

Kerpiçten evler arasından geçtim.

Arnavut kaldırımları da oldu 

Ayaklarımın altında,

Memleketimden hediye.

Açan çuha çiçekleri de oldu

Çamların dibi sıra;

Sarı, mor ve beyaz.

Leylek te gördüm havada...

Bunlar değildi aradığım.

Hayır bunlar değildi özlediğim.

		21.10.1999

		ANKARA', 'Bir yol gittim, Yayan, omuzum yüklü. Kerpiçten evler arasından geçtim. Arnavut kaldırımları da oldu  Ayaklarımın altında, Memleketimden hedi...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yoluma-cikanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış Ayrılığı', 'kis-ayriligi-selcuk-coskun-i4570', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kuzeye bakar güneş

Yollar;

beyaz, soğuk yüreklerle dolu.

Sular katı, akmaz ovalarda...

Kanımı donduran; hayır, hayır soğuk değil ayrılık...

Yarin dudağındaki tebessümü görememek,

Doyasıya sarılamamak özlediğinde.

Kanımı kaynatan; hayır,

hayır bahar değil

Sensin sevdiğim.

Bahardan önce gönlümde açan gelinciğim.

			29.01.1998

			ANKARA', 'Kuzeye bakar güneş Yollar; beyaz, soğuk yüreklerle dolu. Sular katı, akmaz ovalarda... Kanımı donduran; hayır, hayır soğuk değil ayrılık... ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kis-ayriligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nar', 'nar-selcuk-coskun-761yz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Narın dallarına dokundum ilkin.

Sarı, turunç ve al-al oldu ellerim.

Sonra utandım ama az...

Narın yavrusunu yemiştim.

Yarin tenine dokunduğun ilk an gibi,

Ellerim titredi, midem yandı...

Hamdı, tazeydi, gün görmemişti nar meyvesi.

Yarim gibi saftı sarı turunç al-aldı.

Uzakta biliyorum.

O kuytu bahçede,

Nar ağacım.

Yarimin bahçesinde...

		29.01.1998

		ANKARA', 'Narın dallarına dokundum ilkin. Sarı, turunç ve al-al oldu ellerim. Sonra utandım ama az... Narın yavrusunu yemiştim. Yarin tenine dokunduğu...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/nar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyunun Sonu', 'oyunun-sonu-selcuk-coskun-iwke8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cezalardan usanmış, şımarık çocuk oldum.

Monoton bu devinimler.

Kalktığım sabah, yattığım gece aynı.

Sevi yok dost yok.

Tanışlar sanki maskeli baloda.

Yaşadığım ömrüm riyakar.

Sırıtır sefilliğime sokak kedileri bile.

Şehrin keşmekeşinde dingindir bahçem.

Ama hiç, hiç açmaz çiçekler.

Günler sayılıdır hep; Ha geldi! Ha bitecek!

Bilirim; vaktidir, 

Uzak denizlerde ağlar çekilir.

Balıkçının tuzağı ve garip balığın canı,

Bilirim oyunun sonudur.

14.09.1997/ANKARA', 'Cezalardan usanmış, şımarık çocuk oldum. Monoton bu devinimler. Kalktığım sabah, yattığım gece aynı. Sevi yok dost yok. Tanışlar sanki maske...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/oyunun-sonu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yılgı', 'yilgi-selcuk-coskun-a0qgv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Büyüdüm;

Yarım asır olmuş.

Yenilgiler, savaşlar.

Ganimetler.

Ve yeni yenilgiler.

Yorulmuşum be sevdiklerim!

Bırakın gideyim uzaklara,

Unutun beni.

Kıskıvrak sarmış hayallerim.

Ah ulaşamadığım hayallerim.

Yorulmuşum,

Yenilmişim be sevdiklerim!

Sığınağım kalmamış,

Anlamazsınız.

Bu;

En büyük,

Ve en son yenilgi.

O da silmiş defterden

Yorulmuşum be sevdiklerim!

Bırakın gideyim uzaklara,

Unutun beni.

Unutun...

                 19.05.1999

	ANKARA', 'Büyüdüm; Yarım asır olmuş. Yenilgiler, savaşlar. Ganimetler. Ve yeni yenilgiler. Yorulmuşum be sevdiklerim! Bırakın gideyim uzaklara, Unutun...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yilgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olsam', 'olsam-selcuk-coskun-49crj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir fakir çiftçi olsam;

Kıt kanaat geçinen.

Tek derdi karnını doyuracağı

Bir tas aş ve

Yağmayan yağmur olan

Bir fakir çiftçi olsam.

			

	28.10.1996

	ANKARA', 'Bir fakir çiftçi olsam; Kıt kanaat geçinen. Tek derdi karnını doyuracağı Bir tas aş ve Yağmayan yağmur olan Bir fakir çiftçi olsam. 			 	28....', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/olsam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyemediğim', 'diyemedigim-selcuk-coskun-0t9ku', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Denizin kumunu eleyemezsin.

Suları bitmez,

Nehri sen içemezsin.

Ölçüsü yok ki sevginin,

Tartamazsın.

Öldürsen de 

Seni severim 

Anlayamazsın.

Unutursun.

Güneşe koşamaz,

Gözüme bakamazsın.

“Seni Seviyorum !” 

diyemezsin.

Durup dururken.

Utanırsın,

Kanarsın,

Yenilirsin...

	

	17.11.1996

	ANKARA', 'Denizin kumunu eleyemezsin. Suları bitmez, Nehri sen içemezsin. Ölçüsü yok ki sevginin, Tartamazsın. Öldürsen de  Seni severim  Anlayamazsın...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/diyemedigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuhaf', 'tuhaf-selcuk-coskun-swy4r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tuhaf değil mi?

Yağmurun baharda yağması,

Hayat vermesi.

Kedilerin aşk zamanını bilmesi,

Kurdun kuzuya,

İnsanın insana düşmanlığı.

Tuhaf değil mi?

Yarinin kuyunu kazması...

		23.05.1999

		ANKARA', 'Tuhaf değil mi? Yağmurun baharda yağması, Hayat vermesi. Kedilerin aşk zamanını bilmesi, Kurdun kuzuya, İnsanın insana düşmanlığı. Tuhaf değ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tuhaf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çingene', 'cingene-selcuk-coskun-hf2wd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çingene gönlüm,

Bağlasan durmaz.

Söylediğin,

Gösterdiğin limanlar

Yetmez.

Dört duvara sığmaz.

Başka ufukların 

Deli gönlüm

Kimse benle uçmaz.

“dünya bir tarla, çingeneler çiçektir.”

		16.10.1996

		ANKARA', 'Çingene gönlüm, Bağlasan durmaz. Söylediğin, Gösterdiğin limanlar Yetmez. Dört duvara sığmaz. Başka ufukların  Deli gönlüm Kimse benle uçmaz...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cingene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçin', 'i-cin-selcuk-coskun-6ky7o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep derim ya!

Senin için ölürüm.

Bilmezsin

Kim bilir kaç kere

Öldüm.

Kalbim durmadan,

Kanım donmadan

Ellerin ellerimdeyken

Ve yürürken.

	16.08.1996

	ANKARA', 'Hep derim ya! Senin için ölürüm. Bilmezsin Kim bilir kaç kere Öldüm. Kalbim durmadan, Kanım donmadan Ellerin ellerimdeyken Ve yürürken. 	16....', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-selcuk-coskun-jwlkn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hain bir baykuş olsam,

Gecelerde...

Pencerene konsam.

Çırılçıplak saflığında

Seni seyretsem,

Yatağında...

Sabah,

Uyandığında kaçsam,

Sezdirmeden.

Sessiz,

Saf hayallerle

Bir başka gecene uçsam.

16.07.1995

Ankara', 'Hain bir baykuş olsam, Gecelerde... Pencerene konsam. Çırılçıplak saflığında Seni seyretsem, Yatağında... Sabah, Uyandığında kaçsam, Sezdirm...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç', 'agac-selcuk-coskun-1liw0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Duru yağmur kokusuyla tanıdım,

Bahar ışıklarında gördüm yüzünü.

Kim bilir kaç,

Umarsız gece bekledim;

Sualsiz,

Koca bir ağaç gibi

Kış geldi,

Yapraklarımı dökmedim.

							               18.06.1995

ANKARA', 'Duru yağmur kokusuyla tanıdım, Bahar ışıklarında gördüm yüzünü. Kim bilir kaç, Umarsız gece bekledim; Sualsiz, Koca bir ağaç gibi Kış geldi,...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/agac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadar', 'kadar-selcuk-coskun-ts2uc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağladım.

Sabaha kadar

değil

Sen dönünceye 

kadar.

							05.06.1995

	ANKARA', 'Ağladım. Sabaha kadar değil Sen dönünceye  kadar. 							05.06.1995 	ANKARA...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kadar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönüş', 'donus-selcuk-coskun-g1e9b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biliyorsun

Güzde gideceğim.

Gelişim Sen, varışım yaz.

Zaman gardiyan.

Günleri sayma;

Geceleri say!

Sensiz,

Bensiz geçen geceleri...

Ayrılık bu bilirsin 

Çok yaman...

		05.06.1995

		ANKARA', 'Biliyorsun Güzde gideceğim. Gelişim Sen, varışım yaz. Zaman gardiyan. Günleri sayma; Geceleri say! Sensiz, Bensiz geçen geceleri... Ayrılık ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/donus-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baykuş', 'baykus-selcuk-coskun-flh53', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağustos böcekleri öter,

Cılız lambanın etrafında.

Ağaçlar,

Çiçekler,

Otlar dans eder;

Melteminde gecenin.

Kasvetlidir baykuş,

Düşünceli.

Zor geçer geceleri,

Benim gibi.

O kirazın dalında,

Bakışır dururuz.

Gecenin bir vakti.

							14.06.1995

	ANKARA', 'Ağustos böcekleri öter, Cılız lambanın etrafında. Ağaçlar, Çiçekler, Otlar dans eder; Melteminde gecenin. Kasvetlidir baykuş, Düşünceli. Zor...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/baykus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yar', 'yar-selcuk-coskun-le6gp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmurun grisinde çiğ,

Ayın dolunun da pus oldun.

Sabahımda tan,

Soframda aşım,

Ah deli başım!

Hayatım,

Yarim oldun...

		07.06.1995

		ANKARA', 'Yağmurun grisinde çiğ, Ayın dolunun da pus oldun. Sabahımda tan, Soframda aşım, Ah deli başım! Hayatım, Yarim oldun... 		07.06.1995 		ANKARA...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esir', 'esir-selcuk-coskun-rq8os', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kavanozdaki balık bana,

Öyle bakma.

O hallerden kurtaramam

Seni

Bilemezsin;

Ne kötüdür kavanozun 

dışı...

yapamazsın !

boşuna çırpınma

Kavanozdaki balık

O hallerden kurtaramam 

Seni

Bu düzen;

Senden,

Benden

Eski...

	01.06.1995

	ANKARA', 'Kavanozdaki balık bana, Öyle bakma. O hallerden kurtaramam Seni Bilemezsin; Ne kötüdür kavanozun  dışı... yapamazsın ! boşuna çırpınma Kavan...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/esir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğun', 'yoklugun-selcuk-coskun-2maav', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyku tutmuyor;

Ay kadar eski,

Ay kadar yorgunum.

Nafile uyku tutmuyor.

Dalar gibi

oluyorum

ama çok kısa,

nöbetçi gibi.

Oda 7 adım,

dolaşıyorum.

Yokluğunla konuşup,

Yokluğunla sevişiyorum

O kısa rüyalarda...

		03.06.1995

		ANKARA', 'Uyku tutmuyor; Ay kadar eski, Ay kadar yorgunum. Nafile uyku tutmuyor. Dalar gibi oluyorum ama çok kısa, nöbetçi gibi. Oda 7 adım, dolaşıyor...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yoklugun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yağmur', 'sen-yagmur-selcuk-coskun-1jqsn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmur verdi seni

Bulutları önüne katan

Rüzgar.

Sonbahar götürmeye kalktı;

Mevsimin renkleriyle.

Yağmur kadar,

Rüzgar ve güz kadar

Eskidir sevdam

Yağmur verdi seni,

Güzle bağlama

ellerimi...	

03.06.1999

ANKARA', 'Yağmur verdi seni Bulutları önüne katan Rüzgar. Sonbahar götürmeye kalktı; Mevsimin renkleriyle. Yağmur kadar, Rüzgar ve güz kadar Eskidir s...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçek', 'cicek-selcuk-coskun-q6xsn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah o kokun,

Var ya

En güzeline

Değişmem

Çiçeğin...

	26.05.1995

	ANKARA', 'Ah o kokun, Var ya En güzeline Değişmem Çiçeğin... 	26.05.1995 	ANKARA...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son mu ki Bu Yağmur', 'son-mu-ki-bu-yagmur-selcuk-coskun-dv2s2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kutsanmış sular içtim çocukluğumda

Hep elimi tutacağını sanarak babamın.

Caka attım akranlarıma.

Sonra kaç kişi tuttu bilmiyorum ki

Ellerimi...

Issız odalar yarattım kendime ilkin,

Kaçamak yaptım hayattan

Gitar çaldım, şiir yazdım,

Sonra; 

Aşıkta oldum.

Bahçeler ektim beynimde

Çiçeklerini sulamadığım.

Seni, 

Evet seni gördüm düşümde,

Seslendim,

Dönmedin, bakmadın, gülmedin gülüm.

	             17.03.1999

		KAYSERİ', 'Kutsanmış sular içtim çocukluğumda Hep elimi tutacağını sanarak babamın. Caka attım akranlarıma. Sonra kaç kişi tuttu bilmiyorum ki Ellerimi...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/son-mu-ki-bu-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Bilir Bir Gün', 'kim-bilir-bir-gun-selcuk-coskun-tvu9e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biliyorum uzun sürmeyecek

Bir gün,

Bakışlarından

İçine

Kalbine gireceğim

O an anlayacaksın

İnsan;

Bilmeden aşık olur.

		01.06.1995

		ANKARA', 'Biliyorum uzun sürmeyecek Bir gün, Bakışlarından İçine Kalbine gireceğim O an anlayacaksın İnsan; Bilmeden aşık olur. 		01.06.1995 		ANKARA...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kim-bilir-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-selcuk-coskun-hhgx2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçimde bir sızı

Gözümde uzak bir sıla,

Sırılsıklam olmuş sokaklar

Elimde cigara,

Kim bilir kaçıncı

Martılar çığlık atar;

yokluğuna 

Deniz bile köpürmez

Öfkem kadar

Lanet okurum yokluğuna,

Sensiz

Boş sokaklara...

                                 01.06.1995

		ANKARA', 'İçimde bir sızı Gözümde uzak bir sıla, Sırılsıklam olmuş sokaklar Elimde cigara, Kim bilir kaçıncı Martılar çığlık atar; yokluğuna  Deniz bi...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yeniden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bosluk', 'bosluk-selcuk-coskun-8vnbr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimde bir sızı

Gözümde uzak bir sıla,

Sırılsıklam olmuş sokaklar

Elimde cigara,

Kim bilir kaçıncı

Martılar çığlık atar;

yokluğuna 

Deniz bile köpürmez

Öfkem kadar

Lanet okurum yokluğuna,

Sensiz

Boş sokaklara...

                                 01.06.1995

		ANKARA', 'İçimde bir sızı Gözümde uzak bir sıla, Sırılsıklam olmuş sokaklar Elimde cigara, Kim bilir kaçıncı Martılar çığlık atar; yokluğuna  Deniz bi...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bosluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gömüt', 'gomut-selcuk-coskun-6ubc4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ismarlama olmaz ki bu;

Nasıl, nerede başına geleceği bilinmez.

Aşk bu !

baharda gelir şanslıysan.

Yada yapraklar dökülürken sarı, kırmızı ve bej.

Yeltenme sonu bellidir.

Kalın duvardır sevdiğin, ateş tuğlasından

Haykırsan,

Yalvarsan,

Yaksan duyuramazsın sesini.

Sıcak ölümdür bu...

Ayrılıktır bir tek sen bilirsin.

Ölmeden gömülürsün...

		03.12.1995

		ANKARA', 'Ismarlama olmaz ki bu; Nasıl, nerede başına geleceği bilinmez. Aşk bu ! baharda gelir şanslıysan. Yada yapraklar dökülürken sarı, kırmızı ve...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gomut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döndüm', 'dondum-selcuk-coskun-c20bh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Döndüm;

Yalnızlığım ve ben.

Her şey bıraktığım gibi değil

Ben bile...

Kavanozdaki balık ölmüş,

Soruda sormuyorlar.

Şehir kulak kesilmiş,

Şarkımı bekliyor.

Oysa !

Unutmuşum

Şarkı söylemesini de.

								17.05.1999

	ANKARA', 'Döndüm; Yalnızlığım ve ben. Her şey bıraktığım gibi değil Ben bile... Kavanozdaki balık ölmüş, Soruda sormuyorlar. Şehir kulak kesilmiş, Şar...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dondum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz', 'karadeniz-selcuk-coskun-0ynjq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Takalarını özledim Be...!

Gecenin gizinde  hayalet gibi,

Usulca salınan takalarını.

Sonu sefilliğe ulaşan,

Yıllara karşı durmaya uğraşan,

Arnavut taşından sokaklarını özledim.

sabahları kokuları karışan

Yosunu, ekmeğini özledim

Haftalarca dinmeyen,

İnsanı çıldırtan

Yağmurunu bile özledim.

								03.12.1995

	ANKARA', 'Takalarını özledim Be...! Gecenin gizinde  hayalet gibi, Usulca salınan takalarını. Sonu sefilliğe ulaşan, Yıllara karşı durmaya uğraşan, Ar...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karadeniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizin Sesi', 'denizin-sesi-selcuk-coskun-mun0v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Radyoda eski günler çalıyor,

Dinliyorum.

Korkum büyük yalanım kadar,

Hayatım kadar yalın bitimi günün.

Solgun neonlar ve Kızılay orada;

Hiç gidesim yok !

Yollara düşmek gereksiz.

Rüzgar bekliyorum;

Yelkeni dolduracak.

Denizin sesini özledim be kadınım. 	

				

                                             17.05.1999

			ANKARA', 'Radyoda eski günler çalıyor, Dinliyorum. Korkum büyük yalanım kadar, Hayatım kadar yalın bitimi günün. Solgun neonlar ve Kızılay orada; Hiç ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/denizin-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudum', 'umudum-selcuk-coskun-pm6nz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çiğ düştüğünde yonca yaprağına;

Kusursuz oldu dünyam.

Ve akşamın loşluğunda kadehteydi hayat.

Biraz buruk, biraz tatlı,

Şarap tadında...

Uzadı gece yanımda uyuduğunda.

Kralıydım uykusuz gecenin;

Hem kölesi yalnızlığın,

Hem de efendisi,

Amaçsızdı, suskundu sabah.

Dalmışım rüyalara,

Sen uyandığında

Sır olsun,

Söz ver, anlatma !

Bir asır oldu,

Uyandım;

Umudun krallığına...

	

		11.10.1997

		ANKARA', 'Çiğ düştüğünde yonca yaprağına; Kusursuz oldu dünyam. Ve akşamın loşluğunda kadehteydi hayat. Biraz buruk, biraz tatlı, Şarap tadında... Uza...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/umudum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renk', 'renk-selcuk-coskun-y8crc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sınırsızdır renkler gizimde

Sadece;

Beyazla siyah arasında gidip gelir.

Her insan,

Her olay ayrı boyar beni

Bazen gridir günler.

Bazen beyaz geçer,

Monotondur.

Kimi gün;

Pembe !

Pembe nadirdir; bir anlık...

Sınırsızdır renkler gizimde

Sadece;

Beyazla siyah arasında gidip gelen.

		19.05.1998

		KAYSERİ', 'Sınırsızdır renkler gizimde Sadece; Beyazla siyah arasında gidip gelir. Her insan, Her olay ayrı boyar beni Bazen gridir günler. Bazen beyaz...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/renk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıl Saçlım', 'kizil-saclim-selcuk-coskun-uxoq8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karşımda duruyordu

Gözlerinde aşkın kini

Ve dudakları

Al, al olmuştu.

Kızıl saçlıydı, inceydi;

Gülerdi yokluğuma

Sanki kolları her zaman 

Sarmaya hazırdı.

Ben buradayım 

alsana diyen

yeminler eden 

yorulmuş, aldatılmış

kızıl saçlım ...

	              09.07.1999

                  	ANKARA', 'Karşımda duruyordu Gözlerinde aşkın kini Ve dudakları Al, al olmuştu. Kızıl saçlıydı, inceydi; Gülerdi yokluğuma Sanki kolları her zaman  Sa...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kizil-saclim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıskanç (Gitar)', 'kiskanc-gitar-selcuk-coskun-32oq1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne olur kıskanma,

Senin saçların yok ki

Kumral, dans eden.

Bu aldatmak değil ki.

Buğulu,

Yakar gibi bakmıyorsun.

Özlemini duymuyorum,

Ayrılmadık ki 

Hiç !

17’den bu yana

Ne olmuş?

Üç gündür yanına

Varmadıysam,

Ne olur?

Dokunmadıysam.

Tenin kavurmalı,

dokunduğunda insanı,

Ve onun gibi kızdırmalı,

Bağlamalı;

Ayrılmamacasına...

Ne olur kıskanma

Gitarım

Aşk bu...

							               04.12.1994

ANKARA', 'Ne olur kıskanma, Senin saçların yok ki Kumral, dans eden. Bu aldatmak değil ki. Buğulu, Yakar gibi bakmıyorsun. Özlemini duymuyorum, Ayrılm...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kiskanc-gitar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkı', 'sarki-selcuk-coskun-tzmnc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O şarkı çalıyor yine

Cızırtılı plaktan

Beni Selaniğ’e götüren

Yaslı kadınların sesi içimi eziyor.

Ayrılıklar yaşayan o ırklar geliyor aklıma

Yüzyılın başında...

Tuna’nın al kan rengi gözlerimin içinde

Yaslı kadınların sesi içimi eziyor.

O yalın aşk hikayelerini görüyorum 

Rüyalarda.

İnsanlara anlatmak istiyorum.

Olmuyor be güzelim.

Yolları, geçtiğim ırmakları,

Köyleri, ladinleri unuttum.

Kenttin içinde yittim.

Olmuyor be güzelim.

Yaşanmıyor...

								              21.05.1999

		ANKARA', 'O şarkı çalıyor yine Cızırtılı plaktan Beni Selaniğ’e götüren Yaslı kadınların sesi içimi eziyor. Ayrılıklar yaşayan o ırklar geliyor aklıma...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sarki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum', 'mum-selcuk-coskun-1reiu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bulutun altındayım.

Gün,

Şimdilerde devreder,

Geceye.

Yeni doğuşlar,

Yeni seviler besler içinde.

Mumlar yakarım aşkıma...

			

                                01.06.1995

                                 ANKARA', 'Bulutun altındayım. Gün, Şimdilerde devreder, Geceye. Yeni doğuşlar, Yeni seviler besler içinde. Mumlar yakarım aşkıma... 			               ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hal', 'hal-selcuk-coskun-pi88h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaz geldi gelincik.

Saçlarının rengi

Yakındır açılır.

Tenin kumral,

Gözlerin bir başka

Bakar.

Bilirsin;

Bu hallerin 

Beni...

Büsbütün yakar.

		19.07.1995

		ANKARA', 'Yaz geldi gelincik. Saçlarının rengi Yakındır açılır. Tenin kumral, Gözlerin bir başka Bakar. Bilirsin; Bu hallerin  Beni... Büsbütün yakar....', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabah Gelirim', 'sabah-gelirim-selcuk-coskun-x0ydl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabah kalkıp yanına koşacağım,

Biliyorsun.

Yalnızca

Yanında olmak

İçin.

Yüzünü görmek,

Sesini duymak,

Saçlarının kokusunu içime

Çekmek için

Yarın yanında olacağım.

Yeni sevgilerle,

Günaydın diyeceğim.

Yada !

Kulağına,

Sevgimi fısıldayacağım.

Gözlerindeki

O bir anlık pırıltıyı

Görmek için

Belki de öleceğim.

	16.05.1999

	KAYSERİ', 'Sabah kalkıp yanına koşacağım, Biliyorsun. Yalnızca Yanında olmak İçin. Yüzünü görmek, Sesini duymak, Saçlarının kokusunu içime Çekmek için ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sabah-gelirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varamadığım', 'varamadigim-selcuk-coskun-m579u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzadı günlerim.

Gecelerim bir başka kasvetli,

Hiç çekilmez.

Yollar, yollar...

Varacağım yerler uzak.

Sen

Uçurum kenarında çiçek,

Söylesene

Bu yıllar nasıl geçecek?

Yaklaşmaz sana adımlarım.

Sen

Uçurum kenarında çiçek,

Ben

Yazı bekleyen uç-uç böcek.

							              28.10.1996

ANKARA', 'Uzadı günlerim. Gecelerim bir başka kasvetli, Hiç çekilmez. Yollar, yollar... Varacağım yerler uzak. Sen Uçurum kenarında çiçek, Söylesene B...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/varamadigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Tren', 'kara-tren-selcuk-coskun-dwlx6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şımarmış bulutlar,

Rüzgarın

Önünde koştururlar.

Ben 

Zamanın arkasında nefes-nefes.

Doğuya giden eski bir tren gibiyim.

Kapkara tüter

Dumanım

Ve tekliye, tekliye çıkarım

Yokuşu...

Kasvetliyim

Ayrılık yakın ya yardan.

	29.01.1998

	ANKARA', 'Şımarmış bulutlar, Rüzgarın Önünde koştururlar. Ben  Zamanın arkasında nefes-nefes. Doğuya giden eski bir tren gibiyim. Kapkara tüter Dumanı...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kara-tren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Gördüm Sensiz', 'dus-gordum-sensiz-selcuk-coskun-12xzi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kurak topraklar üzerinden geçtik.

Çatlamış, çalı çırpı sapsarı bürümüş.

Düşler gördük yıldızsız zifiri gecelerde

Ayrı, ayrı...

Sarıldık soğukta uzaklardan birbirimize,

Baharı bekleyerek.

Yürüdük saatlerce yağmurda,

Birbirimizden habersiz.

Tam kavuştuk!

Yollar, dağlar, şehirler girdi aramıza

Kara kedi misali...

Masallar anlattılar 

Senden, benden,

Kinden, savaştan,

Çocuklardan

Ve aşktan...

	29.01.1998

	ANKARA', 'Kurak topraklar üzerinden geçtik. Çatlamış, çalı çırpı sapsarı bürümüş. Düşler gördük yıldızsız zifiri gecelerde Ayrı, ayrı... Sarıldık soğu...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dus-gordum-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanıdık', 'tanidik-selcuk-coskun-4zoha', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bildik yüzlerden değil

Anlatılmış, duyulmuş masal

Değil!

Yo korkaklık, hainlik hiç değil.

Gözlerinde gördüğüm;

Yağmur, deniz ve tuz

Ve birde benim yalnızlığım.

Dudaklarından dökülen sözler

Senin değil aşkın...

		26.02.00

		ANKARA', 'Bildik yüzlerden değil Anlatılmış, duyulmuş masal Değil! Yo korkaklık, hainlik hiç değil. Gözlerinde gördüğüm; Yağmur, deniz ve tuz Ve birde...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tanidik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oysa Sendeydi Tüm Ümitlerim', 'oysa-sendeydi-tum-umitlerim-selcuk-coskun-bfe18', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kağıttan uçaklar uçuruyorum gökyüzüme,

Umut dolu, sevgi yüklü 

Ama kağıttan.

Kartondan evler yapıyorum.

Kırmızı çatılı, mavi boyalı,

Çocuklar ve kediler oynuyor bahçesinde...

Ama kartondan.

Telden insanlar yoğuruyorum;

Koşan, savaşan, ulaşan, dans eden, konuşan ve sevişen...

Ruhları yok!

Hepsi telden.

Şiir yazıyorum sana,

Yalın, yalansız, sualsiz...

Ama karşılıksız.

	26.03.00

    	ANKARA', 'Kağıttan uçaklar uçuruyorum gökyüzüme, Umut dolu, sevgi yüklü  Ama kağıttan. Kartondan evler yapıyorum. Kırmızı çatılı, mavi boyalı, Çocukla...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oysa-sendeydi-tum-umitlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Bekliyorum', 'seni-bekliyorum-selcuk-coskun-lletq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şehrimin ötesindeyim.

Ruhum; kasvetlide değil hani.

Ama neden bilemiyorum sıkıntım.

Elimde bir tutam papatya seni bekliyorum.

Acıtmıyor artık sözleri insanların.

Gecelerim dingin,

Yüreğim kocaman,

Ve yanan yüzlerce mum,

Ve gitar!

Ve şiir

Ve sen aklımda...

Ama neden bilmiyorum sıkıntım.

Elimde bir tutam papatya seni bekliyorum.

                 27.03.00

	ANKARA', 'Şehrimin ötesindeyim. Ruhum; kasvetlide değil hani. Ama neden bilemiyorum sıkıntım. Elimde bir tutam papatya seni bekliyorum. Acıtmıyor artı...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seni-bekliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Şehri', 'sensizlik-sehri-selcuk-coskun-zvgvm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuzeye döndüm yüzümü, yaşadığım şehre bakıyorum.

Işıklar bir bir yanıyor uzaklarda.

Cigaranın dumanını öyle bir çekiyorum ki ciğerlerime, kendime şaşıyorum.

Öldürecek bu beni biliyorum,

Cigara değil sensizlik.

		30.03.00

		ANKARA', 'Kuzeye döndüm yüzümü, yaşadığım şehre bakıyorum. Işıklar bir bir yanıyor uzaklarda. Cigaranın dumanını öyle bir çekiyorum ki ciğerlerime, ke...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sensizlik-sehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Beklerim Kurtuluşu', 'senden-beklerim-kurtulusu-selcuk-coskun-hhkkh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne güzel diyorum hayat ve ölüm peşim sıra.

Acımıyorum yitmeme yaşarken.

Ne olsa olsun, önümüz bahar.

Yok toprak kabul eder nasıl olsa, diyorum.

Nazar boncuğum da yok artık,

Değerse değsin kem gözler.

Yitecek ne kaldı ki benden...

Ne beklerim biliyorsun senden.

			01.04.00

			ANKARA', 'Ne güzel diyorum hayat ve ölüm peşim sıra. Acımıyorum yitmeme yaşarken. Ne olsa olsun, önümüz bahar. Yok toprak kabul eder nasıl olsa, diyor...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/senden-beklerim-kurtulusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Düşlediğim Ellerindi', 'i-lk-dusledigim-ellerindi-selcuk-coskun-x54e3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kahve gözlerini düşlüyorum,

Rüzgar dalga dalga yapsın istiyorum saçlarını.

Elini de tutmak sonra.

Kumlara yazmak ismini,

Dalgasız kıyıda.

Yüzünü yüzüme sürmek,

Seni seviyorum demek sonra...

		04.04.00

  		ANKARA', 'Kahve gözlerini düşlüyorum, Rüzgar dalga dalga yapsın istiyorum saçlarını. Elini de tutmak sonra. Kumlara yazmak ismini, Dalgasız kıyıda. Yü...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ilk-dusledigim-ellerindi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğru mu Mevsim?', 'dogru-mu-mevsim-selcuk-coskun-w31bu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonu olacak mı şimdi yaşadığım mutluluğun,

Bu kadar yılmış ve korkmuşken.

Bir kere daha dene diyebilecek miyim,

Sence ?

Ümit etmeli miyim senden gelecek aşkı,

Yoksa boşuna mı bu çırpınışlarım.

Yoksa eskisi gibi mi olmalı hayatım.

Ama bak bahar geldi gülüm,

Aşksız olamam ki...

			05.04.00

			ANKARA', 'Sonu olacak mı şimdi yaşadığım mutluluğun, Bu kadar yılmış ve korkmuşken. Bir kere daha dene diyebilecek miyim, Sence ? Ümit etmeli miyim se...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dogru-mu-mevsim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölmem ki !', 'olmem-ki-selcuk-coskun-gt7dx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yakamoz kovalayan denizciyim ben gecelerinde...

Rüzgar küsmesin diye,

Daha yelkensiz takaların icat edilmediği denizde.

Sakın aldanma geleceğim yöne,

Gelmezsem, gelmeyeceksem üzülme.

Aklına gelmesin ölüm.

Öleceksem, öldüysem üzülme.

Aşıksam ölmem ki.

( 08.04.00-ANKARA)', 'Yakamoz kovalayan denizciyim ben gecelerinde... Rüzgar küsmesin diye, Daha yelkensiz takaların icat edilmediği denizde. Sakın aldanma gelece...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olmem-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-selcuk-coskun-r85qs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sanrılarla kıvranırken ben seziyor musun gidişimi dünyandan ?

Üşüyor musun yapraksız ağaç gibi...

Seviyor musun beni ?

( 09.04.00-ANKARA )', 'Sanrılarla kıvranırken ben seziyor musun gidişimi dünyandan ? Üşüyor musun yapraksız ağaç gibi... Seviyor musun beni ? ( 09.04.00-ANKARA )...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sevgili-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mihenk', 'mihenk-selcuk-coskun-3jp0s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülersem, gül benimle;

Ağlarsam, ağla...

Gidiyorum dersem, ardım sıra gelme,

Ölürsem, ölme...

Seviyorum dersem, sevme beni...

Nedenini düşün dur...

( 09.04.00-ANKARA )', 'Gülersem, gül benimle; Ağlarsam, ağla... Gidiyorum dersem, ardım sıra gelme, Ölürsem, ölme... Seviyorum dersem, sevme beni... Nedenini düşün...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mihenk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçmalık', 'sacmalik-selcuk-coskun-65nlz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Küçük odama sığınmışım,

Mumlar yakıyorum kendi yarattığım karanlıklara...

Ve elime aldığım kadehteki kendi kanım.

Ölmekte çok kolay biliyorum, 

sevdan olmasa,

Yitecek tek hayatı olana...

Gitmekte doğmuyor içime,

Aynada şaşırıyor aldığım bu biçime.

Seni düşünüyorum; hep eksik kalıyor hayallerim.

Gelmeyeceksin biliyorum...

( 09.04.00-ANKARA )', 'Küçük odama sığınmışım, Mumlar yakıyorum kendi yarattığım karanlıklara... Ve elime aldığım kadehteki kendi kanım. Ölmekte çok kolay biliyoru...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sacmalik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkak', 'korkak-selcuk-coskun-0opoy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Saçların parlıyor biliyor musun,

Işıksız günde bile, benim gözümde...

Ve gözlerin hep aşkla bakıyor her nesneye...

Ellerin öyle minik ki çekiniyorum tutmaya kırılırlar diye...

Ve seni öyle seviyorum ki,

Korkuyorum söylemeye...

(09.04.00-ANKARA)', 'Saçların parlıyor biliyor musun, Işıksız günde bile, benim gözümde... Ve gözlerin hep aşkla bakıyor her nesneye... Ellerin öyle minik ki çek...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/korkak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toplam', 'toplam-selcuk-coskun-q1rs3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün gece biriktirdiğim düşlerimi topladım bir araya,

Ve ayırdım en saflarını bir yana.

Hepsinden sen çıktın...

( 09.04.00-ANKARA )', 'Dün gece biriktirdiğim düşlerimi topladım bir araya, Ve ayırdım en saflarını bir yana. Hepsinden sen çıktın... ( 09.04.00-ANKARA )...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/toplam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkım', 'sarkim-selcuk-coskun-dns68', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Leylaklar açacak az kaldı.

Selanik''ten doğumumu müjdeleyecekler sana.

Bir çingenenin kemanından dökülecek şarkım.

Belki de ayağı çıplak bir kız çocuğu mırıldanacak...

Ve sana getirecekler topladığım tüm papatyaları.

Bileceksin seni özlediğimi...

( 09.04.00-ANKARA )', 'Leylaklar açacak az kaldı. Selanik''ten doğumumu müjdeleyecekler sana. Bir çingenenin kemanından dökülecek şarkım. Belki de ayağı çıplak bir ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sarkim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarim', 'yarim-selcuk-coskun-ndynf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Salıncaklar kurduk diktiğim ağaçların arasına.

Sallanmak değildi istediğimiz.

Soğan ve zeytini katık ettik ekmeğimize.

Hiç gocunmadık boşa giden emeklerimize...

Ve seni anlattık birbirimize,

Bacım ve ben kulaklarını çıtlattık,

Dün gece...

( 10.04.00-ANKARA)', 'Salıncaklar kurduk diktiğim ağaçların arasına. Sallanmak değildi istediğimiz. Soğan ve zeytini katık ettik ekmeğimize. Hiç gocunmadık boşa g...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşi Batıran', 'gunesi-batiran-selcuk-coskun-8epfv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yol olsa gitsem dedim dostuma,

Kor ateş olsa dedim yarim yaksa,

Ayrı düşler kursak dedim yan yana,

Hatta bir damacana şarap olsa dedim yanımda...

Güneşi beraber batırsak dedim aşkıma...

( 10.04.00-ANKARA )', 'Yol olsa gitsem dedim dostuma, Kor ateş olsa dedim yarim yaksa, Ayrı düşler kursak dedim yan yana, Hatta bir damacana şarap olsa dedim yanım...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gunesi-batiran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yine Aklıma Düşen', 'sen-yine-aklima-dusen-selcuk-coskun-uhmeh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yarın sana gelincik toplayacağım,

ellerin tarlalarından.

Rüzgar getireceğim koynuma saklayıp,

kuşların göğünden...

Karamsarlığına mumlar yakacağım.

Seni anlatacağım tanışlarıma...

( 10.04.00-ANKARA )', 'Yarın sana gelincik toplayacağım, ellerin tarlalarından. Rüzgar getireceğim koynuma saklayıp, kuşların göğünden... Karamsarlığına mumlar yak...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-yine-aklima-dusen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olsan', 'sen-olsan-selcuk-coskun-ymy8p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün doğsa diyorum,

Hiç bitmese ve batmasa, 

benim olsa güneş.

Bir çiçek açsan diyorum,

Kışa inat,

Kanat çırpsa martılarım,

Yamaçta açan katmerine...

Bir rüya görsem diyorum,

İçinde;

sen olsan,

uyanmasam...

		15.04.00

		ANKARA', 'Bir gün doğsa diyorum, Hiç bitmese ve batmasa,  benim olsa güneş. Bir çiçek açsan diyorum, Kışa inat, Kanat çırpsa martılarım, Yamaçta açan ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-olsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanmak', 'yanmak-selcuk-coskun-3qn4u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana diyeceklerimi duyma,

Göstereceklerimi görme...

Yazdıklarımı okuma,

Boyandığım yeşile dokunma...

Benim utkularımı isteme,

İçtiğim şarabı tatma...

Yoksa sende aşık olursun baharda...

                               15.04.00

		ANKARA', 'Sana diyeceklerimi duyma, Göstereceklerimi görme... Yazdıklarımı okuma, Boyandığım yeşile dokunma... Benim utkularımı isteme, İçtiğim şarabı...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yanmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende ki Biz', 'sende-ki-biz-selcuk-coskun-53njt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana aşkımın itirafı,

Hem doğumum olacak,

Ve de ölümüm.

	16.04.00

	ANKARA', 'Sana aşkımın itirafı, Hem doğumum olacak, Ve de ölümüm. 	16.04.00 	ANKARA...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sende-ki-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uydu', 'uydu-selcuk-coskun-l27wu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni düşündüm yine, masmavi bir göğün altında, gelincik tarlasında.

Ve saçların, gözlerin, 

Ellerin-ellerimde...

Senden bir dünya kurdum sonra kutupsuz, 

Aşkımı sınadım sonra,

Ben gelecekten korkma...

			19.04.00

			ANKARA', 'Seni düşündüm yine, masmavi bir göğün altında, gelincik tarlasında. Ve saçların, gözlerin,  Ellerin-ellerimde... Senden bir dünya kurdum son...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uydu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanmak Gece, Gece', 'yanmak-gece-gece-selcuk-coskun-oknaj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Söylesene;

gün nasıl aydınlanır,

gecenin ardından, 

güneş doğmadan.

Söylesene;

Yollar sana varmayacaksa,

Ne işe yarar.

Gece yoksan yanımda,

Söylesene;

Yanmak neye yarar...

		30.04.00

		ANKARA', 'Söylesene; gün nasıl aydınlanır, gecenin ardından,  güneş doğmadan. Söylesene; Yollar sana varmayacaksa, Ne işe yarar. Gece yoksan yanımda, ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yanmak-gece-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Af', 'af-selcuk-coskun-if3d7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Farkına varmazsın ilk önce,

Tuhaf gelir sözler.

Umursamazsın akşamın oluşunu,

Sarhoşsan.

Bir gün, hiç ummadığın bir yerde,

Karşına çıkarda, şaşırırsın.

Büyük konuşma sakın,

Belki de bağışlarsın.

		04.05.00

		ANKARA', 'Farkına varmazsın ilk önce, Tuhaf gelir sözler. Umursamazsın akşamın oluşunu, Sarhoşsan. Bir gün, hiç ummadığın bir yerde, Karşına çıkarda, ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/af-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat Yediydi ve Öldüler', 'saat-yediydi-ve-olduler-selcuk-coskun-bzlld', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kızıl bayraklar dalgalanıyordu.

Gün soğuk, yürekler sıcak.

Havada zaferin muştusu trampet sesleri,

Sağır ediyor düşmanı.

Ve çakır gözlü sarışın bir asker en önde...

Gözlerinin içinde; umut.

Ardında bitmek bilmeyen kavganın izleri.

Ve birde o taş yoldan varılan gömüt.

			17.03.00

			ANKARA', 'Kızıl bayraklar dalgalanıyordu. Gün soğuk, yürekler sıcak. Havada zaferin muştusu trampet sesleri, Sağır ediyor düşmanı. Ve çakır gözlü sarı...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/saat-yediydi-ve-olduler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanımdandır O Yeditepeli Şehirde ki Kardeşim', 'kanimdandir-o-yeditepeli-sehirde-ki-kardesim-selcuk-coskun-aokkv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğimi satılığa çıkartmışlar Salı Pazarında, Kadıköy''de, İstanbul''un göbeğinde,

Bana sormadan.

Kan kusturmuşlar yerimi söylemeyenlere sonraları.

Kardeşimi görmüşler direkler arasında,

Kafası sıfır tıraşlı,

Özlediğimi söyleyemediğim şarkılar söylüyormuş.

Altında asker pantolonu,

Sonra geçirmişte ayağına postalı, 

Hem yatağını da özlüyormuş.

			01.04.00

			ANKARA', 'Yüreğimi satılığa çıkartmışlar Salı Pazarında, Kadıköy''de, İstanbul''un göbeğinde, Bana sormadan. Kan kusturmuşlar yerimi söylemeyenlere sonr...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kanimdandir-o-yeditepeli-sehirde-ki-kardesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğrularım Yanlışsa Dönülür mü Yoldan', 'dogrularim-yanlissa-donulur-mu-yoldan-selcuk-coskun-z5dd7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beklemek mi lazım yarının olmasını,

yoksa yol almak mı karanlığın içinde,

Sezdirmeden yaşadığını.

Çatalına geldiğinde sapağın, 

geri mi dönsek, 

yoksa seçsek mi her hangi bir yolu...

Bu kadar zor mu?

 istediğin hayatı yaşamak özgürce...

			05.04.00

			ANKARA', 'Beklemek mi lazım yarının olmasını, yoksa yol almak mı karanlığın içinde, Sezdirmeden yaşadığını. Çatalına geldiğinde sapağın,  geri mi döns...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dogrularim-yanlissa-donulur-mu-yoldan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoş', 'sarhos-selcuk-coskun-i2tgn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sokak lambasının süzülen cılız, 

loş ışığın altında dikilirim,

Beklediğimin gelmeyeceğini bilerek.

Tuhaf; 

gecenin karanlığında 

ne güzel gelir 

boş şişelerin şıngırtısı.

Şeytan da yoklar sonra ayazda,

Bu da hoşuna gider,

Tuhaf değil mi?

				05.04.00

				ANKARA', 'Sokak lambasının süzülen cılız,  loş ışığın altında dikilirim, Beklediğimin gelmeyeceğini bilerek. Tuhaf;  gecenin karanlığında  ne güzel ge...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sarhos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcu', 'yolcu-selcuk-coskun-744hx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana yazdığım şiirleri okuduğunda

Ben ve aşkın,

gitmiş olacağız şehrinden...

			09.04.00

			ANKARA', 'Sana yazdığım şiirleri okuduğunda Ben ve aşkın, gitmiş olacağız şehrinden... 			09.04.00 			ANKARA...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Coşkun']::text[], 8.5, '{"poet":"Selçuk Coşkun","poet_slug":"selcuk-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yolcu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbaharda Bir Düş', 'sonbaharda-bir-dus-vedat-koseoglu-nj9pw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Niçin bu hüzün, söyle buna sebep ne?

Bilmem neden böyle çökmüş omuzların?

Yıllar birer çizgi olup düşmüş yüzüne

Şarkımızı söylemez olmuş dudakların...

Üzülme ! Yalnız senden götürmedi zaman, 

Bak işte ben de o eski ben değilim,

Artık bütün yollar dik, bütün ufuklar duman,

Eylülde bir yaprak gibi titriyor elim...

Ne çıkar eskise beden değişse çehremiz,

İçimizde gizli gizli yanan korlar var,

Bu sonbahar gününde kalsak ta sessiz,

Söylenmemiş herşeyi söyler bakışlar...

Çaresiziz! Mümkün değil maziye dönüş,

''Geçmiş zaman olur ki hayali cihan değer''

Herşeyi yeniden yaşamak olsa da bir düş,

İsterdim, ''Şimdi bana kaybolan yıllarımı verseler''', 'Niçin bu hüzün, söyle buna sebep ne? Bilmem neden böyle çökmüş omuzların? Yıllar birer çizgi olup düşmüş yüzüne Şarkımızı söylemez olmuş dud...', ARRAY['Türk Edebiyatı','Şiir','Vedat Köseoğlu']::text[], 8.5, '{"poet":"Vedat Köseoğlu","poet_slug":"vedat-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonbaharda-bir-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçemediğim', 'vazgecemedigim-vedat-koseoglu-x0sw0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Doğumum kaçınılmazdı, 

Doğdum! 

Ve vazgeçemedim nefes almaktan, yaşamaktan

Anne kucağında uyumaktan ve ağlamaktan da vazgeçemedim. 

Büyümem  de kaçınılmazdı, 

Her canlı gibi, 

Büyüdüm.

Arkadaşlarım oldu, oyunlarımız ve yaramazlıklarımız

Hepsi de vazgeçilemezdi bir zamanlar, 

Birini, otekine tercih edemezdim.

Okula gittim, isteyerek ve severek

Daha bir bağlandım yaşama, 

Giderek daha bir vazgeçilmez oldu herşey, 

Vazgeçilemezlik beraberinde getirdi hep kaçınılmazlığı.

Pek çok şeyden kaçamadım zaten, 

Konuşmalar, tartışmalar ve kavgalar

Aşklar geldi peşisıra

Yanılgılar, ağlamalar ve hüzünler

Hepsi bir bütünün parçası gibiydiler

Ve hepsinin yaşanması da kaçınılamazdı

Yaşandılar.

Sevinçler bürüdü kimi zaman bedenimi

Tutku haline döndüler kimi zaman

Sürüklendim peşleri sıra ve 

Vazgeçemedim! 

Giderek daha bir kaçınılamaz oldu herşey, 

Saçıma ilk karlar düştüğünde daha iyi anladım, 

Anladım ki, herşey bir düzen içindedir, 

İyi ve kötüsüyle herşey yaşanacaktır

Kaçınılamaz oldukları kadar da vazgeçilemezdirler, 

Anladım ki sevdalar ayrılıkların

Ve sevinçler hüzünlerin kardeşidirler.

Kimi zaman terk ettiler dostlar, 

Üzülmek te kaçınılmazdı.

Kaçınılamaz olan herşey birgün vazgeçilemez olup

Geri geldi.

Giderek daha bir kaçınılamaz ve vazgeçilemez oldu herşey, 

Anladım ki hayat dediğimiz şey

Kaçamadığımız ve vazgeçemediklerimizin

Bir örgüsüdür, 

Doğan güneşin batışı gibi

Ölüm de kaçınılmazdır, 

Bilmiyorum belki de vazgeçilemezdir.

Ama

Bildiğim birşey var, 

O; 

Ölümün bu kaçınılamazlığına 

Geride kalan bunca vazgeçilemez görünüp 

Vazgeçilenlere karşın

Senden 

ASLA VAZGEÇEMEDİĞİMDİR...', 'Doğumum kaçınılmazdı,  Doğdum!  Ve vazgeçemedim nefes almaktan, yaşamaktan Anne kucağında uyumaktan ve ağlamaktan da vazgeçemedim.  Büyümem ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Köseoğlu']::text[], 8.5, '{"poet":"Vedat Köseoğlu","poet_slug":"vedat-koseoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/vazgecemedigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırdışı Bir Koşuk', 'sirdisi-bir-kosuk-ejdan-sadrazam-jadrr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birileri,

biryerlerde,

yinelerken senin sözlerini,

 o hiç başlamak   ve sonlandırmak istemediğin özlemlerini

söyleminde tütsülüyor işine gelmeyeni her sabah aşısız yaban zeytini.             

Adımlarına  yetişemediğim sıcak bir sonbahar,  başparmağımda  kuruyan mürekkebin ağırlığı   ve gündoğumunun bakırsı kokusu içimi burkan dert şimdi.

Sanki,

sanki 

gizemli ve ağır;

sanki 

bir sır.

Birileri, 

biryerlerde, 

söylerken yalnızlığın ebedi şarkılarını,

detone bir an  yokluğun vokalistliği 

ve rüzgarın yönünü değiştiren soru;

tüm insanların bir filozof olup da bunu bilmemesi.

Soytarının soykütüğüne kayıtlı,

 doğal beklentilerimizi karşılamayan devinim,

sanki 

hayranlık ve korku,

sanki

ümit ve düşkırıklığı.

Güneş etrafında dolaşmanın kazancı nedir?

Ey, suçu sokaklarca paylaşan günlük felaket bağımlısı  insanlar!

Nehri kendine çağıran deniz,

bir an  depreşir 

ve durulur.

Bilir ki, ne kadar depreşse 

kumlarca o kadar yutulur.

Değil mi ki, 

özgün kimliğinde sakladığı yaratı, 

zorunluluğun prangalarından kurtuldukça

ve düşünceye köstek vuran dogmalar kudurdukça;

Arşimed ile Galileo arasında

 yerçekimine kapılır,

şafakta taçyaprakları boydan boya  hırpalanır ama 

sır,

taşı konuşturuncaya değin

söylenip

durur.', 'Birileri, biryerlerde, yinelerken senin sözlerini,  o hiç başlamak   ve sonlandırmak istemediğin özlemlerini söyleminde tütsülüyor işine gel...', ARRAY['Türk Edebiyatı','Şiir','Ejdan Sadrazam']::text[], 8.5, '{"poet":"Ejdan Sadrazam","poet_slug":"ejdan-sadrazam","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/sirdisi-bir-kosuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Koşuk', 'kara-kosuk-ejdan-sadrazam-bsd0q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir tek kartal başta, 

başta kral;

         her taraftan,

            ve her kafadan çıkan sese, Mosse.                           

Mosse.

Siri Laom

         Afrika,

           daha on yaşında 

düşlerinde bile duymadığı o sözcüğü işittiğinde

        tüm bedeni çıplaktı

                 ve toprak ıslak

danışıksız suçlama, usta bir boyunduruk

Mosse, en küçük askerdi şimdi,

          ve en küçük kaçak.

Mosse,

       Siri Laom

               Afrika. 

   

               Soğanın kabuğunda bedeni

        kim ısıtır  geceyi,

kim, kim kazanır tacı ?

o keskin kılıcı;

cangılda sürek avı

    dişi aslan

       dişi keskin,

  her saldırısında hür,

  yengisi ise ölümdür.

  

 Mosse 

          Siri Laom

                      Afrika.', 'Bir tek kartal başta,  başta kral;          her taraftan,             ve her kafadan çıkan sese, Mosse.                            Mosse. Si...', ARRAY['Türk Edebiyatı','Şiir','Ejdan Sadrazam']::text[], 8.5, '{"poet":"Ejdan Sadrazam","poet_slug":"ejdan-sadrazam","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kara-kosuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vız Gelir Dost', 'viz-gelir-dost-gokhan-phoenix-altinay-gil1n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'D urmadan koşacağız

E n son nefese kadar

N e coplar ne baskılar

İ şkenceler zindanlar

Z afere engel değil idamlar

G ün gelir dağlarımızda 

E ylem sesleri yankılanır

Z emheri ayazı vız gelir DOST!!

M avzer omuzda

İ syan yürekte oldukça

Ş arkılarla karşılarız ölümü, türkülerle', 'D urmadan koşacağız E n son nefese kadar N e coplar ne baskılar İ şkenceler zindanlar Z afere engel değil idamlar G ün gelir dağlarımızda  E...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Phoenix Altınay']::text[], 8.5, '{"poet":"Gökhan Phoenix Altınay","poet_slug":"gokhan-phoenix-altinay","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/viz-gelir-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '55 Dk.', '55-dk-gokhan-phoenix-altinay-lygqe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Deniz''i gördüm düşümde

Gece yarısı beyaz gömlekle

Üşüyor sandım önce, Üşümüyordu

Ağlıyor sandım, gülümsüyordu

Devrimi haykırıyordu

Etrafındakiler, onlar mutluydular

Kemik bulmuş köpek misali

Deniz dalgalanmış köpürmüştü

Durmaksızın haykırıyordu

Ölüme değil

Düzeneydi isyanı

Bir an

Bir an 

Boğazına bir şey düğümlendi sanki

Her şey sustu

Beyaz bir güvercinin kanat sesleri dışında

55 dk. sürdü düşüm

Bir şiir kadar kısa

Bir destan kadar uzun bir

55 dk.', 'Deniz''i gördüm düşümde Gece yarısı beyaz gömlekle Üşüyor sandım önce, Üşümüyordu Ağlıyor sandım, gülümsüyordu Devrimi haykırıyordu Etrafında...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Phoenix Altınay']::text[], 8.5, '{"poet":"Gökhan Phoenix Altınay","poet_slug":"gokhan-phoenix-altinay","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/55-dk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur', 'ne-olur-misat-bektas-a4snc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kirk yilda bir sansim gülmüs yüzüme,

Cok görme bu sevinci bana ne olur,

Gömülürse benligim yine hüzüne,

Mutluluk ömrümce bir hayal olur.

Sevmek ümit kaynagim hasret ucurum ,

Beni ellerinle itme ne olur,

Senden ayrilirsam ben kahrolürüm,

Dünyayi basima yima ne olur.

Sevgiye gönülden inaniyorsan,

Iste mutluluga giden yol budur,

Gözlerin kapanip kalbin durmadan,

Bu yoldan geriye dönme ne olur.', 'Kirk yilda bir sansim gülmüs yüzüme, Cok görme bu sevinci bana ne olur, Gömülürse benligim yine hüzüne, Mutluluk ömrümce bir hayal olur. Sev...', ARRAY['Türk Edebiyatı','Şiir','Mişat Bektas']::text[], 8.5, '{"poet":"Mişat Bektas","poet_slug":"misat-bektas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ne-olur-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çanakkale Hatırası', 'canakkale-hatirasi-i-lhan-yuksel-yhqmw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Agamemnon rahibine esir 

Truvada unuttuğum şu sır 

Doğranan bebeğe kırk üç asır 

Geçti hatti hitaya yanarım 

Agamemnonun hatırasına 

Çanakkale de kadırgasına 

Adını koyup geldi baskına 

Kanayan şu yaraya yanarım 

Düzerken firavuna methiye 

Uzak durduğum Moğol Çinliye 

Japon hindli kızılderiliye 

Kaybettiğim kıtaya yanarım 

Sümer hitayın kitabesine 

Hattuşilinin hitabesine 

Turanın kayıp alfabesine 

Oğuzun hatıraya yanarım 

Yıkık nagazaki Hiroşima 

Bana ne dedim geldi başıma 

Esir Afrikalı gardaşıma 

İslediğim hataya yanarım 

Yaydılar merne putun neslini 

Bozdular bitki otun neslini 

Karıştırıp saf atın neslini 

Katıra kardeş taya yanarım', 'Agamemnon rahibine esir  Truvada unuttuğum şu sır  Doğranan bebeğe kırk üç asır  Geçti hatti hitaya yanarım  Agamemnonun hatırasına  Çanakka...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/canakkale-hatirasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçerden Çıkan Adam', 'i-cerden-cikan-adam-yusuf-hayaloglu-kh3b9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçerden çıkacak birazdan adam

Yılların tortusu çökmüş yüzüne

Alnını güneşe serecek adam

Uykusuz ranzalar suskun voltalar

Geride kalacak ve ah hüzünle

Bir gül gibi savrulup gülecek adam

Kar yağmıştır sardunyanın üstüne

Anılar toza toza bulanmıştır

Kitaplar sobada yanmış

Ah sazlar duvarda kalmış

Güzelim şarkılar yağmalanmıştır

İçerden çıkacak birazdan adam

Yıpranmış bavulu hantal sesiyle

Kendini yollara vuracak adam

Yüz çeviren DOSTLAR sinsi tavırlar

Açığa çıkacak ve ah kendiyle

Bir ince hesabı görecek adam

Susamıştır TEBESSÜMÜN seyrine

Saçları hiçbirgün okşanmamıştır

Bir İHTİLAL kadar yalnız

Ah vefanız kadar yanlış

Mümkünse farzedin YAŞAMAMIŞTIR', 'İçerden çıkacak birazdan adam Yılların tortusu çökmüş yüzüne Alnını güneşe serecek adam Uykusuz ranzalar suskun voltalar Geride kalacak ve a...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Hayaloğlu']::text[], 8.5, '{"poet":"Yusuf Hayaloğlu","poet_slug":"yusuf-hayaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/icerden-cikan-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MH-01 Karbasan''ın Güneşi (Manzum Hikaye)', 'mh-01-karbasan-in-gunesi-manzum-hikaye-mustafa-nadi-tascioglu-95i32', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '24 Kasım Öğretmenler Günü münasebetiyle

                bütün öğretmenlerimize...

Köy muhtarı ünledi “Hey köylüler toplanın! 

Güzel haberlerim var, haydi biraz canlanın

Kaymakam beyimizin yanından geliyorum

Kaymakam bey sözünü tutacak biliyorum

Bu yıl bizim köye de bir okul yapılacak

Bizim de geleceğe yolumuz açılacak”

Muhtarın bu sözleri tastamam doğru idi

O ay atılan temel okulun temeliydi

Köylü devlet elele çalıştılar imece

Çarçabuk bitti okul Ağustos’a gelince

Kaymakam gelip köye bitmiş okulu gezdi

Köylünün gözlerinde bir nurlu ışık sezdi

Dedi ki; “Bir ay sonra bir öğretmen gelecek

Onun için kalacak bir de ev gerekecek”

Muhtar girdi araya dedi ki; “Kaymakam bey, 

Biz o işi hallettik, gelsin tek öğretmen bey”

Köylüler arasında konuşmalar başladı

Yapılan konuşmayı kaymakam anlamadı

Dedi ki; “Konu nedir? Bu köylünün derdi ne? 

Derman olunacaksa, önce derdi biline”

Muhtar; “Beyim dert yoktur, öğretmen gelsin hele”

Ve köylüye dönerek; “Gelen meledir, mele! ”

“Bu mele de kim ola” diye sordu kaymakam

“Mele, öğretmen demek” dedi ordan bir adam

Kaymakam öğretmene ayrılan evi gördü

Önce bir miktar evi sonra muhtarı övdü

Sonraki ay içinde köye geldi bir adam

Gelişinde tanımak mümkün değildi tozdan

Elindeki vâlizle yorulmuştu besbelli

Görünüşte bir yere gidiyordu temelli

Meydanda toplu duran köylülere yürüdü

Yürüme değildi bu, ayakları sürüdü

Erişince meydana dedi; “Selâm Aleyküm

Ben buraya atanan öğretmen Hasan Türk’üm”

Muhtar koşup gelerek sarıldı ellerine

“Hoş geldin” dedi önce, sonra köylülerine

“Çok şükür gardaşlarım, gün doğdu Karbasan’a

Haydi hoş geldin deyin şimdi Mele Hasan’a”

Köylü çabuk alıştı bu gelen öğretmene

Mele Hasan başladı köylüyü eğitmeye

Meydan Mele Hasan’ın ilk dersânesi oldu

Köylünün büyükleri bu dersâneye doldu

Dedi ki; ”Siz büyükler bilmeli bazı şeyi

Sonra biz küçüklere öğretiriz her şeyi

Kin, cehâlet, tembellik en büyük düşman bize

Bu benim de burada ilk dersim olsun size

Önce sevgi, hep sevgi, herkese sevgi verin

İlgiyi ve saygıyı, sevgiye katıp verin

Çocukların ışığı sizin bu ilginizle

Sonra da okuldaki düzenli dersimizle

Parlayıp güneş gibi ufkumuzu saracak

Bizdeki karanlıklar onlarla ışıyacak

Sakın siz çocukları okuldan gevşetecek

Sonra da cehâletin çukuruna itecek

Hareketler yapmayın ve sözlerden sakının

Okula önem verin, ciddi tâvır takının

Biz de bu çocuklara okulu sevdirelim

Onlara aydınlığın ipucunu verelim”

Mele Hasan hep böyle dersler verdi köylüye

İyiye kanat gerdi, yol vermedi kötüye

Yeni bir ufka doğru yürüyorken Karbasan

Köylülerin gönlünde büyüdü Mele Hasan

Zor zamanlarda gelip kapısını çaldılar

Dar zamanda toplanıp, fikrini danıştılar

Ne zaman bir dert olsa dediler ki; ”Sakın Ha! 

Mele’ye danışmadan kendince bir iş yapma

O bizim ışığımız, dostumuz, gururumuz

Mele olmazsa eğer doğruyu zor buluruz

Mele’ye iyi bakın, üzmeyin incitmeyin

Cehâleti burada bir daha diriltmeyin”

Okulda çocuklara babadır Mele Hasan

Dertliye ve garibe anadır Mele Hasan

Hem öğretir onlara bilmediği her şeyi

Hem kana kana verir gözleriyle sevgiyi

Bir köye bir öğretmen belki de azdı ama

Yorgunluk uğramadı o yıl Mele Hasan’a

Her çocuk için özel bir alâka gösterdi

Emeği yıl bitmeden meyvelerini verdi

Tüm çocuklar okuyor ve hesap yapıyordu

Yüzlerce Mele Hasan yârına bakıyordu

Analar ve babalar, çocuklara kızmıyor

“Mele Hasan duyarsa o çok üzülür” diyor

Çocuklar Mele Hasan üzülmesin diyerek

Haylazlığı bırakıp, yanlışlığı iterek

İyi, doğru, güzel ve sevgiye uçuyordu

Mele Hasan’la köyde çiçekler açıyordu

Köy bir yılda değişmiş, iş ve verim artmıştı

Çalışmayana herkes kötü kötü bakmıştı

Köy çevresi emekle ve ağaçla donandı

Her ağaçta Mele’nin elinin izi vardı

Okulun çevresiyse, bir cennet köşesiydi

Okul çocukların ve Mele’nin neşesiydi

O yıl da böyle geçti, hep tohumlar ekerek

Her eve bir ışık ve gül ağacı dikerek

Yeni yılla beraber kötü haberler geldi

Söylendi ki; ”Eşkiya dağlardan düze indi

Köy basarmış bölücü, meleleri kahpece

Vurur olmuş köylerde, hem gündüz hem de gece”

Köylüye korku düştü, korku cana değildi

Silahlar kuşanılıp, eşkiyaya çevrildi

Ya eşkıya gelir de Mele’ye uzanırsa

Işıklar heder olur, karanlık kazanırsa

Kurşunlar bize gelsin, Mele’ye değmesin tek

O bizim ışığımız, ışısın sonsuza dek

Günler güne eklendi, böyle bir endişeyle

Köyde çocuklar bile gülmez oldu neşeyle

Sonra o uğursuz gün geldi bilmem ne diye

Bir kahpe geldi köye “Kamyon devrildi” diye

Mele Hasan atladı, yola doğru fırladı

Arkasından o kahpe silah birden patladı

Mele yere düşmüştü düşerken de ölmüştü

Kahpe soyu durarak baş ucunda gülmüştü

O anda yeri göğü kapladı silah sesi

Kahpenin boğazında kaldı son pis nefesi

İlk duyulan muhtarın o acıklı sesiydi

Ağlayan onun değil, tüm köylünün sesiydi

“Mele Hasan öldü anam, Mele Hasan öldü

Dostlar ışığımız söndü, Mele Hasan öldü”

Mele Hasan’ı köyün meydanına gömdüler

Mezar taşına “MELE BİR GÜNEŞTİ” yazdılar', '24 Kasım Öğretmenler Günü münasebetiyle                 bütün öğretmenlerimize... Köy muhtarı ünledi “Hey köylüler toplanın!  Güzel haberler...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Nadi Taşçıoğlu']::text[], 8.5, '{"poet":"Mustafa Nadi Taşçıoğlu","poet_slug":"mustafa-nadi-tascioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":122,"source_url":"https://www.antoloji.com/mh-01-karbasan-in-gunesi-manzum-hikaye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
