INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnönüler', 'i-nonuler-fazil-husnu-daglarca-0h5n3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '- Savunan yurt.

Susamis, analara, ogullara, kizlara kardesim,

Su,

Susamis vakte.

Durmaz biz dursak bile vatanda,

Otlarin kurusu,

Ekinlerin yasi hiç.

Kurmus mu diyorsun ölümümüz,

Daha büyük bir ölüme pusu,

Kelime-i sahadetlerle yükselen daglarda?

Ahaca birikmis yüzlerce yil,

Arzusu

Bu toprakta yasayan seylerin.', '- Savunan yurt. Susamis, analara, ogullara, kizlara kardesim, Su, Susamis vakte. Durmaz biz dursak bile vatanda, Otlarin kurusu, Ekinlerin y...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/inonuler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık Yapı', 'karanlik-yapi-fazil-husnu-daglarca-mwcoq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vurmus daglara daglara isigi

Belli olmus uzagi yitmisliginden

Düsünür bizi

Gece asagida

Üstlerden büyür samanyolu

Bir sevgiye benzer

Baska bir sevgiye benzerken

Gece asagida

Bagislar öldürmüsü

Çalani yalan soyleyeni kaçani

Topraga çig düsmeden

Gece asagida

Bir eski savas alaninda korkunç

Bir ayrilikta upuzun

Neler soyunur neler

Gece asagida

Nice yorgun olursa olsun yercek

Yükünden yesilinden

Uyutur böçegi otu

Gece asagida

Bu nedir bulamiyorum

Yildizlar yildiz

Gökyüzü gök

Gece asagida

Hani yapilar vardir

Tas tas doldurur boslugu

Öylece duvarlari örer

Gece asagida

Susma

Dinleme gerek

Iletine güne tohumu

Gece asagida

Bakma

Anlama gerek

Azalir biraz simdi

Gece asagida

Kisi yerin dibine dek çirilçiplak

Basarisiz uykusuz

Ama bir umut verir

Gece asagida', 'Vurmus daglara daglara isigi Belli olmus uzagi yitmisliginden Düsünür bizi Gece asagida Üstlerden büyür samanyolu Bir sevgiye benzer Baska b...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/karanlik-yapi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızılırmak Kıyıları', 'kizilirmak-kiyilari-fazil-husnu-daglarca-v1m3j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kardaş, senin dediklerin yok,

Halay çekilen toprak bu toprak değil.

Çık hele Anadoluya,

Kamyonlarla gel, kağnılarla gel gayrı,

O kadar uzak değil.

Çamı bitmiş, kavağı azalmış,

Gamla örtülü bayırlar, çıplak değil.

Yedi ay kıştan sonra,

Yeşeren senin yaşamındır,

Yaprak değil.

Yersin, içersin sofrasından, üç yüz senedir,

Kuvvetlisin ama kuvvet hak değil.

Bakımsızlıklarla göçüp gitmiş bir cihan,

Mevsimler soğumuş, sular azalmış,

Buğday, Selçuklulardan kalan başak değil.

Parça parça yarılmış öküz ardında,

Parmağı üç pare, tırnağı ak değil.

Utanır elin ayağın,

Korkarsın yakından görsen,

Eli el değil, ayağı ayak değil.

Gün doğar, tarla kuşları uçuşurlar,

Ağır bir aydınlık, bildiğin şafak değil.

Öyle dalmış ki yüzyıllar süren uykusuna,

Uyandırmazsan,

Uyanacak değil.

Dertle, sefaletle yüklü,

Siyah leşlerle kararmış, berrak değil.

Çağlayan ne,

Akan kim,

Kızılırmak değil.

Kardaş, görmüyorum ama hala duyabiliyorum,

Geçmiş zamanlar gelecek zamanlardan parlak değil.

Vakte şahadet edercesine yükselmiş,

Akşam parıltısından, bütün zaferler üzerine,

Dağlar dalgalanmakta, bayrak değil.', 'Kardaş, senin dediklerin yok, Halay çekilen toprak bu toprak değil. Çık hele Anadoluya, Kamyonlarla gel, kağnılarla gel gayrı, O kadar uzak ...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kizilirmak-kiyilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuluğun Korkusu', 'korkulugun-korkusu-fazil-husnu-daglarca-57eie', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen korkutursun

Küçücük kuslari

Bahçelerde sabahtan aksama dek

Ama gelince kocaman gökler geceleyin

Üstüne dogru

Senin korktugunu duyarim.', 'Sen korkutursun Küçücük kuslari Bahçelerde sabahtan aksama dek Ama gelince kocaman gökler geceleyin Üstüne dogru Senin korktugunu duyarim....', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/korkulugun-korkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldürdügümüz', 'oldurdugumuz-fazil-husnu-daglarca-mh5am', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geceyle parlayan gözleri vardi,

Cesurdu, cesurdu ziyade.

Nasil ki çekti bizi,

Istifade.

Karanlik magaranin kapisinda durduk,

Geçerken biraktik tasi.

Sustu büyük bagirmasinda,

Gecelerin ve ormanlarin sirdasi.

Artik bizim gibi degil,

Su içmez, kimildamaz.

Uyanikligi hiç yok,

Uykusu az.

Öyle garip ve öyle sade,

Süsler yapacagiz süslerinden.

Tüyleri gibi aydinlik,

Ve bir sey görmeyen.

Hazir, etrafin düsmanliginda,

Zaferin bitmez tükenmez yemegi.

Aklimizin, korkumuzun, ellerimizin,

Beraber yiyecegi !', 'Geceyle parlayan gözleri vardi, Cesurdu, cesurdu ziyade. Nasil ki çekti bizi, Istifade. Karanlik magaranin kapisinda durduk, Geçerken birakt...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oldurdugumuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Samsun''dan Ankara''ya', 'samsun-dan-ankara-ya-fazil-husnu-daglarca-9zjdq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '- Ordunun silahlari alinmis 

ve alinmakta

Atim acindan hasta, çalmislar kilicimi,

Üsürüm.

Içimde silah sesleri,

Sabaha kadar, tövbe tövbe,

Gecelerle dövüsürüm.

Kabzelerim vardi paril paril,

Altin elmas.

Getirmistim ta Orta Asyadan,

Ta bati Avrupa hayran olmustu,

Kalmis agirliklarinca avuçlarimda yas.

Hepsi bir baska biçimdeydi,

Ama kardesti tüfekle yay.

Onlarla yasamam hizlanirdi,

Duyulurdu suyun ekmegin lezzeti daha hos,

Daha kolay.

Çalmislar kilicimi,

Vaktim bir atesle kizillasir önce.

Sonra tarihler tarihler döger içimizdekileri,

O kadar hafif, o kadar yalin,

Kilinç olur düsünce.', '- Ordunun silahlari alinmis  ve alinmakta Atim acindan hasta, çalmislar kilicimi, Üsürüm. Içimde silah sesleri, Sabaha kadar, tövbe tövbe, G...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/samsun-dan-ankara-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-fazil-husnu-daglarca-do0s5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kisi seni severse

Soyunur aya karsi

Sever

Ölüsüne dek', 'Kisi seni severse Soyunur aya karsi Sever Ölüsüne dek...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/seni-sevmek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simgelerde Yüzler', 'simgelerde-yuzler-fazil-husnu-daglarca-ti2o9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir isik üstünde gelir

Gelir o

Isirsin

Seversin yeri gögü

Uyanmis tutsaklar çagrisina dek.

Dolar da

Dolar da yüregine tohumlarin davranisi

Uzarsin

Bir anidan bir gelecege gövermiscene.

Gelir de bir uykusuza su

Gelir bir orman uyanik yellerden.

Gider hele

Yildizlarin

Gider hele göllerin yalnizligi

Kalirsiniz

Yaptiklarinizla yüz yüze, çirilçiplak.

Almistiniz

Vurmustunuz

Ovalar basak çogalimiyla doluydu,

Derelerde vardi bilinmez anilarin gücü

Agaçlarin yemisleri sizin agirliginizdaydi,

Çalmistiniz

Öldürmüstünüz çünkü.

Bir sorgu günü degil anlamak günü

Gözleriniz açilsa

Maviden

Açik kalsa agziniz kandan simdi

Sizi bagislamaz yeralti otlari bile

Almaz yilan uykulari bile düslerinizi sizin

Siz dikeysiniz, siz hamsiniz.

Simdi ne siz varsiniz, ne o, ne oteki,

Yaban yesili ev yesilini kovmustur.

Yine issiz

Yeryüzü gökyüzü,

Yine issiz

Ölüler unutulmus gider

Ölülerin ardindan bir köpek gider.

Kopmuscasina sen simdi

Karanligin, yoklugun ardinda sen

Bitersin yerden göge;

Upuzun

Egri uzun

Dar uzun.

Gider o

Gider

Gider bir isik üstünde.', 'Bir isik üstünde gelir Gelir o Isirsin Seversin yeri gögü Uyanmis tutsaklar çagrisina dek. Dolar da Dolar da yüregine tohumlarin davranisi U...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/simgelerde-yuzler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akdeniz Şiirleri', 'akdeniz-siirleri-fazil-husnu-daglarca-i56el', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen Deniz Gök,

Bir an dursanız uykuda

Büyür bir yosun geceye karşı.

Tedirgin olur ölüler

Bir an yaslansanız karanlığa,

Sen Deniz Gök.

---------------------

Dalarım engine

Ki yaşadığım

Anladığımdr.

Roma''yla Kartaca''nın arasında

Yüzer, sevgi sevgi

İstanbul.

Böler bir kuş düsüncemi ikiye

Maviden

Yarıda kalır içki.

---------------------

Dersin ki

Ellerimize değecek

Yıldızlar

Büyüyecek büyüyecek de.

Dersin ki

Bir aydınlığı var

Sevgililer için,

Karanlık sessiz de.

Dersin ki

Uyuyamıyorum

Yalnızız

Gece, mavi de.

---------------------

Sessizdi yeryüzü

Yeryüzünde bircik Akdeniz vardı

Akdenizde

Yalnız ikimiz.

Beni seviyor musun dedim,

Yumdu gözlerini uzaklığa,

Tam sorulacak an, diye gülümsedi,

Tam sorulacak yer.

---------------------

Bir kocaman yeşil bir kocaman boz

Yellerde

Çarpar birbirine çarpar enginlere dek.

Dalgaların ucunda yıldızların ucu

Her köpük bir fırtına

Her köpük bir evren.

Su deniz su gök gizlenebilir

Seni sevdiğim

Gizlenemez.

---------------------

Havaya da yalıma da ağaca da benzer ama

En çok suya benzer

Sevgimiz.

Morluğun acısı var sonu yok

Karışır yaşamımıza

Kendiliğinden.

Herkes ölünce toprak olurmuş

Hayır hayır

Bizim su olacağımız besbelli.

---------------------

Akdeniz enginlerde kararmaktadır

Ama

Ben

Öyle maviyim ki.

Akdeniz bir gitmişlikle eski, uzak,

Ama

Ben

Sahibi gibiyim yıldızların.

Akdeniz seni bir daha yaratamaz

Ama

Ben

Seni bir daha sevebilirim.

---------------------

Deli gibi bir gürültu, ansızın,

Yırtılırcasına yarılır sessizlik,

Düşünür Akdeniz.

İşte uçaklar geçer havalarından

Kalır mavilik üstünde apak izleri,

Akdeniz anlar ve sever.

---------------------

Denizdir,

Her aksam üstü

Bütün düşüncelerde

Gelip gider.

Senin le

Acısı

Uzunluğu

Aksi.

Ve gece yarısıdır bu masmavi şey,

Senin

Uzaklarda

Unuttuğun sessizlik.

---------------------

Duymuştun

Bu türküyü

Çok eskiden de.

Bu türküyle anılarsın yelden

Yeşilden

Kadırgaların dibindeki sessiz yosunları.

Bu Akdeniz dalgalarında bu türküde sen

Varsın ışıl ışıl

Ve yoksun biraz.

---------------------

İyice düşün bu bütün yaşamamızdır.', 'Sen Deniz Gök, Bir an dursanız uykuda Büyür bir yosun geceye karşı. Tedirgin olur ölüler Bir an yaslansanız karanlığa, Sen Deniz Gök. ------...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":103,"source_url":"https://www.antoloji.com/akdeniz-siirleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sivaslı Karınca', 'sivasli-karinca-fazil-husnu-daglarca-r50f8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Koca Kizilirmak köpüre köpüre

Akiyordu,

Bir telgraf diregi dibinde,

Zamanlar kadar telassiz ve köpüksüz,

Yürüyordu,

Sivasli bir karinca.

Karsi kiyidan parlak,

Kisniyordu,

Atlar doru doru,

Atlarin sarkisindan ayrilmis,

Yürüyordu,

Atlarin mesafesini anlamaz.

Sesi, adimlarinin sesi, memnun ve bahtiyar,

Duyuluyordu,

Kahraman.

Bir açligin ayaklarinca aziz,

Yürüyordu

Yeryüzünden.

Rahat gidisinden belli,

Biliyordu,

Dagi, suyu, otlari, lezzetle.

Baska karincalardan kopmus,

Yürüyordu,

Baska karincalara.

Gayretle, çalismakla, yorulmazlikla,

Benziyordu,

Afrika''dakine, Çin''dekine, Paris''tekine,

Kara topragin alni üstünde, kara,

Yürüyordu,

Alin yazisindan daha hür.

Yoktu fikirlerden, davalardan haberi,

Yürümüyordu,

Rüyasi hiç.

Bugday tanesi üzre,

Yürüyordu,

Sivasli bir karinca.', 'Koca Kizilirmak köpüre köpüre Akiyordu, Bir telgraf diregi dibinde, Zamanlar kadar telassiz ve köpüksüz, Yürüyordu, Sivasli bir karinca. Kar...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sivasli-karinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sular Bizden Akıllıdır', 'sular-bizden-akillidir-fazil-husnu-daglarca-nkk2x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sular bizden akillidir, daha evvel görür aksami,

Iner havadan önce, karanliga,

Büyük bir balik gibi ortadan silinir,

Kaçisirken hayvanlar daga.

Sular bizden akillidir, memnun olur,

Sadece agaçlardan.

Baska insanlardan degil,

Bizi yalniz birakan.

Sular bizden akillidir, uyumaz,

Açar mavilige, iri gözlerini.

Ve bekler bir ölüm sirri içinde,

Kendi hayatinin yerini.', 'Sular bizden akillidir, daha evvel görür aksami, Iner havadan önce, karanliga, Büyük bir balik gibi ortadan silinir, Kaçisirken hayvanlar da...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sular-bizden-akillidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tenha', 'tenha-fazil-husnu-daglarca-pgsn2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben ölecegim, kimse seyretmesin,

Günes ve düsünceler içinde.

Soyunacagim elbiselerden ve hatiralardan,

Bir semalar sessizliginde.

Asude ve mahzun ellerimle,

Nasibimi bir kenara birakip.

Eski sarkilar söylerken,

Daglarda atesler yakip.

Kimse seyretmesin, ask ve sonsuzluk,

Garip mezarliklar -arasindan gidecegim.-

Kokulu sularla yikanarak

Karanliklarda zevk edecegim.', 'Ben ölecegim, kimse seyretmesin, Günes ve düsünceler içinde. Soyunacagim elbiselerden ve hatiralardan, Bir semalar sessizliginde. Asude ve m...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tenha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenilen Büyür', 'yenilen-buyur-fazil-husnu-daglarca-yqpx6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte karanlik büyümüstür,

Dag daha dag

Su daha su

Yildiz daha yildiz olmustur ötelerde.

İşte karanlik büyümüstür,

Ellerin

Ayaklarin

Soluklarin karasi,

Göklere, göklerin karasina karismistir kocaman.

İşte karanlik büyümüstür,

Yarali atlarin kisnemeleri

Geri çekilen toplarin gicirtisiyla büyümüstür yusyuvarlak.

Uzaklarda

İzmirden çok uzaklarda

İşte karanlik büyümüstür,

İşte gözlerini örtmüstür yenilen.', 'İşte karanlik büyümüstür, Dag daha dag Su daha su Yildiz daha yildiz olmustur ötelerde. İşte karanlik büyümüstür, Ellerin Ayaklarin Soluklar...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yenilen-buyur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Parıltısı', 'zaman-pariltisi-fazil-husnu-daglarca-cfrvy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlıklarda, gündüzlerin arkasındayım,

Bitmiş ikinci dünya savaşı, uğursuz ve kahraman

Uzakta esir uluslar türkü söyler,

Türklüğümün farkındayım.

Bir soluk gelmekte karşı gezegenlerden,

Vakt içinden inmektedir gölgeler.

Toprak üzerinde, atmosferler üzerinde

Soğuyan gecemin farkındayım.

Biçimler, evlere, eşyalara rahatça sığmış,

Var olmuş var olmayan.

Biçimler sonsuzluğa yaklaşmıs,

Aklımın farkındayım.

Ne ağaçlar uzanmış mevsimlerimce

Ne yıldızlar gerçek, aydınlığım kadar.

Aşkla kımıldayan küçücük ışıklar uçuşur içimde yön yön,

Yaşadığımı farkındayım.', 'Karanlıklarda, gündüzlerin arkasındayım, Bitmiş ikinci dünya savaşı, uğursuz ve kahraman Uzakta esir uluslar türkü söyler, Türklüğümün farkı...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/zaman-pariltisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahret', 'ahret-ziya-osman-saba-vaxvk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu garip dünyada ben yadırgadım yerimi...

Yıllardan sonra gir gün, görüp çektiklerimi,

Tanrım bir meleğine emredecek: ''Yetişir!''

Gözlerimi o saat sessiz kapayacağım.

Beni bekleyedursun bir köşede yatağım;

Bütün yorgunluğumu alacak bir teneşir.

Bir yükü atmış gibi içimde bir hafiflik,

Oraya geçmek için aşacağım bir eşik,

Bir lâhza tutacağım bana uzanan eli.

Bir el gözlerimdeki perdeyi sıyıracak.

Onları bulacağım... Ve annem şaşıracak:.

''Oğlum! Ne kadar da büyümüş ben görmeyeli', 'Bu garip dünyada ben yadırgadım yerimi... Yıllardan sonra gir gün, görüp çektiklerimi, Tanrım bir meleğine emredecek: ''Yetişir!'' Gözlerimi o...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ahret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Yaşamak İçin', 'artik-yasamak-i-cin-ziya-osman-saba-mbraa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Artık yaşamak için herkesten kaçacağız,

Dünya bize verecek yalnız güzellikleri,

Yalnız, semalarından dökecek ruhumuza,

Geceler mehtapları ve gündüzler seheri

Düşünceli yürürken, bir yol dönemecinde

Çıkacak ömrümüze beyaz dallarla bahar.

Hatırlatacak bize sen çocukluğumuzu,

Erguvanlı bir bahçe, mor salkımlı bir duvar.

Tekrar yaşayacağız ümitli sabahları,

Bulacağız dünyanın o en güzel yerini.

Ebedi bir sahilde yeniden tadacağız

Kol kola sükûn dolu akşam gezmelerini...', 'Artık yaşamak için herkesten kaçacağız, Dünya bize verecek yalnız güzellikleri, Yalnız, semalarından dökecek ruhumuza, Geceler mehtapları ve...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/artik-yasamak-icin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baharı Beklerken Yazılmış Şiir', 'bahari-beklerken-yazilmis-siir-ziya-osman-saba-ggqrg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O günü görmek için sade bekleyeceğiz,

Göreceğiz bir sabah yeşil tomurcukları.

Hazırlanıyor gibi, gökyüzü, ufuk, deniz,

Bir sabah dökülecek baharların baharı.

Bu bahar yalnız mesut günler taşımaktadır,

Başbaşa kalacağız kenarında bir suyun,

Göz alabildiğine yeşil uzanan çayır,

Bir saadet içinde sessiz otlayan koyun.

Bu bahar güleceğiz en içten bir sevinçle,

Bir melek ordan bize uzatacak elini.

-Beni bırakma kalbim, kalbim sen bana söyle.

Ümitlerin en güzelini!..', 'O günü görmek için sade bekleyeceğiz, Göreceğiz bir sabah yeşil tomurcukları. Hazırlanıyor gibi, gökyüzü, ufuk, deniz, Bir sabah dökülecek b...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bahari-beklerken-yazilmis-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben De', 'ben-de-ziya-osman-saba-zx69h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne çok anlatacaklarınız var

Birbirimize nişanlılar!

Ben de bir zamanlar sizin kadar mesuttum,

Ben de şu parkın sıralarında oturdum,

Ümid ettim, hayal kurdum...

Şahit bütün ömrüme bu şehir, bütün yurdum.

Ben de o mektepte okurdum

Küçük mektepli!

Bugün gibi hatiramda

İlk gün, ilk ders, ilk hece.

Şiirler yazmak için öğrendiğim güzel Türkçe.

Yeni kitaplarım, siyah göğüslüğüm,

Sevinçle dolup taşardı gönlüm.

Beri yanda günler akar giderdi.

Benim de bir anne üstüme titrer

Bir baba benimle iftihar ederdi.', 'Ne çok anlatacaklarınız var Birbirimize nişanlılar! Ben de bir zamanlar sizin kadar mesuttum, Ben de şu parkın sıralarında oturdum, Ümid ett...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Ev', 'beyaz-ev-ziya-osman-saba-zghlz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerimin önünde hep aynı beyaz ev.

Her dağ yamacına kurduğum,

Beliren her su kenarında,

Pembe damlı, yeşil pancurlu, balkonlu,

Balkonuna tırmanan sarmaşık.

Gece, pencerelerinden sızacak ışık,

Kışın tütecek bacası.

Kapıyı ittiğinde çalacak bir çıngırak.

-Duyuyorum o sesi şimdiden, berrak-

Geçecegim yol, çıkacağım üç basamak,

Ellerinden sıyırıp atacağım eldiven,

Her halin, gülüşün, kokun, bütün ruhunla sen!

Ah, bütün bir ömür bırakmayacağım el,

Okşayacağım saç, dinleyeceğim ses,

Bakmakla doymayacağım yüz...

Açık pancurlardan o gün dolacak gündüz,

O günkü hava,

Bir kapıyı açman, dolaşman sofada.

Şaşıracağım: Böyle gezinen kim?

-Evim! Evim!.. Ellerimle asacağım

Camlarına perdelerini.

Yatak odasında düsüneceğiz bir an

İki kişilik karyolanın yerini...

Yatak odamız, yemek odaşi, kiler

Raflarında ellerinle yapılmış reçeller.

Karşı karşıya oturacağımız sofra,

Sürahide ışıldayan su,

Yazın, rüzgâra koyacağımız testi;

Senin yatacağın öğle uykusu...

Sararacak bir yandan çardaktaki üzümler,

Kâh esecek rüzgâr, kâh dinleyeceğiz yağmuru,

Kâh karlarla bembeyaz kesilecek çimenler.

Hep geçireceğiz içimizden:

Hayat beraber, ölüm beraber...

Şu göklerin altında,

Olacağız o kadar bahtiyar

Ki çıkıp mezarlarından annemiz, babamız da,

Beyaz evimize yerleşecekler,

Uzun kış geceleri onlar da aramızda

Göz göze bakışacak, mangalı exsecekler...', 'Gözlerimin önünde hep aynı beyaz ev. Her dağ yamacına kurduğum, Beliren her su kenarında, Pembe damlı, yeşil pancurlu, balkonlu, Balkonuna t...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/beyaz-ev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemiyorum', 'bilemiyorum-ziya-osman-saba-ntlfi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilemiyorum yıllardır neredeyim? 

Hergün yediğim ekmek, susayıp içtiğim su,

Kolundan tutup gitmek istediğim kadın,

Yaşamak kaygısı, gök hasreti, ölüm korkusu,

Ve Rabbim senin adın! 

Yıllar var ki içindeyim hayatın.

Anıyorum gençliğimi, özlüyorum çocukluğumu,

Fakat bilemiyorum yarını.

Bilemiyorum Rabbim, maksadını, kararını.

Hepimiz işte dünyadayız,

Yataktaki hastamız, topraktaki ölümüz; 

Neyiz, ne olacağız? 

Bir şey bilmiyorum... Nefes almaktayım yalnız.

Rabbim! beni yaratmışsın,

İnsan şeklinde görünüyorum,

Terlerim yazın, üşürüm kışın,

Düşünüyorum, düşünüyorum...', 'Bilemiyorum yıllardır neredeyim?  Hergün yediğim ekmek, susayıp içtiğim su, Kolundan tutup gitmek istediğim kadın, Yaşamak kaygısı, gök hasr...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bilemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Oda, Bir Saat Sesi', 'bir-oda-bir-saat-sesi-ziya-osman-saba-rrcmh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir oda, içinde bir saat sesi

Hayatın sırtımdan giden pençesi,

Ve beni maziye götüren bir el,

Eski günlerimiz, sessiz ve güzel...

Bulduğum kayıplar, her günkü yerin,

İşte konsol, ayna, köşe minderin,

Seccaden, tesbihin, namaz başörtün.

Bir şey değişmemiş, sanki daha dün.

Yine ortancalar altı camının,

Dışarda sükûnu yaz akşamının,

Bahçemiz sulanmış, ıslak her çiçek.

Kapı çalınacak, babam gelecek...', 'Bir oda, içinde bir saat sesi Hayatın sırtımdan giden pençesi, Ve beni maziye götüren bir el, Eski günlerimiz, sessiz ve güzel... Bulduğum k...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-oda-bir-saat-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ölünün Arkasından', 'bir-olunun-arkasindan-ziya-osman-saba-wje7y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey ölü, az daha yaşatmak isterdim seni,

Habersiz bırakıp gittiğin evde.

Giysen hazır duran terliklerini,

Odalarda dolaşsan, öksürsen

Toplasan bu yaz da bahçende yemişleri,

Az daha ömür sürsen.

Gözlerimin önünde hep boyun bosun,

Nasıl girerdin şu kapıdan, memnun

Şu iskemleye otururdun.

Avuçlarımda, ılık, el sıkışın,

Bana bakışın...

Nasıl uzatırdın bana şu sürahiyi?

Seyrederdik uçan bulutları, geçen gemileri.

Nasıl son defa konuştun, son defa güldün?

Nasıl öldün?..

Nasıl öldü, Yarabbim, nasil öleceğiz?

Hangi sonsuz geceler, iklimler geçeceğiz,

Bundan sonra da bir gün aynı sofrada

Oturacak mıyız bir daha!..', 'Ey ölü, az daha yaşatmak isterdim seni, Habersiz bırakıp gittiğin evde. Giysen hazır duran terliklerini, Odalarda dolaşsan, öksürsen Toplasa...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-olunun-arkasindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sokakta Giderken', 'bir-sokakta-giderken-ziya-osman-saba-dl8nz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Taşında otlar biten şu sokakta yürümek.

Bir bahçe duvarının kokulu gölgesinden.

Uzakta, mektepteyken okuduğumuz şarkı.

Su içmek o tasasız günlerin çeşmesinden.

Kalbe aşina bütün rastladıklarım,

Herşey eskisi gibi, herkes bahtiyar, iyi!

Bana büyük babamı hatırlatan ihtiyar,

Çocukluk arkadaşım sarı benekli kedi

Bütün günahlarımı affetmiş sanki Tanrım,

Duyuyorum kalbimde tadılmamış sevgiyi.

Ah, sade koşmak, koşmak istiyorum içimden:

Aradığım diyara bu yol çıkacak gibi', 'Taşında otlar biten şu sokakta yürümek. Bir bahçe duvarının kokulu gölgesinden. Uzakta, mektepteyken okuduğumuz şarkı. Su içmek o tasasız gü...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bir-sokakta-giderken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Rüzgar', 'bu-ruzgar-ziya-osman-saba-pns55', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu rüzgar her vakit böyle esmeyecek.

Gökte bulut, suda yelken, dalda çiçek.

Bir gün, bir gün var ki, günden güne gerçek,

Çatır çatır servi, çıtır çıtır böcek.

- Çek ciğerlerine, bir nefes daha çek,

Bu rüzgar her vakit böyle esmeyecek.', 'Bu rüzgar her vakit böyle esmeyecek. Gökte bulut, suda yelken, dalda çiçek. Bir gün, bir gün var ki, günden güne gerçek, Çatır çatır servi, ...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bu-ruzgar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz', 'guz-ziya-osman-saba-bvkpp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çiçeğin rengi soldu, bitti şarkısı kuşun

yol tenha, dal mecalsiz, su durgun

tabut yapılan tahta, ev ev taşınan odun

bahar, ümit yerine; ey kış, içimde korkun

ben artık korkmuyorum, her şeyde bir hikmet var

gecenin sonu seher, kışın sonunda bahar

belki de bir bahçeyi müjdeliyor şu duvar

birer ağaç altında sevgilimiz, annemiz

gece değmemiş sema, dalga bilmeyen deniz

en güzel, en bahtiyar, en aydınlık, en temiz

ümitler içindeyim, çok şükür öleceğiz

insanlar.. ne sonuncusu, ne de ilki

çoluğu, çocuğu, erkeği, dişisi

şu sokaklardaki, taşıtlardaki, pencerelerdeki

azametli, dalkavuk, hiddetli sinsi

ordular: insanlardan.. geçtikleri yerde ot bitmeyen

ev bark yıkan, pusu kuran, hak yiyen

insanlar kurt, insanlar fil, insanlar tilki

açmayan gül, ötmeyen bülbül, yeşermeyen sevgi 

bir ümit dünyasında hepimiz

nereden gelir, nereye gideriz

gün gelir, hatırlamak bile bir acı olur

gençlik aşkı, sevinci, daha dünkü ümidi

yumruklasan göğsünü bir boş yankı duyulur

gün gelir, en gür çeşmeler damla damla kurur

bakarsın, bir yazın ağaçlarında şimdi

üç beş kuru yaprak çırpınır durur

şu garip yeryüzünde anlaşılmaz ömrümüz

gelip yanıbaşıma boynunu büken öksüz

evladı gitmiş ana, siyah yeldirmeli dul

son kalan eşyasını mezada veren yoksul

fakirin iç çekişi, zenginlerin usancı

gurbete düşmüş yolcu, yolcu bekleyen hancı

şu anda yeraltına günahıyla gömülen

büyük tımarhanede kahkahalarla gülen

ölü, ölü yıkayıcı, hasta, hastabakıcı

allahım, cümlemize acı

patik yap kunduracı, bol bol patik

bebeler için, ilk adımı atacak

çocuklar için, koşacak oynayacak

terzi abla, mini mini elbise dik

yazlık, kışlık, mevsimlik

saçlarına kurdela, bileklerine bilezik

ama şu dünya hali, bin türlü kaza, bela

ama bunca hastalık, gıdasızlık, verem

tabutçu, ölçünü büyük tut, büyük

çocukların öldüğünü istemem', 'çiçeğin rengi soldu, bitti şarkısı kuşun yol tenha, dal mecalsiz, su durgun tabut yapılan tahta, ev ev taşınan odun bahar, ümit yerine; ey k...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/guz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Akşamki Yolumda', 'her-aksamki-yolumda-ziya-osman-saba-d958l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her akşamki yoluma koyulmuş gidiyorum.

Her akşamdan vücudum bu akşam daha yorgun.

Öyle istiyorum ki bu akşam biraz sükûn,

Bir cami eşiğine yatıversem diyorum

-Rabbim, şuracıkta sen bari gözlerimi yum!

Sen, bana en son kalan, ben senin en son kulun;

Bu akşam, artık seni anmayan İstanbulun

Bomboş bir camiinde uyumak istiyorum.

Sonsuz sessizliğini dinlemek istiyorum.

Bilirim ki taşlığın bir dösek kadar ılık,

Sana az daha yakın yaşamak için artık,

Rabbim, ben yalnxiz zeytin ve ekmek istiyorum.', 'Her akşamki yoluma koyulmuş gidiyorum. Her akşamdan vücudum bu akşam daha yorgun. Öyle istiyorum ki bu akşam biraz sükûn, Bir cami eşiğine y...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-aksamki-yolumda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansız Tesadüfler', 'i-mkansiz-tesadufler-ziya-osman-saba-iesap', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Cahit Sıtkı Tarancı''ya-

Susamis, analara, ogullara, kizlara kardesim,

Su,

Susamis vakte.

Şimdi çıkıverecek karşıma arkadaşım,

Mektebe gitmek için geçtiğimiz şu yoldan.

Babam tok sesiyle birden çağıracak: ''Ziya!''

Kalbimde eski sevinç, dallarda eski bahar.

Gözlerimi kapatıp: ''Bil?'' diyecek birisi.

Bir mahşer ortasinda şaşırıp kalacağım.

Ve girecek koluma bir melek gibi karim.

Saracak etrafımı doğmamış çocuklarım', 'Cahit Sıtkı Tarancı''ya- Susamis, analara, ogullara, kizlara kardesim, Su, Susamis vakte. Şimdi çıkıverecek karşıma arkadaşım, Mektebe gitmek...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/imkansiz-tesadufler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İyilik', 'i-yilik-ziya-osman-saba-uemb8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-Yaşar Nabi''ye-

Sabah... Ah şükrederek çıkmak geceden.

Ayak bastığım kıyı, yeniden doğuş.

Sabah, beliren evim, bahçeler ve sen,

Henüz uyuyan dallar, havalanan kuş.

Bu sabah bilmiyorum bu kırlar nere?

Çamlardan çimenlere dökülen sükûn.

Geçen ömrümü bana söyleyen dere,

Sessizce yaşamayı öğreten koyun.

Bir yol başlıyor gibi, ümitli, rahat.

Tanrim! bu sabah içim senin eserin:

İyilik, teselliler, merhamet, şevkat...

İçimde bir sabahın, o kadar serin.

Bilinmez sevgililerle yıkanan göğüs.

İyilik... Ürperisi vücutta ruhun.

İyilik... Beyaz koyun, gülümseyen yüz,

Şu bahar, mavi gökler, yemyeşil sükûn.

Bu sabah gözlerimle okşadıklarım,

Herşey, bütün tabiat, ağaçlar, dere,

Ey bütün sevdiklerim ve sen ey Tanrım!

Titrek elleri öpmek, kapanmak yerlere...', '-Yaşar Nabi''ye- Sabah... Ah şükrederek çıkmak geceden. Ayak bastığım kıyı, yeniden doğuş. Sabah, beliren evim, bahçeler ve sen, Henüz uyuyan...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/iyilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurban', 'kurban-ziya-osman-saba-mutsc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanrım, sonsuz dünyada ben âcım ve ufağım,

Kulların arasinda Tanrım ben bir koyunum.

İki tuğla halinde kenetlenmiş dudağım,

Sonra geçtiğim yollar kum, hep kum, daim kum.

Aradığım pınardan içebilsem bir yudum.

Artık o günden sonra hiç susmayacağım.

İnecek gözlerime uzun, en rahat uykum.

Tuz çalınıp ağzıma, bağlanınca ayağım.

Kulların arasında ben yaşadım sessizce,

Hiç ağzımı açmadım, verdim bütün yünümü.

En geniş bir sabahı düşünerek her gece,

Ben, Tanrım, şuracıkta bekliyorum günümü.', 'Tanrım, sonsuz dünyada ben âcım ve ufağım, Kulların arasinda Tanrım ben bir koyunum. İki tuğla halinde kenetlenmiş dudağım, Sonra geçtiğim y...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kurban-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misakımilli Sokağı No.37', 'misakimilli-sokagi-no-37-ziya-osman-saba-pj489', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah, şimdi hatıralar mahallesinde

Misakımilli sokak No.37

Orası bütün evler, bütün ömür içinde,

Mesut olduğumuz evdi.

Talihin bir gün karşımıza çıkardığı.

Elele döşediğimiz bir çift küçük odası.

Ne diyeyim bilmem ki:

Gönül sarayı, aşk yuvası...

Akşamlar iner ''kaymak yoğurt''çularla

Kaldırımlar benim için gölgelenirdi.

Saatler ilerler bozacılarla,

Derken bir komşu seslenirdi.

Pencerelerimizden biri komşu arsaya bakar,

Ötekinin önünde bir havagazı feneri;

Rüzgarla açılıp kapanırdı ışığı,

Geceleri...

O geceler, doğan günler orada,

Kaderlerin en güzelini ördü.

Misakımilli sokağı No.37,

Çocuğum orada dünyayı gördü.

Misakımilli sokağı! Senin

Esen rüzgar, yağan karını sevdim.

Camın önüne her oturuşta seyrettiğim,

Arnavut kaldırımlarını sevdim.

Bir çocukluk oyunu mu oynadık orada?

Sen gelin olmuştun, ben güvey.

Sen öyle güzel; ben daha genç,

Yepyeni, taptazeydi her şey.

Ne zaman o sokağa yolum düşse şimdi,

Ayaklarım geri geri gider.

Evler cansızdır elbet, insanlar vefasız,

Komşumuz başkalarına komşuluk eder.

Yabancı perdeler aşılmış penceresi,

Bir vakitler içinde çocuğumun oturdügu.

-Yeni kiracılar evlatsız besbelli-

Sımdi birkaç saksının durduğu.

Söz birliği etmiş şimdi saksılar, perdeler,

Elektrik lambasıyla değiştirilen fener.

O sokağa ne zaman yolum düşse, bir ses:

Günler gecti, gecti, gecti... xder.', 'Ah, şimdi hatıralar mahallesinde Misakımilli sokak No.37 Orası bütün evler, bütün ömür içinde, Mesut olduğumuz evdi. Talihin bir gün karşımı...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/misakimilli-sokagi-no-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Anmazsın', 'nasil-anmazsin-ziya-osman-saba-zhcbp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasil anmazsın o çocukluk günlerini!

Dalda bülbülü vardı, gökte beyaz bulutu.

Annem vardı, babam vardı.

Bahçemizde, ılık, uzayan günlerdi yaz,

Bir beyaz âlemdi kış.

Başkaydı günesi, böyle değildi ayı.

Artık istemiyorum yaşamayı!

Bir gün ver bana Tanrım,

Ta çocukluğumdan kalmış...', 'Nasil anmazsın o çocukluk günlerini! Dalda bülbülü vardı, gökte beyaz bulutu. Annem vardı, babam vardı. Bahçemizde, ılık, uzayan günlerdi ya...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/nasil-anmazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Oldu', 'ne-oldu-ziya-osman-saba-ytfhb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Odamız kararırken indirdiğin perdeler,

-Çarşının gittikçe artan gürültüsü-

Gelip kenarına oturduğun minder,

Genç kızken işlediğin masa örtüsü,

Yeşil abajurlu lambamız,

Küçük sobamız,

Anlatsanız,

Ne oldu o geceler, eski akşamlarımız?

Beyaz elbiseler giydiğin zamanlar...

Niçin yazmadık bir yere satır satır,

Duvarlar! ne oldu konuştuklarımız?

Yüzünün pembeliği, saçlarının örgüsü.

Ben diyeyim: Kış şarkısı; sen de: Yaz türküsü.

Ne ettik ömrümüzü..', 'Odamız kararırken indirdiğin perdeler, -Çarşının gittikçe artan gürültüsü- Gelip kenarına oturduğun minder, Genç kızken işlediğin masa örtüs...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüler', 'oluler-ziya-osman-saba-z1xjs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ölüler, ölüler nerelerdesiniz?

Ölüler, bir bilinmez yerdesiniz.

Artık gündüzleriniz gece,

Bütün günleriniz: dün.

Artık her sözünüz sükût,

Her işaretiniz gizli.

Tutuyoruz nasihatlerinizi...

Ölüler, ölüler her yerdesiniz!

Ne zaman aynaya baksam,

Görünüveriyor babam...

Bahçem, odam, sofam,

Nereye geçsem, nereye çıksam;

Hâtıram!

Her yerde sizden bir eser.

Gökyüzünde bir bulut

Bıraktığınız sesler

Yakın güneşe, aya.

Dokunabilsem oraya,

Kiminiz konuşacak,

Kiminiz gülecek,

Eski günler gelecek.

Ölüler bilebilsem gittiğiniz yeri,

Ruhum, muradına erecek;

Annem döşeğimi serecek,

Toprağınız toprağım,

Aranızda yatacağım.', 'Ölüler, ölüler nerelerdesiniz? Ölüler, bir bilinmez yerdesiniz. Artık gündüzleriniz gece, Bütün günleriniz: dün. Artık her sözünüz sükût, He...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/oluler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rabbim, Nihayet Sana', 'rabbim-nihayet-sana-ziya-osman-saba-g75yq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rabbim, nihayet sana itaat edeceğiz...

Artik ne kin, ne haset, ne de yaşamak hırsı,

Belki her sabah vakti, belki gece yarısı,

Artık nefes almayı bırakıp gideceğiz...

Ben artık korkmuyorum, herşeyde bir hikmet var

Gecenin sonu seher, kışın sonunda bahar.

Belki de bir bahçeyi müjdeliyor şu duvar,

Birer ağaç altında sevgilimiz, annemiz.

Gece değmemiş sema, dalga bilmeyen deniz,

En güzel, en bahtiyar, en aydınlık, en temiz

Ümitler içindeyim, çok sükür öleceğiz...', 'Rabbim, nihayet sana itaat edeceğiz... Artik ne kin, ne haset, ne de yaşamak hırsı, Belki her sabah vakti, belki gece yarısı, Artık nefes al...', ARRAY['Türk Edebiyatı','Şiir','Ziya Osman Saba']::text[], 8.5, '{"poet":"Ziya Osman Saba","poet_slug":"ziya-osman-saba","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/rabbim-nihayet-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Memet Daha', 'bir-memet-daha-fazil-husnu-daglarca-61kqk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Topraktan mı çıktı yarı toprak bir yaratık,

Gökten mi indi yarı gök bir kartal.

Bir Memet daha var oldu o sıra,

Tepenin doruğunda kalpağı al.

Bir Memet olduğu besbelli,

Saçları başakta, gözleri çiçekte.

Elleri ayakları öylesine kocaman,

Yüzü altı Memet''in yüzüne öylesine benzemekte.

Vardı üç adimda masalcana,

Ağzı duman tüten makineliye, dev.

Kabzeyi kavrar kavramaz bastı tetiğe

Fışkırdı namludan sonsuz bir alev.

Allah Allah, şaştı bütün dağlar, bütün gök,

Şaştı dost düşman.

Bu kimdir, bu kaçıncı Memet''tir,

Ölülerde dirilerde dondu kan.

Görsen efsane, görmesen efsane,

Duysan efsane.

Uzak mıdır bayraktan düşen,

Yakın mıdır ne?

Bir parıltı bir parıltı tarihten,

Tanrıca dik.

Yurdun ulusun kutsal gücü,

Bu yedinci Memet, Memetcik.', 'Topraktan mı çıktı yarı toprak bir yaratık, Gökten mi indi yarı gök bir kartal. Bir Memet daha var oldu o sıra, Tepenin doruğunda kalpağı al...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-memet-daha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Eller miydi', 'bu-eller-miydi-fazil-husnu-daglarca-qowbj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu eller miydi masallar arasından

Rüyalara uzattığım bu eller miydi.

Arzu dolu, yaşamak dolu,

Bu eller miydi resimleri tutarken uyuyan.

Bilyaların aydınlık dünyacıkları

Bu eller miydi hayatı o dünyaların.

Altın bir oyun gibi eserdi

Altın tüylerinden mevsimin rüzgarı.

Topraktan evler yapan bu eller miydi

Ki şimdi değmekte toprak olan evlere.

El işi vazifelerin önünde

Tırnaklarını yiyerek düşünmek ne iyiydi.

Kaybolmus o çizgilerden

Falcının saadet dedikleri.

O köylü çakısının kestiği yer

Söğüt dallarından düdük yaparken...

Bu eller miydi kesen mavi serçeyi

Birkaç damla kan ki zafer ve kahramanlık.

Yorganın altına saklanarak

Bu eller miydi sevmeyen geceyi.

Ayrılmış sevgili oyuncaklardan

Kırmış küçücük şişelerini.

Ve her şeyden ve her şeyden sonra

Bu eller miydi Allaha açılan !', 'Bu eller miydi masallar arasından Rüyalara uzattığım bu eller miydi. Arzu dolu, yaşamak dolu, Bu eller miydi resimleri tutarken uyuyan. Bily...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Dağlarca']::text[], 8.5, '{"poet":"Fazıl Hüsnü Dağlarca","poet_slug":"fazil-husnu-daglarca","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-eller-miydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız Ölüm', 'zamansiz-olum-sairhan-zubeyir-bayrakdar-4zcsb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni sevdiğimi o kadar çok şeylerle

anlatmak istedim ki ama bunu sana anlatamadım

dilim varmadı tutuldu sanki bir an

ama şimdi sen bunun farkında değilsin

ve biranda bıraktın beni zamansız

sence bu zamansız ölüm değil mi

sen beni zamansız öldürdün

arkandan kalleş gibi vurdun

sence bu aşk mı sevgi mi söyle bana', 'seni sevdiğimi o kadar çok şeylerle anlatmak istedim ki ama bunu sana anlatamadım dilim varmadı tutuldu sanki bir an ama şimdi sen bunun far...', ARRAY['Türk Edebiyatı','Şiir','Şairhan Zübeyir Bayrakdar']::text[], 8.5, '{"poet":"Şairhan Zübeyir Bayrakdar","poet_slug":"sairhan-zubeyir-bayrakdar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/zamansiz-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nakarat', 'nakarat-sairhan-zubeyir-bayrakdar-wnvbh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir güneş doğuyor,dağların ardından

yakıyor aşkın yürekleri yaktığı gibi yeri

bir güneş doğuyor,dağların ardından 

kızıllaşıyor elveda der gibi

yağmur yağıyor bulutlardan

bir bebeğin gözyaşları gibi

şimsek bir gürültü ile çakıyor

annesin uzak kalmış bebenin ağlaması gibi

bahçelerde gül vardı kokuyordu

yarimin mis kokulu saçları gibi

yarim ağlar dağların ardında

yolverin,verin bana yol ey yüce dağlar', 'bir güneş doğuyor,dağların ardından yakıyor aşkın yürekleri yaktığı gibi yeri bir güneş doğuyor,dağların ardından  kızıllaşıyor elveda der g...', ARRAY['Türk Edebiyatı','Şiir','Şairhan Zübeyir Bayrakdar']::text[], 8.5, '{"poet":"Şairhan Zübeyir Bayrakdar","poet_slug":"sairhan-zubeyir-bayrakdar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nakarat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'onur', 'onur-sairhan-zubeyir-bayrakdar-gma99', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'seni seviyorum sen sevmesende

ben seni istiyorum sen istemesende

sen benimsin benim olacaksın

sen benim ONUR''umsun

bu şiir sana ey sevgili arkadasım onur', 'seni seviyorum sen sevmesende ben seni istiyorum sen istemesende sen benimsin benim olacaksın sen benim ONUR''umsun bu şiir sana ey sevgili a...', ARRAY['Türk Edebiyatı','Şiir','Şairhan Zübeyir Bayrakdar']::text[], 8.5, '{"poet":"Şairhan Zübeyir Bayrakdar","poet_slug":"sairhan-zubeyir-bayrakdar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/onur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-mine-yavas-6d38l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir an bir rüya gördüm

Aşk, sevgi diye birşey vardı,

Kimsede görülmemiş, yalansız,

Sahte olmayan ama,

Birden bire bir uyandım ki,

Herşey gerçektede olmayan,

Sadece masallarda, filmlerde ve

Rüyalarda olan birşeymiş, aslı olmayan.

Bir an için gerçek sandım fakat,

Neyseki, dedikleri gibi gerçektede yokmuş....', 'Bir an bir rüya gördüm Aşk, sevgi diye birşey vardı, Kimsede görülmemiş, yalansız, Sahte olmayan ama, Birden bire bir uyandım ki, Herşey ger...', ARRAY['Türk Edebiyatı','Şiir','Mine Yavaş']::text[], 8.5, '{"poet":"Mine Yavaş","poet_slug":"mine-yavas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ruya-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özlüyorum', 'seni-ozluyorum-eylul-demiray-bpjlz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bi şiir yazmak istiyorum ...

bu senin şiirin olsun .

şuan yüreğimden sıcacık süzülüp gelen bi arzu bu.

düşünüyorum ne yazmalıyım diye...!

ona hislerimi nasıl anlatmalıyım?

ama bak seni anımsayınca,

yanaklarımdan süzülen damlalar anlatıyor.

karanlık geceler anlatıyor ; 

beni kollarına verdiğin,soğuk karanlık geceler...

daha kış bitmeden,yalancı sıcaklara aldanıp,

sevgiyle, özveriyle açan

küçücük badem ve zerdali çiçekleri anlatıyor.

evet! küçücük beyaz,pembe çiçekler...

zulmün üstesinden gelmenin gururuyla ,

meydan okudukları karlar altından gülümseyen

o güzelim badem ve zerdali çiçekleri...

kardelenlerin eşsizliğini de unutmuyorum bu arada.

sokakta, yürekleri birbirine sevgiyle kenetlenmiş

gözleri ışıl ışıl,pembe yanaklı

oynayan çocukların çığlıkları anlatıyor.

sabahları beni uyandırmaya gelen,

dünyanın en tatlı kadınının

sıcacık,uyan kızım,diyen tatlı sesi anlatıyor.

bak tatlım dinle! dinlediğim şarkı anlatıyor.

çalan sazın sesinin güzelliği anlatıyor.

bir inanç uğruna verilen kavga anlatıyor.

görüyorsunya, işte!

bu durumda bana tek şey yapmak kalıyor;

seni özlediğimi yazmak...

evet sevgili insan,bu yazdığımı hiç unutma!

   seni özlüyorum.....', 'bi şiir yazmak istiyorum ... bu senin şiirin olsun . şuan yüreğimden sıcacık süzülüp gelen bi arzu bu. düşünüyorum ne yazmalıyım diye...! on...', ARRAY['Türk Edebiyatı','Şiir','Eylül Demiray']::text[], 8.5, '{"poet":"Eylül Demiray","poet_slug":"eylul-demiray","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/seni-ozluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mum', 'mum-ozdemir-asaf-98bxm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'MUM

Mum yanıyor, zaman yanıyordu..

Bir tarafındakiler gülüyor,

Bir tarafındakiler ağlıyordu.

Biri vardı aralarında.

Düşünüyor, hayata bakıyordu.

Mum yanıyor, zaman yanıyordu

Erzurumun köylerinde.

Akşamın ve sabahın erken olduğu

Ali Baba dağının eteklerinde

Geniş vakitler yaşanıyordu.

Mum yanıyor, zaman yanıyordu

Hasankale ovasında.

Geceye karşıydı karlı Palandökenler.

Bir adam vardı hayallerin ortasında..

Kar kadar beyazdı ümidler.

Bu adam üç bin on beşde

Yunan medeniyetini okuyordu.

Kaldırıp başını kitaplardan

Kervanlaşmış dağlara bakıyordu..

Bakınca akşam oluyordu.

Hasankale ovasında, Kuruderede

Kilometreler santimleşiyor,

Santimler asırlaşıyordu..

Güneşe ve geceye karşıydı karlı Palandökenler.

O adam hayata bakıyordu.

Bir tarafta ağlayanlar, bir tarafta gülenler..

Bir tarafta bunlar için ölenler..

Mum yanıyor, zaman yanıyordu.

Mumun alevi titreyor,

Umudun alevi titremiyordu.', 'MUM Mum yanıyor, zaman yanıyordu.. Bir tarafındakiler gülüyor, Bir tarafındakiler ağlıyordu. Biri vardı aralarında. Düşünüyor, hayata bakıyo...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/mum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bir Sonbahar', 'eski-bir-sonbahar-huseyin-nihal-atsiz-bwu9a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sonbahardı... Seninle geçiyorduk o yoldan; 

Topraklardan, havadan bir hüzün taşıyordu

                 Bize yaklaşıyordu

Gönlümüzde yepyeni bir duygu yaşıyordu.

Rüzgarların değildi bu musiki, bu hüzün; 

Hatırladın değil mi? Kuşlar ağlaşıyordu...

Havada bir serinlik... Tatlı bir hayal gibi...

Toprak nasıl meçhuldü tıpkı istikbal gibi? 

O gün tabiat başka bir türlü yaşıyordu.

Kalbin acı, gözlerin yaşla dolmuştu senin; 

Yapraklar gibi yere dökülüyordu enin; 

O nağme mesafeyi, zamanı aşıyordu.

O bir beste değildi: Kuşlar ağlaşıyordu.

En hazin şey muhakkak öksüz kalan ocaktır.

Bu ocak hüzünlerle dolup boşalacaktır.

Eski bir sonbaharı, küçük kuşları anmak

Belki veda etmektir sana birkaç satırla...

Yine bir sonbaharda ordan yalnız geçersen

Beraber geçtiğimiz serin günü hatırla! ..', 'Sonbahardı... Seninle geçiyorduk o yoldan;  Topraklardan, havadan bir hüzün taşıyordu                  Bize yaklaşıyordu Gönlümüzde yepyeni ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Nihal Atsız']::text[], 8.5, '{"poet":"Hüseyin Nihal Atsız","poet_slug":"huseyin-nihal-atsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/eski-bir-sonbahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazar', 'nazar-zehra-ozpay-6yby5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana sevgili olmak, 

Nazar boncuğu gibi 

İlişti düşlerime, 

Çıkarıp atsam 

Nazara geliyorum, 

Birlikte yatsam 

Yanıyorum.. 

Sana yar olmak, 

Gökkuşağı gibi, 

Serap gibi, 

Uzansam dokunamıyorum, 

Seni alnıma yazamıyorum', 'Sana sevgili olmak,  Nazar boncuğu gibi  İlişti düşlerime,  Çıkarıp atsam  Nazara geliyorum,  Birlikte yatsam  Yanıyorum..  Sana yar olmak, ...', ARRAY['Türk Edebiyatı','Şiir','Zehra Özpay']::text[], 8.5, '{"poet":"Zehra Özpay","poet_slug":"zehra-ozpay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Türk Gençliğine', 'butun-turk-gencligine-huseyin-nihal-atsiz-ym11g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I

Yer bulmasın gönlünde ne ihtiras, ne haset.

Sen bütün varlığınla yurdumuzun malısın.

Sen bir insan değilsin; ne kemiksin ne de et;

Tunçtan bir heykel gibi ebedi kalmalısın.

Iztırap çek inleme... Ses çıkarmadan aşın.

Bir damlacık aksa da bir acizdir göz yaşın;

Yarı yolda ölse de en yürekten yoldaşın,

Tek başına dileğe doğru at salmalısın.

Ezilmekten çekinme ... Gerilemekten sakın!

İradenle olmalı bütün uzaklar yakın,

Dolu dizgin yaparken ülküne doğru akın,

Ateşe atılmalı, denize dalmalısın.

Ölümlerden sakınma, meyus olmaktan utan!

Bir kere düşün nedir seni dünyada tutan?

Mefkuresinden başka her varlığı unutan,

Kahramanlar gibi sen ebedi kalmalısın...

						  

II

Sen ne elde ve dilde gezen billur bir sağrak,

Ne de sıska bir göğse takılan bir çiçeksin;

Seninde bu dünyada nasibin var savaşmak!...

Kayalarla güreşip dağlarda öleceksin.

Yoldaşlık ederekten gökte güneşle, ayla,

Aşarsın tepe, ırmak; yürürsün ova ,yayla...

Hayata ne biçimde geldinse bir borayla 

Daha sert bir kasırga içinde biteceksin.

KIZIL ELMA uğruna kılıç çekince kından,

Bahtiyarlık denen şey artık geçmez yakından.

Mesut olup gülmeyi sök, çıkar hatırından.

Belki öldükten sonra bir parça güleceksin.

Yüz paralık kurşunla gider “HAYAT” dediğin;

“ Tanrı yolu” uzaktır; erken kalk sıkı giyin.

Yazık, bütün ömrünce o kadar özlediğin 

Güzel Kızıl Elma’na varmadan öleceksin.

						

III

Belki bir gün çöllerde kaybedersin eşini,

Belki bir gün ağlarsın kaçtı diye karına.

Işıksız kulübende boranın esişini

Dinleyerek çıkarsın bir ümitsiz yarına.

Gün olur ki mertliğin uğrar kahpe bir hınca;

Namert bir el arkandan seni vurur kadınca;

Bir gün sabrın tükenir... Silahını kapınca 

Haykırarak çıkarsın yurdunun dağlarına...

Hayatın kamçısıyla sızar derinden kanlar,

Senin büyük derdinden başkaları ne anlar?

Vicdanını  “Paris”e, “Moskova”ya satanlar,

Küfür diye bakarlar senin dualarına.

Hey arkadaş!.. Bu yolda bende coşkun bir selim,

Beraberiz seninle, işte elinde elim.

Seninle bu hayatın gel beraber gülelim,

Ölümüne , gamına, tipisine, karına...

						

IV

Atandan kalmış olan kılıcı iyi bile,

Onu bütün gücünle vuracaksın çağında.

Savaş... Bunu tadını ey Türk sen bulamazsın,

Ne  sevgili yanında, ne baba ocağında...

Savaşmaktan kaçınır, kim varsa alnı kara,

Kan dökmeyi bilenler hükmeder topraklara...

Kazanmanın sırrını bilmiyorsan git, ara

“Çanakkale” ufkunda, “Sakarya” toprağında.

Siyasette muhabbet... Hepsi yalan, palavra...

Doğru sözü “Kül Tegin” kitabesinde ara...

Lenin’den bahsederse karşında bir maskara,

Bir tebessüm belirsin sadece dudağında.

Yatağında ölmeyi hatırından sök, çıkar!

Döşeğin kara toprak, yorganındır belki kar...

Sen gurbette kalırsan, ben ölürsem ne çıkar?

Ruhlarımız buluşur elbet “Tanrıdağı”nda...

					           

V

Mukadderat isterse seni  yoldan çevirsin ,

Sen hele bu yollarda yıpranarak aşın da,

Varsın bütün ömrünce bir an nasip olmasın,

Yorgunluğu gidermek serin bir su başında.

Bir gülüşten ne çıkar, ne çıkar  ağlamaktan?

Kullar kancıklık eder, bela bulursun Hak’tan.

Gün olur ki bir yudum su ararsın bataktan,

Gün olur ki bir tutam tuz bulunmaz aşında.

Bir çığ gibi yürürsün bir lahza durmaksızın,

Bir ilahi kaynaktan geliyor çünkü hızın.

Duyguların ölmüştür... Tapınılan bir kızın,

Bir füsun bulamazsın gözlerinde, kaşında.

Iztırabı kanına kat da göz kırpmadan iç!

Varsın gülsün ardından, ne çıkar, bir iki piç...

Bu varlık dünyasında yalnız senin hiç mi hiç,

Bir şeyin olmayacak hatta mezar taşında....', 'I Yer bulmasın gönlünde ne ihtiras, ne haset. Sen bütün varlığınla yurdumuzun malısın. Sen bir insan değilsin; ne kemiksin ne de et; Tunçtan...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Nihal Atsız']::text[], 8.5, '{"poet":"Hüseyin Nihal Atsız","poet_slug":"huseyin-nihal-atsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":85,"source_url":"https://www.antoloji.com/butun-turk-gencligine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizliğin Sesi', 'sessizligin-sesi-zehra-ozpay-c67c1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızlığım gölgem 

Gölgem yalnızlığım 

Nefesim yankılanır gibi 

Kapılarda, tablolarda 

Dört yanımda sensizliğim.. 

İtiraf saati geldi çattı bile, 

Dostlarım.. 

Kendimi seçtim 

Bakmaya, dinlemeye, 

Konuşmaya, 

Kendimle.. 

Gözler hüzünlü gibi, 

Hafiften nemli 

Bakışlar, kulak kesilir bazen 

Saatin fısıltısına 

Sakin..... 

Çıt duyulmaz etrafta 

Yalnızca dolaşan ayak sesleri, 

Sessizliğin..', 'Yalnızlığım gölgem  Gölgem yalnızlığım  Nefesim yankılanır gibi  Kapılarda, tablolarda  Dört yanımda sensizliğim..  İtiraf saati geldi çattı...', ARRAY['Türk Edebiyatı','Şiir','Zehra Özpay']::text[], 8.5, '{"poet":"Zehra Özpay","poet_slug":"zehra-ozpay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sessizligin-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlarla Dans', 'yildizlarla-dans-zehra-ozpay-itihk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İşte yeni bir yıldız 

Yeni bir samanyolu 

Sana göz kırpıyor bak 

Yeni bir aşkın 

gelişini müjdeliyor 

Acaba, ele verir mi sırlarımı? 

Hey! Durda dinle! 

Simsiyah dalgaların üzerine indi gece 

Ve hoş bir melodi söylüyor şimdi 

Yakamozların eşliğinde 

Sandallar dansediyor bak! 

Hey, yakışıklı! 

Danseder misin benimle? 

Hiç durmadan, başımız dönünceye dek 

Ve uzansak ıslak kumların üzerine 

Yıldızları seyretsek seninle.. 

İşte, işte bir yıldız kayıyor bak! 

Hadi gözlerini kapat, 

Ellerimden tut ve bir dilek dile..', 'İşte yeni bir yıldız  Yeni bir samanyolu  Sana göz kırpıyor bak  Yeni bir aşkın  gelişini müjdeliyor  Acaba, ele verir mi sırlarımı?  Hey! D...', ARRAY['Türk Edebiyatı','Şiir','Zehra Özpay']::text[], 8.5, '{"poet":"Zehra Özpay","poet_slug":"zehra-ozpay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yildizlarla-dans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma', 'unutma-huseyin-nihal-atsiz-z2tib', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yetmiş gün bir öksüz gibi yaşadın;

Annenin gittiği günü unutma!

Senin için kendini harcayan kadın,

Unutulmaz oğlum, onu unutma...

Mezarı olursa koy birkaç çiçek,

Babanın rüyası olunca gerçek.

İstersen dünyada her şeyden el çek;

Bayrağı, ırkını, dünü unutma!

Anneni konuştur getirip dile;

Anlatsın nasıldı çektiğim çile.

Gurbette tükenip dönmesem bile

Unutma oğlum hiç, beni unutma!

		19 Ağustos 1944', 'Yetmiş gün bir öksüz gibi yaşadın; Annenin gittiği günü unutma! Senin için kendini harcayan kadın, Unutulmaz oğlum, onu unutma... Mezarı olu...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Nihal Atsız']::text[], 8.5, '{"poet":"Hüseyin Nihal Atsız","poet_slug":"huseyin-nihal-atsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unutma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukçada Ben Varım', 'cocukcada-ben-varim-ozdemir-asaf-5hiez', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ÇOCUKÇADA BEN VARIM

Ben böyle yazdım sanma

Ben böyle düşündüm

Başından beri

Sözcükler koşuyordu

Düşünmelerimin ardından

Çocuklar, çocuklar gibi

Bayram yerlerinde

Çocuklar oynuyordu

Düşlerimin içindeki

Bayram yerlerinde

Ben onlara

Hiçbir zaman

Kapalı perdeleri göstermedim

Kapalı kapıları göstermedim

Hiçbirini salıncağa bindirmedim

Sallamadım

Atlı karıncalarda döndürmedim

Onlar gelişi gidiş sandırırlar

Vuruşan otoları seviyorlardı onlar

Çünkü hem gidiyorlardı

Gidiyorken güldürüyorlardı

Kafa kafaya vurduruyorlardı

Gülüyorlardı

Bizi kandırdıkları gibi kandırırlar

Onlar

Yarın oynayacakları oyunu

Oyunun başını sonunu

Bizlerden iyi biliyorlardı.', 'ÇOCUKÇADA BEN VARIM Ben böyle yazdım sanma Ben böyle düşündüm Başından beri Sözcükler koşuyordu Düşünmelerimin ardından Çocuklar, çocuklar g...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/cocukcada-ben-varim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyuş Ve Düşünüş', 'duyus-ve-dusunus-yahya-kemal-beyatli-mwjhr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdiklerim göçüp gidiyorlar birer birer

Ay geçmiyor ki almayayım gamlı bir haber.

Kalbim zaman zaman bu haberlerle burkulu; 

Zihnim düşünceden dağınık, gözlerim dolu.

Kaybetti asrımızda ölüm eski hüznünü,

Lakayd olan muhimsemiyor gamlı bir günü.

Çok şey bilen diyor:''Gidecek her gelen nesil

Ey sade-dil bu bahsi hayatında böyle bil

Hiç durmadan, hayat öğtür devreden bu çark,

Ölmek sırayladır, sıralanmakta varsa fark.

İlmin derin görüşleri, aklın hükümleri

Doldurmuyor boşalmış olan hisli bir yeri', 'Sevdiklerim göçüp gidiyorlar birer birer Ay geçmiyor ki almayayım gamlı bir haber. Kalbim zaman zaman bu haberlerle burkulu;  Zihnim düşünce...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatlı']::text[], 8.5, '{"poet":"Yahya Kemal Beyatlı","poet_slug":"yahya-kemal-beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/duyus-ve-dusunus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak', 'aglamak-ozdemir-asaf-ejdee', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-I-

Ağlamak, 

Unutmak kadar kolaydır inan. 

Sevin ağlayabiliyorsan, 

Sevin ağlıyorsan, 

Gül ağlayabiliyorum diye, 

Gül ağlıyorum, ağlıyorum diye. 

Sana birşey yapamam 

Ağlayamıyorsan... 

-II-

Ağlamak, 

Bazı acılarda yetmez, 

Bazı ölümlere.. 

Örtüsüdür bazı acıların, 

Örter, örtülmez, 

Savunur bir süre. 

Ağlayanlar sevinmeli, 

Sevin ağlıyabiliyorsan, 

Acılar art arda dinmeli.. 

Durur bir nöbetçi gibi, 

Durur bir bekçi gibi, 

Zamana gülmeli - gülmeli.. 

Sevin ağlayabiliyorsan. 

Unutmanın kardeşidir ağlamak. 

Uyur uyanır yatağında duyguların, 

Düşüncenin kucağında, hep çocuktur 

Ağlamak...', '-I- Ağlamak,  Unutmak kadar kolaydır inan.  Sevin ağlayabiliyorsan,  Sevin ağlıyorsan,  Gül ağlayabiliyorum diye,  Gül ağlıyorum, ağlıyorum ...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/aglamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rindlerin Akşamı', 'rindlerin-aksami-yahya-kemal-beyatli-0upl8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dönülmez akşamın ufkundayız.Vakit çok geç; 

Bu son fasıldır ey ömrüm nasıl geçersen geç! 

Cihana bir daha gelmek hayal edilse bile,

Avunmak istemeyiz öyle bir teselliyle.

Geniş kanatları boşlukta simsiyah açılan

Ve arkasında güneş doğmayan büyük kapıdan

Geçince başlayacak bitmeyen sükunlu gece.

Guruba karşı bu son bahçelerde, keyfince,

Ya şevk içinde harab ol, ya aşk içinde gönül! 

Ya lale açmalıdır göğsümüzde yahud gül.', 'Dönülmez akşamın ufkundayız.Vakit çok geç;  Bu son fasıldır ey ömrüm nasıl geçersen geç!  Cihana bir daha gelmek hayal edilse bile, Avunmak ...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatlı']::text[], 8.5, '{"poet":"Yahya Kemal Beyatlı","poet_slug":"yahya-kemal-beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/rindlerin-aksami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Paylaşılmaz', 'yalnizlik-paylasilmaz-ozdemir-asaf-ciu41', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızlık, yaşamda bir an, 

Hep yeniden başlayan..

Dışından anlaşılmaz.

Ya da kocaman bir yalan, 

Kovdukça kovalayan..

Paylaşılmaz.

Bir düşün''de beni sana ayıran

Yalnızlık paylaşılmaz

Paylaşılsa yalnızlık olmaz.', 'Yalnızlık, yaşamda bir an,  Hep yeniden başlayan.. Dışından anlaşılmaz. Ya da kocaman bir yalan,  Kovdukça kovalayan.. Paylaşılmaz. Bir düşü...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalnizlik-paylasilmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Shakespeare''den Shakespeare''e', 'shakespeare-den-shakespeare-e-ozdemir-asaf-cgmss', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok şey var

Olmakla olmamak arasında

Bence bütün ve her şey

Bölmekle çıkarmak arasında

Çokluk ikiye bölerler her şeyi

Toplamakla çarpmak arasında

Ben dörde bölerim her şeyi

Gitmekle kalmak arasında

Bir yokluk, yok olmak

Aldanmakla inanmak arasında

Bir varlık, var olmak

Unutulmakla unutmak arasında

Ben yok oldum kimi zaman

Yok olmamak içindim kimi zaman

Var oldum öyle anlar oldu ki

Var olmamak içindim kimi zaman

Her şey senin yüzünden

Deyip çıkmak vardı aradan

Ama ben bilirdim ki

Benim yüzümdendi de çoğu zaman', 'Çok şey var Olmakla olmamak arasında Bence bütün ve her şey Bölmekle çıkarmak arasında Çokluk ikiye bölerler her şeyi Toplamakla çarpmak ara...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/shakespeare-den-shakespeare-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuslat', 'vuslat-yahya-kemal-beyatli-0q6d9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir uykuyu cananla beraber uyuyanlar, 

Ömrün bütün ikbalini vuslatta duyanlar, 

Bir hazzı tükenmez gece sanmakla zamanı, 

Görmezler ufuklarda şafak söktüğü anı. 

Gördükleri rü''ya,ezeli bahçedir aşka; 

Her mevsimi bir yaz ve esen rüzgarı başka, 

Bülbülden o eğlencede feryad işitilmez, 

Gül solmayı,mehtab azalıp bitmeği bilmez; 

Gök kubbesi her lahza bütün gözlere mavi, 

Zenginler o cennette fakirlerle müsavi; 

Sevdaları hulyalı havuzlarda serinler, 

Sonsuz gibi bir fıskiye ahengini dinler. 

Bir ruh o derin bahçede bir def''a yaşarsa, 

Boynunda onun kolları,koynunda o varsa, 

Dalmışsa,onun saçlarının rayihasiyle. 

Sevmekteki efsunu duyar her nefesiyle; 

Yıldızları boydan boya doğmuş gibi, varlık, 

Bir mu''cize halinde,o gözlerdedir artık; 

Kanmaz en uzun buseye,öptükçe susuzdur. 

Zira susatan zevk o dudaklardaki tuzdur; 

İnsan ne yaratmışsa yaratmıştır o tuzdan, 

Bir sır gibidir az çok ilah olduğumuzdan. 

Onlar ki bu güller tutuşan bahçededirler. 

Bir gün, nereden,hangi tesadüfle gelirler? 

Aşk onları sevk ettiği günlerde,kaderden, 

Rüzgar gibi bir şevk alır oldukları yerden; 

Geldikleri yol... Ömrün ışıktan yoludur o: 

Alemde bir akşam ne semavi koşudur o! 

Dört atlı o gerdune gelirken dolu dizgin, 

Sevmiş iki ruh,ufku görürler daha engin. 

Simaları gittikçe parıldar bu zaferle, 

Gök her tarafından donanır meş''alelerle. 

Bir uykuyu cananla beraber uyuyanlar, 

Varlıkta bütün zevki o cennette duyanlar, 

Dünyayı unutmuş bulunurken o sularda, 

-Zalim saat ihmal edilen vakti çalar da- 

Bir an uyanırlarsa leziz uykularından, 

Baştan başa,her yer kesilir kapkara zindan. 

Bir faciadır böyle bir alemde uyanmak, 

Günden güne hicranla bunalmış gibi yanmak. 

Ey talih! Ölümden de beterdir bu karanlık; 

Ey aşk! O gönüller sana mal oldular artık; 

Ey vuslat! O aşıkları efsununa ram et! 

Ey tatlı ve ulvi gece! Yıllarca devam et!', 'Bir uykuyu cananla beraber uyuyanlar,  Ömrün bütün ikbalini vuslatta duyanlar,  Bir hazzı tükenmez gece sanmakla zamanı,  Görmezler ufuklard...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatlı']::text[], 8.5, '{"poet":"Yahya Kemal Beyatlı","poet_slug":"yahya-kemal-beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/vuslat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süleymaniye''de Bayram Sabahı', 'suleymaniye-de-bayram-sabahi-yahya-kemal-beyatli-k0u6m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Artarak gönlümün aydınlığı her saniyede

Bir mehâbetli sabah oldu Süleymâniye''de

Kendi gök kubbemiz altında bu bayram saati,

Dokuz asrında bütün halkı, bütün memleketi

Yer yer aksettiriyor mavileşen manzaradan,

Kalkıyor tozlu zaman perdesi her an aradan.

Gecenin bitmeye yüz tuttuğu andan beridir,

Duyulan gökte kanat, yerde ayak sesleridir.

Bir geliş var! .. Ne mübârek, ne garîb âlem bu! ..

Hava boydan boya binlerce hayâletle dolu...

Her ufuktan bu geliş eski seferlerdendir; 

O seferlerle açılmış nice yerlerdendir.

Bu sükûnette karıştıkça karanlıkla ışık

Yürüyor, durmadan, insan ve hayâlet karışık; 

Kimi gökten, kimi yerden üşüşüp her kapıya,

Giriyor, birbiri ardınca, ilâhî yapıya.

Tanrının mâbedi her bir tarafından doluyor,

Bu saatlerde Süleymâniye târih oluyor.

Ordu-milletlerin en çok döğüşen, en sarpı

Adamış sevdiği Allah''ına bir böyle yapı.

En güzel mâbedi olsun diye en son dînin

Budur öz şekli hayâl ettiği mîmârînin.

Görebilsin diye sonsuzluğu her yerden iyi,

Seçmiş İstanbul''un ufkunda bu kudsî tepeyi; 

Taşımış harcını gâzîleri, serdârıyle,

Taşı yenmiş nice bin işçisi, mîmâriyle.

Hür ve engin vatanın hem gece, hem gündüzüne,

Uhrevî bir kapı açmış buradan gökyüzüne,

Taa ki geçsin ezelî rahmete ruh orduları..

Bir neferdir, bu zafer mâbedinin mîmârı.

Ulu mâbed! Seni ancak bu sabah anlıyorum; 

Ben de bir vârisin olmakla bugün mağrûrum; 

Bir zaman hendeseden âbide zannettimdi; 

Kubben altında bu cumhûra bakarken şimdi,

Senelerden beri rüyâda görüp özlediğim

Cedlerin mağfiret iklîmine girmiş gibiyim.

Dili bir, gönlü bir, îmânî bir insan yığını

Görüyor varlığının bir yere toplandığını; 

Büyük Allah''ı anarken bir ağızdan herkes

Nice bin dalgalı Tekbîr oluyor tek bir ses; 

Yükselen bir nakaratın büyüyen velvelesi,

Nice tuğlarla karışmış nice bin at yelesi! 

Gördüm ön safta oturmuş nefer esvaplı biri

Dinliyor vecd ile tekrar alınan Tekbîr''i

Ne kadar saf idi sîmâsı bu mü''min neferin! 

Kimdi? Bânisi mi, mîmârı mı ulvî eserin? 

Taa Malazgirt ovasından yürüyen Türkoğlu

Bu nefer miydi? Derin gözleri yaşlarla dolu,

Yüzü dünyâda yiğit yüzlerinin en güzeli,

Çok büyük bir iş görmekle yorulmuş belli; 

Hem büyük yurdu kuran hem koruyan kudretimiz

Her zaman varlığımız, hem kanımız hem etimiz; 

Vatanın hem yaşayan vârisi hem sâhibi o,

Görünür halka bu günlerde teselli gibi o,

Hem bu toprakta bugün, bizde kalan her yerde,

Hem de çoktan beri kaybettiğimiz yerlerde.

Karşı dağlarda tutuşmuş gibi gül bahçeleri,

Koyu bir kırmızılık gökten ayırmakta yeri.

Gökte top sesleri var, belli, derinden derine; 

Belki yüzlerce şehir sesleniyor birbirine.

Çok yakından mı bu sesler, çok uzaklardan mı? 

Üsküdar''dan mı? Hisar''dan mı? Kavaklar''dan mı? 

Bursa''dan, Konya''dan, İzmir''den, uzaktan uzağa,

Çarpıyor birbiri ardınca o dağdan bu dağa; 

Şimdi her merhaleden, taa Bâyezîd''den, Van''dan,

Aynı top sesleri birbir geliyor her yandan.

Ne kadar duygulu, engin ve mübârek bu seher! 

Kadın erkek ve çocuk, gönlü dolanlar, yer yer,

Dinliyor hepsi büyük hâtırâlar rüzgârını,

Çaldıran topları ardınca Mohaç toplarını.

Gökte top sesleri, bir bir, nerelerden geliyor? 

Mutlaka her biri bir başka zaferden geliyor:

Kosova''dan, Niğbolu''dan, Varna''dan, İstanbul''dan..

Anıyor her biri bir vak''ayı heybetle bu an; 

Belgrad''dan mı? Budin, Eğri ve Uyvar''dan mı? 

Son hudutlarda yücelmiş sıra dağlardan mı? 

Deniz ufkunda bu top sesleri nerden geliyor? 

Barbaros, belki, donanmayla seferden geliyor! ..

Adalar''dan mı? Tunus''dan m, Cezayir''den mi? 

Hür ufuklarda donanmış iki yüz pâre gemi

Yeni doğmus aya baktıkları yerden geliyor; 

O mübârek gemiler hangi seherden geliyor? 

Ulu mâbedde karıştım vatanın birliğine.

Çok şükür Allaha, gördüm, bu saatlerde yine

Yaşayanlarla beraber bulunan ervâhı.

Doludur gönlüm ışıklarla bu bayram sabahı.', 'Artarak gönlümün aydınlığı her saniyede Bir mehâbetli sabah oldu Süleymâniye''de Kendi gök kubbemiz altında bu bayram saati, Dokuz asrında bü...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatlı']::text[], 8.5, '{"poet":"Yahya Kemal Beyatlı","poet_slug":"yahya-kemal-beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/suleymaniye-de-bayram-sabahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Macera', 'macera-ozdemir-asaf-t4oq5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben yürümeye başlayınca denizlerin üstünde

Karalarda koşanlar durup bana baktılar.

Ben de gittim

Sığınacağım adaları birer birer batırdım.', 'Ben yürümeye başlayınca denizlerin üstünde Karalarda koşanlar durup bana baktılar. Ben de gittim Sığınacağım adaları birer birer batırdım....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/macera-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlerimiz', 'gunlerimiz-yagmur-atsiz-rozlm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çözülen bir yün yumağı

Akıp giden günlerimiz

Mezar taşlarından suskun

Telaşsız sessiz sitemsiz

Savrulan yapraklar gibi

Akıp giden günlerimiz

Cenaze törenlerinde

Telaşsız sessiz sitemsiz

Bir suçluyu aklar gibi

Akıp giden günlerimiz

Sanki bir sır saklar gibi

Telaşsız sessiz sitemsiz

Doğmayan şafaklar gibi

Akıp giden günlerimiz

Haksız ittifaklar gibi

Akıp giden günlerimiz

Bir kitaba başlar gibi

Koşarken yavaşlar gibi

Düşen arkadaşlar gibi

Akıp giden günlerimiz', 'Çözülen bir yün yumağı Akıp giden günlerimiz Mezar taşlarından suskun Telaşsız sessiz sitemsiz Savrulan yapraklar gibi Akıp giden günlerimiz...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Atsız']::text[], 8.5, '{"poet":"Yağmur Atsız","poet_slug":"yagmur-atsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gunlerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köşeyi Dönenlerin Şarkısı', 'koseyi-donenlerin-sarkisi-yagmur-atsiz-wnvw0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yürekleriniz sızlar mı

güneş körse ve gök sağır

içinizi ısıtanlar

alacalı yıldızlar mı

kimliği belirsizler mi

kurşun sıkan üstünüze

bazen canınız ister mi

hüzünlenmek ağır ağır

bir tutam tuz kattınız mı

tek bir yoksulun aşına

hiç sevgi yarattınız mı

dinsin diye bunca kahır

bir gün el uzattınız mı

bir insana karşılıksız

hiç güzellik tattınız mı

kadeh kadeh satır satır

dönün dönün köşeleri

aydınlıktan karanlığa

bu yıl uğursuzun ama

gün doğmadan neler doğar', 'yürekleriniz sızlar mı güneş körse ve gök sağır içinizi ısıtanlar alacalı yıldızlar mı kimliği belirsizler mi kurşun sıkan üstünüze bazen ca...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Atsız']::text[], 8.5, '{"poet":"Yağmur Atsız","poet_slug":"yagmur-atsiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/koseyi-donenlerin-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Böyle Sevdim', 'i-ste-boyle-sevdim-tolga-duyal-icu6a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bambaşka duygularla sevdim ben seni

O bakışlarındaki güler yüzü sevdim belki

Kimbilir belkide bana uzak oluşunu sevmeyişini beni

Yüreğimin gökyüzüsün sen,öyleki yeri asla dolmaz tıpkı hasret gibi

Bambaşka duygularla sevdim ben seni

Bazen mutluluğum oldun bazen hüznüm,ben oldun bazen

Yaşadım seni,sensiz,isyan edercesine sen varmış gibi

Yüreğimin gökyüzüsün sen,öyleki yeri asla dolmaz tıpkı hasret gibi

Bambaşka duygularla sevdim ben seni

Elimdeki ufacık bir resimle geçirdim gün oldu tüm vaktimi

İşte o zaman şiirler okuyordum sana,senin için olan herşeyi

Yüreğimin gökyüzüsün sen,öyleki yeri asla dolmaz tıpkı hasret gibi

Bambaşka duygularla sevdim ben seni

Güzel olan herşeyi hissettim seni düşünürken ben

Mis kokulu çiçekleri,baharı hissettim daha birçok şeyi

Yüreğimin gökyüzüsün sen,öyleki yeri asla dolmaz tıpkı hasret gibi

Bambaşka duygularla sevdim ben seni

Yeminim var hemde sonuna kadar gerçekçi

Aynen senin güzelliğin gibi,gözyaşları gibi,benim gibi

Yüreğimin gökyüzüsün sen,öyleki yeri asla dolmaz tıpkı hasret gibi', 'Bambaşka duygularla sevdim ben seni O bakışlarındaki güler yüzü sevdim belki Kimbilir belkide bana uzak oluşunu sevmeyişini beni Yüreğimin g...', ARRAY['Türk Edebiyatı','Şiir','Tolga Duyal']::text[], 8.5, '{"poet":"Tolga Duyal","poet_slug":"tolga-duyal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iste-boyle-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Sevdam', 'gizli-sevdam-metin-saydam-vj8zc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'içim aciyor yüregim

Seni goruyorum baktigim her yerde

Kalabaliklar her yerimde insanlar

Yanimda yuzlerce insan,yuzlerce insan var

Gozlerim yine de seni arar

Bakişlarin karsimda,eririm gozlerinde

Yalnizligim,kederim,huznum benim

Içimde gizli yaram

Agliyorum içimden ey gozleri karam

Yuregim oy gizli sevdam

Ateslerde yakanim kanayan yaram

Ne yapsam,nasil anlatsam

Bakişinmi ararim,nefesini duyarim

Simdi,simdi yanimda olsan

Oylece kalsan

O cok sevdigim kokun var ya

Koklasam,koklasam

Basımı,gogsune o en sevdigim 

Yerine yaslasam

Yok yuregim,yok sevdam,yok kanayan yaram

Ne sen varsın,ne de gozlerin

Ben böyle deli gibi seni ozlerim,seni beklerim.

                                                                             16.07.2000', 'içim aciyor yüregim Seni goruyorum baktigim her yerde Kalabaliklar her yerimde insanlar Yanimda yuzlerce insan,yuzlerce insan var Gozlerim y...', ARRAY['Türk Edebiyatı','Şiir','Metin Saydam']::text[], 8.5, '{"poet":"Metin Saydam","poet_slug":"metin-saydam","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gizli-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'itiraf', 'itiraf-tolga-duyal-q05ka', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum desem inanırmısın bana

Hayalini görüyorum desem rüyalarımda

Hiç ummadık bir yerde,ummadık bir zamanda 

O güzel sesin kulağıma fısıldıyor desem

Seni seviyorum desem inanırmısın bana

Kanadı kırık bir kuş misali çırpınıyor yüreğim

Benim için önemi yok artık ne gündüzün ne gecenin

Başkasıyım ben sanki kendim değilim desem

Seni seviyorum desem inanırmısın bana

Gökyüzünün alacakaranlığında da sen varsın ya

Hatta okyanuslar da,dağlarda,uçsuzbucaksız yollarda bile sen

Senin deryan da hergeçengün boğuluyorum desem

Seni seviyorum desem inanırmısın bana

Seni senden fazla seviyorum belkide gülüm

Ekmeği,suyu sever gibi,onlarsız nasıl geçmezse şu ömrüm

Şuna inan ki ama şuna inan sensizde geçmez desem

Seni seviyorum desem inanırmısın bana...', 'Seni seviyorum desem inanırmısın bana Hayalini görüyorum desem rüyalarımda Hiç ummadık bir yerde,ummadık bir zamanda  O güzel sesin kulağıma...', ARRAY['Türk Edebiyatı','Şiir','Tolga Duyal']::text[], 8.5, '{"poet":"Tolga Duyal","poet_slug":"tolga-duyal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/itiraf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Sensizim', 'yine-sensizim-tolga-duyal-7tj17', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bak şimdi yine sensizim şu ilkbahar günün de

Dermansızım ve halsizim odamda yine benle

Seni düşünmek doyasıya artık seni vermiyor ki bana

Bari sen ver yar ne olur çaldığın duyguları tekrar bana

Ne çok isterdim bilirmisin hissetmek şu an o ela gözlerini

Bahar ile bütünleşen,onun kadar temiz ve cıvıl cıvıl yüreğini

Evet yüreğini hissetmek isterdim belki unuturdum o zaman ümitsizliğimi

Çaresizliğimi,sensizliğimi ve seni ne kadar çok özlediğimi', 'Bak şimdi yine sensizim şu ilkbahar günün de Dermansızım ve halsizim odamda yine benle Seni düşünmek doyasıya artık seni vermiyor ki bana Ba...', ARRAY['Türk Edebiyatı','Şiir','Tolga Duyal']::text[], 8.5, '{"poet":"Tolga Duyal","poet_slug":"tolga-duyal","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yine-sensizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öpücük', 'opucuk-zulkuf-cengiz-n7168', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni bir kere öpsem 

İkinin hatrı kalırdı

İki kere öpsem 

Üç boynunu bükerdi

Üç defa öpsem

Dört de isterdi

Dört defa öpsem seni

Beş bana küserdi

Beş kere öpmek istesem seni

Altı darılırdı

Altı defa öpsem

Yedi benim suçum ne derdi

Yedi defa öpsem

Sekiz''in kalbini kırardım

Sekiz kere öpsem

Dokuz bende öpmek isterim derdi

Dokuz defa öpsem 

Sana sorurdum 

Devam mı tamam mı', 'Seni bir kere öpsem  İkinin hatrı kalırdı İki kere öpsem  Üç boynunu bükerdi Üç defa öpsem Dört de isterdi Dört defa öpsem seni Beş bana küs...', ARRAY['Türk Edebiyatı','Şiir','Zülküf Cengiz']::text[], 8.5, '{"poet":"Zülküf Cengiz","poet_slug":"zulkuf-cengiz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/opucuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geldim İşte', 'geldim-i-ste-ahmet-telli-38jrg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sülfür inceldi ve en yorgun yerinden kırıldı ayna

Tenhaydı düşlerim, geceydi, çıkıp geldim işte

Su ve ateş bir de gülünç yalnızlığım var sana

Getirebildiğim, kokularını yitirmişti çünkü güller

Suyu dinle  ateşi yak özledim demek bu

Parasız yatılı hüzünlerden ne kalır geriye

Biraz Tamil biraz Türküz ayıptır söylemesi

İntiharsa günahtır külliyen yasak bilirsin

Pısırık bir ihtilal gibi getirdim sana bunları

Bir de belleğim, başıma bela hazin ve komik üstelik

Hatırla eskiyen meydan saatini, çocukluğundur

Tayyare pulları getirdim sana evden kaçışlarımı

İstersen yok say bunları tespih de yapabilirsin

Beni vur saatin altında seni seviyorumdur bu

Şiir yazan bir adamın fotoğrafı var yanımda

Kendini ölümlü sanıyor onu getirdim ganimettir

Büyüdü büyülenerek, taşlayarak kovdu kabilesi onu

Suyun öte yakasında yaşadı, Sisyphos dediler adına

Sülfür inceldi ve en yorgun yerinden kırıldı ayna

Ayna pusluydu bunca yıl nice sır taşımaktan

Kırılmanın sesini duydum ve onu getirdim sana

Unutulmaya geldim işte onarılmaya değil

Kov beni kabilenden ama bekliyorum demek bu', 'Sülfür inceldi ve en yorgun yerinden kırıldı ayna Tenhaydı düşlerim, geceydi, çıkıp geldim işte Su ve ateş bir de gülünç yalnızlığım var san...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/geldim-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müjdeler Olsun', 'mujdeler-olsun-necip-fazil-kisakurek-7yruw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öleceğiz müjdeler olsun müjdeler olsun

Ölümüde öldüren Rabbe secdeler olsun', 'Öleceğiz müjdeler olsun müjdeler olsun Ölümüde öldüren Rabbe secdeler olsun...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/mujdeler-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul', 'istanbul-saim-gurer-rb6wy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Asiyana cikmistim simdi,

O dunyanin en guzel dedigi pencereden,

bakmistim bogazicine,fikretin.

sonra o kadincagizla muhabbete dalmistik,

fikretin cocuklugundan,olumune,

oglunun isyanina...

taa aksama kadar..

ne cabuk aksamlar olur gozunu sevdigim yerinde..

sonra besiktasa inmis grubun kizillanisini seyretmeye,,

belki galata koprusunde yurumus,

balik ekmek yerken,

dusunmustum balikcilari..

sonra vapura binmistim,

bir cay soylemistim,

birde sigara yakmistim,

bir sarki gelmistiki aklima,

vapur yanasmis,

kalamisa,todoriye gitmistim,

pinarin oldugu meyhaneye,

icmistim raki,az bir suyla,

o sevgiliye siz dedigi sarkiyi dinlerken...

birde bakmistim sabah olmus,

nede cabuk sabahlar olur gozunu sevdigim yerinde

belki bir sabahci iskembeciye yurumustum,

ahhh guzel istanbulum benim









kalkip bir sabahci iskembeciye gitmistim sonra yuruyerek,', 'Asiyana cikmistim simdi, O dunyanin en guzel dedigi pencereden, bakmistim bogazicine,fikretin. sonra o kadincagizla muhabbete dalmistik, fik...', ARRAY['Türk Edebiyatı','Şiir','Saim Gürer']::text[], 8.5, '{"poet":"Saim Gürer","poet_slug":"saim-gurer","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/istanbul-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Dönüş', 'aska-donus-umit-yasar-oguzcan-1n3pd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dönebilmek o dönüşü olmayan yollardan

Sürekli bir aldanış bir daha bir daha

Hiç bitmeyecek gecelerden bir sabaha

Çikabilmek ve sevmek durmadan usanmadan

Konuşmak konuşmak gözlerle fısıltılarla

Duymak büyülü sıcaklıgını beyaz ellerin

Her geçen dakika var oldugunu anlamak için

Yaşamak arzu dolu dudaklarda, şarkılarla

Unutmak ne varsa kötülükten yana

İnmek sevilen gözlerin derinligine

Öyle mutlu, öyle sarhoş, alabildigine

Bin yıl içmek o sulardan kana kana

Her gün ona koşmak daglardan tepelerden

Her yerde, her zaman onsuz edememek

O en tatlı hayal, en büyük gerçek

Anlarsın taşan o günlerden gecelerden

Sonra bir gün o bütün karanlıkları yırtasin gelir

Başını alıp gidesin gelir uzak denizlere

Artık her şey boş ve yalan sevdin ya bir kere

Her yerinden bir bugu halinde o yükselir

Sen yoksun artık anla yeryüzünde bir o var

Onun elleri var, gözleri, dudakları

Anlarsın tenin besledigi zaman toprakları

Ve hala seversin zaman bitinceye kadar

Yeniden var oluştur ya da bir başka türlü oluştur bu

Nice aldanmalardan sonra bir aşka dönüştür bu.', 'Dönebilmek o dönüşü olmayan yollardan Sürekli bir aldanış bir daha bir daha Hiç bitmeyecek gecelerden bir sabaha Çikabilmek ve sevmek durmad...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/aska-donus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkmıydı O?', 'askmiydi-o-umit-yasar-oguzcan-6no0b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk mıydı o, aşkımsı bir şey miydi 

Neydi çekip kendine, beni bağlayan 

Kanatan dudağımı, tenimi dağlayan 

Elleri ta içimde o dev miydi 

Etime bir alev değmişçesine 

Nasıl da yakardı öptüğü zaman 

Bir su gibi akıp gitti avuçlarımdan 

Yorgunum şimdi bin yıl sevmişçesine 

Hani o yalnız benim olan gül, kırmızı

Gözlerimin önünde açılan sonsuz bahçe

Hani, o var olmalarımız öpüştükçe 

O delice sürdürmeler yaşantımızı 

Hiç doymamak oysa, tene, kokuya, aşka 

Sarıldıkça güçlenmek, bütünlenmek 

Kudurmuş arzularla zamanı yenmek 

Ve en kuytularda buluşmak korka korka 

Kimi gün utanmak otlardan, çimenlerden 

Kimi gece mıhlamak gölgemizi duvara 

Varmak için o sevgiyle açılmış kollara 

Apansız düşmek yükseklerden bir yerden 

Oydu işte alıştığım, özlediğim şimdi de 

Sevgice bir tutku, aşkımsı bir yakınlık 

Avunmak... Kırık dökük anılarla artık 

Kimbilir? o geceler yaşanmadı belki de', 'Aşk mıydı o, aşkımsı bir şey miydi  Neydi çekip kendine, beni bağlayan  Kanatan dudağımı, tenimi dağlayan  Elleri ta içimde o dev miydi  Eti...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/askmiydi-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçışına Uğrayan Çiçek', 'kacisina-ugrayan-cicek-edip-cansever-q2pcg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Surayi goturun dedim onlara

Buraya da, burayi da

Alin goturun dedim

Cimenlerin tirse bugusunun ustunden

Tirse bugunun duslere degen ustunden

Duslerin aycicegi giysilerinin ustunden

O zaman anlatirim dedim onlara

Pencere onumun niye uctugunu.

Evet

Donup geliyor az sonra

Kolumun altina yerlesiyor

Kendisiyle yer degistirir gibi

Itiyorum onu, itiyorum, itiyorum

Butun zamanlar bitti diyorum-anlasa''ya-

Iki tek kiraz agaci kaldi yalniz

Iki tek kiraz agaci

Ilkyazlar ve butun baslangiclar bitti

Kiraz agaclari? onlar da

Gozlerimin deli kirmizisini yikamak icin

Agladiklari zaman

Ne vardi sundurmanin ustunde-ne vardi-

Animsayamiyorum simdi

-Pek simdi degil, coktandir-

Yagmurlar yagdigi zaman buyuyen

Gecmisi olmayan bir saksi mi

Yoksa

Bir sap cicek mi-saksisiz-

Kacisina ugrayan bir cicek

Neden olmasin

Yagmurlar

Yagmurlar yagdigi zaman.

Sular insanlar gibi geciyor aklimdan

Mavi aklimdan

Sordular-animsiyorum-

Bir gun

Neyle ortulurmus ki su

Suyla demistim -elbette suyla-

Ya yasam

Bir baska yasamla, bir baska, bir baska, bir baska

Oysa butun yasamlar bitti

Ilkyazlar ve butun baslangiclar

Sular

Insanlar gibi duruyor aklimda.

Dislerimin arasindan gosteriyorum ellerimi

Korkuyla kacisiyor guvercinle karanfil

Donup arkama bakmiyorum

Odalar bitti cunku, merdivenler de

Disarsi var:surasi, burasi, orasi

Ve yagmur-yagmurlar-

Ah su yagmurlar durmasa ya

Ne guzel islaniyor ilkyaz

Ne guzel ne guzel ne guzel

Denize zorla sokulmus

Aglamakli bir cocuk gibi.', 'Surayi goturun dedim onlara Buraya da, burayi da Alin goturun dedim Cimenlerin tirse bugusunun ustunden Tirse bugunun duslere degen ustunden...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/kacisina-ugrayan-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaktüs', 'kaktus-edip-cansever-95xl1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sonunu istemiyorum sessizliğin

Yokluğu istemiyorum bu akşamüstü çınlamasında

Yüzümü dizlerime dayıyorum, bitiştiriyorum

Kollarımı da

Bir kaktus olmalıyım ben, dışıma yağan bir sağnak

Olmalıyım

Uçsuz bucaksız dünyada

Güneşin doğuşunu bekleyen.

Ufukta ansızın bir ışık çizgisi

Avuclarimdayim belki.', 'Sonunu istemiyorum sessizliğin Yokluğu istemiyorum bu akşamüstü çınlamasında Yüzümü dizlerime dayıyorum, bitiştiriyorum Kollarımı da Bir kak...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kaktus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavga', 'kavga-edip-cansever-qu9v3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sivridir ayaklari bastikca kati taslara

Kadinlar memelidir-Ya viski icelim ya bira

Hayatta olmayan masalar vardir ya

Tam iste onlar icinde bir masa

Mike ile Jim''e soyle bu gece kadinlara.

Mike kadin sevmez, onu kahveye birakiriz ayrica

Azicik kagit oynar acilir Okyanuslara

Hayatta olmayan adalar vardir ya

Tam iste onlar icinde bir ada

Bizi biliyorsun ya-goz kirpar-kadinlara.

Sivridir ayaklari gokyuzu vurunca damlara

Bu kavga, bu iste yuzuncu katindan bir kavga

Hayatta olmayan insanlar vardir ya

Sen misin Mike, Jim sen misin yoksa

Hadi aldirmayalim-icini ceker-bu gece kadinlara.', 'Sivridir ayaklari bastikca kati taslara Kadinlar memelidir-Ya viski icelim ya bira Hayatta olmayan masalar vardir ya Tam iste onlar icinde b...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kavga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canticum', 'canticum-muharrem-huseyinoglu-7waib', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nusret ve ben

Üç te hamal

Taşıyamam ki tek başıma

Mezarına kadar

Garipti mahsundu

İçliydi en önemlisi

İçerdi her akşam

Ama iyi adamdı

''Keserim ayağını'' dedi

Doktorun biri

Aldırmadı

Güldü içinden

Ne ayağını verdi

Ne şişesini

Kendi ayağı4 ile gitti Nusret

*Dua edilen şarkı', 'Nusret ve ben Üç te hamal Taşıyamam ki tek başıma Mezarına kadar Garipti mahsundu İçliydi en önemlisi İçerdi her akşam Ama iyi adamdı ''Keser...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Hüseyinoğlu']::text[], 8.5, '{"poet":"Muharrem Hüseyinoğlu","poet_slug":"muharrem-huseyinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/canticum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden', 'neden-emrah-akyol-dd3jt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beğendin,

Hoşlandın,

Çıktın.

Elini Tuttun,

Öptün.

O sıcaklığı hissettin.

O anın hiç bitmemesini istedin.

Konuştun,

Gözlerine baktın,içine

Daldın gittin derinlere.

Neden böyle oldu peki?

Neden böyle olur hep?

Büyütürsün ezerler

Seversin terk ederler

Hayata küstürürler,

Neden böyle?....Neden böyle?...!!!', 'Beğendin, Hoşlandın, Çıktın. Elini Tuttun, Öptün. O sıcaklığı hissettin. O anın hiç bitmemesini istedin. Konuştun, Gözlerine baktın,içine Da...', ARRAY['Türk Edebiyatı','Şiir','Emrah Akyol']::text[], 8.5, '{"poet":"Emrah Akyol","poet_slug":"emrah-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
