INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''a Dair 2', 'ask-a-dair-2-mehmet-calik-dgbev', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Masum değilsiniz

Sizde biliyordunuz

Aşk şiir için vardı

Ve siz

Anadan üryan

Buram buram

Şiir kokuyordunuz', 'Masum değilsiniz Sizde biliyordunuz Aşk şiir için vardı Ve siz Anadan üryan Buram buram Şiir kokuyordunuz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çalık']::text[], 8.5, '{"poet":"Mehmet Çalık","poet_slug":"mehmet-calik","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ask-a-dair-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nadas', 'nadas-mehmet-calik-a568v', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hey sen

Bakire bir fahişenin

