INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vay Be', 'vay-be-pinar-altanoglu-fhlsr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bayram geliyormuş gene,

bebekler doğacakmış gene,

çiçekler kopacakmış gene,

şiirler şarkı olacakmış gene,

insanlar sevişecekmiş gene...

vay be ...............

          

Viyana 8.6.96', 'Bayram geliyormuş gene, bebekler doğacakmış gene, çiçekler kopacakmış gene, şiirler şarkı olacakmış gene, insanlar sevişecekmiş gene... vay ...', ARRAY['Türk Edebiyatı','Şiir','Pınar Altanoğlu']::text[], 8.5, '{"poet":"Pınar Altanoğlu","poet_slug":"pinar-altanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/vay-be-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-tolga-baydar-o59cj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum

Bunu biliyorsun

Sevmeni istiyorum

Bu düş son bulsun

Senin beni sevdiğin

Diliyorum ki gerçek olsun', 'Seni seviyorum Bunu biliyorsun Sevmeni istiyorum Bu düş son bulsun Senin beni sevdiğin Diliyorum ki gerçek olsun...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seni-seviyorum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklerim', 'beklerim-tolga-baydar-70dvi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlık çökse de üzerime

Yıldızların ışıltısı aydınlatır yüzümü

Ve düşlerim, beklerim....

Doğacak güneşi, aydınlığı.....', 'Karanlık çökse de üzerime Yıldızların ışıltısı aydınlatır yüzümü Ve düşlerim, beklerim.... Doğacak güneşi, aydınlığı........', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/beklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belli Ki Bir Ölen Var', 'belli-ki-bir-olen-var-tolga-baydar-dag54', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sade kahve içtim sabah sabah

Uykum açılsın diye

Bir mahurluk var üzerimde

Ölüme mi gidiyorum ne

Açıldı önümde yollar

Sesler, canhıraş bağırmalar

Belli ki bir ölen var

Arkasından ağlamasınlar', 'Sade kahve içtim sabah sabah Uykum açılsın diye Bir mahurluk var üzerimde Ölüme mi gidiyorum ne Açıldı önümde yollar Sesler, canhıraş bağırm...', ARRAY['Türk Edebiyatı','Şiir','Tolga Baydar']::text[], 8.5, '{"poet":"Tolga Baydar","poet_slug":"tolga-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/belli-ki-bir-olen-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin Hazal Kokar', 'ellerin-hazal-kokar-hasan-kaya-efrrz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceler hep soğuk olur sensiz

düşlerim üşür

Kirli günahkar işçi elerim gibi.

karanlık içimize sinmişse.

direnmek zor

Düşlerinde yalınayak gezerim,

çırılçıplak bedenim.

Dokunsan tutuşur tenim.

anlımın teri aşım ekmeğim.

Yorgunluklara direnmek zor

Kanmış soran gözlerin

Yeşile hasret hazan mevsimi...

Kınalı elerin yorgun dokunur

hazal kokar

Mevsim yine sonbahar

aylardan eylül,

direnmek zor.', 'Geceler hep soğuk olur sensiz düşlerim üşür Kirli günahkar işçi elerim gibi. karanlık içimize sinmişse. direnmek zor Düşlerinde yalınayak ge...', ARRAY['Türk Edebiyatı','Şiir','Hasan Kaya']::text[], 8.5, '{"poet":"Hasan Kaya","poet_slug":"hasan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ellerin-hazal-kokar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekermiyiz Kendimizi Tane Tane', 'cekermiyiz-kendimizi-tane-tane-mustafa-caliskan-u8ogc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tesbih gibi mi çekeriz

Kendimizi kendimize doğru,

Yoksa tesbih gibi tane tane

Bir tane dağıtırmıyız

Kendimizi evrene doğru;

Sormak ayıp, cevap kayıp,

Sevda uzayıp giden bir teselli olalı...

Hasretlik gırtlağımıza oturalı

Dağıtırmıyız bilmem ama

Toplanması güç olur

Güç olur sevdaları toplamak

Aşkları sevgileri yudumlamak

Boncukları dizeriz ipler üstüne

Gelip geçmeyen zaman dilimine

Tek tek sayarız

Geçen dakikalara karşı

Uzayıp giden zaman dilimine

Bir dur deriz ; ve çekeriz

Yoksa tesbih gibi tane tane

Kendimizi sonsuza doğru

Sormayın ne olur

Sormak ayıp, cevap kayıp

Sevda uzayıp giden bir teselli olalı...

Çekeriz kendimizi kendimize

Tane tane...

(1995)', 'Tesbih gibi mi çekeriz Kendimizi kendimize doğru, Yoksa tesbih gibi tane tane Bir tane dağıtırmıyız Kendimizi evrene doğru; Sormak ayıp, cev...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çalışkan']::text[], 8.5, '{"poet":"Mustafa Çalışkan","poet_slug":"mustafa-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/cekermiyiz-kendimizi-tane-tane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akseden Görüntü', 'akseden-goruntu-mustafa-caliskan-20odz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tuzu kuru ırmakların

Kendilerini ve kedilerini

Savunma biçimleri nedense,

Nedense bir tuhaftır ya

Orada öylece durup bakarız

Kıyısından aynalara

Görünce kendimizi

Gitmelerimiz hafiften olur...

Saçlarımız dökülür ırmaklara

Yansıması bir nur olur

Dalga dalga

Uzayan semalara

Görünüşleri farklı olur

Çerçeveleri ise daha farklı

Nedense garip karşılanır

Duraklarız bir an

Dikkatlice ve sessizce bakarız

Aşağıdan semalara

Görünce kendimizi 

Ve akseden görüntümüzü

Gitmelerimiz seyrekleşir...

Tuzu kuru ırmaklar

Bir an tatlıya bürünür gözümüzde

Kendileri ve kedileri

Savunma biçimleri gariptir

Uzaklaşırız ince ince

Ardında garip bir iz bırakarak

Ayak izleri görünür sadece

Baktıkça kendimize

Gitmelerimiz hızlanır

Toz olur, bulut olur

Ve kaybolur git gide....

(1995)', 'Tuzu kuru ırmakların Kendilerini ve kedilerini Savunma biçimleri nedense, Nedense bir tuhaftır ya Orada öylece durup bakarız Kıyısından ayna...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çalışkan']::text[], 8.5, '{"poet":"Mustafa Çalışkan","poet_slug":"mustafa-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/akseden-goruntu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahenk', 'ahenk-mustafa-caliskan-ps9hj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Terzilerin mini minnacık yüksüklerinde

Yüksüklenmelerin en koyusu

Kendi halinde dalgalanırken

Bir mahrumiyet çeker

Dibe doğru bizi,

Özlediğimiz sizi de...

Belki ardından geleceksiniz diye

Maviye çalınmış duvarları

İzlerini taşıyor her bir kenarları

Mahsun bi çare bakar içe doğru

Yükselmiş göğe doğru

İçine çeker bizi,

Özlediğimiz sizi de...

Sokaklarında yürürsün yalınayak

Dizilmiş taşları sayarsın

Saymak ne kelime, 

Sayıklarsın

Gece kendine çeker bizi,

Özlediğimiz sizi de...

Sokaklarında yalınayak yürürsün

Soğuklardan en soğuk

İçinizde sızlarken

Bir hüzün kaplar içinizi

Soğuk içine çeker bizi

Özlediğimiz sizi de...

Dallarında yaprakları kurumuş ağaçların

Gövdelerinde dolaşan karıncalar

Karıncalarda bir sessizlik

Fakat içinizde 

Derin bir haykırış geceye

Gece içine çeker bizi,

Özlediğimiz sizi de...

Yeni gelinin telli duvağına işlenmiş

Hayatın serendipleri

Gözlerinde yaş var gelinin

Kalbinde derin bir sızı

Bir sızı ki adım adım çeker

Gecenin loş ışıklarıyla

Dolaşır durur seninle beraber gölgeler

Tılsım misali edasıyla

İçine çeker sizi,

Özlediğimiz hepimizi...

(1995)', 'Terzilerin mini minnacık yüksüklerinde Yüksüklenmelerin en koyusu Kendi halinde dalgalanırken Bir mahrumiyet çeker Dibe doğru bizi, Özlediği...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çalışkan']::text[], 8.5, '{"poet":"Mustafa Çalışkan","poet_slug":"mustafa-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ahenk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevsek''te Sevmesek''te', 'sevsek-te-sevmesek-te-mustafa-caliskan-nhpdm', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmesek''te sevildiğini bildiğimiz sevgiliyi

Sevsek''te

Tuhaf bir duvar gibi ara yerde duran

Sahipsiz gözyaşları vardır daima

Daima bir cinneti kendine kale edinen sevgi

Siperden çıkar çıkmaz daha ilk kurşunda

İlk kurşunda kalbinde bir inilti

Yalnızlıklar içinde aranan

Sevginin seviyesizliği

Damla damla iner yanaklarından

Sanki duvarlar ağlıyor

Korkunç bir ürperti sara benliği

Yarı açık kapıların ardından

Uzanan bir gençlik türküsü

Anlatıyor;

Sevsek''te sevildiğini bildiğimiz sevgiliyi

Sevmesek''te

Tuhaf bir duvar gibi ara yerde duran

Sahipsiz gözyaşları vardır

Bakarsın için burkulur bir an için

Yer ve gök inilti salar bu acıya

Ve yaralanmış kalbinin

Cansız, yere yığılmışlığın

Bir portresidir,

Sevsek''te sevildiğini bildiğimiz sevgiliyi

Sevmesek''te.....

(1995)', 'Sevmesek''te sevildiğini bildiğimiz sevgiliyi Sevsek''te Tuhaf bir duvar gibi ara yerde duran Sahipsiz gözyaşları vardır daima Daima bir cinne...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çalışkan']::text[], 8.5, '{"poet":"Mustafa Çalışkan","poet_slug":"mustafa-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sevsek-te-sevmesek-te-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Uçuş', 'sonsuz-ucus-mustafa-caliskan-twea5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Özgürlüğün simgesidir şu uçan kuşlar

Yaprak yaprak açılıyor semaya doğru kanatlar

Dert yok tasa yok umurundamı ki dünya

Son uçuş, hani sonsuzluğa doğru var ya

Sıcak sevgiler sıcak ülkeler ve gökyüzü

Bir mutluluk saçar size görünen her yüzü

(1995)', 'Özgürlüğün simgesidir şu uçan kuşlar Yaprak yaprak açılıyor semaya doğru kanatlar Dert yok tasa yok umurundamı ki dünya Son uçuş, hani sonsu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çalışkan']::text[], 8.5, '{"poet":"Mustafa Çalışkan","poet_slug":"mustafa-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sonsuz-ucus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başkası', 'bir-baskasi-ahmet-gumustekin-qiqbi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben sevmedim,

Seni sevdiğim kadar,

Bir başkasını.

Ben özlemedim,

Seni özlediğim kadar,

Bir başkasını.

Ama sen,

Gittin sevdin.

Bir başkasını.', 'Ben sevmedim, Seni sevdiğim kadar, Bir başkasını. Ben özlemedim, Seni özlediğim kadar, Bir başkasını. Ama sen, Gittin sevdin. Bir başkasını....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gümüştekin']::text[], 8.5, '{"poet":"Ahmet Gümüştekin","poet_slug":"ahmet-gumustekin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-baskasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Halde', 'halde-ahmet-arslan-de151', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni delice sevdim

Sen başkasını sevdiğin halde

Seni istemekten bıkmadım

Sen beni istemediğin halde

Sana aşkımı söyledim

Beni dinlemediğin halde

Geceleri camının altında sabahladım

Karanlıktan korkar olduğum halde

Adını  duvarla yazdım

Okumadan geçtiğin halde

Rüyalarımda hep seni görmek isterdim

Her rüyamda bana hayır dediğin halde

Canımı ortaya koydum

Canım senin için değersiz olduğu halde

Ama yine de mezar taşıma

Eceliyle öldü yazdırdım

İntiharıma sen sebep olduğun halde...!', 'Seni delice sevdim Sen başkasını sevdiğin halde Seni istemekten bıkmadım Sen beni istemediğin halde Sana aşkımı söyledim Beni dinlemediğin h...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Arslan']::text[], 8.5, '{"poet":"Ahmet Arslan","poet_slug":"ahmet-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/halde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Senin Olan Birşey Ver', 'bana-senin-olan-birsey-ver-celal-kabadayi-kmhz7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bana senin olan birşey ver

bir gülücük yanağında açan

bir öpücük sıcak dudaklarından

bir dünya senin yarattığın

bana sevgini ver

bana senin olan birşey ver

tepedeki kar aklığında

tarladaki pamuk yumuşaklığında

bir sevgili sıcaklığında

bana ellerini ver

bana senin olan birşey ver

yağmurda yıkanmış çiçek güzelliğinde

kötüyle tanışmamış çocuk temizliğinde

yaşamı bağrına basan okyanus derinliğinde

bana yüreğini ver', 'bana senin olan birşey ver bir gülücük yanağında açan bir öpücük sıcak dudaklarından bir dünya senin yarattığın bana sevgini ver bana senin ...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bana-senin-olan-birsey-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessiz Düşünceler', 'sessiz-dusunceler-afsar-timucin-bjwjn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimseyi aramıyorum kapandım kendime

Kimse de artık beni aramasın

Koşa koşa gelen yazı denizi

Her duyguyu her düşünceyi

Tek başıma yaşarım

Birilerini aradım kapılarını çaldım

Yıllarca belki de yüzyıllarca

Anlatmak istedim kendimi birilerine

Neye yaradı bunca yakınlığım

Sandılar ki onlar olmadan

Taşıyamam kendimi bir yerden bir yere

Oysa benim tek amacım şuydu

Birlikte gidelim güzelliklere

Yüreğim uyuyan dalgalar gibi durgun

Kafam tam anlamında bir kaçak

Ben kimselerin anmadığı adam

Yüzyıl yaşamış gibi yorgun

Daha dün doğmuş gibi çocuk', 'Kimseyi aramıyorum kapandım kendime Kimse de artık beni aramasın Koşa koşa gelen yazı denizi Her duyguyu her düşünceyi Tek başıma yaşarım Bi...', ARRAY['Türk Edebiyatı','Şiir','Afşar Timuçin']::text[], 8.5, '{"poet":"Afşar Timuçin","poet_slug":"afsar-timucin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sessiz-dusunceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Unutamayacaksın', 'beni-unutamayacaksin-i-smail-safa-yildiz-gkm0m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yastıklara kapanacaksın her gece yatakta

Gözlerin tavana dikilmiş

Ellerin bomboş

Yanaklarında damlayan yaşlar

Ve böyle sabahlayacaksın tüm gecelerini

Beni arayacaksın

Beni soracaksın her yerde

Saçların alnına düşmüş

Seninle geçen günlerimizi hatırlayarak

Ağlayacaksın hıçkıra hıçkıra

Böyle geçip gidecek günlerin ard arda

Dertleşecek kimse yok

Gözyaşlarınla ıslanacak yastık

Ama halden anlayan kim?

Boşuna kendini yiyip bitireceksin

Dişlerini sıkacaksın, avuçlarını oyacaksın

Lakin boşa

Beni unutamayacaksın...', 'Yastıklara kapanacaksın her gece yatakta Gözlerin tavana dikilmiş Ellerin bomboş Yanaklarında damlayan yaşlar Ve böyle sabahlayacaksın tüm g...', ARRAY['Türk Edebiyatı','Şiir','İsmail Safa Yıldız']::text[], 8.5, '{"poet":"İsmail Safa Yıldız","poet_slug":"i-smail-safa-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beni-unutamayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-seracettin-karayagiz-i2tju', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gündüz zihinlerimde sen,

Gece rüyalarımda sen,

Okuyorum dilimde sen,

Hayalimde hülyam sensin.

Kahvedeyim fincanda sen,

Saz çalarım telinde sen,

Falcı söyler dilimde sen,                                                            Can ben isem canan sensin.

Yürüyorum karşımda sen,

Sevdan ile başımda sen,

Sayıklarım düşümde sen,

Hasta benim,ilaç sensin.

Sabaha dek ağlatan sen,

Sular gibi çağlatan sen,

Hem derdimin sebebi sen,

Hem derdime çare sensin.

                                   (6.8.1974)', 'Gündüz zihinlerimde sen, Gece rüyalarımda sen, Okuyorum dilimde sen, Hayalimde hülyam sensin. Kahvedeyim fincanda sen, Saz çalarım telinde s...', ARRAY['Türk Edebiyatı','Şiir','Seracettin Karayağız']::text[], 8.5, '{"poet":"Seracettin Karayağız","poet_slug":"seracettin-karayagiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teselli', 'teselli-seracettin-karayagiz-22uqe', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyorum

En şiddetli depremlerin izleri var kalbinde...

Yüreğin şu harabelerden daha harap...

Ama boşver,madem ki anlamadı

Düşünme boşuna.

Biliyorum

Hayallerin sel afetine uğradı sanki...

''Ümitsiz de yaşanır mı?'' diyorsun belki de.

Ama boşver,madem ki kalpsizdi

Üzülme boşuna.

Biliyorum 

Bir derya kadar dolusun şimdi

Dokunsam ağlarsın belki de

Ama birgün seni,meyhane kapısında,

Böyle perperişan görüp güleceğini

Düşün de... ağlama...

                                    (17.1.1975)', 'Biliyorum En şiddetli depremlerin izleri var kalbinde... Yüreğin şu harabelerden daha harap... Ama boşver,madem ki anlamadı Düşünme boşuna. ...', ARRAY['Türk Edebiyatı','Şiir','Seracettin Karayağız']::text[], 8.5, '{"poet":"Seracettin Karayağız","poet_slug":"seracettin-karayagiz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/teselli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'unuttum', 'unuttum-seracettin-karayagiz-qphkh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni gördükten sonra 

Gecemi,gündüzümü,

Ne için nerede olduğumu,

Kim olduğumu,

Velhasıl herşeyimi...Unuttum.

Unutamadığımtek şey var o da:

Sensin.

                                (26.3.1975', 'Seni gördükten sonra  Gecemi,gündüzümü, Ne için nerede olduğumu, Kim olduğumu, Velhasıl herşeyimi...Unuttum. Unutamadığımtek şey var o da: S...', ARRAY['Türk Edebiyatı','Şiir','Seracettin Karayağız']::text[], 8.5, '{"poet":"Seracettin Karayağız","poet_slug":"seracettin-karayagiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/unuttum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokaklarda Mızıka Çalma Çocuk', 'sokaklarda-mizika-calma-cocuk-attila-i-lhan-mx1k7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Boynuna o yeşil fuları sarma çocuk

Gece trenlerine binme, kaybolursun

Sokaklarda mızıka çalma çocuk

Vurulursun...', 'Boynuna o yeşil fuları sarma çocuk Gece trenlerine binme, kaybolursun Sokaklarda mızıka çalma çocuk Vurulursun......', ARRAY['Türk Edebiyatı','Şiir','Attila İlhan']::text[], 8.5, '{"poet":"Attila İlhan","poet_slug":"attila-i-lhan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sokaklarda-mizika-calma-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bu Handa Garip Misafir', 'ben-bu-handa-garip-misafir-i-lhan-yuksel-oyfne', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben Bu Handa Garip Misafir

Ben bu handa garip misafir 

Gelip geri gitmeye geldim 

Yürümeyen şu bedenimi 

Yürü deyip itmeye geldim 

Ne maldan verilir ne mülkten 

Kazancın kesbin bu dünyada 

Denir iki tahta bir top kefen 

Başa da yeter ayağa da 

Gel deyi çağrıldığım yer 

Bırak diyor mülkü malı da 

Buraya her çağrılan gider 

Sultanı beyi hamalı da 

Ne ileri gider ne geri 

Ölüm diye saat kurulmuş 

Denilir kapıdan gir içeri 

Ömür biter saat dururmuş', 'Ben Bu Handa Garip Misafir Ben bu handa garip misafir  Gelip geri gitmeye geldim  Yürümeyen şu bedenimi  Yürü deyip itmeye geldim  Ne maldan...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-bu-handa-garip-misafir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkların Basit Mazisi', 'asklarin-basit-mazisi-tugba-ucar-ryntf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen sevememissin hic!

daha hissedemiyorken,

sürünmüssün elleri kırık bir aska.

senin asklarının basit mazisi bu...

sana ask icin ''o bir tas corbadır '' demişler.

kavgaların yalancı şahitleri olan küfürleri gosterip,

asktan sonrasını anlatmışlar.

öncesini sorduğunda ise,

''saman aleviydi'' diyip gülüp geçmişler...

Sen aşkı açlıgın için kullanmışsın

garipliğine ,sevgisizliğine yem etmişsin..

sehrin garip bakıslarıyla beraber kurban etmissin her yolcuya

bu ''modern'' dunyada ''face to face '' degil

''fight to fight'' diyerek sevişmişsin..

''''entellektuel formuller'''' uretmıssin

sevgini yoketmek icin..

aşkın gözlerini bağlayıp,

acı ile yalamışsın dudaklarını.

sen elleri kırık bir aska sürünmüssün

hala bir tas corba sanıyorsun sevgiyi....', 'sen sevememissin hic! daha hissedemiyorken, sürünmüssün elleri kırık bir aska. senin asklarının basit mazisi bu... sana ask icin ''o bir tas ...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Uçar']::text[], 8.5, '{"poet":"Tuğba Uçar","poet_slug":"tugba-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/asklarin-basit-mazisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Razıyım Acıtmana', 'raziyim-acitmana-tugba-ucar-1r91j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hani koşup gelsen

sıyrılsan geçmiş bedenlerden,aşklardan

sarılsan sarmasık bedenınle

Razıyım acıtmana yüregimi

hani açsan yüregini

koşsan pişmanlıklarla dolu bedenime

yetim sevdalar bekliyor seni burada

nehir gözlerinle yıka kapılarımı!!!

bıcak cekilen bi hüzün melodilerle sevgi hapsediyor

emiyor ruhum seytanın karanlıgını

hani sıyrılsan tedirginligimden

sarılsan gercek umudunla...

hani koşup gelsen diyorum

sarılsan ıslak saçlı ruhuma

razıyım acıtmana!....', 'hani koşup gelsen sıyrılsan geçmiş bedenlerden,aşklardan sarılsan sarmasık bedenınle Razıyım acıtmana yüregimi hani açsan yüregini koşsan pi...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Uçar']::text[], 8.5, '{"poet":"Tuğba Uçar","poet_slug":"tugba-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/raziyim-acitmana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medusa''ya', 'medusa-ya-tugba-ucar-mi4r9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayatımız devrik cumlelerle dolu.

 Farkettin mi Medusa? 

Hayatımız hayatlarımız  olmus.

 Kalem kopek olmus,kagıt derin bir gol,sarkılarsa cıglık..

.Hersey ''''karma '''' dedigin gibi..

    Eski defterlerde ise sadece karalanan isimler var. Unutmak icin karaladıgım ama asla unutamadıgım.

 Sayfaları her cevirisimde ayrıntılarıyla hatırladıgım isimler..

.Aslında derinlere gomdugum..

   Sahne  hep aynı aslında. 

Farkettin mi Medusa? 

Sadece dekor ve isimler degisik.Replikler aynı . Degistirmeye calıstık senle. 

Ama farklı olamamısız...

  Ruzgar hep aynı yonden esmis.

Bizse ona karayel,poyraz demisiz.. 

Biz hep sonbahar yapragı olmusuz. 

İlkbaharı ,hani o senin gozlerin  parıldayarak anlattıgın,

günesin insan tenini en guzel sekilde oksadıgı mevsime ulasamamısız , 

martı olamamısız Medusa...



    Biz asık olamamısız Medusa.. 

Önce garip bir nota toplulugu olan aşkı,

 gecenin demir dilli habercisi akrep 12'' e vurdugunda , yakalayıp susturmus,

sonra senin benim yapmısız. 

O parcalanmıs . Parcalamısız onu .

 Katil olmusuz biz Medusa..

biz askı MÖ. ''nde

 bırakmısız Medusa..

Biz hala bir istasyondayız Medusa!..

Yolcu olamamısız...', 'Hayatımız devrik cumlelerle dolu.  Farkettin mi Medusa?  Hayatımız hayatlarımız  olmus.  Kalem kopek olmus,kagıt derin bir gol,sarkılarsa cı...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Uçar']::text[], 8.5, '{"poet":"Tuğba Uçar","poet_slug":"tugba-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/medusa-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-mustafa-caliskan-2i1ly', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonbahar yaprakları dökülmüş yine ağaçların

Hepsi bir bir önümden geçti geçmiş hatıraların

Özlemini duyuyorum ben hala senin için

Şekilden şekile giriyorum ben biçim biçim

Yanımda olmanı istiyorum her an benimle

El ele kol kola olmak istiyoeum ben seninle

Yollar hey gidi kıvrım kıvrım yollar ayırdınız ikimizi

Yollar ki mahsun bıraktınız kalbimizdeki sevgimizi

Hey sevda seninle dağları aşmalı, dolaşmalı, yıpratmalı

Değil yollar değil dağlar sevgimize engel olmamalı

Seninle ey güzel yarim seninle dağları aşarım

Seninle, sevgim için, benliğime sığmam taşarım

Senin için inan güzelim, sevgi için, aşk için

O güzel gözlerin, o tatlı gülümseyişin için

(1995)', 'Sonbahar yaprakları dökülmüş yine ağaçların Hepsi bir bir önümden geçti geçmiş hatıraların Özlemini duyuyorum ben hala senin için Şekilden ş...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çalışkan']::text[], 8.5, '{"poet":"Mustafa Çalışkan","poet_slug":"mustafa-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medet Ya Rabbi', 'medet-ya-rabbi-mustafa-caliskan-lsdpl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günahlar içinde boğulduk kaldık hiç durmadan

Sonu ne olur diye hiç düşünmedik daima yürüdük

Bir kıvılcım, bir ışık bekledi kalbimiz her zaman

Nihayet yolun sonunun ne olduğunu hepimiz gördük

Rabbimiz karşısında el pençe divan duracağız

Yarab medet, yarab medet diye yalvaracağız

Affedicisin sen, affedersin bizleri diyeceğiz

Allahın huzurunda son bir yakarışa geçeceğiz

Açın gözünüzü ey kullar son demleri bekleme

Son demlerde neler olacağını bilemezsin hiç

Henüz vakit varken bu düşünceni erteleme

Ölüm kapıya gelince tövbeye vakit kalmaz hiç

(1995)', 'Günahlar içinde boğulduk kaldık hiç durmadan Sonu ne olur diye hiç düşünmedik daima yürüdük Bir kıvılcım, bir ışık bekledi kalbimiz her zama...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çalışkan']::text[], 8.5, '{"poet":"Mustafa Çalışkan","poet_slug":"mustafa-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/medet-ya-rabbi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlasana...', 'hatirlasana-mustafa-caliskan-x9bk8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her gece gizlice buluşmuştuk seninle

El ele verip, diz dize oturmuştuk ikimiz

Buluşmuştu gözlerim o ceylan gözlerinle

Nasıl unutursun ki o günleri, hatırlasana...

Bazen ceylan pınarları gibi akardı gözyaşlarımız

Hep sevgimizi anlatırdı birbirimize ıslak dudaklarımız

Bizi konuşurdu cümle alem çınlardı kulaklarımız

Özlem dolu günlerdi o günler, hatırlasana...

Hani hiç ayrılmayacaktık birbirimizden

Hani kimseyi görmeyecekti gözlerimiz

Hani kimseye bağlanmayacaktık kalbimizden

Hani unutuldumu ki sözlerimiz hadi hatırlasana...

Her zaman hayalini kuruyorduk ya mutluluğun

Umutla bekliyorduk ufkumuzda gelecek olan huzurun

Ayrılık olmasın diye söz vermiştik ya, şerefin namusun

Nerede kaldı o sözler, hani nerede, hatırlasana...

Hatırlasana sevdam o son geceyi sarılmıştık birbirimize

Konmasın dedik hiç bir leke tertemiz sevgimize

Ama şimdi ne oldu böyle sevdam, seven kalbimize

Artık dön diyor gönlüm, seni bekliyor ellerim ve gözlerim

Sana sarıldığım günü özlüyorum şimdi sevdam,

Hatırlasana...', 'Her gece gizlice buluşmuştuk seninle El ele verip, diz dize oturmuştuk ikimiz Buluşmuştu gözlerim o ceylan gözlerinle Nasıl unutursun ki o g...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çalışkan']::text[], 8.5, '{"poet":"Mustafa Çalışkan","poet_slug":"mustafa-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hatirlasana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlim İrfan Yolu', 'i-lim-i-rfan-yolu-mustafa-caliskan-7v2qm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlimde saklıdır bütün beşeriyet

İlme uzanan eller yok ki hayret

Cahil kalmak akıl karımıdır sizce

İlme yönelmekaptallıkmıdır kimine göre

Köşe başında oyurmakla yapılan boş lakırtı

Zar ile tavla atmak ise bomboş takırtı

Hoşunuza mı gidiyor zamanı boş yaşamak

İlim ve fen öğrenmek yerine

Kahvede oyun oynamak

Kurtarırmı dersin kurulan boş hayaller

Faydası oldumu sana yaşadığın seneler

İlim irfan yolu her kapıya açıktır

Bu uğurda çaba sarfetmek yerine

Kapalı kapılar ardında savrulmak niye

Devam edin, belki bulursunuz huzuru

Eğer elleriniz boş dönerseniz

Yapmayın sakın bizlere kuruntu

Yaşam tatlıdır belkide bu şekilde

Sonu ise aptallıktır, cahilliktir, divaneliktir,

Ben söylemiş olayım yine de...

(1995)', 'İlimde saklıdır bütün beşeriyet İlme uzanan eller yok ki hayret Cahil kalmak akıl karımıdır sizce İlme yönelmekaptallıkmıdır kimine göre Köş...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çalışkan']::text[], 8.5, '{"poet":"Mustafa Çalışkan","poet_slug":"mustafa-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ilim-irfan-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Sevdalar İçin', 'o-sevdalar-i-cin-turgut-baygin-6zlm5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ki mavi gözlü bir kadın değildir aşk

Önce sevdiğini söylemez 

Öyle kolay tutmaz ellerini adamın

tuttu mu da bırakmaz haa !

Ki öyle unutulmaz da değildir 

                                       bi yandan

o sevdalar da unutulur

unutulur da

kapanmaz yarası sonradan.

(nisan 00)', 'Ki mavi gözlü bir kadın değildir aşk Önce sevdiğini söylemez  Öyle kolay tutmaz ellerini adamın tuttu mu da bırakmaz haa ! Ki öyle unutulmaz...', ARRAY['Türk Edebiyatı','Şiir','Turgut Bayğın']::text[], 8.5, '{"poet":"Turgut Bayğın","poet_slug":"turgut-baygin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/o-sevdalar-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidip Gelmeler', 'gidip-gelmeler-turgut-baygin-0vbnl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Daha dün gibiydi gidişiniz

Daha dün gibi geldiniz

Bunca zaman nerelerdeydiniz

Bu hangi şehrin yağmuru üzerinizdeki

Kimbilir hangi kaldırımları adımladınız

ne acılar musallat oldu başınıza kimbilir

ya yalnızlığınızdan kaçtınız

ya da yalnızlığınız

devirdi sizi böyle

tek yumrukta

Belki de o isimsiz olur olmaz meyhanelerde

dudaklarınız eksik olmadı hiç kadehlerden

dışarıda yağmur yağdı

siz içtiniz...

Siz içtiniz

bütün şehirlere gece çöktü

sokaklar ve insanlar değişti çoktan

siz içtiniz

ama bırakmadı sizi

o geberesice yalnızlığınız

Daha dün gibiydi gidişiniz

bu hangi sevdanın firari dumanı gözlerinizde

bu hangi sevdanın sağanak yalnızlığı üzerinizde

demekki gitmek size yaramıyor

kimbilir ne acı çektiniz ciğerlerinize

tütün gibi

tütünden beter.

(temmuz 00)', 'Daha dün gibiydi gidişiniz Daha dün gibi geldiniz Bunca zaman nerelerdeydiniz Bu hangi şehrin yağmuru üzerinizdeki Kimbilir hangi kaldırımla...', ARRAY['Türk Edebiyatı','Şiir','Turgut Bayğın']::text[], 8.5, '{"poet":"Turgut Bayğın","poet_slug":"turgut-baygin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gidip-gelmeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birşeyleri Mavileştiren Sendin', 'birseyleri-mavilestiren-sendin-turgut-baygin-zf7qd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Simsiyahtı o gün saçların

Kaç zamandır ilk o gün o kadar siyahtın

özlemişim meğer karanlığını

ağladın

kaç günlerin gecesi döküldü yanaklarıma

anlaşılan birileri senden söz etti bu gece

birileri intiharı denemiş olabilir üç beş kere

bir kaç tren kalktı gitti sensiz

bir kaç Haydarpaşa

bir kaç Alsancak

ayrı şehirlerden gelip geçti hüznün

Sen gittiğinden beri 

martılar hala o mavi vapuru bekliyor

ah birşeyleri mavileştiren sendin

her zaman geç kaldığın o dolmuş duraklarını

948 den kalma çiçekçi dükkanını

ve ne bayramların gelip geçtiği

ne kavgaların üzerinde adı olan o meydanları

o ilk aşkların masum gazinolarını

ah birşeyleri diyorum

mavileştiren sendin

işte ondandır şimdi bu ilk yağmurların maviliği

anlaşılan benden söz ettin bu gece

anlatamam içimde dönüp duran dünyayı.

(temmuz--ağustos 00)', 'Simsiyahtı o gün saçların Kaç zamandır ilk o gün o kadar siyahtın özlemişim meğer karanlığını ağladın kaç günlerin gecesi döküldü yanaklarım...', ARRAY['Türk Edebiyatı','Şiir','Turgut Bayğın']::text[], 8.5, '{"poet":"Turgut Bayğın","poet_slug":"turgut-baygin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/birseyleri-mavilestiren-sendin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gam', 'gam-necati-karaman-7jne1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaya gezsen ne çıkar iki cihan sana râm

Kainat tüm savrulsa olurmu hiç sana gam', 'Yaya gezsen ne çıkar iki cihan sana râm Kainat tüm savrulsa olurmu hiç sana gam...', ARRAY['Türk Edebiyatı','Şiir','Necati Karaman']::text[], 8.5, '{"poet":"Necati Karaman","poet_slug":"necati-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/gam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyine', 'neyine-necati-karaman-i5qpg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sızlanan sarsılan ahkâm vezin senin neyine

Geceler bir dolu gâm gündüz senin neyine

Devletim dâim ol dersin lâkin hikmet bilmezsin 

Aklın dünyada kalmışsa hükümranlık neyine

İnsaf bu kadar tarih bu kadar kültür berhava

Sen bu ahval sahibiyken hüküm senin neyine

Payimal  olan millettir sen nefsinle yaşa dur

Zerzebil olan izzettir bu gam senin neyine', 'Sızlanan sarsılan ahkâm vezin senin neyine Geceler bir dolu gâm gündüz senin neyine Devletim dâim ol dersin lâkin hikmet bilmezsin  Aklın dü...', ARRAY['Türk Edebiyatı','Şiir','Necati Karaman']::text[], 8.5, '{"poet":"Necati Karaman","poet_slug":"necati-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/neyine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğin Özgür Olmayınca', 'yuregin-ozgur-olmayinca-osman-erdal-erturan-h3c17', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yüreğin özgür olmayınca 

yıldızlar zincire vurulur

olmayan resimlerinde

gözlerin tutuklu kalır

sayılı olunca attığın adımlar

bin kez gidip gelirsin

ulaşmak için uzaklığına

halden anlamayınca zaman 

sessiz kalır

kül biriktirir

dumanlara

(05-08-2000 BARTIN)', 'yüreğin özgür olmayınca  yıldızlar zincire vurulur olmayan resimlerinde gözlerin tutuklu kalır sayılı olunca attığın adımlar bin kez gidip g...', ARRAY['Türk Edebiyatı','Şiir','Osman Erdal Erturan']::text[], 8.5, '{"poet":"Osman Erdal Erturan","poet_slug":"osman-erdal-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yuregin-ozgur-olmayinca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekşi Elma Ağacının Altında', 'eksi-elma-agacinin-altinda-osman-erdal-erturan-2n1mr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ekşi elma ağacını altında 

suya düştü yıldızlar

az kaldı

umutlanıyordum

parmaklarım

tel örgünün dışında', 'ekşi elma ağacını altında  suya düştü yıldızlar az kaldı umutlanıyordum parmaklarım tel örgünün dışında...', ARRAY['Türk Edebiyatı','Şiir','Osman Erdal Erturan']::text[], 8.5, '{"poet":"Osman Erdal Erturan","poet_slug":"osman-erdal-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/eksi-elma-agacinin-altinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Beyaz Kalem', 'bir-beyaz-kalem-osman-erdal-erturan-0aywr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir beyaz kalem

bir beyaz kağıda

bir beyaz gökyüzüne 

uçup gitmiş

bir beyaz kuş için yazdı

''sevgi'' ''yi

(1993 ankara)', 'bir beyaz kalem bir beyaz kağıda bir beyaz gökyüzüne  uçup gitmiş bir beyaz kuş için yazdı ''sevgi'' ''yi (1993 ankara)...', ARRAY['Türk Edebiyatı','Şiir','Osman Erdal Erturan']::text[], 8.5, '{"poet":"Osman Erdal Erturan","poet_slug":"osman-erdal-erturan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-beyaz-kalem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlem', 'duslem-yalniz-kurt-vjwyz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir ikili düşlemin ortasına sürüklendim

yüksek ateşlerin burgusundan geçip 

bir başı mağrur sevgiliden alınan öpücük gibi

her zaman cesur 

her zaman yürekli

bilmesemde

kanıma giren

bu serseri

sevgilinin kimliğini

bu karanlıklar benim değildi 

bu tapınım 

bu adresler 

bu zelzeleli mevsimler 

benim değildi

yalnız seslerimdi sessiz

uzak zamanlı duvarlarda yansıyan

anlamıyor  bilmiyordun 

içimde nice çınar ağaçları devrilmişti

kim kesmişti dallarımı böyle

hayasız

arsız 

kansız

heyy  vicdansız

alyakuz', 'bir ikili düşlemin ortasına sürüklendim yüksek ateşlerin burgusundan geçip  bir başı mağrur sevgiliden alınan öpücük gibi her zaman cesur  h...', ARRAY['Türk Edebiyatı','Şiir','Yalnız Kurt']::text[], 8.5, '{"poet":"Yalnız Kurt","poet_slug":"yalniz-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/duslem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Solukla', 'solukla-yalniz-kurt-lqvju', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'solukla 

solukla havayı

önemsemekten korkma

git

ama beni bırakma

yaşadığın

bunca zaman

ve uçtuğun

bunca yükseklik

yaşamın olacak sonsuza dek

koş tavşan koş

kaz çukuru

ve unut güneşin parlak rengini

yaşadığın bunca zaman

ve uçtuğun

bunca yükseklik

yaşamın 

amansız gelgitlerinde sürüklenirse

ve enbüyük dalgasında dengelenirse

koşarsın

erken ölümlere doğru

ve engeller

yılları çok yakında anlarsa

ve eğer tepede hiç oda yoksa

yaşanacak

vebeynin 

karanlık uğultularla patlarsa

seni 

ayın karanlık 

yüzünde göreceğim

delilik

kafanın içinde 

delilik

beyninin içindedir

bıçağı kaldırırsın 

yaşama doğru

ve değişimi sağlarsın

aklını başına getirinceye dek

kafanın içinde biri var

o  sen değilsin

ben degilim

ve fırlatıp atarsın 

çirkef bir sevdanın

dehlizine anahtarı

sonra

çoksonra

dost sandıkların 

değişik ezgiler çalmaya başlarsa

seni ayın karanlık yüzünde gören

ben olmayacağım

anlamışsındırki 

bu benim değil

duygularımın sözcüklere savaşıdır 

ve sıradan insanlarız sadece

tanrı bilir yalnızca 

sevmemiz gerekenin

ne olmadığını

çayırlıktan

çok uzaktan

bir ezan sesi  duyulur

imansızları

dizlerinin üzerinde

durmaya davet eder

koşma artık tavşan

kazma çukuru

bu ileti senin için

bak bugünde güneş doğdu', 'solukla  solukla havayı önemsemekten korkma git ama beni bırakma yaşadığın bunca zaman ve uçtuğun bunca yükseklik yaşamın olacak sonsuza dek...', ARRAY['Türk Edebiyatı','Şiir','Yalnız Kurt']::text[], 8.5, '{"poet":"Yalnız Kurt","poet_slug":"yalniz-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/solukla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasaklı Şiirler', 'yasakli-siirler-cihan-akmaz-jq946', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oğlu olmaksa rüzgarın 

Özgürlük

Kardeşi olmaksa güneşin

Hasret

Çığlığı olmaksa kartalın

İsyan

Olmaksa şövalyesi zamanın

Yalnızlık

Ve seveni olmaksa Rab bın

Aşk

Buna da sevda derler iki gözüm

Dokunma

Ateşten

Yasaklı şiirler', 'Oğlu olmaksa rüzgarın  Özgürlük Kardeşi olmaksa güneşin Hasret Çığlığı olmaksa kartalın İsyan Olmaksa şövalyesi zamanın Yalnızlık Ve seveni ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Akmaz']::text[], 8.5, '{"poet":"Cihan Akmaz","poet_slug":"cihan-akmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yasakli-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlarımız', 'kadinlarimiz-nazim-hikmet-ran-47ywj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Toprak öyle bitip tükenmez, /dağlar öyle uzakta, 

sanki gidenler hiçbir zaman 

             hiçbir menzile erişemeyecekti.

Kağnılar yürüyordu yekpare meşaleden tekerlekleriyle

Ve onlar 

ayın altında dönen ilk tekerlekti.

Ayın altında öküzler

başka ve çok küçük bir dünyadan gelmişler gibi 

                                                    ufacık kısacıktılar

ve pırıltılar vardı hasta kırık boynuzlarında

ve ayakları altından akan 

                         toprak, 

                         to
..........
..........', 'Toprak öyle bitip tükenmez, /dağlar öyle uzakta,  sanki gidenler hiçbir zaman               hiçbir menzile erişemeyecekti. Kağnılar yürüyord...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kadinlarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-zeki-demir-f8g0h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yoksun

Gidişin ilk gününde.

Yoksun

İsmin dilimde

Hayalin gözümde.

Yoksun

Özleyip bakmak istediğimde,















BİR RESMİN BİLE YOK ELİMDE.', 'Yoksun Gidişin ilk gününde. Yoksun İsmin dilimde Hayalin gözümde. Yoksun Özleyip bakmak istediğimde, BİR RESMİN BİLE YOK ELİMDE....', ARRAY['Türk Edebiyatı','Şiir','Zeki Demir']::text[], 8.5, '{"poet":"Zeki Demir","poet_slug":"zeki-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yoksun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön Artık', 'don-artik-zeki-demir-bxmr8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensizlik bir girdap oldu,

beni yuttu boğdu.

Sevdan kor ateş oldu,

yüreğimi kavurdu.

Hasretin yeldi fırtına oldu,

beni sensizliğe savurdu.

Dön artık bebeğim,

çıldırmak üzereyim.

Uzakta olsak sevdiğim ,

eminim yüreğindeyim....', 'Sensizlik bir girdap oldu, beni yuttu boğdu. Sevdan kor ateş oldu, yüreğimi kavurdu. Hasretin yeldi fırtına oldu, beni sensizliğe savurdu. D...', ARRAY['Türk Edebiyatı','Şiir','Zeki Demir']::text[], 8.5, '{"poet":"Zeki Demir","poet_slug":"zeki-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/don-artik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Düşünmediğim', 'hic-dusunmedigim-nogay-yaren-l10b9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç düşünmediğim sen,

Bir gül bahçesinde aykırı ama sevecen,

Büyümek istemedin nedense,

Hani,

Yeldeğirmeni de yoktu karşında,

Oysa sen...

Büyümek girdabına karşı 

Don Kişottun

Bir türlü sevemedin kendini..

Benim seni sevdiğim kadar.', 'Hiç düşünmediğim sen, Bir gül bahçesinde aykırı ama sevecen, Büyümek istemedin nedense, Hani, Yeldeğirmeni de yoktu karşında, Oysa sen... Bü...', ARRAY['Türk Edebiyatı','Şiir','Nogay Yaren']::text[], 8.5, '{"poet":"Nogay Yaren","poet_slug":"nogay-yaren","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hic-dusunmedigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairim', 'sairim-nogay-yaren-h3jqb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şairim ben

Anlatamadıklarımı yazarım,

Yazdıklarımı anlatamam 

Anlatmamda onun için,

Yazarım...', 'Şairim ben Anlatamadıklarımı yazarım, Yazdıklarımı anlatamam  Anlatmamda onun için, Yazarım......', ARRAY['Türk Edebiyatı','Şiir','Nogay Yaren']::text[], 8.5, '{"poet":"Nogay Yaren","poet_slug":"nogay-yaren","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sairim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksik Rüya', 'eksik-ruya-nogay-yaren-48pr7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin en olgun yerinde 

Rüyalar görülür...

Şaşkın mı şaşkındır her yanım,

Aklıma takılan ..

Yarım kalan rüyalarım..

Ölüm beyazı, sen yokken çarşafım 

Bir yanım, Ölü denizi andırır 

Saklı Kalır bir yanım ..

Bilirim;

Rüyamın yarısı da sende,

Sen gelince rüyama,

Tamamlanır her yanım.', 'Gecenin en olgun yerinde  Rüyalar görülür... Şaşkın mı şaşkındır her yanım, Aklıma takılan .. Yarım kalan rüyalarım.. Ölüm beyazı, sen yokke...', ARRAY['Türk Edebiyatı','Şiir','Nogay Yaren']::text[], 8.5, '{"poet":"Nogay Yaren","poet_slug":"nogay-yaren","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eksik-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidip Gelen Sevmelerimiz', 'gidip-gelen-sevmelerimiz-nogay-yaren-523wn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnat, ayaktaydım

Gece korkardı...

Solmaz bir çiçeğin gülüşünden

Sen çiçekdin.

Suladığım .Özene Bezene .

Sonraları ..

Bir Hoş oldu..

Kaygılarım..Kopuktum şimdi yaşamdan.

Yok canım bu ben değilim..

Sevmelerim azaldımı ne?

Ne oldu bana abartan ben?

Nerdeyim şimdi?

Sevgi nerede sen neredesin ?

Gidip gelen sevmelerim 

Bir var bir yok ...ah etmem 

Aslında bu ben..

İşte böyle gidip gelen sevmelerim 

Aklıma takılan Onca soru..

Hadi artık sevdiğim sevdiceğim...

Otur işte dizimin dibinde.', 'İnat, ayaktaydım Gece korkardı... Solmaz bir çiçeğin gülüşünden Sen çiçekdin. Suladığım .Özene Bezene . Sonraları .. Bir Hoş oldu.. Kaygılar...', ARRAY['Türk Edebiyatı','Şiir','Nogay Yaren']::text[], 8.5, '{"poet":"Nogay Yaren","poet_slug":"nogay-yaren","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gidip-gelen-sevmelerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur ve Toprak', 'yagmur-ve-toprak-nogay-yaren-u761j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmur ve Toprak

Bilirim Yağmur bile,

Özler toprağını,

Bilir susamışlığını toprağın,

Yağmur döne döne düşer toprağa

Susamışlıktır bunun adı.

Şimdi kıskanır sevdalı iki göz

Yağmurla toprağın dansını.', 'Yağmur ve Toprak Bilirim Yağmur bile, Özler toprağını, Bilir susamışlığını toprağın, Yağmur döne döne düşer toprağa Susamışlıktır bunun adı....', ARRAY['Türk Edebiyatı','Şiir','Nogay Yaren']::text[], 8.5, '{"poet":"Nogay Yaren","poet_slug":"nogay-yaren","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yagmur-ve-toprak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farklı Renkler', 'farkli-renkler-nogay-yaren-f0cid', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Farklı Renkler

Sen toprağa düşen yağmur

Sıcaklığında gelmiştin bana,

Toprağın heyecanı gibiydi 

Yüreğim..

Darmadağın hayatımdı sana anlattıklarım,

Rüzgar ile kavak hışırtısıydı

Gecedeki dostlarım...

Ve alışılmamış alışkanlıklarım vardı,

Sana zor gelen 

Ah birde olmasa dediğin..

Kıskançlığım..

Yüzümü ağartan kıskançlığım..

Sende kül rengiydi..

İşte bu yüzden sevemedim 

Seni..bu yüzden', 'Farklı Renkler Sen toprağa düşen yağmur Sıcaklığında gelmiştin bana, Toprağın heyecanı gibiydi  Yüreğim.. Darmadağın hayatımdı sana anlattık...', ARRAY['Türk Edebiyatı','Şiir','Nogay Yaren']::text[], 8.5, '{"poet":"Nogay Yaren","poet_slug":"nogay-yaren","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/farkli-renkler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zakkum ve Gece', 'zakkum-ve-gece-nogay-yaren-1fbkc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne korkular yaşadım seninle 

Ölüm dizimde ..

Zakkum sevdası gibi ..

Geceye korkuyla başlarım ..

Günahlarım ağırdır gecede .

Kusurlarım örtüşürken geceyle 

Bitmeyecekmiş gibi..

Sonsuz bir güne başlama telaşı 

Sevdan hep içimde ..

Oysa bilirim seninle,

Günahlarım ağırdır gecede.

Düşünse aklım güler mi ?

Güler mi bu halime .

Hiç hesap vermeyen ..

Asi demeye varmayan dilim ?

Ruhuma anlatır seni 

Anlatırda ...

Bilirim seninle 

Günahlarım ağırdır gecede.

Sen ve Ben 

Biliriz ki ..

Günahlarımız çoktur Gece de ..

Ve Gece bilir ki... 

Günahlar her dilde üç hece .', 'Ne korkular yaşadım seninle  Ölüm dizimde .. Zakkum sevdası gibi .. Geceye korkuyla başlarım .. Günahlarım ağırdır gecede . Kusurlarım örtüş...', ARRAY['Türk Edebiyatı','Şiir','Nogay Yaren']::text[], 8.5, '{"poet":"Nogay Yaren","poet_slug":"nogay-yaren","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zakkum-ve-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mercek', 'mercek-necip-fazil-kisakurek-cm4m9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kesildi mi yoksa ardı, arkası,

Nur diyarından kol kol gelenlerin?

Yetmez mi ampulün nura cakası,

Başları dönmez mi gökdelenlerin?

Hiç kalmadı soran : Ne var insanda?

Ben duvarda ezikbir böcek miyim?

Yoksa, pırıl pırıl, tek damla kanda,

Kainatı süzen bir mercek miyim?

                               

                                              (1978)', 'Kesildi mi yoksa ardı, arkası, Nur diyarından kol kol gelenlerin? Yetmez mi ampulün nura cakası, Başları dönmez mi gökdelenlerin? Hiç kalmad...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mercek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-necip-fazil-kisakurek-pu77a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elimde, sükutun nabzını dinle,

Dinle de gönlümü alıver gitsin!

Saçlarımdan tutup, kor gözlerinle,

Yaşlı gözlerime dalıver gitsin!

Yürü, gölgen seni uğurlamakta,

Küçülüp küçülüp kaybol ırakta

Yolu tam dönerken arkana bak da,

Köşede bir lahza kalıver gitsin!

Ümidim yılların seline düştü,

Saçının en titrek teline düştü,

Kuru yaprak gibi eline düştü,

İstersen rüzgara salıver gitsin!

                                       (1923)', 'Elimde, sükutun nabzını dinle, Dinle de gönlümü alıver gitsin! Saçlarımdan tutup, kor gözlerinle, Yaşlı gözlerime dalıver gitsin! Yürü, gölg...', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/veda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şiir de Benden Dedim Geceye', 'bir-siir-de-benden-dedim-geceye-aysel-kumru-korkut-g8nii', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir şiir de benden dedim geceye.

Sessizdi,

bütün ışıklarını soyunmuş,

esrarlı 

ve tekinsizdi.

İşi de başından aşkın, belli ki yorulmuş...

ama iyi biliyordum ben,

bütün geceler gibi

sabaha o da yolcuydu

Dedi, 

''Sen de kimsin?

Bu şiir de neyin nesi?

Bitmedi henüz işkenceler,

bitmedi dil çözmeceler.

Daha yakılacak yerler de var.

Ama güneş de doğacak birazdan,

işte benim için

en büyük keder.

Oyalama beni!

Şiir vaktimi heder eder.''

Şiirimde aşk vardı oysa,

aşkı yitirmişleri ısıtacak.

Sevgi vardı kucak kucak,

çözülmeyenlere ilaç olacak.

Kovulmak zor iş be dostlar

gittiğin kapılardan.

Elinde şiirler,

aklında neler neler...

dumanlar yükselirken çatılardan

öylece kalakalmak.', 'Bir şiir de benden dedim geceye. Sessizdi, bütün ışıklarını soyunmuş, esrarlı  ve tekinsizdi. İşi de başından aşkın, belli ki yorulmuş... am...', ARRAY['Türk Edebiyatı','Şiir','Aysel Kumru Korkut']::text[], 8.5, '{"poet":"Aysel Kumru Korkut","poet_slug":"aysel-kumru-korkut","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bir-siir-de-benden-dedim-geceye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Kadınım', 'ben-kadinim-aysel-kumru-korkut-rtpgm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Asırlardır ezilmişliğin sesini taşırım nesilden nesile,

bir yanım direnmenin türküsünde,

bir yanım nakış işleyen uysal elimde.

Sessizim, suskunum,

suskunum ölesiye.

Taş da olsa aşım,

yıllardan beri pişirir

sofranıza taşırım.

Şiirin sevecen sokaklarında

yazılmamış sözler ararım.

Hiç söylenmemiş şarkılara

güfteler yazarım.

Bebek emzirir, çocuk büyütürüm.

Karlı dağ doruklarınca umutlarım;

tuvali çekip havaya asar,

asırlar boyu ezilmişliğimin

boyasız, fırçasız resmini yaparım.

Ben de varım heyyyyy!

Ben de varım.

Fabrikada, büroda, okulda,

Adım başı ırzına geçilen sokaklarda,

Güneydoğuda, Kuzeybatıda,

tarlada, yaylada, tahta başında,

heykelde, kemanda, piyanoda,

Sri Lanka''da, Kanada''da,

dünyanın her yanında 

yüreğimin ince sızısıyla

varım ben.

Ben hepinizin annesiyim.

Ben kadınım.

Etimle, kemiğimle,

bir yanım direnmenin türküsünde,

bir yanım ağıt yakan gözlerimde.', 'Asırlardır ezilmişliğin sesini taşırım nesilden nesile, bir yanım direnmenin türküsünde, bir yanım nakış işleyen uysal elimde. Sessizim, sus...', ARRAY['Türk Edebiyatı','Şiir','Aysel Kumru Korkut']::text[], 8.5, '{"poet":"Aysel Kumru Korkut","poet_slug":"aysel-kumru-korkut","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/ben-kadinim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sekiz Nota', 'sekiz-nota-aysel-kumru-korkut-tc4e8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sekiz notadan değil mi bütün müzikler?

Şarkılar, türküler, ninniler,

özgün müzik, arabesk, pop,

sanat, arya, opera

ve ağıtlar

ve bütün klasikler?

Üç renkten değil midir binlerce renk?

Yüz binlerce resim;

boya, badana, duvar, kapı,

çiçek, ağaç, kuş kanadı;

mavi deniz, yeşil orman,

beyaz bulut, sarı güneş;

sevgi rengi, nefret rengi,

kardeşliğin toz pembesi,

düşmanlığın kara sesi?

Yirmi dokuz harf,

kitaplar dolusu sözcük,

raf dolu, kucak dolu,

özgür beyinlerin yolu.

Bilinenler, bilinmeyenler;

sevilenler, sevilmeyenler;

yakılanlar, kurtarılanlar,

suç unsuru sayılanlar;

baş köşeye konulanlar.

Anayasa, babayasa...

Yaşamın anlamı kitaplar,

şiir, roman, hikaye,

ve de anı, deneme.

Şarkı sözü, tiyatro, sinema, senaryo,

dilimin ucunda duruyor dahasının adları

ve 

e-maile taşınmış dost mektupları.

Ve faturalar

ve senet sepet,

dilekçeler, havaleler;

çek, bono, tapu, sicil,

tahvil mahvil,

kayıt kuyut,

askerlik, nüfus,

oturum kağıdı, kafa kağıdı,

iyi hal kağıdı,

sabıka kaydı

başımızın belaları.

Hepsi hepsi yirmi dokuz harf...

Ne diyelim dostlar

bir tek kibrit çöpü pişirmez mi zaten bütün aşkları?

Ve bir tek kibrit çöpü çıkartmaz mı bütün yangınları?', 'Sekiz notadan değil mi bütün müzikler? Şarkılar, türküler, ninniler, özgün müzik, arabesk, pop, sanat, arya, opera ve ağıtlar ve bütün klasi...', ARRAY['Türk Edebiyatı','Şiir','Aysel Kumru Korkut']::text[], 8.5, '{"poet":"Aysel Kumru Korkut","poet_slug":"aysel-kumru-korkut","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/sekiz-nota-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yenilir mi Sanat', 'yenilir-mi-sanat-aysel-kumru-korkut-aeld0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yenilmiş miydi müzik?

Milyonlarca ezginin kaynağı?

Coşkulu, ağıtlı, sevgili, neşeli,

hüzünlü sekiz nota?

Yenilmiş miydi

top, tüfek, makine seslerine;

uçaksavarlara, roketatarlara?

Şiir, dergi ve kitaplarda mı kalmıştı?

Sessiz miydi köşesinde?

Üzgün müydü?

Şiddet meyvelerini verirken bir bir,

öğrenci adlı taze fidanların dallarında,

okullarda, yollarda?

Yoksa o da bir başka kavgaya mı katılmıştı

unutup çocukları savaş alanı şu dünyada?

Yenilmiş miydi zamana ve teknoloji eşkiyasına resim?

Renklerini çılgınlar mı çalmıştı ressamlarımızın?

Yoksa savaş oyunu çizeri mi olmuştu hepsi

atari salonlarına?

Tiyatroyu perdesinin ardına mı hapsetmişti televizyon?

Sinema, korku ve heyecan mıydı artık?

Kan, güç, nefret, öç ve acımasızlık mıydı?

Sevgiye yer kalmamış mıydı ak perdede

ve hiçbir yerde?

Ekranlardan sızan şiddet

çok paralar kazandırdı kimilerine

yirminci yüzyılda.

Gözlerimiz kör değil,

elbet görüyoruz

ve soruyoruz:

Neden gücümüz yetmiyor bu çocukları korumaya?

Yenildi mi sanat?

Yenildi mi yarışta?

Yenilir mi sanat

bir avuç çapulcuya?', 'Yenilmiş miydi müzik? Milyonlarca ezginin kaynağı? Coşkulu, ağıtlı, sevgili, neşeli, hüzünlü sekiz nota? Yenilmiş miydi top, tüfek, makine s...', ARRAY['Türk Edebiyatı','Şiir','Aysel Kumru Korkut']::text[], 8.5, '{"poet":"Aysel Kumru Korkut","poet_slug":"aysel-kumru-korkut","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yenilir-mi-sanat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskiden', 'eskiden-adem-i-ris-fy3vk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eskisi gibi değilsin sen

Belki sen eskiden daha güzeldin

Belki dudağımda şiir 

Gözlerimde yemindin

Belki hiç bilmezsin ama

Sen tek sevdiğimdin

Ama şimdi sen;

Kadehlerde bir içkisin

Eskisi gibi değilsin sen

Belki sen eskisi gibisin

Belki sen hala yüzünde aynı masumluk

Sözünde aynı soğukluk 

Ve siyah teninsin 

Sen yaşadığıma delilsin

Ama bilki sen eskisi gibi değilsin 

Çünkü sen benim değilsin', 'Eskisi gibi değilsin sen Belki sen eskiden daha güzeldin Belki dudağımda şiir  Gözlerimde yemindin Belki hiç bilmezsin ama Sen tek sevdiğimd...', ARRAY['Türk Edebiyatı','Şiir','Adem İriş']::text[], 8.5, '{"poet":"Adem İriş","poet_slug":"adem-i-ris","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/eskiden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birazdan Gün Doğacak', 'birazdan-gun-dogacak-erdem-bayazit-vder9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nuri Pakdil''e

Beton duvarlar arasında bir çiçek açtı

Siz kahramanısınız çelik dişliler arasında direnen insanlığın

Saçlarınız ızdırap denizinde bir tutam başak

Elleriniz kök salmış ağacıdır zamana

O inanmışlar çağının.

Zaman akar yer direnir gökyüzü kanat gerer

Siz ölümsüz çiçeği taşırsınız göğsünüzde

Karanlığın ormanında iman güneşidir gözünüz

Soluğunuz umutsuz ceylanların gözyaşına sünger.

Gün doğar rüzgar eser bulut dolanır

Rahmet şarkısı söyler yağmurlar

Alnınız en soylu isyandır demir külçelere

Gürültü susar ses donar sevgi tohumu patlar

Sessiz bir bombadır konuşur derinlerde.

Ey bizim sabır yüklü toprağımızın kutsal ağacı

Sen bize hayatsın umutsun mezarlar kadar derin

Bizi tutan bir şey varsa dirilten o sensin

Üzerinde uyuduğumuz yavru kuşların tüy renkli sıcaklığı.

Ey damarlarımızda donan buz yüzlü heykeller beldesinden

Yıkıntılar sonrası sığındığım şefkat anası

Ey dağları yerinden oynatan ses ey mermeri toz eden rüzgar 

Ey alemi donatan ışık toprağa can veren el.

Gün olur toprak uyanır ağaç uyanır uyanır böcekler

Sarı bozkır titrer çıplak ağaçlar yeşerir gök yıkanır kirli dumanlardan

Su coşar deniz kabarır canlanır ölü şehirler

Yemyeşil bir rüzgar eser yıldızlar arasından.

Şimdi siz taşıyorsunuz müjdenin kurşun yükünü

Çatlayacak yalanın çelik kabuğu

Sizin bahçenizde büyüyecek imanın güneş yüzlü çocuğu.

Güzlek,1966', 'Nuri Pakdil''e Beton duvarlar arasında bir çiçek açtı Siz kahramanısınız çelik dişliler arasında direnen insanlığın Saçlarınız ızdırap denizi...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/birazdan-gun-dogacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz', 'deniz-erdem-bayazit-ygn55', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Denizin bir gülüşünü arıyor çocuklar ellerinde oltaları

Geçmişin günün geleceğin yükünü üstünde

Pul pul taşıyan balıkları

Denizin bir gülüşünü yakalıyor çocuklar ellerinde oltaları

Karaköy 1960', 'Denizin bir gülüşünü arıyor çocuklar ellerinde oltaları Geçmişin günün geleceğin yükünü üstünde Pul pul taşıyan balıkları Denizin bir gülüşü...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/deniz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haber Veriyorum', 'haber-veriyorum-erdem-bayazit-1wo77', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Altımızda kayan bu ölü şehri durdursana

Ey gücü toprak kadar eski

Ey gücü yer kadar ağır çocuk

Büyüyen elimin üstüne koy elini

Sana bir yürek vuruşu gibi belirli

Gelen zamanı haber veriyorum

Ankara 1967', 'Altımızda kayan bu ölü şehri durdursana Ey gücü toprak kadar eski Ey gücü yer kadar ağır çocuk Büyüyen elimin üstüne koy elini Sana bir yüre...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/haber-veriyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mumun Alevi', 'mumun-alevi-tugba-ucar-vt64q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'mumun öksüz ve hüzünlü dumanı,

kırmızı bir umudun üzerinde dansediyor.

bir sağa bir sola...

ben cekiyorum alevi bedenime .

o ise yitirilmis sevdaların anısına,

gözlerime salıyor mavi ısıgını

sarımtırak anılarımı bedenlerle sarmalıyor.

ben şarkı söylüyorum mumun alevine,

o kendini savuruyor.

uzun bir aşk düşünde,

eşlik ediyor bana

bir aşağı bir yukarı...

mumun alevi söyle bana ,neden bu kadar kızılsın?

alır mısın kızıllıgına beni,

yakar  mısın odalarımızı,

götürür müsün sevdiğimin yanına?

sabahları akşamları...

hey mumun çıplak ve masum dumanı,

dansedelim seninle!!...', 'mumun öksüz ve hüzünlü dumanı, kırmızı bir umudun üzerinde dansediyor. bir sağa bir sola... ben cekiyorum alevi bedenime . o ise yitirilmis ...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Uçar']::text[], 8.5, '{"poet":"Tuğba Uçar","poet_slug":"tugba-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mumun-alevi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Hayat Nereye!', 'hey-hayat-nereye-tugba-ucar-qnbqx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'açlığa gebe karınlar ve vitrinlerde bıraktıkları,

süslü beşiklerse onlar için günah olan..

gözlerinin en derininde ise intikam almak icin cırpınan acı.

onların odaları çıplak ,ama hayatları karmakarısık.

saklamak icin uğrastıkları tek sey ise hüzünleri

aşkları ise en saf,en nazlı mevsiminde,

korkuları ise güvensizliği kardeş bilmiş.

daha büyümeden küçük bedenler,

sarhoş bir yüke sancılanmışlar.

cocuk ayakları coktan nasır tutmus,

saçlarındaki kir ise hayatın bedeli.

bıçakları ise hayatın tehtidine karsı her an ellerinde,

kavga ise bulamadıkları ekmek kadar kutsal

sokaklar,caddeler babaları...

onlar hayatı çile diye bellemişler

emzirilecek coçuklar,

bekar memeler ve maço penisler,

ve açlığa gebe karınlar..

Hey hayat Nereye!

 Uğramıcak mısın bu sofralara!?..', 'açlığa gebe karınlar ve vitrinlerde bıraktıkları, süslü beşiklerse onlar için günah olan.. gözlerinin en derininde ise intikam almak icin cı...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Uçar']::text[], 8.5, '{"poet":"Tuğba Uçar","poet_slug":"tugba-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hey-hayat-nereye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kağıttan Evler', 'kagittan-evler-tugba-ucar-o5frv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kağıttan evler yaptık biz yüreklerimize,

sonrada sıcak yuvalar kurduk 

sıcak ama çarpık yuvalar!!

aşkın hor görüldüğü,

sevginin yerine hayatların istenildiği,

birbirimizden karşılık beklediğimiz,

karanlık yuvalar kurduk aslında o evlere.

o kağıttan evlere..

yataklarımıza başkalarının özlemiyle girdik

sevişirken başkalarını istedik

harmanımız ihanetti çünkü!!

geceleri soldurduk ,yıldızları karartık

yanlızlığımızdan nefret ettik

sığındık o kağıttan evlere..

birileri inatlasmalı

hayatın züppe bekaretiyle

kagıttan evler , orospu sokaklar,

erken ölümler ...

sıcak ama çarpık yuvalar!!!..', 'kağıttan evler yaptık biz yüreklerimize, sonrada sıcak yuvalar kurduk  sıcak ama çarpık yuvalar!! aşkın hor görüldüğü, sevginin yerine hayat...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Uçar']::text[], 8.5, '{"poet":"Tuğba Uçar","poet_slug":"tugba-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kagittan-evler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önden Gidenler İçin', 'onden-gidenler-i-cin-erdem-bayazit-l1ibr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Sait Mutlu, Sabri Arslan, Mehmet Emin Balyan, Ahmet Yücel''in aziz hatıralarına''

Onlar gittiler

Yalnız bir yemin kaldı aramızda

Ben şimdi bu yanda

Kasılmış çıplak bir kurşun gibiyim

Namluda.

Onlar gittiler

Topraktan bir işaret taşıyarak alınlarında

Ben şimdi bu yanda

Gerilmiş bir an gibiyim

Doğumla ölüm arasına.

Onlar gittiler

Gelen zamandan bir haber gibiydiler.

Ben şimdi bu yanda

İçilmiş bir and için bekleyenim

Kurulmuş saat gibi.

Onlar gittiler

Giderken bir muştu gibiydiler.

Ankara, 1968', '''Sait Mutlu, Sabri Arslan, Mehmet Emin Balyan, Ahmet Yücel''in aziz hatıralarına'' Onlar gittiler Yalnız bir yemin kaldı aramızda Ben şimdi bu...', ARRAY['Türk Edebiyatı','Şiir','Erdem Bayazıt']::text[], 8.5, '{"poet":"Erdem Bayazıt","poet_slug":"erdem-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/onden-gidenler-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter Artık Dön Sevdam', 'yeter-artik-don-sevdam-sair-kuscu-zht8y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yüce dağlar engel oldu 

gözlerime kanlar doldu 

genç ömrüm sararıp soldu 

yeter  yeter artık dön sevdam 

yüce dağlar geçit vermez 

o yar artık geri dönmez 

bu gönül bu gönül başka yar sevmez

yeter yeter artık dön sevdam', 'yüce dağlar engel oldu  gözlerime kanlar doldu  genç ömrüm sararıp soldu  yeter  yeter artık dön sevdam  yüce dağlar geçit vermez  o yar art...', ARRAY['Türk Edebiyatı','Şiir','Şair Kuşçu']::text[], 8.5, '{"poet":"Şair Kuşçu","poet_slug":"sair-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yeter-artik-don-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Olmamalıydı Can', 'boyle-olmamaliydi-can-mehmet-tas-effuw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'böyle olmamalıydı can

böyle olmamalıydı

deli kısrak vahşiliginde

koşup giderken zaman

bir kahpe el tutup yelesinden

kalbime kazık saplar gibi birden

ya da mil çeker gibi gözlerime

ihanetin sisli aynasından

şavkını saçmamalıydı birden...

böyle olmamalıydı can

böyle olmamalıydı

efil efil eserken rüzgar

dalda yaprak yuvada kuş

ve çocuklar mutluyken beşiklerinde

bülbüle inat açarken gonca

mevsimler hepten baharken

bir el tutup yakasından hazanın

sinsi uçuslarında yarasaların

yeniden sorgular gibi hatıraları

ya da yeniden yazar gibi tarihini

müebbed hapse mahkum bahtımın

bahçeme atmamalydı..

böyle olmamalıydı can

böyle olmamalıydı

bir mızrak ihanetindeki kalemin

sararan sayfalarıma

kan damlar gibi birden

UNUTTUM diye yazmamalıydı..

böyle olmamalıydı can

böyle olmamalıydı...', 'böyle olmamalıydı can böyle olmamalıydı deli kısrak vahşiliginde koşup giderken zaman bir kahpe el tutup yelesinden kalbime kazık saplar gib...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/boyle-olmamaliydi-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gittin Hayatın Anlamı Yok', 'sen-gittin-hayatin-anlami-yok-mehmet-tas-wpgom', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ve bir yağmur sonrasıydı

hava durgundu

gökkuşağı yedi rengini

yorgun ayaklarına sermişti...

bir kuş tüyü hafifliğinde 

sessizdi gelişin.....

susuyordun

susuyordu bütün evren

sadece gözlerimizdi konuşan.

senin kipriklerinde boncuk boncuk

benim boğazımda düğüm düğüm

öylesine asılı kalmıştı sözler...

kal gitme diyecektim

gökkuşağının yedi renginden

yedi ayrı taç öreyim başına

saçlarında tel tel yıldızlar oynaşşın....

kal gitme can

kal gitme

sen yokken bulutlar yağmur taşımaz

şahrem şahrem yarılır yer

umuda yeşermez tohum

kal gitme can

sensiz neye yarar bu şehir

bu dünya,bu evren

sensiz gün doğmaz sabahları

kuşlar ötmez

meyve vermez ağaçlar

sensiz hayat olmaz can....

kal gitme

bebekler uyanamaz uykusundan

yağmurlar yağmaz

çöl olur evren...

Bir yağmur sonrasıydı

hava durgundu

gittin hiç birşey söylemeden

bir fırtınada koydun beni

şimdi bir girdabın içindeyim

ellerim sensiz

gözlerim sensiz

ruhum bedenim sensiz

bunca sensizlik içinde

ben neye yararım.....', 'Ve bir yağmur sonrasıydı hava durgundu gökkuşağı yedi rengini yorgun ayaklarına sermişti... bir kuş tüyü hafifliğinde  sessizdi gelişin........', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sen-gittin-hayatin-anlami-yok-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma Gönül Bİr Gün Unutur Seni', 'sanma-gonul-bi-r-gun-unutur-seni-ayhan-ozturk-el-duzcevi-24hqp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne doğan güneş ne yağan yağmur 

Sanma sensiz  dünya avutur beni

Aklıma gelince o eski günler

Sanma bu gönül bir gün unutur seni

Ölmek için geç, doğmak için erken

Ömrüm geçti hep seni düşünürken

İçimde sana ait bunca şey varken

Sanma bu gönül bir gün unutur seni

Ektiğin çiçekler birgün solsada

Hasretin içimde kor’la dolsada

Adım unutulup mecnun olsada

Sanma bu gönül bir gün unutur seni

Gözlerim yaşarır adın andıkça

Sevgim bine çıkar aşkın yandıkça

Birgün  döneceğini böyle sandıkça

Sanma bu gönül bir gün unutur seni

Bir demet gül iken gönül bağımda

Kavruldum tutuşdun hasret yağında

Sevmişken seni ben  gençlik çağında

Sanma bu gönül bir gün unutur seni

Düzcevi söyleme sözü boşuna

Gecesine; gündüzüne; loşuna

Gitsede belalım senin hoşuna

Sanma bu gönül bir gün unutur seni

11 Şubat 1999 Perşembe', 'Ne doğan güneş ne yağan yağmur  Sanma sensiz  dünya avutur beni Aklıma gelince o eski günler Sanma bu gönül bir gün unutur seni Ölmek için g...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Öztürk el Düzcevi']::text[], 8.5, '{"poet":"Ayhan Öztürk el Düzcevi","poet_slug":"ayhan-ozturk-el-duzcevi","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sanma-gonul-bir-gun-unutur-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yaşamak', 'seni-yasamak-behcet-necatigil-yeiql', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni her özlediğimde sevgilim, 

Gökyüzüne bakıyorum; 

Göğün mavisinde gözlerini görüyorum çünkü.

Seni her özlediğimde bir tanem,

Denizlere bak
..........
..........', 'Seni her özlediğimde sevgilim,  Gökyüzüne bakıyorum;  Göğün mavisinde gözlerini görüyorum çünkü. Seni her özlediğimde bir tanem, Denizlere b...', ARRAY['Türk Edebiyatı','Şiir','Behçet Necatigil']::text[], 8.5, '{"poet":"Behçet Necatigil","poet_slug":"behcet-necatigil","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/seni-yasamak-83-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adın Gibi Dümdüz Olmuşsun Düzce', 'adin-gibi-dumduz-olmussun-duzce-ayhan-ozturk-el-duzcevi-djx8x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oyunlar oynardım sokaklarında

Adın bir türküydü dudaklarımda

Otobüs beklerken duraklarında

Adın gibi dümdüz olmuşsun Düzce

Zalim dünya böyleyse; dönmesin çarkın

Toplu mezar olmuş; İnönü parkın

Kalmamış; yaşayan ölüden farkın

Adın gibi dümdüz olmuşsun Düzce

Bolu Padişah Kaynaşlı beydi

Deprem her yiğidin boynunu eğdi

Üçgünlük bebeğin günahı neydi

Adın gibi dümdüz olmuşsun Düzce

Vilayet olmaktı bir tek hayalin

Kaymakam’ın oldu olmadi valin; 

Şimdi kasabaya dönmüş bak halin

Adın gibi dümdüz olmuşsun Düzce', 'Oyunlar oynardım sokaklarında Adın bir türküydü dudaklarımda Otobüs beklerken duraklarında Adın gibi dümdüz olmuşsun Düzce Zalim dünya böyle...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Öztürk el Düzcevi']::text[], 8.5, '{"poet":"Ayhan Öztürk el Düzcevi","poet_slug":"ayhan-ozturk-el-duzcevi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/adin-gibi-dumduz-olmussun-duzce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-ayhan-ozturk-el-duzcevi-xs9s4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Okusunda adam olsun isterdin; 

Okudumda adam olmadım anne

Oğlunla hep gurur duymak isterdin

Sana layık evlat olmadım anne

Bir yaşına  geldin anan kaybettin; 

Onyedi yaşında; baban kaybettin

Yaşın otuz oldu kocan kaybettin

Ömrünce tek bir kez gülmedin anne

Beş kardeştik giymedinde giydirdin, 

Kendin aç durdun; bize yedirdin

Karanlığın ardı aydınlık derdin; 

Sensiz dünyamda güneş doğmadı anne

En güzel halinle hayalimdesin; 

Hem gündüzümde hem gecemdesin

İnanmam hekimler; ne derse desin

Bende yaşıyorsun ölmedin anne', 'Okusunda adam olsun isterdin;  Okudumda adam olmadım anne Oğlunla hep gurur duymak isterdin Sana layık evlat olmadım anne Bir yaşına  geldin...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Öztürk el Düzcevi']::text[], 8.5, '{"poet":"Ayhan Öztürk el Düzcevi","poet_slug":"ayhan-ozturk-el-duzcevi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/anne-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi gel !...', 'hadi-gel-adil-koruyan-zjojm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hadi gel !..

Unutalım dünü, bugünü,

Kim olduğumuzu.

Yeni bir sayfa açalım,

Yeniden doğmuş gibi.

Kimse olmasın.

Kaderi biz çizelim,

Umutlar bizimle yeşersin.

Seven sadece biz olalım,

Hadi gel desem, gelir misin?', 'Hadi gel !.. Unutalım dünü, bugünü, Kim olduğumuzu. Yeni bir sayfa açalım, Yeniden doğmuş gibi. Kimse olmasın. Kaderi biz çizelim, Umutlar b...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hadi-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş işçisi', 'tas-iscisi-adil-koruyan-tx1g3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir taş işçisiyim, işim yaratmak,

Cansıza can vermek, taşa ruh.

Mermerin donukluğunda, gözlere sıcaklık,

Sertliğinde, saçları uçuşturmak.

Bütün bedeni ölümsüzleştirmek.

Bir tanrı misali, işim yaratmak.

Sonra yarattığım heykele kul olmak,

Ve ömür boyu sana tapmak...', 'Bir taş işçisiyim, işim yaratmak, Cansıza can vermek, taşa ruh. Mermerin donukluğunda, gözlere sıcaklık, Sertliğinde, saçları uçuşturmak. Bü...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tas-iscisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '20 Yıl sonra', '20-yil-sonra-adil-koruyan-f86vr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günler, aylar ve derken yıllar

Birbiri ardınca tam yirmi yıl geçti.

Sen yine o gül yanaklı dilber,

Ben ise, yaşlı bir aşık.

Sokaklar bile alay ediyor benimle,

Diyorlar, sevgilin hala güzel,

Sen nasıl çöktün böyle?

Cevap vermeden yürüyorum

Yaşlandığımı hissediyorum.

Yirmi yıl öncesini düşünüyorum

Seni ve bir de kendimi.

Kahin olmadığımı biliyorum,

Bunları sana söylediğimi.', 'Günler, aylar ve derken yıllar Birbiri ardınca tam yirmi yıl geçti. Sen yine o gül yanaklı dilber, Ben ise, yaşlı bir aşık. Sokaklar bile al...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/20-yil-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızca Sen', 'yanlizca-sen-gokhan-bozdogan-3a0g1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yaşıyorsak,

bu anı paylaşıyorsak

herşey farklı ayrı olmalı seninle.

sıra gelen alışılmışın dışında,

yalandan dolandan uzak bir dünya olmalı.

geri gelmesin o acılar,o keder o tasa

herşey yüreğimizce olsun,

gönlümüzce coşsun.

hissetsin dilediğim zaman ellerim ellerini

yüreğim sevgini,

yaşayalım seninle bütün geceleri.

yaşanmamışı yaşayalım

tadılmamışı tadalım.

şiirler yazalım sadece bize ait,

bizim bildiğimiz.

her zanman sevgiyle gülsün yüzümüz,

kuşatsın her yanımızı yaşama sevinci.

dans etsin umutlarımızda hayallerimiz.

bütün bir ömür botunca,

seninle başlayan günüm

seninle sürüp gitsin.

geceleri yatağımda bir gül ol.

ve

tüm yaşamımda yanlızca sen varol

seni çok seviyorum.', 'yaşıyorsak, bu anı paylaşıyorsak herşey farklı ayrı olmalı seninle. sıra gelen alışılmışın dışında, yalandan dolandan uzak bir dünya olmalı....', ARRAY['Türk Edebiyatı','Şiir','Gökhan Bozdoğan']::text[], 8.5, '{"poet":"Gökhan Bozdoğan","poet_slug":"gokhan-bozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yanlizca-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sevmek', 'seni-sevmek-gokhan-bozdogan-qr9fz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni sevmek kadar 

güzel birşey olmasa gerek.

seni ne kadar svdiğimi bir anlata bilsem

bir anlata bilsem yüreğimden gelen sesi.

bir deniz düşün,

birden bir meltem esiyor,

sarıyor vücudunu

serinletiyor ya yüreğini.

işte ben o meltemim.

bir yıldız düşün semada

yalnızca sen ve o varsın,

birden göz kırpar

kayıp kaybolur ya

hani dilek tutasın diye,

işte ben o yıldızım 

senin gecende.

umutlarını düşün sonra

hani o en zor anlarında

sığınıp beklediğin umutların varya

en mutsuz anında seni yşama bağlayan 

işte ben o umudum sevgilim yüreğinde.

her an,

en zor,en acı,en mutlu anında

yanındayım sevgilim.

beni yüreğinde hisset,

duygularınla yaşa beni.

bensizliği düşünme.

çünkü senin için,

aşkın,sevgin yüreğin,hayallerin ve mutluluğun için

bensizlik yok.

seni seviyorum ve seninleyim herşeyim.', 'seni sevmek kadar  güzel birşey olmasa gerek. seni ne kadar svdiğimi bir anlata bilsem bir anlata bilsem yüreğimden gelen sesi. bir deniz dü...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Bozdoğan']::text[], 8.5, '{"poet":"Gökhan Bozdoğan","poet_slug":"gokhan-bozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/seni-sevmek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader', 'kader-gokhan-bozdogan-thgg2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'birgün bu satırları yazarken

evimin yıkılacağını,

çadırda yaşayacağımı

özlemle geçmişimi ancağımı bilemezdim.

artık geleceğimi değil geçmişimi istiyorum,

herkes bir kere ölür ben hergün ölüyorum.

bir enkazın ağırlığı var üzerimde

yııklmayı bekleyen

mumutlarımı hayallerimi bitirmek isteyen.', 'birgün bu satırları yazarken evimin yıkılacağını, çadırda yaşayacağımı özlemle geçmişimi ancağımı bilemezdim. artık geleceğimi değil geçmişi...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Bozdoğan']::text[], 8.5, '{"poet":"Gökhan Bozdoğan","poet_slug":"gokhan-bozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kader-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİDİYORUM', 'gi-di-yorum-fatih-i-stanbullu-yy5el', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yanaklarımdan süzülüp toprağadüşen,

her damla yaşımda umutlarım saklıydı.

Ama boşa gitmediler bir çiçeğin köküne,

oradanda özüne ulaştılar.

O çiçek mechul, o çiçek sır, bilinmez.

Kim bilir belki onu sen koklayacaksın,

Dalından koparıp okşayacaksın.

Bel ki gözün gibi bakacaksın, belkide solduracaksın.

Umutlarımı sana emanet ediyorum, bense çok uzaklara gidiyorum.

Senin gelmeni istemediğim bir yere, çiçeğe hayat veren yaşatan,

karanlığa gidiyorum...

Arkam da göz yaşları bırakıyorum, şarkıları bırakıyorum, şiirleri bırakıyorum.

Ben gidiyorum kaçınılmaz  meçhule gidiyorum...

Soğuduğumu, gözlerimin karardığını hissediyorum.

Son bir kez  pencereden bakıyorum, sen yoksun gelenler arasında.

Göz yaşlarımı mendillere, hasretimi sensizliğe, sevgimi yıldızlara sarıp gidiyorum.

Umutlarımı sana bırakıyorum, zaman ayrılık vakti, beni almaya geldiler. 

Zaman meçhul, yer meçhul, taşıt meçhul. Bildiğim tek şey gidiyorum...

ELVEDA KAR ÇİÇEĞİM, ELVEDA GECE GÖZLÜM,

ELVEDA GÜNEŞ, DÜN, BUGÜN, YARIN, ELVEDA ELVEDA BÜTÜN KALANLARA ELVEDA... BEN GİDİYORUM', 'Yanaklarımdan süzülüp toprağadüşen, her damla yaşımda umutlarım saklıydı. Ama boşa gitmediler bir çiçeğin köküne, oradanda özüne ulaştılar. ...', ARRAY['Türk Edebiyatı','Şiir','Fatih İstanbullu']::text[], 8.5, '{"poet":"Fatih İstanbullu","poet_slug":"fatih-i-stanbullu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gidiyorum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalet Şehir', 'hayalet-sehir-i-brahim-sudak-r643x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kapat Gözlerini Önce

Sıyrıl  gün batımı dünyandan

varmısın? yokmusun  bilinmez ol istersen

öyleya varla yok arasındyız

gariplikler vadisinde bir garip sahradayız.

Kapat öyleyse gözlerini 

Ve kur kendi Hayal Şehrini.

Bakbakalım neler istiyorsun

burdada seviyormusun

istiyormusun aşkları ve sevdayı

istiyormusun sözüm ona arkadaşlıkları

neyse bu senin şehrin

ve senin hayalin öyleya 

ozaman kapat gözlerini önce', 'Kapat Gözlerini Önce Sıyrıl  gün batımı dünyandan varmısın? yokmusun  bilinmez ol istersen öyleya varla yok arasındyız gariplikler vadisinde...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sudak']::text[], 8.5, '{"poet":"İbrahim Sudak","poet_slug":"i-brahim-sudak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayalet-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalvarış', 'yalvaris-fatih-i-stanbullu-keilz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Merhabayla sarılan ellerimiz;

elvedayla ayrılmasın  ne olur.

Kaçamak ve masum bakışan gözlerimiz;

Nefretle kapanmasın ne olur.

Gezdiğimiz sahiller, yazı yazdığımız kumsallar;

Nefretle anılmasın ne olur.

Her şey birgin ölmeye mahkumdur;

Sevgimizde bizimle beraber ölsün ne olur.

Gülen ve  bakmaya doyamadığımız yüzümüze

yağmur yağmasın ne olur.

Ve benim ol bende senin HEP BİRLİKTE OLALALIM NE OLUR.', 'Merhabayla sarılan ellerimiz; elvedayla ayrılmasın  ne olur. Kaçamak ve masum bakışan gözlerimiz; Nefretle kapanmasın ne olur. Gezdiğimiz sa...', ARRAY['Türk Edebiyatı','Şiir','Fatih İstanbullu']::text[], 8.5, '{"poet":"Fatih İstanbullu","poet_slug":"fatih-i-stanbullu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yalvaris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun', 'sen-yoksun-fatih-i-stanbullu-ucjjp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasretin gözlerine takıldı gözlerim.

Yalnızlığın canını almak istiyor ellerim.

Yasak kelimeler konuşuyor artık dilim.

Ne olursa olsun artık olacaksa yada olmaya razıysa.

Hasret kurşunlar sıkıyor bağrıma, canım yanıyor.

Yüreğimde depremler oluyor, kıyamet koparcasına

Ellerim bir sarhoşunkinden farksız bir titremede

Sisli bir havada uçamaya çalışan bir martıyım.

Fırtınalı bir havaya dayanmaya çalışan bir uçutma umutlarım..

Ve küskünüm sensiz herşeye;içtiğim suya, yediğim yemeğe,

aynadaki görüntüme, kalem tutan ellerime küskünüm.

Çok sevdiğim sevmeyi bile sevmiyorum  artık.

Kandırmaya çalışıyorum ama kanmıyor yüreğim, çocukça ağlamada...

Çünkü sen yoksun,  öksüz ellerim, çaresiz yüreğim, titrek ve yalancı gülüşüm

bir kandırmacada...

Ve yalnızım karanlıktan daha yalnız, yalnızlıktan daha yalnız...

ÇÜNKÜ SEN YOKSUN, BEN VARRIM, BEN YALNIZIM, YALNIZ BENİM... :(((', 'Hasretin gözlerine takıldı gözlerim. Yalnızlığın canını almak istiyor ellerim. Yasak kelimeler konuşuyor artık dilim. Ne olursa olsun artık ...', ARRAY['Türk Edebiyatı','Şiir','Fatih İstanbullu']::text[], 8.5, '{"poet":"Fatih İstanbullu","poet_slug":"fatih-i-stanbullu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-yoksun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '7.', '7-sair-talay-y7u3j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zaman akıyordu.

Bilmiyordum o dönemde tam olarak saatlerin neyi gösterdiğini,

Sadece güneşin ve akşam üstlerinin tadı vardı yaşamda,

Ufak bir çocukken, tepeler hayal ederdim,

Koşardım, annemin arkamdan seslenen seslerini dinlemeden,

Hep bir ufuk olurdu ve tepelerin arkası ....

Ulaşılacak hep bir nokta, yeşil yemyeşil hazlar,

Sevincimin rengiü, hüznün şekerlerle kandırılmaya eğilimli bir tadı vardı,

Sevgi komşu kızının güzel gözleriydi,

Zaman akıyordu,

Ovalar sarıya boyandı,

Şimdiyalnızım,

Ne aşılacak tepeler, ne dönülecek evler,

Renkler kayboldu,

Ve güzel gözler ....

Ne yapar 

Bir nehir 

Eğer denizi bulamazsa', 'Zaman akıyordu. Bilmiyordum o dönemde tam olarak saatlerin neyi gösterdiğini, Sadece güneşin ve akşam üstlerinin tadı vardı yaşamda, Ufak bi...', ARRAY['Türk Edebiyatı','Şiir','Şair Talay']::text[], 8.5, '{"poet":"Şair Talay","poet_slug":"sair-talay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçmeler Ustası', 'vazgecmeler-ustasi-tugrul-asi-balkar-v1daa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya kirletilmişse,

Üstünüze sıçramış 

Bir şey vardır mutlaka.

Benimki aşktan bir leke,

Kazındıkça kendini temize çeken

Gizlice. Sürtündükçe kıvılcımlar saçan

Çakaralmaz renk cümbüşü işte.

Ya sizinki? 

Ben vazgeçmeler ustasıyım.

Reddedemem önerinizi,

Paylaşalım elbette:

Lekeniz sizde kalsın, 

Ben aşk''ı alırım sadece.

Dünya kirletilmişse,

Üstünüze sıçramış 

Bir şey vardır mutlaka.

Benimki iki soluk arasında

Gelip geçen zaman.

Hangisi ölüm hangisi yaşam? 

Ya sizinki? 

Ben vazgeçmeler ustasıyım.

Yaşadığınız bir ömür değil mi? 

Seçimi siz  yapsanız, istediğiniz sahneyi seçseniz:

İster ilkincisi olsun ister sonuncusu fark etmez ki,

- Başarımızı arttıracaktır provalardaki performansınız -

Artanıyla yetinirim zaten ben, ilk gösteri için 

siz önden buyrunuz  lütfen! 

Dünya kirletilmişse,

Üstünüze sıçramış

Bir şey vardır mutlaka.

Benimki korkusuz ve kuşkusuz bir aşk,

Başdöndürücü  ve anısız,

Fısıldaşmaları dalgınlıklara takılı.

Ya sizinki? 

Hala anlamadınız mı? 

Demiştim:

Ben vazgeçmeler ustasıyım. 

Aşk''ı bana terk etmiştiniz zaten,

Üstü...kalabilir sizde...', 'Dünya kirletilmişse, Üstünüze sıçramış  Bir şey vardır mutlaka. Benimki aşktan bir leke, Kazındıkça kendini temize çeken Gizlice. Sürtündükç...', ARRAY['Türk Edebiyatı','Şiir','Tuğrul Asi Balkar']::text[], 8.5, '{"poet":"Tuğrul Asi Balkar","poet_slug":"tugrul-asi-balkar","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/vazgecmeler-ustasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GEL', 'gel-sair-nuri-ks230', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonbaharda bekleme beni

Gül açma mevsiminde gelirim dedin

Gel...

Kadife gülde arama beni

Sarı güler benim dedin

Gel...

Aradan kaç mevsim gecti

Gel...

Artık bitsin hasretim.

Gel...

Sarı gülüm nezaman istersen

Gel...

Ilık ılık vuslat rüzgarı eserken

Gel...

Ben seni hiç beklemesken

Gel...

Yayılsın dört yana kokun

Gel...

Sarı yapragınla ruhuma dokun

Gel...

Azametinden diğer güller solsun

Gel...

Bir can borcum var,senin olsun

Gel...

Kara toprağıma sarı gülüm

Ne olur ben cagırmadan gel

Eyy! Sevgili ölüm...', 'Sonbaharda bekleme beni Gül açma mevsiminde gelirim dedin Gel... Kadife gülde arama beni Sarı güler benim dedin Gel... Aradan kaç mevsim gec...', ARRAY['Türk Edebiyatı','Şiir','Şair Nuri']::text[], 8.5, '{"poet":"Şair Nuri","poet_slug":"sair-nuri","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gel-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkimiz mi Hemen mi', 'i-kimiz-mi-hemen-mi-umit-yasar-oguzcan-j31cm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oraya varmak mı? İkimiz mi? Hemen mi?

Dur, bekle beni, geliyorum

En güzel yerinden öpeceğim

Bilmem dudakların mı? Gözlerin mi?

Önce sesindi beni çağıran aşka

Sonra bakışların, ellerin oldu

Ve bir sabah başladı ömrümde, nasıl

Gördüğüm bütün sabahlardan başka

Frenleri patladı içimde özlemin

Ben bu aşkı dizginleyemem artık

En iyisi gelmen bana, gel ama hiç gitme

Varalım doyulmaz tadına bitişikliğin.

 Bak ellerin de üşümüş, ama kalbim sımsıcak

Titreme, korkma; artık yanımdasın

Hiç bırakma bu çocuksu hâlini, ne güzel

Ne güzel seninle bir aydınlık olmak

Söyle, bir daha söyle, benim de, seninim de

Yaklaş uyandır beni bir ölüm uykusundan

Sarın maviliğime, bu bizim gökyüzümüz

Baksana,bir evren çalkalanıyor içimde

Oraya varmak mı demiştin? En yüceye

İkimiz miydi? Hemen miydi?

Bak nasıl seninle bir bütün olduk şimdi

Nerde miyiz? Oradayız işte', 'Oraya varmak mı? İkimiz mi? Hemen mi? Dur, bekle beni, geliyorum En güzel yerinden öpeceğim Bilmem dudakların mı? Gözlerin mi? Önce sesindi ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ikimiz-mi-hemen-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimdi o? Yanındaki kimdi?', 'kimdi-o-yanindaki-kimdi-umit-yasar-oguzcan-usssi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimdi o? Yanındaki kimdi? Ne konuşuyordunuz? İşte buna dayanamam. Kahrolurum.

Dün gece ne yaptın? Nereye gittin? Ah otursaydın da beni düşünseydin ya! Eğlenebildin mi bari?

Yatarken ne okudun? Sonra iyi uyuyabildin mi? Rüyanda neler gördün? Söylesene.

Anladım artık beni sevmiyorsun. Sevdiğini sanmakla yanılmışım.

Zaten çirkin bir adamım ben, sinirliyim, kıskancım, fazla hisliyim. Daima beni seveceğini düşünmemeliydin. Suçluyum. Kendimi sevgilerimin bencilliğinden kurtaramadım. Zayıf, bencil bir adamım öyleyse.

Sonra yalancıyım, iki yüzlüyüm. Seninle konuşurken seninle yatmayı düşünüyorum. Sevgiyle elini tuttuğum zaman, aslında kalçalarını tutuyorum, bilmiyorsun.

Kendime göre hesaplarım da var benim. Yanımda olman gurur veriyor, sevinç veriyor bana. Fakat sana kimse bakmasın istiyorum, kimse konuşmasın seninle. Hep benim ol, durmadan benim ol. Günün her saatinde ve ölünceye kadar benim ol.

Beni seviyor musun? Evet mi? Öyleyse söyle. Kimdi o? Yanındaki kimdi? Nereye gidiyordunuz?

Seven zalimdir biliyorsun, aşk egoisttir. Sen zalim olma. Anlamıyorsun, anlamıyorsun.... . Biraz anla beni.

Sana sitem etmeyeceğim artık. Bütün suç benim. Seni bu kadar sevmemeliydim. Şu köhne ve utanmaz dünyada ne bir kimse bu kadar sevilmeye değer, ne de bir kimsenin bu kadar sevmeye hakkı var.

Kendimizi ne sanıyoruz? Biz neyiz ki? Sus, cevap verme. Teselliye ihtiyacım yok.

Seni bu kadar sevmenin cezasını kendime ödeteceğim. 

Göreceksin.', 'Kimdi o? Yanındaki kimdi? Ne konuşuyordunuz? İşte buna dayanamam. Kahrolurum. Dün gece ne yaptın? Nereye gittin? Ah otursaydın da beni düşün...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kimdi-o-yanindaki-kimdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Yaşamadan Olmaz', 'seni-yasamadan-olmaz-hasan-ejderha-atp2u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni yaşamadan

Ne ekinler göverir

Ne de koyverir söğüt yeşilini

Bülbül çıkamaz sabaha uyumadan.

Seni yaşamadan olmaz can

Bereketsiz olur harman

Sevinemez babam

Yenilenemez urbam

Seni yaşamadan...

Olmaz seni yaşamadan

Yitik güzellikler bulunmaz

Nohut tarlada kalır yolunmaz

Yayık yayılmaz

Gelin olunmaz

Olmaz, olmaz

Seni yaşamadan

Ali birden ikiye geçemezdi

Her yıl bire-beş gelen hasat

Bakarsın bu yıl gelmezdi

Seni yaşamadan

Belki gülmesini bilmezdi bebekler

Somurtkan olurdu bütün beşer

Çirkin olurdu belki de güzel olacaklar

Yapa-yalnız kalırdı belkide eşler

Seni yasamadan.', 'Seni yaşamadan Ne ekinler göverir Ne de koyverir söğüt yeşilini Bülbül çıkamaz sabaha uyumadan. Seni yaşamadan olmaz can Bereketsiz olur har...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-yasamadan-olmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem Hasta Değildi O Zaman', 'annem-hasta-degildi-o-zaman-hasan-ejderha-8whx0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Bilge''ye''

Annem hasta değildi o zaman

Babam başını elleri arasına alıp

Uzaklara, taa uzaklara dalıp

Geceler boyu düşünmezdi

Yine gelmiştik buralara

Uzaklara gitmemiştim ben

Koşup yamaçlara

Getirmiştim anneme her çiçekten

Annem hasta değildi o zaman

Babam elimden tutardı yolda

Annem hasta değildi o zaman

Herkes saçlarıma gülüyor okulda

Nolur anneler hasta olmasın

Kurdaleli gelsin kızlar okula

Annem hasta değildi o zaman...

Babam at oludu bana evde

Hepsi oluyor babaların belki de

Akşam evlerine gelince

/Şimdi düşünüyor babam

şimdi üzülüyor babam/

Ben de 

Ağlıyorum babam görmeden.

Annem hasta değildi o zaman...

Uyukladı mı babamı yerine kaldırırdık

/Babam uyumuyor artı

Babamın yüzü karanlık/

Olsun... Ben de uyumam

Ama... Babamın gömleği yırtık

Büyümeye çalışıyorum durmadan

Büyüyünce dikerim onu ben

Biliyorum üzülüyor annem

Üzülmesin iyileşsin annem

Babama bakabilirim ben.', '''Bilge''ye'' Annem hasta değildi o zaman Babam başını elleri arasına alıp Uzaklara, taa uzaklara dalıp Geceler boyu düşünmezdi Yine gelmiştik ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/annem-hasta-degildi-o-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyalarımı Yoluyorum', 'ruyalarimi-yoluyorum-hasan-ejderha-dbxa5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I.

Harmanı yanan bir ihtiyarın 

Yoksulluğunca yanıyorum

Onmaz bir yarayım şimdi

Bir yetimin gözyaşında kanıyorum

Tutturmuşum baharlar diye

Gelmeyen baharın çiçeğiyle oynuyorum

Rüyasına yatıyorum bir çiçeğin

Sonra rüyalarımı yoluyorum

Buz kaplı yüreklere kaçıyorum

Olmuyor, yine de kaynıyorum

Hrmanı yanan bir ihtiyarın

Yoksulluğunca yanıp

Gelmeyen baharın

Gelişine ağlıyorum.

II.

Beni bir hangara çekin

Ağlayacağım.

Bahtımı avuçlarımda topladım

Bağlayacağım.

Öyle susuzum ki

Kanmayacağım.

Yaşım, yam-yaşım biliyorum

Yanmayacağım.

Oysa, bir sevgi esintisi gelse

Parlayacağım.', 'I. Harmanı yanan bir ihtiyarın  Yoksulluğunca yanıyorum Onmaz bir yarayım şimdi Bir yetimin gözyaşında kanıyorum Tutturmuşum baharlar diye G...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ruyalarimi-yoluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiiraydın Gün', 'siiraydin-gun-celal-kabadayi-owh4k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'günaydın şiir,şiiraydın gün

elimde demsiz çayım

yine çok şekerli düşlerdeyim

güneş ufuktan dokundukça göğe

mavilik belirginleşiyor gözlerimde

serin serin kıvırtıyor tanyeli

sokakta erkenciler oynaşıyor

gözlerinde son uyku kırıntıları

geceyi siliyorlar içlerinden

apak şiirler sızıyor yüreğime

her sabah yeniden doğuyorum aşkla

koşup perdeleri aralıyorum hemen

Sibel birazdan geçecek diye

sevinçler uyandırıyor ilkyaz içimde

güneşi sıyırıp yedi renginden

boyuyorum bütün karanlıkları

aydınlık sözcüklerle karşılıyorum yaşamı

günaydın şiir,şiiraydın gün', 'günaydın şiir,şiiraydın gün elimde demsiz çayım yine çok şekerli düşlerdeyim güneş ufuktan dokundukça göğe mavilik belirginleşiyor gözlerimd...', ARRAY['Türk Edebiyatı','Şiir','Celal Kabadayı']::text[], 8.5, '{"poet":"Celal Kabadayı","poet_slug":"celal-kabadayi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/siiraydin-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İz', 'i-z-selami-karabulut-md9jd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İZ

                             Dilek Bingül'' ün anısına

gidiyorsun, dudaklarında ürperten bulanıklık

yanıtsız soruların soğuk esintisi

çiğnenmiş mevsimin gücenik göğünde

alnında çözüldükçe büyüyen hüznün dilsizliği

izi keşkelere karışmış zorlu bir ikilem

gölgelere düşen güz dönümü burukluğunda

uzak mevsimlerin yüzünde yalnız yabancılığı

hangi acının örsüne değen zamana denk

dudaklarındaki gülüşün, yarım kalmış menevişi

sinsi bir elin hoyratça sildiği izde

geride kalan boş bir kovanın uğultusu

anlatır düğümlenen esrarın karmaşık yazgısını', 'İZ                              Dilek Bingül'' ün anısına gidiyorsun, dudaklarında ürperten bulanıklık yanıtsız soruların soğuk esintisi çiğn...', ARRAY['Türk Edebiyatı','Şiir','Selami Karabulut']::text[], 8.5, '{"poet":"Selami Karabulut","poet_slug":"selami-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/iz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Düşlerimin Ortağı', 'yalanci-duslerimin-ortagi-tugba-ucar-1bjoq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir gece yalancı düşlerimin ortağı oldu,

kamçıladık içimizdeki kötü adamı..

sevgim diyerek önüne  biraz ten koydum

öpmek güzeldi,

hiç reddetmedi..

karanlık banklarda ellerimiz değil

intikam dokunuyordu birbirine.

yitirmistik ve yalancı bir düşe ortaklık ediyorduk şimdide..



deniz kokusu , coktan bizden olanları götürmüş,

ve bizi bekliyordu.

alışmıştı deniz kentin fedakar ışıkları altında kanamaya.

dalgaları duyamıcak kadar kördüm!..

ben ona sarıldım ısıtsın diye ;ancak ısıtmıyor,

aksine içimi üşütüyordu.

biraz ten koydum önüne,

ten güzeldi..

yüregi sallananların unutmak icin tek ilacı..

biz onunla ıslak bir öpücüğü paylastık sadece,

haram kıldık sonrasını.

sevgiyi ise deniz coktan dalgalarına ortak etmisti,

ten güzeldi

hiç  reddetmedi....', 'bir gece yalancı düşlerimin ortağı oldu, kamçıladık içimizdeki kötü adamı.. sevgim diyerek önüne  biraz ten koydum öpmek güzeldi, hiç reddet...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Uçar']::text[], 8.5, '{"poet":"Tuğba Uçar","poet_slug":"tugba-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yalanci-duslerimin-ortagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensin', 'sensin-gulay-atilay-aagbo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benimde oldu!!

Adını koyamadığım.

Suçummu günahımmı?

Sırımmı desem?

Düşünce özgürlüğünü aşan

Arzularla tutuşan

Alev alev yanan söndüremediğim

Bedenime ızdırap veren

Yanlız yatağımı dağıtan

Ruhuma tazelik veren 

Unutulmayacak hazları tattıran

Günahım!!!!

Sevgi yoksunluğumdaki

Suçum!!!

Kalbimin derinliklerindeki

Sırrım!!!

Sensin bu altına imza atamıyacağım 

Kaleme aldıklarım

Sensiz seninle olan her anım

Düşüncelerin sonunda

Kavrulan bedenim

Duyduğu hazzın sonunda

Doyuma ulaşırken

Dudaklarımda ismini ısırdığım 

SENSİN!!!!', 'Benimde oldu!! Adını koyamadığım. Suçummu günahımmı? Sırımmı desem? Düşünce özgürlüğünü aşan Arzularla tutuşan Alev alev yanan söndüremediği...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sensin-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Desen', 'gel-desen-gulay-atilay-nu5wz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gel desen bir gün bana geldesen

Özlem yüklü kalbin ruhuma işliyen sesinle 

Bana gell!!!!  desen 

Seninim!! senin olanı benden istesen 

Bekleyişlerim düşünce sonsuzluğunda

Özlemim sensizlik mayasıyla kabardı

Kalbim yanlızlığımın kahrında 

Gel desen birgün bana gel desen!!

Sensiz geçen her günümün ardında sen 

Boş yatağımın baş ucunda sen!!!

Kalbimde sonsuz sevgin..

Bana verdiğin minicik resmin.....

Vesen sen herşeyim.. bana gel desen!!

Biliyormusun neler olacak ?

Ömrümün sonbaharında

Bahar çiçekleri açacak..

Saçılacak  dört bir yana rengarenk güller

Mutluluk çığlıkları atacağım ekseninde 

Seninim geldim!! feryatlarım kaplıyacak evreni

Ne olur ahh!! ne olur ? BANA GEL!!!desen...

Ömrüm seni beklemekle geçecek olsada

Sana adadım son tebessümlerimi.

Sen sen BİRTENEM son nefesimsedede olsa

Ne olur ne olur?BANA GEL!!desen.

Benimsin KADINIM desen !!!', 'Gel desen bir gün bana geldesen Özlem yüklü kalbin ruhuma işliyen sesinle  Bana gell!!!!  desen  Seninim!! senin olanı benden istesen  Bekle...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gel-desen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Bir Dönsen', 'bana-bir-donsen-gulay-atilay-xgu7c', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensiz hergünümün ardından gün batıyor...

Başlıyor gün boyu sensizliğimin  ruh baskısı

Yat yata bilirsen.. uyu .uyu diyorum kendime

Kalbim isyan ediyor sensizliğime

Neden neden?diyorum.neden sensizim ben?

İsyan ediyorum kaderime....

Aahhh!!!!  bana bir dönsen...

Kalbimin isyanına ruhum.

Ruhumun isyanına bedenim dayanmıyor

Gözlerimdeki son ışık ümitsizlikle soldu.

Duyduğum her şarkı beni ağlatıyor..

Yazdığım her şiirde sen. yanlız sen ..

Artık kalemimle bir bütünüm ben.

Ahhh!!!! bana bir dönsen..

Biliyormusun nelerle avunuyorum?.

Senle geçen günlerimi unutamıyorum

Sor bana birtanem. hangi gün? diye

Ben hergün seninle sensizliği yaşıyorum..

Bu isyan bu bekleyiş bitecek biliyorum

Kaderime kahroluşlarım son bulacak.

Ahhh!!! bana bir dönsen.

Dökülüyor bahar dallarındaki meyve çiçekleri

Ben kokularını duyamıyorum neden?

Tükeniyor tanrının bahşettiği günler 

Bunu biliyorum gülemiyorum neden?

Sensizliğin verdiği ızdırablarla ben

Göçüp gitsemde ne olur ''''beni unutma'''' sen.

Ahhh!!!!! ahh!! ne olur bana bir dönsen...

Yazdıklarım burada bitmiyecek 

Sanırım  kalemimde beni terk etmiyecek.

Ben bir gün.birgün onu terkedersem ..

Sen. sen birtanem bembeyaz sayfalarımda 

Sonsuza dek tertemiz yaşayacaksın.

Şiirlerimde mutsuzum yarınlarımdan umutsuzum..

Yinede diyorum.Ahhh!!!! 

Ahh!!BANA BİR DÖNSEN..

BİRTANEME..', 'Sensiz hergünümün ardından gün batıyor... Başlıyor gün boyu sensizliğimin  ruh baskısı Yat yata bilirsen.. uyu .uyu diyorum kendime Kalbim i...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bana-bir-donsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümün Son Deminde', 'omrumun-son-deminde-gulay-atilay-v2jhx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ömrümün son deminde

Ateşten gömlek giydim

Desenlerini aşkın hasretin özleminle

Süsledim.

Nakış nakış düşüncelerimle bezedim.

Düğmelerini iliklerken

Birtanem!!!!dedim

Aşkım !!!!dedim

Özlemim!!!! dedim

Arzum !!!! dedim 

Hasretim!!!! dedim 

Yoksun biliyorum belki hiç olmıyacaksın :((

Yemin ederim!!!! sen çözmeden ..

Çıkmıyacak gömleğim

Hasretinle yaksada bedenimi

Nakış nakış seninle bezediğim 

Gömleğimle öleceğim .....', 'Ömrümün son deminde Ateşten gömlek giydim Desenlerini aşkın hasretin özleminle Süsledim. Nakış nakış düşüncelerimle bezedim. Düğmelerini ili...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/omrumun-son-deminde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akşam', 'aksam-osman-guzelgoz-0fzs0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günbatımlarının hüznüyle

İçimde titrer

Ve tüllenir akşam

Geceye kollarını açıp

Hasretle hüzünlenir akşam

Ağaran saçlarıdır gündüzlerimin

Sızlayan başımda

Güllenir akşam

Tenim izlerini taşır

Gecelerimle savaşır

Ellerinden tutup garipliğimin

Ufkuma ulaşır akşam', 'Günbatımlarının hüznüyle İçimde titrer Ve tüllenir akşam Geceye kollarını açıp Hasretle hüzünlenir akşam Ağaran saçlarıdır gündüzlerimin Sız...', ARRAY['Türk Edebiyatı','Şiir','Osman Güzelgöz']::text[], 8.5, '{"poet":"Osman Güzelgöz","poet_slug":"osman-guzelgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aksam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-gokhan-bozdogan-h3abb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'senin yanında zaman duruyor saatler geçmiyorsa

ellerini tutarken kalbim hızla çarpıyorsa

gözlerine bakarken hayatım anlam buluyorsa

birtek sebebi var sevgilim,

sana olan sevgim', 'senin yanında zaman duruyor saatler geçmiyorsa ellerini tutarken kalbim hızla çarpıyorsa gözlerine bakarken hayatım anlam buluyorsa birtek s...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Bozdoğan']::text[], 8.5, '{"poet":"Gökhan Bozdoğan","poet_slug":"gokhan-bozdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seni-seviyorum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Batık', 'batik-zeynep-uzunbay-hoylv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Batıyormuşum da

Batmışım

Bir uzak maviye

Limanımmışsın gibi sen 

Gelemeden sana

Böyle batık batık dururken 

Özlüyorum işte

ÖZLEMEK bu ya...', 'Batıyormuşum da Batmışım Bir uzak maviye Limanımmışsın gibi sen  Gelemeden sana Böyle batık batık dururken  Özlüyorum işte ÖZLEMEK bu ya......', ARRAY['Türk Edebiyatı','Şiir','Zeynep Uzunbay']::text[], 8.5, '{"poet":"Zeynep Uzunbay","poet_slug":"zeynep-uzunbay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/batik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz Sokak', 'cikmaz-sokak-umit-yasar-oguzcan-whmu5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir daha dünyaya gelsem

Yine seni severdim

Beni üzesin diye

Beni deli divane edesin diye

Biliyorum

Sen de bir daha dünyaya gelsen

Yine beni sevmezdin

Kahrımdan öleyim diye', 'Bir daha dünyaya gelsem Yine seni severdim Beni üzesin diye Beni deli divane edesin diye Biliyorum Sen de bir daha dünyaya gelsen Yine beni ...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cikmaz-sokak-158-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Eski Yalnızlığımdır Aşk Benim', 'en-eski-yalnizligimdir-ask-benim-umit-yasar-oguzcan-azpac', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En eski yalnızlığımdır aşk benim

Gitgide büyüyen karanlıklarla

Ne zaman sevdiysem kavruldu tenim

Bir ateşin açtığı yanıklarla

Sabahı olmazdı çok gecelerin 

Alır, götürürlerdi beni onlar

Öptüğüm elleriyle, korkunç derin 

Bir uçurumun kenarına kadar.

Sonra bırakır giderlerdi, üzgün

Bakardım sessizce arkalarından 

Sonra umutsuzluk, gözyaşı ve kan.

Bütün umutlarım biterdi bir gün 

Bir gecenin orsatında kalırdım 

Tek başıma ben, ben ve yalnızlığım.', 'En eski yalnızlığımdır aşk benim Gitgide büyüyen karanlıklarla Ne zaman sevdiysem kavruldu tenim Bir ateşin açtığı yanıklarla Sabahı olmazdı...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/en-eski-yalnizligimdir-ask-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İklimsizlik', 'i-klimsizlik-selami-karabulut-sx5br', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'KİKLİMSİZLİK

koynunda sakla üşümesin bu an’ımız

dudaklarında buruk tadıyla kalsın

buğulu gözlerin bir gece yarısı treni

nerelere götürdü beni bir bilsen

bir oylum köz, solgun fotoğraflarda kalmış gülüş

solgundu bütün mevsimler sen gideli

gözlerim yağmurlu bir günün ikindisi

üşürdüm ıslak anıların sağanağında

ne bir karanfil ağızlı baharı

ne de güne düşen suretimde bulutsuzluğu düşledim

sessizliğin yanıtsız soruların toplamı

ne kadarda birikmiş iri, siyah gözlerinde

kül renginde bir kaç kırık sözcük

harlı ateş gibi yakıyor düştüğü yeri

bana hep boşa yitip giden günleri anımsatıyor

boşa akıp giden yıldızları

bir düş değil şu an yaşadıklarımız

gerçeğin aynasında endamı görkemli

teninde yaz şafağı bir akşam

keyfince çıkar tadını

menekşeler açsın gözlerinin kuytuluğunda

belki zor bir dahaki sefere

kuşlar kanatlarında hep gurbet taşırken bize', 'KİKLİMSİZLİK koynunda sakla üşümesin bu an’ımız dudaklarında buruk tadıyla kalsın buğulu gözlerin bir gece yarısı treni nerelere götürdü ben...', ARRAY['Türk Edebiyatı','Şiir','Selami Karabulut']::text[], 8.5, '{"poet":"Selami Karabulut","poet_slug":"selami-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/iklimsizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heyecan ve Fırtına', 'heyecan-ve-firtina-nurullah-genc-q1vjk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir hitit lalesi tanıyordum ilk defa

masum bir aldanıştı hayat pencerelerde

intiharı koklayan çiçeklerle beraber

çığlıklarıma tutkun bir kuyunun dibinde

onun o gökkubbeyi yakan güzelliğini

şarkılar soyleyerek anıyordum ilk defa

gemi benim olmalı, su benim olmalıydı

gemiciler göklerde ruhumu bulmalıydı

tutuşan bir dal gibi titriyordum ilk defa

yuvasız karıncalar ve kuşlarla bilendim

kahır yüklü atlarla, yokuşlarla bilendim

bulutları ayinde görüyordum ilk defa

mazide kın arayan kılıçlarla bilendim

yollar hep bana doğru koşuyor; farkındayım

dağlar bile kendini aşıyor; farkındayım

savaşçı mızrağını kırıyor sevda için

cemre damarlarıma düşüyor; farkındayım

üflenen her kandilin yerinde bir süreyya

ağlayan her çocuğun bakışlarında akşam

ölümüne müstehzi adımlarla yaklaşan

esir uykularında kalan binlerce rüya

çelik prangaları süsleyen hakimlere

ulaşır mı, merhamet ırmağı taşısa da

ihanete uğrayan gözyaşları gibiyim

gene siyah bir perde çekildi üzerime

silahlar avutuyor benimle kendisini 

oysa ben yalnız senle avunuyorum

öfkeli mahkemeler, kan tüküren dosyalar

cinnet savcılarını sürüyor menzilime

oysa ben yalnız seni, seni savunuyorum', 'bir hitit lalesi tanıyordum ilk defa masum bir aldanıştı hayat pencerelerde intiharı koklayan çiçeklerle beraber çığlıklarıma tutkun bir kuy...', ARRAY['Türk Edebiyatı','Şiir','Nurullah Genç']::text[], 8.5, '{"poet":"Nurullah Genç","poet_slug":"nurullah-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/heyecan-ve-firtina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Umu', 'son-umu-selami-karabulut-s2syv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SON UMU

                                     Metin Altıok’a

eski bir ilkyaz resminden yontulmuş

göğünü arayan sorularla geldim

düğümlenen sesimde dizginsiz sözcükler…

anlatacaklarımı hangi suskunluk bozabilir 

bilmem ki!

ıslanmış bir bekleyişin daralan soluğunda 

son umu bu, acıdıkça tazelenen

uzak yollardan biçimlendirip alnıma kondurduğum

uğuldarken ardımdan yılgın ıslığıyla rüzgâr

ömrüm, küllenen hangi yanılgının serinliği bu

sustuğum yerde başlayıp bastığım izlerde büyüyen

sökülürken ayazlanmış bir gönencin örgüsü

kaldırımlara düşen gölgem kadar yalnızken

yadsıdıklarımı yeni baştan düşündüm de geldim

paltomda birikmiş simli kar tozları…

zamanı mıydı, anlamı aşınmış imgelerden

sesimin dalgınlığına yeni bir ahenk bulmanın 

bilmem ki!', 'SON UMU                                      Metin Altıok’a eski bir ilkyaz resminden yontulmuş göğünü arayan sorularla geldim düğümlenen se...', ARRAY['Türk Edebiyatı','Şiir','Selami Karabulut']::text[], 8.5, '{"poet":"Selami Karabulut","poet_slug":"selami-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/son-umu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adressiz Şiir', 'adressiz-siir-selami-karabulut-454a1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün ilk kez yeniden düşündüm seni

Bir çiçeğin gölgesine gömüp yüzümü

Baktım dakikalarca aynı zamana. 

Bir sis gibi dağılan anılardan geri

Hiç bir şey kalmaz sanırdım meğer

Bakışların belleğimi zorlamadan önce.

Ne kadarda zormuş aynı göğün altında

Aynı havayı teneffüs edipte ayrı kalmak.

Dün ilk kez yenden düşündüm seni

Karıştırırken eski anıların defterini

Bir yaprak düştü, bir kalem kırıldı yüreğimde.

Küflü bir kilidin anahtarı olmalı 

Ya da ilk öpüşmenin esrikliği dudaklarımda.

Koştum, aradım parçalanmış aynalarda yüzünü

Bir tek solgun gülüşlü resmin kalmış

O fırtınalı günlerden bana kalan yadigar.', 'Dün ilk kez yeniden düşündüm seni Bir çiçeğin gölgesine gömüp yüzümü Baktım dakikalarca aynı zamana.  Bir sis gibi dağılan anılardan geri Hi...', ARRAY['Türk Edebiyatı','Şiir','Selami Karabulut']::text[], 8.5, '{"poet":"Selami Karabulut","poet_slug":"selami-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/adressiz-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklık', 'uzaklik-selami-karabulut-1zl80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'UZAKLIK 

I

bakıp susma zamanı, kırgın

sararmış otlara düşen uykulu ikindi

yanılgım mı içimde yangın mı

acıyan sularda yitirdiğim yaz

II

göveren hangi zamandanmış o

bir konar göçerin acısına yaşıt

bir tutam kehribar sarısı perçem

soğuk mezatlara düşer kavruk yüzüm

sırrı lâl aynaların aymazlığıyla

şimdi ulaşılamayandır parmaklarımla dokunduğum

eski bir aşkın anısı eskiyen günle yıkanırken

III

artık yıllanmış gömüden dingin acılar saçılır

gün görmüş pişmanlıklarla örülü 

yok sayılmış uçarı günlerin sessizliğini bozan

yorgun, leke gibi sarar boşluğunu unutulmuşluğun

zaman geçirdiği köprülerden silerken bıraktığı izi

geride yalnızca bir fısıltının kendince gizli

bir boşluğu kalır durmadan büyüyen

IV

söz biter... aşınmış bir yüzle gidilir akşama

anlık aldanışlar gibi kuşkulu

hüzündür şimdi, uzayan sessizliğin yankısı

sırı kalmamış uzaklığın penceresinde

hangi yönünden baksam kendi yokluğuna dönük', 'UZAKLIK  I bakıp susma zamanı, kırgın sararmış otlara düşen uykulu ikindi yanılgım mı içimde yangın mı acıyan sularda yitirdiğim yaz II göve...', ARRAY['Türk Edebiyatı','Şiir','Selami Karabulut']::text[], 8.5, '{"poet":"Selami Karabulut","poet_slug":"selami-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/uzaklik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuk', 'konuk-selami-karabulut-79cx9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'KONUK

I

                      örselenmiş sözlerdi aramızda 

                      bizden önce kanayan

                                                     

eskisine gölge düşüren acı, git

sinmiş duvarlarına akşamın

veda vaktinde bir konuğun telaşı

geçmiş ilkyazın son bir ışıltısı

banmış serinliğini kirpiklerinin burcuna

dalgın, kederli bir serçe gibi susmakta

geride kirli yüzüyle bıraktıkların

küstüm çiçeğinden, o yalnızca esefle gülen

zamansızdı belki henüz vakitli diyemem

zor dilimlere bölünmüş

şu suskun günümün yorgun vardiyasında

kağşamış bir mumum

gecenin üstünden sessizce geçtiği

sisli peronların kalabalık yalnızlığına karışan 

içimde bir göçmenin yaban hali

koşması gibi aksak bir çocuğun 

gizlice eksildiğim bu istasyonda...

II

dilsiz bir dalgınlığa dönüştü

uzak bir boşlukta

geceye anlam veren sesindeki kuşku

varla yok arası

sinsi bir aykırılık bu, sendeki sana rağmen

dindi, yorgun yağan karın sesi

işte sevgilim onlar da sustu

ardıç ağacına çakmak taşıyla yazdıklarımız

orda, yanık gazel kokan 

nasır bağlamış sağır anıların orda

sustu, ölümlü bir gerçeğin önünde

yakamozlanmış sularda dinlenen ay gibi

ah! kimliksiz acılarla dinginleşen yüzüm

mahsur kaldığım aynalarda

aksine vuran eylüldür genişleyen soluğum

içinde sönmüş arzuların kederini yansıtan

git de parlak bir yalan bul kendine', 'KONUK I                       örselenmiş sözlerdi aramızda                        bizden önce kanayan                                       ...', ARRAY['Türk Edebiyatı','Şiir','Selami Karabulut']::text[], 8.5, '{"poet":"Selami Karabulut","poet_slug":"selami-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/konuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Çocuğu', 'sokak-cocugu-selami-karabulut-ie3bc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aldım avuçlarını yüreğime

Kuru dalda 

Bir tutam yaprak

Öpüp taç ettim başıma

Sen değil miydin daha dün 

Lacivert geceler boyu 

Sönük yıldızlar gibi susan.

Gömülüp köşedeki evin duldasına 

Vururdun efkarını 

Henüz düşmeden gün

Kirpiklerinin ucuna.

Gözlerinde geceden kalma kor

Nefesinde anason kokusu

Hep aynı kederli şarkılar,

Hep aynı kederli söyleyiş

Meze olurdu sesin 

Sarhoş ve serserilere.

Nasılda geçtin o yollardan 

Ne çabuk değiştirdin 

Ömrüne tersten esen rüzgarı

Ellerinde gün hazinesi kitaplar

Gözlerinde pırıltılı heyecan', 'Aldım avuçlarını yüreğime Kuru dalda  Bir tutam yaprak Öpüp taç ettim başıma Sen değil miydin daha dün  Lacivert geceler boyu  Sönük yıldızl...', ARRAY['Türk Edebiyatı','Şiir','Selami Karabulut']::text[], 8.5, '{"poet":"Selami Karabulut","poet_slug":"selami-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sokak-cocugu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Çıkmazı', 'huzun-cikmazi-berceste-ozkan-t10w8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yamurlu bir günün akşamı,

Gün batarken ağlıyorum.

Yaprağın yere düşüşünde,

Bende yere düşüyorum.

Rüzgarla uçuşan yapraklarla,

Bende ordan oraya savruluyorum.

Biliyorum içimdeki ses,

Hüzün çıkmazındayım!..', 'Yamurlu bir günün akşamı, Gün batarken ağlıyorum. Yaprağın yere düşüşünde, Bende yere düşüyorum. Rüzgarla uçuşan yapraklarla, Bende ordan or...', ARRAY['Türk Edebiyatı','Şiir','Berceste Özkan']::text[], 8.5, '{"poet":"Berceste Özkan","poet_slug":"berceste-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/huzun-cikmazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Senfonisi', 'guz-senfonisi-selami-karabulut-gf20e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'GÜZ SENFONİSİ 

  

I 

ey esrik gülüşleri yorgun 

göğü hüzünlü gurbet türküsü 

bulutlarından tanırım seni 

ağır aksak giden günlerinden

yankısız aynalarda gömülü yüzüm

uzak yollarda unutuyor gülüşünü

esmer bir sessizlik 

hüzünle ağıyor kirpiklerime

II

gün siyah bir tüle büründü 

insanlar koyu renk giysilere

caddeler boyu hüzün, evler boyunca keder

her yüz kendi yalnızlığına gömülü 

buğulu camların ardında dalgın, kırık 

bir şeyler yitirmişliğin acısı var

savrulup giden ekim yapraklarının ardında

sarı ot kokusu bulaşmış elleriyle

üstüne titrediği fesleğen ölüsünü seviyor

duvar dibinde solgun, alık bir resim

ömründe çok kez yaşadığı halde 

yine de şaşarak  bakıyor bu an’a

kim bilir belki de kendi sonbaharını görüyor

kendi gözleriyle kendi teninde

III 

                             kızım Eylül’e

güz deyince hep çocukluğumdur 

içimde art arda yıkılan ormanlar

ürperdikçe uzayan sessizliğim

aynı kum saatinin dönencinde 

aynı yorgun kıvrımında ömrün

rutubet kokulu odalar, camı kırık pencereler

ürkek yabani bir çocuk canlanır gözümde

soluk benizli ama yarın dolu avuçları

seslensen uyanmaz dalgınlığından

kirpiklerinde iri yaş tomurcukları

hüzün damlayan ellerinde buluttan rüzgâr

bilmediği odalarda yarı ölü aydınlık

gülüşü yarım ağızda acı bir türkü

tanımsız heyecan vardır ellerinde

hep eylülle başlar macerası 

Eylül’le devam eder





IV

aynı aynalara yürüdük, aynı umutlarla

yorgun omuzlarında kasvetli ağırlık, 

dudaklarında ucuz ruj, yanaklarında abartılı pudra

aynı kadını sevdik, aynı heyecanla

aynı zaman diliminde, aynı arkadaşla

şimdi aynı yolu yürümesek de







V 

utangaç gülüşlerinde şehvet

uzun saçlarıyla rüzgâr taşırdı bana

gün akşama döner dönmez

durup yorgun sessizliğimin kıyısında

heyecanla bakardı yollarıma

dar dünyasına açılan perdenin arasından

yumuşacık yüzü, merak dolu gözleriyle

kim bilir ne hayalleri vardı

öfke fıçısı uçarı benliğimde

öylesine bir tutkuydu belki de

okşanmak istenen genç kızlık gururuyla

adına güz tadında yazdığım şiirlerden 

ısrarla her gün bir yenisini isterdi

belki de en çok onları sevdi

giderayak bir gülüşü kaldı bende

bir de salkım üzüm gibi bakışı

düğüm düğüm anısı boğazımda

yağmur yüklü bulut dolu gözlerim

yıkar kirpiklerimi tenhalarda sessiz sessiz

bağ bozumu vakti geldiğinde





VI

şimdi oralarda akşamları buruk

sabahları telaşlı

bitip tükenmeyen bir didinmenin adıdır çalışmak

ince, biçimsiz, kırılgan

devinip durur kendi ekseninde umarsızlık

yoksulluk yaşamın diğer bir adıdır

nasırlı parmaklarsa umuda açılan kapı

bir gider bir gelir, ufuklarının penceresindeki aydınlık

zaman tohumun toprağa düştüğü andır

filizlenip büyüdüğü, hasat edildiği an

su geçirgenliği az killi toprak gibi

hiç bir şeyin ifadesi değildir

ömürlerinin takviminden savrulup giden yaprak

dantel dantel işlenmiş umutlarda

en gizli korungan yerlerinde birer düş

uzak kentlerden tanımadıkları 

kurtarıcıdır beklerler hep

yüreklerimde avuç avuç köz 

sandıklarında çeyizleri…

kaldırmadan çalışırlar başlarını 

şeker pancarı tarlalarında

ağır törelerin çemberiyle sarılmış kızlar	

şimdi oralarda çocuklar alın çizgilerinden uzak

bir oyunu oynar gibi sürülerini otlatırlar



VII 

gagası sarı, alnı sakar, göğsü kınalı

pembe ağızlarında odalar dolusu cıvıltı

bir şeyler taşırlardı durmadan kurt, solucan, böcek...

ipince sevinç dalgası bir avuç

ne çabuk büyüttüler yavrularını 

kısacık bu zaman içinde kırlangıçlar

terk edip gidek onlar da bu kenti

bırakarak arkalarında ölü bir sessizliği

kaybedecek gökyüzü mavisini

göçüp giden kuşların ardından

tam zamanı işte şimdi 

toprak, su, hava, rüzgar

söylerler bir zaman

hüzünlü bir turna türküsü 

hep bir olup, bir ağızdan

sadece bir ben duyarım bunu

bir de elimde mahzun duran bağlamam', 'GÜZ SENFONİSİ     I  ey esrik gülüşleri yorgun  göğü hüzünlü gurbet türküsü  bulutlarından tanırım seni  ağır aksak giden günlerinden yankıs...', ARRAY['Türk Edebiyatı','Şiir','Selami Karabulut']::text[], 8.5, '{"poet":"Selami Karabulut","poet_slug":"selami-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":114,"source_url":"https://www.antoloji.com/guz-senfonisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayacaksın', 'aglayacaksin-i-brahim-torun-si4cz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevgi için yazılmış

Bir sabah öldüğümü duyacaksın

Sapsarı bir sonbahar sabahı

Kapanacak gözlerim,

Ağlayacaksın...

Köşe başından bir tabut çıkacak

Ve arkamda sen,

Elinde bir demet çiçek,

Dudağında dualar,

Mahsun gözlerle bakacaksın...

Göz yaşların güneşle parlayacak

Ağlamak gelmesede içinden,

Ağlayacaksın...

Hayalim belirecek karşında

Belki bana benzetemeyeceksin

Koşup kapanmak isteyeceksin

Taze toprağıma mezarımın,

Bırakmayacaklar...

Yeniden beni hatırlayacaksın

Sessiz gözyaşlarıyla

Ağlayacaksın...', 'Sevgi için yazılmış Bir sabah öldüğümü duyacaksın Sapsarı bir sonbahar sabahı Kapanacak gözlerim, Ağlayacaksın... Köşe başından bir tabut çı...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Torun']::text[], 8.5, '{"poet":"İbrahim Torun","poet_slug":"i-brahim-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aglayacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanık', 'tanik-selami-karabulut-re8wi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'TANIK

tanığımdır yıldızlar

bu dört duvar

yalnız masa, kırık ay

akşamcıyım kaç zaman

bir kalemin aydınlığında

utangaç bir kız çocuğu 

sakladığı gibi acemiliğini ürkekçe

mavi gülüşlü

bir yudum su

dokudum ilmiklerini dizelerin

kulak verip yüreğime

pul düştü geceden gözlerime

mora çaldı usumun heceleri

bir avuç acemi ışık

bir avuç telaşlı yağmur kuşu

doğdu avuçlarıma

       

saksılarda süs çiçeklerine inat

ey acıya kirpiklerini eğdiren 

at yüzünden geceyi

kendimi getirdim şiirlerimde

kalbim bir ışık şelalesi', 'TANIK tanığımdır yıldızlar bu dört duvar yalnız masa, kırık ay akşamcıyım kaç zaman bir kalemin aydınlığında utangaç bir kız çocuğu  sakladı...', ARRAY['Türk Edebiyatı','Şiir','Selami Karabulut']::text[], 8.5, '{"poet":"Selami Karabulut","poet_slug":"selami-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sahit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zemheri', 'zemheri-selami-karabulut-cpfyi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akşamdan beri yağan kar kapatmış yolları.

Buzdan birer cam karşı ki gecekondular

Beyaz bir yokluğun içinde belli belirsiz

Serçeler bile uçuşmuyor

Yalnızlık şimdi bir akasya ağacı gibi

Tren hattı boyu yollarda tek başına.

                                                                           .../.. 

Göz bebeklerinde bir yalım ateş 

Buza keserken el ayak 

Çetin  bir zemheri.

Bir kardelen çiçeğisin sen

Dikenli tellerin tam dibinde.

İnadına baharı çağrıştıran.', 'Akşamdan beri yağan kar kapatmış yolları. Buzdan birer cam karşı ki gecekondular Beyaz bir yokluğun içinde belli belirsiz Serçeler bile uçuş...', ARRAY['Türk Edebiyatı','Şiir','Selami Karabulut']::text[], 8.5, '{"poet":"Selami Karabulut","poet_slug":"selami-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zemheri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkıma', 'askima-i-brahim-torun-kjtpm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seviyorum seni,kabul edemesen de

Evet diyeceksin bir gün, şimdi naz etsende

Mahkum olmuşum aşkına, karşılık vermesende

Razıyım beni kırsanda, yinede seni sevmeye

Aşığınım, dönüşüm yok, sonu ölümüm olsa bile

Özliyorum seni, yanında iken bile

Zormuş aşk dedikleri, karşılık görmeyince

Tek sevdiğim sen oldun, tek sen olacaksın gönlümde

Üzme, yeter artık, aç gönlünü, bu büyük sevgime

Mutlaka benim olacaksın, yar etmem

Yar etmem seni kimseye...', 'Seviyorum seni,kabul edemesen de Evet diyeceksin bir gün, şimdi naz etsende Mahkum olmuşum aşkına, karşılık vermesende Razıyım beni kırsanda...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Torun']::text[], 8.5, '{"poet":"İbrahim Torun","poet_slug":"i-brahim-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/askima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahım Kaldı', 'ahim-kaldi-i-brahim-torun-bw8jw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Baharın koynunda kışı yaşadım

Tomurcuk güllerde hep ahım kaldı

Çiçeğin yerine dikeni kokladım

Lalede sümbülde hep ahım kaldı

Gözümde her zaman biraz yaş oldu

Hislerim titredi duygum burkuldu

Nereye gittimse kör talih buldu

Mutluluk neşede hep ahım kaldı

Hatıra verdiğin mendil elimde

Ayrılık sancısı yatar gönlümde

Ümitle hasretle hep ahım kaldı

Şafak yolunu bekleyip durdum

Dönecektir diye hep hayal kurdum

Ne yazık bekleyip boşa yoruldum

Ufukta yollarda hep ahım kaldı

İbrahimim kaderden çeker dururum

Yıkıldı benliğim büyün gururum

Elimde saçımı yolar dururum

Maziyle anıda hep ahım kaldı', 'Baharın koynunda kışı yaşadım Tomurcuk güllerde hep ahım kaldı Çiçeğin yerine dikeni kokladım Lalede sümbülde hep ahım kaldı Gözümde her zam...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Torun']::text[], 8.5, '{"poet":"İbrahim Torun","poet_slug":"i-brahim-torun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ahim-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarap', 'sarap-cemal-sureya-gjzz4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saat on ikiden sonra,

Bütün içkiler,

Şaraptır.

(Yeni Yaprak, sayı:14, Şubat 1990)
..........
..........', 'Saat on ikiden sonra, Bütün içkiler, Şaraptır. (Yeni Yaprak, sayı:14, Şubat 1990) .......... .............', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sarap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Tanesi', 'kar-tanesi-gulay-atilay-gfr6g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben bir KaRTanesi__yim.

Yoğun karların içinde

Kaybolmuş tek bir tane.

Yapayalnız çaresiz

Birgün karların içinde dolaşırken

Sanki sisler kayboldu aniden

Bir güneş doğdu dünyama

Baktım sensin karşımda

Eriteceğini sandım birden

Beni değil yanlızlığımı

Umutsuzluğumu çaresizliğimi

Duydun sandım birden

Biçareliğimi haykırışlılarımı

Derken bir beter oldum

Yanlızken,düşünmeden

Anladım ansızın gerçeği

Bu bir düş olmalıydı

Kendime geldiğim de

Benbir KaRTanesi__ ydim

Bukez UÇURUMUN başındaki..

Bir KaRTanesi__yim ben gerçekten

Gülümseyişleri bile soğuk

Üzülüşü bir amaç olmuş

Ama gülmesi gereken

Yaşamak haram olmuş

Ama yaşaması gereken

Yoğun karların içinde

Uçurumun başında

Yokolmaya mahkum :((', 'Ben bir KaRTanesi__yim. Yoğun karların içinde Kaybolmuş tek bir tane. Yapayalnız çaresiz Birgün karların içinde dolaşırken Sanki sisler kayb...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kar-tanesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masa Da Masaymış Ha', 'masa-da-masaymis-ha-edip-cansever-ec6ym', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adam yaşama sevinci içinde 

Masaya anahtarlarını koydu

Bakır kâseye çiçekleri koydu

Sütünü yumurtasını koydu

Pencereden gelen ışığı koydu

Bisiklet sesini çıkrık sesini

Ekmeğin havanın yumuşaklığını koydu

Adam masaya

Aklında olup bitenleri koydu

Ne yapmak istiyordu hayatta

İşte onu koydu

Kimi seviyordu kimi sevmiyordu

Adam masaya onları da koydu

Üç kere üç dokuz ederdi

Adam koydu masaya dokuzu

Pencere yanındaydı gökyüzü yanında

Uzandı masaya sonsuzu koydu

Bir bira içmek istiyordu kaç gündür

Masaya biranın dökülüşünü koydu

Uykusunu koydu uyanıklığını koydu

Tokluğunu açlığını koydu.

Masa da masaymış ha

Bana mısın demedi bu kadar yüke

Bir iki sallandı durdu

Adam ha babam koyuyordu.

(1954)', 'Adam yaşama sevinci içinde  Masaya anahtarlarını koydu Bakır kâseye çiçekleri koydu Sütünü yumurtasını koydu Pencereden gelen ışığı koydu Bi...', ARRAY['Türk Edebiyatı','Şiir','Edip Cansever']::text[], 8.5, '{"poet":"Edip Cansever","poet_slug":"edip-cansever","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/masa-da-masaymis-ha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbulu Anlatmak', 'istanbulu-anlatmak-gulay-atilay-nh4a2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Istanbul''u bir kelimeyle anlat'' deseler, 

''Sevgi'' derdim. 

''Bir kelime daha'' deseler, 

''Özlem'' derdim. 

''Istanbul sana kimi hatırlatır?'' deseler, 

''Seni'' derdim. 

''En çok hangi semtini seviyorsun?'' deseler, 

''AVCILAR'' derdim. 

''Hangi mevsimde daha güzeldir?'' deseler, 

''Sevgi mevsiminde'' derdim. 

''Ya ayrılık?'' deseler, 

''Ayrılığında bile sevgi var'' derdim. 

''Istanbul kime benziyor?'' deseler, 

''En çok, sevilene'' derdim. 

''Istanbul''u tek kelimeyle anlat'' deseler, 

''Sevdiğim'' derdim. 

''Sevgi dememis miydin biraz önce?'' deseler, 

''Ben ne dedim ki'' derdim. :)))

''''Bilinmiyor', '''Istanbul''u bir kelimeyle anlat'' deseler,  ''Sevgi'' derdim.  ''Bir kelime daha'' deseler,  ''Özlem'' derdim.  ''Istanbul sana kimi hatırlatır?'' de...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/istanbulu-anlatmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arkadaş', 'arkadas-aysegul-gunes-l8f5n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Birgün bir bakarsın arkadas 

Sokakta kıvrıldıgın yerde 

Bir soğukluk bir acı vardır

Hava soğuktur sense hastasındır

Ne olacak kaybettiğim canım olsun dersin

Nasıl olsa kaybedecegın bir o kalmıstır

Seneler önce yine böyle bi gunde kaybetmişsindir herseyinisen aslında

Kafanı kaldırırbakarsın insanlara buruk bir acıyla

Dalarsın düşlere, bende böyleydim diye

Sana acınıpta önüne atılan parayla

Bastırısın aclıgını birassda olsa

Sonra kuytu bi yer bulup ilişirsin yine

Günler böyle gelip geçer

Birgün bir bakars&yacute; n arkadas

Bir sıcaklık hissedersin yanında, artık üşümüyorsundur.

Yanına baktığında kaybetiğin aileni görürsün

Yine düş gördüğünü sanırsın üzüntüyle

Başını eger süngünü düşürürsün yine

Fakat, bu sefer başını egdiğinde yere bakmıyorsundur 

Gecenin karanlıgında buz kesmiş bir caddenin

İşlek kaldırımının kuytu bir kösesinde yatan vücudunu görürsün

Gülersin kendine gördüğünü düş sandıgın için

Başına toplanmış insanlar vardır

Ne olduğunu merak eden fakat yardımı düşünmeyan insanlar

Zaten yardım edilecek bişey kalmamışyır artık...

Bir an buruk bir sevinç kaplar içini

Sis bulutları dagalır hayatındaki

Sevinirsin soğuk caddelerde olmadıgın

Ailenin yanında oldugun için şimdi

Fakat üzülürsünde aynı zamanda 

Senin gibi cok cocuk vardır sokaklarda 

Senin gibi acı cekmiş fakat kavusamamış cocuklar...', 'Birgün bir bakarsın arkadas  Sokakta kıvrıldıgın yerde  Bir soğukluk bir acı vardır Hava soğuktur sense hastasındır Ne olacak kaybettiğim ca...', ARRAY['Türk Edebiyatı','Şiir','Ayşegül Güneş']::text[], 8.5, '{"poet":"Ayşegül Güneş","poet_slug":"aysegul-gunes","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/arkadas-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kız Çocuğu', 'kiz-cocugu-nazim-hikmet-ran-s8efp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kapıları çalan benim 

kapıları birer birer.

Gözünüze görünemem

göze görünmez ölüler.

Hiroşima''da öleli 

oluyor bir on yıl kadar.

Yedi yaşınd
..........
..........', 'Kapıları çalan benim  kapıları birer birer. Gözünüze görünemem göze görünmez ölüler. Hiroşima''da öleli  oluyor bir on yıl kadar. Yedi yaşınd...', ARRAY['Türk Edebiyatı','Şiir','Nazım Hikmet Ran']::text[], 8.5, '{"poet":"Nazım Hikmet Ran","poet_slug":"nazim-hikmet-ran","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kiz-cocugu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Mendilim ''''ANLATIM''''', 'beyaz-mendilim-anlatim-gulay-atilay-ocvl5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beyaz mendilin . (ayrılık oldu)  :((

Bana vermeni istememiştim eve döndüğümde bir burukluk sarmıştı dört yanımı

anlamıştım bugünü yaşayacağımızı.

Kaderimin kötülüğünün cilvesi.

Şimdi koynumda mendilim elimde resmin gözlerimde yaş

Kalbimde sevdandan bana kalan kahreden yas.

Evet   ''''SEVGİLİM''''

Ben seni düşlerimde yaşatacağım. Sessizliğimde avaz avaz adını haykıracağım.

Yıllar sonra bir

gün karşılaştığımızda, uzun uzun yüzüne bakarken, utanmayacağım.

Evet ayrılık unutmak anlamına gelmiyor. Gözlerim hala gözlerine değiyor,

ellerim havada boşluğa

uzanan umutları yakalamaya çabalıyor. Mutlu değildim, mutlu değilim, belki

de hiç olmadım, olmayacağım...

Merak etme tersini düşünüp kendini üzme. Bu arada, sen mutlu isen dahada

mutluluklar dilerim. tebrik ederim.

Bir gün, bir uyku arasında, rastlarsam sana, düşlerimde kendimi

tutmayacağım.

seni'' o kadar çok özledim ki,

Sarıldığımda ağlayacağım .

Senin'' o nedenini bimediğim nedenle benden nefret eden kalbini

okşayacağım....

/Erenköy', 'Beyaz mendilin . (ayrılık oldu)  :(( Bana vermeni istememiştim eve döndüğümde bir burukluk sarmıştı dört yanımı anlamıştım bugünü yaşayacağı...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/beyaz-mendilim-anlatim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oku', 'oku-mehmet-tas-sechj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'oku...

parmakların titremeden

buğu buğu olmadan gözlerin

bir düşünce bulutundan inerek sağnak sağnak

kıraç toprakların efkarıyla oku...

buz gibi odamın katı talnızlığında

romatizmalı dizlerim sızlayarak

boş midemin acı sancılarında

bu satırları senin için yazdım....

oku....

bir şarkının ardında

ağlayabiliyorsan benim gibi

teselli arıyorsan boşalan kadehlerde

aşk sancılarında kıvrana kıvrana

umutla bekliyorsan gideni

bulmak için bu satırlarda kendini

hıçkırıklarını gizlemeden oku.....

oku...

kadere tutsaksan zamanın hücresinde

dost dost diye sarılmışsan karanlıklara

ve bir çile sağınağında çaresizsen

dinmesin diye aşkın sancısı

yaralı gönlüne tuz basarak oku...

oku...

bir mabed kurmuşsan sevgiden

eller secde etmişse mihrabında

tanrı katından boş dönen duaların

sessiz ağlayışlarında

sevenler aşkına

unutulmuşlar aşkına OKU.....', 'oku... parmakların titremeden buğu buğu olmadan gözlerin bir düşünce bulutundan inerek sağnak sağnak kıraç toprakların efkarıyla oku... buz ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Taş']::text[], 8.5, '{"poet":"Mehmet Taş","poet_slug":"mehmet-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/oku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizden Ziyade', 'bizden-ziyade-seyit-ahmet-kutuzman-6g9br', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'o kızgın suları sormadan geçtim

at sürdüm aşkımın hudutlarına

kara kurşun sıktım binden ziyade

üç gece karardı karşı ki dağlar

üç kaşık zehirden ibaret dünya

gözlerin gelmedi aklıma artık

çok şeyler unuttum aydan ötede

bir rüzgar esmedi güneşten gayrı

yıldızda düşündüm sabah etmeyi

gece inkar etti karanlıkları

birden yuvarlandı taşlar dereye

neden ağladı ihtiyar kadın

artık sarhoş olan umutlarıma

ışıklar uzaydan gece döndüler

boş yere sevindi kuşlar havada

at sürdüm aşkımın hudutlarına

kara kurşun sıktım binden ziyade

ne kadar iriydi gözlerin senin

şeytan bahçesine dönmeden evvel

gece kasırgalar kahpece esti

mihricanlar değdi eylülden önce

söğütlüden yaprak düştü sulara

sessiz sessiz aktı ceyhan bu gece

gece kasırgalar kahpece esti

kan doldu gözüme kinden ziyade

bomboz mezarlıklar düştü aklıma

ufuklara gömdüm eski dünyamı

ve yine at sürdüm geceden sonra

yanık bahçelerde tükendi sesim

alın beni burdan yare götürün

gömün bir namlunun içine artık

desinler dünyada aşık kalmadı

çünkü silah sıktım binden ziyade....', 'o kızgın suları sormadan geçtim at sürdüm aşkımın hudutlarına kara kurşun sıktım binden ziyade üç gece karardı karşı ki dağlar üç kaşık zehi...', ARRAY['Türk Edebiyatı','Şiir','Seyit Ahmet Kutuzman']::text[], 8.5, '{"poet":"Seyit Ahmet Kutuzman","poet_slug":"seyit-ahmet-kutuzman","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bizden-ziyade-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Kalan Mezar', 'bana-kalan-mezar-gulay-atilay-f4x4f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '8  Ağustos sabahı...

Uyandım kahroluşlarımla kalbim buruk.

Hayattayım işte acılarımla başbaşa.

Mutluluğu buldum sanmıştım ama :(( 

Oysa kalbim sonsuz bir boşlukta..

Seni nedensiz kaybettim biliyorum..

Suçum neydi hala merak ediyorum..

Kaderime isyan etmiyorum, yinede

Sana sonsuz mutluluklar diliyorum

Ne  hayat bilmediğim kadar güzel

Ne  insanlar göründükleri kadar iyiymiş..

Buralarda yok olurum acılarla ve öğrenirim

kalpsizliği ve artık ölüm bile acır bana.

Son nefesimde son bir oyun son bir zar

Artık bana kalan karanlık ......

MEZAR...

8/8/2000', '8  Ağustos sabahı... Uyandım kahroluşlarımla kalbim buruk. Hayattayım işte acılarımla başbaşa. Mutluluğu buldum sanmıştım ama :((  Oysa kalb...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bana-kalan-mezar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terkettin', 'terkettin-gulay-atilay-z3fec', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkımıza umut ile bakan gözlerim 

Sıcaklığına sevgine alışmışken 

Terkettin. 

Tuttuğu her şeyde tenini hisseden ellerim 

Dokunuşuna alışmışken 

Terkettin. 

Ağzından çıkan her kelimeyle titreyen yüregim 

Sesine alışmışken 

Terkettin. 

Seni düşünerek dalıp giden benligim 

Rüyalarda sana alışmışken 

Terkettin. 

Yazdığı her mısrada sevgimizi anlatan kalemim 

Şiirlerde sana alışmışken 

Terkettin. 

Seni hatırladığım her an kuş olup kanatlanıyorken 

Düşüncelerde uçup sımsıcak sevgine konuyorken 

Terkettin.

Simdi donuklaştım. 

Gözyaşı dolu geceleri silemez oldum. 

Yazdığım sevgi dolu şiirleri okuyamaz oldum. 

Aşkını hatırlatan hiç bir şeye bakamaz oldum. 

Sakladığım mendilini tutamaz oldum.

Elimdeki resmine bakamaz oldum.

Tam sana kavuştum aşkımı  buldum derken. 

Terkettin...... 

      Sevdiceğim buralardan çekip gideceğim.

      Sonunda sensizliği terkedeceğim..

     09/Ağustos/2000', 'Aşkımıza umut ile bakan gözlerim  Sıcaklığına sevgine alışmışken  Terkettin.  Tuttuğu her şeyde tenini hisseden ellerim  Dokunuşuna alışmışk...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/terkettin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Umutlarıma Boğmuştum...', 'seni-umutlarima-bogmustum-tugba-ucar-dltsl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kendi umutlarıma seni de ortak etmiştim.

aslında sana değil,

umutlarıma bağlanmıştım her kelimende

kaybolmuştum ve arıyordum bedeninde bedenimi

sesine vurulmustum ilk

sesindeki inatçı perdeye..

sogukluklar , yabancılıklar hep çekmişti beni

bir adam, hatta '' o  adam'' konusuyordu düşümde senin yerine

düş perisi gerçekle küskünlüğünü bozmuştur diye  inandırmıstım kendimi

seni umutlarıma bogmuş

umutlarını yalamıştım telefondaki düşüşlerde

çalmıştım kalbimden bir aşkı doğurtmak için

günler bir yalanla nasılda geçiyordu...

senin sesinde hayallerime göz kırpmış,

köpek gibi ulumuştum.

umutlarımla bir başkasının bedeninde sevişmeyi kolay sanmıştım!..

kırmamalıydım,yalanlamalıydım nefretimi,

kendi kavgalarımın kurbanı olmamalıydın.

ama kolay sanmıştım bir başkasının bedenininde soluklamayı...

seni umutlarıma boğmuş,

sevgini kurban seçmiştim. 

günler bir yalanla nasılda çekişiyordu..

sesimdeki ihtimaller ve çelişkiler azalıyor ey eski sevgili

artık yanlızca kendimi boğuyorum

kırmak ,kırılmaktan daha kötü...', 'kendi umutlarıma seni de ortak etmiştim. aslında sana değil, umutlarıma bağlanmıştım her kelimende kaybolmuştum ve arıyordum bedeninde beden...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Uçar']::text[], 8.5, '{"poet":"Tuğba Uçar","poet_slug":"tugba-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/seni-umutlarima-bogmustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekerleme', 'tekerleme-tugba-ucar-qdrdi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'tekerlemelerin en ucuz köşesiyim ben,

kalelerin korkak şövalyesiyim.

tatlı rüyalar sevgilim!

sakin ol,

rüyanda dinazoru uyandırma.

mor savaşların turkuaz masallarında  çingene bir kadınım

oyunların en tembeli benim

dalgın bir tacizin ardından gülerim

 Ey Afrodit ve Ey Aynaaa!

söyleyin bana '' var mı bu dünyada benden daha güzeli?'' 

oynak bir sabahın kızıl denizindeyim

tatlı rüyalar sevgilim,

mumun alevindeyim. 

sakin ol sevgilim

sakın dinazoru uyandırma', 'tekerlemelerin en ucuz köşesiyim ben, kalelerin korkak şövalyesiyim. tatlı rüyalar sevgilim! sakin ol, rüyanda dinazoru uyandırma. mor savaş...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Uçar']::text[], 8.5, '{"poet":"Tuğba Uçar","poet_slug":"tugba-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/tekerleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğun Güz Akşamları', 'cocuklugun-guz-aksamlari-tugba-ucar-km57v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mert''e

cocuksun sen bir guz aksami

karanligi kendine dost bilen.

buyumeden kuculen,

cocuk olmadan buyuyen...

sevgin seni uzak sehirlere goturur her gece .

her gece  ayri bir insani dusler,

daginik bir kadinin dusleri olursun...

cocuksun sen soguk teninde 

acilara gebe..

buyumuste kuculmus

cocuk olmadan yitirmis...', 'Mert''e cocuksun sen bir guz aksami karanligi kendine dost bilen. buyumeden kuculen, cocuk olmadan buyuyen... sevgin seni uzak sehirlere gotu...', ARRAY['Türk Edebiyatı','Şiir','Tuğba Uçar']::text[], 8.5, '{"poet":"Tuğba Uçar","poet_slug":"tugba-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cocuklugun-guz-aksamlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suskun', 'suskun-mustafa-oymak-hjhvx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep suskun kalacak değilim

Bir patlarsam içimde volkanlar yanacak

Hep sessizce kaçacak değilim

Bir gün dönersem geri gözlerinde korkum kalacak

Hep sensiz olacak değilim

Bir gün bulursam seni ellerin ellerimde olacak', 'Hep suskun kalacak değilim Bir patlarsam içimde volkanlar yanacak Hep sessizce kaçacak değilim Bir gün dönersem geri gözlerinde korkum kalac...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Oymak']::text[], 8.5, '{"poet":"Mustafa Oymak","poet_slug":"mustafa-oymak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/suskun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İltimas', 'i-ltimas-cemal-safi-f3wwk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen olmazdın Tanrı''nın adaleti şaşmasa,

Seni tarif mümkündü lisanları aşmasa,

Nice güzeller yaratırdı sıradan,

Seni yaratıyorken bu kadar uğraşmasa.', 'Sen olmazdın Tanrı''nın adaleti şaşmasa, Seni tarif mümkündü lisanları aşmasa, Nice güzeller yaratırdı sıradan, Seni yaratıyorken bu kadar uğ...', ARRAY['Türk Edebiyatı','Şiir','Cemal Safi']::text[], 8.5, '{"poet":"Cemal Safi","poet_slug":"cemal-safi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/iltimas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkına Aşığım', 'askina-asigim-hasan-ejderha-irqlg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'akşam oldu çiçeklerde

Sessiz ve serin

Aşkına aşığım ben

Çiçek omrü yaşayıp gidenlerin', 'akşam oldu çiçeklerde Sessiz ve serin Aşkına aşığım ben Çiçek omrü yaşayıp gidenlerin...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/askina-asigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Sende', 'gul-sende-gulay-atilay-o84ng', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülen gözlerini düşledim hep sensiz gecelerde

Işıl ışıl ışık saçan sevgi ile sevgili bakan gözlerini.

Derinliğinde mutluluğu bulduğum sözlerini

düşledim..

Gülüşünü düşledim hep sensiz gecelerde

Içten gelen içimi yakan içten kahkahanı

Pınarlardan akan sular gibi çağlayan sevdanı

düşledim..

Güller açan içten gülen gül yüzünü düşledim

Yüzümün alev alev yanmasını düşledim

Ellerini düşledim hep sensiz gecelerde

Sevgin ile titreyen  ellerimi tutuşunu..

Ellerimin avuçlarında kayboluşunu

hapsedilmişliğimi düşledim..

Dudaklarını düşledim hep sensiz gecelerde

Alev olan volkan olan dudaklarını

Deydiği yerimi yakan dudaklarını düşledim

Alev alev öpüşünü yakışını düşledim

Ben seni düşledim hep sensiz gecelerimde

Yalnızca seni düşledim seni özledim seni bekledim

Gülerek gelmeni boynuma atılmanı bana sarılmanı..

düşledim...

Gel artık !!!!

Gülsün bu gönlüm .sende benimle  GÜL

09/08/2000  Erenköy....', 'Gülen gözlerini düşledim hep sensiz gecelerde Işıl ışıl ışık saçan sevgi ile sevgili bakan gözlerini. Derinliğinde mutluluğu bulduğum sözler...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gul-sende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurulup Vurulup Kıvranmaya Tiryakiyim', 'vurulup-vurulup-kivranmaya-tiryakiyim-hasan-ejderha-m6a2e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çalıyı ucundan sürüyen

Deliler gibidir yüreğim

Bir türlü çekemem çalıyı yerine

Öyle hınçla dolarım ki

Hayal kurarım ufuklar ötesine

Hürriyetimi biçmeyen bir kadın

Çalıyı düzgün sürüdüğüm mekanlar çizerim

Şiir kitaplarında gezen hafiye olur,

Yüreğimi kurşunlayan imajlarla,

Hazzına doyumsuz mısraların izini sürerim.

Pergelin ucundan kurtulduğum anlar

Kendi dairemi kendim çizerim

Oturturum denizleri, okyonusları yüreğime

Çıkarım bir dağ tepesine, dalga seslerini dinlerim.

Vurulup vurulup kıvranmaya tiryakiyim

Kurşunların önüne giderim koşa koşa

En acıyan noktalarımdan kurşun yer,

Her sevinçten acı bekler acı çekerim.

Kapıp bayrağımı sevince koşar,

Hep çileye, acıya, bayrak dikerim.', 'Çalıyı ucundan sürüyen Deliler gibidir yüreğim Bir türlü çekemem çalıyı yerine Öyle hınçla dolarım ki Hayal kurarım ufuklar ötesine Hürriyet...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vurulup-vurulup-kivranmaya-tiryakiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erken Doğum', 'erken-dogum-hasan-ejderha-kxo36', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bana pırangalı günlerin 

acısı gerek

Satmak için muşamba toplayan

çocuğun

kazandığı helvanın 

sevinci ya da.

Dünyada balon diye zıplayan

binlerce, oyuncağa

hasreti sabinin.

Kabenin duvarına asılan

şiirlerin zamanı

O ano yaşayanların

ilhamı.

Köprünün üstüne kadar gelmiş

yolcu ademin

aşkla dolu son dermanı.

Ve... hasretim

zamanı yüreği ile yaşayanların 

her anı', 'Bana pırangalı günlerin  acısı gerek Satmak için muşamba toplayan çocuğun kazandığı helvanın  sevinci ya da. Dünyada balon diye zıplayan bin...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ejderha']::text[], 8.5, '{"poet":"Hasan Ejderha","poet_slug":"hasan-ejderha","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/erken-dogum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge', 'golge-ahmet-yakut-x4z86', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gölgen yaptın beni

Tek farkımızsa,

Islak gözlerimdi', 'Gölgen yaptın beni Tek farkımızsa, Islak gözlerimdi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yakut']::text[], 8.5, '{"poet":"Ahmet Yakut","poet_slug":"ahmet-yakut","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/golge-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-gokhan-sozen-yqqpj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İsyanım var kadere

Ne öldürdü,

Ne güldürdü.

Şu kahpe dünyada

Sevdiğimi öldürdü.', 'İsyanım var kadere Ne öldürdü, Ne güldürdü. Şu kahpe dünyada Sevdiğimi öldürdü....', ARRAY['Türk Edebiyatı','Şiir','Gökhan Sözen']::text[], 8.5, '{"poet":"Gökhan Sözen","poet_slug":"gokhan-sozen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/isyan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoktun', 'sen-yoktun-mustafa-erkan-4v7ry', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geçmedı akşam her yerde sen varsın

Denizin üstünde güneşin morluğunu

Birlikte seyretmek seninle.

Dudaklarına buse saçlarına gül kondurmak istedim

Fakat sen,sen yoktun.

          Uzakta bir balıkçı teknesi yol almış gidiyor

          Mendireğinde bir parlak ışık dümeninde yaşlı bir amca,

          Bağrına sokulup ağlamak istiyorum

          Fakat sen,sen yoktun.', 'Geçmedı akşam her yerde sen varsın Denizin üstünde güneşin morluğunu Birlikte seyretmek seninle. Dudaklarına buse saçlarına gül kondurmak is...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Erkan']::text[], 8.5, '{"poet":"Mustafa Erkan","poet_slug":"mustafa-erkan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sen-yoktun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmayı Dene', 'kalmayi-dene-celalettin-bugra-kurt-7wi2n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''''buralardan gitmek gerek'''' diyorsun

gel de şafağında kalmayı dene

kavlin kanatlansın sedalar üstü

çağrın meydan meydan ses versin yine

açsın toprağında mana gerçeği

rahmet sağnağıyla ulaşsın bine

-bırak şimdi buralardan gitmeyi

sevda sazındaki gönül telinin

yarım besteleri bitmedi daha

kal da baharında çiçekler açsın

mevsiminle kaldır şiiri şaha

esrik yaraların şifa tatmadan

koyma uzaklarda kendini vah''a

_bırak şimdi buralardan gitmeyi

bak-gör dergahının ahvali yaman

umut kayıp gitmiş gelmiyor ele

menekşeler öksüz,güller de yetim

bir ses bin hışımla vuruyor tele

felek ağlasın mı,yoksa yansın mı

kalpler kör kalsın da düşsün mü sele

-bırak şimdi buralardan gitmeyi

asrın girdabında erirken zaman

cehl''in sunakları çöker ola ki

ankebut''tan doğen müjde yeniden

yürekleri Hakka çeker ola ki

maksatımız Mutlak Yare ulaşıp

bileğimiz zülmü büker ola ki

-bırak şimdi buralardan gitmeyi

hazırlığım tamam deme hasrete

hasret yollarını bugün ertele

al sazını düzen eyle garipten

gümbür gümbür tellerine vur hele

gönlümüze vuslat demi yaşatıp

yarım bestemizi bitir aşk ile

-bırak şimdi buralardan gitmeyi', '''''buralardan gitmek gerek'''' diyorsun gel de şafağında kalmayı dene kavlin kanatlansın sedalar üstü çağrın meydan meydan ses versin yine açsı...', ARRAY['Türk Edebiyatı','Şiir','Celalettin Buğra Kurt']::text[], 8.5, '{"poet":"Celalettin Buğra Kurt","poet_slug":"celalettin-bugra-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/kalmayi-dene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ancak Karıncalara Merhaba Derken Diz Çökeriz', 'ancak-karincalara-merhaba-derken-diz-cokeriz-akgun-akova-ab85p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'başımızın beladan bir türlü kurtulmayışı sevgilim

bu taralelliliklerle

usta işi sevişmelerle günde üç dört beş

kanla canla

insan olmanın hakkını vere vere yaşamamızdan

uğradıkları onca bozguna rağmen

bebek yüzlü düşmanların

üstümüze üstümüze gelmeleri komiğime gidiyor

bizim

ancak karıncalara merhaba derken diz çökeceğimizi

orangutanlar bile anlardı vallahi', 'başımızın beladan bir türlü kurtulmayışı sevgilim bu taralelliliklerle usta işi sevişmelerle günde üç dört beş kanla canla insan olmanın hak...', ARRAY['Türk Edebiyatı','Şiir','Akgün Akova']::text[], 8.5, '{"poet":"Akgün Akova","poet_slug":"akgun-akova","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ancak-karincalara-merhaba-derken-diz-cokeriz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-abdul-mesud-ciftci-bznks', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşlerin parlayıp söndüğü yerde

Buluşmak seninle bir akşam üstü

Umarsız şarkılar dudağımda bir yarım ezgi

Sığınmak gözlerine sığınmak bir akşam üstü

Gözlerin bir çığlık bir yaralı haykırış

Gözlerin bu gece çok uzaktan geçen bir gemi 

Bir orman bir gece kar altındayken

Çocuksu uçarı koşmak seninle

Elini avucumda bulup yitirmek yitirmek

Sığınmak ellerine sığınmak bir gece vakti

Ellerin bir martı telaşlı ve ürkek

Ellerin fırtınada çırpınan bir beyaz yelken 

Bir kenti böylece bırakıp gitmek

İçinde bin kaygı binbir soruyla

Bitmemiş bir şarkı dudağımda bir yarım ezgi

Sığınmak şarkılara sığınmak bir ömür boyu

Gözlerin bir çığlık bir yaralı haykırış

Gözlerin bu gece çok uzaktan geçen bir gemi... 

Zülfü Livaneli', 'Düşlerin parlayıp söndüğü yerde Buluşmak seninle bir akşam üstü Umarsız şarkılar dudağımda bir yarım ezgi Sığınmak gözlerine sığınmak bir ak...', ARRAY['Türk Edebiyatı','Şiir','Abdül Mesud Çiftçi']::text[], 8.5, '{"poet":"Abdül Mesud Çiftçi","poet_slug":"abdul-mesud-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gozlerin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
